window.CARDIO = window.CARDIO || {};
CARDIO.registry = CARDIO.registry || {};
CARDIO.registry.fcPub = {"cards":[{"id":"fc-152-4dad7f","poly":"cardio","fiche":"152","front":"Endocardite infectieuse (EI) : définition ?","back":"Infection de l'**endocarde**, le plus souvent d'une ou plusieurs **valves natives** ; aussi endocarde **pariétal** ou tout **matériel intracardiaque**.","prio":"P1","sec":"s1"},{"id":"fc-152-0d595a","poly":"cardio","fiche":"152","front":"EI : citer les matériels intracardiaques qui peuvent être infectés ?","back":"**Prothèse valvulaire** · sonde de **stimulateur** ou de **défibrillateur** · **assistance ventriculaire** · **cathéter veineux central**.","prio":"P2","sec":"s1"},{"id":"fc-152-d0e029","poly":"cardio","fiche":"152","front":"EI : quels types de germes en cause ?","back":"Une **bactérie** le plus souvent ; plus rarement un **champignon**.","prio":"P2","sec":"s1"},{"id":"fc-152-ce8c85","poly":"cardio","fiche":"152","front":"Endocardites non infectieuses : citer les causes ?","back":"**Cancers** (endocardites **marastiques**) ; maladies auto-immunes : **lupus** (lésions de Libman-Sacks), **syndrome des antiphospholipides**.","prio":"P2","sec":"s1"},{"id":"fc-152-56805f","poly":"cardio","fiche":"152","front":"Lupus : nom des lésions d'endocardite non infectieuse ?","back":"Lésions de **Libman-Sacks**.","prio":"P3","sec":"s1"},{"id":"fc-152-0209f2","poly":"cardio","fiche":"152","front":"Endocardites non infectieuses : dans quel cadre diagnostique de l'EI entrent-elles ?","back":"Causes d'EI **à hémocultures négatives**.","prio":"P3","sec":"s1"},{"id":"fc-152-7510c5","poly":"cardio","fiche":"152","front":"EI : comment a évolué l'incidence ces dernières décennies ?","back":"**Pas de diminution** ; ce sont le **profil des patients** (plus âgés) et la **répartition des germes** qui ont changé.","prio":"P2","sec":"s1"},{"id":"fc-152-b1aecd","poly":"cardio","fiche":"152","front":"EI : citer des procédures à risque en augmentation ?","back":"Chirurgie sous **CEC**, **cathéters veineux**, cathétérisme cardiaque, **hémodialyse**, pose de stimulateur/défibrillateur, ponction articulaire, chambre implantable, **toxicomanie IV**.","prio":"P2","sec":"s1"},{"id":"fc-152-3785e9","poly":"cardio","fiche":"152","front":"EI : quelles valvulopathies dégénératives sont citées comme situations à risque ?","back":"**Fibrose** valvulaire et **prolapsus mitral**.","prio":"P3","sec":"s1"},{"id":"fc-152-d9d366","poly":"cardio","fiche":"152","front":"EI : mécanisme physiopathologique de départ ?","back":"**Porte d'entrée** → **bactériémie** (ou fongémie) importante et/ou répétée → fixation sur un endocarde, de préférence **déjà lésé**.","prio":"P2","sec":"s1"},{"id":"fc-152-b6d699","poly":"cardio","fiche":"152","front":"EI : un endocarde sain peut-il être infecté ?","back":"**Oui** : un germe très virulent comme ***S. aureus*** peut infecter un endocarde **sain**.","prio":"P1","sec":"s1"},{"id":"fc-152-b69adc","poly":"cardio","fiche":"152","front":"Végétation d'EI : composition ?","back":"Amas de **fibrine**, **plaquettes**, **cellules inflammatoires** et **germes**.","prio":"P1","sec":"s1"},{"id":"fc-152-d2dbfe","poly":"cardio","fiche":"152","front":"Végétation d'EI : conséquences ?","back":"**Embolies** systémiques (cœur gauche) ou pulmonaires septiques (cœur droit) ; **foyers infectieux à distance** ; rarement obstruction valvulaire.","prio":"P1","sec":"s1"},{"id":"fc-152-3b7c20","poly":"cardio","fiche":"152","front":"EI : conséquence d'une destruction valvulaire (perforation, rupture de cordages) ?","back":"**Fuite (régurgitation) aiguë** → **insuffisance cardiaque**.","prio":"P2","sec":"s1"},{"id":"fc-152-d64773","poly":"cardio","fiche":"152","front":"EI aortique : quel abcès peut donner un BAV ?","back":"Un **abcès septal**, proche des voies de conduction.","prio":"P1","sec":"s1"},{"id":"fc-152-7ee19d","poly":"cardio","fiche":"152","front":"Abcès d'EI : conséquence d'une rupture ?","back":"**Faux anévrisme** ou **fistule intracardiaque**.","prio":"P3","sec":"s1"},{"id":"fc-152-95b5e1","poly":"cardio","fiche":"152","front":"EI sur prothèse : conséquence d'une désinsertion ?","back":"**Fuite paraprothétique**.","prio":"P2","sec":"s1"},{"id":"fc-152-0d2fc0","poly":"cardio","fiche":"152","front":"EI : citer des manifestations de l'atteinte systémique (inflammatoire, immunologique, vasculaire) ?","back":"**Choc septique**, **anévrismes infectieux (mycotiques)**, glomérulonéphrite, purpura vasculaire, faux panaris d'Osler, Janeway, Roth, facteurs rhumatoïdes, parfois cryoglobulinémie.","prio":"P2","sec":"s1"},{"id":"fc-152-41b38a","poly":"cardio","fiche":"152","front":"EI : quelle proportion survient sans cardiopathie à risque connue ?","back":"**50 %** (cardiopathie non connue ou absente).","prio":"P1","sec":"s1"},{"id":"fc-152-c5ba2a","poly":"cardio","fiche":"152","front":"EI : citer les 4 situations du groupe à haut risque ?","back":"**Antécédent d'EI** · **prothèse valvulaire** (TAVI inclus) ou matériel de réparation valvulaire · **cardiopathie congénitale cyanogène** · **assistance ventriculaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-6ec78b","poly":"cardio","fiche":"152","front":"EI : un TAVI classe-t-il le patient à haut risque ?","back":"**Oui** : toute prothèse valvulaire, chirurgicale ou **percutanée (TAVI inclus)**.","prio":"P1","sec":"s2"},{"id":"fc-152-1d01f8","poly":"cardio","fiche":"152","front":"EI : dispositifs à haut risque pendant les 6 mois suivant la pose ?","back":"Dispositifs de **fermeture** (CIV, auricule gauche), **prothèses vasculaires**, **filtres caves**, **shunts ventriculoatriaux**.","prio":"P2","sec":"s2"},{"id":"fc-152-336e50","poly":"cardio","fiche":"152","front":"EI : cardiopathie congénitale réparée avec matériel prothétique, durée du haut risque (points clés) ?","back":"**6 mois** après le geste, ou **à vie** s'il persiste un **shunt résiduel**.","prio":"P2","sec":"s2"},{"id":"fc-152-062543","poly":"cardio","fiche":"152","front":"EI : citer les situations à risque intermédiaire ?","back":"Valvulopathies **dégénératives** ; **congénitales** (bicuspidie aortique) ; **post-rhumatismale** ; **CMH** ; **stimulateur/défibrillateur**.","prio":"P2","sec":"s2"},{"id":"fc-152-f0cf91","poly":"cardio","fiche":"152","front":"Bicuspidie aortique ou stimulateur cardiaque : antibioprophylaxie de l'EI ?","back":"**Non** à ce seul titre : risque **intermédiaire** (éducation seulement).","prio":"P2","sec":"s2"},{"id":"fc-152-980592","poly":"cardio","fiche":"152","front":"EI : à quels patients s'adressent les mesures d'éducation ?","back":"À **tous** les patients à risque (**haut** ou **intermédiaire**).","prio":"P1","sec":"s2"},{"id":"fc-152-f7bc47","poly":"cardio","fiche":"152","front":"EI : à quels patients est réservée l'antibioprophylaxie ?","back":"Aux seuls patients à **haut risque**.","prio":"P1","sec":"s2"},{"id":"fc-152-d2b6ac","poly":"cardio","fiche":"152","front":"Prévention de l'EI : fréquence des visites chez le dentiste ?","back":"**2 fois/an** si haut risque ; **1 fois/an** pour les autres cardiopathies à risque.","prio":"P1","sec":"s2"},{"id":"fc-152-efeafb","poly":"cardio","fiche":"152","front":"EI : germe le plus fréquent et sa part ?","back":"***Staphylococcus aureus*** : **30 %** des EI.","prio":"P1","sec":"s2"},{"id":"fc-152-506bf9","poly":"cardio","fiche":"152","front":"EI à S. aureus : porte d'entrée ?","back":"**Cutanée** : plaie, cathéter veineux ou de dialyse, toxicomanie IV, geste peropératoire, stimulateur/défibrillateur.","prio":"P1","sec":"s2"},{"id":"fc-152-9a4024","poly":"cardio","fiche":"152","front":"EI à streptocoques oraux : part et porte d'entrée ?","back":"**20 %** ; porte d'entrée **buccodentaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-9dade4","poly":"cardio","fiche":"152","front":"EI à streptocoque du groupe D (S. gallolyticus) : part et porte d'entrée ?","back":"**13 %** ; porte d'entrée **digestive** : cancer, polypes, diverticules coliques.","prio":"P1","sec":"s2"},{"id":"fc-152-978f6f","poly":"cardio","fiche":"152","front":"EI à staphylocoques à coagulase négative : part et porte d'entrée ?","back":"**10 %** ; porte d'entrée **cutanée**.","prio":"P2","sec":"s2"},{"id":"fc-152-a11404","poly":"cardio","fiche":"152","front":"EI à entérocoques : part et porte d'entrée ?","back":"**10 %** ; porte d'entrée **digestive** et **urinaire**.","prio":"P1","sec":"s2"},{"id":"fc-152-194809","poly":"cardio","fiche":"152","front":"EI à germes du groupe HACEK : part et porte d'entrée ?","back":"**5 %** ; porte d'entrée **buccodentaire**.","prio":"P2","sec":"s2"},{"id":"fc-152-eec320","poly":"cardio","fiche":"152","front":"EI à Candida : part et porte d'entrée ?","back":"**< 5 %** ; porte d'entrée **cutanée** (immunosuppression, cathéter, toxicomanie IV…).","prio":"P2","sec":"s2"},{"id":"fc-152-9b3488","poly":"cardio","fiche":"152","front":"EI : proportion sans germe retrouvé malgré plusieurs techniques ?","back":"**5-10 %**.","prio":"P3","sec":"s2"},{"id":"fc-152-329919","poly":"cardio","fiche":"152","front":"EI : citer des germes « autres » rares (< 5 %) ?","back":"***Coxiella burnetii***, ***Bartonella***, ***Brucella***, ***Chlamydia***, ***Tropheryma whipplei***.","prio":"P3","sec":"s2"},{"id":"fc-152-01644c","poly":"cardio","fiche":"152","front":"EI : quelle famille de germes domine ?","back":"**Cocci Gram positif** : en **amas** (staphylocoques) et en **chaînettes** (streptocoques, entérocoques).","prio":"P2","sec":"s2"},{"id":"fc-152-7f5a28","poly":"cardio","fiche":"152","front":"Groupe HACEK : signification ?","back":"***Haemophilus*** spp., ***Aggregatibacter*** actinomycetemcomitans, ***Cardiobacterium*** hominis, ***Eikenella*** corrodens, ***Kingella*** kingae.","prio":"P2","sec":"s2"},{"id":"fc-152-427bd2","poly":"cardio","fiche":"152","front":"EI : citer les 5 associations « fièvre + … » qu'il est inacceptable de ne pas rattacher à une EI ?","back":"Fièvre + **souffle** · + **cardiopathie à risque** · + **AVC** · + **lombalgie** · + **purpura**.","prio":"P1","sec":"s3"},{"id":"fc-152-36ceb4","poly":"cardio","fiche":"152","front":"Insuffisance cardiaque fébrile : quel diagnostic évoquer ?","back":"Une **endocardite infectieuse**.","prio":"P1","sec":"s3"},{"id":"fc-152-14e313","poly":"cardio","fiche":"152","front":"EI : caractère de la présentation clinique ?","back":"Maladie **systémique**, **polymorphe** : signes inconstants, c'est le **contexte** qui fait évoquer le diagnostic.","prio":"P2","sec":"s3"},{"id":"fc-152-de71b7","poly":"cardio","fiche":"152","front":"EI : quelle association de signes est très évocatrice ?","back":"Un **syndrome infectieux** associé à des **signes d'atteinte de l'endocarde**.","prio":"P2","sec":"s3"},{"id":"fc-152-daee22","poly":"cardio","fiche":"152","front":"EI : quel signe clinique a la plus grande valeur chez un patient fébrile ?","back":"Un **souffle nouveau ou modifié**.","prio":"P1","sec":"s3"},{"id":"fc-152-8a7395","poly":"cardio","fiche":"152","front":"EI : l'absence de souffle élimine-t-elle le diagnostic ?","back":"**Non**.","prio":"P1","sec":"s3"},{"id":"fc-152-dc2f6a","poly":"cardio","fiche":"152","front":"EI : fréquence de la splénomégalie ?","back":"**20-30 %**.","prio":"P3","sec":"s3"},{"id":"fc-152-9da18f","poly":"cardio","fiche":"152","front":"EI : que traduisent des syncopes ou lipothymies ?","back":"Un **BAV** par **abcès septal** interrompant les voies de conduction.","prio":"P1","sec":"s3"},{"id":"fc-152-bb4473","poly":"cardio","fiche":"152","front":"EI : citer les atteintes neurologiques possibles ?","back":"**AVC** ischémique ou hémorragique, **méningite**, **hémorragie méningée**, **abcès cérébral**.","prio":"P2","sec":"s3"},{"id":"fc-152-dedcb4","poly":"cardio","fiche":"152","front":"EI : signes pulmonaires et leurs mécanismes ?","back":"**OAP** (insuffisance cardiaque gauche) ; **pneumopathies récidivantes abcédées** (**embolies pulmonaires septiques**).","prio":"P2","sec":"s3"},{"id":"fc-152-01361a","poly":"cardio","fiche":"152","front":"EI : atteintes articulaires possibles ?","back":"**Arthrite** périphérique, **spondylodiscite** (foyers infectieux à distance).","prio":"P2","sec":"s3"},{"id":"fc-152-8a7663","poly":"cardio","fiche":"152","front":"EI : fréquence des signes cutanéomuqueux ?","back":"**Rares** : **5-15 %**.","prio":"P3","sec":"s3"},{"id":"fc-152-1abf54","poly":"cardio","fiche":"152","front":"EI : quel signe cutané est pathognomonique ?","back":"Les **nodosités d'Osler** (« faux panaris »).","prio":"P1","sec":"s3"},{"id":"fc-152-2a3bd1","poly":"cardio","fiche":"152","front":"EI : citer les signes cutanéomuqueux possibles ?","back":"**Purpura**, nodosités d'**Osler**, placards de **Janeway**, hémorragies **sous-conjonctivales** et **sous-unguéales**.","prio":"P3","sec":"s3"},{"id":"fc-152-742952","poly":"cardio","fiche":"152","front":"EI : placards de Janeway, définition ?","back":"**Placards érythémateux palmoplantaires**.","prio":"P2","sec":"s3"},{"id":"fc-152-bf9f4d","poly":"cardio","fiche":"152","front":"EI : taches de Roth, définition ?","back":"**Exsudats hémorragiques rétiniens** vus au **fond d'œil**.","prio":"P2","sec":"s3"},{"id":"fc-152-0473c5","poly":"cardio","fiche":"152","front":"EI : atteinte rénale clinique et mécanismes ?","back":"**Hématurie** et/ou **protéinurie** : **glomérulonéphrite** immunologique ou **infarctus rénal**.","prio":"P2","sec":"s3"},{"id":"fc-152-9a2d5e","poly":"cardio","fiche":"152","front":"EI : les deux piliers du diagnostic ?","back":"**Hémocultures** (germe) + **échographie cardiaque** (atteinte de l'endocarde).","prio":"P1","sec":"s4"},{"id":"fc-152-7f707f","poly":"cardio","fiche":"152","front":"EI : quelle erreur est une notion inacceptable vis-à-vis des hémocultures ?","back":"**Débuter les antibiotiques avant les hémocultures**.","prio":"P1","sec":"s4"},{"id":"fc-152-3bf0b5","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : nombre et espacement ?","back":"Idéalement **3** prélèvements veineux, espacés d'**au moins 30 min**.","prio":"P1","sec":"s4"},{"id":"fc-152-1c6d7c","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : type de culture et site interdit ?","back":"Culture **aéroanaérobie** ; **jamais sur un cathéter déjà en place**.","prio":"P1","sec":"s4"},{"id":"fc-152-3a3e2e","poly":"cardio","fiche":"152","front":"Hémocultures dans l'EI : pourquoi prévenir le laboratoire ?","back":"Germes à croissance difficile (**HACEK**, ***Brucella***, streptocoques déficients, **levures**) : culture parfois **prolongée**.","prio":"P2","sec":"s4"},{"id":"fc-152-64d8a3","poly":"cardio","fiche":"152","front":"EI : hémocultures initiales négatives, que faire ?","back":"Les **répéter pendant 2 ou 3 jours**, surtout si antibiotiques déjà reçus.","prio":"P2","sec":"s4"},{"id":"fc-152-5252ae","poly":"cardio","fiche":"152","front":"EI : rentabilité des hémocultures ?","back":"Germe isolé dans **90 %** des cas (**10 %** d'EI à hémocultures négatives).","prio":"P1","sec":"s4"},{"id":"fc-152-da3b36","poly":"cardio","fiche":"152","front":"EI : place de l'ETT ?","back":"**Systématique en 1re intention**, chez **tous**.","prio":"P1","sec":"s4"},{"id":"fc-152-d4a0ba","poly":"cardio","fiche":"152","front":"EI : 3 indications de l'ETO systématique ?","back":"ETT **positive** ; ETT **négative avec forte suspicion** ; **matériel intracardiaque**.","prio":"P1","sec":"s4"},{"id":"fc-152-d64ca2","poly":"cardio","fiche":"152","front":"EI : échographie normale, conduite ?","back":"EI **non éliminée** : refaire **ETT + ETO après 7-10 jours**.","prio":"P1","sec":"s4"},{"id":"fc-152-38086f","poly":"cardio","fiche":"152","front":"EI : lésions recherchées en échographie ?","back":"**Végétations**, destructions valvulaires, **abcès**, fistules, pseudoanévrismes, désinsertion de prothèse, fuite paraprothétique ; + sévérité et retentissement des fuites.","prio":"P2","sec":"s4"},{"id":"fc-152-430d31","poly":"cardio","fiche":"152","front":"EI : intérêt du scanner cardiaque injecté ?","back":"Abcès ou végétations **non vus en échographie**, notamment sur **prothèse valvulaire**.","prio":"P2","sec":"s4"},{"id":"fc-152-c6c073","poly":"cardio","fiche":"152","front":"EI : indication du TEP-scanner au ¹⁸FDG ou de la scintigraphie aux leucocytes marqués ?","back":"Suspicion d'EI **sur prothèse valvulaire** ou **sur stimulateur/défibrillateur** quand le **diagnostic reste douteux**.","prio":"P2","sec":"s4"},{"id":"fc-152-ef7fc0","poly":"cardio","fiche":"152","front":"EI : intérêt supplémentaire du TEP-scanner corps entier ?","back":"Il montre aussi les **localisations septiques secondaires**.","prio":"P3","sec":"s4"},{"id":"fc-152-110a21","poly":"cardio","fiche":"152","front":"EI : intérêt de l'ECG dans le bilan ?","back":"**BAV** (troubles de conduction) ; **ischémie** par embolie coronarienne.","prio":"P1","sec":"s4"},{"id":"fc-152-da162d","poly":"cardio","fiche":"152","front":"EI : anomalies possibles de la NFS ?","back":"**Hyperleucocytose à PNN**, **anémie** inflammatoire ou hémolytique, **thrombopénie**.","prio":"P3","sec":"s4"},{"id":"fc-152-7fdf48","poly":"cardio","fiche":"152","front":"EI : examens biologiques du bilan des complications, hors NFS ?","back":"**CRP** (inflammation) ; **facteur rhumatoïde** (immunologie) ; **ionogramme**, **créatininémie**, hématurie, protéinurie (rein).","prio":"P3","sec":"s4"},{"id":"fc-152-9aac1e","poly":"cardio","fiche":"152","front":"EI : objectif du scanner cérébral et thoraco-abdomino-pelvien ?","back":"**Localisations septiques secondaires** (parfois asymptomatiques) et **anévrismes infectieux** ; injecté seulement **si la fonction rénale le permet**.","prio":"P1","sec":"s4"},{"id":"fc-152-241f36","poly":"cardio","fiche":"152","front":"EI : localisations secondaires recherchées au scanner ?","back":"**Encéphale**, **rate**, **rein**, **foie**, **vertèbres**.","prio":"P3","sec":"s4"},{"id":"fc-152-38dc71","poly":"cardio","fiche":"152","front":"EI : IRM cérébrale versus scanner ?","back":"**Plus sensible**, mais **moins disponible**.","prio":"P3","sec":"s4"},{"id":"fc-152-c9a774","poly":"cardio","fiche":"152","front":"EI : indication de l'angiographie cérébrale ?","back":"Suspicion d'**anévrisme infectieux (mycotique)**.","prio":"P2","sec":"s4"},{"id":"fc-152-1ba1f0","poly":"cardio","fiche":"152","front":"EI : examens si suspicion d'embolie coronarienne ?","back":"**Coronarographie** et **troponine**.","prio":"P3","sec":"s4"},{"id":"fc-152-a1ff65","poly":"cardio","fiche":"152","front":"EI : radiographie thoracique, que chercher ?","back":"**OAP** (EI du cœur gauche) ; **pneumopathies** (EI du cœur droit).","prio":"P3","sec":"s4"},{"id":"fc-152-26189d","poly":"cardio","fiche":"152","front":"EI certaine : critères cliniques ?","back":"**2 majeurs**, ou **1 majeur + 3 mineurs**, ou **5 mineurs** (ou critères histologiques).","prio":"P2","sec":"s5"},{"id":"fc-152-2a4c1f","poly":"cardio","fiche":"152","front":"EI possible : critères ?","back":"**1 majeur + 1 ou 2 mineurs**, ou **3 mineurs**.","prio":"P2","sec":"s5"},{"id":"fc-152-533ee9","poly":"cardio","fiche":"152","front":"EI : critères histologiques d'EI certaine ?","back":"Patient opéré : **germe en culture** d'une valve ou d'un embole, ou végétation/abcès avec **infection active** à l'anatomopathologie.","prio":"P3","sec":"s5"},{"id":"fc-152-c3603a","poly":"cardio","fiche":"152","front":"EI : 2 critères majeurs ?","back":"**Hémocultures positives pour l'EI** + **imagerie positive** (échographie, scanner cardiaque, TEP-¹⁸FDG ou scintigraphie aux leucocytes marqués).","prio":"P2","sec":"s5"},{"id":"fc-152-ffaa2a","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : germes « typiques » sur ≥ 2 hémocultures ?","back":"***S. aureus***, **streptocoques oraux**, ***S. gallolyticus***, ***Enterococcus faecalis***, **HACEK**.","prio":"P2","sec":"s5"},{"id":"fc-152-e63fac","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : ≥ 2 hémocultures positives, quel intervalle entre les prélèvements ?","back":"Prélevées à **plus de 12 heures** d'intervalle.","prio":"P3","sec":"s5"},{"id":"fc-152-4035f9","poly":"cardio","fiche":"152","front":"Critère majeur d'EI : 3 hémocultures à germe typique, délai exigé ?","back":"**≥ 1 heure** entre le premier et le dernier prélèvement.","prio":"P3","sec":"s5"},{"id":"fc-152-2d0791","poly":"cardio","fiche":"152","front":"Critère majeur d'EI pour Coxiella burnetii ?","back":"**≥ 1 hémoculture positive** ou **IgG de phase I > 1/800**.","prio":"P3","sec":"s5"},{"id":"fc-152-09f81f","poly":"cardio","fiche":"152","front":"EI : citer les 5 critères mineurs ?","back":"**Terrain** à risque (haut/intermédiaire, toxicomanie IV) · **fièvre > 38 °C** · phénomènes **vasculaires** · phénomènes **immunologiques** · argument **microbiologique** non majeur.","prio":"P2","sec":"s5"},{"id":"fc-152-f5e98e","poly":"cardio","fiche":"152","front":"Critère mineur d'EI : phénomènes vasculaires ?","back":"**Embolies** artérielles ou pulmonaires, **anévrismes infectieux**, **hémorragies**, **placards de Janeway** (même asymptomatiques).","prio":"P3","sec":"s5"},{"id":"fc-152-740be4","poly":"cardio","fiche":"152","front":"Critère mineur d'EI : phénomènes immunologiques ?","back":"**Glomérulonéphrite**, **nodosités d'Osler**, **taches de Roth**, **facteurs rhumatoïdes**.","prio":"P3","sec":"s5"},{"id":"fc-152-8decb6","poly":"cardio","fiche":"152","front":"EI du cœur droit : terrains ?","back":"**Toxicomanes IV**, porteurs de **stimulateur/défibrillateur**, de **voie veineuse centrale**, cardiopathie congénitale avec atteinte droite.","prio":"P2","sec":"s5"},{"id":"fc-152-cffb9a","poly":"cardio","fiche":"152","front":"EI du cœur droit : germe le plus fréquent chez le toxicomane ou le porteur de stimulateur ?","back":"Les **staphylocoques**.","prio":"P2","sec":"s5"},{"id":"fc-152-03907a","poly":"cardio","fiche":"152","front":"EI du cœur droit : signes révélateurs ?","back":"**Signes respiratoires** : pneumopathies récidivantes, souvent **abcédées**, par **embolies pulmonaires septiques**.","prio":"P2","sec":"s5"},{"id":"fc-152-fd1fa3","poly":"cardio","fiche":"152","front":"EI sur prothèse précoce : définition et mécanisme habituel ?","back":"Dans l'**année** qui suit la pose ; souvent **contamination périopératoire**.","prio":"P2","sec":"s5"},{"id":"fc-152-22562d","poly":"cardio","fiche":"152","front":"EI sur prothèse tardive : définition ?","back":"Survenue **plus d'un an** après la pose de la prothèse.","prio":"P3","sec":"s5"},{"id":"fc-152-22bea3","poly":"cardio","fiche":"152","front":"EI sur prothèse : pronostic par rapport à la valve native ?","back":"**Plus sévère**, que l'EI soit précoce ou tardive.","prio":"P2","sec":"s5"},{"id":"fc-152-b04ce8","poly":"cardio","fiche":"152","front":"EI : risque selon le type de prothèse (biologique ou mécanique) ?","back":"**Même risque** d'EI.","prio":"P3","sec":"s5"},{"id":"fc-152-d22a06","poly":"cardio","fiche":"152","front":"EI : mortalité hospitalière ?","back":"**15-30 %**.","prio":"P1","sec":"s6"},{"id":"fc-152-79bc4c","poly":"cardio","fiche":"152","front":"EI : deux principales causes de décès ?","back":"**Insuffisance cardiaque aiguë** et **complications neurologiques**.","prio":"P1","sec":"s6"},{"id":"fc-152-e9f580","poly":"cardio","fiche":"152","front":"EI : quelles formes sont les plus graves ?","back":"EI **sur prothèse** et EI **à staphylocoque**.","prio":"P1","sec":"s6"},{"id":"fc-152-6cebed","poly":"cardio","fiche":"152","front":"EI : foyers infectieux à distance issus des végétations ?","back":"**Abcès spléniques ou rénaux**, **arthrites**, **spondylodiscite**, **méningite**.","prio":"P2","sec":"s6"},{"id":"fc-152-3c4dff","poly":"cardio","fiche":"152","front":"EI : complications de la destruction valvulaire, de l'abcès ou de la désinsertion ?","back":"Fuites valvulaires/paraprothétiques, fistules, **insuffisance cardiaque aiguë** (OAP, choc cardiogénique), **BAV**.","prio":"P2","sec":"s6"},{"id":"fc-152-54a008","poly":"cardio","fiche":"152","front":"EI : complications de l'inflammation systémique ?","back":"AEG, **choc septique**, vascularite, glomérulonéphrite, **anévrismes infectieux**, **hémorragies** (cérébrale…).","prio":"P2","sec":"s6"},{"id":"fc-152-22ca63","poly":"cardio","fiche":"152","front":"EI : citer des facteurs de mauvais pronostic ?","back":"**IC aiguë**, complications **neurologiques**, sepsis mal maîtrisé, **abcès** intracardiaque, **prothèse**, végétations **volumineuses**, *S. aureus*/champignons, terrain fragile.","prio":"P1","sec":"s6"},{"id":"fc-152-769f06","poly":"cardio","fiche":"152","front":"EI : germes très virulents de mauvais pronostic ?","back":"***S. aureus*** et **champignons**.","prio":"P2","sec":"s6"},{"id":"fc-152-d8c2d3","poly":"cardio","fiche":"152","front":"EI : terrain fragile de mauvais pronostic ?","back":"**Âge avancé**, **diabète**, **immunodépression**, insuffisance cardiaque, rénale ou respiratoire préexistante.","prio":"P3","sec":"s6"},{"id":"fc-152-c32c70","poly":"cardio","fiche":"152","front":"EI : quand prévenir le chirurgien cardiaque ?","back":"**Dès que le diagnostic est posé**.","prio":"P1","sec":"s6"},{"id":"fc-152-d2f450","poly":"cardio","fiche":"152","front":"Équipe endocardite : composition minimale ?","back":"**Cardiologues**, **chirurgiens cardiaques**, **infectiologues**, **microbiologistes** (± imageurs), dans un centre des valvulopathies.","prio":"P3","sec":"s6"},{"id":"fc-152-bcda51","poly":"cardio","fiche":"152","front":"Équipe endocardite : intérêt et sollicitation ?","back":"Elle **améliore le pronostic** ; **toujours sollicitée** (patients graves/complexes adressés, sinon avis à distance).","prio":"P3","sec":"s6"},{"id":"fc-152-bebec0","poly":"cardio","fiche":"152","front":"EI : la spondylodiscite est-elle un phénomène inflammatoire ou un foyer septique ?","back":"Un **foyer infectieux à distance** issu des végétations.","prio":"P2","sec":"s6"},{"id":"fc-152-2aeb35","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : proportion ?","back":"**10 %** des EI.","prio":"P1","sec":"s7"},{"id":"fc-152-383f37","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives avec forte présomption : examens complémentaires ?","back":"**Techniques spéciales d'hémocultures**, **sérologies**, **PCR**.","prio":"P2","sec":"s7"},{"id":"fc-152-f1a007","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : 4 grandes causes ?","back":"**Antibiothérapie préalable** · germes à **croissance lente** · germes **intracellulaires** · **endocardites non infectieuses**.","prio":"P2","sec":"s7"},{"id":"fc-152-4ff619","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : germes à croissance lente ou difficile ?","back":"**Streptocoques déficients**, **HACEK**, ***Brucella***, **champignons**.","prio":"P3","sec":"s7"},{"id":"fc-152-59b917","poly":"cardio","fiche":"152","front":"EI à hémocultures négatives : germes intracellulaires ?","back":"***Coxiella*** (fièvre Q), ***Chlamydia***, ***Bartonella***, ***Tropheryma whipplei***, ***Mycoplasma***, ***Legionella***.","prio":"P3","sec":"s7"},{"id":"fc-152-041442","poly":"cardio","fiche":"152","front":"EI opérée : devenir des pièces opératoires ?","back":"**Histologie**, **culture** et éventuellement **PCR**.","prio":"P2","sec":"s7"},{"id":"fc-152-108602","poly":"cardio","fiche":"152","front":"EI à S. gallolyticus ou à entérocoque : examen digestif imposé ?","back":"**Coloscopie** à la recherche d'une **tumeur colique**.","prio":"P2","sec":"s7"},{"id":"fc-152-cfdcbe","poly":"cardio","fiche":"152","front":"Traitement de l'EI : citer les 5 volets ?","back":"**Antibiotiques** (ou antifongiques) · indications **chirurgicales** · **complications** · **porte d'entrée** · **surveillance**.","prio":"P2","sec":"s8"},{"id":"fc-152-fbb661","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : 4 caractéristiques et durée ?","back":"**Bactéricide**, **synergique** (plusieurs molécules), **fortes doses**, **IV**, **4 à 6 semaines**.","prio":"P1","sec":"s8"},{"id":"fc-152-4c59bc","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : effet d'une chirurgie sur sa durée ?","back":"**Aucun** : durée **inchangée**.","prio":"P1","sec":"s8"},{"id":"fc-152-e56f02","poly":"cardio","fiche":"152","front":"EI : germe identifié, comment ajuster l'antibiothérapie ?","back":"**Adaptée à l'antibiogramme**, avec l'aide d'un **infectiologue**.","prio":"P2","sec":"s8"},{"id":"fc-152-4fccf1","poly":"cardio","fiche":"152","front":"Antibiothérapie de l'EI : sur quoi adapter les doses ?","back":"Fonctions **rénale** et **hépatique** + **concentrations plasmatiques** d'aminosides et de vancomycine.","prio":"P2","sec":"s8"},{"id":"fc-152-813e48","poly":"cardio","fiche":"152","front":"EI : 3 indications de l'antibiothérapie probabiliste ?","back":"**Forte suspicion**, **sepsis sévère**, **indication chirurgicale urgente** ; juste après les hémocultures, sans attendre le résultat.","prio":"P1","sec":"s8"},{"id":"fc-152-5c8290","poly":"cardio","fiche":"152","front":"EI communautaire sur valve native ou prothèse ≥ 1 an : antibiothérapie probabiliste ?","back":"**Ampicilline + ceftriaxone** (ou oxacilline) **+ gentamicine**, IV.","prio":"P1","sec":"s8"},{"id":"fc-152-aa1783","poly":"cardio","fiche":"152","front":"EI communautaire, allergie à la pénicilline : probabiliste ?","back":"**Céfazoline** (ou vancomycine) **+ gentamicine**.","prio":"P2","sec":"s8"},{"id":"fc-152-543e3b","poly":"cardio","fiche":"152","front":"EI non communautaire ou prothèse < 1 an : antibiothérapie probabiliste ?","back":"**Vancomycine** (ou daptomycine) **+ gentamicine + rifampicine** ; même schéma si allergie.","prio":"P1","sec":"s8"},{"id":"fc-152-fc5245","poly":"cardio","fiche":"152","front":"EI postopératoire précoce sur prothèse : germes et mortalité ?","back":"Germes **hospitaliers** parfois multirésistants, surtout **staphylocoque doré ou blanc** ; mortalité **≈ 50 %**.","prio":"P2","sec":"s8"},{"id":"fc-152-f513dd","poly":"cardio","fiche":"152","front":"EI postopératoire précoce : lésions habituelles et conduite ?","back":"EI souvent aiguë avec **abcès de l'anneau** et **désinsertion** ; **réintervention précoce** le plus souvent.","prio":"P3","sec":"s8"},{"id":"fc-152-c7b799","poly":"cardio","fiche":"152","front":"EI sur prothèse : quand faire l'ETO ?","back":"En cas de **forte suspicion**, et aussi **une fois le diagnostic confirmé** (bilan des lésions).","prio":"P3","sec":"s8"},{"id":"fc-152-46e6ff","poly":"cardio","fiche":"152","front":"EI à SAMS sur valve native : traitement ?","back":"**Cloxacilline** (ou céfazoline) IV, **4 à 6 semaines** ; céfazoline si allergie.","prio":"P1","sec":"s9"},{"id":"fc-152-fc5820","poly":"cardio","fiche":"152","front":"EI à SARM sur valve native : traitement ?","back":"**Vancomycine** IV, **4-6 semaines** (idem si allergie).","prio":"P1","sec":"s9"},{"id":"fc-152-ea2878","poly":"cardio","fiche":"152","front":"EI à SAMS sur prothèse : traitement ?","back":"**Cloxacilline** (ou céfazoline) **+ rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P1","sec":"s9"},{"id":"fc-152-e73559","poly":"cardio","fiche":"152","front":"EI à SARM sur prothèse : traitement ?","back":"**Vancomycine + rifampicine** 6 semaines **+ gentamicine 2 semaines** (idem si allergie).","prio":"P2","sec":"s9"},{"id":"fc-152-722caf","poly":"cardio","fiche":"152","front":"EI sur prothèse à S. aureus : implication chirurgicale ?","back":"**Indication chirurgicale** (infectieuse) en phase active.","prio":"P2","sec":"s9"},{"id":"fc-152-c40f0e","poly":"cardio","fiche":"152","front":"EI à streptocoque oral ou S. gallolyticus sur valve native : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) IV, **4 semaines**.","prio":"P1","sec":"s10"},{"id":"fc-152-a04010","poly":"cardio","fiche":"152","front":"EI à streptocoque sur valve native résistant à la pénicilline : ajout ?","back":"**Gentamicine 2 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-ecabc7","poly":"cardio","fiche":"152","front":"EI à streptocoque sur valve native, allergie : traitement ?","back":"**Vancomycine 4 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-ddd6f4","poly":"cardio","fiche":"152","front":"EI à streptocoque sur prothèse : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) **6 semaines** ; allergie : vancomycine 6 sem + gentamicine 2 sem.","prio":"P2","sec":"s10"},{"id":"fc-152-0e69fe","poly":"cardio","fiche":"152","front":"EI à streptocoque oral : bilan de la porte d'entrée ?","back":"**Panoramique dentaire** + **consultation de stomatologie**.","prio":"P2","sec":"s10"},{"id":"fc-152-e3243f","poly":"cardio","fiche":"152","front":"EI à entérocoque, cas général : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone**, **6 semaines** (ou ceftriaxone remplacée par gentamicine 2 semaines).","prio":"P1","sec":"s10"},{"id":"fc-152-a87990","poly":"cardio","fiche":"152","front":"EI à entérocoque : le traitement diffère-t-il entre valve native et prothèse ?","back":"**Non** : même traitement, **6 semaines** dans les deux cas.","prio":"P2","sec":"s10"},{"id":"fc-152-b559cc","poly":"cardio","fiche":"152","front":"EI à entérocoque : allergie ou résistance aux bêtalactamines ?","back":"**Vancomycine 6 semaines + gentamicine 2 semaines**.","prio":"P2","sec":"s10"},{"id":"fc-152-e5af34","poly":"cardio","fiche":"152","front":"EI à entérocoque résistant à la gentamicine : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone**, 6 semaines.","prio":"P3","sec":"s10"},{"id":"fc-152-aac46c","poly":"cardio","fiche":"152","front":"EI à entérocoque résistant à la vancomycine : traitement ?","back":"**Daptomycine + ampicilline** (ou fosfomycine), 6 semaines ; allergie : **daptomycine + fosfomycine**.","prio":"P2","sec":"s10"},{"id":"fc-152-81555b","poly":"cardio","fiche":"152","front":"EI à entérocoque : bilan de la porte d'entrée ?","back":"**Coloscopie** ; **ECBU** + échographie (ou scanner) des voies urinaires.","prio":"P2","sec":"s10"},{"id":"fc-152-f47b53","poly":"cardio","fiche":"152","front":"EI : durée d'antibiotiques pour streptocoque versus entérocoque ?","back":"Streptocoque : **4 sem** (native), **6 sem** (prothèse) ; entérocoque : **6 sem** dans les deux cas.","prio":"P1","sec":"s10"},{"id":"fc-152-45e882","poly":"cardio","fiche":"152","front":"Allergie à la pénicilline : quelle prescription est une notion inacceptable ?","back":"**Prescrire une pénicilline**.","prio":"P1","sec":"s11"},{"id":"fc-152-2fef94","poly":"cardio","fiche":"152","front":"EI chez l'allergique à la pénicilline : exceptions à la vancomycine ?","back":"**Céfazoline** pour le SAMS (et 1er choix du probabiliste communautaire) ; **daptomycine + fosfomycine** pour l'entérocoque résistant à la vancomycine.","prio":"P2","sec":"s11"},{"id":"fc-152-3a8afd","poly":"cardio","fiche":"152","front":"EI fongique : traitement anti-infectieux ?","back":"**Antifongiques** à la place des antibiotiques (molécule non précisée).","prio":"P2","sec":"s11"},{"id":"fc-152-dcec2d","poly":"cardio","fiche":"152","front":"EI fongique : implication chirurgicale et porte d'entrée ?","back":"**Indication chirurgicale** (infectieuse) en phase active ; porte d'entrée **cutanée** (*Candida*).","prio":"P2","sec":"s11"},{"id":"fc-152-0363a2","poly":"cardio","fiche":"152","front":"EI : fréquence d'une indication chirurgicale en phase active ?","back":"**Environ 50 %** des cas, sans attendre la fin des antibiotiques.","prio":"P1","sec":"s12"},{"id":"fc-152-5f6dba","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : déroulement du geste ?","back":"**Débridement** des tissus infectés, puis **plastie** si possible, sinon **remplacement** valvulaire (biologique ou mécanique).","prio":"P2","sec":"s12"},{"id":"fc-152-2d7f92","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : 3 familles d'indications ?","back":"**Hémodynamiques**, **infectieuses**, **emboliques** (« HIE »).","prio":"P1","sec":"s12"},{"id":"fc-152-78b18b","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications hémodynamiques ?","back":"IC gauche **réfractaire** ou **choc cardiogénique** ; IC gauche ou signe échographique de **mauvaise tolérance**.","prio":"P2","sec":"s12"},{"id":"fc-152-7bba82","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : signes d'infection non contrôlée localement ?","back":"**Abcès**, **fistule**, faux anévrisme, végétations qui **grossissent**, **désinsertion** de prothèse, **BAV**.","prio":"P2","sec":"s12"},{"id":"fc-152-5c5f85","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications infectieuses liées au germe ?","back":"EI **fongique** ou à germes **multirésistants** ; EI sur prothèse à ***S. aureus*** ou à **Gram négatif non HACEK**.","prio":"P2","sec":"s12"},{"id":"fc-152-36c662","poly":"cardio","fiche":"152","front":"EI : délai d'hémocultures positives sous antibiotiques qui indique la chirurgie ?","back":"Toujours positives après **plus de 7 jours** (embolies et métastases septiques contrôlées).","prio":"P3","sec":"s12"},{"id":"fc-152-314449","poly":"cardio","fiche":"152","front":"Chirurgie de l'EI : indications emboliques ?","back":"Végétation du cœur gauche **≥ 10 mm** persistante après embolie(s) malgré antibiotiques adaptés, ou associée à une autre indication.","prio":"P2","sec":"s12"},{"id":"fc-152-85164e","poly":"cardio","fiche":"152","front":"EI tardive sur prothèse : part du staphylocoque et pronostic ?","back":"Staphylocoque dans **50 %** des cas ; pronostic **meilleur** que l'EI précoce.","prio":"P3","sec":"s12"},{"id":"fc-152-dde171","poly":"cardio","fiche":"152","front":"EI tardive sur prothèse : quand discuter la réintervention ?","back":"**Sepsis non maîtrisé**, **risque embolique** important, **dysfonction sévère** de prothèse, atteinte périvalvulaire avec **désinsertion**.","prio":"P3","sec":"s12"},{"id":"fc-152-58ce0f","poly":"cardio","fiche":"152","front":"EI : faut-il attendre la fin des antibiotiques pour opérer ?","back":"**Non** : on opère dès que l'indication existe.","prio":"P1","sec":"s12"},{"id":"fc-152-0c51c4","poly":"cardio","fiche":"152","front":"EI sur stimulateur, défibrillateur ou cathéter central : geste obligatoire ?","back":"**Extraire tout le matériel** (souvent par voie **percutanée**), puis **réimplanter à distance**.","prio":"P1","sec":"s13"},{"id":"fc-152-05b3b2","poly":"cardio","fiche":"152","front":"EI du cœur droit chez le toxicomane IV : valve et image pulmonaire typiques ?","back":"Végétation **tricuspide** ; pneumopathie bilatérale avec **abcès pulmonaire** (embolies pulmonaires septiques).","prio":"P2","sec":"s13"},{"id":"fc-152-fe1293","poly":"cardio","fiche":"152","front":"EI : porte d'entrée retrouvée dans quelle proportion ?","back":"**50 %** des cas : la chercher **selon le germe**.","prio":"P3","sec":"s13"},{"id":"fc-152-ab3152","poly":"cardio","fiche":"152","front":"EI : place du traitement de la porte d'entrée ?","back":"Il **fait partie du traitement** de l'EI.","prio":"P2","sec":"s13"},{"id":"fc-152-5007b6","poly":"cardio","fiche":"152","front":"EI sous traitement : critères d'efficacité ?","back":"Régression **fièvre** et **syndrome inflammatoire** ; **stérilisation des hémocultures** ; évolution échographique favorable ; **pas de complication**.","prio":"P1","sec":"s14"},{"id":"fc-152-05eb35","poly":"cardio","fiche":"152","front":"EI sous traitement : surveillance de tolérance principale ?","back":"**Fonction rénale** : aminosides, vancomycine, mais aussi **amoxicilline**.","prio":"P1","sec":"s14"},{"id":"fc-152-85aba5","poly":"cardio","fiche":"152","front":"Amoxicilline : mécanismes de toxicité rénale ?","back":"**Réaction immunoallergique** ou **cristallurie** → atteinte interstitielle aiguë ou nécrose tubulaire aiguë.","prio":"P2","sec":"s14"},{"id":"fc-152-aff409","poly":"cardio","fiche":"152","front":"EI sous traitement : examen pour dépister un BAV ?","back":"**ECG**.","prio":"P2","sec":"s14"},{"id":"fc-152-7250f6","poly":"cardio","fiche":"152","front":"EI guérie : groupe de risque du patient ?","back":"**Haut risque** (antécédent d'EI).","prio":"P1","sec":"s15"},{"id":"fc-152-bd5bcd","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : son efficacité est-elle prouvée ?","back":"**Non**, jamais formellement prouvée.","prio":"P3","sec":"s15"},{"id":"fc-152-feb34a","poly":"cardio","fiche":"152","front":"Prévention de l'EI : document à remettre ?","back":"**Carte de prévention** adaptée au groupe de risque, à montrer au médecin/dentiste.","prio":"P2","sec":"s15"},{"id":"fc-152-f88448","poly":"cardio","fiche":"152","front":"Prévention de l'EI : fréquence du brossage des dents ?","back":"**2 à 3 fois par jour**.","prio":"P3","sec":"s15"},{"id":"fc-152-891f5e","poly":"cardio","fiche":"152","front":"Prévention de l'EI : mesures cutanées et urinaires ?","back":"**Désinfecter les plaies** ; **éradiquer les colonisations bactériennes chroniques** cutanées et urinaires.","prio":"P2","sec":"s15"},{"id":"fc-152-47b74f","poly":"cardio","fiche":"152","front":"Prévention de l'EI : conduite face à une infection bactérienne locale ?","back":"La **traiter par antibiotiques**.","prio":"P3","sec":"s15"},{"id":"fc-152-e426c1","poly":"cardio","fiche":"152","front":"Prévention de l'EI : mesures concernant les voies veineuses ?","back":"**Asepsie stricte** lors des gestes à risque ; **limiter** les voies veineuses et les **changer régulièrement** si besoin prolongé.","prio":"P3","sec":"s15"},{"id":"fc-152-bd4705","poly":"cardio","fiche":"152","front":"Prévention de l'EI : interdits et conduites à tenir pour le patient ?","back":"Pas de **tatouage** ni **piercing** ; pas d'**automédication antibiotique** ; **consulter vite si fièvre**.","prio":"P1","sec":"s15"},{"id":"fc-152-ba5286","poly":"cardio","fiche":"152","front":"Patient à risque d'EI : quelle omission est une notion inacceptable ?","back":"**Oublier les mesures de prévention non médicamenteuses**.","prio":"P1","sec":"s15"},{"id":"fc-152-e75655","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : soins dentaires concernés ?","back":"Manipulation de la **gencive** ou de la **région périapicale**, ou **effraction de la muqueuse**.","prio":"P1","sec":"s15"},{"id":"fc-152-d5a9c1","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI chez l'adulte (référence item 152) ?","back":"**Amoxicilline 2 g** per os ou IV, **dose unique**, **30-60 min avant** le geste.","prio":"P1","sec":"s15"},{"id":"fc-152-a65677","poly":"cardio","fiche":"152","front":"Antibioprophylaxie de l'EI : alternative céphalosporine ?","back":"**Céfazoline** (ou ceftriaxone) **1 g** IM ou IV, 30-60 min avant.","prio":"P2","sec":"s15"},{"id":"fc-152-4de59e","poly":"cardio","fiche":"152","front":"Antibioprophylaxie chez le porteur de valve (item 153) : schéma « en général » ?","back":"**Amoxicilline 3 g**, **1 heure avant**, pour tout geste dentaire à risque infectieux, détartrage compris.","prio":"P3","sec":"s15"},{"id":"fc-152-43bc9b","poly":"cardio","fiche":"152","front":"Fièvre chez un patient à risque d'EI : conduite du patient ?","back":"Prévenir **rapidement son médecin**, présenter sa **carte** ; **aucun antibiotique sans avis médical**.","prio":"P1","sec":"s15"},{"id":"fc-152-565915","poly":"cardio","fiche":"152","front":"EI sans indication opératoire en phase active : chirurgie ultérieure ?","back":"Parfois **chirurgie à distance**, selon les indications habituelles des **valvulopathies**.","prio":"P3","sec":"s15"},{"id":"fc-153-87e2cd","poly":"cardio","fiche":"153","front":"Prothèses valvulaires : 2 grandes familles ?","back":"**Mécanique** et **biologique** (bioprothèse chirurgicale ou **percutanée = TAVI**).","prio":"P1","sec":"s1"},{"id":"fc-153-c8d246","poly":"cardio","fiche":"153","front":"Prothèse valvulaire : risque d'endocardite par rapport à une valve native ?","back":"**Accru** pour toute prothèse (**corps étranger**).","prio":"P1","sec":"s1"},{"id":"fc-153-fa544f","poly":"cardio","fiche":"153","front":"Valve mécanique : composition ?","back":"Partie mécanique en **titane et carbone** ; collerette en tissu type **Dacron** pour la suture.","prio":"P3","sec":"s1"},{"id":"fc-153-ff108b","poly":"cardio","fiche":"153","front":"Valve mécanique : traitement antithrombotique ?","back":"**AVK définitif**, à vie.","prio":"P1","sec":"s1"},{"id":"fc-153-d7cf27","poly":"cardio","fiche":"153","front":"Valve mécanique : place des AOD ?","back":"**Formellement contre-indiqués**, **même transitoirement**.","prio":"P1","sec":"s1"},{"id":"fc-153-f80adb","poly":"cardio","fiche":"153","front":"Valve mécanique : avec quoi relayer l'AVK si besoin ?","back":"**HNF** ou **HBPM** (jamais d'AOD).","prio":"P1","sec":"s1"},{"id":"fc-153-940540","poly":"cardio","fiche":"153","front":"Valve mécanique : durabilité ?","back":"**Excellente**, prévue pour **toute la vie** (plus de 15 ans sans complication).","prio":"P2","sec":"s1"},{"id":"fc-153-cdad40","poly":"cardio","fiche":"153","front":"Bioprothèse chirurgicale : origine habituelle du tissu ?","back":"Surtout **xénogreffe** : péricarde bovin ou équin, valve aortique porcine ; le plus souvent montée sur armature (**stentée**).","prio":"P2","sec":"s1"},{"id":"fc-153-f25bfe","poly":"cardio","fiche":"153","front":"Bioprothèse chirurgicale : durabilité moyenne ?","back":"**Limitée** : **10 ans** en moyenne, parfois moins (sujet jeune, type de prothèse).","prio":"P1","sec":"s1"},{"id":"fc-153-f17b5c","poly":"cardio","fiche":"153","front":"TAVI : principe de pose ?","back":"Tissu animal sur armature métallique type stent, fixé sur l'anneau aortique calcifié par **cathétérisme rétrograde sous anesthésie locale**.","prio":"P2","sec":"s1"},{"id":"fc-153-5347ae","poly":"cardio","fiche":"153","front":"TAVI : durabilité ?","back":"Dégénère comme toute bioprothèse ; durabilité **encore à définir** (très peu de recul au-delà de 5 ans).","prio":"P3","sec":"s1"},{"id":"fc-153-aba15c","poly":"cardio","fiche":"153","front":"Valves mécaniques : 3 générations ?","back":"À **bille** (Starr®, retirée en 2007) · **monodisques** (Björk-Shiley®, Medtronic-Hall®) · **double ailette** (Saint-Jude®…).","prio":"P2","sec":"s1"},{"id":"fc-153-35a6df","poly":"cardio","fiche":"153","front":"Valve mécanique la plus posée aujourd'hui et ses atouts ?","back":"**Double ailette** : bonne hémodynamique, **moins thrombogène**.","prio":"P1","sec":"s1"},{"id":"fc-153-b06f8e","poly":"cardio","fiche":"153","front":"Valve mécanique : les AVK suppriment-ils le risque de thrombose ?","back":"**Non** : ils le **réduisent sans l'annuler**.","prio":"P2","sec":"s1"},{"id":"fc-153-935514","poly":"cardio","fiche":"153","front":"Prothèses en tissu humain : 2 types ?","back":"**Allogreffe/homogreffe** (valve aortique d'un donneur surtout) et **autogreffe**.","prio":"P3","sec":"s1"},{"id":"fc-153-9090e4","poly":"cardio","fiche":"153","front":"Intervention de Ross : principe ?","back":"Racine aortique remplacée par la **racine pulmonaire du patient** ; homogreffe ou xénogreffe en position pulmonaire.","prio":"P3","sec":"s1"},{"id":"fc-153-06e12e","poly":"cardio","fiche":"153","front":"Intervention d'Ozaki : principe ?","back":"Le **péricarde postérieur du patient** sert à fabriquer une valve aortique à trois cusps.","prio":"P3","sec":"s1"},{"id":"fc-153-8ac6c1","poly":"cardio","fiche":"153","front":"Bioprothèse stentless : avantages et inconvénient ?","back":"Meilleure **hémodynamique**, durée parfois plus longue ; mais se soude et se calcifie → **réintervention difficile** (rarement posée).","prio":"P3","sec":"s1"},{"id":"fc-153-7af7ea","poly":"cardio","fiche":"153","front":"TAVI : 2 modes de déploiement ?","back":"**Par ballon** (Sapien 3®) ou **autodéployable** (Evolut R®, Evolut Pro®, recapturables).","prio":"P3","sec":"s1"},{"id":"fc-153-2d16f3","poly":"cardio","fiche":"153","front":"Choix de prothèse : inconvénient de chaque famille ?","back":"Mécanique : risque **thromboembolique** + **saignement** sous anticoagulant ; biologique : **dégénérescence** → réintervention.","prio":"P1","sec":"s2"},{"id":"fc-153-9e65c8","poly":"cardio","fiche":"153","front":"Choix de prothèse : 3 critères ?","back":"**Choix éclairé du patient** · balance **thromboembolique/hémorragique** · risque de **dégénérescence**.","prio":"P2","sec":"s2"},{"id":"fc-153-832ab4","poly":"cardio","fiche":"153","front":"Valve mécanique préférée : âges repères ?","back":"**< 60 ans** en aortique ; **< 65 ans** en mitral.","prio":"P1","sec":"s2"},{"id":"fc-153-99c3b1","poly":"cardio","fiche":"153","front":"Bioprothèse préférée : âges repères ?","back":"**> 65 ans** en aortique ; **> 70 ans** en mitral.","prio":"P1","sec":"s2"},{"id":"fc-153-399462","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale : pourquoi un âge seuil plus élevé qu'en aortique ?","back":"La bioprothèse **mitrale dure moins**.","prio":"P2","sec":"s2"},{"id":"fc-153-a24543","poly":"cardio","fiche":"153","front":"Arguments pour une valve mécanique (hors âge) ?","back":"Souhait du patient ; pas de CI aux AVK ; risque de **dégénérescence précoce** (hypoparathyroïdie, IRC) ; autre indication d'AVK (**FA, MTE**) ; réintervention à haut risque.","prio":"P2","sec":"s2"},{"id":"fc-153-1dd0e6","poly":"cardio","fiche":"153","front":"Maladies exposant à une dégénérescence précoce de bioprothèse ?","back":"**Hypoparathyroïdie** et **IRC**.","prio":"P3","sec":"s2"},{"id":"fc-153-a07387","poly":"cardio","fiche":"153","front":"Arguments pour une bioprothèse (hors âge) ?","back":"Souhait ; **CI aux AVK** ou risque de complication ; **thrombose de valve mécanique malgré INR efficace** ; **désir de grossesse** ; faible risque de réintervention.","prio":"P2","sec":"s2"},{"id":"fc-153-d9a0a2","poly":"cardio","fiche":"153","front":"Désir de grossesse : quel type de prothèse privilégier et pourquoi ?","back":"**Bioprothèse** : les **AVK sont tératogènes**.","prio":"P1","sec":"s2"},{"id":"fc-153-daa417","poly":"cardio","fiche":"153","front":"Valve mécanique : conséquences d'un sous-dosage et d'un surdosage en AVK ?","back":"Sous-dosage : **thrombose** ; surdosage : **saignement**.","prio":"P1","sec":"s2"},{"id":"fc-153-1f640b","poly":"cardio","fiche":"153","front":"Aortique ≥ 60 ans (mitral ≥ 65 ans) sans FA ni risque cardioembolique : prothèse ?","back":"**Bioprothèse**.","prio":"P2","sec":"s2"},{"id":"fc-153-345188","poly":"cardio","fiche":"153","front":"Aortique ≥ 60 ans (mitral ≥ 65 ans) avec FA : prothèse ?","back":"**Valve mécanique**, sauf risque hémorragique élevé ou très élevé (→ bioprothèse).","prio":"P2","sec":"s2"},{"id":"fc-153-0241f7","poly":"cardio","fiche":"153","front":"Aortique < 60 ans (mitral < 65 ans) sans FA : quand préférer une bioprothèse ?","back":"Espérance de vie **très courte (≤ 5 ans)** ; aussi si espérance de vie **< 10-12 ans**, CI ou impossibilité d'anticoaguler, risque hémorragique accru sous AVK, **INR labiles**.","prio":"P3","sec":"s2"},{"id":"fc-153-e7961e","poly":"cardio","fiche":"153","front":"Algorithme de choix : arguments qui orientent vers la bioprothèse ?","back":"Espérance de vie **< 10-12 ans**, CI ou impossibilité d'anticoaguler, risque hémorragique accru sous AVK, **INR labiles**.","prio":"P3","sec":"s2"},{"id":"fc-153-155523","poly":"cardio","fiche":"153","front":"TAVI : indications ?","back":"**RA serré** contre-indiqué à la chirurgie ou à risque **haut ou intermédiaire** (tout âge) ; et **dès 75 ans** quel que soit le risque.","prio":"P1","sec":"s2"},{"id":"fc-153-78075e","poly":"cardio","fiche":"153","front":"Après 75 ans : place du TAVI (ESC 2021) ?","back":"Envisagé **en 1re intention si l'anatomie est favorable**.","prio":"P1","sec":"s2"},{"id":"fc-153-88643d","poly":"cardio","fiche":"153","front":"TAVI : qui décide ?","back":"La **Heart Team** : cardiologues, chirurgiens cardiaques, anesthésistes-réanimateurs, gériatres.","prio":"P2","sec":"s2"},{"id":"fc-153-9c6035","poly":"cardio","fiche":"153","front":"Valve-in-valve : définition ?","back":"**TAVI posé par voie percutanée dans une bioprothèse** chirurgicale ou un TAVI **dégénéré**.","prio":"P2","sec":"s2"},{"id":"fc-153-a4afdb","poly":"cardio","fiche":"153","front":"Valve-in-valve : quand l'anticiper ?","back":"**Dès tout remplacement aortique par bioprothèse**, en Heart Team.","prio":"P3","sec":"s2"},{"id":"fc-153-b0701f","poly":"cardio","fiche":"153","front":"Valve-in-valve : intérêt chez les patients à risque haut ou intermédiaire ?","back":"Éviter une chirurgie **redux** à haut risque.","prio":"P3","sec":"s2"},{"id":"fc-153-b44580","poly":"cardio","fiche":"153","front":"Remplacement d'une seule valve chez un jeune en bonne santé : mortalité périopératoire ?","back":"**Pas plus de 1 à 2 %** ; augmente avec l'âge, le nombre de gestes et les comorbidités.","prio":"P2","sec":"s2"},{"id":"fc-153-8ba683","poly":"cardio","fiche":"153","front":"Bioprothèse : mécanismes de la dégénérescence des feuillets ?","back":"**Calcification** (valve sténosante) ou **déchirure**, surtout commissurale (valve fuyante).","prio":"P2","sec":"s3"},{"id":"fc-153-8fe9ee","poly":"cardio","fiche":"153","front":"Bioprothèse : anticoagulant systématique au long cours ?","back":"**Non justifié** (bioprothèse chirurgicale) et **non indiqué** (TAVI) : risque de thrombose de feuillets **faible**.","prio":"P2","sec":"s3"},{"id":"fc-153-377fe6","poly":"cardio","fiche":"153","front":"Prothèses : 5 familles de complications ?","back":"**T**hromboemboliques · **H**émorragiques · **I**nfectieuses · **D**égénérescence · **D**ésinsertion (THIDD).","prio":"P1","sec":"s3"},{"id":"fc-153-7cd650","poly":"cardio","fiche":"153","front":"Prothèses : complications les plus fréquentes ?","back":"**Thromboemboliques**, surtout sur valve **mécanique**.","prio":"P1","sec":"s3"},{"id":"fc-153-5253af","poly":"cardio","fiche":"153","front":"Complications thromboemboliques des prothèses : principal facteur de risque ?","back":"Une **anticoagulation insuffisante**.","prio":"P1","sec":"s3"},{"id":"fc-153-7b25cb","poly":"cardio","fiche":"153","front":"Valve mécanique sous anticoagulant : risque hémorragique annuel ?","back":"Environ **1,2 % par an**.","prio":"P3","sec":"s3"},{"id":"fc-153-bc54d8","poly":"cardio","fiche":"153","front":"Endocardite précoce sur prothèse (jusqu'à 1 an) : mortalité ?","back":"De l'ordre de **50 %**.","prio":"P1","sec":"s3"},{"id":"fc-153-294a38","poly":"cardio","fiche":"153","front":"Bioprothèse : délai habituel de dégénérescence ?","back":"En général **5 à 15 ans** ; plus tôt en **mitral** et chez le **jeune**.","prio":"P1","sec":"s3"},{"id":"fc-153-a433be","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : fréquence et moment ?","back":"**5 %** des cas, surtout les **premiers mois**.","prio":"P2","sec":"s3"},{"id":"fc-153-083f0b","poly":"cardio","fiche":"153","front":"Valve mécanique : fourchette d'INR cible ?","back":"Entre **2,5 et 4**.","prio":"P1","sec":"s4"},{"id":"fc-153-a1d6fb","poly":"cardio","fiche":"153","front":"INR cible d'une valve mécanique : 2 paramètres qui le déterminent ?","back":"**Risque thrombotique de la prothèse** (modèle) + présence d'**au moins 1 facteur de risque patient**.","prio":"P1","sec":"s4"},{"id":"fc-153-6866ac","poly":"cardio","fiche":"153","front":"Valve mécanique à risque faible : INR cible ?","back":"**2,5** sans facteur patient ; **3,0** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-b833d6","poly":"cardio","fiche":"153","front":"Valve mécanique à risque moyen : INR cible ?","back":"**3,0** sans facteur patient ; **3,5** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-afde94","poly":"cardio","fiche":"153","front":"Valve mécanique à risque élevé : INR cible ?","back":"**3,5** sans facteur patient ; **4,0** avec ≥ 1 facteur.","prio":"P1","sec":"s4"},{"id":"fc-153-2e7ed8","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique faible : exemples ?","back":"**Carbomedics®**, **Medtronic Hall®**, ATS®, Medtronic Open-Pivot®, **St Jude Medical®**, Sorin Bicarbon®.","prio":"P3","sec":"s4"},{"id":"fc-153-96e294","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique moyen ?","back":"**Autres doubles ailettes**, récentes ou à données de suivi insuffisantes.","prio":"P2","sec":"s4"},{"id":"fc-153-8fc42f","poly":"cardio","fiche":"153","front":"Valves mécaniques à risque thrombotique élevé ?","back":"**Starr-Edwards®** (bille), Lillehei-Kaster®, Omniscience®, **Björk-Shiley®** et autres **prothèses à disque**.","prio":"P2","sec":"s4"},{"id":"fc-153-67678a","poly":"cardio","fiche":"153","front":"INR cible des valves mécaniques : facteurs de risque liés au patient ?","back":"Remplacement **mitral ou tricuspide** · **ATCD thromboembolique** · **FA** · **sténose mitrale** (tout degré) · **FEVG < 35 %**.","prio":"P1","sec":"s4"},{"id":"fc-153-112314","poly":"cardio","fiche":"153","front":"INR cible : une sténose mitrale peu serrée compte-t-elle comme facteur patient ?","back":"**Oui**, quel que soit son degré.","prio":"P2","sec":"s4"},{"id":"fc-153-f90687","poly":"cardio","fiche":"153","front":"INR cible d'une valve mécanique : qui le fixe et selon quoi ?","back":"**Individuellement avec le cardiologue** : type et position de prothèse, facteurs emboliques, **risque hémorragique**.","prio":"P2","sec":"s4"},{"id":"fc-153-c1f92c","poly":"cardio","fiche":"153","front":"Valve mécanique : rythme des contrôles d'INR ?","back":"**1 à 2 fois/semaine** jusqu'à l'équilibre, puis **au moins 1 fois/mois**.","prio":"P1","sec":"s4"},{"id":"fc-153-e19946","poly":"cardio","fiche":"153","front":"Valve mécanique : écart toléré autour de l'INR cible ?","back":"**± 0,5** point au maximum.","prio":"P1","sec":"s4"},{"id":"fc-153-abee5d","poly":"cardio","fiche":"153","front":"AVK : définition d'un patient bien équilibré ?","back":"**Au moins 70 %** des INR dans la cible.","prio":"P2","sec":"s4"},{"id":"fc-153-47cca4","poly":"cardio","fiche":"153","front":"Valve mécanique : quand débuter l'AVK ?","back":"**Tôt**, dès les **premiers jours postopératoires**, puis **à vie**.","prio":"P1","sec":"s5"},{"id":"fc-153-fc524c","poly":"cardio","fiche":"153","front":"Valve mécanique : où inscrire l'INR cible ?","back":"Dans le **carnet de surveillance** de l'anticoagulant.","prio":"P2","sec":"s5"},{"id":"fc-153-d07afa","poly":"cardio","fiche":"153","front":"Relais héparine-AVK : délai d'efficacité de l'AVK ?","back":"**4 à 6 jours**.","prio":"P2","sec":"s5"},{"id":"fc-153-3b9af7","poly":"cardio","fiche":"153","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **≥ 4-5 jours** de chevauchement et **2 INR efficaces à 24 h** d'intervalle.","prio":"P2","sec":"s5"},{"id":"fc-153-e93b78","poly":"cardio","fiche":"153","front":"HBPM chez le porteur de valve mécanique : statut ?","back":"**Pas d'AMM**, mais acceptées comme **alternative à l'HNF** par les recommandations européennes.","prio":"P3","sec":"s5"},{"id":"fc-153-bdf139","poly":"cardio","fiche":"153","front":"Valve mécanique : ajout d'un antiagrégant à l'AVK en Europe ?","back":"**Non**, sauf **transitoire** (stent récent) ou **définitif** (thromboembolie sous INR efficace).","prio":"P1","sec":"s5"},{"id":"fc-153-0a6107","poly":"cardio","fiche":"153","front":"Valve mécanique : structure recommandée pour l'éducation thérapeutique ?","back":"Une **clinique des anticoagulants**.","prio":"P3","sec":"s5"},{"id":"fc-153-09864e","poly":"cardio","fiche":"153","front":"AVK : contenu de l'éducation thérapeutique ?","back":"Éviter les **coprescriptions**, connaître les **seuils d'alerte** de l'INR, consulter si **saignement**, signaler l'AVK à tout médecin.","prio":"P2","sec":"s5"},{"id":"fc-153-eb6b39","poly":"cardio","fiche":"153","front":"Automesure de l'INR : remboursement et proportion de patients concernés ?","back":"**Remboursée depuis 2017** (porteurs de valve mécanique) ; possible chez **≈ 50 %** des patients.","prio":"P2","sec":"s5"},{"id":"fc-153-84a4f0","poly":"cardio","fiche":"153","front":"Valve mécanique et geste à haut risque hémorragique : gestion de l'AVK ?","back":"**Arrêt 4 à 5 jours avant** + relais préopératoire par **héparine à dose curative**.","prio":"P1","sec":"s5"},{"id":"fc-153-1732a9","poly":"cardio","fiche":"153","front":"Geste à haut risque hémorragique sous AVK : INR visé le jour de l'acte ?","back":"**< 1,5** (**< 1,2** en neurochirurgie).","prio":"P2","sec":"s5"},{"id":"fc-153-252cc7","poly":"cardio","fiche":"153","front":"Valve mécanique : reprise de l'AVK après un geste ?","back":"Dans les **24-48 h**, sous couverture d'héparine jusqu'à INR efficace.","prio":"P2","sec":"s5"},{"id":"fc-153-175edc","poly":"cardio","fiche":"153","front":"Après chirurgie sous AVK : délai minimal de reprise de l'héparine curative ?","back":"**Pas avant la 6ᵉ heure** postopératoire.","prio":"P3","sec":"s5"},{"id":"fc-153-1d3462","poly":"cardio","fiche":"153","front":"Geste à risque hémorragique modéré (soins dentaires) sous AVK : conduite ?","back":"Le plus souvent **sans arrêter l'AVK**, après avoir vérifié un INR dans le **bas de la fourchette**.","prio":"P2","sec":"s5"},{"id":"fc-153-af1aec","poly":"cardio","fiche":"153","front":"Arrêt simple de l'AVK 3-4 jours sans relais : applicable à une valve mécanique ?","back":"**Non** (réservé à TVP/EP au-delà du 3ᵉ mois ou FA à faible risque embolique).","prio":"P2","sec":"s5"},{"id":"fc-153-f97490","poly":"cardio","fiche":"153","front":"Surdosage en AVK sans saignement : lieu de prise en charge et conduite générale ?","back":"Le plus souvent en **ambulatoire** ; chercher la **cause** ; **INR de contrôle le lendemain**.","prio":"P2","sec":"s5"},{"id":"fc-153-531794","poly":"cardio","fiche":"153","front":"Valve mécanique (cible 3), 4 < INR < 6 sans saignement : conduite ?","back":"Pas de saut de prise, pas de vitamine K : **adapter la posologie**.","prio":"P3","sec":"s5"},{"id":"fc-153-9e61a1","poly":"cardio","fiche":"153","front":"Valve mécanique (cible 3), 6 < INR < 10 sans saignement : conduite ?","back":"**Sauter une prise** ; avis cardiologique pour discuter **1-2 mg de vitamine K per os**.","prio":"P3","sec":"s5"},{"id":"fc-153-836498","poly":"cardio","fiche":"153","front":"Valve mécanique, INR > 10 sans saignement : conduite ?","back":"**Avis spécialisé sans délai** ou **hospitalisation**.","prio":"P3","sec":"s5"},{"id":"fc-153-0b90b6","poly":"cardio","fiche":"153","front":"Porteur de valve mécanique : prescription constituant une notion inacceptable ?","back":"Prescrire un **AOD** (anti-IIa ou anti-Xa).","prio":"P1","sec":"s5"},{"id":"fc-153-9f7d17","poly":"cardio","fiche":"153","front":"Bioprothèse aortique en rythme sinusal : antithrombotique ?","back":"**Aspirine ou AVK 3 mois**, puis **plus rien**.","prio":"P1","sec":"s6"},{"id":"fc-153-dddda4","poly":"cardio","fiche":"153","front":"Bioprothèse aortique : autres options citées que l'aspirine ?","back":"**AOD** ou simple **antiagrégant** pendant **au moins 3 mois** (AVK par certaines équipes).","prio":"P3","sec":"s6"},{"id":"fc-153-7b0652","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale en rythme sinusal : antithrombotique ?","back":"**AVK les 3 premiers mois**, puis plus rien.","prio":"P1","sec":"s6"},{"id":"fc-153-07d35b","poly":"cardio","fiche":"153","front":"Bioprothèse tricuspide ou plastie mitrale : antithrombotique ?","back":"**AVK 3 mois**, puis plus rien.","prio":"P2","sec":"s6"},{"id":"fc-153-2ea47f","poly":"cardio","fiche":"153","front":"Bioprothèse après le 3ᵉ mois : AOD autorisés ?","back":"**Oui**, si l'indication **n'est pas valvulaire** (FA…).","prio":"P2","sec":"s6"},{"id":"fc-153-85bbff","poly":"cardio","fiche":"153","front":"Bioprothèse + FA : faut-il anticoaguler au long cours ?","back":"**Oui** : la FA impose une anticoagulation au long cours.","prio":"P1","sec":"s6"},{"id":"fc-153-0ac068","poly":"cardio","fiche":"153","front":"Bioprothèse mitrale + FA : AOD dès le postopératoire ?","back":"**Toléré dès le postopératoire** immédiat.","prio":"P2","sec":"s6"},{"id":"fc-153-3707e4","poly":"cardio","fiche":"153","front":"Bioprothèse aortique + FA : AOD ?","back":"**Envisageable dès le postopératoire**.","prio":"P3","sec":"s6"},{"id":"fc-153-816a65","poly":"cardio","fiche":"153","front":"TAVI en rythme sinusal : antithrombotique ?","back":"**Aspirine faible dose seule**, au long cours ; **pas d'anticoagulation efficace**.","prio":"P1","sec":"s6"},{"id":"fc-153-b13418","poly":"cardio","fiche":"153","front":"TAVI + FA ou maladie thromboembolique : antithrombotique ?","back":"**AVK ou AOD seul**, au long cours, **sans aspirine** associée.","prio":"P1","sec":"s6"},{"id":"fc-153-dc2357","poly":"cardio","fiche":"153","front":"AOD : valve mécanique versus bioprothèse ?","back":"**Interdits** sur valve mécanique ; **permis** sur bioprothèse (FA dès le postopératoire, ou après 3 mois si indication non valvulaire).","prio":"P1","sec":"s6"},{"id":"fc-153-c9a8a4","poly":"cardio","fiche":"153","front":"Porteur de prothèse : pourquoi une prophylaxie draconienne à vie ?","back":"**Sujet à risque infectieux** : risque majoré d'**endocardite** ; prévenir et traiter tout foyer, surtout **ORL et dentaire**.","prio":"P1","sec":"s7"},{"id":"fc-153-5b53ed","poly":"cardio","fiche":"153","front":"Porteur de prothèse chez le dentiste : document à présenter ?","back":"Sa **carte d'antibioprophylaxie**.","prio":"P2","sec":"s7"},{"id":"fc-153-8085cf","poly":"cardio","fiche":"153","front":"Porteur de prothèse : le détartrage nécessite-t-il une antibioprophylaxie ?","back":"**Oui** : tout geste dentaire à risque infectieux, **détartrage compris**.","prio":"P1","sec":"s7"},{"id":"fc-153-64fe4d","poly":"cardio","fiche":"153","front":"Porteur de prothèse : fréquence minimale du suivi dentaire ?","back":"**Au moins 2 fois par an**, contrôlé à l'interrogatoire.","prio":"P1","sec":"s7"},{"id":"fc-153-1bab5d","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : dose de référence d'amoxicilline (item 152) ?","back":"**2 g** per os ou IV, **30-60 min avant**, prise unique.","prio":"P1","sec":"s7"},{"id":"fc-153-66adba","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire selon l'item 153 (« en général ») ?","back":"**Amoxicilline 3 g**, **1 heure avant** les soins.","prio":"P2","sec":"s7"},{"id":"fc-153-9c0d10","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : alternative par céphalosporine ?","back":"**Céfazoline** (ou ceftriaxone) **1 g IM ou IV**, 30-60 min avant.","prio":"P2","sec":"s7"},{"id":"fc-153-7850aa","poly":"cardio","fiche":"153","front":"Points clés item 152 : molécules de l'antibioprophylaxie résumées ?","back":"**Amoxicilline ou clindamycine** 30-60 min avant.","prio":"P3","sec":"s7"},{"id":"fc-153-71923d","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire : soins concernés (item 152) ?","back":"Manipulation de la **gencive** ou de la **région périapicale**, ou **effraction muqueuse**.","prio":"P2","sec":"s7"},{"id":"fc-153-9a663c","poly":"cardio","fiche":"153","front":"Après remplacement valvulaire : quand l'ETT postopératoire précoce et pourquoi ?","back":"**Dans les premiers jours** ; essentielle pour **dépister les complications**.","prio":"P2","sec":"s8"},{"id":"fc-153-2193e5","poly":"cardio","fiche":"153","front":"Après remplacement valvulaire : réadaptation, quand et combien de temps ?","back":"Vers le **8ᵉ jour**, centre de **réadaptation cardiorespiratoire** pour **3 à 4 semaines**.","prio":"P2","sec":"s8"},{"id":"fc-153-7377fe","poly":"cardio","fiche":"153","front":"Porteur de prothèse : rythme du suivi par le médecin traitant ?","back":"À **1 mois**, puis **tous les 3 mois** (clinique + équilibre de l'AVK).","prio":"P1","sec":"s8"},{"id":"fc-153-2f92f8","poly":"cardio","fiche":"153","front":"Porteur de prothèse : quand l'ETT de référence ?","back":"Au **2ᵉ-4ᵉ mois**, chez le cardiologue.","prio":"P1","sec":"s8"},{"id":"fc-153-817035","poly":"cardio","fiche":"153","front":"ETT de référence : pourquoi attendre le 2ᵉ-4ᵉ mois ?","back":"Une fois corrigées l'**anémie** et la **tachycardie** postopératoires (qui augmentent le débit).","prio":"P2","sec":"s8"},{"id":"fc-153-8e62f5","poly":"cardio","fiche":"153","front":"Porteur de prothèse : fréquence du suivi cardiologique au long cours ?","back":"**1 à 2 fois/an** ; suivi spécialisé **au minimum annuel**.","prio":"P1","sec":"s8"},{"id":"fc-153-8c830b","poly":"cardio","fiche":"153","front":"Porteur de prothèse : les 3 documents ?","back":"**Carte de porteur de prothèse** · **carnet de surveillance de l'anticoagulant** · **carte d'antibioprophylaxie**.","prio":"P1","sec":"s8"},{"id":"fc-153-88e393","poly":"cardio","fiche":"153","front":"Carte de porteur de prothèse : informations et moment de remise ?","back":"**Type, diamètre, numéro de série** ; remise **à la sortie de chirurgie cardiaque**.","prio":"P3","sec":"s8"},{"id":"fc-153-f9968c","poly":"cardio","fiche":"153","front":"Suivi du porteur de prothèse : 5 volets ?","back":"**Cartes**, **clinique**, **ECG**, **échocardiographie**, **biologie** (INR).","prio":"P2","sec":"s8"},{"id":"fc-153-fa03f5","poly":"cardio","fiche":"153","front":"Bioprothèse : auscultation normale ?","back":"Bruits **identiques à une valve native** ; en aortique, **petit souffle éjectionnel systolique** normal.","prio":"P2","sec":"s8"},{"id":"fc-153-db2548","poly":"cardio","fiche":"153","front":"Valve mécanique : auscultation normale ?","back":"Bruits d'ouverture et surtout de fermeture **intenses, claqués, métalliques** (doubles ailettes récentes moins bruyantes).","prio":"P2","sec":"s8"},{"id":"fc-153-e6ffe2","poly":"cardio","fiche":"153","front":"Prothèse : modifications auscultatoires pathologiques ?","back":"Bruits **moins intenses** ou **variables** (hors FA) ; **souffle systolique** nouveau/renforcé ; **bruit diastolique** surajouté.","prio":"P1","sec":"s8"},{"id":"fc-153-b58c59","poly":"cardio","fiche":"153","front":"Porteur de prothèse : points à vérifier à chaque consultation ?","back":"Pas de **symptômes**, de **fièvre** ni foyer infectieux, ni manifestation **ischémique** ou **hémorragique** ; suivi **dentaire** régulier.","prio":"P2","sec":"s8"},{"id":"fc-153-b34e2c","poly":"cardio","fiche":"153","front":"Porteur de prothèse : dyspnée ou récidive d'insuffisance cardiaque, conduite ?","back":"Suspecter une **dysfonction de prothèse** → **réhospitalisation**.","prio":"P1","sec":"s8"},{"id":"fc-153-2c5170","poly":"cardio","fiche":"153","front":"Porteur de prothèse : 3 situations où ne pas adresser au spécialiste est inacceptable ?","back":"Patient **symptomatique** · **souffle de novo** (symptomatique ou non) · **suivi annuel**.","prio":"P1","sec":"s8"},{"id":"fc-153-4c3208","poly":"cardio","fiche":"153","front":"Porteur de prothèse : apports et limites de l'ECG ?","back":"Surveille le **rythme** (régression d'HVG/HVD) ; **ne renseigne pas spécifiquement sur la prothèse**.","prio":"P2","sec":"s9"},{"id":"fc-153-37db4c","poly":"cardio","fiche":"153","front":"Porteur de prothèse : principal intérêt de l'ECG ?","back":"Dépister un **passage en FA**, surtout avec une prothèse **mitrale**.","prio":"P2","sec":"s9"},{"id":"fc-153-7ce8a8","poly":"cardio","fiche":"153","front":"Valve mécanique sans complication : rythme de l'ETT ?","back":"**Tous les 1 à 2 ans**.","prio":"P1","sec":"s9"},{"id":"fc-153-2366e3","poly":"cardio","fiche":"153","front":"Bioprothèse conventionnelle : rythme de l'ETT ?","back":"À **3 mois**, **1 an**, puis **chaque année**.","prio":"P1","sec":"s9"},{"id":"fc-153-b1ea67","poly":"cardio","fiche":"153","front":"Prothèses justifiant une vigilance échographique accrue ?","back":"**TAVI**, bioprothèses de **dernière génération**, situations à risque de **dégénérescence précoce**.","prio":"P3","sec":"s9"},{"id":"fc-153-d08352","poly":"cardio","fiche":"153","front":"Prothèse : rôle respectif ETT et ETO ?","back":"**ETT** = surveillance ; **ETO** = diagnostic des **dysfonctions** (seulement si suspicion).","prio":"P1","sec":"s9"},{"id":"fc-153-aa625d","poly":"cardio","fiche":"153","front":"Prothèse : 3 suspicions imposant une ETO systématique ?","back":"**Thrombose**, **endocardite**, **désinsertion**.","prio":"P1","sec":"s9"},{"id":"fc-153-75fcb1","poly":"cardio","fiche":"153","front":"Prothèse mitrale : intérêt particulier de l'ETO ?","back":"Elle est **très bien vue** par voie transœsophagienne.","prio":"P3","sec":"s9"},{"id":"fc-153-dc801b","poly":"cardio","fiche":"153","front":"Dysfonction de prothèse : imagerie de recours ?","back":"**Imagerie multimodale** : ETO, **radiocinéma**, scanner, TEP-scanner.","prio":"P3","sec":"s9"},{"id":"fc-153-33ee49","poly":"cardio","fiche":"153","front":"Complications thromboemboliques : valve mécanique ou bioprothèse ?","back":"**Beaucoup plus** fréquentes sur valve **mécanique**.","prio":"P1","sec":"s10"},{"id":"fc-153-5ef859","poly":"cardio","fiche":"153","front":"Thromboses de prothèse : période de risque maximal ?","back":"La **1re année** (collerette non endothélialisée) ; le risque **persiste** ensuite.","prio":"P2","sec":"s10"},{"id":"fc-153-305a45","poly":"cardio","fiche":"153","front":"Thrombose de prothèse : situations à risque plus élevé ?","back":"Prothèse **mitrale** · prothèse **ancienne** (bille) · **FA** · **dysfonction VG**.","prio":"P2","sec":"s10"},{"id":"fc-153-8bbcfd","poly":"cardio","fiche":"153","front":"Embolies systémiques d'origine prothétique : localisation principale ?","back":"**Cérébrales dans 70 %** des cas (AIT, AVC).","prio":"P1","sec":"s10"},{"id":"fc-153-3a653c","poly":"cardio","fiche":"153","front":"Embolies d'origine prothétique : autres localisations ?","back":"**Ischémie aiguë de membre**, **IDM** par embolie coronaire, **infarctus rénal ou splénique**.","prio":"P3","sec":"s10"},{"id":"fc-153-2a13ae","poly":"cardio","fiche":"153","front":"Thrombose non obstructive de valve mécanique : terrain et diagnostic ?","back":"Surtout prothèses **mitrales** ; thrombus sur la **face atriale** vu en **ETO**.","prio":"P2","sec":"s10"},{"id":"fc-153-076c47","poly":"cardio","fiche":"153","front":"Thromboembolie sous INR efficace (valve mécanique) : conduite ?","back":"Ajout **définitif** d'un **antiagrégant**.","prio":"P2","sec":"s10"},{"id":"fc-153-428571","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : présentation clinique ?","back":"Accidents **brutaux** : **OAP**, **syncope**, **choc**, voire **mort subite**.","prio":"P1","sec":"s10"},{"id":"fc-153-8f28f5","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : auscultation ?","back":"**Bruits de prothèse atténués** ; souffle systolique (aortique) ou **roulement diastolique** (mitrale).","prio":"P1","sec":"s10"},{"id":"fc-153-a8118c","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : examens diagnostiques ?","back":"**Radiocinéma** (jeu diminué) ; **ETT + ETO** (gradients élevés, thrombus) ; **scanner injecté synchronisé**.","prio":"P2","sec":"s10"},{"id":"fc-153-4bd308","poly":"cardio","fiche":"153","front":"Valve mécanique mitrale : gradient moyen transmitral normal ?","back":"**< 6 mmHg**.","prio":"P3","sec":"s10"},{"id":"fc-153-b56246","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : sur quel type surtout ?","back":"Les prothèses **percutanées** (TAVI) ; plus rarement chirurgicales.","prio":"P2","sec":"s10"},{"id":"fc-153-e63fb1","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : signe ETT évocateur ?","back":"Gradients qui montent **brutalement** (**> 10 mmHg**, gradient moyen jusqu'à > 20) **sans calcification** des cusps.","prio":"P2","sec":"s10"},{"id":"fc-153-b734b1","poly":"cardio","fiche":"153","front":"Thrombose de bioprothèse : confirmation et traitement ?","back":"**ETO** (image d'addition) ± scanner (hypodense) ; **anticoagulation par AVK ou AOD**.","prio":"P2","sec":"s10"},{"id":"fc-153-a1098f","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : premier examen biologique ?","back":"**INR en urgence** (anticoagulation souvent insuffisante).","prio":"P1","sec":"s10"},{"id":"fc-153-3cde76","poly":"cardio","fiche":"153","front":"Thrombose obstructive de valve mécanique : lieu d'hospitalisation et traitement médical ?","back":"**USIC** ; **héparine IV à la seringue + aspirine** (bolus IV puis per os).","prio":"P1","sec":"s10"},{"id":"fc-153-f92f56","poly":"cardio","fiche":"153","front":"Thrombose de valve mécanique : indications de réintervention urgente ?","back":"Thrombose **aiguë** (mortalité **30 %**) ou ailette bloquée **non réversible** sous héparine-aspirine.","prio":"P2","sec":"s10"},{"id":"fc-153-5ee509","poly":"cardio","fiche":"153","front":"Thrombose de valve mécanique : indications de la thrombolyse ?","back":"**Chirurgie contre-indiquée** ou forme **subaiguë résistante** à l'anticoagulation.","prio":"P2","sec":"s10"},{"id":"fc-153-efe00c","poly":"cardio","fiche":"153","front":"Thrombose de prothèse : pourquoi penser aux hémocultures ?","back":"**Fébricule** possible : distinction (ou association) avec une **endocardite** parfois difficile.","prio":"P2","sec":"s10"},{"id":"fc-153-cb34c7","poly":"cardio","fiche":"153","front":"Fièvre inexpliquée chez un porteur de prothèse : premier geste ?","back":"**Hémocultures systématiques avant toute antibiothérapie**, puis échocardiographie.","prio":"P1","sec":"s11"},{"id":"fc-153-ff6e35","poly":"cardio","fiche":"153","front":"Fièvre chez un porteur de prothèse : 2 notions inacceptables ?","back":"Antibiothérapie **à l'aveugle** ; **ne pas penser à l'endocardite**.","prio":"P1","sec":"s11"},{"id":"fc-153-f9af9f","poly":"cardio","fiche":"153","front":"EI postopératoire précoce sur prothèse : germes ?","back":"Germes **hospitaliers** parfois multirésistants, surtout **staphylocoque doré ou blanc** (contamination peropératoire).","prio":"P1","sec":"s11"},{"id":"fc-153-8000c5","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : présentation et lésions ?","back":"En général **aiguë**, avec **abcès de l'anneau** et **désinsertion**.","prio":"P2","sec":"s11"},{"id":"fc-153-e92dc5","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : délai maximal de révélation ?","back":"**Jusqu'à 1 an** après la chirurgie.","prio":"P2","sec":"s11"},{"id":"fc-153-f07880","poly":"cardio","fiche":"153","front":"EI postopératoire précoce : traitement habituel ?","back":"**Réintervention précoce** le plus souvent.","prio":"P2","sec":"s11"},{"id":"fc-153-cb4abf","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : germes ?","back":"Proches de la valve native, mais **staphylocoque dans 50 %** des cas.","prio":"P2","sec":"s11"},{"id":"fc-153-c778c4","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : pronostic ?","back":"**Meilleur** que l'EI précoce.","prio":"P2","sec":"s11"},{"id":"fc-153-02f01f","poly":"cardio","fiche":"153","front":"EI tardive sur prothèse : indications de réintervention ?","back":"**Sepsis non maîtrisé**, **risque embolique** important, **dysfonction sévère**, **atteinte périvalvulaire** (désinsertion).","prio":"P2","sec":"s11"},{"id":"fc-153-1ef2f5","poly":"cardio","fiche":"153","front":"EI sur prothèse : intérêt du TEP-scanner ?","back":"Aide au **diagnostic** et **bilan des emboles** ; fixation focale autour de la prothèse ; utile **dès le postopératoire**.","prio":"P2","sec":"s11"},{"id":"fc-153-afccf5","poly":"cardio","fiche":"153","front":"EI sur prothèse : qui discute le dossier ?","back":"Un **staff multidisciplinaire** (**équipe endocardite**).","prio":"P2","sec":"s11"},{"id":"fc-153-30b188","poly":"cardio","fiche":"153","front":"EI sur prothèse < 1 an : antibiothérapie probabiliste ?","back":"**Vancomycine** (ou daptomycine) **+ gentamicine + rifampicine**.","prio":"P1","sec":"s11"},{"id":"fc-153-1ca6b0","poly":"cardio","fiche":"153","front":"EI sur prothèse ≥ 1 an, communautaire : antibiothérapie probabiliste ?","back":"**Ampicilline + ceftriaxone** (ou oxacilline) **+ gentamicine**.","prio":"P2","sec":"s11"},{"id":"fc-153-5a28f7","poly":"cardio","fiche":"153","front":"EI sur prothèse à staphylocoque méti-S : traitement ?","back":"**Cloxacilline** (ou céfazoline) **+ rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-153-0bf16c","poly":"cardio","fiche":"153","front":"EI sur prothèse à streptocoque oral : traitement ?","back":"**Pénicilline G** (ou amoxicilline ou ceftriaxone) **6 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-153-661144","poly":"cardio","fiche":"153","front":"EI sur prothèse : durée des schémas antibiotiques ?","back":"**6 semaines**, inchangée même si chirurgie.","prio":"P1","sec":"s11"},{"id":"fc-153-4b8a6f","poly":"cardio","fiche":"153","front":"EI sur prothèse : indications infectieuses de chirurgie liées au germe ?","back":"**Staphylococcus aureus** ou bactéries **à Gram négatif non HACEK**.","prio":"P2","sec":"s11"},{"id":"fc-153-da9987","poly":"cardio","fiche":"153","front":"EI : risque selon prothèse biologique ou mécanique ?","back":"**Le même** ; pronostic plus sévère que sur valve native.","prio":"P3","sec":"s11"},{"id":"fc-153-bbbd79","poly":"cardio","fiche":"153","front":"Hémorragies sous AVK : types possibles ?","back":"**Cérébral**, **digestif**, **hématurie**, ménométrorragies, hématome post-traumatique.","prio":"P3","sec":"s12"},{"id":"fc-153-cebc6c","poly":"cardio","fiche":"153","front":"Saignement digestif ou hématurie sous AVK : que rechercher ?","back":"Une **lésion organique sous-jacente**.","prio":"P2","sec":"s12"},{"id":"fc-153-e622c0","poly":"cardio","fiche":"153","front":"Hémorragie grave sous AVK : critères ?","back":"Non contrôlable par moyens usuels · **instabilité hémodynamique** · geste hémostatique · **transfusion** · localisation menaçant le pronostic vital/fonctionnel.","prio":"P1","sec":"s12"},{"id":"fc-153-14e07f","poly":"cardio","fiche":"153","front":"Hémorragie sous AVK : mesures locales possibles ?","back":"**Compression**, hémostatique local (colle), **vasoconstricteur** local (adrénaline), **embolisation**.","prio":"P3","sec":"s12"},{"id":"fc-153-446590","poly":"cardio","fiche":"153","front":"Hémorragie non grave sous AVK : conduite ?","back":"Souvent en **ambulatoire** ; **INR en urgence** ; corriger un surdosage ; rechercher la cause.","prio":"P2","sec":"s12"},{"id":"fc-153-3aebb0","poly":"cardio","fiche":"153","front":"Traumatisme crânien sous AVK : conduite ?","back":"**INR en urgence**, **scanner cérébral en urgence**, hospitalisation **au moins 24 h**.","prio":"P1","sec":"s12"},{"id":"fc-153-0c30f2","poly":"cardio","fiche":"153","front":"Hémorragie grave sous AVK : antidotes ?","back":"**Vitamine K** + **CCP (PPSB)** ; INR en urgence sans attendre le résultat pour traiter.","prio":"P2","sec":"s12"},{"id":"fc-153-b3b6f8","poly":"cardio","fiche":"153","front":"Valve mécanique et hémorragie sévère : gestion de l'anticoagulation ?","back":"**Arrêter l'AVK** mais **garder obligatoirement une héparine** (HNF : **TCA 1,5 à 2 fois le témoin**).","prio":"P2","sec":"s12"},{"id":"fc-153-203289","poly":"cardio","fiche":"153","front":"Valve mécanique : quand interrompre toute anticoagulation ?","back":"**Très temporairement**, seulement si le saignement **menace la vie** (**hémorragie intracrânienne**).","prio":"P2","sec":"s12"},{"id":"fc-153-80b872","poly":"cardio","fiche":"153","front":"CCP et vitamine K : pourquoi les associer ?","back":"CCP d'action **très rapide mais courte** ; vitamine K agit en **quelques heures**.","prio":"P3","sec":"s12"},{"id":"fc-153-af259a","poly":"cardio","fiche":"153","front":"Après CCP : surveillance de l'INR ?","back":"**À 30 min** (CCP complémentaire si > 1,5), puis **6-8 h** après, puis **1 fois/jour**.","prio":"P3","sec":"s12"},{"id":"fc-153-250d8b","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : définition ?","back":"Altération **non infectieuse** des feuillets (**calcifications** ou **déchirure**) → **sténose et/ou fuite**.","prio":"P1","sec":"s13"},{"id":"fc-153-1ef477","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : facteurs de précocité ?","back":"Type de substitut, site **mitral > aortique**, âge **jeune > âgé**.","prio":"P2","sec":"s13"},{"id":"fc-153-38d981","poly":"cardio","fiche":"153","front":"Bioprothèse : délai moyen de réopération selon les notions indispensables ?","back":"En moyenne **10 ans** après la pose.","prio":"P3","sec":"s13"},{"id":"fc-153-3cd470","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : signes d'appel ?","back":"**Souffle** qui apparaît ou change, **symptômes d'effort**, cusps calcifiées ou prothèse sténosante/fuyante à l'écho, **IC**.","prio":"P2","sec":"s13"},{"id":"fc-153-8ba495","poly":"cardio","fiche":"153","front":"Dégénérescence de bioprothèse : examens diagnostiques ?","back":"**ETT** ; **scanner** souvent nécessaire pour la distinguer d'une **thrombose**.","prio":"P2","sec":"s13"},{"id":"fc-153-e9c58d","poly":"cardio","fiche":"153","front":"Dégénérescence sévère et symptomatique : traitement ?","back":"**Réintervention** (souvent à risque, redux) ou **valve-in-valve** percutané, discuté en Heart Team.","prio":"P1","sec":"s13"},{"id":"fc-153-899874","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : conséquence hémodynamique ?","back":"**Fuite paraprothétique**.","prio":"P2","sec":"s14"},{"id":"fc-153-f64caa","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : 2 mécanismes ?","back":"**Spontanée** (sutures lâchées sur tissus fragiles) ou, le plus souvent, **endocardite infectieuse**.","prio":"P2","sec":"s14"},{"id":"fc-153-22c38c","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : souffle selon la position ?","back":"**Diastolique** si prothèse aortique ; **systolique** si prothèse mitrale.","prio":"P2","sec":"s14"},{"id":"fc-153-900f37","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : signes d'appel ?","back":"**Souffle nouveau**, flux de régurgitation anormal à l'écho, **anémie hémolytique**, insuffisance cardiaque.","prio":"P2","sec":"s14"},{"id":"fc-153-de707d","poly":"cardio","fiche":"153","front":"Hémolyse mécanique : bilan biologique ?","back":"**LDH élevées**, **haptoglobine basse**, **schizocytes**.","prio":"P2","sec":"s14"},{"id":"fc-153-c1ce1f","poly":"cardio","fiche":"153","front":"Hémolyse : quel marqueur signe l'origine mécanique ?","back":"Les **schizocytes** (hématies fragmentées).","prio":"P2","sec":"s14"},{"id":"fc-153-d5bf8e","poly":"cardio","fiche":"153","front":"Désinsertion importante et symptomatique : traitement ?","back":"Réintervention **chirurgicale** ou **percutanée** avec un **plug** dans la zone désinsérée.","prio":"P3","sec":"s14"},{"id":"fc-153-1c4f00","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : quelle cause rechercher systématiquement ?","back":"Une **endocardite** (hémocultures, échographie).","prio":"P2","sec":"s14"},{"id":"fc-153-af77e4","poly":"cardio","fiche":"153","front":"Bioprothèse dont les gradients montent : dégénérescence ou thrombose ?","back":"Dégénérescence : **progressive**, cusps **calcifiées** ; thrombose : **brutale**, **sans calcification**.","prio":"P1","sec":"s15"},{"id":"fc-153-ce167b","poly":"cardio","fiche":"153","front":"Porteur de prothèse avec AIT ou AVC : examens ?","back":"**INR** et **ETO** (thrombose obstructive ou non).","prio":"P2","sec":"s15"},{"id":"fc-153-ac8039","poly":"cardio","fiche":"153","front":"Porteur de prothèse avec souffle nouveau sans symptôme : conduite ?","back":"**Avis cardiologique**, même asymptomatique ; ETT.","prio":"P1","sec":"s15"},{"id":"fc-153-10c169","poly":"cardio","fiche":"153","front":"Porteur de prothèse fébrile : quelles complications peuvent coexister ?","back":"**Thrombose** et **endocardite**.","prio":"P2","sec":"s15"},{"id":"fc-153-004099","poly":"cardio","fiche":"153","front":"Survie après remplacement valvulaire : déterminants ?","back":"**Maladie initiale**, son **retentissement cardiaque**, **comorbidités**, **complications des prothèses**.","prio":"P3","sec":"s16"},{"id":"fc-153-79f51b","poly":"cardio","fiche":"153","front":"Porteur de prothèse : 2 contraintes à vie ?","back":"**Observance de l'anticoagulant** (valve mécanique) et **prophylaxie de l'endocardite** (toutes).","prio":"P1","sec":"s16"},{"id":"fc-153-7b325b","poly":"cardio","fiche":"153","front":"Valve mécanique : objectif principal du suivi par le médecin traitant ?","back":"L'**équilibre parfait** de l'anticoagulation.","prio":"P1","sec":"s16"},{"id":"fc-153-8930fa","poly":"cardio","fiche":"153","front":"Remplacement percutané : situations où il est en essor ?","back":"**Sténose aortique sur valve native** et **bioprothèse dégénérée**, dans des indications sélectionnées.","prio":"P3","sec":"s16"},{"id":"fc-153-1e6084","poly":"cardio","fiche":"153","front":"Porteur de prothèse : notion inacceptable concernant l'éducation ?","back":"**Oublier l'éducation** : prévention de l'EI et, si besoin, anticoagulation efficace.","prio":"P1","sec":"s16"},{"id":"fc-153-94d651","poly":"cardio","fiche":"153","front":"Antibioprophylaxie dentaire chez un allergique à la pénicilline : notion inacceptable ?","back":"Prescrire une **pénicilline** malgré l'allergie.","prio":"P1","sec":"s7"},{"id":"fc-153-15aa47","poly":"cardio","fiche":"153","front":"Valve-in-valve à anticiper, espérance de vie > 10 ans : quelle bioprothèse chirurgicale préférer ?","back":"Une bioprothèse **qui s'y prête** : **stentée**, **bien visible**, à **feuillets internes courts**.","prio":"P3","sec":"s2"},{"id":"fc-153-b3c48b","poly":"cardio","fiche":"153","front":"Prévention de l'endocardite : mesures non médicamenteuses ?","back":"**Hygiène buccodentaire**, dentiste 2 fois/an, désinfection des plaies, **éviter tatouages et piercings**, limiter les voies veineuses, **pas d'automédication antibiotique**, consulter vite si fièvre.","prio":"P2","sec":"s7"},{"id":"fc-153-f4377b","poly":"cardio","fiche":"153","front":"EI sur prothèse : caractéristiques de l'antibiothérapie ?","back":"**Bactéricide**, molécules **synergiques**, **fortes doses**, **IV**, durée prolongée ; adaptée à l'antibiogramme avec l'infectiologue.","prio":"P2","sec":"s11"},{"id":"fc-153-9d159a","poly":"cardio","fiche":"153","front":"EI : part des cas avec chirurgie indiquée en phase active ?","back":"Environ **50 %** : prévenir le chirurgien cardiaque **dès le diagnostic**.","prio":"P3","sec":"s11"},{"id":"fc-153-c7b799","poly":"cardio","fiche":"153","front":"EI sur prothèse : quand faire l'ETO ?","back":"En cas de **forte suspicion**, et **aussi une fois le diagnostic confirmé** (bilan précis des lésions).","prio":"P2","sec":"s11"},{"id":"fc-153-adab29","poly":"cardio","fiche":"153","front":"EI sur prothèse : quand débuter une antibiothérapie probabiliste ?","back":"Forte suspicion, **sepsis sévère** ou chirurgie urgente, toujours **après les hémocultures**.","prio":"P2","sec":"s11"},{"id":"fc-153-58dd94","poly":"cardio","fiche":"153","front":"EI sur prothèse à staphylocoque méti-R : traitement ?","back":"**Vancomycine + rifampicine** 6 semaines **+ gentamicine 2 semaines**.","prio":"P3","sec":"s11"},{"id":"fc-153-e6272b","poly":"cardio","fiche":"153","front":"EI sur prothèse à entérocoque : traitement ?","back":"**Amoxicilline** (ou ampicilline) **+ ceftriaxone** (ou gentamicine à sa place) : **6 semaines** (gentamicine **2 semaines**).","prio":"P3","sec":"s11"},{"id":"fc-153-7757c8","poly":"cardio","fiche":"153","front":"Surdosage en AVK sur valve mécanique (cible 3) : quelle colonne du tableau ne pas appliquer ?","back":"Celle de l'**INR cible 2,5** (saut de prise dès 4 < INR < 6 ; arrêt + vitamine K si INR > 6).","prio":"P3","sec":"s5"},{"id":"fc-153-283999","poly":"cardio","fiche":"153","front":"Relais par héparine autour d'un geste : risques propres ?","back":"Complications **hémorragiques et thrombotiques**, malgré une apparence rassurante.","prio":"P3","sec":"s5"},{"id":"fc-153-8173d9","poly":"cardio","fiche":"153","front":"Après une thrombose de valve mécanique : mesures à la sortie ?","back":"AVK à vie avec **INR cible à adapter** + **éducation renforcée** (le **sous-dosage** est la cause principale).","prio":"P2","sec":"s10"},{"id":"fc-153-d283cb","poly":"cardio","fiche":"153","front":"Désinsertion de prothèse : examens de confirmation ?","back":"**ETT** et surtout **ETO** (systématique si suspicion) : fuite paraprothétique.","prio":"P2","sec":"s14"},{"id":"fc-203-682fa9","poly":"cardio","fiche":"203","front":"Dyspnée : définition ?","back":"**Sensation subjective** de gêne respiratoire lors d'une activité qui normalement n'en provoque pas.","prio":"P1","sec":"s1"},{"id":"fc-203-8e8e8d","poly":"cardio","fiche":"203","front":"Dyspnée et insuffisance respiratoire : exemple de dyspnée sans insuffisance respiratoire ?","back":"**Anémie aiguë**.","prio":"P1","sec":"s1"},{"id":"fc-203-1d0f00","poly":"cardio","fiche":"203","front":"Exemple d'insuffisance respiratoire sans dyspnée ?","back":"**Coma**.","prio":"P1","sec":"s1"},{"id":"fc-203-6b2ba8","poly":"cardio","fiche":"203","front":"Dyspnée aiguë versus chronique : délais d'installation ?","back":"Aiguë : **heures à jours** ; chronique : **semaines à mois**.","prio":"P1","sec":"s1"},{"id":"fc-203-4f546e","poly":"cardio","fiche":"203","front":"Orthopnée : définition ?","back":"Dyspnée en **décubitus**.","prio":"P1","sec":"s1"},{"id":"fc-203-8a9c17","poly":"cardio","fiche":"203","front":"Platypnée : définition ?","back":"Dyspnée en **orthostatisme** (debout).","prio":"P1","sec":"s1"},{"id":"fc-203-7a1ce6","poly":"cardio","fiche":"203","front":"NYHA I : définition ?","back":"**Aucune gêne** lors des efforts habituels.","prio":"P2","sec":"s1"},{"id":"fc-203-11e8fd","poly":"cardio","fiche":"203","front":"NYHA II : définition ?","back":"Gêne aux **efforts importants** : marche rapide ou en côte, escaliers **≥ 2 étages**.","prio":"P1","sec":"s1"},{"id":"fc-203-8886b1","poly":"cardio","fiche":"203","front":"NYHA III : définition ?","back":"Gêne aux **efforts peu intenses** : marche à plat, escaliers **< 2 étages**.","prio":"P1","sec":"s1"},{"id":"fc-203-083e8c","poly":"cardio","fiche":"203","front":"NYHA IV : définition ?","back":"Gêne **au repos** ou aux **efforts minimes** (se laver, s'habiller).","prio":"P1","sec":"s1"},{"id":"fc-203-2e347d","poly":"cardio","fiche":"203","front":"Échelle MRC : nombre de stades ?","back":"**5 stades, de 0 à 4** (version pneumologique).","prio":"P2","sec":"s1"},{"id":"fc-203-cde9d7","poly":"cardio","fiche":"203","front":"MRC stade 0 ?","back":"Dyspnée seulement lors d'un **exercice intense**.","prio":"P3","sec":"s1"},{"id":"fc-203-cc29be","poly":"cardio","fiche":"203","front":"MRC stade 1 ?","back":"Dyspnée à la **marche rapide à plat** ou en montant une **pente légère**.","prio":"P3","sec":"s1"},{"id":"fc-203-fb1119","poly":"cardio","fiche":"203","front":"MRC stade 2 ?","back":"Marche à plat **plus lente que les gens du même âge**, ou arrêt à son propre rythme.","prio":"P3","sec":"s1"},{"id":"fc-203-83badd","poly":"cardio","fiche":"203","front":"MRC stade 3 ?","back":"Arrêt après environ **100 m** ou quelques minutes de marche.","prio":"P2","sec":"s1"},{"id":"fc-203-9a6d06","poly":"cardio","fiche":"203","front":"MRC stade 4 ?","back":"Empêche de **sortir de chez soi**, ou dès l'**habillage**.","prio":"P3","sec":"s1"},{"id":"fc-203-ae73df","poly":"cardio","fiche":"203","front":"Dyspnée : éléments de l'interrogatoire ?","back":"**Terrain** · **rapidité d'installation** · **circonstances** (effort, position, facteurs déclenchants, horaire) · **intensité** · **signes associés**.","prio":"P2","sec":"s2"},{"id":"fc-203-c71b00","poly":"cardio","fiche":"203","front":"Dyspnée inspiratoire : orientation ?","back":"Cause **laryngée**.","prio":"P1","sec":"s2"},{"id":"fc-203-edbe0f","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire : orientation ?","back":"Cause **bronchique** (asthme, BPCO).","prio":"P1","sec":"s2"},{"id":"fc-203-f7ec2e","poly":"cardio","fiche":"203","front":"Polypnée et bradypnée : seuils ?","back":"Polypnée **> 20 cycles/min** ; bradypnée **< 10 cycles/min**.","prio":"P1","sec":"s2"},{"id":"fc-203-25c4c2","poly":"cardio","fiche":"203","front":"Dyspnée de Kussmaul : rythme et orientation ?","back":"Inspiration, pause, expiration, pause ; **acidose métabolique**.","prio":"P1","sec":"s2"},{"id":"fc-203-5539ef","poly":"cardio","fiche":"203","front":"Dyspnée de Cheyne-Stokes : rythme et orientation ?","back":"Polypnée **croissante puis décroissante** entrecoupée d'**apnées** ; **IC grave** (origine centrale).","prio":"P1","sec":"s2"},{"id":"fc-203-e1f3bd","poly":"cardio","fiche":"203","front":"Hyperpnée et hypopnée : définitions ?","back":"Hyperpnée : volume courant **augmenté** ; hypopnée (oligopnée) : volume courant **diminué**.","prio":"P3","sec":"s2"},{"id":"fc-203-f5b5b0","poly":"cardio","fiche":"203","front":"Dyspnée : examens physiques à ne pas oublier en dehors des poumons ?","back":"**Cardiovasculaire** complet (IC, **TVP**), **ORL**, **thyroïdien**, **neuromusculaire**.","prio":"P2","sec":"s2"},{"id":"fc-203-119e3a","poly":"cardio","fiche":"203","front":"Dyspnée : éléments d'orientation à l'auscultation pulmonaire ?","back":"Normale, **crépitants**, **sibilants**, râles bronchiques, **abolition du murmure vésiculaire**.","prio":"P3","sec":"s2"},{"id":"fc-203-1ebd64","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : 3 mécanismes traduits par les signes de gravité ?","back":"**Épuisement ventilatoire**, **hypoxémie/hypercapnie**, **défaillance circulatoire**.","prio":"P2","sec":"s3"},{"id":"fc-203-b55649","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de lutte (muscles accessoires) ?","back":"**Tirage** sus-sternal/sus-claviculaire, creusement intercostal, **battement des ailes du nez**, **balancement thoraco-abdominal**, expiration abdominale active.","prio":"P1","sec":"s3"},{"id":"fc-203-9e5356","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de gravité généraux et circulatoires ?","back":"**Cyanose**, sueurs, **tachycardie > 120/min**, **marbrures**, angoisse, **SpO₂ < 90 %**.","prio":"P1","sec":"s3"},{"id":"fc-203-55d01b","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : signes de gravité neurologiques ?","back":"**Astérixis** (encéphalopathie respiratoire), **agitation**, **somnolence**, coma.","prio":"P1","sec":"s3"},{"id":"fc-203-4f0c03","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : conduite si SpO₂ < 90 % ?","back":"**Oxygène**.","prio":"P1","sec":"s3"},{"id":"fc-203-3f2e2a","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec signes de choc : priorité ?","back":"**Traiter le choc** avant l'analyse de la dyspnée.","prio":"P1","sec":"s3"},{"id":"fc-203-6e54d5","poly":"cardio","fiche":"203","front":"Exacerbation de BPCO : signes de gravité ?","back":"Dyspnée de **repos**, cyanose, désaturation, **polypnée > 25/min**, défaillance hémodynamique, signes neurologiques, **hypercapnie**.","prio":"P1","sec":"s3"},{"id":"fc-203-39daff","poly":"cardio","fiche":"203","front":"Asthme aigu grave : signes ?","back":"**Thorax bloqué** en inflation, **disparition des sibilants et du murmure**, pouls paradoxal possible, **parole impossible**.","prio":"P1","sec":"s3"},{"id":"fc-203-c6c51e","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : causes dont la gravité est souvent sous-estimée ?","back":"**Laryngées** (œdème de Quincke) et **neuromusculaires** (polyradiculonévrites).","prio":"P2","sec":"s3"},{"id":"fc-203-664081","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : quelle omission est une notion inacceptable ?","back":"**Oublier les examens de 1re intention**.","prio":"P1","sec":"s4"},{"id":"fc-203-2e87ce","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : bilan de 1re intention ?","back":"**Gazométrie artérielle**, **ECG**, **radiographie thoracique**, NFP, iono, glycémie, **BNP/NT-proBNP**, **D-dimères** si suspicion d'EP.","prio":"P1","sec":"s4"},{"id":"fc-203-dec0ed","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : apport de la gazométrie artérielle ?","back":"**Gravité** (hypoxémie, hypercapnie) ; parfois orientation (**effet shunt** de l'EP).","prio":"P2","sec":"s4"},{"id":"fc-203-bbb792","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : apport de l'ECG ?","back":"Signes d'**EP**, de **coronaropathie**, de **trouble du rythme**.","prio":"P2","sec":"s4"},{"id":"fc-203-5bfd82","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : ce que recherche la radiographie du thorax ?","back":"Anomalie de la **paroi**, de la **plèvre**, du **parenchyme**, du **médiastin** ; **cardiomégalie**.","prio":"P2","sec":"s4"},{"id":"fc-203-3ec168","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : seuil de BNP rendant l'IC peu probable ?","back":"**BNP < 100 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-203-7d9080","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : seuil de NT-proBNP rendant l'IC peu probable ?","back":"**NT-proBNP < 300 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-203-97f668","poly":"cardio","fiche":"203","front":"NT-proBNP : seuils selon l'âge (ESC 2021) ?","back":"**> 450** avant 55 ans ; **> 900** de 55 à 75 ans ; **> 1 800 pg/mL** après 75 ans.","prio":"P3","sec":"s4"},{"id":"fc-203-c9cdf0","poly":"cardio","fiche":"203","front":"D-dimères : seuil et condition d'exclusion de l'EP ?","back":"**< 500 µg/L**, si probabilité clinique **faible ou intermédiaire**.","prio":"P1","sec":"s4"},{"id":"fc-203-a3c7ab","poly":"cardio","fiche":"203","front":"Suspicion d'EP : examens de 2e intention ?","back":"**Échodoppler veineux** des MI et/ou **angioscanner pulmonaire** et/ou **scintigraphie V/Q**.","prio":"P1","sec":"s4"},{"id":"fc-203-d8bd94","poly":"cardio","fiche":"203","front":"Dyspnée : autres examens de 2e intention (hors EP) ?","back":"**Échocardiographie doppler**, **EFR**, cathétérisme cardiaque, épreuve d'effort métabolique.","prio":"P2","sec":"s4"},{"id":"fc-203-38e620","poly":"cardio","fiche":"203","front":"Dyspnée aiguë de l'adulte : 3 causes les plus fréquentes ?","back":"**OAP**, **embolie pulmonaire**, **décompensation d'une maladie respiratoire chronique**.","prio":"P1","sec":"s5"},{"id":"fc-203-b45566","poly":"cardio","fiche":"203","front":"Dyspnée aiguë de l'enfant : 3 causes les plus fréquentes ?","back":"**Corps étranger inhalé**, **laryngite**, **épiglottite**.","prio":"P1","sec":"s5"},{"id":"fc-203-0e53c3","poly":"cardio","fiche":"203","front":"Arbre décisionnel de la dyspnée aiguë : première question ?","back":"**Signes de choc ?**","prio":"P1","sec":"s5"},{"id":"fc-203-e4ab34","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire avec sibilants ou ronchi : causes ?","back":"**Asthme**, **BPCO**, **pseudo-asthme cardiaque**.","prio":"P1","sec":"s5"},{"id":"fc-203-c41007","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec crépitants : orientations ?","back":"**OAP** (IVG) ; attention pseudo-asthme et **SDRA** ; avec fièvre/condensation : **pneumopathie**.","prio":"P1","sec":"s5"},{"id":"fc-203-d08af3","poly":"cardio","fiche":"203","front":"Dyspnée aiguë avec syndrome pleural : causes ?","back":"**Pneumothorax** ou **épanchement pleural**.","prio":"P1","sec":"s5"},{"id":"fc-203-8358fe","poly":"cardio","fiche":"203","front":"Dyspnée aiguë isolée (auscultation normale) : causes à chercher ?","back":"**EP**, **sepsis sévère**, **anémie**, **acidose métabolique**, **atteinte neuromusculaire** ; psychogène en dernier.","prio":"P1","sec":"s5"},{"id":"fc-203-68192b","poly":"cardio","fiche":"203","front":"Dyspnée psychogène (hyperventilation) : statut diagnostique ?","back":"**Diagnostic d'élimination**.","prio":"P1","sec":"s5"},{"id":"fc-203-9e68a5","poly":"cardio","fiche":"203","front":"Atteinte neuromusculaire : particularité de la dyspnée ?","back":"**Tardive**, peut précéder de peu l'**arrêt respiratoire**.","prio":"P1","sec":"s5"},{"id":"fc-203-5f9bb8","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : cause cardiaque la plus fréquente ?","back":"L'**œdème aigu du poumon**.","prio":"P1","sec":"s6"},{"id":"fc-203-142e7d","poly":"cardio","fiche":"203","front":"OAP : signes cliniques ?","back":"**Orthopnée**, wheezing, **crépitants bilatéraux**, expectoration **rose saumonée**.","prio":"P1","sec":"s6"},{"id":"fc-203-cf355e","poly":"cardio","fiche":"203","front":"OAP : terrain et facteur déclenchant typiques ?","back":"Cardiopathie connue, **ATCD d'infarctus** ; déclencheur type **FA**.","prio":"P2","sec":"s6"},{"id":"fc-203-8caf15","poly":"cardio","fiche":"203","front":"OAP : arguments paracliniques ?","back":"Radio : **œdème alvéolaire**, cardiomégalie ; ECG : **onde Q**, FA rapide ; **BNP/NT-proBNP élevé**.","prio":"P1","sec":"s6"},{"id":"fc-203-befbe8","poly":"cardio","fiche":"203","front":"OAP : argument diagnostique thérapeutique ?","back":"Amélioration sous **diurétique** ou **trinitrine IV**.","prio":"P2","sec":"s6"},{"id":"fc-203-dc1cba","poly":"cardio","fiche":"203","front":"Pseudo-asthme cardiaque : clinique et signification ?","back":"Orthopnée, **sibilants ± crépitants** ; **équivalent d'OAP** (forme bronchospastique).","prio":"P2","sec":"s6"},{"id":"fc-203-0b52d3","poly":"cardio","fiche":"203","front":"Tamponnade : signes cliniques ?","back":"Orthopnée, tachycardie, **bruits du cœur assourdis**, **poumons normaux**, **turgescence jugulaire**, **pouls paradoxal**.","prio":"P2","sec":"s6"},{"id":"fc-203-a061c4","poly":"cardio","fiche":"203","front":"Pouls paradoxal : définition ?","back":"Pouls qui **diminue à l'inspiration profonde**.","prio":"P3","sec":"s6"},{"id":"fc-203-feab1b","poly":"cardio","fiche":"203","front":"Tamponnade : contexte et tableau hémodynamique habituel ?","back":"Complication d'une **péricardite avec épanchement** ; en général **collapsus** ou **état de choc** avec signes d'**insuffisance ventriculaire droite**.","prio":"P3","sec":"s6"},{"id":"fc-203-c5678d","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : troubles du rythme pouvant être en cause ?","back":"**Troubles du rythme supraventriculaire** et **tachycardie ventriculaire**.","prio":"P3","sec":"s6"},{"id":"fc-203-0bef22","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : 5 causes cardiaques ?","back":"**OAP**, **pseudo-asthme cardiaque**, **tamponnade**, **troubles du rythme**, **choc cardiogénique**.","prio":"P2","sec":"s6"},{"id":"fc-203-a5ee89","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : contextes favorisants ?","back":"**Alitement**, **long voyage**, **immobilisation plâtrée**, **période postopératoire**.","prio":"P1","sec":"s7"},{"id":"fc-203-31a76e","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : mode de début ?","back":"En règle **très brutal** ; douleur thoracique fréquente mais **inconstante**.","prio":"P2","sec":"s7"},{"id":"fc-203-0741b6","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : auscultation ?","back":"**Souvent normale**, sauf **tachycardie**.","prio":"P1","sec":"s7"},{"id":"fc-203-95bddc","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : anomalie gazométrique ?","back":"**Effet shunt** : **hypoxie avec hypocapnie**.","prio":"P1","sec":"s7"},{"id":"fc-203-57c315","poly":"cardio","fiche":"203","front":"Embolie pulmonaire : complication à distance ?","back":"**Hypertension pulmonaire post-embolique**.","prio":"P2","sec":"s7"},{"id":"fc-203-090fbf","poly":"cardio","fiche":"203","front":"EP : 2 tableaux trompeurs chez le patient respiratoire ?","back":"EP sur **terrain bronchoemphysémateux** ; EP **associée** à une exacerbation de BPCO.","prio":"P2","sec":"s7"},{"id":"fc-203-0ac37d","poly":"cardio","fiche":"203","front":"Crise d'asthme : signes ?","back":"Dyspnée **expiratoire** avec **sibilants**.","prio":"P2","sec":"s8"},{"id":"fc-203-a9bfcd","poly":"cardio","fiche":"203","front":"Exacerbation de BPCO : déclencheur fréquent et signes ?","back":"**Surinfection bronchique** ; majoration de la dyspnée, de la toux, du volume ou de la **purulence des crachats**.","prio":"P2","sec":"s8"},{"id":"fc-203-e3bd43","poly":"cardio","fiche":"203","front":"Pneumopathie infectieuse : signes ?","back":"**Fièvre** + toux/expectoration purulente ; **foyer de crépitants** ± condensation ; opacité **systématisée**.","prio":"P2","sec":"s8"},{"id":"fc-203-bd1602","poly":"cardio","fiche":"203","front":"SDRA : définition ?","back":"Défaillance pulmonaire aiguë très sévère : **perméabilité alvéolocapillaire augmentée**, **œdème lésionnel**, mortalité élevée.","prio":"P2","sec":"s8"},{"id":"fc-203-0d4ee6","poly":"cardio","fiche":"203","front":"SDRA : causes ?","back":"**Pneumopathie**, **sepsis**, **inhalation**, EP, **traumatisme**, état de choc, toxique.","prio":"P2","sec":"s8"},{"id":"fc-203-f3d467","poly":"cardio","fiche":"203","front":"SDRA : principal diagnostic différentiel ?","back":"L'**œdème pulmonaire hémodynamique** (OAP cardiogénique).","prio":"P2","sec":"s8"},{"id":"fc-203-00a68d","poly":"cardio","fiche":"203","front":"Pneumothorax : terrain ?","back":"Sujet **longiligne**, **tabac**, **emphysème**.","prio":"P2","sec":"s8"},{"id":"fc-203-75fc05","poly":"cardio","fiche":"203","front":"Pneumothorax : signes d'examen et radiologiques ?","back":"Abolition des **vibrations vocales** et du **murmure**, **tympanisme** ; **hyperclarté** radiographique.","prio":"P1","sec":"s8"},{"id":"fc-203-7e52c2","poly":"cardio","fiche":"203","front":"BPCO : quelle décompensation cardiaque une surinfection bronchopulmonaire peut-elle déclencher ?","back":"Une **poussée d'insuffisance cardiaque** (les deux maladies s'intriquent).","prio":"P2","sec":"s8"},{"id":"fc-203-0b33d4","poly":"cardio","fiche":"203","front":"BPCO encombré : piège diagnostique concernant l'OAP ?","back":"L'**OAP est souvent diagnostiqué par excès**.","prio":"P2","sec":"s8"},{"id":"fc-203-8b44a8","poly":"cardio","fiche":"203","front":"Atélectasie : origines possibles ?","back":"**Bénigne** ou **maligne**.","prio":"P3","sec":"s8"},{"id":"fc-203-4b8244","poly":"cardio","fiche":"203","front":"Dyspnée laryngotrachéale : signes ?","back":"Dyspnée **inspiratoire**, bradypnée inspiratoire, **cornage**, **tirage** ; **dysphonie** fréquente si origine laryngée.","prio":"P1","sec":"s9"},{"id":"fc-203-72d05c","poly":"cardio","fiche":"203","front":"Dyspnée laryngée : causes ?","back":"**Œdème de Quincke**, **corps étranger** inhalé, chez l'enfant **épiglottite** et **laryngite**.","prio":"P1","sec":"s9"},{"id":"fc-203-ad0453","poly":"cardio","fiche":"203","front":"Œdème de Quincke : contexte fréquent ?","back":"**Choc anaphylactique** (œdème de la glotte).","prio":"P2","sec":"s9"},{"id":"fc-203-e5458c","poly":"cardio","fiche":"203","front":"Dyspnée trachéale : causes ?","back":"**Sténose tumorale**, **corps étranger**, **granulome post-intubation**.","prio":"P3","sec":"s9"},{"id":"fc-203-7b3193","poly":"cardio","fiche":"203","front":"Dyspnée inspiratoire d'installation progressive : orientation ?","back":"Cause **néoplasique**.","prio":"P2","sec":"s9"},{"id":"fc-203-994cf0","poly":"cardio","fiche":"203","front":"Dyspnée laryngée : 2 consignes immédiates ?","back":"**Laisser le patient assis** ; **ne pas examiner l'oropharynx**.","prio":"P1","sec":"s9"},{"id":"fc-203-a746ac","poly":"cardio","fiche":"203","front":"Dyspnée : causes neurologiques ?","back":"**Atteintes bulbaires**, **polyradiculonévrite**, **myasthénie**.","prio":"P2","sec":"s9"},{"id":"fc-203-73a309","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : causes rares à connaître ?","back":"Pseudo-asthme, tamponnade, chocs, acidose, hyperthermie, sténoses trachéales, **intoxication au CO**, **pneumocystose**.","prio":"P3","sec":"s9"},{"id":"fc-203-eeaec3","poly":"cardio","fiche":"203","front":"Causes extrathoraciques (acidose, anémie) : type de trouble ventilatoire ?","back":"Plutôt une **polypnée** qu'une dyspnée.","prio":"P3","sec":"s9"},{"id":"fc-203-cf84a8","poly":"cardio","fiche":"203","front":"Dyspnée : notion indispensable sur les causes non cardiopulmonaires ?","back":"Savoir évoquer les causes **extracardiaques et extrapulmonaires** (anémie, ORL…).","prio":"P2","sec":"s10"},{"id":"fc-203-f060be","poly":"cardio","fiche":"203","front":"OAP cardiogénique : diagnostic différentiel lésionnel ?","back":"**OAP lésionnel du SDRA** (contexte d'agression : infection, sepsis, inhalation, traumatisme, choc).","prio":"P2","sec":"s10"},{"id":"fc-203-c04667","poly":"cardio","fiche":"203","front":"Dyspnée aiguë grave : examens de 2e intention aux urgences ?","back":"**Angioscanner** ou scanner pulmonaire, **échocardiographie**, selon l'orientation.","prio":"P3","sec":"s11"},{"id":"fc-203-90576a","poly":"cardio","fiche":"203","front":"Item 203 : traitements cités directement (sans dose) ?","back":"**Oxygène** dès SpO₂ < 90 % ; réponse au **diurétique** ou à la **trinitrine IV** comme argument d'OAP.","prio":"P3","sec":"s11"},{"id":"fc-203-d34153","poly":"cardio","fiche":"203","front":"OAP au domicile : prise en charge initiale ?","back":"Patient **assis/demi-assis**, **furosémide IV**, **nitrés sublinguaux** si PAS > 100 mmHg, Samu selon gravité, hospitalisation.","prio":"P1","sec":"s12"},{"id":"fc-203-d4ec45","poly":"cardio","fiche":"203","front":"OAP : dose de furosémide ?","back":"**1 mg/kg IV**, à répéter si besoin ; adaptée ensuite à la **diurèse**.","prio":"P1","sec":"s12"},{"id":"fc-203-7134b7","poly":"cardio","fiche":"203","front":"OAP : condition des nitrés sublinguaux ?","back":"**PAS > 100 mmHg**.","prio":"P1","sec":"s12"},{"id":"fc-203-8f4dfa","poly":"cardio","fiche":"203","front":"OAP : trinitrine IV, dose et condition ?","back":"**1 mg/h**, adaptée à la PA, si **PAS ≥ 110 mmHg**.","prio":"P1","sec":"s12"},{"id":"fc-203-ee4c91","poly":"cardio","fiche":"203","front":"OAP : objectif d'oxygénation ?","back":"**SaO₂ > 90 %** (sonde nasale ou masque) ; prudence si risque d'hypercapnie.","prio":"P2","sec":"s12"},{"id":"fc-203-509031","poly":"cardio","fiche":"203","front":"OAP : indications de la CPAP ?","back":"Échec du traitement médical : **FR > 25/min** ou **SaO₂ < 90 %**.","prio":"P1","sec":"s12"},{"id":"fc-203-d9843f","poly":"cardio","fiche":"203","front":"OAP : quand intuber ?","back":"CPAP insuffisante, **détresse persistante** ou **épuisement** → ventilation invasive.","prio":"P2","sec":"s12"},{"id":"fc-203-547df5","poly":"cardio","fiche":"203","front":"OAP : place de la morphine ?","back":"**Non systématique** : seulement si anxiété importante non contrôlée ou douleur thoracique.","prio":"P1","sec":"s12"},{"id":"fc-203-6f0172","poly":"cardio","fiche":"203","front":"OAP : bêtabloquant pendant la poussée ?","back":"**Ne pas l'introduire** ; si déjà pris, en général arrêté ou diminué.","prio":"P1","sec":"s12"},{"id":"fc-203-7562e0","poly":"cardio","fiche":"203","front":"OAP : prévention thromboembolique ?","back":"**HBPM préventive systématique** (ex. énoxaparine 2 000 ou 4 000 UI/j) ; **plaquettes** avant toute héparine.","prio":"P2","sec":"s12"},{"id":"fc-203-f40149","poly":"cardio","fiche":"203","front":"HBPM et insuffisance rénale sévère : règle ?","back":"**Contre-indiquée si ClCr < 30 mL/min** ; la prescrire = **notion inacceptable**.","prio":"P1","sec":"s12"},{"id":"fc-203-a6928e","poly":"cardio","fiche":"203","front":"OAP déclenché par une FA rapide : traitement ?","back":"**Digoxine IV** + **anticoagulation efficace**.","prio":"P2","sec":"s12"},{"id":"fc-203-4b8c52","poly":"cardio","fiche":"203","front":"Digoxine IV en urgence chez l'insuffisant cardiaque : condition ?","back":"**Kaliémie normale**.","prio":"P3","sec":"s12"},{"id":"fc-203-227bae","poly":"cardio","fiche":"203","front":"OAP sur poussée hypertensive : traitement (item 234) ?","back":"**Nicardipine IV** 1 à 5 mg/h.","prio":"P2","sec":"s12"},{"id":"fc-203-fd9f6d","poly":"cardio","fiche":"203","front":"Nicardipine et insuffisance cardiaque : divergence du Collège ?","back":"Item 224 : **CI dans l'IC** (nitrés IV en 1re intention) ; item 234 : **nicardipine IV** pour l'OAP hypertensif.","prio":"P3","sec":"s12"},{"id":"fc-203-807ada","poly":"cardio","fiche":"203","front":"OAP : quand instaurer IEC, ARA2 ou ARNI ?","back":"**Secondairement**, **après la poussée**.","prio":"P2","sec":"s12"},{"id":"fc-203-9412f1","poly":"cardio","fiche":"203","front":"Insuffisance cardiaque aiguë : causes à traitement spécifique (CHAMPIT) ?","back":"**SCA**, urgence **hypertensive**, **arythmie**, complication **mécanique** d'un SCA, **EP**, **infection**, **tamponnade**.","prio":"P1","sec":"s12"},{"id":"fc-203-764dc1","poly":"cardio","fiche":"203","front":"Choc cardiogénique : définition ?","back":"**PA < 90 mmHg** + **hypoperfusion** (PA pincée, oligurie, marbrures, extrémités froides, obnubilation).","prio":"P1","sec":"s13"},{"id":"fc-203-78d635","poly":"cardio","fiche":"203","front":"Choc cardiogénique : prise en charge et monitorage ?","back":"**Inotropes**, **sonde urinaire systématique**, **PA invasive** radiale ; sans réponse : **assistance circulatoire**.","prio":"P2","sec":"s13"},{"id":"fc-203-ff66d6","poly":"cardio","fiche":"203","front":"Choc cardiogénique : inotrope de référence ?","back":"**Dobutamine IV**.","prio":"P1","sec":"s13"},{"id":"fc-203-88fb32","poly":"cardio","fiche":"203","front":"Choc cardiogénique sous bêtabloquant : inotrope à préférer ?","back":"**Milrinone** ou **énoximone** (inhibiteurs des phosphodiestérases).","prio":"P2","sec":"s13"},{"id":"fc-203-049af4","poly":"cardio","fiche":"203","front":"Lévosimendan : classe et usage ?","back":"**Sensibilisateur calcique** ; parfois si sevrage des inotropes impossible.","prio":"P3","sec":"s13"},{"id":"fc-203-7ce192","poly":"cardio","fiche":"203","front":"Tamponnade : traitement ?","back":"Urgence médicochirurgicale en USIC : **remplissage par macromolécules**, **ponction péricardique écho-guidée** ou drainage chirurgical.","prio":"P1","sec":"s13"},{"id":"fc-203-1340dd","poly":"cardio","fiche":"203","front":"Tamponnade confirmée : pourquoi drainer ?","back":"Risque d'**arrêt cardiaque par adiastolie**.","prio":"P2","sec":"s13"},{"id":"fc-203-f0dc4c","poly":"cardio","fiche":"203","front":"EP grave (choc ou hypotension sévère) : traitement ?","back":"Réanimation/USIC, **fibrinolyse** sauf CI ; si CI ou échec : **embolectomie chirurgicale sous CEC**.","prio":"P1","sec":"s13"},{"id":"fc-203-9e4ea3","poly":"cardio","fiche":"203","front":"EP sans choc : fibrinolyse systématique ?","back":"**Non** ; risque intermédiaire haut : reperfusion seulement si **détérioration**.","prio":"P1","sec":"s13"},{"id":"fc-203-ee80ac","poly":"cardio","fiche":"203","front":"EP à haut risque : dose initiale d'HNF ?","back":"**500 UI/kg/j**, puis adaptée au TCA ou à l'anti-Xa.","prio":"P2","sec":"s13"},{"id":"fc-203-d20322","poly":"cardio","fiche":"203","front":"HNF dans l'EP (item 226) : cibles biologiques ?","back":"TCA **1,5 à 2,5 × le témoin** ou anti-Xa **0,3 à 0,7 U**.","prio":"P2","sec":"s13"},{"id":"fc-203-98d8cb","poly":"cardio","fiche":"203","front":"HNF selon l'item 330 : cibles biologiques ?","back":"TCA **2 à 3 × le témoin** et/ou anti-Xa **0,5 à 0,8/mL**.","prio":"P3","sec":"s13"},{"id":"fc-203-3fcbfd","poly":"cardio","fiche":"203","front":"HNF : antidote et utilisation en insuffisance rénale ?","back":"Antidote : **sulfate de protamine IV** ; utilisable si **ClCr < 30 mL/min**.","prio":"P2","sec":"s13"},{"id":"fc-203-9a3e79","poly":"cardio","fiche":"203","front":"Relais HNF-AVK dans l'EP : quand arrêter l'HNF ?","back":"Après **≥ 5 jours** et **2 INR consécutifs > 2** à 24 h d'intervalle.","prio":"P2","sec":"s13"},{"id":"fc-203-01776f","poly":"cardio","fiche":"203","front":"EP : durée minimale d'anticoagulation ?","back":"**Au moins 3 mois**.","prio":"P1","sec":"s13"},{"id":"fc-203-51855e","poly":"cardio","fiche":"203","front":"EP grave avec choc : durée d'anticoagulation ?","back":"Facteur de risque majeur persistant : **> 6 mois**, voire au long cours.","prio":"P3","sec":"s13"},{"id":"fc-203-865380","poly":"cardio","fiche":"203","front":"FA avec état de choc : traitement ?","back":"**Cardioversion électrique immédiate**.","prio":"P2","sec":"s13"},{"id":"fc-203-6ebf21","poly":"cardio","fiche":"203","front":"Suspicion de tachycardie ventriculaire : critères ECG ?","back":"**FC > 100/min**, **QRS > 120 ms** sur **au moins 3 battements**.","prio":"P2","sec":"s13"},{"id":"fc-203-fe0dbf","poly":"cardio","fiche":"203","front":"Suspicion de TV : conduite immédiate ?","back":"**Alerter le 15** et se préparer à une **réanimation**.","prio":"P2","sec":"s13"},{"id":"fc-203-6ecc0d","poly":"cardio","fiche":"203","front":"Tamponnade chez l'anticoagulé : neutralisation selon l'anticoagulant ?","back":"Héparine : **protamine** ; AVK : **vitamine K** ; dabigatran : **idarucizumab** ; autres AOD : **PPSB** ou Feiba®.","prio":"P3","sec":"s13"},{"id":"fc-203-1a9104","poly":"cardio","fiche":"203","front":"Dyspnée expiratoire grave : examen pour rechercher l'hypercapnie ?","back":"**Gazométrie artérielle**.","prio":"P2","sec":"s14"},{"id":"fc-203-a68e2c","poly":"cardio","fiche":"203","front":"SDRA : lieu de prise en charge ?","back":"**Réanimation**.","prio":"P1","sec":"s14"},{"id":"fc-203-196398","poly":"cardio","fiche":"203","front":"Dyspnée aiguë : surveillance commune à toutes les situations ?","back":"**Gazométrie** + réévaluation des **signes de gravité**.","prio":"P2","sec":"s15"},{"id":"fc-203-ddd360","poly":"cardio","fiche":"203","front":"OAP : paramètres pour adapter furosémide et trinitrine ?","back":"**Diurèse** pour le furosémide ; **PA** pour la trinitrine.","prio":"P2","sec":"s15"},{"id":"fc-203-d96674","poly":"cardio","fiche":"203","front":"HNF : quand contrôler TCA ou anti-Xa ?","back":"Entre 2 injections (SC) ou **4 h** après le début de la perfusion IV, et **4 h** après chaque changement de dose.","prio":"P3","sec":"s15"},{"id":"fc-203-716cd0","poly":"cardio","fiche":"203","front":"HNF : surveillance plaquettaire ?","back":"**2 fois/semaine pendant 21 jours** (risque de **TIH**).","prio":"P1","sec":"s15"},{"id":"fc-203-e7f0d4","poly":"cardio","fiche":"203","front":"TIH : critères plaquettaires ?","back":"Plaquettes **< 150 G/L** ou **baisse de 50 %**.","prio":"P2","sec":"s15"},{"id":"fc-203-cb0c77","poly":"cardio","fiche":"203","front":"Après un OAP : correction des causes curables ?","back":"**Revascularisation coronaire** si possible, **correction valvulaire**.","prio":"P3","sec":"s15"},{"id":"fc-203-026241","poly":"cardio","fiche":"203","front":"Dyspnée chronique : premier examen à réaliser ?","back":"**NFP** : toujours **éliminer une anémie**.","prio":"P1","sec":"s16"},{"id":"fc-203-85cedb","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes les plus fréquentes ?","back":"**Cardiaques** ou **pulmonaires**.","prio":"P2","sec":"s16"},{"id":"fc-203-c8e6d5","poly":"cardio","fiche":"203","front":"Dyspnée chronique : examens à discuter après la NFP ?","back":"**EFR** + gazométrie, **ECG**, **radio**, **échocardiographie**, épreuve d'effort avec gaz, scanner, cathétérisme.","prio":"P2","sec":"s16"},{"id":"fc-203-8a2b45","poly":"cardio","fiche":"203","front":"Épreuve d'effort avec mesure des gaz respiratoires : intérêt ?","back":"**Objective la gêne** et oriente vers une cause **cardiaque ou pulmonaire**.","prio":"P2","sec":"s16"},{"id":"fc-203-368345","poly":"cardio","fiche":"203","front":"Dyspnée chronique : valeur d'un BNP strictement normal ?","back":"**IC peu probable** (BNP moins validé qu'en aigu).","prio":"P2","sec":"s16"},{"id":"fc-203-f86cc6","poly":"cardio","fiche":"203","front":"Dyspnée chronique, IC suspectée : examen clé ?","back":"**Échocardiographie** (cardiopathie, pressions intracardiaques élevées).","prio":"P2","sec":"s16"},{"id":"fc-203-348f95","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes cardiaques ?","back":"Toutes les causes d'**insuffisance cardiaque** + **constriction péricardique**.","prio":"P1","sec":"s17"},{"id":"fc-203-6327cb","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes pulmonaires obstructives ?","back":"**BPCO**, **asthme à dyspnée continue**.","prio":"P1","sec":"s17"},{"id":"fc-203-7ea8a7","poly":"cardio","fiche":"203","front":"Dyspnée chronique : causes de trouble restrictif ?","back":"**PID**, **pneumoconioses**, séquelles pleurales post-tuberculeuses, **paralysie phrénique**, **cyphoscoliose**, **obésité morbide**.","prio":"P2","sec":"s17"},{"id":"fc-203-2da7a6","poly":"cardio","fiche":"203","front":"Pneumoconiose : définition ?","back":"Maladie **non cancéreuse** due à l'**inhalation de particules** (ex. **asbestose**).","prio":"P3","sec":"s17"},{"id":"fc-203-5558ab","poly":"cardio","fiche":"203","front":"HTAP : causes ?","back":"**Idiopathique**, **familiale**, **connectivite** (sclérodermie), **shunt intracardiaque**, **VIH**, **toxique**.","prio":"P2","sec":"s17"},{"id":"fc-203-e405fa","poly":"cardio","fiche":"203","front":"HTP post-embolique : définition ?","back":"Complication **grave** après une ou plusieurs EP, avec HTP **précapillaire** persistante.","prio":"P2","sec":"s17"},{"id":"fc-203-5801ad","poly":"cardio","fiche":"203","front":"Dyspnée chronique : autres causes (hors cœur, poumon, HTP) ?","back":"Obstacle des **VAS**, **anémie**, acidose, cause **neuromusculaire**, hyperventilation, troubles du transport de l'O₂ ou **CO**.","prio":"P2","sec":"s17"},{"id":"fc-203-8dd9c2","poly":"cardio","fiche":"203","front":"Platypnée-orthodéoxie : définition et cause à rechercher ?","back":"Dyspnée **debout** avec **désaturation** ; **shunt droite-gauche** (foramen ovale perméable).","prio":"P2","sec":"s17"},{"id":"fc-221-12f6e5","poly":"cardio","fiche":"221","front":"Athérome : définition ?","back":"Remaniements de l'**intima** des artères de **gros et moyen calibre**, par accumulation **focale**, avec **modifications de la média**.","prio":"P1","sec":"s1"},{"id":"fc-221-084fb3","poly":"cardio","fiche":"221","front":"Athérome : composants de l'accumulation focale ?","back":"**Lipides** et glucides complexes · **sang** et produits sanguins · **tissu fibreux** · **dépôts calcaires**.","prio":"P2","sec":"s1"},{"id":"fc-221-603ecf","poly":"cardio","fiche":"221","front":"Malade polyathéromateux (polyvasculaire) : définition ?","back":"Atteinte d'**au moins 2 territoires artériels**, **symptomatique** ou **asymptomatique mais significative**.","prio":"P1","sec":"s1"},{"id":"fc-221-20b2e3","poly":"cardio","fiche":"221","front":"Une plaque < 50 % non compliquée dans un 2ᵉ territoire suffit-elle à définir le polyvasculaire ?","back":"**Non** : elle reflète une athérosclérose débutante.","prio":"P1","sec":"s1"},{"id":"fc-221-bedb11","poly":"cardio","fiche":"221","front":"Sténose carotidienne à 50 % asymptomatique chez un patient AOMI : polyvasculaire ?","back":"**Oui** : atteinte **asymptomatique mais significative**.","prio":"P2","sec":"s1"},{"id":"fc-221-5fe89f","poly":"cardio","fiche":"221","front":"Athérome : quand dépister les autres territoires ?","back":"À **chaque lésion** découverte, puis **tout au long** de la prise en charge et du suivi.","prio":"P1","sec":"s1"},{"id":"fc-221-c5a94e","poly":"cardio","fiche":"221","front":"Dépistage des autres territoires athéromateux : condition d'intérêt ?","back":"Qu'il **change la prise en charge** (ex. revasculariser une sténose carotidienne trouvée dans le bilan d'une AOMI).","prio":"P2","sec":"s1"},{"id":"fc-221-712fb7","poly":"cardio","fiche":"221","front":"Maladies cardiovasculaires : rang de mortalité dans le monde ?","back":"**1re cause de mortalité** dans le monde.","prio":"P2","sec":"s2"},{"id":"fc-221-234e4c","poly":"cardio","fiche":"221","front":"Mortalité CV en France : rang actuel ?","back":"**2e rang, derrière le cancer** ; reste la **1re cause chez les femmes**.","prio":"P2","sec":"s2"},{"id":"fc-221-400273","poly":"cardio","fiche":"221","front":"France : niveau de mortalité CV en Europe ?","back":"Parmi les **plus faibles** ; pays à **faible niveau de risque CV** (ESC).","prio":"P3","sec":"s2"},{"id":"fc-221-2abcf8","poly":"cardio","fiche":"221","front":"Écarts de mortalité CV entre pays : explication principale ?","back":"**Environnement** et **habitudes alimentaires** plus que la génétique.","prio":"P3","sec":"s2"},{"id":"fc-221-86bacb","poly":"cardio","fiche":"221","front":"Mortalité CV : gradient géographique ?","back":"**Plus élevée** : nord et est de l'Europe ; intermédiaire : Amérique du Nord ; **plus faible** : Europe du Sud et Japon.","prio":"P3","sec":"s2"},{"id":"fc-221-13a16e","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : rapport d'incidence homme/femme ?","back":"**3 à 5 fois** plus élevée chez l'homme ; écart qui **diminue avec l'âge**.","prio":"P2","sec":"s2"},{"id":"fc-221-142ba8","poly":"cardio","fiche":"221","front":"SCA chez la femme, notamment jeune : tendance et cause ?","back":"En **augmentation**, à cause de la hausse du **tabagisme**.","prio":"P2","sec":"s2"},{"id":"fc-221-f7069d","poly":"cardio","fiche":"221","front":"Maladies CV : évolution de la mortalité et de la prévalence ?","back":"Mortalité **en baisse** (prise en charge, prévention) ; prévalence **en hausse** (**vieillissement** et baisse de la mortalité de ces maladies).","prio":"P2","sec":"s2"},{"id":"fc-221-d09639","poly":"cardio","fiche":"221","front":"Incidence mondiale des maladies CV : tendance et causes ?","back":"**Fort accroissement attendu** : alimentation, **sédentarité**, **obésité**, **diabète**.","prio":"P3","sec":"s2"},{"id":"fc-221-c5b09f","poly":"cardio","fiche":"221","front":"Pays en voie de développement : évolution des maladies athéromateuses ?","back":"**Transition épidémiologique** : prévalence et incidence en hausse.","prio":"P3","sec":"s2"},{"id":"fc-221-2f8ec4","poly":"cardio","fiche":"221","front":"Formation de la plaque : étape initiale ?","back":"**Accumulation des LDL** dans l'intima puis **oxydation** par les radicaux libres.","prio":"P2","sec":"s3"},{"id":"fc-221-56b3d3","poly":"cardio","fiche":"221","front":"Athérogenèse : devenir des monocytes attirés dans la paroi ?","back":"Ils deviennent **macrophages** puis **cellules spumeuses**.","prio":"P2","sec":"s3"},{"id":"fc-221-421b3e","poly":"cardio","fiche":"221","front":"Athérogenèse : quels récepteurs captent les LDL oxydées ?","back":"Les **récepteurs scavengers** (« éboueurs »).","prio":"P3","sec":"s3"},{"id":"fc-221-40221b","poly":"cardio","fiche":"221","front":"Dysfonction endothéliale : facteurs favorisants et conséquences ?","back":"**Tabagisme**, LDL oxydées ; baisse des capacités **vasodilatatrices** et **antithrombotiques**.","prio":"P2","sec":"s3"},{"id":"fc-221-64844a","poly":"cardio","fiche":"221","front":"Athérogenèse : rôle des métalloprotéases ?","back":"Libérées par l'inflammation, elles **détruisent la matrice extracellulaire**.","prio":"P3","sec":"s3"},{"id":"fc-221-7b74e6","poly":"cardio","fiche":"221","front":"Athérogenèse : rôle des cellules musculaires lisses ?","back":"Migrent de la **média** vers la néo-intima ; sécrètent **collagène**, matrice et facteurs de croissance.","prio":"P2","sec":"s3"},{"id":"fc-221-2f2dcc","poly":"cardio","fiche":"221","front":"Plaque d'athérome : structure finale ?","back":"**Centre lipidique** recouvert **tardivement** d'une **chape fibreuse**.","prio":"P2","sec":"s3"},{"id":"fc-221-eb8d28","poly":"cardio","fiche":"221","front":"Stries lipidiques : à quel âge sont-elles observées ?","back":"**Dès le jeune âge** (autopsie).","prio":"P3","sec":"s3"},{"id":"fc-221-099bfa","poly":"cardio","fiche":"221","front":"Plaque instable : composition et risque ?","back":"**Très lipidique** et **très inflammatoire** ; **très vulnérable à la rupture**.","prio":"P2","sec":"s3"},{"id":"fc-221-312e86","poly":"cardio","fiche":"221","front":"Plaque d'athérome stable : composition ?","back":"**Centre lipidique**, cellules **spumeuses**, musculaires et inflammatoires, recouverts d'une **chape fibreuse**.","prio":"P3","sec":"s3"},{"id":"fc-221-b5827e","poly":"cardio","fiche":"221","front":"Sténose athéromateuse : 2 modes d'aggravation ?","back":"**Progressif** (croissance de plaque) ou **brutal** (rupture/érosion → **thrombus** → réduction, voire **occlusion**).","prio":"P1","sec":"s4"},{"id":"fc-221-dcc6cc","poly":"cardio","fiche":"221","front":"Hémorragie intraplaque : conséquence ?","back":"**Aggrave la sténose** ; augmente brusquement le volume, la chape peut se rompre.","prio":"P3","sec":"s4"},{"id":"fc-221-97ad15","poly":"cardio","fiche":"221","front":"Rupture de plaque : plaques les plus exposées ?","back":"Plaques **jeunes**, riches en **lipides** et cellules inflammatoires, à **chape fine**, souvent **peu sténosantes**.","prio":"P2","sec":"s4"},{"id":"fc-221-bc5ea0","poly":"cardio","fiche":"221","front":"Rupture de plaque : est-elle toujours symptomatique ?","back":"**Non** : beaucoup restent **asymptomatiques**.","prio":"P3","sec":"s4"},{"id":"fc-221-588e6b","poly":"cardio","fiche":"221","front":"Progression de la plaque : mode principal ?","back":"**Surtout par poussées**, lors des ruptures, en incorporant du matériel thrombotique.","prio":"P3","sec":"s4"},{"id":"fc-221-ef0442","poly":"cardio","fiche":"221","front":"Régression de plaque : est-elle démontrée chez l'homme ?","back":"**Difficile à démontrer** (vue chez l'animal).","prio":"P3","sec":"s4"},{"id":"fc-221-e01ee8","poly":"cardio","fiche":"221","front":"Remodelage artériel compensateur versus constrictif ?","back":"Compensateur : **élargit** le diamètre, préserve la lumière ; constrictif : **réduit** le diamètre, majore la sténose.","prio":"P3","sec":"s4"},{"id":"fc-221-ef47c7","poly":"cardio","fiche":"221","front":"Réduction progressive de la lumière artérielle : tableaux cliniques ?","back":"**Ischémie chronique stable** : angor d'effort, claudication intermittente, claudication digestive.","prio":"P2","sec":"s4"},{"id":"fc-221-7bc876","poly":"cardio","fiche":"221","front":"Érosion de plaque : mécanisme et exemple ?","back":"Fortes contraintes de **cisaillement** → thrombose superficielle, embolisation distale ; ex. **SCA sans sus-décalage de ST**.","prio":"P3","sec":"s4"},{"id":"fc-221-927cef","poly":"cardio","fiche":"221","front":"Athérome : quand commence-t-il ?","back":"**Très tôt, dès l'enfance** ; progression selon les **FDR** et le **vieillissement**.","prio":"P2","sec":"s4"},{"id":"fc-221-9f0470","poly":"cardio","fiche":"221","front":"Accident athéromateux : sa gravité est-elle proportionnelle à l'ancienneté de l'athérome ?","back":"**Pas toujours** : une plaque coronaire **jeune** qui se rompt peut donner un infarctus ou une **mort subite**.","prio":"P2","sec":"s4"},{"id":"fc-221-31e5a0","poly":"cardio","fiche":"221","front":"Occlusion artérielle chronique asymptomatique : explication ?","back":"Une **collatéralité** supplée le territoire.","prio":"P3","sec":"s4"},{"id":"fc-221-300430","poly":"cardio","fiche":"221","front":"Anévrismes : sont-ils tous dus à l'athérome ?","back":"**Non**.","prio":"P3","sec":"s4"},{"id":"fc-221-65c987","poly":"cardio","fiche":"221","front":"Rupture de plaque : complications aiguës selon le territoire ?","back":"**SCA avec sus-décalage du ST** (thrombose occlusive), **AVC ischémique**, **ischémie aiguë** d'un membre inférieur.","prio":"P2","sec":"s4"},{"id":"fc-221-0562a3","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : de quoi dépend surtout le risque de complication ou de récidive ?","back":"Du **nombre de facteurs de risque** présents.","prio":"P2","sec":"s4"},{"id":"fc-221-3e332f","poly":"cardio","fiche":"221","front":"Athérome : sites de développement préférentiels ?","back":"Près des **flux turbulents** : **ostium**, **bifurcation**, zone de **contrainte mécanique**.","prio":"P1","sec":"s5"},{"id":"fc-221-461628","poly":"cardio","fiche":"221","front":"Maladie athéromateuse : 4 territoires principaux ?","back":"**Coronaires**, **carotides**, **artères des membres inférieurs**, **aorte abdominale**.","prio":"P1","sec":"s5"},{"id":"fc-221-be1ce1","poly":"cardio","fiche":"221","front":"Plaques de la crosse aortique : conséquence clinique ?","back":"**AVC**.","prio":"P2","sec":"s5"},{"id":"fc-221-b3a0d9","poly":"cardio","fiche":"221","front":"Sténose des artères rénales : conséquences ?","back":"**HTA** et **insuffisance rénale**.","prio":"P1","sec":"s5"},{"id":"fc-221-4ea8d1","poly":"cardio","fiche":"221","front":"Sténose des artères digestives : conséquence ?","back":"**Ischémie mésentérique**.","prio":"P1","sec":"s5"},{"id":"fc-221-161b96","poly":"cardio","fiche":"221","front":"Lésions de l'aorte terminale : complication favorisée ?","back":"**Anévrisme de l'aorte abdominale**.","prio":"P2","sec":"s5"},{"id":"fc-221-e19f0f","poly":"cardio","fiche":"221","front":"Athérome : facteurs de risque non modifiables ?","back":"**Âge**, **sexe masculin**, **antécédents familiaux**.","prio":"P1","sec":"s6"},{"id":"fc-221-51797c","poly":"cardio","fiche":"221","front":"Athérome : facteurs de risque modifiables principaux ?","back":"**Tabagisme**, **HTA**, **dyslipidémies**, **diabète**.","prio":"P1","sec":"s6"},{"id":"fc-221-0bc3a2","poly":"cardio","fiche":"221","front":"Athérome : facteurs prédisposants ?","back":"**Obésité**, **sédentarité**, stress/conditions psychosociales, **pollution atmosphérique**.","prio":"P2","sec":"s6"},{"id":"fc-221-1a6906","poly":"cardio","fiche":"221","front":"Facteur de risque CV propre à la femme : exemple ?","back":"**Ménopause précoce**.","prio":"P2","sec":"s6"},{"id":"fc-221-03e4fb","poly":"cardio","fiche":"221","front":"Marqueur de risque CV : définition ?","back":"**Associé** à un risque plus élevé, **sans lien de causalité établi**.","prio":"P1","sec":"s6"},{"id":"fc-221-d1d4c2","poly":"cardio","fiche":"221","front":"Marqueur de risque biologique : exemple ?","back":"Marqueurs inflammatoires : **CRP**.","prio":"P2","sec":"s6"},{"id":"fc-221-a693e4","poly":"cardio","fiche":"221","front":"Plaque carotidienne à l'échographie : facteur ou marqueur de risque coronarien ?","back":"**Marqueur** de risque (vasculaire).","prio":"P2","sec":"s6"},{"id":"fc-221-28b2b1","poly":"cardio","fiche":"221","front":"Prévention primaire versus secondaire : définitions ?","back":"Primaire : **avant** l'expression clinique ; secondaire : **après** une maladie CV chronique ou aiguë.","prio":"P1","sec":"s6"},{"id":"fc-221-e34587","poly":"cardio","fiche":"221","front":"Lésion sévère asymptomatique (ex. sténose carotidienne serrée) : niveau de prévention ?","back":"Stratégie en général **équivalente à la prévention secondaire**.","prio":"P1","sec":"s6"},{"id":"fc-221-0f9c49","poly":"cardio","fiche":"221","front":"Coronarien : fréquence d'une AOMI, sténose carotidienne ou rénale associée ?","back":"**20 %** chacune.","prio":"P3","sec":"s7"},{"id":"fc-221-94caa2","poly":"cardio","fiche":"221","front":"AOMI, sténose carotidienne ou AAA : fréquence d'une atteinte coronarienne associée ?","back":"**40-50 %**.","prio":"P2","sec":"s7"},{"id":"fc-221-d4dfa2","poly":"cardio","fiche":"221","front":"Quel terrain est le plus souvent polyvasculaire ?","back":"Les patients atteints d'**AOMI**.","prio":"P2","sec":"s7"},{"id":"fc-221-6963fb","poly":"cardio","fiche":"221","front":"Athérome : symptôme sexuel pouvant révéler une maladie artérielle ?","back":"La **dysfonction érectile**.","prio":"P3","sec":"s7"},{"id":"fc-221-4e876e","poly":"cardio","fiche":"221","front":"Bilan d'extension du polyathéromateux : éléments ?","back":"**FDR** + **risque CV global**, clinique de **tous les territoires**, **PA aux 2 bras**, **ECG**, **IPS**, dépistage de l'**AAA**.","prio":"P1","sec":"s7"},{"id":"fc-221-0f396b","poly":"cardio","fiche":"221","front":"PA aux deux bras : écart évocateur de sténose subclavière ?","back":"**> 15 mmHg** sur **plusieurs mesures**.","prio":"P1","sec":"s7"},{"id":"fc-221-900744","poly":"cardio","fiche":"221","front":"Polyathéromateux : place de l'ECG ?","back":"**Systématique**.","prio":"P1","sec":"s7"},{"id":"fc-221-b5e2fe","poly":"cardio","fiche":"221","front":"Bilan d'extension du polyathéromateux : chez qui dépister notamment l'AAA ?","back":"Notamment l'**homme après 65 ans**.","prio":"P1","sec":"s7"},{"id":"fc-221-56aa39","poly":"cardio","fiche":"221","front":"Polyathéromateux : critères de choix des explorations complémentaires ?","back":"Bilan **clinique**, **risque CV global**, prévalence d'un autre territoire, besoin d'un **geste invasif**.","prio":"P2","sec":"s7"},{"id":"fc-221-054c00","poly":"cardio","fiche":"221","front":"AOMI : examen d'imagerie de dépistage et de diagnostic ?","back":"**Échodoppler artériel des MI** avec **mesure de l'IPS**.","prio":"P2","sec":"s7"},{"id":"fc-221-9bcd4f","poly":"cardio","fiche":"221","front":"AAA asymptomatique : seuils d'intervention ?","back":"Diamètre **55 mm** (**50 mm chez la femme**) ou croissance **≥ 5 mm/an**.","prio":"P1","sec":"s8"},{"id":"fc-221-047ffc","poly":"cardio","fiche":"221","front":"Sténose carotidienne asymptomatique : seuil d'endartériectomie ?","back":"**> 60 %** (le plus souvent > 80 %), si espérance de vie **> 5 ans**.","prio":"P1","sec":"s8"},{"id":"fc-221-3e8fd7","poly":"cardio","fiche":"221","front":"Après un SCA : seuil de revascularisation des sténoses coronaires ?","back":"Sténoses significatives **> 70 %**.","prio":"P1","sec":"s8"},{"id":"fc-221-ae1ade","poly":"cardio","fiche":"221","front":"Angor stable ou ischémie silencieuse : la revascularisation est-elle systématique ?","back":"**Non**.","prio":"P1","sec":"s8"},{"id":"fc-221-568a6f","poly":"cardio","fiche":"221","front":"Angor stable : indications de revascularisation ?","back":"Symptômes **malgré traitement**, **FEVG altérée**, ischémie à **seuil bas** ou **étendue**, chirurgie à haut risque prévue, **FFR ≤ 0,8**.","prio":"P1","sec":"s8"},{"id":"fc-221-db14b7","poly":"cardio","fiche":"221","front":"FFR : seuil de sténose hémodynamiquement significative ?","back":"**FFR ≤ 0,8**.","prio":"P1","sec":"s8"},{"id":"fc-221-0352cf","poly":"cardio","fiche":"221","front":"Polyvasculaire en situation aiguë ou instable : conduite ?","back":"Revasculariser **rapidement la lésion coupable**, **sans prolonger le dépistage**.","prio":"P1","sec":"s8"},{"id":"fc-221-0cec23","poly":"cardio","fiche":"221","front":"Plusieurs lésions à traiter hors urgence : qui décide de l'ordre des gestes ?","back":"**Réunion pluridisciplinaire**, au cas par cas.","prio":"P2","sec":"s8"},{"id":"fc-221-2909ba","poly":"cardio","fiche":"221","front":"Bêtabloquant : chez quels patients athéromateux son efficacité est-elle prouvée ?","back":"**Seulement après un infarctus** (notamment FEVG altérée).","prio":"P1","sec":"s9"},{"id":"fc-221-341948","poly":"cardio","fiche":"221","front":"Bêtabloquant chez le polyvasculaire ou le coronarien stable : bénéfice pronostique ?","back":"**Non démontré**.","prio":"P2","sec":"s9"},{"id":"fc-221-f18f07","poly":"cardio","fiche":"221","front":"Prévention de l'athérome : moyens contre la dysfonction endothéliale ?","back":"Supprimer ou traiter **tous les FDR modifiables** (tabac, sédentarité).","prio":"P2","sec":"s10"},{"id":"fc-221-fba57e","poly":"cardio","fiche":"221","front":"Statines : actions sur la plaque d'athérome ?","back":"Baisse des **LDL**, **stabilisation** de la plaque, baisse de l'**inflammation**.","prio":"P1","sec":"s10"},{"id":"fc-221-e37dba","poly":"cardio","fiche":"221","front":"Faire régresser le volume des plaques : moyens ?","back":"**Statines à fortes doses** ± **ézétimibe**, ou **anti-PCSK9**.","prio":"P2","sec":"s10"},{"id":"fc-221-015741","poly":"cardio","fiche":"221","front":"Athérome : traitements réduisant l'inflammation ?","back":"**Aspirine** et **statines**.","prio":"P2","sec":"s10"},{"id":"fc-221-f67128","poly":"cardio","fiche":"221","front":"Athérome : traitement réduisant les contraintes mécaniques ?","back":"Les **antihypertenseurs**.","prio":"P2","sec":"s10"},{"id":"fc-221-14dfe2","poly":"cardio","fiche":"221","front":"Lésions menaçantes : gestes selon le territoire ?","back":"Coronaires : **angioplastie/pontage** ; carotides : **chirurgie/angioplastie** ; anévrismes : **chirurgie/endoprothèse** ; MI : angioplastie/pontage.","prio":"P2","sec":"s10"},{"id":"fc-221-f6a66a","poly":"cardio","fiche":"221","front":"Aspirine en prévention primaire : recommandation ?","back":"**Pas de prescription systématique**, même chez le diabétique ; seulement si très haut risque vasculaire et faible risque hémorragique.","prio":"P1","sec":"s10"},{"id":"fc-221-c45916","poly":"cardio","fiche":"221","front":"Aspirine : effets indésirables et contre-indications ?","back":"EI : **saignements**, **intolérance gastrique** ; CI rares : intolérance gastrique, **allergie**.","prio":"P2","sec":"s10"},{"id":"fc-221-195e01","poly":"cardio","fiche":"221","front":"Polyathéromateux : mesures hygiénodiététiques ?","back":"**Arrêt du tabac**, **diététique + éducation thérapeutique**, **activité physique régulière** prescrite.","prio":"P1","sec":"s11"},{"id":"fc-221-9158f5","poly":"cardio","fiche":"221","front":"Polyathéromateux : trio médicamenteux de fond ?","back":"**Antiagrégant** (aspirine ou clopidogrel) + **statine** + **IEC (ou ARA2)**.","prio":"P1","sec":"s11"},{"id":"fc-221-e6f679","poly":"cardio","fiche":"221","front":"Polyvasculaire : dose d'aspirine ?","back":"**Entre 75 et 325 mg/j**, au long cours.","prio":"P1","sec":"s11"},{"id":"fc-221-23427d","poly":"cardio","fiche":"221","front":"Coronarien : dose d'aspirine (item 339) ?","back":"**75 à 100 mg/j**.","prio":"P2","sec":"s11"},{"id":"fc-221-a4a0d3","poly":"cardio","fiche":"221","front":"Polyvasculaire : indications du clopidogrel à la place de l'aspirine ?","back":"**Intolérance à l'aspirine** ou atteinte polyvasculaire **compliquée**, notamment **AOMI**.","prio":"P1","sec":"s11"},{"id":"fc-221-0fd752","poly":"cardio","fiche":"221","front":"Prévention secondaire (très haut risque) : objectif de LDL-C ?","back":"**< 0,55 g/L** (< 1,4 mmol/L).","prio":"P1","sec":"s11"},{"id":"fc-221-f82174","poly":"cardio","fiche":"221","front":"Polyvasculaire : bénéfices des IEC (ou ARA2) ?","back":"Baisse du risque d'**infarctus** et d'**AVC** ; freinent l'altération de la **fonction rénale**.","prio":"P2","sec":"s11"},{"id":"fc-221-7d0866","poly":"cardio","fiche":"221","front":"Prévention secondaire : quelle omission est une notion inacceptable ?","back":"**Oublier l'aspirine et les statines**.","prio":"P1","sec":"s11"},{"id":"fc-221-40d952","poly":"cardio","fiche":"221","front":"Bêtabloquant après infarctus à FEVG normale : bénéfice à distance ?","back":"**Remis en cause**.","prio":"P3","sec":"s11"},{"id":"fc-221-dcb879","poly":"cardio","fiche":"221","front":"AOMI : objectifs tensionnels et glycémique (item 225) ?","back":"PAS **≤ 120-129**, PAD **≤ 70-79 mmHg** ; **HbA1c < 7 %**.","prio":"P2","sec":"s12"},{"id":"fc-221-56e450","poly":"cardio","fiche":"221","front":"AOMI : objectifs LDL et IMC ?","back":"LDL-C **< 0,55 g/L** et baisse **≥ 50 %** ; IMC **20-25 kg/m²** ; régime méditerranéen.","prio":"P2","sec":"s12"},{"id":"fc-221-424231","poly":"cardio","fiche":"221","front":"AOMI : modalités de la marche ?","back":"Régulière, de préférence **supervisée** : **≥ 30-45 min**, **≥ 3 fois/semaine**, en **ralentissant ou s'arrêtant** quelques minutes au seuil douloureux.","prio":"P1","sec":"s12"},{"id":"fc-221-1f62fb","poly":"cardio","fiche":"221","front":"AOMI : durée du réentraînement supervisé ?","back":"**3 fois/semaine pendant 12 semaines**.","prio":"P3","sec":"s12"},{"id":"fc-221-1a05c2","poly":"cardio","fiche":"221","front":"AOMI : indications de revascularisation ?","back":"Autant que possible si **ischémie permanente** ; possible si claudication sévère malgré traitement + réadaptation ; **parfois** d'emblée si périmètre **< 100 m** handicapant et/ou atteinte aorto-iliaque sévère.","prio":"P2","sec":"s12"},{"id":"fc-221-b336c6","poly":"cardio","fiche":"221","front":"AOMI : techniques de revascularisation ?","back":"**Angioplastie** (± stent) ou **pontage** (de préférence **veineux**).","prio":"P2","sec":"s12"},{"id":"fc-221-23523d","poly":"cardio","fiche":"221","front":"AOMI : bénéfice supplémentaire de la statine ?","back":"Peut **allonger le périmètre de marche**.","prio":"P3","sec":"s12"},{"id":"fc-221-b16d3c","poly":"cardio","fiche":"221","front":"AOMI : chez qui envisager un IEC ou un sartan ?","back":"Chez **tout** patient avec AOMI, **quel que soit le niveau de PA** (sauf CI).","prio":"P1","sec":"s12"},{"id":"fc-221-875b05","poly":"cardio","fiche":"221","front":"AOMI : précaution avec les bêtabloquants ?","back":"Prudence si **ischémie critique** sans revascularisation possible.","prio":"P3","sec":"s12"},{"id":"fc-221-c679b7","poly":"cardio","fiche":"221","front":"AOMI symptomatique versus asymptomatique : antiagrégant ?","back":"Symptomatique : **pour tous** ; asymptomatique (IPS < 0,90) : **débattu**, sauf atteinte d'un autre territoire.","prio":"P2","sec":"s12"},{"id":"fc-221-5bbd33","poly":"cardio","fiche":"221","front":"Vasoactifs (pentoxifylline) dans l'AOMI : intérêt ?","back":"Gain **modeste** du périmètre de marche, **sans bénéfice pronostique**.","prio":"P3","sec":"s12"},{"id":"fc-221-94a203","poly":"cardio","fiche":"221","front":"Après angioplastie des MI : durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s12"},{"id":"fc-221-787636","poly":"cardio","fiche":"221","front":"Après revascularisation des MI : surveillance ?","back":"**Clinique + échodoppler** (thrombose de stent ou de pontage, dégradation des anastomoses).","prio":"P3","sec":"s12"},{"id":"fc-221-2fb4a9","poly":"cardio","fiche":"221","front":"AAA : population à dépister par échographie ?","back":"**Homme > 65 ans**, ou plus jeune avec FDR (tabac, maladie athéromateuse, ATCD familiaux d'anévrisme).","prio":"P1","sec":"s13"},{"id":"fc-221-060b59","poly":"cardio","fiche":"221","front":"AAA : 2 techniques de traitement ?","back":"**Chirurgie ouverte** (mise à plat-greffe) ou **endoprothèse** par voie fémorale.","prio":"P2","sec":"s13"},{"id":"fc-221-905d9d","poly":"cardio","fiche":"221","front":"Endoprothèse aortique : indications ?","back":"Anatomie favorable ; sujets à **haut risque chirurgical** (possible à bas risque après information).","prio":"P3","sec":"s13"},{"id":"fc-221-7b871f","poly":"cardio","fiche":"221","front":"AAA sous le seuil opératoire, de diamètre > 45 mm : rythme de surveillance échographique ?","back":"**Tous les 6 mois**.","prio":"P3","sec":"s13"},{"id":"fc-221-0c7d3e","poly":"cardio","fiche":"221","front":"AAA : effet de la poursuite du tabac ?","back":"L'anévrisme grossit **3 fois plus vite**.","prio":"P3","sec":"s13"},{"id":"fc-221-9a530e","poly":"cardio","fiche":"221","front":"Après traitement d'un AAA : surveillance selon la technique ?","back":"Prothèse : **échodoppler** (faux anévrismes anastomotiques) ; endoprothèse : **scanner ou écho** (endofuites).","prio":"P3","sec":"s13"},{"id":"fc-221-35930d","poly":"cardio","fiche":"221","front":"Porteur d'AAA : risque de décès CV par une autre atteinte versus rupture ?","back":"**10 fois plus** de risque de mourir d'une autre atteinte CV (coronaire, AVC).","prio":"P2","sec":"s13"},{"id":"fc-221-641604","poly":"cardio","fiche":"221","front":"Sténose carotidienne asymptomatique serrée, espérance de vie ≤ 5 ans : geste ?","back":"**Pas d'endartériectomie**.","prio":"P1","sec":"s13"},{"id":"fc-221-44bade","poly":"cardio","fiche":"221","front":"Lésions carotidiennes menaçantes : alternative à l'endartériectomie ?","back":"**Angioplastie carotidienne**.","prio":"P3","sec":"s13"},{"id":"fc-221-9d0b37","poly":"cardio","fiche":"221","front":"Porteur de prothèse artérielle : antibioprophylaxie ?","back":"Peut se justifier lors de **tout acte à risque bactérien**.","prio":"P3","sec":"s13"},{"id":"fc-221-b730b6","poly":"cardio","fiche":"221","front":"Après SCA : durée habituelle de la bithérapie P2Y12 + aspirine ?","back":"**12 mois**.","prio":"P1","sec":"s14"},{"id":"fc-221-e78982","poly":"cardio","fiche":"221","front":"Angor stable après stent actif : bithérapie antiplaquettaire ?","back":"**Clopidogrel + aspirine 6 mois**.","prio":"P2","sec":"s14"},{"id":"fc-221-2b4794","poly":"cardio","fiche":"221","front":"Angor stable après angioplastie : prasugrel ou ticagrélor ?","back":"**Non indiqués** : **clopidogrel**.","prio":"P2","sec":"s14"},{"id":"fc-221-754960","poly":"cardio","fiche":"221","front":"Après SCA : statine, dose et objectifs ?","back":"**Forte dose** d'emblée (atorvastatine 80 ou rosuvastatine 20 mg) ; baisse **≥ 50 %** et LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s14"},{"id":"fc-221-cb44ab","poly":"cardio","fiche":"221","front":"Après SCA : quand ajouter l'ézétimibe ?","back":"Objectif non atteint après **4 semaines** à dose maximale tolérée : **ézétimibe 10 mg**.","prio":"P2","sec":"s14"},{"id":"fc-221-614fd3","poly":"cardio","fiche":"221","front":"Anti-PCSK9 après SCA : condition de remboursement ?","back":"LDL-C restant **> 0,7 g/L**.","prio":"P3","sec":"s14"},{"id":"fc-221-e25b19","poly":"cardio","fiche":"221","front":"Après SCA : les IEC/ARA2 sont-ils systématiques ?","back":"**Non** : surtout si **FEVG ≤ 40 %**, **diabète**, **IRC**.","prio":"P2","sec":"s14"},{"id":"fc-221-008713","poly":"cardio","fiche":"221","front":"Après infarctus : quand le bêtabloquant est-il formellement indiqué ?","back":"**FEVG ≤ 40 %**.","prio":"P2","sec":"s14"},{"id":"fc-221-a40207","poly":"cardio","fiche":"221","front":"Bêtabloquant : contre-indications ?","back":"**Asthme**, **BPCO très sévère**, **Raynaud**, **bradycardie < 50/min**, **BAV 2e-3e degré**.","prio":"P1","sec":"s14"},{"id":"fc-221-8da5d0","poly":"cardio","fiche":"221","front":"Trinitrine sublinguale : effets indésirables et précaution de prise ?","back":"**Céphalées**, **chute de PA** → **s'asseoir ou s'allonger**.","prio":"P2","sec":"s14"},{"id":"fc-221-761db2","poly":"cardio","fiche":"221","front":"Inhibiteurs calciques bradycardisants : quand les utiliser et association interdite ?","back":"Si BB CI ou mal tolérés ; **ne pas associer aux BB** (trouble de conduction).","prio":"P2","sec":"s14"},{"id":"fc-221-191db7","poly":"cardio","fiche":"221","front":"Dérivés nitrés : association contre-indiquée ?","back":"**IPDE5** (sildénafil).","prio":"P1","sec":"s14"},{"id":"fc-221-981cee","poly":"cardio","fiche":"221","front":"Ivabradine : conditions d'utilisation ?","back":"BB CI ou mal tolérés, **rythme sinusal**, **FC ≥ 70 bpm** ; inefficace en **FA**.","prio":"P3","sec":"s14"},{"id":"fc-221-1a9b96","poly":"cardio","fiche":"221","front":"Antiangineux : effets indésirables caractéristiques ?","back":"Dihydropyridines : **œdèmes des MI** ; nitrés : céphalées ; nicorandil : **ulcérations** ; ivabradine : **phosphènes**.","prio":"P3","sec":"s14"},{"id":"fc-221-ecbace","poly":"cardio","fiche":"221","front":"Après SCA : indications d'un IPP associé à l'aspirine ?","back":"Risque hémorragique digestif : **âge ≥ 65 ans**, **ATCD d'ulcère**, **corticothérapie** prolongée.","prio":"P3","sec":"s14"},{"id":"fc-221-f60521","poly":"cardio","fiche":"221","front":"Après SCA : indication de l'antiminéralocorticoïde ?","back":"**FEVG ≤ 40 %** avec **IC congestive** ou **diabète**, après BB et IEC.","prio":"P3","sec":"s14"},{"id":"fc-221-8fb060","poly":"cardio","fiche":"221","front":"Antiminéralocorticoïde : contre-indications ?","back":"**Insuffisance rénale** (créatinine > 221 µmol/L), **hyperkaliémie**.","prio":"P3","sec":"s14"},{"id":"fc-221-ea39ae","poly":"cardio","fiche":"221","front":"Après SCA : réadaptation cardiovasculaire ?","back":"**Recommandée et proposée à tous** (hospitalisation ou ambulatoire), avec éducation thérapeutique.","prio":"P1","sec":"s14"},{"id":"fc-221-1f5b2e","poly":"cardio","fiche":"221","front":"Angor stable : revascularisation systématique versus traitement médical optimal ?","back":"La revascularisation systématique **ne fait pas mieux**.","prio":"P2","sec":"s14"},{"id":"fc-221-b6c84b","poly":"cardio","fiche":"221","front":"Angor stable : place des dihydropyridines ?","back":"**1re intention** si CI aux BB ou FC < 60 bpm ; **2e intention** avec les BB si angor résiduel.","prio":"P3","sec":"s14"},{"id":"fc-221-5bb50c","poly":"cardio","fiche":"221","front":"Rupture de plaque en urgence : traitement antithrombotique ?","back":"**Antiplaquettaires** (aspirine, clopidogrel) + **héparine**.","prio":"P1","sec":"s15"},{"id":"fc-221-1c48bf","poly":"cardio","fiche":"221","front":"SCA : dose initiale puis d'entretien de l'aspirine ?","back":"**250 mg IVD**, puis **75-100 mg/j** per os.","prio":"P1","sec":"s15"},{"id":"fc-221-ce6b35","poly":"cardio","fiche":"221","front":"SCA : posologie du clopidogrel ?","back":"Charge **600 mg** per os puis **75 mg/j** ; avec fibrinolyse : **300 mg** seulement si âge < 75 ans.","prio":"P2","sec":"s15"},{"id":"fc-221-c9c15d","poly":"cardio","fiche":"221","front":"SCA : posologie du prasugrel et du ticagrélor ?","back":"Prasugrel **60 mg** puis **10 mg/j** ; ticagrélor **180 mg** puis **90 mg × 2/j**.","prio":"P2","sec":"s15"},{"id":"fc-221-7353a2","poly":"cardio","fiche":"221","front":"Prasugrel : contre-indication et situations où il est non recommandé ?","back":"**ATCD d'AVC** ; non recommandé après **75 ans** et/ou si poids **< 60 kg**.","prio":"P2","sec":"s15"},{"id":"fc-221-57d77a","poly":"cardio","fiche":"221","front":"Ticagrélor : effets indésirables réversibles ?","back":"**Bradycardie** et **dyspnée**.","prio":"P3","sec":"s15"},{"id":"fc-221-a841d0","poly":"cardio","fiche":"221","front":"SCA avec angioplastie immédiate : anticoagulation ?","back":"HNF **70-100 UI/kg IVD** ou énoxaparine **0,5 mg/kg IVD**.","prio":"P2","sec":"s15"},{"id":"fc-221-2025fd","poly":"cardio","fiche":"221","front":"SCA ST- à haut risque : anticoagulation ?","back":"Énoxaparine **1 mg/kg SC × 2/j** ou fondaparinux **2,5 mg/j SC**.","prio":"P3","sec":"s15"},{"id":"fc-221-b9b9aa","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : héparinothérapie ?","back":"HNF bolus **5 000 UI** puis **500 UI/kg/j** IV, **TCA entre 2 et 3**, dès le diagnostic.","prio":"P2","sec":"s15"},{"id":"fc-221-4f8214","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : mesures associées ?","back":"Antalgiques de **niveau 3**, **oxygène** nasal, remplissage si besoin, **soins locaux** immédiats.","prio":"P3","sec":"s15"},{"id":"fc-221-2eb5d2","poly":"cardio","fiche":"221","front":"Ischémie aiguë de membre : traitement au long cours selon l'origine ?","back":"Thrombotique : **antiagrégant** + FDR ; embolique : traitement **étiologique** (anticoagulation si FA).","prio":"P3","sec":"s15"},{"id":"fc-221-7c65a7","poly":"cardio","fiche":"221","front":"SCA ST- : bithérapie antiagrégante dès l'admission ?","back":"**Non** tant que la coronarographie n'est pas faite (sauf délai **> 24 h**).","prio":"P2","sec":"s15"},{"id":"fc-221-280d27","poly":"cardio","fiche":"221","front":"SCA : choix de l'inhibiteur P2Y12 ?","back":"**Prasugrel ou ticagrélor** en 1re intention si angioplastie primaire ; **clopidogrel** si CI, risque hémorragique ou **fibrinolyse**.","prio":"P2","sec":"s15"},{"id":"fc-221-ab6234","poly":"cardio","fiche":"221","front":"Polyathéromateux : rythme du bilan clinique de suivi ?","back":"**Annuel**, examen de **tous les territoires** artériels.","prio":"P1","sec":"s16"},{"id":"fc-221-6a548d","poly":"cardio","fiche":"221","front":"Polyathéromateux au long cours : réévaluations régulières ?","back":"**FDR**, **risque CV global**, bilan d'extension annuel ; atteinte des **objectifs de prévention secondaire**.","prio":"P2","sec":"s16"},{"id":"fc-221-a864e0","poly":"cardio","fiche":"221","front":"Polyathéromateux : 4 apprentissages de l'éducation thérapeutique ?","back":"**Activité physique** et hygiène · **observance/tolérance** · **objectifs** de prévention · **signes d'alerte** (douleur thoracique, déficit).","prio":"P2","sec":"s16"},{"id":"fc-222-2191e4","poly":"cardio","fiche":"222","front":"Facteur de risque cardiovasculaire : définition ?","back":"Donnée clinique ou biologique qui augmente le risque de maladie **et** en est une **cause** : le réduire diminue la maladie.","prio":"P1","sec":"s1"},{"id":"fc-222-9d3ff9","poly":"cardio","fiche":"222","front":"Marqueur de risque : définition ?","back":"Simple **témoin** qui évolue avec la maladie ; le faire baisser **ne change pas** son évolution.","prio":"P1","sec":"s1"},{"id":"fc-222-8211fb","poly":"cardio","fiche":"222","front":"Lien causal d'un facteur de risque : 5 conditions ?","back":"**Précède** la maladie · relation **dose-effet** · caractère **universel** · **plausible** · liaison **forte et indépendante**.","prio":"P1","sec":"s1"},{"id":"fc-222-b59568","poly":"cardio","fiche":"222","front":"Prévention CV : principe général ?","back":"Supprimer ou abaisser autant que possible **l'ensemble** des facteurs de risque.","prio":"P2","sec":"s1"},{"id":"fc-222-84baeb","poly":"cardio","fiche":"222","front":"Prévention primaire : définition et objectif ?","back":"Sujet **sans aucun accident vasculaire** ; réduire l'incidence en dépistant et contrôlant les FDR.","prio":"P1","sec":"s1"},{"id":"fc-222-cda528","poly":"cardio","fiche":"222","front":"Prévention secondaire : définition ?","back":"Après un **accident vasculaire** **ou** devant des **lésions vasculaires documentées**.","prio":"P1","sec":"s1"},{"id":"fc-222-81ed4c","poly":"cardio","fiche":"222","front":"Prévention secondaire : objectifs ?","back":"Réduire le risque de **récidive** et **freiner la progression** des lésions.","prio":"P2","sec":"s1"},{"id":"fc-222-25b5f6","poly":"cardio","fiche":"222","front":"Prévention primosecondaire : population visée ?","back":"Patients sans pathologie CV cliniquement décelable mais avec des **lésions athéromateuses infracliniques**.","prio":"P1","sec":"s1"},{"id":"fc-222-0a8a62","poly":"cardio","fiche":"222","front":"Prévention individuelle : de quoi dépend son effet ?","back":"D'autant plus grand que le **risque CV global** (tous les FDR) est **élevé**.","prio":"P1","sec":"s1"},{"id":"fc-222-f34859","poly":"cardio","fiche":"222","front":"Prévention collective : caractéristiques ?","back":"Mesures simples à **effet individuel modéré**, mais fort impact car touchant un **très grand nombre**.","prio":"P2","sec":"s1"},{"id":"fc-222-9508e8","poly":"cardio","fiche":"222","front":"Recommandations HAS de prévention CV : 4 grands facteurs de risque ciblés ?","back":"**Dyslipidémies**, **HTA**, **diabète**, **tabagisme**.","prio":"P2","sec":"s1"},{"id":"fc-222-91d711","poly":"cardio","fiche":"222","front":"Facteurs de risque CV non modifiables ?","back":"**Âge**, **sexe masculin**, **hérédité**.","prio":"P1","sec":"s2"},{"id":"fc-222-2e4119","poly":"cardio","fiche":"222","front":"Décès cardiovasculaires : répartition par sexe en nombre absolu ?","back":"Plus nombreux chez la **femme (54 %)**.","prio":"P2","sec":"s2"},{"id":"fc-222-def54b","poly":"cardio","fiche":"222","front":"Mortalité CV avant 65 ans : homme versus femme ?","back":"**3 à 4 fois** plus élevée chez l'homme ; accidents **10 ans plus tôt** en moyenne.","prio":"P2","sec":"s2"},{"id":"fc-222-d474f3","poly":"cardio","fiche":"222","front":"Hérédité cardiovasculaire : définition ?","back":"Événement **précoce** chez un parent ou dans la fratrie : **< 55 ans** (homme), **< 65 ans** (femme).","prio":"P1","sec":"s2"},{"id":"fc-222-58d59a","poly":"cardio","fiche":"222","front":"Hérédité CV : 2 mécanismes possibles ?","back":"Transmission **génétique** d'un FDR modifiable, ou souvent **environnement familial** défavorable (tabac, alimentation, sédentarité).","prio":"P2","sec":"s2"},{"id":"fc-222-c9a589","poly":"cardio","fiche":"222","front":"Étude Interheart : nombre de facteurs modifiables d'IDM retenus ?","back":"**9 facteurs**, à tout âge et dans les deux sexes.","prio":"P1","sec":"s2"},{"id":"fc-222-d98236","poly":"cardio","fiche":"222","front":"Interheart : 6 facteurs de risque délétères ?","back":"**Tabac**, **hypercholestérolémie**, **HTA**, **diabète**, **obésité abdominale**, **facteurs psychosociaux**.","prio":"P1","sec":"s2"},{"id":"fc-222-ba3c2c","poly":"cardio","fiche":"222","front":"Interheart : facteurs protecteurs (rang A) ?","back":"**Fruits et légumes** et **activité physique**.","prio":"P1","sec":"s2"},{"id":"fc-222-59f12f","poly":"cardio","fiche":"222","front":"Interheart : part des IDM expliqués par les 9 facteurs ?","back":"**90 %**.","prio":"P3","sec":"s2"},{"id":"fc-222-f463c2","poly":"cardio","fiche":"222","front":"Consommation légère d'alcool et risque CV ?","back":"Associée à une **absence de risque**, voire une possible **baisse** du risque CV.","prio":"P3","sec":"s2"},{"id":"fc-222-d88209","poly":"cardio","fiche":"222","front":"Tabac : rang parmi les causes de mortalité ?","back":"**1re cause de mortalité évitable**.","prio":"P1","sec":"s3"},{"id":"fc-222-756099","poly":"cardio","fiche":"222","front":"Tabac : décès annuels dans le monde ?","back":"Environ **5 millions** ; 1 décès sur 5 chez l'homme, 1 sur 20 chez la femme.","prio":"P3","sec":"s3"},{"id":"fc-222-3cb197","poly":"cardio","fiche":"222","front":"Tabac en France : décès annuels et part cardiovasculaire ?","back":"**73 000 décès/an** (dont ~2 000 par tabagisme passif) ; **un quart** cardiovasculaires.","prio":"P1","sec":"s3"},{"id":"fc-222-ffd340","poly":"cardio","fiche":"222","front":"Tabac : 4 mécanismes de toxicité cardiovasculaire ?","back":"**Baisse du HDL-C** · sang **thrombogène** · altération de la **vasomotricité** (spasmes) · **CO** gênant le transport d'O₂.","prio":"P2","sec":"s3"},{"id":"fc-222-ce5ef3","poly":"cardio","fiche":"222","front":"Nicotine : rôle dans les complications CV du tabac ?","back":"**Aucun rôle propre** ; elle crée surtout la **dépendance**.","prio":"P1","sec":"s3"},{"id":"fc-222-fb4895","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : effets sur FC et PA ?","back":"Les petits effets de la cigarette sur FC et PAS **disparaissent totalement** sous substituts.","prio":"P2","sec":"s3"},{"id":"fc-222-53fc85","poly":"cardio","fiche":"222","front":"Interheart : rang du tabac parmi les facteurs de risque d'IDM ?","back":"**2e**, juste derrière les **dyslipidémies**.","prio":"P2","sec":"s3"},{"id":"fc-222-e03eed","poly":"cardio","fiche":"222","front":"Tabac : existe-t-il un seuil de consommation sans danger ?","back":"**Non** : risque proportionnel à la consommation, **sans seuil**.","prio":"P1","sec":"s3"},{"id":"fc-222-b23073","poly":"cardio","fiche":"222","front":"Tabac : le risque varie-t-il selon le mode de consommation ?","back":"**Non** : identique (cigarette avec/sans filtre, pipe, cigare, narguilé, tabac à mâcher).","prio":"P1","sec":"s3"},{"id":"fc-222-fccbaa","poly":"cardio","fiche":"222","front":"Accident coronarien aigu du sujet jeune : facteur de risque essentiel ?","back":"Le **tabac**, souvent **isolé**.","prio":"P1","sec":"s3"},{"id":"fc-222-b59abc","poly":"cardio","fiche":"222","front":"Tabagisme passif : augmentation du risque d'IDM ?","back":"**+24 %** pour 1-7 h/semaine ; **+62 %** au-delà de 22 h/semaine.","prio":"P3","sec":"s3"},{"id":"fc-222-51d2c1","poly":"cardio","fiche":"222","front":"AOMI : proportion de fumeurs ?","back":"**90 %**.","prio":"P1","sec":"s3"},{"id":"fc-222-e056d2","poly":"cardio","fiche":"222","front":"Tabac : atteintes CV hors coronaires ?","back":"**AOMI**, **anévrisme de l'aorte abdominale**, **AVC** (corrélé à la consommation).","prio":"P2","sec":"s3"},{"id":"fc-222-2ce433","poly":"cardio","fiche":"222","front":"Maladie coronarienne : facteur de risque le plus important ?","back":"L'**hypercholestérolémie**.","prio":"P1","sec":"s4"},{"id":"fc-222-a44fc1","poly":"cardio","fiche":"222","front":"Cholestérolémie totale et risque coronarien : type de relation ?","back":"Corrélation **positive** et **exponentielle**.","prio":"P3","sec":"s4"},{"id":"fc-222-042d30","poly":"cardio","fiche":"222","front":"Cholestérol : fraction déterminante au niveau individuel ?","back":"Le **LDL-C élevé**.","prio":"P1","sec":"s4"},{"id":"fc-222-1aeb2b","poly":"cardio","fiche":"222","front":"HDL-C : rôle dans le risque CV ?","back":"HDL-C **bas** = FDR **indépendant** ; élevé = protecteur, **mais pas au-delà de 1 g/L**.","prio":"P2","sec":"s4"},{"id":"fc-222-0919d2","poly":"cardio","fiche":"222","front":"Bilan lipidique de référence : composition ?","back":"**EAL à jeun** : cholestérol total, **HDL-C**, **triglycérides** ; LDL-C calculé.","prio":"P1","sec":"s4"},{"id":"fc-222-de3585","poly":"cardio","fiche":"222","front":"Formule de Friedewald ?","back":"**LDL-C = CT − HDL-C − TG/5** (en g/L).","prio":"P1","sec":"s4"},{"id":"fc-222-1c9b4a","poly":"cardio","fiche":"222","front":"Formule de Friedewald : condition de validité ?","back":"**TG < 3,5 g/L**.","prio":"P1","sec":"s4"},{"id":"fc-222-fefec5","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : mutations en cause ?","back":"Surtout le **récepteur au LDL**, plus rarement **apoB** ou **PCSK9**.","prio":"P3","sec":"s4"},{"id":"fc-222-ef7809","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote : fréquence et LDL-C ?","back":"**1/500** ; LDL-C **2 à 4 g/L**.","prio":"P1","sec":"s4"},{"id":"fc-222-e923a4","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote : signes cliniques ?","back":"Parfois **xanthomes tendineux** (calcanéen, extenseurs), **arc cornéen**, **xanthélasma**.","prio":"P2","sec":"s4"},{"id":"fc-222-cdf020","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale hétérozygote non traitée : âge des complications coronariennes ?","back":"Dès la **quarantaine**, voire avant si autres FDR.","prio":"P2","sec":"s4"},{"id":"fc-222-35dac2","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale homozygote : fréquence, LDL-C, complications ?","back":"**1/1 000 000** ; LDL-C **> 5 g/L** ; complications coronariennes possibles **avant 20 ans**.","prio":"P2","sec":"s4"},{"id":"fc-222-7b6eed","poly":"cardio","fiche":"222","front":"Hypercholestérolémies : forme la plus fréquente ?","back":"**Polygénique** (terrain génétique + alimentation riche en graisses saturées).","prio":"P2","sec":"s4"},{"id":"fc-222-d1d1cf","poly":"cardio","fiche":"222","front":"HTA : prévalence chez l'adulte en France ?","back":"**20 à 30 %** ; < 5 % avant 35 ans, **> 60 %** après 65 ans.","prio":"P3","sec":"s5"},{"id":"fc-222-e997ca","poly":"cardio","fiche":"222","front":"HTA : seuil en consultation ?","back":"PA **≥ 140/90 mmHg**, persistante.","prio":"P1","sec":"s5"},{"id":"fc-222-9e462a","poly":"cardio","fiche":"222","front":"HTA : seuil en automesure ?","back":"**≥ 135/85 mmHg**.","prio":"P1","sec":"s5"},{"id":"fc-222-8b237c","poly":"cardio","fiche":"222","front":"HTA : seuil en MAPA des 24 h ?","back":"**≥ 130/80 mmHg**.","prio":"P1","sec":"s5"},{"id":"fc-222-4c53f4","poly":"cardio","fiche":"222","front":"« PA élevée » (ESC 2024) : définition et conduite ?","back":"PA **> 120/70** sans critère d'HTA ; évaluer le **risque CV global** (SCORE2) et discuter un antihypertenseur.","prio":"P3","sec":"s5"},{"id":"fc-222-c7baae","poly":"cardio","fiche":"222","front":"HTA stade 1 : chiffres ?","back":"PAS **140-159** · PAD **90-99 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-c904e6","poly":"cardio","fiche":"222","front":"HTA stade 2 : chiffres ?","back":"PAS **160-179** · PAD **100-109 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-33d75d","poly":"cardio","fiche":"222","front":"HTA stade 3 : chiffres ?","back":"PAS **≥ 180** · PAD **≥ 110 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-587474","poly":"cardio","fiche":"222","front":"HTA systolique isolée : définition ?","back":"PAS **≥ 140** et PAD **< 90 mmHg**.","prio":"P2","sec":"s5"},{"id":"fc-222-9144c1","poly":"cardio","fiche":"222","front":"HTA : 3 organes cibles ?","back":"**Cœur** (coronaires, IC), **cerveau** (AVC), **reins** (insuffisance rénale).","prio":"P1","sec":"s5"},{"id":"fc-222-f019de","poly":"cardio","fiche":"222","front":"HTA secondaire : proportion et causes ?","back":"**10 %** : maladie **rénale**, cause **hormonale** (surrénalienne), **médicaments** ou toxiques.","prio":"P1","sec":"s5"},{"id":"fc-222-7edfea","poly":"cardio","fiche":"222","front":"HTA essentielle : facteurs environnementaux ?","back":"**Surpoids**, **sédentarité**, excès d'**alcool** et de **sel**.","prio":"P2","sec":"s5"},{"id":"fc-222-029dce","poly":"cardio","fiche":"222","front":"Mesure de la PA au cabinet : méthode recommandée ?","back":"**Appareil semi-automatique**, mesures répétées sur **plus d'une visite** ; stéthoscope seulement si **FA**.","prio":"P2","sec":"s5"},{"id":"fc-222-c888b0","poly":"cardio","fiche":"222","front":"HTA : comment confirmer le diagnostic ?","back":"Mesure **hors du cabinet** : **automesure** ou **MAPA** ; jamais sur une seule mesure.","prio":"P1","sec":"s5"},{"id":"fc-222-6c6af1","poly":"cardio","fiche":"222","front":"MAPA : indications ?","back":"Effet **blouse blanche**, **HTA masquée**, HTA **résistante**, absence de baisse nocturne, hypotension (diabétique, sujet âgé).","prio":"P2","sec":"s5"},{"id":"fc-222-077c31","poly":"cardio","fiche":"222","front":"HTA masquée : définition ?","back":"**Absente au cabinet** mais **confirmée en MAPA**.","prio":"P2","sec":"s5"},{"id":"fc-222-a7b842","poly":"cardio","fiche":"222","front":"Automesure tensionnelle : 2 usages ?","back":"**Confirmer** le diagnostic d'HTA hors du cabinet et **vérifier l'efficacité du traitement**.","prio":"P2","sec":"s5"},{"id":"fc-222-2ece22","poly":"cardio","fiche":"222","front":"Diabète : critères diagnostiques ?","back":"Glycémie à jeun **> 1,26 g/L (7 mmol/L) à 2 reprises**, ou **> 2 g/L (11,1 mmol/L)** à tout moment.","prio":"P1","sec":"s6"},{"id":"fc-222-0ff00d","poly":"cardio","fiche":"222","front":"Hyperglycémie à jeun non diabétique : définition ?","back":"Glycémie à jeun **entre 1,00 et 1,26 g/L**.","prio":"P1","sec":"s6"},{"id":"fc-222-334be0","poly":"cardio","fiche":"222","front":"Diabète en France : prévalence et répartition des types ?","back":"**≈ 3 millions** (5 %) ; type 1 ≈ 5 %, **type 2 ≈ 95 %**.","prio":"P3","sec":"s6"},{"id":"fc-222-19264b","poly":"cardio","fiche":"222","front":"Diabète de type 2 : circonstances de découverte habituelles ?","back":"**Dépistage systématique** : > 50 ans, sédentaire, surpoids, asymptomatique, souvent hérédité de diabète.","prio":"P2","sec":"s6"},{"id":"fc-222-7771d1","poly":"cardio","fiche":"222","front":"Quel type de diabète domine le risque cardiovasculaire ?","back":"Le **DT2** (prévalence élevée et croissante).","prio":"P2","sec":"s6"},{"id":"fc-222-d44ce3","poly":"cardio","fiche":"222","front":"Diabète : complications microvasculaires ?","back":"**Rétinopathie**, **néphropathie**, **neuropathie**.","prio":"P1","sec":"s6"},{"id":"fc-222-faad75","poly":"cardio","fiche":"222","front":"Diabète : complications macrovasculaires ?","back":"**Maladie coronarienne**, **AVC**, **AOMI**.","prio":"P1","sec":"s6"},{"id":"fc-222-3e307c","poly":"cardio","fiche":"222","front":"Diabète : facteur multiplicatif du risque cardiovasculaire ?","back":"**× 2 à 3** (types 1 et 2).","prio":"P3","sec":"s6"},{"id":"fc-222-4e0da5","poly":"cardio","fiche":"222","front":"Maladie cardiovasculaire chez un patient : quel trouble métabolique rechercher ?","back":"Un **diabète** (souvent non diagnostiqué).","prio":"P2","sec":"s6"},{"id":"fc-222-97d6a4","poly":"cardio","fiche":"222","front":"Diabète de type 1 : caractéristiques ?","back":"**Insulinodépendant d'emblée**, début le plus souvent **avant 20 ans** ; ≈ 5 % des diabètes.","prio":"P3","sec":"s6"},{"id":"fc-222-7d7ffb","poly":"cardio","fiche":"222","front":"IMC : formule et seuil d'obésité ?","back":"**Poids/taille²** (kg/m²) ; obésité si **≥ 30**.","prio":"P1","sec":"s7"},{"id":"fc-222-ebf02d","poly":"cardio","fiche":"222","front":"IMC : seuils de maigreur, normal et surpoids ?","back":"Maigreur **< 18,5** ; normal **18,5-25** ; surpoids **25-29,9**.","prio":"P2","sec":"s7"},{"id":"fc-222-95948a","poly":"cardio","fiche":"222","front":"Surpoids et obésité en France : chiffres ?","back":"**≈ 20 millions** en surpoids dont **6 millions** d'obèses.","prio":"P3","sec":"s7"},{"id":"fc-222-546848","poly":"cardio","fiche":"222","front":"Quel indicateur anthropométrique est le mieux corrélé au risque CV ?","back":"Le **périmètre ombilical** (graisse viscérale), mieux que l'IMC.","prio":"P1","sec":"s7"},{"id":"fc-222-4e69fd","poly":"cardio","fiche":"222","front":"Syndrome métabolique (FID 2005) : critère obligatoire ?","back":"**Obésité centrale** : périmètre **≥ 94 cm** (homme), **≥ 80 cm** (femme).","prio":"P1","sec":"s7"},{"id":"fc-222-038e75","poly":"cardio","fiche":"222","front":"Syndrome métabolique : critères associés (au moins 2) ?","back":"**TG > 1,50 g/L** · **HDL-C < 0,40** (H) / **< 0,50 g/L** (F) · **PA ≥ 130/85** · **glycémie > 1 g/L** ou DT2.","prio":"P1","sec":"s7"},{"id":"fc-222-b2cddb","poly":"cardio","fiche":"222","front":"Cumul de plusieurs facteurs de risque : effet sur le risque ?","back":"Les risques se **multiplient** (ne s'additionnent pas).","prio":"P2","sec":"s7"},{"id":"fc-222-e268dc","poly":"cardio","fiche":"222","front":"Facteurs psychosociaux de risque CV : exemples ?","back":"**Dépression**, troubles psychiques, catégorie sociale **défavorisée**, **isolement social**.","prio":"P2","sec":"s7"},{"id":"fc-222-38845a","poly":"cardio","fiche":"222","front":"Facteurs psychosociaux : pourquoi absents des équations de risque ?","back":"Faute d'**évaluation simple et rigoureuse**.","prio":"P2","sec":"s7"},{"id":"fc-222-05688f","poly":"cardio","fiche":"222","front":"Alcool en excès : effet tensionnel ?","back":"**Favorise l'HTA** ; sa réduction fait partie des mesures hygiénodiététiques.","prio":"P2","sec":"s7"},{"id":"fc-222-111ebc","poly":"cardio","fiche":"222","front":"Évaluer le risque CV global : intérêt ?","back":"Repérer les personnes qui **profiteront le plus** de la prévention.","prio":"P1","sec":"s8"},{"id":"fc-222-6995de","poly":"cardio","fiche":"222","front":"Risque CV global : définition ?","back":"Probabilité de développer une maladie CV dans un temps donné, compte tenu de **tous** les FDR.","prio":"P2","sec":"s8"},{"id":"fc-222-d3c66d","poly":"cardio","fiche":"222","front":"Prévention primaire : scores européens de risque CV ?","back":"**SCORE2**, **SCORE2-OP**, **SCORE2-Diabetes** (connaître leur existence, pas les calculer).","prio":"P2","sec":"s8"},{"id":"fc-222-1c9651","poly":"cardio","fiche":"222","front":"Ancien SCORE (ESC 2016) : ce qu'il estimait ?","back":"Seulement la **mortalité** CV à 10 ans, de 40 à 65 ans.","prio":"P3","sec":"s8"},{"id":"fc-222-429c58","poly":"cardio","fiche":"222","front":"SCORE2 : population et événements estimés ?","back":"**40-69 ans** apparemment sains ; événements **mortels et non mortels** (IDM, AVC) à **10 ans**.","prio":"P2","sec":"s8"},{"id":"fc-222-e8bb19","poly":"cardio","fiche":"222","front":"SCORE2 : paramètres utilisés ?","back":"Région, **sexe**, **âge**, **tabagisme** actif, **PAS**, **cholestérol total**, **HDL-C**.","prio":"P3","sec":"s8"},{"id":"fc-222-db5f0a","poly":"cardio","fiche":"222","front":"SCORE2-OP : population et particularité ?","back":"**≥ 70 ans** ; **ajusté aux risques concurrents** (sinon surestimation du risque et du bénéfice).","prio":"P3","sec":"s8"},{"id":"fc-222-e1344a","poly":"cardio","fiche":"222","front":"SCORE2-Diabetes : population et paramètres ajoutés ?","back":"**DT2 de 40-69 ans** sans maladie CV ; ajoute **âge au diagnostic**, **HbA1c**, **DFGe**.","prio":"P3","sec":"s8"},{"id":"fc-222-571ef6","poly":"cardio","fiche":"222","front":"SCORE2 : groupe de risque de la France ?","back":"Groupe **à faible risque**.","prio":"P3","sec":"s8"},{"id":"fc-222-2edfa5","poly":"cardio","fiche":"222","front":"SCORE2 et SCORE2-OP : situations où ils ne s'appliquent pas ?","back":"Maladie CV **documentée**, **diabète**, **hypercholestérolémie familiale**, **insuffisance rénale**, **grossesse** (d'emblée haut risque).","prio":"P2","sec":"s8"},{"id":"fc-222-07405d","poly":"cardio","fiche":"222","front":"SCORE2 < 50 ans : seuils de risque élevé et très élevé ?","back":"Élevé **2,5 à < 7,5 %** ; très élevé **≥ 7,5 %**.","prio":"P3","sec":"s9"},{"id":"fc-222-04f29a","poly":"cardio","fiche":"222","front":"SCORE2 entre 50 et 69 ans : seuils de risque élevé et très élevé ?","back":"Élevé **5 à < 10 %** ; très élevé **≥ 10 %**.","prio":"P2","sec":"s9"},{"id":"fc-222-bcbe86","poly":"cardio","fiche":"222","front":"SCORE2-OP ≥ 70 ans : seuils de risque élevé et très élevé ?","back":"Élevé **7,5 à < 15 %** ; très élevé **≥ 15 %**.","prio":"P3","sec":"s9"},{"id":"fc-222-da3476","poly":"cardio","fiche":"222","front":"Catégories SCORE2 : indication médicamenteuse selon le risque ?","back":"Faible à modéré : **généralement non** ; élevé : **le plus souvent** ; très élevé : **généralement**.","prio":"P2","sec":"s9"},{"id":"fc-222-b29c51","poly":"cardio","fiche":"222","front":"Seuils SCORE2 variables avec l'âge : pourquoi ?","back":"Éviter de **sous-traiter les jeunes** et de **surtraiter les âgés**.","prio":"P3","sec":"s9"},{"id":"fc-222-0780a0","poly":"cardio","fiche":"222","front":"Sujet sain ≥ 70 ans : hypolipémiant ?","back":"**Peut être envisagé** (classe IIb) ; décision **individuelle et partagée**.","prio":"P3","sec":"s9"},{"id":"fc-222-bab68a","poly":"cardio","fiche":"222","front":"Diabétique : seuil de risque très élevé à 10 ans ?","back":"**≥ 20 %**, ou maladie CV athéroscléreuse, ou lésion grave d'organe cible.","prio":"P2","sec":"s9"},{"id":"fc-222-c3f47f","poly":"cardio","fiche":"222","front":"Diabétique : lésions d'organe cible classant à très haut risque ?","back":"**Insuffisance rénale**, **protéinurie**, **microalbuminurie**, **rétinopathie**.","prio":"P3","sec":"s9"},{"id":"fc-222-c618aa","poly":"cardio","fiche":"222","front":"Insuffisant rénal chronique : niveau de risque CV ?","back":"**D'emblée haut ou très haut risque** ; SCORE2 **sous-estimerait** son risque.","prio":"P2","sec":"s9"},{"id":"fc-222-1e9dec","poly":"cardio","fiche":"222","front":"IRC : marqueurs dont l'aggravation majore le risque CV ?","back":"**Baisse du DFGe** et hausse de l'**albuminurie** (RAC).","prio":"P3","sec":"s9"},{"id":"fc-222-9ffe59","poly":"cardio","fiche":"222","front":"Scores de risque : 2 éléments associés au risque mais non intégrés ?","back":"**Antécédents familiaux** d'accident CV prématuré et **facteurs psychosociaux**.","prio":"P1","sec":"s10"},{"id":"fc-222-bafb3d","poly":"cardio","fiche":"222","front":"Imagerie des organes cibles pour stratifier le risque CV : en routine ?","back":"**Non** (épaisseur intima-média, **score calcique**, HVG échographique).","prio":"P1","sec":"s10"},{"id":"fc-222-6a2a88","poly":"cardio","fiche":"222","front":"Microalbuminurie : signification ?","back":"Marqueur **précoce de néphropathie** ; prédit le risque CV et rénal **indépendamment du DFGe**.","prio":"P2","sec":"s10"},{"id":"fc-222-4a1f97","poly":"cardio","fiche":"222","front":"Diabétique : dépistage de l'IRC ?","back":"**Au moins 1 fois/an** : **rapport albuminurie/créatininurie** (RAC) sur échantillon urinaire.","prio":"P1","sec":"s10"},{"id":"fc-222-a399a7","poly":"cardio","fiche":"222","front":"Biomarqueurs sans valeur ajoutée pour stratifier le risque CV ?","back":"**Facteurs de thrombose**, **CRP ultrasensible**, **homocystéine**.","prio":"P2","sec":"s10"},{"id":"fc-222-bad7af","poly":"cardio","fiche":"222","front":"Prévention primaire : données à recueillir en consultation ?","back":"**Tabac**, **PA**, **poids**, **taille**, **périmètre abdominal**, ATCD familiaux, **alimentation**, **activité physique**.","prio":"P1","sec":"s11"},{"id":"fc-222-f28029","poly":"cardio","fiche":"222","front":"Prévention primaire : biologie de référence ?","back":"**Glycémie** et **bilan lipidique complet à jeun**.","prio":"P1","sec":"s11"},{"id":"fc-222-a7399a","poly":"cardio","fiche":"222","front":"Prévention primaire : conduite selon le niveau de risque ?","back":"Favorable : **encourager** ; faible/modéré : **prévention collective** ; haut risque : prise en charge **médicalisée**.","prio":"P1","sec":"s11"},{"id":"fc-222-94111a","poly":"cardio","fiche":"222","front":"Prévention : conditions d'un changement de comportement durable ?","back":"**Dialogue** médecin-patient de qualité et **éducation thérapeutique** ; convaincre sans contraindre.","prio":"P2","sec":"s11"},{"id":"fc-222-258611","poly":"cardio","fiche":"222","front":"Prévention : quand acquérir les comportements protecteurs pour qu'ils durent ?","back":"**Dès l'enfance et l'adolescence**.","prio":"P3","sec":"s11"},{"id":"fc-222-f19fce","poly":"cardio","fiche":"222","front":"Prévention CV : à quelle occasion l'aborder ?","back":"À **chaque consultation**.","prio":"P2","sec":"s11"},{"id":"fc-222-a0e25c","poly":"cardio","fiche":"222","front":"LDL-C au-dessus de l'objectif, risque faible ou modéré : 1re intention ?","back":"**Modification du mode de vie seule**.","prio":"P1","sec":"s12"},{"id":"fc-222-c167d3","poly":"cardio","fiche":"222","front":"LDL-C au-dessus de l'objectif, risque élevé ou très élevé : 1re intention ?","back":"Mode de vie **associé d'emblée à un hypolipémiant**.","prio":"P1","sec":"s12"},{"id":"fc-222-e9619e","poly":"cardio","fiche":"222","front":"Prévention primaire lipidique : délai de réévaluation ?","back":"**3 mois** ; si objectif non atteint, instaurer/intensifier l'hypolipémiant.","prio":"P1","sec":"s12"},{"id":"fc-222-1226cd","poly":"cardio","fiche":"222","front":"Objectifs de LDL-C selon le risque ?","back":"Faible **< 1,15** ; modéré **< 1** ; élevé **< 0,70** ; très élevé/prévention secondaire **< 0,55 g/L**.","prio":"P1","sec":"s12"},{"id":"fc-222-31b919","poly":"cardio","fiche":"222","front":"Régime hypolipémiant : apport en graisses saturées et œufs ?","back":"Graisses saturées **< 10-12 %** des calories ; pas d'acides gras trans ; **≈ 3 œufs/semaine**.","prio":"P3","sec":"s12"},{"id":"fc-222-cd4a36","poly":"cardio","fiche":"222","front":"Hypolipémiant de 1er choix en prévention primaire ?","back":"Une **statine**, à dose faible/modérée augmentée progressivement.","prio":"P1","sec":"s12"},{"id":"fc-222-76864e","poly":"cardio","fiche":"222","front":"Objectif lipidique non atteint sous statine : stratégie ?","back":"Statine à dose **maximale tolérée** ou plus puissante, puis **+ ézétimibe** (en dernier colestyramine).","prio":"P2","sec":"s12"},{"id":"fc-222-f75b99","poly":"cardio","fiche":"222","front":"Intolérance aux statines : alternatives ?","back":"**Ézétimibe**, voire colestyramine, rarement fibrate.","prio":"P2","sec":"s12"},{"id":"fc-222-3f8be8","poly":"cardio","fiche":"222","front":"Statines : contre-indication citée ?","back":"**Grossesse**.","prio":"P2","sec":"s12"},{"id":"fc-222-414dfa","poly":"cardio","fiche":"222","front":"Sous hypolipémiant : quand contrôler le bilan lipidique ?","back":"**8 à 12 semaines** après le début, puis après chaque adaptation.","prio":"P2","sec":"s12"},{"id":"fc-222-3c2dea","poly":"cardio","fiche":"222","front":"Statine : surveillance des ALAT ?","back":"**Avant**, à **8-12 semaines**, puis **1 fois/an** ; arrêt ou baisse si **> 3 N**.","prio":"P2","sec":"s12"},{"id":"fc-222-b1ec18","poly":"cardio","fiche":"222","front":"Statine : quand doser les CPK et seuil d'arrêt ?","back":"Seulement si **myalgies** ou situation à risque ; arrêt si **CPK > 5 N**.","prio":"P2","sec":"s12"},{"id":"fc-222-c27dea","poly":"cardio","fiche":"222","front":"Prévention primaire lipidique : cible thérapeutique principale et pourquoi ?","back":"Le **LDL-C** : les preuves de bénéfice reposent sur sa baisse ; objectif fixé par la catégorie de risque.","prio":"P1","sec":"s12"},{"id":"fc-222-1d520c","poly":"cardio","fiche":"222","front":"Traitement antihypertenseur : 2 paramètres qui décident ?","back":"**Niveau de PA** et **risque CV global**.","prio":"P1","sec":"s13"},{"id":"fc-222-a83e53","poly":"cardio","fiche":"222","front":"Antihypertenseur : limite d'âge (ESC 2024) ?","back":"**Aucune**.","prio":"P3","sec":"s13"},{"id":"fc-222-178b30","poly":"cardio","fiche":"222","front":"HTA : 4 piliers de la prise en charge ?","back":"**Mesures hygiénodiététiques**, **FDR associés**, **médicaments**, **éducation thérapeutique**.","prio":"P3","sec":"s13"},{"id":"fc-222-f599b4","poly":"cardio","fiche":"222","front":"HTA confirmée : délai de traitement médicamenteux ?","back":"**Traitement immédiat chez tous**.","prio":"P1","sec":"s13"},{"id":"fc-222-81c706","poly":"cardio","fiche":"222","front":"PAS 130-139 avec risque CV élevé : conduite ?","back":"Médicament **après 3 mois** de mesures hygiénodiététiques si cible non atteinte.","prio":"P2","sec":"s13"},{"id":"fc-222-690d9b","poly":"cardio","fiche":"222","front":"PAS 130-139 sans risque élevé : conduite ?","back":"**Pas de médicament** ; surveillance, risque réévalué chaque année.","prio":"P2","sec":"s13"},{"id":"fc-222-80be44","poly":"cardio","fiche":"222","front":"HTA : mesures hygiénodiététiques chiffrées ?","back":"IMC **20-25**, tour de taille < 94/80 cm, alcool **< 10 unités/semaine**, sel **5-6 g/j**, + potassium, arrêt du tabac.","prio":"P2","sec":"s13"},{"id":"fc-222-c47638","poly":"cardio","fiche":"222","front":"Hypertendu : PA cible et délai ?","back":"PAS **120-129**, PAD **70-79 mmHg**, idéalement à **3 mois**.","prio":"P2","sec":"s13"},{"id":"fc-222-602692","poly":"cardio","fiche":"222","front":"HTA : traitement de 1re intention chez la majorité des patients ?","back":"**Bithérapie d'emblée** : IEC/ARA2 + **inhibiteur calcique** ou **diurétique thiazidique**, faible dose, association fixe.","prio":"P1","sec":"s13"},{"id":"fc-222-4f9221","poly":"cardio","fiche":"222","front":"HTA : association interdite ?","back":"**IEC + ARA2**.","prio":"P1","sec":"s13"},{"id":"fc-222-a90bfe","poly":"cardio","fiche":"222","front":"HTA : place du bêtabloquant ?","back":"Seulement s'il existe une **autre indication** ; **jamais en monothérapie**.","prio":"P1","sec":"s13"},{"id":"fc-222-81b3c5","poly":"cardio","fiche":"222","front":"HTA : indications de la monothérapie plutôt que la bithérapie ?","back":"PA élevée 120-139/70-89 avec indication, **fragilité**, **hypotension orthostatique**, âge **≥ 85 ans** ; PA élevée + risque élevé : si **≥ 130/80 après 3 mois** de MHD.","prio":"P2","sec":"s13"},{"id":"fc-222-f83537","poly":"cardio","fiche":"222","front":"Sevrage tabagique : objectif ?","back":"**Arrêt total et définitif**, le plus tôt possible.","prio":"P1","sec":"s14"},{"id":"fc-222-09ef21","poly":"cardio","fiche":"222","front":"Conseil minimum d'arrêt du tabac : principe et effet ?","back":"Aborder le tabac **à chaque consultation** ; peut **doubler le taux de sevrage à 1 an**.","prio":"P1","sec":"s14"},{"id":"fc-222-345a17","poly":"cardio","fiche":"222","front":"Fumeur : évaluations avant sevrage ?","back":"**Motivation**, dépendance physique (**test de Fagerström**), **autres dépendances**.","prio":"P1","sec":"s14"},{"id":"fc-222-1a29af","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : bénéfice ?","back":"Évitent le syndrome de sevrage et **doublent les chances d'arrêt**.","prio":"P1","sec":"s14"},{"id":"fc-222-d8a200","poly":"cardio","fiche":"222","front":"Substituts nicotiniques : schéma de prescription ?","back":"**Patch + forme orale** ; dose ajustée vite ; décroissance sur **au moins 3 mois**.","prio":"P1","sec":"s14"},{"id":"fc-222-35e51f","poly":"cardio","fiche":"222","front":"Fumer sous patch nicotinique : contre-indication ?","back":"**Non** (sevrage progressif possible).","prio":"P2","sec":"s14"},{"id":"fc-222-63085d","poly":"cardio","fiche":"222","front":"Femme enceinte fumeuse : substituts nicotiniques ?","back":"**Prescriptibles**, avec **accompagnement médical**.","prio":"P2","sec":"s14"},{"id":"fc-222-f0be07","poly":"cardio","fiche":"222","front":"Sevrage tabagique : médicaments autres que les substituts ?","back":"**Bupropion** ou **varénicline**.","prio":"P2","sec":"s14"},{"id":"fc-222-6d3abb","poly":"cardio","fiche":"222","front":"Cigarette électronique : place dans le sevrage ?","back":"**Pas un dispositif médical** ; avec nicotine, en **2e intention**, associée aux autres méthodes.","prio":"P2","sec":"s14"},{"id":"fc-222-3b140c","poly":"cardio","fiche":"222","front":"Sevrage tabagique : quand orienter en tabacologie ?","back":"**Dépendance sévère**, **rechutes** antérieures, **dépendances multiples**.","prio":"P2","sec":"s14"},{"id":"fc-222-4f1ca3","poly":"cardio","fiche":"222","front":"Sevrage tabagique : prise de poids moyenne ?","back":"**5 kg** ; bénéfice de l'arrêt bien supérieur.","prio":"P2","sec":"s14"},{"id":"fc-222-693370","poly":"cardio","fiche":"222","front":"Interdiction de fumer dans les lieux publics : effet ?","back":"Baisse **significative et rapide** de l'incidence des **IDM**.","prio":"P2","sec":"s14"},{"id":"fc-222-45d9bf","poly":"cardio","fiche":"222","front":"Sevrage tabagique : thérapies comportementales validées ?","back":"**TCC** (autocontrôle, gestion du stress, affirmation de soi), efficaces dans des études contrôlées.","prio":"P3","sec":"s14"},{"id":"fc-222-eccd6c","poly":"cardio","fiche":"222","front":"PNNS : 4 messages ?","back":"**5 fruits et légumes/j** · **poisson 2 fois/semaine** · limiter graisses saturées, sucres, sel · **activité physique**.","prio":"P1","sec":"s15"},{"id":"fc-222-15b7b5","poly":"cardio","fiche":"222","front":"Activité physique recommandée chez l'adulte ?","back":"**≥ 30 min, 5 j/semaine** : **150-300 min/sem** modérée ou **75-150 min** intense.","prio":"P2","sec":"s15"},{"id":"fc-222-ac0abd","poly":"cardio","fiche":"222","front":"Alimentation méditerranéenne : composition ?","back":"Fruits et légumes, **acides gras insaturés** (huile d'olive), produits de la mer ; **peu de viande rouge**.","prio":"P1","sec":"s15"},{"id":"fc-222-7e9244","poly":"cardio","fiche":"222","front":"Étude validant l'alimentation méditerranéenne ?","back":"**PREDIMED**.","prio":"P2","sec":"s15"},{"id":"fc-222-31b50e","poly":"cardio","fiche":"222","front":"Activité physique minimale réduisant déjà la mortalité CV ?","back":"**1 h 30/semaine** d'intensité modérée (3 à 5 séances).","prio":"P3","sec":"s15"},{"id":"fc-222-e1972a","poly":"cardio","fiche":"222","front":"Activité physique et comorbidités : volume à risque ?","back":"**> 5 h/semaine**.","prio":"P3","sec":"s15"},{"id":"fc-222-09a928","poly":"cardio","fiche":"222","front":"Avant une activité physique modérée ou plus : outil HAS ?","back":"Autoquestionnaire **Q-AAP+**.","prio":"P3","sec":"s15"},{"id":"fc-222-0679fc","poly":"cardio","fiche":"222","front":"Bilan médical minimal avant activité physique : indications ?","back":"**Q-AAP+ positif**, **> 45 ans**, sujet **inactif**, activité très intense, suspicion de maladie.","prio":"P3","sec":"s15"},{"id":"fc-222-8ad029","poly":"cardio","fiche":"222","front":"Épreuve d'effort avant activité > 6 MET chez l'asymptomatique : quand est-elle recommandée ?","back":"Si risque CV **élevé ou très élevé** (actif ou inactif).","prio":"P3","sec":"s15"},{"id":"fc-222-2bc22f","poly":"cardio","fiche":"222","front":"Prévention secondaire : 4 caractéristiques ?","back":"**Systématique**, **multirisque**, **intensive**, **médicalisée**.","prio":"P1","sec":"s16"},{"id":"fc-222-392405","poly":"cardio","fiche":"222","front":"Prévention secondaire : faut-il calculer un score de risque ?","back":"**Non** : risque **d'emblée très élevé**.","prio":"P2","sec":"s16"},{"id":"fc-222-dbf34a","poly":"cardio","fiche":"222","front":"BASIC : signification ?","back":"**B**êtabloquant, **A**ntiagrégant, **S**tatine, **I**EC, **C**ontrôle des facteurs de risque.","prio":"P1","sec":"s16"},{"id":"fc-222-9afda7","poly":"cardio","fiche":"222","front":"BASIC : réduction de mortalité totale post-IDM par classe ?","back":"Environ **25 %** pour chacune des 4 classes.","prio":"P1","sec":"s16"},{"id":"fc-222-668a36","poly":"cardio","fiche":"222","front":"BASIC : contenu du « C » ?","back":"**Arrêt du tabac**, contrôle de la **PA** et de la **glycémie**, lutte contre la **sédentarité**.","prio":"P2","sec":"s16"},{"id":"fc-222-c7486b","poly":"cardio","fiche":"222","front":"Prévention secondaire : place de la statine ?","back":"**Systématique** quels que soient âge, sexe, FDR et cholestérol de départ ; cible **LDL-C < 0,55 g/L**.","prio":"P1","sec":"s16"},{"id":"fc-222-092e13","poly":"cardio","fiche":"222","front":"Après un accident coronarien : quelle démarche chez les apparentés, et surtout dans quel cas ?","back":"Une **enquête familiale** chez les apparentés, surtout si le patient est **jeune**.","prio":"P1","sec":"s16"},{"id":"fc-222-35a9ce","poly":"cardio","fiche":"222","front":"Inhibiteurs de PCSK9 : nature et efficacité ?","back":"**Anticorps SC** (alirocumab, évolocumab) ; baisse supplémentaire du LDL-C **≈ 50 %** sous statine.","prio":"P3","sec":"s16"},{"id":"fc-222-c15dab","poly":"cardio","fiche":"222","front":"Après IDM : statine prescrite et objectif ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg** ; LDL-C **< 0,55 g/L** et baisse **≥ 50 %**.","prio":"P1","sec":"s16"},{"id":"fc-222-16e91a","poly":"cardio","fiche":"222","front":"Après IDM : aspirine, dose ?","back":"**75 à 100 mg/j**, au long cours.","prio":"P1","sec":"s16"},{"id":"fc-222-0c5449","poly":"cardio","fiche":"222","front":"Après IDM : doses d'entretien des inhibiteurs P2Y12 ?","back":"Clopidogrel **75 mg/j** ; prasugrel **10 mg/j** ; ticagrélor **90 mg × 2/j** ; habituellement **12 mois**.","prio":"P2","sec":"s16"},{"id":"fc-222-4d05b9","poly":"cardio","fiche":"222","front":"Après IDM à FEVG basse : bêtabloquants validés ?","back":"**Carvédilol**, **métoprolol**, **bisoprolol**, **nébivolol**.","prio":"P2","sec":"s16"},{"id":"fc-222-f6eefc","poly":"cardio","fiche":"222","front":"Bêtabloquant si FEVG basse : schéma de titration ?","back":"Débuter très bas (bisoprolol **1,25 mg/j**), paliers **hebdomadaires** jusqu'à **10 mg/j** selon tolérance.","prio":"P3","sec":"s16"},{"id":"fc-222-e89aec","poly":"cardio","fiche":"222","front":"IEC : contre-indications ?","back":"**Grossesse**, ATCD d'**angio-œdème**, **sténose bilatérale des artères rénales**, **hyperkaliémie**.","prio":"P1","sec":"s16"},{"id":"fc-222-fcf5f0","poly":"cardio","fiche":"222","front":"Après IDM : BB et IEC sont-ils systématiques selon l'item SCA ?","back":"**Non** : formellement indiqués si **FEVG ≤ 40 %** (IEC/ARA2 aussi si diabète ou IRC).","prio":"P2","sec":"s16"},{"id":"fc-222-c7202b","poly":"cardio","fiche":"222","front":"Après IDM : indication de l'éplérénone ?","back":"**FEVG ≤ 40 %** avec IC congestive ou diabète, **après** BB + IEC.","prio":"P3","sec":"s16"},{"id":"fc-222-59ecdc","poly":"cardio","fiche":"222","front":"Après IDM avec indication d'anticoagulation (FA) : schéma ?","back":"Anticoagulant pleine dose **+ clopidogrel 12 mois**, puis anticoagulant seul ; trithérapie possible ≈ 1 mois.","prio":"P3","sec":"s16"},{"id":"fc-222-3dd333","poly":"cardio","fiche":"222","front":"FEVG < 35 % à distance d'un IDM malgré traitement optimal : conduite ?","back":"**Défibrillateur automatique implantable** (≥ 6 semaines post-IDM).","prio":"P2","sec":"s16"},{"id":"fc-222-d670aa","poly":"cardio","fiche":"222","front":"Prévention secondaire : 2 notions inacceptables ?","back":"**Oublier le BASIC** ; **ignorer la cible de LDL-C < 0,55 g/L**.","prio":"P1","sec":"s16"},{"id":"fc-222-165279","poly":"cardio","fiche":"222","front":"Après un SCA : à qui proposer une réadaptation cardiovasculaire ?","back":"À **tout patient** (hospitalisation ou ambulatoire) : surveillance, éducation thérapeutique, reprise de l'activité physique.","prio":"P2","sec":"s16"},{"id":"fc-222-b1016c","poly":"cardio","fiche":"222","front":"Après IDM : quand ajouter l'ézétimibe à la statine ?","back":"**10 mg** si LDL-C au-dessus de l'objectif après **4 semaines** de statine à dose maximale tolérée.","prio":"P3","sec":"s16"},{"id":"fc-222-1f8547","poly":"cardio","fiche":"222","front":"Prévention secondaire : quand associer un IPP ?","back":"Si **risque hémorragique digestif élevé** (âge ≥ 65 ans, ATCD d'ulcère, corticothérapie prolongée…).","prio":"P3","sec":"s16"},{"id":"fc-222-60498f","poly":"cardio","fiche":"222","front":"Après un accident coronarien : bénéfice de l'arrêt du tabac ?","back":"Décès **−36 %** ; récidive d'IDM **−32 %** ; bénéfice aussi important après **pontage** ou **angioplastie**.","prio":"P3","sec":"s17"},{"id":"fc-222-67035d","poly":"cardio","fiche":"222","front":"Coronarien fumeur : substituts nicotiniques ?","back":"**Recommandés** (HAS 2014) : bien tolérés, sans aggravation coronarienne ni trouble du rythme.","prio":"P1","sec":"s17"},{"id":"fc-222-e44d2b","poly":"cardio","fiche":"222","front":"Coronarien fumeur : pourquoi une aide médicalisée ?","back":"Rechutes **fréquentes et précoces** (dépendance forte + changement brutal).","prio":"P2","sec":"s17"},{"id":"fc-222-e3a4c3","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : objectif de base et première étape ?","back":"**PA ≤ 140/90 mmHg**, d'abord par les **mesures hygiénodiététiques**.","prio":"P2","sec":"s17"},{"id":"fc-222-0679e0","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : quand ajouter un médicament ?","back":"PA d'emblée **≥ 160/100**, ou **≥ 140/90 après 3 mois** de mesures hygiénodiététiques.","prio":"P1","sec":"s17"},{"id":"fc-222-e759f5","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : PAS cible selon l'âge (ESC 2021) ?","back":"**120-129** avant 70 ans ; **130-139** à partir de 70 ans (voire jusqu'à 130 si bien toléré) ; **PAD < 80** pour tous.","prio":"P2","sec":"s17"},{"id":"fc-222-b017af","poly":"cardio","fiche":"222","front":"Prévention secondaire : PA cible des points clés ?","back":"**< 130/80 mmHg**.","prio":"P1","sec":"s17"},{"id":"fc-222-e9287d","poly":"cardio","fiche":"222","front":"Coronarien hypertendu : antihypertenseurs de 1re intention ?","back":"**IEC**, **ARA2** ou **bêtabloquant**.","prio":"P2","sec":"s17"},{"id":"fc-222-83415f","poly":"cardio","fiche":"222","front":"Hypertendu angineux : antihypertenseurs préférentiels ?","back":"**Inhibiteur calcique** ou **bêtabloquant**.","prio":"P3","sec":"s17"},{"id":"fc-222-1b681e","poly":"cardio","fiche":"222","front":"Après IDM : facteur multiplicatif du risque lié au diabète ?","back":"**× 2 à 3** le risque d'événement cardiaque grave.","prio":"P2","sec":"s18"},{"id":"fc-222-f310fa","poly":"cardio","fiche":"222","front":"Coronarien diabétique : stratégie principale de prévention ?","back":"**Correction agressive de tous les autres FDR** (bénéfice glycémique post-IDM non démontré).","prio":"P1","sec":"s18"},{"id":"fc-222-ed6750","poly":"cardio","fiche":"222","front":"Enquête familiale : âges définissant un coronarien « relativement jeune » ?","back":"**< 55 ans** (homme), **< 65 ans** (femme).","prio":"P1","sec":"s18"},{"id":"fc-222-ffa2b9","poly":"cardio","fiche":"222","front":"Enquête familiale : qui dépister ?","back":"**Frères, sœurs** et **enfants**, pour une prévention primaire précoce.","prio":"P2","sec":"s18"},{"id":"fc-222-e012e6","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : objectif de LDL-C jusqu'à 20 ans ?","back":"**< 1,3 g/L**.","prio":"P3","sec":"s18"},{"id":"fc-222-f254bf","poly":"cardio","fiche":"222","front":"Hypercholestérolémie familiale : dépistage des apparentés ?","back":"**Dépistage en cascade** des apparentés du **1er degré**.","prio":"P2","sec":"s18"},{"id":"fc-222-34f0c3","poly":"cardio","fiche":"222","front":"Coronarien : effet de l'activité physique sur la mortalité ?","back":"Mortalité totale et coronarienne **−20 à 25 %**.","prio":"P1","sec":"s18"},{"id":"fc-222-ab50bb","poly":"cardio","fiche":"222","front":"Coronarien : l'activité physique réduit-elle les récidives d'IDM non mortels ?","back":"**Non**, pas significativement.","prio":"P2","sec":"s18"},{"id":"fc-222-d226dc","poly":"cardio","fiche":"222","front":"Activité physique chez le coronarien : effets biologiques ?","back":"**Antiagrégant**, **anti-inflammatoire**, hausse **VO₂max**, meilleure **fonction endothéliale**, effet **antiarythmique**.","prio":"P3","sec":"s18"},{"id":"fc-222-605679","poly":"cardio","fiche":"222","front":"Coronarien jeune : quelle dyslipidémie génétique évoquer ?","back":"L'**hypercholestérolémie familiale hétérozygote** (LDL-C 2 à 4 g/L).","prio":"P2","sec":"s18"},{"id":"fc-222-776d52","poly":"cardio","fiche":"222","front":"Sous IEC : surveillance biologique ?","back":"**Créatininémie** et **kaliémie** **1 semaine** après l'introduction et chaque hausse de dose.","prio":"P2","sec":"s19"},{"id":"fc-222-3073c7","poly":"cardio","fiche":"222","front":"Sous bêtabloquant : surveillance ?","back":"**FC et PA** à chaque consultation.","prio":"P2","sec":"s19"},{"id":"fc-222-11195e","poly":"cardio","fiche":"222","front":"Après un SCA : examens pour rechercher d'autres localisations athéromateuses ?","back":"Échodoppler des **TSA**, échographie de l'**aorte abdominale**, échodoppler des **MI**.","prio":"P2","sec":"s19"},{"id":"fc-222-1b9a08","poly":"cardio","fiche":"222","front":"Tabac : fréquence de réévaluation au long cours ?","back":"**À chaque visite** (rechutes fréquentes et précoces).","prio":"P2","sec":"s19"},{"id":"fc-222-077ba3","poly":"cardio","fiche":"222","front":"Après IDM : éléments de sortie et suivi ?","back":"**BASIC complet**, **réadaptation**, plan tabac/PA/glycémie/activité ; suivi médecin traitant + cardiologue.","prio":"P2","sec":"s19"},{"id":"fc-223-5c5242","poly":"cardio","fiche":"223","front":"Dyslipidémie : principal danger ?","back":"La **maladie cardiovasculaire athéromateuse**, quel que soit le territoire.","prio":"P1","sec":"s1"},{"id":"fc-223-e0577f","poly":"cardio","fiche":"223","front":"Risque athéromateux : relation avec le LDL-C et le HDL-C ?","back":"**Augmente** avec le LDL-C (et le cholestérol non HDL) ; **diminue** avec le HDL-C ; risque **graduel**.","prio":"P1","sec":"s1"},{"id":"fc-223-3cc11c","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie : de quoi dépend le risque CV associé ?","back":"En grande partie des facteurs qui l'accompagnent : **surpoids**, **diabète**, **HDL bas**.","prio":"P2","sec":"s1"},{"id":"fc-223-baaf23","poly":"cardio","fiche":"223","front":"Triglycérides : seuil de risque de pancréatite aiguë ?","back":"**TG > 10 g/L**.","prio":"P1","sec":"s1"},{"id":"fc-223-a2e683","poly":"cardio","fiche":"223","front":"Dyslipidémie : cible principale du traitement et pourquoi ?","back":"Le **LDL-C** : c'est en le baissant que le **bénéfice CV** a été prouvé.","prio":"P1","sec":"s1"},{"id":"fc-223-8569ad","poly":"cardio","fiche":"223","front":"Hypercholestérolémie pure (HCH) : définition ?","back":"**LDL-C > 1,60 g/L** (ex-type IIa).","prio":"P1","sec":"s1"},{"id":"fc-223-5c0611","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie pure (HTG) : définition ?","back":"**TG > 1,5 g/L** (essentiellement type IV).","prio":"P1","sec":"s1"},{"id":"fc-223-dd3ef9","poly":"cardio","fiche":"223","front":"Hyperlipidémie mixte (HLM) : définition ?","back":"**HCH + HTG** (essentiellement type IIb, très rarement III).","prio":"P1","sec":"s1"},{"id":"fc-223-2a227d","poly":"cardio","fiche":"223","front":"Hypo-HDLémie : définition ?","back":"HDL-C **< 0,40 g/L** (homme), **< 0,50 g/L** (femme) ; peut s'ajouter aux 3 types.","prio":"P1","sec":"s1"},{"id":"fc-223-08db59","poly":"cardio","fiche":"223","front":"Classification de Fredrickson : place actuelle ?","back":"Biochimique, **de moins en moins utilisée** ; on raisonne en HCH, HTG, HLM.","prio":"P2","sec":"s1"},{"id":"fc-223-2e4be3","poly":"cardio","fiche":"223","front":"Bilan lipidique : valeur dans le temps ?","back":"**Photo à un instant donné**, variable avec l'**alimentation** et le **poids**.","prio":"P2","sec":"s1"},{"id":"fc-223-0906aa","poly":"cardio","fiche":"223","front":"Dyslipidémie : le phénotype renseigne-t-il sur le génotype ?","back":"**Pas forcément** : un même génotype peut donner plusieurs phénotypes selon les circonstances.","prio":"P3","sec":"s1"},{"id":"fc-223-9172d4","poly":"cardio","fiche":"223","front":"Étude génétique des dyslipidémies : nécessaire pour traiter ?","back":"**Peu souvent nécessaire** pour décider du traitement.","prio":"P3","sec":"s1"},{"id":"fc-223-9307d8","poly":"cardio","fiche":"223","front":"Bilan lipidique : chez qui est-il conseillé ?","back":"Chez **tout adulte**.","prio":"P1","sec":"s2"},{"id":"fc-223-23c070","poly":"cardio","fiche":"223","front":"Bilan lipidique normal : délai avant de le refaire ?","back":"**Pas avant 5 ans**.","prio":"P1","sec":"s2"},{"id":"fc-223-838e08","poly":"cardio","fiche":"223","front":"EAL : paramètres dosés ?","back":"**Cholestérol total**, **HDL-C**, **triglycérides** ; LDL-C **calculé**.","prio":"P1","sec":"s2"},{"id":"fc-223-51fe0f","poly":"cardio","fiche":"223","front":"Friedewald : formule en g/L et en mmol/L ?","back":"LDL-C = CT − HDL-C − **TG/5** (g/L) ou − **TG/2,2** (mmol/L).","prio":"P1","sec":"s2"},{"id":"fc-223-a49eb9","poly":"cardio","fiche":"223","front":"Friedewald : seuil de TG au-delà duquel le LDL-C calculé n'a pas de valeur ?","back":"**TG ≥ 3,5 g/L**.","prio":"P1","sec":"s2"},{"id":"fc-223-9580fb","poly":"cardio","fiche":"223","front":"Bilan lipidique normal (Afssaps 2005) : 3 conditions réunies ?","back":"LDL-C **< 1,6** · HDL-C **> 0,4** · TG **< 1,5 g/L**, chez un sujet sans autre FDR.","prio":"P1","sec":"s2"},{"id":"fc-223-52e52b","poly":"cardio","fiche":"223","front":"Bilan lipidique anormal : 2 étapes suivantes ?","back":"**Classer** l'anomalie (HCH, HTG, HLM ± hypo-HDL) puis chercher une **cause secondaire**.","prio":"P2","sec":"s2"},{"id":"fc-223-5d4dcc","poly":"cardio","fiche":"223","front":"Dyslipidémie : causes secondaires recherchées à l'interrogatoire ?","back":"**Alcool** et **médicaments**.","prio":"P1","sec":"s3"},{"id":"fc-223-9e7343","poly":"cardio","fiche":"223","front":"Hypothyroïdie : examen et dyslipidémie associée ?","back":"**TSH** ; le plus souvent HCH ou HLM.","prio":"P1","sec":"s3"},{"id":"fc-223-ef376f","poly":"cardio","fiche":"223","front":"Cholestase : examens et dyslipidémie associée ?","back":"**Bilirubine**, **phosphatases alcalines** ; **HCH**.","prio":"P2","sec":"s3"},{"id":"fc-223-1fd687","poly":"cardio","fiche":"223","front":"Syndrome néphrotique : dyslipidémie associée et moyens diagnostiques ?","back":"**HLM** ; **protéinurie**, œdèmes.","prio":"P2","sec":"s3"},{"id":"fc-223-11920e","poly":"cardio","fiche":"223","front":"Insuffisance rénale chronique : dyslipidémie associée ?","back":"**HTG** ou **HLM** (créatinine).","prio":"P2","sec":"s3"},{"id":"fc-223-47333e","poly":"cardio","fiche":"223","front":"Alcoolisme et diabète : dyslipidémie associée ?","back":"**Hypertriglycéridémie**.","prio":"P1","sec":"s3"},{"id":"fc-223-568d14","poly":"cardio","fiche":"223","front":"Médicaments responsables d'hypertriglycéridémie ?","back":"**Œstrogènes**, **rétinoïdes**, **antirétroviraux** ; aussi corticoïdes et antipsychotiques (HTG ou HLM).","prio":"P2","sec":"s3"},{"id":"fc-223-51fe84","poly":"cardio","fiche":"223","front":"Ciclosporine : dyslipidémie induite ?","back":"**HCH** ou **HLM**.","prio":"P3","sec":"s3"},{"id":"fc-223-1a2485","poly":"cardio","fiche":"223","front":"Dyslipidémie : bilan biologique des causes secondaires ?","back":"**TSH**, **bilirubine + PAL**, **protéinurie**, **créatinine**, **glycémie + HbA1c**.","prio":"P1","sec":"s3"},{"id":"fc-223-723d75","poly":"cardio","fiche":"223","front":"Hypercholestérolémie polygénique : fréquence et LDL-C habituel ?","back":"**Très fréquente** ; LDL-C le plus souvent **1,3-2,5 g/L**.","prio":"P2","sec":"s4"},{"id":"fc-223-bb1494","poly":"cardio","fiche":"223","front":"Hypercholestérolémie polygénique : particularité ?","back":"Souvent assez **sensible à l'alimentation**.","prio":"P2","sec":"s4"},{"id":"fc-223-d364c0","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : fréquence ?","back":"**1 à 2 %** de la population.","prio":"P2","sec":"s4"},{"id":"fc-223-083d66","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : bilan typique ?","back":"**HLM modérée** : CT 2,5-3,5 g/L (LDL-C 1,6-2,5), **TG 1,5-5 g/L**.","prio":"P3","sec":"s4"},{"id":"fc-223-682420","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie familiale : bilan et risque athérogène ?","back":"**HTG pure** chez le sujet et ses apparentés ; risque athérogène **incertain**.","prio":"P2","sec":"s4"},{"id":"fc-223-1785c5","poly":"cardio","fiche":"223","front":"Hypertriglycéridémie familiale : 2 diagnostics différentiels ?","back":"**HTG dépendante de l'alimentation** et **hyperlipidémie familiale combinée**.","prio":"P2","sec":"s4"},{"id":"fc-223-95c983","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : fréquence et bilan ?","back":"**Rare** (1/10 000 à 1/5 000) ; CT 3-6 g/L, TG 4-10 g/L.","prio":"P3","sec":"s4"},{"id":"fc-223-6d1c04","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : 2 conditions d'expression ?","back":"Génotype **apoE E2/E2** + un **facteur associé** (surpoids, diabète, hypothyroïdie, certains traitements).","prio":"P2","sec":"s4"},{"id":"fc-223-5bb132","poly":"cardio","fiche":"223","front":"Hyperchylomicronémies primitives : TG et risque ?","back":"Très rares ; TG **> 10 g/L** (jusqu'à 100) ; risque majeur de **pancréatite aiguë**.","prio":"P2","sec":"s4"},{"id":"fc-223-48cc91","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale monogénique : cause la plus fréquente ?","back":"Mutation du gène du **récepteur aux LDL (LDL-R)**.","prio":"P1","sec":"s4"},{"id":"fc-223-676408","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale par mutation de l'apoB : particularités ?","back":"Plus rare ; LDL moins bien fixées ; hypercholestérolémie **plus modérée** (LDL-C **classiquement 2-3 g/L**), xanthomes rares.","prio":"P3","sec":"s4"},{"id":"fc-223-19f846","poly":"cardio","fiche":"223","front":"Mutation gain de fonction de PCSK9 : mécanisme ?","back":"PCSK9 se lie davantage au LDL-R, qui est **détruit** au lieu d'être recyclé.","prio":"P3","sec":"s4"},{"id":"fc-223-760b4a","poly":"cardio","fiche":"223","front":"Score Dutch-HF : rôle ?","back":"Diagnostic de **probabilité** d'hypercholestérolémie familiale (ATCD, xanthomes, LDL-C).","prio":"P3","sec":"s4"},{"id":"fc-223-473a3e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : LDL-C avant traitement (points clés) ?","back":"Entre **2 et 4 g/L** ; forme hétérozygote **fréquente**, homozygote très rare.","prio":"P1","sec":"s4"},{"id":"fc-223-3832b9","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote (LDL-R) : fréquence ?","back":"**1/300** (mutation retrouvée dans 80 % des cas).","prio":"P3","sec":"s4"},{"id":"fc-223-801a08","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale homozygote : fréquence, LDL-C, risque ?","back":"**1/500 000** ; LDL-C **> 5 g/L** ; complications dès la **1re décennie**.","prio":"P3","sec":"s4"},{"id":"fc-223-532eea","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : dépôts lipidiques évocateurs ?","back":"**Xanthomes tendineux** et **arc cornéen prématuré** (inconstants).","prio":"P2","sec":"s4"},{"id":"fc-223-8f05e7","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : xanthomes caractéristiques ?","back":"**Xanthomes plans palmaires** et **tubéreux** jaune orangé.","prio":"P3","sec":"s4"},{"id":"fc-223-535de5","poly":"cardio","fiche":"223","front":"Hyperlipidémie familiale combinée : stabilité du phénotype ?","back":"**Variable** dans une famille, voire chez une même personne (HLM, HCH ou HTG).","prio":"P3","sec":"s4"},{"id":"fc-223-58f846","poly":"cardio","fiche":"223","front":"SCORE2 (ESC 2021) : population et événement estimé ?","back":"**40-69 ans** ; risque à **10 ans** d'événement CV majeur (IDM, AVC, décès CV).","prio":"P1","sec":"s5"},{"id":"fc-223-c967a1","poly":"cardio","fiche":"223","front":"SCORE2 : paramètre lipidique utilisé ?","back":"**Cholestérol non-HDL** (= CT − HDL-C).","prio":"P2","sec":"s5"},{"id":"fc-223-b22d76","poly":"cardio","fiche":"223","front":"SCORE2-OP : population ?","back":"**70 ans ou plus**.","prio":"P2","sec":"s5"},{"id":"fc-223-86278c","poly":"cardio","fiche":"223","front":"SCORE2-Diabetes : population ?","back":"**DT2** sans maladie CV athéroscléreuse ni lésion grave d'organe cible.","prio":"P2","sec":"s5"},{"id":"fc-223-66e19c","poly":"cardio","fiche":"223","front":"Dyslipidémie : situations où SCORE2 n'est pas adapté ?","back":"**Diabète**, **IRC** (DFG < 60), **hypercholestérolémie familiale** (élevé/très élevé d'emblée) ; **prévention secondaire** (très élevé).","prio":"P1","sec":"s5"},{"id":"fc-223-83c4df","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : catégorie de risque CV ?","back":"**Élevé** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-223-072cdd","poly":"cardio","fiche":"223","front":"Maladie CV établie (coronaire, AIT/AVC, AOMI) : catégorie de risque ?","back":"**Très élevé** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-223-0cade0","poly":"cardio","fiche":"223","front":"IRC à risque CV très élevé : critères ?","back":"**DFG < 30**, ou **DFG 30-44 avec RAC > 30**.","prio":"P2","sec":"s5"},{"id":"fc-223-77d08b","poly":"cardio","fiche":"223","front":"IRC à risque CV élevé : critères ?","back":"DFG 30-45 et RAC < 30 ; DFG 45-59 et RAC 30-299 ; DFG > 60 et RAC > 300.","prio":"P3","sec":"s5"},{"id":"fc-223-61beba","poly":"cardio","fiche":"223","front":"Diabète à risque modéré : définition ?","back":"**Bien contrôlé depuis < 10 ans**, sans atteinte d'organe cible ni FDR associé.","prio":"P2","sec":"s5"},{"id":"fc-223-cf40cf","poly":"cardio","fiche":"223","front":"Diabète à risque élevé : définition ?","back":"Sans maladie CV ni AOC, mais avec un **FDR associé** ou **> 10 ans** d'évolution.","prio":"P1","sec":"s5"},{"id":"fc-223-e294ca","poly":"cardio","fiche":"223","front":"Diabète à risque très élevé : définition ?","back":"**Maladie CV** ou **AOC sévère** (insuffisance rénale, microangiopathie sur 3 sites).","prio":"P2","sec":"s5"},{"id":"fc-223-2da0c0","poly":"cardio","fiche":"223","front":"Sujet sain 50-69 ans : seuils SCORE2 des catégories ?","back":"Faible-modéré **< 5 %** ; élevé **5-10 %** ; très élevé **> 10 %**.","prio":"P2","sec":"s5"},{"id":"fc-223-6e7590","poly":"cardio","fiche":"223","front":"Sujet sain < 50 ans : seuils SCORE2 ?","back":"Faible-modéré **< 2,5 %** ; élevé **2,5-7,5 %** ; très élevé **> 7,5 %**.","prio":"P3","sec":"s5"},{"id":"fc-223-8d4112","poly":"cardio","fiche":"223","front":"Sujet sain ≥ 70 ans : seuils SCORE2-OP ?","back":"Faible-modéré **< 7,5 %** ; élevé **7,5-15 %** ; très élevé **> 15 %**.","prio":"P3","sec":"s5"},{"id":"fc-223-8e251f","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque faible ?","back":"**< 1,15 g/L** (< 3 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-6a6e5b","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque modéré ?","back":"**< 1 g/L** (< 2,6 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-00a58d","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque élevé ?","back":"**< 0,70 g/L** (< 1,8 mmol/L).","prio":"P1","sec":"s5"},{"id":"fc-223-56291f","poly":"cardio","fiche":"223","front":"Cible de LDL-C : risque très élevé ?","back":"**< 0,55 g/L** (< 1,4 mmol/L), en prévention primaire ou secondaire.","prio":"P1","sec":"s5"},{"id":"fc-223-af2ee1","poly":"cardio","fiche":"223","front":"Stratégie ESC : LDL-C au-dessus de la cible versus nettement au-dessus ?","back":"Au-dessus : **envisager** un médicament ; nettement au-dessus : **associer** un médicament.","prio":"P2","sec":"s5"},{"id":"fc-223-3e82b6","poly":"cardio","fiche":"223","front":"Prévention secondaire avec LDL-C au-dessus de la cible : conduite ?","back":"Médicament associé **d'emblée** aux conseils de mode de vie.","prio":"P1","sec":"s5"},{"id":"fc-223-dc04f4","poly":"cardio","fiche":"223","front":"Seuils ESC de LDL-C pour un médicament d'emblée selon le risque ?","back":"**> 1,9 g/L** (faible/modéré) ; **> 1 g/L** (élevé) ; **> 0,70 g/L** (très élevé) ; **> 0,55** (secondaire).","prio":"P3","sec":"s5"},{"id":"fc-223-cf0d1d","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : les 4 cibles générales s'appliquent-elles ?","back":"**Non** : objectifs propres.","prio":"P2","sec":"s5"},{"id":"fc-223-718e26","poly":"cardio","fiche":"223","front":"LDL-C à 1,6 g/L : signification ?","back":"Seuil d'un **bilan normal** chez un sujet sans autre FDR, **pas la cible** thérapeutique.","prio":"P1","sec":"s6"},{"id":"fc-223-fc9210","poly":"cardio","fiche":"223","front":"LDL-C à 1,3 g/L dans l'hypercholestérolémie familiale : signification ?","back":"**Cible jusqu'à 20 ans**.","prio":"P2","sec":"s6"},{"id":"fc-223-f333e7","poly":"cardio","fiche":"223","front":"Coronarien dyslipidémique : faut-il calculer SCORE2 ?","back":"**Non** : maladie CV établie = **très élevé d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-223-b5c1bb","poly":"cardio","fiche":"223","front":"Fibrates « souvent efficaces » : dans quelle dyslipidémie primitive ?","back":"La **dysbêtalipoprotéinémie** (pas l'hypercholestérolémie familiale).","prio":"P3","sec":"s6"},{"id":"fc-223-75696f","poly":"cardio","fiche":"223","front":"Diététique dans les dyslipidémies : indication et durée ?","back":"**Toute** anomalie lipidique et tout FDR ; **au long cours**, même sous médicament.","prio":"P1","sec":"s7"},{"id":"fc-223-22086c","poly":"cardio","fiche":"223","front":"Hypercholestérolémie, régime : apport maximal en acides gras saturés ?","back":"**< 10-12 %** des calories, remplacés par des **mono- ou poly-insaturés**.","prio":"P1","sec":"s7"},{"id":"fc-223-8442d5","poly":"cardio","fiche":"223","front":"Acides gras trans : recommandation ?","back":"**À supprimer** (« partiellement hydrogénés »).","prio":"P2","sec":"s7"},{"id":"fc-223-65431c","poly":"cardio","fiche":"223","front":"Régime hypocholestérolémiant : aliments à augmenter ?","back":"**Oméga-3** (poissons) et **fibres** (fruits, légumes, céréales complètes).","prio":"P2","sec":"s7"},{"id":"fc-223-94d39f","poly":"cardio","fiche":"223","front":"Cholestérol alimentaire : limitation et œufs ?","back":"Limitation **modérée** ; œufs conservés, **≈ 3 par semaine**.","prio":"P2","sec":"s7"},{"id":"fc-223-0f66a6","poly":"cardio","fiche":"223","front":"Régime méditerranéen : repères chiffrés ?","back":"**Huile d'olive** ; **5 portions** de fruits et légumes/j ; fruits à coque **30 g/j**.","prio":"P2","sec":"s7"},{"id":"fc-223-f3c657","poly":"cardio","fiche":"223","front":"Points clés diététiques : lipides totaux, cholestérol alimentaire, sel ?","back":"Lipides **< 35 %** de l'apport ; cholestérol **< 300 mg/j** ; NaCl **< 6 g/j**.","prio":"P3","sec":"s7"},{"id":"fc-223-f410d5","poly":"cardio","fiche":"223","front":"HTG modérée sans hyperchylomicronémie : mesures diététiques ?","back":"**Perte de poids** (graisse abdominale), moins d'**alcool**, moins de **sucres**, équilibre du **diabète**.","prio":"P1","sec":"s7"},{"id":"fc-223-1ef288","poly":"cardio","fiche":"223","front":"HTG modérée : place des médicaments ?","back":"**Impact mineur** ; la diététique est l'essentiel du traitement.","prio":"P2","sec":"s7"},{"id":"fc-223-1aae46","poly":"cardio","fiche":"223","front":"HTG majeure avec hyperchylomicronémie : prise en charge diététique ?","back":"**Avis spécialisé** ; lipides **< 30 g/j**.","prio":"P3","sec":"s7"},{"id":"fc-223-d48ade","poly":"cardio","fiche":"223","front":"Aliments enrichis en stérols végétaux : place ?","back":"Utilisation seulement **discutée**.","prio":"P3","sec":"s7"},{"id":"fc-223-b09f49","poly":"cardio","fiche":"223","front":"Prévention primaire : délai minimal de diététique avant médicament ?","back":"**Au moins 3 mois**, si le LDL-C reste éloigné de la cible.","prio":"P1","sec":"s8"},{"id":"fc-223-6475fb","poly":"cardio","fiche":"223","front":"Prévention primaire : quand un hypolipémiant d'emblée ?","back":"LDL-C **très au-dessus** de la cible.","prio":"P2","sec":"s8"},{"id":"fc-223-bdce9a","poly":"cardio","fiche":"223","front":"Hypercholestérolémie : hypolipémiant de 1er choix et pourquoi ?","back":"**Statine** : bénéfice CV le **mieux démontré**.","prio":"P1","sec":"s8"},{"id":"fc-223-c0fd54","poly":"cardio","fiche":"223","front":"Statine en prévention primaire : posologie initiale ?","back":"**Faible ou modérée**, augmentée progressivement jusqu'à la cible.","prio":"P2","sec":"s8"},{"id":"fc-223-67f5e0","poly":"cardio","fiche":"223","front":"Statines anciennes versus récentes ?","back":"Anciennes : **simvastatine**, **pravastatine** ; récentes : **atorvastatine**, **rosuvastatine**.","prio":"P2","sec":"s8"},{"id":"fc-223-ccab71","poly":"cardio","fiche":"223","front":"Statines : contre-indication ?","back":"**Grossesse**.","prio":"P1","sec":"s8"},{"id":"fc-223-8b057e","poly":"cardio","fiche":"223","front":"Statine : baisse attendue du LDL-C ?","back":"**25 à 50 %** selon la molécule et la dose.","prio":"P3","sec":"s8"},{"id":"fc-223-e7c540","poly":"cardio","fiche":"223","front":"Prévention secondaire : délai de mise sous hypolipémiant ?","back":"**D'emblée**, avec la diététique, souvent à **forte posologie** (baisse > 50 %).","prio":"P1","sec":"s9"},{"id":"fc-223-f684d0","poly":"cardio","fiche":"223","front":"Après un SCA : statine et posologie ?","back":"**Statine forte dose**, ex. atorvastatine **80 mg** ou rosuvastatine **20 mg**.","prio":"P1","sec":"s9"},{"id":"fc-223-396bbb","poly":"cardio","fiche":"223","front":"Après un SCA : double objectif lipidique ?","back":"Baisse du LDL-C **≥ 50 %** et LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s9"},{"id":"fc-223-ca4ac6","poly":"cardio","fiche":"223","front":"Après un SCA, cible non atteinte sous statine : délai et ajout ?","back":"Après **4 semaines** à dose maximale tolérée : **ézétimibe 10 mg**.","prio":"P1","sec":"s9"},{"id":"fc-223-154434","poly":"cardio","fiche":"223","front":"Après un SCA, cible toujours non atteinte malgré l'ézétimibe (item 339) ?","back":"**Inhibiteur de PCSK9**, remboursé si LDL-C **> 0,7 g/L**.","prio":"P2","sec":"s9"},{"id":"fc-223-a2687c","poly":"cardio","fiche":"223","front":"Après un SCA : aspirine et durée du P2Y12 ?","back":"Aspirine **75-100 mg/j** au long cours ; P2Y12 habituellement **12 mois**.","prio":"P2","sec":"s9"},{"id":"fc-223-28b67f","poly":"cardio","fiche":"223","front":"Antiminéralocorticoïde : effets indésirables de la spironolactone ?","back":"**Hyperkaliémie**, insuffisance rénale ; **gynécomastie**, **impuissance**.","prio":"P3","sec":"s9"},{"id":"fc-223-42032e","poly":"cardio","fiche":"223","front":"Après un SCA : quand le bêtabloquant est-il formellement indiqué ?","back":"Si **FEVG ≤ 40 %** (non systématique sinon).","prio":"P3","sec":"s9"},{"id":"fc-223-d7a79e","poly":"cardio","fiche":"223","front":"Après un SCA : quand implanter un DAI ?","back":"**FEVG < 35 %** à **≥ 6 semaines** de l'IDM après optimisation ; gilet en attendant.","prio":"P3","sec":"s9"},{"id":"fc-223-7721f0","poly":"cardio","fiche":"223","front":"Cible de LDL-C non atteinte sous statine : 1re étape ?","back":"**Intensifier** : dose **maximale tolérée** ou statine **plus puissante**.","prio":"P1","sec":"s10"},{"id":"fc-223-6c560b","poly":"cardio","fiche":"223","front":"Cible non atteinte à dose maximale tolérée de statine : 2e étape ?","back":"**Statine + ézétimibe**.","prio":"P1","sec":"s10"},{"id":"fc-223-3074f4","poly":"cardio","fiche":"223","front":"Escalade hypolipémiante (item 223) : dernier recours ?","back":"**Statine + colestyramine**.","prio":"P2","sec":"s10"},{"id":"fc-223-568060","poly":"cardio","fiche":"223","front":"Ézétimibe ajouté à la statine : baisse supplémentaire du LDL-C ?","back":"**≈ 20 %**.","prio":"P3","sec":"s10"},{"id":"fc-223-f75b99","poly":"cardio","fiche":"223","front":"Intolérance aux statines : alternatives ?","back":"**Ézétimibe**, voire colestyramine, **rarement fibrates** ; diététique maintenue.","prio":"P1","sec":"s10"},{"id":"fc-223-b68000","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : molécules et voie ?","back":"**Alirocumab**, **évolocumab** ; anticorps monoclonaux **sous-cutanés**.","prio":"P3","sec":"s10"},{"id":"fc-223-48d8bd","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : efficacité ?","back":"**−50 %** de LDL-C en plus de la statine ; **moins d'événements CV**.","prio":"P3","sec":"s10"},{"id":"fc-223-856871","poly":"cardio","fiche":"223","front":"Anti-PCSK9 : conditions de remboursement ?","back":"**Accord préalable** ; prévention secondaire ou LDL-C **> 0,7 g/L** malgré statine à dose maximale tolérée.","prio":"P3","sec":"s10"},{"id":"fc-223-f777ed","poly":"cardio","fiche":"223","front":"Ajout d'un anti-PCSK9 : que faire de la statine ?","back":"La **poursuivre** à dose maximale tolérée.","prio":"P3","sec":"s10"},{"id":"fc-223-e83c29","poly":"cardio","fiche":"223","front":"HTG : causes secondaires à éliminer ?","back":"**Alcoolisme**, **diabète**, **IRC**, médicaments (œstrogènes, rétinoïdes, antirétroviraux, corticoïdes, antipsychotiques).","prio":"P1","sec":"s11"},{"id":"fc-223-a111b0","poly":"cardio","fiche":"223","front":"HTG entre 1,5 et 5 g/L : traitement ?","back":"**Diététique seule**.","prio":"P1","sec":"s11"},{"id":"fc-223-3782c7","poly":"cardio","fiche":"223","front":"HTG : indication du fibrate ?","back":"**TG > 5 g/L malgré une diététique bien suivie**, en association à celle-ci.","prio":"P1","sec":"s11"},{"id":"fc-223-6bd414","poly":"cardio","fiche":"223","front":"HTG > 5 g/L : traitement éventuellement associé au fibrate ?","back":"**Oméga-3 (n-3) à forte posologie** (formulation non commercialisée en France en 2025).","prio":"P3","sec":"s11"},{"id":"fc-223-d80547","poly":"cardio","fiche":"223","front":"HTG : contrôle biologique après mise en route du traitement ?","back":"Bilan lipidique **8 à 12 semaines** après.","prio":"P2","sec":"s11"},{"id":"fc-223-1fa443","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale hétérozygote : dépistage familial ?","back":"**Dépistage en cascade** des **apparentés du 1er degré**.","prio":"P1","sec":"s12"},{"id":"fc-223-bcaf9e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : cible de LDL-C jusqu'à 20 ans ?","back":"**< 1,3 g/L** (3,4 mmol/L).","prio":"P1","sec":"s12"},{"id":"fc-223-608f5e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale après 20 ans : cible de LDL-C ?","back":"Cible du **risque élevé** (< 0,70) ou de la **prévention secondaire** (< 0,55 g/L).","prio":"P2","sec":"s12"},{"id":"fc-223-90df0e","poly":"cardio","fiche":"223","front":"Hypercholestérolémie familiale : traitement ?","back":"**Identique** à l'hypercholestérolémie isolée (diététique, statine, escalade) ; **avis spécialisé** si résistance.","prio":"P2","sec":"s12"},{"id":"fc-223-b00e06","poly":"cardio","fiche":"223","front":"Diabète à risque modéré : cible de LDL-C ?","back":"**< 1 g/L**.","prio":"P2","sec":"s12"},{"id":"fc-223-63cd2f","poly":"cardio","fiche":"223","front":"Diabète avec FDR associé ou > 10 ans d'évolution : cible de LDL-C ?","back":"**< 0,70 g/L** (risque élevé).","prio":"P1","sec":"s12"},{"id":"fc-223-dc0a66","poly":"cardio","fiche":"223","front":"Diabète avec maladie CV ou atteinte d'organe cible sévère : cible de LDL-C ?","back":"**< 0,55 g/L**.","prio":"P2","sec":"s12"},{"id":"fc-223-cc4981","poly":"cardio","fiche":"223","front":"Insuffisance rénale sous statine : précaution ?","back":"IR modérée à sévère = **situation à risque** : doser les **CPK**.","prio":"P2","sec":"s12"},{"id":"fc-223-b6e5f7","poly":"cardio","fiche":"223","front":"Dyslipidémie pendant la grossesse : traitement ?","back":"**Diététique** ; statines **contre-indiquées**.","prio":"P1","sec":"s12"},{"id":"fc-223-d0171c","poly":"cardio","fiche":"223","front":"Dysbêtalipoprotéinémie : traitement ?","back":"**Diététique** et **statines** ; **fibrates** souvent efficaces.","prio":"P3","sec":"s12"},{"id":"fc-223-a29c82","poly":"cardio","fiche":"223","front":"Hypolipémiant : délai du bilan lipidique de contrôle ?","back":"**8 à 12 semaines** après l'instauration et après chaque adaptation.","prio":"P1","sec":"s13"},{"id":"fc-223-b637a5","poly":"cardio","fiche":"223","front":"Hypolipémiants (surtout statines) : effet indésirable le plus fréquent ?","back":"Les **myalgies** ; surveillance **essentiellement clinique**.","prio":"P1","sec":"s13"},{"id":"fc-223-073bf2","poly":"cardio","fiche":"223","front":"Statine : CPK systématiques ?","back":"**Non** : seulement en **situation à risque**.","prio":"P1","sec":"s13"},{"id":"fc-223-60fbf4","poly":"cardio","fiche":"223","front":"Statine : seuil de CPK imposant l'arrêt ?","back":"**CPK > 5 N** (dosées à distance d'un effort sportif).","prio":"P1","sec":"s13"},{"id":"fc-223-58b2cc","poly":"cardio","fiche":"223","front":"Statine : situations à risque justifiant un dosage des CPK ?","back":"**Douleurs musculaires**, **IR** modérée-sévère, **hypothyroïdie**, ATCD de myopathie génétique, **alcool**, **> 70 ans**.","prio":"P2","sec":"s13"},{"id":"fc-223-15a413","poly":"cardio","fiche":"223","front":"Statine : calendrier des ALAT ?","back":"**Avant**, **8-12 semaines** après le début ou toute hausse de dose, puis **tous les ans** si < 3 N.","prio":"P2","sec":"s13"},{"id":"fc-223-c4d2e3","poly":"cardio","fiche":"223","front":"Statine avec ALAT > 3 N : conduite ?","back":"**Arrêter ou réduire** la statine ; recontrôle après **4 à 6 semaines**.","prio":"P1","sec":"s13"},{"id":"fc-223-2a68f0","poly":"cardio","fiche":"223","front":"Points clés : délai d'évaluation de l'efficacité hypolipémiante et des transaminases ?","back":"Bilan lipidique à **2-3 mois** ; transaminases à **3 mois**.","prio":"P3","sec":"s13"},{"id":"fc-223-ffe2c1","poly":"cardio","fiche":"223","front":"Dyslipidémie au long cours : suivi une fois la cible atteinte ?","back":"Tolérance : **myalgies**, **ALAT annuelles** si < 3 N ; diététique poursuivie.","prio":"P2","sec":"s14"},{"id":"fc-223-ca6b24","poly":"cardio","fiche":"223","front":"Après un SCA : suivi conjoint et objectifs ?","back":"**Médecin référent + cardiologue** ; tabac, activité, régime, **LDL-C dans l'objectif** sans toxicité, glycémie, PA.","prio":"P2","sec":"s14"},{"id":"fc-223-83fd8d","poly":"cardio","fiche":"223","front":"Après un SCA : localisations athéromateuses à rechercher ?","back":"Échodoppler des **TSA**, échographie de l'**aorte abdominale**, échodoppler des **MI**.","prio":"P2","sec":"s14"},{"id":"fc-223-f98e46","poly":"cardio","fiche":"223","front":"Après un SCA : réadaptation cardiovasculaire ?","back":"**Proposée à tous**.","prio":"P1","sec":"s14"},{"id":"fc-224-f236f7","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique de PA au cabinet (consultation) ?","back":"Moyenne des PAS **≥ 140 mmHg** et/ou des PAD **≥ 90 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-6b1876","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique en automesure (AMT) ?","back":"PA moyenne **≥ 135/85 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-d77e3d","poly":"cardio","fiche":"224","front":"HTA : quel est le seuil diagnostique en MAPA des 24 h ?","back":"PA moyenne des 24 h **≥ 130/80 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-f9736c","poly":"cardio","fiche":"224","front":"PA normale chez l'adulte (cabinet ou AMT) : quelles valeurs ?","back":"PAS **< 120** **et** PAD **< 70 mmHg**.","prio":"P2","sec":"s1"},{"id":"fc-224-b8154b","poly":"cardio","fiche":"224","front":"PA dite « élevée » : quelle définition simple ?","back":"PA **> 120/70 mmHg** sans critère diagnostique d'HTA.","prio":"P2","sec":"s1"},{"id":"fc-224-b420e6","poly":"cardio","fiche":"224","front":"PA élevée (ESC 2024) au cabinet : quelles valeurs ?","back":"PAS **120-139** et/ou PAD **70-89 mmHg** (AMT : 120-134 et/ou 70-84).","prio":"P3","sec":"s1"},{"id":"fc-224-a8059c","poly":"cardio","fiche":"224","front":"PA élevée (ESC 2024) : qu'impose-t-elle ?","back":"D'évaluer le **risque CV global** (SCORE2, SCORE2-OP, SCORE2-Diabetes ou haut risque d'emblée) ; antihypertenseur parfois si risque assez élevé.","prio":"P3","sec":"s1"},{"id":"fc-224-07b30c","poly":"cardio","fiche":"224","front":"MAPA nocturne : quel seuil définit l'HTA ?","back":"PAS **≥ 120** et/ou PAD **≥ 70 mmHg** (MAPA diurne : ≥ 135/85).","prio":"P3","sec":"s1"},{"id":"fc-224-02d79e","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 1 (consultation) ?","back":"PAS **140-159** et/ou PAD **90-99 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-fe0b28","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 2 (consultation) ?","back":"PAS **160-179** et/ou PAD **100-109 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-ded472","poly":"cardio","fiche":"224","front":"HTA : quelles sont les valeurs du grade 3 (consultation) ?","back":"PAS **≥ 180** et/ou PAD **≥ 110 mmHg**.","prio":"P1","sec":"s1"},{"id":"fc-224-6a9f3a","poly":"cardio","fiche":"224","front":"HTA de grade 3 : que faut-il rechercher systématiquement ?","back":"Une **urgence hypertensive** (atteinte **aiguë** d'un organe cible).","prio":"P1","sec":"s1"},{"id":"fc-224-c1b9ea","poly":"cardio","fiche":"224","front":"HTA dans le monde : combien de personnes et quel rang de mortalité ?","back":"Plus de **1,5 milliard** de personnes ; **1re cause de mortalité** (plus de **10 millions** de décès/an).","prio":"P3","sec":"s1"},{"id":"fc-224-9103b2","poly":"cardio","fiche":"224","front":"HTA en France (2023) : combien d'adultes hypertendus ?","back":"**17 millions** ; **1,6 million** de nouveaux patients traités chaque année.","prio":"P3","sec":"s1"},{"id":"fc-224-189c34","poly":"cardio","fiche":"224","front":"Étude ESTEBAN : quelle prévalence de l'HTA chez les 18-74 ans ?","back":"**30 %** des adultes.","prio":"P2","sec":"s1"},{"id":"fc-224-5e2a3a","poly":"cardio","fiche":"224","front":"Étude ESTEBAN : quelle part des hypertendus est diagnostiquée, traitée et contrôlée ?","back":"Seulement **25 %** (50 % non traités ; 50 % des traités hors objectif).","prio":"P2","sec":"s1"},{"id":"fc-224-0710df","poly":"cardio","fiche":"224","front":"Prévalence de l'HTA selon l'âge : chiffres après 70 et 80 ans ?","back":"**Plus de 60 %** après 70 ans ; **70 %** après 80 ans.","prio":"P2","sec":"s1"},{"id":"fc-224-275672","poly":"cardio","fiche":"224","front":"HTA : quelle répartition essentielle / secondaire ?","back":"**90 %** essentielle ; **10 %** secondaire.","prio":"P1","sec":"s1"},{"id":"fc-224-04ffc1","poly":"cardio","fiche":"224","front":"Dépistage de l'HTA (ESC 2024) : à quel rythme mesurer la PA ?","back":"Au moins **tous les 3 ans avant 40 ans** ; au moins **1 fois/an à partir de 40 ans**.","prio":"P1","sec":"s1"},{"id":"fc-224-9aa5c1","poly":"cardio","fiche":"224","front":"HTA en France : quel rang comme facteur de risque CV de mortalité ?","back":"**1er FDR CV** de mortalité ; 1re maladie chronique ; 2e facteur d'années de vie perdues en bonne santé.","prio":"P3","sec":"s1"},{"id":"fc-224-c211cd","poly":"cardio","fiche":"224","front":"Hypertendu vs normotendu : quel surrisque d'AVC ?","back":"**× 7** (mortalité CV globale doublée).","prio":"P2","sec":"s1"},{"id":"fc-224-48ea76","poly":"cardio","fiche":"224","front":"Hypertendu vs normotendu : surrisques d'IC, d'insuffisance coronarienne et d'AOMI ?","back":"IC **× 4** ; insuffisance coronarienne **× 3** ; AOMI **× 2**.","prio":"P2","sec":"s1"},{"id":"fc-224-ac6de4","poly":"cardio","fiche":"224","front":"HTA : quelles autres complications sont plus fréquentes que chez le normotendu (hors AVC, IC, coronaires, AOMI) ?","back":"**FA**, **IRC terminale**, **démence vasculaire**.","prio":"P3","sec":"s1"},{"id":"fc-224-5c63ef","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : la réversibilité du risque est-elle meilleure pour les AVC ou les coronaires ?","back":"Bien meilleure pour les **AVC** que pour les accidents coronariens.","prio":"P3","sec":"s1"},{"id":"fc-224-af9831","poly":"cardio","fiche":"224","front":"Méta-analyse 2015 : baisser la PAS de 10 et la PAD de 5-6 mmHg pendant 5 ans réduit le risque d'AVC de combien ?","back":"D'**un tiers** (coronaires : 1/6 ; IC : 46 %).","prio":"P3","sec":"s1"},{"id":"fc-224-65c90a","poly":"cardio","fiche":"224","front":"Régulation de la PA à court terme : quel système ?","back":"Le système **sympathique** (baroréflexe carotidien et aortique, centre vasopresseur, médullosurrénales).","prio":"P3","sec":"s2"},{"id":"fc-224-9c9223","poly":"cardio","fiche":"224","front":"Régulation de la PA à moyen terme : quels systèmes ?","back":"**SRAA** et **peptides natriurétiques** (ANP, BNP).","prio":"P3","sec":"s2"},{"id":"fc-224-0eb90a","poly":"cardio","fiche":"224","front":"Régulation de la PA à long terme : quels mécanismes ?","back":"**Natriurèse de pression** et système **arginine-vasopressine**.","prio":"P3","sec":"s2"},{"id":"fc-224-48ebcc","poly":"cardio","fiche":"224","front":"HTA essentielle : quels facteurs environnementaux alimentaires ?","back":"Alimentation **riche en sodium** et **pauvre en potassium** (fruits, légumes) ; + surpoids, alcool, sédentarité.","prio":"P2","sec":"s2"},{"id":"fc-224-4f44f6","poly":"cardio","fiche":"224","front":"HTA essentielle : quelle part est familiale et quel profil ?","back":"**15 %** ; début souvent **avant 30 ans**, même profil chez un ou les deux parents.","prio":"P3","sec":"s2"},{"id":"fc-224-ad7957","poly":"cardio","fiche":"224","front":"HTA familiale précoce : faut-il un test génétique ?","back":"**Non** : composante **polygénique** ; formes monogéniques très rares.","prio":"P2","sec":"s2"},{"id":"fc-224-0a1fb1","poly":"cardio","fiche":"224","front":"HTA essentielle : quelles 4 anomalies l'entretiennent ?","back":"Vaisseaux de résistance **hyperréactifs** ; artérioles **remodelées** ; aorte **rigide** ; **rétention hydrosodée**.","prio":"P3","sec":"s2"},{"id":"fc-224-c12e35","poly":"cardio","fiche":"224","front":"HTA secondaire : quel est l'intérêt d'en identifier la cause ?","back":"Un **traitement ciblé** peut nettement améliorer le contrôle, voire **guérir** l'HTA.","prio":"P3","sec":"s2"},{"id":"fc-224-4cf9ef","poly":"cardio","fiche":"224","front":"HTA : comment est-elle le plus souvent découverte ?","back":"Elle est le plus souvent **totalement latente** : découverte lors d'un examen systématique (d'où le dépistage régulier).","prio":"P2","sec":"s3"},{"id":"fc-224-0f6b79","poly":"cardio","fiche":"224","front":"HTA : quelles céphalées typiques peut-elle donner ?","back":"Céphalées **occipitales matinales**, un peu battantes, résistant aux antalgiques, cédant au lever ou dans la matinée.","prio":"P3","sec":"s3"},{"id":"fc-224-064fc0","poly":"cardio","fiche":"224","front":"Symptômes non spécifiques de l'HTA (céphalées, phosphènes, épistaxis) : justifient-ils un traitement immédiat ?","back":"**Non** : ils n'affirment pas l'HTA et ne justifient pas à eux seuls un antihypertenseur immédiat.","prio":"P2","sec":"s3"},{"id":"fc-224-408876","poly":"cardio","fiche":"224","front":"PA ≥ 140/90 mmHg au cabinet : que conclut-on ?","back":"**Suspicion** d'HTA, à **confirmer hors cabinet** avant de traiter (sauf urgence hypertensive).","prio":"P1","sec":"s3"},{"id":"fc-224-3776db","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quel appareil, et quand garder le stéthoscope ?","back":"Appareil **électronique validé** au bras ; stéthoscope plus en 1re intention, **sauf en fibrillation atriale**.","prio":"P2","sec":"s3"},{"id":"fc-224-dbd0b4","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : combien de temps de repos préalable ?","back":"Assis au calme **plus de 5 min** ; plus de **30 min** après effort, café ou cigarette ; vessie vide.","prio":"P1","sec":"s3"},{"id":"fc-224-dece75","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : combien de mesures et laquelle retenir ?","back":"**Au moins 3** mesures à 1-2 min ; **moyenne des 2 dernières**.","prio":"P1","sec":"s3"},{"id":"fc-224-954fda","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quand faire des mesures supplémentaires ?","back":"Si les **2 premières PAS** diffèrent de plus de **10 mmHg**.","prio":"P3","sec":"s3"},{"id":"fc-224-9db537","poly":"cardio","fiche":"224","front":"1re consultation pour HTA : pourquoi mesurer la PA aux deux bras ?","back":"Une asymétrie fait suspecter une **sténose de l'artère subclavière** ; le bras le plus haut = bras de référence.","prio":"P2","sec":"s3"},{"id":"fc-224-6ee31f","poly":"cardio","fiche":"224","front":"Hypotension orthostatique : quelle définition ?","back":"Baisse de PAS **≥ 20 mmHg** et/ou de PAD **≥ 10 mmHg** debout à **1 et 3 min**.","prio":"P1","sec":"s3"},{"id":"fc-224-97e8ae","poly":"cardio","fiche":"224","front":"Mesure de la PA : combien de temps prendre la FC de repos au pouls ?","back":"Au moins **30 s**, à la recherche d'une arythmie.","prio":"P3","sec":"s3"},{"id":"fc-224-fb9952","poly":"cardio","fiche":"224","front":"Artères calcifiées incompressibles : de combien le brassard surestime-t-il la PA ?","back":"D'environ **20 mmHg** (parfois 40 à 50).","prio":"P3","sec":"s3"},{"id":"fc-224-ac2460","poly":"cardio","fiche":"224","front":"Manœuvre d'Osler : que montre-t-elle ?","back":"Pouls radial encore perçu brassard gonflé au-dessus de la PAS = **artère calcifiée incompressible**.","prio":"P3","sec":"s3"},{"id":"fc-224-e2d705","poly":"cardio","fiche":"224","front":"Pression pulsée : quel seuil marque une rigidité artérielle ?","back":"PAS − PAD **> 65 mmHg**.","prio":"P3","sec":"s3"},{"id":"fc-224-8b989c","poly":"cardio","fiche":"224","front":"Mesure de la PA au cabinet : quel brassard et à quelle hauteur ?","back":"**Brassard adapté** au bras (3 tailles : obèse, standard, enfant), **à hauteur du cœur**.","prio":"P2","sec":"s3"},{"id":"fc-224-259259","poly":"cardio","fiche":"224","front":"HTA : quel examen hors cabinet est recommandé en France pour la confirmer ?","back":"L'**automesure (AMT)** ; MAPA à défaut.","prio":"P1","sec":"s4"},{"id":"fc-224-35a46e","poly":"cardio","fiche":"224","front":"HTA suspectée : que faut-il faire avant tout antihypertenseur (hors urgence) ?","back":"**Confirmer l'HTA hors cabinet** (AMT de préférence, sinon MAPA).","prio":"P1","sec":"s4"},{"id":"fc-224-484869","poly":"cardio","fiche":"224","front":"Automesure : quel appareil utiliser ?","back":"Appareil **validé, semi-automatique**, à **brassard huméral** (le poignet expose à plus d'erreurs).","prio":"P2","sec":"s4"},{"id":"fc-224-2cdb58","poly":"cardio","fiche":"224","front":"Automesure : en quoi consiste la « règle des 3 » ?","back":"**3 jours** de suite ; **3 mesures** le matin et **3** le soir ; soit **18 mesures**.","prio":"P1","sec":"s4"},{"id":"fc-224-58af79","poly":"cardio","fiche":"224","front":"Automesure : à quels moments mesurer ?","back":"**Matin** 20 min après le lever, avant petit-déjeuner et médicaments ; **soir** dans l'heure avant le coucher.","prio":"P2","sec":"s4"},{"id":"fc-224-e69848","poly":"cardio","fiche":"224","front":"MAPA : quand la préférer à l'automesure pour confirmer l'HTA ?","back":"Quand l'AMT est **impossible ou peu fiable** (manipulation, report des valeurs, anxiété).","prio":"P2","sec":"s4"},{"id":"fc-224-a5fb4a","poly":"cardio","fiche":"224","front":"MAPA : quelle fréquence de mesure le jour et la nuit ?","back":"Toutes les **15-30 min le jour**, **30-60 min la nuit**, sur 24 h avec journal.","prio":"P3","sec":"s4"},{"id":"fc-224-f5c7d6","poly":"cardio","fiche":"224","front":"MAPA : quelle PA prédit le mieux le risque CV ?","back":"La **PA nocturne** (plus que la diurne).","prio":"P2","sec":"s4"},{"id":"fc-224-24b6bc","poly":"cardio","fiche":"224","front":"MAPA : quelles autres indications que la confirmation de l'HTA ?","back":"Confirmer une **HTA résistante** ; hypotensions symptomatiques ; forte variabilité ; explorer la **PA nocturne**.","prio":"P2","sec":"s4"},{"id":"fc-224-c29e5b","poly":"cardio","fiche":"224","front":"HTA de grade 2 à la 1re consultation : dans quel délai faire la mesure hors cabinet ?","back":"**Dans le mois**.","prio":"P1","sec":"s4"},{"id":"fc-224-44065a","poly":"cardio","fiche":"224","front":"HTA de grade 3 sans urgence : dans quel délai faire la mesure hors cabinet ?","back":"**Dans la semaine**.","prio":"P1","sec":"s4"},{"id":"fc-224-9ff965","poly":"cardio","fiche":"224","front":"HTA « blouse blanche » : quelle définition ?","back":"PA de cabinet **> 140/90 mmHg** mais mesures ambulatoires **ne confirmant pas** l'HTA.","prio":"P1","sec":"s4"},{"id":"fc-224-1322af","poly":"cardio","fiche":"224","front":"HTA blouse blanche : quelle conduite ?","back":"**Pas de médicament** ; MHD ; surveillance régulière hors cabinet (risque d'HTA confirmée plus tard).","prio":"P1","sec":"s4"},{"id":"fc-224-ad0e63","poly":"cardio","fiche":"224","front":"HTA masquée : quelle définition ?","back":"PA de cabinet **< 140/90 mmHg** mais **HTA en ambulatoire** (ex. AMT > 135/85).","prio":"P1","sec":"s4"},{"id":"fc-224-fc58f0","poly":"cardio","fiche":"224","front":"HTA masquée : quel risque et quelle prise en charge ?","back":"**Même risque** CV que l'HTA habituelle → **même prise en charge**, guidée par les mesures hors cabinet.","prio":"P1","sec":"s4"},{"id":"fc-224-2faef2","poly":"cardio","fiche":"224","front":"HTA blouse blanche et HTA masquée : quelles fréquences chez l'adulte ?","back":"Blouse blanche **15-20 %** ; masquée **10-15 %**.","prio":"P3","sec":"s4"},{"id":"fc-224-029753","poly":"cardio","fiche":"224","front":"HTA confirmée : quels sont les 5 objectifs de l'évaluation initiale ?","back":"**Niveau de PA** ; **risque CV global** ; **organes cibles** ; **facteurs aggravants** ; arguments pour une **HTA secondaire**.","prio":"P1","sec":"s5"},{"id":"fc-224-a8610a","poly":"cardio","fiche":"224","front":"HTA : quel signe d'examen clinique rechercher sur le poids et la silhouette ?","back":"Une **obésité viscérale** : poids, IMC, **tour de taille** debout.","prio":"P3","sec":"s5"},{"id":"fc-224-9a35b0","poly":"cardio","fiche":"224","front":"HTA : quels antécédents obstétricaux rechercher à l'interrogatoire ?","back":"HTA ou diabète **gravidique**, **prééclampsie**, prématurité, fausses couches répétées, mort fœtale in utero.","prio":"P3","sec":"s5"},{"id":"fc-224-d6e0ea","poly":"cardio","fiche":"224","front":"HTA : quel facteur aggravant évoquent des ronflements et des pauses respiratoires nocturnes ?","back":"Un **SAOS**.","prio":"P2","sec":"s5"},{"id":"fc-224-042dea","poly":"cardio","fiche":"224","front":"HTA : quel est le bilan biologique systématique ?","back":"Glycémie à jeun + **HbA1c** ; bilan lipidique ; natrémie, **kaliémie** ; Hb ; **créatininémie** + DFG ; rapport **protéinurie/créatininurie**.","prio":"P1","sec":"s5"},{"id":"fc-224-69cca4","poly":"cardio","fiche":"224","front":"HTA : quel examen non biologique est systématique dans le bilan initial ?","back":"**ECG de repos** (HVG, séquelle d'infarctus, repolarisation, FA).","prio":"P1","sec":"s5"},{"id":"fc-224-01e146","poly":"cardio","fiche":"224","front":"HTA : que cherche le dosage systématique de la kaliémie ?","back":"Une **hypokaliémie**, argument pour une **HTA secondaire**.","prio":"P2","sec":"s5"},{"id":"fc-224-6d99eb","poly":"cardio","fiche":"224","front":"HTA : quand faire une échocardiographie ?","back":"Si **ECG anormal** ou **symptômes cardiaques** ; **pas** chez l'asymptomatique à ECG normal.","prio":"P1","sec":"s5"},{"id":"fc-224-020816","poly":"cardio","fiche":"224","front":"HTA : quand faire un IPS ou un échodoppler (TSA, membres inférieurs) ?","back":"Si **souffle** ou **symptômes d'AOMI** ; pas chez l'asymptomatique.","prio":"P2","sec":"s5"},{"id":"fc-224-fe672d","poly":"cardio","fiche":"224","front":"HTA : quand le fond d'œil est-il recommandé ?","back":"**Recommandé dans le grade 3** ; grade 2-3 avec suspicion d'**HTA maligne**.","prio":"P2","sec":"s5"},{"id":"fc-224-c2dac0","poly":"cardio","fiche":"224","front":"HTA chez une femme : quel dosage faire si une grossesse est possible ?","back":"**β-hCG** (certains antihypertenseurs sont contre-indiqués).","prio":"P1","sec":"s5"},{"id":"fc-224-89117c","poly":"cardio","fiche":"224","front":"HVG à l'ECG : quels indices, et quelle est la sensibilité de l'ECG ?","back":"Indices de **Sokolow, Cornell, Lewis** ; ECG **peu sensible** (signes = HVG marquée).","prio":"P2","sec":"s5"},{"id":"fc-224-3b112c","poly":"cardio","fiche":"224","front":"Échocardiographie : quels seuils de masse VG définissent l'HVG ?","back":"**> 115 g/m²** chez l'homme ; **> 95 g/m²** chez la femme.","prio":"P3","sec":"s5"},{"id":"fc-224-04bf21","poly":"cardio","fiche":"224","front":"Atteinte rénale de l'HTA : quel seuil de DFG définit l'insuffisance rénale ?","back":"DFG **< 60 ml/min/1,73 m²**.","prio":"P2","sec":"s5"},{"id":"fc-224-2aa53d","poly":"cardio","fiche":"224","front":"Rapport protéinurie/créatininurie : quels seuils (pathologique, protéinurie) ?","back":"Pathologique dès **> 30 mg/g** ; protéinurie si **> 300 mg/g**.","prio":"P3","sec":"s5"},{"id":"fc-224-b7b792","poly":"cardio","fiche":"224","front":"HTA : chez qui la microalbuminurie est-elle systématique ?","back":"**Seulement chez le diabétique**.","prio":"P2","sec":"s5"},{"id":"fc-224-49eef5","poly":"cardio","fiche":"224","front":"Fond d'œil dans l'HTA : que définissent les stades 3 et 4 ?","back":"Stade 3 : **hémorragies, exsudats** ; stade 4 : **œdème papillaire** (PA non contrôlée + stade 4 = HTA maligne).","prio":"P1","sec":"s5"},{"id":"fc-224-e9b977","poly":"cardio","fiche":"224","front":"HTA et FA : quelle place de l'HTA ?","back":"**1re cause** de FA : **70 %** des patients en FA sont hypertendus.","prio":"P2","sec":"s5"},{"id":"fc-224-f744e4","poly":"cardio","fiche":"224","front":"HTA : par combien multiplie-t-elle le risque de mort subite ?","back":"**× 3**.","prio":"P3","sec":"s5"},{"id":"fc-224-acbe96","poly":"cardio","fiche":"224","front":"AVC de l'hypertendu : quelle part ischémique / hémorragique ?","back":"**80 %** ischémiques (dont AIT) ; **20 %** hémorragies cérébrales.","prio":"P2","sec":"s5"},{"id":"fc-224-b318ec","poly":"cardio","fiche":"224","front":"HTA : quelle atteinte rénale chronique typique ?","back":"La **néphroangiosclérose** (microalbuminurie précoce puis insuffisance rénale qui aggrave l'HTA).","prio":"P2","sec":"s5"},{"id":"fc-224-6b30c3","poly":"cardio","fiche":"224","front":"HTA : quelles causes d'IRA iatrogène ?","back":"**Diurétique** (déshydratation extracellulaire) ; **bloqueur du SRA** sur sténose bilatérale des artères rénales ou sur rein unique.","prio":"P1","sec":"s5"},{"id":"fc-224-1257fd","poly":"cardio","fiche":"224","front":"HTA : par combien la mortalité CV est-elle multipliée selon le sexe ?","back":"**× 5** chez l'homme ; **× 3** chez la femme.","prio":"P3","sec":"s5"},{"id":"fc-224-d6d6e0","poly":"cardio","fiche":"224","front":"HVG de l'HTA : quel mécanisme peut donner un angor sans athérome ?","back":"La baisse de la **réserve coronarienne** due à l'HVG.","prio":"P3","sec":"s5"},{"id":"fc-224-b95cb7","poly":"cardio","fiche":"224","front":"Hypertendu à risque CV élevé d'emblée : quelles situations ?","back":"Antécédent coronarien, **AVC/AIT**, **AOMI**, IC, IR modérée/sévère, atteinte d'organe cible **cardiaque ou vasculaire**, **hypercholestérolémie familiale**.","prio":"P2","sec":"s5"},{"id":"fc-224-940249","poly":"cardio","fiche":"224","front":"Hypertendu diabétique de 40 à 69 ans : quel score de risque CV ?","back":"**SCORE2-Diabetes**.","prio":"P2","sec":"s5"},{"id":"fc-224-5760d4","poly":"cardio","fiche":"224","front":"Hypertendu sans haut risque d'emblée ni diabète : quels scores de risque CV ?","back":"**SCORE2** ou **SCORE2-OP** (risque à 10 ans).","prio":"P2","sec":"s5"},{"id":"fc-224-6413e8","poly":"cardio","fiche":"224","front":"HTA : quand demander un avis spécialisé d'emblée ?","back":"Grade **3** ; HTA **avant 40 ans** (si obèse : dépister d'abord un SAOS) ; HTA **résistante** ; contexte d'HTA secondaire.","prio":"P1","sec":"s5"},{"id":"fc-224-412263","poly":"cardio","fiche":"224","front":"HTA : quel mécanisme d'insuffisance cardiaque à FEVG préservée ?","back":"**Trouble du remplissage** lié à l'**HVG** et à la fibrose, sur cœur hypertrophié **non dilaté**.","prio":"P3","sec":"s5"},{"id":"fc-224-de1029","poly":"cardio","fiche":"224","front":"HTA : quelles causes d'insuffisance cardiaque à FEVG altérée ?","back":"**Ischémique**, ou **postcharge élevée** (HTA sévère) sur cœur dilaté et hypertrophié (**HVG excentrique**).","prio":"P3","sec":"s5"},{"id":"fc-224-6e8227","poly":"cardio","fiche":"224","front":"HTA secondaire : dans quelles situations la dépister ?","back":"PA **> 180/110**, surtout brutale ; HTA **résistante** ; âge **≤ 40 ans** ; **hypokaliémie** ; tout point d'appel.","prio":"P1","sec":"s6"},{"id":"fc-224-cb4911","poly":"cardio","fiche":"224","front":"HTA + souffle précordial + pouls fémoraux faibles : quelle cause évoquer ?","back":"Une **coarctation aortique**.","prio":"P1","sec":"s6"},{"id":"fc-224-1e4062","poly":"cardio","fiche":"224","front":"HTA + crises de céphalées, sueurs, palpitations : quelle cause évoquer ?","back":"Un **phéochromocytome** (**triade de Ménard**).","prio":"P1","sec":"s6"},{"id":"fc-224-938657","poly":"cardio","fiche":"224","front":"HTA + crampes, asthénie, tétanie, constipation : quelle cause évoquer ?","back":"**Hypokaliémie** → **hyperaldostéronisme**.","prio":"P1","sec":"s6"},{"id":"fc-224-bbc68e","poly":"cardio","fiche":"224","front":"HTA + souffle aortique abdominal : quelle cause évoquer ?","back":"Une **HTA rénovasculaire**.","prio":"P2","sec":"s6"},{"id":"fc-224-0ea316","poly":"cardio","fiche":"224","front":"HTA + gros reins palpables : quelle cause évoquer ?","back":"Une **polykystose rénale**.","prio":"P2","sec":"s6"},{"id":"fc-224-7cc7e8","poly":"cardio","fiche":"224","front":"HTA + vergetures pourpres, amyotrophie proximale, bosse de bison : quelle cause ?","back":"Un **hypercortisolisme** (Cushing).","prio":"P2","sec":"s6"},{"id":"fc-224-01f8ba","poly":"cardio","fiche":"224","front":"HTA médicamenteuse : citer des médicaments en cause.","back":"**Contraceptifs oraux**, vasoconstricteurs nasaux, **corticoïdes**, **AINS**, EPO, ciclosporine, tacrolimus, anti-VEGF, ITK, ergot de seigle.","prio":"P1","sec":"s6"},{"id":"fc-224-f5dcb6","poly":"cardio","fiche":"224","front":"HTA toxique : citer les toxiques en cause.","back":"**Réglisse** (boissons anisées, bonbons, tisanes), cannabis, **cocaïne**, amphétamines, **alcool**.","prio":"P2","sec":"s6"},{"id":"fc-224-372dd4","poly":"cardio","fiche":"224","front":"HTA rénale : quelles sont les causes rénales les plus fréquentes ?","back":"**Glomérulopathies chroniques** et **polykystose**.","prio":"P2","sec":"s6"},{"id":"fc-224-742d59","poly":"cardio","fiche":"224","front":"Sténose athéromateuse de l'artère rénale : quel siège typique ?","back":"**Ostium et tiers proximal** ; cause rénovasculaire la plus fréquente.","prio":"P2","sec":"s6"},{"id":"fc-224-8da210","poly":"cardio","fiche":"224","front":"Dysplasie fibromusculaire des artères rénales : quel terrain et quel siège ?","back":"**Femme jeune** ; **deux tiers distaux** de l'artère.","prio":"P2","sec":"s6"},{"id":"fc-224-02f828","poly":"cardio","fiche":"224","front":"Phéochromocytome : dans quelle proportion donne-t-il une HTA ?","back":"**70 %** des cas (tumeur rare, souvent bénigne, de la médullosurrénale).","prio":"P3","sec":"s6"},{"id":"fc-224-dfd242","poly":"cardio","fiche":"224","front":"Phéochromocytome : quelles formes familiales ?","back":"**NEM2**, **von Hippel-Lindau**, **neurofibromatose 1**, paragangliomes familiaux.","prio":"P3","sec":"s6"},{"id":"fc-224-54b64e","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quelles causes et leurs fréquences ?","back":"**Hyperplasie bilatérale (70 %)** ; **adénome surrénalien (30 %)** ; rarement corticosurrénalome malin.","prio":"P2","sec":"s6"},{"id":"fc-224-77b3fc","poly":"cardio","fiche":"224","front":"Coarctation aortique : quel mécanisme et quel siège ?","back":"Fermeture anormale du canal artériel → sténose de l'**isthme aortique** ; enfant et adulte jeune.","prio":"P2","sec":"s6"},{"id":"fc-224-bd7dc3","poly":"cardio","fiche":"224","front":"HTA et SAOS : chez qui évoquer un SAOS ?","back":"**Obèse**, surtout si HTA **résistante** ; profil **« non dipper »** en MAPA.","prio":"P2","sec":"s6"},{"id":"fc-224-d4c76a","poly":"cardio","fiche":"224","front":"Profil « non dipper » en MAPA : de quoi s'agit-il ?","back":"**Absence de baisse nocturne** de la PA.","prio":"P2","sec":"s6"},{"id":"fc-224-df99f2","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles substances interfèrent avec leur action ou métabolisme ?","back":"**AINS**, antirétroviraux, inhibiteurs du CYP17A1 (**jus de pamplemousse**, macrolides, antifongiques azolés).","prio":"P2","sec":"s6"},{"id":"fc-224-e1696f","poly":"cardio","fiche":"224","front":"Sténose de l'artère rénale : quel profil rénine-aldostérone ?","back":"Hyperaldostéronisme **secondaire** : rénine **et** aldostérone **élevées**.","prio":"P2","sec":"s6"},{"id":"fc-224-90de66","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quel profil biologique ?","back":"Aldostérone **haute**, **rénine basse**, rapport aldostérone/rénine très élevé.","prio":"P2","sec":"s6"},{"id":"fc-224-82daa4","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : une kaliémie normale l'exclut-elle ?","back":"**Non** : hypokaliémie (< 3,7 mmol/L) **inconstante**.","prio":"P2","sec":"s6"},{"id":"fc-224-513ec8","poly":"cardio","fiche":"224","front":"Sténose de l'artère rénale : quels signes l'évoquent ?","back":"Souffle abdominal latéralisé ; **OAP récidivant** sans cause cardiaque ; IR parfois révélée par un IEC/ARA2 ; petit rein homolatéral.","prio":"P3","sec":"s6"},{"id":"fc-224-d43392","poly":"cardio","fiche":"224","front":"Phéochromocytome : quel dosage pour le diagnostic ?","back":"**Dérivés méthoxylés** (métanéphrines, normétanéphrines) urinaires et/ou plasmatiques.","prio":"P2","sec":"s6"},{"id":"fc-224-1ae797","poly":"cardio","fiche":"224","front":"Phéochromocytome : quels examens de localisation ?","back":"**Scanner** + **scintigraphie à la MIBG** (tumeur parfois extrasurrénalienne).","prio":"P3","sec":"s6"},{"id":"fc-224-cb79a7","poly":"cardio","fiche":"224","front":"Coarctation aortique : quels signes cliniques ?","back":"Souffle mésosystolique parasternal gauche et dorsal ; **pouls fémoraux absents** ; HTA aux bras, PA basse aux jambes.","prio":"P3","sec":"s6"},{"id":"fc-224-7f856e","poly":"cardio","fiche":"224","front":"Rénine et aldostérone : dans quelles conditions de prélèvement ?","back":"**Matin, 2 h après le lever**, **normokaliémie**, apports sodés larges, après arrêt des médicaments interférents.","prio":"P3","sec":"s6"},{"id":"fc-224-dbf604","poly":"cardio","fiche":"224","front":"Dosage rénine-aldostérone : quels délais d'arrêt des médicaments ?","back":"**ARM : 6 semaines** ; **IEC, ARA2, diurétiques, bêtabloquants : 2 semaines**.","prio":"P3","sec":"s6"},{"id":"fc-224-6127e0","poly":"cardio","fiche":"224","front":"SAOS suspecté chez un hypertendu : quel examen ?","back":"**Polygraphie ventilatoire** (ou polysomnographie) nocturne.","prio":"P3","sec":"s6"},{"id":"fc-224-8a88ab","poly":"cardio","fiche":"224","front":"HTA endocrinienne : quelles endocrinopathies citer en dehors du phéochromocytome et du Conn ?","back":"**Cushing**, **acromégalie**, **hyperthyroïdie**.","prio":"P3","sec":"s6"},{"id":"fc-224-d71b32","poly":"cardio","fiche":"224","front":"Crise hypertensive : quelle définition et quelle gravité ?","back":"HTA de **grade 3 sans souffrance viscérale** ; **pas une urgence**.","prio":"P1","sec":"s7"},{"id":"fc-224-01cab9","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quelle définition ?","back":"HTA (souvent **> 180/110**) + **atteinte aiguë d'un organe cible** ; pronostic vital engagé.","prio":"P1","sec":"s7"},{"id":"fc-224-bda761","poly":"cardio","fiche":"224","front":"HTA maligne : quelle définition ?","back":"PA élevée (pas de seuil) + **œdème papillaire** au fond d'œil (**stade 4**).","prio":"P1","sec":"s7"},{"id":"fc-224-b1885f","poly":"cardio","fiche":"224","front":"HTA maligne : quelles atteintes aiguës peuvent s'associer ?","back":"**IRA**, IVG/ischémie, **PRES**/encéphalopathie, **microangiopathie thrombotique** (hémolyse mécanique, thrombopénie).","prio":"P2","sec":"s7"},{"id":"fc-224-308293","poly":"cardio","fiche":"224","front":"HTA maligne non traitée : quelle évolution ?","back":"**Insuffisance rénale sévère, irréversible et mortelle en quelques mois**.","prio":"P2","sec":"s7"},{"id":"fc-224-b9f281","poly":"cardio","fiche":"224","front":"Urgences hypertensives : citer les principales.","back":"HTA + **SCA** ; **OAP** ; **dissection aortique** ; encéphalopathie ; **PRES** ; AVC/hémorragie méningée ; phéochromocytome ; toxiques ; **prééclampsie sévère** ; HTA maligne.","prio":"P1","sec":"s7"},{"id":"fc-224-1ec227","poly":"cardio","fiche":"224","front":"PRES : quels signes l'évoquent dans une urgence hypertensive ?","back":"**Cécité centrale** et **lésions occipitales**.","prio":"P3","sec":"s7"},{"id":"fc-224-4d16b3","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quel bilan cherche une microangiopathie thrombotique ?","back":"NFS, **schizocytes**, bilirubine libre, **haptoglobine**, **LDH**.","prio":"P2","sec":"s7"},{"id":"fc-224-6491d4","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quand faire un scanner cérébral ?","back":"Si suspicion d'**hémorragie** ou d'**AVC**.","prio":"P2","sec":"s7"},{"id":"fc-224-e572eb","poly":"cardio","fiche":"224","front":"Consultation d'annonce de l'HTA : quel en est l'aboutissement ?","back":"Un **plan de soins** et une **décision médicale partagée** (objectifs, dont la cible de PA).","prio":"P2","sec":"s8"},{"id":"fc-224-7798c3","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : de combien réduit-il le risque d'AVC ?","back":"De **20-30 %** (SCA et IC : 10-20 %).","prio":"P2","sec":"s8"},{"id":"fc-224-5e6fb3","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : existe-t-il une limite d'âge ?","back":"**Aucune limite d'âge**.","prio":"P1","sec":"s8"},{"id":"fc-224-e4b5a2","poly":"cardio","fiche":"224","front":"Traitement de l'HTA : quels sont les 4 piliers ?","back":"**MHD** ; traitement des **FDR** associés ; **médicaments** ; **éducation thérapeutique**.","prio":"P2","sec":"s8"},{"id":"fc-224-73a493","poly":"cardio","fiche":"224","front":"Stratégie antihypertensive : de quoi dépend-elle ?","back":"Du **niveau de PA**, du **risque CV** et de l'**atteinte des organes cibles**.","prio":"P1","sec":"s8"},{"id":"fc-224-712a4b","poly":"cardio","fiche":"224","front":"PAS de consultation 130-139 mmHg sans risque CV élevé : quelle conduite ?","back":"**MHD** sans médicament ; surveillance de la PA ; réévaluation annuelle du risque.","prio":"P2","sec":"s8"},{"id":"fc-224-c79a1e","poly":"cardio","fiche":"224","front":"PAS 130-139 mmHg avec risque CV élevé : quand ajouter un médicament ?","back":"Après **3 mois** de MHD si cible non atteinte : **monothérapie** si PA ≥ 130/80.","prio":"P2","sec":"s8"},{"id":"fc-224-a2c1a5","poly":"cardio","fiche":"224","front":"HTA confirmée : quand débuter un médicament ?","back":"**D'emblée, chez tous**, en même temps que les MHD.","prio":"P1","sec":"s8"},{"id":"fc-224-0a3cbe","poly":"cardio","fiche":"224","front":"HTA : en combien de temps viser la cible tensionnelle ?","back":"Idéalement en **3 mois**, avec suivi fréquent (mensuel si besoin).","prio":"P1","sec":"s8"},{"id":"fc-224-661d5f","poly":"cardio","fiche":"224","front":"HTA : quelle est la cible tensionnelle générale (ESC 2024) ?","back":"PAS **120-129** et PAD **70-79 mmHg**, si possible **120/70**.","prio":"P1","sec":"s8"},{"id":"fc-224-394536","poly":"cardio","fiche":"224","front":"Cible tensionnelle inatteignable ou mal tolérée : quel objectif ?","back":"PA **la plus basse possible** et **< 140/90 mmHg**.","prio":"P2","sec":"s8"},{"id":"fc-224-e328b9","poly":"cardio","fiche":"224","front":"Cible tensionnelle : quand l'adapter d'emblée ?","back":"**Hypotension orthostatique**, **fragilité**, âge **> 85 ans**, espérance de vie limitée.","prio":"P2","sec":"s8"},{"id":"fc-224-0ebc74","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quel apport de sel viser ?","back":"**5-6 g/j** (natriurèse ≈ **100 mmol/j**), **sans régime sans sel strict**.","prio":"P1","sec":"s8"},{"id":"fc-224-ee101e","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quelle limite pour l'alcool ?","back":"**< 10 unités/semaine**.","prio":"P1","sec":"s8"},{"id":"fc-224-28278c","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quels objectifs de poids et de tour de taille ?","back":"IMC **20-25 kg/m²** ; tour de taille **< 94 cm (H)**, **< 80 cm (F)**.","prio":"P2","sec":"s8"},{"id":"fc-224-cb0a78","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quand ne pas majorer les apports en potassium ?","back":"En cas de **maladie rénale chronique avancée**.","prio":"P2","sec":"s8"},{"id":"fc-224-a4fe34","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : faut-il limiter le café ?","back":"**Non** ; boissons associant taurine et caféine déconseillées.","prio":"P2","sec":"s8"},{"id":"fc-224-c34ef1","poly":"cardio","fiche":"224","front":"Régime sans sel strict dans l'HTA : pourquoi l'éviter ?","back":"Inutile et dangereux : **déshydratation, hypovolémie**, atteinte rénale, surtout sous IEC/ARA2.","prio":"P2","sec":"s8"},{"id":"fc-224-a83ac3","poly":"cardio","fiche":"224","front":"MHD bien suivies : de combien baissent-elles la PAS ?","back":"De **5 à 10 mmHg**.","prio":"P2","sec":"s8"},{"id":"fc-224-96af02","poly":"cardio","fiche":"224","front":"Équivalence sel : 1 g de NaCl correspond à combien de sodium ?","back":"**17 mmol** de sodium.","prio":"P3","sec":"s8"},{"id":"fc-224-ad6d62","poly":"cardio","fiche":"224","front":"PAS de consultation 120-129 mmHg : quel traitement ?","back":"**MHD** seules, **sans médicament**.","prio":"P2","sec":"s8"},{"id":"fc-224-636781","poly":"cardio","fiche":"224","front":"MHD dans l'HTA : quelle activité physique conseiller ?","back":"**Aérobie** (endurance) + **résistance** dynamique et/ou isométrique, régulière et adaptée ; lutter contre la **sédentarité**.","prio":"P3","sec":"s8"},{"id":"fc-224-3a7f9a","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles sont les 5 classes qui réduisent la morbi-mortalité CV ?","back":"**Inhibiteurs calciques**, **IEC**, **ARA2**, **bêtabloquants**, **thiazidiques** (ou apparentés).","prio":"P1","sec":"s9"},{"id":"fc-224-2a66a5","poly":"cardio","fiche":"224","front":"HTA confirmée non compliquée : par quel schéma débuter ?","back":"**Bithérapie** à **faible dose**, **association fixe** (1 comprimé), **1 prise/j**.","prio":"P1","sec":"s9"},{"id":"fc-224-801f3e","poly":"cardio","fiche":"224","front":"HTA : quelles bithérapies initiales privilégier ?","back":"**IEC ou ARA2 + IC dihydropyridine**, ou **IEC ou ARA2 + thiazidique**.","prio":"P1","sec":"s9"},{"id":"fc-224-367899","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelle association est interdite ?","back":"**IEC + ARA2**.","prio":"P1","sec":"s9"},{"id":"fc-224-a89fba","poly":"cardio","fiche":"224","front":"HTA : quand utiliser un bêtabloquant à l'initiation ?","back":"**Seulement s'il a une autre indication** (moins efficace sur les AVC ; pas de monothérapie par bêtabloquant).","prio":"P1","sec":"s9"},{"id":"fc-224-8a5126","poly":"cardio","fiche":"224","front":"HTA : quels critères justifient une monothérapie initiale ?","back":"PA élevée avec indication de médicament ; **fragilité** modérée/sévère ; **hypotension orthostatique** ; âge **≥ 85 ans**.","prio":"P2","sec":"s9"},{"id":"fc-224-9b0726","poly":"cardio","fiche":"224","front":"Hypertendu post-infarctus ou angineux : quelles classes préférer ?","back":"Post-infarctus : **IEC, ARA2 ou bêtabloquant** ; angor : **IC ou bêtabloquant**.","prio":"P3","sec":"s9"},{"id":"fc-224-8d3bc5","poly":"cardio","fiche":"224","front":"HTA + diabète avec microalbuminurie ou insuffisance rénale : quelle classe préférer ?","back":"**IEC ou ARA2** (iSGLT2 probablement aussi).","prio":"P2","sec":"s9"},{"id":"fc-224-c1c885","poly":"cardio","fiche":"224","front":"IEC : quelles contre-indications absolues ?","back":"**Grossesse** ; **angio-œdème** sous IEC.","prio":"P1","sec":"s9"},{"id":"fc-224-556a39","poly":"cardio","fiche":"224","front":"ARA2 : quelle contre-indication absolue ?","back":"La **grossesse**.","prio":"P1","sec":"s9"},{"id":"fc-224-0096a2","poly":"cardio","fiche":"224","front":"IEC et ARA2 : quelles contre-indications relatives ?","back":"**Hyperkaliémie** ; femme en âge de procréer sans contraception efficace ; **sténose bilatérale** des artères rénales ; IR sévère.","prio":"P2","sec":"s9"},{"id":"fc-224-88d728","poly":"cardio","fiche":"224","front":"Diurétiques thiazidiques : quelles contre-indications ?","back":"**Aucune absolue** ; relatives : **hypercalcémie**, **hypokaliémie**, **goutte**, grossesse.","prio":"P1","sec":"s9"},{"id":"fc-224-7f00ee","poly":"cardio","fiche":"224","front":"Bêtabloquants : quelles contre-indications absolues ?","back":"**Asthme** ; **BAV 2 et 3**.","prio":"P1","sec":"s9"},{"id":"fc-224-74ce9b","poly":"cardio","fiche":"224","front":"Bêtabloquants : quelles contre-indications relatives ?","back":"**Bradycardie** ; **syndrome de Raynaud**.","prio":"P2","sec":"s9"},{"id":"fc-224-221ca3","poly":"cardio","fiche":"224","front":"IC dihydropyridines : quelles contre-indications ?","back":"**Aucune absolue** ; relative : **insuffisance cardiaque non contrôlée**.","prio":"P1","sec":"s9"},{"id":"fc-224-7e9dda","poly":"cardio","fiche":"224","front":"IC non dihydropyridines (bradycardisants) : quelles contre-indications absolues ?","back":"**BAV 2 et 3** ; **IC à fonction systolique altérée**.","prio":"P1","sec":"s9"},{"id":"fc-224-3bbf95","poly":"cardio","fiche":"224","front":"Thiazidiques : quels effets indésirables ?","back":"**Hypokaliémie**, **hyponatrémie**, hyperglycémie, **hyperuricémie**, IR fonctionnelle.","prio":"P1","sec":"s9"},{"id":"fc-224-9e0227","poly":"cardio","fiche":"224","front":"IEC : quel est l'effet indésirable typique (absent sous ARA2) ?","back":"La **toux** (+ hyperkaliémie, IR fonctionnelle, communes aux ARA2).","prio":"P1","sec":"s9"},{"id":"fc-224-92a860","poly":"cardio","fiche":"224","front":"IC dihydropyridines : quels effets indésirables ?","back":"**Œdèmes des membres inférieurs**, céphalées, vertiges, flushs.","prio":"P1","sec":"s9"},{"id":"fc-224-04c2c3","poly":"cardio","fiche":"224","front":"IC non dihydropyridines : quels effets indésirables propres ?","back":"Ceux des dihydropyridines + **bradycardie**, **troubles de conduction**, **constipation**.","prio":"P2","sec":"s9"},{"id":"fc-224-ddd48d","poly":"cardio","fiche":"224","front":"Bêtabloquants : quels effets indésirables ?","back":"**Asthénie**, **bradycardie sinusale**, acrosyndrome, hypoglycémie, baisse de libido, dysfonction érectile, prise de poids.","prio":"P2","sec":"s9"},{"id":"fc-224-5c1d01","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles classes ont la meilleure persistance au long cours ?","back":"**ARA2 et IEC** > IC > thiazidiques et bêtabloquants.","prio":"P3","sec":"s9"},{"id":"fc-224-6f40db","poly":"cardio","fiche":"224","front":"Antihypertenseurs : quelles interactions imposent d'adapter le traitement ?","back":"**Bradycardisants + bêtabloquants** ; **AINS + IEC/ARA2**.","prio":"P3","sec":"s9"},{"id":"fc-224-5f19aa","poly":"cardio","fiche":"224","front":"Éducation thérapeutique dans l'HTA : quel geste apprendre en cas de risque d'hypovolémie ?","back":"**Diminuer ou suspendre transitoirement** diurétiques, IEC et ARA2.","prio":"P2","sec":"s9"},{"id":"fc-224-c188ed","poly":"cardio","fiche":"224","front":"Hypertendu en insuffisance cardiaque à fonction systolique altérée : quelles classes préférer ?","back":"**IEC** (ARA2 si intolérance), **bêtabloquant**, **diurétique** ; probablement iSGLT2 ; ARM aussi.","prio":"P3","sec":"s9"},{"id":"fc-224-6c4413","poly":"cardio","fiche":"224","front":"Sujet âgé hypertendu : sur quoi raisonner pour adapter le traitement ?","back":"Sur la **fragilité** et l'**espérance de vie**, pas sur l'âge seul ; dépister systématiquement l'**hypotension orthostatique**.","prio":"P1","sec":"s10"},{"id":"fc-224-9f32e0","poly":"cardio","fiche":"224","front":"Hypertendu de moins de 85 ans non fragile : faut-il adapter le traitement ?","back":"**Non** : prise en charge **standard**.","prio":"P2","sec":"s10"},{"id":"fc-224-167534","poly":"cardio","fiche":"224","front":"Hypertendu traité qui atteint 85 ans et tolère bien : faut-il baisser le traitement ?","back":"**Non** : pas d'arrêt ni de baisse systématique.","prio":"P2","sec":"s10"},{"id":"fc-224-57e33a","poly":"cardio","fiche":"224","front":"Sujet âgé : quels critères imposent de débuter en monothérapie ?","back":"**Fragilité** modérée/sévère, âge **≥ 85 ans** ou espérance de vie **< 3 ans**.","prio":"P1","sec":"s10"},{"id":"fc-224-4a0747","poly":"cardio","fiche":"224","front":"Sujet âgé hypertendu fragile ou ≥ 85 ans : quel nombre maximal de classes ?","back":"**Pas plus d'une trithérapie** ; cible individualisée, sans hypotension orthostatique.","prio":"P2","sec":"s10"},{"id":"fc-224-987edc","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quels antihypertenseurs en 1re intention ?","back":"**IC dihydropyridine** et/ou **IEC/ARA2**.","prio":"P2","sec":"s10"},{"id":"fc-224-4e07b7","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quel antihypertenseur en 2e intention ?","back":"**Thiazidique** (ou apparenté) à **faible dose**.","prio":"P2","sec":"s10"},{"id":"fc-224-683833","poly":"cardio","fiche":"224","front":"Sujet âgé fragile ou ≥ 85 ans : quels antihypertenseurs éviter ?","back":"**Bêtabloquants** (sauf indication formelle) et **alphabloquants**.","prio":"P2","sec":"s10"},{"id":"fc-224-8c70d5","poly":"cardio","fiche":"224","front":"Thiazidiques et grossesse : quel type de contre-indication ?","back":"CI **relative** (pas absolue), contrairement aux IEC/ARA2.","prio":"P2","sec":"s10"},{"id":"fc-224-e07632","poly":"cardio","fiche":"224","front":"Prééclampsie sévère ou éclampsie : quelle prise en charge ?","back":"Urgence hypertensive imposant une **extraction fœtale en urgence**.","prio":"P1","sec":"s10"},{"id":"fc-224-ec4aa9","poly":"cardio","fiche":"224","front":"Hypertendu sous diurétique/IEC/ARA2 avec diarrhée ou canicule : quelle conduite ?","back":"**Diminution ou arrêt transitoire** ; contrôle ionogramme et créatininémie/DFG.","prio":"P1","sec":"s10"},{"id":"fc-224-95043b","poly":"cardio","fiche":"224","front":"Urgence hypertensive : où hospitaliser et à quel rythme surveiller la PA ?","back":"**Soins intensifs** ou **réanimation** ; PA **toutes les 15 min**.","prio":"P2","sec":"s11"},{"id":"fc-224-2b29ca","poly":"cardio","fiche":"224","front":"Urgence hypertensive avec point d'appel neurologique : quel examen avant tout antihypertenseur ?","back":"Un **scanner cérébral**.","prio":"P2","sec":"s11"},{"id":"fc-224-f9c970","poly":"cardio","fiche":"224","front":"Urgence hypertensive (cas général) : quel objectif de baisse de PA ?","back":"**− 25 % en 2 h**, puis **160/110 mmHg en 2 à 6 h**, sans chute brutale.","prio":"P2","sec":"s11"},{"id":"fc-224-83fca2","poly":"cardio","fiche":"224","front":"Urgence hypertensive : pourquoi éviter une baisse trop rapide de la PA ?","back":"Autorégulation altérée : risque d'hypoperfusion **cérébrale**, d'ischémie **myocardique** ou **rénale**.","prio":"P2","sec":"s11"},{"id":"fc-224-7ec0ce","poly":"cardio","fiche":"224","front":"Urgence hypertensive : quels antihypertenseurs IV de 1re intention ?","back":"**Urapidil IV** et/ou **nicardipine IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-b136f8","poly":"cardio","fiche":"224","front":"Phéochromocytome en urgence hypertensive : quelle molécule IV ?","back":"Le **labétalol IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-934d10","poly":"cardio","fiche":"224","front":"Urgence hypertensive avec SCA ou OAP : quel antihypertenseur IV de 1re intention ?","back":"Les **dérivés nitrés IV**.","prio":"P2","sec":"s11"},{"id":"fc-224-9472d1","poly":"cardio","fiche":"224","front":"Nicardipine IV dans l'item 224 : quelle contre-indication ?","back":"L'**insuffisance cardiaque** (l'item 234 la cite pourtant dans la poussée hypertensive de l'OAP).","prio":"P3","sec":"s11"},{"id":"fc-224-7d1eed","poly":"cardio","fiche":"224","front":"Dissection aortique : quel objectif tensionnel ?","back":"**PAS < 120 mmHg le plus vite possible** (pas de baisse progressive).","prio":"P2","sec":"s11"},{"id":"fc-224-de0ca3","poly":"cardio","fiche":"224","front":"Hémorragie intracérébrale : quel objectif tensionnel ?","back":"Baisse **dans les 6 h** vers une **PAS de 140-160 mmHg** ; éviter une chute de PAS > 70 mmHg.","prio":"P3","sec":"s11"},{"id":"fc-224-15a018","poly":"cardio","fiche":"224","front":"AVC ischémique sans reperfusion : quand baisser la PA ?","back":"Seulement si PA **> 220/120 mmHg** : − 10-15 % sur quelques heures.","prio":"P3","sec":"s11"},{"id":"fc-224-b86000","poly":"cardio","fiche":"224","front":"Thrombolyse IV d'un AVC : quels seuils de PA avant et pendant 24 h ?","back":"**< 185/110** avant, puis **< 180/105** pendant 24 h.","prio":"P3","sec":"s11"},{"id":"fc-224-857685","poly":"cardio","fiche":"224","front":"Thrombectomie d'un AVC : quel seuil de PA ?","back":"**< 180/105** avant et pendant les 24 h suivantes.","prio":"P3","sec":"s11"},{"id":"fc-224-c7cfac","poly":"cardio","fiche":"224","front":"Après un AVC ischémique : quand débuter ou reprendre l'antihypertenseur ?","back":"Patient **stable** encore **≥ 140/90 mmHg au moins 3 jours** après l'AVC.","prio":"P2","sec":"s11"},{"id":"fc-224-399e49","poly":"cardio","fiche":"224","front":"Après un AVC : quelles classes antihypertensives privilégier ?","back":"**IEC, ARA2, IC** ou **diurétique**.","prio":"P3","sec":"s11"},{"id":"fc-224-15b281","poly":"cardio","fiche":"224","front":"OAP hypertensif : quand introduire IEC, ARA2 ou valsartan/sacubitril ?","back":"**Secondairement**, une fois la poussée passée.","prio":"P3","sec":"s11"},{"id":"fc-224-ec7fb6","poly":"cardio","fiche":"224","front":"OAP : quand ne pas introduire de bêtabloquant ?","back":"**Pendant la poussée** (arrêt ou baisse s'il était déjà prescrit).","prio":"P3","sec":"s11"},{"id":"fc-224-e1041d","poly":"cardio","fiche":"224","front":"Dissection aortique : quand opérer en urgence ?","back":"Atteinte de l'**aorte ascendante** (type A de Stanford) ; sauf type B (aorte descendante) sans complication périphérique.","prio":"P3","sec":"s11"},{"id":"fc-224-a2c906","poly":"cardio","fiche":"224","front":"Sténose athéromateuse de l'artère rénale : quand discuter une revascularisation ?","back":"**Uniquement** si souffrance du rein homolatéral (HTA résistante, DFG qui baisse, protéinurie) **et** rein encore fonctionnel.","prio":"P3","sec":"s12"},{"id":"fc-224-905ce8","poly":"cardio","fiche":"224","front":"Sténose athéromateuse vs dysplasie fibromusculaire : quelle angioplastie ?","back":"Athérome : **avec endoprothèse** ; dysplasie : **sans endoprothèse** (plus largement utilisée).","prio":"P3","sec":"s12"},{"id":"fc-224-af85e1","poly":"cardio","fiche":"224","front":"Phéochromocytome : quelle préparation avant la chirurgie ?","back":"**Alphabloquant** à petites doses augmentées progressivement, **associé à un bêtabloquant**, avant l'**exérèse**.","prio":"P2","sec":"s12"},{"id":"fc-224-a95f82","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire : quand proposer une surrénalectomie ?","back":"Lésion **unilatérale** (latéralisation par cathétérisme veineux) **et** patient demandeur.","prio":"P3","sec":"s12"},{"id":"fc-224-e1533f","poly":"cardio","fiche":"224","front":"Hyperaldostéronisme primaire non opéré : quel traitement médical ?","back":"**Spironolactone** (ARM) en 1re intention.","prio":"P2","sec":"s12"},{"id":"fc-224-d2d4b0","poly":"cardio","fiche":"224","front":"SAOS de l'hypertendu : quel traitement ?","back":"Masque de **pression positive** nocturne.","prio":"P3","sec":"s12"},{"id":"fc-224-855145","poly":"cardio","fiche":"224","front":"Insuffisance rénale apparue sous IEC/ARA2 : quelle cause évoquer ?","back":"Une **sténose des artères rénales**.","prio":"P2","sec":"s12"},{"id":"fc-224-9fb181","poly":"cardio","fiche":"224","front":"Premiers mois de traitement de l'HTA : quand contrôler la PA par AMT ?","back":"**1 mois après chaque adaptation** et **avant chaque consultation**.","prio":"P1","sec":"s13"},{"id":"fc-224-37d1a7","poly":"cardio","fiche":"224","front":"Introduction ou changement de dose d'IEC/ARA2 ou de diurétique : quel contrôle biologique ?","back":"**Ionogramme sanguin** + **créatininémie/DFGe**.","prio":"P1","sec":"s13"},{"id":"fc-224-6bf8db","poly":"cardio","fiche":"224","front":"HTA : que vérifier à chaque consultation de suivi des premiers mois ?","back":"**Hypotension orthostatique**, **effets indésirables**, tolérance (réadapter la cible si besoin).","prio":"P2","sec":"s13"},{"id":"fc-224-6ea4d6","poly":"cardio","fiche":"224","front":"Cible tensionnelle non atteinte à 1 mois sous bithérapie : quelle conduite ?","back":"Renforcer **MHD** et **observance**, puis passer à la **trithérapie** **avant** d'augmenter les doses.","prio":"P1","sec":"s13"},{"id":"fc-224-16ebe7","poly":"cardio","fiche":"224","front":"HTA : quelle trithérapie utiliser ?","back":"**IEC/ARA2 + IC + thiazidique** (ou apparenté).","prio":"P1","sec":"s13"},{"id":"fc-224-2cfe8d","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé : à quel rythme le revoir en consultation ?","back":"**Tous les 3 à 6 mois** (6 mois si faible risque ou grade 1 ; 3 mois si risque élevé ou MHD seules).","prio":"P3","sec":"s13"},{"id":"fc-224-cc0992","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé : à quel rythme le bilan rénal et ionique ?","back":"**Chaque année** (plus souvent chez l'âgé).","prio":"P3","sec":"s13"},{"id":"fc-224-717d8b","poly":"cardio","fiche":"224","front":"Hypertendu contrôlé sans diabète ni dyslipidémie : à quel rythme glycémie et lipides ?","back":"**Tous les 3 ans**.","prio":"P3","sec":"s13"},{"id":"fc-224-eeaae1","poly":"cardio","fiche":"224","front":"Hypertendu avec ECG initial normal : à quel rythme refaire l'ECG ?","back":"**Tous les 3 à 5 ans**, sauf cardiopathie ou nouveaux symptômes.","prio":"P3","sec":"s13"},{"id":"fc-224-84b2ad","poly":"cardio","fiche":"224","front":"HTA résistante : quelle définition ?","back":"PA hors cible malgré MHD et **≥ 3 classes à dose optimale dont un thiazidique**, confirmée par **AMT/MAPA**.","prio":"P2","sec":"s14"},{"id":"fc-224-3d106b","poly":"cardio","fiche":"224","front":"HTA hors cible sous trithérapie sans thiazidique : est-ce une HTA résistante ?","back":"**Non** : sans thiazidique, on ne parle pas d'HTA résistante.","prio":"P2","sec":"s14"},{"id":"fc-224-89dabb","poly":"cardio","fiche":"224","front":"HTA résistante : quelles causes de fausse résistance éliminer ?","back":"**Blouse blanche**, brassard inadapté, doses insuffisantes ou pas de diurétique, **mauvaise observance**, MHD non suivies.","prio":"P2","sec":"s14"},{"id":"fc-224-068138","poly":"cardio","fiche":"224","front":"HTA résistante : quels facteurs de résistance rechercher ?","back":"**Excès de sel**, prise de poids, alcool, dépression, **AINS**, corticoïdes, œstrogènes, toxiques, **apnées du sommeil**.","prio":"P2","sec":"s14"},{"id":"fc-224-50d0cb","poly":"cardio","fiche":"224","front":"HTA résistante sans cause curable : quel médicament de 4e ligne ?","back":"**Spironolactone** (ARM) ; **éplérénone** si mal tolérée.","prio":"P2","sec":"s14"},{"id":"fc-224-c2b3de","poly":"cardio","fiche":"224","front":"HTA résistante : quelles options après l'ARM ?","back":"**Bêtabloquant**, puis éventuellement alphabloquant ou antihypertenseur central ; **dénervation rénale** au cas par cas.","prio":"P3","sec":"s14"},{"id":"fc-224-3064d5","poly":"cardio","fiche":"224","front":"HTA de l'enfant : sur quoi repose sa définition ?","back":"Sur des **normes pédiatriques** (abaques selon l'**âge** et le **sexe**).","prio":"P1","sec":"s15"},{"id":"fc-224-888cae","poly":"cardio","fiche":"224","front":"HTA de l'enfant : quand mesurer la PA ?","back":"À l'**examen systématique annuel après 3 ans** et en présence de **facteurs de risque**.","prio":"P1","sec":"s15"},{"id":"fc-224-e2db86","poly":"cardio","fiche":"224","front":"Mesure de la PA chez l'enfant : quelle précaution technique ?","back":"Un **brassard adapté** à sa taille.","prio":"P2","sec":"s15"},{"id":"fc-224-c21b0a","poly":"cardio","fiche":"224","front":"HTA de l'enfant : quel terrain familial augmente le risque ?","back":"Parent(s) **hypertendu(s)**, surtout si l'HTA parentale a débuté **jeune**.","prio":"P3","sec":"s15"},{"id":"fc-225-458199","poly":"cardio","fiche":"225","front":"AOMI : de quelle maladie s'agit-il et quelle étendue artérielle ?","back":"**Athérome** rétrécissant ou bouchant les artères des membres inférieurs, de l'**aorte terminale** aux artères des orteils.","prio":"P1","sec":"s1"},{"id":"fc-225-8023b1","poly":"cardio","fiche":"225","front":"AOMI : pourquoi reste-t-elle longtemps asymptomatique ?","back":"Débit encore suffisant et développement d'**artères collatérales**, d'autant mieux que l'évolution est lente.","prio":"P2","sec":"s1"},{"id":"fc-225-05a2a5","poly":"cardio","fiche":"225","front":"AOMI : quel mécanisme explique la claudication ?","back":"**Ischémie d'effort** : le muscle manque d'oxygène quand ses besoins augmentent.","prio":"P2","sec":"s1"},{"id":"fc-225-5cc157","poly":"cardio","fiche":"225","front":"AOMI : quel rang parmi les localisations de l'athérosclérose ?","back":"**3ᵉ localisation**, après l'atteinte **coronarienne** et **cérébrale**.","prio":"P1","sec":"s1"},{"id":"fc-225-55baef","poly":"cardio","fiche":"225","front":"AOMI symptomatique : quel sexe et quel âge de pic ?","back":"Plus fréquente chez l'**homme** ; pic **60-75 ans** (homme), **70-80 ans** (femme).","prio":"P2","sec":"s1"},{"id":"fc-225-cb04a5","poly":"cardio","fiche":"225","front":"AOMI après 60 ans : quelle prévalence ?","back":"**1 à 5 %** (formes cliniques) ; jusqu'à **10-15 %** avec les formes asymptomatiques.","prio":"P3","sec":"s1"},{"id":"fc-225-03977c","poly":"cardio","fiche":"225","front":"AOMI : combien de formes infracliniques pour une forme clinique ?","back":"**Deux à quatre** (d'où l'intérêt du dépistage).","prio":"P2","sec":"s1"},{"id":"fc-225-ba6289","poly":"cardio","fiche":"225","front":"AOMI : quels sont les deux facteurs de risque principaux ?","back":"**Tabagisme** et **diabète** (+ souvent hypercholestérolémie, HTA).","prio":"P2","sec":"s1"},{"id":"fc-225-432567","poly":"cardio","fiche":"225","front":"AOMI du diabétique : quelles particularités ?","back":"Formes plus souvent **graves d'emblée**, plus **distales**, de pronostic plus sévère.","prio":"P2","sec":"s1"},{"id":"fc-225-d3ae07","poly":"cardio","fiche":"225","front":"AOMI : quel facteur de risque concerne plutôt le sujet jeune ?","back":"Le **tabac**.","prio":"P3","sec":"s1"},{"id":"fc-225-9189ef","poly":"cardio","fiche":"225","front":"Classification de Leriche et Fontaine : que définit chaque stade ?","back":"**I** asymptomatique ; **II** claudication ; **III** douleur de repos ; **IV** ulcération ou gangrène.","prio":"P1","sec":"s2"},{"id":"fc-225-8ac67e","poly":"cardio","fiche":"225","front":"AOMI : quelle classification a largement remplacé celle de Leriche et Fontaine ?","back":"Celle de **Rutherford** (grade 0 à III).","prio":"P2","sec":"s2"},{"id":"fc-225-2e7d32","poly":"cardio","fiche":"225","front":"Claudication intermittente typique : quelles caractéristiques ?","back":"Crampe du **mollet** après une distance, obligeant à **s'arrêter**, cédant en **moins de 5 min** ; distance **classiquement stable**.","prio":"P1","sec":"s2"},{"id":"fc-225-c048ff","poly":"cardio","fiche":"225","front":"Claudication : à partir de quelle distance de marche est-elle sévère ?","back":"Distance de marche **inférieure à 100 m**.","prio":"P1","sec":"s2"},{"id":"fc-225-3afed6","poly":"cardio","fiche":"225","front":"Claudication fessière : quel niveau d'atteinte ?","back":"Atteinte **aorto-iliaque**.","prio":"P1","sec":"s2"},{"id":"fc-225-804b9b","poly":"cardio","fiche":"225","front":"Claudication atypique : citer des formes fréquentes.","back":"Distance **variable** ; douleur au pied, à la cuisse ou à la fesse ; **paresthésies** d'effort ; patient qui **ralentit** sans s'arrêter.","prio":"P2","sec":"s2"},{"id":"fc-225-603446","poly":"cardio","fiche":"225","front":"Syndrome de Leriche : quels signes ?","back":"Claudication **fessière** et/ou fatigabilité à la marche + **impuissance**, par atteinte **aorto-iliaque** (homme).","prio":"P1","sec":"s2"},{"id":"fc-225-f0d270","poly":"cardio","fiche":"225","front":"AOMI masquée : quelles situations peuvent masquer une atteinte sévère ?","back":"Collatérales très développées ; sujet qui **ne marche plus assez** ; **neuropathie** (diabète, IR, grand âge).","prio":"P1","sec":"s2"},{"id":"fc-225-d0d004","poly":"cardio","fiche":"225","front":"AOMI masquée (neuropathie, sujet qui ne marche plus assez) : quel risque évolutif ?","back":"Le patient **peut** arriver **d'emblée en ischémie permanente**.","prio":"P2","sec":"s2"},{"id":"fc-225-fcc9fd","poly":"cardio","fiche":"225","front":"Douleurs de décubitus de l'AOMI (stade III) : quelles caractéristiques ?","back":"Brûlures des **orteils et de l'avant-pied** en position couchée, **calmées jambe pendante**.","prio":"P1","sec":"s2"},{"id":"fc-225-bdc876","poly":"cardio","fiche":"225","front":"Ulcères artériels : où siègent-ils surtout ?","back":"**Zones de frottement ou d'appui** : orteil, dos et bord externe du pied, talon.","prio":"P2","sec":"s2"},{"id":"fc-225-776b21","poly":"cardio","fiche":"225","front":"Gangrène de l'AOMI : chez qui est-elle plus fréquente ?","back":"Chez le **diabétique**, souvent avec des lésions infectées.","prio":"P2","sec":"s2"},{"id":"fc-225-1d7283","poly":"cardio","fiche":"225","front":"Ischémie permanente : quelle définition ?","back":"Stades **III et IV**, douleurs depuis **plus de 15 jours** résistant aux antalgiques usuels.","prio":"P1","sec":"s2"},{"id":"fc-225-4e0c8b","poly":"cardio","fiche":"225","front":"Ischémie critique : quels seuils de pression la définissent ?","back":"Ischémie permanente + pression de **cheville < 50 mmHg** ou d'**hallux < 30 mmHg**.","prio":"P1","sec":"s2"},{"id":"fc-225-68fa23","poly":"cardio","fiche":"225","front":"Ischémie critique : quel risque pour le membre ?","back":"Membre **menacé** : haut risque d'**amputation** sans revascularisation.","prio":"P2","sec":"s2"},{"id":"fc-225-b827f5","poly":"cardio","fiche":"225","front":"AOMI : quel est le temps de recoloration normal ?","back":"**Moins de 3 secondes** (allongé si ischémie).","prio":"P2","sec":"s2"},{"id":"fc-225-4fe174","poly":"cardio","fiche":"225","front":"Pouls pédieux : dans quelle proportion est-il absent de naissance ?","back":"Chez **5 %** de la population.","prio":"P3","sec":"s2"},{"id":"fc-225-79588f","poly":"cardio","fiche":"225","front":"Examen d'un patient avec AOMI : quels anévrismes rechercher systématiquement ?","back":"**Abdominal** (aortique) et **poplité**.","prio":"P2","sec":"s2"},{"id":"fc-225-edee33","poly":"cardio","fiche":"225","front":"AOMI : que signifie une douleur à la pression du mollet ?","back":"Une **ischémie sévère**.","prio":"P3","sec":"s2"},{"id":"fc-225-01eb04","poly":"cardio","fiche":"225","front":"Suspicion clinique d'AOMI : quel examen compléter systématiquement ?","back":"La mesure de l'**IPS**.","prio":"P1","sec":"s2"},{"id":"fc-225-034b73","poly":"cardio","fiche":"225","front":"AOMI : quelles autres atteintes athéromateuses rechercher ?","back":"**Maladie coronarienne** et atteinte **cérébrovasculaire** (fréquemment associées).","prio":"P2","sec":"s2"},{"id":"fc-225-a4c008","poly":"cardio","fiche":"225","front":"Troubles trophiques de l'AOMI : quel risque infectieux ?","back":"**Portes d'entrée** d'infection : cellulite, arthrite, **ostéite**, voire septicémie.","prio":"P3","sec":"s2"},{"id":"fc-225-a600bd","poly":"cardio","fiche":"225","front":"IPS : comment le calculer pour chaque jambe ?","back":"**Plus haute** pression de cheville (tibiale postérieure ou pédieuse) / **plus haute** pression des **deux bras**.","prio":"P1","sec":"s3"},{"id":"fc-225-089111","poly":"cardio","fiche":"225","front":"IPS : avec quel matériel le mesure-t-on au cabinet ?","back":"Un brassard et un **doppler de poche**.","prio":"P3","sec":"s3"},{"id":"fc-225-dc93a8","poly":"cardio","fiche":"225","front":"IPS : quelles valeurs sont normales ?","back":"**1,00 à 1,40**.","prio":"P1","sec":"s3"},{"id":"fc-225-954d06","poly":"cardio","fiche":"225","front":"IPS : quel seuil définit l'AOMI ?","back":"IPS **< 0,90** (au moins une cheville).","prio":"P1","sec":"s3"},{"id":"fc-225-9b2a87","poly":"cardio","fiche":"225","front":"IPS : quel seuil définit une AOMI sévère ?","back":"IPS **< 0,70** (le texte du chapitre ; les points clés ont une coquille).","prio":"P1","sec":"s3"},{"id":"fc-225-bd5286","poly":"cardio","fiche":"225","front":"IPS < 0,90 : quelle portée au-delà du diagnostic d'AOMI ?","back":"**Marqueur de risque cardiovasculaire** élevé (accidents coronariens ou cérébraux).","prio":"P1","sec":"s3"},{"id":"fc-225-afd4ac","poly":"cardio","fiche":"225","front":"IPS > 1,40 : que traduit-il ?","back":"Des artères **anormalement rigides** par **médiacalcose** (diabétique âgé, dialysé).","prio":"P1","sec":"s3"},{"id":"fc-225-381cd6","poly":"cardio","fiche":"225","front":"IPS > 1,40 : quelle mesure faire à la place ?","back":"La **pression d'orteil** : index d'orteil **< 0,70** = AOMI ; pression d'orteil **< 30 mmHg** = ischémie critique.","prio":"P2","sec":"s3"},{"id":"fc-225-665799","poly":"cardio","fiche":"225","front":"Médiacalcose : en quoi diffère-t-elle de l'athérosclérose ?","back":"**Calcification de la média** sans rétrécissement de la lumière.","prio":"P3","sec":"s3"},{"id":"fc-225-65a06f","poly":"cardio","fiche":"225","front":"Diabétique symptomatique avec IPS de repos normal : quelle conduite ?","back":"**Pression d'orteil** et **tests d'effort** (IPS après effort, TcPO2 à l'effort) : l'IPS de repos peut faussement rassurer.","prio":"P2","sec":"s3"},{"id":"fc-225-f3c82e","poly":"cardio","fiche":"225","front":"Test sur tapis roulant : quel résultat évoque une AOMI chez un claudicant à IPS de repos normal ?","back":"Baisse de la pression de cheville **> 30 mmHg** et/ou de l'IPS **> 20 %** juste après la marche.","prio":"P3","sec":"s3"},{"id":"fc-225-6fa425","poly":"cardio","fiche":"225","front":"Test de marche de 6 minutes : que mesure-t-il ?","back":"Le **handicap fonctionnel global** (non spécifique de l'AOMI).","prio":"P3","sec":"s3"},{"id":"fc-225-eb7810","poly":"cardio","fiche":"225","front":"TcPO2 : à quoi sert-elle dans l'AOMI ?","back":"Diagnostic et évaluation de l'**ischémie critique** (oxygénation cutanée, après hyperémie par la chaleur).","prio":"P2","sec":"s3"},{"id":"fc-225-25f6f3","poly":"cardio","fiche":"225","front":"TcPO2 au dos du pied : quel seuil définit l'hypoxie critique ?","back":"**< 10 mmHg** (normale > 50 mmHg).","prio":"P2","sec":"s3"},{"id":"fc-225-1c4546","poly":"cardio","fiche":"225","front":"AOMI : quel examen d'imagerie est le plus utilisé ?","back":"L'**échodoppler artériel** (non invasif ; localise et quantifie les sténoses).","prio":"P1","sec":"s3"},{"id":"fc-225-c1221e","poly":"cardio","fiche":"225","front":"AOMI : quand demander un angioscanner ou une angio-IRM ?","back":"**Seulement si une revascularisation est envisagée**.","prio":"P1","sec":"s3"},{"id":"fc-225-d23040","poly":"cardio","fiche":"225","front":"Angio-IRM des membres inférieurs : quelle limite pour le chirurgien ?","back":"Elle **ne voit pas les calcifications** ; gadolinium CI si clairance < 30 mL/min/1,73 m².","prio":"P3","sec":"s3"},{"id":"fc-225-528242","poly":"cardio","fiche":"225","front":"AOMI : quand réalise-t-on l'artériographie ?","back":"Essentiellement **pendant les procédures de revascularisation**.","prio":"P2","sec":"s3"},{"id":"fc-225-04fa1d","poly":"cardio","fiche":"225","front":"AOMI : quel est le bilan de base ?","back":"**IPS + échodoppler**.","prio":"P1","sec":"s3"},{"id":"fc-225-3930fc","poly":"cardio","fiche":"225","front":"Douleur du mollet à l'effort cédant au repos : quel diagnostic différentiel neurologique ?","back":"Le **canal lombaire étroit**.","prio":"P1","sec":"s4"},{"id":"fc-225-443758","poly":"cardio","fiche":"225","front":"Douleur de jambe à la marche : quels diagnostics différentiels non artériels ?","back":"**Neurologiques** (canal lombaire étroit), **rhumatologiques**, **veineux** (claudication post-thrombotique), **musculaires** (statines).","prio":"P2","sec":"s4"},{"id":"fc-225-eaf911","poly":"cardio","fiche":"225","front":"Douleur de décubitus de jambe : quels diagnostics différentiels ?","back":"**Neuropathie sensitive**, syndromes douloureux régionaux complexes, **compression radiculaire**.","prio":"P3","sec":"s4"},{"id":"fc-225-ace6ac","poly":"cardio","fiche":"225","front":"Ulcère de jambe non artériel : quelles autres causes ?","back":"**Veineux**, microcirculatoire, **neuropathique**, traumatique.","prio":"P3","sec":"s4"},{"id":"fc-225-cf5979","poly":"cardio","fiche":"225","front":"Sujet âgé avec canal lombaire étroit ou myalgies sous statine : l'AOMI est-elle exclue ?","back":"**Non** : plusieurs causes peuvent **coexister**.","prio":"P2","sec":"s4"},{"id":"fc-225-495f5a","poly":"cardio","fiche":"225","front":"Artériopathies oblitérantes des membres inférieurs : quelle part est athéromateuse ?","back":"**Plus de 95 %**.","prio":"P3","sec":"s4"},{"id":"fc-225-fbe736","poly":"cardio","fiche":"225","front":"Artériopathies non athéromateuses inflammatoires : lesquelles ?","back":"Maladies de **Buerger**, **Takayasu**, **Horton** ; certaines collagénoses (PAN, lupus).","prio":"P3","sec":"s4"},{"id":"fc-225-cf6d50","poly":"cardio","fiche":"225","front":"Artériopathies non athéromateuses propres à l'artère poplitée : lesquelles ?","back":"**Artère poplitée piégée** ; **kyste poplité sous-adventiciel**.","prio":"P3","sec":"s4"},{"id":"fc-225-80e957","poly":"cardio","fiche":"225","front":"Traitement de l'AOMI : quels sont les deux objectifs distincts ?","back":"**Général** : pronostic CV et vital ; **local** : symptômes et protection du membre.","prio":"P1","sec":"s5"},{"id":"fc-225-d10a8c","poly":"cardio","fiche":"225","front":"AOMI : à quels stades s'applique le traitement général ?","back":"À **tous les stades**, asymptomatique compris, et **après revascularisation**.","prio":"P1","sec":"s5"},{"id":"fc-225-2aa5c0","poly":"cardio","fiche":"225","front":"AOMI : quelles mesures viennent en tête du traitement général ?","back":"**Arrêt du tabac** et contrôle du **diabète**.","prio":"P1","sec":"s5"},{"id":"fc-225-0e86e6","poly":"cardio","fiche":"225","front":"AOMI : quel réentraînement à la marche viser ?","back":"**3 fois/semaine pendant 12 semaines**.","prio":"P2","sec":"s5"},{"id":"fc-225-c989eb","poly":"cardio","fiche":"225","front":"AOMI : chez qui prescrire une statine ?","back":"**Tous** les patients (systématique).","prio":"P1","sec":"s5"},{"id":"fc-225-8e0c09","poly":"cardio","fiche":"225","front":"AOMI : quel objectif de LDL-c ?","back":"**< 0,55 g/L (1,4 mmol/L)** et baisse d'**au moins 50 %**.","prio":"P1","sec":"s5"},{"id":"fc-225-17ef18","poly":"cardio","fiche":"225","front":"AOMI : quand l'antiagrégant plaquettaire est-il indiqué ?","back":"Chez **tout patient avec AOMI symptomatique** (aspirine ou clopidogrel).","prio":"P1","sec":"s5"},{"id":"fc-225-b27648","poly":"cardio","fiche":"225","front":"AOMI asymptomatique isolée (IPS < 0,90) : faut-il un antiagrégant ?","back":"Indication **débattue**, sauf autre atteinte athéromateuse.","prio":"P2","sec":"s5"},{"id":"fc-225-b16d3c","poly":"cardio","fiche":"225","front":"AOMI : chez qui envisager un IEC ou un sartan ?","back":"Chez **tout patient avec AOMI**, quel que soit le niveau de PA, sans contre-indication.","prio":"P1","sec":"s5"},{"id":"fc-225-bd9d2d","poly":"cardio","fiche":"225","front":"AOMI : quelles cibles tensionnelle et glycémique ?","back":"PAS **≤ 120-129** et PAD **≤ 70-79 mmHg** ; **HbA1c < 7 %**.","prio":"P2","sec":"s5"},{"id":"fc-225-f02c89","poly":"cardio","fiche":"225","front":"AOMI : quand proposer un bêtabloquant ?","back":"Si **indication formelle** (cardiopathie ischémique, IC à FE altérée, certaines arythmies) ; **prudence** si ischémie critique non revascularisable.","prio":"P2","sec":"s5"},{"id":"fc-225-b804ef","poly":"cardio","fiche":"225","front":"Antiagrégant dans l'AOMI : quelles molécules ?","back":"**Aspirine** ou **clopidogrel**.","prio":"P1","sec":"s5"},{"id":"fc-225-85778c","poly":"cardio","fiche":"225","front":"AOMI : quelles mesures hygiéno-diététiques ?","back":"**Arrêt du tabac**, **régime méditerranéen**, IMC entre **20 et 25 kg/m²**, **exercice modéré**.","prio":"P2","sec":"s5"},{"id":"fc-225-4cf018","poly":"cardio","fiche":"225","front":"Arrêt du tabac et marche régulière : comment améliorent-ils la claudication ?","back":"Développement des **collatérales** et du métabolisme musculaire (plus de **mitochondries**).","prio":"P2","sec":"s6"},{"id":"fc-225-019fa8","poly":"cardio","fiche":"225","front":"Claudication : quel programme de marche ?","back":"Au moins **30-45 min**, **au moins 3 fois/semaine**, en **ralentissant ou s'arrêtant** quelques minutes dès la douleur.","prio":"P1","sec":"s6"},{"id":"fc-225-adfd45","poly":"cardio","fiche":"225","front":"Claudication : pourquoi préférer la réadaptation supervisée ?","back":"**Meilleurs résultats** que le programme seul ; toujours associée à l'**éducation thérapeutique**.","prio":"P2","sec":"s6"},{"id":"fc-225-1746c9","poly":"cardio","fiche":"225","front":"Claudication : quand envisager une revascularisation d'emblée ?","back":"Périmètre de marche **< 100 m** très invalidant ou atteinte **aorto-iliaque sévère et extensive**.","prio":"P1","sec":"s6"},{"id":"fc-225-335579","poly":"cardio","fiche":"225","front":"Claudication sans périmètre très court ni atteinte aorto-iliaque sévère : quelle stratégie ?","back":"**Réadaptation à la marche d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-225-b4c5c5","poly":"cardio","fiche":"225","front":"Claudication : quand revasculariser après le traitement médical ?","back":"Claudication sévère altérant la qualité de vie **malgré** un traitement bien mené incluant la réadaptation.","prio":"P2","sec":"s6"},{"id":"fc-225-e2b9ff","poly":"cardio","fiche":"225","front":"Revascularisation de l'AOMI : quelles techniques ?","back":"**Angioplastie au ballonnet ± stent**, ou **pontage**.","prio":"P2","sec":"s6"},{"id":"fc-225-0b6da4","poly":"cardio","fiche":"225","front":"Vasoactifs (pentoxifylline) dans la claudication : quel intérêt ?","back":"Gain **modeste** du périmètre de marche, **aucun bénéfice pronostique**.","prio":"P3","sec":"s6"},{"id":"fc-225-a0290c","poly":"cardio","fiche":"225","front":"Statine dans la claudication : quel effet possible en plus du pronostic ?","back":"Un **allongement du périmètre de marche**.","prio":"P3","sec":"s6"},{"id":"fc-225-922f85","poly":"cardio","fiche":"225","front":"Ischémie permanente ou critique : quel est l'objectif principal ?","back":"**Revasculariser autant que possible**.","prio":"P1","sec":"s7"},{"id":"fc-225-c4a59e","poly":"cardio","fiche":"225","front":"Ischémie permanente : quel geste endovasculaire principal ?","back":"**Angioplastie intraluminale au ballonnet**, ± **stent**.","prio":"P2","sec":"s7"},{"id":"fc-225-5d9db5","poly":"cardio","fiche":"225","front":"Angioplastie des artères des membres inférieurs : quelles lésions donnent les meilleurs résultats ?","back":"Lésions **courtes et proximales**.","prio":"P3","sec":"s7"},{"id":"fc-225-faee2f","poly":"cardio","fiche":"225","front":"Pontage dans l'AOMI : quel matériau préférer ?","back":"Une **veine** (sinon une prothèse).","prio":"P2","sec":"s7"},{"id":"fc-225-8394bb","poly":"cardio","fiche":"225","front":"Endartériectomie fémorale : quel intérêt ?","back":"Améliore le réseau **fémoral profond**, donc les collatérales de cuisse si la fémorale superficielle est occluse.","prio":"P3","sec":"s7"},{"id":"fc-225-66f4af","poly":"cardio","fiche":"225","front":"Ischémie permanente : quels traitements associés à la revascularisation ?","back":"**Antalgiques**, **soins de plaies** pluridisciplinaires, socle médical (statine, antiagrégant, FDR).","prio":"P2","sec":"s7"},{"id":"fc-225-7ac1d5","poly":"cardio","fiche":"225","front":"AOMI : quand recourir à l'amputation ?","back":"Revascularisation **impossible ou en échec** : geste ultime contre la douleur et/ou l'infection.","prio":"P1","sec":"s7"},{"id":"fc-225-b52c59","poly":"cardio","fiche":"225","front":"Amputation dans l'AOMI : où et comment la réaliser ?","back":"En zone **saine et bien oxygénée** (**TcPO2**), en gardant si possible l'**appui** ou le **genou**.","prio":"P2","sec":"s7"},{"id":"fc-225-156dfa","poly":"cardio","fiche":"225","front":"Prostaglandines dans l'AOMI : quelle indication ?","back":"**Ischémie critique non revascularisable** (perfusions quotidiennes, plusieurs semaines).","prio":"P3","sec":"s7"},{"id":"fc-225-989575","poly":"cardio","fiche":"225","front":"Après angioplastie ± stent : quelle durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s7"},{"id":"fc-225-80f7d5","poly":"cardio","fiche":"225","front":"Patient revascularisé devenu asymptomatique : peut-on arrêter le traitement préventif ?","back":"**Non** : il n'est pas guéri, hygiène de vie et médicaments continuent.","prio":"P1","sec":"s7"},{"id":"fc-225-5e9e59","poly":"cardio","fiche":"225","front":"Pontage dans l'AOMI : quels sont les plus fréquents ?","back":"**Aorto-bi-iliaque** (ou bifémoral), **fémoropoplité**, **fémorojambier** ; extra-anatomique si besoin.","prio":"P3","sec":"s7"},{"id":"fc-225-dd2a0d","poly":"cardio","fiche":"225","front":"Claudication : de combien l'espérance de vie est-elle réduite ?","back":"De **10 ans** en moyenne.","prio":"P2","sec":"s8"},{"id":"fc-225-023f86","poly":"cardio","fiche":"225","front":"Claudication : quel pronostic vital à 5 ans ?","back":"**20 %** de complications CV et **20 %** de décès (moitié de cause CV).","prio":"P2","sec":"s8"},{"id":"fc-225-b6deb7","poly":"cardio","fiche":"225","front":"Claudication : quel pronostic local ?","back":"**25 %** s'aggravent (dont 1/5 jusqu'à l'amputation majeure) ; amputation à 5 ans ≈ **5 %**.","prio":"P3","sec":"s8"},{"id":"fc-225-d21db6","poly":"cardio","fiche":"225","front":"Ischémie critique : quelle mortalité à 5 ans ?","back":"Proche de **70 %**.","prio":"P1","sec":"s8"},{"id":"fc-225-b514b3","poly":"cardio","fiche":"225","front":"Ischémie permanente : à quoi compare-t-on son espérance de vie ?","back":"À celle de **certains cancers**.","prio":"P3","sec":"s8"},{"id":"fc-225-d8a10b","poly":"cardio","fiche":"225","front":"Après revascularisation d'une AOMI : quelle surveillance ?","back":"**Clinique et échodoppler** (thrombose de stent ou de pontage, dégradation des anastomoses).","prio":"P2","sec":"s8"},{"id":"fc-225-80e70b","poly":"cardio","fiche":"225","front":"Patient avec AOMI ou AAA : quelles atteintes rechercher (notion indispensable) ?","back":"Une **maladie coronarienne** et une **sténose carotidienne**.","prio":"P1","sec":"s8"},{"id":"fc-225-4a3ba3","poly":"cardio","fiche":"225","front":"Ischémie aiguë de membre : quelle définition ?","back":"Interruption **brutale** du flux artériel d'un membre : **urgence vasculaire**, pronostic du membre voire vital engagé.","prio":"P1","sec":"s9"},{"id":"fc-225-5ff412","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels éléments déterminent la gravité ?","back":"La **PA** du patient, la **circulation collatérale** et la qualité du **réseau d'aval**.","prio":"P2","sec":"s9"},{"id":"fc-225-02e727","poly":"cardio","fiche":"225","front":"Ischémie aiguë : en combien de temps souffrent nerfs, muscles et peau ?","back":"**Nerfs** dans les **2 h** ; **muscles** dans les **6-8 h** ; **peau** à partir de la **24ᵉ h**.","prio":"P1","sec":"s9"},{"id":"fc-225-f225ff","poly":"cardio","fiche":"225","front":"Syndrome des loges : quel mécanisme ?","back":"**Œdème musculaire** dans des **loges aponévrotiques inextensibles** comprimant les tissus jusqu'à l'arrêt circulatoire.","prio":"P2","sec":"s9"},{"id":"fc-225-11be60","poly":"cardio","fiche":"225","front":"Syndrome des loges : quel traitement ?","back":"**Aponévrotomie de décharge**.","prio":"P1","sec":"s9"},{"id":"fc-225-4e2a80","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle douleur typique ?","back":"Début **brutal**, intense, **en broiement**, avec impotence fonctionnelle.","prio":"P1","sec":"s9"},{"id":"fc-225-14a68d","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels signes physiques ?","back":"Membre **froid**, **livide**, muscles douloureux, **pouls abolis** en aval, **anesthésie**, **paralysie**.","prio":"P1","sec":"s9"},{"id":"fc-225-30e596","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quel déficit moteur fibulaire typique ?","back":"Le patient **ne peut plus relever le pied** (nerf fibulaire commun).","prio":"P3","sec":"s9"},{"id":"fc-225-a066d7","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle forme est la plus grave ?","back":"Occlusion de la **bifurcation aortique** : deux jambes, paralysie, jusqu'au **collapsus**.","prio":"P2","sec":"s9"},{"id":"fc-225-52b28f","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade I de Rutherford : quelles caractéristiques ?","back":"**Viable** : pas de déficit sensitif ni moteur ; urgence relative.","prio":"P1","sec":"s9"},{"id":"fc-225-2bd2ac","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade IIa : quelles caractéristiques ?","back":"Discrètement menaçante : déficit sensitif **absent ou limité aux orteils**, pas de déficit moteur.","prio":"P1","sec":"s9"},{"id":"fc-225-28aa12","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade IIb : quelles caractéristiques ?","back":"Immédiatement menaçante : déficit sensitif **au-delà des orteils**, déficit moteur **modéré**.","prio":"P1","sec":"s9"},{"id":"fc-225-aa7173","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade III : quelles caractéristiques ?","back":"**Irréversible** : anesthésie importante, **paralysie** ; perte tissulaire inévitable.","prio":"P1","sec":"s9"},{"id":"fc-225-2abb8a","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quel mécanisme ?","back":"La **reperfusion** relargue **acides** et **radicaux libres**, avec des conséquences générales parfois sévères.","prio":"P2","sec":"s9"},{"id":"fc-225-5f432a","poly":"cardio","fiche":"225","front":"Ischémie aiguë : sur quoi repose le diagnostic ?","back":"Sur la **clinique** : équipe chirurgicale alertée au plus tôt, aucune imagerie ne doit retarder le geste.","prio":"P1","sec":"s10"},{"id":"fc-225-a6ce69","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels gestes faire toujours au lit du patient ?","back":"**Auscultation cardiaque + ECG**, **palpation abdominale** (anévrisme), **bilan de coagulation**.","prio":"P1","sec":"s10"},{"id":"fc-225-f6cfe6","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand réaliser un échodoppler ?","back":"Seulement s'il ne fait perdre **aucun temps** (notamment grade **I**).","prio":"P1","sec":"s10"},{"id":"fc-225-e8c854","poly":"cardio","fiche":"225","front":"Ischémie aiguë : où et pourquoi réaliser l'artériographie ?","back":"Le plus souvent **au bloc**, pour guider le geste (qualité du **réseau d'aval**).","prio":"P2","sec":"s10"},{"id":"fc-225-463fbf","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand faire le bilan cardiaque et artériel étiologique ?","back":"**Après** la revascularisation.","prio":"P2","sec":"s10"},{"id":"fc-225-30d063","poly":"cardio","fiche":"225","front":"Thrombose artérielle in situ : quel terrain et quelle douleur ?","back":"Sujet **plutôt âgé**, FDR, **souvent** AOMI préexistante ; douleur d'intensité **moyenne** (collatérales).","prio":"P2","sec":"s10"},{"id":"fc-225-e58495","poly":"cardio","fiche":"225","front":"Embolie artérielle sur artère saine : quel terrain et quelle douleur ?","back":"Sujet **classiquement jeune**, sans antécédent vasculaire ; douleur **brutale, sévère**, parfois précédée de **palpitations**.","prio":"P2","sec":"s10"},{"id":"fc-225-da2d74","poly":"cardio","fiche":"225","front":"Embolie artérielle : quel trouble du rythme en est une cause cardiaque ?","back":"La **fibrillation atriale**.","prio":"P2","sec":"s10"},{"id":"fc-225-833163","poly":"cardio","fiche":"225","front":"Embolie artérielle : citer d'autres causes cardiaques que la FA.","back":"**Infarctus** (anévrisme du VG), **endocardite**, valvulopathies et prothèses, **myxome**, FOP avec anévrisme du septum.","prio":"P3","sec":"s10"},{"id":"fc-225-665fe6","poly":"cardio","fiche":"225","front":"Thrombose artérielle in situ : citer des causes.","back":"**AOMI** ; **anévrisme poplité thrombosé** ; déshydratation du sujet âgé ; thrombopénie à l'héparine ; artériopathies non athéromateuses.","prio":"P3","sec":"s10"},{"id":"fc-225-e7f3aa","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quel traitement médical débuter dès le diagnostic ?","back":"**Héparine non fractionnée**, après prélèvement du **bilan de coagulation**.","prio":"P1","sec":"s11"},{"id":"fc-225-0d53cf","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle posologie d'HNF ?","back":"Bolus IV **5 000 UI** puis **500 UI/kg/j** ; objectif **TCA 2 à 3**.","prio":"P1","sec":"s11"},{"id":"fc-225-012562","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quels traitements associés à l'héparine ?","back":"**Antalgiques de niveau 3**, **oxygène nasal**, remplissage si besoin, **soins locaux**.","prio":"P2","sec":"s11"},{"id":"fc-225-225ed0","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quelle position et protection du membre ?","back":"Position **légèrement déclive**, protection par mousse ou coton, sans frottement.","prio":"P3","sec":"s11"},{"id":"fc-225-e412c5","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade I : quelle stratégie ?","back":"**Imagerie en urgence** puis revascularisation **dans les heures à venir**.","prio":"P1","sec":"s11"},{"id":"fc-225-49f441","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade II : quelle stratégie ?","back":"**Revascularisation en urgence absolue** (thrombectomie ou pontage), sans imagerie qui retarde.","prio":"P1","sec":"s11"},{"id":"fc-225-dd4d81","poly":"cardio","fiche":"225","front":"Ischémie aiguë grade III : quelle stratégie ?","back":"**Amputation**.","prio":"P1","sec":"s11"},{"id":"fc-225-a064f4","poly":"cardio","fiche":"225","front":"Embolie sur artère saine : quel est le geste de référence ?","back":"**Embolectomie par sonde de Fogarty** (sous contrôle angiographique).","prio":"P1","sec":"s11"},{"id":"fc-225-8732b7","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand discuter une thrombolyse in situ ?","back":"Lit d'aval jambier de **mauvaise qualité** **et** ischémie **peu sévère**.","prio":"P2","sec":"s11"},{"id":"fc-225-4af165","poly":"cardio","fiche":"225","front":"Ischémie aiguë revascularisée tardivement : quel geste associer ?","back":"**Aponévrotomie de décompression**, en général systématique.","prio":"P2","sec":"s11"},{"id":"fc-225-fc472a","poly":"cardio","fiche":"225","front":"Ischémie aiguë : quand l'angioplastie complète-t-elle la revascularisation ?","back":"Devant une **sténose résiduelle** après embolectomie ou thrombolyse.","prio":"P3","sec":"s11"},{"id":"fc-225-c5b779","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quel trouble métabolique dépister systématiquement ?","back":"**Acidose métabolique hyperkaliémique** (ionogramme systématique).","prio":"P1","sec":"s12"},{"id":"fc-225-d1142e","poly":"cardio","fiche":"225","front":"Acidose hyperkaliémique après revascularisation : quel traitement ?","back":"**Bicarbonates IV** (correction progressive) ; chélateur du potassium voire **dialyse** ; lavage du membre.","prio":"P2","sec":"s12"},{"id":"fc-225-be1bfe","poly":"cardio","fiche":"225","front":"Après revascularisation d'une ischémie aiguë : comment dépister l'IRA ?","back":"**Sonde urinaire avec diurèse horaire**, urée, créatininémie, **CPK**.","prio":"P2","sec":"s12"},{"id":"fc-225-6b871d","poly":"cardio","fiche":"225","front":"IRA du syndrome de revascularisation : quel mécanisme principal ?","back":"**Nécrose tubulaire** : choc, **myoglobine** précipitant dans les tubules, produits de contraste.","prio":"P3","sec":"s12"},{"id":"fc-225-22393f","poly":"cardio","fiche":"225","front":"Syndrome de revascularisation : quels autres troubles biologiques ?","back":"Hyperuricémie, **myoglobinurie**, **hypocalcémie**, hyperphosphorémie ; CIVD possible.","prio":"P3","sec":"s12"},{"id":"fc-225-66c368","poly":"cardio","fiche":"225","front":"Ischémie aiguë d'origine embolique sur FA : quel traitement au long cours ?","back":"**Anticoagulation au long cours**.","prio":"P1","sec":"s12"},{"id":"fc-225-db146e","poly":"cardio","fiche":"225","front":"Ischémie aiguë par thrombose sur AOMI : quel traitement au long cours ?","back":"**Antiagrégant plaquettaire** + contrôle strict des FDR CV.","prio":"P1","sec":"s12"},{"id":"fc-225-eeb057","poly":"cardio","fiche":"225","front":"FA avec valve mécanique ou RM serré : quel anticoagulant oral ?","back":"Un **AVK** (warfarine) : **AOD contre-indiqués**.","prio":"P1","sec":"s12"},{"id":"fc-225-771ee3","poly":"cardio","fiche":"225","front":"AOD : quelle vérification faire avant la prescription ?","back":"La **fonction rénale** (déconseillés si clairance < 30 à 25 mL/min).","prio":"P2","sec":"s12"},{"id":"fc-225-73d4d2","poly":"cardio","fiche":"225","front":"AVK : quelle INR cible pour la plupart des indications ?","back":"INR **entre 2 et 3**.","prio":"P1","sec":"s12"},{"id":"fc-225-658e61","poly":"cardio","fiche":"225","front":"AVK : quel est l'AVK de référence et lequel ne pas débuter ?","back":"**Warfarine** ; ne pas débuter la **fluindione** (risque immunoallergique).","prio":"P2","sec":"s12"},{"id":"fc-225-3b9af7","poly":"cardio","fiche":"225","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **au moins 4-5 jours** de chevauchement **et** **2 INR efficaces** à 24 h d'intervalle.","prio":"P2","sec":"s12"},{"id":"fc-225-be9b62","poly":"cardio","fiche":"225","front":"CHA₂DS₂-VA : combien de points pour un antécédent d'embolie artérielle ?","back":"**2 points** ; score > 1 → anticoagulation orale au long cours indiquée.","prio":"P2","sec":"s12"},{"id":"fc-225-c9a4ba","poly":"cardio","fiche":"225","front":"AVK : quand le patient est-il considéré équilibré ?","back":"Si **au moins 70 %** des INR sont dans la cible.","prio":"P3","sec":"s12"},{"id":"fc-225-5e2c63","poly":"cardio","fiche":"225","front":"Sous AOD : faut-il un suivi biologique de routine de la coagulation ?","back":"**Non** (TCA, TP, INR perturbés mais non interprétables).","prio":"P2","sec":"s12"},{"id":"fc-225-01537b","poly":"cardio","fiche":"225","front":"Valve mécanique mitrale ou à disque : quelle INR cible ?","back":"**3 à 4,5**.","prio":"P3","sec":"s12"},{"id":"fc-225-bc23d8","poly":"cardio","fiche":"225","front":"AOD : en combien de temps sont-ils efficaces après la 1re prise ?","back":"Environ **2 h** : anticoagulation immédiate, sans relais par héparine.","prio":"P3","sec":"s12"},{"id":"fc-225-df4df2","poly":"cardio","fiche":"225","front":"Anévrisme artériel : quelle définition ?","back":"Dilatation **focale et permanente**, perte du **parallélisme des parois**, diamètre augmenté de **> 50 %**.","prio":"P1","sec":"s13"},{"id":"fc-225-6a0c43","poly":"cardio","fiche":"225","front":"Anévrismes hors cerveau : quels sièges les plus fréquents ?","back":"**Aorte** (surtout **sous-rénale**), artères **poplitées**, artères **iliaques**.","prio":"P1","sec":"s13"},{"id":"fc-225-7d4441","poly":"cardio","fiche":"225","front":"AAA : quel mécanisme pariétal ?","back":"**Média** qui perd ses fibres élastiques et son collagène, sous l'action d'enzymes (**métalloprotéases**).","prio":"P3","sec":"s13"},{"id":"fc-225-a566d1","poly":"cardio","fiche":"225","front":"Porteur d'AAA : quel risque est le plus important ?","back":"**10 fois plus** de risque de mourir d'une autre atteinte CV (coronaire, AVC) que de la rupture.","prio":"P1","sec":"s13"},{"id":"fc-225-8654bc","poly":"cardio","fiche":"225","front":"AAA : quelle prévalence chez l'homme de plus de 65 ans ?","back":"**2 à 5 %**.","prio":"P3","sec":"s13"},{"id":"fc-225-5b850c","poly":"cardio","fiche":"225","front":"AAA : quels sont les facteurs de risque (hors âge) ?","back":"**Tabagisme** et **antécédents familiaux** d'anévrisme.","prio":"P1","sec":"s13"},{"id":"fc-225-3336b1","poly":"cardio","fiche":"225","front":"AAA : quel terrain est paradoxalement moins souvent atteint ?","back":"Les **diabétiques**.","prio":"P2","sec":"s13"},{"id":"fc-225-3bf73d","poly":"cardio","fiche":"225","front":"AAA sous-rénal < 40 mm : quel risque annuel de rupture ?","back":"Très faible : **0,4 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-580f47","poly":"cardio","fiche":"225","front":"AAA sous-rénal de 50-59 mm : quel risque annuel de rupture ?","back":"**3 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-d56bdd","poly":"cardio","fiche":"225","front":"AAA sous-rénal > 60 mm : quel risque annuel de rupture ?","back":"**15 %/an**.","prio":"P2","sec":"s13"},{"id":"fc-225-005f48","poly":"cardio","fiche":"225","front":"AAA : à diamètre égal, quel sexe a le plus de risque de rupture ?","back":"La **femme** : près de **4 fois** plus.","prio":"P1","sec":"s13"},{"id":"fc-225-a6859d","poly":"cardio","fiche":"225","front":"AAA : sur quel terrain survient-il dans 80-90 % des cas ?","back":"Chez un **athéromateux** (surtout AOMI).","prio":"P3","sec":"s13"},{"id":"fc-225-4303b0","poly":"cardio","fiche":"225","front":"AAA familial génétique : quelles maladies du tissu élastique ?","back":"**Marfan**, **Ehlers-Danlos**, **Loeys-Dietz**.","prio":"P3","sec":"s13"},{"id":"fc-225-fa9d6d","poly":"cardio","fiche":"225","front":"AAA : comment est-il le plus souvent découvert ?","back":"**Fortuitement** : masse **battante et expansive** paraombilicale ou, plus souvent, sur une imagerie abdominale.","prio":"P1","sec":"s13"},{"id":"fc-225-e1cf23","poly":"cardio","fiche":"225","front":"AAA symptomatique : quels signes de fissuration ou rupture ?","back":"Douleur **abdominale ou lombaire**, avec ou sans **choc hémorragique**.","prio":"P1","sec":"s13"},{"id":"fc-225-4ebd95","poly":"cardio","fiche":"225","front":"AAA : quelles fistules rares peut-il donner ?","back":"**Aortocave** (IC à débit élevé) ou **aortodigestive** (hémorragie digestive).","prio":"P3","sec":"s13"},{"id":"fc-225-e273ac","poly":"cardio","fiche":"225","front":"Anévrisme poplité : quelles associations rechercher ?","back":"AAA dans **30 %** des cas ; **bilatéral** dans près de la moitié des cas.","prio":"P1","sec":"s13"},{"id":"fc-225-7792b3","poly":"cardio","fiche":"225","front":"Anévrisme poplité : comment peut-il se révéler ?","back":"**Masse battante** du creux poplité, artériopathie progressive, voire **ischémie aiguë**.","prio":"P2","sec":"s13"},{"id":"fc-225-646e69","poly":"cardio","fiche":"225","front":"AAA : quelles complications symptomatiques beaucoup plus rares que la rupture ?","back":"**Embolie** (thrombus intra-anévrismal), **compression** des organes voisins, **syndrome inflammatoire**.","prio":"P3","sec":"s13"},{"id":"fc-225-42e7e9","poly":"cardio","fiche":"225","front":"AAA : chez qui le dépister par échographie ?","back":"Patient **polyathéromateux**, notamment **homme après 65 ans**.","prio":"P1","sec":"s14"},{"id":"fc-225-68303e","poly":"cardio","fiche":"225","front":"AAA : quelle population à risque dépister (détail item 225) ?","back":"**Hommes > 65 ans**, ou plus jeunes avec FDR (tabac, athérome, antécédents familiaux d'anévrisme).","prio":"P3","sec":"s14"},{"id":"fc-225-284edb","poly":"cardio","fiche":"225","front":"AAA : quel examen pour dépister, mesurer et surveiller ?","back":"L'**échographie abdominale** (diamètre maximal ; dépiste aussi poplitées et iliaques).","prio":"P1","sec":"s14"},{"id":"fc-225-d43573","poly":"cardio","fiche":"225","front":"AAA : quel est l'examen préthérapeutique de référence ?","back":"Le **scanner abdominopelvien injecté** (IRM en alternative).","prio":"P1","sec":"s14"},{"id":"fc-225-20c385","poly":"cardio","fiche":"225","front":"AAA : pourquoi l'artériographie n'est-elle pas utile ?","back":"Elle ne voit que la lumière : **pas de mesure fiable** (thrombus mural fréquent).","prio":"P2","sec":"s14"},{"id":"fc-225-47cfa0","poly":"cardio","fiche":"225","front":"AAA asymptomatique : quelle est la priorité de prise en charge ?","back":"La **prévention générale** : rechercher **maladie coronarienne** et **sténose carotidienne**.","prio":"P1","sec":"s15"},{"id":"fc-225-427fdc","poly":"cardio","fiche":"225","front":"AAA : quel est le principal facteur prédictif de rupture ?","back":"Le **diamètre**.","prio":"P2","sec":"s15"},{"id":"fc-225-525f5d","poly":"cardio","fiche":"225","front":"AAA : quelle croissance moyenne ?","back":"**2-4 mm/an**, non linéaire ; **3 fois plus rapide** si le tabagisme continue.","prio":"P3","sec":"s15"},{"id":"fc-225-c91e38","poly":"cardio","fiche":"225","front":"AAA : à partir de quel diamètre surveiller par échographie tous les 6 mois ?","back":"**Au-delà de 45 mm**.","prio":"P2","sec":"s15"},{"id":"fc-225-e2b413","poly":"cardio","fiche":"225","front":"AAA asymptomatique : à partir de quel diamètre intervenir (item 225) ?","back":"**Au-delà de 50-55 mm**, après scanner abdominopelvien.","prio":"P2","sec":"s15"},{"id":"fc-225-114a0d","poly":"cardio","fiche":"225","front":"AAA : quel seuil chirurgical donne l'item 221 ?","back":"**55 mm** (**50 mm chez la femme**) ou croissance **≥ 5 mm/an**.","prio":"P1","sec":"s15"},{"id":"fc-225-1b0bc4","poly":"cardio","fiche":"225","front":"AAA asymptomatique : quelles options de traitement ?","back":"**Chirurgie à ciel ouvert** (mise à plat-greffe) ou **endoprothèse** par voie endovasculaire.","prio":"P2","sec":"s15"},{"id":"fc-225-34e48e","poly":"cardio","fiche":"225","front":"Endoprothèse aortique : par quelle voie et chez qui ?","back":"Par l'**artère fémorale** ; patients à **haut risque chirurgical** si anatomie favorable.","prio":"P3","sec":"s15"},{"id":"fc-225-b10f5e","poly":"cardio","fiche":"225","front":"Douleur abdominale ou lombaire chez un porteur d'AAA : que craindre ?","back":"Une **fissuration ou rupture** : **urgence vitale**.","prio":"P1","sec":"s16"},{"id":"fc-225-ec5a0f","poly":"cardio","fiche":"225","front":"AAA rompu ou fissuré : où adresser le patient ?","back":"**En urgence** dans un **centre spécialisé de chirurgie vasculaire**.","prio":"P1","sec":"s16"},{"id":"fc-225-8c8198","poly":"cardio","fiche":"225","front":"AAA fissuré : quel examen avant le traitement ?","back":"Un **scanner** abdominal (aucune autre imagerie ne doit retarder en cas de choc).","prio":"P1","sec":"s16"},{"id":"fc-225-8e29bc","poly":"cardio","fiche":"225","front":"AAA rompu : quelles options thérapeutiques en urgence ?","back":"**Chirurgie** ou **endoprothèse**.","prio":"P3","sec":"s16"},{"id":"fc-225-3075e6","poly":"cardio","fiche":"225","front":"Rupture intrapéritonéale d'un AAA : quel tableau ?","back":"Tableau habituellement **cataclysmique**, sans possibilité d'intervenir à temps.","prio":"P2","sec":"s16"},{"id":"fc-225-9a37d3","poly":"cardio","fiche":"225","front":"Ischémie aiguë de membre par embolie partie d'un AAA : quel ordre de traitement ?","back":"Revasculariser le membre **en urgence**, la cure de l'AAA vient **ensuite**.","prio":"P3","sec":"s16"},{"id":"fc-225-1f6d94","poly":"cardio","fiche":"225","front":"Après chirurgie conventionnelle d'AAA : que surveiller et comment ?","back":"**Échodoppler** à long terme : **faux anévrismes anastomotiques**.","prio":"P2","sec":"s17"},{"id":"fc-225-b8ede1","poly":"cardio","fiche":"225","front":"Après endoprothèse aortique : quelle complication impose une imagerie au long cours ?","back":"Les **endofuites** (pression persistante dans le sac → évolution, voire rupture).","prio":"P2","sec":"s17"},{"id":"fc-225-ebb6aa","poly":"cardio","fiche":"225","front":"Prothèse artérielle : quelle prévention lors d'un acte à risque bactérien ?","back":"Une **antibioprophylaxie** (risque d'infection de prothèse lors d'une bactériémie).","prio":"P3","sec":"s17"},{"id":"fc-225-e8a18d","poly":"cardio","fiche":"225","front":"Athérome aortique : quels sièges préférentiels ?","back":"**Bifurcation aortique** et **origine de chaque branche**.","prio":"P2","sec":"s18"},{"id":"fc-225-e9e94c","poly":"cardio","fiche":"225","front":"Plaques aortiques : quelle prévalence à 40-55 ans et quel FDR le plus lié ?","back":"**25 %** des hommes, **20 %** des femmes ; FDR le plus lié : le **tabac**.","prio":"P3","sec":"s18"},{"id":"fc-225-b5841c","poly":"cardio","fiche":"225","front":"Athérome aortique : quelle complication peut-il donner ?","back":"Des **embolies** (cerveau, membres, viscères) ; le plus souvent muet.","prio":"P2","sec":"s18"},{"id":"fc-225-87c18d","poly":"cardio","fiche":"225","front":"Calcifications aortiques asymptomatiques : quelle signification ?","back":"**Marqueur de risque cardiovasculaire** (augmente avec leur étendue).","prio":"P2","sec":"s18"},{"id":"fc-225-583952","poly":"cardio","fiche":"225","front":"Sténose athéromateuse d'une artère rénale : quelle conséquence tensionnelle ?","back":"Activation du **SRAA** → **HTA rénovasculaire** (HTA secondaire).","prio":"P2","sec":"s18"},{"id":"fc-225-01fd0b","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique : quel symptôme typique ?","back":"**Angor digestif** : douleurs abdominales **après les repas**.","prio":"P1","sec":"s18"},{"id":"fc-225-fefbac","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique grave : quel retentissement ?","back":"Altération de l'état général et **amaigrissement** (peur de manger).","prio":"P2","sec":"s18"},{"id":"fc-225-f3eaf7","poly":"cardio","fiche":"225","front":"Ischémie mésentérique chronique : quel examen pour confirmer la sténose ?","back":"**Échodoppler des artères digestives** (ou angioscanner, angio-IRM).","prio":"P3","sec":"s18"},{"id":"fc-225-6df74a","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quelle triade évoque le diagnostic ?","back":"Douleur aiguë **pauvre en signes physiques** ; **vidange digestive accélérée** ; indices d'**embolie** (FA).","prio":"P1","sec":"s18"},{"id":"fc-225-7139f0","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quelle gravité ?","back":"**Urgence vitale chirurgicale** : pronostic lié à la rapidité de prise en charge.","prio":"P1","sec":"s18"},{"id":"fc-225-1f54d2","poly":"cardio","fiche":"225","front":"Ischémie mésentérique aiguë : quel mécanisme ?","back":"Occlusion **brutale** d'artère(s) digestive(s) par **thrombose in situ ou embolie** ; infarctus rare grâce aux collatérales.","prio":"P2","sec":"s18"},{"id":"fc-226-f8fb89","poly":"cardio","fiche":"226","front":"TVP et EP : quelle relation entre ces deux entités ?","back":"Deux présentations d'une **même maladie** : la **MTEV**, avec les mêmes facteurs favorisants.","prio":"P1","sec":"s1"},{"id":"fc-226-ec5a9c","poly":"cardio","fiche":"226","front":"EP : dans quelle proportion est-elle secondaire à une TVP ?","back":"Dans **70 %** des cas.","prio":"P1","sec":"s1"},{"id":"fc-226-f5b7c9","poly":"cardio","fiche":"226","front":"TVP proximale : quelle définition ?","back":"Atteinte de la veine **poplitée**, fémorale, iliaque ou cave (sus-poplitée).","prio":"P1","sec":"s1"},{"id":"fc-226-b3775c","poly":"cardio","fiche":"226","front":"TVP distale : quelles veines sont concernées ?","back":"Veines **jambières** (tibiales postérieures, fibulaires) et **surales** (soléaires, gastrocnémiennes).","prio":"P1","sec":"s1"},{"id":"fc-226-b04ac9","poly":"cardio","fiche":"226","front":"TVP poplitée : est-elle proximale ou distale ?","back":"**Proximale**.","prio":"P1","sec":"s1"},{"id":"fc-226-419bbd","poly":"cardio","fiche":"226","front":"TVP proximale vs distale : laquelle expose le plus à l'EP ?","back":"La TVP **proximale** (risque d'EP beaucoup plus important).","prio":"P1","sec":"s1"},{"id":"fc-226-c83e43","poly":"cardio","fiche":"226","front":"TVP distale mise en évidence : faut-il l'anticoaguler ?","back":"**Oui**, dès qu'elle est mise en évidence, même si son dépistage et son traitement sont discutés.","prio":"P1","sec":"s1"},{"id":"fc-226-e91778","poly":"cardio","fiche":"226","front":"EP grave ou à haut risque : quelle définition ?","back":"Choc ou hypotension : **PAS < 90 mmHg** ou **baisse > 40 mmHg pendant > 15 min**, hors cause rythmique, hypovolémique ou septique.","prio":"P1","sec":"s1"},{"id":"fc-226-8a3f8c","poly":"cardio","fiche":"226","front":"EP à haut risque : quelle mortalité ?","back":"**> 15 %**.","prio":"P1","sec":"s1"},{"id":"fc-226-7b0c93","poly":"cardio","fiche":"226","front":"TVP : quels sont les buts du traitement ?","back":"Éviter l'**EP** (précoce) et le **syndrome post-thrombotique** (tardif).","prio":"P2","sec":"s1"},{"id":"fc-226-7f472e","poly":"cardio","fiche":"226","front":"EP : quels sont les buts du traitement ?","back":"Baisser **mortalité** et morbidité, le risque de **cœur pulmonaire postembolique** et de **récidive**.","prio":"P2","sec":"s1"},{"id":"fc-226-0cc004","poly":"cardio","fiche":"226","front":"TVP proximale : environ quelle part a une EP asymptomatique visible à l'angioscanner ?","back":"Environ **la moitié**.","prio":"P3","sec":"s1"},{"id":"fc-226-c153a5","poly":"cardio","fiche":"226","front":"TVP distales asymptomatiques postopératoires : quelle part s'étend aux veines proximales ?","back":"Environ **25 %**.","prio":"P2","sec":"s1"},{"id":"fc-226-c4b6b2","poly":"cardio","fiche":"226","front":"TVP distale vs proximale : quel risque de récidive ?","back":"La TVP distale récidive **2 fois moins**.","prio":"P3","sec":"s1"},{"id":"fc-226-0981d0","poly":"cardio","fiche":"226","front":"TVP proximale : quelle part est symptomatique ?","back":"**80 %**, avec forte probabilité d'EP associée.","prio":"P3","sec":"s1"},{"id":"fc-226-25a6c4","poly":"cardio","fiche":"226","front":"EP : quand survient-elle par rapport au début de la TVP ?","back":"Dans les **3 à 7 jours**.","prio":"P2","sec":"s1"},{"id":"fc-226-99f0f4","poly":"cardio","fiche":"226","front":"EP : quelle part tue dans l'heure ?","back":"Près de **10 %**.","prio":"P2","sec":"s1"},{"id":"fc-226-1ae438","poly":"cardio","fiche":"226","front":"EP : quelle fréquence de choc et de dysfonction VD ?","back":"Choc : **5-10 %** des EP ; dysfonction VD : **1 fois sur 2**.","prio":"P3","sec":"s1"},{"id":"fc-226-3fee99","poly":"cardio","fiche":"226","front":"MTEV symptomatique sans anticoagulant : quel risque de récidive à 3 mois ?","back":"**50 %**.","prio":"P1","sec":"s1"},{"id":"fc-226-bc4942","poly":"cardio","fiche":"226","front":"MTEV : quel risque de récidive à 1 an selon qu'elle est provoquée ou non ?","back":"**9 %** si non provoquée ; **3 %** si provoquée.","prio":"P2","sec":"s1"},{"id":"fc-226-763047","poly":"cardio","fiche":"226","front":"Récidive de MTEV : sous quelle forme survient-elle souvent ?","back":"Souvent **sous la même forme** que le 1er épisode (TVP ou EP).","prio":"P3","sec":"s1"},{"id":"fc-226-77ad00","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quand apparaît-il en moyenne ?","back":"Dans les **2 premières années**.","prio":"P3","sec":"s1"},{"id":"fc-226-bc7930","poly":"cardio","fiche":"226","front":"Contention dès la phase initiale d'une TVP : quel effet sur le syndrome post-thrombotique ?","back":"Gardée **au moins 3 mois**, elle divise son risque par **2**.","prio":"P3","sec":"s1"},{"id":"fc-226-6b9625","poly":"cardio","fiche":"226","front":"Triade de Virchow : quels éléments ?","back":"**Stase** veineuse, **lésion** pariétale, **anomalie de l'hémostase**.","prio":"P2","sec":"s1"},{"id":"fc-226-267e4c","poly":"cardio","fiche":"226","front":"EP : à partir de quelle obstruction du lit artériel apparaît le retentissement hémodynamique ?","back":"**30 à 50 %** du lit artériel pulmonaire.","prio":"P3","sec":"s1"},{"id":"fc-226-9f9746","poly":"cardio","fiche":"226","front":"EP grave : quel mécanisme peut aboutir au décès secondaire dans les 24-48 h ?","back":"**Ischémie du VD** (besoins accrus en O₂, perfusion diminuée), ± nouvelles embolies.","prio":"P3","sec":"s1"},{"id":"fc-226-a57d60","poly":"cardio","fiche":"226","front":"EP : quelles conséquences des petites embolies distales ?","back":"**Hémoptysie**, **épanchement pleural**, voire **infarctus pulmonaire** (pas d'effet hémodynamique).","prio":"P3","sec":"s1"},{"id":"fc-226-d3aa1a","poly":"cardio","fiche":"226","front":"MTEV : à quelle question pratique répond le classement des facteurs de risque ?","back":"**Combien de temps traiter** (provoquée ou non).","prio":"P2","sec":"s2"},{"id":"fc-226-49b829","poly":"cardio","fiche":"226","front":"MTEV provoquée vs non provoquée : quelle différence ?","back":"Provoquée : facteur **transitoire** ; non provoquée : facteur **persistant** ou absent (risque de récidive plus élevé).","prio":"P1","sec":"s2"},{"id":"fc-226-b42dc6","poly":"cardio","fiche":"226","front":"Facteurs temporaires majeurs de MTEV (3 derniers mois) : lesquels ?","back":"Chirurgie sous AG **> 30 min**, **fracture** d'un MI, immobilisation **> 3 jours** ; + œstroprogestatifs, grossesse, post-partum, THM.","prio":"P1","sec":"s2"},{"id":"fc-226-2f330a","poly":"cardio","fiche":"226","front":"Facteurs temporaires mineurs de MTEV (2 derniers mois) : lesquels ?","back":"Chirurgie sous AG **< 30 min**, immobilisation **< 3 jours**, traumatisme non plâtré, **voyage > 6 h**.","prio":"P2","sec":"s2"},{"id":"fc-226-ee2f6c","poly":"cardio","fiche":"226","front":"Facteurs permanents de MTEV : lesquels ?","back":"**Cancer actif** ; maladies inflammatoires chroniques **digestives ou articulaires** (Crohn, RCH).","prio":"P1","sec":"s2"},{"id":"fc-226-d7f72d","poly":"cardio","fiche":"226","front":"Après une chirurgie : combien de temps dure le risque de MTEV ?","back":"**Élevé 2 semaines**, reste haut **2 à 3 mois**.","prio":"P2","sec":"s2"},{"id":"fc-226-a962b4","poly":"cardio","fiche":"226","front":"Chirurgies les plus à risque de MTEV : lesquelles ?","back":"**Orthopédie** (prothèse de hanche ou genou, fracture de hanche, plâtre), polytraumatisme, lésion médullaire, chirurgie majeure avec cancer.","prio":"P2","sec":"s2"},{"id":"fc-226-efd508","poly":"cardio","fiche":"226","front":"Thrombophilies constitutionnelles : lesquelles ?","back":"Mutations des **facteurs II et V** ; déficits en **protéine C**, **protéine S**, **antithrombine**.","prio":"P1","sec":"s2"},{"id":"fc-226-06eabb","poly":"cardio","fiche":"226","front":"Thrombophilie acquise : laquelle citer ?","back":"Le **syndrome des antiphospholipides**.","prio":"P2","sec":"s2"},{"id":"fc-226-e423f3","poly":"cardio","fiche":"226","front":"TVP iatrogène : quel matériel en est responsable ?","back":"Les **cathéters veineux profonds**.","prio":"P3","sec":"s2"},{"id":"fc-226-ef2710","poly":"cardio","fiche":"226","front":"TVP provoquée : quelle définition opérationnelle ?","back":"**Chirurgie ou fracture des MI dans les 3 mois**, ou **immobilisation > 3 jours**.","prio":"P1","sec":"s2"},{"id":"fc-226-e96ec1","poly":"cardio","fiche":"226","front":"TVP non provoquée : quelle conséquence diagnostique ?","back":"Un **bilan à visée étiologique** est nécessaire.","prio":"P1","sec":"s2"},{"id":"fc-226-3b21f7","poly":"cardio","fiche":"226","front":"TVP : sur quoi doit reposer le diagnostic ?","back":"Sur une **méthode objective** (la clinique ne fait qu'orienter).","prio":"P1","sec":"s3"},{"id":"fc-226-01fb9e","poly":"cardio","fiche":"226","front":"TVP : quels signes cliniques sont évocateurs ?","back":"Douleur du MI, **œdème unilatéral** (écart > 3 cm), signes inflammatoires, veines superficielles dilatées.","prio":"P1","sec":"s3"},{"id":"fc-226-3976c7","poly":"cardio","fiche":"226","front":"TVP : quel tableau clinique est le plus évocateur ?","back":"La **phlegmatia alba dolens**, typiquement unilatérale ou asymétrique, surtout si installation brutale.","prio":"P2","sec":"s3"},{"id":"fc-226-b925ed","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : quel item retire des points ?","back":"**Autre diagnostic** au moins aussi probable : **−2**.","prio":"P1","sec":"s3"},{"id":"fc-226-f3fbaa","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : comment lire le résultat ?","back":"**0** = faible (≈ 3 %) ; **1-2** = intermédiaire (≈ 17 %) ; **≥ 3** = forte (≈ 75 %).","prio":"P1","sec":"s3"},{"id":"fc-226-d4c791","poly":"cardio","fiche":"226","front":"Score de Wells de la TVP : citer des items à +1.","back":"Plâtre/paralysie, chirurgie < 4 sem ou alitement > 3 j, **cancer**, **ATCD de TVP**, mollet > 3 cm, œdème de tout le membre...","prio":"P2","sec":"s3"},{"id":"fc-226-5383be","poly":"cardio","fiche":"226","front":"Score de Wells : chez quels patients est-il valable ?","back":"Patient **hospitalisé comme ambulatoire** ; calculé **avant** tout examen.","prio":"P2","sec":"s3"},{"id":"fc-226-acf1da","poly":"cardio","fiche":"226","front":"D-dimères : quelle technique de dosage préconiser ?","back":"Technique **quantitative, très sensible et validée** (ELISA la plus efficace).","prio":"P2","sec":"s3"},{"id":"fc-226-0efaae","poly":"cardio","fiche":"226","front":"D-dimères ELISA dans la TVP : quelles performances ?","back":"Sensibilité **> 95 %**, VPN **> 95 %** ; seuil **500 µg/L**.","prio":"P1","sec":"s3"},{"id":"fc-226-ef8fc8","poly":"cardio","fiche":"226","front":"D-dimères : quel est leur rôle diagnostique ?","back":"**Éliminer** la TVP (peu spécifiques : positifs → échodoppler).","prio":"P1","sec":"s3"},{"id":"fc-226-cc11b9","poly":"cardio","fiche":"226","front":"D-dimères : quelles situations les élèvent en dehors de la MTEV ?","back":"**Âge**, inflammation, **cancer**, traumatisme, hématome, **postopératoire**, **grossesse**, post-partum.","prio":"P1","sec":"s3"},{"id":"fc-226-ebea45","poly":"cardio","fiche":"226","front":"TVP : quel est l'examen de 1re intention pour confirmer ou éliminer ?","back":"L'**échodoppler veineux** des MI (sensibilité et spécificité **> 95 %**).","prio":"P1","sec":"s3"},{"id":"fc-226-4757ae","poly":"cardio","fiche":"226","front":"Échodoppler veineux : quelle limite principale ?","back":"**Opérateur-dépendant** : appareil adapté et **opérateur expérimenté** requis.","prio":"P2","sec":"s3"},{"id":"fc-226-901ea2","poly":"cardio","fiche":"226","front":"Échodoppler : quels signes affirment une TVP ?","back":"**Thrombus vu directement**, veine **incompressible** sous la sonde, signal doppler diminué ou aboli.","prio":"P1","sec":"s3"},{"id":"fc-226-c58659","poly":"cardio","fiche":"226","front":"Phlébographie dans la TVP : quelle place ?","back":"**N'est plus utilisée**.","prio":"P2","sec":"s3"},{"id":"fc-226-eb44d7","poly":"cardio","fiche":"226","front":"Angioscanner dans la TVP : quand le faire ?","back":"Pour compléter l'échodoppler à l'étage **abdominopelvien** quand il ne conclut pas.","prio":"P3","sec":"s3"},{"id":"fc-226-de41bb","poly":"cardio","fiche":"226","front":"Suspicion de TVP : quand ne pas doser les D-dimères ?","back":"Âge **≥ 80 ans**, **cancer**, ou **chirurgie < 30 jours** : échodoppler directement.","prio":"P1","sec":"s3"},{"id":"fc-226-ee8ccf","poly":"cardio","fiche":"226","front":"Suspicion de TVP avec D-dimères négatifs : que conclure ?","back":"TVP **éliminée** : chercher un autre diagnostic.","prio":"P1","sec":"s3"},{"id":"fc-226-217f4d","poly":"cardio","fiche":"226","front":"Suspicion de TVP : dans quel délai réaliser l'échodoppler ?","back":"Dans les **24-48 h** (en urgence si possible).","prio":"P1","sec":"s3"},{"id":"fc-226-f1e566","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité forte avec échodoppler normal : quelle conduite ?","back":"Surveillance ± anticoagulant curatif et contention ± **nouvel échodoppler à 48 h**.","prio":"P2","sec":"s3"},{"id":"fc-226-11cda4","poly":"cardio","fiche":"226","front":"EP : devant quels symptômes faut-il toujours l'évoquer ?","back":"**Dyspnée** aiguë ou récente, **malaise ou syncope**, **douleur thoracique**.","prio":"P1","sec":"s4"},{"id":"fc-226-61877d","poly":"cardio","fiche":"226","front":"Suspicion d'EP : quels examens d'orientation sont indispensables ?","back":"**Radiographie thoracique**, **gazométrie artérielle**, **ECG**.","prio":"P1","sec":"s4"},{"id":"fc-226-a0235a","poly":"cardio","fiche":"226","front":"EP : quelle douleur thoracique est typique ?","back":"Douleur **pleurale** (point de côté brutal).","prio":"P2","sec":"s4"},{"id":"fc-226-ca333b","poly":"cardio","fiche":"226","front":"EP : que traduit une syncope ?","back":"Une **forte chute du débit systémique** (rare).","prio":"P2","sec":"s4"},{"id":"fc-226-505a0c","poly":"cardio","fiche":"226","front":"EP : quelle part est spontanée (idiopathique) ?","back":"**20 à 30 %**.","prio":"P3","sec":"s4"},{"id":"fc-226-ab7c84","poly":"cardio","fiche":"226","front":"EP : les signes de TVP sont-ils fréquents à l'examen ?","back":"**Non** : absents dans **deux tiers** des cas ; TVP symptomatique < 1 fois sur 4.","prio":"P2","sec":"s4"},{"id":"fc-226-727737","poly":"cardio","fiche":"226","front":"EP : que montre la radiographie thoracique et à quoi sert-elle ?","back":"Anomalies **aspécifiques** ; sert surtout à **éliminer une autre cause** ; **normale, elle n'élimine pas** l'EP.","prio":"P1","sec":"s4"},{"id":"fc-226-2be192","poly":"cardio","fiche":"226","front":"EP : quelle anomalie gazométrique typique ?","back":"**Hypoxémie-hypocapnie** (normale dans **20 %** des cas).","prio":"P1","sec":"s4"},{"id":"fc-226-7baf06","poly":"cardio","fiche":"226","front":"EP : quand faire encore une gazométrie artérielle ?","back":"Si **saturation < 90 %** en air ambiant.","prio":"P3","sec":"s4"},{"id":"fc-226-07a0b9","poly":"cardio","fiche":"226","front":"EP : quels signes ECG de souffrance VD ?","back":"ECG **normal** ou simple **tachycardie sinusale** possibles ; souffrance VD : **S1Q3**, **BBD**, arythmie supraventriculaire, **T négatives de V1 à V4**.","prio":"P1","sec":"s4"},{"id":"fc-226-a5e7c8","poly":"cardio","fiche":"226","front":"EP : quel piège ECG peut faire évoquer un SCA ?","back":"Les **T négatives de V1 à V4** (ischémie du VD).","prio":"P1","sec":"s4"},{"id":"fc-226-773034","poly":"cardio","fiche":"226","front":"Scores de probabilité d'EP : quelles probabilités réelles ?","back":"≈ **10 %** si faible ; **30 %** si modérée ; **65 %** si forte.","prio":"P3","sec":"s4"},{"id":"fc-226-42b43a","poly":"cardio","fiche":"226","front":"Scores de probabilité d'EP : lesquels utiliser ?","back":"**Genève révisé** et **Wells simplifié**.","prio":"P1","sec":"s4"},{"id":"fc-226-990332","poly":"cardio","fiche":"226","front":"Wells simplifié de l'EP : à partir de quel score l'EP est-elle probable ?","back":"**≥ 2** (peu probable : 0-1).","prio":"P2","sec":"s4"},{"id":"fc-226-dc9cd9","poly":"cardio","fiche":"226","front":"Genève révisé : quels seuils en 3 niveaux ?","back":"Faible **0-1** ; intermédiaire **2-4** ; forte **≥ 5**.","prio":"P3","sec":"s4"},{"id":"fc-226-4b2d38","poly":"cardio","fiche":"226","front":"EP : que signifient des D-dimères normaux ?","back":"MTEV **très peu probable** (forte VPN).","prio":"P1","sec":"s5"},{"id":"fc-226-aba85f","poly":"cardio","fiche":"226","front":"EP : quelle spécificité des D-dimères ELISA ?","back":"**40 %** (sensibilité > 95 %).","prio":"P3","sec":"s5"},{"id":"fc-226-8e0276","poly":"cardio","fiche":"226","front":"EP : quel seuil de D-dimères après 50 ans ?","back":"**Âge × 10** µg/L (si probabilité faible ou intermédiaire).","prio":"P1","sec":"s5"},{"id":"fc-226-be6752","poly":"cardio","fiche":"226","front":"Suspicion d'EP en probabilité forte : faut-il doser les D-dimères ?","back":"**Non** : **angioscanner d'emblée**.","prio":"P1","sec":"s5"},{"id":"fc-226-cab89c","poly":"cardio","fiche":"226","front":"EP : quel est l'examen le plus performant ?","back":"L'**angioscanner pulmonaire** multicoupe.","prio":"P1","sec":"s5"},{"id":"fc-226-856cdb","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire : quelles performances diagnostiques ?","back":"Sensibilité **83 %**, spécificité **> 90 %** (examen le plus performant).","prio":"P2","sec":"s5"},{"id":"fc-226-2334b9","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire négatif : quand exclut-il l'EP ?","back":"Si la probabilité clinique est **faible ou intermédiaire**.","prio":"P1","sec":"s5"},{"id":"fc-226-e7cff3","poly":"cardio","fiche":"226","front":"Probabilité forte d'EP et angioscanner négatif : quelle conduite ?","back":"Faire un **autre examen** (scintigraphie, voire angiographie) ou pas de traitement.","prio":"P2","sec":"s5"},{"id":"fc-226-e75c47","poly":"cardio","fiche":"226","front":"Angioscanner pulmonaire : quelles contre-indications ?","back":"**Insuffisance rénale**, **allergie à l'iode**.","prio":"P2","sec":"s5"},{"id":"fc-226-0ca99d","poly":"cardio","fiche":"226","front":"Suspicion d'EP : quel résultat d'échodoppler veineux suffit à confirmer l'EP ?","back":"Une **TVP proximale**.","prio":"P1","sec":"s5"},{"id":"fc-226-e90366","poly":"cardio","fiche":"226","front":"Suspicion d'EP : une TVP distale ou un échodoppler normal sont-ils concluants ?","back":"**Non** : TVP distale insuffisante ; échodoppler normal **n'élimine pas** l'EP.","prio":"P1","sec":"s5"},{"id":"fc-226-26e811","poly":"cardio","fiche":"226","front":"Scintigraphie V/Q : quel aspect évoque une EP ?","back":"Défaut de **perfusion** avec **ventilation normale** (mismatch).","prio":"P2","sec":"s5"},{"id":"fc-226-538b92","poly":"cardio","fiche":"226","front":"Scintigraphie V/Q : quand exclut-elle l'EP ?","back":"**Normale** + probabilité clinique **faible**.","prio":"P2","sec":"s5"},{"id":"fc-226-b3e151","poly":"cardio","fiche":"226","front":"ETT dans l'EP : quels signes de cœur pulmonaire aigu ?","back":"**VD dilaté**, **septum paradoxal**, hypokinésie VD, pressions pulmonaires élevées.","prio":"P2","sec":"s5"},{"id":"fc-226-445962","poly":"cardio","fiche":"226","front":"EP en choc sans angioscanner possible : quel rôle de l'ETT ?","back":"Une **surcharge droite peut suffire** pour fibrinoliser ; son absence rend l'EP peu probable.","prio":"P1","sec":"s5"},{"id":"fc-226-15ceeb","poly":"cardio","fiche":"226","front":"Suspicion d'EP sans choc, probabilité faible/intermédiaire : quelle stratégie ?","back":"**D-dimères** : négatifs → pas de traitement ; positifs → **angioscanner**.","prio":"P1","sec":"s5"},{"id":"fc-226-1fc7eb","poly":"cardio","fiche":"226","front":"Suspicion d'EP sans choc : que faire si le scanner est impossible ?","back":"**Échodoppler veineux** (TVP proximale = confirmation) et/ou **scintigraphie V/Q**.","prio":"P2","sec":"s5"},{"id":"fc-226-fc89ae","poly":"cardio","fiche":"226","front":"Suspicion d'EP à haut risque, scanner disponible tout de suite : quelle conduite ?","back":"**Angioscanner** : positif → **thrombolyse ou embolectomie** ; négatif → autre cause.","prio":"P1","sec":"s5"},{"id":"fc-226-d792bd","poly":"cardio","fiche":"226","front":"Suspicion d'EP en choc, patient instable avec dysfonction VD à l'ETT : quelle conduite ?","back":"**Thrombolyse ou embolectomie** d'emblée.","prio":"P1","sec":"s5"},{"id":"fc-226-1eb366","poly":"cardio","fiche":"226","front":"Angiographie pulmonaire : quelle place actuelle ?","back":"**N'est plus pratiquée**.","prio":"P3","sec":"s5"},{"id":"fc-226-5c9f53","poly":"cardio","fiche":"226","front":"EP et grossesse : l'angioscanner est-il contre-indiqué ?","back":"**Non** : l'irradiation n'est plus une contre-indication avec les techniques actuelles.","prio":"P2","sec":"s5"},{"id":"fc-226-5575b7","poly":"cardio","fiche":"226","front":"Suspicion d'EP pendant la grossesse : quel examen habituel ?","back":"L'**échodoppler veineux** (les D-dimères peuvent être **faussement positifs**).","prio":"P2","sec":"s5"},{"id":"fc-226-f1a550","poly":"cardio","fiche":"226","front":"EP : quel ordre de questions pour stratifier la gravité ?","back":"1) **Choc/hypotension** ? 2) **sPESI** et **VD** ? 3) **Troponine** si sPESI ≥ 1 ou VD+.","prio":"P1","sec":"s6"},{"id":"fc-226-86d872","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quelle définition ?","back":"Pas de choc ; sPESI ≥ 1 ou VD+, avec **troponine positive et VD+**.","prio":"P1","sec":"s6"},{"id":"fc-226-138613","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire faible : quelle définition ?","back":"Pas de choc ; sPESI ≥ 1 ou VD+, **troponine négative**.","prio":"P1","sec":"s6"},{"id":"fc-226-78ebad","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle définition ?","back":"Pas de choc ; **sPESI = 0** et **VD normal**.","prio":"P1","sec":"s6"},{"id":"fc-226-2ed1f7","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire : quelle mortalité ?","back":"**3 à 15 %**.","prio":"P2","sec":"s6"},{"id":"fc-226-baeb22","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quelle orientation ?","back":"Anticoagulant, **réanimation/USIC**, surveillance ; reperfusion si **détérioration**.","prio":"P1","sec":"s6"},{"id":"fc-226-7f10c0","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire faible : quelle orientation ?","back":"Anticoagulant, **hospitalisation en médecine**.","prio":"P1","sec":"s6"},{"id":"fc-226-962d4a","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle orientation ?","back":"Anticoagulant, **hospitalisation courte ou ambulatoire**.","prio":"P1","sec":"s6"},{"id":"fc-226-1de4fb","poly":"cardio","fiche":"226","front":"sPESI : quels sont les critères (1 point chacun) ?","back":"Âge **> 80 ans**, Sat **< 90 %**, PAS **< 100**, FC **> 110**, **cancer**, **IC ou maladie pulmonaire chronique**.","prio":"P1","sec":"s6"},{"id":"fc-226-f48e40","poly":"cardio","fiche":"226","front":"sPESI : quelle mortalité selon le score ?","back":"**0** → ≈ **1 %** ; **≥ 1** → ≈ **10 %**.","prio":"P2","sec":"s6"},{"id":"fc-226-1800cb","poly":"cardio","fiche":"226","front":"EP : quels marqueurs de dysfonction VD ?","back":"**ETT** (VD dilaté, VD/VG augmenté), **angioscanner** (VD/VG), turgescence jugulaire, ECG.","prio":"P2","sec":"s6"},{"id":"fc-226-cef7d7","poly":"cardio","fiche":"226","front":"EP : quel marqueur biologique d'ischémie du VD ?","back":"La **troponine** T ou I.","prio":"P2","sec":"s6"},{"id":"fc-226-893f7a","poly":"cardio","fiche":"226","front":"EP : que peut montrer l'ETT en plus de la dysfonction VD ?","back":"Un **foramen ovale perméable** (aggrave l'hypoxie) ou un **thrombus** des cavités droites.","prio":"P3","sec":"s6"},{"id":"fc-226-8947f3","poly":"cardio","fiche":"226","front":"EP : quelle est la règle concernant l'hospitalisation ?","back":"**L'hospitalisation reste la règle**.","prio":"P1","sec":"s6"},{"id":"fc-226-d23aea","poly":"cardio","fiche":"226","front":"EP : quand peut-on discuter un traitement ambulatoire ?","back":"**PESI = 0** **et** aucun critère d'hospitalisation de la TVP proximale.","prio":"P1","sec":"s6"},{"id":"fc-226-3eb93a","poly":"cardio","fiche":"226","front":"EP traitée en ambulatoire : quelles conditions ?","back":"**Diagnostic de certitude**, **éducation**, surveillance par **médecin traitant et infirmier**, risques et contexte psychosocial évalués.","prio":"P2","sec":"s6"},{"id":"fc-226-f66f43","poly":"cardio","fiche":"226","front":"Grosse jambe : quels diagnostics différentiels de la TVP ?","back":"Claquage, **kyste synovial**, SPT, insuffisance veineuse, **érysipèle**, lymphangite, lymphœdème, compression, œdème général.","prio":"P2","sec":"s7"},{"id":"fc-226-a85123","poly":"cardio","fiche":"226","front":"Suspicion d'EP avec douleur thoracique : quels diagnostics différentiels ?","back":"**Infarctus**, **péricardite**, **dissection aortique**, **pneumothorax**.","prio":"P2","sec":"s7"},{"id":"fc-226-4542ba","poly":"cardio","fiche":"226","front":"Suspicion d'EP avec dyspnée aiguë : quels diagnostics différentiels ?","back":"**OAP**, crise d'asthme, décompensation de **BPCO**, **pneumopathie**.","prio":"P2","sec":"s7"},{"id":"fc-226-c6a858","poly":"cardio","fiche":"226","front":"Œdème de jambe + D-dimères positifs : le diagnostic de TVP est-il posé ?","back":"**Non** : les D-dimères excluent, l'**imagerie** confirme.","prio":"P1","sec":"s7"},{"id":"fc-226-0be034","poly":"cardio","fiche":"226","front":"MTEV : quand débuter l'anticoagulation avant la confirmation ?","back":"Dès une probabilité **forte ou intermédiaire**, sans risque hémorragique important.","prio":"P1","sec":"s8"},{"id":"fc-226-5ebd2f","poly":"cardio","fiche":"226","front":"MTEV : quel bilan biologique avant le traitement ?","back":"Hémogramme avec **plaquettes**, TP, TCA, fibrinogène, **créatininémie avec DFG**.","prio":"P1","sec":"s8"},{"id":"fc-226-adf4c7","poly":"cardio","fiche":"226","front":"AOD anti-Xa dans la MTEV : quelles molécules et quelles modalités ?","back":"**Rivaroxaban**, **apixaban** : d'emblée, **sans héparine ni relais AVK** ; devenus la **référence**.","prio":"P1","sec":"s8"},{"id":"fc-226-1c52d0","poly":"cardio","fiche":"226","front":"AOD dans la MTEV : quelle contre-indication rénale ?","back":"**DFGe < 30 mL/min**.","prio":"P1","sec":"s8"},{"id":"fc-226-c67a8c","poly":"cardio","fiche":"226","front":"HBPM et fondaparinux : pourquoi les préférer à l'HNF ?","back":"Plus simples, **pas d'adaptation** à un test d'hémostase, **moins de TIH**.","prio":"P2","sec":"s8"},{"id":"fc-226-6b7a8a","poly":"cardio","fiche":"226","front":"HBPM et fondaparinux : quelle contre-indication rénale ?","back":"**DFG < 30 mL/min**.","prio":"P1","sec":"s8"},{"id":"fc-226-7b5594","poly":"cardio","fiche":"226","front":"EP : quelles HBPM ont l'AMM en France ?","back":"**Énoxaparine** et **tinzaparine** seulement.","prio":"P2","sec":"s8"},{"id":"fc-226-e29fe6","poly":"cardio","fiche":"226","front":"MTEV : dans quelles situations l'HNF est-elle recommandée ?","back":"**IR sévère** (< 30 mL/min), patient **instable**, **geste** prévisible, patient **fibrinolysé**, risque hémorragique.","prio":"P1","sec":"s8"},{"id":"fc-226-065854","poly":"cardio","fiche":"226","front":"MTEV sans insuffisance rénale : quelles options anticoagulantes ?","back":"**HBPM + relais AVK immédiat** (chevauchement ≥ 5 j), **ou AOD anti-Xa d'emblée**.","prio":"P1","sec":"s8"},{"id":"fc-226-a0decc","poly":"cardio","fiche":"226","front":"HNF : quand contrôler le TCA ou l'anti-Xa en IV continue ?","back":"**4 h** après le début, puis 4 h après chaque changement de dose.","prio":"P2","sec":"s8"},{"id":"fc-226-1b3a5f","poly":"cardio","fiche":"226","front":"HNF : quelle surveillance des plaquettes ?","back":"**Avant**, puis **2 fois/semaine pendant 21 jours**.","prio":"P1","sec":"s8"},{"id":"fc-226-d624ca","poly":"cardio","fiche":"226","front":"HBPM : quand surveiller les plaquettes ?","back":"Non systématique, sauf : après une **HNF**, MTEV **postopératoire**, nouvel épisode thrombotique, lésion cutanée au point d'injection.","prio":"P2","sec":"s8"},{"id":"fc-226-7575e9","poly":"cardio","fiche":"226","front":"HBPM : quand doser l'anti-Xa ?","back":"Si risque d'accumulation ou de saignement : **IR modérée**, âge élevé, petit poids, obésité.","prio":"P3","sec":"s8"},{"id":"fc-226-57028b","poly":"cardio","fiche":"226","front":"AVK : à quel rythme contrôler l'INR ?","back":"**2 à 3 fois/semaine** à l'initiation, puis toutes les **3 à 4 semaines**.","prio":"P2","sec":"s8"},{"id":"fc-226-c3ad17","poly":"cardio","fiche":"226","front":"TIH : quelle définition biologique ?","back":"Plaquettes **< 150 G/L** ou **baisse de 50 %** par rapport à la valeur avant traitement.","prio":"P1","sec":"s8"},{"id":"fc-226-8bf611","poly":"cardio","fiche":"226","front":"Relais héparine-AVK dans la MTEV : quand débuter l'AVK ?","back":"**Dès le 1er jour** de l'injectable.","prio":"P1","sec":"s8"},{"id":"fc-226-9dea2c","poly":"cardio","fiche":"226","front":"Relais AVK dans la MTEV : quelles doses initiales ?","back":"**Warfarine 5 mg** ou **acénocoumarol 4 mg** (moins chez le sujet âgé).","prio":"P2","sec":"s8"},{"id":"fc-226-9d7c98","poly":"cardio","fiche":"226","front":"Fluindione : peut-on l'initier ?","back":"**Non** : initiation déconseillée (risque d'atteinte rénale **immunoallergique**).","prio":"P2","sec":"s8"},{"id":"fc-226-ccf764","poly":"cardio","fiche":"226","front":"Relais héparine-AVK : quand arrêter l'injectable ?","back":"Après **au moins 5 jours** **et** **2 INR consécutifs > 2** à 24 h d'intervalle.","prio":"P1","sec":"s8"},{"id":"fc-226-c26582","poly":"cardio","fiche":"226","front":"AVK dans la MTEV : quelle INR cible ?","back":"**2,5** (entre **2 et 3**).","prio":"P1","sec":"s8"},{"id":"fc-226-7c3d3d","poly":"cardio","fiche":"226","front":"Compression élastique d'une TVP : quelle classe et quelle pression ?","back":"**Classe 3** : **30 à 40 mmHg** à la cheville.","prio":"P1","sec":"s8"},{"id":"fc-226-32de5d","poly":"cardio","fiche":"226","front":"Compression élastique d'une TVP : quelle durée ?","back":"**Au moins 6 mois** (texte) ; **2 ans** selon les points clés ; plus si symptômes.","prio":"P2","sec":"s8"},{"id":"fc-226-8657c5","poly":"cardio","fiche":"226","front":"Compression veineuse : quelles contre-indications ?","back":"**AOMI avec IPS < 0,6**, microangiopathie diabétique (> 30 mmHg), **phlegmatia caerulea**, **thrombose septique**.","prio":"P1","sec":"s8"},{"id":"fc-226-34e84f","poly":"cardio","fiche":"226","front":"MTEV : faut-il aliter le patient ?","back":"**Non** : lever précoce ; dans l'EP, après **24 h d'anticoagulation efficace**, avec contention.","prio":"P1","sec":"s8"},{"id":"fc-226-2ff113","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité intermédiaire ou forte : quel traitement avant l'échodoppler ?","back":"**Contention + HBPM ou fondaparinux à dose curative**, sans risque hémorragique important.","prio":"P1","sec":"s9"},{"id":"fc-226-8da98f","poly":"cardio","fiche":"226","front":"Suspicion de TVP en probabilité faible : quel traitement avant l'échodoppler ?","back":"**Contention seule** (pas d'anticoagulant).","prio":"P1","sec":"s9"},{"id":"fc-226-a41d52","poly":"cardio","fiche":"226","front":"TVP proximale : quels critères imposent l'hospitalisation ?","back":"Clairance **< 30 mL/min**, pathologie à **risque hémorragique**, **syndrome obstructif sévère** ou TVP **iliocave**, contexte inadapté.","prio":"P1","sec":"s9"},{"id":"fc-226-9388ed","poly":"cardio","fiche":"226","front":"TVP proximale sans critère d'hospitalisation : où traiter ?","back":"En **ambulatoire** (HBPM ou AOD) ou après courte hospitalisation.","prio":"P2","sec":"s9"},{"id":"fc-226-8c351d","poly":"cardio","fiche":"226","front":"TVP proximale : quand discuter une thrombolyse ?","back":"Pas en 1re intention, sauf **syndrome obstructif sévère** ou **phlegmatia caerulea** (sauver le membre).","prio":"P2","sec":"s9"},{"id":"fc-226-0a5533","poly":"cardio","fiche":"226","front":"Rivaroxaban dans la MTEV : quelle posologie ?","back":"**15 mg × 2/j pendant 21 jours**, puis **20 mg × 1/j**.","prio":"P1","sec":"s9"},{"id":"fc-226-ca4779","poly":"cardio","fiche":"226","front":"Apixaban dans la MTEV : quelle posologie ?","back":"**10 mg × 2/j pendant 7 jours**, puis **5 mg × 2/j**.","prio":"P1","sec":"s9"},{"id":"fc-226-c07d55","poly":"cardio","fiche":"226","front":"Énoxaparine curative : quelle posologie ?","back":"**100 UI/kg/12 h** SC (1 mg/kg/12 h).","prio":"P1","sec":"s9"},{"id":"fc-226-d05791","poly":"cardio","fiche":"226","front":"Tinzaparine curative : quelle posologie ?","back":"**175 UI/kg/24 h** SC.","prio":"P1","sec":"s9"},{"id":"fc-226-8e68f5","poly":"cardio","fiche":"226","front":"Fondaparinux curatif : quelle posologie ?","back":"**7,5 mg/24 h** SC pour un poids de 50 à 100 kg.","prio":"P2","sec":"s9"},{"id":"fc-226-ebefce","poly":"cardio","fiche":"226","front":"HNF dans la MTEV : quelle posologie ?","back":"**500 UI/kg/j**, SC ou IV continue, adaptée au TCA ou à l'anti-Xa.","prio":"P2","sec":"s9"},{"id":"fc-226-cadebc","poly":"cardio","fiche":"226","front":"Nadroparine curative : quelles posologies ?","back":"**85 UI/kg/12 h** (Fraxiparine®) ou **171 UI/kg/24 h** (Fraxodi®).","prio":"P3","sec":"s9"},{"id":"fc-226-c0afc0","poly":"cardio","fiche":"226","front":"TVP sous anticoagulant : quand refaire un échodoppler ?","back":"**En fin de traitement** (séquelles) ; pas d'imagerie pendant le traitement.","prio":"P2","sec":"s9"},{"id":"fc-226-b9d5ee","poly":"cardio","fiche":"226","front":"TVP distale symptomatique : quel est le traitement de référence ?","back":"Un **AOD** à dose curative.","prio":"P1","sec":"s10"},{"id":"fc-226-b0c693","poly":"cardio","fiche":"226","front":"TVP distale, 1er épisode avec facteur déclenchant évident : quelle durée ?","back":"**6 semaines**.","prio":"P1","sec":"s10"},{"id":"fc-226-61f368","poly":"cardio","fiche":"226","front":"TVP distale idiopathique, récidivante, avec facteur persistant ou cancer : quelle durée ?","back":"**Au moins 3 mois**.","prio":"P1","sec":"s10"},{"id":"fc-226-380dd3","poly":"cardio","fiche":"226","front":"TVP distale étendue des veines tibiales postérieures ou fibulaires : quelle durée de contention ?","back":"**Au moins 2 ans** (plus si symptômes).","prio":"P2","sec":"s10"},{"id":"fc-226-8cb23e","poly":"cardio","fiche":"226","front":"TVP distale : où la traiter ?","back":"En **ambulatoire** sauf cas particulier, avec lever précoce.","prio":"P2","sec":"s10"},{"id":"fc-226-465cda","poly":"cardio","fiche":"226","front":"HBPM pour une MTEV postopératoire : quelle surveillance particulière ?","back":"Surveiller les **plaquettes** (exception à la règle).","prio":"P2","sec":"s10"},{"id":"fc-226-b5904c","poly":"cardio","fiche":"226","front":"EP à faible risque : quelle mortalité ?","back":"Environ **1 %**.","prio":"P2","sec":"s11"},{"id":"fc-226-d25ab0","poly":"cardio","fiche":"226","front":"EP traitée sous héparine en ambulatoire : de quoi informer le patient ?","back":"Des **signes de TIH**.","prio":"P3","sec":"s11"},{"id":"fc-226-54ba1e","poly":"cardio","fiche":"226","front":"EP à faible risque ou intermédiaire faible : quels anticoagulants ?","back":"**AOD anti-Xa**, ou **énoxaparine/tinzaparine/fondaparinux** avec relais AVK.","prio":"P2","sec":"s11"},{"id":"fc-226-6e2355","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : faut-il fibrinolyser ?","back":"**Non systématiquement** : reperfusion **si détérioration**.","prio":"P1","sec":"s12"},{"id":"fc-226-e643bb","poly":"cardio","fiche":"226","front":"EP à risque intermédiaire haut : quels traitements complémentaires ?","back":"**Oxygène** (voire ventilation), **remplissage et/ou inotropes**, monitorage.","prio":"P2","sec":"s12"},{"id":"fc-226-467f16","poly":"cardio","fiche":"226","front":"EP à haut risque : quel traitement de reperfusion ?","back":"**Fibrinolyse** en l'absence de contre-indication, en réanimation/USIC.","prio":"P1","sec":"s12"},{"id":"fc-226-6d6353","poly":"cardio","fiche":"226","front":"EP à haut risque avec fibrinolyse contre-indiquée ou en échec : quelle option ?","back":"**Embolectomie** chirurgicale en urgence (sous CEC).","prio":"P1","sec":"s12"},{"id":"fc-226-a243c1","poly":"cardio","fiche":"226","front":"EP à haut risque : quel anticoagulant utiliser ?","back":"L'**HNF** (patient instable, fibrinolyse).","prio":"P1","sec":"s12"},{"id":"fc-226-db8d71","poly":"cardio","fiche":"226","front":"Après embolectomie pour EP massive : quel dispositif est suggéré ?","back":"Un **filtre cave**.","prio":"P2","sec":"s12"},{"id":"fc-226-7d56c8","poly":"cardio","fiche":"226","front":"EP grave avec choc : quelle durée d'anticoagulation ?","back":"**Plus de 6 mois, voire au long cours** (1re EP à haut risque non provoquée : non limitée).","prio":"P3","sec":"s12"},{"id":"fc-226-c0b031","poly":"cardio","fiche":"226","front":"HTAP pendant une EP : quel contrôle ?","back":"**ETT-doppler** pour vérifier que la PAP baisse.","prio":"P2","sec":"s12"},{"id":"fc-226-a6ea52","poly":"cardio","fiche":"226","front":"MTEV avec clairance < 30 mL/min : quel anticoagulant ?","back":"L'**HNF**, avec relais AVK dès J1.","prio":"P1","sec":"s13"},{"id":"fc-226-d9c37a","poly":"cardio","fiche":"226","front":"Filtre cave : quelles indications ?","back":"**CI aux anticoagulants** ; **récidive sous traitement bien conduit** ; suites d'**embolectomie** pour EP massive.","prio":"P1","sec":"s13"},{"id":"fc-226-cea0bd","poly":"cardio","fiche":"226","front":"Contre-indication provisoire aux anticoagulants : quel filtre cave ?","back":"Un filtre **temporaire**, à **retirer** dès que la CI disparaît.","prio":"P1","sec":"s13"},{"id":"fc-226-db82d2","poly":"cardio","fiche":"226","front":"Filtre cave laissé en place : quel risque ?","back":"Risque **augmenté de récidive thrombotique**.","prio":"P2","sec":"s13"},{"id":"fc-226-e9a995","poly":"cardio","fiche":"226","front":"Filtre cave permanent : quelle conséquence sur la durée d'anticoagulation ?","back":"Facteur majeur persistant : **plus de 6 mois, voire au long cours**.","prio":"P3","sec":"s13"},{"id":"fc-226-a0fb6e","poly":"cardio","fiche":"226","front":"TVP proximale ou EP : quelle durée minimale d'anticoagulation ?","back":"**3 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-f85d9a","poly":"cardio","fiche":"226","front":"TVP proximale ou EP avec facteur transitoire majeur : quelle durée ?","back":"**3 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-986146","poly":"cardio","fiche":"226","front":"TVP proximale ou EP sans facteur transitoire majeur : quelle durée ?","back":"**6 mois**.","prio":"P2","sec":"s14"},{"id":"fc-226-343e10","poly":"cardio","fiche":"226","front":"MTEV avec facteur majeur persistant ou récidive proximale : quelle durée ?","back":"**Plus de 6 mois**, voire **au long cours**.","prio":"P2","sec":"s14"},{"id":"fc-226-f2036b","poly":"cardio","fiche":"226","front":"MTEV avec cancer : quelle durée d'anticoagulation ?","back":"**Tant que le cancer est actif**.","prio":"P2","sec":"s14"},{"id":"fc-226-44a691","poly":"cardio","fiche":"226","front":"TVP proximale ou EP récidivantes, ou HTP postembolique : quelle durée ?","back":"**Au long cours** (non limitée).","prio":"P2","sec":"s14"},{"id":"fc-226-475b4a","poly":"cardio","fiche":"226","front":"MTEV et SAPL ou HTP-TEC : quel anticoagulant au long cours ?","back":"**AVK (INR 2-3)**, pas d'AOD.","prio":"P2","sec":"s14"},{"id":"fc-226-4a1f3e","poly":"cardio","fiche":"226","front":"Score HERDOO2 : à quoi sert-il ?","back":"Évaluer le **risque de récidive chez la femme** après un 1er épisode non provoqué.","prio":"P3","sec":"s14"},{"id":"fc-226-78e43e","poly":"cardio","fiche":"226","front":"Homme, 1er épisode de MTEV non provoqué sans facteur persistant majeur : quelle durée ?","back":"Risque de récidive **modéré** : **6 mois ou durée non limitée**.","prio":"P3","sec":"s14"},{"id":"fc-226-c115ca","poly":"cardio","fiche":"226","front":"Risque de récidive modéré : quels arguments pour une durée non limitée ?","back":"Facteur persistant mineur, **filtre cave non retirable**, présentation en **EP**, choix du patient.","prio":"P3","sec":"s14"},{"id":"fc-226-6d6a1e","poly":"cardio","fiche":"226","front":"Risque hémorragique élevé : comment adapter la durée d'anticoagulation ?","back":"3-6 mois → **3 mois** ; durée non limitée → **6 mois**, voire 3.","prio":"P3","sec":"s14"},{"id":"fc-226-544e3d","poly":"cardio","fiche":"226","front":"Avant d'arrêter l'anticoagulation après une EP : que faut-il éliminer ?","back":"Une **HTP postembolique**.","prio":"P2","sec":"s14"},{"id":"fc-226-e0be6c","poly":"cardio","fiche":"226","front":"Durée d'anticoagulation : quel élément non médical peut entrer dans la décision ?","back":"La **préférence du patient**.","prio":"P2","sec":"s14"},{"id":"fc-226-1a068a","poly":"cardio","fiche":"226","front":"MTEV sous contraception œstroprogestative : quelle conduite ?","back":"**Arrêt** (devient **contre-indiquée**) ; remplacer par **progestatif continu** ou **DIU**.","prio":"P1","sec":"s15"},{"id":"fc-226-762456","poly":"cardio","fiche":"226","front":"MTEV chez une femme ménopausée sous THM : quelle conduite ?","back":"Le **THM** est **contre-indiqué**.","prio":"P1","sec":"s15"},{"id":"fc-226-01c0e9","poly":"cardio","fiche":"226","front":"MTEV pendant la grossesse : quel anticoagulant ?","back":"Les **HBPM**.","prio":"P1","sec":"s15"},{"id":"fc-226-e70fc4","poly":"cardio","fiche":"226","front":"MTEV liée aux œstroprogestatifs, à la grossesse ou au THM oral : quelle durée ?","back":"Facteurs transitoires majeurs : **3 mois**.","prio":"P3","sec":"s15"},{"id":"fc-226-0ad482","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : est-il systématique après un 1er épisode de MTEV ?","back":"**Non** ; non recommandé non plus après un 1er épisode **après 50 ans**.","prio":"P2","sec":"s16"},{"id":"fc-226-a6de5f","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quelles indications ?","back":"1er épisode non provoqué **< 50 ans** avec ATCD familial au 1er degré ; MTEV **récidivante** ; site **atypique**.","prio":"P2","sec":"s16"},{"id":"fc-226-e143eb","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quels sites de thrombose atypiques le justifient ?","back":"**Splanchnique**, **membre supérieur**, **cérébral** (thrombose non provoquée).","prio":"P3","sec":"s16"},{"id":"fc-226-074a02","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : que doser ?","back":"**Antithrombine**, **protéines C et S** ; mutations **facteur V Leiden** et **facteur II G20210A**.","prio":"P2","sec":"s16"},{"id":"fc-226-ac80c5","poly":"cardio","fiche":"226","front":"Bilan de thrombophilie : quand le réaliser ?","back":"**Entre le 3e et le 6e mois**, et **72 h après l'arrêt d'un AOD** (pas en phase aiguë).","prio":"P2","sec":"s16"},{"id":"fc-226-d6d19e","poly":"cardio","fiche":"226","front":"MTEV : quelle incidence de cancer découvert ?","back":"**6 à 28 %**, surtout dans les **6 à 12 premiers mois**, et si TVP idiopathique ou récidivante.","prio":"P3","sec":"s16"},{"id":"fc-226-1f7186","poly":"cardio","fiche":"226","front":"Recherche d'un cancer après MTEV : quels examens chez l'homme et chez la femme ?","back":"Homme : **PSA** ; femme : examen gynéco, **mammographie**, écho pelvienne ; tous : sang dans les selles, **radio de thorax**.","prio":"P2","sec":"s16"},{"id":"fc-226-ea59ca","poly":"cardio","fiche":"226","front":"Recherche de cancer après MTEV : endoscopies et body-scanner sont-ils systématiques ?","back":"**Non** : seulement s'il y a des signes d'orientation.","prio":"P2","sec":"s16"},{"id":"fc-226-d185f6","poly":"cardio","fiche":"226","front":"Recherche de cancer après MTEV : chez qui surtout ?","back":"**Après 40 ans** ou si le bilan de thrombophilie est négatif ; surveillance clinique **au moins 1 an**.","prio":"P3","sec":"s16"},{"id":"fc-226-54ebfa","poly":"cardio","fiche":"226","front":"MTEV et cancer actif : pourquoi préférer l'HBPM aux AVK ?","back":"AVK **moins efficaces et moins bien tolérés** ; HBPM prolongée : moins de récidives.","prio":"P2","sec":"s17"},{"id":"fc-226-16badf","poly":"cardio","fiche":"226","front":"MTEV et cancer : quand éviter les AOD en 1re intention ?","back":"Cancers **digestifs** et **génito-urinaires** (risque de saignement).","prio":"P2","sec":"s17"},{"id":"fc-226-f27d22","poly":"cardio","fiche":"226","front":"MTEV et cancer : quelles doses d'HBPM ?","back":"**Daltéparine 200 UI/kg/j** 1 mois puis 150 ; **tinzaparine 175 UI/kg/j** ; **énoxaparine 150 UI/kg/j**.","prio":"P3","sec":"s17"},{"id":"fc-226-94987c","poly":"cardio","fiche":"226","front":"MTEV et cancer : quelle durée idéale d'HBPM ?","back":"**3 à 6 mois** ; au-delà, HBPM si cancer traité, sinon **relais AVK**.","prio":"P3","sec":"s17"},{"id":"fc-226-f3f7ce","poly":"cardio","fiche":"226","front":"MTEV et cancer sous HBPM : quand interrompre l'HBPM ?","back":"Thrombopénie post-chimiothérapie **< 50 G/L** (reprise au-dessus).","prio":"P3","sec":"s17"},{"id":"fc-226-b430bb","poly":"cardio","fiche":"226","front":"TVP du membre supérieur : quelle cause la plus fréquente ?","back":"Du **matériel** (cathéter central, sonde de pacemaker).","prio":"P2","sec":"s17"},{"id":"fc-226-5581bf","poly":"cardio","fiche":"226","front":"TVP du membre supérieur : comment la traiter ?","back":"Comme une **TVP des membres inférieurs** (mêmes molécules, doses, surveillance).","prio":"P3","sec":"s17"},{"id":"fc-226-3421b0","poly":"cardio","fiche":"226","front":"Thrombose veineuse superficielle : quel siège habituel et quels signes ?","back":"**Grande veine saphène** ; douleur, rougeur, **cordon induré**.","prio":"P2","sec":"s18"},{"id":"fc-226-14f769","poly":"cardio","fiche":"226","front":"TVS : pourquoi faire un échodoppler ?","back":"Chercher une extension profonde : **TVP associée dans 10 %** des cas.","prio":"P2","sec":"s18"},{"id":"fc-226-5f4778","poly":"cardio","fiche":"226","front":"TVS sur veine saine non variqueuse : que rechercher ?","back":"Une **cause générale** : cancer, Buerger, Behçet, hémopathie, maladie auto-immune, thrombophilie.","prio":"P2","sec":"s18"},{"id":"fc-226-86e838","poly":"cardio","fiche":"226","front":"TVS atteignant la jonction grande saphène-veine fémorale : quel traitement ?","back":"**Anticoagulant à dose curative** ou **chirurgie**.","prio":"P2","sec":"s18"},{"id":"fc-226-153270","poly":"cardio","fiche":"226","front":"TVS sans atteinte de la jonction saphéno-fémorale : quel traitement anticoagulant ?","back":"**Fondaparinux** (ou HBPM) à dose **prophylactique**, **6 semaines** pour le fondaparinux.","prio":"P2","sec":"s18"},{"id":"fc-226-1043a7","poly":"cardio","fiche":"226","front":"TVS : quels traitements ne sont pas recommandés en 1re intention ?","back":"**AINS par voie générale**, anticoagulant **curatif**, chirurgie sans atteinte de la jonction.","prio":"P3","sec":"s18"},{"id":"fc-226-c43d89","poly":"cardio","fiche":"226","front":"TVS : quelle compression à la phase aiguë ?","back":"Compression veineuse, de préférence par **bandage**.","prio":"P3","sec":"s18"},{"id":"fc-226-e9b201","poly":"cardio","fiche":"226","front":"TVS : si un anticoagulant est instauré, quelle durée ?","back":"**7 à 30 jours** (seules durées évaluées).","prio":"P2","sec":"s18"},{"id":"fc-226-09cfdb","poly":"cardio","fiche":"226","front":"EP : quelle complication précoce mortelle ?","back":"Le **choc cardiogénique réfractaire**.","prio":"P1","sec":"s19"},{"id":"fc-226-ec0e18","poly":"cardio","fiche":"226","front":"EP : quelle complication à moyen terme rare mais grave ?","back":"L'**HTP chronique postembolique**.","prio":"P2","sec":"s19"},{"id":"fc-226-859f69","poly":"cardio","fiche":"226","front":"TVP : quelles complications ?","back":"**Récidive**, **syndrome post-thrombotique**, **EP**.","prio":"P2","sec":"s19"},{"id":"fc-226-6c08a3","poly":"cardio","fiche":"226","front":"Après une MTEV : que faire à chaque nouvelle situation à risque ?","back":"**Reprendre la prévention** : la récidive reste toujours possible, surtout si le facteur favorisant est permanent.","prio":"P2","sec":"s19"},{"id":"fc-226-08d384","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quels signes ?","back":"Lourdeur de jambe, **dilatation des veines superficielles**, **œdème** de cheville, dermite ocre, atrophie blanche, **ulcère sus-malléolaire**.","prio":"P3","sec":"s19"},{"id":"fc-226-c85c56","poly":"cardio","fiche":"226","front":"Syndrome post-thrombotique : quel examen de choix ?","back":"L'**échodoppler veineux** (obstruction, reflux).","prio":"P3","sec":"s19"},{"id":"fc-226-4b3bef","poly":"cardio","fiche":"226","front":"HTP chronique postembolique : quel traitement de choix ?","back":"L'**endartériectomie pulmonaire** (équipes entraînées).","prio":"P3","sec":"s19"},{"id":"fc-226-2b2f45","poly":"cardio","fiche":"226","front":"Endartériectomie vs embolectomie pulmonaire : quelle différence d'indication ?","back":"Endartériectomie : **HTP chronique postembolique** ; embolectomie : **EP aiguë grave** en urgence.","prio":"P3","sec":"s19"},{"id":"fc-226-40dc68","poly":"cardio","fiche":"226","front":"MTEV sous anticoagulant : faut-il une imagerie de suivi pendant le traitement ?","back":"**Non**, sauf HTAP au cours de l'EP (ETT-doppler).","prio":"P1","sec":"s19"},{"id":"fc-226-daf6b7","poly":"cardio","fiche":"226","front":"Prévention de la MTEV : sur quoi s'adapte-t-elle ?","back":"Sur le **risque thrombotique**, le **risque hémorragique** et la **fonction rénale**.","prio":"P1","sec":"s20"},{"id":"fc-226-ef0030","poly":"cardio","fiche":"226","front":"Prévention de la MTEV avec risque hémorragique élevé : quelle mesure ?","back":"**Compression seule** (+ mobilisation précoce).","prio":"P1","sec":"s20"},{"id":"fc-226-79fe4b","poly":"cardio","fiche":"226","front":"Prévention de la MTEV : l'aspirine est-elle indiquée ?","back":"**Non**.","prio":"P1","sec":"s20"},{"id":"fc-226-b1fec5","poly":"cardio","fiche":"226","front":"Voyage de plus de 6 h : quelle prévention pour tous ?","back":"Pas de vêtements serrés, bonne **hydratation**, contraction régulière des **mollets**.","prio":"P2","sec":"s20"},{"id":"fc-226-8a5098","poly":"cardio","fiche":"226","front":"Voyage de plus de 6 h avec facteurs prédisposants : quelle prévention ?","back":"Chaussettes de contention **classe 2 ou 3** ± une injection d'**HBPM avant le départ**.","prio":"P2","sec":"s20"},{"id":"fc-226-753444","poly":"cardio","fiche":"226","front":"Prévention de la MTEV en médecine : quelles posologies ?","back":"**Énoxaparine 0,4 mL/24 h SC** ou **fondaparinux 2,5 mg/24 h**.","prio":"P1","sec":"s20"},{"id":"fc-226-837fc4","poly":"cardio","fiche":"226","front":"Prévention de la MTEV après prothèse de hanche : quelle durée ?","back":"**4 à 6 semaines**.","prio":"P1","sec":"s20"},{"id":"fc-226-0be05e","poly":"cardio","fiche":"226","front":"Prévention de la MTEV après prothèse de genou : quelle durée ?","back":"**10-15 jours**.","prio":"P1","sec":"s20"},{"id":"fc-226-bfcb5f","poly":"cardio","fiche":"226","front":"Énoxaparine préventive (points clés) : quelles doses selon le risque ?","back":"**2 000 UI/j** si risque modéré ; **4 000 UI/j** si risque élevé.","prio":"P2","sec":"s20"},{"id":"fc-230-6d0c03","poly":"cardio","fiche":"230","front":"Douleur thoracique aiguë : quelle est la première question à se poser ?","back":"Le patient est-il en **détresse vitale** ? (la description de la douleur passe au second plan).","prio":"P1","sec":"s1"},{"id":"fc-230-7caeaa","poly":"cardio","fiche":"230","front":"Douleur thoracique aiguë : quelles sont les 4 urgences cardiovasculaires à évoquer ?","back":"**PIED** : **P**éricardite, **I**nfarctus (SCA), **E**mbolie pulmonaire, **D**issection aortique.","prio":"P1","sec":"s1"},{"id":"fc-230-af10f9","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle cause digestive exceptionnelle est une urgence thérapeutique ?","back":"La **rupture de l'œsophage**.","prio":"P1","sec":"s1"},{"id":"fc-230-dcf411","poly":"cardio","fiche":"230","front":"Rupture de l'œsophage : quels signes l'évoquent ?","back":"Douleur + **dyspnée**, **emphysème sous-cutané** (crépitation neigeuse), **pneumomédiastin**.","prio":"P1","sec":"s1"},{"id":"fc-230-f9feb9","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle complication grave redouter ?","back":"Un épanchement abondant avec **tamponnade**.","prio":"P2","sec":"s1"},{"id":"fc-230-fd81ed","poly":"cardio","fiche":"230","front":"Douleur thoracique : qu'est-ce qui pèse souvent plus lourd que les détails de la douleur ?","back":"Le **terrain**, l'**âge**, le **contexte** et un **examen soigneux**.","prio":"P2","sec":"s1"},{"id":"fc-230-feb190","poly":"cardio","fiche":"230","front":"Douleur thoracique : quels signes de détresse vitale chercher d'emblée ?","back":"**Collapsus/choc**, **détresse respiratoire**, **signes neurologiques**.","prio":"P1","sec":"s2"},{"id":"fc-230-56f121","poly":"cardio","fiche":"230","front":"Douleur thoracique avec détresse vitale : quelle orientation ?","back":"**Réanimation ou Usic**, **via le Samu**.","prio":"P1","sec":"s2"},{"id":"fc-230-815466","poly":"cardio","fiche":"230","front":"Détresse respiratoire : quels signes ?","back":"Polypnée **> 30/min** ou bradypnée **< 10/min**, **tirage**, sueurs, cyanose, **SpO₂ < 90 %**, encéphalopathie.","prio":"P1","sec":"s2"},{"id":"fc-230-c3bf85","poly":"cardio","fiche":"230","front":"Détresse hémodynamique : quels signes ?","back":"**Arrêt circulatoire**, **état de choc** (hypotension, marbrures, oligurie), cœur pulmonaire, **pouls paradoxal**.","prio":"P1","sec":"s2"},{"id":"fc-230-1ab225","poly":"cardio","fiche":"230","front":"Pouls paradoxal : quelle définition ?","back":"Pouls qui **diminue à l'inspiration** profonde.","prio":"P2","sec":"s2"},{"id":"fc-230-22e264","poly":"cardio","fiche":"230","front":"Arrêt circulatoire : quels signes ?","back":"Patient **inconscient**, pouls **carotidien ou fémoral non perçu**.","prio":"P1","sec":"s2"},{"id":"fc-230-9a8a94","poly":"cardio","fiche":"230","front":"Patient avec douleur thoracique : comment organiser le transfert ?","back":"**Médicalisé, via le 15**.","prio":"P1","sec":"s2"},{"id":"fc-230-4e24c8","poly":"cardio","fiche":"230","front":"Douleur thoracique : pourquoi ne pas appeler le 15 est-il une faute grave ?","back":"Si SCA : **mortalité préhospitalière élevée** (risque de **FV**).","prio":"P1","sec":"s2"},{"id":"fc-230-468555","poly":"cardio","fiche":"230","front":"Suspicion d'urgence cardiovasculaire : quels examens systématiques ?","back":"**ECG 12 dérivations + V3R, V4R, V7, V8, V9**, **radiographie pulmonaire**, **troponine ultrasensible**.","prio":"P1","sec":"s3"},{"id":"fc-230-b7e041","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle notion inacceptable concerne la troponine ?","back":"Doser la troponine **avant** d'avoir réalisé l'**ECG**.","prio":"P1","sec":"s3"},{"id":"fc-230-fdb18e","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelle est la base de la prise en charge ?","back":"**Interrogatoire**, **ECG** et **dosage répété** des troponines ultrasensibles.","prio":"P1","sec":"s3"},{"id":"fc-230-190675","poly":"cardio","fiche":"230","front":"Échocardiographie et scanner thoracique : quelle place dans la douleur thoracique ?","back":"**Souvent** utiles en **2e intention**, mais à faire **en urgence** sur une suspicion d'**EP** (et de dissection).","prio":"P1","sec":"s3"},{"id":"fc-230-e5ba81","poly":"cardio","fiche":"230","front":"SCA : dans quelle proportion clinique et ECG font-ils le diagnostic ?","back":"**Plus de 90 %** des cas.","prio":"P2","sec":"s3"},{"id":"fc-230-6743e9","poly":"cardio","fiche":"230","front":"ECG percritique et troponines normales : excluent-ils des lésions coronariennes ?","back":"**Non**, notamment un **angor instable**.","prio":"P1","sec":"s3"},{"id":"fc-230-eda3d0","poly":"cardio","fiche":"230","front":"Dissection aortique : que montre la radiographie de thorax ?","back":"**Médiastin élargi**, **double contour aortique**, épanchement pleural éventuel.","prio":"P1","sec":"s3"},{"id":"fc-230-cd38f5","poly":"cardio","fiche":"230","front":"SCA : quelle place de la radiographie de thorax ?","back":"Normale, souvent **inutile** sans insuffisance cardiaque.","prio":"P3","sec":"s3"},{"id":"fc-230-066b29","poly":"cardio","fiche":"230","front":"Tamponnade : quels signes ECG et radiographiques ?","back":"**Microvoltage**, parfois **alternance électrique** ; cœur « **en carafe** » si épanchement abondant.","prio":"P1","sec":"s3"},{"id":"fc-230-7b7c51","poly":"cardio","fiche":"230","front":"Coronarographie : quel résultat dans la myopéricardite ?","back":"**Normale**.","prio":"P2","sec":"s3"},{"id":"fc-230-fd521c","poly":"cardio","fiche":"230","front":"Embolie pulmonaire : quels signes ECG ?","back":"**Tachycardie sinusale**, **S1Q3**, **BBD**, ondes **T négatives** dans les précordiales droites (V1, V3).","prio":"P2","sec":"s3"},{"id":"fc-230-179669","poly":"cardio","fiche":"230","front":"SCA : quel terrain et quelles présentations ?","back":"FDR/ATCD coronariens ; douleur de **repos**, angor **de novo** ou **crescendo**.","prio":"P1","sec":"s4"},{"id":"fc-230-231048","poly":"cardio","fiche":"230","front":"SCA : à partir de quelle durée de douleur évoquer un infarctus ?","back":"**Plus de 20 minutes**.","prio":"P1","sec":"s4"},{"id":"fc-230-6206a6","poly":"cardio","fiche":"230","front":"SCA : chez qui les formes atypiques sont-elles fréquentes ?","back":"Chez la **femme** et le **sujet âgé** (douleur de la mandibule à l'ombilic, digestive).","prio":"P1","sec":"s4"},{"id":"fc-230-1ea644","poly":"cardio","fiche":"230","front":"Douleur ischémique : quelles caractéristiques typiques ?","back":"**Constriction**, pesanteur, brûlure ; **rétrosternale** ; irradiations cou, épaules, avant-bras ; déclenchée par l'**effort**.","prio":"P1","sec":"s4"},{"id":"fc-230-59a694","poly":"cardio","fiche":"230","front":"Douleur plutôt non ischémique : quelles caractéristiques ?","back":"**Coup de poignard**, majorée par la **respiration**, punctiforme, provoquée par un mouvement, de quelques secondes.","prio":"P2","sec":"s4"},{"id":"fc-230-184a0a","poly":"cardio","fiche":"230","front":"SCA non compliqué : que montre l'examen clinique ?","back":"Il est **normal** ; il cherche une autre localisation athéromateuse.","prio":"P2","sec":"s4"},{"id":"fc-230-96d49a","poly":"cardio","fiche":"230","front":"Douleur thoracique avec bloc de branche gauche : comment le considérer ?","back":"Comme un **équivalent de SCA ST+**.","prio":"P1","sec":"s4"},{"id":"fc-230-7eee32","poly":"cardio","fiche":"230","front":"Ischémie de la circonflexe : quel piège ECG et quelle conduite ?","back":"**Peut être électriquement muette** : enregistrer **V7, V8, V9**.","prio":"P1","sec":"s4"},{"id":"fc-230-650080","poly":"cardio","fiche":"230","front":"Sous-décalage de ST de V2 à V4 avec douleur prolongée : quelle conduite ?","back":"Occlusion de la **circonflexe** : prise en charge **comme un ST+**.","prio":"P1","sec":"s4"},{"id":"fc-230-fbab97","poly":"cardio","fiche":"230","front":"SCA : quel appareillage implanté peut rendre l'ECG trompeur ?","back":"Un **pacemaker** : l'ECG peut alors être **trompeur**.","prio":"P2","sec":"s4"},{"id":"fc-230-27a0e5","poly":"cardio","fiche":"230","front":"SCA ST+ confirmé à l'ECG : faut-il attendre la troponine ?","back":"**Non** : dosage inutile, la reperfusion se fait **sans attendre** le résultat.","prio":"P1","sec":"s4"},{"id":"fc-230-ed71f4","poly":"cardio","fiche":"230","front":"SCA sans sus-décalage persistant : quand refaire le dosage de troponine ?","back":"**1 ou 2 heures** après H0.","prio":"P1","sec":"s4"},{"id":"fc-230-1c8495","poly":"cardio","fiche":"230","front":"Troponine H0 élevée, ou faible mais en hausse significative : que conclure ?","back":"**SCA ST- à haut risque**.","prio":"P1","sec":"s4"},{"id":"fc-230-1d5999","poly":"cardio","fiche":"230","front":"Troponine faible sans hausse au 2e dosage : quelle conduite ?","back":"Penser à un **diagnostic différentiel** (ou SCA à bas risque) et **poursuivre la surveillance en Usic**.","prio":"P2","sec":"s4"},{"id":"fc-230-653dd9","poly":"cardio","fiche":"230","front":"Infarctus inférieur : quel diagnostic peut-il mimer ?","back":"Une **gastroentérite**.","prio":"P1","sec":"s4"},{"id":"fc-230-f148eb","poly":"cardio","fiche":"230","front":"Dissection aortique : quels facteurs favorisants ?","back":"**HTA ancienne**, **syndrome de Marfan**.","prio":"P1","sec":"s5"},{"id":"fc-230-b5d5df","poly":"cardio","fiche":"230","front":"Dissection aortique : quelle douleur typique ?","back":"Intense, **en déchirement**, irradiant dans le **dos**, **migratrice** vers les lombes ; typiquement sur **poussée hypertensive**.","prio":"P1","sec":"s5"},{"id":"fc-230-d039a5","poly":"cardio","fiche":"230","front":"Dissection aortique : quels signes d'examen ?","back":"**Asymétrie tensionnelle > 20 mmHg**, **pouls aboli**, souffle d'**IA**, **déficit neurologique**.","prio":"P1","sec":"s5"},{"id":"fc-230-5b5f96","poly":"cardio","fiche":"230","front":"Dissection aortique : par quelles complications peut-elle se révéler ?","back":"Ischémie de membre, **AVC**, infarctus **mésentérique**, **tamponnade**, IA aiguë, SCA par dissection coronaire.","prio":"P1","sec":"s5"},{"id":"fc-230-feebd4","poly":"cardio","fiche":"230","front":"Dissection aortique : que montre l'ECG ?","back":"Normal, ou aspect de **SCA** si extension à une coronaire.","prio":"P1","sec":"s5"},{"id":"fc-230-5ebf40","poly":"cardio","fiche":"230","front":"Dissection aortique : les D-dimères sont-ils souvent normaux ?","back":"**Non** : des D-dimères **normaux sont rares** dans une dissection.","prio":"P2","sec":"s5"},{"id":"fc-230-306004","poly":"cardio","fiche":"230","front":"Score de probabilité de dissection : quels groupes et quelle lecture ?","back":"Terrain, douleur, examen (1 point chacun) : **0-1 faible**, **2-3 forte**.","prio":"P3","sec":"s5"},{"id":"fc-230-bf0387","poly":"cardio","fiche":"230","front":"Dissection aortique : quel examen confirme le plus souvent le diagnostic ?","back":"L'**angioscanner thoracique** (notamment si instable ; prépare la chirurgie).","prio":"P2","sec":"s5"},{"id":"fc-230-308177","poly":"cardio","fiche":"230","front":"Dissection aortique : quand réaliser une ETT/ETO ?","back":"**Seulement si l'hémodynamique est stable**.","prio":"P3","sec":"s5"},{"id":"fc-230-64b14b","poly":"cardio","fiche":"230","front":"EP : quel terrain l'évoque ?","back":"**Cancer**, œstroprogestatifs + tabac, **postopératoire**, post-partum, **alitement**, ATCD de MTEV.","prio":"P1","sec":"s6"},{"id":"fc-230-a0dfa0","poly":"cardio","fiche":"230","front":"EP : quelle présentation clinique typique ?","back":"Douleur **basithoracique** avec **dyspnée aiguë**, polypnée, toux, parfois hémoptysie tardive.","prio":"P1","sec":"s6"},{"id":"fc-230-33d2af","poly":"cardio","fiche":"230","front":"EP : quel signe d'examen est un signe de gravité ?","back":"Les signes d'**insuffisance ventriculaire droite**.","prio":"P1","sec":"s6"},{"id":"fc-230-3d15c8","poly":"cardio","fiche":"230","front":"Douleur thoracique + dyspnée + radiographie normale : quel diagnostic évoquer obligatoirement ?","back":"Une **embolie pulmonaire**.","prio":"P1","sec":"s6"},{"id":"fc-230-31067d","poly":"cardio","fiche":"230","front":"Infarctus pulmonaire : quel tableau ?","back":"Douleur **pariétopleurale** fébrile, hémoptysie **noirâtre tardive** ; **bon pronostic**.","prio":"P2","sec":"s6"},{"id":"fc-230-0a5494","poly":"cardio","fiche":"230","front":"Cœur pulmonaire aigu de l'EP : quel tableau ?","back":"**Dyspnée isolée**, défaillance VD ou **collapsus** ; douleur au second plan.","prio":"P2","sec":"s6"},{"id":"fc-230-5f2461","poly":"cardio","fiche":"230","front":"EP à haut risque : quelle définition ?","back":"Choc ou hypotension : PAS **< 90 mmHg** ou baisse **≥ 40 mmHg** > 15 min (hors arythmie, hypovolémie, sepsis).","prio":"P1","sec":"s6"},{"id":"fc-230-8d0bf5","poly":"cardio","fiche":"230","front":"EP à haut risque suspectée : quel examen ?","back":"**Scanner thoracique** s'il est disponible tout de suite, sinon **échocardiographie** (VD dilaté).","prio":"P1","sec":"s6"},{"id":"fc-230-39510b","poly":"cardio","fiche":"230","front":"EP sans choc : quels scores de probabilité ?","back":"**Wells modifié** ou **Genève modifié**.","prio":"P2","sec":"s6"},{"id":"fc-230-44b702","poly":"cardio","fiche":"230","front":"EP en probabilité faible ou modérée : quel premier examen ?","back":"Les **D-dimères** (positifs > 500 µg/L ou > 10 × l'âge après 50 ans → angioscanner).","prio":"P1","sec":"s6"},{"id":"fc-230-fb5a27","poly":"cardio","fiche":"230","front":"D-dimères Elisa négatifs en probabilité modérée d'EP : que conclure ?","back":"**EP éliminée**.","prio":"P1","sec":"s6"},{"id":"fc-230-645a14","poly":"cardio","fiche":"230","front":"EP en probabilité forte : quelle conduite diagnostique ?","back":"D-dimères **inutiles** : **angioscanner d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-230-c34db7","poly":"cardio","fiche":"230","front":"EP en probabilité intermédiaire ou haute : quand débuter l'antithrombotique ?","back":"**Avant même la confirmation**.","prio":"P1","sec":"s6"},{"id":"fc-230-ed52cf","poly":"cardio","fiche":"230","front":"EP : les signes de thrombose veineuse sont-ils constants ?","back":"**Non** : absents dans **un tiers des cas**.","prio":"P3","sec":"s6"},{"id":"fc-230-886831","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel terrain ?","back":"Contexte **viral**, fièvre, ou forme **récidivante**.","prio":"P2","sec":"s7"},{"id":"fc-230-2c2c2e","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelles caractéristiques de la douleur ?","back":"Majorée à l'**inspiration profonde** et au **décubitus**, **calmée par l'antéflexion**.","prio":"P1","sec":"s7"},{"id":"fc-230-a4e72b","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel signe d'auscultation ?","back":"Un **frottement péricardique**, classiquement **fugace et inconstant**.","prio":"P2","sec":"s7"},{"id":"fc-230-0d3de1","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels signes ECG ?","back":"Sus-ST **concave et diffus**, **sans miroir ni onde Q**, **sous-décalage de PQ**, microvoltage.","prio":"P1","sec":"s7"},{"id":"fc-230-7b9c8d","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels examens sont obligatoires ?","back":"**Échocardiographie** et **troponines**.","prio":"P1","sec":"s7"},{"id":"fc-230-a8552e","poly":"cardio","fiche":"230","front":"Péricardite avec échocardiographie normale : que conclure ?","back":"Elle n'est pas exclue (**péricardite sèche**) : savoir **répéter** l'écho.","prio":"P1","sec":"s7"},{"id":"fc-230-763742","poly":"cardio","fiche":"230","front":"Péricardite aiguë : pourquoi est-ce un diagnostic d'élimination ?","back":"C'est l'étiologie **la plus bénigne**, qui peut ressembler à un **SCA**.","prio":"P2","sec":"s7"},{"id":"fc-230-8e6134","poly":"cardio","fiche":"230","front":"Tamponnade : quels signes cliniques ?","back":"**Dyspnée/orthopnée**, **turgescence jugulaire**, reflux hépatojugulaire, tachycardie, **PAS < 90**, **pouls paradoxal**.","prio":"P1","sec":"s7"},{"id":"fc-230-036713","poly":"cardio","fiche":"230","front":"Tamponnade : quelle définition chiffrée du pouls paradoxal ?","back":"PAS d'inspiration **inférieure de 10 mmHg** à la PAS d'expiration.","prio":"P1","sec":"s7"},{"id":"fc-230-6ca308","poly":"cardio","fiche":"230","front":"Tamponnade : quel examen confirme et que montre-t-il ?","back":"L'**échocardiographie** : **collapsus des cavités droites** en expiration, compression du VG par le VD en inspiration.","prio":"P1","sec":"s7"},{"id":"fc-230-facfc1","poly":"cardio","fiche":"230","front":"Pouls paradoxal de la tamponnade : quel mécanisme ?","back":"À l'inspiration, le retour veineux dilate le **VD**, qui **comprime le VG** et fait baisser la PAS.","prio":"P2","sec":"s7"},{"id":"fc-230-d8b896","poly":"cardio","fiche":"230","front":"Myopéricardite : quelle étiologie la plus fréquente ?","back":"**Virale**.","prio":"P2","sec":"s7"},{"id":"fc-230-149bf2","poly":"cardio","fiche":"230","front":"Myopéricardite : pourquoi est-elle trompeuse ?","back":"Elle peut **mimer un SCA**, avec **élévation prolongée des troponines**.","prio":"P1","sec":"s7"},{"id":"fc-230-238f68","poly":"cardio","fiche":"230","front":"Myopéricardite : que montre l'IRM ?","back":"Œdème et **rehaussement tardif sous-épicardique**, **sans systématisation artérielle**.","prio":"P2","sec":"s7"},{"id":"fc-230-627a8c","poly":"cardio","fiche":"230","front":"Myocardite isolée : quel est son principal diagnostic différentiel ?","back":"Le **SCA**.","prio":"P2","sec":"s7"},{"id":"fc-230-e1031e","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : quelle est la survenue typique de l'EP ?","back":"**Progressive**, avec dyspnée (SCA et dissection : brutale).","prio":"P2","sec":"s8"},{"id":"fc-230-1477c2","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : quel terrain pour la péricardite ?","back":"**Sujet jeune**, **contage viral**.","prio":"P2","sec":"s8"},{"id":"fc-230-a9dd47","poly":"cardio","fiche":"230","front":"4 urgences cardiovasculaires : pour laquelle la radiographie de thorax est-elle la plus contributive ?","back":"La **dissection aortique**.","prio":"P2","sec":"s8"},{"id":"fc-230-6f11a8","poly":"cardio","fiche":"230","front":"Douleur de dissection vs douleur de SCA : quel type typique pour chacune ?","back":"Dissection : **coup de poignard**, transfixiante ; SCA : **constrictive**, brûlure.","prio":"P2","sec":"s8"},{"id":"fc-230-f8a969","poly":"cardio","fiche":"230","front":"EP et péricardite : quel siège de douleur typique pour chacune ?","back":"EP : **latéro- ou basithoracique** ; péricardite : **rétrosternale**.","prio":"P3","sec":"s8"},{"id":"fc-230-50e895","poly":"cardio","fiche":"230","front":"Pneumothorax : quels signes cliniques ?","back":"Douleur pleurale, **tympanisme**, **murmure vésiculaire aboli**, parfois dyspnée.","prio":"P1","sec":"s9"},{"id":"fc-230-317c18","poly":"cardio","fiche":"230","front":"Pneumothorax partiel : quelle radiographie demander ?","back":"Un cliché **en expiration**.","prio":"P3","sec":"s9"},{"id":"fc-230-699caa","poly":"cardio","fiche":"230","front":"Épanchement pleural : quels signes cliniques et radiographiques ?","back":"Douleur pleurale, **matité** ; radio : **ligne de Damoiseau**.","prio":"P2","sec":"s9"},{"id":"fc-230-3d3fda","poly":"cardio","fiche":"230","front":"Pneumopathie infectieuse : quels signes ?","back":"**Fièvre**, souffle tubaire et crépitants, opacité avec **bronchogramme aérien**.","prio":"P2","sec":"s9"},{"id":"fc-230-e9dbf8","poly":"cardio","fiche":"230","front":"Spasme œsophagien : quelles caractéristiques ?","back":"Douleur d'allure **angineuse**, déclenchée par la **déglutition**, parfois **calmée par les nitrés**.","prio":"P2","sec":"s9"},{"id":"fc-230-dd3a03","poly":"cardio","fiche":"230","front":"Syndrome de Tietze : quelle définition et quel signe ?","back":"Inflammation du **cartilage sternocostal** ; douleur **reproduite à la palpation**.","prio":"P2","sec":"s9"},{"id":"fc-230-01c31d","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles causes abdominales projetées ?","back":"**Lithiase** vésiculaire, **ulcère**, **pancréatite**, appendicite sous-hépatique, abcès sous-phrénique.","prio":"P2","sec":"s9"},{"id":"fc-230-19492e","poly":"cardio","fiche":"230","front":"Douleur thoracique psychogène : quelle fréquence et quelle prudence ?","back":"**Extrêmement fréquente** mais diagnostic à poser **avec la plus grande prudence**.","prio":"P1","sec":"s9"},{"id":"fc-230-5bad60","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles sont les 6 urgences non cardiaques ?","back":"**Pleurésies/pneumonies**, **pneumothorax**, **pancréatite**, **ulcère compliqué**, **cholécystite**, **douleurs radiculaires**.","prio":"P1","sec":"s9"},{"id":"fc-230-0007a1","poly":"cardio","fiche":"230","front":"Douleur thoracique : quelles causes neurologiques citer ?","back":"**Zona intercostal**, tassement vertébral.","prio":"P3","sec":"s9"},{"id":"fc-230-dcaaa5","poly":"cardio","fiche":"230","front":"Dissection aortique : quel piège abdominal peut-elle donner ?","back":"Une **ischémie mésentérique** (douleur abdominale trompeuse).","prio":"P2","sec":"s9"},{"id":"fc-230-0708a8","poly":"cardio","fiche":"230","front":"Angor stable : quand la douleur est-elle caractéristique ?","back":"**Constrictive**, déclenchée par l'**effort** (ou un repas), cédant à l'arrêt ou à la **trinitrine en 1 à 3 min**.","prio":"P1","sec":"s10"},{"id":"fc-230-65cd62","poly":"cardio","fiche":"230","front":"Angor fonctionnel : quelles causes ?","back":"**RA serré**, **CMH**, **anémie**, **tachycardies** (FA), **hyperthyroïdie**.","prio":"P2","sec":"s10"},{"id":"fc-230-ed8bda","poly":"cardio","fiche":"230","front":"HTAP sévère : pourquoi peut-elle donner une douleur angineuse ?","back":"**Ischémie du VD** quand la pression intra-VD dépasse la pression de perfusion coronaire.","prio":"P3","sec":"s10"},{"id":"fc-230-164b9e","poly":"cardio","fiche":"230","front":"Syndrome coronarien chronique suspecté : quels éléments du score de probabilité clinique ?","back":"**Âge**, **sexe**, **type de douleur/dyspnée** (0-3 points), **nombre de FDR** (0-5).","prio":"P2","sec":"s10"},{"id":"fc-230-dbd051","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie < 5 % : quelle conduite ?","back":"**Aucun** examen complémentaire.","prio":"P1","sec":"s10"},{"id":"fc-230-e0296d","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie modérée (15-50 %) : quel examen ?","back":"**Scanner coronarien** ou **imagerie fonctionnelle**.","prio":"P2","sec":"s10"},{"id":"fc-230-6821cb","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie élevée (> 50-85 %) : quel examen ?","back":"Une **imagerie fonctionnelle**.","prio":"P2","sec":"s10"},{"id":"fc-230-7a0955","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie > 85 % : quel examen ?","back":"Une **coronarographie** diagnostique.","prio":"P1","sec":"s10"},{"id":"fc-230-c681ee","poly":"cardio","fiche":"230","front":"Probabilité clinique de coronaropathie faible (5-15 %) : quelle stratégie ?","back":"**Scanner coronaire d'emblée** ou **réévaluer** la probabilité (ECG, épreuve d'effort, écho, score calcique...).","prio":"P3","sec":"s10"},{"id":"fc-230-b71756","poly":"cardio","fiche":"230","front":"Arrêt circulatoire : quand débuter la réanimation ?","back":"Dès qu'il est **diagnostiqué ou suspecté**, avec appel du 15.","prio":"P1","sec":"s11"},{"id":"fc-230-c9dc48","poly":"cardio","fiche":"230","front":"Massage cardiaque externe : quelles modalités ?","back":"Talon de la main au milieu du thorax, **4 à 5 cm**, **100/min**, relais environ toutes les **2 min**.","prio":"P1","sec":"s11"},{"id":"fc-230-6d69d1","poly":"cardio","fiche":"230","front":"Fibrillation ventriculaire : quel est le seul traitement efficace ?","back":"Le **choc électrique externe** (défibrillation précoce).","prio":"P1","sec":"s11"},{"id":"fc-230-8050dc","poly":"cardio","fiche":"230","front":"Arrêt cardiaque : dans quel délai idéal délivrer le 1er choc ?","back":"Dans les **3 minutes** suivant l'arrêt.","prio":"P1","sec":"s11"},{"id":"fc-230-861e54","poly":"cardio","fiche":"230","front":"Après un choc électrique externe : quand vérifier la reprise circulatoire ?","back":"Après **2 min** de RCP.","prio":"P2","sec":"s11"},{"id":"fc-230-53d1ff","poly":"cardio","fiche":"230","front":"Asystolie : faut-il défibriller ?","back":"**Non** : on **masse**.","prio":"P1","sec":"s11"},{"id":"fc-230-9cf016","poly":"cardio","fiche":"230","front":"Activité électrique sans pouls : quelle conduite ?","back":"**Poursuivre le massage**.","prio":"P2","sec":"s11"},{"id":"fc-230-28f21a","poly":"cardio","fiche":"230","front":"RCP de l'adulte : le bouche-à-bouche est-il recommandé ?","back":"**Non** ; libérer les voies aériennes et limiter les interruptions du massage.","prio":"P2","sec":"s11"},{"id":"fc-230-022d59","poly":"cardio","fiche":"230","front":"RCP médicalisée : quelle posologie d'adrénaline ?","back":"**1 mg toutes les 4 min** IV (ou endotrachéale).","prio":"P2","sec":"s11"},{"id":"fc-230-8f9435","poly":"cardio","fiche":"230","front":"FV/TV réfractaire aux chocs : quel antiarythmique et quelle dose ?","back":"**Amiodarone 300 mg IV** avant le 3e choc, puis **150 mg** si réfractaire ou récidivante.","prio":"P2","sec":"s11"},{"id":"fc-230-5edd6a","poly":"cardio","fiche":"230","front":"RCP : quand donner du sulfate de magnésium ?","back":"**Torsades de pointes** ou suspicion d'**hypomagnésémie** (2 g IVD).","prio":"P3","sec":"s11"},{"id":"fc-230-017fef","poly":"cardio","fiche":"230","front":"Intubation pendant la RCP : combien de temps peut-on interrompre le massage ?","back":"**Pas plus de 30 s**.","prio":"P3","sec":"s11"},{"id":"fc-230-fe74e4","poly":"cardio","fiche":"230","front":"Isoprénaline : quelle contre-indication dans le contexte du SCA ?","back":"La **phase aiguë d'un IDM**.","prio":"P3","sec":"s11"},{"id":"fc-230-b58fb6","poly":"cardio","fiche":"230","front":"Douleur thoracique en urgence : quelle surveillance pendant le transfert ?","back":"**Monitorage ECG continu**.","prio":"P2","sec":"s11"},{"id":"fc-230-be8a3f","poly":"cardio","fiche":"230","front":"SCA ST+ : quels équivalents ECG ?","back":"**BBG**, sus-décalage en **V7-V9**, sous-décalage de **V2 à V4** avec douleur prolongée.","prio":"P1","sec":"s12"},{"id":"fc-230-46455b","poly":"cardio","fiche":"230","front":"Douleur thoracique aux urgences : dans quel délai faire l'ECG ?","back":"Dans les **10 minutes** suivant l'admission.","prio":"P1","sec":"s12"},{"id":"fc-230-2134f8","poly":"cardio","fiche":"230","front":"SCA ST+ : où transférer le patient ?","back":"En **Usic** (risque de FV) ou **directement en salle de coronarographie**.","prio":"P1","sec":"s12"},{"id":"fc-230-9f23ca","poly":"cardio","fiche":"230","front":"SCA ST+ : quand choisir l'angioplastie primaire ?","back":"Si elle est faisable dans les **120 minutes** ; sinon **fibrinolyse immédiate**.","prio":"P1","sec":"s12"},{"id":"fc-230-583ac6","poly":"cardio","fiche":"230","front":"SCA ST+ après fibrinolyse : quelle conduite ?","back":"Échec → **angioplastie de sauvetage** ; succès → **coronarographie dans les 24 h**.","prio":"P1","sec":"s12"},{"id":"fc-230-f144aa","poly":"cardio","fiche":"230","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P1","sec":"s12"},{"id":"fc-230-9dfabe","poly":"cardio","fiche":"230","front":"Angioplastie coronaire : quelle voie d'abord préférer ?","back":"La voie **radiale** (beaucoup moins d'hémorragies).","prio":"P2","sec":"s12"},{"id":"fc-230-e40a81","poly":"cardio","fiche":"230","front":"SCA : quelle posologie d'aspirine ?","back":"**250 mg IVD** puis **75-100 mg/j** per os, au long cours.","prio":"P1","sec":"s12"},{"id":"fc-230-2cc37c","poly":"cardio","fiche":"230","front":"SCA ST+ en angioplastie primaire : quels P2Y12 de 1re intention ?","back":"**Prasugrel** (60 mg puis 10 mg/j) ou **ticagrélor** (180 mg puis 90 mg × 2/j).","prio":"P1","sec":"s12"},{"id":"fc-230-06aac9","poly":"cardio","fiche":"230","front":"Prasugrel : quelles contre-indications et limites ?","back":"**ATCD d'AVC** ; non recommandé après **75 ans** et/ou poids **< 60 kg**.","prio":"P1","sec":"s12"},{"id":"fc-230-d11b01","poly":"cardio","fiche":"230","front":"Ticagrélor : quels effets indésirables ?","back":"**Bradycardie** et **dyspnée**, réversibles à l'arrêt.","prio":"P2","sec":"s12"},{"id":"fc-230-6020eb","poly":"cardio","fiche":"230","front":"Clopidogrel dans le SCA : quelle posologie (hors fibrinolyse) ?","back":"Charge **600 mg** puis **75 mg/j**.","prio":"P2","sec":"s12"},{"id":"fc-230-a21aea","poly":"cardio","fiche":"230","front":"SCA ST+ fibrinolysé : quel P2Y12 utiliser ?","back":"Le **clopidogrel**, seul P2Y12 autorisé (charge 300 mg si < 75 ans, puis 75 mg/j) ; prasugrel et ticagrélor non autorisés.","prio":"P1","sec":"s12"},{"id":"fc-230-bc9b02","poly":"cardio","fiche":"230","front":"SCA : combien de temps poursuivre la bithérapie antiplaquettaire ?","back":"**12 mois**.","prio":"P1","sec":"s12"},{"id":"fc-230-d01564","poly":"cardio","fiche":"230","front":"SCA avec angioplastie immédiate : quel anticoagulant ?","back":"**HNF 70-100 UI/kg IVD** ou **énoxaparine 0,5 mg/kg IVD**.","prio":"P2","sec":"s12"},{"id":"fc-230-05b560","poly":"cardio","fiche":"230","front":"Fibrinolyse : citer des contre-indications absolues.","back":"ATCD d'**AVC hémorragique**, AVC < 6 mois, tumeur cérébrale, traumatisme/hémorragie digestive < 1 mois, **dissection aortique**.","prio":"P1","sec":"s12"},{"id":"fc-230-eff1d3","poly":"cardio","fiche":"230","front":"SCA : quand prescrire de l'oxygène ?","back":"**Uniquement** si SaO₂ **< 90 %** ou PaO₂ **< 60 mmHg** (hyperoxie délétère).","prio":"P1","sec":"s12"},{"id":"fc-230-fa8189","poly":"cardio","fiche":"230","front":"SCA : quelle statine et quelle dose ?","back":"Forte dose : **atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P1","sec":"s12"},{"id":"fc-230-f55f7b","poly":"cardio","fiche":"230","front":"Infarctus du VD : quelle classe médicamenteuse est contre-indiquée ?","back":"Les **vasodilatateurs** (dérivés nitrés).","prio":"P1","sec":"s12"},{"id":"fc-230-736e90","poly":"cardio","fiche":"230","front":"Infarctus du VD : quels signes l'évoquent ?","back":"ST+ **inférieur**, **hypotension**, **poumons clairs**, **turgescence jugulaire**.","prio":"P2","sec":"s12"},{"id":"fc-230-cb0047","poly":"cardio","fiche":"230","front":"SCA : quand utiliser un dérivé nitré IV ?","back":"En cas d'**HTA** ou d'**IC congestive** (dinitrate d'isosorbide 2 mg/h).","prio":"P2","sec":"s12"},{"id":"fc-230-a96ef6","poly":"cardio","fiche":"230","front":"Complication du SCA : BAV nodal de l'IDM inférieur ; quel traitement ?","back":"**Atropine** (+ remplissage si hypotension vagale).","prio":"P2","sec":"s12"},{"id":"fc-230-de52ff","poly":"cardio","fiche":"230","front":"Complication du SCA : BAV infranodal ; quelle conduite ?","back":"Stimulation provisoire, le plus souvent **stimulateur permanent**.","prio":"P2","sec":"s12"},{"id":"fc-230-bf6658","poly":"cardio","fiche":"230","front":"Complication du SCA : choc cardiogénique ; quel traitement ?","back":"**Dobutamine** puis assistance circulatoire **si le terrain le permet** ; chercher une complication mécanique à l'écho.","prio":"P2","sec":"s12"},{"id":"fc-230-c1ea65","poly":"cardio","fiche":"230","front":"Complication du SCA : rupture de pilier mitral ; quelle conduite ?","back":"**Chirurgie urgente**.","prio":"P2","sec":"s12"},{"id":"fc-230-9968ea","poly":"cardio","fiche":"230","front":"Complication du SCA : hémopéricarde par rupture de la paroi libre ; quelle conduite ?","back":"**Chirurgie immédiate**.","prio":"P2","sec":"s12"},{"id":"fc-230-847a26","poly":"cardio","fiche":"230","front":"Complication du SCA : thrombus intra-VG ; quel traitement ?","back":"**Anticoagulation curative**.","prio":"P2","sec":"s12"},{"id":"fc-230-8e62bc","poly":"cardio","fiche":"230","front":"Ondes Q de nécrose sur l'ECG : est-il trop tard pour reperfuser ?","back":"**Non**, pas nécessairement.","prio":"P2","sec":"s12"},{"id":"fc-230-6c685b","poly":"cardio","fiche":"230","front":"SCA ST- à très haut risque : quels critères ?","back":"**Choc**, douleur persistante/récidivante, **IC**, **TV/FV**/arrêt, complication mécanique, ECG dynamique.","prio":"P1","sec":"s13"},{"id":"fc-230-c1f838","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque : quels critères ?","back":"IDM ST- confirmé (ECG/troponine), **GRACE > 140**, sus-ST transitoire, sous-ST dynamique ou T négatives.","prio":"P1","sec":"s13"},{"id":"fc-230-10e9b7","poly":"cardio","fiche":"230","front":"SCA ST- : dans quel délai la coronarographie ?","back":"**< 2 h** si très haut risque ; **< 24 h** si haut risque.","prio":"P1","sec":"s13"},{"id":"fc-230-73df3c","poly":"cardio","fiche":"230","front":"SCA ST- : quand pratiquer un pontage plutôt qu'une angioplastie ?","back":"Lésions du **tronc gauche** ou **tritronculaires complexes**, surtout chez le diabétique.","prio":"P3","sec":"s13"},{"id":"fc-230-4a0a2c","poly":"cardio","fiche":"230","front":"SCA ST- : quand ajouter le P2Y12 ?","back":"Le plus souvent **sur table de coronarographie**, avant l'angioplastie (pas de bithérapie dès l'admission).","prio":"P1","sec":"s13"},{"id":"fc-230-6c53c7","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque : quels anticoagulants en Usic ?","back":"**Énoxaparine 1 mg/kg SC × 2/j** ou **fondaparinux 2,5 mg/j SC** (+ bolus d'HNF en coronarographie).","prio":"P1","sec":"s13"},{"id":"fc-230-42c4f3","poly":"cardio","fiche":"230","front":"SCA ST- à haut risque avec IRC sévère (CI aux HBPM/fondaparinux) : quel anticoagulant ?","back":"**HNF IVSE 400-600 UI/kg/24 h**.","prio":"P2","sec":"s13"},{"id":"fc-230-fe7d1c","poly":"cardio","fiche":"230","front":"SCA ST- avec risque hémorragique élevé : quelle durée de bithérapie antiplaquettaire ?","back":"**1 à 6 mois**.","prio":"P2","sec":"s13"},{"id":"fc-230-0b6285","poly":"cardio","fiche":"230","front":"SCA : citer des facteurs de risque hémorragique.","back":"Âge **> 75 ans**, **sexe féminin**, **IR**, AVC ancien, poids < 65 kg, diathèse hémorragique.","prio":"P3","sec":"s13"},{"id":"fc-230-f07345","poly":"cardio","fiche":"230","front":"SCA ST- : quelle notion inacceptable concerne la gravité ?","back":"Ne pas évaluer la **gravité**, qui fixe le **délai de coronarographie**.","prio":"P2","sec":"s13"},{"id":"fc-230-272507","poly":"cardio","fiche":"230","front":"IEC/ARA2 après SCA : quand surtout les prescrire ?","back":"Surtout si **FEVG ≤ 40 %**, diabète ou IRC.","prio":"P2","sec":"s13"},{"id":"fc-230-7d1eed","poly":"cardio","fiche":"230","front":"Dissection aortique : quel objectif tensionnel ?","back":"**Normaliser** la PA (urgence hypertensive) : **PAS < 120 mmHg** le plus vite possible.","prio":"P2","sec":"s14"},{"id":"fc-230-3affac","poly":"cardio","fiche":"230","front":"Dissection aortique : quelles formes relèvent d'une chirurgie urgente ?","back":"Toutes, **sauf** les formes limitées à l'**aorte descendante** (type B non compliqué).","prio":"P1","sec":"s14"},{"id":"fc-230-921720","poly":"cardio","fiche":"230","front":"Dissection aortique de type A : quelle définition et quelle conduite ?","back":"Atteinte de l'**aorte ascendante** : **chirurgie en urgence**.","prio":"P2","sec":"s14"},{"id":"fc-230-c59a54","poly":"cardio","fiche":"230","front":"Dissection aortique de type B sans complication : quelle conduite ?","back":"**Pas de chirurgie en urgence** (une complication périphérique fait changer).","prio":"P2","sec":"s14"},{"id":"fc-230-5249d7","poly":"cardio","fiche":"230","front":"Dissection aortique : quels antihypertenseurs IV ?","back":"**Urapidil** ou **nicardipine** IV (1re intention des urgences hypertensives).","prio":"P3","sec":"s14"},{"id":"fc-230-396501","poly":"cardio","fiche":"230","front":"Dissection aortique : quelle contre-indication thérapeutique absolue retenir ?","back":"La **fibrinolyse**.","prio":"P1","sec":"s14"},{"id":"fc-230-202eb6","poly":"cardio","fiche":"230","front":"Dissection aortique : où hospitaliser et quelle surveillance de la PA ?","back":"**Soins intensifs ou réanimation** ; PA **toutes les 15 min**.","prio":"P3","sec":"s14"},{"id":"fc-230-7c1395","poly":"cardio","fiche":"230","front":"Dissection aortique : quelles complications guetter ?","back":"**Ischémie de membre**, **AVC**, **ischémie mésentérique**, **tamponnade**.","prio":"P2","sec":"s14"},{"id":"fc-230-2e67fd","poly":"cardio","fiche":"230","front":"EP à haut risque en choc sans scanner possible : que suffit-il pour fibrinolyser ?","back":"Une **surcharge droite à l'ETT**.","prio":"P1","sec":"s15"},{"id":"fc-230-711c82","poly":"cardio","fiche":"230","front":"EP à haut risque confirmée : quel traitement ?","back":"**Thrombolyse** (ou embolectomie), en **réanimation/USIC**.","prio":"P1","sec":"s15"},{"id":"fc-230-a09cf6","poly":"cardio","fiche":"230","front":"EP à haut risque avec thrombolyse contre-indiquée ou en échec : quelle option ?","back":"**Embolectomie chirurgicale en urgence** (sous CEC).","prio":"P1","sec":"s15"},{"id":"fc-230-7203a2","poly":"cardio","fiche":"230","front":"EP à haut risque : quel anticoagulant et quelle dose ?","back":"**HNF 500 UI/kg/j** IV continue.","prio":"P1","sec":"s15"},{"id":"fc-230-cf2959","poly":"cardio","fiche":"230","front":"HNF : quelles cibles biologiques (item 226) ?","back":"**TCA 1,5-2,5 × le témoin** ou **anti-Xa 0,3-0,7 U**, 4 h après le début.","prio":"P2","sec":"s15"},{"id":"fc-230-1b3a5f","poly":"cardio","fiche":"230","front":"HNF : quelle surveillance des plaquettes ?","back":"**Avant** puis **2 fois/semaine pendant 21 jours**.","prio":"P1","sec":"s15"},{"id":"fc-230-d50554","poly":"cardio","fiche":"230","front":"Après embolectomie pour EP massive : quel dispositif proposer ?","back":"Un **filtre cave**.","prio":"P2","sec":"s15"},{"id":"fc-230-17a7aa","poly":"cardio","fiche":"230","front":"EP de gravité intermédiaire sans choc : la fibrinolyse est-elle systématique ?","back":"**Non**.","prio":"P1","sec":"s15"},{"id":"fc-230-25e558","poly":"cardio","fiche":"230","front":"Sous HNF : quels critères définissent une thrombopénie induite (TIH) ?","back":"Plaquettes **< 150 G/L** ou **chute de 50 %**.","prio":"P2","sec":"s15"},{"id":"fc-230-85ddaf","poly":"cardio","fiche":"230","front":"EP à risque intermédiaire haut : quelle définition et quelle orientation ?","back":"sPESI ≥ 1, **VD dilaté et troponine +** : anticoagulant en **réanimation/USIC**, reperfusion si aggravation.","prio":"P1","sec":"s16"},{"id":"fc-230-ee18f4","poly":"cardio","fiche":"230","front":"EP à faible risque : quelle définition et quelle orientation ?","back":"**sPESI = 0**, VD normal : **hospitalisation courte ou ambulatoire**.","prio":"P1","sec":"s16"},{"id":"fc-230-c2f9bb","poly":"cardio","fiche":"230","front":"EP sans choc : quel est l'anticoagulant de référence ?","back":"Un **AOD anti-Xa** (rivaroxaban ou apixaban).","prio":"P1","sec":"s16"},{"id":"fc-230-1f6981","poly":"cardio","fiche":"230","front":"Rivaroxaban dans l'EP : quelle posologie ?","back":"**15 mg × 2/j pendant 21 jours**, puis **20 mg/j**.","prio":"P1","sec":"s16"},{"id":"fc-230-f65385","poly":"cardio","fiche":"230","front":"Apixaban dans l'EP : quelle posologie ?","back":"**10 mg × 2/j pendant 7 jours**, puis **5 mg × 2/j**.","prio":"P1","sec":"s16"},{"id":"fc-230-637eb7","poly":"cardio","fiche":"230","front":"EP : quelles posologies d'énoxaparine et de tinzaparine ?","back":"Énoxaparine **100 UI/kg/12 h SC** ; tinzaparine **175 UI/kg/24 h SC**.","prio":"P2","sec":"s16"},{"id":"fc-230-fbb415","poly":"cardio","fiche":"230","front":"HBPM, fondaparinux, AOD : quelle contre-indication rénale commune ?","back":"**DFG < 30 mL/min**.","prio":"P1","sec":"s16"},{"id":"fc-230-b5facd","poly":"cardio","fiche":"230","front":"EP : quand lever le patient ?","back":"Après **24 h d'anticoagulation efficace**, avec bas de contention.","prio":"P2","sec":"s16"},{"id":"fc-230-fa7329","poly":"cardio","fiche":"230","front":"EP sous AVK : quelle INR cible ?","back":"**2,5** (entre 2 et 3).","prio":"P1","sec":"s16"},{"id":"fc-230-092002","poly":"cardio","fiche":"230","front":"EP : quelle durée d'anticoagulation selon le contexte ?","back":"**3 mois** si facteur réversible ; **> 3 mois** sans facteur ; **illimitée** si récidive ou thrombophilie.","prio":"P1","sec":"s16"},{"id":"fc-230-be3f19","poly":"cardio","fiche":"230","front":"EP chez une femme sous œstroprogestatifs : quelle conduite contraceptive ?","back":"**Arrêter puis contre-indiquer** ; alternatives : **progestatif continu** ou **DIU**.","prio":"P1","sec":"s16"},{"id":"fc-230-468e09","poly":"cardio","fiche":"230","front":"EP pendant la grossesse : quel anticoagulant ?","back":"Les **HBPM** (AVK tératogènes).","prio":"P1","sec":"s16"},{"id":"fc-230-dea3f9","poly":"cardio","fiche":"230","front":"EP sur cancer : quelles limites des AOD ?","back":"Évités dans les cancers **digestifs** et **génito-urinaires** (risque hémorragique).","prio":"P3","sec":"s16"},{"id":"fc-230-dd8cf7","poly":"cardio","fiche":"230","front":"EP avec contre-indication aux anticoagulants : quelle option ?","back":"Un **filtre cave** (temporaire si CI provisoire, retiré ensuite).","prio":"P2","sec":"s16"},{"id":"fc-230-1d3c0a","poly":"cardio","fiche":"230","front":"EP, relais par AVK : quand arrêter l'héparine ?","back":"Après **≥ 5 jours** et **2 INR > 2** à 24 h d'intervalle (AVK débuté dès J1).","prio":"P2","sec":"s16"},{"id":"fc-230-7bb3e2","poly":"cardio","fiche":"230","front":"Tamponnade : quelle hospitalisation ?","back":"**Soins intensifs de cardiologie** (urgence médicochirurgicale).","prio":"P2","sec":"s17"},{"id":"fc-230-90e539","poly":"cardio","fiche":"230","front":"Tamponnade confirmée : quel traitement ?","back":"**Drainage** : **ponction péricardique écho-guidée** ou drainage chirurgical.","prio":"P1","sec":"s17"},{"id":"fc-230-1d2353","poly":"cardio","fiche":"230","front":"Tamponnade : quel traitement d'attente avant le drainage ?","back":"**Remplissage** par macromolécules.","prio":"P2","sec":"s17"},{"id":"fc-230-6f8c47","poly":"cardio","fiche":"230","front":"Tamponnade : pourquoi le drainage est-il impératif ?","back":"Risque d'**arrêt cardiaque par adiastolie**.","prio":"P2","sec":"s17"},{"id":"fc-230-537810","poly":"cardio","fiche":"230","front":"Antidote de l'HNF : lequel ?","back":"Le **sulfate de protamine**.","prio":"P1","sec":"s17"},{"id":"fc-230-602d3c","poly":"cardio","fiche":"230","front":"Antidotes des AVK : lesquels ?","back":"**PPSB** (action très rapide) + **vitamine K** (efficace en quelques heures).","prio":"P1","sec":"s17"},{"id":"fc-230-650190","poly":"cardio","fiche":"230","front":"Antidote du dabigatran : lequel ?","back":"L'**idarucizumab**.","prio":"P2","sec":"s17"},{"id":"fc-230-fea664","poly":"cardio","fiche":"230","front":"Tamponnade : quels contextes étiologiques habituels ?","back":"Péricardite **néoplasique**, **traumatique**, **tuberculeuse**, hémopéricarde ; exceptionnellement virale.","prio":"P3","sec":"s17"},{"id":"fc-230-74ff6f","poly":"cardio","fiche":"230","front":"Tamponnade : quelle notion inacceptable le Collège retient-il ?","back":"Ne pas la **reconnaître**, ou ne pas organiser sa **prise en charge urgente**.","prio":"P2","sec":"s17"},{"id":"fc-230-9e025e","poly":"cardio","fiche":"230","front":"Péricardite aiguë : faut-il hospitaliser systématiquement ?","back":"**Non** : seulement si complication ou facteur de gravité majeur.","prio":"P1","sec":"s18"},{"id":"fc-230-65b854","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quels facteurs majeurs imposent l'hospitalisation ?","back":"**Fièvre > 38 °C**, début subaigu, épanchement **> 20 mm** ou tamponnade, **échec** de l'aspirine/AINS à 7 jours.","prio":"P2","sec":"s18"},{"id":"fc-230-31565d","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelles mesures non médicamenteuses ?","back":"**Repos** et **arrêt du sport** jusqu'à normalisation des symptômes, CRP, ECG, écho.","prio":"P2","sec":"s18"},{"id":"fc-230-af1240","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie d'aspirine ?","back":"**750 à 1 000 mg toutes les 8 h**.","prio":"P1","sec":"s18"},{"id":"fc-230-dd6928","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie d'ibuprofène ?","back":"**600 mg toutes les 8 h**.","prio":"P2","sec":"s18"},{"id":"fc-230-032002","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle durée d'anti-inflammatoire ?","back":"Pleine dose **1 à 2 semaines** puis décroissance ; arrêt progressif en **4 à 8 semaines**.","prio":"P2","sec":"s18"},{"id":"fc-230-0b7daa","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quelle posologie et quelle durée de colchicine ?","back":"**0,5 mg × 2/j** (0,5 mg/j si < 70 kg, > 70 ans ou DFG < 35) pendant **3 mois**.","prio":"P1","sec":"s18"},{"id":"fc-230-cb8f70","poly":"cardio","fiche":"230","front":"Colchicine : quelles interactions surveiller ?","back":"Inhibiteurs du **CYP3A4** : macrolides, ciclosporine, vérapamil, statines.","prio":"P3","sec":"s18"},{"id":"fc-230-ea7c54","poly":"cardio","fiche":"230","front":"Péricardite aiguë : peut-on donner des corticoïdes en 1re intention ?","back":"**Non** (notion inacceptable : récidives) ; seulement après échec AINS + colchicine.","prio":"P1","sec":"s18"},{"id":"fc-230-67ff78","poly":"cardio","fiche":"230","front":"Péricardite récidivante : quelle cause fréquente et quelle prévention ?","back":"Traitement **trop court** ; la **colchicine** prévient les récidives.","prio":"P2","sec":"s18"},{"id":"fc-230-92fc44","poly":"cardio","fiche":"230","front":"Péricardite aiguë : quel suivi ?","back":"Revoir à **7 jours**, **1 mois** (écho avant d'arrêter l'anti-inflammatoire), **3 et 6 mois**.","prio":"P2","sec":"s18"},{"id":"fc-230-8c1f63","poly":"cardio","fiche":"230","front":"Péricardite tuberculeuse : quel traitement ?","back":"**Antituberculeux**, associés pour certains à la **prednisone** (prévenir la constriction).","prio":"P3","sec":"s18"},{"id":"fc-230-077603","poly":"cardio","fiche":"230","front":"Angor de novo : comment le considérer ?","back":"Comme un **SCA** jusqu'à preuve du contraire.","prio":"P1","sec":"s19"},{"id":"fc-230-34837a","poly":"cardio","fiche":"230","front":"Angor stable : quels traitements systématiques ?","back":"Correction des FDR, **aspirine** et **statine**, anti-ischémiques pour les symptômes.","prio":"P1","sec":"s19"},{"id":"fc-230-a31d68","poly":"cardio","fiche":"230","front":"Angor stable : quand faire une coronarographie d'emblée ?","back":"Angor **sévère** (classe ≥ 3) ou **FEVG altérée**.","prio":"P2","sec":"s19"},{"id":"fc-230-4dbb75","poly":"cardio","fiche":"230","front":"Trinitrine sublinguale : quelle précaution de prise ?","back":"**Assis ou allongé** (céphalées, hypotension).","prio":"P2","sec":"s19"},{"id":"fc-230-e8611f","poly":"cardio","fiche":"230","front":"Angor stable : quel anti-ischémique de 1re intention ?","back":"Un **bêtabloquant**.","prio":"P1","sec":"s19"},{"id":"fc-230-733032","poly":"cardio","fiche":"230","front":"Bêtabloquant dans l'angor : quelles contre-indications ?","back":"**Asthme**, BPCO très sévère, Raynaud, bradycardie < 50/min, **BAV 2e ou 3e degré**.","prio":"P2","sec":"s19"},{"id":"fc-230-dad04a","poly":"cardio","fiche":"230","front":"Inhibiteur calcique bradycardisant dans l'angor : quelle association interdire ?","back":"Avec un **bêtabloquant** (troubles de conduction).","prio":"P1","sec":"s19"},{"id":"fc-230-d5fa46","poly":"cardio","fiche":"230","front":"Angor stable : quand préférer un inhibiteur calcique dihydropyridine ?","back":"**1re intention** si BB contre-indiqué ou FC < 60 bpm ; **2e intention** associé au BB.","prio":"P3","sec":"s19"},{"id":"fc-230-75c192","poly":"cardio","fiche":"230","front":"Nicorandil : quel effet indésirable caractéristique ?","back":"**Ulcérations** péribuccales, intestinales, périanales.","prio":"P3","sec":"s19"},{"id":"fc-230-023c10","poly":"cardio","fiche":"230","front":"Ivabradine : quelles conditions et quel effet indésirable ?","back":"Rythme **sinusal** avec FC ≥ 70 bpm (inefficace en FA) ; EI : **phosphènes**.","prio":"P3","sec":"s19"},{"id":"fc-230-cd4672","poly":"cardio","fiche":"230","front":"Dérivés nitrés au long cours : quelle association est contre-indiquée ?","back":"Avec les **inhibiteurs de la PDE5** (sildénafil).","prio":"P2","sec":"s19"},{"id":"fc-230-0266e5","poly":"cardio","fiche":"230","front":"Après angioplastie pour angor stable : quelle bithérapie antiplaquettaire ?","back":"**Aspirine + clopidogrel** habituellement **6 mois** ; **pas de prasugrel ni ticagrélor**.","prio":"P1","sec":"s19"},{"id":"fc-230-63916d","poly":"cardio","fiche":"230","front":"Angor stable : quel objectif de LDL-C ?","back":"**< 0,55 g/L**.","prio":"P1","sec":"s19"},{"id":"fc-230-baeee5","poly":"cardio","fiche":"230","front":"Douleur thoracique sans urgence vitale : quel est l'objectif ?","back":"Il reste **urgent de rassurer et de soulager**.","prio":"P2","sec":"s20"},{"id":"fc-230-c1d2bd","poly":"cardio","fiche":"230","front":"Urgences non cardiaques de douleur thoracique : quel degré d'urgence de prise en charge ?","back":"**Moyenne urgence**, prise en charge spécifique selon la cause.","prio":"P3","sec":"s20"},{"id":"fc-230-e0f202","poly":"cardio","fiche":"230","front":"SCA en Usic : quelle surveillance ?","back":"**Monitorage ECG continu**, ECG 2 fois/j et à chaque douleur, troponine, ETT à l'admission, biologie quotidienne.","prio":"P2","sec":"s21"},{"id":"fc-230-f03f8e","poly":"cardio","fiche":"230","front":"ECG du ST+ après reperfusion : quelle évolution ?","back":"Le sus-décalage **régresse vite** ; persistant si **anévrisme** ; T négative après **48 h**.","prio":"P3","sec":"s21"},{"id":"fc-230-7efe80","poly":"cardio","fiche":"230","front":"Après un SCA ST+ : quel délai de sortie ?","back":"Entre **J3 et J5** (ST- non compliqué : 24-48 h après revascularisation).","prio":"P2","sec":"s21"},{"id":"fc-230-7ea8a1","poly":"cardio","fiche":"230","front":"Après un SCA : quelle ordonnance pour 1 an ?","back":"**Aspirine + P2Y12** (12 mois), **statine forte dose**, ± bêtabloquant et IEC, traitement des FDR.","prio":"P1","sec":"s21"},{"id":"fc-230-82767d","poly":"cardio","fiche":"230","front":"Après un SCA : quel objectif de LDL-C ?","back":"**< 0,55 g/L** et baisse **≥ 50 %**.","prio":"P1","sec":"s21"},{"id":"fc-230-ad1596","poly":"cardio","fiche":"230","front":"Après un SCA, LDL-C hors objectif sous statine maximale : quelle conduite ?","back":"Ajouter **ézétimibe 10 mg**, puis **anti-PCSK9**.","prio":"P2","sec":"s21"},{"id":"fc-230-b584b5","poly":"cardio","fiche":"230","front":"Après un SCA : quand poser un défibrillateur implantable ?","back":"**FEVG < 35 %** persistante à distance (**≥ 6 semaines**) après optimisation.","prio":"P2","sec":"s21"},{"id":"fc-230-da82cc","poly":"cardio","fiche":"230","front":"Après un SCA avec FEVG ≤ 40 % : quels traitements ?","back":"**IEC/ARA2**, **bêtabloquant** ; antagoniste minéralocorticoïde si IC ou diabète.","prio":"P2","sec":"s21"},{"id":"fc-230-3ac6b9","poly":"cardio","fiche":"230","front":"Après un SCA : quelle réadaptation recommander ?","back":"La **réadaptation cardiaque**, recommandée pour tous.","prio":"P2","sec":"s21"},{"id":"fc-231-e7d80c","poly":"cardio","fiche":"231","front":"ECG : que traduit un QRS fin ?","back":"Une activation ventriculaire par les **voies de conduction rapides** (NAV, His, branches, Purkinje).","prio":"P1","sec":"s1"},{"id":"fc-231-9649a9","poly":"cardio","fiche":"231","front":"ECG : que traduit un QRS large ?","back":"Une progression lente **de proche en proche** dans le muscle : **TV** ou **bloc de branche complet**.","prio":"P1","sec":"s1"},{"id":"fc-231-de67ea","poly":"cardio","fiche":"231","front":"Tachycardie régulière à QRS larges : comment la considérer ?","back":"Comme une **TV** jusqu'à preuve du contraire (une TSV avec bloc de branche est possible).","prio":"P1","sec":"s1"},{"id":"fc-231-5e38be","poly":"cardio","fiche":"231","front":"Stimulation du VD par pacemaker : quel aspect de QRS ?","back":"QRS large d'aspect de **BBG**.","prio":"P2","sec":"s1"},{"id":"fc-231-6b270d","poly":"cardio","fiche":"231","front":"Dysfonction sinusale marquée : quel rythme d'échappement apparaît ?","back":"Un **échappement jonctionnel** : pas de P devant le QRS, parfois P rétrograde derrière.","prio":"P2","sec":"s1"},{"id":"fc-231-1db1b7","poly":"cardio","fiche":"231","front":"BAV complet avec échappement à QRS fins : quel siège du bloc ?","back":"**Nodal** (suprahissien).","prio":"P1","sec":"s1"},{"id":"fc-231-dd141e","poly":"cardio","fiche":"231","front":"BAV bas situé : quel échappement et quelles conséquences ?","back":"Échappement à **QRS larges** : bradycardie extrême et **QT long**.","prio":"P3","sec":"s1"},{"id":"fc-231-9b7dbe","poly":"cardio","fiche":"231","front":"ECG : quelle polarité donne un front qui vient vers l'électrode ?","back":"Une onde **positive** (négative s'il s'éloigne ; isodiphasique s'il est perpendiculaire).","prio":"P3","sec":"s1"},{"id":"fc-231-0d45dd","poly":"cardio","fiche":"231","front":"Bloc de branche : quelle orientation de l'onde T est normale ?","back":"En **sens inverse** du QRS (discordance appropriée), à ne pas prendre pour un SCA.","prio":"P1","sec":"s1"},{"id":"fc-231-9f19b6","poly":"cardio","fiche":"231","front":"Dérivations du plan frontal : lesquelles ?","back":"**D1, D2, D3** + **aVR, aVL, aVF** (servent à calculer l'axe).","prio":"P1","sec":"s2"},{"id":"fc-231-ba3897","poly":"cardio","fiche":"231","front":"ECG : quand ajouter V3R et V4R ?","back":"**Parfois**, chez l'**enfant** et en cas de suspicion de **SCA**.","prio":"P2","sec":"s2"},{"id":"fc-231-a882e5","poly":"cardio","fiche":"231","front":"Dérivation de Lewis : à quoi sert-elle ?","back":"À **démasquer une activité atriale** peu visible (lue en D1).","prio":"P3","sec":"s2"},{"id":"fc-231-7683ff","poly":"cardio","fiche":"231","front":"Électrodes V1-V2 posées trop haut : quel aspect peuvent-elles créer ?","back":"Une **pseudonécrose** ou une repolarisation antérieure atypique.","prio":"P2","sec":"s2"},{"id":"fc-231-4dec2f","poly":"cardio","fiche":"231","front":"Territoire inférieur de l'ECG : quelles dérivations ?","back":"**D2, D3, aVF**.","prio":"P1","sec":"s2"},{"id":"fc-231-95e9f4","poly":"cardio","fiche":"231","front":"Territoire antéroseptal de l'ECG : quelles dérivations ?","back":"**V1, V2, V3**.","prio":"P1","sec":"s2"},{"id":"fc-231-6a7251","poly":"cardio","fiche":"231","front":"Territoire latéral haut de l'ECG : quelles dérivations ?","back":"**D1, aVL**.","prio":"P1","sec":"s2"},{"id":"fc-231-ca94ac","poly":"cardio","fiche":"231","front":"Territoire latéral bas de l'ECG : quelles dérivations ?","back":"**V5, V6**.","prio":"P1","sec":"s2"},{"id":"fc-231-c6511f","poly":"cardio","fiche":"231","front":"Territoire postérieur de l'ECG : quelles dérivations ?","back":"**V7, V8, V9**.","prio":"P1","sec":"s2"},{"id":"fc-231-10f3d6","poly":"cardio","fiche":"231","front":"Ventricule droit à l'ECG : quelles dérivations l'explorent ?","back":"**V1, V2, V3R, V4R**.","prio":"P2","sec":"s2"},{"id":"fc-231-a56c4a","poly":"cardio","fiche":"231","front":"Territoire apical de l'ECG : quelle dérivation ?","back":"**V4**.","prio":"P2","sec":"s2"},{"id":"fc-231-2d7904","poly":"cardio","fiche":"231","front":"Axe du QRS : quelles dérivations suffisent pour l'estimer ?","back":"**D1 et aVF** (D2 tranche si D1 positif et aVF négatif).","prio":"P1","sec":"s2"},{"id":"fc-231-1baa19","poly":"cardio","fiche":"231","front":"Axe du QRS : quelles sont les valeurs normales ?","back":"**−30° à +90°**.","prio":"P1","sec":"s2"},{"id":"fc-231-74df90","poly":"cardio","fiche":"231","front":"Axe : D1 positif, aVF négatif, D2 négatif ; que conclure ?","back":"Axe **hypergauche** (au-delà de −30°).","prio":"P2","sec":"s2"},{"id":"fc-231-239827","poly":"cardio","fiche":"231","front":"Axe : D1 négatif et aVF positif ; que conclure ?","back":"Axe **hyperdroit** (+90° à +180°).","prio":"P2","sec":"s2"},{"id":"fc-231-2b39e7","poly":"cardio","fiche":"231","front":"Axe : D1 et aVF négatifs ; que conclure ?","back":"**Axe extrême** (−90° à −180°).","prio":"P2","sec":"s2"},{"id":"fc-231-4069ac","poly":"cardio","fiche":"231","front":"Axe du QRS chez l'obèse ou en cas de cardiomégalie : quelle orientation ?","back":"Cœur **horizontal** : axe proche de **0°** (sujet filiforme : proche de 90°).","prio":"P3","sec":"s2"},{"id":"fc-231-1e480e","poly":"cardio","fiche":"231","front":"D1 négatif avec onde P négative en D1 : à quoi penser d'abord ?","back":"À une **inversion des électrodes** frontales (avant l'HBPG).","prio":"P1","sec":"s2"},{"id":"fc-231-1a0044","poly":"cardio","fiche":"231","front":"Papier ECG à 25 mm/s : que valent un petit et un grand carreau ?","back":"Petit carreau **40 ms** ; grand carreau **200 ms** (1 mm = 0,1 mV).","prio":"P1","sec":"s3"},{"id":"fc-231-a1432e","poly":"cardio","fiche":"231","front":"ECG : comment calculer rapidement la fréquence cardiaque ?","back":"**300 / nombre de grands carreaux** entre deux QRS.","prio":"P1","sec":"s3"},{"id":"fc-231-a8c044","poly":"cardio","fiche":"231","front":"Fréquence cardiaque normale de l'adulte : quelles bornes ?","back":"**60-100 bpm** (bradycardie < 60, tachycardie > 100).","prio":"P1","sec":"s3"},{"id":"fc-231-98f1de","poly":"cardio","fiche":"231","front":"Onde P normale : quelle durée et quelle amplitude ?","back":"Durée **< 120 ms** ; amplitude **< 2,5 mm** en D2.","prio":"P2","sec":"s3"},{"id":"fc-231-517d80","poly":"cardio","fiche":"231","front":"Intervalle PR normal : quelle durée ?","back":"**120 à 200 ms**.","prio":"P1","sec":"s3"},{"id":"fc-231-ff9cca","poly":"cardio","fiche":"231","front":"QRS normal : quelle durée ?","back":"**70 à 110 ms**.","prio":"P1","sec":"s3"},{"id":"fc-231-25730c","poly":"cardio","fiche":"231","front":"Onde Q physiologique : quels critères ?","back":"**< 1/3** du QRS et **< 40 ms**.","prio":"P2","sec":"s3"},{"id":"fc-231-3d5cca","poly":"cardio","fiche":"231","front":"QT corrigé : quelle valeur normale ?","back":"**< 450 ms** à 60 bpm (en pratique 470-480 ms).","prio":"P1","sec":"s3"},{"id":"fc-231-7b5c07","poly":"cardio","fiche":"231","front":"Onde P sinusale : quelle polarité ?","back":"**Positive en D1** et dans les **inférieures** (nœud sinusal en haut à droite de l'OD).","prio":"P1","sec":"s3"},{"id":"fc-231-86c35e","poly":"cardio","fiche":"231","front":"Rythme sinusal : quelle définition ?","back":"Chaque **P suivie d'un QRS** et chaque **QRS précédé d'une P**.","prio":"P1","sec":"s3"},{"id":"fc-231-7a3a18","poly":"cardio","fiche":"231","front":"P sinusales régulières non conduites (BAV3) : s'agit-il d'un rythme sinusal ?","back":"**Non**.","prio":"P2","sec":"s3"},{"id":"fc-231-8d5a30","poly":"cardio","fiche":"231","front":"Intervalle PR : quelle partie de la conduction explore-t-il ?","back":"**Toute la conduction**, de la sortie du nœud sinusal au réseau de Purkinje.","prio":"P2","sec":"s3"},{"id":"fc-231-81eb50","poly":"cardio","fiche":"231","front":"QT : comment le mesurer ?","back":"Du début de Q à la fin de T, là où la T est la plus ample (**souvent V2-V3**), par la **tangente** ; sans l'**onde U**.","prio":"P2","sec":"s3"},{"id":"fc-231-69000a","poly":"cardio","fiche":"231","front":"QTc : quelle formule utiliser ?","back":"**Bazett** : QTc = QT / √RR (RR en secondes).","prio":"P1","sec":"s3"},{"id":"fc-231-2f9cd9","poly":"cardio","fiche":"231","front":"ECG normal : où les ondes T peuvent-elles être négatives ?","back":"**aVR et V1**, parfois **D3 et aVL**.","prio":"P1","sec":"s3"},{"id":"fc-231-80c688","poly":"cardio","fiche":"231","front":"Lecture systématique d'un ECG : quelles 4 étapes ?","back":"**Rythme**, **conduction**, **repolarisation**, **morphologie**.","prio":"P2","sec":"s3"},{"id":"fc-231-6e0aa8","poly":"cardio","fiche":"231","front":"Point J sus-décalé de V1 à V4 chez un homme jeune : que conclure ?","back":"**Repolarisation physiologique**, pas un SCA.","prio":"P1","sec":"s3"},{"id":"fc-231-17fc41","poly":"cardio","fiche":"231","front":"Mesure du QT avec une onde U incluse : quelle erreur ?","back":"Le QT est **surestimé** (ex. hypokaliémie).","prio":"P2","sec":"s3"},{"id":"fc-231-2ebbb3","poly":"cardio","fiche":"231","front":"Bloc de branche : comment déterminer son côté ?","back":"En **V1** : QRS positif = **bloc droit** ; négatif = **bloc gauche**.","prio":"P1","sec":"s4"},{"id":"fc-231-7e3f13","poly":"cardio","fiche":"231","front":"Bloc de branche complet : quelle durée de QRS ?","back":"**> 120 ms**.","prio":"P1","sec":"s4"},{"id":"fc-231-d09fa1","poly":"cardio","fiche":"231","front":"BBD complet : quel aspect ECG ?","back":"V1 : **RsR'** (positif) ; V6 : **qRs** avec S traînante.","prio":"P1","sec":"s4"},{"id":"fc-231-5abd26","poly":"cardio","fiche":"231","front":"BBG complet : quel aspect ECG ?","back":"V1 : **rS ou QS** (négatif) ; V6, D1, aVL : **notch**, R souvent exclusive.","prio":"P1","sec":"s4"},{"id":"fc-231-d7d7d1","poly":"cardio","fiche":"231","front":"Bloc de branche : que décrire avant de parler du bloc ?","back":"Le **rythme atrial** (une TSV associée n'est pas rare).","prio":"P2","sec":"s4"},{"id":"fc-231-de4bc6","poly":"cardio","fiche":"231","front":"Douleur thoracique persistante + BBG : quelle conduite ?","back":"Évoquer un **infarctus antérieur** : avis cardiologique rapide **sans attendre la troponine**.","prio":"P1","sec":"s4"},{"id":"fc-231-d7c061","poly":"cardio","fiche":"231","front":"Hémibloc : sur quoi repose le diagnostic ?","back":"Sur l'**axe** (QRS très modérément élargi > 110 ms + déviation axiale).","prio":"P1","sec":"s4"},{"id":"fc-231-984149","poly":"cardio","fiche":"231","front":"Hémibloc antérieur gauche : quel critère ?","back":"Axe au-delà de **−30°** (D2 négatif) ; **fréquent**.","prio":"P1","sec":"s4"},{"id":"fc-231-aff589","poly":"cardio","fiche":"231","front":"Hémibloc postérieur gauche : quel critère ?","back":"Axe **> +90°** (D1 négatif), sans pathologie du VD, morphologie longiligne ni infarctus latéral ; **rare**.","prio":"P1","sec":"s4"},{"id":"fc-231-5f4393","poly":"cardio","fiche":"231","front":"Bloc bifasciculaire : quelles associations ?","back":"**HBAG + BBD** ou **HBPG + BBD** (QRS > 120 ms).","prio":"P1","sec":"s4"},{"id":"fc-231-298651","poly":"cardio","fiche":"231","front":"Bloc de branche incomplet : quelle durée de QRS ?","back":"Entre **110 et 120 ms**.","prio":"P3","sec":"s4"},{"id":"fc-231-56b2b3","poly":"cardio","fiche":"231","front":"Bloc de branche fonctionnel : quelle définition ?","back":"Bloc qui n'apparaît qu'à partir d'une certaine **fréquence** (en tachycardie ou bradycardie).","prio":"P3","sec":"s4"},{"id":"fc-231-1c113b","poly":"cardio","fiche":"231","front":"Syncope + bloc bifasciculaire : quelle conduite ?","back":"**Hospitalisation en cardiologie avec télémétrie** (risque de BAV complet infrahissien).","prio":"P2","sec":"s4"},{"id":"fc-231-0cca00","poly":"cardio","fiche":"231","front":"Bloc de branche : peut-il donner une bradycardie ?","back":"**Non**.","prio":"P1","sec":"s4"},{"id":"fc-231-4cde8a","poly":"cardio","fiche":"231","front":"Bradycardie : quelles sont les deux structures responsables possibles ?","back":"Le **nœud sinusal** (dysfonction sinusale) ou le **NAV** (BAV 2 ou 3).","prio":"P1","sec":"s5"},{"id":"fc-231-af6fd2","poly":"cardio","fiche":"231","front":"Bradycardie : quelle question pose le diagnostic ?","back":"**Que font les ondes P ?**","prio":"P1","sec":"s5"},{"id":"fc-231-083e0f","poly":"cardio","fiche":"231","front":"Bradycardie avec plus d'ondes P que de QRS : quel diagnostic ?","back":"Un **BAV**.","prio":"P1","sec":"s5"},{"id":"fc-231-38915e","poly":"cardio","fiche":"231","front":"Bradycardie avec P trop lentes ou absentes : quel diagnostic ?","back":"Une **dysfonction sinusale**.","prio":"P1","sec":"s5"},{"id":"fc-231-0333d8","poly":"cardio","fiche":"231","front":"BAV1 : quelle définition ECG ?","back":"PR **constant > 200 ms**, aucune P bloquée.","prio":"P1","sec":"s5"},{"id":"fc-231-72e99a","poly":"cardio","fiche":"231","front":"BAV2 Mobitz 1 : quel aspect et quel siège ?","back":"PR qui **s'allonge progressivement** puis P bloquée (Luciani-Wenckebach) ; **suprahissien**.","prio":"P1","sec":"s5"},{"id":"fc-231-4836c4","poly":"cardio","fiche":"231","front":"BAV2 Mobitz 2 : quel aspect et quel siège ?","back":"PR **constant** puis P bloquée **inopinément** ; **infrahissien**.","prio":"P1","sec":"s5"},{"id":"fc-231-4a914e","poly":"cardio","fiche":"231","front":"BAV 2/1 : comment préciser son siège ?","back":"**Infrahissien** si QRS larges ; **suprahissien** si QRS fins avec du Mobitz 1 à d'autres moments.","prio":"P2","sec":"s5"},{"id":"fc-231-1027bd","poly":"cardio","fiche":"231","front":"BAV3 : quelle définition ECG ?","back":"**Dissociation atrioventriculaire complète** (P dissociées, bien vues en V1).","prio":"P1","sec":"s5"},{"id":"fc-231-4e62bc","poly":"cardio","fiche":"231","front":"Onde P bloquée qui arrive plus tôt que les autres : quel diagnostic évoquer ?","back":"Une **extrasystole atriale bloquée** (et non un BAV2).","prio":"P2","sec":"s5"},{"id":"fc-231-bdad23","poly":"cardio","fiche":"231","front":"Échappement jonctionnel : quel aspect de l'onde P rétrograde ?","back":"Derrière le QRS (dans le ST), **négative en D2**.","prio":"P2","sec":"s5"},{"id":"fc-231-0bf618","poly":"cardio","fiche":"231","front":"Bloc sinoatrial du 2e degré : quel aspect ?","back":"Pause sans P ni QRS valant **le double** de l'intervalle PP normal.","prio":"P3","sec":"s5"},{"id":"fc-231-2f02b1","poly":"cardio","fiche":"231","front":"Maladie de l'oreillette : quel aspect ECG ?","back":"Alternance **FA / bradycardie sinusale** avec **pauses** à l'arrêt de la FA.","prio":"P3","sec":"s5"},{"id":"fc-231-4180e8","poly":"cardio","fiche":"231","front":"FA avec RR devenus constants et lents : quel diagnostic ?","back":"FA + **BAV complet**.","prio":"P3","sec":"s5"},{"id":"fc-231-1b2773","poly":"cardio","fiche":"231","front":"Bradycardie : quel trouble ionique faut-il évoquer ?","back":"L'**hyperkaliémie** (BAV ou dysfonction sinusale).","prio":"P1","sec":"s5"},{"id":"fc-231-2567ed","poly":"cardio","fiche":"231","front":"Tachycardie supraventriculaire : où naît-elle et quel aspect des QRS ?","back":"Au-dessus de la bifurcation du His ; QRS **fins** le plus souvent (larges si bloc de branche).","prio":"P1","sec":"s6"},{"id":"fc-231-ce3112","poly":"cardio","fiche":"231","front":"NAV : quelle propriété le rend vital en cas de tachycardie atriale ?","back":"Sa conduction **décrémentielle** (filtre : sans lui, une FA deviendrait FV).","prio":"P2","sec":"s6"},{"id":"fc-231-60460a","poly":"cardio","fiche":"231","front":"Tachycardie sinusale : quels arguments ?","back":"P **positives en D1, D2, D3, aVF**, fréquence qui varie **progressivement**, contexte d'**hypermétabolisme**.","prio":"P2","sec":"s6"},{"id":"fc-231-4fd73c","poly":"cardio","fiche":"231","front":"TSV non sinusale : comment varie la fréquence ?","back":"Par **« marches d'escalier »**.","prio":"P2","sec":"s6"},{"id":"fc-231-cd85ce","poly":"cardio","fiche":"231","front":"Fibrillation atriale : quel aspect ECG ?","back":"QRS **irrégulièrement irréguliers**, ligne de base en mailles amples ou fine trémulation, 100-200 bpm.","prio":"P1","sec":"s6"},{"id":"fc-231-9ba2ac","poly":"cardio","fiche":"231","front":"Tachycardie complètement irrégulière à QRS fins : quel diagnostic ?","back":"La **FA** est le **seul** diagnostic.","prio":"P1","sec":"s6"},{"id":"fc-231-17406e","poly":"cardio","fiche":"231","front":"Tachycardie irrégulière à QRS larges : quel diagnostic évoquer (hors préexcitation) ?","back":"**FA + bloc de branche**.","prio":"P3","sec":"s6"},{"id":"fc-231-f18f6f","poly":"cardio","fiche":"231","front":"Flutter atrial : quelles caractéristiques ECG ?","back":"Activité atriale **monomorphe** vers **300 bpm**, **sans retour à la ligne isoélectrique** dans au moins une dérivation (dents de scie).","prio":"P1","sec":"s6"},{"id":"fc-231-e415d9","poly":"cardio","fiche":"231","front":"Flutter typique antihoraire : quelle polarité des ondes F ?","back":"**Négatives en D2, D3, aVF**, **positives en V1**.","prio":"P1","sec":"s6"},{"id":"fc-231-aebc35","poly":"cardio","fiche":"231","front":"Flutter typique : quel circuit ?","back":"Réentrée dans l'**OD** par l'**isthme cavotricuspide**.","prio":"P2","sec":"s6"},{"id":"fc-231-bf9547","poly":"cardio","fiche":"231","front":"Flutter : quelle fréquence ventriculaire classique ?","back":"**150 bpm** (conduction 2/1).","prio":"P1","sec":"s6"},{"id":"fc-231-6180e9","poly":"cardio","fiche":"231","front":"Flutter et FA : quel lien ?","back":"**Mêmes facteurs favorisants** ; un même patient peut faire les deux.","prio":"P2","sec":"s6"},{"id":"fc-231-324ff2","poly":"cardio","fiche":"231","front":"Flutter droit vs gauche : lequel est le plus fréquent ?","back":"Le flutter **droit**, beaucoup plus fréquent.","prio":"P3","sec":"s6"},{"id":"fc-231-856058","poly":"cardio","fiche":"231","front":"Tachycardie jonctionnelle (maladie de Bouveret) : quelles caractéristiques ?","back":"**Très régulière**, souvent vers **200 bpm** (130-260).","prio":"P1","sec":"s6"},{"id":"fc-231-73f76c","poly":"cardio","fiche":"231","front":"Réentrée intranodale : que voit-on de l'activité atriale ?","back":"Souvent **invisible**, parfois devinée dans le ST.","prio":"P2","sec":"s6"},{"id":"fc-231-e261d2","poly":"cardio","fiche":"231","front":"Rythme réciproque : quel mécanisme ?","back":"Réentrée par une **voie accessoire** (faisceau de Kent).","prio":"P2","sec":"s6"},{"id":"fc-231-2b218e","poly":"cardio","fiche":"231","front":"Tachycardie jonctionnelle : comment la réduire ?","back":"**Manœuvres vagales** ou **adénosine IV**.","prio":"P2","sec":"s6"},{"id":"fc-231-bf6825","poly":"cardio","fiche":"231","front":"Manœuvres vagales : lesquelles ?","back":"**Valsalva**, compression carotidienne **unilatérale**, grand verre d'**eau froide**.","prio":"P2","sec":"s6"},{"id":"fc-231-73cf55","poly":"cardio","fiche":"231","front":"Compression oculaire : est-elle recommandée ?","back":"**Non** (risque de décollement de rétine du myope).","prio":"P3","sec":"s6"},{"id":"fc-231-0383f1","poly":"cardio","fiche":"231","front":"Adénosine IV : quelles modalités et quelle durée d'effet ?","back":"En **flash IV** ; effet d'**une dizaine de secondes**.","prio":"P3","sec":"s6"},{"id":"fc-231-f40655","poly":"cardio","fiche":"231","front":"Adénosine : quelles contre-indications ?","back":"**Asthme**, **hypotension** ou **HTA non contrôlée** (selon les items), **FA sur voie accessoire**.","prio":"P2","sec":"s6"},{"id":"fc-231-817297","poly":"cardio","fiche":"231","front":"Extrasystole atriale : quel aspect ?","back":"P **précoce** de morphologie différente, puis **QRS fin**.","prio":"P2","sec":"s6"},{"id":"fc-231-d5037a","poly":"cardio","fiche":"231","front":"Extrasystole ventriculaire : quel aspect ?","back":"**QRS large** prématuré ± P' rétrograde.","prio":"P1","sec":"s6"},{"id":"fc-231-3e04cf","poly":"cardio","fiche":"231","front":"Extrasystoles fréquentes ou polymorphes : que rechercher ?","back":"Une **cardiopathie**.","prio":"P2","sec":"s6"},{"id":"fc-231-013c02","poly":"cardio","fiche":"231","front":"Bigéminisme : quelle définition ?","back":"Une extrasystole **1 battement sur 2** (trigéminisme : 1 sur 3).","prio":"P3","sec":"s6"},{"id":"fc-231-d087d5","poly":"cardio","fiche":"231","front":"Flutter conduit en 2/1 : comment démasquer les ondes F ?","back":"Par une **manœuvre vagale** (ralentit transitoirement les ventricules).","prio":"P2","sec":"s6"},{"id":"fc-231-8a4d69","poly":"cardio","fiche":"231","front":"TV : quel risque évolutif ?","back":"**TV → FV → asystolie** (plus de la moitié des morts subites).","prio":"P1","sec":"s7"},{"id":"fc-231-ba0f71","poly":"cardio","fiche":"231","front":"TV : quels mécanismes selon le terrain ?","back":"**Réentrée** : la plus fréquente sur cardiopathie (fibrose) ; **automatisme anormal** : le plus fréquent sur cœur sain.","prio":"P2","sec":"s7"},{"id":"fc-231-bd5779","poly":"cardio","fiche":"231","front":"TV : quels critères ECG de suspicion ?","back":"FC **> 100 bpm** + QRS **> 120 ms** sur au moins **3 battements** consécutifs.","prio":"P1","sec":"s7"},{"id":"fc-231-bb50b1","poly":"cardio","fiche":"231","front":"TV non soutenue vs soutenue : quelle limite ?","back":"Non soutenue : 3 battements à **30 s** ; soutenue : **> 30 s**.","prio":"P1","sec":"s7"},{"id":"fc-231-cfe11a","poly":"cardio","fiche":"231","front":"TV : quels arguments ECG de certitude ?","back":"**Dissociation ventriculoatriale** (plus de QRS que de P), **complexes de capture et de fusion**.","prio":"P1","sec":"s7"},{"id":"fc-231-c40edd","poly":"cardio","fiche":"231","front":"TV : quels arguments en faveur (non formels) ?","back":"**Cardiopathie**, **concordance** V1-V6, **axe extrême** (QRS positif en aVR), aspect atypique de bloc.","prio":"P2","sec":"s7"},{"id":"fc-231-af7639","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : quel aspect ECG et quelle conséquence ?","back":"Tachycardie **irrégulière à QRS larges polymorphes** : débit nul, **arrêt cardiaque**.","prio":"P1","sec":"s7"},{"id":"fc-231-228073","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : quel geste en premier ?","back":"**Choc électrique immédiat** ; massage en attendant.","prio":"P1","sec":"s7"},{"id":"fc-231-cc88c2","poly":"cardio","fiche":"231","front":"Torsade de pointes : quelle définition ?","back":"TV **polymorphe** qui s'arrête seule ou dégénère en **FV**.","prio":"P2","sec":"s7"},{"id":"fc-231-b06390","poly":"cardio","fiche":"231","front":"Torsade de pointes installée vs FV : comment les distinguer ?","back":"Par le **QT long** sur les tracés antérieurs et le **contexte**.","prio":"P3","sec":"s7"},{"id":"fc-231-802b11","poly":"cardio","fiche":"231","front":"Tachycardie mal tolérée hémodynamiquement : quelle conduite ?","back":"**Cardioversion électrique externe**, quel que soit l'aspect.","prio":"P1","sec":"s7"},{"id":"fc-231-71862e","poly":"cardio","fiche":"231","front":"Tachycardie bien tolérée : quel effet de l'adénosine oriente vers une TV ?","back":"**Aucun effet** (la TV ne dépend pas du NAV).","prio":"P1","sec":"s7"},{"id":"fc-231-363930","poly":"cardio","fiche":"231","front":"Adénosine ou manœuvre vagale qui arrête la tachycardie : quel diagnostic ?","back":"Une **tachycardie jonctionnelle** (réentrée dépendant du NAV).","prio":"P1","sec":"s7"},{"id":"fc-231-25a12b","poly":"cardio","fiche":"231","front":"Adénosine ou manœuvre vagale qui démasque l'activité atriale : quels diagnostics ?","back":"Tachycardie **sinusale**, **flutter**, **tachycardie atriale**.","prio":"P1","sec":"s7"},{"id":"fc-231-e593e2","poly":"cardio","fiche":"231","front":"Dissociation de la TV vs du BAV3 : quelle différence ?","back":"TV : **plus de QRS que de P** ; BAV3 : **plus de P que de QRS**.","prio":"P1","sec":"s7"},{"id":"fc-231-98a38e","poly":"cardio","fiche":"231","front":"Hypertrophie auriculaire droite : quel critère ?","back":"Onde P **> 2,5 mm en D2** (ou > 2 mm en V1-V2).","prio":"P3","sec":"s8"},{"id":"fc-231-f9a30f","poly":"cardio","fiche":"231","front":"Hypertrophie auriculaire gauche : quel critère ?","back":"Onde P **> 110 ms** (120 en pratique), composante négative **> 40 ms en V1**.","prio":"P3","sec":"s8"},{"id":"fc-231-ced348","poly":"cardio","fiche":"231","front":"Indice de Sokolow : quel calcul et quelle norme ?","back":"**S (V1 ou V2) + R (V5 ou V6)** ; normal **< 35 mm**.","prio":"P1","sec":"s8"},{"id":"fc-231-d6d58a","poly":"cardio","fiche":"231","front":"HVG sévère : quels signes de repolarisation ?","back":"**T négatives** avec **sous-ST** en latéral, **disparition de la q septale**.","prio":"P2","sec":"s8"},{"id":"fc-231-cc6c49","poly":"cardio","fiche":"231","front":"HVG électrique : quelles causes les plus fréquentes ?","back":"**HTA**, puis **rétrécissement aortique**.","prio":"P1","sec":"s8"},{"id":"fc-231-8bc704","poly":"cardio","fiche":"231","front":"HVG importante : quels aspects pièges en V1-V2 ?","back":"**QS** (pseudonécrose) et **pseudo sus-décalage de ST**.","prio":"P2","sec":"s8"},{"id":"fc-231-997ba9","poly":"cardio","fiche":"231","front":"HVD : quel est le signe ECG le plus précoce ?","back":"**Axe > 110°** (90° en pratique).","prio":"P3","sec":"s8"},{"id":"fc-231-4fa336","poly":"cardio","fiche":"231","front":"Embolie pulmonaire : quel aspect ECG d'hypertrophie aiguë ?","back":"**S1Q3T3** (S en D1, Q et T négative en D3).","prio":"P3","sec":"s8"},{"id":"fc-231-592c72","poly":"cardio","fiche":"231","front":"Hypokaliémie : quels signes ECG ?","back":"T **plates ou négatives**, **sous-ST**, **QT allongé**, **onde U**.","prio":"P1","sec":"s9"},{"id":"fc-231-ada778","poly":"cardio","fiche":"231","front":"Hypokaliémie : quels troubles du rythme ?","back":"Extrasystoles, TV, **torsade de pointes**, FV.","prio":"P2","sec":"s9"},{"id":"fc-231-6de25c","poly":"cardio","fiche":"231","front":"Hyperkaliémie : quels signes ECG ?","back":"T **amples, pointues, symétriques**, **PR allongé**, **QRS élargi**.","prio":"P1","sec":"s9"},{"id":"fc-231-f5697a","poly":"cardio","fiche":"231","front":"Hyperkaliémie : quels troubles de conduction et du rythme ?","back":"**BAV**, **dysfonction sinusale**, TV.","prio":"P1","sec":"s9"},{"id":"fc-231-46e9ce","poly":"cardio","fiche":"231","front":"QT long : quel risque ?","back":"La **torsade de pointes**.","prio":"P2","sec":"s9"},{"id":"fc-231-3e0a36","poly":"cardio","fiche":"231","front":"QT long : quelles causes ?","back":"**Bradycardie extrême**, **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** associés, QT long **congénital**.","prio":"P1","sec":"s9"},{"id":"fc-231-221d40","poly":"cardio","fiche":"231","front":"QT long sur un ECG : quel réflexe ?","back":"**Vérifier les médicaments** et le **ionogramme**.","prio":"P2","sec":"s9"},{"id":"fc-231-0da2da","poly":"cardio","fiche":"231","front":"Péricardite aiguë : quels signes ECG de la phase 1 ?","back":"**Microvoltage**, sus-ST **concave, diffus, sans miroir**, **sous-décalage de PQ**.","prio":"P2","sec":"s9"},{"id":"fc-231-bbc194","poly":"cardio","fiche":"231","front":"Péricardite aiguë : quelle évolution ECG après la phase 1 ?","back":"T plates, puis **T négatives** persistantes, puis retour progressif à la normale.","prio":"P3","sec":"s9"},{"id":"fc-231-1455bc","poly":"cardio","fiche":"231","front":"Préexcitation (voie accessoire) : quels signes ECG ?","back":"**PR court < 120 ms**, **onde delta**, anomalies de repolarisation.","prio":"P2","sec":"s9"},{"id":"fc-231-ea48bd","poly":"cardio","fiche":"231","front":"Syndrome de Wolff-Parkinson-White : quelle définition ?","back":"**Voie accessoire** antérograde + palpitations par **tachycardie jonctionnelle**.","prio":"P2","sec":"s9"},{"id":"fc-231-86a3c6","poly":"cardio","fiche":"231","front":"FA préexcitée (super-Wolff) : quel aspect ECG ?","back":"Tachycardie **irrégulière, très rapide**, QRS de largeur variable **« en accordéon »**.","prio":"P2","sec":"s9"},{"id":"fc-231-a9ea01","poly":"cardio","fiche":"231","front":"FA préexcitée : quels gestes sont interdits ?","back":"**Bloquer le NAV** : ni massage, ni adénosine (risque de FV).","prio":"P2","sec":"s9"},{"id":"fc-231-0d1e80","poly":"cardio","fiche":"231","front":"SCA ST+ : où se trouve le sus-décalage ?","back":"**En regard de la paroi qui souffre** ; le sous-décalage ailleurs est un **miroir**.","prio":"P1","sec":"s10"},{"id":"fc-231-22219a","poly":"cardio","fiche":"231","front":"Douleur thoracique : quel ECG réaliser ?","back":"Un **ECG 18 dérivations** (+ V7-V9, V3R-V4R).","prio":"P1","sec":"s10"},{"id":"fc-231-4621d8","poly":"cardio","fiche":"231","front":"Ondes T négatives : quand sont-elles pathologiques ?","back":"**Deux T négatives dans un même territoire** (ex. D2 et D3).","prio":"P1","sec":"s10"},{"id":"fc-231-828e2c","poly":"cardio","fiche":"231","front":"T négatives dans toutes les précordiales : quelle étiologie éliminer en premier ?","back":"L'**ischémie myocardique**.","prio":"P2","sec":"s10"},{"id":"fc-231-3215fa","poly":"cardio","fiche":"231","front":"Sus-décalage du ST : quels critères de significativité ?","back":"**≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **au moins 2 dérivations adjacentes**.","prio":"P1","sec":"s10"},{"id":"fc-231-fd542b","poly":"cardio","fiche":"231","front":"Onde de Pardee : quelle définition ?","back":"Sus-décalage du ST qui **englobe l'onde T**.","prio":"P1","sec":"s10"},{"id":"fc-231-e730e9","poly":"cardio","fiche":"231","front":"BBG complet + douleur thoracique aiguë : que faut-il éliminer ?","back":"Un **SCA ST+** (échographie ± coronarographie).","prio":"P1","sec":"s10"},{"id":"fc-231-3c2333","poly":"cardio","fiche":"231","front":"SCA ST+ : comment évolue le sus-décalage avec et sans reperfusion ?","back":"Avec reperfusion : **régression rapide** ; sans : persiste **plusieurs jours** ; indéfiniment si **anévrisme**.","prio":"P2","sec":"s10"},{"id":"fc-231-f667c9","poly":"cardio","fiche":"231","front":"SCA ST+ : quand apparaît l'onde T négative ?","back":"Après **48 h**.","prio":"P2","sec":"s10"},{"id":"fc-231-b9ba85","poly":"cardio","fiche":"231","front":"Ondes Q de nécrose : quand apparaissent-elles et quels critères ?","back":"**En principe** vers la **6ᵉ heure** (parfois plus tôt) ; **≥ 1/3 (ou 1/4)** de l'amplitude du QRS et **> 30-40 ms**.","prio":"P1","sec":"s10"},{"id":"fc-231-7601f4","poly":"cardio","fiche":"231","front":"Ondes Q de nécrose : quel équivalent ECG ?","back":"Le **rabotage** (écrêtement) de l'onde R, surtout décrit en **V2-V3-V4**.","prio":"P3","sec":"s10"},{"id":"fc-231-5a2a1f","poly":"cardio","fiche":"231","front":"SCA sans sus-décalage : quels aspects ECG possibles ?","back":"**Sous-ST**, **T inversées**, **pseudo-normalisation** de T, T aplaties, ou **ECG normal**.","prio":"P1","sec":"s10"},{"id":"fc-231-1aa176","poly":"cardio","fiche":"231","front":"Sus-décalage du ST : quelles sont les 5 causes ?","back":"**SCA**, **anévrisme** ventriculaire, **repolarisation précoce**, **Prinzmetal**, **péricardite**.","prio":"P2","sec":"s10"},{"id":"fc-231-38a5a5","poly":"cardio","fiche":"231","front":"Sus-ST de péricardite vs de SCA : quelle différence ECG ?","back":"Péricardite : **diffus, concave, sans miroir** ; SCA : Pardee **avec miroir**.","prio":"P2","sec":"s10"},{"id":"fc-231-0d87a5","poly":"cardio","fiche":"231","front":"SCA ST+ sans miroir : peut-on conclure à une péricardite ?","back":"**Non** : un SCA ST+ peut manquer de miroir.","prio":"P2","sec":"s10"},{"id":"fc-231-d6a93b","poly":"cardio","fiche":"231","front":"Ondes Q déjà présentes sur un SCA ST+ : la reperfusion est-elle inutile ?","back":"**Non**, elle reste utile.","prio":"P1","sec":"s10"},{"id":"fc-231-05d984","poly":"cardio","fiche":"231","front":"Pacemaker : dans quelles bradycardies est-il indiqué ?","back":"Bradycardies **symptomatiques** ; **BAV infrahissiens** (Mobitz 2, BAV3) **même sans symptôme**.","prio":"P2","sec":"s11"},{"id":"fc-231-707da6","poly":"cardio","fiche":"231","front":"Défibrillateur implantable : quelle fonction en plus de la défibrillation ?","back":"Il fait **toujours pacemaker** (sauf le défibrillateur sous-cutané).","prio":"P3","sec":"s11"},{"id":"fc-231-206912","poly":"cardio","fiche":"231","front":"Resynchronisation cardiaque : quelle indication de principe ?","back":"**BBG** qui désynchronise le VG + **insuffisance cardiaque**.","prio":"P3","sec":"s11"},{"id":"fc-231-84d00d","poly":"cardio","fiche":"231","front":"Spike de stimulation : pourquoi est-il pathognomonique ?","back":"Impulsion de **0,4 à 1 ms**, plus brève que tout phénomène physiologique.","prio":"P3","sec":"s11"},{"id":"fc-231-d6258c","poly":"cardio","fiche":"231","front":"Stimulation bipolaire : quel piège ECG ?","back":"Le spike est **peu visible** et peut passer inaperçu.","prio":"P3","sec":"s11"},{"id":"fc-231-2de4f7","poly":"cardio","fiche":"231","front":"Pacemaker pour BAV : quel aspect ECG après le spike ?","back":"**QRS large d'aspect BBG** (stimulation du VD).","prio":"P2","sec":"s11"},{"id":"fc-231-89b628","poly":"cardio","fiche":"231","front":"Pacemaker pour dysfonction sinusale : quel aspect après le spike ?","back":"Une **onde P** suit le spike (stimulation atriale).","prio":"P3","sec":"s11"},{"id":"fc-231-81d2e5","poly":"cardio","fiche":"231","front":"Pacemaker et SCA : quel piège ECG ?","back":"Le pacemaker peut **masquer** les anomalies ischémiques.","prio":"P2","sec":"s11"},{"id":"fc-231-949492","poly":"cardio","fiche":"231","front":"ECG en urgence : quelles indications ?","back":"**Défaillance d'organe**, **douleur thoracique**, **palpitations**, **syncope**, troubles **K/Ca**.","prio":"P1","sec":"s12"},{"id":"fc-231-b28108","poly":"cardio","fiche":"231","front":"ECG : quelles urgences absolues (item 237) ?","back":"Tachycardie **régulière à QRS larges** ; repolarisation évoquant un **SCA** ; QRS fins **> 150/min** avec signes de gravité.","prio":"P1","sec":"s12"},{"id":"fc-231-eb634f","poly":"cardio","fiche":"231","front":"Monitorage ECG (scope) : quelles indications ?","back":"**Urgences**, réanimation, **transfert médicalisé**, soins intensifs, **syncope** rythmique suspectée, peropératoire.","prio":"P2","sec":"s12"},{"id":"fc-231-12c7c7","poly":"cardio","fiche":"231","front":"ECG 12 dérivations : dans quel bilan est-il obligatoire ?","back":"Le bilan de l'**HTA**.","prio":"P1","sec":"s12"},{"id":"fc-231-babf38","poly":"cardio","fiche":"231","front":"ECG préopératoire : à partir de quel âge ?","back":"Après **65 ans** (ou patient/intervention à risque).","prio":"P2","sec":"s12"},{"id":"fc-231-9abaf7","poly":"cardio","fiche":"231","front":"Holter ECG : quelles caractéristiques ?","back":"**2 à 12 dérivations**, **24 à 96 h**, lu en différé.","prio":"P3","sec":"s12"},{"id":"fc-231-57900c","poly":"cardio","fiche":"231","front":"Holter de 24 h : quelle condition pour l'indiquer devant des symptômes ?","back":"Symptômes **épisodiques** susceptibles de **revenir pendant l'enregistrement**, ECG standard non contributif.","prio":"P3","sec":"s12"},{"id":"fc-231-1a052d","poly":"cardio","fiche":"231","front":"Holter implantable : quelle durée et quelles indications ?","back":"Jusqu'à **3 ans** ; **syncope inexpliquée** ou **FA silencieuse**.","prio":"P3","sec":"s12"},{"id":"fc-231-a892d3","poly":"cardio","fiche":"231","front":"Symptômes rythmiques rares : quel enregistrement proposer ?","back":"ECG ambulatoire jusqu'à **21 jours** ou enregistreur d'événements.","prio":"P3","sec":"s12"},{"id":"fc-231-858c29","poly":"cardio","fiche":"231","front":"Tachycardie (FC > 100/min) : quelle première mesure ?","back":"**Monitorage ECG** continu.","prio":"P2","sec":"s13"},{"id":"fc-231-6b3e5a","poly":"cardio","fiche":"231","front":"Tachycardie bien tolérée à QRS fins : quelle séquence diagnostique ?","back":"**Manœuvres vagales**, puis **adénosine IV** en flash si échec.","prio":"P1","sec":"s13"},{"id":"fc-231-76e929","poly":"cardio","fiche":"231","front":"Flutter d'aspect typique : comment confirmer son caractère typique ?","back":"Par l'**exploration électrophysiologique** qui précède l'**ablation par radiofréquence**.","prio":"P3","sec":"s13"},{"id":"fc-231-56b875","poly":"cardio","fiche":"231","front":"Réentrée intranodale : quel est le traitement de référence au long cours ?","back":"L'**ablation de la voie lente**.","prio":"P2","sec":"s13"},{"id":"fc-231-1e2961","poly":"cardio","fiche":"231","front":"Cardioversion d'une FA : quelle anticoagulation préalable ?","back":"**3 semaines** d'anticoagulation efficace (sauf ETO sans thrombus, FA < 24 h ou urgence vitale).","prio":"P1","sec":"s13"},{"id":"fc-231-f34c20","poly":"cardio","fiche":"231","front":"Après cardioversion d'une FA : combien de temps poursuivre l'anticoagulation ?","back":"**4 semaines au minimum**.","prio":"P1","sec":"s13"},{"id":"fc-231-d205a3","poly":"cardio","fiche":"231","front":"Tachycardie sinusale : quel traitement ?","back":"Traiter la **cause** (nécessaire et le plus souvent suffisant).","prio":"P1","sec":"s13"},{"id":"fc-231-ca4170","poly":"cardio","fiche":"231","front":"Compression carotidienne : quelles contre-indications ?","back":"**Athérome** important ou **souffle carotidien**.","prio":"P3","sec":"s13"},{"id":"fc-231-71ac60","poly":"cardio","fiche":"231","front":"TV suspectée : quelles premières mesures ?","back":"**Alerte (15)**, préparation à la réanimation, **monitorage ECG** continu.","prio":"P1","sec":"s14"},{"id":"fc-231-ba7eed","poly":"cardio","fiche":"231","front":"TV : quel effet des manœuvres vagales et de l'adénosine sur sa fréquence ?","back":"En général **aucun effet**.","prio":"P2","sec":"s14"},{"id":"fc-231-5f4a4d","poly":"cardio","fiche":"231","front":"Après une TV symptomatique : quel dispositif en prévention secondaire ?","back":"Un **défibrillateur automatique implantable**.","prio":"P1","sec":"s14"},{"id":"fc-231-a42543","poly":"cardio","fiche":"231","front":"Fibrillation ventriculaire : peut-elle se réduire spontanément ?","back":"**Jamais**.","prio":"P2","sec":"s14"},{"id":"fc-231-23e93e","poly":"cardio","fiche":"231","front":"FV : dans quel délai délivrer idéalement le premier choc ?","back":"**Dans les 3 minutes** ; à défaut, toujours débuter le massage.","prio":"P1","sec":"s14"},{"id":"fc-231-c9dc48","poly":"cardio","fiche":"231","front":"Massage cardiaque externe : quelles modalités ?","back":"Centre du thorax, **4 à 5 cm**, **100/min**, relais environ toutes les **2 min**.","prio":"P1","sec":"s14"},{"id":"fc-231-1d4f75","poly":"cardio","fiche":"231","front":"Après un choc par DSA : quand vérifier la reprise circulatoire ?","back":"Après **2 minutes** de RCP.","prio":"P2","sec":"s14"},{"id":"fc-231-4d9230","poly":"cardio","fiche":"231","front":"Défibrillateur biphasique : quelle énergie ?","back":"Jusqu'à **200 J** (monophasique : 360 J).","prio":"P3","sec":"s14"},{"id":"fc-231-1d7746","poly":"cardio","fiche":"231","front":"FV réfractaire : quand donner adrénaline et amiodarone ?","back":"Après échec de **2 chocs** : adrénaline + **amiodarone 300 mg**.","prio":"P2","sec":"s14"},{"id":"fc-231-3f2cb1","poly":"cardio","fiche":"231","front":"Arrêt cardiaque : quelle posologie d'adrénaline ?","back":"**1 mg toutes les 4 min** IV.","prio":"P2","sec":"s14"},{"id":"fc-231-d3342d","poly":"cardio","fiche":"231","front":"Lidocaïne dans la FV : quand l'utiliser ?","back":"**Seulement si l'amiodarone n'est pas disponible** (aucun bénéfice démontré).","prio":"P3","sec":"s14"},{"id":"fc-231-53d1ff","poly":"cardio","fiche":"231","front":"Asystolie : faut-il défibriller ?","back":"**Non** : massage.","prio":"P1","sec":"s14"},{"id":"fc-231-0a9d06","poly":"cardio","fiche":"231","front":"Après récupération d'un arrêt cardiaque : quelles mesures ?","back":"Contrôle **thermique** et **glycémique**, éviter hypoxie/hypercapnie, **coronarographie** au moindre doute.","prio":"P2","sec":"s14"},{"id":"fc-231-943f00","poly":"cardio","fiche":"231","front":"Arrêt cardiaque récupéré : quelle est la 1re étiologie ?","back":"La **cardiopathie ischémique**.","prio":"P2","sec":"s14"},{"id":"fc-231-cc1f50","poly":"cardio","fiche":"231","front":"Après arrêt cardiaque par FV récupéré : quel dispositif ?","back":"Un **défibrillateur automatique implantable** (prévention secondaire).","prio":"P1","sec":"s14"},{"id":"fc-231-394d1e","poly":"cardio","fiche":"231","front":"Insuffisant cardiaque à FEVG diminuée : quel seul antiarythmique possible ?","back":"L'**amiodarone**.","prio":"P2","sec":"s14"},{"id":"fc-231-45f364","poly":"cardio","fiche":"231","front":"RCP de l'adulte : quelle place du bouche-à-bouche ?","back":"**Plus recommandé** : le **massage** reste prioritaire.","prio":"P2","sec":"s14"},{"id":"fc-231-0b7785","poly":"cardio","fiche":"231","front":"Thrombolyse préhospitalière dans l'arrêt cardiaque : est-elle recommandée ?","back":"**Non**, sauf au cas par cas (IDM ou EP massive avérés ou fortement suspectés).","prio":"P3","sec":"s14"},{"id":"fc-231-b6bb96","poly":"cardio","fiche":"231","front":"QT long ou torsade de pointes : quels traitements ?","back":"**Corriger les troubles ioniques**, **accélérer la FC**, **arrêter les médicaments** allongeant le QT.","prio":"P2","sec":"s15"},{"id":"fc-231-bffab9","poly":"cardio","fiche":"231","front":"Torsade de pointes : comment accélérer la fréquence cardiaque ?","back":"**Isoprénaline** ou **stimulation** percutanée.","prio":"P2","sec":"s15"},{"id":"fc-231-7a4435","poly":"cardio","fiche":"231","front":"Torsade de pointes : quel sel minéral et quelle dose ?","back":"**Sulfate de magnésium 2 g IV directe**.","prio":"P2","sec":"s15"},{"id":"fc-231-de5e70","poly":"cardio","fiche":"231","front":"Isoprénaline : quelle contre-indication ?","back":"L'**IDM aigu**.","prio":"P2","sec":"s15"},{"id":"fc-231-e29058","poly":"cardio","fiche":"231","front":"Torsade de pointes sur BAV3 : quelle signification ?","back":"Un **signe de gravité** (éviter les médicaments allongeant le QT).","prio":"P3","sec":"s15"},{"id":"fc-231-a19288","poly":"cardio","fiche":"231","front":"FA préexcitée : quel traitement après la phase aiguë ?","back":"L'**ablation de la voie accessoire**.","prio":"P3","sec":"s15"},{"id":"fc-231-c149e7","poly":"cardio","fiche":"231","front":"Sous-décalage du ST de V1 à V3 : quelle conduite ?","back":"Possible **miroir** d'un sus-ST **postérieur** : regarder **V7-V9**.","prio":"P1","sec":"s16"},{"id":"fc-231-9617ea","poly":"cardio","fiche":"231","front":"BBG ou BAV3 à QRS larges chez un douloureux thoracique : quelle limite de l'ECG ?","back":"ECG **non informatif** pour le sus-ST : coronarographie urgente à discuter.","prio":"P2","sec":"s16"},{"id":"fc-231-b981bf","poly":"cardio","fiche":"231","front":"SCA ST+ : quel délai pour préférer l'angioplastie primaire ?","back":"Faisable dans les **120 min**, sinon **fibrinolyse**.","prio":"P1","sec":"s16"},{"id":"fc-231-2ad74c","poly":"cardio","fiche":"231","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion est-il faible ?","back":"Après la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P2","sec":"s16"},{"id":"fc-231-1f4ace","poly":"cardio","fiche":"231","front":"SCA ST+ fibrinolysé : quel P2Y12 ?","back":"**Clopidogrel seul** (charge 300 mg si < 75 ans).","prio":"P1","sec":"s16"},{"id":"fc-231-f0ff93","poly":"cardio","fiche":"231","front":"SCA : quand donner de l'oxygène ?","back":"**Seulement si hypoxémie** (SaO₂ < 90 % ou PaO₂ < 60 mmHg).","prio":"P1","sec":"s16"},{"id":"fc-231-e40a81","poly":"cardio","fiche":"231","front":"SCA : quelle posologie d'aspirine ?","back":"**250 mg IVD** puis **75-100 mg/j**.","prio":"P1","sec":"s16"},{"id":"fc-231-57149f","poly":"cardio","fiche":"231","front":"Bradycardie : quels signes de mauvaise tolérance ?","back":"**Syncope**/lipothymie, angor, **IC**, choc, oligurie, signes neurologiques de bas débit, **torsade**.","prio":"P1","sec":"s17"},{"id":"fc-231-688ddd","poly":"cardio","fiche":"231","front":"BAV3, Mobitz 2 ou BAV de haut degré : quelle orientation ?","back":"**Risque vital** : hospitalisation en **Usic** avec scope.","prio":"P1","sec":"s17"},{"id":"fc-231-c1e06a","poly":"cardio","fiche":"231","front":"Bradycardie : quelles causes aiguës réversibles rechercher ?","back":"**IDM ST+**, **médicament bradycardisant**, **hyperkaliémie**.","prio":"P1","sec":"s17"},{"id":"fc-231-44de2e","poly":"cardio","fiche":"231","front":"Bradycardie mal tolérée : quels traitements d'urgence ?","back":"**Atropine** ou **isoprénaline**, ou **stimulation temporaire**.","prio":"P1","sec":"s17"},{"id":"fc-231-780e2d","poly":"cardio","fiche":"231","front":"Atropine : sur quels troubles conductifs agit-elle ?","back":"**BAV nodaux** et **dysfonction sinusale** seulement (aggrave un bloc infrahissien).","prio":"P2","sec":"s17"},{"id":"fc-231-b71ad7","poly":"cardio","fiche":"231","front":"BAV au cours d'un SCA ST+ inférieur : quelles caractéristiques ?","back":"BAV **nodal**, répond à l'**atropine**, habituellement **transitoire**.","prio":"P1","sec":"s17"},{"id":"fc-231-770d46","poly":"cardio","fiche":"231","front":"BAV au cours d'un SCA ST+ antérieur : quelles caractéristiques ?","back":"BAV **infranodal**, ne répond pas à l'atropine ; souvent **stimulateur définitif**.","prio":"P1","sec":"s17"},{"id":"fc-231-75b9fe","poly":"cardio","fiche":"231","front":"BAV sur IDM inférieur non régressif : quand discuter un stimulateur ?","back":"S'il n'a pas régressé à **J5**.","prio":"P3","sec":"s17"},{"id":"fc-231-f684bc","poly":"cardio","fiche":"231","front":"Bradycardie sans cause curable : quelles indications de stimulateur ?","back":"**Mobitz 2**, **BAV3**, BAV de haut degré ; dysfonction sinusale seulement si **symptomatique**.","prio":"P1","sec":"s17"},{"id":"fc-231-39bfa0","poly":"cardio","fiche":"231","front":"Syncope avec troubles conductifs ou blocs alternants : quelle conduite ?","back":"**Hospitalisation urgente** et recherche d'une **cardiopathie**.","prio":"P1","sec":"s17"},{"id":"fc-231-b6cf3b","poly":"cardio","fiche":"231","front":"Exploration électrophysiologique : quel HV impose un stimulateur ?","back":"**HV ≥ 70 ms**.","prio":"P3","sec":"s17"},{"id":"fc-231-6d4f0a","poly":"cardio","fiche":"231","front":"Resynchronisation cardiaque : quels critères d'indication ?","back":"IC symptomatique (**NYHA II-IV**), **FEVG ≤ 35 %**, **QRS ≥ 130 ms**.","prio":"P2","sec":"s17"},{"id":"fc-231-4b5f62","poly":"cardio","fiche":"231","front":"Syncope chez un cardiaque avec bloc de branche : quelle autre cause évoquer qu'un BAV ?","back":"Une **TV**.","prio":"P1","sec":"s17"},{"id":"fc-231-4b9da6","poly":"cardio","fiche":"231","front":"BAV complet vs dysfonction sinusale : lequel est le plus grave ?","back":"Le **BAV complet** (torsades, asystolie).","prio":"P2","sec":"s17"},{"id":"fc-231-bfc8be","poly":"cardio","fiche":"231","front":"Onde de Pardee : avec quoi ne pas la confondre ?","back":"Avec un **élargissement du QRS**.","prio":"P2","sec":"s18"},{"id":"fc-231-e63e7b","poly":"cardio","fiche":"231","front":"P régulières à fréquence normale : prouvent-elles un rythme sinusal ?","back":"**Non** : BAV3 si elles ne sont pas conduites.","prio":"P2","sec":"s18"},{"id":"fc-231-3bd9b5","poly":"cardio","fiche":"231","front":"SCA ST+ traité par angioplastie : quel inhibiteur P2Y12 et pour quelle durée ?","back":"**Prasugrel** ou **ticagrélor** (clopidogrel si CI) ; **12 mois**.","prio":"P2","sec":"s16"},{"id":"fc-231-171d1f","poly":"cardio","fiche":"231","front":"Inhibiteurs P2Y12 du SCA ST+ : quelles doses de charge et d'entretien ?","back":"Prasugrel **60 mg** puis **10 mg/j** ; ticagrélor **180 mg** puis **90 mg** ×2/j ; clopidogrel **600 mg** puis **75 mg/j**.","prio":"P3","sec":"s16"},{"id":"fc-231-422c84","poly":"cardio","fiche":"231","front":"Prasugrel : quelles restrictions d'emploi ?","back":"CI si **ATCD d'AVC** ; non recommandé après **75 ans** et/ou si poids **< 60 kg**.","prio":"P3","sec":"s16"},{"id":"fc-231-b9a9b0","poly":"cardio","fiche":"231","front":"FV/TV réfractaire : quelle dose d'amiodarone si elle persiste ou récidive après la 1re dose ?","back":"**150 mg** (après 300 mg juste avant le 3ᵉ choc).","prio":"P3","sec":"s14"},{"id":"fc-231-c5412b","poly":"cardio","fiche":"231","front":"Flutters atypiques : quel circuit et quelle fréquence atriale ?","back":"Isthme cavotricuspide **non impliqué** (droits, gauches ou biatriaux) ; **120-320 bpm**, morphologies variables.","prio":"P3","sec":"s6"},{"id":"fc-232-8f5dd6","poly":"cardio","fiche":"232","front":"FA : quelle est sa définition ?","back":"Tachycardie **irrégulière** (arythmie) d'origine **supraventriculaire**.","prio":"P1","sec":"s1"},{"id":"fc-232-aa7a86","poly":"cardio","fiche":"232","front":"FA : à quelle fréquence se fait l'activité électrique des oreillettes ?","back":"**400 à 600/min**, de façon rapide et **désordonnée** (oreillettes sans contraction efficace).","prio":"P1","sec":"s1"},{"id":"fc-232-890dad","poly":"cardio","fiche":"232","front":"FA : quelle structure détermine la fréquence ventriculaire ?","back":"Le **nœud AV**, qui filtre et ne laisse passer qu'une partie des influx, au hasard → rythme ventriculaire **irrégulier**.","prio":"P1","sec":"s1"},{"id":"fc-232-2f1cf8","poly":"cardio","fiche":"232","front":"FA : de quoi dépend le filtrage par le nœud AV ?","back":"Du **système nerveux autonome** et des **médicaments bradycardisants** (cible des freinateurs nodaux).","prio":"P2","sec":"s1"},{"id":"fc-232-61facf","poly":"cardio","fiche":"232","front":"FA « clinique » : sur quel examen et quel critère est-elle retenue ?","back":"**ECG** monopiste ou 12 dérivations : activation atriale anarchique **sans onde P** individualisable.","prio":"P1","sec":"s1"},{"id":"fc-232-3ff0a2","poly":"cardio","fiche":"232","front":"ECG de FA : une durée minimale d'enregistrement de 30 s est-elle encore exigée ?","back":"**Non**, cette durée minimale n'est plus exigée.","prio":"P2","sec":"s1"},{"id":"fc-232-04e6a1","poly":"cardio","fiche":"232","front":"FA évoquée sur la seule photopléthysmographie (montre) : diagnostic valide ?","back":"**Non valide** : il faut un tracé **ECG** (un ECG monopiste connecté convient).","prio":"P1","sec":"s1"},{"id":"fc-232-adcbd3","poly":"cardio","fiche":"232","front":"FA : quelle est sa place parmi les troubles du rythme ?","back":"Le trouble du rythme **le plus fréquent**, **lié à l'âge**.","prio":"P2","sec":"s1"},{"id":"fc-232-69a7dc","poly":"cardio","fiche":"232","front":"FA : combien de patients en France ?","back":"**500 000 à 750 000**.","prio":"P3","sec":"s1"},{"id":"fc-232-03eb7a","poly":"cardio","fiche":"232","front":"FA : comment évolue sa prévalence avec l'âge ?","back":"**Rare avant 50 ans** ; environ **10 %** de la population **après 80 ans**.","prio":"P2","sec":"s1"},{"id":"fc-232-8dce94","poly":"cardio","fiche":"232","front":"Obésité et FA : effet de chaque +5 kg/m² d'IMC ?","back":"Fréquence de la FA augmentée de **30 %**.","prio":"P3","sec":"s1"},{"id":"fc-232-e67a00","poly":"cardio","fiche":"232","front":"FA : quelle part de l'ensemble des AVC lui est due ?","back":"**20 à 25 %** des AVC (par embolie cérébrale).","prio":"P2","sec":"s1"},{"id":"fc-232-dd9d4b","poly":"cardio","fiche":"232","front":"FA et flutter atrial : quel lien ?","back":"La FA peut **succéder** à un flutter (typique ou atypique) ou lui être **associée**.","prio":"P3","sec":"s1"},{"id":"fc-232-83e61f","poly":"cardio","fiche":"232","front":"FA et insuffisance cardiaque : quel lien ?","back":"La FA peut **révéler ou aggraver** une insuffisance cardiaque.","prio":"P2","sec":"s1"},{"id":"fc-232-760980","poly":"cardio","fiche":"232","front":"FA : citer ses 4 conséquences hémodynamiques ?","back":"**Perte de la systole atriale** ; FC mal adaptée à l'effort ; **insuffisance cardiaque** ; risque **thromboembolique**.","prio":"P2","sec":"s1"},{"id":"fc-232-a20012","poly":"cardio","fiche":"232","front":"FA : comment se comporte la fréquence ventriculaire à l'effort ?","back":"Tachycardie irrégulière au repos qui **s'accélère à l'effort**.","prio":"P3","sec":"s1"},{"id":"fc-232-448bd8","poly":"cardio","fiche":"232","front":"FA : où se forme le thrombus et où migre-t-il ?","back":"Dans l'**auricule gauche** (stase) → **circulation systémique** (grande circulation).","prio":"P1","sec":"s1"},{"id":"fc-232-755f59","poly":"cardio","fiche":"232","front":"FA : quel cercle vicieux entretient l'arythmie ?","back":"**Dilatation** atriale (remodelage) qui, à son tour, entretient la FA ; évolution aussi vers la **fibrose** des oreillettes puis, plus tard, du tissu de conduction.","prio":"P3","sec":"s1"},{"id":"fc-232-79cc4d","poly":"cardio","fiche":"232","front":"FA et embolie pulmonaire : cause ou complication ?","back":"L'EP est une **cause** possible de FA, **pas une complication** (les emboles de FA vont dans la grande circulation).","prio":"P1","sec":"s1"},{"id":"fc-232-59aa60","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA paroxystique ?","back":"Retour en sinusal (spontané ou après cardioversion) en **moins de 7 jours**.","prio":"P2","sec":"s2"},{"id":"fc-232-7b7640","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA persistante ?","back":"Retour en sinusal (spontané ou après cardioversion) **au-delà de 7 jours**.","prio":"P2","sec":"s2"},{"id":"fc-232-0eef41","poly":"cardio","fiche":"232","front":"Classification de la FA : définition de la FA permanente ?","back":"Échec ou absence de tentative de cardioversion : stratégie de **contrôle de la fréquence**, on ne cherche plus le sinusal.","prio":"P2","sec":"s2"},{"id":"fc-232-cc415d","poly":"cardio","fiche":"232","front":"Premier épisode de FA : comment le classe-t-on ?","back":"**Pas encore classable**.","prio":"P3","sec":"s2"},{"id":"fc-232-d60d6e","poly":"cardio","fiche":"232","front":"Cardioversion (réduction) : définition ?","back":"Tout geste médical qui rétablit le rythme sinusal : **médicament** ou **choc électrique**.","prio":"P2","sec":"s2"},{"id":"fc-232-900b15","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : définition ?","back":"Coexistence d'une FA **paroxystique** et d'une **dysfonction sinusale** (syndrome bradycardie-tachycardie), surtout chez le **sujet âgé**.","prio":"P2","sec":"s2"},{"id":"fc-232-c4ffb3","poly":"cardio","fiche":"232","front":"FA de cause aiguë (à distinguer des FA récidivantes) : exemples ?","back":"FA **postopératoire**, **infarctus**, infection pulmonaire, **péricardite**…","prio":"P2","sec":"s2"},{"id":"fc-232-870cca","poly":"cardio","fiche":"232","front":"Type de FA (paroxystique, persistante, permanente) : rôle dans l'anticoagulation au long cours ?","back":"**Aucun** : seul compte le risque (**CHA₂DS₂-VA**, terrain).","prio":"P1","sec":"s2"},{"id":"fc-232-325e28","poly":"cardio","fiche":"232","front":"FA : 3 grandes circonstances de découverte ?","back":"**Fortuite** (patient asymptomatique) ; **bilan d'un symptôme** (palpitations, essoufflement récent) ; **complication révélatrice** (AVC, poussée d'IC).","prio":"P1","sec":"s3"},{"id":"fc-232-f6f443","poly":"cardio","fiche":"232","front":"FA : symptômes usuels ?","back":"**Palpitations** ; **dyspnée d'effort** ; **angor fonctionnel** ; **asthénie** inexpliquée.","prio":"P1","sec":"s3"},{"id":"fc-232-f8738a","poly":"cardio","fiche":"232","front":"FA : symptôme trompeur typique de la personne âgée ?","back":"**Chutes inexpliquées** (et lipothymies).","prio":"P1","sec":"s3"},{"id":"fc-232-a26066","poly":"cardio","fiche":"232","front":"FA : autres symptômes trompeurs ?","back":"Incapacité à l'effort, accès de « faiblesse », cœur qui « bat trop lentement », **bouffées de chaleur**, **œdèmes des MI** ; rarement syncope (pause de régularisation).","prio":"P2","sec":"s3"},{"id":"fc-232-0eb32a","poly":"cardio","fiche":"232","front":"FA : valeur du pouls et du récit des palpitations pour le diagnostic ?","back":"**Mal corrélés** à la FA réelle (signes absents ou intermittents) → **ECG indispensable**.","prio":"P1","sec":"s3"},{"id":"fc-232-907927","poly":"cardio","fiche":"232","front":"FA paroxystique : comment la prendre sur le fait ?","back":"**Holter** ou autre monitorage ECG.","prio":"P1","sec":"s3"},{"id":"fc-232-afcdc7","poly":"cardio","fiche":"232","front":"FA : que trouve l'auscultation ?","back":"Bruits du cœur **irréguliers**, rythme plus ou moins rapide.","prio":"P2","sec":"s3"},{"id":"fc-232-abc82c","poly":"cardio","fiche":"232","front":"FA au lit du patient : 4 objectifs de la prise en charge initiale ?","back":"**Tolérance** ; **complication** d'emblée ; **cardiopathie** sous-jacente ; **facteurs déclenchants ou favorisants**.","prio":"P1","sec":"s3"},{"id":"fc-232-dc2653","poly":"cardio","fiche":"232","front":"FA : paramètres de tolérance à évaluer ?","back":"**FC**, **PA**, **diurèse**, **FR**, **état de conscience**.","prio":"P2","sec":"s3"},{"id":"fc-232-271132","poly":"cardio","fiche":"232","front":"FA : complications à rechercher d'emblée ?","back":"**OAP** ou signes d'IC ; **embolie artérielle systémique** (examen des artères + examen neurologique).","prio":"P1","sec":"s3"},{"id":"fc-232-8df615","poly":"cardio","fiche":"232","front":"ECG de FA : aspect des ondes P ?","back":"**Absentes**, remplacées par une activité atriale anarchique.","prio":"P1","sec":"s4"},{"id":"fc-232-b4964a","poly":"cardio","fiche":"232","front":"ECG de FA : aspect de la ligne de base ?","back":"**Trémulations à petites mailles** (habituel) ou FA à **grosses mailles**.","prio":"P2","sec":"s4"},{"id":"fc-232-807c64","poly":"cardio","fiche":"232","front":"ECG de FA : principale caractéristique des QRS ?","back":"Le plus souvent **irréguliers**, et **fins** (largeur le plus souvent < 120 ms).","prio":"P1","sec":"s4"},{"id":"fc-232-5a37c6","poly":"cardio","fiche":"232","front":"FA avec QRS larges : quoi évoquer ?","back":"Un **bloc de branche** associé.","prio":"P1","sec":"s4"},{"id":"fc-232-b5242f","poly":"cardio","fiche":"232","front":"FA avec QRS lents et réguliers : quoi évoquer ?","back":"Une FA associée à un **BAV complet**.","prio":"P1","sec":"s4"},{"id":"fc-232-9cca0d","poly":"cardio","fiche":"232","front":"ECG de FA : que signifient des pauses ?","back":"Pauses ou dysfonction sinusale **de régularisation** (syndrome tachycardie-bradycardie).","prio":"P2","sec":"s4"},{"id":"fc-232-0859ef","poly":"cardio","fiche":"232","front":"FA découverte : bilan biologique de 1re intention ?","back":"**Ionogramme sanguin**, **créatinine**, **TSHus**, **NFS**.","prio":"P1","sec":"s4"},{"id":"fc-232-05ed37","poly":"cardio","fiche":"232","front":"FA : but de l'échocardiographie ?","back":"Rechercher une **cardiopathie sous-jacente**.","prio":"P1","sec":"s4"},{"id":"fc-232-4fd4cc","poly":"cardio","fiche":"232","front":"FA suspectée mais non documentée (ex. bilan d'AVC) : quels moyens ?","back":"**Holter prolongé de 72 h** ; interrogation du **pacemaker ou du DAI** s'il existe.","prio":"P1","sec":"s4"},{"id":"fc-232-8164ed","poly":"cardio","fiche":"232","front":"FA sur cœur normal non captée au holter : quel recours ?","back":"ECG monopistes par **outils connectés** (montre, applications).","prio":"P3","sec":"s4"},{"id":"fc-232-9508f8","poly":"cardio","fiche":"232","front":"Dépistage de routine de la FA à chaque contact médical : pour qui ?","back":"Patient **≥ 65 ans** ou à risque.","prio":"P2","sec":"s4"},{"id":"fc-232-9c55e3","poly":"cardio","fiche":"232","front":"Dépistage organisé de la FA : pour qui ?","back":"Patient **≥ 75 ans**, ou **≥ 65 ans à risque thromboembolique**.","prio":"P2","sec":"s4"},{"id":"fc-232-aa4099","poly":"cardio","fiche":"232","front":"Dépistage systématique de la FA par monitoring prolongé : dans quel bilan ?","back":"Bilan d'une **embolie cryptogénique**.","prio":"P1","sec":"s4"},{"id":"fc-232-574d21","poly":"cardio","fiche":"232","front":"FA : 2 risques majeurs ?","back":"**Insuffisance cardiaque** (cadence rapide et irrégulière) + **embolie artérielle systémique** (caillot de l'OG).","prio":"P1","sec":"s5"},{"id":"fc-232-6377e4","poly":"cardio","fiche":"232","front":"FA très rapide avec état de choc, résistante aux freinateurs : conduite ?","back":"**Cardioversion immédiate par choc électrique externe** (situation très rare), avec prévention thromboembolique obligatoire.","prio":"P1","sec":"s5"},{"id":"fc-232-441c13","poly":"cardio","fiche":"232","front":"FA à grosses mailles : quel piège diagnostique ?","back":"La confondre avec un **flutter atrial**.","prio":"P1","sec":"s5"},{"id":"fc-232-b06a69","poly":"cardio","fiche":"232","front":"FA : asthénie chronique attribuée à la FA ou aux médicaments, quoi évoquer ?","back":"Un **SAOS** méconnu.","prio":"P2","sec":"s5"},{"id":"fc-232-9d3a14","poly":"cardio","fiche":"232","front":"FA : la troponine figure-t-elle dans le bilan biologique de 1re intention du Collège ?","back":"**Non** : ionogramme, créatinine, TSHus, NFS.","prio":"P3","sec":"s5"},{"id":"fc-232-0fdc78","poly":"cardio","fiche":"232","front":"FA : facteurs déclenchants ?","back":"**Hypokaliémie**, **fièvre**, **privation de sommeil**, **réaction vagale**, **alcool** (ivresse) ou substances illicites, **électrocution**.","prio":"P1","sec":"s6"},{"id":"fc-232-a82ec8","poly":"cardio","fiche":"232","front":"FA : facteur prédisposant le plus puissant ?","back":"**L'âge**.","prio":"P2","sec":"s6"},{"id":"fc-232-66d602","poly":"cardio","fiche":"232","front":"FA : facteurs de prédisposition modifiables ?","back":"Obésité, hyperthyroïdie, diabète, HTA, tabac et alcool en excès, **sports de grande endurance**, **SAOS**.","prio":"P2","sec":"s6"},{"id":"fc-232-674b98","poly":"cardio","fiche":"232","front":"FA : première étiologie ?","back":"**HTA** (souvent avec **HVG**, surtout chez le sujet âgé).","prio":"P1","sec":"s6"},{"id":"fc-232-eb6d47","poly":"cardio","fiche":"232","front":"FA : étiologie à toujours rechercher, 2e en fréquence ?","back":"**Valvulopathies**, surtout **mitrales** (plus qu'aortiques).","prio":"P1","sec":"s6"},{"id":"fc-232-519ee0","poly":"cardio","fiche":"232","front":"FA : étiologies cardiaques en dehors de l'HTA et des valvulopathies ?","back":"SCA et séquelles d'infarctus ; **cardiomyopathies** (dilatées, hypertrophiques, restrictives) ; **péricardites** ; chirurgie cardiaque récente ; congénitales (**CIA**).","prio":"P2","sec":"s6"},{"id":"fc-232-a8eda9","poly":"cardio","fiche":"232","front":"FA : étiologies pulmonaires ?","back":"Pneumopathies aiguës ou chroniques, **embolie pulmonaire**, **SAOS**, cœur pulmonaire chronique.","prio":"P2","sec":"s6"},{"id":"fc-232-801cc2","poly":"cardio","fiche":"232","front":"FA : étiologies endocriniennes ?","back":"**Hyperthyroïdie** (cardiothyréose), phéochromocytome.","prio":"P2","sec":"s6"},{"id":"fc-232-10a82c","poly":"cardio","fiche":"232","front":"FA : étiologie rénale ?","back":"**Insuffisance rénale sévère**.","prio":"P3","sec":"s6"},{"id":"fc-232-fa20dd","poly":"cardio","fiche":"232","front":"FA idiopathique : comment est-elle retenue ?","back":"**Par élimination** seulement.","prio":"P2","sec":"s6"},{"id":"fc-232-cc271d","poly":"cardio","fiche":"232","front":"FA idiopathique : poids du terrain génétique ?","back":"Un apparenté du 1er degré en FA augmente de **40 %** la probabilité d'être atteint.","prio":"P3","sec":"s6"},{"id":"fc-232-06212e","poly":"cardio","fiche":"232","front":"FA : quelle comorbidité respiratoire est souvent sous-estimée ?","back":"L'**apnée du sommeil** (SAOS).","prio":"P2","sec":"s6"},{"id":"fc-232-dcbc01","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : examens non biologiques systématiques ?","back":"**ECG**, **radiographie de thorax**, **échocardiographie transthoracique**.","prio":"P1","sec":"s6"},{"id":"fc-232-1a2a47","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : examens biologiques ?","back":"**TSHus**, ionogramme, fonction rénale, **bilan hépatique**.","prio":"P2","sec":"s6"},{"id":"fc-232-199d2b","poly":"cardio","fiche":"232","front":"Bilan étiologique de FA : quand demander d'autres examens ?","back":"**Seulement sur signe d'appel**.","prio":"P3","sec":"s6"},{"id":"fc-232-6091ac","poly":"cardio","fiche":"232","front":"FA : HTA difficile à affirmer, quels examens ?","back":"**Automesure** ou **MAPA**, sans hésiter.","prio":"P2","sec":"s6"},{"id":"fc-232-60d5e2","poly":"cardio","fiche":"232","front":"FA : comment rechercher un SAOS ?","back":"**Polygraphie** à encourager, surtout chez l'obèse.","prio":"P2","sec":"s6"},{"id":"fc-232-8e6b40","poly":"cardio","fiche":"232","front":"Cardioversion de FA : pourquoi anticoaguler quel que soit le score ?","back":"Tout retour en sinusal (médicament ou choc) expose à une embolie pendant **au moins 4 semaines** → anticoagulation **obligatoire**.","prio":"P1","sec":"s7"},{"id":"fc-232-b6c8c2","poly":"cardio","fiche":"232","front":"FA + prothèse mécanique ou RM modéré à sévère : calcule-t-on le CHA₂DS₂-VA ?","back":"**Non** : risque thromboembolique d'emblée **très élevé** → anticoagulation d'office par **AVK**.","prio":"P1","sec":"s7"},{"id":"fc-232-b1a61d","poly":"cardio","fiche":"232","front":"FA + cardiomyopathie hypertrophique ou amylose cardiaque : anticoagulation ?","back":"**Systématique**, sans calculer le score : **AOD (ou AVK)**.","prio":"P1","sec":"s7"},{"id":"fc-232-91b0bb","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « C » et points ?","back":"**Congestion** : insuffisance cardiaque clinique, FEVG altérée ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-172267","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « H » et points ?","back":"**HTA**, traitée ou non, équilibrée ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-ea214a","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « A₂ » et points ?","back":"Âge **≥ 75 ans** = **2 points**.","prio":"P1","sec":"s7"},{"id":"fc-232-b0638c","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « D » et points ?","back":"**Diabète**, traité ou non, équilibré ou non = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-224e51","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « S₂ » et points ?","back":"**Stroke** : AVC ou embolie artérielle = **2 points**.","prio":"P1","sec":"s7"},{"id":"fc-232-bbc246","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « V » et points ?","back":"Atteinte **vasculaire** : coronaropathie, AOMI, athérome des troncs cérébraux = **1 point**.","prio":"P2","sec":"s7"},{"id":"fc-232-0e26a2","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : critère « A » (seul) et points ?","back":"Âge **65-74 ans** = **1 point**.","prio":"P1","sec":"s7"},{"id":"fc-232-64301b","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : score maximal ?","back":"**8** points.","prio":"P3","sec":"s7"},{"id":"fc-232-00579b","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : risque embolique annuel selon le score ?","back":"De **1 à 18 %** pour un score de 0 à 8, de façon exponentielle (en gros **+ 2 %** par point).","prio":"P2","sec":"s7"},{"id":"fc-232-a6ce7e","poly":"cardio","fiche":"232","front":"FA : 2 facteurs qui augmentent le risque embolique sans compter dans le CHA₂DS₂-VA ?","back":"**SAOS** et **insuffisance rénale sévère**.","prio":"P2","sec":"s7"},{"id":"fc-232-a3d60d","poly":"cardio","fiche":"232","front":"CHA₂DS₂-VA : le sexe féminin compte-t-il ?","back":"**Non** (le type de FA non plus).","prio":"P1","sec":"s7"},{"id":"fc-232-cc49e0","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA = 0 : conduite antithrombotique ?","back":"**Pas d'antithrombotique**.","prio":"P1","sec":"s7"},{"id":"fc-232-e4a29a","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA = 1 : conduite antithrombotique ?","back":"Anticoagulant **conseillé**, décidé **au cas par cas avec le patient** (bénéfice/risque) ; AOD (ou AVK).","prio":"P1","sec":"s7"},{"id":"fc-232-37ef84","poly":"cardio","fiche":"232","front":"FA, CHA₂DS₂-VA > 1 : conduite antithrombotique ?","back":"Anticoagulant oral **indiscutable** ; AOD (ou AVK).","prio":"P1","sec":"s7"},{"id":"fc-232-ce998a","poly":"cardio","fiche":"232","front":"FA sans valve mécanique ni RM : AOD ou AVK en priorité ?","back":"**AOD à favoriser** par rapport aux AVK.","prio":"P1","sec":"s7"},{"id":"fc-232-fd50db","poly":"cardio","fiche":"232","front":"FA : quel risque évaluer systématiquement avant d'anticoaguler ?","back":"Le **risque hémorragique** (balance bénéfice/risque).","prio":"P1","sec":"s7"},{"id":"fc-232-c93c7d","poly":"cardio","fiche":"232","front":"Insuffisant cardiaque en FA : score recommandé (item 234) pour le risque hémorragique ?","back":"**HAS-BLED**.","prio":"P2","sec":"s7"},{"id":"fc-232-79c252","poly":"cardio","fiche":"232","front":"FA isolée sans cardiopathie ni comorbidité : niveau de risque embolique ?","back":"**Très faible**.","prio":"P2","sec":"s7"},{"id":"fc-232-e0ae2a","poly":"cardio","fiche":"232","front":"FA après choc électrique en urgence : durée minimale d'anticoagulation ?","back":"Anticoagulant oral **au moins 4 semaines**, puis réévaluation du risque chronique (**CHA₂DS₂-VA**).","prio":"P1","sec":"s8"},{"id":"fc-232-9ecec1","poly":"cardio","fiche":"232","front":"Cardioversion de FA en urgence : quel anticoagulant ?","back":"**Héparine ou anticoagulant oral** ; AOD utilisable d'emblée s'il n'y en a pas déjà un efficace (sauf CI).","prio":"P2","sec":"s8"},{"id":"fc-232-5f5e12","poly":"cardio","fiche":"232","front":"Premier épisode de FA bien toléré : quel anticoagulant ?","back":"**AOD d'emblée** (sauf CI) ; les **HBPM ne sont pas approuvées** dans cette indication.","prio":"P2","sec":"s8"},{"id":"fc-232-6d1422","poly":"cardio","fiche":"232","front":"Premier épisode de FA : comment ralentir au départ ?","back":"**Freinateur nodal** : bêtabloquant, vérapamil ou diltiazem, digoxine.","prio":"P2","sec":"s8"},{"id":"fc-232-1d158f","poly":"cardio","fiche":"232","front":"Premier épisode de FA sans retour spontané en sinusal : conduite ?","back":"**Cardioversion programmée**, mêmes règles que la FA persistante (3 semaines d'anticoagulation ou ETO).","prio":"P2","sec":"s8"},{"id":"fc-232-527670","poly":"cardio","fiche":"232","front":"Premier épisode de FA réduit : poursuit-on un antiarythmique ?","back":"**Non**, habituellement ; anticoagulation poursuivie selon le terrain (CHA₂DS₂-VA).","prio":"P2","sec":"s8"},{"id":"fc-232-f7497e","poly":"cardio","fiche":"232","front":"Vérapamil et diltiazem : contre-indication majeure dans la FA ?","back":"**Insuffisance cardiaque**.","prio":"P1","sec":"s8"},{"id":"fc-232-3c2873","poly":"cardio","fiche":"232","front":"Cardioversion programmée : durée d'anticoagulation préalable ?","back":"**Au moins 3 semaines**, efficace et **documentée** (héparine ou anticoagulant oral) ; les points clés disent **3 à 4 semaines**.","prio":"P1","sec":"s9"},{"id":"fc-232-e57a69","poly":"cardio","fiche":"232","front":"Cardioversion programmée : 2 situations qui permettent de raccourcir le délai d'anticoagulation ?","back":"**ETO sans thrombus** dans l'oreillette gauche ; FA débutée de façon **certaine il y a < 24 h** (rare).","prio":"P1","sec":"s9"},{"id":"fc-232-51543c","poly":"cardio","fiche":"232","front":"Cardioversion programmée : quand faire une ETO en plus de l'anticoagulation ?","back":"Risque très élevé (**valve mécanique mitrale**, **RM**) ou anticoagulation préalable incertaine/mal documentée.","prio":"P2","sec":"s9"},{"id":"fc-232-1c4c0c","poly":"cardio","fiche":"232","front":"Cardioversion programmée : modalités ?","back":"**Choc électrique externe sous anesthésie générale** et/ou **antiarythmique** (combinables).","prio":"P2","sec":"s9"},{"id":"fc-232-1ff785","poly":"cardio","fiche":"232","front":"Cardioversion médicamenteuse : antiarythmiques cités ?","back":"**Amiodarone**, **flécaïnide**.","prio":"P2","sec":"s9"},{"id":"fc-232-70507b","poly":"cardio","fiche":"232","front":"Après une cardioversion de FA : durée minimale d'anticoagulation ?","back":"**Au moins 4 semaines**, puis décision selon le risque chronique (CHA₂DS₂-VA).","prio":"P1","sec":"s9"},{"id":"fc-232-0d1e25","poly":"cardio","fiche":"232","front":"Risque embolique après cardioversion médicamenteuse : différent du choc ?","back":"**Non** : même risque, que la cardioversion soit médicamenteuse ou électrique.","prio":"P1","sec":"s9"},{"id":"fc-232-188bbd","poly":"cardio","fiche":"232","front":"FA persistante en attente de cardioversion : quel traitement associer à l'anticoagulation ?","back":"**Ralentir** la cadence ventriculaire par un **bradycardisant** (freinateur nodal).","prio":"P2","sec":"s9"},{"id":"fc-232-2cd13f","poly":"cardio","fiche":"232","front":"FA persistante après cardioversion : quelle stratégie ensuite ?","back":"**Contrôle du rythme**.","prio":"P3","sec":"s9"},{"id":"fc-232-7616b4","poly":"cardio","fiche":"232","front":"Flécaïnide : contre-indication dans la FA ?","back":"**Insuffisance cardiaque** (et coronarien : amiodarone seule).","prio":"P1","sec":"s9"},{"id":"fc-232-2f16b5","poly":"cardio","fiche":"232","front":"Cardioversion guidée par ETO chez un non anticoagulé : quel anticoagulant pendant le geste ?","back":"**HNF** ; anticoagulant oral débuté **le jour même**, pour **au moins 4 semaines**.","prio":"P2","sec":"s9"},{"id":"fc-232-789cc9","poly":"cardio","fiche":"232","front":"Cardioversion guidée par ETO : rôle des héparines ?","back":"Anticoagulant **d'action rapide**, le plus souvent en attendant que l'anticoagulant oral soit efficace.","prio":"P3","sec":"s9"},{"id":"fc-232-f55101","poly":"cardio","fiche":"232","front":"ETO sans thrombus avant cardioversion : de quoi dispense-t-elle ?","back":"Des 3 semaines d'anticoagulation **avant**, **jamais** des 4 semaines **après**.","prio":"P1","sec":"s9"},{"id":"fc-232-41e578","poly":"cardio","fiche":"232","front":"AOD : 3 situations où ils ne remplacent pas les AVK ?","back":"**Valve mécanique**, **insuffisance rénale sévère**, **SAPL triple positif**.","prio":"P1","sec":"s10"},{"id":"fc-232-b95a0c","poly":"cardio","fiche":"232","front":"AOD : délai d'action et relais ?","back":"Efficace environ **2 h** après la 1re prise → **pas de relais** par héparine.","prio":"P2","sec":"s10"},{"id":"fc-232-b8d568","poly":"cardio","fiche":"232","front":"AOD chez le sujet de plus de 80 ans : particularité ?","back":"Souvent **dose réduite**.","prio":"P3","sec":"s10"},{"id":"fc-232-611596","poly":"cardio","fiche":"232","front":"Dabigatran : mécanisme ?","back":"**Anti-IIa** (inhibiteur de la thrombine).","prio":"P2","sec":"s10"},{"id":"fc-232-2d6741","poly":"cardio","fiche":"232","front":"Dabigatran : antidote ?","back":"**Idarucizumab**.","prio":"P1","sec":"s10"},{"id":"fc-232-3e60d5","poly":"cardio","fiche":"232","front":"Rivaroxaban et apixaban : mécanisme ?","back":"**Inhibiteurs du facteur Xa**.","prio":"P2","sec":"s10"},{"id":"fc-232-e26d4f","poly":"cardio","fiche":"232","front":"AOD : nombre de prises par jour ?","back":"Dabigatran **2** ; rivaroxaban **1** ; apixaban **2** (la plupart des indications).","prio":"P3","sec":"s10"},{"id":"fc-232-c52084","poly":"cardio","fiche":"232","front":"Dabigatran : en dessous de quelle clairance (Cockcroft) est-il déconseillé ?","back":"**< 30 à 25 mL/min**.","prio":"P3","sec":"s10"},{"id":"fc-232-065d2c","poly":"cardio","fiche":"232","front":"AVK : molécule de référence et place de la fluindione ?","back":"**Warfarine** ; fluindione en **2e intention** seulement (instauration déconseillée par l'ANSM).","prio":"P2","sec":"s10"},{"id":"fc-232-1dfa0b","poly":"cardio","fiche":"232","front":"Fluindione : effet indésirable spécifique cité ?","back":"**Atteinte rénale immunoallergique**.","prio":"P3","sec":"s10"},{"id":"fc-232-a78044","poly":"cardio","fiche":"232","front":"AVK dans la FA (hors valve mécanique) : INR cible ?","back":"**2,5 (2 à 3)**.","prio":"P1","sec":"s10"},{"id":"fc-232-f9884d","poly":"cardio","fiche":"232","front":"AVK et grossesse ?","back":"**Tératogènes** : contre-indiqués au 1er trimestre.","prio":"P2","sec":"s10"},{"id":"fc-232-419e24","poly":"cardio","fiche":"232","front":"AOD : 3 avantages sur les AVK ?","back":"**Action rapide** ; **pas de surveillance biologique** ; beaucoup moins d'**hémorragies intracrâniennes**.","prio":"P2","sec":"s10"},{"id":"fc-232-1f42de","poly":"cardio","fiche":"232","front":"AOD : 3 inconvénients ?","back":"**Accumulation si insuffisance rénale** ; observance difficile à vérifier ; un peu plus d'hémorragies **digestives et génitales**.","prio":"P2","sec":"s10"},{"id":"fc-232-0c1a1c","poly":"cardio","fiche":"232","front":"Sous AOD : TCA, TP et INR mesurent-ils l'efficacité ?","back":"**Non** : perturbés mais non interprétables ; **pas de test biologique** de routine.","prio":"P1","sec":"s10"},{"id":"fc-232-7b0135","poly":"cardio","fiche":"232","front":"FA + valve mécanique ou RM modéré à sévère : quel anticoagulant ?","back":"**AVK seuls** ; **AOD contre-indiqués** (CI absolue).","prio":"P1","sec":"s11"},{"id":"fc-232-fdeb31","poly":"cardio","fiche":"232","front":"FA sur prothèse mécanique : quelle complication valvulaire vérifier ?","back":"L'absence de **thrombose de valve**.","prio":"P3","sec":"s11"},{"id":"fc-232-316f24","poly":"cardio","fiche":"232","front":"FA valvulaire (prothèse ou RM) : stratégie souvent retenue et pourquoi ?","back":"**Contrôle de la fréquence** : l'oreillette dilatée tient mal le rythme sinusal.","prio":"P2","sec":"s11"},{"id":"fc-232-c97119","poly":"cardio","fiche":"232","front":"AVK : délai d'efficacité et conséquence à l'instauration ?","back":"Efficaces après **4 à 6 jours** → débuter dès J1 **sous héparine**.","prio":"P2","sec":"s11"},{"id":"fc-232-3b9af7","poly":"cardio","fiche":"232","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"Après **au moins 4 à 5 jours** de chevauchement **et 2 INR** efficaces à 24 h d'intervalle.","prio":"P1","sec":"s11"},{"id":"fc-232-6e9633","poly":"cardio","fiche":"232","front":"AVK sur valve mécanique mitrale ou à disque : INR cible ?","back":"**3 à 4,5** (texte) ; les points clés donnent **3,7** pour la valve mécanique mitrale.","prio":"P2","sec":"s11"},{"id":"fc-232-e13441","poly":"cardio","fiche":"232","front":"Fermeture percutanée de l'auricule gauche : rationnel et technique ?","back":"Les thrombi naissent surtout dans l'**auricule gauche** ; dispositif posé par voie veineuse et **cathétérisme transseptal**.","prio":"P3","sec":"s11"},{"id":"fc-232-cca5d3","poly":"cardio","fiche":"232","front":"Fermeture percutanée de l'auricule gauche : indication ?","back":"FA sans prothèse mécanique ni RM modéré à sévère, **CHA₂DS₂-VA ≥ 2**, CI **formelle et permanente** aux anticoagulants, validée en **comité pluridisciplinaire**.","prio":"P2","sec":"s11"},{"id":"fc-232-dfc6cf","poly":"cardio","fiche":"232","front":"Fermeture chirurgicale de l'auricule chez un patient en FA opéré du cœur : dispense-t-elle de l'anticoagulation ?","back":"**Non**, l'anticoagulation est **maintenue**.","prio":"P1","sec":"s11"},{"id":"fc-232-1af820","poly":"cardio","fiche":"232","front":"Contrôle de la fréquence dans la FA : principe ?","back":"**Ralentir** les ventricules en gardant la FA (freinateurs nodaux : bêtabloquants, vérapamil/diltiazem, digitaliques).","prio":"P2","sec":"s12"},{"id":"fc-232-d196e6","poly":"cardio","fiche":"232","front":"Contrôle de la fréquence : objectif et moyen de vérification ?","back":"**FC < 110 bpm** lors d'une marche normale de 5 min, vérifiée par **holter**.","prio":"P2","sec":"s12"},{"id":"fc-232-84da41","poly":"cardio","fiche":"232","front":"Contrôle du rythme dans la FA : moyens ?","back":"Antiarythmiques (**amiodarone**, **flécaïnide**, **propafénone**) ; **ablation par cathéter** (isolation des veines pulmonaires).","prio":"P2","sec":"s12"},{"id":"fc-232-db5691","poly":"cardio","fiche":"232","front":"FA chez le coronarien et/ou l'insuffisant cardiaque : quel antiarythmique ?","back":"**Amiodarone seule**.","prio":"P1","sec":"s12"},{"id":"fc-232-ccf966","poly":"cardio","fiche":"232","front":"FA permanente : cardioversion ou contrôle du rythme ?","back":"**Non, par définition** : contrôle de la fréquence si nécessaire.","prio":"P2","sec":"s12"},{"id":"fc-232-a764da","poly":"cardio","fiche":"232","front":"FA paroxystique (tableau 13.2) : contrôle de la fréquence et du rythme ?","back":"**Oui, le plus souvent** pour les deux (souvent antiarythmique + bêtabloquant).","prio":"P3","sec":"s12"},{"id":"fc-232-ba513b","poly":"cardio","fiche":"232","front":"FA paroxystique : place de l'ablation par cathéter ?","back":"Recommandée **en 1re ligne**, à égalité avec un antiarythmique, selon le patient ; meilleur maintien du sinusal à long terme.","prio":"P2","sec":"s12"},{"id":"fc-232-4209ab","poly":"cardio","fiche":"232","front":"FA : ablation recommandée si l'on suspecte quelle atteinte du VG induite par la FA ?","back":"**Tachycardiomyopathie** (dysfonction systolique VG induite par la FA) ; ablation à considérer chez certains insuffisants cardiaques à FE altérée.","prio":"P2","sec":"s12"},{"id":"fc-232-a0f5fb","poly":"cardio","fiche":"232","front":"FA sur cœur normal : profil typique ?","back":"Sujet d'**âge mûr** (quinquagénaire), FA souvent **paroxystique**, sans cardiopathie ni comorbidité, échocardiographie **normale**.","prio":"P2","sec":"s12"},{"id":"fc-232-325d2e","poly":"cardio","fiche":"232","front":"FA sur cœur normal : quels diagnostics éliminer ?","back":"**HTA** et **SAOS**.","prio":"P2","sec":"s12"},{"id":"fc-232-c4686b","poly":"cardio","fiche":"232","front":"FA paroxystique sur cœur normal : évolution habituelle ?","back":"En quelques mois ou années vers une forme **persistante** (parfois persistante d'emblée).","prio":"P3","sec":"s12"},{"id":"fc-232-f40ce2","poly":"cardio","fiche":"232","front":"FA sur cœur normal : antiarythmique de 1re intention pour maintenir le sinusal ?","back":"**Flécaïnide** ; **ablation** envisageable après information éclairée.","prio":"P2","sec":"s12"},{"id":"fc-232-acc0f9","poly":"cardio","fiche":"232","front":"FA sur cœur normal avec CHA₂DS₂-VA = 0 : anticoagulant au long cours ?","back":"**Non** (risque embolique très faible).","prio":"P2","sec":"s12"},{"id":"fc-232-84d1c1","poly":"cardio","fiche":"232","front":"Amiodarone : effets indésirables à expliquer au patient ?","back":"**Thyroïde**, **photosensibilisation**, **dépôts cornéens**.","prio":"P2","sec":"s12"},{"id":"fc-232-c271d8","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque en urgence : comment ralentir et à quelle condition ?","back":"**Digoxine IV**, seulement si la **kaliémie est normale**.","prio":"P1","sec":"s13"},{"id":"fc-232-dcf3d4","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : délai de la cardioversion ?","back":"**Différée** le temps d'une anticoagulation efficace ; contrôle de la fréquence en attendant.","prio":"P2","sec":"s13"},{"id":"fc-232-ad8667","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : échec du maintien du sinusal, conduite ?","back":"On **respecte la FA** et on contrôle la fréquence par **bêtabloquants**.","prio":"P2","sec":"s13"},{"id":"fc-232-83bf5e","poly":"cardio","fiche":"232","front":"FA + poussée d'insuffisance cardiaque : bêtabloquant ?","back":"**Pas d'introduction** pendant la poussée ; s'il est déjà pris, arrêt ou baisse en général.","prio":"P2","sec":"s13"},{"id":"fc-232-3b36b4","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : durée de l'anticoagulation ?","back":"Avant la cardioversion puis **au long cours dans tous les cas**.","prio":"P2","sec":"s13"},{"id":"fc-232-a1cbc3","poly":"cardio","fiche":"232","front":"FA + insuffisance cardiaque : la FA est-elle cause ou conséquence ?","back":"On ne le sait **pas toujours** ; FA souvent **persistante**.","prio":"P3","sec":"s13"},{"id":"fc-232-8ad8bd","poly":"cardio","fiche":"232","front":"FA révélée par un infarctus cérébral : terrain typique ?","back":"Souvent **femme âgée**, FA méconnue, **HTA mal équilibrée ou diabète** ; embolie souvent **sylvienne superficielle gauche**.","prio":"P2","sec":"s13"},{"id":"fc-232-0edf4b","poly":"cardio","fiche":"232","front":"FA révélée par un AVC : prise en charge initiale ?","back":"**Imagerie cérébrale** obligatoire ; **unité neurovasculaire** ; discussion **thrombolyse** ou **thromboaspiration**.","prio":"P2","sec":"s13"},{"id":"fc-232-85f3eb","poly":"cardio","fiche":"232","front":"Infarctus cérébral sur FA à la phase aiguë : AVK ou héparine ?","back":"**Ni AVK ni héparine** (risque de transformation hémorragique).","prio":"P1","sec":"s13"},{"id":"fc-232-c28641","poly":"cardio","fiche":"232","front":"Infarctus cérébral sur FA : anticoagulation à la sortie ?","back":"**Impérative** au long cours (S₂ = 2 points au CHA₂DS₂-VA).","prio":"P2","sec":"s13"},{"id":"fc-232-313290","poly":"cardio","fiche":"232","front":"FA à la phase aiguë d'un infarctus avec décompensation hémodynamique : conduite ?","back":"**Cardioversion électrique immédiate**.","prio":"P1","sec":"s14"},{"id":"fc-232-aa7a41","poly":"cardio","fiche":"232","front":"FA après SCA : association antithrombotique par défaut ?","back":"**Anticoagulant oral à pleine dose + clopidogrel pendant 12 mois** (éviter les saignements de la trithérapie).","prio":"P1","sec":"s14"},{"id":"fc-232-d52a1a","poly":"cardio","fiche":"232","front":"FA après SCA : quand une trithérapie est-elle possible ?","back":"**Faible risque hémorragique** + **haut risque ischémique**, sur une durée limitée (habituellement **1 mois**).","prio":"P1","sec":"s14"},{"id":"fc-232-11e462","poly":"cardio","fiche":"232","front":"FA après SCA : traitement antithrombotique après 1 an ?","back":"**Anticoagulant seul**.","prio":"P1","sec":"s14"},{"id":"fc-232-b98d75","poly":"cardio","fiche":"232","front":"FA après SCA : posologie du clopidogrel ?","back":"**75 mg/j**.","prio":"P2","sec":"s14"},{"id":"fc-232-e6fb7b","poly":"cardio","fiche":"232","front":"FA après SCA en trithérapie : posologie de l'aspirine ?","back":"**75-100 mg/j** per os.","prio":"P2","sec":"s14"},{"id":"fc-232-547046","poly":"cardio","fiche":"232","front":"FA après SCA : quand ajouter un IPP ?","back":"Risque d'hémorragie digestive élevé : âge **≥ 65 ans**, antécédent d'**ulcère**, **corticothérapie** au long cours…","prio":"P2","sec":"s14"},{"id":"fc-232-c19d01","poly":"cardio","fiche":"232","front":"Sous anticoagulant : quelle classe médicamenteuse éviter ?","back":"Les **anti-inflammatoires** (majorent le risque hémorragique).","prio":"P2","sec":"s14"},{"id":"fc-232-8fadc6","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : que documenter ?","back":"L'**alternance** FA paroxystique rapide / bradycardie sinusale (sujet âgé, asymptomatique ou lipothymies/syncopes).","prio":"P3","sec":"s15"},{"id":"fc-232-7a40da","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : pourquoi les bradycardisants sont-ils périlleux ?","back":"Ils **aggravent la dysfonction sinusale**.","prio":"P2","sec":"s15"},{"id":"fc-232-8cf8ce","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette : indications du stimulateur définitif ?","back":"Pauses sinusales symptomatiques (en règle **> 3 s**) ou bradycardie sinusale symptomatique **non iatrogène** (en pratique **< 50 bpm**).","prio":"P2","sec":"s15"},{"id":"fc-232-c91b97","poly":"cardio","fiche":"232","front":"Maladie de l'oreillette avec pause de réduction symptomatique : quel geste considérer ?","back":"**Ablation des veines pulmonaires**.","prio":"P3","sec":"s15"},{"id":"fc-232-e6daf5","poly":"cardio","fiche":"232","front":"AVK : mode d'action ?","back":"Inhibent les facteurs **vitamine K-dépendants** : **II, VII, IX, X**.","prio":"P2","sec":"s16"},{"id":"fc-232-6df8cf","poly":"cardio","fiche":"232","front":"AVK équilibré : fréquence de l'INR ?","back":"**Au moins 1 fois/mois**, résultats notés dans un **carnet**.","prio":"P1","sec":"s16"},{"id":"fc-232-3a5738","poly":"cardio","fiche":"232","front":"AVK à l'instauration : rythme des INR ?","back":"2/semaine de J0 à J14, 1/semaine jusqu'à J30, 1/2 semaines jusqu'à J60, puis **au moins 1/mois**.","prio":"P3","sec":"s16"},{"id":"fc-232-57038f","poly":"cardio","fiche":"232","front":"AVK : quand un patient est-il dit équilibré ?","back":"**Au moins 70 %** des INR dans la cible.","prio":"P2","sec":"s16"},{"id":"fc-232-53ecfa","poly":"cardio","fiche":"232","front":"Automesure de l'INR : chez qui est-elle remboursée ?","back":"Porteurs de **valve mécanique**.","prio":"P3","sec":"s16"},{"id":"fc-232-8b2402","poly":"cardio","fiche":"232","front":"AOD : surveillance ?","back":"Efficacité **clinique** + **fonction rénale au moins 1 fois/an**.","prio":"P1","sec":"s16"},{"id":"fc-232-837a63","poly":"cardio","fiche":"232","front":"AOD : part d'élimination rénale ?","back":"Dabigatran **80 %**, rivaroxaban **33 %**, apixaban **25 %**.","prio":"P3","sec":"s16"},{"id":"fc-232-9956ba","poly":"cardio","fiche":"232","front":"AOD : interactions médicamenteuses citées ?","back":"Macrolides, antiprotéases, antifongiques azolés, certains anticancéreux, **amiodarone**, **diltiazem**, **vérapamil**.","prio":"P3","sec":"s16"},{"id":"fc-232-df8666","poly":"cardio","fiche":"232","front":"HNF : cibles de surveillance ?","back":"**TCA** 2 à 3 fois le témoin et/ou **anti-Xa** 0,5 à 0,8.","prio":"P2","sec":"s16"},{"id":"fc-232-e5fbdf","poly":"cardio","fiche":"232","front":"HNF : quand faire le 1er TCA ?","back":"Vers la **5e heure**, puis au moins 1 fois/j.","prio":"P3","sec":"s16"},{"id":"fc-232-4b6ea7","poly":"cardio","fiche":"232","front":"HNF : quel TCA signe un surdosage ?","back":"TCA **> 3 fois le témoin**.","prio":"P2","sec":"s16"},{"id":"fc-232-716cd0","poly":"cardio","fiche":"232","front":"HNF : surveillance plaquettaire ?","back":"Numération **avant ou dans les 24 h** suivant le début (TIH, typiquement J5-J8).","prio":"P2","sec":"s16"},{"id":"fc-232-192748","poly":"cardio","fiche":"232","front":"Digoxine : précautions de surveillance ?","back":"Risque de **surdosage** (surtout si insuffisance rénale) → **dosage plasmatique** régulier.","prio":"P2","sec":"s16"},{"id":"fc-232-d0c401","poly":"cardio","fiche":"232","front":"AVK : antidotes et rapidité d'action ?","back":"**PPSB** (action très rapide) + **vitamine K** (en quelques heures).","prio":"P1","sec":"s16"},{"id":"fc-232-e6440a","poly":"cardio","fiche":"232","front":"Anti-Xa (rivaroxaban, apixaban) : existe-t-il un antidote ?","back":"En **cours de commercialisation**.","prio":"P3","sec":"s16"},{"id":"fc-232-c229e8","poly":"cardio","fiche":"232","front":"Geste programmé à risque hémorragique modéré sous AVK : arrêt nécessaire ?","back":"La plupart se font **sans arrêt**, INR en limite basse de la cible.","prio":"P3","sec":"s16"},{"id":"fc-232-04fb51","poly":"cardio","fiche":"232","front":"AVK à arrêter avant un geste, FA sans antécédent embolique : relais ?","back":"Arrêt **sans relais** par héparine.","prio":"P2","sec":"s16"},{"id":"fc-232-e05075","poly":"cardio","fiche":"232","front":"AVK à arrêter, FA avec antécédent embolique ou valve mécanique : conduite ?","back":"**Relais préopératoire par héparine curative** ; reprise des AVK en 24-48 h.","prio":"P2","sec":"s16"},{"id":"fc-232-05513b","poly":"cardio","fiche":"232","front":"Avant chirurgie sous AVK : INR visé ?","back":"**< 1,5** (< 1,2 en neurochirurgie).","prio":"P3","sec":"s16"},{"id":"fc-232-692186","poly":"cardio","fiche":"232","front":"FA : place de la correction des comorbidités ?","back":"Étape **obligatoire et fondamentale chez tous les patients**, quelle que soit la stratégie.","prio":"P1","sec":"s17"},{"id":"fc-232-8bbe86","poly":"cardio","fiche":"232","front":"FA chez l'obèse : objectif pondéral ?","back":"Perte de poids de **10 %** et/ou **IMC < 27 kg/m²**.","prio":"P2","sec":"s17"},{"id":"fc-232-6c1069","poly":"cardio","fiche":"232","front":"FA avec HTA : objectif tensionnel ?","back":"**PA systolique < 130 mmHg**.","prio":"P1","sec":"s17"},{"id":"fc-232-23509b","poly":"cardio","fiche":"232","front":"FA : mesures hygiéno-diététiques à proposer ?","back":"**Activité physique adaptée**, **alcool limité**, **sevrage tabagique**, perte de poids.","prio":"P2","sec":"s17"},{"id":"fc-232-4dcd1e","poly":"cardio","fiche":"232","front":"FA et SAOS : dépistage par questionnaire ?","back":"**N'est plus indiqué** : on discute un traitement et on encourage la **polygraphie**.","prio":"P2","sec":"s17"},{"id":"fc-232-f63402","poly":"cardio","fiche":"232","front":"Éducation sous anticoagulant : points clés ?","back":"Interactions, prévention et **signes d'alarme des saignements** ; INR et cible (AVK) ; fonction rénale (AOD) ; **carnet** ; **contraception** (tératogénicité).","prio":"P2","sec":"s17"},{"id":"fc-232-cf8ea1","poly":"cardio","fiche":"232","front":"Sous AVK : conseils supplémentaires au patient ?","back":"Éviter les coprescriptions, connaître les **seuils d'alerte de l'INR**, consulter si saignement, signaler le traitement à tout médecin.","prio":"P2","sec":"s17"},{"id":"fc-232-435b3d","poly":"cardio","fiche":"232","front":"FA : pronostic ?","back":"**Pas de risque de mort subite**, mais un risque d'**embolie cérébrale**.","prio":"P1","sec":"s17"},{"id":"fc-232-1294df","poly":"cardio","fiche":"232","front":"FA due à l'HTA : quel terrain métabolique est souvent associé ?","back":"**Surpoids** et/ou **syndrome métabolique**.","prio":"P3","sec":"s17"},{"id":"fc-232-dc4525","poly":"cardio","fiche":"232","front":"Suivi de la FA : que réévaluer régulièrement ?","back":"La balance **bénéfice/risque de l'anticoagulant** ; HTA (automesure, MAPA) et SAOS (polygraphie) ; fréquence par **holter**.","prio":"P2","sec":"s17"},{"id":"fc-233-2feb57","poly":"cardio","fiche":"233","front":"Rétrécissement aortique (RA) : définition ?","back":"**Obstacle à l'éjection du VG**, siégeant le plus souvent sur la valve aortique elle-même (temps : **systole**).","prio":"P1","sec":"s1"},{"id":"fc-233-beecd5","poly":"cardio","fiche":"233","front":"Valvulopathie la plus fréquente ?","back":"Le **rétrécissement aortique**, surtout dégénératif après 65 ans.","prio":"P1","sec":"s1"},{"id":"fc-233-49dc84","poly":"cardio","fiche":"233","front":"Insuffisance mitrale (IM) : définition ?","back":"Défaut d'étanchéité de la mitrale : **reflux systolique du VG vers l'atrium gauche**.","prio":"P1","sec":"s1"},{"id":"fc-233-cc66f1","poly":"cardio","fiche":"233","front":"IM primaire et IM secondaire : différence ?","back":"**Primaire** = valve malade ; **secondaire** = valve saine, VG ou anneau malade.","prio":"P1","sec":"s1"},{"id":"fc-233-6e11b9","poly":"cardio","fiche":"233","front":"Insuffisance aortique (IA) : définition ?","back":"**Reflux diastolique** (régurgitation) de l'aorte vers le VG.","prio":"P1","sec":"s1"},{"id":"fc-233-d3153a","poly":"cardio","fiche":"233","front":"IA : fréquence et évolution habituelle ?","back":"**Peu fréquente**, prévalence croissante avec l'âge ; peut rester **asymptomatique** de nombreuses années.","prio":"P2","sec":"s1"},{"id":"fc-233-988364","poly":"cardio","fiche":"233","front":"Autres obstacles à l'éjection du VG (hors chapitre) ?","back":"Rétrécissement **supra-aortique**, **sous-aortique** (diaphragme), obstruction dynamique des **cardiomyopathies obstructives**.","prio":"P3","sec":"s1"},{"id":"fc-233-95bee9","poly":"cardio","fiche":"233","front":"Valve aortique normale : nombre de cusps et mode d'ouverture ?","back":"**Tricuspide** (antérodroite, antérogauche, non coronaire) ; s'ouvre **passivement** selon le gradient VG–aorte.","prio":"P2","sec":"s1"},{"id":"fc-233-5fa63f","poly":"cardio","fiche":"233","front":"Bicuspidie aortique : définition et fréquence ?","back":"**2 cusps au lieu de 3** (anomalie congénitale) ; **1 à 2 %** de la population ; favorise le RA (et peut donner une IA).","prio":"P1","sec":"s1"},{"id":"fc-233-bd9f37","poly":"cardio","fiche":"233","front":"Racine aortique : composants ?","back":"**Anneau**, **sinus de Valsalva**, **jonction sinotubulaire**, puis aorte initiale.","prio":"P3","sec":"s1"},{"id":"fc-233-15e760","poly":"cardio","fiche":"233","front":"Valve mitrale : anatomie ?","back":"**2 feuillets** (antérieur = grande valve, postérieur = petite valve) sur un anneau, **2 commissures**, cordages issus de **2 piliers**.","prio":"P2","sec":"s1"},{"id":"fc-233-b16ff1","poly":"cardio","fiche":"233","front":"Valve mitrale en systole : où se rejoignent les feuillets ?","back":"**Dans le plan de l'anneau**.","prio":"P3","sec":"s1"},{"id":"fc-233-fa9eac","poly":"cardio","fiche":"233","front":"IM type I de Carpentier : mécanisme et exemples ?","back":"**Dilatation de l'anneau** ou **perforation**/déchirure d'un feuillet : IM **atriale**, perforation par endocardite.","prio":"P2","sec":"s1"},{"id":"fc-233-e2bae5","poly":"cardio","fiche":"233","front":"IM type II de Carpentier : mécanisme et exemple ?","back":"**Excès de jeu valvulaire** (cordage allongé ou rompu ± excès de tissu) → **prolapsus** : IM **dystrophiques**.","prio":"P1","sec":"s1"},{"id":"fc-233-2253d5","poly":"cardio","fiche":"233","front":"IM type IIIa de Carpentier : mécanisme et exemple ?","back":"**Restriction** du jeu en systole **et** en diastole : IM **rhumatismale** et apparentées (médicaments, radiothérapie).","prio":"P2","sec":"s1"},{"id":"fc-233-0d0630","poly":"cardio","fiche":"233","front":"IM type IIIb de Carpentier : mécanisme et exemple ?","back":"**Limitation du jeu en systole** seulement : IM **secondaire** (ischémique après infarctus inférieur, dilatation/dysfonction du VG).","prio":"P2","sec":"s1"},{"id":"fc-233-85862e","poly":"cardio","fiche":"233","front":"RA : type de surcharge et adaptation du VG ?","back":"**Surcharge de pression** → **hypertrophie concentrique** (loi de Laplace), FEVG longtemps normale.","prio":"P2","sec":"s1"},{"id":"fc-233-907fd5","poly":"cardio","fiche":"233","front":"Gradient VG–aorte normal ?","back":"**2 à 5 mmHg**.","prio":"P3","sec":"s1"},{"id":"fc-233-86822d","poly":"cardio","fiche":"233","front":"RA : pourquoi la FA est-elle en général mal tolérée ?","back":"VG épais qui se remplit mal (**dysfonction diastolique**) : la contraction atriale devient indispensable.","prio":"P2","sec":"s1"},{"id":"fc-233-2d685a","poly":"cardio","fiche":"233","front":"RA : pourquoi la récupération après le geste peut-elle être incomplète ?","back":"Une **fibrose** du VG hypertrophié (coronaires n'irriguant plus tout le muscle).","prio":"P3","sec":"s1"},{"id":"fc-233-d225d9","poly":"cardio","fiche":"233","front":"IM : type de surcharge et adaptation du VG ?","back":"**Surcharge de volume** → dilatation, **hypertrophie excentrique**.","prio":"P2","sec":"s1"},{"id":"fc-233-3571f3","poly":"cardio","fiche":"233","front":"IM : pourquoi la FEVG est-elle surestimée et quel seuil de dysfonction ?","back":"Le VG se vide aussi dans l'oreillette → FEVG surestimée : dysfonction dès **< 60 %**.","prio":"P1","sec":"s1"},{"id":"fc-233-8a1624","poly":"cardio","fiche":"233","front":"IM : de quoi dépend le volume régurgité ?","back":"Taille de l'**orifice de fuite**, **gradient VG–AG**, **durée de la systole**.","prio":"P3","sec":"s1"},{"id":"fc-233-6def39","poly":"cardio","fiche":"233","front":"IM chronique : conséquences en amont ?","back":"**AG dilaté** (risque de **FA**) et **HTP post-capillaire**.","prio":"P2","sec":"s1"},{"id":"fc-233-e3d1f2","poly":"cardio","fiche":"233","front":"IM aiguë : pourquoi l'HTP est-elle immédiate et importante ?","back":"L'AG n'a **pas le temps de se dilater** (pas d'amortissement par sa compliance).","prio":"P2","sec":"s1"},{"id":"fc-233-220247","poly":"cardio","fiche":"233","front":"IM : définition hémodynamique de l'HTP post-capillaire au cathétérisme ?","back":"**PAPO > 15 mmHg**, avec onde V de reflux.","prio":"P3","sec":"s1"},{"id":"fc-233-299e1a","poly":"cardio","fiche":"233","front":"IA : type de surcharge ?","back":"**Mixte** : volume + pression ; VG dilaté et hypertrophié, **plus que dans l'IM**.","prio":"P2","sec":"s1"},{"id":"fc-233-3ae08d","poly":"cardio","fiche":"233","front":"IA : retentissement artériel ?","back":"PAS qui monte, **PAD qui baisse** → pression pulsée large, **hyperpulsatilité**.","prio":"P2","sec":"s1"},{"id":"fc-233-6bf229","poly":"cardio","fiche":"233","front":"IA : pourquoi un angor sans coronaropathie ?","back":"Coronaires perfusées surtout en diastole : la **PAD basse** réduit leur perfusion.","prio":"P2","sec":"s1"},{"id":"fc-233-884ab4","poly":"cardio","fiche":"233","front":"IA aiguë : pourquoi un OAP ?","back":"VG de taille normale ou peu dilaté : les **pressions de remplissage montent d'un coup**.","prio":"P2","sec":"s1"},{"id":"fc-233-03d9e3","poly":"cardio","fiche":"233","front":"IA chronique : de quoi dépend le volume de fuite ?","back":"Orifice régurgitant, **durée de la diastole**, gradient diastolique aorte–VG.","prio":"P3","sec":"s1"},{"id":"fc-233-0193c7","poly":"cardio","fiche":"233","front":"IA chronique avec VG très dilaté ou FE abaissée : risque après chirurgie ?","back":"Remodelage du VG parfois **irréversible**.","prio":"P3","sec":"s1"},{"id":"fc-233-af6bad","poly":"cardio","fiche":"233","front":"IA aiguë : particularité auscultatoire ?","back":"Parfois **peu audible**.","prio":"P3","sec":"s1"},{"id":"fc-233-e4b937","poly":"cardio","fiche":"233","front":"Valvulopathie : une FEVG normale rassure-t-elle ?","back":"**Non** : longtemps normale dans le RA serré ; dans l'IM sévère, **< 60 %** est déjà une dysfonction.","prio":"P2","sec":"s1"},{"id":"fc-233-f560bc","poly":"cardio","fiche":"233","front":"RA : cause la plus fréquente entre 30 et 65 ans ?","back":"La **bicuspidie** aortique.","prio":"P1","sec":"s2"},{"id":"fc-233-fe1004","poly":"cardio","fiche":"233","front":"RA : cause la plus fréquente chez le sujet âgé ?","back":"Le **RA dégénératif** (maladie de **Mönckeberg**), de loin après 65-70 ans.","prio":"P1","sec":"s2"},{"id":"fc-233-d79d4d","poly":"cardio","fiche":"233","front":"RA dégénératif : mécanisme ?","back":"**Calcifications** à la base des valvules qui se rigidifient ; plus la sténose est serrée, plus la valve est calcifiée ; proche de l'**athérosclérose**.","prio":"P2","sec":"s2"},{"id":"fc-233-e9c6e8","poly":"cardio","fiche":"233","front":"Bicuspidie : anomalie aortique associée à rechercher ?","back":"**Anévrisme de l'aorte ascendante** (plus rarement **coarctation**).","prio":"P1","sec":"s2"},{"id":"fc-233-253607","poly":"cardio","fiche":"233","front":"Bicuspidie : transmission et conséquence ?","back":"Possiblement **autosomique dominante** à pénétrance variable → **dépistage des apparentés du 1er degré**.","prio":"P2","sec":"s2"},{"id":"fc-233-f7a2ff","poly":"cardio","fiche":"233","front":"RA post-rhumatismal : fréquence et lésions associées ?","back":"Devenu **rare** (encore chez les migrants) ; **habituellement** associé à une **IA** et une atteinte **mitrale** (RM + IM).","prio":"P3","sec":"s2"},{"id":"fc-233-b2ccd5","poly":"cardio","fiche":"233","front":"IM : première cause des fuites sévères ?","back":"L'**IM dystrophique** (Carpentier II) : élongation ou **rupture de cordages** → prolapsus.","prio":"P1","sec":"s2"},{"id":"fc-233-a0c1ce","poly":"cardio","fiche":"233","front":"Maladie de Barlow : caractéristiques ?","back":"**Dégénérescence myxoïde** : valves redondantes, épaissies, hypermobiles.","prio":"P2","sec":"s2"},{"id":"fc-233-00859e","poly":"cardio","fiche":"233","front":"Dégénérescence fibroélastique mitrale : terrain et atteinte typiques ?","back":"Plus fréquente ; sujet **plus âgé**, surtout **homme**, **valve postérieure**, **rupture de cordage**.","prio":"P2","sec":"s2"},{"id":"fc-233-164508","poly":"cardio","fiche":"233","front":"IM dystrophique : dystrophies du tissu conjonctif associées ?","back":"Parfois **Marfan** ou **Ehlers-Danlos**.","prio":"P3","sec":"s2"},{"id":"fc-233-8319d7","poly":"cardio","fiche":"233","front":"IM rhumatismale : caractéristiques ?","back":"Rare en pays développés, endémique ailleurs ; souvent avec un **RM** (« maladie mitrale ») et une atteinte aortique ; valves épaissies, rétractées.","prio":"P2","sec":"s2"},{"id":"fc-233-fca90e","poly":"cardio","fiche":"233","front":"IM apparentées au rhumatisme : causes médicamenteuses et autres ?","back":"**Dérivés de l'ergot de seigle**, anorexigènes retirés (**fenfluramine**, **benfluorex**) ; **radiothérapie**.","prio":"P2","sec":"s2"},{"id":"fc-233-d09e6a","poly":"cardio","fiche":"233","front":"IM par endocardite : terrain et lésions ?","back":"Plus de la moitié sur **valve déjà lésée** ; **ruptures de cordages** ou **perforations**, surtout de la valve antérieure.","prio":"P2","sec":"s2"},{"id":"fc-233-fe8cac","poly":"cardio","fiche":"233","front":"IM secondaire : causes ?","back":"IM **ischémique** (classiquement après infarctus **inférieur**) ou **dilatation/dysfonction du VG**.","prio":"P1","sec":"s2"},{"id":"fc-233-54d9cf","poly":"cardio","fiche":"233","front":"IM atriale : mécanisme ?","back":"Anneau dilaté par un **AG très dilaté** (Carpentier I) ; plus rare.","prio":"P3","sec":"s2"},{"id":"fc-233-3321c0","poly":"cardio","fiche":"233","front":"CMH obstructive : mécanisme de l'IM ?","back":"Feuillet antérieur aspiré dans la chambre de chasse (**SAM**).","prio":"P3","sec":"s2"},{"id":"fc-233-1a2f71","poly":"cardio","fiche":"233","front":"IA type 1 (mouvement normal des cusps) : mécanismes ?","back":"**Dilatation de la racine aortique** ou **perforation** de cusp (surtout endocardite).","prio":"P2","sec":"s2"},{"id":"fc-233-952bd9","poly":"cardio","fiche":"233","front":"IA par dilatation de la racine : causes ?","back":"Idiopathique, génétique (**Marfan**, Loeys-Dietz, Ehlers-Danlos), **aortites**, bicuspidie, **dissection**.","prio":"P2","sec":"s2"},{"id":"fc-233-ad87da","poly":"cardio","fiche":"233","front":"IA : aortites causales citées ?","back":"**Takayasu**, **Horton**, Behçet, **spondylarthrite ankylosante**, **syphilis**.","prio":"P2","sec":"s2"},{"id":"fc-233-2270f3","poly":"cardio","fiche":"233","front":"Maladie annuloectasiante : définition et risque ?","back":"Dilatation surtout de l'anneau et des sinus → risque de **dissection ou rupture** ; penser **Marfan**.","prio":"P1","sec":"s2"},{"id":"fc-233-e50321","poly":"cardio","fiche":"233","front":"IA type 2 (prolapsus) : causes ?","back":"Dystrophie isolée, **bicuspidie** (prolapsus de la cusp fusionnée) ; plus rarement endocardite, traumatisme, dissection, CIV sous-aortique (**Laubry-Pezzi**).","prio":"P2","sec":"s2"},{"id":"fc-233-022446","poly":"cardio","fiche":"233","front":"IA type 3 (restriction) : causes ?","back":"**RAA** ; **médicaments** (ergot de seigle, fenfluramine, **benfluorex**, MDMA) ; carcinoïde ; **radiothérapie médiastinale**.","prio":"P2","sec":"s2"},{"id":"fc-233-3b30e8","poly":"cardio","fiche":"233","front":"Syndrome carcinoïde : pourquoi les valves gauches sont-elles rarement atteintes ?","back":"La sérotonine est arrêtée par le **filtre pulmonaire** (sauf foramen ovale perméable ou métastase pulmonaire).","prio":"P3","sec":"s2"},{"id":"fc-233-85f070","poly":"cardio","fiche":"233","front":"Bicuspidie : 3 complications valvulaires ou infectieuses ?","back":"**RA** à tout âge, **IA** (prolapsus de la plus grande cusp), **endocardite** ; plus dilatation aortique.","prio":"P2","sec":"s2"},{"id":"fc-233-03acb5","poly":"cardio","fiche":"233","front":"Principales causes d'IA en Occident ?","back":"**Dystrophie valvulaire**, **dilatation aortique**, **bicuspidie**, **endocardite**.","prio":"P1","sec":"s2"},{"id":"fc-233-467890","poly":"cardio","fiche":"233","front":"Causes d'IM aiguë ?","back":"**Rupture de cordages**, **infarctus** (rupture ou dysfonction de pilier), traumatisme thoracique, **perforation** par endocardite.","prio":"P1","sec":"s2"},{"id":"fc-233-832d95","poly":"cardio","fiche":"233","front":"IM dystrophique : ballonnisation ou prolapsus, différence ?","back":"**Ballonnisation** : feuillet qui bombe dans l'AG, bord libre dans le plan de l'anneau ; **prolapsus** : l'extrémité passe en arrière de ce plan.","prio":"P3","sec":"s2"},{"id":"fc-233-b80900","poly":"cardio","fiche":"233","front":"Causes d'IA aiguë ?","back":"Surtout **endocardite** ; **dissection aortique** ; **traumatisme**.","prio":"P1","sec":"s2"},{"id":"fc-233-c4c3cd","poly":"cardio","fiche":"233","front":"IA sur prothèse : une fuite minime est-elle anormale ?","back":"**Non**, une IA minime est **normale** sur toute prothèse.","prio":"P3","sec":"s2"},{"id":"fc-233-ac3ab1","poly":"cardio","fiche":"233","front":"Valvulopathies : circonstances de découverte ?","back":"**Souffle** (souvent fortuit), **symptômes d'effort**, **complication** (IC, OAP, FA), **fièvre** prolongée, écho pour autre chose.","prio":"P2","sec":"s3"},{"id":"fc-233-05797a","poly":"cardio","fiche":"233","front":"RA : 3 symptômes typiques ?","back":"**Dyspnée**, **angor**, **syncope**, tous **à l'effort**.","prio":"P1","sec":"s3"},{"id":"fc-233-bd0849","poly":"cardio","fiche":"233","front":"RA : signification de l'apparition des symptômes ?","back":"**Cassure évolutive** : mauvais pronostic sans traitement.","prio":"P1","sec":"s3"},{"id":"fc-233-3cf3d0","poly":"cardio","fiche":"233","front":"IM : symptômes ?","back":"Rien si modérée ; **dyspnée d'effort** lente et progressive ± asthénie, palpitations ; tard orthopnée ; **OAP tardif et grave**.","prio":"P2","sec":"s3"},{"id":"fc-233-947b15","poly":"cardio","fiche":"233","front":"IA : symptômes ?","back":"Longtemps **asymptomatique** ; dyspnée d'effort, asthénie ; angor rare ; signes de repos tardifs, de mauvais pronostic.","prio":"P2","sec":"s3"},{"id":"fc-233-daf802","poly":"cardio","fiche":"233","front":"Souffle de RA : caractéristiques ?","back":"**Mésosystolique éjectionnel**, losangique, **rude, râpeux**, au **2e EIC droit**, irradiant aux **vaisseaux du cou**.","prio":"P1","sec":"s3"},{"id":"fc-233-a5c286","poly":"cardio","fiche":"233","front":"RA serré calcifié : signe auscultatoire associé ?","back":"**B2 aboli**.","prio":"P1","sec":"s3"},{"id":"fc-233-112953","poly":"cardio","fiche":"233","front":"RA : signification d'un frémissement ?","back":"En général, un RA **significatif** (souffle **4/6**).","prio":"P2","sec":"s3"},{"id":"fc-233-419754","poly":"cardio","fiche":"233","front":"Souffle d'IM : caractéristiques ?","back":"**Holosystolique** (B1 à B2), à la **pointe**, irradiant à l'**aisselle**, en **jet de vapeur**.","prio":"P1","sec":"s3"},{"id":"fc-233-e07e80","poly":"cardio","fiche":"233","front":"Souffle systolique après une diastole longue : RA ou IM ?","back":"**RA** : se renforce ; **IM** : ne se renforce pas.","prio":"P1","sec":"s3"},{"id":"fc-233-af4eae","poly":"cardio","fiche":"233","front":"Souffle d'IA : caractéristiques ?","back":"**Diastolique**, le long du **bord gauche du sternum** ; holodiastolique si importante.","prio":"P1","sec":"s3"},{"id":"fc-233-27b3f6","poly":"cardio","fiche":"233","front":"Souffle d'IA : comment mieux l'entendre ?","back":"Patient **penché en avant**, en **expiration bloquée**.","prio":"P2","sec":"s3"},{"id":"fc-233-0add15","poly":"cardio","fiche":"233","front":"IA : signes auscultatoires de sévérité ?","back":"**Roulement de Flint** apexien ou **galop**.","prio":"P2","sec":"s3"},{"id":"fc-233-5c6726","poly":"cardio","fiche":"233","front":"IM : l'intensité du souffle reflète-t-elle la sévérité ?","back":"**Souvent**, mais **pas toujours**.","prio":"P2","sec":"s3"},{"id":"fc-233-0f3927","poly":"cardio","fiche":"233","front":"Prolapsus mitral : signe auscultatoire caractéristique ?","back":"**Clic mésosystolique**, puis souffle méso-télésystolique ou télésystolique.","prio":"P1","sec":"s3"},{"id":"fc-233-39d95d","poly":"cardio","fiche":"233","front":"IM importante : signes auscultatoires associés ?","back":"Galop **B3**, roulement mésodiastolique d'hyperdébit, éclat de **B2 pulmonaire** (HTP), souffle d'IT fonctionnelle ; crépitants.","prio":"P2","sec":"s3"},{"id":"fc-233-7e368b","poly":"cardio","fiche":"233","front":"IA : signes périphériques ?","back":"**Hyperpulsatilité** des pouls, battements du cou, oscillation de la tête, pulsatilité sous-unguéale.","prio":"P1","sec":"s3"},{"id":"fc-233-e18271","poly":"cardio","fiche":"233","front":"IA : signe tensionnel de sévérité ?","back":"**Différentielle élargie** avec **PAD abaissée**.","prio":"P1","sec":"s3"},{"id":"fc-233-f30a23","poly":"cardio","fiche":"233","front":"RA évolué à bas débit : particularité du souffle ?","back":"**Atténué**, voire presque **inaudible**.","prio":"P2","sec":"s3"},{"id":"fc-233-cfa189","poly":"cardio","fiche":"233","front":"Maladie aortique : définition ?","back":"Association d'un **RA** et d'une **IA**.","prio":"P3","sec":"s3"},{"id":"fc-233-19afba","poly":"cardio","fiche":"233","front":"Frémissement du RA : comment le chercher ?","back":"Plat de la main, patient **penché en avant**, en **fin d'expiration**.","prio":"P3","sec":"s3"},{"id":"fc-233-6bf73c","poly":"cardio","fiche":"233","front":"Souffle d'IA : avis cardiologique nécessaire ?","back":"**Oui**, symptomatique ou non.","prio":"P1","sec":"s3"},{"id":"fc-233-453205","poly":"cardio","fiche":"233","front":"Valvulopathie « asymptomatique » : quel piège à l'interrogatoire ?","back":"Le patient a souvent **réduit ses activités** sans s'en rendre compte : chercher une baisse progressive des efforts.","prio":"P1","sec":"s3"},{"id":"fc-233-38cbf1","poly":"cardio","fiche":"233","front":"Souffle faible : quelles valvulopathies sévères peut-il cacher ?","back":"**RA à bas débit** ; **IM secondaire** (souffle discret voire inaudible, mal corrélé à la sévérité).","prio":"P2","sec":"s3"},{"id":"fc-233-a12db9","poly":"cardio","fiche":"233","front":"Valvulopathies : examen clé ?","back":"L'**échocardiographie transthoracique** (ETT).","prio":"P1","sec":"s4"},{"id":"fc-233-78d7be","poly":"cardio","fiche":"233","front":"ETT d'une valvulopathie : 4 questions ?","back":"**Confirmer** ; **mécanisme et cause** ; **quantifier** ; **retentissement** et voisinage (VG, PAP, oreillette, autres valves, aorte).","prio":"P1","sec":"s4"},{"id":"fc-233-bda131","poly":"cardio","fiche":"233","front":"ETT : signes de RA ?","back":"Valve remaniée, **calcifiée**, qui s'ouvre mal ; vitesses accélérées (**> 2,5 m/s**).","prio":"P2","sec":"s4"},{"id":"fc-233-200c1b","poly":"cardio","fiche":"233","front":"RA serré : seuil de vitesse maximale ?","back":"**Vmax > 4 m/s** (normale ≈ 1 m/s).","prio":"P1","sec":"s4"},{"id":"fc-233-ffe0b1","poly":"cardio","fiche":"233","front":"RA serré : seuil de gradient moyen ?","back":"**> 40 mmHg** (normal 2-5 mmHg).","prio":"P1","sec":"s4"},{"id":"fc-233-577b7b","poly":"cardio","fiche":"233","front":"RA serré : seuil de surface ?","back":"**< 1 cm²** ou **< 0,6 cm²/m²** (normale 2-3,5 cm²).","prio":"P1","sec":"s4"},{"id":"fc-233-7636f4","poly":"cardio","fiche":"233","front":"RA critique : seuil de surface ?","back":"**≤ 0,75 cm²** ou ≤ 0,4 cm²/m².","prio":"P3","sec":"s4"},{"id":"fc-233-e7da14","poly":"cardio","fiche":"233","front":"RA serré à bas gradient : situation et examen ?","back":"**Bas débit** (VES ≤ 35 mL/m²) avec gradient < 40 mmHg → **écho sous faible dose de dobutamine**.","prio":"P1","sec":"s4"},{"id":"fc-233-c7ead1","poly":"cardio","fiche":"233","front":"Pseudosténose aortique : définition et conduite ?","back":"Surface < 1 cm² au repos qui **dépasse 1 cm²** sous dobutamine : **surveiller** et traiter comme une **insuffisance cardiaque**.","prio":"P1","sec":"s4"},{"id":"fc-233-0d7e78","poly":"cardio","fiche":"233","front":"RA : place de l'ETO ?","back":"Peu d'intérêt, sauf **patient peu échogène** (planimétrie si sévérité douteuse).","prio":"P3","sec":"s4"},{"id":"fc-233-74d840","poly":"cardio","fiche":"233","front":"RA asymptomatique : seuil de FEVG faisant discuter le remplacement ?","back":"**FEVG ≤ 55 %** due au seul RA (strain, IRM si doute).","prio":"P2","sec":"s4"},{"id":"fc-233-d6d844","poly":"cardio","fiche":"233","front":"IM : quand l'ETO est-elle obligatoire ?","back":"**Endocardite** suspectée (végétations fines invisibles en ETT).","prio":"P1","sec":"s4"},{"id":"fc-233-0657ca","poly":"cardio","fiche":"233","front":"IM : autre intérêt de l'ETO ?","back":"Préciser le **mécanisme** et la **faisabilité d'une plastie** (souvent en préopératoire).","prio":"P2","sec":"s4"},{"id":"fc-233-ff17a1","poly":"cardio","fiche":"233","front":"IM : grades de sévérité ?","back":"Minime ou modérée = **grades I-II** ; significative ou importante = **grades III-IV**.","prio":"P2","sec":"s4"},{"id":"fc-233-53dbe4","poly":"cardio","fiche":"233","front":"IM : quelle autre valve vérifier à l'écho ?","back":"La **tricuspide** : sa fuite doit parfois être corrigée pendant la chirurgie mitrale.","prio":"P2","sec":"s4"},{"id":"fc-233-370990","poly":"cardio","fiche":"233","front":"IA : quels grades imposent une surcharge de volume significative ?","back":"**Seuls les grades 3 et 4** (sur 4 grades).","prio":"P2","sec":"s4"},{"id":"fc-233-c7120c","poly":"cardio","fiche":"233","front":"ECG du RA serré ?","back":"**HVG de type surcharge systolique** ; HAG ; **BBG**, **BAV 1** ; FA si évolué.","prio":"P2","sec":"s4"},{"id":"fc-233-417af0","poly":"cardio","fiche":"233","front":"RA : un ECG sans HVG exclut-il un RA serré ?","back":"**Non**.","prio":"P2","sec":"s4"},{"id":"fc-233-101276","poly":"cardio","fiche":"233","front":"ECG de l'IM ?","back":"Longtemps **normal** ; HAG, HVG, FA ; **HVD** si HTP sévère.","prio":"P3","sec":"s4"},{"id":"fc-233-271c72","poly":"cardio","fiche":"233","front":"Radiographie de l'IM évoluée ?","back":"**Cardiomégalie**, AG dilaté (arc moyen gauche convexe), signes d'HTP et d'IC (Kerley, redistribution, œdème).","prio":"P3","sec":"s4"},{"id":"fc-233-afa896","poly":"cardio","fiche":"233","front":"ECG de l'IA ?","back":"Rythme sinusal en général ; **HVG diastolique** (grandes R, T positives) ; FA ou ESV = **mauvais pronostic**.","prio":"P3","sec":"s4"},{"id":"fc-233-48faf4","poly":"cardio","fiche":"233","front":"Radiographie de l'IA volumineuse ?","back":"**Index cardiothoracique augmenté** ; aorte déroulée.","prio":"P3","sec":"s4"},{"id":"fc-233-0706ca","poly":"cardio","fiche":"233","front":"Épreuve d'effort dans le RA : indication ?","back":"**RA serré asymptomatique**, pour vérifier objectivement l'absence de symptôme.","prio":"P2","sec":"s4"},{"id":"fc-233-8fff24","poly":"cardio","fiche":"233","front":"Épreuve d'effort dans le RA symptomatique ?","back":"**Contre-indiquée**.","prio":"P1","sec":"s4"},{"id":"fc-233-9f4edb","poly":"cardio","fiche":"233","front":"Épreuve d'effort du RA : quels signes d'anomalie ?","back":"Niveau atteint ; **PA qui monte mal ou qui baisse**.","prio":"P3","sec":"s4"},{"id":"fc-233-3005b9","poly":"cardio","fiche":"233","front":"Valvulopathie : place du cathétérisme ?","back":"Habituellement **inutile** ; seulement si **discordance** clinique/écho ou patient peu échogène.","prio":"P2","sec":"s4"},{"id":"fc-233-1869a2","poly":"cardio","fiche":"233","front":"RA : indications de la coronarographie préopératoire ?","back":"**Homme > 40 ans** ou **femme ménopausée** même sans FDR ; à tout âge si FDR, angor d'effort ou IC.","prio":"P1","sec":"s4"},{"id":"fc-233-1939f9","poly":"cardio","fiche":"233","front":"IM : imagerie coronaire préopératoire ?","back":"**Coroscanner** si faible probabilité prétest ; sinon **coronarographie** (ischémie, baisse de FEVG, homme > 40 ans, femme ménopausée, FDR).","prio":"P2","sec":"s4"},{"id":"fc-233-e657ba","poly":"cardio","fiche":"233","front":"Avant TAVI : examen systématique et but ?","back":"**Scanner cardiaque** : anneau, culot aortique, distance des ostia coronaires → **taille de prothèse**.","prio":"P1","sec":"s4"},{"id":"fc-233-eea95b","poly":"cardio","fiche":"233","front":"Scanner pré-TAVI : autres apports ?","back":"**Axes artériels** (ilio-fémoral, subclavier, carotidien) ; **score calcique valvulaire**.","prio":"P3","sec":"s4"},{"id":"fc-233-5aac0b","poly":"cardio","fiche":"233","front":"IA : place de l'IRM ?","back":"Aorte ascendante (non irradiante ; gadolinium CI si IR sévère) ; volumes du VG, FEVG, volume régurgité.","prio":"P3","sec":"s4"},{"id":"fc-233-e934db","poly":"cardio","fiche":"233","front":"RA : piège du gradient seul ?","back":"Avec un **bas débit**, un RA serré peut avoir un gradient **< 40 mmHg** → compléter par la **surface**.","prio":"P2","sec":"s4"},{"id":"fc-233-90e192","poly":"cardio","fiche":"233","front":"Valvulopathie : 2 éléments qui font basculer vers l'intervention ?","back":"**Apparition de symptômes** et **retentissement** (VG, oreillette/FA, HTP).","prio":"P2","sec":"s5"},{"id":"fc-233-c56b7d","poly":"cardio","fiche":"233","front":"RA serré asymptomatique : critères d'intervention ?","back":"**Épreuve d'effort anormale** ; **Vmax > 5 m/s** ; **aggravation rapide** ; **FEVG < 55 %**.","prio":"P2","sec":"s5"},{"id":"fc-233-e07f1d","poly":"cardio","fiche":"233","front":"IM primaire importante asymptomatique : critères d'intervention ?","back":"**DTS ≥ 40 mm** (avec rupture de cordage), **FEVG ≤ 60 %**, **PAPs ≥ 50 mmHg**, **FA** ou **AG > 60 mL/m²**.","prio":"P2","sec":"s5"},{"id":"fc-233-990641","poly":"cardio","fiche":"233","front":"IA sévère asymptomatique : critères d'intervention formels ?","back":"**DTS > 50 mm ou > 25 mm/m²**, ou **FEVG ≤ 50 %**.","prio":"P2","sec":"s5"},{"id":"fc-233-d042d4","poly":"cardio","fiche":"233","front":"IA sévère asymptomatique, chirurgie à bas risque : critères ?","back":"**DTS > 20 mm/m²** ou **FEVG ≤ 55 %**.","prio":"P3","sec":"s5"},{"id":"fc-233-8230cf","poly":"cardio","fiche":"233","front":"Aorte ascendante : seuils d'intervention ?","back":"**≥ 55 mm** ; **≥ 50 mm si Marfan** ; ≥ 45 mm si Marfan avec FDR ; ≥ 50 mm si bicuspidie avec FDR.","prio":"P2","sec":"s5"},{"id":"fc-233-f33197","poly":"cardio","fiche":"233","front":"IM : progressive ou brutale, quelle tolérance ?","back":"Progressive = **bien tolérée**, IC tardive ; brutale (cordage, endocardite, infarctus) = **OAP rapide**.","prio":"P1","sec":"s5"},{"id":"fc-233-113d9d","poly":"cardio","fiche":"233","front":"IA : 2 déterminants du pronostic ?","back":"**Retentissement sur le VG** et **dilatation aortique** (dissection, rupture).","prio":"P3","sec":"s5"},{"id":"fc-233-3ded2f","poly":"cardio","fiche":"233","front":"IA grades 3-4 : pourquoi opérer souvent avant les symptômes ?","back":"Lésions du VG possiblement **irréversibles**.","prio":"P2","sec":"s5"},{"id":"fc-233-adfc9d","poly":"cardio","fiche":"233","front":"RA : complications ?","back":"**Insuffisance cardiaque**, **FA mal tolérée**, troubles de conduction, **mort subite** (surtout RA serré symptomatique) ; plus rarement endocardite, embolies calcaires.","prio":"P2","sec":"s5"},{"id":"fc-233-908e51","poly":"cardio","fiche":"233","front":"Syndrome de Heyde : définition ?","back":"RA + **anémie ferriprive** par **angiodysplasies intestinales** ± déficit acquis en facteur **von Willebrand**.","prio":"P3","sec":"s5"},{"id":"fc-233-cf9d81","poly":"cardio","fiche":"233","front":"RA : territoires des embolies calcaires ?","back":"**Cerveau**, **rein**, **coronaires**, artère centrale de la rétine.","prio":"P3","sec":"s5"},{"id":"fc-233-382a21","poly":"cardio","fiche":"233","front":"IM : complications ?","back":"**Rupture de cordage**, **endocardite**, **FA ou flutter**, troubles du rythme ventriculaire (rares), **insuffisance cardiaque**.","prio":"P2","sec":"s5"},{"id":"fc-233-678902","poly":"cardio","fiche":"233","front":"IM : signification d'une FA chez l'asymptomatique ?","back":"Elle justifie une **chirurgie précoce**.","prio":"P2","sec":"s5"},{"id":"fc-233-57ca17","poly":"cardio","fiche":"233","front":"IA : complications ?","back":"**Endocardite** (faible surrisque), **IC** tardive, **dissection ou rupture aortique**, mort subite (rare).","prio":"P3","sec":"s5"},{"id":"fc-233-35227c","poly":"cardio","fiche":"233","front":"IM aiguë : gravité ?","back":"Le plus souvent grave sur le plan hémodynamique : **urgence vitale**.","prio":"P1","sec":"s5"},{"id":"fc-233-76ad4b","poly":"cardio","fiche":"233","front":"OAP unilatéral : quelle valvulopathie aiguë évoquer ?","back":"**IM aiguë** par **rupture de cordage** (fuite dirigée vers un poumon).","prio":"P1","sec":"s6"},{"id":"fc-233-ac40c1","poly":"cardio","fiche":"233","front":"Souffle systolique éjectionnel dans une IA : signification la plus fréquente ?","back":"Souffle d'**hyperdébit**, pas forcément un RA.","prio":"P2","sec":"s6"},{"id":"fc-233-dbbff9","poly":"cardio","fiche":"233","front":"Roulement mésodiastolique sans RM : quelles causes ?","back":"**IM importante** (hyperdébit) ou **IA sévère** (**roulement de Flint**).","prio":"P2","sec":"s6"},{"id":"fc-233-b59213","poly":"cardio","fiche":"233","front":"IA aiguë : orientation selon la présence de fièvre ?","back":"**Fièvre → endocardite** ; douleur thoracique ou AVC **sans fièvre → dissection aortique**.","prio":"P1","sec":"s6"},{"id":"fc-233-d9ba15","poly":"cardio","fiche":"233","front":"IM atriale vs IM ventriculaire : types de Carpentier ?","back":"**Atriale** = type I (anneau dilaté) ; **ventriculaire** = type IIIb (piliers déplacés).","prio":"P2","sec":"s6"},{"id":"fc-233-7daedb","poly":"cardio","fiche":"233","front":"Diagnostics différentiels d'un souffle diastolique d'IA ?","back":"**Insuffisance pulmonaire**, rupture d'un sinus aortique, **canal artériel**, fistule coronarienne, frottement péricardique ; l'écho tranche.","prio":"P3","sec":"s6"},{"id":"fc-233-8c84dd","poly":"cardio","fiche":"233","front":"Rupture de pilier post-infarctus : quel piège ?","back":"La prendre pour une simple décompensation cardiaque : c'est une **urgence chirurgicale**.","prio":"P1","sec":"s6"},{"id":"fc-233-6482b0","poly":"cardio","fiche":"233","front":"RA symptomatique : conduite initiale obligatoire ?","back":"**Adresser au spécialiste** (ne pas le faire est inacceptable).","prio":"P1","sec":"s7"},{"id":"fc-233-85eb48","poly":"cardio","fiche":"233","front":"RA serré symptomatique : traitement ?","back":"**Traiter la valve** dans tous les cas : **RVA chirurgical ou TAVI**, pratiquement **sans limite d'âge** si état général conservé.","prio":"P1","sec":"s7"},{"id":"fc-233-efe604","poly":"cardio","fiche":"233","front":"RA : qui décide entre chirurgie et TAVI ?","back":"La **Heart Team** (âge, fragilité, comorbidités, souhaits du patient).","prio":"P2","sec":"s7"},{"id":"fc-233-47735a","poly":"cardio","fiche":"233","front":"RVA par bioprothèse : pour qui et limite ?","back":"Patient **> 65 ans** ; pas d'anticoagulant au long cours ; **dégénérescence en 10-15 ans**.","prio":"P2","sec":"s7"},{"id":"fc-233-0fc2e2","poly":"cardio","fiche":"233","front":"RVA par prothèse mécanique : pour qui et contrainte ?","back":"**Sujet jeune** ; longue durabilité ; **anticoagulation à vie**.","prio":"P2","sec":"s7"},{"id":"fc-233-155523","poly":"cardio","fiche":"233","front":"TAVI : indications ?","back":"**Inopérable ou à risque opératoire** quel que soit l'âge ; **1re intention après 75 ans** si voie fémorale possible.","prio":"P1","sec":"s7"},{"id":"fc-233-1788a6","poly":"cardio","fiche":"233","front":"Valvuloplastie aortique au ballon : seule indication restante ?","back":"**Chirurgie non cardiaque urgente à risque** chez un RA serré symptomatique (**resténose précoce** fréquente).","prio":"P2","sec":"s7"},{"id":"fc-233-7f70a2","poly":"cardio","fiche":"233","front":"RA serré asymptomatique sans critère d'intervention : conduite ?","back":"**Surveillance médicale et ETT**, suivi **annuel** spécialisé ; réadresser si souffle modifié ou symptômes.","prio":"P2","sec":"s7"},{"id":"fc-233-f7722a","poly":"cardio","fiche":"233","front":"Vrai RA serré avec FE < 35 % : opère-t-on ?","back":"**Discuter le remplacement** : risque plus élevé, mais pronostic **le plus mauvais chez les non-opérés**.","prio":"P2","sec":"s7"},{"id":"fc-233-e1c606","poly":"cardio","fiche":"233","front":"Prothèse mécanique : quel anticoagulant et pour combien de temps ?","back":"**AVK à vie** ; **AOD contre-indiqués**.","prio":"P1","sec":"s7"},{"id":"fc-233-490eec","poly":"cardio","fiche":"233","front":"Prothèse mécanique : INR cible (item 153) ?","back":"**Entre 2,5 et 4** selon le risque thrombotique de la prothèse et du patient (ex. aortique à faible risque sans FDR : 2,5).","prio":"P2","sec":"s7"},{"id":"fc-233-9bba53","poly":"cardio","fiche":"233","front":"Prothèse mécanique sous AVK : ajoute-t-on un antiagrégant ?","back":"**Non**, sauf situation particulière (stent récent, embolie sous INR efficace).","prio":"P3","sec":"s7"},{"id":"fc-233-f1a417","poly":"cardio","fiche":"233","front":"Bioprothèse aortique chirurgicale : antithrombotique ?","back":"**Aspirine ou AVK 3 mois** puis rien (sauf autre indication, ex. FA).","prio":"P2","sec":"s7"},{"id":"fc-233-4b38dc","poly":"cardio","fiche":"233","front":"Après TAVI : antithrombotique ?","back":"**Aspirine seule** si rythme sinusal ; **anticoagulation** si FA (AOD autorisés).","prio":"P2","sec":"s7"},{"id":"fc-233-32eea6","poly":"cardio","fiche":"233","front":"Antibioprophylaxie de l'endocardite : schéma de référence avant soin dentaire à risque ?","back":"**Amoxicilline 2 g** per os ou IV **30-60 min avant** (item 152) ; l'item 153 cite 3 g 1 h avant.","prio":"P1","sec":"s7"},{"id":"fc-233-467e61","poly":"cardio","fiche":"233","front":"Antibioprophylaxie chez l'allergique à la pénicilline : quelle erreur éviter ?","back":"Prescrire une **pénicilline** (notion inacceptable).","prio":"P1","sec":"s7"},{"id":"fc-233-dfd7cf","poly":"cardio","fiche":"233","front":"Antibioprophylaxie : alternatives à l'amoxicilline citées ?","back":"**Ampicilline** ; ou **céfazoline** / **ceftriaxone** (1 g IM ou IV).","prio":"P3","sec":"s7"},{"id":"fc-233-d14291","poly":"cardio","fiche":"233","front":"RA avec FE < 35 % : classes de l'IC à FE diminuée ?","back":"**IEC** (ou ARA2/sacubitril-valsartan), **bêtabloquant**, **antialdostérone**, **gliflozine**, **diurétique de l'anse** si congestion.","prio":"P2","sec":"s7"},{"id":"fc-233-911b0d","poly":"cardio","fiche":"233","front":"RA : 3 erreurs thérapeutiques ?","back":"Récuser sur le **seul âge** ; renoncer parce que la **FE est basse** ; proposer la **valvuloplastie** comme traitement de fond.","prio":"P1","sec":"s7"},{"id":"fc-233-01897a","poly":"cardio","fiche":"233","front":"IM importante symptomatique : conduite ?","back":"**On opère** ; il n'y a pas de traitement médical de fond de l'IM primaire.","prio":"P1","sec":"s8"},{"id":"fc-233-54ae1e","poly":"cardio","fiche":"233","front":"IM primaire : technique chirurgicale de préférence ?","back":"**Plastie reconstructrice**, à privilégier dans les **prolapsus**.","prio":"P1","sec":"s8"},{"id":"fc-233-44abea","poly":"cardio","fiche":"233","front":"IM avec VG altéré : plastie possible ?","back":"**Oui**, la plastie peut toujours être envisagée.","prio":"P2","sec":"s8"},{"id":"fc-233-ea903f","poly":"cardio","fiche":"233","front":"IM : remplacement valvulaire contre-indiqué en dessous de quelle FE ?","back":"**FE < 30 %** (contrairement à la plastie).","prio":"P2","sec":"s8"},{"id":"fc-233-00f554","poly":"cardio","fiche":"233","front":"IM à haut risque chirurgical : alternative ?","back":"**Clip percutané** (suture bord à bord), en centre expérimenté.","prio":"P2","sec":"s8"},{"id":"fc-233-8bb6a8","poly":"cardio","fiche":"233","front":"IM primaire importante asymptomatique sans critère : surveillance ?","back":"**Écho-doppler tous les 6 mois** ; chirurgie dès retentissement, dyspnée d'effort ou FA.","prio":"P2","sec":"s8"},{"id":"fc-233-7f9807","poly":"cardio","fiche":"233","front":"IM minime ou modérée (grade I-II) : conduite ?","back":"**Pas d'intervention** ; réévaluation clinique et écho ; hygiène, soins dentaires **sans antibioprophylaxie**.","prio":"P2","sec":"s8"},{"id":"fc-233-f9136b","poly":"cardio","fiche":"233","front":"IM secondaire : première étape thérapeutique ?","back":"**Traiter l'insuffisance cardiaque** (médicaments, **resynchronisation si QRS larges**) ; puis intervention plutôt **percutanée** si échec.","prio":"P1","sec":"s8"},{"id":"fc-233-3b2cbb","poly":"cardio","fiche":"233","front":"Resynchronisation cardiaque : critères (item 234) ?","back":"IC NYHA II-IV, **FEVG ≤ 35 %** et **QRS ≥ 130 ms**.","prio":"P2","sec":"s8"},{"id":"fc-233-8c3b6b","poly":"cardio","fiche":"233","front":"Plastie mitrale : avantages ?","back":"Respecte l'appareil sous-valvulaire, moindre morbimortalité, moindre risque d'endocardite, **pas d'anticoagulant** au long cours.","prio":"P2","sec":"s8"},{"id":"fc-233-7553b8","poly":"cardio","fiche":"233","front":"Plastie mitrale : limites ?","back":"**Léger risque de récidive** ; chirurgien expérimenté ; pas toujours faisable.","prio":"P3","sec":"s8"},{"id":"fc-233-956b15","poly":"cardio","fiche":"233","front":"IM : prothèse mécanique pour qui ?","back":"Plutôt **< 65 ans**, ou anticoagulant déjà nécessaire (**FA**).","prio":"P2","sec":"s8"},{"id":"fc-233-830627","poly":"cardio","fiche":"233","front":"IM : bioprothèse pour qui ?","back":"Plutôt **> 70 ans**, **CI aux anticoagulants**, **désir de grossesse**.","prio":"P2","sec":"s8"},{"id":"fc-233-ea8c73","poly":"cardio","fiche":"233","front":"IM primaire en OAP : traitement médical ?","back":"**Furosémide IV** 1 mg/kg + **trinitrine IV** 1 mg/h si PAS ≥ 110 mmHg.","prio":"P2","sec":"s8"},{"id":"fc-233-491e3e","poly":"cardio","fiche":"233","front":"IM + FA sur valve native sans RM : anticoagulant ?","back":"**AOD à privilégier** sur les AVK, selon le CHA₂DS₂-VA.","prio":"P2","sec":"s8"},{"id":"fc-233-4c82d0","poly":"cardio","fiche":"233","front":"Prothèse mécanique mitrale : INR cible (item 153) ?","back":"**3,0 à 4,0** selon le risque thrombotique de la prothèse (position mitrale = facteur de risque).","prio":"P3","sec":"s8"},{"id":"fc-233-076a10","poly":"cardio","fiche":"233","front":"Bioprothèse ou plastie mitrale : antithrombotique ?","back":"**AVK 3 mois** puis rien (sauf autre indication, ex. FA).","prio":"P3","sec":"s8"},{"id":"fc-233-a6c3cf","poly":"cardio","fiche":"233","front":"Maladie de Marfan : but du bêtabloquant ?","back":"**Réduire le risque de dissection aortique**.","prio":"P3","sec":"s8"},{"id":"fc-233-5c470d","poly":"cardio","fiche":"233","front":"IM : 3 erreurs de prise en charge ?","back":"**Clip** d'emblée chez un opérable ; opérer d'emblée une **IM secondaire** ; se rassurer sur une **FE à 58 %**.","prio":"P2","sec":"s8"},{"id":"fc-233-655073","poly":"cardio","fiche":"233","front":"IA sévère symptomatique : indication opératoire ?","back":"**Formelle**.","prio":"P1","sec":"s9"},{"id":"fc-233-1894ba","poly":"cardio","fiche":"233","front":"IA sévère et autre chirurgie cardiaque prévue (pontage, aorte, valve) : opérer l'IA ?","back":"Oui : indication **formelle** à la traiter dans le même temps.","prio":"P2","sec":"s9"},{"id":"fc-233-f2aea3","poly":"cardio","fiche":"233","front":"IA : l'indication opératoire peut-elle reposer sur le seul diamètre aortique ?","back":"**Oui**, quel que soit le grade de la fuite.","prio":"P2","sec":"s9"},{"id":"fc-233-c21508","poly":"cardio","fiche":"233","front":"IA opérée : à partir de quel diamètre remplacer aussi l'aorte ?","back":"**≥ 45 mm**.","prio":"P3","sec":"s9"},{"id":"fc-233-4a620e","poly":"cardio","fiche":"233","front":"IA aiguë sévère avec insuffisance cardiaque : indication ?","back":"Chirurgie **formelle et urgente**.","prio":"P1","sec":"s9"},{"id":"fc-233-9d92bb","poly":"cardio","fiche":"233","front":"Facteurs de risque aortiques (seuils abaissés) ?","back":"ATCD de **dissection**, IA ou IM sévère, **désir de grossesse**, **HTA non contrôlée**, progression **> 3 mm/an**.","prio":"P3","sec":"s9"},{"id":"fc-233-becc17","poly":"cardio","fiche":"233","front":"IA isolée : traitement chirurgical ?","back":"**RVA** par prothèse mécanique ou biologique, choix discuté avec le patient.","prio":"P2","sec":"s9"},{"id":"fc-233-5f509e","poly":"cardio","fiche":"233","front":"IA : quand préférer une bioprothèse ?","back":"En général **après 60-65 ans** ou si **désir de grossesse** ; prévenir d'une **réopération vers 10 ans**.","prio":"P2","sec":"s9"},{"id":"fc-233-ee15ab","poly":"cardio","fiche":"233","front":"IA + dilatation aortique : intervention de Bentall ?","back":"**RVA + tube aortique** avec **réimplantation des coronaires**.","prio":"P2","sec":"s9"},{"id":"fc-233-97b612","poly":"cardio","fiche":"233","front":"TAVI dans l'IA ?","back":"**Pas un traitement de l'IA** ; exceptionnel (très haut risque, sans endocardite) ; risque de **migration**.","prio":"P2","sec":"s9"},{"id":"fc-233-d8c16a","poly":"cardio","fiche":"233","front":"IA sévère en insuffisance cardiaque : bêtabloquant ?","back":"**Contre-indiqué** classiquement : allonge la diastole et **aggrave la fuite**.","prio":"P1","sec":"s9"},{"id":"fc-233-ed07b8","poly":"cardio","fiche":"233","front":"IA sévère en IC en attente de chirurgie : traitement ?","back":"**Diurétiques**, éventuellement IEC ou autre vasodilatateur ; **ne retarde pas la chirurgie**.","prio":"P2","sec":"s9"},{"id":"fc-233-fa832c","poly":"cardio","fiche":"233","front":"IA symptomatique traitée seulement par les médicaments de l'IC : erreur ?","back":"**Oui**, notion inacceptable : l'amélioration ne doit pas retarder la chirurgie.","prio":"P1","sec":"s9"},{"id":"fc-233-3b5ddc","poly":"cardio","fiche":"233","front":"IA : existe-t-il un médicament efficace ?","back":"**Non**, aucun médicament n'a démontré de bénéfice.","prio":"P1","sec":"s9"},{"id":"fc-233-2c232c","poly":"cardio","fiche":"233","front":"IA modérée à sévère : IEC pour prévenir le remodelage ?","back":"**Non recommandés**.","prio":"P2","sec":"s9"},{"id":"fc-233-053ca9","poly":"cardio","fiche":"233","front":"Marfan avec dilatation aortique : traitement validé ?","back":"**Bêtabloquant** (ARA2 seulement si intolérance).","prio":"P2","sec":"s9"},{"id":"fc-233-f112f8","poly":"cardio","fiche":"233","front":"IA sévère et sport ?","back":"**Compétition contre-indiquée** ; loisir d'endurance modéré encouragé.","prio":"P3","sec":"s9"},{"id":"fc-233-4ff580","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : examen à ne jamais oublier à partir d'un certain âge ?","back":"**Imagerie des coronaires** (coronarographie ou coroscanner).","prio":"P1","sec":"s10"},{"id":"fc-233-d97cde","poly":"cardio","fiche":"233","front":"IA : indications de l'imagerie coronaire préopératoire ?","back":"**Homme > 40 ans**, **femme > 50 ans**, FDR, coroscanner anormal ou non concluant.","prio":"P3","sec":"s10"},{"id":"fc-233-8624cb","poly":"cardio","fiche":"233","front":"Bicuspidie avant chirurgie : quoi mesurer ?","back":"La **taille de l'aorte** (geste associé ?).","prio":"P1","sec":"s10"},{"id":"fc-233-388ee6","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : examen vasculaire pour tous ?","back":"**Échodoppler des troncs supra-aortiques**.","prio":"P2","sec":"s10"},{"id":"fc-233-accb24","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : recherche de foyers infectieux ?","back":"Foyers **ORL et dentaires** : radiographie des sinus, **panoramique dentaire**, traitement des foyers.","prio":"P1","sec":"s10"},{"id":"fc-233-f81c58","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : autres éléments ?","back":"**Comorbidités** (fonction rénale, poumon) ; **avis gériatrique** chez le sujet très âgé.","prio":"P2","sec":"s10"},{"id":"fc-233-6a720f","poly":"cardio","fiche":"233","front":"Bilan préopératoire valvulaire : buts ?","back":"**Évaluer le risque opératoire** et préciser le geste (pontage, aorte, tricuspide ?).","prio":"P2","sec":"s10"},{"id":"fc-233-a4bd9a","poly":"cardio","fiche":"233","front":"IM aiguë : tableau clinique ?","back":"**Urgence vitale** : OAP (parfois **unilatéral**), choc.","prio":"P1","sec":"s11"},{"id":"fc-233-d5f1c3","poly":"cardio","fiche":"233","front":"IM aiguë lors d'un SCA : place dans les causes de décompensation ?","back":"Cause **mécanique** (« M » de **CHAMPIT**) ; rupture ou dysfonction de pilier.","prio":"P2","sec":"s11"},{"id":"fc-233-adb1b4","poly":"cardio","fiche":"233","front":"OAP : mesures générales ?","back":"Position **assise**, voie veineuse, monitorage, ECG ; morphine non systématique ; **CPAP** si échec ; intubation si épuisement.","prio":"P2","sec":"s11"},{"id":"fc-233-9e8f6e","poly":"cardio","fiche":"233","front":"OAP : critères d'échec justifiant la CPAP ?","back":"**FR > 25/min**, **SaO₂ < 90 %**.","prio":"P3","sec":"s11"},{"id":"fc-233-c3a9a9","poly":"cardio","fiche":"233","front":"Choc cardiogénique : définition et traitement ?","back":"**PA < 90 mmHg + hypoperfusion** : **inotropes** (dobutamine), sonde urinaire, PA invasive ; assistance (ECMO) si échec.","prio":"P2","sec":"s11"},{"id":"fc-233-bf99d4","poly":"cardio","fiche":"233","front":"IM aiguë mal tolérée : traitement définitif ?","back":"**Chirurgie urgente** après traitement de l'OAP ou du choc.","prio":"P1","sec":"s11"},{"id":"fc-233-2031a6","poly":"cardio","fiche":"233","front":"IM aiguë : oxygénothérapie, quand et quel objectif ?","back":"Si **SaO₂ < 90 %** ; objectif **> 90 %** (prudence si risque d'hypercapnie).","prio":"P2","sec":"s11"},{"id":"fc-233-3ef0f2","poly":"cardio","fiche":"233","front":"Choc cardiogénique chez un patient sous bêtabloquant : quel inotrope à la place de la dobutamine ?","back":"**Milrinone** ou **énoximone**.","prio":"P3","sec":"s11"},{"id":"fc-233-08f2ee","poly":"cardio","fiche":"233","front":"IA aiguë : délai chirurgical selon la cause ?","back":"**Urgente** si IC ou dissection ; un peu **différée** possible si endocardite ou traumatisme selon la tolérance.","prio":"P2","sec":"s11"},{"id":"fc-233-a1017b","poly":"cardio","fiche":"233","front":"Endocardite avec IA : indications chirurgicales discutées ?","back":"**Sepsis non maîtrisé**, **insuffisance cardiaque**, **risque embolique majeur** (grosses végétations).","prio":"P3","sec":"s11"},{"id":"fc-233-c74588","poly":"cardio","fiche":"233","front":"RA : rythme du suivi ?","back":"**Suivi annuel** par le spécialiste ; réadresser si souffle modifié ou nouveaux symptômes.","prio":"P1","sec":"s12"},{"id":"fc-233-5ecd6d","poly":"cardio","fiche":"233","front":"IM significative asymptomatique : suivi ?","back":"Au moins une **ETT annuelle**.","prio":"P1","sec":"s12"},{"id":"fc-233-6ea638","poly":"cardio","fiche":"233","front":"IA importante : rythme du suivi ?","back":"**Tous les 6 mois à 1 an**, par un **cardiologue**.","prio":"P1","sec":"s12"},{"id":"fc-233-ae1708","poly":"cardio","fiche":"233","front":"IA modérée à moyenne : rythme du suivi ?","back":"**Tous les 2 à 3 ans** (IA sévère : 1 à 2 fois/an).","prio":"P3","sec":"s12"},{"id":"fc-233-827cb3","poly":"cardio","fiche":"233","front":"Aorte dilatée : rythme du suivi ?","back":"Écho **chaque année** ; IRM (plutôt) ou scanner de temps en temps.","prio":"P3","sec":"s12"},{"id":"fc-233-ee8b48","poly":"cardio","fiche":"233","front":"Porteur de prothèse : dyspnée ou récidive d'IC, quoi suspecter ?","back":"Une **dysfonction de prothèse**.","prio":"P1","sec":"s12"},{"id":"fc-233-dbabce","poly":"cardio","fiche":"233","front":"Porteur de prothèse : éléments de chaque consultation ?","back":"Symptômes, **auscultation de la prothèse**, **fièvre** ou foyer infectieux, signes ischémiques ou hémorragiques, suivi dentaire.","prio":"P2","sec":"s12"},{"id":"fc-233-9f8547","poly":"cardio","fiche":"233","front":"Après remplacement valvulaire : réadaptation cardiaque ?","back":"Vers **J8**, pendant **3-4 semaines**.","prio":"P3","sec":"s12"},{"id":"fc-233-285ec5","poly":"cardio","fiche":"233","front":"Après remplacement valvulaire : quand l'ETT de référence ?","back":"Au **2e-4e mois** (après une ETT postopératoire précoce).","prio":"P3","sec":"s12"},{"id":"fc-233-335575","poly":"cardio","fiche":"233","front":"Rythme des ETT : prothèse mécanique ou bioprothèse ?","back":"Mécanique : **tous les 1-2 ans** ; bioprothèse : **3 mois, 1 an puis chaque année**.","prio":"P3","sec":"s12"},{"id":"fc-233-a7d505","poly":"cardio","fiche":"233","front":"IA : erreur après régression des signes d'IC sous diurétiques ?","back":"**Repousser la chirurgie** : le remodelage du VG peut persister après remplacement.","prio":"P2","sec":"s12"},{"id":"fc-233-b52581","poly":"cardio","fiche":"233","front":"Patient valvulaire : 2 messages d'éducation ?","back":"**Prévention de l'endocardite** ; **consultation urgente** si symptômes d'effort.","prio":"P1","sec":"s13"},{"id":"fc-233-8ffc34","poly":"cardio","fiche":"233","front":"Fièvre chez un valvulaire : quoi évoquer ?","back":"**Endocardite infectieuse**.","prio":"P1","sec":"s13"},{"id":"fc-233-87a48e","poly":"cardio","fiche":"233","front":"Valvulopathie : quand adresser au spécialiste ?","back":"**Symptômes**, souffle modifié, **suivi annuel** ; une **IA sévère** même asymptomatique.","prio":"P1","sec":"s13"},{"id":"fc-233-d8bd12","poly":"cardio","fiche":"233","front":"Valve native (IM, IA, RA) : antibioprophylaxie avant soin dentaire ?","back":"**Non** (pas de prescription systématique) ; hygiène buccodentaire et cutanée.","prio":"P1","sec":"s13"},{"id":"fc-233-4fd58d","poly":"cardio","fiche":"233","front":"Valvulopathie native : mesures préventives de l'endocardite ?","back":"Hygiène buccodentaire, **dentiste 1 fois/an**, désinfection des plaies, consulter vite si fièvre, **pas d'automédication antibiotique**.","prio":"P2","sec":"s13"},{"id":"fc-233-9eb383","poly":"cardio","fiche":"233","front":"Indications de l'antibioprophylaxie de l'endocardite ?","back":"**Prothèse valvulaire** (TAVI compris) ou matériel de réparation, **antécédent d'endocardite**, **cardiopathie cyanogène**.","prio":"P1","sec":"s13"},{"id":"fc-233-2bdaca","poly":"cardio","fiche":"233","front":"Porteur de prothèse : documents à remettre ?","back":"**Carte de porteur de prothèse**, carnet d'anticoagulant (INR cible), carte d'antibioprophylaxie.","prio":"P2","sec":"s13"},{"id":"fc-233-0827fe","poly":"cardio","fiche":"233","front":"Porteur de prothèse : fréquence du suivi dentaire ?","back":"**Au moins 2 fois/an**.","prio":"P2","sec":"s13"},{"id":"fc-233-b00bcc","poly":"cardio","fiche":"233","front":"Maladie de Marfan : mesure familiale ?","back":"**Dépistage des apparentés du 1er degré**.","prio":"P1","sec":"s13"},{"id":"fc-233-aef3ec","poly":"cardio","fiche":"233","front":"Bicuspidie avec IA : taux de récurrence familiale ?","back":"**10 %** → dépistage familial proposé.","prio":"P3","sec":"s13"},{"id":"fc-233-829395","poly":"cardio","fiche":"233","front":"IA : 3 notions inacceptables ?","back":"Antibiotiques **systématiques** avant tout soin dentaire ; ne pas expliquer la prophylaxie ; ne pas évoquer un **Marfan** devant une IA annuloectasiante.","prio":"P1","sec":"s13"},{"id":"fc-233-44fdd6","poly":"cardio","fiche":"233","front":"IA aiguë : évolution et risques ?","back":"Évolution **rapide** ; risque d'**OAP**, voire de **mort subite** → chirurgie précoce habituelle.","prio":"P2","sec":"s5"},{"id":"fc-233-644857","poly":"cardio","fiche":"233","front":"IA sur prothèse : 2 types et leurs causes ?","back":"**Paraprothétique** (désinsertion septique ou aseptique) ; **intraprothétique** (thrombus, endocardite, dégénérescence).","prio":"P3","sec":"s2"},{"id":"fc-233-97895e","poly":"cardio","fiche":"233","front":"IA : rythme de l'examen dentaire recommandé ?","back":"**Tous les 6 mois** (2 fois par an), avec une bonne hygiène buccodentaire.","prio":"P3","sec":"s13"},{"id":"fc-234-41da80","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : définition physiopathologique ?","back":"Le cœur ne délivre plus un **débit adapté** aux besoins et/ou ne fonctionne qu'avec des **pressions de remplissage anormalement hautes**.","prio":"P1","sec":"s1"},{"id":"fc-234-c5bd0a","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : définition clinique (3 éléments) ?","back":"**Symptômes** (dyspnée, œdèmes, fatigue) + **signes** (tachycardie, crépitants, turgescence jugulaire) + **dysfonction cardiaque** (structure ou fonction).","prio":"P1","sec":"s1"},{"id":"fc-234-49142b","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : origines possibles de la dysfonction ?","back":"**Myocarde**, **valves**, **péricarde**, trouble du **rythme** ou de la **conduction**.","prio":"P2","sec":"s1"},{"id":"fc-234-799a31","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : pourquoi le diagnostic clinique est-il parfois difficile ?","back":"Symptômes **peu spécifiques**, signes **peu sensibles** (la rétention hydrosodée disparaît vite sous traitement).","prio":"P2","sec":"s1"},{"id":"fc-234-9bd9ee","poly":"cardio","fiche":"234","front":"Dysfonction VG systolique asymptomatique : intérêt de la dépister ?","back":"**Traiter tôt** et améliorer le pronostic.","prio":"P2","sec":"s1"},{"id":"fc-234-53c901","poly":"cardio","fiche":"234","front":"IC à FE diminuée : seuil de FEVG ?","back":"**FEVG ≤ 40 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-d0e5fd","poly":"cardio","fiche":"234","front":"IC à FE légèrement diminuée : seuil de FEVG ?","back":"**FEVG 41 à 49 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-86cab7","poly":"cardio","fiche":"234","front":"IC à FE préservée : seuil de FEVG ?","back":"**FEVG ≥ 50 %**.","prio":"P1","sec":"s1"},{"id":"fc-234-3cf582","poly":"cardio","fiche":"234","front":"IC à FE préservée : fréquence et terrain ?","back":"**Au moins 50 %** des IC ; surtout la **femme** et le **sujet âgé**.","prio":"P1","sec":"s1"},{"id":"fc-234-8ea052","poly":"cardio","fiche":"234","front":"IC à FE légèrement diminuée : traitement ?","back":"Mêmes traitements que l'IC à FE diminuée, mais niveau de recommandation **IIb, C** (et non I, A).","prio":"P2","sec":"s1"},{"id":"fc-234-ba5464","poly":"cardio","fiche":"234","front":"IC aiguë : définition ?","back":"Symptômes et signes d'apparition **généralement rapide** (de novo ou cardiopathie connue) : **congestion** et/ou **bas débit** ; le plus souvent hospitalisation pour traitement **IV**.","prio":"P1","sec":"s1"},{"id":"fc-234-a93859","poly":"cardio","fiche":"234","front":"IC chronique : définition ?","back":"Patient **hors décompensation**, ambulatoire, sous traitement **oral**.","prio":"P2","sec":"s1"},{"id":"fc-234-7a0094","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : prévalence ?","back":"**1 à 2 %** de la population, croissante avec l'âge.","prio":"P2","sec":"s1"},{"id":"fc-234-2a5c1c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : âge moyen au diagnostic ?","back":"**75 à 80 ans** en Europe (78 ans dans les points clés).","prio":"P3","sec":"s1"},{"id":"fc-234-727424","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : mortalité à 5 ans ?","back":"Environ **50 %**.","prio":"P2","sec":"s1"},{"id":"fc-234-309f0c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : évolution de la prévalence et de l'incidence ?","back":"**Prévalence en hausse** (vieillissement, meilleure prise en charge) ; **incidence standardisée sur l'âge en baisse**.","prio":"P3","sec":"s1"},{"id":"fc-234-1dd34f","poly":"cardio","fiche":"234","front":"Examen clinique pauvre : élimine-t-il une IC ?","back":"**Non** : chez un patient traité, les signes congestifs peuvent avoir disparu.","prio":"P1","sec":"s1"},{"id":"fc-234-7002c8","poly":"cardio","fiche":"234","front":"Débit cardiaque : formule ?","back":"**DC = VES × FC**.","prio":"P2","sec":"s2"},{"id":"fc-234-436e67","poly":"cardio","fiche":"234","front":"Fraction d'éjection : formule ?","back":"**FE = VES / VTD = (VTD − VTS) / VTD**.","prio":"P2","sec":"s2"},{"id":"fc-234-0ddea9","poly":"cardio","fiche":"234","front":"VES : 3 déterminants ?","back":"**Précharge**, **postcharge**, **contractilité**.","prio":"P3","sec":"s2"},{"id":"fc-234-d8982b","poly":"cardio","fiche":"234","front":"IC à FE préservée : mécanisme ?","back":"VG qui se vide bien mais **se remplit mal** : parois épaissies, fibreuses, **rigides** ; cavité en général non dilatée.","prio":"P2","sec":"s2"},{"id":"fc-234-00848a","poly":"cardio","fiche":"234","front":"IC à FE préservée : facteurs associés ?","back":"**HTA** et **obésité** ; sujet âgé, femme.","prio":"P3","sec":"s2"},{"id":"fc-234-18774d","poly":"cardio","fiche":"234","front":"OAP cardiogénique : mécanisme ?","back":"Pression capillaire pulmonaire élevée (en général **≥ 25 mmHg**) → **transsudat** vers les alvéoles.","prio":"P1","sec":"s2"},{"id":"fc-234-885550","poly":"cardio","fiche":"234","front":"Œdème pulmonaire lésionnel : mécanisme ?","back":"Lésion de la **membrane alvéolocapillaire** (causes nombreuses) : œdème **non cardiogénique**.","prio":"P2","sec":"s2"},{"id":"fc-234-00ef68","poly":"cardio","fiche":"234","front":"Mécanismes compensateurs de l'IC : citer ?","back":"**Dilatation** VG, **hypertrophie**, loi de **Starling**, **tachycardie**, **vasoconstriction**, **rétention hydrosodée**, **activation neurohormonale**.","prio":"P2","sec":"s2"},{"id":"fc-234-18b82a","poly":"cardio","fiche":"234","front":"Dilatation ventriculaire compensatrice : bénéfice et prix ?","back":"Maintient le **VES** malgré une FE basse ; mais **contrainte pariétale** accrue.","prio":"P3","sec":"s2"},{"id":"fc-234-d29488","poly":"cardio","fiche":"234","front":"Hypertrophie concentrique : loi en jeu ?","back":"**Laplace** : contrainte = pression × rayon / épaisseur.","prio":"P3","sec":"s2"},{"id":"fc-234-679dec","poly":"cardio","fiche":"234","front":"Loi de Starling : principe ?","back":"Plus les fibres sont étirées par la précharge, plus l'**inotropie** augmente (jusqu'à une limite).","prio":"P3","sec":"s2"},{"id":"fc-234-cc9450","poly":"cardio","fiche":"234","front":"Rétention hydrosodée de l'IC : bénéfice et prix ?","back":"Augmente volume et précharge ; prix : **signes congestifs** (œdèmes, épanchements).","prio":"P3","sec":"s2"},{"id":"fc-234-2f90f7","poly":"cardio","fiche":"234","front":"Activation neurohormonale : effets délétères ?","back":"Travail cardiaque accru, effets **proarythmiques**, **toxicité des catécholamines** sur les myocytes.","prio":"P3","sec":"s2"},{"id":"fc-234-998fca","poly":"cardio","fiche":"234","front":"Désynchronisation ventriculaire : cause typique ?","back":"Trouble de conduction, typiquement le **BBG** : paroi latérale qui se contracte **en retard** → peut aggraver l'IC.","prio":"P2","sec":"s2"},{"id":"fc-234-0f0968","poly":"cardio","fiche":"234","front":"FA dans l'IC : conséquences ?","back":"Perte de la systole atriale (aggrave **souvent** l'IC) et risque accru d'**AVC**.","prio":"P2","sec":"s2"},{"id":"fc-234-0439c3","poly":"cardio","fiche":"234","front":"IC : cause de la plupart des morts subites ?","back":"**TV/FV** (d'où le défibrillateur implantable).","prio":"P2","sec":"s2"},{"id":"fc-234-9fb469","poly":"cardio","fiche":"234","front":"Anciens noms des IC à FE diminuée et préservée ?","back":"IC **systolique** (FE diminuée) et IC **diastolique** (FE préservée).","prio":"P3","sec":"s2"},{"id":"fc-234-df85e5","poly":"cardio","fiche":"234","front":"IC droite : cause la plus fréquente ?","back":"L'**IC gauche** (hypertension pulmonaire).","prio":"P2","sec":"s2"},{"id":"fc-234-f1c785","poly":"cardio","fiche":"234","front":"Dyspnée d'effort dans l'IC : valeur ?","back":"Fréquente, souvent révélatrice, **peu spécifique** ; reflète la sévérité (**NYHA**).","prio":"P2","sec":"s3"},{"id":"fc-234-2a80e1","poly":"cardio","fiche":"234","front":"IC : 2 symptômes plus spécifiques que la dyspnée d'effort ?","back":"**Orthopnée** et **dyspnée paroxystique nocturne**.","prio":"P1","sec":"s3"},{"id":"fc-234-ee7a72","poly":"cardio","fiche":"234","front":"Orthopnée : définition et mécanisme ?","back":"Dyspnée en **décubitus** (dort tête relevée) ; redistribution du sang vers le thorax → pression capillaire en hausse.","prio":"P2","sec":"s3"},{"id":"fc-234-ea15fe","poly":"cardio","fiche":"234","front":"IC : signes trompeurs faisant penser au poumon ?","back":"**Asthme cardiaque** (bradypnée expiratoire sifflante), **toux** d'effort ou de décubitus, **hémoptysies**.","prio":"P1","sec":"s3"},{"id":"fc-234-7547b0","poly":"cardio","fiche":"234","front":"Subœdème pulmonaire : définition ?","back":"Crise de dyspnée de repos (OAP) qui **cède spontanément**.","prio":"P2","sec":"s3"},{"id":"fc-234-11e8fd","poly":"cardio","fiche":"234","front":"NYHA II : définition ?","back":"Gêne pour des **efforts importants** : marche rapide, en côte, escaliers **≥ 2 étages**.","prio":"P1","sec":"s3"},{"id":"fc-234-8886b1","poly":"cardio","fiche":"234","front":"NYHA III : définition ?","back":"Gêne pour des **efforts peu intenses** : marche en terrain plat, escaliers **< 2 étages**.","prio":"P1","sec":"s3"},{"id":"fc-234-083e8c","poly":"cardio","fiche":"234","front":"NYHA IV : définition ?","back":"Gêne **permanente au repos** ou pour des efforts minimes (s'habiller, se laver).","prio":"P1","sec":"s3"},{"id":"fc-234-7a1ce6","poly":"cardio","fiche":"234","front":"NYHA I : définition ?","back":"**Aucune gêne** pour les efforts habituels.","prio":"P2","sec":"s3"},{"id":"fc-234-e54be3","poly":"cardio","fiche":"234","front":"IC sévère : signes ?","back":"Respiration de **Cheyne-Stokes**, **confusion** (bas débit cérébral), troubles digestifs.","prio":"P2","sec":"s3"},{"id":"fc-234-07690c","poly":"cardio","fiche":"234","front":"IC droite : symptôme digestif ?","back":"**Hépatalgie** (hypocondre droit), d'abord à l'effort puis au repos.","prio":"P2","sec":"s3"},{"id":"fc-234-fa3033","poly":"cardio","fiche":"234","front":"IC : signes cardiaques à l'examen ?","back":"Choc de pointe dévié vers l'aisselle, tachycardie ou rythme irrégulier, **galop B3**, éclat de B2 pulmonaire, souffle d'IM ou d'IT.","prio":"P2","sec":"s3"},{"id":"fc-234-53b9a4","poly":"cardio","fiche":"234","front":"IC : épanchement pleural, nature à la ponction ?","back":"**Transsudat** (protides **< 30 g/L**).","prio":"P2","sec":"s3"},{"id":"fc-234-32693b","poly":"cardio","fiche":"234","front":"IC : seuil de PAS signant la gravité ?","back":"**PAS < 100 mmHg**.","prio":"P1","sec":"s3"},{"id":"fc-234-a583ef","poly":"cardio","fiche":"234","front":"OAP avec PA élevée : possible ?","back":"**Oui** : **OAP hypertensif**.","prio":"P2","sec":"s3"},{"id":"fc-234-29e183","poly":"cardio","fiche":"234","front":"IC droite : signes périphériques ?","back":"**TRHOA** : Turgescence jugulaire, Reflux hépatojugulaire, Hépatomégalie, Œdèmes, Ascite.","prio":"P1","sec":"s3"},{"id":"fc-234-99659d","poly":"cardio","fiche":"234","front":"IC droite : signe très spécifique ?","back":"**Turgescence jugulaire** (patient demi-assis).","prio":"P2","sec":"s3"},{"id":"fc-234-7155d8","poly":"cardio","fiche":"234","front":"Œdèmes de l'IC : caractéristiques ?","back":"**Mous, blancs, indolores**, prenant le **godet**, **déclives** (jambes, lombes si alité).","prio":"P2","sec":"s3"},{"id":"fc-234-cd68c0","poly":"cardio","fiche":"234","front":"IC à un stade très avancé : signes ?","back":"Pouls alternant, oligurie, **cachexie**, Cheyne-Stokes.","prio":"P3","sec":"s3"},{"id":"fc-234-79bcc3","poly":"cardio","fiche":"234","front":"IC hors poussée sous traitement : signification de signes physiques présents ?","back":"Élément de **gravité** (examen souvent pauvre).","prio":"P2","sec":"s3"},{"id":"fc-234-0e27e9","poly":"cardio","fiche":"234","front":"IC : rôle de l'ECG ?","back":"Peu utile au diagnostic positif ; oriente vers une **cause** (onde Q, trouble du rythme, hypertrophie).","prio":"P2","sec":"s4"},{"id":"fc-234-bae4a1","poly":"cardio","fiche":"234","front":"IC : anomalie ECG à repérer pour le traitement ?","back":"**Bloc de branche**, surtout **gauche** (QRS > 120 ms) → discuter **resynchronisation**.","prio":"P1","sec":"s4"},{"id":"fc-234-d949e4","poly":"cardio","fiche":"234","front":"Radiographie thoracique dans la dyspnée aiguë : indication ?","back":"**Toujours** faite ; indispensable pour le retentissement pleuropulmonaire.","prio":"P2","sec":"s4"},{"id":"fc-234-d33970","poly":"cardio","fiche":"234","front":"BNP/NT-proBNP : origine et atout principal ?","back":"Dosés en **1re intention** ; libérés par les **myocytes étirés** ; excellente **valeur prédictive négative**.","prio":"P1","sec":"s4"},{"id":"fc-234-02584a","poly":"cardio","fiche":"234","front":"IC : examen clé indispensable ?","back":"**ETT couplée au doppler** : type d'IC (FEVG), cause, retentissement, orientation thérapeutique.","prio":"P1","sec":"s4"},{"id":"fc-234-62735e","poly":"cardio","fiche":"234","front":"Radiographie : seuil de cardiomégalie ?","back":"**Rapport cardiothoracique > 0,5** (son absence n'écarte pas l'IC).","prio":"P2","sec":"s4"},{"id":"fc-234-a9aed2","poly":"cardio","fiche":"234","front":"Radiographie : 3 stades de la stase pulmonaire ?","back":"**Redistribution** vers les sommets → **œdème interstitiel** (Kerley) → **œdème alvéolaire** (ailes de papillon).","prio":"P2","sec":"s4"},{"id":"fc-234-3f9521","poly":"cardio","fiche":"234","front":"Œdème interstitiel radiologique : signes ?","back":"**Lignes B de Kerley**, hiles flous, images réticulonodulaires des bases.","prio":"P3","sec":"s4"},{"id":"fc-234-3fe409","poly":"cardio","fiche":"234","front":"Dyspnée aiguë : seuils BNP/NT-proBNP sous lesquels l'IC est très improbable ?","back":"**BNP < 100 pg/mL** ; **NT-proBNP < 300 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-234-d07d10","poly":"cardio","fiche":"234","front":"Présentation non aiguë : seuils BNP/NT-proBNP sous lesquels l'IC est très improbable ?","back":"**BNP < 35 pg/mL** ; **NT-proBNP < 125 pg/mL**.","prio":"P1","sec":"s4"},{"id":"fc-234-3e6053","poly":"cardio","fiche":"234","front":"Hors urgence : stratégie diagnostique (ESC 2021) ?","back":"Doser **BNP/NT-proBNP** ; si ≥ seuils (ou forte suspicion, dosage indisponible) → **échocardiographie**.","prio":"P2","sec":"s4"},{"id":"fc-234-7273af","poly":"cardio","fiche":"234","front":"BNP en faveur d'une origine cardiaque d'une dyspnée aiguë ?","back":"**BNP > 300 pg/mL**.","prio":"P3","sec":"s4"},{"id":"fc-234-897304","poly":"cardio","fiche":"234","front":"NT-proBNP en faveur d'une origine cardiaque selon l'âge ?","back":"**> 450** pg/mL avant 50 ans, **> 900** de 50 à 75 ans, **> 1 800** après 75 ans.","prio":"P3","sec":"s4"},{"id":"fc-234-a8b59d","poly":"cardio","fiche":"234","front":"Peptides natriurétiques : facteurs qui les augmentent ou les diminuent ?","back":"Augmentent : **âge**, **insuffisance rénale**, **FA** ; diminuent : **obésité**.","prio":"P2","sec":"s4"},{"id":"fc-234-cfd0ae","poly":"cardio","fiche":"234","front":"BNP en zone grise : interprétation ?","back":"Toujours tenir compte de la **clinique**.","prio":"P3","sec":"s4"},{"id":"fc-234-096709","poly":"cardio","fiche":"234","front":"ETT : orientation étiologique selon l'aspect ?","back":"Trouble segmentaire → **ischémie** ; hypertrophie → **HTA** ; hypertrophie asymétrique septale → **CMH**.","prio":"P3","sec":"s4"},{"id":"fc-234-57ac5f","poly":"cardio","fiche":"234","front":"IC : biologie standard (ESC 2021) ?","back":"Natrémie, kaliémie, créatinine, BNP, glycémie/HbA1c, lipides, bilan hépatique, **TSHus**, NFS, **ferritine** et saturation de la transferrine.","prio":"P3","sec":"s4"},{"id":"fc-234-505644","poly":"cardio","fiche":"234","front":"Coroscanner dans l'IC : quand le privilégier ?","back":"Probabilité coronaire **faible ou intermédiaire**, ou tests d'ischémie non concluants.","prio":"P3","sec":"s4"},{"id":"fc-234-99df79","poly":"cardio","fiche":"234","front":"Coronarographie normale + FEVG basse sans autre cause : diagnostic ?","back":"**Cardiomyopathie dilatée**.","prio":"P3","sec":"s4"},{"id":"fc-234-ce0794","poly":"cardio","fiche":"234","front":"IRM cardiaque dans l'IC : indications ?","back":"FE si peu échogène ; **myocardite**, DAVD, sarcoïdose, **amylose** ; séquelle d'infarctus, viabilité ; fibrose.","prio":"P3","sec":"s4"},{"id":"fc-234-3008f8","poly":"cardio","fiche":"234","front":"Scintigraphie au technétium : quelle indication dans l'IC ?","back":"**Amylose à transthyrétine**.","prio":"P3","sec":"s4"},{"id":"fc-234-8688c5","poly":"cardio","fiche":"234","front":"Épreuve d'effort avec VO₂ : intérêt ?","back":"Capacité d'effort objective ; pic de VO₂ très abaissé → discuter une **greffe**.","prio":"P3","sec":"s4"},{"id":"fc-234-233096","poly":"cardio","fiche":"234","front":"Cathétérisme droit : seuil de résistances pulmonaires contre-indiquant la greffe ?","back":"**> 5 unités Wood**.","prio":"P3","sec":"s4"},{"id":"fc-234-20d224","poly":"cardio","fiche":"234","front":"BNP bas au cours d'une dyspnée aiguë : conséquence ?","back":"**Douter** de l'origine cardiaque.","prio":"P2","sec":"s4"},{"id":"fc-234-f77f7c","poly":"cardio","fiche":"234","front":"Insuffisance cardiaque : première cause ?","back":"**Cardiopathie ischémique**.","prio":"P1","sec":"s5"},{"id":"fc-234-aa262a","poly":"cardio","fiche":"234","front":"IC ischémique sans infarctus : particularité ?","back":"FE éventuellement **réversible** après revascularisation (**viabilité**).","prio":"P2","sec":"s5"},{"id":"fc-234-0e983a","poly":"cardio","fiche":"234","front":"HTA et IC : mécanismes ?","back":"Hypertrophie + fibrose → dysfonction **diastolique** (IC à FE préservée du sujet âgé) ; maladie coronaire ; baisse de FE par postcharge élevée.","prio":"P2","sec":"s5"},{"id":"fc-234-b0762a","poly":"cardio","fiche":"234","front":"Cardiomyopathie dilatée : définition et place chez le jeune ?","back":"Dilatation + **baisse de la FEVG** ; **1re cause d'IC et de transplantation chez le sujet jeune**.","prio":"P1","sec":"s5"},{"id":"fc-234-82f895","poly":"cardio","fiche":"234","front":"CMD familiale : fréquence et transmission ?","back":"Environ **25 %** ; monogénique, le plus souvent **autosomique dominante**.","prio":"P2","sec":"s5"},{"id":"fc-234-531982","poly":"cardio","fiche":"234","front":"CMD : causes toxiques ?","back":"**Alcool**, **amphétamines**, **cocaïne**.","prio":"P2","sec":"s5"},{"id":"fc-234-acd647","poly":"cardio","fiche":"234","front":"CMD : causes infectieuses ?","back":"**Myocardites virales** (coxsackie, CMV, HHV-6, VIH) ou bactériennes (brucellose, borréliose) ; **Chagas**.","prio":"P3","sec":"s5"},{"id":"fc-234-efe564","poly":"cardio","fiche":"234","front":"CMD : causes auto-immunes ?","back":"**Sarcoïdose**, Churg et Strauss, sclérodermie, lupus.","prio":"P3","sec":"s5"},{"id":"fc-234-2a40d7","poly":"cardio","fiche":"234","front":"CMD : causes endocriniennes et nutritionnelles ?","back":"Dysthyroïdie, phéochromocytome, hypocalcémie ; carences en **carnitine**, **thiamine**, **sélénium**.","prio":"P3","sec":"s5"},{"id":"fc-234-a20f5a","poly":"cardio","fiche":"234","front":"CMD : causes médicamenteuses et autres ?","back":"Chloroquine, clozapine ; **anthracyclines**, **trastuzumab** ; **péripartum** ; **takotsubo**.","prio":"P2","sec":"s5"},{"id":"fc-234-1465da","poly":"cardio","fiche":"234","front":"Cardiomyopathie hypertrophique : caractéristiques ?","back":"Hypertrophie le plus souvent **asymétrique septale**, FE conservée ; obstruction sous-aortique dans ~**25 %** ; **autosomique dominante** (sarcomère).","prio":"P1","sec":"s5"},{"id":"fc-234-583808","poly":"cardio","fiche":"234","front":"CMH : place dans la mort subite ?","back":"**1re cause de mort subite chez le jeune athlète**.","prio":"P1","sec":"s5"},{"id":"fc-234-53a97c","poly":"cardio","fiche":"234","front":"Cardiomyopathie restrictive : cause la plus fréquente et pronostic ?","back":"**Amylose cardiaque** ; pronostic **en général sévère** dès les signes d'IC.","prio":"P2","sec":"s5"},{"id":"fc-234-62b236","poly":"cardio","fiche":"234","front":"Valvulopathie compliquée d'IC : signification ?","back":"**Tournant évolutif grave** → traitement radical souvent justifié.","prio":"P2","sec":"s5"},{"id":"fc-234-3ced5f","poly":"cardio","fiche":"234","front":"Valvulopathie pouvant donner un OAP avec VG normal ?","back":"Le **RM**.","prio":"P3","sec":"s5"},{"id":"fc-234-b21007","poly":"cardio","fiche":"234","front":"Tachycardiomyopathie : définition ?","back":"Altération de la FE due à une **FA rapide permanente et prolongée** ; traiter le trouble du rythme **guérit souvent** l'IC.","prio":"P2","sec":"s5"},{"id":"fc-234-89ebaa","poly":"cardio","fiche":"234","front":"IC : causes péricardiques ?","back":"Épanchement abondant, **tamponnade**, **péricardite chronique constrictive**.","prio":"P2","sec":"s5"},{"id":"fc-234-52895c","poly":"cardio","fiche":"234","front":"IC à débit augmenté : causes ?","back":"**Anémie**, **fistule artérioveineuse**, **hyperthyroïdie**, carence en **thiamine** (béribéri), Paget.","prio":"P2","sec":"s5"},{"id":"fc-234-1dcb33","poly":"cardio","fiche":"234","front":"IC droite isolée : causes pulmonaires et vasculaires ?","back":"**Cœur pulmonaire** (hypoxémie), **embolie pulmonaire** (aiguë ou séquelles), **HTAP**.","prio":"P2","sec":"s5"},{"id":"fc-234-9534d6","poly":"cardio","fiche":"234","front":"IC droite isolée : causes cardiaques ?","back":"**Infarctus du VD**, cardiomyopathie VD **arythmogène**, valvulopathie **tricuspide**, **péricardite constrictive**.","prio":"P2","sec":"s5"},{"id":"fc-234-a77407","poly":"cardio","fiche":"234","front":"IC à FEVG abaissée : quelle cause toujours éliminer ?","back":"Une origine **ischémique** (coronarographie, ou coroscanner chez le sujet jeune).","prio":"P1","sec":"s5"},{"id":"fc-234-6312e9","poly":"cardio","fiche":"234","front":"OAP cardiogénique : prise en charge ?","back":"**Immédiate** : les examens ne doivent **pas retarder** le traitement.","prio":"P1","sec":"s6"},{"id":"fc-234-a59726","poly":"cardio","fiche":"234","front":"OAP : tableau clinique ?","back":"Polypnée, **orthopnée** (reste assis), anxiété, sueurs, cyanose, expectoration **mousseuse saumonée**, tirage.","prio":"P1","sec":"s6"},{"id":"fc-234-dc7739","poly":"cardio","fiche":"234","front":"OAP : évolution des crépitants avec la sévérité ?","back":"De plus en plus haut dans les champs : « **marée montante** ».","prio":"P2","sec":"s6"},{"id":"fc-234-0e1539","poly":"cardio","fiche":"234","front":"OAP : troponine modérément élevée, signification ?","back":"Possible **sans SCA** ; n'affirme pas une maladie coronaire aiguë.","prio":"P2","sec":"s6"},{"id":"fc-234-6aa7c2","poly":"cardio","fiche":"234","front":"OAP : gaz du sang typiques ?","back":"**Hypoxie**, **hypocapnie**.","prio":"P3","sec":"s6"},{"id":"fc-234-c58d40","poly":"cardio","fiche":"234","front":"IC aiguë : premier facteur déclenchant à rechercher ?","back":"**Rupture** ou mauvaise observance du **traitement** ; **écarts de régime sans sel**.","prio":"P1","sec":"s6"},{"id":"fc-234-f1f3af","poly":"cardio","fiche":"234","front":"IC aiguë : autres facteurs déclenchants ?","back":"Infection, anémie, **FA**, poussée hypertensive, **SCA**, embolie pulmonaire, dysthyroïdie (amiodarone), iatrogénie.","prio":"P2","sec":"s6"},{"id":"fc-234-c4fa75","poly":"cardio","fiche":"234","front":"IC aiguë : médicaments déclenchants ?","back":"Antiarythmique **dépresseur** du cœur, **bêtabloquant**, **AINS**, **diltiazem/vérapamil**, excès de diurétiques ou vasodilatateurs.","prio":"P2","sec":"s6"},{"id":"fc-234-92b4a0","poly":"cardio","fiche":"234","front":"Choc cardiogénique : critère tensionnel ?","back":"**PAS < 90 mmHg**, ou chute de **> 30 mmHg**, pendant **au moins 30 min**.","prio":"P1","sec":"s6"},{"id":"fc-234-63a3b0","poly":"cardio","fiche":"234","front":"Choc cardiogénique : signes d'hypoperfusion ?","back":"Extrémités **froides, cyanosées, marbrées** ; **oligurie < 20 mL/h** ; sueurs ; **confusion**/agitation ; débit bas à l'écho.","prio":"P1","sec":"s6"},{"id":"fc-234-e53e63","poly":"cardio","fiche":"234","front":"Choc cardiogénique : moyen mnémotechnique de la fiche ?","back":"**PSTOC** : Pression effondrée, Sueurs, Troubles de perfusion, Oligurie, Conscience altérée.","prio":"P2","sec":"s6"},{"id":"fc-234-504fef","poly":"cardio","fiche":"234","front":"Choc cardiogénique : définition et pronostic ?","back":"Stade ultime de défaillance aiguë : chute du débit, **anoxie tissulaire** ; **mauvais pronostic**.","prio":"P2","sec":"s6"},{"id":"fc-234-ef0b3b","poly":"cardio","fiche":"234","front":"Choc cardiogénique : la PAS suffit-elle au diagnostic ?","back":"**Non** : hypotension + **hypoperfusion** + **bas débit**.","prio":"P2","sec":"s6"},{"id":"fc-234-fb921c","poly":"cardio","fiche":"234","front":"IC aiguë au cours d'un SCA : principe ?","back":"Traiter **à la fois** le SCA et la poussée.","prio":"P3","sec":"s6"},{"id":"fc-234-50ba35","poly":"cardio","fiche":"234","front":"Dyspnée aiguë : 4 diagnostics différentiels de l'OAP ?","back":"**PEBA** : Pneumopathie, Embolie pulmonaire, BPCO (exacerbation), Asthme.","prio":"P1","sec":"s7"},{"id":"fc-234-a6e01d","poly":"cardio","fiche":"234","front":"Pneumopathie vs OAP : arguments ?","back":"Tableau **infectieux**, crépitants **localisés**, opacité **systématisée**, BNP normal ou peu élevé.","prio":"P2","sec":"s7"},{"id":"fc-234-a15e18","poly":"cardio","fiche":"234","front":"Embolie pulmonaire vs OAP : argument auscultatoire ?","back":"Auscultation pulmonaire souvent **normale** (contexte favorisant).","prio":"P2","sec":"s7"},{"id":"fc-234-fede35","poly":"cardio","fiche":"234","front":"Asthme et BPCO vs OAP : arguments ?","back":"Antécédents ; **sibilants**, dyspnée expiratoire (asthme) ; ronchi, expectoration (BPCO).","prio":"P3","sec":"s7"},{"id":"fc-234-bbbbf9","poly":"cardio","fiche":"234","front":"OAP cardiogénique vs lésionnel : nature du liquide ?","back":"Cardiogénique = **transsudat** ; lésionnel = **exsudat**.","prio":"P1","sec":"s7"},{"id":"fc-234-f6fb5a","poly":"cardio","fiche":"234","front":"OAP au domicile : traitement par le médecin ?","back":"**Asseoir** ; **furosémide IV 1 mg/kg** (à refaire) ; **nitrés sublinguaux si PAS > 100 mmHg** ; Samu, hospitalisation.","prio":"P1","sec":"s8"},{"id":"fc-234-d4ec45","poly":"cardio","fiche":"234","front":"OAP : dose de furosémide ?","back":"**1 mg/kg IV**, puis adaptée à la diurèse.","prio":"P1","sec":"s8"},{"id":"fc-234-c03737","poly":"cardio","fiche":"234","front":"OAP à l'hôpital : trinitrine, dose et condition ?","back":"**1 mg/h IV**, adaptée à la PA, si **PAS ≥ 110 mmHg**.","prio":"P1","sec":"s8"},{"id":"fc-234-235b65","poly":"cardio","fiche":"234","front":"OAP : oxygénothérapie ?","back":"Si **SaO₂ < 90 %**, objectif **> 90 %** ; prudence si risque d'hypercapnie.","prio":"P1","sec":"s8"},{"id":"fc-234-d7738e","poly":"cardio","fiche":"234","front":"OAP : morphine ?","back":"**Pas systématique** : anxiété importante non contrôlée ou douleur thoracique.","prio":"P1","sec":"s8"},{"id":"fc-234-c489e3","poly":"cardio","fiche":"234","front":"OAP : traitement anticoagulant ?","back":"**HBPM préventive**, **systématique**.","prio":"P1","sec":"s8"},{"id":"fc-234-62a5a9","poly":"cardio","fiche":"234","front":"OAP ne répondant pas au traitement : conduite ?","back":"**CPAP** (FR > 25/min, SaO₂ < 90 %) ; si échec ou épuisement → **intubation**.","prio":"P1","sec":"s8"},{"id":"fc-234-c0b2bc","poly":"cardio","fiche":"234","front":"OAP à l'hôpital : voie veineuse et monitorage ?","back":"Voie veineuse avec **G5 %** ; monitorage FC, PA, oxymétrie, scope.","prio":"P2","sec":"s8"},{"id":"fc-234-0631f7","poly":"cardio","fiche":"234","front":"OAP : quelle cause rechercher systématiquement ?","back":"Une cause spécifique (**CHAMPIT**) et le **facteur déclenchant**.","prio":"P2","sec":"s8"},{"id":"fc-234-94038f","poly":"cardio","fiche":"234","front":"OAP sur FA rapide : traitement ajouté ?","back":"**Digoxine IV** (si kaliémie normale) + **anticoagulation efficace**.","prio":"P2","sec":"s8"},{"id":"fc-234-af0bb2","poly":"cardio","fiche":"234","front":"OAP hypertensif : traitements proposés ?","back":"**Trinitrine IV** ; l'item 234 cite aussi la **nicardipine IV 1 à 5 mg/h**.","prio":"P2","sec":"s8"},{"id":"fc-234-1dc173","poly":"cardio","fiche":"234","front":"Nicardipine dans l'OAP : quelle contradiction du Collège ?","back":"Proposée par l'item 234, mais dite **contre-indiquée dans l'IC** par l'item 224, qui préfère les **nitrés IV**.","prio":"P2","sec":"s8"},{"id":"fc-234-f4f0e9","poly":"cardio","fiche":"234","front":"OAP : introduction d'un bêtabloquant ?","back":"**Non** : l'introduire pendant la poussée est une **faute**.","prio":"P1","sec":"s8"},{"id":"fc-234-3ef061","poly":"cardio","fiche":"234","front":"OAP chez un patient déjà sous bêtabloquant ?","back":"Généralement **arrêté ou diminué**.","prio":"P2","sec":"s8"},{"id":"fc-234-d00233","poly":"cardio","fiche":"234","front":"OAP : quand instaurer IEC, ARA2 ou sacubitril/valsartan ?","back":"**Après** la poussée.","prio":"P2","sec":"s8"},{"id":"fc-234-992281","poly":"cardio","fiche":"234","front":"Après un OAP : étapes ?","back":"Bêtabloquant une fois **stabilisé** (avant la sortie possible) ; **ETT** ; recherche d'**ischémie** si FEVG basse ; éducation.","prio":"P2","sec":"s8"},{"id":"fc-234-ff66d6","poly":"cardio","fiche":"234","front":"Choc cardiogénique : inotrope de référence ?","back":"**Dobutamine** IV.","prio":"P2","sec":"s9"},{"id":"fc-234-a0af73","poly":"cardio","fiche":"234","front":"Choc cardiogénique sous bêtabloquant : quel inotrope ?","back":"**Inhibiteur des phosphodiestérases** : **milrinone** ou **énoximone**.","prio":"P2","sec":"s9"},{"id":"fc-234-fcc23e","poly":"cardio","fiche":"234","front":"Choc cardiogénique : surveillance invasive ?","back":"**Sonde urinaire** systématique ; **PA invasive** (cathéter radial).","prio":"P3","sec":"s9"},{"id":"fc-234-3b261b","poly":"cardio","fiche":"234","front":"Lévosimendan : mécanisme et indication ?","back":"**Sensibilisateur calcique** (inotrope + vasodilatateur) ; si **sevrage des inotropes impossible**.","prio":"P3","sec":"s9"},{"id":"fc-234-1ec872","poly":"cardio","fiche":"234","front":"Choc cardiogénique réfractaire : options ?","back":"**Assistance circulatoire** (ECMO, uni- ou biventriculaire), cœur artificiel, **greffe en urgence**.","prio":"P2","sec":"s9"},{"id":"fc-234-5c83cb","poly":"cardio","fiche":"234","front":"CHAMPIT : signification ?","back":"**C**oronarien (SCA), **H**ypertension, **A**rythmie, **M**écanique (rupture, CIV, IM aiguë), **P**ulmonaire (EP), **I**nfection, **T**amponnade.","prio":"P1","sec":"s9"},{"id":"fc-234-984516","poly":"cardio","fiche":"234","front":"Poussée d'IC sans OAP : hospitalisation systématique ?","back":"**Non** : parfois augmenter le diurétique oral suffit ; sinon **cure de diurétiques IV**.","prio":"P2","sec":"s9"},{"id":"fc-234-01503b","poly":"cardio","fiche":"234","front":"Poussée d'IC sans OAP : étapes ?","back":"Diurétique (oral ou IV), **rééquilibrer** le traitement oral, **chercher la cause**, puis éducation.","prio":"P2","sec":"s9"},{"id":"fc-234-fe7362","poly":"cardio","fiche":"234","front":"Décompensation chez un patient sous bêtabloquant (règle générale) ?","back":"**Ne pas arrêter** le bêtabloquant, sauf mauvaise réponse ou **choc cardiogénique**.","prio":"P1","sec":"s9"},{"id":"fc-234-2cdc25","poly":"cardio","fiche":"234","front":"Bêtabloquant après stabilisation : modalités ?","back":"Réintroduit puis augmenté par **paliers hebdomadaires** ; surveiller FC et PA.","prio":"P3","sec":"s9"},{"id":"fc-234-9346bc","poly":"cardio","fiche":"234","front":"Prévention de l'IC : principe ?","back":"Traiter **chaque cause** (HTA, valvulopathie, infarctus, FDR, toxiques, rythme) avant que le myocarde ne s'abîme.","prio":"P2","sec":"s10"},{"id":"fc-234-74974b","poly":"cardio","fiche":"234","front":"Infarctus : mesure préventive de l'IC ?","back":"**Reperfusion précoce** pour limiter la nécrose.","prio":"P2","sec":"s10"},{"id":"fc-234-527695","poly":"cardio","fiche":"234","front":"Diabétique à haut risque CV : antidiabétique à privilégier pour prévenir l'IC ?","back":"Une **gliflozine**.","prio":"P2","sec":"s10"},{"id":"fc-234-d24989","poly":"cardio","fiche":"234","front":"Chimiothérapies cardiotoxiques : mesure préventive ?","back":"**Surveiller la fonction cardiaque**.","prio":"P3","sec":"s10"},{"id":"fc-234-e25da1","poly":"cardio","fiche":"234","front":"IC : apport sodé maximal ?","back":"**5 à 6 g de sel/j**.","prio":"P1","sec":"s10"},{"id":"fc-234-4cd805","poly":"cardio","fiche":"234","front":"IC : conduite après un écart de régime salé ?","back":"**Augmenter le diurétique** le jour même, voire le lendemain.","prio":"P2","sec":"s10"},{"id":"fc-234-fb75ca","poly":"cardio","fiche":"234","front":"IC : prise de poids devant faire consulter ?","back":"**2 à 3 kg**, a fortiori brutale **en 2 à 3 jours**.","prio":"P1","sec":"s10"},{"id":"fc-234-576868","poly":"cardio","fiche":"234","front":"IC : signification d'un amaigrissement progressif sans œdème ?","back":"**Dénutrition** : signe de gravité, mauvais pronostic.","prio":"P2","sec":"s10"},{"id":"fc-234-8be15b","poly":"cardio","fiche":"234","front":"CMD avec consommation d'alcool excessive : conduite ?","back":"**Arrêt total** (régression partielle voire totale possible).","prio":"P2","sec":"s10"},{"id":"fc-234-d29d6f","poly":"cardio","fiche":"234","front":"IC : activité physique ?","back":"**Encouragée** hors décompensation ; **pas de repos strict** (le déconditionnement aggrave).","prio":"P2","sec":"s10"},{"id":"fc-234-b26db0","poly":"cardio","fiche":"234","front":"IC : restrictions professionnelles ?","back":"Proscrire efforts importants, emplois à risque (poids lourds, transports), horaires décalés.","prio":"P3","sec":"s10"},{"id":"fc-234-ca5ed5","poly":"cardio","fiche":"234","front":"IC : vaccinations recommandées ?","back":"**Antigrippale**, **anti-Covid-19**, **antipneumococcique**.","prio":"P2","sec":"s10"},{"id":"fc-234-ab4cac","poly":"cardio","fiche":"234","front":"IC : contraception ?","back":"Œstrogènes **minidosés** ou **DIU** (grossesse à risque).","prio":"P2","sec":"s10"},{"id":"fc-234-e54009","poly":"cardio","fiche":"234","front":"IC : réadaptation cardiaque ?","back":"**Recommandée** si possible : reprise de l'effort + éducation thérapeutique.","prio":"P2","sec":"s10"},{"id":"fc-234-3321c8","poly":"cardio","fiche":"234","front":"IC : notion inacceptable sur le régime ?","back":"**Oublier les conseils de régime pauvre en sel**.","prio":"P1","sec":"s10"},{"id":"fc-234-3221f0","poly":"cardio","fiche":"234","front":"IC : pourquoi prendre en charge les comorbidités ?","back":"Elles réduisent la tolérance des cardioprotecteurs et augmentent erreurs de prise et effets indésirables.","prio":"P2","sec":"s10"},{"id":"fc-234-74b677","poly":"cardio","fiche":"234","front":"IC à FE diminuée : 4 classes réduisant la mortalité ?","back":"**IEC** (ou sacubitril/valsartan, ARA2 si intolérance), **bêtabloquant**, **antialdostérone**, **gliflozine**.","prio":"P1","sec":"s11"},{"id":"fc-234-31bbde","poly":"cardio","fiche":"234","front":"IC à FE diminuée : classe ajoutée pour les signes congestifs ?","back":"**Diurétique de l'anse** (5e classe).","prio":"P1","sec":"s11"},{"id":"fc-234-591752","poly":"cardio","fiche":"234","front":"IC à FE diminuée : première étape avant les médicaments ?","back":"**Corriger une cause curable** (revascularisation, valve) ; éliminer une origine ischémique.","prio":"P2","sec":"s11"},{"id":"fc-234-719aae","poly":"cardio","fiche":"234","front":"IEC dans l'IC à FE diminuée : chez qui ?","back":"**Tous** les patients, **quelle que soit la classe NYHA** ; débuter faible, monter vers les doses des essais.","prio":"P1","sec":"s11"},{"id":"fc-234-1695a3","poly":"cardio","fiche":"234","front":"IEC dans l'IC : doses cibles des essais ?","back":"**Énalapril 20 mg**, **captopril 150 mg**, **ramipril 10 mg**.","prio":"P2","sec":"s11"},{"id":"fc-234-e89aec","poly":"cardio","fiche":"234","front":"IEC : contre-indications ?","back":"**Sténose bilatérale des artères rénales**, ATCD d'**angio-œdème**, **grossesse**, **hyperkaliémie**.","prio":"P2","sec":"s11"},{"id":"fc-234-e5b551","poly":"cardio","fiche":"234","front":"IEC : effets indésirables principaux dans l'IC ?","back":"**Hypotension**, **insuffisance rénale**.","prio":"P2","sec":"s11"},{"id":"fc-234-90b61d","poly":"cardio","fiche":"234","front":"ARA2 dans l'IC : place ?","back":"**Si intolérance aux IEC** ; mieux tolérés (moins de toux), efficacité proche.","prio":"P2","sec":"s11"},{"id":"fc-234-aef60d","poly":"cardio","fiche":"234","front":"Sacubitril/valsartan : mécanisme ?","back":"Bloque le récepteur **AT1** + inhibe la **néprilysine** (dégradation des peptides natriurétiques).","prio":"P2","sec":"s11"},{"id":"fc-234-8e0c89","poly":"cardio","fiche":"234","front":"Sacubitril/valsartan : place ?","back":"En 1re intention possible, ou **en remplacement de l'IEC** si symptômes persistants ; plus efficace que l'énalapril.","prio":"P2","sec":"s11"},{"id":"fc-234-1b4546","poly":"cardio","fiche":"234","front":"Bêtabloquant dans l'IC : conditions d'introduction ?","back":"Patient **stabilisé**, sans décompensation ; départ à **1/8e** de la dose max, paliers **hebdomadaires**.","prio":"P1","sec":"s11"},{"id":"fc-234-b27170","poly":"cardio","fiche":"234","front":"Bêtabloquants de l'IC : molécules ?","back":"**Carvédilol**, **bisoprolol**, métoprolol, nébivolol.","prio":"P2","sec":"s11"},{"id":"fc-234-aaec9a","poly":"cardio","fiche":"234","front":"Bisoprolol dans l'IC : dose initiale et cible ?","back":"**1,25 mg/j** → **10 mg/j** selon tolérance.","prio":"P3","sec":"s11"},{"id":"fc-234-39063a","poly":"cardio","fiche":"234","front":"Carvédilol dans l'IC : dose initiale et cible ?","back":"**3,125 mg × 2/j** → **25 mg × 2/j** selon tolérance.","prio":"P3","sec":"s11"},{"id":"fc-234-a40207","poly":"cardio","fiche":"234","front":"Bêtabloquant : contre-indications ?","back":"**Asthme** ou BPCO sévère, bradycardie ou hypotension symptomatique, **BAV 2 ou 3**.","prio":"P2","sec":"s11"},{"id":"fc-234-5ae699","poly":"cardio","fiche":"234","front":"Bêtabloquants dans l'IC : bénéfices ?","back":"Moins de symptômes, de décès, d'hospitalisations et de **morts subites**.","prio":"P2","sec":"s11"},{"id":"fc-234-559dc0","poly":"cardio","fiche":"234","front":"Antialdostérone dans l'IC à FE basse : indication ?","back":"Tous les patients en **NYHA II à IV**.","prio":"P1","sec":"s11"},{"id":"fc-234-c06bfc","poly":"cardio","fiche":"234","front":"Antialdostérones : molécules et contre-indications ?","back":"**Spironolactone**, **éplérénone** ; CI : **hyperkaliémie**, **insuffisance rénale**.","prio":"P2","sec":"s11"},{"id":"fc-234-b16e5f","poly":"cardio","fiche":"234","front":"Spironolactone : effets indésirables spécifiques ?","back":"**Gynécomastie**, **impuissance**.","prio":"P3","sec":"s11"},{"id":"fc-234-c44cbc","poly":"cardio","fiche":"234","front":"Gliflozine dans l'IC à FE diminuée : chez qui ?","back":"Patient **diabétique ou non**.","prio":"P1","sec":"s11"},{"id":"fc-234-e32203","poly":"cardio","fiche":"234","front":"Gliflozines : molécules et effets indésirables ?","back":"**Dapagliflozine**, **empagliflozine** ; infections génitales, **acidocétose** (surtout diabétique).","prio":"P2","sec":"s11"},{"id":"fc-234-199ad3","poly":"cardio","fiche":"234","front":"Diurétique de l'anse au long cours : dose ?","back":"**Dose minimale** contrôlant les œdèmes : de **20 mg/j** à 500 mg/j, voire 1 g/j de furosémide.","prio":"P2","sec":"s11"},{"id":"fc-234-980289","poly":"cardio","fiche":"234","front":"Diurétique thiazidique dans l'IC : place ?","back":"**En association** au furosémide en cas de **résistance** (formes graves).","prio":"P2","sec":"s11"},{"id":"fc-234-48ba91","poly":"cardio","fiche":"234","front":"IEC/ARA2 : surveillance biologique ?","back":"PA, **créatinine**, **kaliémie** **1 semaine** après l'introduction et chaque hausse de dose.","prio":"P2","sec":"s11"},{"id":"fc-234-411c2b","poly":"cardio","fiche":"234","front":"IEC/ARA2 : quand réduire ou arrêter ?","back":"Hypotension symptomatique ou créatinine augmentée de **> 20-30 %**.","prio":"P3","sec":"s11"},{"id":"fc-234-6515c0","poly":"cardio","fiche":"234","front":"Antialdostérone : surveillance ?","back":"**Kaliémie** et **fonction rénale**, surtout avec un IEC.","prio":"P2","sec":"s11"},{"id":"fc-234-b9423d","poly":"cardio","fiche":"234","front":"Gliflozine : effet sur la fonction rénale ?","back":"Légère baisse initiale, puis effet plutôt **néphroprotecteur**.","prio":"P3","sec":"s11"},{"id":"fc-234-570b18","poly":"cardio","fiche":"234","front":"IC à FE altérée : médicaments contre-indiqués ?","back":"**Diltiazem**, **vérapamil**, **antiarythmiques de classe I** (flécaïnide).","prio":"P1","sec":"s11"},{"id":"fc-234-2455df","poly":"cardio","fiche":"234","front":"IC : AINS ?","back":"**À éviter** (rétention hydrosodée) ; à proscrire avec un IEC.","prio":"P1","sec":"s11"},{"id":"fc-234-4ad145","poly":"cardio","fiche":"234","front":"IC à FE altérée : dihydropyridines (amlodipine) ?","back":"Effet **neutre** sur la mortalité : possibles si angor ou HTA.","prio":"P3","sec":"s11"},{"id":"fc-234-c70fa3","poly":"cardio","fiche":"234","front":"IEC et antialdostérone : peut-on les débuter en même temps ?","back":"**Non** (hyperkaliémie, insuffisance rénale).","prio":"P1","sec":"s11"},{"id":"fc-234-e068d9","poly":"cardio","fiche":"234","front":"IC à FE diminuée + cardiopathie ischémique stable : antiagrégant ?","back":"**Aspirine 75 à 100 mg/j**.","prio":"P3","sec":"s11"},{"id":"fc-234-ed25e5","poly":"cardio","fiche":"234","front":"Ivabradine : mécanisme et indication ?","back":"Bloque le canal **If** (ralentit la FC) ; NYHA II-IV, **rythme sinusal**, FC **> 70-75/min** malgré bêtabloquant (ou CI).","prio":"P2","sec":"s12"},{"id":"fc-234-af3041","poly":"cardio","fiche":"234","front":"Digoxine dans l'IC : effet sur la survie ?","back":"**Neutre** ; améliore les symptômes ; réservée aux IC graves résistantes.","prio":"P2","sec":"s12"},{"id":"fc-234-fddd1d","poly":"cardio","fiche":"234","front":"Dérivés nitrés au long cours dans l'IC ?","back":"En **appoint** si pressions de remplissage élevées.","prio":"P3","sec":"s12"},{"id":"fc-234-9aa85b","poly":"cardio","fiche":"234","front":"IC + FA : anticoagulant préféré ?","back":"**AOD** (rivaroxaban, apixaban, dabigatran) **préférés aux AVK** ; scores **CHA₂DS₂-VA** et **HAS-BLED**.","prio":"P1","sec":"s12"},{"id":"fc-234-f9f773","poly":"cardio","fiche":"234","front":"IC : autres indications d'anticoagulation que la FA ?","back":"**Thrombus intracavitaire**, **AVC embolique**.","prio":"P2","sec":"s12"},{"id":"fc-234-164e21","poly":"cardio","fiche":"234","front":"IC + FA : comment ralentir ?","back":"**Bêtabloquants** et/ou **digitaliques** (vérapamil, diltiazem interdits) ; FC < 110 bpm à la marche.","prio":"P2","sec":"s12"},{"id":"fc-234-1fc0ea","poly":"cardio","fiche":"234","front":"IC à FE diminuée + FA : seul antiarythmique utilisable ?","back":"**Amiodarone** (associable au bêtabloquant).","prio":"P1","sec":"s12"},{"id":"fc-234-257e1e","poly":"cardio","fiche":"234","front":"Amiodarone dans l'IC : risque spécifique ?","back":"**Dysthyroïdie**, pouvant décompenser l'IC.","prio":"P2","sec":"s12"},{"id":"fc-234-f8bd81","poly":"cardio","fiche":"234","front":"AVK chez l'insuffisant cardiaque en FA : INR cible ?","back":"**2,5 (2 à 3)**, sauf valve mécanique mitrale.","prio":"P3","sec":"s12"},{"id":"fc-234-9a922c","poly":"cardio","fiche":"234","front":"Après infarctus avec FE basse : bêtabloquant sans symptôme d'IC ?","back":"**Oui**, même sans symptôme d'IC si la FE est basse.","prio":"P2","sec":"s12"},{"id":"fc-234-e553f4","poly":"cardio","fiche":"234","front":"Après infarctus étendu avec FE < 40 % : antialdostérone de référence ?","back":"**Éplérénone** (moins de décès, de morts subites, de récidives d'IC).","prio":"P2","sec":"s12"},{"id":"fc-234-e9a5d8","poly":"cardio","fiche":"234","front":"Après IDM : contre-indications de l'antialdostérone ?","back":"Insuffisance rénale (créatinine **> 221 µmol/L**), **hyperkaliémie**.","prio":"P3","sec":"s12"},{"id":"fc-234-1e3661","poly":"cardio","fiche":"234","front":"Après IDM : objectif lipidique ?","back":"LDL-C baissé d'au moins **50 %** et **< 0,55 g/L** (statine forte dose).","prio":"P2","sec":"s12"},{"id":"fc-234-7256ad","poly":"cardio","fiche":"234","front":"Après IDM : ajout si LDL non atteint sous statine ?","back":"**Ézétimibe 10 mg** après 4 semaines ; puis **anti-PCSK9** si LDL > 0,7 g/L.","prio":"P3","sec":"s12"},{"id":"fc-234-1e3ea0","poly":"cardio","fiche":"234","front":"Statines forte dose après IDM : doses ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P3","sec":"s12"},{"id":"fc-234-641ea7","poly":"cardio","fiche":"234","front":"Inhibiteurs P2Y12 d'entretien : doses ?","back":"Clopidogrel **75 mg/j** ; prasugrel **10 mg/j** ; ticagrélor **90 mg × 2/j**.","prio":"P3","sec":"s12"},{"id":"fc-234-2f4c3c","poly":"cardio","fiche":"234","front":"Prasugrel : contre-indication et restrictions ?","back":"CI si **ATCD d'AVC** ; non recommandé **> 75 ans** ou **< 60 kg**.","prio":"P3","sec":"s12"},{"id":"fc-234-eb602f","poly":"cardio","fiche":"234","front":"Après IDM + anticoagulant nécessaire : association par défaut ?","back":"**Clopidogrel + anticoagulant 12 mois**, puis anticoagulant seul.","prio":"P2","sec":"s12"},{"id":"fc-234-efe394","poly":"cardio","fiche":"234","front":"Après IDM avec FEVG < 35 % précoce : conduite rythmique ?","back":"**Gilet défibrillateur**, réévaluation ; **DAI** si FEVG < 35 % **≥ 6 semaines** après, traitement optimisé.","prio":"P2","sec":"s12"},{"id":"fc-234-ea39ae","poly":"cardio","fiche":"234","front":"Après SCA : réadaptation cardiovasculaire ?","back":"Proposée **à tous**.","prio":"P3","sec":"s12"},{"id":"fc-234-e8aadd","poly":"cardio","fiche":"234","front":"Resynchronisation cardiaque : indication ?","back":"IC **NYHA II à IV** + **FEVG ≤ 35 %** + **QRS ≥ 130 ms**.","prio":"P1","sec":"s13"},{"id":"fc-234-1da2be","poly":"cardio","fiche":"234","front":"Resynchronisation : facteurs d'efficacité ?","back":"**BBG**, **QRS ≥ 150 ms**, cardiopathie **non ischémique**.","prio":"P2","sec":"s13"},{"id":"fc-234-7d428d","poly":"cardio","fiche":"234","front":"Resynchronisation : technique ?","back":"Sondes **OD**, **VD** et paroi latérale du VG via le **sinus coronaire** ; stimulation simultanée.","prio":"P3","sec":"s13"},{"id":"fc-234-6fc071","poly":"cardio","fiche":"234","front":"DAI en prévention secondaire : indication ?","back":"Arrêt cardiaque par **FV récupéré** ou **TV symptomatique**.","prio":"P1","sec":"s13"},{"id":"fc-234-83b991","poly":"cardio","fiche":"234","front":"DAI en prévention primaire : indication ?","back":"**NYHA II-III**, **FEVG ≤ 35 %** ; ischémique ≥ **6 semaines** post-IDM ; non ischémique après ≥ **3 mois** de traitement.","prio":"P1","sec":"s13"},{"id":"fc-234-5e2628","poly":"cardio","fiche":"234","front":"DAI : principales complications ?","back":"**Infections de sonde**, **chocs inappropriés**.","prio":"P2","sec":"s13"},{"id":"fc-234-48ca13","poly":"cardio","fiche":"234","front":"DAI en NYHA IV : indiqué ?","back":"**Non**, sauf projet de greffe ou d'assistance (survie probable > 1 an requise).","prio":"P2","sec":"s13"},{"id":"fc-234-2c3d1e","poly":"cardio","fiche":"234","front":"Amiodarone dans l'IC : réduit-elle la mortalité ou la mort subite ?","back":"**Non**, ni l'une ni l'autre.","prio":"P2","sec":"s13"},{"id":"fc-234-de34e0","poly":"cardio","fiche":"234","front":"IC résistante au traitement médical : options ?","back":"**Greffe cardiaque**, ou parfois **assistance ventriculaire** (en attente de greffe ou définitive).","prio":"P1","sec":"s13"},{"id":"fc-234-3292a0","poly":"cardio","fiche":"234","front":"IC avancée sans greffe ni assistance possible : prise en charge ?","back":"**Soins de support** ou **soins palliatifs**.","prio":"P2","sec":"s13"},{"id":"fc-234-2cedb6","poly":"cardio","fiche":"234","front":"IC à FE préservée : critères diagnostiques ?","back":"Symptômes/signes d'IC + **FEVG ≥ 50 %** + **BNP/NT-proBNP augmenté** + arguments ETT (pressions élevées, **HVG** ou **OG dilatée**).","prio":"P1","sec":"s14"},{"id":"fc-234-330f04","poly":"cardio","fiche":"234","front":"IC à FE préservée : seuils échographiques d'HVG et d'OG ?","back":"Masse VG **≥ 115 g/m²** (homme), **≥ 95 g/m²** (femme) ; OG **> 34 mL/m²**.","prio":"P3","sec":"s14"},{"id":"fc-234-447e1c","poly":"cardio","fiche":"234","front":"IC à FE préservée : classe médicamenteuse hautement recommandée ?","back":"**Gliflozines** (dapagliflozine, empagliflozine).","prio":"P1","sec":"s14"},{"id":"fc-234-e71c3f","poly":"cardio","fiche":"234","front":"IC à FE préservée : mesures associées ?","back":"Prévenir la **FA**, les **poussées hypertensives**, la **surcharge volumique** ; traiter l'**ischémie**.","prio":"P1","sec":"s14"},{"id":"fc-234-59f6bb","poly":"cardio","fiche":"234","front":"IC à FE préservée : axes A à G ?","back":"**A**rythmies, **B**lood pressure, **C**omorbidités, **D**iurétique, **E**xercice, **F**ollow-up, **G**liflozines.","prio":"P3","sec":"s14"},{"id":"fc-234-d24550","poly":"cardio","fiche":"234","front":"IC à FE préservée : inhibiteur calcique ralentisseur ?","back":"**Possible** (allonge la diastole), contrairement à l'IC à FE altérée.","prio":"P2","sec":"s14"},{"id":"fc-234-6b7b93","poly":"cardio","fiche":"234","front":"IC à FE préservée : diurétiques ?","back":"Thiazidique ou de l'anse si **congestion**, en surveillant la fonction rénale.","prio":"P3","sec":"s14"},{"id":"fc-234-cce07c","poly":"cardio","fiche":"234","front":"Remodelage inverse : définition ?","back":"Amélioration voire **normalisation** de la fonction après traitement de l'IC ou de sa cause.","prio":"P2","sec":"s15"},{"id":"fc-234-7a97d0","poly":"cardio","fiche":"234","front":"IC en NYHA IV : mortalité ?","back":"Jusqu'à **40 à 50 % par an**.","prio":"P2","sec":"s15"},{"id":"fc-234-0c2ea3","poly":"cardio","fiche":"234","front":"IC : 2 grands modes de décès ?","back":"**Mort subite** (TV/FV) et **IC réfractaire**.","prio":"P2","sec":"s15"},{"id":"fc-234-921d89","poly":"cardio","fiche":"234","front":"Hospitalisation pour décompensation : signification pronostique ?","back":"**Facteur de gravité**.","prio":"P2","sec":"s15"},{"id":"fc-234-f95c5a","poly":"cardio","fiche":"234","front":"IC : complications thromboemboliques ?","back":"Embolies systémiques (thrombus des cavités gauches dilatées, FA) ; **embolie pulmonaire** (alitement).","prio":"P3","sec":"s15"},{"id":"fc-234-0fcbcc","poly":"cardio","fiche":"234","front":"IC : complications rénales et électrolytiques ?","back":"Hypo- ou hyperkaliémie, **hyponatrémie**, **insuffisance rénale**.","prio":"P3","sec":"s15"},{"id":"fc-234-32fb95","poly":"cardio","fiche":"234","front":"Complications de l'IC : moyen mnémotechnique ?","back":"**DÉTHER** : Décès, Épisodes de décompensation, Troubles du rythme, Hypotension, Emboliques, Rein et électrolytes.","prio":"P3","sec":"s15"},{"id":"fc-234-e21381","poly":"cardio","fiche":"234","front":"IC : facteurs pronostiques péjoratifs ?","back":"**NYHA III-IV**, hospitalisations répétées, cause ischémique, **FE basse**, QRS > 120 ms, **hyponatrémie**, BNP élevé, pic de **VO₂** bas.","prio":"P2","sec":"s15"},{"id":"fc-234-21a707","poly":"cardio","fiche":"234","front":"Après hospitalisation pour IC : principal risque ?","back":"**Réhospitalisation** : contrôler la congestion et optimiser le traitement en ambulatoire.","prio":"P2","sec":"s16"},{"id":"fc-234-c49af3","poly":"cardio","fiche":"234","front":"Après hospitalisation pour IC : éducation thérapeutique ?","back":"Patient + entourage : **signes d'alerte**, **régime pauvre en sel**, **observance**, autoprise en charge.","prio":"P1","sec":"s16"},{"id":"fc-234-6b7fe3","poly":"cardio","fiche":"234","front":"IC : télésurveillance, principe ?","back":"Symptômes, PA, FC, **poids** transmis presque chaque jour ; alertes → dépister tôt une décompensation.","prio":"P2","sec":"s16"},{"id":"fc-234-d82952","poly":"cardio","fiche":"234","front":"IC stabilisée : rôle des infirmiers en pratique avancée ?","back":"Suivi et prescription sous **responsabilité médicale**.","prio":"P3","sec":"s16"},{"id":"fc-234-71e423","poly":"cardio","fiche":"234","front":"IC : 4 signes d'alerte à apprendre au patient ?","back":"**Poids** qui monte, **souffle** qui s'aggrave, **dormir assis**, **jambes ou ventre** qui gonflent.","prio":"P2","sec":"s16"},{"id":"fc-234-1300bc","poly":"cardio","fiche":"234","front":"IC : place de l'arrêt du tabac ?","back":"**Impératif chez tous**, a fortiori en cas de **cardiopathie ischémique**.","prio":"P2","sec":"s10"},{"id":"fc-234-64873b","poly":"cardio","fiche":"234","front":"Cardiomyopathie : pourquoi parle-t-on de diagnostic d'élimination ?","back":"Il faut d'abord écarter une cause **ischémique**, **valvulaire**, **congénitale** ou **hypertensive**.","prio":"P3","sec":"s5"},{"id":"fc-234-b3e0bf","poly":"cardio","fiche":"234","front":"Coronarographie dans l'IC : indications ?","back":"Angor, probabilité coronaire **intermédiaire à haute** ou ischémie prouvée, chez un patient **revascularisable**.","prio":"P3","sec":"s4"},{"id":"fc-234-162ae3","poly":"cardio","fiche":"234","front":"IC + FA persistante : anticoagulation autour d'une cardioversion ?","back":"**3 à 4 semaines** d'anticoagulation efficace avant (ou ETO sans thrombus), puis au moins **4 semaines** après.","prio":"P3","sec":"s12"},{"id":"fc-234-7d8eb9","poly":"cardio","fiche":"234","front":"Indication à la fois de resynchronisation et de DAI : quel dispositif ?","back":"**Dispositif combiné** (défibrillation + resynchronisation).","prio":"P3","sec":"s13"},{"id":"fc-234-bc2778","poly":"cardio","fiche":"234","front":"IC à FE préservée : traitement comparé à celui de l'IC à FE altérée ?","back":"Moins codifié (moins d'études) mais finalement **proche** ; mêmes mesures hygiénodiététiques, éducation et suivi.","prio":"P3","sec":"s14"},{"id":"fc-234-1a9a6f","poly":"cardio","fiche":"234","front":"IC avec faiblesse musculaire : que rechercher ?","back":"Une **myopathie associée**, surtout en cas de **CMD**.","prio":"P3","sec":"s3"},{"id":"fc-235-cfe8ad","poly":"cardio","fiche":"235","front":"Péricardite aiguë : définition ?","back":"**Inflammation aiguë des feuillets du péricarde**.","prio":"P1","sec":"s1"},{"id":"fc-235-d3bfae","poly":"cardio","fiche":"235","front":"Péricardite aiguë : 3 enjeux ?","back":"**Diagnostic différentiel** d'une douleur thoracique ; **tamponnade** ; **récidives** (20 à 30 %), ± constriction selon la cause.","prio":"P1","sec":"s1"},{"id":"fc-235-526da3","poly":"cardio","fiche":"235","front":"Douleur thoracique évoquant une péricardite : 3 diagnostics graves à toujours évoquer ?","back":"**SCA**, **embolie pulmonaire**, **dissection aortique**.","prio":"P1","sec":"s1"},{"id":"fc-235-04ae10","poly":"cardio","fiche":"235","front":"Péricardite aiguë : 4 critères diagnostiques ?","back":"**Précordialgie typique** ; **frottement péricardique** ; **ECG typique** ; **épanchement** à l'échocardiographie.","prio":"P1","sec":"s1"},{"id":"fc-235-f4a4e2","poly":"cardio","fiche":"235","front":"Péricardite aiguë : combien de critères faut-il ?","back":"**Au moins 2 sur 4**.","prio":"P1","sec":"s1"},{"id":"fc-235-1f49ff","poly":"cardio","fiche":"235","front":"Suspicion de péricardite : examens systématiques ?","back":"**ECG** et **échocardiographie**.","prio":"P1","sec":"s1"},{"id":"fc-235-8753d9","poly":"cardio","fiche":"235","front":"CRP élevée : fait-elle partie des critères de péricardite ?","back":"**Non**, le syndrome inflammatoire n'est pas un critère.","prio":"P1","sec":"s1"},{"id":"fc-235-d4f9e7","poly":"cardio","fiche":"235","front":"Péricardite aiguë : caractéristiques de la fièvre ?","back":"**Modérée**, présente **dès le début**, avec myalgies, asthénie, souvent après un **épisode grippal**.","prio":"P1","sec":"s2"},{"id":"fc-235-825488","poly":"cardio","fiche":"235","front":"Péricardite chez le sujet âgé : particularité de la fièvre ?","back":"Elle **manque plus souvent**.","prio":"P2","sec":"s2"},{"id":"fc-235-bac473","poly":"cardio","fiche":"235","front":"Douleur de péricardite : facteurs aggravants ?","back":"**Décubitus**, **inspiration profonde**, **toux**.","prio":"P1","sec":"s2"},{"id":"fc-235-4ca2e2","poly":"cardio","fiche":"235","front":"Douleur de péricardite : position antalgique ?","back":"**Antéflexion** (assis, penché en avant).","prio":"P1","sec":"s2"},{"id":"fc-235-3ac2d9","poly":"cardio","fiche":"235","front":"Douleur de péricardite : siège, durée et réponse à la trinitrine ?","back":"Rétrosternale ou précordiale gauche, **prolongée**, **résistante à la trinitrine**.","prio":"P1","sec":"s2"},{"id":"fc-235-f7fbe8","poly":"cardio","fiche":"235","front":"Péricardite : symptômes associés possibles en dehors de la douleur ?","back":"**Dyspnée** (soulagée par l'antéflexion), **toux sèche**, **dysphonie**, **hoquet**.","prio":"P2","sec":"s2"},{"id":"fc-235-a3d8c2","poly":"cardio","fiche":"235","front":"Frottement péricardique : caractéristiques ?","back":"Précoce, **systolodiastolique**, changeant avec le temps et la position ; **inconstant et fugace**.","prio":"P1","sec":"s2"},{"id":"fc-235-14928e","poly":"cardio","fiche":"235","front":"Frottement péricardique : valeur diagnostique ?","back":"Il **confirme** le diagnostic.","prio":"P2","sec":"s2"},{"id":"fc-235-a22c85","poly":"cardio","fiche":"235","front":"Absence de frottement péricardique : élimine-t-elle une péricardite ?","back":"**Non** (frottement inconstant et fugace).","prio":"P1","sec":"s2"},{"id":"fc-235-371e60","poly":"cardio","fiche":"235","front":"Douleur résistante à la trinitrine : élimine-t-elle un SCA ST+ ?","back":"**Non** : dans le SCA ST+, douleur et sus-décalage persistent aussi après trinitrine.","prio":"P2","sec":"s2"},{"id":"fc-235-7c834d","poly":"cardio","fiche":"235","front":"Péricardite virale typique : profil du patient et début ?","back":"Sujet **jeune**, plutôt **masculin**, syndrome grippal récent ; début **brutal et fébrile**.","prio":"P1","sec":"s2"},{"id":"fc-235-5f5ab6","poly":"cardio","fiche":"235","front":"Péricardite virale typique : résultat habituel de l'échocardiographie ?","back":"**Le plus souvent normale**.","prio":"P2","sec":"s2"},{"id":"fc-235-8a6b30","poly":"cardio","fiche":"235","front":"Péricardite : un premier ECG normal élimine-t-il le diagnostic ?","back":"**Non** : l'ECG est **à répéter**.","prio":"P1","sec":"s3"},{"id":"fc-235-9354e3","poly":"cardio","fiche":"235","front":"ECG de péricardite : caractéristiques des anomalies ?","back":"**Diffuses**, **sans territoire coronaire**, **sans image en miroir**.","prio":"P1","sec":"s3"},{"id":"fc-235-4a0b93","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade I : quand et aspect ?","back":"**1er jour** : sus-décalage de ST **concave vers le haut**, T **positives**.","prio":"P1","sec":"s3"},{"id":"fc-235-b5b668","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade II : quand et aspect ?","back":"Entre la **24e et la 48e heure** : ondes T **plates**.","prio":"P2","sec":"s3"},{"id":"fc-235-223432","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade III : quand et aspect ?","back":"**1re semaine** : ondes T **négatives**.","prio":"P2","sec":"s3"},{"id":"fc-235-9ba48d","poly":"cardio","fiche":"235","front":"ECG de péricardite, stade IV : quand et aspect ?","back":"Au cours du **1er mois** : **normalisation**.","prio":"P2","sec":"s3"},{"id":"fc-235-3a71fb","poly":"cardio","fiche":"235","front":"ECG de péricardite : anomalie du segment PQ ?","back":"**Sous-décalage de PQ** à la phase initiale.","prio":"P1","sec":"s3"},{"id":"fc-235-f8dd58","poly":"cardio","fiche":"235","front":"Péricardite : troubles du rythme possibles ?","back":"**Tachycardie sinusale**, extrasystoles atriales, **FA**, **flutter atrial**.","prio":"P2","sec":"s3"},{"id":"fc-235-49c276","poly":"cardio","fiche":"235","front":"Épanchement péricardique abondant : signes ECG ?","back":"**Microvoltage** et parfois **alternance électrique** (mêmes signes que dans la tamponnade).","prio":"P1","sec":"s3"},{"id":"fc-235-813055","poly":"cardio","fiche":"235","front":"Microvoltage : définition ?","back":"QRS **< 5 mm** en dérivations périphériques et **< 10 mm** en précordiales.","prio":"P2","sec":"s3"},{"id":"fc-235-dd40e2","poly":"cardio","fiche":"235","front":"Péricardite : bilan biologique initial ?","back":"**NFS**, **CRP**, **troponine** (imposée), **ionogramme**, **urée**, **créatinine** ; hémocultures si fièvre ; IDR discutée.","prio":"P1","sec":"s3"},{"id":"fc-235-52fa30","poly":"cardio","fiche":"235","front":"Péricardite avec troponine nettement élevée : quoi évoquer ?","back":"Une **myocardite associée** (surtout avec trouble de cinétique du VG) ; ne pas conclure trop vite au **SCA**.","prio":"P1","sec":"s3"},{"id":"fc-235-eee44e","poly":"cardio","fiche":"235","front":"Péricardite typique sans gravité : sérologies virales ?","back":"**Inutiles**.","prio":"P2","sec":"s3"},{"id":"fc-235-8650e2","poly":"cardio","fiche":"235","front":"Péricardite : aspect habituel de la radiographie thoracique ?","back":"**Le plus souvent normale**.","prio":"P3","sec":"s3"},{"id":"fc-235-120e0a","poly":"cardio","fiche":"235","front":"Épanchement abondant : aspect radiologique ?","back":"Cardiomégalie avec cœur triangulaire **« en carafe »** ou rectitude du bord gauche.","prio":"P2","sec":"s3"},{"id":"fc-235-a15a1e","poly":"cardio","fiche":"235","front":"Radiographie de thorax dans la péricardite : intérêt ?","back":"Orientation **étiologique** (pathologie pulmonaire associée, épanchement pleural).","prio":"P3","sec":"s3"},{"id":"fc-235-4b8521","poly":"cardio","fiche":"235","front":"Péricardite « sèche » : définition ?","back":"Péricardite avec **échocardiographie normale** (sans épanchement).","prio":"P2","sec":"s4"},{"id":"fc-235-502b04","poly":"cardio","fiche":"235","front":"Échocardiographie dans la péricardite : apports ?","back":"**Abondance**, **topographie**, **tolérance** de l'épanchement ; confirme une **tamponnade** ; cherche une altération de la **FEVG**.","prio":"P2","sec":"s4"},{"id":"fc-235-af0f64","poly":"cardio","fiche":"235","front":"Masse péricardique à l'écho : signification habituelle ?","back":"Rare, habituellement **maligne**.","prio":"P3","sec":"s4"},{"id":"fc-235-d7bc06","poly":"cardio","fiche":"235","front":"Épanchement péricardique minime : épaisseur ?","back":"**< 10 mm**.","prio":"P2","sec":"s4"},{"id":"fc-235-d8133b","poly":"cardio","fiche":"235","front":"Épanchement péricardique modéré : épaisseur ?","back":"**10 à 20 mm**.","prio":"P2","sec":"s4"},{"id":"fc-235-61e265","poly":"cardio","fiche":"235","front":"Épanchement péricardique abondant : épaisseur ?","back":"**> 20 mm**.","prio":"P1","sec":"s4"},{"id":"fc-235-37ff2d","poly":"cardio","fiche":"235","front":"Péricardite : indications du scanner ou de l'IRM ?","back":"En **2e intention** : patient **non échogène**, **péricardite néoplasique**, **épanchement cloisonné**.","prio":"P2","sec":"s4"},{"id":"fc-235-a66cf4","poly":"cardio","fiche":"235","front":"IRM dans la péricardite : apports ?","back":"Inflammation du péricarde, **myocardite associée** (rehaussement tardif), sans irradiation.","prio":"P3","sec":"s4"},{"id":"fc-235-c412cd","poly":"cardio","fiche":"235","front":"Ponction péricardique : 3 indications ?","back":"**Tamponnade** ; forte suspicion **néoplasique** ; épanchement **abondant symptomatique** persistant après **1 semaine** de traitement.","prio":"P2","sec":"s4"},{"id":"fc-235-a1cda4","poly":"cardio","fiche":"235","front":"Liquide péricardique : analyses biochimiques ?","back":"**Glucose**, **protides**, **LDH**.","prio":"P3","sec":"s4"},{"id":"fc-235-478634","poly":"cardio","fiche":"235","front":"Liquide péricardique : analyses microbiologiques et moléculaires ?","back":"Cytologie, **Gram** et **Ziehl-Nielsen**, **culture**, **PCR** virale et tuberculeuse.","prio":"P3","sec":"s4"},{"id":"fc-235-de4716","poly":"cardio","fiche":"235","front":"Suspicion de péricardite purulente : geste privilégié ?","back":"**Drainage péricardique chirurgical**.","prio":"P2","sec":"s4"},{"id":"fc-235-aa40c2","poly":"cardio","fiche":"235","front":"Péricardite aiguë : hospitalisation systématique ?","back":"**Non**, inutile dans la majorité des cas.","prio":"P1","sec":"s5"},{"id":"fc-235-36e354","poly":"cardio","fiche":"235","front":"Péricardite : combien de facteurs majeurs suffisent à hospitaliser ?","back":"**Un seul**.","prio":"P1","sec":"s5"},{"id":"fc-235-e26c16","poly":"cardio","fiche":"235","front":"Péricardite : 4 facteurs prédictifs majeurs (ESC 2015) ?","back":"**Fièvre > 38 °C** ; **début subaigu** ; **épanchement > 20 mm** ou tamponnade ; **résistance** à l'aspirine/AINS après **7 jours**.","prio":"P1","sec":"s5"},{"id":"fc-235-736493","poly":"cardio","fiche":"235","front":"Péricardite : définition du début subaigu ?","back":"Symptômes présents depuis **plusieurs jours ou semaines**.","prio":"P2","sec":"s5"},{"id":"fc-235-21fecc","poly":"cardio","fiche":"235","front":"Péricardite : facteurs mineurs (hospitalisation discutée) ?","back":"**Immunodépression**, **anticoagulant**, **traumatisme thoracique**, **myocardite associée** (troponine élevée).","prio":"P1","sec":"s5"},{"id":"fc-235-9e5173","poly":"cardio","fiche":"235","front":"Péricardite : autres situations d'hospitalisation que les facteurs majeurs ?","back":"**Complication d'emblée** (tamponnade, récidive, constriction), **mauvaise tolérance**, **étiologie particulière** suspectée.","prio":"P2","sec":"s5"},{"id":"fc-235-51305a","poly":"cardio","fiche":"235","front":"Péricardite typique du jeune sans facteur ni complication : prise en charge ?","back":"**Ambulatoire**, réévaluation à **7 jours**.","prio":"P2","sec":"s5"},{"id":"fc-235-864544","poly":"cardio","fiche":"235","front":"Péricardite avec signes droits, hypotension et pouls paradoxal : conduite ?","back":"Suspecter une **tamponnade** : **USIC** et appel en urgence pour **drainage**.","prio":"P1","sec":"s5"},{"id":"fc-235-30156c","poly":"cardio","fiche":"235","front":"Sus-décalage de ST : péricardite ou SCA, arguments ECG ?","back":"Péricardite : **diffus**, **concave**, sans territoire ni miroir, sous-PQ ; SCA : territorial, **classiquement convexe**, **miroir** habituel, puis **onde Q**.","prio":"P1","sec":"s6"},{"id":"fc-235-8a8782","poly":"cardio","fiche":"235","front":"SCA ST+ : critère de topographie du sus-décalage ?","back":"**Au moins 2 dérivations contiguës**, dont la localisation désigne le territoire.","prio":"P2","sec":"s6"},{"id":"fc-235-1b2991","poly":"cardio","fiche":"235","front":"SCA ST+ : délai d'apparition classique de l'onde Q ?","back":"À partir de la **6e heure**.","prio":"P3","sec":"s6"},{"id":"fc-235-4606c9","poly":"cardio","fiche":"235","front":"Péricardite : y a-t-il des ondes Q ?","back":"**Non**.","prio":"P2","sec":"s6"},{"id":"fc-235-5514e6","poly":"cardio","fiche":"235","front":"Constriction péricardique : diagnostic différentiel principal ?","back":"La **cardiomyopathie restrictive**.","prio":"P2","sec":"s6"},{"id":"fc-235-ef62b3","poly":"cardio","fiche":"235","front":"Péricardite aiguë : cause la plus fréquente ?","back":"**Virale ou inconnue** (idiopathique) : **9 cas sur 10**.","prio":"P1","sec":"s7"},{"id":"fc-235-868cf6","poly":"cardio","fiche":"235","front":"Péricardite : 3 causes à rechercher car elles changent le traitement ?","back":"**Tuberculose**, **cancer**, **maladies auto-immunes**.","prio":"P2","sec":"s7"},{"id":"fc-235-17a5de","poly":"cardio","fiche":"235","front":"Péricardite : 2e cause après la forme virale, et évolution de la tuberculose ?","back":"Cause **néoplasique** en 2e position ; tuberculose **en régression**.","prio":"P3","sec":"s7"},{"id":"fc-235-93991a","poly":"cardio","fiche":"235","front":"Péricardite virale : virus en cause ?","back":"**Entérovirus** (coxsackie A et B), échovirus, adénovirus, CMV, parvovirus B19, EBV, herpès, VIH, VHC, grippe…","prio":"P2","sec":"s7"},{"id":"fc-235-707433","poly":"cardio","fiche":"235","front":"Péricardite virale : mécanisme ?","back":"Infection + **réaction immunitaire** associée ; rarement prouvée.","prio":"P2","sec":"s7"},{"id":"fc-235-2daed8","poly":"cardio","fiche":"235","front":"Péricardite virale : seul examen qui confirme le virus ?","back":"La **PCR** (liquide ou biopsie péricardique) ; deux sérologies à 15 jours ne font qu'**orienter**.","prio":"P2","sec":"s7"},{"id":"fc-235-966880","poly":"cardio","fiche":"235","front":"Péricardite virale : complication la plus fréquente ?","back":"La **récidive** (**20 à 30 %**) ; tamponnade et constriction **rares**.","prio":"P1","sec":"s7"},{"id":"fc-235-3820af","poly":"cardio","fiche":"235","front":"Péricardite chronique récidivante à virus prouvé : traitements discutés ?","back":"**Immunoglobulines**, **interféron α**.","prio":"P3","sec":"s7"},{"id":"fc-235-eeb007","poly":"cardio","fiche":"235","front":"Péricardite chez le patient VIH : mécanismes ?","back":"VIH ou autre virus ; **surinfection** bactérienne ou fongique ; **lymphome** ou **sarcome de Kaposi**.","prio":"P3","sec":"s7"},{"id":"fc-235-54a210","poly":"cardio","fiche":"235","front":"Péricardite du jeune sans complication : principal risque évolutif ?","back":"La **récidive** (la tamponnade est rare dans la forme virale).","prio":"P2","sec":"s7"},{"id":"fc-235-403748","poly":"cardio","fiche":"235","front":"Péricardite purulente : terrain ?","back":"**Immunodéprimé** ; infection sévère (septicémie, pleuropulmonaire, après chirurgie cardiaque ou thoracique).","prio":"P2","sec":"s8"},{"id":"fc-235-914a29","poly":"cardio","fiche":"235","front":"Péricardite purulente : germes cités ?","back":"**Staphylocoques**, **pneumocoques**, **streptocoques**, **bacilles à Gram négatif**…","prio":"P3","sec":"s8"},{"id":"fc-235-3ffb64","poly":"cardio","fiche":"235","front":"Péricardite purulente : traitement ?","back":"**Antibiothérapie adaptée au germe** + **drainage chirurgical** souvent nécessaire.","prio":"P2","sec":"s8"},{"id":"fc-235-0bdcf5","poly":"cardio","fiche":"235","front":"Péricardite purulente : pronostic ?","back":"**Sévère** : tamponnade fréquente, constriction.","prio":"P3","sec":"s8"},{"id":"fc-235-b50254","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : présentation ?","back":"Péricardite **subaiguë liquidienne**, altération de l'état général, fièvre modérée persistante.","prio":"P2","sec":"s8"},{"id":"fc-235-5d20be","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : terrains ?","back":"Sujet tuberculeux, âgé ou greffé, **VIH**, alcoolique ; contage ou virage récent de l'IDR.","prio":"P3","sec":"s8"},{"id":"fc-235-d41243","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : éléments diagnostiques ?","back":"**BK** (direct, culture, PCR) ; **adénosine-déaminase** élevée dans le liquide ; parfois **granulome**.","prio":"P3","sec":"s8"},{"id":"fc-235-c6a7fe","poly":"cardio","fiche":"235","front":"Péricardite tuberculeuse : traitement ?","back":"**Antituberculeux** ; pour certains + **prednisone** pour limiter la constriction.","prio":"P2","sec":"s8"},{"id":"fc-235-516b30","poly":"cardio","fiche":"235","front":"IDR négative : élimine-t-elle une péricardite tuberculeuse ?","back":"**Non** : faussement négative dans **près d'un tiers** des cas.","prio":"P2","sec":"s8"},{"id":"fc-235-ccafe5","poly":"cardio","fiche":"235","front":"Péricardite néoplasique : cancers en cause ?","back":"Métastases : **cancer bronchique**, **sein**, mélanomes, leucémies, lymphomes, Kaposi.","prio":"P2","sec":"s8"},{"id":"fc-235-12d770","poly":"cardio","fiche":"235","front":"Mésothéliome péricardique primitif : fréquence relative ?","back":"**40 fois moins fréquent** que les métastases.","prio":"P3","sec":"s8"},{"id":"fc-235-a8da21","poly":"cardio","fiche":"235","front":"Péricardite néoplasique : caractéristiques de l'épanchement ?","back":"**Hémorragique**, **tamponnade** fréquente, **récidive** fréquente.","prio":"P2","sec":"s8"},{"id":"fc-235-43933d","poly":"cardio","fiche":"235","front":"Péricardite auto-immune : maladies en cause ?","back":"**Lupus**, **polyarthrite rhumatoïde**, sclérodermie, périartérite noueuse, dermatomyosite.","prio":"P3","sec":"s8"},{"id":"fc-235-f3d345","poly":"cardio","fiche":"235","front":"Péricardite auto-immune : quand la retenir ?","back":"**Diagnostic d'élimination** (liquide : lymphocytes augmentés, anticorps antisarcolemme ; myocardite associée).","prio":"P2","sec":"s8"},{"id":"fc-235-c6da87","poly":"cardio","fiche":"235","front":"Péricardite précoce de l'infarctus : délai et contexte ?","back":"**J3-J5**, après un infarctus **transmural** ; évolution le plus souvent favorable.","prio":"P2","sec":"s8"},{"id":"fc-235-3b6fee","poly":"cardio","fiche":"235","front":"Syndrome de Dressler : délai ?","back":"**2e-16e semaine** (item 235) ; classiquement la **3e semaine** (item 339).","prio":"P2","sec":"s8"},{"id":"fc-235-787d8d","poly":"cardio","fiche":"235","front":"Syndrome de Dressler : tableau ?","back":"Fièvre, péricardite, **pleurésie**, **arthralgies**, AEG, syndrome inflammatoire, **QT allongé** ; devenu rare.","prio":"P2","sec":"s8"},{"id":"fc-235-ac262f","poly":"cardio","fiche":"235","front":"Péricardite urémique : terrain ?","back":"Insuffisance rénale sévère **non encore dialysée** ou **premières semaines** de dialyse.","prio":"P2","sec":"s8"},{"id":"fc-235-266e20","poly":"cardio","fiche":"235","front":"Péricardite chez un dialysé au long cours : signification ?","back":"Le plus souvent une **épuration inadaptée**.","prio":"P3","sec":"s8"},{"id":"fc-235-795a7d","poly":"cardio","fiche":"235","front":"Syndrome postpéricardotomie : définition ?","back":"Péricardite inflammatoire dans les **jours ou mois** après **chirurgie** ou **transplantation cardiaque** ; tamponnade possible ; en postopératoire, penser aussi à l'**hémopéricarde**.","prio":"P2","sec":"s8"},{"id":"fc-235-798f96","poly":"cardio","fiche":"235","front":"Constriction péricardique : première cause actuelle ?","back":"La **chirurgie cardiaque**.","prio":"P2","sec":"s8"},{"id":"fc-235-7390ea","poly":"cardio","fiche":"235","front":"Péricardite post-radique : délai habituel ?","back":"En général **1 an** après l'irradiation thoracique.","prio":"P3","sec":"s8"},{"id":"fc-235-8c1ef9","poly":"cardio","fiche":"235","front":"Péricardite : causes médicamenteuses citées ?","back":"**Hydralazine**, **pénicilline**.","prio":"P3","sec":"s8"},{"id":"fc-235-c66db1","poly":"cardio","fiche":"235","front":"Péricardite : causes citées parmi les « autres causes » (hors médicaments) ?","back":"**Dissection aortique** (avec tamponnade), **irradiation thoracique**, **traumatismes**, **hypothyroïdie**, **rhumatisme articulaire aigu**.","prio":"P3","sec":"s8"},{"id":"fc-235-84f944","poly":"cardio","fiche":"235","front":"Péricardite traumatique : circonstances et fréquence ?","back":"Traumatisme thoracique ou cardiaque (**hémopéricarde**), **cathétérisme** (ablation par radiofréquence, pose de stimulateur), **postopératoire immédiat** ; causes **relativement fréquentes**.","prio":"P3","sec":"s8"},{"id":"fc-235-de1022","poly":"cardio","fiche":"235","front":"Tamponnade : causes à évoquer ?","back":"**Hémopéricarde**, **traumatique**, **néoplasique**, **tuberculeuse**, **post-infarctus**, **dissection aortique** ; virale exceptionnellement.","prio":"P2","sec":"s8"},{"id":"fc-235-9ee51e","poly":"cardio","fiche":"235","front":"Péricardite bénigne : repos ?","back":"**Arrêt de l'exercice physique** jusqu'à normalisation des symptômes, **CRP**, **ECG** et **écho** (en général le 1er mois).","prio":"P1","sec":"s9"},{"id":"fc-235-3509e5","poly":"cardio","fiche":"235","front":"Péricardite bénigne : traitement médicamenteux ?","back":"Antalgique + **AINS** (aspirine ou ibuprofène) + **colchicine** + **protecteur gastrique**.","prio":"P1","sec":"s9"},{"id":"fc-235-069c1f","poly":"cardio","fiche":"235","front":"Péricardite : posologie de l'aspirine ?","back":"**750 à 1 000 mg toutes les 8 h**, 1 à 2 semaines à pleine dose.","prio":"P1","sec":"s9"},{"id":"fc-235-ccca3a","poly":"cardio","fiche":"235","front":"Péricardite : posologie de l'ibuprofène ?","back":"**600 mg toutes les 8 h**, 1 à 2 semaines à pleine dose.","prio":"P1","sec":"s9"},{"id":"fc-235-6b34a3","poly":"cardio","fiche":"235","front":"Péricardite : durée totale de l'AINS (ESC 2015) ?","back":"Pleine dose 1 à 2 semaines puis **arrêt progressif** au bout de **4 à 8 semaines**.","prio":"P2","sec":"s9"},{"id":"fc-235-95fddb","poly":"cardio","fiche":"235","front":"Péricardite : posologie et durée de la colchicine ?","back":"**0,5 mg × 2/j** pendant **3 mois**.","prio":"P1","sec":"s9"},{"id":"fc-235-149af6","poly":"cardio","fiche":"235","front":"Colchicine : quand réduire à 0,5 mg/j ?","back":"Poids **< 70 kg**, âge **> 70 ans** ou DFG **< 35 mL/min**.","prio":"P2","sec":"s9"},{"id":"fc-235-67a43d","poly":"cardio","fiche":"235","front":"Colchicine : contre-indication ?","back":"**Insuffisance rénale sévère**.","prio":"P1","sec":"s9"},{"id":"fc-235-3ad457","poly":"cardio","fiche":"235","front":"Colchicine : modalités d'arrêt ?","back":"Arrêt progressif : la **dernière semaine** à **0,5 mg/j un jour sur deux**.","prio":"P2","sec":"s9"},{"id":"fc-235-8a26aa","poly":"cardio","fiche":"235","front":"Colchicine : interactions via quel cytochrome et quels médicaments ?","back":"**CYP3A4** : macrolides, ciclosporine, vérapamil, statines.","prio":"P2","sec":"s9"},{"id":"fc-235-01340f","poly":"cardio","fiche":"235","front":"Colchicine dans la péricardite : bénéfices ?","back":"Calme la douleur, raccourcit les symptômes, **réduit de 50 %** le risque de récidive.","prio":"P1","sec":"s9"},{"id":"fc-235-0f1409","poly":"cardio","fiche":"235","front":"Péricardite aiguë : corticoïdes en 1re intention ?","back":"**Non** : notion **inacceptable** (risque de récidive).","prio":"P1","sec":"s9"},{"id":"fc-235-3af1fb","poly":"cardio","fiche":"235","front":"Anti-inflammatoires de la péricardite : arrêt brutal ou progressif ?","back":"**Progressif** (AINS comme colchicine).","prio":"P2","sec":"s9"},{"id":"fc-235-7c41d5","poly":"cardio","fiche":"235","front":"Péricardite hospitalisée : traitement de base ?","back":"Le même : **repos**, antalgique, **AINS + colchicine**, protecteur gastrique, puis traitement de la cause ou complication.","prio":"P2","sec":"s10"},{"id":"fc-235-1c7909","poly":"cardio","fiche":"235","front":"Péricardite + myocardite associée : examen de référence ?","back":"**IRM** (et échocardiographie).","prio":"P2","sec":"s10"},{"id":"fc-235-a3105a","poly":"cardio","fiche":"235","front":"Échec de AINS + colchicine : traitement ajouté ?","back":"**Corticoïdes 0,25 à 0,5 mg/kg/j**, **en plus** de la bithérapie.","prio":"P2","sec":"s10"},{"id":"fc-235-0b6e06","poly":"cardio","fiche":"235","front":"Échec de la bithérapie : remplace-t-on AINS + colchicine par les corticoïdes ?","back":"**Non**, on **ajoute** la corticothérapie.","prio":"P2","sec":"s10"},{"id":"fc-235-f49065","poly":"cardio","fiche":"235","front":"Péricardite sous anticoagulant : risque des AINS ?","back":"**Majoration du risque hémorragique** (à éviter sous AVK ou AOD).","prio":"P2","sec":"s10"},{"id":"fc-235-55e502","poly":"cardio","fiche":"235","front":"Péricardite néoplasique avec tamponnade : conduite ?","back":"**Ponction en urgence** ; cytologie ou biopsie ; suivi clinique et échographique (récidives).","prio":"P2","sec":"s11"},{"id":"fc-235-637dc5","poly":"cardio","fiche":"235","front":"Tamponnade : mécanisme ?","back":"Épanchement abondant et/ou brutal qui **comprime les cavités droites** → **adiastolie**, risque d'arrêt cardiocirculatoire.","prio":"P1","sec":"s12"},{"id":"fc-235-a061c4","poly":"cardio","fiche":"235","front":"Pouls paradoxal : définition ?","back":"PAS inspiratoire **inférieure de 10 mmHg** à la PAS expiratoire (baisse marquée du pouls en inspiration).","prio":"P1","sec":"s12"},{"id":"fc-235-622f11","poly":"cardio","fiche":"235","front":"Pouls paradoxal : mécanisme ?","back":"À l'inspiration, le retour veineux dilate le VD qui **comprime le VG** → baisse de la PAS.","prio":"P2","sec":"s12"},{"id":"fc-235-0b52d3","poly":"cardio","fiche":"235","front":"Tamponnade : signes cliniques ?","back":"**Signes droits** (turgescence jugulaire, RHJ), **choc** (tachycardie, **PAS < 90 mmHg**), **bruits du cœur assourdis**, **pouls paradoxal**.","prio":"P1","sec":"s12"},{"id":"fc-235-294718","poly":"cardio","fiche":"235","front":"Tamponnade : symptômes respiratoires ?","back":"**Dyspnée positionnelle** : polypnée puis **orthopnée**, toux.","prio":"P2","sec":"s12"},{"id":"fc-235-35fbbd","poly":"cardio","fiche":"235","front":"Tamponnade : type de choc ?","back":"**Choc obstructif**.","prio":"P2","sec":"s12"},{"id":"fc-235-ae0446","poly":"cardio","fiche":"235","front":"Tamponnade : examen qui confirme ?","back":"L'**échocardiographie**.","prio":"P1","sec":"s12"},{"id":"fc-235-7e826c","poly":"cardio","fiche":"235","front":"Tamponnade : signes échographiques ?","back":"**Collapsus diastolique des cavités droites**, compression du VG par le VD en inspiration, **swinging heart**, septum paradoxal.","prio":"P2","sec":"s12"},{"id":"fc-235-a31acd","poly":"cardio","fiche":"235","front":"Tamponnade : prise en charge ?","back":"**USIC**, **remplissage par macromolécules**, arrêt/neutralisation des anticoagulants discuté, **ponction échoguidée** ou **drainage chirurgical** en urgence.","prio":"P1","sec":"s12"},{"id":"fc-235-e68c5f","poly":"cardio","fiche":"235","front":"Tamponnade confirmée à l'écho : conséquence ?","back":"Elle **impose le drainage** (risque d'arrêt par adiastolie).","prio":"P1","sec":"s12"},{"id":"fc-235-8f9ddc","poly":"cardio","fiche":"235","front":"Tamponnade sous HNF : antidote ?","back":"**Sulfate de protamine** (neutralisation instantanée).","prio":"P2","sec":"s12"},{"id":"fc-235-1b4592","poly":"cardio","fiche":"235","front":"Tamponnade sous AVK : antidotes ?","back":"**PPSB** (action très rapide) + **vitamine K** (quelques heures), toujours associés.","prio":"P2","sec":"s12"},{"id":"fc-235-2d6741","poly":"cardio","fiche":"235","front":"Dabigatran : antidote ?","back":"**Idarucizumab**.","prio":"P2","sec":"s12"},{"id":"fc-235-673763","poly":"cardio","fiche":"235","front":"Anti-Xa oraux : neutralisation possible ?","back":"**PPSB** ou **Feiba®** ; antidote spécifique en cours de commercialisation.","prio":"P3","sec":"s12"},{"id":"fc-235-091119","poly":"cardio","fiche":"235","front":"AOD : meilleur « antidote » selon le Collège ?","back":"Le **temps écoulé depuis la dernière prise** (demi-vie courte).","prio":"P3","sec":"s12"},{"id":"fc-235-a2d2c6","poly":"cardio","fiche":"235","front":"HBPM et fondaparinux : antidote ?","back":"**Pas d'antidote** (en cours de développement).","prio":"P3","sec":"s12"},{"id":"fc-235-9094c9","poly":"cardio","fiche":"235","front":"Hémorragie grave sous AVK : surveillance de l'INR après CCP ?","back":"INR **30 min** après le CCP (complément si **> 1,5**), puis à **6-8 h** et 1 fois/j.","prio":"P3","sec":"s12"},{"id":"fc-235-6e6c58","poly":"cardio","fiche":"235","front":"Péricardite : 6 complications ?","back":"**Épanchement abondant**, **tamponnade**, **myocardite**, **récidive**, **péricardite chronique**, **constriction**.","prio":"P1","sec":"s13"},{"id":"fc-235-817522","poly":"cardio","fiche":"235","front":"Myocardite associée : présentation ?","back":"IC **fébrile**, parfois **choc** (fulminante) ; **troponine** nettement élevée ± trouble de cinétique.","prio":"P2","sec":"s13"},{"id":"fc-235-452cec","poly":"cardio","fiche":"235","front":"Péricardite récidivante : fréquence et cause favorisante ?","back":"**20 à 30 %** (la plus fréquente) ; souvent après un traitement **trop court**.","prio":"P1","sec":"s13"},{"id":"fc-235-ee5f1d","poly":"cardio","fiche":"235","front":"Péricardite récidivante : délai typique ?","back":"**Entre 3 mois et 3 ans** après une péricardite d'allure virale.","prio":"P2","sec":"s13"},{"id":"fc-235-87bfee","poly":"cardio","fiche":"235","front":"Péricardite chronique : définition ?","back":"Évolution **> 3 mois**.","prio":"P2","sec":"s13"},{"id":"fc-235-c76c89","poly":"cardio","fiche":"235","front":"Péricardite chronique : causes retrouvées en pratique ?","back":"Surtout des **causes néoplasiques** (plus que la tuberculose).","prio":"P2","sec":"s13"},{"id":"fc-235-1d88f7","poly":"cardio","fiche":"235","front":"Péricardite chronique : examen pour la biopsie ?","back":"**Péricardoscopie** avec biopsie dirigée.","prio":"P3","sec":"s13"},{"id":"fc-235-32413c","poly":"cardio","fiche":"235","front":"Constriction péricardique : fréquence après péricardite ?","back":"Constriction modérée dans **moins de 10 %** des cas.","prio":"P2","sec":"s13"},{"id":"fc-235-ad408a","poly":"cardio","fiche":"235","front":"Constriction péricardique : mécanisme ?","back":"Péricarde épaissi fibreux ou **fibrocalcaire** → **adiastolie** avec **égalisation des pressions télédiastoliques** des 4 cavités.","prio":"P2","sec":"s13"},{"id":"fc-235-919c9a","poly":"cardio","fiche":"235","front":"Constriction péricardique : présentation clinique ?","back":"IC **droite** souvent prédominante (turgescence jugulaire, **ascite**) et gauche.","prio":"P2","sec":"s13"},{"id":"fc-235-0c170a","poly":"cardio","fiche":"235","front":"Constriction péricardique : signe au cathétérisme droit ?","back":"Aspect en **« dip-plateau »**.","prio":"P3","sec":"s13"},{"id":"fc-235-521768","poly":"cardio","fiche":"235","front":"Constriction péricardique : traitement chirurgical ?","back":"**Péricardectomie**.","prio":"P2","sec":"s13"},{"id":"fc-235-4dfb6a","poly":"cardio","fiche":"235","front":"Constriction péricardique : terrains ?","back":"**Chirurgie cardiaque** (1re cause), **tuberculose**, **péricardite purulente**.","prio":"P3","sec":"s13"},{"id":"fc-235-0f7bf1","poly":"cardio","fiche":"235","front":"Calcifications péricardiques : meilleur examen pour les voir ?","back":"Le **scanner** (parfois visibles à la radio).","prio":"P3","sec":"s13"},{"id":"fc-235-b4ef06","poly":"cardio","fiche":"235","front":"Colchicine : conduite en cas de diarrhée ?","back":"Elle doit **souvent** conduire à **baisser la dose**.","prio":"P2","sec":"s13"},{"id":"fc-235-bfbd67","poly":"cardio","fiche":"235","front":"Colchicine avec un inhibiteur du CYP3A4 : biologie à surveiller ?","back":"**Transaminases**, **créatinine**, **CPK**, **NFS**, **plaquettes**.","prio":"P3","sec":"s13"},{"id":"fc-235-a6658f","poly":"cardio","fiche":"235","front":"Péricardite : calendrier de suivi ?","back":"**J7** (médecin traitant), **1 mois** (cardiologue + écho), **3 et 6 mois**.","prio":"P1","sec":"s14"},{"id":"fc-235-308234","poly":"cardio","fiche":"235","front":"Péricardite : quand l'échocardiographie de contrôle ?","back":"À **1 mois**, **avant l'arrêt** de l'anti-inflammatoire.","prio":"P1","sec":"s14"},{"id":"fc-235-bdb17a","poly":"cardio","fiche":"235","front":"Péricardite : objectif de la consultation à J7 ?","back":"Vérifier l'absence de symptômes (résistance à 7 jours = **facteur majeur**).","prio":"P2","sec":"s14"},{"id":"fc-235-752573","poly":"cardio","fiche":"235","front":"Péricardite : objectifs des consultations à 3 et 6 mois ?","back":"Absence de symptômes, normalisation **CRP** et **écho**, modalités d'**arrêt des traitements**.","prio":"P2","sec":"s14"},{"id":"fc-235-3fd11e","poly":"cardio","fiche":"235","front":"Péricardite : conditions de reprise du sport ?","back":"Disparition des symptômes et normalisation **CRP**, **ECG**, **écho** (en général après le **1er mois**).","prio":"P1","sec":"s14"},{"id":"fc-235-fefccd","poly":"cardio","fiche":"235","front":"Péricardite : message à donner sur la durée du traitement ?","back":"Une durée **insuffisante** expose à la **récidive**.","prio":"P2","sec":"s14"},{"id":"fc-236-e47e43","poly":"cardio","fiche":"236","front":"Troubles de conduction : 3 cadres ?","back":"**Dysfonction sinusale** ; **bloc atrioventriculaire** ; **bloc de branche / hémibloc**.","prio":"P1","sec":"s1"},{"id":"fc-236-ed0fd3","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : ce qui est atteint ?","back":"Le nœud sinusal : trouble de l'**automatisme** et/ou **bloc sinoatrial**.","prio":"P2","sec":"s1"},{"id":"fc-236-d98729","poly":"cardio","fiche":"236","front":"BAV : ce qui est atteint ?","back":"La **jonction atrioventriculaire** et/ou les **deux branches** du His à la fois.","prio":"P2","sec":"s1"},{"id":"fc-236-1a5800","poly":"cardio","fiche":"236","front":"Rythme d'échappement : où naît-il ?","back":"Toujours **en aval** de la zone malade.","prio":"P1","sec":"s1"},{"id":"fc-236-f1b7e6","poly":"cardio","fiche":"236","front":"Troubles de conduction : règle de gravité ?","back":"Plus la lésion est **distale**, plus l'échappement est **lent et instable** → plus c'est grave.","prio":"P1","sec":"s1"},{"id":"fc-236-e0059e","poly":"cardio","fiche":"236","front":"Bloc suprahissien vs hissien/infrahissien : échappement ?","back":"Suprahissien (sinus, NAV) : plus **rapide et stable** ; hissien/infrahissien : **lent, instable**.","prio":"P1","sec":"s1"},{"id":"fc-236-fa2419","poly":"cardio","fiche":"236","front":"Trouble de conduction : sur quel examen repose le diagnostic ?","back":"L'**ECG** (diagnostic électrocardiographique).","prio":"P1","sec":"s1"},{"id":"fc-236-6a2df9","poly":"cardio","fiche":"236","front":"Tissu de conduction : trajet de haut en bas ?","back":"Nœud sinusal → **NAV** → **His** → branches droite et gauche (hémibranches antérieure et postérieure) → **Purkinje**.","prio":"P3","sec":"s1"},{"id":"fc-236-b800cc","poly":"cardio","fiche":"236","front":"NAV : vascularisation ?","back":"**Artère du NAV**, branche de la **coronaire droite** (croix des sillons).","prio":"P3","sec":"s1"},{"id":"fc-236-2179da","poly":"cardio","fiche":"236","front":"Faisceau de His et branches : vascularisation ?","back":"**1re septale de l'IVA** et artère du NAV.","prio":"P3","sec":"s1"},{"id":"fc-236-8c50bb","poly":"cardio","fiche":"236","front":"Tissu nodal vs His-Purkinje : conduction et influence du SNA ?","back":"Nodal : lente, **décrémentielle**, forte influence du SNA ; His-Purkinje : rapide, « **tout ou rien** », peu d'influence.","prio":"P2","sec":"s1"},{"id":"fc-236-1c700c","poly":"cardio","fiche":"236","front":"Échappement nodal (NAV) : fréquence et QRS ?","back":"**40-60 bpm**, QRS **fins**, **stable**.","prio":"P2","sec":"s1"},{"id":"fc-236-7a994e","poly":"cardio","fiche":"236","front":"Échappement hissien : fréquence et QRS ?","back":"**35-45 bpm**, QRS fins, instable.","prio":"P3","sec":"s1"},{"id":"fc-236-9658ad","poly":"cardio","fiche":"236","front":"Échappement infrahissien : fréquence et QRS ?","back":"**< 40 bpm**, QRS **larges**, instable.","prio":"P2","sec":"s1"},{"id":"fc-236-6b5ac3","poly":"cardio","fiche":"236","front":"Trouble de conduction : de quoi peut-il être le marqueur ?","back":"D'une **cardiopathie**, à rechercher.","prio":"P2","sec":"s1"},{"id":"fc-236-3e77e2","poly":"cardio","fiche":"236","front":"QRS large sans bloc de branche systématisé : mécanisme ?","back":"**Bloc intraventriculaire non systématisé** (cardiopathie).","prio":"P3","sec":"s1"},{"id":"fc-236-a618bc","poly":"cardio","fiche":"236","front":"BAV complet nodal vs infranodal : quel est le plus grave ?","back":"**Infranodal** : échappement lent, instable, risque d'**asystolie**.","prio":"P1","sec":"s1"},{"id":"fc-236-bc13e6","poly":"cardio","fiche":"236","front":"Troubles de conduction : sont-ils souvent asymptomatiques ?","back":"**Oui** : dysfonction sinusale latente, BAV 1 et la plupart des BAV 2.","prio":"P2","sec":"s2"},{"id":"fc-236-79fe43","poly":"cardio","fiche":"236","front":"Bas débit cérébral par bradycardie : symptômes ?","back":"**Lipothymies**, **syncopes à l'emporte-pièce (Adams-Stokes)**, pseudovertiges.","prio":"P1","sec":"s2"},{"id":"fc-236-dc3c42","poly":"cardio","fiche":"236","front":"Bradycardie permanente : symptômes de bas débit cardiaque ?","back":"Moindre capacité d'effort, dyspnée d'effort, **asthénie**, **angor**, **insuffisance cardiaque**.","prio":"P2","sec":"s2"},{"id":"fc-236-64dc49","poly":"cardio","fiche":"236","front":"Bradycardie chez le sujet âgé : signes trompeurs ?","back":"**Chutes à répétition**, **déclin cognitif**, réduction d'activité.","prio":"P1","sec":"s2"},{"id":"fc-236-cb7daf","poly":"cardio","fiche":"236","front":"Dysfonction sinusale + FA : symptômes possibles ?","back":"**Palpitations** ou **embolie artérielle** (maladie rythmique atriale).","prio":"P3","sec":"s2"},{"id":"fc-236-372919","poly":"cardio","fiche":"236","front":"BAV à l'effort seulement : siège habituel ?","back":"**Intra- ou infrahissien** (fréquence-dépendant).","prio":"P3","sec":"s2"},{"id":"fc-236-abd4a0","poly":"cardio","fiche":"236","front":"Torsade de pointes sur bradycardie : facteurs favorisants et risque ?","back":"**Bradycardie** + **allongement du QT** ; risque de **fibrillation ventriculaire**.","prio":"P1","sec":"s2"},{"id":"fc-236-c448d6","poly":"cardio","fiche":"236","front":"BAV : circonstances de découverte typiques ?","back":"**Bradycardie constatée** à l'éveil ou bilan d'une **lipothymie/syncope**.","prio":"P2","sec":"s2"},{"id":"fc-236-954999","poly":"cardio","fiche":"236","front":"Bloc de branche isolé : symptômes ?","back":"**Toujours asymptomatique** (découverte fortuite).","prio":"P1","sec":"s2"},{"id":"fc-236-c1100c","poly":"cardio","fiche":"236","front":"Bloc de branche + syncopes : signification ?","back":"**Signe de gravité** immédiat ; peut signer une cardiopathie (surtout BBG) ou faire suspecter un **BAV paroxystique**.","prio":"P1","sec":"s2"},{"id":"fc-236-b9bb38","poly":"cardio","fiche":"236","front":"Dysfonction sinusale du sujet âgé : quel médicament rechercher ?","back":"Un **bradycardisant**, surtout **bêtabloquant**, y compris en **collyre**.","prio":"P2","sec":"s2"},{"id":"fc-236-90164d","poly":"cardio","fiche":"236","front":"Bradycardie sinusale du sportif d'endurance asymptomatique : traiter ?","back":"**Non** (hypertonie vagale).","prio":"P1","sec":"s2"},{"id":"fc-236-9ea516","poly":"cardio","fiche":"236","front":"Dysfonction sinusale du sujet âgé : faut-il traiter ?","back":"**Souvent oui** (fibrose, souvent avec FA ou atteinte du NAV).","prio":"P2","sec":"s2"},{"id":"fc-236-f421b9","poly":"cardio","fiche":"236","front":"Nœud sinusal : localisation ?","back":"Atrium droit, à la jonction avec la **veine cave supérieure**.","prio":"P3","sec":"s3"},{"id":"fc-236-b0056c","poly":"cardio","fiche":"236","front":"Rythme sinusal normal : fréquence ?","back":"**50-100 bpm**.","prio":"P3","sec":"s3"},{"id":"fc-236-b70b90","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : 2 mécanismes ?","back":"Impulsion **non fabriquée** (trouble de l'automatisme) ou **non transmise** à l'oreillette (bloc sinoatrial).","prio":"P2","sec":"s3"},{"id":"fc-236-b85633","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : cause habituelle ?","back":"**Fibrose liée à l'âge**.","prio":"P2","sec":"s3"},{"id":"fc-236-6baa1a","poly":"cardio","fiche":"236","front":"Maladie rythmique atriale : définition ?","back":"Dysfonction sinusale + troubles du rythme atrial : **syndrome brady-tachy** ou **pauses post-réductionnelles**.","prio":"P2","sec":"s3"},{"id":"fc-236-2d1a1a","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : critère de bradycardie ?","back":"Bradycardie sinusale inappropriée **< 50 bpm** à l'éveil (< 40/min la nuit).","prio":"P1","sec":"s3"},{"id":"fc-236-2e11e5","poly":"cardio","fiche":"236","front":"Bradycardie sinusale inappropriée : définition et tolérance ?","back":"Bradycardie diurne marquée (< 50 bpm) **sans cause extrinsèque** ; en général **bien tolérée** (symptômes possibles avec l'âge).","prio":"P3","sec":"s3"},{"id":"fc-236-365f6a","poly":"cardio","fiche":"236","front":"Pause sinusale : seuil pathologique ?","back":"**> 3 secondes**.","prio":"P1","sec":"s3"},{"id":"fc-236-b5fecd","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : critères ECG (liste) ?","back":"Bradycardie < 50 bpm, **incompétence chronotrope**, pauses > 3 s, **BSA 2 ou 3**, brady-tachy, pause > 3 s au massage sinocarotidien ou tilt-test.","prio":"P2","sec":"s3"},{"id":"fc-236-d7eeb6","poly":"cardio","fiche":"236","front":"Pause sinusale : comment se termine-t-elle ?","back":"Par un échappement **atrial** (P différente) ou **jonctionnel** (QRS sans P).","prio":"P3","sec":"s3"},{"id":"fc-236-83a3a2","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : examen de référence ?","back":"**Holter** (ECG continu).","prio":"P2","sec":"s3"},{"id":"fc-236-19d318","poly":"cardio","fiche":"236","front":"BSA du 1er degré : aspect ECG ?","back":"**Rien** (invisible à l'ECG).","prio":"P2","sec":"s3"},{"id":"fc-236-488ef7","poly":"cardio","fiche":"236","front":"BSA 2e degré type I : aspect ECG ?","back":"P irrégulières puis pause **inférieure au double** du cycle sinusal le plus court.","prio":"P3","sec":"s3"},{"id":"fc-236-9e4d4d","poly":"cardio","fiche":"236","front":"BSA 2e degré type II : aspect ECG ?","back":"Pauses égales à un **multiple** du cycle sinusal (2/1, 3/1).","prio":"P2","sec":"s3"},{"id":"fc-236-22d030","poly":"cardio","fiche":"236","front":"BSA 3e degré : aspect ECG ?","back":"Bradycardie à **échappement jonctionnel** (QRS fins) sans activité sinusale.","prio":"P2","sec":"s3"},{"id":"fc-236-f10294","poly":"cardio","fiche":"236","front":"Insuffisance chronotrope : définition ?","back":"FC qui n'accélère pas assez à l'effort ; seuil habituel : FC max **< 75 %** de la fréquence maximale théorique ; courbe **aplatie** au holter.","prio":"P2","sec":"s3"},{"id":"fc-236-2f0fd0","poly":"cardio","fiche":"236","front":"Pauses post-réductionnelles : mécanisme ?","back":"**Sidération du nœud sinusal** à l'arrêt de l'arythmie atriale.","prio":"P3","sec":"s3"},{"id":"fc-236-120688","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : comment prouver le lien avec les symptômes ?","back":"**Holter avec journal** des symptômes ; si rares : enregistreur longue durée ou **moniteur implantable**.","prio":"P2","sec":"s3"},{"id":"fc-236-e68f65","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : intérêt du test d'effort ?","back":"Diagnostic de l'**insuffisance chronotrope**.","prio":"P3","sec":"s3"},{"id":"fc-236-442c76","poly":"cardio","fiche":"236","front":"Dysfonction sinusale sévère symptomatique : bilan minimal ?","back":"**Échocardiographie**, **ionogramme**, **créatinine**, **troponine** + causes extrinsèques.","prio":"P3","sec":"s3"},{"id":"fc-236-ab3f3d","poly":"cardio","fiche":"236","front":"Ondes P bloquées : compatibles avec une dysfonction sinusale ?","back":"**Non**, jamais : penser au **BAV**.","prio":"P1","sec":"s3"},{"id":"fc-236-c1a36b","poly":"cardio","fiche":"236","front":"Faisceau de His : particularité anatomique ?","back":"**Seule communication électrique** entre oreillettes et ventricules.","prio":"P2","sec":"s4"},{"id":"fc-236-ef694d","poly":"cardio","fiche":"236","front":"Phénomène de Wenckebach : définition ?","back":"Stimulation atriale de plus en plus rapide → la conduction nodale s'allonge progressivement jusqu'au **blocage** (conduction **décrémentielle**).","prio":"P2","sec":"s4"},{"id":"fc-236-1641e0","poly":"cardio","fiche":"236","front":"BAV complet infranodal : fréquence d'échappement ?","back":"**15-40/min**, instable, risque d'**asystolie**.","prio":"P2","sec":"s4"},{"id":"fc-236-27c2e7","poly":"cardio","fiche":"236","front":"BAV : 4 éléments à préciser à l'ECG ?","back":"**Degré**, **paroxystique ou permanent**, **congénital ou acquis**, et surtout **siège**.","prio":"P2","sec":"s4"},{"id":"fc-236-0bac45","poly":"cardio","fiche":"236","front":"BAV du 1er degré : critère ECG ?","back":"**PR > 200 ms**, fixe et constant.","prio":"P1","sec":"s4"},{"id":"fc-236-96b5ed","poly":"cardio","fiche":"236","front":"BAV du 1er degré : siège habituel ?","back":"Généralement **nodal** (exceptionnellement intrahissien).","prio":"P2","sec":"s4"},{"id":"fc-236-646088","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 1 : critère ECG ?","back":"**Allongement progressif du PR** jusqu'à une P bloquée, puis PR plus court.","prio":"P1","sec":"s4"},{"id":"fc-236-798533","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 1 : siège ?","back":"**Toujours nodal**.","prio":"P1","sec":"s4"},{"id":"fc-236-9fbe30","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 2 : critère ECG ?","back":"**Une P bloquée** inopinée **sans allongement préalable du PR**.","prio":"P1","sec":"s4"},{"id":"fc-236-c880b7","poly":"cardio","fiche":"236","front":"BAV 2 Mobitz 2 : siège ?","back":"**Toujours hissien ou infrahissien** ; évolue souvent vers le BAV complet.","prio":"P1","sec":"s4"},{"id":"fc-236-ad8157","poly":"cardio","fiche":"236","front":"BAV de haut degré : critère ECG ?","back":"**Plusieurs P bloquées** de suite ou conduction rythmée (ex. 3:1).","prio":"P2","sec":"s4"},{"id":"fc-236-71aa2e","poly":"cardio","fiche":"236","front":"BAV de haut degré : siège habituel ?","back":"**Hissien ou infrahissien**, rarement nodal ; évolue souvent vers le BAV complet.","prio":"P2","sec":"s4"},{"id":"fc-236-862b37","poly":"cardio","fiche":"236","front":"BAV 2/1 : peut-on le classer en Mobitz 1 ou 2 ?","back":"**Non**, inclassable : la **largeur du QRS** oriente (large → infranodal).","prio":"P1","sec":"s4"},{"id":"fc-236-bd516b","poly":"cardio","fiche":"236","front":"BAV du 3e degré : critère ECG ?","back":"Aucune P conduite : **dissociation atrioventriculaire**, ventricules plus lents que les oreillettes.","prio":"P1","sec":"s4"},{"id":"fc-236-df840a","poly":"cardio","fiche":"236","front":"BAV complet sur FA : aspect ECG ?","back":"Bradycardie avec rythme ventriculaire **régulier**.","prio":"P2","sec":"s4"},{"id":"fc-236-13d530","poly":"cardio","fiche":"236","front":"Bloc nodal : effet de l'atropine, isoprénaline et effort ?","back":"**Amélioré**.","prio":"P1","sec":"s4"},{"id":"fc-236-88e2d4","poly":"cardio","fiche":"236","front":"Bloc hissien/infrahissien : effet de l'atropine et de l'effort ?","back":"**Aggravé**.","prio":"P1","sec":"s4"},{"id":"fc-236-8bd597","poly":"cardio","fiche":"236","front":"Bloc nodal vs infranodal : effet du massage sinocarotidien ?","back":"Aggrave le **nodal** ; améliore l'infranodal.","prio":"P2","sec":"s4"},{"id":"fc-236-690e75","poly":"cardio","fiche":"236","front":"Bloc infranodal : terrain fréquent ?","back":"**Bloc de branche** préexistant.","prio":"P2","sec":"s4"},{"id":"fc-236-dd791d","poly":"cardio","fiche":"236","front":"QRS < 120 ms avec BAV : orientation ?","back":"Très en faveur d'un bloc **nodal**, sans certitude.","prio":"P2","sec":"s4"},{"id":"fc-236-e97178","poly":"cardio","fiche":"236","front":"BAV à QRS fins : piège classique ?","back":"Le BAV **intrahissien**, rare, à QRS fins.","prio":"P1","sec":"s4"},{"id":"fc-236-14adca","poly":"cardio","fiche":"236","front":"Bloc hissien/infrahissien : examen de référence pour l'affirmer ?","back":"L'**EEP** (étude électrophysiologique endocavitaire).","prio":"P2","sec":"s4"},{"id":"fc-236-77d53c","poly":"cardio","fiche":"236","front":"BAV : lesquels sont symptomatiques ?","back":"**Haut degré** et **BAV 3** ; Mobitz 1 et 2 : inconstants ; BAV 1 : sans symptôme (sauf PR très long).","prio":"P2","sec":"s4"},{"id":"fc-236-b51c03","poly":"cardio","fiche":"236","front":"BAV : forme la plus fréquente ?","back":"**BAV dégénératif du sujet âgé** ; toujours chercher une cause **médicamenteuse** associée.","prio":"P2","sec":"s4"},{"id":"fc-236-2ec9a9","poly":"cardio","fiche":"236","front":"BAV permanent : examen suffisant ?","back":"L'**ECG**.","prio":"P3","sec":"s4"},{"id":"fc-236-8e9f9f","poly":"cardio","fiche":"236","front":"BAV non permanent suspecté : examens ?","back":"**Holter**, parfois **moniteur cardiaque implantable**.","prio":"P3","sec":"s4"},{"id":"fc-236-19dd61","poly":"cardio","fiche":"236","front":"EEP : seuil pathologique de l'intervalle HV ?","back":"**HV ≥ 70 ms** (atteinte infrahissienne).","prio":"P2","sec":"s4"},{"id":"fc-236-880057","poly":"cardio","fiche":"236","front":"BAV : bilan minimal étiologique ?","back":"**Ionogramme**, **échocardiographie**, **troponine**.","prio":"P2","sec":"s4"},{"id":"fc-236-481c63","poly":"cardio","fiche":"236","front":"BAV chez un sujet < 50 ans : bilan approfondi ?","back":"**IRM cardiaque** (myocardite) et recherche **génétique**.","prio":"P3","sec":"s4"},{"id":"fc-236-77fae9","poly":"cardio","fiche":"236","front":"BAV congénital : cause principale ?","back":"**Immunologique** : anticorps maternels **anti-Ro/SSA** (lupus, Gougerot-Sjögren).","prio":"P3","sec":"s4"},{"id":"fc-236-d22d24","poly":"cardio","fiche":"236","front":"Bradyarythmie : définition ?","back":"**BAV sur FA permanente** : FA lente avec pauses > 3 s, ou rythme lent **régulier** (BAV 3) ou **irrégulier** (BAV 2).","prio":"P3","sec":"s4"},{"id":"fc-236-b13d67","poly":"cardio","fiche":"236","front":"Branche gauche du His : subdivisions ?","back":"Hémibranche **antérieure (fine)** et **postérieure (épaisse)**.","prio":"P3","sec":"s5"},{"id":"fc-236-67abf9","poly":"cardio","fiche":"236","front":"Branches et Purkinje : sensibilité au SNA et à l'ischémie ?","back":"**Peu sensibles**.","prio":"P3","sec":"s5"},{"id":"fc-236-d3eb27","poly":"cardio","fiche":"236","front":"Bloc de branche : définition ?","back":"**Ralentissement** ou **interruption** de la conduction dans une branche du His.","prio":"P2","sec":"s5"},{"id":"fc-236-aa7fec","poly":"cardio","fiche":"236","front":"Bloc de branche complet : critère de durée du QRS ?","back":"**QRS > 120 ms**.","prio":"P1","sec":"s5"},{"id":"fc-236-43ee37","poly":"cardio","fiche":"236","front":"Bloc de branche : comment déterminer le côté ?","back":"**V1 positif = droit** ; **V1 négatif = gauche**.","prio":"P1","sec":"s5"},{"id":"fc-236-a36376","poly":"cardio","fiche":"236","front":"Bloc de branche incomplet : valeur ?","back":"QRS ≤ 120 ms : **peu de valeur** sémiologique ou clinique.","prio":"P3","sec":"s5"},{"id":"fc-236-a630c9","poly":"cardio","fiche":"236","front":"BBD complet : aspect en V1 et V6 ?","back":"V1 **rsR'** ; V6 qRs avec **onde S traînante**.","prio":"P2","sec":"s5"},{"id":"fc-236-3b86e7","poly":"cardio","fiche":"236","front":"BBG complet : aspect en V1 et V6 ?","back":"V1 **rS ou QS** ; D1 et V6 **R avec notch**.","prio":"P2","sec":"s5"},{"id":"fc-236-0679df","poly":"cardio","fiche":"236","front":"BBD : localisation des T négatives ?","back":"En général **V1-V2** (parfois V3).","prio":"P2","sec":"s5"},{"id":"fc-236-25a1f7","poly":"cardio","fiche":"236","front":"BBG : localisation des T négatives ?","back":"En général **D1, aVL, V5-V6**.","prio":"P2","sec":"s5"},{"id":"fc-236-b02577","poly":"cardio","fiche":"236","front":"BBG et suspicion d'infarctus : conduite ?","back":"Prendre en charge comme un **SCA ST+** (le BBG gêne le diagnostic).","prio":"P1","sec":"s5"},{"id":"fc-236-38badd","poly":"cardio","fiche":"236","front":"HBAG : critères ?","back":"QRS < 120 ms, **axe gauche au-delà de −45°**, qR en D1-aVL, rS en D2-D3-aVF avec **S3 > S2**.","prio":"P2","sec":"s5"},{"id":"fc-236-000067","poly":"cardio","fiche":"236","front":"HBPG : critères ?","back":"**Axe droit > +90°** (hors pathologie du VD ou morphologie longiligne), aspect **S1Q3**.","prio":"P2","sec":"s5"},{"id":"fc-236-b43395","poly":"cardio","fiche":"236","front":"HBAG vs HBPG : fréquence et gravité ?","back":"HBAG **fréquent** ; HBPG plus **rare**, potentiellement **plus grave**.","prio":"P2","sec":"s5"},{"id":"fc-236-a04314","poly":"cardio","fiche":"236","front":"Bloc bifasciculaire : définition ?","back":"**BBD + HBAG** ou **BBD + HBPG**.","prio":"P2","sec":"s5"},{"id":"fc-236-2a78b4","poly":"cardio","fiche":"236","front":"Bloc alternant : définition et signification ?","back":"BBD puis BBG, ou HBAG/HBPG alternants sur BBD : **trifasciculaire** = BAV complet paroxystique infrahissien, **grave**.","prio":"P1","sec":"s5"},{"id":"fc-236-b784ad","poly":"cardio","fiche":"236","front":"IDM antérieur : fréquence et risque du bloc de branche ?","back":"**10 %** ; nécrose septale étendue → risque de **BAV complet brutal** avec asystolie.","prio":"P2","sec":"s5"},{"id":"fc-236-b88243","poly":"cardio","fiche":"236","front":"Bloc bifasciculaire + perte de connaissance : conduite ?","back":"Rechercher une **cardiopathie**, puis **EEP** (HV ≥ 70 ms → stimulateur).","prio":"P2","sec":"s5"},{"id":"fc-236-19013c","poly":"cardio","fiche":"236","front":"Trouble de conduction : 3 éléments qui guident la conduite ?","back":"**Type** de trouble, **contexte** clinique, **tolérance hémodynamique**.","prio":"P2","sec":"s6"},{"id":"fc-236-d95d21","poly":"cardio","fiche":"236","front":"Bradycardie mal tolérée : critères ?","back":"**Syncope**/lipothymie, **angor**, **insuffisance cardiaque**, **choc** (hypotension, oligurie, signes neurologiques), **torsade de pointes**.","prio":"P1","sec":"s6"},{"id":"fc-236-a5c71a","poly":"cardio","fiche":"236","front":"Troubles de conduction imposant l'hospitalisation urgente ?","back":"**BAV 3**, **Mobitz 2**, **haut degré**, **blocs alternants**, **BSA 3**, **syncope + trouble conductif** (M.A.S.H. 33).","prio":"P1","sec":"s6"},{"id":"fc-236-6398c2","poly":"cardio","fiche":"236","front":"Bloc de branche isolé sans symptôme aigu : explorations ?","back":"**Non urgentes**.","prio":"P2","sec":"s6"},{"id":"fc-236-4eca47","poly":"cardio","fiche":"236","front":"Trouble de conduction à risque vital : conduite immédiate ?","back":"**USIC**, **scope**, surveillance pouls, PA, FR, SpO₂, diurèse ; traiter une cause réversible.","prio":"P1","sec":"s6"},{"id":"fc-236-d5db11","poly":"cardio","fiche":"236","front":"BAV 3 : comment prévenir la torsade de pointes ?","back":"**Éviter les médicaments allongeant le QT** ; **corriger une hypokaliémie**.","prio":"P1","sec":"s6"},{"id":"fc-236-73c596","poly":"cardio","fiche":"236","front":"Bradycardie par BAV complet vs dysfonction sinusale : laquelle est la plus grave ?","back":"Le **BAV complet** (torsades, asystolie).","prio":"P1","sec":"s6"},{"id":"fc-236-0f840e","poly":"cardio","fiche":"236","front":"Mauvaise tolérance d'une bradycardie : moyen mnémotechnique ?","back":"**ACTIONS** : Angor, Choc, Torsade, Insuffisance cardiaque, Oligurie, signes Neurologiques, Syncope.","prio":"P3","sec":"s6"},{"id":"fc-236-bbd9bb","poly":"cardio","fiche":"236","front":"Trouble de conduction : notion inacceptable ?","back":"**Oublier de rechercher une cause curable**.","prio":"P1","sec":"s7"},{"id":"fc-236-6cf6ef","poly":"cardio","fiche":"236","front":"Troubles de conduction : 3 causes aiguës réversibles prioritaires ?","back":"**IDM ST+**, **médicament bradycardisant**, **hyperkaliémie**.","prio":"P1","sec":"s7"},{"id":"fc-236-e07192","poly":"cardio","fiche":"236","front":"Hyperkaliémie : particularités des troubles conductifs ?","back":"Atteinte **à tous les étages** ; ondes T **amples et pointues**.","prio":"P1","sec":"s7"},{"id":"fc-236-c2ac0c","poly":"cardio","fiche":"236","front":"Hyperkaliémie responsable de troubles conductifs : contextes à risque ?","back":"**Insuffisance rénale** ; **médicaments hyperkaliémiants**.","prio":"P2","sec":"s7"},{"id":"fc-236-31cc3f","poly":"cardio","fiche":"236","front":"Troubles de conduction vagaux : pronostic ?","back":"**Bénins**.","prio":"P2","sec":"s7"},{"id":"fc-236-b7b3cf","poly":"cardio","fiche":"236","front":"Troubles de conduction : cause chronique la plus fréquente ?","back":"**Dégénérescence fibreuse** liée à l'âge.","prio":"P2","sec":"s7"},{"id":"fc-236-d5baf8","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : médicaments en cause ?","back":"**Bêtabloquants**, inhibiteurs calciques bradycardisants, **amiodarone**, **ivabradine**, **digitaliques**, **clonidine**.","prio":"P2","sec":"s7"},{"id":"fc-236-865d4a","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : causes extrinsèques non médicamenteuses ?","back":"Vagale, **HTIC**, syndromes méningés, hyperkaliémie, hypoxie/hypercapnie/acidose **sévères**, apnées du sommeil, **hypothermie**, **hypothyroïdie**, ictère rétentionnel sévère.","prio":"P3","sec":"s7"},{"id":"fc-236-238ed0","poly":"cardio","fiche":"236","front":"Maladie de Lenègre : définition ?","back":"BAV dégénératif du sujet âgé (**fibrose** ± calcifications).","prio":"P2","sec":"s7"},{"id":"fc-236-d6eb39","poly":"cardio","fiche":"236","front":"BAV : causes infectieuses ?","back":"**Endocardite** (abcès de l'anneau), myocardite de **Lyme** ou virale.","prio":"P2","sec":"s7"},{"id":"fc-236-96710e","poly":"cardio","fiche":"236","front":"BAV : causes iatrogènes interventionnelles ?","back":"Chirurgie valvulaire, **TAVI**, myomectomie, cathétérisme, **ablation** par radiofréquence.","prio":"P3","sec":"s7"},{"id":"fc-236-511fd9","poly":"cardio","fiche":"236","front":"BAV : valvulopathie en cause ?","back":"**Rétrécissement aortique calcifié**.","prio":"P3","sec":"s7"},{"id":"fc-236-118512","poly":"cardio","fiche":"236","front":"BAV : maladies infiltratives en cause ?","back":"**Sarcoïdose**, **amylose**, hémochromatose, maladie de Fabry.","prio":"P3","sec":"s7"},{"id":"fc-236-bbfb41","poly":"cardio","fiche":"236","front":"Bloc de branche : causes extrinsèques ?","back":"**Hyperkaliémie** ; antiarythmiques de classe I (**flécaïnide**), **antidépresseurs tricycliques**.","prio":"P2","sec":"s7"},{"id":"fc-236-b1c298","poly":"cardio","fiche":"236","front":"BBD : causes ?","back":"Variante de la normale ou atteinte du **VD** (congénitale, HTP, séquelle d'EP).","prio":"P3","sec":"s7"},{"id":"fc-236-4b4176","poly":"cardio","fiche":"236","front":"Causes aiguës réversibles de trouble de conduction : moyen mnémotechnique ?","back":"**MIMI** : Médicament, Ischémie, Métabolique (hyperkaliémie), Infectieuse/inflammatoire.","prio":"P2","sec":"s7"},{"id":"fc-236-b2d6b0","poly":"cardio","fiche":"236","front":"Trouble de conduction : bilan minimal ?","back":"**É.T.I.** : Échocardiographie, Troponine, Ionogramme.","prio":"P2","sec":"s7"},{"id":"fc-236-04ad41","poly":"cardio","fiche":"236","front":"BBG ou BAV 3 à QRS larges avec suspicion d'IDM : piège ?","back":"ECG **non informatif** : ne pas se rassurer sur l'absence de sus-ST ; coronarographie urgente à discuter.","prio":"P1","sec":"s8"},{"id":"fc-236-80e5c8","poly":"cardio","fiche":"236","front":"Syncope chez un cardiopathe porteur d'un bloc de branche : diagnostic à évoquer en plus du BAV ?","back":"**Tachycardie ventriculaire**.","prio":"P1","sec":"s8"},{"id":"fc-236-ee6ef5","poly":"cardio","fiche":"236","front":"FA lente et régulière : quoi évoquer ?","back":"Un **BAV complet** sur FA.","prio":"P1","sec":"s8"},{"id":"fc-236-cd85f6","poly":"cardio","fiche":"236","front":"BAV sur FA permanente vs maladie rythmique atriale : différence ?","back":"**Bradyarythmie** = BAV sur FA permanente ; **maladie rythmique atriale** = FA le plus souvent paroxystique + dysfonction sinusale.","prio":"P2","sec":"s8"},{"id":"fc-236-5ad11d","poly":"cardio","fiche":"236","front":"BBD isolé vs BBG : pronostic ?","back":"BBD typique isolé du jeune asymptomatique à examen normal = **variante de la normale** ; **BBG jamais bénin**.","prio":"P2","sec":"s8"},{"id":"fc-236-04fe06","poly":"cardio","fiche":"236","front":"Bradycardie mal tolérée : moyens pour accélérer le cœur ?","back":"**Isoprénaline**, **atropine**, ou **stimulation temporaire**.","prio":"P1","sec":"s9"},{"id":"fc-236-ad93df","poly":"cardio","fiche":"236","front":"Isoprénaline : mode d'administration et efficacité ?","back":"**Perfusion IV continue** ; efficace sur **tous les blocs** ; à privilégier.","prio":"P2","sec":"s9"},{"id":"fc-236-d2b3f1","poly":"cardio","fiche":"236","front":"Isoprénaline : contre-indication majeure ?","back":"**IDM aigu** (inférieur comme antérieur).","prio":"P1","sec":"s9"},{"id":"fc-236-9ac8de","poly":"cardio","fiche":"236","front":"Atropine : mode d'administration et indications ?","back":"**Bolus IV**, action **brève** ; seulement **BAV nodal** ou **dysfonction sinusale**.","prio":"P2","sec":"s9"},{"id":"fc-236-be9aeb","poly":"cardio","fiche":"236","front":"Atropine sur un bloc infranodal ?","back":"**Inefficace**, voire **aggrave** le bloc.","prio":"P1","sec":"s9"},{"id":"fc-236-b4017e","poly":"cardio","fiche":"236","front":"Échec de l'isoprénaline avec mauvaise tolérance : conduite ?","back":"**Stimulation temporaire percutanée** (sonde d'entraînement).","prio":"P2","sec":"s9"},{"id":"fc-236-72afb2","poly":"cardio","fiche":"236","front":"Stimulation externe transthoracique : place et inconvénient ?","back":"**Secours** en attendant ; **douloureuse**.","prio":"P2","sec":"s9"},{"id":"fc-236-b50ea2","poly":"cardio","fiche":"236","front":"Sonde de stimulation temporaire : complications ?","back":"**Tamponnade**, **thrombose**.","prio":"P3","sec":"s9"},{"id":"fc-236-f61e3b","poly":"cardio","fiche":"236","front":"Atropine et isoprénaline : statut thérapeutique ?","back":"**Traitements d'attente** (régression du trouble ou pose du stimulateur).","prio":"P2","sec":"s9"},{"id":"fc-236-8b6913","poly":"cardio","fiche":"236","front":"Atropine dans l'arrêt cardiaque (item 331) : dose ?","back":"**1 mg** toutes les **3 à 5 min**, jusqu'à **0,04 mg/kg** au total.","prio":"P3","sec":"s9"},{"id":"fc-236-a87a20","poly":"cardio","fiche":"236","front":"Isoprénaline dans l'arrêt cardiaque (item 331) : préparation ?","back":"**5 ampoules à 0,2 mg** dans **250 mL** de G5 %, débit adapté, objectif ≥ 50-60/min.","prio":"P3","sec":"s9"},{"id":"fc-236-12ba3f","poly":"cardio","fiche":"236","front":"Trouble de conduction avec cause réversible : stimulateur ?","back":"**Non** : on traite la cause.","prio":"P1","sec":"s10"},{"id":"fc-236-cd64ae","poly":"cardio","fiche":"236","front":"Trouble de conduction : SCA le plus souvent en cause ?","back":"**Inférieur**.","prio":"P2","sec":"s10"},{"id":"fc-236-b92886","poly":"cardio","fiche":"236","front":"Bradycardie médicamenteuse : conduite ?","back":"**Arrêt** du bradycardisant (bêtabloquant y compris **collyre**, inhibiteur calcique, amiodarone, digitalique).","prio":"P2","sec":"s10"},{"id":"fc-236-9560e7","poly":"cardio","fiche":"236","front":"BAV complet sur IDM : fréquence ?","back":"**2-5 %** des IDM, plus souvent **inférieurs**.","prio":"P2","sec":"s11"},{"id":"fc-236-d8b823","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : siège et installation ?","back":"**Nodal** (> 90 %), installation **progressive** (souvent BAV 1 puis BAV 2 à QRS fins).","prio":"P1","sec":"s11"},{"id":"fc-236-4e7867","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : mécanisme ?","back":"**Vagal** s'il est précoce, ou ischémie de l'**artère du NAV**.","prio":"P2","sec":"s11"},{"id":"fc-236-962fbe","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur : évolution et traitement ?","back":"**Régressif** en règle ; répond bien à l'**atropine**.","prio":"P1","sec":"s11"},{"id":"fc-236-2177d8","poly":"cardio","fiche":"236","front":"BAV de l'IDM inférieur persistant : quand discuter un stimulateur ?","back":"S'il persiste à **J5**.","prio":"P2","sec":"s11"},{"id":"fc-236-d050c4","poly":"cardio","fiche":"236","front":"BAV de l'IDM antérieur : caractéristiques ?","back":"**Infranodal**, **brutal**, souvent précédé d'un **bloc de branche**, nécrose étendue, **mortalité importante**.","prio":"P1","sec":"s11"},{"id":"fc-236-2a0d2e","poly":"cardio","fiche":"236","front":"BAV de l'IDM antérieur : traitement ?","back":"Ne répond pas à l'atropine : **stimulation temporaire**, souvent **stimulateur définitif**.","prio":"P1","sec":"s11"},{"id":"fc-236-2d62a0","poly":"cardio","fiche":"236","front":"Hypertonie vagale du SCA inférieur : traitement ?","back":"**Atropine** + **remplissage par macromolécules**.","prio":"P2","sec":"s11"},{"id":"fc-236-1a1adb","poly":"cardio","fiche":"236","front":"BAV sur infarctus aigu : 2 médicaments contre-indiqués ?","back":"**Isoprénaline** et **bêtabloquants** (en aigu).","prio":"P1","sec":"s11"},{"id":"fc-236-702bfc","poly":"cardio","fiche":"236","front":"BBG apparu à la phase aiguë d'un IDM antérieur : signification ?","back":"Atteinte **infrahissienne** de mauvais pronostic (IC, choc cardiogénique).","prio":"P2","sec":"s11"},{"id":"fc-236-73aaa8","poly":"cardio","fiche":"236","front":"Torsade de pointes sur bradycardie : traitement principal ?","back":"**Accélérer la FC** : isoprénaline et/ou stimulation.","prio":"P1","sec":"s12"},{"id":"fc-236-01bb29","poly":"cardio","fiche":"236","front":"Torsade de pointes : corrections électrolytiques ?","back":"**Hypomagnésémie** et **hypokaliémie**.","prio":"P2","sec":"s12"},{"id":"fc-236-f599bb","poly":"cardio","fiche":"236","front":"Torsade de pointes : médicaments à arrêter ?","back":"Tout médicament **allongeant le QT**.","prio":"P2","sec":"s12"},{"id":"fc-236-2c3127","poly":"cardio","fiche":"236","front":"Sulfate de magnésium dans les torsades (item 331) : dose ?","back":"**2 g en IV directe**.","prio":"P3","sec":"s12"},{"id":"fc-236-7d67e3","poly":"cardio","fiche":"236","front":"BAV : indications du stimulateur définitif ?","back":"**Mobitz 2**, **BAV 3**, **haut degré**, en l'absence de cause curable ou réversible.","prio":"P1","sec":"s13"},{"id":"fc-236-18374c","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : indication du stimulateur ?","back":"**Symptomatique** avec **preuve du lien** bradycardie-symptômes, sans cause réversible.","prio":"P1","sec":"s13"},{"id":"fc-236-97c9f4","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : pauses justifiant un stimulateur même asymptomatiques ?","back":"Pauses **> 6 s**, documentées chez un sujet de **plus de 40 ans**.","prio":"P2","sec":"s13"},{"id":"fc-236-a6e466","poly":"cardio","fiche":"236","front":"Dysfonction sinusale : exception au critère symptomatique ?","back":"**Bradycardisant indispensable** (FA rapide de maladie rythmique, bêtabloquant d'une cardiopathie).","prio":"P3","sec":"s13"},{"id":"fc-236-614564","poly":"cardio","fiche":"236","front":"BAV 2 : quand poser un stimulateur ?","back":"Siège **infrahissien** évoqué, ou **symptomatique** quel que soit le siège.","prio":"P2","sec":"s13"},{"id":"fc-236-d84c4c","poly":"cardio","fiche":"236","front":"Bloc de branche : indications du stimulateur ?","back":"**Syncope + HV ≥ 70 ms** ; **bloc alternant**.","prio":"P2","sec":"s13"},{"id":"fc-236-9a72f4","poly":"cardio","fiche":"236","front":"BBG : quand discuter une resynchronisation ?","back":"**BBG ≥ 130 ms** + insuffisance cardiaque + **FEVG ≤ 35 %**.","prio":"P2","sec":"s13"},{"id":"fc-236-35436f","poly":"cardio","fiche":"236","front":"Stimulateur simple chambre : sonde et mode ?","back":"Sonde dans le **VD**, mode **VVI**.","prio":"P2","sec":"s13"},{"id":"fc-236-a40440","poly":"cardio","fiche":"236","front":"Stimulateur double chambre : sondes et mode ?","back":"**Oreillette droite** + **VD**, mode **DDD**.","prio":"P2","sec":"s13"},{"id":"fc-236-3b2f07","poly":"cardio","fiche":"236","front":"Stimulateur triple chambre : principe et indication ?","back":"Stimule **VD + VG** (sonde via le sinus coronaire) ; stimulation ventriculaire nécessaire avec **dysfonction VG**.","prio":"P2","sec":"s13"},{"id":"fc-236-2a9586","poly":"cardio","fiche":"236","front":"Stimulateur sans sonde : principe ?","back":"Capsule dans le **VD** par voie **veineuse fémorale**.","prio":"P3","sec":"s13"},{"id":"fc-236-3d8931","poly":"cardio","fiche":"236","front":"Pose d'un stimulateur : conditions ?","back":"**Consentement** ; **bloc opératoire**, anesthésie locale, **asepsie rigoureuse** ; voie **subclavière**.","prio":"P2","sec":"s13"},{"id":"fc-236-2da767","poly":"cardio","fiche":"236","front":"Dysfonction sinusale asymptomatique ou bradycardie de cause réversible : faut-il un stimulateur ?","back":"**Non** : ce serait une erreur (hors pauses > 6 s) ; la cause d'abord, le lien symptômes-ECG ensuite.","prio":"P2","sec":"s13"},{"id":"fc-236-d85feb","poly":"cardio","fiche":"236","front":"Bloc de branche + syncope sans BAV documenté : examen ?","back":"**EEP** avec mesure du HV ; si normale → **moniteur cardiaque implantable**.","prio":"P2","sec":"s14"},{"id":"fc-236-a916d8","poly":"cardio","fiche":"236","front":"BBG découvert : notion inacceptable ?","back":"Ne pas rechercher de **cardiopathie sous-jacente**.","prio":"P1","sec":"s14"},{"id":"fc-236-3d7dac","poly":"cardio","fiche":"236","front":"BBG isolé : bilan ?","back":"Recherche d'**HTA** méconnue ou de cardiopathie par **échocardiographie**.","prio":"P2","sec":"s14"},{"id":"fc-236-e36d7e","poly":"cardio","fiche":"236","front":"BBD isolé : bilan ?","back":"Recherche d'une pathologie **pulmonaire** ou du **VD**.","prio":"P2","sec":"s14"},{"id":"fc-236-a266e3","poly":"cardio","fiche":"236","front":"Bloc de branche sans indication de stimulateur : surveillance ?","back":"**Clinique et ECG** (sauf BBD typique sur cœur sain).","prio":"P2","sec":"s14"},{"id":"fc-236-80c059","poly":"cardio","fiche":"236","front":"Après pose d'un stimulateur : contrôles initiaux ?","back":"**Radiographie** (position des sondes) et contrôle au **programmateur**.","prio":"P2","sec":"s15"},{"id":"fc-236-b2e47a","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : rythme des contrôles ?","back":"Premier à **1-3 mois**, puis **annuel** au centre implanteur.","prio":"P2","sec":"s15"},{"id":"fc-236-89f60b","poly":"cardio","fiche":"236","front":"Contrôle de stimulateur : contenu ?","back":"ECG, **télémétrie** (pile, sondes), lecture des mémoires, reprogrammation.","prio":"P3","sec":"s15"},{"id":"fc-236-3fb2b9","poly":"cardio","fiche":"236","front":"Stimulateur : durée de vie du boîtier ?","back":"Changement tous les **8 à 12 ans** environ.","prio":"P2","sec":"s15"},{"id":"fc-236-dd0561","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : IRM possible ?","back":"**Oui** le plus souvent (dispositifs **IRM-conditionnels**) : mode IRM avant, reprogrammation après.","prio":"P2","sec":"s15"},{"id":"fc-236-98eaa7","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : signes devant faire consulter ?","back":"**Rougeur**, **écoulement**, douleur du boîtier, **fièvre inexpliquée** (infection du matériel).","prio":"P2","sec":"s15"},{"id":"fc-236-a9a795","poly":"cardio","fiche":"236","front":"Porteur de stimulateur : documents et informations ?","back":"**Carte** du dispositif ; risque d'**interférences** électromagnétiques.","prio":"P3","sec":"s15"},{"id":"fc-236-c4cad8","poly":"cardio","fiche":"236","front":"Télésurveillance du stimulateur : intérêts ?","back":"Transmissions automatiques, **téléalertes** (dysfonctionnement, événement rythmique), moins de déplacements.","prio":"P3","sec":"s15"},{"id":"fc-237-9f823d","poly":"cardio","fiche":"237","front":"Palpitations : définition ?","back":"Perception **anormale** de battements cardiaques, normaux ou anormaux (trouble **subjectif**).","prio":"P1","sec":"s1"},{"id":"fc-237-42f282","poly":"cardio","fiche":"237","front":"Palpitations : valeur diagnostique du symptôme ?","back":"**Très peu spécifique** : de la tachycardie sinusale réflexe à la **TV**.","prio":"P1","sec":"s1"},{"id":"fc-237-ba950a","poly":"cardio","fiche":"237","front":"Palpitations : 4 buts du bilan ?","back":"**Diagnostic positif**, **étiologie**, **tolérance** et pronostic, risque d'**arythmie maligne** et de **mort subite**.","prio":"P2","sec":"s1"},{"id":"fc-237-7250c2","poly":"cardio","fiche":"237","front":"Palpitations associées à une syncope, douleur thoracique ou dyspnée : priorité ?","back":"Les palpitations **passent au second plan** derrière le symptôme plus grave.","prio":"P2","sec":"s1"},{"id":"fc-237-581d28","poly":"cardio","fiche":"237","front":"Troubles du rythme les plus fréquents donnant des palpitations ?","back":"**FA** et **flutters atriaux**, puis **tachycardies jonctionnelles**.","prio":"P2","sec":"s1"},{"id":"fc-237-c50644","poly":"cardio","fiche":"237","front":"Palpitations : 3 notions indispensables ?","back":"**ECG pendant les symptômes** (corrélation électroclinique) ; recherche d'une **cardiopathie** ; recherche des **signes de gravité**.","prio":"P1","sec":"s1"},{"id":"fc-237-888f39","poly":"cardio","fiche":"237","front":"Palpitations : place de l'interrogatoire ?","back":"**Premier temps**, indispensable ; oriente **le plus souvent** le diagnostic.","prio":"P2","sec":"s2"},{"id":"fc-237-6ba304","poly":"cardio","fiche":"237","front":"Palpitations : caractéristiques à préciser à l'interrogatoire ?","back":"**Durée**, **déclencheur**, **début et fin** (brutaux/progressifs), paroxystique ou permanent, **repos/effort**, **fréquence**, **régularité**.","prio":"P1","sec":"s2"},{"id":"fc-237-1f3e0c","poly":"cardio","fiche":"237","front":"Palpitations : antécédents à rechercher ?","back":"**Cardiopathie** (IDM, HTA, myocardiopathie) et **mort subite familiale** (Brugada, QT long, DAVD).","prio":"P2","sec":"s2"},{"id":"fc-237-1ee604","poly":"cardio","fiche":"237","front":"Palpitations : traitements à rechercher ?","back":"**Antiarythmique** ; médicament qui **allonge le QT**.","prio":"P2","sec":"s2"},{"id":"fc-237-fd9313","poly":"cardio","fiche":"237","front":"Palpitations : astuce pour caractériser le rythme ?","back":"Faire **tapoter du doigt** le rythme sur le bord d'une table.","prio":"P2","sec":"s2"},{"id":"fc-237-15796c","poly":"cardio","fiche":"237","front":"Palpitations : éléments orientant vers une tachycardie jonctionnelle ?","back":"**Début et fin brutaux**, **polyurie** en fin d'accès, démarrage au **changement brusque de position**.","prio":"P1","sec":"s2"},{"id":"fc-237-b860c3","poly":"cardio","fiche":"237","front":"Palpitations : causes extracardiaques à chercher ?","back":"**Excitants** (alcool, tabac, cocaïne, amphétamines), sympathomimétiques, hormones thyroïdiennes, **grossesse**, **hyperthyroïdie**, fièvre, déshydratation, **apnées du sommeil**.","prio":"P2","sec":"s2"},{"id":"fc-237-667b5b","poly":"cardio","fiche":"237","front":"Palpitations : priorité absolue ?","back":"Éliminer une **arythmie ventriculaire potentiellement létale** (TV, FV).","prio":"P1","sec":"s3"},{"id":"fc-237-a05e3c","poly":"cardio","fiche":"237","front":"Palpitations : antécédents personnels alarmants ?","back":"**IDM**, HTA ou cardiopathie, trouble du rythme connu, porteur de **stimulateur** ou **défibrillateur**.","prio":"P2","sec":"s3"},{"id":"fc-237-0f29c3","poly":"cardio","fiche":"237","front":"Mort subite familiale évoquant une arythmie génétique : âge ?","back":"Mort subite **du nourrisson** ou **avant 35 ans**.","prio":"P1","sec":"s3"},{"id":"fc-237-065cf3","poly":"cardio","fiche":"237","front":"Mort subite familiale précoce : arythmies génétiques et conduite ?","back":"**Brugada**, **QT long**, **DAVD** ; dresser l'**arbre généalogique**.","prio":"P2","sec":"s3"},{"id":"fc-237-322ded","poly":"cardio","fiche":"237","front":"Palpitations : signes cliniques de gravité ?","back":"**FC > 150 bpm**, **hypotension**/hypoperfusion, **angor**, **dyspnée**, signes **neurologiques**, trouble de **conscience**, **syncope**/lipothymie.","prio":"P1","sec":"s3"},{"id":"fc-237-f2edcf","poly":"cardio","fiche":"237","front":"Palpitations : signe neurologique de gravité, mécanisme ?","back":"**Infarctus cérébral** par embolie sur **FA**.","prio":"P3","sec":"s3"},{"id":"fc-237-a7dea8","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : diagnostic à retenir ?","back":"**TV jusqu'à preuve du contraire** : se préparer à réanimer.","prio":"P1","sec":"s3"},{"id":"fc-237-02ae03","poly":"cardio","fiche":"237","front":"Tachycardie très rapide avec anomalie de repolarisation : interprétation ?","back":"Urgence (SCA possible), mais **angor fonctionnel** possible, surtout si **FC > 200 bpm**.","prio":"P2","sec":"s3"},{"id":"fc-237-50f37e","poly":"cardio","fiche":"237","front":"Tachycardie à QRS fins > 150 bpm avec signes de gravité : niveau d'urgence ?","back":"**Urgence absolue**.","prio":"P1","sec":"s3"},{"id":"fc-237-852333","poly":"cardio","fiche":"237","front":"Signes de gravité des palpitations : moyen mnémotechnique ?","back":"**THADNCS** : Tachycardie > 150, Hypotension, Angor, Dyspnée, Neurologique, Conscience, Syncope.","prio":"P3","sec":"s3"},{"id":"fc-237-2f2989","poly":"cardio","fiche":"237","front":"Palpitations : ECG de repos, place et résultat habituel ?","back":"**Systématique** ; **le plus souvent normal**.","prio":"P1","sec":"s4"},{"id":"fc-237-679749","poly":"cardio","fiche":"237","front":"ECG de repos : extrasystoles supraventriculaires, que rechercher ?","back":"**FA**, **flutter** ou **tachycardie atriale** focale.","prio":"P2","sec":"s4"},{"id":"fc-237-aab24b","poly":"cardio","fiche":"237","front":"ECG de repos : extrasystole ventriculaire, que rechercher ?","back":"Une **TV**.","prio":"P2","sec":"s4"},{"id":"fc-237-a2dd49","poly":"cardio","fiche":"237","front":"ECG de repos chez un patient à palpitations : anomalies à repérer ?","back":"**Brugada**, ischémie, **préexcitation**, **QT long**, **CMH**, repolarisation précoce.","prio":"P2","sec":"s4"},{"id":"fc-237-d19336","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS fins : hypothèses ?","back":"**Jonctionnelle**, **sinusale**, **flutter** ou **tachycardie atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-6a168e","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : hypothèses ?","back":"**TV**, ou tachycardie supraventriculaire avec **anomalie de conduction**.","prio":"P2","sec":"s4"},{"id":"fc-237-293b67","poly":"cardio","fiche":"237","front":"Tachycardie irrégulière : hypothèse principale ?","back":"**Fibrillation atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-18e44b","poly":"cardio","fiche":"237","front":"Manœuvres vagales et adénosine : mécanisme ?","back":"**Blocage transitoire du nœud AV**.","prio":"P2","sec":"s4"},{"id":"fc-237-d16165","poly":"cardio","fiche":"237","front":"Test vagal ou à l'adénosine : intérêt diagnostique ?","back":"Utile **dès que le diagnostic n'est pas évident** : diagnostic précis de la tachycardie dans **la majorité des cas**.","prio":"P2","sec":"s12"},{"id":"fc-237-0bdc8f","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : arrêt brutal de la tachycardie, diagnostic ?","back":"**Tachycardie jonctionnelle** (réentrée intranodale ou voie accessoire).","prio":"P1","sec":"s4"},{"id":"fc-237-b4aa8f","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : ralentissement avec activité atriale visible, diagnostic ?","back":"**FA**, **flutter** ou **tachycardie atriale**.","prio":"P1","sec":"s4"},{"id":"fc-237-292589","poly":"cardio","fiche":"237","front":"Test vagal ou adénosine : aucun effet, diagnostic ?","back":"Évoque une **TV** (absence d'effet **en général**) ; une **dissociation AV** en fait le diagnostic de certitude.","prio":"P1","sec":"s4"},{"id":"fc-237-dd0228","poly":"cardio","fiche":"237","front":"Adénosine : contre-indications ?","back":"**Asthme**, **HTA non contrôlée** ; aussi **hypotension artérielle** et **FA sur voie accessoire**.","prio":"P1","sec":"s12"},{"id":"fc-237-c46fa9","poly":"cardio","fiche":"237","front":"Palpitations : 3 principes du diagnostic étiologique ?","back":"Chercher une **cardiopathie** ; sinon une **cause extracardiaque** ; obtenir une **corrélation électroclinique**.","prio":"P2","sec":"s5"},{"id":"fc-237-c1b402","poly":"cardio","fiche":"237","front":"Corrélation électroclinique : définition ?","back":"Concordance entre les **symptômes** et une **anomalie ECG** enregistrée simultanément.","prio":"P1","sec":"s5"},{"id":"fc-237-606bdc","poly":"cardio","fiche":"237","front":"Palpitations : examen d'imagerie systématique ?","back":"**ETT** (FEVG, cinétique, cardiopathie, taille des oreillettes).","prio":"P2","sec":"s5"},{"id":"fc-237-d45351","poly":"cardio","fiche":"237","front":"Palpitations : biologie de routine ?","back":"Notamment **ionogramme**, **NFS**, **alcoolémie**, **β-hCG**, **TSH** (ou selon le contexte).","prio":"P2","sec":"s5"},{"id":"fc-237-809c77","poly":"cardio","fiche":"237","front":"Palpitations : examens complémentaires selon le contexte ?","back":"**IRM**, **épreuve d'effort** (palpitations d'effort), **coronarographie** (doute ischémique).","prio":"P3","sec":"s5"},{"id":"fc-237-4a6275","poly":"cardio","fiche":"237","front":"Enregistrement ECG : lien entre durée et sensibilité ?","back":"Plus l'enregistrement est **long**, meilleure est la **sensibilité**.","prio":"P2","sec":"s5"},{"id":"fc-237-b1ca7b","poly":"cardio","fiche":"237","front":"Palpitations fréquentes : enregistrement adapté ?","back":"**Holter ECG 24 à 96 h**.","prio":"P1","sec":"s5"},{"id":"fc-237-baac1f","poly":"cardio","fiche":"237","front":"Palpitations peu fréquentes (< 1/semaine) : enregistrement externe adapté ?","back":"**ECG ambulatoire de longue durée**, jusqu'à **21 jours**.","prio":"P1","sec":"s5"},{"id":"fc-237-d0a3f1","poly":"cardio","fiche":"237","front":"Holter implantable : durée et position ?","back":"Surveillance de **3 à 5 ans** ; position **parasternale sous-cutanée**.","prio":"P2","sec":"s5"},{"id":"fc-237-d42308","poly":"cardio","fiche":"237","front":"Holter implantable : ce qu'il enregistre et suivi ?","back":"Asystolies, bradycardies, tachycardies ; suivi par **télécardiologie**.","prio":"P3","sec":"s5"},{"id":"fc-237-532d3f","poly":"cardio","fiche":"237","front":"Holter implantable : indication ?","back":"Crises **peu fréquentes** (surveillance de 3 à 5 ans).","prio":"P2","sec":"s5"},{"id":"fc-237-fc98ed","poly":"cardio","fiche":"237","front":"Montre connectée : type de tracé et intérêt ?","back":"Tracé **D1** (automatique ou déclenché) ; permet la **corrélation électroclinique**.","prio":"P2","sec":"s5"},{"id":"fc-237-a73bad","poly":"cardio","fiche":"237","front":"Étude électrophysiologique : intérêts diagnostiques ?","back":"**Dualité nodale**, **voie accessoire**, déclenchement d'arythmies (stimulation atriale ou ventriculaire en 2 sites).","prio":"P3","sec":"s5"},{"id":"fc-237-279aa5","poly":"cardio","fiche":"237","front":"Étude électrophysiologique : intérêt thérapeutique ?","back":"Traiter dans le même temps une arythmie atriale, une **réentrée intranodale**, une **voie accessoire**.","prio":"P3","sec":"s5"},{"id":"fc-237-0b3af4","poly":"cardio","fiche":"237","front":"Palpitations : tests pharmacologiques spécialisés cités ?","back":"**Isoprénaline**, **ajmaline**.","prio":"P3","sec":"s5"},{"id":"fc-237-fd3cb7","poly":"cardio","fiche":"237","front":"ECG de repos normal chez un patient à palpitations : rassurant ?","back":"**Non** : il faut un tracé **pendant** les palpitations.","prio":"P1","sec":"s5"},{"id":"fc-237-776bfd","poly":"cardio","fiche":"237","front":"Extrasystole : définition ?","back":"**Activation ectopique prématurée**, supraventriculaire ou ventriculaire.","prio":"P1","sec":"s6"},{"id":"fc-237-2bb649","poly":"cardio","fiche":"237","front":"Extrasystole : repos compensateur vs interpolée ?","back":"**Repos compensateur** : total = double période ; **interpolée** : pas de repos compensateur.","prio":"P2","sec":"s6"},{"id":"fc-237-919f61","poly":"cardio","fiche":"237","front":"Extrasystoles bigéminées et trigéminées : définitions ?","back":"**Bigéminées** : 1 normal / 1 ES en alternance ; **trigéminées** : 2 normaux puis 1 ES.","prio":"P2","sec":"s6"},{"id":"fc-237-b32e58","poly":"cardio","fiche":"237","front":"Extrasystoles monomorphes vs polymorphes : définitions ?","back":"**Monomorphes** : toutes identiques ; **polymorphes** : plusieurs morphologies.","prio":"P3","sec":"s6"},{"id":"fc-237-1b5747","poly":"cardio","fiche":"237","front":"Extrasystole supraventriculaire : aspect ECG ?","back":"Onde **P'** différente de la P sinusale, QRS habituellement **identique** au QRS sinusal.","prio":"P2","sec":"s6"},{"id":"fc-237-49aabb","poly":"cardio","fiche":"237","front":"Extrasystole atriale bloquée : piège clinique ?","back":"Fausse « **bradycardie au pouls** » (ex. trigéminisme atrial bloqué).","prio":"P2","sec":"s6"},{"id":"fc-237-3650f4","poly":"cardio","fiche":"237","front":"Extrasystole ventriculaire : aspect ECG ?","back":"**QRS prématuré, élargi**, sans activité atriale avant lui.","prio":"P1","sec":"s6"},{"id":"fc-237-cc244b","poly":"cardio","fiche":"237","front":"ESV à couplage court : risque ?","back":"**Phénomène R/T** : **peut déclencher** des arythmies ventriculaires **létales** (indicateur majeur de risque).","prio":"P1","sec":"s6"},{"id":"fc-237-e4dc0a","poly":"cardio","fiche":"237","front":"ESV bénignes : exemple cité ?","back":"ESV **infundibulaires ventriculaires droites**.","prio":"P3","sec":"s6"},{"id":"fc-237-5dcde4","poly":"cardio","fiche":"237","front":"Extrasystoles : sont-elles pathologiques en elles-mêmes ?","back":"**Non**, mais imposent de chercher une **cardiopathie** ou une **cause extracardiaque**.","prio":"P1","sec":"s6"},{"id":"fc-237-0d4ba0","poly":"cardio","fiche":"237","front":"Extrasystoles : causes extracardiaques ?","back":"Alcoolisation, électrocution, maladies respiratoires, **hyperthyroïdie**, troubles électrolytiques, anxiété ou dépression, **grossesse**, **apnées du sommeil**.","prio":"P2","sec":"s6"},{"id":"fc-237-bd04c2","poly":"cardio","fiche":"237","front":"Extrasystoles : bilan de base ?","back":"ECG, **ETT**, **épreuve d'effort**, **holter** (charge, morphologies, couplage).","prio":"P2","sec":"s6"},{"id":"fc-237-9b28b8","poly":"cardio","fiche":"237","front":"Extrasystoles chez un obèse, diabétique ou hypertendu : surveillance ?","back":"**Répéter les holters** pour dépister une **FA** à risque thromboembolique.","prio":"P1","sec":"s6"},{"id":"fc-237-ee3224","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : définition ?","back":"Fréquence sinusale de repos **> 100 bpm**.","prio":"P1","sec":"s7"},{"id":"fc-237-875f31","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : mode de début et de fin ?","back":"**Progressifs**.","prio":"P1","sec":"s7"},{"id":"fc-237-52ece4","poly":"cardio","fiche":"237","front":"Tachycardie sinusale adaptée : causes cardiaques ou cardiopulmonaires ?","back":"**Insuffisance cardiaque**, **embolie pulmonaire**, **épanchement péricardique**.","prio":"P2","sec":"s7"},{"id":"fc-237-f6befa","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : causes extracardiaques ?","back":"Fièvre, hypoxie, anémie, hypovolémie, hypotension, **hyperthyroïdie**, **grossesse**, **apnées du sommeil**, alcool.","prio":"P2","sec":"s7"},{"id":"fc-237-72c09e","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : 4 causes à retenir ?","back":"**Grossesse**, **hyperthyroïdie**, **apnées du sommeil**, **alcoolisme**.","prio":"P1","sec":"s7"},{"id":"fc-237-2ccb81","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : causes médicamenteuses ?","back":"Sympathomimétiques, vasodilatateurs, atropiniques ; **sevrage brutal en bêtabloquants**.","prio":"P2","sec":"s7"},{"id":"fc-237-9b99ad","poly":"cardio","fiche":"237","front":"Tachycardie sinusale inappropriée : définition ?","back":"Forme **non adaptative**, exceptionnelle, isolée (orthostatisme, anxiété).","prio":"P2","sec":"s7"},{"id":"fc-237-42f6df","poly":"cardio","fiche":"237","front":"Tachycardie sinusale : traitement ?","back":"**Traiter la cause** : nécessaire et le plus souvent **suffisant**.","prio":"P1","sec":"s7"},{"id":"fc-237-8b70e6","poly":"cardio","fiche":"237","front":"Tachycardies jonctionnelles : définition ?","back":"Tachycardies incluant la **jonction AV** : **réentrée intranodale** et **voies accessoires** (maladie de Bouveret).","prio":"P2","sec":"s8"},{"id":"fc-237-7bb3a6","poly":"cardio","fiche":"237","front":"Réentrée intranodale : terrain ?","back":"**Adolescent ou adulte jeune à cœur sain** ; tachycardie jonctionnelle la plus fréquente.","prio":"P1","sec":"s8"},{"id":"fc-237-76eea9","poly":"cardio","fiche":"237","front":"Réentrée intranodale : tableau clinique ?","back":"Début et fin **brutaux**, minutes à heures, **polyurie** en fin d'accès, parfois battements dans le cou, **bien tolérée le plus souvent**.","prio":"P1","sec":"s8"},{"id":"fc-237-c89092","poly":"cardio","fiche":"237","front":"Réentrée intranodale : comment arrêter la crise ?","back":"**Manœuvre vagale** ou **adénosine** (ou ATP).","prio":"P2","sec":"s8"},{"id":"fc-237-2872fe","poly":"cardio","fiche":"237","front":"Réentrée intranodale : 2 voies nodales et leurs périodes réfractaires ?","back":"**Voie rapide** : période réfractaire **longue** ; **voie lente** : période réfractaire **plus courte**.","prio":"P2","sec":"s8"},{"id":"fc-237-9a7b9c","poly":"cardio","fiche":"237","front":"Réentrée intranodale : mécanisme de déclenchement ?","back":"Souvent une ES atriale bloquée dans la voie rapide → descend par la **voie lente** → remonte par la voie rapide.","prio":"P3","sec":"s8"},{"id":"fc-237-067a1d","poly":"cardio","fiche":"237","front":"Réentrée intranodale en crise : aspect ECG ?","back":"Tachycardie régulière **130 à 250 bpm**, **QRS fins** le plus souvent, **P' rétrogrades négatives en inférieur**.","prio":"P1","sec":"s8"},{"id":"fc-237-7aa3b1","poly":"cardio","fiche":"237","front":"Réentrée intranodale : ECG de repos ?","back":"**Le plus souvent normal**.","prio":"P2","sec":"s8"},{"id":"fc-237-05df63","poly":"cardio","fiche":"237","front":"Réentrée intranodale : comment confirmer l'activité atriale rétrograde ?","back":"La **négativité inférieure disparaît** sur les complexes sinusaux après la crise.","prio":"P3","sec":"s8"},{"id":"fc-237-073f61","poly":"cardio","fiche":"237","front":"Voie accessoire : définition ?","back":"**Bandelette musculaire** (ex. faisceau de **Kent**) reliant directement oreillette et ventricule.","prio":"P2","sec":"s9"},{"id":"fc-237-105dea","poly":"cardio","fiche":"237","front":"Préexcitation : mécanisme ?","back":"Activation ventriculaire en **fusion** : d'abord par la voie accessoire, puis par le nœud AV.","prio":"P2","sec":"s9"},{"id":"fc-237-2634f2","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : signes ECG de repos ?","back":"**PR < 120 ms**, **onde delta**, **QRS > 120 ms**, troubles de **repolarisation**.","prio":"P2","sec":"s9"},{"id":"fc-237-0b3a64","poly":"cardio","fiche":"237","front":"Préexcitation : effet de l'atropine et des manœuvres vagales ?","back":"**Diminue** sous atropine ; **augmente** avec les manœuvres vagales.","prio":"P3","sec":"s9"},{"id":"fc-237-9a0cb9","poly":"cardio","fiche":"237","front":"Voie accessoire : évolution avec l'âge et terrain ?","back":"**Involue** habituellement avec l'âge ; **jeunes à cœur sain**.","prio":"P3","sec":"s9"},{"id":"fc-237-8429e7","poly":"cardio","fiche":"237","front":"Tachycardie orthodromique : circuit et QRS ?","back":"Descente par le **His**, remontée par la voie accessoire : **QRS fins**.","prio":"P2","sec":"s9"},{"id":"fc-237-68da80","poly":"cardio","fiche":"237","front":"Tachycardie antidromique : circuit et QRS ?","back":"Descente par la **voie accessoire**, remontée par le His : **QRS larges** préexcités.","prio":"P2","sec":"s9"},{"id":"fc-237-4f012a","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : principal danger ?","back":"**FA** conduite très vite (**super-Wolff**) → **FV**, mort subite.","prio":"P1","sec":"s9"},{"id":"fc-237-8368e8","poly":"cardio","fiche":"237","front":"Wolff-Parkinson-White : traitement réduisant le risque de mort subite ?","back":"**Ablation de la voie accessoire**.","prio":"P2","sec":"s9"},{"id":"fc-237-e413ef","poly":"cardio","fiche":"237","front":"Tachycardie sinusale vs réentrée intranodale : différences ?","back":"Sinusale : début/fin **progressifs**, P sinusales ; TRIN : **brutaux**, polyurie, **P' rétrogrades**, arrêt par vagal.","prio":"P1","sec":"s10"},{"id":"fc-237-537aa4","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS larges : piège ?","back":"La prendre pour une tachycardie avec **simple bloc de branche** alors que c'est une **TV**.","prio":"P1","sec":"s10"},{"id":"fc-237-d5f172","poly":"cardio","fiche":"237","front":"Tachycardie irrégulière à QRS très larges : quoi évoquer ?","back":"**FA sur voie accessoire** (super-Wolff) : risque de FV.","prio":"P2","sec":"s10"},{"id":"fc-237-5cd59f","poly":"cardio","fiche":"237","front":"Névrose cardiaque : définition ?","back":"Diagnostic d'**élimination** : **crainte irraisonnée de mort subite**.","prio":"P2","sec":"s10"},{"id":"fc-237-1d8ecf","poly":"cardio","fiche":"237","front":"Névrose cardiaque : critère diagnostique ?","back":"**ECG strictement normal pendant les palpitations** (monitorage prolongé).","prio":"P2","sec":"s10"},{"id":"fc-237-48f5b4","poly":"cardio","fiche":"237","front":"Névrose cardiaque : quand l'évoquer ?","back":"Examens **tous normaux**, aucune pathologie extracardiaque, signes d'**anxiété** ou de **dépression**.","prio":"P2","sec":"s10"},{"id":"fc-237-87a994","poly":"cardio","fiche":"237","front":"Palpitations : notion inacceptable sur la cause psychogène ?","back":"S'orienter **d'emblée** vers une cause psychogène **sans bilan minimal**.","prio":"P1","sec":"s10"},{"id":"fc-237-89510d","poly":"cardio","fiche":"237","front":"Tachycardie régulière mal tolérée (QRS fins ou larges) : traitement ?","back":"**Cardioversion par choc électrique externe**.","prio":"P1","sec":"s11"},{"id":"fc-237-59a119","poly":"cardio","fiche":"237","front":"Arrêt cardiaque sur TV/FV : traitement initial ?","back":"**Défibrillation** par choc électrique externe.","prio":"P1","sec":"s11"},{"id":"fc-237-9e8922","poly":"cardio","fiche":"237","front":"Arrêt cardiaque sur TV/FV après échec de 2 chocs : médicaments ?","back":"**Adrénaline IV** + **amiodarone 300 mg**.","prio":"P1","sec":"s11"},{"id":"fc-237-491b61","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : délai idéal du premier choc ?","back":"Dans les **3 minutes**.","prio":"P2","sec":"s11"},{"id":"fc-237-c65d7d","poly":"cardio","fiche":"237","front":"Défibrillation : énergie ?","back":"Jusqu'à **200 J** (biphasique) ; **360 J** (monophasique).","prio":"P3","sec":"s11"},{"id":"fc-237-77c04f","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : posologie de l'adrénaline ?","back":"**1 mg toutes les 4 minutes**, IV ou endotrachéale.","prio":"P2","sec":"s11"},{"id":"fc-237-bdadd4","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : modalités de l'amiodarone ?","back":"300 mg dilués, juste avant le **3e choc** ; puis **150 mg** si TV/FV réfractaire ou récidivante.","prio":"P3","sec":"s11"},{"id":"fc-237-3d0a1a","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : alternative à l'amiodarone ?","back":"**Lidocaïne 1,5 mg/kg** IV lente (max 3 mg/kg), si amiodarone indisponible.","prio":"P3","sec":"s11"},{"id":"fc-237-2d657b","poly":"cardio","fiche":"237","front":"Arrêt cardiaque : indication du sulfate de magnésium ?","back":"**Torsades de pointes** ou suspicion d'**hypomagnésémie** : **2 g** IV directe.","prio":"P3","sec":"s11"},{"id":"fc-237-3514e8","poly":"cardio","fiche":"237","front":"TV : effet des manœuvres vagales et de l'adénosine ?","back":"**Généralement aucun** sur la fréquence ventriculaire : ne la traitent pas.","prio":"P2","sec":"s11"},{"id":"fc-237-67dbfd","poly":"cardio","fiche":"237","front":"Tachycardie régulière à QRS fins bien tolérée : conduite ?","back":"**Enregistrer l'ECG en crise**, puis **manœuvres vagales**, puis **adénosine** si échec.","prio":"P1","sec":"s12"},{"id":"fc-237-bf6825","poly":"cardio","fiche":"237","front":"Manœuvres vagales : lesquelles ?","back":"**Valsalva**, compression d'**une seule** carotide, grand verre d'**eau froide**.","prio":"P2","sec":"s12"},{"id":"fc-237-7503df","poly":"cardio","fiche":"237","front":"Compression carotidienne : contre-indications ?","back":"**Athérome important** ou **souffle carotidien**.","prio":"P2","sec":"s12"},{"id":"fc-237-0284d1","poly":"cardio","fiche":"237","front":"Compression oculaire bilatérale : encore recommandée ?","back":"**Non** (décollement de rétine chez le myope).","prio":"P3","sec":"s12"},{"id":"fc-237-efce88","poly":"cardio","fiche":"237","front":"Adénosine : mode d'administration et durée d'effet ?","back":"**IV en flash** ; effet d'une **dizaine de secondes**.","prio":"P2","sec":"s12"},{"id":"fc-237-e5bb82","poly":"cardio","fiche":"237","front":"Adénosine : effet indésirable rare ?","back":"**Bronchospasme** intense et transitoire, même chez un non-asthmatique.","prio":"P3","sec":"s12"},{"id":"fc-237-b55c59","poly":"cardio","fiche":"237","front":"Réentrée intranodale : traitement de référence au long cours ?","back":"**Ablation de la voie lente**.","prio":"P1","sec":"s13"},{"id":"fc-237-08cfa3","poly":"cardio","fiche":"237","front":"Ablation de la voie lente : complication à connaître ?","back":"**BAV complet** (risque très faible).","prio":"P1","sec":"s13"},{"id":"fc-237-877107","poly":"cardio","fiche":"237","front":"Réentrée intranodale : options au long cours selon la gêne ?","back":"**Abstention**, « **pill in the pocket** », **ablation**.","prio":"P2","sec":"s13"},{"id":"fc-237-b48763","poly":"cardio","fiche":"237","front":"Tachycardie jonctionnelle sur voie accessoire : réduction ?","back":"**Manœuvres vagales** ou **adénosine IV** ; la préexcitation réapparaît après.","prio":"P2","sec":"s14"},{"id":"fc-237-b89da2","poly":"cardio","fiche":"237","front":"FA sur voie accessoire : adénosine ?","back":"**Contre-indiquée**.","prio":"P2","sec":"s14"},{"id":"fc-237-a9a24d","poly":"cardio","fiche":"237","front":"Après ablation d'une voie accessoire : aspect ECG ?","back":"La **préexcitation disparaît**.","prio":"P3","sec":"s14"},{"id":"fc-237-9f716d","poly":"cardio","fiche":"237","front":"Névrose cardiaque : conduite ?","back":"**Arrêter les explorations**, **rassurer**, éviter un vocabulaire inadapté (« spasmophilie ») ; **avis psychiatrique** souhaitable.","prio":"P2","sec":"s15"},{"id":"fc-237-459e1f","poly":"cardio","fiche":"237","front":"Extrasystoles : traitement propre précisé par le Collège ?","back":"**Aucun** : rechercher la cardiopathie ou la cause extracardiaque.","prio":"P2","sec":"s15"},{"id":"fc-238-dbe4ee","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quelles sont les deux grandes familles ?","back":"Souffle **organique** (anomalie anatomique du cœur) · souffle **anorganique** = fonctionnel = **innocent** (cœur sain).","prio":"P1","sec":"s1"},{"id":"fc-238-5b75e2","poly":"cardio","fiche":"238","front":"Souffle innocent : pourquoi l'entend-on chez l'enfant et pas chez l'adulte ?","back":"Cœur **plus près du stéthoscope** + cavités **plus petites** ; il disparaît à l'âge adulte (persiste parfois chez le jeune adulte).","prio":"P2","sec":"s1"},{"id":"fc-238-d1ccdf","poly":"cardio","fiche":"238","front":"Souffle innocent avant 3 mois : quel mécanisme possible ?","back":"Accélération du flux dans les **branches pulmonaires**, de calibre différent du tronc à cet âge.","prio":"P3","sec":"s1"},{"id":"fc-238-19305d","poly":"cardio","fiche":"238","front":"Malformations cardiaques congénitales : quelle fréquence à la naissance ?","back":"**1 %** des enfants.","prio":"P1","sec":"s1"},{"id":"fc-238-9f6ffe","poly":"cardio","fiche":"238","front":"Souffle chez le nourrisson : quelle proportion est organique ?","back":"**90 %**.","prio":"P1","sec":"s1"},{"id":"fc-238-89e27b","poly":"cardio","fiche":"238","front":"Souffle chez l'enfant d'âge scolaire : quelle proportion est fonctionnelle ?","back":"**Plus des trois quarts**.","prio":"P1","sec":"s1"},{"id":"fc-238-106e24","poly":"cardio","fiche":"238","front":"Souffle fonctionnel : quelle proportion des enfants d'âge scolaire en ont un à un moment de l'enfance ?","back":"**Un tiers à la moitié**.","prio":"P2","sec":"s1"},{"id":"fc-238-d2464c","poly":"cardio","fiche":"238","front":"Souffles innocents : à quel âge se voient-ils surtout ?","back":"À l'**âge scolaire** ; **rarement** chez le nourrisson et le nouveau-né.","prio":"P2","sec":"s1"},{"id":"fc-238-ad21b4","poly":"cardio","fiche":"238","front":"Souffle systolique asymptomatique découvert dans la 2e enfance : quelle origine le plus souvent ?","back":"Le plus souvent **innocent**.","prio":"P2","sec":"s1"},{"id":"fc-238-35db94","poly":"cardio","fiche":"238","front":"Pays occidentaux : quelle est presque toujours la cause d'une cardiopathie organique de l'enfant ?","back":"Une **malformation congénitale** (plus quelques rares cardiomyopathies hypertrophiques ou dilatées).","prio":"P1","sec":"s1"},{"id":"fc-238-a8efa6","poly":"cardio","fiche":"238","front":"Cardiopathie acquise de l'enfant en Occident : quelle fréquence ?","back":"**Exceptionnelle** : les valvulopathies rhumatismales y ont totalement disparu.","prio":"P3","sec":"s1"},{"id":"fc-238-de22ce","poly":"cardio","fiche":"238","front":"Cardiomyopathie ou myocardite comme cause de souffle de l'enfant : quelle fréquence ?","back":"**Rare**.","prio":"P3","sec":"s1"},{"id":"fc-238-623f85","poly":"cardio","fiche":"238","front":"« Souffle au cœur » de l'enfant : pourquoi ne jamais le banaliser d'emblée ?","back":"Le plus souvent innocent, mais il peut être le **seul signe d'appel** d'une cardiopathie congénitale (et source d'anxiété majeure pour les parents).","prio":"P2","sec":"s1"},{"id":"fc-238-6a2208","poly":"cardio","fiche":"238","front":"Auscultation de l'enfant : pourquoi est-elle souvent difficile ?","back":"**Cœur rapide** ; **cris, pleurs, agitation** → distraire l'enfant (jouets, sucette), **stéthoscope pédiatrique**.","prio":"P2","sec":"s2"},{"id":"fc-238-3fc813","poly":"cardio","fiche":"238","front":"Rythme irrégulier chez l'enfant : quelle cause physiologique, et que faire au moindre doute ?","back":"**Arythmie sinusale respiratoire** (parfois très marquée) ; au moindre doute → **ECG**.","prio":"P2","sec":"s2"},{"id":"fc-238-fd9843","poly":"cardio","fiche":"238","front":"Auscultation de l'enfant : quels foyers ajouter aux 4 foyers classiques ?","back":"Région **sous-claviculaire gauche** + **fontanelle antérieure** chez le nourrisson.","prio":"P1","sec":"s2"},{"id":"fc-238-310338","poly":"cardio","fiche":"238","front":"Enfant : que signifie un DB2 au bord sternal gauche variable avec la respiration ?","back":"Fréquent et **physiologique**.","prio":"P1","sec":"s2"},{"id":"fc-238-770fb6","poly":"cardio","fiche":"238","front":"Enfant : quelles causes évoquer devant un DB2 large et fixe ?","back":"**Communication interatriale** ou **bloc de branche droit** (anormal).","prio":"P1","sec":"s2"},{"id":"fc-238-3ee1d7","poly":"cardio","fiche":"238","front":"Enfant : que peut traduire un éclat de B2 au bord sternal gauche ?","back":"Une **HTAP** (pression pulmonaire anormalement élevée).","prio":"P1","sec":"s2"},{"id":"fc-238-f6fe99","poly":"cardio","fiche":"238","front":"Enfant : B3 à l'apex, quelle signification ?","back":"Fréquent (**50 %** des cas) et **physiologique**.","prio":"P1","sec":"s2"},{"id":"fc-238-9de1f7","poly":"cardio","fiche":"238","front":"Enfant : clic mésosystolique apexien, quel diagnostic ?","back":"**Prolapsus mitral**.","prio":"P2","sec":"s2"},{"id":"fc-238-790ed7","poly":"cardio","fiche":"238","front":"Enfant : clic protosystolique, que traduit-il ?","back":"Bruit anormal d'ouverture valvulaire : **sténose valvulaire** aortique ou pulmonaire.","prio":"P1","sec":"s2"},{"id":"fc-238-d0ceb3","poly":"cardio","fiche":"238","front":"Enfant : galop avec B3 associé au souffle, quelle conduite ?","back":"**Anormal** → avis spécialisé.","prio":"P2","sec":"s2"},{"id":"fc-238-6c070e","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : l'intensité est-elle corrélée à la gravité ?","back":"**Généralement non** : cardiopathie grave possible **sans souffle** ; **petite CIV** (mineure) = souffle **intense**.","prio":"P1","sec":"s2"},{"id":"fc-238-30e459","poly":"cardio","fiche":"238","front":"Nouveau-né, nourrisson : quels symptômes font suspecter une cardiopathie ?","back":"**Cyanose** et/ou **insuffisance cardiaque**.","prio":"P1","sec":"s3"},{"id":"fc-238-b1e307","poly":"cardio","fiche":"238","front":"Cyanose du nouveau-né : quelles causes non hypoxiques évoquer ?","back":"**Hypothermie** ou **hypoglycémie**.","prio":"P1","sec":"s3"},{"id":"fc-238-fdf279","poly":"cardio","fiche":"238","front":"Cyanose : quel examen affirme l'hypoxie ?","back":"La **saturation cutanée en O₂** (réfractaire à l'O₂ si cardiaque).","prio":"P1","sec":"s3"},{"id":"fc-238-928a12","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quelles 3 manifestations ?","back":"**Difficultés alimentaires** ; **retard staturopondéral** ; **signes respiratoires** (polypnée, tirage, toux).","prio":"P1","sec":"s3"},{"id":"fc-238-3f2d59","poly":"cardio","fiche":"238","front":"Enfant plus grand : quels symptômes font suspecter une cardiopathie ?","back":"**Infections respiratoires à répétition**, **dyspnée d'effort**, **fatigabilité** (+ mêmes symptômes que le nourrisson, plus rarement).","prio":"P2","sec":"s3"},{"id":"fc-238-68155b","poly":"cardio","fiche":"238","front":"Enfant plus grand : syncope ou douleur thoracique d'effort, quelle cause cardiaque évoquer ?","back":"**Obstacle à l'éjection du VG** : sténose aortique, cardiomyopathie obstructive (symptômes **rares**).","prio":"P2","sec":"s3"},{"id":"fc-238-83f482","poly":"cardio","fiche":"238","front":"Enfant plus grand : quels signes généraux peuvent révéler une cardiopathie ?","back":"Parfois altération de l'état général : **anorexie**, **asthénie**, **douleurs abdominales**.","prio":"P3","sec":"s3"},{"id":"fc-238-418465","poly":"cardio","fiche":"238","front":"Enfant sans symptôme : quel signe d'examen révèle le plus souvent une cardiopathie ?","back":"Un **souffle** (à n'importe quel âge) ou une **anomalie des bruits du cœur**.","prio":"P2","sec":"s3"},{"id":"fc-238-8ec4a1","poly":"cardio","fiche":"238","front":"Nourrisson, enfant : quel est le signe d'insuffisance cardiaque le plus pertinent ?","back":"L'**hépatomégalie**.","prio":"P1","sec":"s3"},{"id":"fc-238-a42f06","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque de l'enfant : que dire des œdèmes des membres inférieurs ?","back":"**Exceptionnels**.","prio":"P1","sec":"s3"},{"id":"fc-238-32cded","poly":"cardio","fiche":"238","front":"Enfant : pouls absent, surtout fémoral, quel diagnostic évoquer d'emblée ?","back":"**Coarctation aortique**.","prio":"P1","sec":"s3"},{"id":"fc-238-784a3f","poly":"cardio","fiche":"238","front":"Quels signes extracardiaques peuvent révéler une cardiopathie de l'enfant ?","back":"**AVC** ; **fièvre au long cours** ; **cassure de la courbe de croissance pondérale**.","prio":"P2","sec":"s3"},{"id":"fc-238-d91d7e","poly":"cardio","fiche":"238","front":"Syndrome polymalformatif : quel examen cardiaque, et dans quels cas ?","back":"**Échocardiographie systématique** au bilan, avec ou sans symptôme, avec ou sans souffle.","prio":"P1","sec":"s3"},{"id":"fc-238-0e02fa","poly":"cardio","fiche":"238","front":"Quels contextes imposent le cardiopédiatre même sans souffle ?","back":"**Syndrome polymalformatif** ; **maladie génétique familiale** touchant cœur/gros vaisseaux (ex. Marfan) ; **cardiopathie congénitale** chez un apparenté du 1er degré.","prio":"P1","sec":"s3"},{"id":"fc-238-d26270","poly":"cardio","fiche":"238","front":"Cardiopédiatre : quels examens pratique-t-il pour poser le diagnostic ?","back":"**Échocardiographie-doppler**, souvent avec un **ECG** ; diagnostic le plus souvent posé d'emblée.","prio":"P2","sec":"s3"},{"id":"fc-238-c15498","poly":"cardio","fiche":"238","front":"Citer les syndromes le plus souvent associés aux cardiopathies congénitales ?","back":"**Trisomie 21**, **DiGeorge**, **Turner**, **Williams-Beuren**, **Noonan**, **CHARGE**, **Marfan** (« Tata dit toujours : Willy ne charge mal »).","prio":"P2","sec":"s3"},{"id":"fc-238-6b4409","poly":"cardio","fiche":"238","front":"Syndrome de DiGeorge : quelle anomalie génétique ?","back":"Microdélétion **22q11**.","prio":"P2","sec":"s3"},{"id":"fc-238-28119f","poly":"cardio","fiche":"238","front":"Syndrome de Turner : quel caryotype ?","back":"**45,X0**.","prio":"P2","sec":"s3"},{"id":"fc-238-93a44c","poly":"cardio","fiche":"238","front":"Syndrome de Williams-Beuren : quelle anomalie génétique ?","back":"Microdélétion du **chromosome 7**.","prio":"P2","sec":"s3"},{"id":"fc-238-4d1ed8","poly":"cardio","fiche":"238","front":"Syndrome CHARGE : que regroupe-t-il ?","back":"**Colobome**, **cardiopathie**, **atrésie des choanes**, **retard** de croissance et de développement, **hypoplasie génitale**, anomalies de l'**oreille** ou surdité.","prio":"P3","sec":"s3"},{"id":"fc-238-85b71a","poly":"cardio","fiche":"238","front":"Trisomie 21 : quelle cardiopathie est citée ?","back":"Le **canal atrioventriculaire**.","prio":"P2","sec":"s3"},{"id":"fc-238-b80a7d","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : les signes fonctionnels sont-ils habituellement présents ?","back":"**Souvent absents** : découverte **fortuite** lors d'un examen systématique.","prio":"P2","sec":"s4"},{"id":"fc-238-c0e360","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quel signe fonctionnel est le plus fréquent ?","back":"La **dyspnée d'effort**.","prio":"P2","sec":"s4"},{"id":"fc-238-75e923","poly":"cardio","fiche":"238","front":"Malaises de l'enfant : sont-ils souvent cardiaques ?","back":"**Assez rarement** : spasmes du sanglot (petit nourrisson), malaises vagaux (grand enfant, adolescent).","prio":"P2","sec":"s4"},{"id":"fc-238-127815","poly":"cardio","fiche":"238","front":"Syncopes du BAV congénital ou des canalopathies : par quels examens les diagnostiquer ?","back":"**ECG** et **holter**.","prio":"P2","sec":"s4"},{"id":"fc-238-6eef2d","poly":"cardio","fiche":"238","front":"Citer des canalopathies pouvant donner des syncopes chez l'enfant ?","back":"**QT long congénital**, **Brugada**…","prio":"P3","sec":"s4"},{"id":"fc-238-25d859","poly":"cardio","fiche":"238","front":"Douleurs thoraciques de l'enfant : sont-elles souvent cardiaques ?","back":"Fréquentes mais **exceptionnellement cardiaques** (à l'inverse de l'adulte).","prio":"P2","sec":"s4"},{"id":"fc-238-d35efa","poly":"cardio","fiche":"238","front":"Décrire un souffle de l'enfant : quels caractères analyser ?","back":"**T**emps, **D**urée, **I**ntensité, **F**rémissement, **T**opographie, **I**rradiations, **V**ariabilité (+ bruits du cœur associés).","prio":"P1","sec":"s4"},{"id":"fc-238-f5f9b4","poly":"cardio","fiche":"238","front":"Souffle systolique : quelles durées possibles ?","back":"**Proto-**, **méso-**, **télé-** ou **holosystolique**.","prio":"P2","sec":"s4"},{"id":"fc-238-26eec6","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quelles irradiations rechercher ?","back":"Dans le **dos** ; en **écharpe** de la base vers l'apex ; en **rayon de roue** sur tout le précordium.","prio":"P2","sec":"s4"},{"id":"fc-238-d26749","poly":"cardio","fiche":"238","front":"Variabilité d'un souffle : avec quelles manœuvres la rechercher ?","back":"**Respiration**, **position** (couché, assis, debout), **compression** d'une carotide ou d'une jugulaire (point très important).","prio":"P1","sec":"s4"},{"id":"fc-238-d85b1c","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 2/6 ?","back":"**Faible**, mais entendu **tout de suite**.","prio":"P2","sec":"s4"},{"id":"fc-238-3060f1","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 3/6 ?","back":"Souffle **fort**.","prio":"P2","sec":"s4"},{"id":"fc-238-455e05","poly":"cardio","fiche":"238","front":"Cotation d'intensité : que signifie 4/6 ?","back":"Avec **thrill**, ou entendu avec le **rebord** du stéthoscope.","prio":"P1","sec":"s4"},{"id":"fc-238-5c72da","poly":"cardio","fiche":"238","front":"Cotation d'intensité : comment distinguer 5/6 et 6/6 ?","back":"Entendus à distance du thorax : **5/6 avec** stéthoscope ; **6/6 sans** stéthoscope.","prio":"P2","sec":"s4"},{"id":"fc-238-fdab57","poly":"cardio","fiche":"238","front":"Souffle variable dans le temps et avec la position : quelle orientation ?","back":"**Pratiquement toujours innocent** (mais cette variabilité manque parfois dans un souffle innocent).","prio":"P1","sec":"s4"},{"id":"fc-238-39a8a9","poly":"cardio","fiche":"238","front":"Souffle bruyant et largement irradié : quelle orientation ?","back":"**A priori organique** (les souffles innocents irradient peu).","prio":"P1","sec":"s4"},{"id":"fc-238-929b55","poly":"cardio","fiche":"238","front":"Souffle diastolique ou double souffle chez l'enfant : quelle orientation ?","back":"**Toujours organique**.","prio":"P1","sec":"s4"},{"id":"fc-238-bb94b2","poly":"cardio","fiche":"238","front":"Souffle frémissant chez l'enfant : quelle orientation ?","back":"**Toujours organique**.","prio":"P1","sec":"s4"},{"id":"fc-238-665db5","poly":"cardio","fiche":"238","front":"Souffle innocent systolodiastolique : lequel ?","back":"Le souffle « **veineux** » du cou (le souffle innocent est presque toujours systolique).","prio":"P2","sec":"s4"},{"id":"fc-238-5eac76","poly":"cardio","fiche":"238","front":"Souffle entendu ou frémissant dans le cou et en sus-sternal : quelle orientation ?","back":"Probable **obstacle aortique**.","prio":"P2","sec":"s4"},{"id":"fc-238-79b5e2","poly":"cardio","fiche":"238","front":"Souffle de l'enfant entendu dans le dos : quelle orientation ?","back":"**Obstacle pulmonaire**.","prio":"P1","sec":"s4"},{"id":"fc-238-f09318","poly":"cardio","fiche":"238","front":"Souffle panradiant à partir de la région mésocardiaque : quelle orientation ?","back":"**CIV**.","prio":"P1","sec":"s4"},{"id":"fc-238-c536ea","poly":"cardio","fiche":"238","front":"Souffle systolique de l'enfant : quels caractères interdisent de l'étiqueter innocent ?","back":"**Holo-** ou **télésystolique**, irradié dans le **dos**, **frémissant**, ou coté **≥ 3/6**.","prio":"P1","sec":"s4"},{"id":"fc-238-4ddc65","poly":"cardio","fiche":"238","front":"Cyanose : à partir de quelle SaO₂ devient-elle cliniquement visible ?","back":"Quand la SaO₂ est **< 85 %**.","prio":"P1","sec":"s5"},{"id":"fc-238-05794b","poly":"cardio","fiche":"238","front":"Cyanose discrète : comment la confirmer ?","back":"Au **saturomètre de pouls** (difficile à voir si SaO₂ transcutanée **> 80 à 85 %**).","prio":"P2","sec":"s5"},{"id":"fc-238-60a0d5","poly":"cardio","fiche":"238","front":"Cyanose : où la chercher ?","back":"**Lèvres**, **muqueuse buccale**, **ongles**.","prio":"P2","sec":"s5"},{"id":"fc-238-f14867","poly":"cardio","fiche":"238","front":"Hypoxie : comment distinguer origine cardiaque et bronchopulmonaire ?","back":"**Cardiaque** = **réfractaire** à l'O₂ (inchangée sous O₂ **100 %**) ; **bronchopulmonaire** = sensible à l'O₂.","prio":"P1","sec":"s5"},{"id":"fc-238-c480a0","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quels symptômes digestifs ?","back":"**Difficultés alimentaires**, **vomissements** après les biberons, **stagnation ou perte de poids**.","prio":"P1","sec":"s5"},{"id":"fc-238-cb7306","poly":"cardio","fiche":"238","front":"Insuffisance cardiaque du nourrisson : quels signes à l'examen ?","back":"**Polypnée de repos**, **tachycardie**, **hépatomégalie** (signe majeur).","prio":"P1","sec":"s5"},{"id":"fc-238-90bcbf","poly":"cardio","fiche":"238","front":"Retard staturopondéral du nourrisson cardiaque : dans quelles cardiopathies est-il fréquent ?","back":"Les **larges shunts** (biberons mal pris, dyspnée, sueurs) → la **courbe de poids** est clé.","prio":"P2","sec":"s5"},{"id":"fc-238-ee0ae7","poly":"cardio","fiche":"238","front":"Fréquence cardiaque de l'enfant : que peut traduire un rythme rapide au repos ?","back":"Une **insuffisance cardiaque** (la FC baisse normalement avec l'âge).","prio":"P2","sec":"s5"},{"id":"fc-238-deafab","poly":"cardio","fiche":"238","front":"Enfant : comment mesurer la PA ?","back":"**Brassard pédiatrique** adapté à la taille et à l'âge ; au **membre inférieur autant qu'au supérieur**.","prio":"P1","sec":"s5"},{"id":"fc-238-5802df","poly":"cardio","fiche":"238","front":"Pouls de l'enfant : quelle comparaison faire ?","back":"Présence et amplitude des **huméraux** vs **fémoraux**.","prio":"P1","sec":"s5"},{"id":"fc-238-2c75c6","poly":"cardio","fiche":"238","front":"Enfant avec HTA et pouls fémoraux absents : quel diagnostic d'emblée ?","back":"**Coarctation aortique**.","prio":"P1","sec":"s5"},{"id":"fc-238-0f371b","poly":"cardio","fiche":"238","front":"Frémissement (thrill) précordial ou sus-sternal chez l'enfant : quelle valeur ?","back":"**Toujours pathologique**.","prio":"P1","sec":"s5"},{"id":"fc-238-ca03e1","poly":"cardio","fiche":"238","front":"Citer les signes qui imposent d'adresser l'enfant au cardiopédiatre (un seul suffit) ?","back":"**Cyanose**, **IC**, **retard staturopondéral** inexpliqué, **HTA**, **pouls fémoraux** anormaux, **frémissement**, **DB2 fixe**, **éclat de B2**, **clic protosystolique**, **galop**.","prio":"P1","sec":"s5"},{"id":"fc-238-efa5e5","poly":"cardio","fiche":"238","front":"Combien de signes d'alerte faut-il pour adresser un enfant au cardiopédiatre ?","back":"**Un seul** (ne pas l'adresser = notion inacceptable).","prio":"P1","sec":"s5"},{"id":"fc-238-4ae6e6","poly":"cardio","fiche":"238","front":"Cardiopédiatre devant un signe d'alerte : quels examens ?","back":"**Échocardiographie dans tous les cas**, un **ECG**, **rarement** une radiographie thoracique.","prio":"P2","sec":"s5"},{"id":"fc-238-229adb","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : qu'est-ce qui suffit le plus souvent à trancher innocent ou organique ?","back":"**Interrogatoire** + bon **examen** (surtout bonne **auscultation**) ; échocardiographie **au moindre doute**.","prio":"P2","sec":"s6"},{"id":"fc-238-30a5e6","poly":"cardio","fiche":"238","front":"ECG et radiographie thoracique devant un souffle de l'enfant : quelle valeur ?","back":"Une simple **valeur d'orientation**.","prio":"P2","sec":"s6"},{"id":"fc-238-62170b","poly":"cardio","fiche":"238","front":"Souffle de l'enfant : quel est l'examen clé du diagnostic ?","back":"L'**échocardiographie**.","prio":"P1","sec":"s6"},{"id":"fc-238-6020c3","poly":"cardio","fiche":"238","front":"Radiographie de l'enfant : quel piège devant une cardiomégalie ?","back":"**Fausse cardiomégalie** due au **thymus** superposé.","prio":"P2","sec":"s6"},{"id":"fc-238-9d6c9d","poly":"cardio","fiche":"238","front":"Radiographie : cardiomégalie vraie chez l'enfant, que permet-elle de dire ?","back":"Une **cardiopathie**, sans en préciser la nature (malformative, plus rarement cardiomyopathie ou myocardite aiguë).","prio":"P3","sec":"s6"},{"id":"fc-238-c17846","poly":"cardio","fiche":"238","front":"Radiographie : arc moyen gauche saillant, quelle signification ?","back":"Tronc de l'artère pulmonaire dilaté → **shunt gauche-droite**.","prio":"P2","sec":"s6"},{"id":"fc-238-d86a4a","poly":"cardio","fiche":"238","front":"Radiographie : arc moyen gauche concave, quelle signification ?","back":"Voie pulmonaire proximale **hypoplasique** (ex. **tétralogie de Fallot**).","prio":"P2","sec":"s6"},{"id":"fc-238-464b4f","poly":"cardio","fiche":"238","front":"Radiographie : pédicule vasculaire étroit, quelle signification ?","back":"**Anomalie de position** des gros vaisseaux.","prio":"P3","sec":"s6"},{"id":"fc-238-016ec4","poly":"cardio","fiche":"238","front":"Radiographie : hypervascularisation pulmonaire, quelle signification ?","back":"**Hyperdébit** pulmonaire → **shunt gauche-droite**.","prio":"P2","sec":"s6"},{"id":"fc-238-921bea","poly":"cardio","fiche":"238","front":"Radiographie : hypovascularisation pulmonaire, quelle signification ?","back":"**Obstacle** sur la voie pulmonaire.","prio":"P2","sec":"s6"},{"id":"fc-238-65560a","poly":"cardio","fiche":"238","front":"ECG de l'enfant : comment sont l'axe de QRS et le PR par rapport à l'adulte ?","back":"Axe **plus droit** ; PR **plus court**.","prio":"P3","sec":"s6"},{"id":"fc-238-2d59ec","poly":"cardio","fiche":"238","front":"ECG de l'enfant : comment varie la fréquence cardiaque ?","back":"D'autant **plus rapide** que l'enfant est **jeune**.","prio":"P3","sec":"s6"},{"id":"fc-238-7072bd","poly":"cardio","fiche":"238","front":"ECG de l'enfant : évolution des ondes T en précordiales droites ?","back":"**Positives** à la naissance, **négatives** vers la fin de la 1re semaine, puis **négatives de V1 à V4** toute l'enfance (normal).","prio":"P2","sec":"s6"},{"id":"fc-238-f17059","poly":"cardio","fiche":"238","front":"Échocardiographie de l'enfant : quelles conditions d'un diagnostic fiable ?","back":"Appareil performant, **capteurs pédiatriques**, **opérateur expérimenté** formé aux cardiopathies congénitales.","prio":"P3","sec":"s6"},{"id":"fc-238-c845bd","poly":"cardio","fiche":"238","front":"Holter ECG chez l'enfant : quelles indications ?","back":"Troubles du rythme **idiopathiques** ou **postopératoires**.","prio":"P3","sec":"s6"},{"id":"fc-238-e3b988","poly":"cardio","fiche":"238","front":"Épreuve d'effort chez l'enfant : quelles modalités ?","back":"**Tapis roulant** chez le petit, **bicyclette ergométrique**.","prio":"P3","sec":"s6"},{"id":"fc-238-fb1438","poly":"cardio","fiche":"238","front":"IRM cardiaque chez l'enfant : quel intérêt particulier ?","back":"Très performante, notamment pour les **gros vaisseaux intrathoraciques**.","prio":"P3","sec":"s6"},{"id":"fc-238-e1e6a7","poly":"cardio","fiche":"238","front":"Scanner cardiaque de l'enfant : quel inconvénient par rapport à l'IRM ?","back":"**Irradiant** (bonne résolution spatiale).","prio":"P3","sec":"s6"},{"id":"fc-238-4e87b7","poly":"cardio","fiche":"238","front":"Cathétérisme cardiaque de l'enfant : quelle principale utilisation aujourd'hui ?","back":"Le **cathétérisme interventionnel** (peu d'indications diagnostiques : bilan préopératoire des cardiopathies complexes).","prio":"P2","sec":"s6"},{"id":"fc-238-b2adbe","poly":"cardio","fiche":"238","front":"Cathétérisme cardiaque de l'enfant : dans quelles conditions avant 10 ans ?","back":"En général sous **anesthésie générale**.","prio":"P3","sec":"s6"},{"id":"fc-238-cb55cd","poly":"cardio","fiche":"238","front":"Souffle innocent : quel temps du cycle ?","back":"**Systolique** (jamais diastolique), ou parfois **continu**.","prio":"P1","sec":"s7"},{"id":"fc-238-37b416","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle durée dans la systole ?","back":"**Proto-** ou **mésosystolique**, **jamais télésystolique** ; éjectionnel, **bref** (1er tiers de la systole).","prio":"P1","sec":"s7"},{"id":"fc-238-e64a40","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle intensité ?","back":"**Faible** : **< 3/6**, souvent variable avec la position.","prio":"P1","sec":"s7"},{"id":"fc-238-16399a","poly":"cardio","fiche":"238","front":"Souffle innocent : quel timbre ?","back":"**Doux**, parfois **musical**.","prio":"P2","sec":"s7"},{"id":"fc-238-2affa9","poly":"cardio","fiche":"238","front":"Souffle innocent : irradiation et frémissement ?","back":"**Ni irradié, ni frémissant**.","prio":"P1","sec":"s7"},{"id":"fc-238-767afb","poly":"cardio","fiche":"238","front":"Souffle innocent : quel reste de l'examen exige-t-il ?","back":"Souffle **isolé**, asymptomatique ; B1 et B2 normaux (DB2 variable possible) ; **pouls fémoraux perçus** ; **PA normale**.","prio":"P1","sec":"s7"},{"id":"fc-238-0b0fc5","poly":"cardio","fiche":"238","front":"Souffle innocent : combien de critères doivent être réunis ?","back":"**Tous** (un seul critère d'organicité suffit à adresser).","prio":"P1","sec":"s7"},{"id":"fc-238-d4a034","poly":"cardio","fiche":"238","front":"Quelles situations hémodynamiques favorisent un souffle innocent ?","back":"Tout ce qui **augmente le débit cardiaque** : **fièvre**, **effort**, **émotion**, **anémie**, **hyperthyroïdie**.","prio":"P1","sec":"s7"},{"id":"fc-238-4ff602","poly":"cardio","fiche":"238","front":"Quelles anomalies morphologiques favorisent un souffle innocent ?","back":"Syndrome du « **dos droit** » ou « **dos plat** », **thorax en entonnoir**, **scolioses**.","prio":"P3","sec":"s7"},{"id":"fc-238-dcf7c4","poly":"cardio","fiche":"238","front":"Souffle innocent : que montrent radiographie, ECG et ETT ?","back":"Un **cœur normal**.","prio":"P2","sec":"s7"},{"id":"fc-238-61a373","poly":"cardio","fiche":"238","front":"Enfant fébrile avec souffle systolique irradié dans le dos : conclusion ?","back":"**Pas innocent** (tous les critères ne sont pas remplis) → **cardiopédiatre**.","prio":"P1","sec":"s7"},{"id":"fc-238-e9a6fd","poly":"cardio","fiche":"238","front":"Absence de variabilité avec la position : élimine-t-elle un souffle innocent ?","back":"**Non** : la variabilité est **inconstante**.","prio":"P2","sec":"s7"},{"id":"fc-238-ff1e93","poly":"cardio","fiche":"238","front":"Nouveau-né : définition de la période ?","back":"De la **naissance** à la **fin du 2e mois**.","prio":"P2","sec":"s8"},{"id":"fc-238-c99989","poly":"cardio","fiche":"238","front":"Coarctation aortique néonatale : quand apparaissent les symptômes ?","back":"À la **fermeture du canal artériel** (parfois dès les premiers jours de vie).","prio":"P2","sec":"s8"},{"id":"fc-238-05ff39","poly":"cardio","fiche":"238","front":"Coarctation néonatale : quels signes cliniques clés ?","back":"**Pouls fémoraux abolis** ; tableau **bruyant** ; souffle systolique doux **sous-claviculaire gauche** irradiant en **interscapulaire**.","prio":"P2","sec":"s8"},{"id":"fc-238-2a2cde","poly":"cardio","fiche":"238","front":"Coarctation néonatale : quel traitement ?","back":"**Chirurgie urgente**.","prio":"P2","sec":"s8"},{"id":"fc-238-35f39c","poly":"cardio","fiche":"238","front":"Quelle est la cause la plus classique de cyanose néonatale ?","back":"La **transposition des gros vaisseaux** (sans souffle ; urgence cardiologique néonatale type).","prio":"P1","sec":"s8"},{"id":"fc-238-9c32c9","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire serrée néonatale : quel mécanisme de la cyanose ?","back":"**Shunt droite-gauche** par le **foramen ovale perméable**.","prio":"P2","sec":"s8"},{"id":"fc-238-7fac4e","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire : quel souffle ?","back":"Systolique **râpeux** au foyer pulmonaire **avec clic protosystolique**.","prio":"P2","sec":"s8"},{"id":"fc-238-9adc7a","poly":"cardio","fiche":"238","front":"Cardiopathies complexes néonatales : quel souffle, et exemples ?","back":"Souffle **absent ou faible** ; ex. **ventricule unique**, **tronc artériel commun**.","prio":"P3","sec":"s8"},{"id":"fc-238-e1b014","poly":"cardio","fiche":"238","front":"Nourrisson : définition de la période ?","back":"De **2 mois** à l'**âge de la marche**.","prio":"P2","sec":"s8"},{"id":"fc-238-8f3d93","poly":"cardio","fiche":"238","front":"Petite CIV restrictive : quel souffle ?","back":"**Holosystolique**, **râpeux**, **intense**, parasternal gauche, en **rayons de roue**.","prio":"P2","sec":"s8"},{"id":"fc-238-363b29","poly":"cardio","fiche":"238","front":"CIV large : quelle auscultation ?","back":"Souffle **faible** + **B1 fort** à la pointe.","prio":"P2","sec":"s8"},{"id":"fc-238-1f3d89","poly":"cardio","fiche":"238","front":"Persistance du canal artériel : quel souffle ?","back":"**Continu** au bord gauche du sternum, crescendo en systole, decrescendo en diastole.","prio":"P2","sec":"s8"},{"id":"fc-238-d84d8b","poly":"cardio","fiche":"238","front":"Quelle est la cardiopathie cyanogène la plus fréquente ?","back":"La **tétralogie de Fallot**.","prio":"P1","sec":"s8"},{"id":"fc-238-becca8","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : quand apparaît la cyanose ?","back":"**Retardée** (quelques semaines ou mois) ; diagnostic en général à la naissance (souffle) ou en anténatal.","prio":"P2","sec":"s8"},{"id":"fc-238-030acf","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : quel souffle ?","back":"Systolique **râpeux** au foyer pulmonaire **sans clic**.","prio":"P2","sec":"s8"},{"id":"fc-238-b80b27","poly":"cardio","fiche":"238","front":"Souffle râpeux au foyer pulmonaire : quel signe distingue sténose valvulaire et Fallot ?","back":"Le **clic protosystolique** : présent dans la sténose valvulaire, **absent** dans le Fallot.","prio":"P2","sec":"s8"},{"id":"fc-238-ce47ce","poly":"cardio","fiche":"238","front":"Tétralogie de Fallot : à quel âge la corriger ?","back":"**Entre 6 mois et 1 an**.","prio":"P2","sec":"s8"},{"id":"fc-238-185d25","poly":"cardio","fiche":"238","front":"2e enfance : quelle tranche d'âge ?","back":"De **2 à 16 ans**.","prio":"P2","sec":"s8"},{"id":"fc-238-0ceaca","poly":"cardio","fiche":"238","front":"CIA : quelle auscultation ?","back":"Souffle systolique au foyer pulmonaire (**hyperdébit**), souvent avec **DB2 fixe et constant**.","prio":"P2","sec":"s8"},{"id":"fc-238-87d2ca","poly":"cardio","fiche":"238","front":"CIA : quel mécanisme du dédoublement de B2 ?","back":"**Fermeture retardée** de la valve pulmonaire.","prio":"P3","sec":"s8"},{"id":"fc-238-6e6a08","poly":"cardio","fiche":"238","front":"Coarctation de la 2e enfance : quels signes ?","back":"**HTA**, pouls fémoraux **diminués**, **gradient tensionnel** membre supérieur/inférieur, souffle systolique doux sous-claviculaire gauche irradiant en interscapulaire.","prio":"P2","sec":"s8"},{"id":"fc-238-5a247d","poly":"cardio","fiche":"238","front":"Sténose valvulaire pulmonaire de la 2e enfance : quand est-elle découverte ?","back":"À des âges **variables** selon sa sévérité (dyspnée d'effort possible).","prio":"P3","sec":"s8"},{"id":"fc-238-505b73","poly":"cardio","fiche":"238","front":"Nouveau-né : quelles cardiopathies chirurgicales sont les plus fréquentes ?","back":"**Coarctation**, **transposition des gros vaisseaux**, **malformations complexes**.","prio":"P2","sec":"s8"},{"id":"fc-238-115711","poly":"cardio","fiche":"238","front":"Nouveau-né : quelles cardiopathies bénignes sont les plus répandues ?","back":"Les **petites CIV**.","prio":"P2","sec":"s8"},{"id":"fc-238-09474c","poly":"cardio","fiche":"238","front":"Nourrisson : quelles malformations sont les plus communes ?","back":"Les **shunts gauche-droite**, surtout les **CIV**.","prio":"P2","sec":"s8"},{"id":"fc-238-7e0d1a","poly":"cardio","fiche":"238","front":"2e enfance : quels souffles dominent ?","back":"Les **souffles fonctionnels** (cardiopathies en général bien tolérées).","prio":"P1","sec":"s8"},{"id":"fc-238-4bea2a","poly":"cardio","fiche":"238","front":"Nourrisson : un souffle faible signe-t-il une petite CIV ?","back":"**Non** : CIV **large** = souffle faible (+ B1 fort) ; **petite** CIV = souffle intense.","prio":"P2","sec":"s8"},{"id":"fc-238-cf95ed","poly":"cardio","fiche":"238","front":"Souffle réunissant tous les critères d'innocence : quels examens complémentaires ?","back":"**Aucun** ; échocardiographie **uniquement en cas de doute**.","prio":"P1","sec":"s9"},{"id":"fc-238-2c5398","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle conclusion donner à la famille, et quand ?","back":"Conclusion **ferme et précise** dès la **première consultation**.","prio":"P1","sec":"s9"},{"id":"fc-238-ace9cf","poly":"cardio","fiche":"238","front":"Souffle innocent : quel traitement et quelle surveillance ?","back":"**Aucun** traitement ; **aucune** surveillance (inutile de revoir l'enfant).","prio":"P1","sec":"s9"},{"id":"fc-238-9e78d9","poly":"cardio","fiche":"238","front":"Souffle innocent : quelle restriction sportive ?","back":"**Aucune** : tous les sports, **y compris en compétition**.","prio":"P1","sec":"s9"},{"id":"fc-238-802c2c","poly":"cardio","fiche":"238","front":"Souffle en période néonatale : quelle notion est inacceptable ?","back":"Le **méconnaître** : même chez un nouveau-né asymptomatique, il est **toujours potentiellement pathologique**.","prio":"P1","sec":"s10"},{"id":"fc-238-f6f6c4","poly":"cardio","fiche":"238","front":"Souffle néonatal : quel bilan avant la sortie de maternité ?","back":"Examen complet + **échographie cardiaque systématique** + souvent **ECG** + souvent **radiographie** pulmonaire de face.","prio":"P2","sec":"s10"},{"id":"fc-238-f083cf","poly":"cardio","fiche":"238","front":"Souffle néonatal : quels signes associés rechercher ?","back":"**Saturation** (cyanose), signes d'**IC**, **pouls fémoraux**, PA au membre inférieur autant qu'au supérieur.","prio":"P1","sec":"s10"},{"id":"fc-238-5c9d87","poly":"cardio","fiche":"238","front":"Nouveau-né : l'absence de souffle élimine-t-elle une cardiopathie grave ?","back":"**Non** : la **transposition des gros vaisseaux** ne donne **pas de souffle**.","prio":"P2","sec":"s10"},{"id":"fc-238-c8a469","poly":"cardio","fiche":"238","front":"Nouveau-né cyanosé : première étape ?","back":"**Confirmer l'hypoxie** par la **saturation transcutanée** (penser hypothermie, hypoglycémie).","prio":"P1","sec":"s11"},{"id":"fc-238-8fb602","poly":"cardio","fiche":"238","front":"Nouveau-né cyanosé sous O₂ à 100 % : que signe une hypoxie inchangée ?","back":"Une origine **cardiaque** → **cardiopédiatre** (échocardiographie).","prio":"P1","sec":"s11"},{"id":"fc-238-7f3d30","poly":"cardio","fiche":"238","front":"Nourrisson, cyanose retardée, souffle râpeux pulmonaire sans clic : quel diagnostic et quelle conduite ?","back":"**Tétralogie de Fallot** → **correction chirurgicale entre 6 mois et 1 an**.","prio":"P2","sec":"s11"},{"id":"fc-238-d5d830","poly":"cardio","fiche":"238","front":"Cardiopathie congénitale cyanogène : quel risque infectieux, et quelle conséquence ?","back":"**Haut risque d'endocardite** → **antibioprophylaxie** avant soins dentaires à risque.","prio":"P1","sec":"s11"},{"id":"fc-238-6c5eb1","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite (adulte) : quelle molécule de référence et quelle dose ?","back":"**Amoxicilline** (ou ampicilline) **2 g** per os ou IV, **30 à 60 min** avant le soin.","prio":"P1","sec":"s11"},{"id":"fc-238-b114f5","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite (adulte) : quelle alternative injectable à l'amoxicilline ?","back":"**Céfazoline** (ou ceftriaxone) **1 g** IM ou IV.","prio":"P2","sec":"s11"},{"id":"fc-238-5fa5a2","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite : quelle durée ?","back":"**Dose unique**, avant un soin dentaire touchant la **gencive** ou la région **périapicale**, ou avec **effraction de la muqueuse**.","prio":"P2","sec":"s11"},{"id":"fc-238-39e629","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite et allergie à la pénicilline : quelle notion inacceptable ?","back":"**Prescrire une pénicilline**.","prio":"P1","sec":"s11"},{"id":"fc-238-66cec4","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite chez l'enfant : posologie selon le Collège ?","back":"**Non précisée** dans le Collège (seule la dose adulte est donnée).","prio":"P3","sec":"s11"},{"id":"fc-238-8d33cb","poly":"cardio","fiche":"238","front":"Nourrisson en IC : quels gestes associer à l'examen ?","back":"**Pouls fémoraux** (vs huméraux), **PA au membre inférieur** autant qu'au supérieur, **poids** sur la courbe → cardiopédiatre.","prio":"P2","sec":"s12"},{"id":"fc-238-aa70ef","poly":"cardio","fiche":"238","front":"Nouveau-né symptomatique à la fermeture du canal, pouls fémoraux abolis : diagnostic et conduite ?","back":"**Coarctation aortique** → **chirurgie urgente**.","prio":"P2","sec":"s12"},{"id":"fc-238-7d7ed1","poly":"cardio","fiche":"238","front":"Large shunt gauche-droite du nourrisson : quand opérer ?","back":"**Tôt**, en général **dans la 1re année de vie**.","prio":"P2","sec":"s12"},{"id":"fc-238-a0f8b8","poly":"cardio","fiche":"238","front":"Large shunt gauche-droite opéré trop tard : quel risque ?","back":"**HTAP irréversible**.","prio":"P2","sec":"s12"},{"id":"fc-238-6308cb","poly":"cardio","fiche":"238","front":"Citer des larges shunts gauche-droite du nourrisson à opérer tôt ?","back":"**CIV large**, **canal artériel**, **canal atrioventriculaire** (trisomie 21).","prio":"P3","sec":"s12"},{"id":"fc-238-3afe9e","poly":"cardio","fiche":"238","front":"Cardiopathie significative de l'enfant : quel paramètre surveiller à chaque examen ?","back":"La **croissance pondérale**.","prio":"P2","sec":"s12"},{"id":"fc-238-4fe5b0","poly":"cardio","fiche":"238","front":"Nourrisson avec signes respiratoires et digestifs : quels signes chercher avant de conclure à une cause non cardiaque ?","back":"L'**hépatomégalie** et les **pouls fémoraux**.","prio":"P1","sec":"s12"},{"id":"fc-238-6428c3","poly":"cardio","fiche":"238","front":"Enfant avec HTA : quel examen clinique pour ne pas rater une coarctation ?","back":"PA aux membres **supérieurs et inférieurs** (brassard adapté) + **pouls huméraux vs fémoraux** ; HTA + fémoraux absents/diminués → **cardiopédiatre**.","prio":"P1","sec":"s13"},{"id":"fc-238-3356cd","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels examens de confirmation ?","back":"**Échocardiographie** et **IRM**.","prio":"P2","sec":"s13"},{"id":"fc-238-c5907f","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels traitements ?","back":"**Chirurgical** ou **endoluminal** (dilatation + **endoprothèse**).","prio":"P2","sec":"s13"},{"id":"fc-238-ea8a46","poly":"cardio","fiche":"238","front":"Coarctation de l'enfant : quels arguments cliniques en plus de l'HTA ?","back":"**Gradient tensionnel** membre supérieur/inférieur ; souffle systolique doux sous-claviculaire gauche irradiant en **interscapulaire** dans le dos.","prio":"P2","sec":"s13"},{"id":"fc-238-55acbe","poly":"cardio","fiche":"238","front":"Souffle innocent : évolution naturelle ?","back":"Il **disparaît avec l'âge** (parfois encore entendu chez le jeune adulte).","prio":"P1","sec":"s14"},{"id":"fc-238-ed8f47","poly":"cardio","fiche":"238","front":"Cardiopathie congénitale réparée avec matériel prothétique : combien de temps à haut risque d'endocardite ?","back":"**6 mois** après l'intervention ; **à vie** s'il persiste un **shunt résiduel**.","prio":"P1","sec":"s14"},{"id":"fc-238-a12d59","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quel rythme de visites chez le dentiste ?","back":"**2 fois/an** si haut risque ; **1 fois/an** pour les autres.","prio":"P2","sec":"s14"},{"id":"fc-238-73a2e3","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quelles précautions cutanées ?","back":"**Désinfecter les plaies** ; éviter **tatouages** et **piercing**.","prio":"P2","sec":"s14"},{"id":"fc-238-038313","poly":"cardio","fiche":"238","front":"Cardiopathie à risque d'endocardite : quels conseils en cas de fièvre ?","back":"**Pas d'antibiotique en automédication** ; **consulter vite**.","prio":"P1","sec":"s14"},{"id":"fc-238-3f0325","poly":"cardio","fiche":"238","front":"Prévention de l'endocardite : quelles autres mesures générales ?","back":"Éradiquer les **colonisations** chroniques (cutanées, urinaires), traiter les infections locales, **asepsie** stricte, **limiter les voies veineuses**.","prio":"P3","sec":"s14"},{"id":"fc-238-48412d","poly":"cardio","fiche":"238","front":"Antibioprophylaxie de l'endocardite : pour quels patients et quels soins ?","back":"Cardiopathies à **haut risque** seulement, avant les **soins dentaires à risque** (l'éducation concerne tous les patients à risque).","prio":"P1","sec":"s14"},{"id":"fc-330-11b95e","poly":"cardio","fiche":"330","front":"Antiagrégants plaquettaires : sur quelle étape de l'hémostase agissent-ils ?","back":"L'**hémostase primaire** (agrégation des plaquettes), étape clé du thrombus **artériel**.","prio":"P1","sec":"s1"},{"id":"fc-330-1e4696","poly":"cardio","fiche":"330","front":"Anticoagulants : à quel niveau agissent-ils ?","back":"Sur la **coagulation** (héparines, AVK, AOD).","prio":"P1","sec":"s1"},{"id":"fc-330-c308ca","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quel mode d'action ?","back":"Ils **activent la fibrinolyse** → destruction d'un caillot **déjà formé**.","prio":"P1","sec":"s1"},{"id":"fc-330-bc89a0","poly":"cardio","fiche":"330","front":"Antiagrégants : dans quelle maladie les retrouve-t-on surtout ?","back":"La **maladie athérothrombotique** (SCA, stent, AOMI, AVC).","prio":"P2","sec":"s1"},{"id":"fc-330-31c772","poly":"cardio","fiche":"330","front":"Anticoagulants : quel risque majeur impose de peser chaque prescription ?","back":"Une **iatrogénie importante** : chaque prescription se pèse, se surveille et s'explique au patient.","prio":"P2","sec":"s1"},{"id":"fc-330-7c1889","poly":"cardio","fiche":"330","front":"HNF, HBPM, fondaparinux : quel est leur mécanisme commun ?","back":"**Activation de l'antithrombine** (anticoagulant physiologique du sang).","prio":"P1","sec":"s1"},{"id":"fc-330-ba551c","poly":"cardio","fiche":"330","front":"AVK : sur quelle cible agissent-ils ?","back":"Synthèse hépatique des facteurs **II, VII, IX, X** (et des **protéines C et S**).","prio":"P1","sec":"s1"},{"id":"fc-330-870fbb","poly":"cardio","fiche":"330","front":"AOD : quelles cibles selon la molécule ?","back":"**Facteur II** (dabigatran) ; **facteur X** (rivaroxaban, apixaban).","prio":"P1","sec":"s1"},{"id":"fc-330-1d376b","poly":"cardio","fiche":"330","front":"Quelle notion transversale ne pas oublier sous AVK et sous AOD ?","back":"L'**éducation du patient**.","prio":"P1","sec":"s1"},{"id":"fc-330-7d5960","poly":"cardio","fiche":"330","front":"Aspirine : quel mécanisme d'action ?","back":"Inhibe la **cyclo-oxygénase** (Cox-1, moindrement Cox-2) → baisse du **thromboxane A2**.","prio":"P1","sec":"s2"},{"id":"fc-330-38b4c3","poly":"cardio","fiche":"330","front":"Aspirine : combien de temps dure son effet antiagrégant ?","back":"**Irréversible**, toute la vie de la plaquette : **7 à 10 jours**.","prio":"P1","sec":"s2"},{"id":"fc-330-9478b8","poly":"cardio","fiche":"330","front":"Aspirine per os : quel délai d'action ?","back":"Rapide : **quelques dizaines de minutes**.","prio":"P3","sec":"s2"},{"id":"fc-330-4e46c8","poly":"cardio","fiche":"330","front":"Inhibiteurs de P2Y12 : quelle voie bloquent-ils ?","back":"La voie de l'**ADP** (récepteur P2Y12).","prio":"P1","sec":"s2"},{"id":"fc-330-fc548a","poly":"cardio","fiche":"330","front":"Citer les inhibiteurs de P2Y12 utilisés ?","back":"**Clopidogrel**, **prasugrel**, **ticagrélor**.","prio":"P1","sec":"s2"},{"id":"fc-330-855583","poly":"cardio","fiche":"330","front":"Clopidogrel : pourquoi est-il inefficace chez certains patients ?","back":"**Prodrogue** activée par le CYP450 (surtout **CYP2C19**) ; mauvais métabolisme chez **15 à 25 %**.","prio":"P1","sec":"s2"},{"id":"fc-330-f91a9b","poly":"cardio","fiche":"330","front":"Inhibition plaquettaire moyenne : clopidogrel vs prasugrel/ticagrélor ?","back":"Clopidogrel **40-50 %** ; prasugrel et ticagrélor **70-80 %** (plus puissants et plus rapides).","prio":"P2","sec":"s2"},{"id":"fc-330-c6c4d8","poly":"cardio","fiche":"330","front":"Double antiagrégation : quelle molécule comporte-t-elle toujours ?","back":"L'**aspirine** (+ un inhibiteur de P2Y12).","prio":"P1","sec":"s2"},{"id":"fc-330-544693","poly":"cardio","fiche":"330","front":"Aspirine dans le SCA : quelle posologie ?","back":"**250 mg IVD**, puis **75-100 mg/j** per os, avec un **IPP**.","prio":"P1","sec":"s2"},{"id":"fc-330-2c2168","poly":"cardio","fiche":"330","front":"Aspirine : à partir de quelle dose apparaissent les effets antalgique, antipyrétique, anti-inflammatoire ?","back":"Au-delà de **1 g/j** chez l'adulte (dose antiagrégante très inférieure).","prio":"P2","sec":"s2"},{"id":"fc-330-8a2199","poly":"cardio","fiche":"330","front":"Aspirine : quelles indications en prévention ?","back":"**Secondaire** : coronaropathie, AOMI, AVC ; **primaire** seulement si très haut risque vasculaire **et** faible risque hémorragique.","prio":"P1","sec":"s2"},{"id":"fc-330-cc6a32","poly":"cardio","fiche":"330","front":"Aspirine : quels effets indésirables ?","back":"**Saignements**, **intolérance gastrique** ; allergie très rare (bien plus souvent suspectée qu'avérée).","prio":"P2","sec":"s2"},{"id":"fc-330-2c4e8e","poly":"cardio","fiche":"330","front":"Syndrome de Widal : quelle triade ?","back":"**Asthme** + **polypose nasale** + **allergie à l'aspirine**.","prio":"P2","sec":"s2"},{"id":"fc-330-9f4e26","poly":"cardio","fiche":"330","front":"Clopidogrel : quelle posologie dans le SCA ?","back":"Charge **600 mg** per os → **75 mg/j**.","prio":"P1","sec":"s2"},{"id":"fc-330-9be336","poly":"cardio","fiche":"330","front":"Clopidogrel associé à une fibrinolyse : quelle dose de charge ?","back":"**300 mg** seulement, avant 75 ans.","prio":"P1","sec":"s2"},{"id":"fc-330-194e3f","poly":"cardio","fiche":"330","front":"Clopidogrel : quelles indications ?","back":"**Angioplastie coronaire programmée** ; SCA si prasugrel/ticagrélor non indiqués, ou **après fibrinolyse** ; avec l'aspirine **3 à 12 mois**.","prio":"P2","sec":"s2"},{"id":"fc-330-76aac2","poly":"cardio","fiche":"330","front":"Clopidogrel : quand est-il le recours dans le SCA ?","back":"Si prasugrel et ticagrélor sont **contre-indiqués** (risque hémorragique, antécédent d'AVC, insuffisance hépatique sévère).","prio":"P2","sec":"s2"},{"id":"fc-330-ff45d2","poly":"cardio","fiche":"330","front":"Prasugrel : quelle posologie ?","back":"Charge **60 mg** per os → **10 mg/j**.","prio":"P1","sec":"s2"},{"id":"fc-330-ab5108","poly":"cardio","fiche":"330","front":"Prasugrel : quelle indication ?","back":"**SCA traité par angioplastie**, patient **< 75 ans**, avec l'aspirine.","prio":"P2","sec":"s2"},{"id":"fc-330-fa0cb8","poly":"cardio","fiche":"330","front":"Prasugrel : quelle contre-indication absolue ?","back":"**Antécédent d'AVC**.","prio":"P1","sec":"s2"},{"id":"fc-330-7dc108","poly":"cardio","fiche":"330","front":"Prasugrel : quelles contre-indications relatives ?","back":"**Poids < 60 kg**, **âge > 75 ans**.","prio":"P1","sec":"s2"},{"id":"fc-330-e2e107","poly":"cardio","fiche":"330","front":"Ticagrélor : quelle posologie ?","back":"Charge **180 mg** → **90 mg matin et soir**.","prio":"P1","sec":"s2"},{"id":"fc-330-b87f2b","poly":"cardio","fiche":"330","front":"Ticagrélor : quel effet indésirable principal ?","back":"**Dyspnée** (**18 %** des patients) ; bradycardie et dyspnée réversibles à l'arrêt.","prio":"P1","sec":"s2"},{"id":"fc-330-4d8896","poly":"cardio","fiche":"330","front":"Duoplavin® : quelle association ?","back":"**Aspirine + clopidogrel** dans un même comprimé.","prio":"P3","sec":"s2"},{"id":"fc-330-4ab5a4","poly":"cardio","fiche":"330","front":"Aspirine : quel effet possible est décrit en plus des effets antiagrégant, antalgique, antipyrétique et anti-inflammatoire ?","back":"Possible effet **anticancéreux** (surtout sur les adénocarcinomes).","prio":"P3","sec":"s2"},{"id":"fc-330-680e9c","poly":"cardio","fiche":"330","front":"Anti-GPIIb/IIIa : quelle cible, et exemples ?","back":"Le **récepteur du fibrinogène** ; **tirofiban**, **eptifibatide**.","prio":"P3","sec":"s2"},{"id":"fc-330-46752b","poly":"cardio","fiche":"330","front":"Antiagrégants : comment surveiller biologiquement leur activité ?","back":"**Aucun test biologique fiable** : pas de surveillance en routine.","prio":"P1","sec":"s2"},{"id":"fc-330-6b2634","poly":"cardio","fiche":"330","front":"SCA : durée classique de l'association inhibiteur de P2Y12 + aspirine ?","back":"Classiquement **12 mois** (de **1 à 12 mois** selon le risque hémorragique).","prio":"P2","sec":"s2"},{"id":"fc-330-2d6ca9","poly":"cardio","fiche":"330","front":"Double antiagrégation : quelle est la tendance actuelle ?","back":"**Raccourcir** la bithérapie et **remplacer l'aspirine** au long cours par l'autre antiagrégant (clopidogrel ou ticagrélor).","prio":"P2","sec":"s2"},{"id":"fc-330-91bac0","poly":"cardio","fiche":"330","front":"Coronarien stenté : combien de temps garder l'aspirine ?","back":"**Le plus souvent à vie**.","prio":"P3","sec":"s2"},{"id":"fc-330-74f948","poly":"cardio","fiche":"330","front":"Patient en prévention secondaire : quel risque à arrêter l'aspirine par crainte du saignement ?","back":"Un **événement athérothrombotique**.","prio":"P1","sec":"s2"},{"id":"fc-330-70334d","poly":"cardio","fiche":"330","front":"HNF : quelles formes existent ?","back":"**Héparine IV** et **héparine calcique** (Calciparine®, SC).","prio":"P2","sec":"s3"},{"id":"fc-330-499ba3","poly":"cardio","fiche":"330","front":"Citer les HBPM ?","back":"**Énoxaparine** (Lovenox®), **tinzaparine** (Innohep®), **nadroparine** (Fraxiparine®), **daltéparine** (Fragmine®).","prio":"P2","sec":"s3"},{"id":"fc-330-9fdd82","poly":"cardio","fiche":"330","front":"Citer les apparentés aux héparines ?","back":"**Fondaparinux** (Arixtra®), **danaparoïde** (Orgaran®), **bivalirudine**.","prio":"P2","sec":"s3"},{"id":"fc-330-558c80","poly":"cardio","fiche":"330","front":"HNF : quelle demi-vie, et conséquence pratique ?","back":"Environ **1 h 30** → **seringue autopousseuse continue** ou plusieurs injections/j (2-3 pour l'héparine calcique).","prio":"P1","sec":"s3"},{"id":"fc-330-aa4580","poly":"cardio","fiche":"330","front":"HNF : comment est-elle éliminée ?","back":"Surtout par **fixation** (protéines, endothélium, macrophages), **peu par le rein**.","prio":"P2","sec":"s3"},{"id":"fc-330-3f28b1","poly":"cardio","fiche":"330","front":"HBPM : combien d'injections par jour ?","back":"**1 ou 2 injections SC/j** (bolus IV possible pour un effet immédiat).","prio":"P2","sec":"s3"},{"id":"fc-330-44cfef","poly":"cardio","fiche":"330","front":"Fondaparinux : combien d'injections par jour ?","back":"**Une seule**, SC ou IV.","prio":"P2","sec":"s3"},{"id":"fc-330-efb541","poly":"cardio","fiche":"330","front":"HBPM et fondaparinux : quelle voie d'élimination, et conséquence ?","back":"**Rénale** essentiellement → **plutôt CI si ClCr < 30 mL/min**.","prio":"P1","sec":"s3"},{"id":"fc-330-db3830","poly":"cardio","fiche":"330","front":"Demi-vie des HBPM et du fondaparinux ?","back":"HBPM **8 à 24 h** ; fondaparinux **17 à 21 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-c7256a","poly":"cardio","fiche":"330","front":"Insuffisance rénale sévère (ClCr < 20-30 mL/min) : quel est le seul anticoagulant utilisable ?","back":"L'**HNF**.","prio":"P1","sec":"s3"},{"id":"fc-330-b85414","poly":"cardio","fiche":"330","front":"HBPM sous 30 mL/min de clairance : quelle exception récente ?","back":"Des règles récentes autorisent l'**énoxaparine** sous ce seuil.","prio":"P2","sec":"s3"},{"id":"fc-330-454cd4","poly":"cardio","fiche":"330","front":"HNF : quel antidote ?","back":"**Sulfate de protamine** IV (neutralisation instantanée).","prio":"P1","sec":"s3"},{"id":"fc-330-77b0dc","poly":"cardio","fiche":"330","front":"HBPM et fondaparinux : existe-t-il un antidote ?","back":"**Non** : en cours de développement.","prio":"P2","sec":"s3"},{"id":"fc-330-ac9d11","poly":"cardio","fiche":"330","front":"Héparines : quelles indications curatives ?","back":"**TVP et EP** ; **troubles du rythme** à anticoaguler (en attendant les anticoagulants oraux) ; **SCA**.","prio":"P1","sec":"s3"},{"id":"fc-330-36d3da","poly":"cardio","fiche":"330","front":"HBPM : quelle utilisation préventive ?","back":"**Prévention de la thrombose veineuse** en chirurgie ou en médecine à risque.","prio":"P2","sec":"s3"},{"id":"fc-330-2f93c9","poly":"cardio","fiche":"330","front":"Danaparoïde : quelle indication principale ?","back":"Patient avec **TIH** actuelle ou passée devant être anticoagulé.","prio":"P1","sec":"s3"},{"id":"fc-330-f3e936","poly":"cardio","fiche":"330","front":"Bivalirudine : quelle utilisation ?","back":"Anticoagulant IV surtout utilisé pendant les **angioplasties coronaires**.","prio":"P2","sec":"s3"},{"id":"fc-330-3bcaa4","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de l'HNF ?","back":"**500 UI/kg/j**, SC ou IV continue, puis adaptée.","prio":"P1","sec":"s3"},{"id":"fc-330-2989e9","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de l'énoxaparine ?","back":"**100 UI/kg/12 h** (1 mg/kg/12 h) SC.","prio":"P1","sec":"s3"},{"id":"fc-330-0b09dd","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative de la tinzaparine ?","back":"**175 UI/kg/24 h** SC.","prio":"P2","sec":"s3"},{"id":"fc-330-d722b0","poly":"cardio","fiche":"330","front":"TVP/EP : posologie curative du fondaparinux ?","back":"**7,5 mg/24 h** SC pour un poids de 50 à 100 kg.","prio":"P2","sec":"s3"},{"id":"fc-330-3a74df","poly":"cardio","fiche":"330","front":"TVP/EP : dans quelles situations l'HNF est-elle recommandée ?","back":"**Insuffisance rénale sévère**, patient **instable**, **geste** possible imposant un arrêt, patient **fibrinolysé**.","prio":"P2","sec":"s3"},{"id":"fc-330-3d95c9","poly":"cardio","fiche":"330","front":"SCA avec angioplastie immédiate : quelles doses d'anticoagulant ?","back":"HNF **70-100 UI/kg IVD** ou énoxaparine **0,5 mg/kg IVD** ; arrêt juste après revascularisation.","prio":"P2","sec":"s3"},{"id":"fc-330-295589","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : quelles doses d'anticoagulant SC ?","back":"Énoxaparine **1 mg/kg SC matin et soir** ou fondaparinux **2,5 mg/j SC**.","prio":"P2","sec":"s3"},{"id":"fc-330-b6babc","poly":"cardio","fiche":"330","front":"SCA ST- sous fondaparinux : que faut-il ajouter pendant la coronarographie ?","back":"Un **bolus d'HNF**.","prio":"P3","sec":"s3"},{"id":"fc-330-91d372","poly":"cardio","fiche":"330","front":"HNF : quand faire la numération plaquettaire ?","back":"**Avant** l'héparine ou dans les **24 h** suivant son introduction (dépistage TIH).","prio":"P1","sec":"s3"},{"id":"fc-330-857943","poly":"cardio","fiche":"330","front":"HNF IV (item 330) : quand faire le 1er TCA ?","back":"**Vers la 5ᵉ heure** après l'instauration, puis **au moins 1 fois/j**.","prio":"P1","sec":"s3"},{"id":"fc-330-5f561c","poly":"cardio","fiche":"330","front":"HNF IV (item 330) : quelle cible biologique ?","back":"**TCA 2 à 3 fois** le témoin et/ou **anti-Xa 0,5 à 0,8**.","prio":"P1","sec":"s3"},{"id":"fc-330-95af60","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA < 45 s ?","back":"**+ 6 000 UI/24 h** + **bolus de 5 000 U**.","prio":"P2","sec":"s3"},{"id":"fc-330-19044c","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA entre 46 et 54 s ?","back":"**+ 3 000 UI/24 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-86a562","poly":"cardio","fiche":"330","front":"Seringue d'HNF : quelle zone de TCA laisse la dose inchangée ?","back":"**55 à 85 s**.","prio":"P2","sec":"s3"},{"id":"fc-330-c0f4b5","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA entre 86 et 110 s ?","back":"**− 3 000 UI/24 h** + arrêt de la seringue **1 h**.","prio":"P3","sec":"s3"},{"id":"fc-330-bf59d4","poly":"cardio","fiche":"330","front":"Seringue d'HNF : conduite si TCA > 110 s ?","back":"**− 6 000 UI/24 h** + arrêt de la seringue **1 h**.","prio":"P2","sec":"s3"},{"id":"fc-330-ee53dd","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quelle cible biologique ?","back":"**TCA 1,5 à 2,5 fois** le témoin ou **anti-Xa 0,3 à 0,7** (≠ item 330).","prio":"P2","sec":"s3"},{"id":"fc-330-809b92","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quand mesurer TCA ou anti-Xa ?","back":"**4 h** après le début de l'IV continue et après chaque changement de dose (entre 2 injections si SC).","prio":"P3","sec":"s3"},{"id":"fc-330-15fe7c","poly":"cardio","fiche":"330","front":"HNF, chapitre MTEV : quel rythme de surveillance des plaquettes ?","back":"Avant traitement puis **2 fois/semaine pendant 21 jours** (inutile au-delà d'un mois).","prio":"P3","sec":"s3"},{"id":"fc-330-fbd84b","poly":"cardio","fiche":"330","front":"HBPM : faut-il mesurer leur activité ?","back":"**Non** en règle, si dose **adaptée au poids** et pas d'**insuffisance rénale**.","prio":"P1","sec":"s3"},{"id":"fc-330-020cc4","poly":"cardio","fiche":"330","front":"HBPM : quand un anti-Xa est-il suggéré (chapitre MTEV) ?","back":"**4 h** après l'initiation si risque d'accumulation ou hémorragique (IR modérée, âge élevé, petit poids, obésité).","prio":"P3","sec":"s3"},{"id":"fc-330-c41600","poly":"cardio","fiche":"330","front":"MTEV : pourquoi préférer HBPM et fondaparinux à l'HNF ?","back":"**Plus commodes**, pas d'adaptation à un test d'hémostase, **moins de TIH**.","prio":"P2","sec":"s3"},{"id":"fc-330-b0448d","poly":"cardio","fiche":"330","front":"Sous HBPM ou fondaparinux : quand surveiller les plaquettes (chapitre MTEV) ?","back":"HBPM après HNF ou MTEV **postopératoire**, nouvel épisode thromboembolique, **lésion cutanée** douloureuse au point d'injection.","prio":"P3","sec":"s3"},{"id":"fc-330-c1819b","poly":"cardio","fiche":"330","front":"Héparines : quels effets indésirables principaux ?","back":"Complications **hémorragiques** ; **TIH** (classique mais rare, immunoallergique).","prio":"P1","sec":"s3"},{"id":"fc-330-cb4dd4","poly":"cardio","fiche":"330","front":"Héparines : citer des effets indésirables plus rares ?","back":"**Ostéoporose**, **alopécie**, élévation des **transaminases**, **priapisme**, **insuffisance surrénalienne aiguë**.","prio":"P3","sec":"s3"},{"id":"fc-330-74206d","poly":"cardio","fiche":"330","front":"Quel est l'AVK de référence ?","back":"La **warfarine** (Coumadine®).","prio":"P2","sec":"s4"},{"id":"fc-330-5e0261","poly":"cardio","fiche":"330","front":"Fluindione : quelle restriction depuis 2017 ?","back":"**Instauration déconseillée** par l'ANSM (risque immunoallergique rare mais grave d'**insuffisance rénale**).","prio":"P1","sec":"s4"},{"id":"fc-330-b49319","poly":"cardio","fiche":"330","front":"Fluindione chez un patient bien équilibré depuis longtemps : faut-il la remplacer ?","back":"**Non** (complications survenant en règle dans les **6 mois**).","prio":"P2","sec":"s4"},{"id":"fc-330-e9c0af","poly":"cardio","fiche":"330","front":"Acénocoumarol (Sintrom®) : combien de prises par jour, et est-ce l'AVK recommandé ?","back":"**2 prises/j** ; ce **n'est pas** l'AVK recommandé.","prio":"P3","sec":"s4"},{"id":"fc-330-ec10c5","poly":"cardio","fiche":"330","front":"AVK : en combien de temps sont-ils pleinement efficaces ?","back":"**3 à 5 jours** de prise (longue demi-vie de certains facteurs).","prio":"P1","sec":"s4"},{"id":"fc-330-7670c7","poly":"cardio","fiche":"330","front":"AVK : pourquoi commencer par une héparine ?","back":"Délai d'action long : l'héparine assure l'anticoagulation jusqu'à ce que l'**INR** prouve le relais.","prio":"P1","sec":"s4"},{"id":"fc-330-7648fc","poly":"cardio","fiche":"330","front":"AVK : quel facteur a la demi-vie la plus courte ?","back":"Le **facteur VII** (4-6 h).","prio":"P3","sec":"s4"},{"id":"fc-330-520ce9","poly":"cardio","fiche":"330","front":"AVK : quel facteur a la demi-vie la plus longue ?","back":"Le **facteur II** (prothrombine, 50-120 h).","prio":"P3","sec":"s4"},{"id":"fc-330-1b5a46","poly":"cardio","fiche":"330","front":"Warfarine : quels dosages de comprimés ?","back":"**2 et 5 mg**.","prio":"P3","sec":"s4"},{"id":"fc-330-60ecd4","poly":"cardio","fiche":"330","front":"Relais héparine → AVK : quand introduire l'AVK ?","back":"**Tôt, dès J1** (sauf exception) ; non effectif avant **4 à 6 jours**.","prio":"P1","sec":"s4"},{"id":"fc-330-564cde","poly":"cardio","fiche":"330","front":"Relais héparine → AVK : quelles conditions pour arrêter l'héparine ?","back":"**Au moins 4 à 5 jours de chevauchement** ET **2 INR efficaces à 24 h d'intervalle**.","prio":"P1","sec":"s4"},{"id":"fc-330-5296ed","poly":"cardio","fiche":"330","front":"AVK dans la MTEV : quelle dose initiale ?","back":"Warfarine **5 mg** (ou acénocoumarol **4 mg**), plus faible chez le **sujet âgé**, puis adaptation à l'INR.","prio":"P2","sec":"s4"},{"id":"fc-330-ff1c12","poly":"cardio","fiche":"330","front":"INR : quelle valeur normale sans traitement ?","back":"**1**.","prio":"P1","sec":"s4"},{"id":"fc-330-98f567","poly":"cardio","fiche":"330","front":"AVK : quelle cible d'INR pour la plupart des indications ?","back":"Entre **2 et 3**.","prio":"P1","sec":"s4"},{"id":"fc-330-d87d87","poly":"cardio","fiche":"330","front":"AVK : qui fixe les cibles d'INR plus élevées ?","back":"Le **spécialiste** (ex. prothèse mécanique **mitrale**).","prio":"P2","sec":"s4"},{"id":"fc-330-06d24b","poly":"cardio","fiche":"330","front":"AVK : quand dit-on un patient correctement équilibré ?","back":"**Au moins 70 %** de ses INR dans la cible.","prio":"P1","sec":"s4"},{"id":"fc-330-823277","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : de J0 à J14 ?","back":"**2 fois/semaine**.","prio":"P2","sec":"s4"},{"id":"fc-330-83a30a","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : de J14 à J30, puis J30 à J60 ?","back":"J14-J30 : **1 fois/semaine** ; J30-J60 : **1 fois toutes les 2 semaines**.","prio":"P2","sec":"s4"},{"id":"fc-330-8f8fc5","poly":"cardio","fiche":"330","front":"Rythme des INR sous AVK : après J60 ?","back":"**1 fois/mois** (minimum au long cours).","prio":"P2","sec":"s4"},{"id":"fc-330-f0a99d","poly":"cardio","fiche":"330","front":"Automesure de l'INR : chez qui est-elle remboursée en France ?","back":"L'**enfant** et le **porteur de valve mécanique**.","prio":"P2","sec":"s4"},{"id":"fc-330-ac8a67","poly":"cardio","fiche":"330","front":"AVK : quels antidotes ?","back":"**PPSB** (très rapide) + **vitamine K** (en quelques heures).","prio":"P1","sec":"s4"},{"id":"fc-330-07a9fe","poly":"cardio","fiche":"330","front":"AVK et grossesse : quelle contre-indication ?","back":"**Tératogènes** : CI lors de la **première partie du 1er trimestre**.","prio":"P1","sec":"s4"},{"id":"fc-330-5f72f8","poly":"cardio","fiche":"330","front":"Dans quelles situations les AVK restent-ils préférés aux AOD ?","back":"**Valve mécanique**, **insuffisance rénale sévère**, **SAPL triple positif**.","prio":"P1","sec":"s4"},{"id":"fc-330-397e24","poly":"cardio","fiche":"330","front":"Éducation sous AVK : quels messages clés ?","back":"Éviter les **coprescriptions**, connaître les **seuils d'alerte** de l'INR, consulter si **saignement**, prévenir tout médecin.","prio":"P2","sec":"s4"},{"id":"fc-330-8f94f8","poly":"cardio","fiche":"330","front":"Citer les 3 AOD et leur activité ?","back":"**Dabigatran** (anti-IIa) ; **rivaroxaban** et **apixaban** (anti-Xa).","prio":"P1","sec":"s5"},{"id":"fc-330-5f5d19","poly":"cardio","fiche":"330","front":"AOD : délai d'efficacité après la première prise ?","back":"**Environ 2 heures** → pas de relais par héparine.","prio":"P1","sec":"s5"},{"id":"fc-330-b3c327","poly":"cardio","fiche":"330","front":"Dabigatran : quelle part d'élimination rénale ?","back":"**80 %**.","prio":"P1","sec":"s5"},{"id":"fc-330-653eca","poly":"cardio","fiche":"330","front":"Rivaroxaban et apixaban : quelle part d'élimination rénale ?","back":"Rivaroxaban **33 %** ; apixaban **25 %**.","prio":"P2","sec":"s5"},{"id":"fc-330-782fd8","poly":"cardio","fiche":"330","front":"Nombre de prises quotidiennes des AOD ?","back":"Dabigatran **2** ; apixaban **2** ; rivaroxaban **1** (2 au début du traitement d'une TVP/EP).","prio":"P2","sec":"s5"},{"id":"fc-330-67070f","poly":"cardio","fiche":"330","front":"AOD et rein : quel seuil de clairance ?","back":"**Déconseillés** si Cockcroft **< 30 à 25 mL/min** ; **CI** en insuffisance rénale sévère.","prio":"P1","sec":"s5"},{"id":"fc-330-beb3ed","poly":"cardio","fiche":"330","front":"AOD : à quels paramètres adapter la posologie ?","back":"**Âge**, **fonction rénale**, **poids**.","prio":"P2","sec":"s5"},{"id":"fc-330-0658fa","poly":"cardio","fiche":"330","front":"AOD : citer des médicaments en interaction ?","back":"**Macrolides**, **antiprotéases**, **azolés**, certains anticancéreux, **amiodarone**, **diltiazem**, **vérapamil**.","prio":"P2","sec":"s5"},{"id":"fc-330-930889","poly":"cardio","fiche":"330","front":"AOD et AVK : quelle classe éviter en association ?","back":"Les **anti-inflammatoires** (risque hémorragique accru).","prio":"P2","sec":"s5"},{"id":"fc-330-1c94ef","poly":"cardio","fiche":"330","front":"AOD : quelle surveillance biologique en routine ?","back":"**Aucune** ; le dosage du médicament est réservé à des situations particulières.","prio":"P1","sec":"s5"},{"id":"fc-330-4ab7e6","poly":"cardio","fiche":"330","front":"Sous AOD : TCA, TP et INR permettent-ils de juger l'efficacité ?","back":"**Non** : ils sont **perturbés** mais ne mesurent pas l'efficacité.","prio":"P1","sec":"s5"},{"id":"fc-330-3c2fa5","poly":"cardio","fiche":"330","front":"Dabigatran : quel antidote ?","back":"**Idarucizumab** (Praxbind®).","prio":"P1","sec":"s5"},{"id":"fc-330-b9b854","poly":"cardio","fiche":"330","front":"AOD vs AVK : quel avantage hémorragique majeur ?","back":"**Beaucoup moins d'hémorragies** globales et surtout **intracrâniennes**.","prio":"P1","sec":"s5"},{"id":"fc-330-e9878a","poly":"cardio","fiche":"330","front":"AOD vs AVK : quels inconvénients ?","back":"**Accumulation** si insuffisance rénale ; **observance** difficile à vérifier ; un peu plus d'hémorragies **digestives et génitales**.","prio":"P2","sec":"s5"},{"id":"fc-330-438f6a","poly":"cardio","fiche":"330","front":"AOD : quelles indications ?","back":"Traitement curatif de la **MTEV** (anti-Xa), prévention thromboembolique de la **FA**, prévention de la MTEV pour certains anti-Xa.","prio":"P2","sec":"s5"},{"id":"fc-330-c9b441","poly":"cardio","fiche":"330","front":"TVP/EP : posologie du rivaroxaban ?","back":"**15 mg 2 fois/j pendant 21 jours**, puis **20 mg 1 fois/j**.","prio":"P1","sec":"s5"},{"id":"fc-330-0b833c","poly":"cardio","fiche":"330","front":"TVP/EP : posologie de l'apixaban ?","back":"**10 mg 2 fois/j pendant 7 jours**, puis **5 mg 2 fois/j**.","prio":"P1","sec":"s5"},{"id":"fc-330-1a3dbb","poly":"cardio","fiche":"330","front":"MTEV : quelle place actuelle des AOD ?","back":"La **référence** de la prise en charge.","prio":"P2","sec":"s5"},{"id":"fc-330-1b77e5","poly":"cardio","fiche":"330","front":"FA : quel score guide la prescription d'un AOD ?","back":"Le score **CHA₂DS₂-VA** (doses souvent réduites après 80 ans).","prio":"P3","sec":"s5"},{"id":"fc-330-2acf09","poly":"cardio","fiche":"330","front":"AOD : quelles prescriptions sont des notions inacceptables ?","back":"AOD sur **valve mécanique**, **rétrécissement mitral** ou **insuffisance rénale sévère**.","prio":"P1","sec":"s5"},{"id":"fc-330-1d213a","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quelles indications actuelles ?","back":"**Infarctus du myocarde**, **AVC**, **embolie pulmonaire grave**.","prio":"P1","sec":"s6"},{"id":"fc-330-e3711c","poly":"cardio","fiche":"330","front":"Fibrinolytiques : quel risque principal ?","back":"**Hémorragique significatif**, notamment **cérébral**.","prio":"P1","sec":"s6"},{"id":"fc-330-a8ce6b","poly":"cardio","fiche":"330","front":"SCA ST+ : quand préférer l'angioplastie primaire à la fibrinolyse ?","back":"Si faisable dans les **120 minutes**.","prio":"P1","sec":"s6"},{"id":"fc-330-b576a0","poly":"cardio","fiche":"330","front":"SCA ST+ fibrinolysé : quelle suite ?","back":"Transfert vers un centre avec salle de cathétérisme (**angioplastie de sauvetage** si échec).","prio":"P2","sec":"s6"},{"id":"fc-330-f144aa","poly":"cardio","fiche":"330","front":"SCA ST+ : à partir de quand le bénéfice de la reperfusion devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul à partir de la 24ᵉ).","prio":"P2","sec":"s6"},{"id":"fc-330-700ecf","poly":"cardio","fiche":"330","front":"Fibrinolyse : quel est le seul inhibiteur de P2Y12 autorisé ?","back":"Le **clopidogrel** (charge **300 mg** uniquement avant 75 ans).","prio":"P1","sec":"s6"},{"id":"fc-330-e82998","poly":"cardio","fiche":"330","front":"Fibrinolyse : quelles contre-indications absolues cérébrales ?","back":"ATCD d'**AVC hémorragique** ; **AVC < 6 mois** ; malformation artérioveineuse ou tumeur cérébrale ; **traumatisme cérébral < 1 mois**.","prio":"P1","sec":"s6"},{"id":"fc-330-1888f5","poly":"cardio","fiche":"330","front":"Fibrinolyse : quelles contre-indications absolues hors cerveau ?","back":"**Hémorragie digestive < 1 mois** ; **dissection aortique** ; ponction/biopsie hépatique ou rénale ou PL **< 24 h** ; anomalie de l'hémostase.","prio":"P1","sec":"s6"},{"id":"fc-330-c64719","poly":"cardio","fiche":"330","front":"EP grave : quel traitement ?","back":"**Fibrinolyse** (réanimation/soins intensifs) ; **embolectomie** si thrombolyse contre-indiquée.","prio":"P1","sec":"s6"},{"id":"fc-330-f00a6e","poly":"cardio","fiche":"330","front":"EP de gravité intermédiaire : fibrinolyse systématique ?","back":"**Non**.","prio":"P2","sec":"s6"},{"id":"fc-330-095a6c","poly":"cardio","fiche":"330","front":"Patient fibrinolysé : quelle héparine ?","back":"L'**HNF**.","prio":"P2","sec":"s6"},{"id":"fc-330-5acbc6","poly":"cardio","fiche":"330","front":"TVP : quand discuter une thrombolyse ?","back":"Pas en 1re intention ; seulement **syndrome obstructif sévère** ou **phlegmatia caerulea** (sauvetage de membre).","prio":"P2","sec":"s6"},{"id":"fc-330-f7adfa","poly":"cardio","fiche":"330","front":"SCA sans contre-indication hémorragique : quelle association antithrombotique ?","back":"**Trithérapie** : **aspirine** + **inhibiteur de P2Y12** + **anticoagulant**.","prio":"P1","sec":"s7"},{"id":"fc-330-a8bde8","poly":"cardio","fiche":"330","front":"SCA ST+ traité par angioplastie primaire : quel P2Y12 en 1re intention ?","back":"**Prasugrel** ou **ticagrélor**.","prio":"P1","sec":"s7"},{"id":"fc-330-db180f","poly":"cardio","fiche":"330","front":"SCA ST- : faut-il une bithérapie antiplaquettaire dès l'admission ?","back":"**Non** avant la coronarographie (plus de saignements) ; envisageable si coronarographie prévue **au-delà de 24 h**.","prio":"P2","sec":"s7"},{"id":"fc-330-f93609","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : quand utiliser l'HNF IVSE, et à quelle dose ?","back":"Si HBPM et fondaparinux contre-indiqués (**insuffisance rénale chronique sévère**) : **400-600 UI/kg/24 h**.","prio":"P2","sec":"s7"},{"id":"fc-330-73df27","poly":"cardio","fiche":"330","front":"SCA ST- à haut risque : combien de temps dure l'anticoagulation SC ?","back":"De l'**admission en Usic** jusqu'à l'**angioplastie** ou au **pontage**.","prio":"P2","sec":"s7"},{"id":"fc-330-f7cebf","poly":"cardio","fiche":"330","front":"Sortie après SCA : quel traitement antiplaquettaire ?","back":"**Double antiagrégation** classiquement **12 mois**, **aspirine au long cours**.","prio":"P1","sec":"s7"},{"id":"fc-330-d080d7","poly":"cardio","fiche":"330","front":"Échec du clopidogrel : quelle cause penser ?","back":"Un **mauvais métabolisme** (15-25 % des patients, CYP2C19).","prio":"P2","sec":"s7"},{"id":"fc-330-856e49","poly":"cardio","fiche":"330","front":"SCA avec anticoagulant oral justifié (FA, thrombus VG) : quelle association ?","back":"Anticoagulant à pleine dose + **clopidogrel pendant 12 mois**, puis anticoagulant seul.","prio":"P2","sec":"s7"},{"id":"fc-330-84d291","poly":"cardio","fiche":"330","front":"SCA avec anticoagulant oral : quand une trithérapie est-elle possible, et combien de temps ?","back":"Faible risque hémorragique + haut risque ischémique : durée limitée, habituellement **1 mois**.","prio":"P3","sec":"s7"},{"id":"fc-330-f4960d","poly":"cardio","fiche":"330","front":"SCA : citer des facteurs de risque hémorragique ?","back":"**Âge > 75 ans**, **sexe féminin**, **insuffisance rénale**, diathèse hémorragique, AVC ancien, **poids < 65 kg**, chirurgie/traumatisme récents.","prio":"P3","sec":"s7"},{"id":"fc-330-0c0ae5","poly":"cardio","fiche":"330","front":"Après un SCA et/ou un stent : quelle conduite pour un geste invasif hémorragique non urgent ?","back":"Le **reporter**.","prio":"P2","sec":"s7"},{"id":"fc-330-0d7697","poly":"cardio","fiche":"330","front":"Prévention secondaire athérothrombotique : quelle alternative à l'aspirine ?","back":"Le **clopidogrel** (intolérance à l'aspirine ou atteinte polyvasculaire compliquée, notamment AOMI).","prio":"P1","sec":"s8"},{"id":"fc-330-43de42","poly":"cardio","fiche":"330","front":"Prévention secondaire : quelle dose d'aspirine (item 221) ?","back":"**75 à 325 mg/j**.","prio":"P2","sec":"s8"},{"id":"fc-330-f9ce4c","poly":"cardio","fiche":"330","front":"Prévention secondaire : quelle dose d'entretien du clopidogrel ?","back":"**75 mg/j**.","prio":"P2","sec":"s8"},{"id":"fc-330-ffbce8","poly":"cardio","fiche":"330","front":"AOMI symptomatique : quel antiagrégant, et pour quel bénéfice ?","back":"**Aspirine ou clopidogrel** pour réduire **infarctus et AVC**.","prio":"P2","sec":"s8"},{"id":"fc-330-d90ec9","poly":"cardio","fiche":"330","front":"AOMI asymptomatique (IPS < 0,90) : faut-il un antiagrégant ?","back":"**Débattu**, sauf autre localisation athéromateuse (ex. cardiopathie ischémique).","prio":"P3","sec":"s8"},{"id":"fc-330-f031f1","poly":"cardio","fiche":"330","front":"Aspirine en prévention primaire chez le diabétique : est-elle systématique ?","back":"**Non** : seulement si très haut risque vasculaire **et** faible risque de saignement.","prio":"P1","sec":"s8"},{"id":"fc-330-1038c0","poly":"cardio","fiche":"330","front":"Angioplastie artérielle des membres inférieurs : durée de la bithérapie antiplaquettaire ?","back":"**1 à 6 mois** selon le geste et sa localisation.","prio":"P3","sec":"s8"},{"id":"fc-330-708ffc","poly":"cardio","fiche":"330","front":"Après stent coronarien : combien de temps retarder un acte invasif hémorragique non urgent (p. 562) ?","back":"**3 à 6 mois** (points clés : **au moins 1 à 3 mois**).","prio":"P1","sec":"s8"},{"id":"fc-330-f83ddb","poly":"cardio","fiche":"330","front":"Geste à risque hémorragique modéré sous aspirine en prévention secondaire : conduite ?","back":"**Ne pas arrêter** l'aspirine (chirurgie, fibroscopie avec biopsie, stomatologie…).","prio":"P1","sec":"s8"},{"id":"fc-330-cdecda","poly":"cardio","fiche":"330","front":"Geste à risque hémorragique très important sous aspirine : conduite ?","back":"Arrêt **court**, **5 jours avant**, reprise **le plus tôt possible**.","prio":"P1","sec":"s8"},{"id":"fc-330-738075","poly":"cardio","fiche":"330","front":"Citer des chirurgies à risque hémorragique très important justifiant d'arrêter l'aspirine ?","back":"Chirurgie **ORL**, **urologique**, **neurologique**.","prio":"P2","sec":"s8"},{"id":"fc-330-2d6944","poly":"cardio","fiche":"330","front":"TVP/EP : quel bilan biologique avant traitement anticoagulant ?","back":"**Hémogramme** avec plaquettes, **TP**, **TCA**, **fibrinogène**, **créatininémie** avec clairance.","prio":"P2","sec":"s9"},{"id":"fc-330-d7ecf6","poly":"cardio","fiche":"330","front":"TVP/EP traitée par AOD anti-Xa : faut-il une héparine préalable ou un relais AVK ?","back":"**Non** : prescription d'emblée.","prio":"P1","sec":"s9"},{"id":"fc-330-e37807","poly":"cardio","fiche":"330","front":"TVP/EP sous AVK : quelle cible d'INR ?","back":"**2,5** (entre 2 et 3).","prio":"P2","sec":"s9"},{"id":"fc-330-ee78bc","poly":"cardio","fiche":"330","front":"TVP proximale et/ou EP : durée minimale d'anticoagulation ?","back":"Au minimum **3 mois**.","prio":"P3","sec":"s9"},{"id":"fc-330-63a410","poly":"cardio","fiche":"330","front":"TVP/EP : posologies curatives de la daltéparine et de la nadroparine (2 injections) ?","back":"Daltéparine **100 UI/kg/12 h** ; nadroparine **85 UI/kg/12 h**.","prio":"P3","sec":"s9"},{"id":"fc-330-7e07d3","poly":"cardio","fiche":"330","front":"Quelles HBPM ont l'AMM dans l'EP ?","back":"**Énoxaparine** et **tinzaparine** seulement.","prio":"P3","sec":"s9"},{"id":"fc-330-083677","poly":"cardio","fiche":"330","front":"Fraxodi® (nadroparine 1 injection/j) : quelle posologie curative ?","back":"**171 UI/kg/24 h**.","prio":"P3","sec":"s9"},{"id":"fc-330-79fe4b","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : l'aspirine est-elle indiquée ?","back":"**Non** (mobilisation précoce, ± compression, anticoagulant injectable).","prio":"P1","sec":"s9"},{"id":"fc-330-519ddf","poly":"cardio","fiche":"330","front":"Prévention de la MTEV en chirurgie : quelles molécules ?","back":"**Énoxaparine** ou **fondaparinux** ; **AOD** possibles en postopératoire selon protocoles.","prio":"P2","sec":"s9"},{"id":"fc-330-15ef7d","poly":"cardio","fiche":"330","front":"Prévention de la MTEV en milieu médical : sur quels critères ?","back":"**Pathologie** (IC, insuffisance respiratoire, rhumatismale…), possibilité de **lever précoce**, **terrain** (âge, cancer, ATCD de MTEV, obésité).","prio":"P2","sec":"s9"},{"id":"fc-330-c23702","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : dose d'énoxaparine en milieu médical ?","back":"**0,4 mL/24 h SC**.","prio":"P1","sec":"s9"},{"id":"fc-330-ad668d","poly":"cardio","fiche":"330","front":"Prévention de la MTEV : dose de fondaparinux ?","back":"**2,5 mg/24 h SC**.","prio":"P2","sec":"s9"},{"id":"fc-330-4b048a","poly":"cardio","fiche":"330","front":"Prévention de la MTEV par HBPM : durée en chirurgie orthopédique ?","back":"**4 à 6 semaines** (prothèse de hanche) ; **10-15 jours** (prothèse de genou).","prio":"P2","sec":"s9"},{"id":"fc-330-78560c","poly":"cardio","fiche":"330","front":"Voyage de plus de 6 h : quelles mesures de prévention de la MTEV ?","back":"Pas de vêtements serrés, **s'hydrater**, contracter les **mollets** ; si facteurs prédisposants : **contention classe 2 ou 3** ± HBPM préventive.","prio":"P3","sec":"s9"},{"id":"fc-330-674696","poly":"cardio","fiche":"330","front":"Héparine : pourquoi garder une durée la plus courte possible ?","back":"Pour **prévenir la TIH**.","prio":"P2","sec":"s9"},{"id":"fc-330-6deb28","poly":"cardio","fiche":"330","front":"Avant de prescrire un AOD : quel paramètre est capital ?","back":"La **clairance de la créatinine**.","prio":"P1","sec":"s10"},{"id":"fc-330-050daa","poly":"cardio","fiche":"330","front":"Insuffisance rénale sévère : quel anticoagulant au long cours ?","back":"L'**AVK** (préféré à l'AOD).","prio":"P2","sec":"s10"},{"id":"fc-330-d2ed59","poly":"cardio","fiche":"330","front":"Valve mécanique ou RM serré : quel anticoagulant oral ?","back":"**AVK** (AOD = **contre-indication absolue**).","prio":"P1","sec":"s10"},{"id":"fc-330-f6e815","poly":"cardio","fiche":"330","front":"Prothèse valvulaire mécanique : combien de temps dure l'AVK ?","back":"**À vie** (débuté dès les premiers jours postopératoires).","prio":"P2","sec":"s10"},{"id":"fc-330-72de14","poly":"cardio","fiche":"330","front":"Valve mécanique : de quoi dépend l'INR cible ?","back":"De la **thrombogénicité de la prothèse** et des **facteurs de risque du patient**.","prio":"P2","sec":"s10"},{"id":"fc-330-bf2ddd","poly":"cardio","fiche":"330","front":"Valve mécanique : quels facteurs de risque patient augmentent l'INR cible ?","back":"Remplacement **mitral** ou **tricuspide**, ATCD **thromboembolique**, **FA**, **sténose mitrale**, **FEVG < 35 %**.","prio":"P3","sec":"s10"},{"id":"fc-330-88d7a9","poly":"cardio","fiche":"330","front":"Valve mécanique peu thrombogène : quelle cible d'INR ?","back":"**2,5** sans facteur de risque ; **3,0** si au moins un.","prio":"P2","sec":"s10"},{"id":"fc-330-723dfb","poly":"cardio","fiche":"330","front":"Valve mécanique moyennement ou très thrombogène : quelle cible d'INR ?","back":"Moyen : **3,0 ou 3,5** ; élevé (valves à bille ou à disque) : **3,5 ou 4,0**.","prio":"P3","sec":"s10"},{"id":"fc-330-8285a7","poly":"cardio","fiche":"330","front":"FA sous AVK (points clés FA) : quelle cible d'INR ?","back":"**2,5** (2 à 3), sauf valve mécanique **mitrale** : **3,7**.","prio":"P3","sec":"s10"},{"id":"fc-330-32b3ef","poly":"cardio","fiche":"330","front":"Valve mécanique et geste programmé : quelle conduite pour l'AVK ?","back":"Arrêt avec **relais préopératoire par héparine curative** (haut risque thrombotique).","prio":"P2","sec":"s10"},{"id":"fc-330-8abf7f","poly":"cardio","fiche":"330","front":"Grossesse : quel anticoagulant pour traiter une MTEV ?","back":"Les **HBPM**.","prio":"P1","sec":"s10"},{"id":"fc-330-342821","poly":"cardio","fiche":"330","front":"Bioprothèse : quand les AOD sont-ils autorisés ?","back":"**Au-delà de 3 mois** si l'indication n'est pas valvulaire (dès le postopératoire si FA sur bioprothèse mitrale).","prio":"P2","sec":"s10"},{"id":"fc-330-200d8a","poly":"cardio","fiche":"330","front":"Bioprothèse aortique : quel traitement les 3 premiers mois ?","back":"**Aspirine** ou **AVK** pendant **3 mois**.","prio":"P3","sec":"s10"},{"id":"fc-330-a978ee","poly":"cardio","fiche":"330","front":"Valve mécanique sous AVK : faut-il ajouter un antiagrégant ?","back":"**Non** (pratique européenne), sauf stent récent ou thromboembolie malgré INR efficace.","prio":"P2","sec":"s10"},{"id":"fc-330-fb60f1","poly":"cardio","fiche":"330","front":"Geste programmé sous AVK à risque hémorragique modéré : conduite ?","back":"**Ne pas interrompre** l'AVK, après avoir vérifié un INR dans la **limite basse** de la fourchette.","prio":"P1","sec":"s11"},{"id":"fc-330-beef46","poly":"cardio","fiche":"330","front":"Geste sous AVK à risque hémorragique plus important : quel INR viser ?","back":"**< 1,5** (**< 1,2 en neurochirurgie**).","prio":"P1","sec":"s11"},{"id":"fc-330-96dd94","poly":"cardio","fiche":"330","front":"AVK et risque thrombotique modéré : conduite avant un geste ?","back":"Arrêt **3 à 4 jours**, **sans relais**, reprise le soir même.","prio":"P1","sec":"s11"},{"id":"fc-330-18345a","poly":"cardio","fiche":"330","front":"Citer des situations à risque thrombotique modéré sous AVK ?","back":"**FA sans antécédent embolique**, TVP/EP **au-delà du 3e mois**, MTEV à risque modéré.","prio":"P2","sec":"s11"},{"id":"fc-330-775e95","poly":"cardio","fiche":"330","front":"AVK et risque thrombotique élevé : conduite avant un geste ?","back":"Arrêt **4 à 5 jours avant** + **relais par héparine à dose curative**.","prio":"P1","sec":"s11"},{"id":"fc-330-6a534f","poly":"cardio","fiche":"330","front":"Citer les situations à risque thrombotique élevé sous AVK ?","back":"**Valve mécanique**, **FA avec antécédent embolique**, **TVP proximale/EP < 3 mois**, **MTEV récidivante idiopathique**.","prio":"P1","sec":"s11"},{"id":"fc-330-97dfe7","poly":"cardio","fiche":"330","front":"Après un geste sous AVK (tableau HAS 22.8) : dans quel délai reprendre l'AVK ?","back":"Dans les **24-48 h**.","prio":"P1","sec":"s11"},{"id":"fc-330-83b77b","poly":"cardio","fiche":"330","front":"Après un geste : au plus tôt quand reprendre une héparine curative ?","back":"**Pas avant la 6ᵉ heure** postopératoire, si le risque hémorragique est contrôlé.","prio":"P1","sec":"s11"},{"id":"fc-330-d8c008","poly":"cardio","fiche":"330","front":"Relais par héparine autour d'un geste : pourquoi ne pas le faire « par sécurité » ?","back":"Source de complications **hémorragiques et thrombotiques** → réservé au haut risque thrombotique.","prio":"P2","sec":"s11"},{"id":"fc-330-9216f3","poly":"cardio","fiche":"330","front":"MTEV récidivante idiopathique : définition ?","back":"**Au moins 2 épisodes**, dont au moins un **sans facteur déclenchant**.","prio":"P2","sec":"s11"},{"id":"fc-330-b54419","poly":"cardio","fiche":"330","front":"MTEV à haut risque et geste programmé : quel dispositif se discute ?","back":"Un **filtre cave** préopératoire, au cas par cas.","prio":"P3","sec":"s11"},{"id":"fc-330-86e639","poly":"cardio","fiche":"330","front":"Héparines : fréquence des accidents hémorragiques ?","back":"**1 à 4 %** en curatif ; **1 à 2 %** en préventif.","prio":"P1","sec":"s12"},{"id":"fc-330-68a685","poly":"cardio","fiche":"330","front":"Héparine : quelles associations médicamenteuses augmentent le risque hémorragique ?","back":"Un autre **antithrombotique** (AVK, antiagrégant) ou un **AINS**.","prio":"P2","sec":"s12"},{"id":"fc-330-fcd71a","poly":"cardio","fiche":"330","front":"Héparine : citer des facteurs de risque hémorragique liés au patient ?","back":"**Âge**, **sexe féminin**, **faible poids**, intensité et durée de l'anticoagulation, **insuffisance rénale**, thrombopénie…","prio":"P3","sec":"s12"},{"id":"fc-330-a0e3a0","poly":"cardio","fiche":"330","front":"Héparine au long cours : quelle anémie typique sans saignement visible ?","back":"Anémie **microcytaire ferriprive** (d'où une NFS régulière).","prio":"P2","sec":"s12"},{"id":"fc-330-9a1131","poly":"cardio","fiche":"330","front":"Surdosage biologique sous HNF : quel seuil de TCA ?","back":"**TCA > 3 fois** le témoin (ou héparinémie élevée).","prio":"P2","sec":"s12"},{"id":"fc-330-a53eeb","poly":"cardio","fiche":"330","front":"Saignement mineur ou surdosage asymptomatique sous héparine : conduite ?","back":"**Adapter les doses** + surveillance clinique et biologique rapprochée.","prio":"P1","sec":"s12"},{"id":"fc-330-53c629","poly":"cardio","fiche":"330","front":"Saignement majeur sous héparine : conduite ?","back":"Peser le risque d'arrêt ; **remplissage** IV puis **transfusion** si besoin ; discuter le **sulfate de protamine**.","prio":"P1","sec":"s12"},{"id":"fc-330-58fe70","poly":"cardio","fiche":"330","front":"Thrombopénie de type I sous héparine : caractéristiques ?","back":"**Précoce**, **bénigne**, **non immune**, sans thrombose ; régresse même si on poursuit l'héparine.","prio":"P2","sec":"s12"},{"id":"fc-330-5c416e","poly":"cardio","fiche":"330","front":"TIH (type II) : quel mécanisme ?","back":"**Immunoallergique** : anticorps contre le **PF4** modifié par l'héparine → activation plaquettaire et de la coagulation.","prio":"P1","sec":"s12"},{"id":"fc-330-c9e56b","poly":"cardio","fiche":"330","front":"TIH : quel est le danger principal ?","back":"**Thrombotique** : thromboses veineuses (**80 %**) et/ou artérielles (**20 %**), pas hémorragique (sauf CIVD).","prio":"P1","sec":"s12"},{"id":"fc-330-dec8a4","poly":"cardio","fiche":"330","front":"TIH : quel délai typique d'apparition ?","back":"**5 à 8 jours** après le début de l'héparine.","prio":"P1","sec":"s12"},{"id":"fc-330-722a42","poly":"cardio","fiche":"330","front":"TIH : quand peut-elle survenir dès J1 ?","back":"Si exposition à l'héparine dans les **3 mois** précédents.","prio":"P1","sec":"s12"},{"id":"fc-330-f8a2a6","poly":"cardio","fiche":"330","front":"TIH sous HBPM : particularité du délai ?","back":"**Plus long** (parfois plus de 3 semaines).","prio":"P2","sec":"s12"},{"id":"fc-330-9b4ffd","poly":"cardio","fiche":"330","front":"TIH : quels seuils plaquettaires doivent la faire évoquer (item 330) ?","back":"Plaquettes **< 100 G/L** et/ou **chute relative de 30 à 50 %** sur deux numérations.","prio":"P1","sec":"s12"},{"id":"fc-330-9abd9e","poly":"cardio","fiche":"330","front":"TIH : quels signes cliniques ou biologiques non plaquettaires l'évoquent ?","back":"Thrombose **nouvelle ou extensive** sous héparine ; **résistance à l'HNF** ; placards au point d'injection ; rarement insuffisance surrénalienne aiguë.","prio":"P1","sec":"s12"},{"id":"fc-330-59fad6","poly":"cardio","fiche":"330","front":"TIH, chapitre MTEV : quels seuils plaquettaires ?","back":"**< 150 G/L** ou baisse de **50 %** par rapport à avant traitement.","prio":"P3","sec":"s12"},{"id":"fc-330-52ec12","poly":"cardio","fiche":"330","front":"Suspicion de TIH : première étape biologique ?","back":"**Confirmer la thrombopénie** sur tube **citraté** et/ou capillaire, avec contrôle sur **lame**.","prio":"P2","sec":"s12"},{"id":"fc-330-5bca7c","poly":"cardio","fiche":"330","front":"TIH : quel test immunologique, et quelle valeur ?","back":"**ELISA anti-PF4** : meilleure valeur prédictive **négative** que positive.","prio":"P3","sec":"s12"},{"id":"fc-330-fb8e4a","poly":"cardio","fiche":"330","front":"Suspicion forte de TIH : conduite ?","back":"**Arrêter l'héparine** et la remplacer par un antithrombotique d'action immédiate, **sans attendre** la biologie.","prio":"P2","sec":"s12"},{"id":"fc-330-3d85bc","poly":"cardio","fiche":"330","front":"Prévention primaire de la TIH : quels 3 principes ?","back":"Héparine **la plus courte possible** ; **relais précoce** par AOD ou AVK ; préférer **HBPM ou fondaparinux**.","prio":"P1","sec":"s12"},{"id":"fc-330-8b4097","poly":"cardio","fiche":"330","front":"TIH : avec quelle héparine et dans quel contexte est-elle plus fréquente ?","back":"Avec l'**HNF** ; en **chirurgie** (cardiaque, orthopédique) plus qu'en médecine.","prio":"P3","sec":"s12"},{"id":"fc-330-714e77","poly":"cardio","fiche":"330","front":"TIH : quelles complications graves possibles ?","back":"**CIVD** (10-20 %) ; thromboses artérielles (aorte abdominale) ; complications **neurologiques** (9,5 %).","prio":"P3","sec":"s12"},{"id":"fc-330-dd84b7","poly":"cardio","fiche":"330","front":"Sous HBPM (item 330) : quand la surveillance des plaquettes reste-t-elle préconisée ?","back":"En **chirurgie ou traumatologie** et chez les patients à risque (héparine dans les **6 mois**, comorbidités **importantes**).","prio":"P3","sec":"s12"},{"id":"fc-330-50c6fa","poly":"cardio","fiche":"330","front":"AVK : quelle place dans la iatrogénie ?","back":"**1re cause iatrogène d'hospitalisation** (13 % des hospitalisations pour effet indésirable médicamenteux).","prio":"P3","sec":"s13"},{"id":"fc-330-ab97ef","poly":"cardio","fiche":"330","front":"Surdosage en AVK asymptomatique : quelle prise en charge ?","back":"Le plus souvent **ambulatoire**, selon l'**INR mesuré** et l'**INR cible**.","prio":"P1","sec":"s13"},{"id":"fc-330-3501aa","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR mesuré entre 4 et 6 sans saignement : conduite ?","back":"**Sauter une prise**, pas de vitamine K ; adapter à la reprise.","prio":"P2","sec":"s13"},{"id":"fc-330-2a88df","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR mesuré entre 6 et 10 sans saignement : conduite ?","back":"**Arrêt de l'AVK** + **1 à 2 mg de vitamine K per os**.","prio":"P2","sec":"s13"},{"id":"fc-330-ec4e3c","poly":"cardio","fiche":"330","front":"Cible INR 2,5, INR > 10 sans saignement : conduite ?","back":"**Arrêt de l'AVK** + **5 mg de vitamine K per os** (½ ampoule buvable adulte).","prio":"P2","sec":"s13"},{"id":"fc-330-edba87","poly":"cardio","fiche":"330","front":"Cible INR 3, INR > 10 sans saignement : conduite ?","back":"**Avis spécialisé sans délai** ou **hospitalisation**.","prio":"P3","sec":"s13"},{"id":"fc-330-dfeb57","poly":"cardio","fiche":"330","front":"Cible INR 3, INR mesuré entre 4 et 6 sans saignement : conduite ?","back":"**Ni saut de prise ni vitamine K** ; adapter la posologie.","prio":"P3","sec":"s13"},{"id":"fc-330-f67702","poly":"cardio","fiche":"330","front":"Cible INR 3, INR entre 6 et 10 sans saignement : conduite ?","back":"**Sauter une prise** ; avis spécialisé pour discuter 1 à 2 mg de vitamine K per os.","prio":"P3","sec":"s13"},{"id":"fc-330-97fba7","poly":"cardio","fiche":"330","front":"Après tout surdosage en AVK : quelles mesures communes ?","back":"**Rechercher la cause**, **INR de contrôle le lendemain**, puis surveillance comme à l'instauration.","prio":"P1","sec":"s13"},{"id":"fc-330-9af2e1","poly":"cardio","fiche":"330","front":"Hémorragie sous AVK : quels critères de gravité ?","back":"**Non contrôlable** ; **instabilité hémodynamique** ; besoin d'un **geste hémostatique** ; besoin d'une **transfusion** ; localisation menaçant le **pronostic vital ou fonctionnel**.","prio":"P1","sec":"s13"},{"id":"fc-330-4cf799","poly":"cardio","fiche":"330","front":"Hémorragie sous AVK : combien de critères pour la dire grave ?","back":"**Au moins un** des 5.","prio":"P1","sec":"s13"},{"id":"fc-330-446590","poly":"cardio","fiche":"330","front":"Hémorragie non grave sous AVK : conduite ?","back":"Souvent **ambulatoire** ; **INR en urgence** ; corriger un surdosage ; **rechercher la cause**.","prio":"P2","sec":"s13"},{"id":"fc-330-114d4f","poly":"cardio","fiche":"330","front":"Citer des gestes hémostatiques locaux sous anticoagulant ?","back":"**Compression** (suture), colle à la **fibrine/thrombine**, **adrénaline** locale, **embolisation**.","prio":"P3","sec":"s13"},{"id":"fc-330-be00a7","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : quels antidotes ?","back":"**CCP/PPSB** (très rapide mais bref) **+ vitamine K** ; hospitalisation et arrêt des AVK.","prio":"P2","sec":"s13"},{"id":"fc-330-bcc4df","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : faut-il attendre l'INR pour traiter ?","back":"**Non** : traitement instauré sans attendre le résultat.","prio":"P2","sec":"s13"},{"id":"fc-330-4a09ff","poly":"cardio","fiche":"330","front":"Hémorragie grave sous AVK : quand contrôler l'INR après le CCP ?","back":"**30 min** après (dose complémentaire si INR > 1,5), puis à **6-8 h**, puis 1 fois/j.","prio":"P3","sec":"s13"},{"id":"fc-330-7bae26","poly":"cardio","fiche":"330","front":"Après une hémorragie grave sous AVK : quelle suite ?","back":"Indication de l'AVK **à nouveau pesée** ; relais par **héparine** si anticoagulation impérative.","prio":"P3","sec":"s13"},{"id":"fc-330-3aebb0","poly":"cardio","fiche":"330","front":"Traumatisme crânien sous AVK : conduite ?","back":"**Hospitalisation ≥ 24 h** + **scanner cérébral en urgence**.","prio":"P1","sec":"s13"},{"id":"fc-330-ad3063","poly":"cardio","fiche":"330","front":"Polytraumatisé sous AVK : conduite ?","back":"**INR en urgence** ; conduite d'une hémorragie grave ou non grave selon la gravité.","prio":"P2","sec":"s13"},{"id":"fc-330-b9a96d","poly":"cardio","fiche":"330","front":"Prévention des hémorragies sous AVK : quelles mesures ?","back":"**Éducation**, vigilance sur les **interactions**, **automesure** de l'INR.","prio":"P2","sec":"s13"},{"id":"fc-330-f25333","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quel est le meilleur antidote ?","back":"Le **temps** écoulé depuis la dernière prise (demi-vie courte).","prio":"P1","sec":"s14"},{"id":"fc-330-d4717b","poly":"cardio","fiche":"330","front":"Anti-Xa (rivaroxaban, apixaban) : comment les antagoniser ?","back":"**PPSB** ou **Feiba®** (antidote spécifique en cours de commercialisation).","prio":"P1","sec":"s14"},{"id":"fc-330-26dd18","poly":"cardio","fiche":"330","front":"Feiba® : de quoi s'agit-il ?","back":"Mélange de **PPSB** et de **facteur VIII**.","prio":"P3","sec":"s14"},{"id":"fc-330-070dda","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quelles informations noter ?","back":"Âge, poids, molécule, dose, prises/j, **heure de la dernière prise**, indication.","prio":"P1","sec":"s14"},{"id":"fc-330-d193ed","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quels prélèvements ?","back":"**Créatinine** (Cockcroft) + **dosage spécifique** du médicament ; contacter le laboratoire d'hémostase.","prio":"P2","sec":"s14"},{"id":"fc-330-71f80b","poly":"cardio","fiche":"330","front":"Saignement actif sous AOD : faut-il attendre le dosage du médicament ?","back":"**Non** : la conduite n'attend pas son résultat.","prio":"P1","sec":"s14"},{"id":"fc-330-c41fd6","poly":"cardio","fiche":"330","front":"Saignement sous AOD : quelles étapes après le recueil d'informations ?","back":"**Prélever**, contacter l'**hémostase**, **interrompre** le traitement, **antagoniser** si besoin.","prio":"P2","sec":"s14"},{"id":"fc-330-0d4792","poly":"cardio","fiche":"330","front":"Quelles sont les notions indispensables de l'item antithrombotiques ?","back":"**Éducation** sous AVK et AOD ; pas d'AOD sur valve mécanique ou RM ; savoir faire un **relais héparine-AVK**.","prio":"P2","sec":"s15"},{"id":"fc-330-731f53","poly":"cardio","fiche":"330","front":"HBPM ou AOD en insuffisance rénale sévère : quel statut ?","back":"**Notion inacceptable**.","prio":"P2","sec":"s15"},{"id":"fc-330-a30024","poly":"cardio","fiche":"330","front":"Aspirine et acte à risque très important : quelle erreur éviter sur le délai d'arrêt ?","back":"L'arrêter **plus de 5 jours** avant.","prio":"P2","sec":"s15"},{"id":"fc-330-c91e4b","poly":"cardio","fiche":"330","front":"Antidotes : citer celui de l'HNF, des AVK, du dabigatran et des anti-Xa ?","back":"**P**rotamine (héparine), **K** + PPSB (AVK), **I**darucizumab (dabigatran), PPSB/Feiba® (anti-Xa).","prio":"P2","sec":"s15"},{"id":"fc-331-afccaa","poly":"cardio","fiche":"331","front":"Mort subite (OMS) : quelle définition ?","back":"Mort **instantanée et soudaine** liée à une maladie aiguë, symptômes annonciateurs de quelques minutes, **1 heure** au plus.","prio":"P2","sec":"s1"},{"id":"fc-331-a621f0","poly":"cardio","fiche":"331","front":"Arrêt cardiocirculatoire : quelle définition ?","back":"Plus d'activité mécanique du cœur : **absence de pouls** + **apnée** ou respiration agonique (**gasping**).","prio":"P1","sec":"s1"},{"id":"fc-331-b05d99","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : sur quoi repose le diagnostic positif ?","back":"**Absence de réponse** + **ventilation inefficace**.","prio":"P1","sec":"s1"},{"id":"fc-331-09dbfe","poly":"cardio","fiche":"331","front":"Arrêt cardiaque récupéré : quelle définition ?","back":"Retour d'une **hémodynamique stable** (pouls et PA convenables) = « réanimé avec succès ».","prio":"P2","sec":"s1"},{"id":"fc-331-1c60f3","poly":"cardio","fiche":"331","front":"Arrêt cardiaque réfractaire : quelle définition française ?","back":"Pas de circulation spontanée après **30 minutes** de réanimation médicale bien conduite.","prio":"P1","sec":"s1"},{"id":"fc-331-f5e612","poly":"cardio","fiche":"331","front":"No-flow : quelle définition ?","back":"Intervalle entre l'arrêt et le **début de la réanimation**, sans mécanique cardiaque efficace.","prio":"P2","sec":"s1"},{"id":"fc-331-841c5e","poly":"cardio","fiche":"331","front":"Low-flow : quelle définition ?","back":"Durée de **réanimation** sans retour d'une hémodynamique convenable (pouls et PA stables).","prio":"P2","sec":"s1"},{"id":"fc-331-bbbdff","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le déterminant le plus important de la survie ?","back":"Le **délai** entre l'arrêt et le début de la réanimation (durée du **no-flow**).","prio":"P1","sec":"s1"},{"id":"fc-331-73d114","poly":"cardio","fiche":"331","front":"Au-delà de 10 min sans hémodynamique : quel pronostic, et quelle exception ?","back":"Récupération et survie **très faibles**, sauf en cas d'**hypothermie**.","prio":"P1","sec":"s1"},{"id":"fc-331-13f4ec","poly":"cardio","fiche":"331","front":"No-flow de plus de 5 min : quel pronostic ?","back":"Pronostic et chances de survie sans séquelle **faibles** (décès très fréquents, séquelles fréquentes).","prio":"P2","sec":"s1"},{"id":"fc-331-813a27","poly":"cardio","fiche":"331","front":"No-flow de plus de 10 min : quel pronostic ?","back":"Survie **quasi nulle** ; les reprises évoluent en général vers une **encéphalopathie anoxique**.","prio":"P2","sec":"s1"},{"id":"fc-331-4f4dca","poly":"cardio","fiche":"331","front":"No-flow bref : quel poids garde la durée du low-flow ?","back":"Elle **pèse moins** : une réanimation longue, mais précoce et efficace, peut aboutir à une récupération cardiaque et cérébrale.","prio":"P2","sec":"s1"},{"id":"fc-331-2aaefa","poly":"cardio","fiche":"331","front":"France : combien de décès par arrêt cardiaque extrahospitalier par an ?","back":"**40 000 par an** (incidence **0,75 ‰**).","prio":"P3","sec":"s1"},{"id":"fc-331-24b51c","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle survie au-delà de 5 min et au-delà de 10 min d'arrêt ?","back":"**7 à 8 %** au-delà de 5 min ; **proche de 0** au-delà de 10 min.","prio":"P3","sec":"s1"},{"id":"fc-331-6a1881","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle survie sans séquelle, notamment neurologique ?","back":"**2 à 4 %**.","prio":"P3","sec":"s1"},{"id":"fc-331-3f12ad","poly":"cardio","fiche":"331","front":"Arrêt cardiaque intrahospitalier : quelle survie ?","back":"Plus élevée : **40-50 %**.","prio":"P3","sec":"s1"},{"id":"fc-331-148e97","poly":"cardio","fiche":"331","front":"Survie sans séquelle : que devient-elle après 30 min de RCP ?","back":"**Nulle**.","prio":"P2","sec":"s1"},{"id":"fc-331-24d99c","poly":"cardio","fiche":"331","front":"Quelles recommandations encadrent la prise en charge de l'arrêt cardiaque en France ?","back":"**ERC 2021**, Société européenne de cardiologie **2022**, recommandations américaines **2020**.","prio":"P3","sec":"s1"},{"id":"fc-331-33b14e","poly":"cardio","fiche":"331","front":"Témoin : comment reconnaître un arrêt cardiaque ?","back":"Personne **inconsciente**, qui **ne bouge plus**, **ne réagit plus**, **ne respire plus** ou fait des **gasps**.","prio":"P1","sec":"s2"},{"id":"fc-331-5cb6e2","poly":"cardio","fiche":"331","front":"Secouriste ou soignant : quel signe ajoute-t-il au diagnostic d'arrêt cardiaque ?","back":"**Absence de pouls carotidien ou fémoral**.","prio":"P1","sec":"s2"},{"id":"fc-331-344c44","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : faut-il une certitude pour débuter la réanimation ?","back":"**Non** : la simple **suspicion** suffit → **15** + réanimation immédiate.","prio":"P1","sec":"s2"},{"id":"fc-331-fc4995","poly":"cardio","fiche":"331","front":"Patient inconscient qui fait des gasps : conduite ?","back":"C'est un **arrêt cardiaque** → **masser**.","prio":"P1","sec":"s2"},{"id":"fc-331-a0851c","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels prodromes possibles ?","back":"**Palpitations**, **douleur thoracique**.","prio":"P3","sec":"s2"},{"id":"fc-331-22cea8","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : sur quel terrain survient-il fréquemment ?","back":"**Maladie coronarienne** ou **insuffisance cardiaque** ; médicaments ayant pu faciliter l'arrêt.","prio":"P3","sec":"s2"},{"id":"fc-331-e7079b","poly":"cardio","fiche":"331","front":"Trouble du rythme de l'arrêt cardiaque : dans quelles circonstances survient-il ?","back":"**Au repos comme à l'effort** : FV d'emblée ou TV dégénérant en FV en quelques minutes.","prio":"P2","sec":"s2"},{"id":"fc-331-95c1a1","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le mode électrique initial le plus fréquent ?","back":"La **fibrillation ventriculaire** (FV).","prio":"P1","sec":"s3"},{"id":"fc-331-87457d","poly":"cardio","fiche":"331","front":"FV : quel est le seul traitement efficace et potentiellement durable ?","back":"Le **choc électrique externe** (CEE), + massage.","prio":"P1","sec":"s3"},{"id":"fc-331-38b601","poly":"cardio","fiche":"331","front":"TV sans pouls : quelle conduite ?","back":"**CEE** + massage (peut dégénérer en FV en quelques minutes).","prio":"P1","sec":"s3"},{"id":"fc-331-3fec5b","poly":"cardio","fiche":"331","front":"Asystolie : quelle conduite ?","back":"**Massage**, **pas de défibrillation**.","prio":"P1","sec":"s3"},{"id":"fc-331-b6f50b","poly":"cardio","fiche":"331","front":"Dissociation électromécanique : quelle définition et quelle conduite ?","back":"Activité électrique sans pouls ni PA (cœur agonique) → **poursuivre le massage**.","prio":"P2","sec":"s3"},{"id":"fc-331-936b41","poly":"cardio","fiche":"331","front":"Choc électrique sur une FV : quel mécanisme ?","back":"Dépolarise simultanément une **masse critique** de cellules → interrompt les **réentrées**.","prio":"P2","sec":"s3"},{"id":"fc-331-96bdfe","poly":"cardio","fiche":"331","front":"Quels rythmes le DSA reconnaît-il comme chocables ?","back":"**FV**, **flutter ventriculaire**, **TV à fréquence élevée**.","prio":"P3","sec":"s3"},{"id":"fc-331-ebdec5","poly":"cardio","fiche":"331","front":"Sans ECG : comment le DSA décide-t-il du choc ?","back":"Il **analyse lui-même** le rythme et ne choque que s'il est chocable.","prio":"P2","sec":"s3"},{"id":"fc-331-3e44ad","poly":"cardio","fiche":"331","front":"Défibrillateurs biphasiques vs monophasiques : quelles énergies ?","back":"Biphasique **jusqu'à 200 J** (plus sûr, plus efficace) ; monophasique **360 J**.","prio":"P3","sec":"s3"},{"id":"fc-331-604331","poly":"cardio","fiche":"331","front":"Au tout début de la RCP : dans quelle proportion trouve-t-on une FV ?","back":"**40 à 70 %** selon la rapidité de la RCP (sinon asystolie).","prio":"P3","sec":"s3"},{"id":"fc-331-cb3a05","poly":"cardio","fiche":"331","front":"Rythme initial selon l'ILCOR 2015 : quelles proportions ?","back":"**FV 70 à 80 %** ; **bradycardie extrême** (BAV haut degré, asystolie) **15 à 20 %**.","prio":"P3","sec":"s3"},{"id":"fc-331-dee6e1","poly":"cardio","fiche":"331","front":"FV non réanimée : comment évolue-t-elle ?","back":"Grosses puis petites mailles, puis tracé plat : **50 %** deviennent une asystolie entre la **4e et la 8e minute**.","prio":"P2","sec":"s3"},{"id":"fc-331-bb0d78","poly":"cardio","fiche":"331","front":"Asystolie : que traduit-elle sur le plan pronostique ?","back":"Un **marqueur du temps écoulé** depuis l'arrêt → **mauvais pronostic** (ou cause extracardiaque).","prio":"P2","sec":"s3"},{"id":"fc-331-ed596e","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur FV : délai idéal du premier choc ?","back":"Dans les **3 minutes** suivant l'arrêt.","prio":"P1","sec":"s3"},{"id":"fc-331-6f3223","poly":"cardio","fiche":"331","front":"Chaîne de survie : qui l'a décrite et quand ?","back":"**Cummins**, **1991**.","prio":"P1","sec":"s4"},{"id":"fc-331-459879","poly":"cardio","fiche":"331","front":"Chaîne de survie de Cummins : citer les 6 maillons ?","back":"**Alerte** précoce (15) ; **RCP** précoce ; **défibrillation** précoce ; **RCP spécialisée** (Smur) ; réanimation hospitalière ; **rétablissement**.","prio":"P1","sec":"s4"},{"id":"fc-331-4b05dc","poly":"cardio","fiche":"331","front":"Chaîne de survie : quels maillons relèvent du grand public ?","back":"L'**alerte précoce** (15) et la **RCP précoce**.","prio":"P2","sec":"s4"},{"id":"fc-331-4f12bc","poly":"cardio","fiche":"331","front":"Chaîne de survie en France : quels maillons sont faibles ?","back":"Les **3 premiers** : alerte, RCP et défibrillation précoces.","prio":"P1","sec":"s4"},{"id":"fc-331-102190","poly":"cardio","fiche":"331","front":"Chaîne de survie : qu'est-ce qui fait la survie ?","back":"La **rapidité** et la **complémentarité** des maillons.","prio":"P2","sec":"s4"},{"id":"fc-331-3cec6d","poly":"cardio","fiche":"331","front":"5e maillon de la chaîne de Cummins : que comprend-il ?","back":"Réanimation hospitalière de **haut niveau** : traiter la cause, hypothermie contrôlée, assistance circulatoire, correction métabolique.","prio":"P3","sec":"s4"},{"id":"fc-331-665dda","poly":"cardio","fiche":"331","front":"France : qui peut défibriller ?","back":"Médecins, mais aussi **infirmiers**, **secouristes** et **ambulanciers**.","prio":"P2","sec":"s4"},{"id":"fc-331-832532","poly":"cardio","fiche":"331","front":"DSA en France : quelle limite à leur déploiement ?","back":"**Peu nombreux** (notamment en cabinet médical) et **mal localisés**.","prio":"P3","sec":"s4"},{"id":"fc-331-1daa65","poly":"cardio","fiche":"331","front":"France : quelle proportion de la population est formée à la RCP ?","back":"Seulement **10 à 15 %**.","prio":"P2","sec":"s4"},{"id":"fc-331-930727","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quel est le rôle primordial du témoin ?","back":"**Raccourcir le no-flow** ; il peut être guidé par téléphone par le **régulateur**.","prio":"P1","sec":"s4"},{"id":"fc-331-132e40","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : de quels facteurs dépend le pronostic ?","back":"**Étiologie**, **lieu**, présence d'un **témoin**, **rapidité des premiers gestes**, et moindrement **durée de réanimation**.","prio":"P3","sec":"s4"},{"id":"fc-331-ba66db","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels éléments améliorent le pronostic ?","back":"Un **rythme chocable** ou la présence d'un **témoin**.","prio":"P1","sec":"s4"},{"id":"fc-331-0300d1","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : au-delà de quelle durée de réanimation le pronostic devient-il nul ?","back":"**30 à 45 minutes**.","prio":"P1","sec":"s4"},{"id":"fc-331-898449","poly":"cardio","fiche":"331","front":"Arrêt cardiaque (points clés) : comment qualifier le pronostic ?","back":"**Catastrophique** ; le principal facteur pronostique reste la **durée du no-flow**.","prio":"P1","sec":"s4"},{"id":"fc-331-391ae4","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quels facteurs initiaux favorables évalue le Smur ?","back":"**Témoin**, **FV** initiale, réanimation **précoce**, défibrillation **rapide**, réanimation **courte**.","prio":"P3","sec":"s4"},{"id":"fc-331-de6a25","poly":"cardio","fiche":"331","front":"Arrêt cardiaque préhospitalier : quelle survie globale ?","back":"**5 à 20 %** (mort quasi certaine **sans témoin**).","prio":"P3","sec":"s4"},{"id":"fc-331-a1fdaa","poly":"cardio","fiche":"331","front":"Patients arrivés vivants à l'hôpital : quelle proportion sort sans séquelle neurologique ?","back":"Seulement **20 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-f35c3b","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sans réanimation : de combien baisse la survie par minute ?","back":"De **10 % par minute**.","prio":"P3","sec":"s4"},{"id":"fc-331-495a76","poly":"cardio","fiche":"331","front":"FV défibrillée en 1 à 3 min : quelle survie ?","back":"**40 à 60 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-12c0f1","poly":"cardio","fiche":"331","front":"FV défibrillée en 4 à 6 min puis en 7 à 10 min : quelle survie ?","back":"**35 %** puis **25 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-db69eb","poly":"cardio","fiche":"331","front":"FV au-delà de 10 min : chance de récupérer un rythme efficace ?","back":"**< 5 %**.","prio":"P3","sec":"s4"},{"id":"fc-331-5b207f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque de l'adulte : quelle est la 1re étiologie ?","back":"**Coronaire** : cardiopathie ischémique aiguë (SCA inaugural) ou **séquelle d'infarctus**.","prio":"P1","sec":"s5"},{"id":"fc-331-ce9103","poly":"cardio","fiche":"331","front":"Cause immédiate la plus fréquente d'arrêt cardiaque : quel mécanisme ?","back":"Une **FV** d'origine **ischémique**.","prio":"P1","sec":"s5"},{"id":"fc-331-08e606","poly":"cardio","fiche":"331","front":"Citer les 3 grands mécanismes électriques d'arrêt cardiaque ?","back":"**FV**, **TV**, **asystolie**.","prio":"P1","sec":"s5"},{"id":"fc-331-69cb19","poly":"cardio","fiche":"331","front":"Bradycardies extrêmes responsables d'arrêt cardiaque : lesquelles ?","back":"**BAV de haut grade** ; **asystolie**.","prio":"P2","sec":"s5"},{"id":"fc-331-2ab8b5","poly":"cardio","fiche":"331","front":"Causes non cardiovasculaires d'arrêt cardiaque : quelle proportion et lesquelles ?","back":"**5 à 25 %** : surtout **toxiques**, **traumatiques**, **insuffisances respiratoires aiguës**, **noyades**.","prio":"P1","sec":"s5"},{"id":"fc-331-5c638d","poly":"cardio","fiche":"331","front":"Cardiomyopathies et valvulopathies causes d'arrêt cardiaque : lesquelles ?","back":"**CMH**, CMD, **dysplasie VD arythmogène**, valvulopathies (surtout **rétrécissement aortique**).","prio":"P3","sec":"s5"},{"id":"fc-331-9f7e03","poly":"cardio","fiche":"331","front":"CMH et mort subite : quelle circonstance fréquente ?","back":"**L'effort** (mais pas seulement) ; surtout CMH familiale et/ou obstructive.","prio":"P3","sec":"s5"},{"id":"fc-331-42bac6","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur cœur structurellement normal : quelles causes rythmiques ?","back":"**FV idiopathique**, **Brugada**, **QT long** ou **QT court**, **WPW**, troubles conductifs paroxystiques.","prio":"P3","sec":"s5"},{"id":"fc-331-c7654d","poly":"cardio","fiche":"331","front":"Citer d'autres causes cardiovasculaires d'arrêt cardiaque ?","back":"**Myocardite**, **tamponnade**, **dissection aortique**, **EP massive**, rupture d'anévrisme, cardiopathies congénitales.","prio":"P3","sec":"s5"},{"id":"fc-331-82e051","poly":"cardio","fiche":"331","front":"Morts subites : fréquence des lésions coronaires retrouvées ?","back":"**40 à 77 %** selon les études.","prio":"P3","sec":"s5"},{"id":"fc-331-e98a47","poly":"cardio","fiche":"331","front":"Quelle proportion d'arrêts cardiaques complique un infarctus ?","back":"**20 à 40 %**.","prio":"P3","sec":"s5"},{"id":"fc-331-2dc220","poly":"cardio","fiche":"331","front":"Arrêt cardiaque avant 30 ans : quelles causes évoquer ?","back":"Troubles du rythme ventriculaire **non ischémiques** et **cardiopathies congénitales** décompensées (coronaire rare).","prio":"P2","sec":"s5"},{"id":"fc-331-55b442","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quand alerter le 15 ?","back":"Dès que l'arrêt est **diagnostiqué ou seulement suspecté** ; demander de l'aide autour de soi.","prio":"P1","sec":"s6"},{"id":"fc-331-b6efbb","poly":"cardio","fiche":"331","front":"ACD : que signifient les 3 lettres ?","back":"**A** : libérer les voies aériennes ; **C** : massage cardiaque ; **D** : défibrillation.","prio":"P1","sec":"s6"},{"id":"fc-331-2bdfbf","poly":"cardio","fiche":"331","front":"Libération des voies aériennes (A) : quels gestes ?","back":"**Basculer la tête** en arrière, **relever le menton**, retirer un corps étranger (doigts en crochet).","prio":"P2","sec":"s6"},{"id":"fc-331-dea7e0","poly":"cardio","fiche":"331","front":"RCP : quel geste est la priorité ?","back":"Le **massage cardiaque externe** (raccourcit le no-flow).","prio":"P1","sec":"s6"},{"id":"fc-331-8d2630","poly":"cardio","fiche":"331","front":"Massage cardiaque externe de l'adulte : profondeur et fréquence ?","back":"**4 à 5 cm**, **100/min**, talon de la main au centre du thorax, victime à plat dos.","prio":"P1","sec":"s6"},{"id":"fc-331-b197b1","poly":"cardio","fiche":"331","front":"Plusieurs sauveteurs : tous les combien changer de masseur ?","back":"Environ toutes les **2 minutes**.","prio":"P2","sec":"s6"},{"id":"fc-331-26c394","poly":"cardio","fiche":"331","front":"Arrêt cardiaque de l'adulte : faut-il faire du bouche-à-bouche ?","back":"**Non** : pas d'insufflations ; interrompre le massage le moins possible.","prio":"P1","sec":"s6"},{"id":"fc-331-744cc3","poly":"cardio","fiche":"331","front":"DSA disponible avant le Smur : conduite ?","back":"L'**utiliser sans attendre** le Smur si on sait s'en servir.","prio":"P1","sec":"s6"},{"id":"fc-331-f10c31","poly":"cardio","fiche":"331","front":"Après un choc du DSA : que faire ?","back":"**Poursuivre la RCP 2 minutes** avant de rechercher une reprise circulatoire.","prio":"P1","sec":"s6"},{"id":"fc-331-0f5a47","poly":"cardio","fiche":"331","front":"Arrivée des secours : quel dispositif de libération des voies aériennes ?","back":"Une **canule de Guedel**.","prio":"P2","sec":"s6"},{"id":"fc-331-7e80ac","poly":"cardio","fiche":"331","front":"Pas de défibrillateur disponible : pourquoi masser dans tous les cas ?","back":"Le massage maintient une **oxygénation tissulaire minimale** et une circulation, d'abord vers le **cerveau**.","prio":"P1","sec":"s6"},{"id":"fc-331-4006d9","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle notion est inacceptable ?","back":"Ne pas connaître l'**ACD** (voies aériennes, massage, défibrillation).","prio":"P1","sec":"s6"},{"id":"fc-331-824755","poly":"cardio","fiche":"331","front":"Pourquoi l'oxygénation reste-t-elle essentielle chez l'enfant et le nourrisson ?","back":"L'arrêt y est souvent d'origine **hypoxique**.","prio":"P2","sec":"s6"},{"id":"fc-331-6f8ca9","poly":"cardio","fiche":"331","front":"Arrivée du Smur : quelles premières étapes ?","back":"**Évaluer les chances de survie**, puis RCP médicalisée selon l'**algorithme universel**.","prio":"P3","sec":"s7"},{"id":"fc-331-2595a5","poly":"cardio","fiche":"331","front":"Rythme chocable (points clés) : quand donner l'adrénaline et l'amiodarone ?","back":"Après **échec de 2 CEE** : **adrénaline IV** + **amiodarone 300 mg**.","prio":"P1","sec":"s7"},{"id":"fc-331-b20098","poly":"cardio","fiche":"331","front":"RCP médicalisée : quelle qualité de compressions ?","back":"**Très bonne qualité** (relais ou appareil), interruptions **minimales**, même pendant la ventilation.","prio":"P2","sec":"s7"},{"id":"fc-331-ac6f2a","poly":"cardio","fiche":"331","front":"RCP médicalisée : pendant l'intubation, combien de temps peut-on interrompre le massage ?","back":"**30 secondes** au plus (ventilation au masque si intubation difficile).","prio":"P2","sec":"s7"},{"id":"fc-331-fcc5a5","poly":"cardio","fiche":"331","front":"RCP médicalisée : quelle surveillance instrumentale ?","back":"**Capnographie** et **pression artérielle invasive**.","prio":"P3","sec":"s7"},{"id":"fc-331-a53444","poly":"cardio","fiche":"331","front":"FV/TV persistante après le 1er choc : quand donner l'adrénaline (texte) ?","back":"Après **2 min de RCP**, juste avant le **2e ou 3e choc**, puis toutes les **4 min**.","prio":"P2","sec":"s7"},{"id":"fc-331-77c04f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : posologie de l'adrénaline ?","back":"**1 mg IV** (ou endotrachéale) **toutes les 4 minutes**.","prio":"P2","sec":"s7"},{"id":"fc-331-bd1411","poly":"cardio","fiche":"331","front":"Arrêt cardiaque sur FV : quand donner l'amiodarone ?","back":"**300 mg** juste avant le **3e choc** ; **150 mg** de plus si FV/TV réfractaire ou récidivante.","prio":"P2","sec":"s7"},{"id":"fc-331-37bdd0","poly":"cardio","fiche":"331","front":"Amiodarone dans l'arrêt cardiaque : comment l'administrer ?","back":"**300 mg** dilués dans **20 à 30 mL** de sérum salé isotonique, **IV rapide**.","prio":"P3","sec":"s7"},{"id":"fc-331-a31816","poly":"cardio","fiche":"331","front":"Lidocaïne dans l'arrêt cardiaque : quelle place et quelle dose ?","back":"Seulement si **amiodarone indisponible** : **1,5 mg/kg** IV lente, sans dépasser **3 mg/kg**.","prio":"P3","sec":"s7"},{"id":"fc-331-49d140","poly":"cardio","fiche":"331","front":"Adrénaline dans l'arrêt cardiaque : quel pronostic selon la dose totale ?","back":"D'autant plus mauvais que la dose est forte : **au-delà de 1 à 2 mg**, survie faible.","prio":"P3","sec":"s7"},{"id":"fc-331-987382","poly":"cardio","fiche":"331","front":"Adrénaline : quel effet est surtout bénéfique dans l'arrêt cardiaque ?","back":"L'effet **alpha-adrénergique** (hausse des débits myocardique et cérébral).","prio":"P3","sec":"s7"},{"id":"fc-331-cc6edc","poly":"cardio","fiche":"331","front":"Amiodarone vs lidocaïne : laquelle améliore la survie à court terme ?","back":"L'**amiodarone**.","prio":"P3","sec":"s7"},{"id":"fc-331-54946d","poly":"cardio","fiche":"331","front":"Antiarythmiques dans l'arrêt cardiaque : quelle indication ?","back":"AC **réfractaire** avec troubles du rythme ventriculaire **récidivants après ≥ 2 chocs**.","prio":"P3","sec":"s7"},{"id":"fc-331-b43269","poly":"cardio","fiche":"331","front":"Rythme chocable : quels traitements préparer pendant la RCP ?","back":"Traitement de la **cause** (intoxication, revascularisation) ; discuter une **assistance circulatoire extracorporelle**.","prio":"P2","sec":"s7"},{"id":"fc-331-5b3225","poly":"cardio","fiche":"331","front":"Asystolie (points clés) : quel médicament ?","back":"**Adrénaline IV**.","prio":"P1","sec":"s8"},{"id":"fc-331-746d99","poly":"cardio","fiche":"331","front":"AC réfractaire en asystolie : quelle place de l'adrénaline ?","back":"Traitement **incontournable** : **1 mg toutes les 4 min**.","prio":"P2","sec":"s8"},{"id":"fc-331-feb8dd","poly":"cardio","fiche":"331","front":"Activité électrique au scope : suffit-elle à conclure à une circulation efficace ?","back":"**Non** : rechercher **pouls** et **PA**.","prio":"P2","sec":"s8"},{"id":"fc-331-da0907","poly":"cardio","fiche":"331","front":"Pronostic : FV ou asystolie ?","back":"Meilleur en **FV** qu'en asystolie.","prio":"P2","sec":"s8"},{"id":"fc-331-1861a0","poly":"cardio","fiche":"331","front":"Torsades de pointes ou hypomagnésémie suspectée pendant un arrêt : quel traitement ?","back":"**Sulfate de magnésium 2 g** en IV directe.","prio":"P2","sec":"s9"},{"id":"fc-331-44a69f","poly":"cardio","fiche":"331","front":"Bradycardie sinusale extrême pendant un arrêt : quel traitement et à quelle dose ?","back":"**Atropine 1 mg**, répétée toutes les **3 à 5 min**, jusqu'à **0,04 mg/kg** au total.","prio":"P2","sec":"s9"},{"id":"fc-331-6001d5","poly":"cardio","fiche":"331","front":"BAV du 3e degré sans hémodynamique efficace : quel traitement ?","back":"**Isoprénaline** (si cause conductive certaine).","prio":"P2","sec":"s9"},{"id":"fc-331-d61b5d","poly":"cardio","fiche":"331","front":"Isoprénaline : quelle préparation et quel objectif ?","back":"**5 ampoules à 0,2 mg** dans **250 mL** de G5 % ; objectif **classiquement** FC d'au moins **50-60/min**.","prio":"P3","sec":"s9"},{"id":"fc-331-07d1b2","poly":"cardio","fiche":"331","front":"Atropine et isoprénaline pendant un arrêt : quelle condition préalable ?","back":"Une cause **conductive ou vagale maligne certaine**.","prio":"P3","sec":"s9"},{"id":"fc-331-80bb73","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : après combien de temps apparaissent acidose métabolique et hyperkaliémie ?","back":"Après **3 à 4 minutes**.","prio":"P2","sec":"s9"},{"id":"fc-331-30e6aa","poly":"cardio","fiche":"331","front":"Bicarbonate de sodium 84 ‰ : dans quelles situations ?","back":"Réanimation **prolongée**, **hyperkaliémie**, acidose préexistante, intoxication aux **stabilisants de membrane** (tricycliques, phénobarbital).","prio":"P3","sec":"s9"},{"id":"fc-331-353639","poly":"cardio","fiche":"331","front":"Bicarbonate dans l'arrêt cardiaque : quel bénéfice démontré ?","back":"La plupart des études ne montrent **pas de gain significatif** de survie.","prio":"P3","sec":"s9"},{"id":"fc-331-0d9fc9","poly":"cardio","fiche":"331","front":"Thrombolyse préhospitalière pendant un arrêt : quand la discuter ?","back":"**Au cas par cas** si **IDM** ou **EP massive** avérés ou fortement suspectés (pas en routine).","prio":"P2","sec":"s9"},{"id":"fc-331-8dc9eb","poly":"cardio","fiche":"331","front":"Après reprise d'activité cardiaque : quand faire une coronarographie ?","back":"**Au moindre doute** de cause coronaire.","prio":"P1","sec":"s10"},{"id":"fc-331-8a897f","poly":"cardio","fiche":"331","front":"Arrêt cardiaque récupéré : quels arguments pour une cause coronaire ?","back":"**Antécédents**, **douleur thoracique** avant l'arrêt, **ECG** post-récupération compatible avec un SCA (sus-ST, BBG…).","prio":"P2","sec":"s10"},{"id":"fc-331-304815","poly":"cardio","fiche":"331","front":"Sidération myocardique post-arrêt : quel traitement de choix ?","back":"La **dobutamine** (inotrope positif).","prio":"P2","sec":"s10"},{"id":"fc-331-1a7de6","poly":"cardio","fiche":"331","front":"Sidération myocardique résistant à la dobutamine : quel recours ?","back":"**Assistance circulatoire** par pompe extracorporelle (± décharge VG).","prio":"P2","sec":"s10"},{"id":"fc-331-6e864c","poly":"cardio","fiche":"331","front":"Post-arrêt : comment surveiller la fonction cardiaque ?","back":"**Échocardiographie**, parfois cathéter de **Swan-Ganz**.","prio":"P3","sec":"s10"},{"id":"fc-331-dbaba8","poly":"cardio","fiche":"331","front":"Quels facteurs favorisent la sidération myocardique post-arrêt ?","back":"**No-flow** et **low-flow** prolongés, **fortes doses de vasopresseurs**, **chocs** nombreux et intenses.","prio":"P3","sec":"s10"},{"id":"fc-331-5757cb","poly":"cardio","fiche":"331","front":"Récupération d'un pouls après un arrêt : est-elle synonyme de survie ?","back":"**Non** : survie rare, séquelles **neurologiques** fréquentes.","prio":"P1","sec":"s10"},{"id":"fc-331-4217e1","poly":"cardio","fiche":"331","front":"Post-arrêt : quelles mesures sont indispensables pour protéger le cerveau ?","back":"**Contrôle thermique**, **contrôle glycémique**, **ni hypoxie ni hypercapnie**.","prio":"P1","sec":"s11"},{"id":"fc-331-3b2dfa","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi éviter hypoxie et hypercapnie ?","back":"Elles provoquent une **hypertension intracrânienne** fatale.","prio":"P2","sec":"s11"},{"id":"fc-331-f34699","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi lutter contre l'hyperglycémie ?","back":"Elle crée un **œdème cérébral** (effet osmotique).","prio":"P2","sec":"s11"},{"id":"fc-331-6acb21","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi prévenir l'hyperthermie ?","back":"Elle **aggrave les lésions d'ischémie-reperfusion**.","prio":"P2","sec":"s11"},{"id":"fc-331-46bb22","poly":"cardio","fiche":"331","front":"Hypothermie contrôlée post-arrêt : quelle cible et quelle place ?","back":"Autour de **34 °C** ; place **débattue** (éviter surtout l'hyperthermie).","prio":"P3","sec":"s11"},{"id":"fc-331-ff7fb9","poly":"cardio","fiche":"331","front":"Post-arrêt : quel rôle de la sédation ?","back":"Met le cerveau **au repos**, baisse ses besoins en O₂, limite l'œdème.","prio":"P3","sec":"s11"},{"id":"fc-331-0247be","poly":"cardio","fiche":"331","front":"Post-arrêt : pourquoi la pression artérielle est-elle cruciale ?","back":"L'**autorégulation** cérébrale peut être perdue : la PA conditionne le pronostic cérébral.","prio":"P3","sec":"s11"},{"id":"fc-331-874b16","poly":"cardio","fiche":"331","front":"Pronostic cérébral post-arrêt : quels examens, et quand sont-ils fiables ?","back":"**Glasgow**, **EEG**, **potentiels évoqués** répétés ; fiabilité accrue entre **J1 et J3**.","prio":"P3","sec":"s11"},{"id":"fc-331-86e607","poly":"cardio","fiche":"331","front":"Arrêt de la réanimation : comment est prise la décision ?","back":"Décision **collégiale**, orientée par un algorithme de **neuropronostication**.","prio":"P1","sec":"s11"},{"id":"fc-331-2593ed","poly":"cardio","fiche":"331","front":"Arrêt cardiaque : quelle information doit être donnée aux proches ?","back":"Une **information régulière** sur le pronostic et l'évolution.","prio":"P1","sec":"s11"},{"id":"fc-331-fd6e04","poly":"cardio","fiche":"331","front":"Information des proches après un arrêt : quelles modalités ?","back":"**Précoce**, permanente mais contrôlée (**peu d'interlocuteurs**).","prio":"P3","sec":"s11"},{"id":"fc-331-9745fb","poly":"cardio","fiche":"331","front":"Mort cérébrale après arrêt cardiaque : condition d'un prélèvement d'organes ?","back":"Information de la famille et absence d'inscription au **registre national des refus**.","prio":"P3","sec":"s11"},{"id":"fc-331-e693ca","poly":"cardio","fiche":"331","front":"Au-delà de quelle durée de no-flow peut-on s'interroger sur l'éthique de la réanimation ?","back":"**10 minutes**.","prio":"P3","sec":"s11"},{"id":"fc-331-953f8d","poly":"cardio","fiche":"331","front":"Survivants d'un arrêt cardiaque : quelles séquelles possibles ?","back":"De l'**état végétatif** aux séquelles **motrices et cognitives** lourdes, perte d'autonomie.","prio":"P3","sec":"s11"},{"id":"fc-339-bafe46","poly":"cardio","fiche":"339","front":"SCA : quelle définition générale ?","back":"Ensemble des manifestations d'une **ischémie myocardique aiguë**.","prio":"P1","sec":"s1"},{"id":"fc-339-320b24","poly":"cardio","fiche":"339","front":"SCA : quel examen sépare SCA ST+ et SCA ST- ?","back":"L'**ECG** du premier contact : sus-décalage **persistant** du ST ou non.","prio":"P1","sec":"s1"},{"id":"fc-339-9aaed4","poly":"cardio","fiche":"339","front":"SCA ST+ : quel mécanisme ?","back":"**Occlusion aiguë** d'une coronaire par un thrombus **fibrinocruorique** (ischémie transmurale).","prio":"P1","sec":"s1"},{"id":"fc-339-4986e0","poly":"cardio","fiche":"339","front":"SCA ST+ : quel traitement en urgence ?","back":"**Désobstruction immédiate** : angioplastie primaire ou fibrinolytique IV.","prio":"P1","sec":"s1"},{"id":"fc-339-723eee","poly":"cardio","fiche":"339","front":"SCA ST+ : quelle douleur typique ?","back":"Persistante **> 30 min**, **non soulagée** par la trinitrine sublinguale.","prio":"P1","sec":"s1"},{"id":"fc-339-95a776","poly":"cardio","fiche":"339","front":"SCA ST+ : faut-il attendre la troponine ?","back":"**Non** : elle est dosée mais son résultat n'est **pas attendu**.","prio":"P1","sec":"s1"},{"id":"fc-339-71897f","poly":"cardio","fiche":"339","front":"SCA ST- : comment distinguer IDM ST- et angor instable ?","back":"Par la **troponine** : élevée = **IDM ST-** ; non élevée = **angor instable**.","prio":"P1","sec":"s1"},{"id":"fc-339-c5c52f","poly":"cardio","fiche":"339","front":"Angor instable : est-ce un SCA ?","back":"**Oui** : diagnostic clinique, il reste un **SCA ST-** (troponine normale).","prio":"P1","sec":"s1"},{"id":"fc-339-5a49d3","poly":"cardio","fiche":"339","front":"SCA ST- : quels aspects ECG possibles ?","back":"**Sous-décalage** de ST, anomalies de **T**, ou ECG **normal** ; sus-décalage percritique régressif possible.","prio":"P2","sec":"s1"},{"id":"fc-339-1dd83f","poly":"cardio","fiche":"339","front":"Infarctus du myocarde : quelle définition biologique ?","back":"Troponine ultrasensible **> 99ᵉ percentile** de la limite supérieure + **au moins un** autre critère.","prio":"P1","sec":"s1"},{"id":"fc-339-413a9c","poly":"cardio","fiche":"339","front":"IDM : quels critères associer à la troponine élevée ?","back":"**Symptômes** ischémiques ; nouvelles anomalies **ECG** (repolarisation, onde Q) ; perte de myocarde viable en **imagerie** ; **thrombus** en coronarographie/autopsie.","prio":"P1","sec":"s1"},{"id":"fc-339-2cd706","poly":"cardio","fiche":"339","front":"IDM de type 1 : quel mécanisme ?","back":"**Accident de plaque** (rupture, ulcération, fissuration, érosion) avec thrombus.","prio":"P2","sec":"s1"},{"id":"fc-339-fe9640","poly":"cardio","fiche":"339","front":"IDM de type 2 : quel mécanisme ?","back":"**Déséquilibre apport/demande** en O₂ **sans** instabilité de plaque (anémie, hypoxémie, arythmie, hypo/hypertension…).","prio":"P2","sec":"s1"},{"id":"fc-339-bcefb4","poly":"cardio","fiche":"339","front":"IDM de type 3, 4 et 5 : quelles définitions ?","back":"Type 3 : **mort subite** sans troponine disponible ; types 4 et 5 : **iatrogènes** (angioplastie, pontage).","prio":"P3","sec":"s1"},{"id":"fc-339-9f11e4","poly":"cardio","fiche":"339","front":"IDM de type 1 : la lésion coronaire est-elle toujours sévère ?","back":"Le plus souvent, mais **mineure dans 5-10 %** des cas.","prio":"P3","sec":"s1"},{"id":"fc-339-0b8fb1","poly":"cardio","fiche":"339","front":"Incidence : comment évoluent SCA ST+ et SCA ST- ?","back":"Le ST+ **diminue**, le ST- **augmente** (probablement mieux repéré par la troponine ultrasensible).","prio":"P2","sec":"s1"},{"id":"fc-339-8c987d","poly":"cardio","fiche":"339","front":"IDM ST+ : quelle mortalité hospitalière en Europe ?","back":"**4 à 12 %** (proche de **10 % à 1 an**).","prio":"P2","sec":"s1"},{"id":"fc-339-f84b96","poly":"cardio","fiche":"339","front":"IDM ST+ : quels facteurs augmentent la mortalité ?","back":"Âge, diabète, insuffisance rénale ou cardiaque, ATCD d'IDM, **FEVG altérée**, atteinte diffuse, **prise en charge tardive**.","prio":"P3","sec":"s1"},{"id":"fc-339-b32311","poly":"cardio","fiche":"339","front":"France : combien d'hospitalisations par an pour IDM ?","back":"**Plus de 60 000**.","prio":"P3","sec":"s1"},{"id":"fc-339-88ab5f","poly":"cardio","fiche":"339","front":"SCA et sexe : quelle répartition selon l'âge ?","back":"Avant 60 ans : **4 fois plus** chez l'homme ; après 75 ans : plus fréquents chez la **femme** (retard de 7 à 10 ans).","prio":"P2","sec":"s1"},{"id":"fc-339-dcdf96","poly":"cardio","fiche":"339","front":"SCA chez la femme : la prise en charge diffère-t-elle ?","back":"**Non** : la même dans les deux sexes (symptômes plus souvent atypiques, hospitalisation plus tardive).","prio":"P1","sec":"s1"},{"id":"fc-339-27e655","poly":"cardio","fiche":"339","front":"SCA : quelle complication peut compliquer toutes les formes ?","back":"La **mort subite** (rythmique).","prio":"P2","sec":"s1"},{"id":"fc-339-0949e5","poly":"cardio","fiche":"339","front":"Plaque vulnérable : quelles caractéristiques ?","back":"Gros **cœur lipidique nécrotique** + **fine chape fibreuse**.","prio":"P3","sec":"s1"},{"id":"fc-339-089bfa","poly":"cardio","fiche":"339","front":"Thrombus du SCA : quel type selon la forme ?","back":"Petit thrombus **blanc** (plaquettaire) non occlusif → **ST-** ; gros thrombus **rouge** occlusif → **ST+**.","prio":"P3","sec":"s1"},{"id":"fc-339-9ad93e","poly":"cardio","fiche":"339","front":"Sus-décalage de ST : comment distinguer spasme et thrombose occlusive ?","back":"**Spasme** (Prinzmetal) : régresse sous **trinitrine** ; thrombose occlusive (ST+) : **persiste**.","prio":"P3","sec":"s1"},{"id":"fc-339-177807","poly":"cardio","fiche":"339","front":"Angor stable vs SCA : quelle différence de mécanisme ?","back":"Angor stable : rétrécissement **progressif** ; SCA : rupture **brutale et imprévisible** de plaque.","prio":"P3","sec":"s1"},{"id":"fc-339-81f0e8","poly":"cardio","fiche":"339","front":"SCA : citer des facteurs déclenchants ?","back":"**Effort violent**, manque de sommeil, excès alimentaire, **infection aiguë**.","prio":"P3","sec":"s1"},{"id":"fc-339-033e67","poly":"cardio","fiche":"339","front":"Douleur thoracique aiguë : quel premier réflexe ?","back":"**Appeler le 15** (Smur, ECG sur place) ; un autre intervenant en 1re intention est à proscrire.","prio":"P1","sec":"s2"},{"id":"fc-339-c8ace5","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : dans quel délai faire l'ECG ?","back":"Dans les **10 minutes**.","prio":"P1","sec":"s2"},{"id":"fc-339-c03b32","poly":"cardio","fiche":"339","front":"Douleur angineuse typique : quelles caractéristiques ?","back":"**Rétrosternale**, **en barre**, **constrictive** ; irradiation bras, cou, **mâchoire** ; intermittente ou persistante.","prio":"P1","sec":"s2"},{"id":"fc-339-8e71fa","poly":"cardio","fiche":"339","front":"SCA : quels signes associés possibles ?","back":"**Sueurs**, nausées, gêne épigastrique, **dyspnée**, malaise lipothymique, voire syncope.","prio":"P2","sec":"s2"},{"id":"fc-339-95605f","poly":"cardio","fiche":"339","front":"SCA : quelles formes atypiques ?","back":"Douleur **épigastrique** ou absente, limitée aux irradiations, brûlure, **dyspnée** ou **asthénie** isolée.","prio":"P1","sec":"s2"},{"id":"fc-339-479a3e","poly":"cardio","fiche":"339","front":"SCA atypique : chez quels patients est-il plus fréquent ?","back":"**Sujet âgé**, **femme**, **diabétique**, **insuffisant rénal**, patient **dément**.","prio":"P1","sec":"s2"},{"id":"fc-339-18b901","poly":"cardio","fiche":"339","front":"Soulagement par la trinitrine : quelle valeur diagnostique ?","back":"**Évocateur mais non spécifique**, et seulement dans le SCA ST-.","prio":"P2","sec":"s2"},{"id":"fc-339-eddce8","poly":"cardio","fiche":"339","front":"Quels tableaux douloureux orientent vers un SCA ST- ?","back":"Douleur spontanée **> 20 min** ; angor **inaugural récent** (< 1 mois) ; angor **crescendo** ; angor **post-IDM**.","prio":"P1","sec":"s2"},{"id":"fc-339-7a645b","poly":"cardio","fiche":"339","front":"Angor inaugural récent orientant vers un SCA ST- : quels critères ?","back":"Moins d'**1 mois**, pour des efforts modérés (classes **II-III** de la CCS).","prio":"P2","sec":"s2"},{"id":"fc-339-28338a","poly":"cardio","fiche":"339","front":"SCA : citer des facteurs de déstabilisation ?","back":"**Anémie**, **infection**, hyperthermie, poussée hypertensive, émotion, exercice violent, **hyperthyroïdie**, chirurgie.","prio":"P2","sec":"s2"},{"id":"fc-339-ab364c","poly":"cardio","fiche":"339","front":"SCA : quel terrain le rend plus probable ?","back":"Âge, homme, **tabac**, hérédité, **diabète**, dyslipidémie, **HTA**, IRC, athérome connu.","prio":"P2","sec":"s2"},{"id":"fc-339-9a2f9c","poly":"cardio","fiche":"339","front":"SCA : que chercher à l'examen physique ?","back":"**Insuffisance cardiaque** congestive, **souffle systolique** (complication mécanique), facteurs de risque, autres localisations athéromateuses.","prio":"P2","sec":"s2"},{"id":"fc-339-1d7250","poly":"cardio","fiche":"339","front":"Douleur thoracique : pourquoi mesurer la PA aux deux bras ?","back":"Une **asymétrie** évoque une **dissection aortique**.","prio":"P1","sec":"s2"},{"id":"fc-339-afffee","poly":"cardio","fiche":"339","front":"ECG 12 dérivations initial du SCA : quels sont ses deux buts ?","back":"**Diagnostic** (sus-décalage persistant ou non) + détection d'une **arythmie ventriculaire** menaçante (**TV**, **FV**).","prio":"P2","sec":"s3"},{"id":"fc-339-023d22","poly":"cardio","fiche":"339","front":"SCA ST- : quand doser la troponine ultrasensible ?","back":"À l'**admission** puis **1 à 2 h** plus tard.","prio":"P1","sec":"s3"},{"id":"fc-339-08a4fe","poly":"cardio","fiche":"339","front":"SCA : quel bilan biologique standard ?","back":"**Glycémie**, **bilan lipidique**, **créatininémie**, **NFS**.","prio":"P2","sec":"s3"},{"id":"fc-339-0f93c6","poly":"cardio","fiche":"339","front":"ETT dans le SCA : quelle place selon le type ?","back":"Ne doit **pas retarder** un ST+ (sauf complication mécanique suspectée) ; très largement indiquée dans le ST-.","prio":"P2","sec":"s3"},{"id":"fc-339-a866b0","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel aspect et combien de dérivations ?","back":"Onde de **Pardee** convexe vers le haut, dans **au moins 2 dérivations contiguës**.","prio":"P1","sec":"s3"},{"id":"fc-339-40ad39","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel seuil en V2-V3 ?","back":"**≥ 2 mm** (≥ 2,5 mm chez l'homme < 40 ans ; ≥ 1,5 mm chez la femme).","prio":"P1","sec":"s3"},{"id":"fc-339-6344f2","poly":"cardio","fiche":"339","front":"Sus-décalage du ST : quel seuil hors V2-V3 ?","back":"**≥ 1 mm** (en l'absence de BBG ou d'HVG).","prio":"P1","sec":"s3"},{"id":"fc-339-4ec244","poly":"cardio","fiche":"339","front":"SCA ST+ : à partir de quand apparaît l'onde Q de nécrose ?","back":"Classiquement à partir de la **6ᵉ heure**.","prio":"P2","sec":"s3"},{"id":"fc-339-57fbb4","poly":"cardio","fiche":"339","front":"SCA ST+ : qu'est-ce que le miroir ?","back":"Un **sous-décalage** dans les dérivations **opposées** (habituel).","prio":"P2","sec":"s3"},{"id":"fc-339-653817","poly":"cardio","fiche":"339","front":"Sus-décalage en V1, V2, V3 : quel territoire ?","back":"**Antéroseptal**.","prio":"P1","sec":"s3"},{"id":"fc-339-9e312a","poly":"cardio","fiche":"339","front":"Sus-décalage en V4 : quel territoire ?","back":"**Apical**.","prio":"P2","sec":"s3"},{"id":"fc-339-a88541","poly":"cardio","fiche":"339","front":"Sus-décalage en V5, V6 : quel territoire ?","back":"**Latéral bas**.","prio":"P2","sec":"s3"},{"id":"fc-339-56fa92","poly":"cardio","fiche":"339","front":"Sus-décalage en D1, aVL : quel territoire ?","back":"**Latéral haut**.","prio":"P1","sec":"s3"},{"id":"fc-339-a7fcdd","poly":"cardio","fiche":"339","front":"Sus-décalage en D2, D3, aVF : quel territoire ?","back":"**Inférieur**.","prio":"P1","sec":"s3"},{"id":"fc-339-90a62a","poly":"cardio","fiche":"339","front":"Sus-décalage en V7, V8, V9 : quel territoire ?","back":"**Postérieur**.","prio":"P1","sec":"s3"},{"id":"fc-339-cbba67","poly":"cardio","fiche":"339","front":"Sus-décalage de V1 à V6 : quel territoire ?","back":"**Antérieur étendu**.","prio":"P2","sec":"s3"},{"id":"fc-339-382484","poly":"cardio","fiche":"339","front":"Sus-décalage inférieur : quelles dérivations ajouter ?","back":"**V3R-V4R** (extension au ventricule droit).","prio":"P1","sec":"s3"},{"id":"fc-339-dcc759","poly":"cardio","fiche":"339","front":"Sous-décalage V1-V3 avec angor persistant : quelle conduite ECG ?","back":"Enregistrer **V7-V9** : un sus-décalage **≥ 0,5 mm** confirme un SCA ST+ (miroir).","prio":"P1","sec":"s3"},{"id":"fc-339-b1188b","poly":"cardio","fiche":"339","front":"BBG chez un patient avec angor persistant : quelle valeur ?","back":"**Équivalent de sus-décalage** (récent ou non).","prio":"P1","sec":"s3"},{"id":"fc-339-e6ab9d","poly":"cardio","fiche":"339","front":"BBG supposé récent chez un patient asymptomatique : quelle valeur ?","back":"**Aucune valeur diagnostique**.","prio":"P2","sec":"s3"},{"id":"fc-339-62cb57","poly":"cardio","fiche":"339","front":"BBD associé à une ischémie : quelle valeur ?","back":"**Équivalent de sus-décalage** (pronostic péjoratif, souvent territoire antérieur).","prio":"P2","sec":"s3"},{"id":"fc-339-049a6c","poly":"cardio","fiche":"339","front":"Pacemaker en stimulation ventriculaire : quelle limite de l'ECG ?","back":"Il ne permet **pas de voir** un sus-décalage.","prio":"P3","sec":"s3"},{"id":"fc-339-9fdfc6","poly":"cardio","fiche":"339","front":"Angor prolongé persistant avec ECG non contributif : conduite ?","back":"**Coronarographie au plus vite**, même si un autre diagnostic est évoqué, dès que le terrain expose.","prio":"P2","sec":"s3"},{"id":"fc-339-4b4d2c","poly":"cardio","fiche":"339","front":"SCA ST- : un ECG normal élimine-t-il le diagnostic ?","back":"**Non** : normal chez **plus de 30 %** des patients.","prio":"P1","sec":"s3"},{"id":"fc-339-edb499","poly":"cardio","fiche":"339","front":"SCA ST- : quand renouveler l'ECG ?","back":"Si la **douleur revient**, et systématiquement **1 à 2 h** plus tard.","prio":"P1","sec":"s3"},{"id":"fc-339-f2a6e7","poly":"cardio","fiche":"339","front":"BBD chez un patient symptomatique : quel aspect oriente vers un SCA ST- ?","back":"**Sous-décalage** de ST en **D1-aVL** et **V5-V6**.","prio":"P3","sec":"s3"},{"id":"fc-339-b4e53d","poly":"cardio","fiche":"339","front":"Troponine ultrasensible : quelle cinétique ?","back":"Monte **dans l'heure** suivant la douleur, reste élevée **plusieurs jours**.","prio":"P2","sec":"s3"},{"id":"fc-339-99bd50","poly":"cardio","fiche":"339","front":"Troponine élevée : quelles causes non coronaires ?","back":"**Tachyarythmie**, **IC**, poussée hypertensive, **myocardite**, valvulopathie, **EP**, **dissection aortique**, **takotsubo**…","prio":"P1","sec":"s3"},{"id":"fc-339-71af2a","poly":"cardio","fiche":"339","front":"Troponine ultrasensible : de quels paramètres dépendent ses valeurs ?","back":"**Âge**, **insuffisance rénale**, délai depuis les symptômes, **sexe**.","prio":"P3","sec":"s3"},{"id":"fc-339-d60eb2","poly":"cardio","fiche":"339","front":"Algorithme troponine 0/1-2 h : que signifie rule-in ?","back":"SCA **très probable** : valeur initiale très élevée ou **hausse significative**.","prio":"P2","sec":"s3"},{"id":"fc-339-c6df05","poly":"cardio","fiche":"339","front":"Algorithme troponine 0/1-2 h : que signifie rule-out ?","back":"SCA **très peu probable** : valeur initiale **très basse et stable**.","prio":"P2","sec":"s3"},{"id":"fc-339-b45453","poly":"cardio","fiche":"339","front":"ETT dans le SCA : qu'apporte-t-elle ?","back":"Troubles de **cinétique segmentaire** et **FEVG** (pronostique) ; aide au diagnostic différentiel.","prio":"P2","sec":"s3"},{"id":"fc-339-697b07","poly":"cardio","fiche":"339","front":"Coroscanner : quel est son principal atout diagnostique ?","back":"Excellente **valeur prédictive négative** (peu invasif, montre la sténose et analyse la plaque).","prio":"P3","sec":"s3"},{"id":"fc-339-c38149","poly":"cardio","fiche":"339","front":"SCA ST+ : quel délai décide entre angioplastie primaire et fibrinolyse ?","back":"**120 minutes** : angioplastie si faisable dans ce délai, sinon **fibrinolyse**.","prio":"P1","sec":"s4"},{"id":"fc-339-d2e4c2","poly":"cardio","fiche":"339","front":"SCA ST+ avec angioplastie faisable à temps : quel trajet du patient ?","back":"Transfert **direct en salle de coronarographie** puis Usic après revascularisation.","prio":"P1","sec":"s4"},{"id":"fc-339-716aab","poly":"cardio","fiche":"339","front":"Après fibrinolyse : quelle conduite selon le résultat ?","back":"**Échec** → angioplastie de **sauvetage** ; **succès** → coronarographie **dans les 24 h**.","prio":"P1","sec":"s4"},{"id":"fc-339-1d5f83","poly":"cardio","fiche":"339","front":"Reperfusion du SCA ST+ : à partir de quand le bénéfice devient-il faible ?","back":"À partir de la **12ᵉ heure** (voire nul après la 24ᵉ).","prio":"P1","sec":"s4"},{"id":"fc-339-97e500","poly":"cardio","fiche":"339","front":"SCA ST- à très haut risque : dans quel délai la coronarographie ?","back":"**Dans les 2 heures** (comme un ST+), transfert immédiat.","prio":"P1","sec":"s4"},{"id":"fc-339-8a5798","poly":"cardio","fiche":"339","front":"SCA ST- : quels critères de très haut risque ?","back":"**Instabilité hémodynamique**/choc ; douleur **réfractaire** ; **IC** ; **TV/FV**/arrêt ; **complication mécanique** ; ECG dynamique.","prio":"P1","sec":"s4"},{"id":"fc-339-b10e91","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : dans quel délai la coronarographie ?","back":"**Dans les 24 heures**.","prio":"P1","sec":"s4"},{"id":"fc-339-518f10","poly":"cardio","fiche":"339","front":"SCA ST- : quels critères de haut risque ?","back":"**IDM ST- confirmé** (troponine) ; **GRACE > 140** ; sus-décalage **transitoire** ; sous-décalage **dynamique** ou T négativées.","prio":"P1","sec":"s4"},{"id":"fc-339-f67a57","poly":"cardio","fiche":"339","front":"SCA ST- sans critère de risque : quelle stratégie ?","back":"Stratégie invasive **ou** test non invasif, selon les habitudes et les explorations disponibles.","prio":"P2","sec":"s4"},{"id":"fc-339-76d0b1","poly":"cardio","fiche":"339","front":"SCA : quels facteurs de risque hémorragique évaluer ?","back":"**> 75 ans**, sexe **féminin**, **insuffisance rénale**, diathèse hémorragique, **AVC ancien**, poids **< 65 kg**, chirurgie récente.","prio":"P3","sec":"s4"},{"id":"fc-339-c02cb1","poly":"cardio","fiche":"339","front":"SCA ST- : où hospitaliser le patient ?","back":"Habituellement **soins intensifs** ; **unité douleur thoracique** possible si non compliqué ou bas risque.","prio":"P2","sec":"s4"},{"id":"fc-339-2e0b96","poly":"cardio","fiche":"339","front":"SCA : citer les notions inacceptables ?","back":"Ne pas **évoquer** le diagnostic à l'interrogatoire ; ne pas faire l'**ECG** immédiat ; ne pas doser la **troponine** 0 et 1-2 h ; ne pas évaluer la **gravité** du ST-.","prio":"P1","sec":"s4"},{"id":"fc-339-cc7371","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : quelle part est d'origine non cardiaque ?","back":"Environ **50 %**.","prio":"P2","sec":"s5"},{"id":"fc-339-47f760","poly":"cardio","fiche":"339","front":"Douleur thoracique au SAU : quelle part d'IDM ST+, d'IDM ST- et d'angor instable ?","back":"**5-10 %** IDM ST+ ; **15-20 %** IDM ST- ; **10 %** angor instable.","prio":"P3","sec":"s5"},{"id":"fc-339-238a18","poly":"cardio","fiche":"339","front":"SCA : quels diagnostics différentiels cardiovasculaires non coronariens ?","back":"**Dissection aortique**, **embolie pulmonaire**, **myocardite/péricardite**, **takotsubo**.","prio":"P1","sec":"s5"},{"id":"fc-339-1f92d9","poly":"cardio","fiche":"339","front":"SCA : citer des diagnostics différentiels extracardiaques ?","back":"**Pneumothorax**, pleurésie, pneumopathie, fracture de côte, **pancréatite**, cholécystite, **RGO**, œsophagite.","prio":"P2","sec":"s5"},{"id":"fc-339-8e55a0","poly":"cardio","fiche":"339","front":"Syndrome de takotsubo : quelle particularité ECG ?","back":"Le **sus-décalage** de ST est parfois **absent**.","prio":"P3","sec":"s5"},{"id":"fc-339-ceb2cb","poly":"cardio","fiche":"339","front":"MINOCA : quelle définition ?","back":"Critères d'**IDM** **sans** sténose **> 50 %** en coronarographie ou coroscanner.","prio":"P2","sec":"s5"},{"id":"fc-339-30cd49","poly":"cardio","fiche":"339","front":"MINOCA : quelle fréquence et quel profil ?","back":"Environ **6 %** des SCA ; plutôt **IDM ST-**, patients plus **jeunes**, ≈ 40 % de **femmes**.","prio":"P3","sec":"s5"},{"id":"fc-339-becf09","poly":"cardio","fiche":"339","front":"MINOCA : quels examens ont une place importante dans le diagnostic ?","back":"L'**IRM** et l'**imagerie endocoronarienne**.","prio":"P3","sec":"s5"},{"id":"fc-339-9aa581","poly":"cardio","fiche":"339","front":"Spasme, dissection coronaire spontanée, embolie coronaire : quel type d'IDM ?","back":"**Type 2**.","prio":"P3","sec":"s5"},{"id":"fc-339-a0b546","poly":"cardio","fiche":"339","front":"SCA ST+ : quand débuter l'aspirine, et à quelle dose ?","back":"**Dès la suspicion** : **250 mg IVD**, puis **75-100 mg/j** per os, + IPP.","prio":"P1","sec":"s6"},{"id":"fc-339-58f2a5","poly":"cardio","fiche":"339","front":"SCA ST+ par angioplastie primaire : quel P2Y12 en 1re intention ?","back":"**Prasugrel** ou **ticagrélor** (clopidogrel si CI ou risque hémorragique).","prio":"P1","sec":"s6"},{"id":"fc-339-2d94fc","poly":"cardio","fiche":"339","front":"SCA : quelle dose du prasugrel ?","back":"Charge **60 mg** per os → **10 mg/j**.","prio":"P1","sec":"s6"},{"id":"fc-339-dfc6da","poly":"cardio","fiche":"339","front":"SCA : quelle dose du ticagrélor ?","back":"Charge **180 mg** → **90 mg matin et soir**.","prio":"P1","sec":"s6"},{"id":"fc-339-79388b","poly":"cardio","fiche":"339","front":"SCA : quelle dose du clopidogrel (hors fibrinolyse) ?","back":"Charge **600 mg** per os → **75 mg/j**.","prio":"P1","sec":"s6"},{"id":"fc-339-3fbc31","poly":"cardio","fiche":"339","front":"Prasugrel : quand est-il contre-indiqué ou non recommandé ?","back":"**CI** si ATCD d'**AVC** ; non recommandé si **> 75 ans** et/ou **< 60 kg**.","prio":"P1","sec":"s6"},{"id":"fc-339-d11b01","poly":"cardio","fiche":"339","front":"Ticagrélor : quels effets indésirables ?","back":"**Bradycardie** et **dyspnée**, réversibles à l'arrêt.","prio":"P2","sec":"s6"},{"id":"fc-339-d50f92","poly":"cardio","fiche":"339","front":"Clopidogrel dans le SCA : quand l'utiliser ?","back":"Si prasugrel et ticagrélor **contre-indiqués** (risque hémorragique, ATCD d'AVC, insuffisance hépatique sévère).","prio":"P2","sec":"s6"},{"id":"fc-339-0f0e45","poly":"cardio","fiche":"339","front":"Angioplastie primaire : quel anticoagulant et quelle dose ?","back":"**HNF 70-100 UI/kg IVD** ou **énoxaparine 0,5 mg/kg IVD**.","prio":"P1","sec":"s6"},{"id":"fc-339-be0521","poly":"cardio","fiche":"339","front":"Angioplastie primaire : quand arrêter l'anticoagulant ?","back":"Habituellement **juste après la revascularisation**.","prio":"P2","sec":"s6"},{"id":"fc-339-b0bf64","poly":"cardio","fiche":"339","front":"Angioplastie coronaire : quelle voie d'abord préférer et pourquoi ?","back":"**Radiale** : beaucoup **moins de saignements** que la fémorale.","prio":"P1","sec":"s6"},{"id":"fc-339-f0ff93","poly":"cardio","fiche":"339","front":"SCA : quand donner de l'oxygène ?","back":"Seulement si **SaO₂ < 90 %** ou **PaO₂ < 60 mmHg** (hyperoxie délétère).","prio":"P1","sec":"s6"},{"id":"fc-339-e2bdc4","poly":"cardio","fiche":"339","front":"SCA : quand donner de la morphine ?","back":"Si **douleur persistante invalidante**.","prio":"P2","sec":"s6"},{"id":"fc-339-adaf9d","poly":"cardio","fiche":"339","front":"Dérivés nitrés IV dans le SCA : quelle molécule et quelle dose ?","back":"**Dinitrate d'isosorbide 2 mg/h**, adapté à la PA.","prio":"P2","sec":"s6"},{"id":"fc-339-9f0a8b","poly":"cardio","fiche":"339","front":"Infarctus du VD : quelle classe est contre-indiquée ?","back":"Les **vasodilatateurs** (dérivés nitrés…).","prio":"P1","sec":"s6"},{"id":"fc-339-758eb6","poly":"cardio","fiche":"339","front":"SCA ST+ pluritronculaire : que faire des autres sténoses significatives ?","back":"**Revascularisation systématique** recommandée.","prio":"P2","sec":"s6"},{"id":"fc-339-df492c","poly":"cardio","fiche":"339","front":"Bêtabloquants dans le SCA : quel effet recherché ?","back":"Baisse de la **consommation d'O₂** (bradycardisants, hypotenseurs, inotropes négatifs).","prio":"P2","sec":"s6"},{"id":"fc-339-bd89b9","poly":"cardio","fiche":"339","front":"Fibrinolyse : quel est le seul inhibiteur P2Y12 autorisé ?","back":"Le **clopidogrel**.","prio":"P1","sec":"s7"},{"id":"fc-339-b579be","poly":"cardio","fiche":"339","front":"Clopidogrel avec fibrinolyse : quelle dose de charge ?","back":"**300 mg**, seulement si âge **< 75 ans** (pas de charge sinon) ; entretien 75 mg/j.","prio":"P1","sec":"s7"},{"id":"fc-339-e37303","poly":"cardio","fiche":"339","front":"Fibrinolyse du SCA ST+ : où et quand ?","back":"IV, **immédiate**, **dès le domicile**.","prio":"P2","sec":"s7"},{"id":"fc-339-7178d4","poly":"cardio","fiche":"339","front":"Fibrinolyse réussie : faut-il transférer le patient ?","back":"**Oui** : vers un centre avec salle de cathétérisme (coronarographie dans les 24 h).","prio":"P1","sec":"s7"},{"id":"fc-339-e82998","poly":"cardio","fiche":"339","front":"Fibrinolyse : quelles contre-indications absolues cérébrales ?","back":"ATCD d'**AVC hémorragique** ; **AVC < 6 mois** ; malformation ou tumeur cérébrale ; **traumatisme cérébral < 1 mois**.","prio":"P1","sec":"s7"},{"id":"fc-339-d4d12c","poly":"cardio","fiche":"339","front":"Fibrinolyse : quelles contre-indications absolues non cérébrales ?","back":"**Hémorragie digestive < 1 mois** ; anomalie de l'hémostase ; ponction/biopsie ou PL **< 24 h** ; **dissection aortique**.","prio":"P1","sec":"s7"},{"id":"fc-339-9cd3b1","poly":"cardio","fiche":"339","front":"SCA ST- : quand donner l'inhibiteur P2Y12 ?","back":"**Après la coronarographie**, **avant l'angioplastie** (souvent sur table).","prio":"P1","sec":"s8"},{"id":"fc-339-df238f","poly":"cardio","fiche":"339","front":"SCA ST- : quand peut-on donner le P2Y12 avant la coronarographie ?","back":"Si la coronarographie ne peut être faite **avant 24 h**.","prio":"P2","sec":"s8"},{"id":"fc-339-25f932","poly":"cardio","fiche":"339","front":"SCA ST- : pourquoi pas de double antiagrégation dès l'admission ?","back":"**Plus de saignements**.","prio":"P2","sec":"s8"},{"id":"fc-339-1458a6","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : quelle dose d'énoxaparine ?","back":"**1 mg/kg SC matin et soir**.","prio":"P1","sec":"s8"},{"id":"fc-339-716c84","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : quelle dose de fondaparinux, et quel ajout ?","back":"**2,5 mg/j SC** + **bolus d'HNF** pendant la coronarographie.","prio":"P1","sec":"s8"},{"id":"fc-339-539773","poly":"cardio","fiche":"339","front":"SCA ST- : quand utiliser l'HNF IVSE, et à quelle dose ?","back":"Si **IRC sévère** (CI des HBPM et du fondaparinux) : **400-600 UI/kg/24 h**.","prio":"P2","sec":"s8"},{"id":"fc-339-29c5d5","poly":"cardio","fiche":"339","front":"SCA ST- à haut risque : combien de temps dure l'anticoagulation ?","back":"De l'**admission en Usic** jusqu'à l'**angioplastie** ou au **pontage**.","prio":"P2","sec":"s8"},{"id":"fc-339-c68e76","poly":"cardio","fiche":"339","front":"SCA ST- : de quoi dépend le choix angioplastie ou pontage ?","back":"**Siège et étendue** des lésions, **âge**, **comorbidités**, **risque opératoire**.","prio":"P2","sec":"s8"},{"id":"fc-339-316be4","poly":"cardio","fiche":"339","front":"SCA ST- : quand le pontage est-il plutôt retenu ?","back":"Lésions du **tronc coronaire gauche** ou **tritronculaires complexes**, surtout chez le **diabétique**.","prio":"P3","sec":"s8"},{"id":"fc-339-0788ec","poly":"cardio","fiche":"339","front":"SCA ST- sans complication : quand le patient sort-il ?","back":"**24-48 h** après la revascularisation.","prio":"P2","sec":"s8"},{"id":"fc-339-3ee148","poly":"cardio","fiche":"339","front":"Dérivés nitrés IV dans le SCA ST- : quel but ?","back":"Visée **antalgique** (aussi antihypertensive ou IC congestive).","prio":"P2","sec":"s8"},{"id":"fc-339-3647c4","poly":"cardio","fiche":"339","front":"Angioplastie coronaire : comment se déroule-t-elle ?","back":"Lésion franchie par un **guide**, dilatée au **ballonnet** ; un **stent** serti sur le ballonnet peut être plaqué dans la paroi.","prio":"P2","sec":"s9"},{"id":"fc-339-438220","poly":"cardio","fiche":"339","front":"Angioplastie : pourquoi donner HNF ou HBPM pendant le geste ?","back":"Pour éviter la **thrombose du cathéter**.","prio":"P2","sec":"s9"},{"id":"fc-339-06630e","poly":"cardio","fiche":"339","front":"Après angioplastie pour SCA : durée de la bithérapie antiagrégante ?","back":"**12 mois** (modulable selon les risques ischémique et hémorragique).","prio":"P1","sec":"s9"},{"id":"fc-339-a179da","poly":"cardio","fiche":"339","front":"Après angioplastie dans l'angor stable : durée habituelle de la bithérapie ?","back":"**6 mois**.","prio":"P2","sec":"s9"},{"id":"fc-339-7e2e2c","poly":"cardio","fiche":"339","front":"Pontage coronarien : quel greffon préférer ?","back":"**Artériel** (artères **mammaires**) ; possiblement veineux (**veine saphène**).","prio":"P2","sec":"s9"},{"id":"fc-339-d9b662","poly":"cardio","fiche":"339","front":"Pontage coronarien : traite-t-il la lésion ?","back":"**Non** : il la **contourne**.","prio":"P2","sec":"s9"},{"id":"fc-339-b9efbf","poly":"cardio","fiche":"339","front":"Pontage coronarien : quelles conditions opératoires habituelles ?","back":"**Sternotomie**, anesthésie générale, cœur arrêté, **circulation extracorporelle**.","prio":"P3","sec":"s9"},{"id":"fc-339-914246","poly":"cardio","fiche":"339","front":"Usic après SCA : quelle surveillance clinique et ECG ?","back":"PA et auscultation **2 fois/j** ; **monitorage ECG continu**.","prio":"P2","sec":"s10"},{"id":"fc-339-93764a","poly":"cardio","fiche":"339","front":"Usic après SCA : quelle surveillance biologique ?","back":"Troponine, glycémie, créatininémie, NFS **chaque jour**.","prio":"P2","sec":"s10"},{"id":"fc-339-77a736","poly":"cardio","fiche":"339","front":"Usic après SCA : quand faire l'ETT ?","back":"**Le jour de l'admission**, puis selon l'évolution.","prio":"P2","sec":"s10"},{"id":"fc-339-369647","poly":"cardio","fiche":"339","front":"SCA ST+ sans complication : quand le patient sort-il ?","back":"Entre **J3 et J5**.","prio":"P2","sec":"s10"},{"id":"fc-339-2a6bbf","poly":"cardio","fiche":"339","front":"Usic : quel est l'objectif principal ?","back":"Dépister et traiter une **complication précoce** (surtout **rythmique**) ; plus fréquentes dans le ST+.","prio":"P1","sec":"s10"},{"id":"fc-339-5f4688","poly":"cardio","fiche":"339","front":"Phase aiguë du SCA : quel trouble du rythme cause la plupart des morts subites ?","back":"La **fibrillation ventriculaire**.","prio":"P1","sec":"s10"},{"id":"fc-339-12f7e3","poly":"cardio","fiche":"339","front":"FV au cours d'un SCA : conduite ?","back":"**Choc électrique externe immédiat** (jamais réversible spontanément).","prio":"P1","sec":"s10"},{"id":"fc-339-895cd5","poly":"cardio","fiche":"339","front":"Troubles du rythme ventriculaire à la phase aiguë : fréquence et lien avec l'étendue de l'ischémie ?","back":"**Très fréquents** et **indépendants** de l'étendue de l'ischémie (ESV → TV → FV).","prio":"P2","sec":"s10"},{"id":"fc-339-efb1f5","poly":"cardio","fiche":"339","front":"FA compliquant un SCA : conduite ?","back":"**Cardioversion** immédiate si mal tolérée ; **anticoagulation** (prévention des embolies).","prio":"P2","sec":"s10"},{"id":"fc-339-3bd9f9","poly":"cardio","fiche":"339","front":"BAV nodal compliquant un SCA : quel territoire et quelle évolution ?","back":"SCA ST+ **inférieur** ; habituellement **transitoire**, répond à l'**atropine**.","prio":"P1","sec":"s10"},{"id":"fc-339-1017df","poly":"cardio","fiche":"339","front":"BAV infranodal compliquant un SCA : quel territoire et quel traitement ?","back":"SCA ST+ **antérieur** ; **pas** de réponse à l'atropine → sonde d'entraînement, souvent **stimulateur permanent**.","prio":"P1","sec":"s10"},{"id":"fc-339-6cee26","poly":"cardio","fiche":"339","front":"Hypertonie vagale du SCA ST+ inférieur : quel traitement ?","back":"**Atropine** + **remplissage** macromoléculaire.","prio":"P2","sec":"s10"},{"id":"fc-339-15d18d","poly":"cardio","fiche":"339","front":"IVG compliquant un SCA : quel traitement ?","back":"**Diurétiques**, **IEC**, **antagonistes des récepteurs minéralocorticoïdes**.","prio":"P2","sec":"s10"},{"id":"fc-339-9feca8","poly":"cardio","fiche":"339","front":"IVG après SCA : quel examen systématique ?","back":"L'**échographie** (complication mécanique ?).","prio":"P2","sec":"s10"},{"id":"fc-339-d78830","poly":"cardio","fiche":"339","front":"Classification de Killip : quels 4 stades ?","back":"**1** pas de râles ; **2** râles < moitié des champs ; **3** râles > moitié (**OAP**), galop ; **4** **choc cardiogénique**.","prio":"P1","sec":"s10"},{"id":"fc-339-689bfb","poly":"cardio","fiche":"339","front":"Préchoc cardiogénique après SCA : quelle définition ?","back":"**PAS < 90 mmHg** mal tolérée, ne répondant pas au remplissage, persistant après correction d'une bradycardie vagale.","prio":"P2","sec":"s10"},{"id":"fc-339-e594d6","poly":"cardio","fiche":"339","front":"Choc cardiogénique constitué : quels signes ?","back":"**Extrémités froides**, **oligurie**, **confusion**.","prio":"P2","sec":"s10"},{"id":"fc-339-a0f089","poly":"cardio","fiche":"339","front":"Choc cardiogénique constitué après SCA : quel traitement ?","back":"**Dobutamine** puis, si le terrain le permet, **assistance circulatoire**.","prio":"P1","sec":"s10"},{"id":"fc-339-548291","poly":"cardio","fiche":"339","front":"Choc cardiogénique compliquant un SCA : quelle mortalité hospitalière ?","back":"**Supérieure à 70 %**.","prio":"P2","sec":"s10"},{"id":"fc-339-f6a123","poly":"cardio","fiche":"339","front":"Préchoc cardiogénique après SCA : quel traitement ?","back":"**Revascularisation rapide** ou chirurgie de la complication mécanique.","prio":"P3","sec":"s10"},{"id":"fc-339-a84f61","poly":"cardio","fiche":"339","front":"Infarctus du VD : quelle triade clinique ?","back":"**Hypotension** + **champs pulmonaires clairs** + **turgescence jugulaire** (complique l'IDM inférieur).","prio":"P1","sec":"s10"},{"id":"fc-339-d98f46","poly":"cardio","fiche":"339","front":"Infarctus du VD : quels signes ECG et échographiques ?","back":"Sus-décalage en **V3R-V4R** ; ETT : **VD dilaté hypokinétique**, OD dilatée, IT.","prio":"P2","sec":"s10"},{"id":"fc-339-5894ab","poly":"cardio","fiche":"339","front":"Rupture de la paroi libre du VG : quels signes de la forme subaiguë ?","back":"**Récidive douloureuse** + **ST qui remonte** + **hypotension** brutale et prolongée.","prio":"P2","sec":"s10"},{"id":"fc-339-dd43b5","poly":"cardio","fiche":"339","front":"Rupture de la paroi libre du VG : conduite ?","back":"**ETT immédiate** ; hémopéricarde → **chirurgie immédiate**.","prio":"P2","sec":"s10"},{"id":"fc-339-0bf1b8","poly":"cardio","fiche":"339","front":"Rupture septale post-IDM : quel signe clinique ?","back":"**Souffle systolique** typiquement **« en rayon de roue »** (dans les 24-48 h).","prio":"P2","sec":"s10"},{"id":"fc-339-a5f9e2","poly":"cardio","fiche":"339","front":"Rupture septale post-IDM : quand la fermer ?","back":"De préférence **différée de quelques jours** (chirurgicale ou percutanée).","prio":"P3","sec":"s10"},{"id":"fc-339-b5f6ff","poly":"cardio","fiche":"339","front":"OAP compliquant un IDM inférieur : quelle complication évoquer ?","back":"Une **rupture de pilier mitral** (postéromédian).","prio":"P1","sec":"s10"},{"id":"fc-339-aa9470","poly":"cardio","fiche":"339","front":"Rupture de pilier mitral : pourquoi le pilier postéromédian ?","back":"Vascularisé par la **coronaire droite seule**.","prio":"P2","sec":"s10"},{"id":"fc-339-0fd6a1","poly":"cardio","fiche":"339","front":"Rupture de pilier mitral : quel traitement ?","back":"**Chirurgie urgente** (suture ou remplacement valvulaire) ; parfois Mitraclip®.","prio":"P2","sec":"s10"},{"id":"fc-339-b39e6f","poly":"cardio","fiche":"339","front":"Thrombus intra-VG post-IDM : quand le dépister et comment le traiter ?","back":"**ETT dans les 48 h** (surtout ST+ antérieur) ; **anticoagulation curative**.","prio":"P2","sec":"s10"},{"id":"fc-339-296182","poly":"cardio","fiche":"339","front":"TVP/EP après SCA : pourquoi sont-elles devenues rares ?","back":"**Anticoagulants** à la phase aiguë et **mobilisation rapide**.","prio":"P3","sec":"s10"},{"id":"fc-339-37cf83","poly":"cardio","fiche":"339","front":"Récidive ischémique après SCA : quels mécanismes ?","back":"**Réocclusion** de l'artère traitée (ST+) ou ischémie à distance chez le **pluritronculaire**.","prio":"P3","sec":"s10"},{"id":"fc-339-212692","poly":"cardio","fiche":"339","front":"Syndrome de Dressler : quand survient-il et comment se présente-t-il ?","back":"**Classiquement 3ᵉ semaine** post-IDM étendu : épanchement péricardique ± pleural, **arthralgies**, **fièvre**, syndrome inflammatoire.","prio":"P2","sec":"s10"},{"id":"fc-339-60f259","poly":"cardio","fiche":"339","front":"Syndrome de Dressler : quel traitement ?","back":"**Anti-inflammatoire** (évolution habituellement favorable).","prio":"P3","sec":"s10"},{"id":"fc-339-6ede29","poly":"cardio","fiche":"339","front":"IVG tardive post-IDM : quels mécanismes ?","back":"**Remodelage** (dilatation du VG) ou **anévrisme** ventriculaire.","prio":"P3","sec":"s10"},{"id":"fc-339-4dc975","poly":"cardio","fiche":"339","front":"Post-IDM : quand implanter un DAI ?","back":"Si **FEVG < 35 %** à au moins **6 semaines** de l'IDM sous traitement optimisé.","prio":"P1","sec":"s10"},{"id":"fc-339-4defea","poly":"cardio","fiche":"339","front":"Post-IDM avec FEVG < 35 % à la phase précoce : quelle protection d'attente ?","back":"**Lifevest** (gilet défibrillateur) + ETT de contrôle après quelques semaines.","prio":"P2","sec":"s10"},{"id":"fc-339-387a49","poly":"cardio","fiche":"339","front":"Après un SCA : quelle durée pour l'aspirine ?","back":"**Au long cours**, **75-100 mg/j**.","prio":"P1","sec":"s11"},{"id":"fc-339-267d6b","poly":"cardio","fiche":"339","front":"Après un SCA : quelle durée pour l'inhibiteur P2Y12 ?","back":"**12 mois** par défaut (réduite à 1-6 mois si risque hémorragique, ou prolongée).","prio":"P1","sec":"s11"},{"id":"fc-339-f1b898","poly":"cardio","fiche":"339","front":"SCA avec anticoagulant oral nécessaire (FA, thrombus VG) : quelle association ?","back":"**Clopidogrel + anticoagulant pleine dose** pendant **12 mois**, puis **anticoagulant seul**.","prio":"P1","sec":"s11"},{"id":"fc-339-31379c","poly":"cardio","fiche":"339","front":"SCA avec anticoagulant oral : quand une trithérapie courte ?","back":"Faible risque hémorragique + haut risque ischémique : habituellement **1 mois**.","prio":"P3","sec":"s11"},{"id":"fc-339-74c28c","poly":"cardio","fiche":"339","front":"Après un SCA : quand prescrire un IPP ?","back":"Si **risque digestif élevé** (≥ 65 ans, ATCD d'ulcère, corticothérapie prolongée…).","prio":"P2","sec":"s11"},{"id":"fc-339-0296d0","poly":"cardio","fiche":"339","front":"Après un SCA : quelle statine en 1re intention ?","back":"**Atorvastatine 80 mg** ou **rosuvastatine 20 mg**.","prio":"P1","sec":"s11"},{"id":"fc-339-82767d","poly":"cardio","fiche":"339","front":"Après un SCA : quel objectif de LDL-C ?","back":"Baisse **≥ 50 %** **et** LDL-C **< 0,55 g/L**.","prio":"P1","sec":"s11"},{"id":"fc-339-02f3a7","poly":"cardio","fiche":"339","front":"Après un SCA, LDL-C non à l'objectif : quel ajout et quand ?","back":"**Ézétimibe 10 mg** si objectif non atteint à **4 semaines** à dose maximale tolérée.","prio":"P2","sec":"s11"},{"id":"fc-339-5225ca","poly":"cardio","fiche":"339","front":"Anti-PCSK9 après SCA : quand sont-ils remboursés ?","back":"Si le LDL-C reste **> 0,7 g/L**.","prio":"P3","sec":"s11"},{"id":"fc-339-e4b56a","poly":"cardio","fiche":"339","front":"Après un SCA : les IEC/ARA2 sont-ils systématiques ?","back":"**Non** : surtout si **FEVG ≤ 40 %**, **diabète**, **IRC**.","prio":"P2","sec":"s11"},{"id":"fc-339-be2923","poly":"cardio","fiche":"339","front":"Après un SCA : quand les bêtabloquants sont-ils formellement indiqués ?","back":"Si **FEVG ≤ 40 %** (non systématiques sinon ; poursuivis si angor résiduel).","prio":"P1","sec":"s11"},{"id":"fc-339-ce8a75","poly":"cardio","fiche":"339","front":"Après un SCA : quand prescrire un antagoniste des récepteurs minéralocorticoïdes ?","back":"**FEVG ≤ 40 %** avec **IC** ou **diabète**, après bêtabloquant + IEC.","prio":"P2","sec":"s11"},{"id":"fc-339-2d4d6a","poly":"cardio","fiche":"339","front":"Antagonistes des récepteurs minéralocorticoïdes : quelles contre-indications ?","back":"**Créatininémie > 221 µmol/L** ou **hyperkaliémie**.","prio":"P3","sec":"s11"},{"id":"fc-339-e40a4b","poly":"cardio","fiche":"339","front":"Réadaptation cardiovasculaire après SCA : à qui la proposer ?","back":"**À tous** les patients.","prio":"P1","sec":"s11"},{"id":"fc-339-cadbd0","poly":"cardio","fiche":"339","front":"Réadaptation cardiovasculaire : que comporte-t-elle ?","back":"Surveillance, **éducation thérapeutique**, **reprise d'activité physique** ; équipe pluridisciplinaire.","prio":"P2","sec":"s11"},{"id":"fc-339-eb095f","poly":"cardio","fiche":"339","front":"Après un SCA : quelle mnémotechnique pour l'ordonnance de sortie ?","back":"**BASIC** : **B**êtabloquant, **A**ntiagrégants, **S**tatine, **I**EC, **C**ontrôle des facteurs de risque (B et I non systématiques).","prio":"P2","sec":"s11"},{"id":"fc-339-9dab53","poly":"cardio","fiche":"339","front":"Suivi après SCA : quelles autres localisations athéromateuses rechercher ?","back":"**Troncs supra-aortiques**, **aorte abdominale** (anévrisme), artères des **membres inférieurs**.","prio":"P2","sec":"s11"},{"id":"fc-339-8b3f90","poly":"cardio","fiche":"339","front":"Après un SCA : quelles notions sont inacceptables ?","back":"Ne pas prescrire la **double antiagrégation**, ni de **statine**, ni prendre en charge les **facteurs de risque**.","prio":"P1","sec":"s11"},{"id":"fc-339-9bdee4","poly":"cardio","fiche":"339","front":"Angor stable : quel mécanisme ?","back":"Besoins en O₂ **> apports**, par **obstruction** (le plus souvent athérosclérose) ou **spasme**.","prio":"P1","sec":"s12"},{"id":"fc-339-5f1aea","poly":"cardio","fiche":"339","front":"Angor stable : quelles circonstances de survenue ?","back":"Surtout l'**effort**, toujours le **même type d'effort** ; aussi stress, repas copieux, **froid**.","prio":"P1","sec":"s12"},{"id":"fc-339-edab8c","poly":"cardio","fiche":"339","front":"Angor typique : comment cède-t-il ?","back":"Très vite à l'**arrêt de l'effort** ou sous **trinitrine sublinguale**.","prio":"P1","sec":"s12"},{"id":"fc-339-077603","poly":"cardio","fiche":"339","front":"Angor de novo : comment le considérer ?","back":"Comme un **SCA jusqu'à preuve du contraire**.","prio":"P1","sec":"s12"},{"id":"fc-339-1dfc5f","poly":"cardio","fiche":"339","front":"Angor stable : quelle classification de sévérité, et quelles classes à haut risque ?","back":"**Société canadienne de cardiologie (CCS)** ; classes **3 ou 4**.","prio":"P2","sec":"s12"},{"id":"fc-339-e8dd03","poly":"cardio","fiche":"339","front":"Angor stable : quelles formes atypiques ?","back":"Épigastrique ou limitée aux irradiations, **blocpnée d'effort**, palpitations d'effort, IVG, **ischémie silencieuse**.","prio":"P2","sec":"s12"},{"id":"fc-339-939794","poly":"cardio","fiche":"339","front":"Blocpnée d'effort : de quoi s'agit-il ?","back":"Impossibilité de **vider l'air à l'expiration** à l'effort (équivalent angineux).","prio":"P3","sec":"s12"},{"id":"fc-339-b44bc3","poly":"cardio","fiche":"339","front":"Angor stable : quelle cause associée chercher à l'auscultation ?","back":"Un souffle de **rétrécissement aortique**.","prio":"P2","sec":"s12"},{"id":"fc-339-c7617e","poly":"cardio","fiche":"339","front":"Cascade ischémique : dans quel ordre surviennent les anomalies ?","back":"Métaboliques (H⁺, K⁺) → **cinétique** (diastole puis systole) → **ST-T** → **douleur** (peut manquer).","prio":"P3","sec":"s12"},{"id":"fc-339-95f952","poly":"cardio","fiche":"339","front":"Angor stable : quels tests fonctionnels ?","back":"**Épreuve d'effort**, de préférence couplée à une imagerie (**écho**, **scintigraphie**, **IRM de stress**).","prio":"P1","sec":"s12"},{"id":"fc-339-04feb0","poly":"cardio","fiche":"339","front":"Tests fonctionnels d'ischémie : quelle contre-indication habituelle ?","back":"Un **SCA récent**.","prio":"P1","sec":"s12"},{"id":"fc-339-0b62a5","poly":"cardio","fiche":"339","front":"Probabilité pré-test d'angor : sur quels éléments ?","back":"**Âge**, **sexe**, **type de douleur**.","prio":"P2","sec":"s12"},{"id":"fc-339-2e9007","poly":"cardio","fiche":"339","front":"Probabilité pré-test : quels profils extrêmes ?","back":"Forte : **homme > 40 ans**, angor typique ; faible : **femme < 50 ans**, douleur atypique.","prio":"P3","sec":"s12"},{"id":"fc-339-1aeab5","poly":"cardio","fiche":"339","front":"Tests fonctionnels : quels arguments pour des sténoses sévères ou multiples ?","back":"Test **précocement positif**, ischémie étendue à **plusieurs segments**, **chute de PA**.","prio":"P2","sec":"s12"},{"id":"fc-339-875fd7","poly":"cardio","fiche":"339","front":"FFR : quel seuil définit une sténose critique ?","back":"**≤ 0,8**.","prio":"P3","sec":"s12"},{"id":"fc-339-a498a7","poly":"cardio","fiche":"339","front":"Coronarographie : citer ses risques ?","back":"**Rénaux** et **anaphylactiques** (iode), infectieux, **vasculaires**, emboliques, **rythmiques**.","prio":"P3","sec":"s12"},{"id":"fc-339-761e31","poly":"cardio","fiche":"339","front":"Coronarographie chez l'insuffisant rénal : quelles précautions ?","back":"**Hyperhydratation** préalable et **moins de contraste**.","prio":"P3","sec":"s12"},{"id":"fc-339-9c2394","poly":"cardio","fiche":"339","front":"Coroscanner : quand est-il utile dans l'angor stable ?","back":"Si tests fonctionnels **douteux ou impossibles** ; très bon pour vérifier un **pontage**.","prio":"P3","sec":"s12"},{"id":"fc-339-bf55e7","poly":"cardio","fiche":"339","front":"Coroscanner : quelles limites ?","back":"**FC rapide ou irrégulière**, **calcifications**, petites artères, stents, **irradiation**.","prio":"P3","sec":"s12"},{"id":"fc-339-daaf65","poly":"cardio","fiche":"339","front":"Angor stable : quelles mortalités annuelles définissent le risque bas, intermédiaire, haut ?","back":"Bas **< 1 %** ; intermédiaire **1 à 3 %** ; haut **> 3 %**.","prio":"P2","sec":"s12"},{"id":"fc-339-17fa9c","poly":"cardio","fiche":"339","front":"Angor stable : quels critères de haut risque ?","back":"Classe **3-4** ; **FEVG diminuée** ; épreuve d'effort positive **≤ 6 min** ; ischémie **> 10 % du VG**.","prio":"P1","sec":"s12"},{"id":"fc-339-b18ce8","poly":"cardio","fiche":"339","front":"Angor stable : quelles lésions à haut risque justifient une revascularisation ?","back":"**Tronc commun gauche**, **IVA proximale**, **tritronculaire proximale**.","prio":"P2","sec":"s12"},{"id":"fc-339-5a6675","poly":"cardio","fiche":"339","front":"Angor stable : quels traitements sont systématiques ?","back":"Correction des **facteurs de risque** + **aspirine** + **statine**.","prio":"P1","sec":"s13"},{"id":"fc-339-f9a20d","poly":"cardio","fiche":"339","front":"Crise d'angor : quel traitement ?","back":"**Trinitrine sublinguale** en spray (assis ou allongé).","prio":"P1","sec":"s13"},{"id":"fc-339-6a90e9","poly":"cardio","fiche":"339","front":"Trinitrine sublinguale : quels effets indésirables ?","back":"**Céphalées**, **chute de PA**.","prio":"P2","sec":"s13"},{"id":"fc-339-add3a3","poly":"cardio","fiche":"339","front":"Angor stable : quel anti-ischémique en 1re intention ?","back":"Les **bêtabloquants**.","prio":"P1","sec":"s13"},{"id":"fc-339-1633a3","poly":"cardio","fiche":"339","front":"Bêtabloquants : quelles contre-indications ?","back":"**Asthme**, BPCO très sévère, **Raynaud**, bradycardie **< 50/min**, **BAV 2ᵉ ou 3ᵉ degré**.","prio":"P1","sec":"s13"},{"id":"fc-339-a31d68","poly":"cardio","fiche":"339","front":"Angor stable : quand faire une coronarographie d'emblée ?","back":"Angor sévère (**classe ≥ 3**) ou **FEVG altérée**.","prio":"P2","sec":"s13"},{"id":"fc-339-4ee5b6","poly":"cardio","fiche":"339","front":"Angor stable : la revascularisation systématique est-elle supérieure au traitement médical ?","back":"**Non** : indications **symptomatique** (angor malgré traitement optimal) ou **pronostique** (haut risque).","prio":"P1","sec":"s13"},{"id":"fc-339-a27e85","poly":"cardio","fiche":"339","front":"Angor stable : quand préférer le pontage ?","back":"Lésions **diffuses** (notamment diabétique) du **tronc commun** et de l'**IVA proximale**, lit d'aval accessible.","prio":"P2","sec":"s13"},{"id":"fc-339-f51402","poly":"cardio","fiche":"339","front":"Inhibiteurs calciques bradycardisants : lesquels, et quelle association interdite ?","back":"**Diltiazem**, **vérapamil** : **ne pas associer aux bêtabloquants** (troubles de conduction).","prio":"P1","sec":"s13"},{"id":"fc-339-07595d","poly":"cardio","fiche":"339","front":"Dihydropyridines dans l'angor : quelle place ?","back":"1re intention si bêtabloquants CI ou **FC < 60/min** ; 2e intention en **association** aux bêtabloquants.","prio":"P2","sec":"s13"},{"id":"fc-339-420dd4","poly":"cardio","fiche":"339","front":"Inhibiteurs calciques : quel effet indésirable commun ?","back":"**Œdèmes des membres inférieurs** (surtout dihydropyridines).","prio":"P2","sec":"s13"},{"id":"fc-339-6d8b44","poly":"cardio","fiche":"339","front":"Dérivés nitrés LP : quelle association est contre-indiquée ?","back":"Les **inhibiteurs de la PDE5** (sildénafil).","prio":"P1","sec":"s13"},{"id":"fc-339-ed5b8a","poly":"cardio","fiche":"339","front":"Dérivés nitrés LP et molsidomine : quelle place dans l'angor stable ?","back":"**3e intention**, formes invalidantes ; timbre posé **18 h/j**.","prio":"P3","sec":"s13"},{"id":"fc-339-75c192","poly":"cardio","fiche":"339","front":"Nicorandil : quel effet indésirable caractéristique ?","back":"**Ulcérations** péribuccales, intestinales, périanales.","prio":"P3","sec":"s13"},{"id":"fc-339-82c0c3","poly":"cardio","fiche":"339","front":"Ivabradine : quelles conditions d'utilisation ?","back":"**Rythme sinusal** avec **FC ≥ 70/min** ; inefficace en FA.","prio":"P2","sec":"s13"},{"id":"fc-339-4588ec","poly":"cardio","fiche":"339","front":"Ivabradine : quel effet indésirable ?","back":"**Phosphènes** (transitoires).","prio":"P3","sec":"s13"},{"id":"fc-339-4f56bc","poly":"cardio","fiche":"339","front":"Angor stable : dose d'aspirine ?","back":"**75-100 mg/j**, systématique chez tout coronarien.","prio":"P2","sec":"s13"},{"id":"fc-339-df0610","poly":"cardio","fiche":"339","front":"Angor stable : quand prescrire le clopidogrel ?","back":"Si **CI à l'aspirine** ; avec l'aspirine après **stent actif** (≈ **6 mois**) ; parfois chez le polyartériel.","prio":"P2","sec":"s13"},{"id":"fc-339-9986ea","poly":"cardio","fiche":"339","front":"Angor stable stenté : prasugrel et ticagrélor sont-ils indiqués ?","back":"**Non**.","prio":"P2","sec":"s13"},{"id":"fc-339-1016a3","poly":"cardio","fiche":"339","front":"Stent actif : quel avantage sur le stent nu ?","back":"**Moins de resténose** (antimitotique).","prio":"P3","sec":"s13"},{"id":"fc-339-cd59ad","poly":"cardio","fiche":"339","front":"Angor stable hypertendu : quels antihypertenseurs en 1re intention ?","back":"**IEC**, **ARA2** ou **bêtabloquant** (HTA > 135/85 en automesure).","prio":"P2","sec":"s13"},{"id":"fc-342-d8163d","poly":"cardio","fiche":"342","front":"« Malaise » : est-ce un diagnostic ?","back":"**Non** : c'est une **plainte**, un motif de recours (mal-être, gêne vague).","prio":"P1","sec":"s1"},{"id":"fc-342-756100","poly":"cardio","fiche":"342","front":"PDCB : quelle définition ?","back":"Perte de conscience réelle ou apparente, **brève**, avec **amnésie** de l'épisode, perte du contrôle moteur et de la réactivité.","prio":"P1","sec":"s1"},{"id":"fc-342-5a74f2","poly":"cardio","fiche":"342","front":"PDCB : quelle première distinction faire ?","back":"PDCB **traumatique** ou **non traumatique**.","prio":"P2","sec":"s1"},{"id":"fc-342-531f6a","poly":"cardio","fiche":"342","front":"PDCB non traumatiques : quelles 3 catégories ?","back":"**Syncope**, **crise d'épilepsie**, **PDCB psychogène**.","prio":"P1","sec":"s1"},{"id":"fc-342-a693e7","poly":"cardio","fiche":"342","front":"Syncope : quelle définition ?","back":"PDCB due à une **hypoperfusion cérébrale**, de déclenchement rapide, avec récupération **complète et spontanée**.","prio":"P1","sec":"s1"},{"id":"fc-342-edc096","poly":"cardio","fiche":"342","front":"Après une syncope : comment sont le comportement et l'orientation ?","back":"**Normaux** ; aucun souvenir de la PDCB.","prio":"P2","sec":"s1"},{"id":"fc-342-320deb","poly":"cardio","fiche":"342","front":"Lipothymie : quelle définition ?","back":"Prodromes **sans perte de connaissance** (présyncope).","prio":"P1","sec":"s1"},{"id":"fc-342-46c72e","poly":"cardio","fiche":"342","front":"Lipothymie : comment la prendre en charge ?","back":"De façon **identique** à une syncope.","prio":"P1","sec":"s1"},{"id":"fc-342-a9847c","poly":"cardio","fiche":"342","front":"Syncope « à l'emporte-pièce » : quelle définition ?","back":"Syncope **sans prodrome**.","prio":"P2","sec":"s1"},{"id":"fc-342-5fe904","poly":"cardio","fiche":"342","front":"Crise d'épilepsie : quel mécanisme de la PDCB ?","back":"**Hyperactivité** cérébrale.","prio":"P3","sec":"s1"},{"id":"fc-342-cbcd53","poly":"cardio","fiche":"342","front":"PDCB psychogène : quel mécanisme ?","back":"Phénomène de **conversion** (imite une épilepsie ou une syncope).","prio":"P3","sec":"s1"},{"id":"fc-342-5311d8","poly":"cardio","fiche":"342","front":"Syncope de Stokes-Adams : que désignait ce terme ?","back":"Syncope **sans prodrome**, pâleur, **< 30 s**, réveil brutal, le plus souvent **rythmique**.","prio":"P2","sec":"s1"},{"id":"fc-342-72abe8","poly":"cardio","fiche":"342","front":"« Malaise » : que peut-il recouvrir d'autre qu'une syncope ?","back":"**Douleur thoracique**, **dyspnée**, **vertige**…","prio":"P2","sec":"s1"},{"id":"fc-342-2e839d","poly":"cardio","fiche":"342","front":"Syncope : quelle durée d'arrêt du flux cérébral suffit à perdre connaissance ?","back":"**6 à 8 secondes**.","prio":"P2","sec":"s2"},{"id":"fc-342-e09a6d","poly":"cardio","fiche":"342","front":"Syncope : quelle structure cérébrale « éteint » la conscience ?","back":"La **substance réticulée activatrice** du tronc cérébral.","prio":"P3","sec":"s2"},{"id":"fc-342-741caf","poly":"cardio","fiche":"342","front":"Syncope : quels deux mécanismes de chute de la PA ?","back":"Baisse du **débit cardiaque** et/ou chute des **résistances périphériques**.","prio":"P2","sec":"s2"},{"id":"fc-342-34096e","poly":"cardio","fiche":"342","front":"Baisse du débit cardiaque responsable de syncope : quelles causes ?","back":"**Bradycardie** ou **tachycardie** ; baisse du **retour veineux** ; **obstacle** circulatoire.","prio":"P3","sec":"s2"},{"id":"fc-342-838361","poly":"cardio","fiche":"342","front":"Chute des résistances responsable de syncope : quelles causes ?","back":"**Réflexe** (levée du tonus sympathique) ; **dysautonomie** ; **médicaments**.","prio":"P3","sec":"s2"},{"id":"fc-342-d66377","poly":"cardio","fiche":"342","front":"Myoclonies de la syncope : quelles caractéristiques ?","back":"Brèves (**< 15 s**), **toujours après** la PDC (souvent après la 30ᵉ s) ; ne signent **pas** une épilepsie.","prio":"P2","sec":"s2"},{"id":"fc-342-b41f96","poly":"cardio","fiche":"342","front":"Pourquoi éviter le terme « syncope convulsivante » ?","back":"Les **myoclonies** de la syncope ne sont pas une épilepsie.","prio":"P3","sec":"s2"},{"id":"fc-342-6176a9","poly":"cardio","fiche":"342","front":"Épilepsie : quelles crises donnent une PDCB ?","back":"Les crises **généralisées** (toniques, cloniques, tonicocloniques, atoniques).","prio":"P3","sec":"s2"},{"id":"fc-342-0fbae0","poly":"cardio","fiche":"342","front":"PDCB psychogènes : quelles caractéristiques de durée et de fréquence ?","back":"Souvent **prolongées** et répétées **plusieurs fois par jour**.","prio":"P3","sec":"s2"},{"id":"fc-342-a0a04d","poly":"cardio","fiche":"342","front":"Causes de syncope : quelle mnémotechnique en 4 familles ?","back":"**O.T.H.R** : **O**bstacle mécanique, **T**rouble du rythme/conduction, **H**ypotension orthostatique, **R**éflexe.","prio":"P1","sec":"s3"},{"id":"fc-342-0e9c77","poly":"cardio","fiche":"342","front":"Causes de syncope (O.T.H.R) : quelles familles sont cardiaques ?","back":"Les deux premières : **Obstacle mécanique** et **Trouble du rythme/conduction**.","prio":"P2","sec":"s3"},{"id":"fc-342-076c6e","poly":"cardio","fiche":"342","front":"Quelle est la 1re cause de syncope ?","back":"L'**hypotension orthostatique**.","prio":"P1","sec":"s3"},{"id":"fc-342-6e0359","poly":"cardio","fiche":"342","front":"Sur cœur sain avec ECG normal : quelle syncope est la plus fréquente ?","back":"La syncope **réflexe**.","prio":"P1","sec":"s3"},{"id":"fc-342-702b08","poly":"cardio","fiche":"342","front":"Rétrécissement aortique serré : quel type de syncope ?","back":"Syncope **à l'effort**.","prio":"P1","sec":"s3"},{"id":"fc-342-949b51","poly":"cardio","fiche":"342","front":"CMH obstructive : quel mécanisme d'obstruction ?","back":"Septum hypertrophié au contact de la grande valve mitrale → obstruction de la **chambre de chasse du VG**.","prio":"P2","sec":"s3"},{"id":"fc-342-0997f0","poly":"cardio","fiche":"342","front":"CMH obstructive : quels signes évoquer ?","back":"**Souffle systolique éjectionnel** au bord gauche du sternum ; syncope **à l'effort ou juste après**.","prio":"P1","sec":"s3"},{"id":"fc-342-1a793a","poly":"cardio","fiche":"342","front":"CMH : quel mode de transmission ?","back":"Souvent génétique, **autosomique dominante** (protéines du sarcomère).","prio":"P3","sec":"s3"},{"id":"fc-342-e8591a","poly":"cardio","fiche":"342","front":"Embolie pulmonaire responsable de syncope : quel mécanisme et quelle gravité ?","back":"Thrombus occlusif du **tronc pulmonaire** ou de la chambre de chasse du VD ; souvent EP **à haut risque**.","prio":"P2","sec":"s3"},{"id":"fc-342-73304a","poly":"cardio","fiche":"342","front":"Tamponnade : pourquoi donne-t-elle une syncope ?","back":"L'épanchement **comprime les cavités à basse pression**, dont le VD.","prio":"P2","sec":"s3"},{"id":"fc-342-2d6913","poly":"cardio","fiche":"342","front":"Citer des causes rares de syncope par obstacle ?","back":"**Thrombose de valve mécanique**, **myxome**, dissection aortique, **HTP sévère**.","prio":"P3","sec":"s3"},{"id":"fc-342-47cf99","poly":"cardio","fiche":"342","front":"Insuffisance cardiaque sévère : est-elle une cause de syncope ?","back":"**Jamais en elle-même** (confusion ou trouble de conscience possibles).","prio":"P1","sec":"s3"},{"id":"fc-342-faa429","poly":"cardio","fiche":"342","front":"Troubles conductifs syncopaux : quels BAV surtout ?","back":"**BAV 3** (surtout **infrahissien**), BAV de **haut degré**, **Mobitz 2**.","prio":"P1","sec":"s3"},{"id":"fc-342-7cde6e","poly":"cardio","fiche":"342","front":"Dysfonction sinusale : à partir de quelle durée de pause devient-elle syncopale ?","back":"Pauses **> 6 secondes** (parfois moins chez le sujet âgé).","prio":"P1","sec":"s3"},{"id":"fc-342-048b60","poly":"cardio","fiche":"342","front":"Maladie de l'oreillette : quelle définition ?","back":"Syndrome **tachycardie-bradycardie** : FA paroxystique + dysfonction sinusale, pauses au retour en sinusal.","prio":"P2","sec":"s3"},{"id":"fc-342-56f2b3","poly":"cardio","fiche":"342","front":"Porteur de stimulateur avec syncope : quelles défaillances rechercher ?","back":"**Sonde déplacée ou rompue**, **batterie usée**.","prio":"P2","sec":"s3"},{"id":"fc-342-14da11","poly":"cardio","fiche":"342","front":"TV responsables de syncope : quelle cause principale ?","back":"La **maladie coronarienne** (SCA ou **séquelle d'infarctus**, parfois des années après).","prio":"P1","sec":"s3"},{"id":"fc-342-b2c180","poly":"cardio","fiche":"342","front":"TV : citer d'autres cardiopathies en cause ?","back":"**Cardiomyopathies** dilatées, hypertrophiques, restrictives ; **dysplasie arythmogène du VD**.","prio":"P2","sec":"s3"},{"id":"fc-342-b45e22","poly":"cardio","fiche":"342","front":"Torsades de pointes : sur quel terrain ECG ?","back":"**QT long**.","prio":"P1","sec":"s3"},{"id":"fc-342-656f2d","poly":"cardio","fiche":"342","front":"TSV : sont-elles une cause fréquente de syncope ?","back":"**Non** : exceptionnelle.","prio":"P1","sec":"s3"},{"id":"fc-342-6ee31f","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle définition ?","back":"Chute de PAS **≥ 20 mmHg** ou de PAD **≥ 10 mmHg**, ou PAS **< 90 mmHg**, dans les **1 à 3 min** debout.","prio":"P1","sec":"s3"},{"id":"fc-342-e319ae","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels facteurs favorisants ?","back":"**Effort préalable**, période **postprandiale**, **alitement prolongé**.","prio":"P2","sec":"s3"},{"id":"fc-342-85f3a0","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels médicaments en cause ?","back":"**Vasodilatateurs** (nitrés, inhibiteurs calciques, bloqueurs du SRAA…), **diurétiques**, **psychotropes**, **antiparkinsoniens**.","prio":"P1","sec":"s3"},{"id":"fc-342-38f51f","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles causes d'hypovolémie ?","back":"**Déshydratation**, diarrhée, vomissements, **hémorragie**, **insuffisance surrénalienne**.","prio":"P2","sec":"s3"},{"id":"fc-342-d889c6","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles dysautonomies primaires et secondaires ?","back":"Primaires : **Parkinson**, **corps de Lewy** ; secondaires : **diabète**, **amylose**, neuropathies paranéoplasiques.","prio":"P2","sec":"s3"},{"id":"fc-342-270471","poly":"cardio","fiche":"342","front":"Syncopes réflexes : quels 3 types ?","back":"**Vasovagale**, **situationnelle**, **syndrome du sinus carotidien**.","prio":"P1","sec":"s3"},{"id":"fc-342-febd26","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel mécanisme ?","back":"Activation **parasympathique** (bradycardie) + baisse du tonus **sympathique** (vasodilatation).","prio":"P2","sec":"s3"},{"id":"fc-342-15defc","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quelles formes ?","back":"**Cardio-inhibitrice**, **vasoplégique** ou **mixte**.","prio":"P3","sec":"s3"},{"id":"fc-342-045b1b","poly":"cardio","fiche":"342","front":"Syncope situationnelle : citer des circonstances ?","back":"**Miction**, vomissements, **défécation**, **toux** (ictus laryngé), éternuements, après effort intense, Valsalva.","prio":"P2","sec":"s3"},{"id":"fc-342-cb9a2c","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : quel déclencheur ?","back":"**Compression du cou** sur le glomus carotidien (rasage, cravate…).","prio":"P2","sec":"s3"},{"id":"fc-342-312dc8","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : de quel « sinus » s'agit-il ?","back":"Du **glomus de l'artère carotide**, pas du nœud sinusal.","prio":"P2","sec":"s3"},{"id":"fc-342-d892dd","poly":"cardio","fiche":"342","front":"Torsade de pointes dégénérant en FV : syncope ou autre ?","back":"**Arrêt cardiaque**, pas une syncope.","prio":"P2","sec":"s3"},{"id":"fc-342-72b7e5","poly":"cardio","fiche":"342","front":"Interrogatoire d'une syncope : quel est son but ?","back":"**Confirmer la PDCB** et écarter si possible une **épilepsie** ou une PDCB **psychogène**.","prio":"P2","sec":"s4"},{"id":"fc-342-caab4d","poly":"cardio","fiche":"342","front":"Interrogatoire d'une syncope : quels éléments de terrain rechercher ?","back":"**Mort subite familiale**, **cardiopathie**, **médicaments** (hypotenseurs, changement récent), cause de **dysautonomie**.","prio":"P1","sec":"s4"},{"id":"fc-342-945700","poly":"cardio","fiche":"342","front":"Syncope : quels symptômes précédents sont des diagnostics prioritaires ?","back":"**Douleur thoracique** ou **dyspnée**.","prio":"P1","sec":"s4"},{"id":"fc-342-f6eac6","poly":"cardio","fiche":"342","front":"Syncope : quels prodromes orientent vers une origine vasovagale ?","back":"**Nausées**, **sueurs froides**.","prio":"P2","sec":"s4"},{"id":"fc-342-7264e9","poly":"cardio","fiche":"342","front":"Syncope : quelles circonstances déclenchantes rechercher ?","back":"Position, effort/repos, **douleur**, **émotion**, phobie du sang/prise de sang, **postprandial**, station debout prolongée, **chaleur**, lieu confiné.","prio":"P2","sec":"s4"},{"id":"fc-342-c5b9c6","poly":"cardio","fiche":"342","front":"Mouvements anormaux : quel élément de chronologie distingue crise et syncope ?","back":"**Dès** la perte de connaissance = **crise** ; **retardés** = myoclonies de **syncope**.","prio":"P1","sec":"s4"},{"id":"fc-342-207f75","poly":"cardio","fiche":"342","front":"Après l'épisode : quel signe oriente vers une crise comitiale ?","back":"**Courbatures** (et phase post-critique).","prio":"P2","sec":"s4"},{"id":"fc-342-2cca55","poly":"cardio","fiche":"342","front":"Témoin rapportant un pouls « aboli » : quelle valeur ?","back":"À prendre avec **prudence** (pouls radial imperceptible si hypotension).","prio":"P2","sec":"s4"},{"id":"fc-342-83ff80","poly":"cardio","fiche":"342","front":"PDC complète impossible à affirmer : sur quoi s'appuyer ?","back":"Sur le **terrain** et l'**ECG initial**.","prio":"P2","sec":"s4"},{"id":"fc-342-bff3e9","poly":"cardio","fiche":"342","front":"Syncope : que signifient un déficit neurologique ou une altération prolongée de la conscience ?","back":"On **sort du domaine cardiovasculaire**.","prio":"P1","sec":"s4"},{"id":"fc-342-de3fc2","poly":"cardio","fiche":"342","front":"Examen d'une syncope : quelle morsure de langue oriente vers une crise comitiale ?","back":"Morsure profonde du **bord latéral** de la langue.","prio":"P1","sec":"s4"},{"id":"fc-342-737285","poly":"cardio","fiche":"342","front":"Syncope : quels signes cardiovasculaires orientent vers un obstacle mécanique ?","back":"**Souffle systolique**, cœur pulmonaire aigu, bruits de **prothèse mécanique assourdis**.","prio":"P2","sec":"s4"},{"id":"fc-342-8dbc38","poly":"cardio","fiche":"342","front":"Syncope avec hypotension prolongée au décours immédiat : quelle orientation ?","back":"Cause **iatrogène** ou **réflexe**.","prio":"P2","sec":"s4"},{"id":"fc-342-d6897b","poly":"cardio","fiche":"342","front":"Recherche d'hypotension orthostatique : quel protocole ?","back":"**5 à 10 min** couché, puis PA à **1, 2 et 3 min** debout.","prio":"P1","sec":"s4"},{"id":"fc-342-bd65a2","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : qu'est-ce qui renforce son imputabilité ?","back":"La **reproduction des symptômes** pendant la chute de PA.","prio":"P2","sec":"s4"},{"id":"fc-342-396701","poly":"cardio","fiche":"342","front":"Syncope : l'âge permet-il de conclure à une cause vasovagale ?","back":"**Non** : il oriente mais trompe (pas forcément vasovagale chez le jeune, possible chez le sujet âgé).","prio":"P2","sec":"s4"},{"id":"fc-342-5966b9","poly":"cardio","fiche":"342","front":"Quel est le diagnostic différentiel le plus fréquent de la syncope aux urgences ?","back":"La **crise d'épilepsie**.","prio":"P1","sec":"s5"},{"id":"fc-342-082d03","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : fréquence d'un déclencheur ?","back":"Syncope : **très fréquent** ; épilepsie : **rare** (stimulation lumineuse, manque de sommeil, alcool).","prio":"P2","sec":"s5"},{"id":"fc-342-4ae710","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quels prodromes respectifs ?","back":"Syncope : tête vide, nausées, sueurs, palpitations ; épilepsie : **aura** (déjà-vu, hallucinations, sensation épigastrique).","prio":"P1","sec":"s5"},{"id":"fc-342-8dedb1","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelles caractéristiques des mouvements ?","back":"Syncope : **< 10**, **tardifs**, asymétriques ; épilepsie : **> 20**, **dès** la PDCB, synchrones.","prio":"P1","sec":"s5"},{"id":"fc-342-c2cd98","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : où est mordue la langue ?","back":"Syncope : **bout** ; épilepsie : **bord latéral**.","prio":"P1","sec":"s5"},{"id":"fc-342-a6b369","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelle couleur de peau ?","back":"Syncope : normale ou **pâle** ; épilepsie : **cyanosée**.","prio":"P2","sec":"s5"},{"id":"fc-342-f2aa15","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quel délai de réveil ?","back":"Syncope : **10 à 30 s** ; épilepsie : **plusieurs minutes**.","prio":"P1","sec":"s5"},{"id":"fc-342-8c9fbd","poly":"cardio","fiche":"342","front":"Syncope vs épilepsie : quelle durée de confusion ?","back":"Syncope : **< 10 s** ; épilepsie : amnésie de fixation de **plusieurs minutes**.","prio":"P2","sec":"s5"},{"id":"fc-342-a6846a","poly":"cardio","fiche":"342","front":"Quels éléments font basculer vers l'épilepsie ?","back":"**Aura**, survenue **pendant le sommeil**, **morsure latérale**, **cyanose**, **confusion prolongée**, courbatures.","prio":"P1","sec":"s5"},{"id":"fc-342-c79089","poly":"cardio","fiche":"342","front":"PDCB psychogène : que montrent rythme, PA et EEG pendant l'épisode ?","back":"Ils sont **normaux**.","prio":"P2","sec":"s5"},{"id":"fc-342-d14664","poly":"cardio","fiche":"342","front":"PDCB psychogène : quels arguments cliniques ?","back":"**Résistance à l'ouverture des yeux**, PDC **> 15 min**, **répétition fréquente** dans la semaine.","prio":"P1","sec":"s5"},{"id":"fc-342-3cb1a4","poly":"cardio","fiche":"342","front":"Perte d'urines et somnolence après l'épisode : quelle valeur ?","back":"**Peu discriminantes** entre syncope et crise.","prio":"P2","sec":"s5"},{"id":"fc-342-4edaae","poly":"cardio","fiche":"342","front":"AIT vertébrobasilaire : en quoi diffère-t-il d'une syncope ?","back":"PDC plutôt **prolongée** + **déficit focal** (vertiges, ataxie, diplopie…) ; cause très rare de PDCB.","prio":"P3","sec":"s5"},{"id":"fc-342-f0822d","poly":"cardio","fiche":"342","front":"Vol sous-clavier : quels signes ?","back":"AIT déclenché par les mouvements du **membre supérieur gauche** ; **différence de PA** entre les bras.","prio":"P3","sec":"s5"},{"id":"fc-342-3c4475","poly":"cardio","fiche":"342","front":"AIT carotidien : donne-t-il une PDCB ?","back":"**Quasiment jamais**.","prio":"P2","sec":"s5"},{"id":"fc-342-37dfbe","poly":"cardio","fiche":"342","front":"Coma et arrêt cardiaque : pourquoi ne sont-ils pas des syncopes ?","back":"Ni **brefs** ni **spontanément résolutifs**.","prio":"P2","sec":"s5"},{"id":"fc-342-badc1c","poly":"cardio","fiche":"342","front":"Confusion mentale : pourquoi n'est-ce pas une syncope ?","back":"**Pas de perte de connaissance** (penser hypoglycémie, hypoxie…).","prio":"P2","sec":"s5"},{"id":"fc-342-03cae5","poly":"cardio","fiche":"342","front":"Cataplexie : quelle définition ?","back":"Perte brutale du **tonus** déclenchée par une **émotion**, **sans** perte de connaissance ni amnésie.","prio":"P2","sec":"s5"},{"id":"fc-342-335a9d","poly":"cardio","fiche":"342","front":"« Drop-attacks » : pourquoi éviter ce terme ?","back":"Il mélange épilepsies rares, maladie de **Ménière** et chutes inexpliquées.","prio":"P3","sec":"s5"},{"id":"fc-342-48d893","poly":"cardio","fiche":"342","front":"Causes neurologiques de malaise ou de crise : lesquelles citer ?","back":"**Hypoglycémie**, **toxiques**, **méningite**, **arrêt de traitement**, **lésion intracérébrale focale**.","prio":"P2","sec":"s5"},{"id":"fc-342-b8d0e2","poly":"cardio","fiche":"342","front":"Malaises ni cardiaques ni neurologiques : lesquels ?","back":"**Malaise somatomorphe**, **attaque de panique**.","prio":"P2","sec":"s5"},{"id":"fc-342-1f3e4f","poly":"cardio","fiche":"342","front":"Malaise avec déficit neurologique : quelle orientation ?","back":"**Urgence neurovasculaire**.","prio":"P1","sec":"s5"},{"id":"fc-342-eb76bf","poly":"cardio","fiche":"342","front":"Syncope au cours d'un SCA ou d'un infarctus : qu'est-ce qui dicte la prise en charge ?","back":"Le **SCA / l'infarctus** lui-même.","prio":"P2","sec":"s5"},{"id":"fc-342-38be38","poly":"cardio","fiche":"342","front":"Syncope : quelles anomalies ECG sinusales ont une valeur diagnostique ?","back":"Bradycardie **< 40 bpm** ou pauses **> 3 s** chez un patient **éveillé**.","prio":"P1","sec":"s6"},{"id":"fc-342-342aa9","poly":"cardio","fiche":"342","front":"Syncope : citer les anomalies ECG à valeur diagnostique immédiate ?","back":"Brady **< 40 bpm** ou pause **> 3 s** éveillé, **TV**, **torsades**, **BAV 3/Mobitz 2**, **bloc alternant**, **TSV > 150 bpm**, défaillance de stimulateur/DAI.","prio":"P1","sec":"s6"},{"id":"fc-342-5d6d67","poly":"cardio","fiche":"342","front":"TSV : à partir de quelle fréquence a-t-elle valeur diagnostique de syncope ?","back":"**> 150 bpm**.","prio":"P2","sec":"s6"},{"id":"fc-342-c7f5ad","poly":"cardio","fiche":"342","front":"Bloc de branche alternant : quelle valeur devant une syncope ?","back":"**Diagnostique** (trifasciculaire).","prio":"P2","sec":"s6"},{"id":"fc-342-06f36f","poly":"cardio","fiche":"342","front":"Bradycardie 40-50 bpm ou pauses < 3 s : quelle valeur ?","back":"**Orientation** vers une dysfonction sinusale causale.","prio":"P2","sec":"s6"},{"id":"fc-342-6f99aa","poly":"cardio","fiche":"342","front":"Mobitz 1, BBG, bloc bifasciculaire : vers quoi orientent-ils ?","back":"Un **BAV paroxystique**.","prio":"P1","sec":"s6"},{"id":"fc-342-d796d9","poly":"cardio","fiche":"342","front":"ESV nombreuses ou en salves : vers quoi orientent-elles ?","back":"Une **TV**.","prio":"P2","sec":"s6"},{"id":"fc-342-b4eaca","poly":"cardio","fiche":"342","front":"QT long : vers quoi oriente-t-il ?","back":"Des **torsades de pointes**.","prio":"P1","sec":"s6"},{"id":"fc-342-7f76a8","poly":"cardio","fiche":"342","front":"Syndrome de Brugada : quel aspect ECG et quel risque ?","back":"**Sus-décalage convexe** de ST en **V1-V3** sans miroir → **FV** (syncope si elle cède, mort subite sinon).","prio":"P2","sec":"s6"},{"id":"fc-342-8e01d9","poly":"cardio","fiche":"342","front":"Wolff-Parkinson-White : quelle valeur devant une syncope ?","back":"**Orientation** vers une cause rythmique.","prio":"P2","sec":"s6"},{"id":"fc-342-c7191c","poly":"cardio","fiche":"342","front":"Onde Q, HVG, troubles de repolarisation : quelle orientation ?","back":"Cardiopathie (**séquelle d'infarctus**…) → chercher une **TV**.","prio":"P2","sec":"s6"},{"id":"fc-342-0844d1","poly":"cardio","fiche":"342","front":"Après clinique + ECG : dans quelle proportion la cause est-elle trouvée ?","back":"**Plus de 50 %**.","prio":"P1","sec":"s6"},{"id":"fc-342-e2f7d0","poly":"cardio","fiche":"342","front":"Syncope sans diagnostic avec anomalie ECG ou cardiopathie : quelle hypothèse dominante ?","back":"Un **trouble du rythme ventriculaire** annonciateur de **mort subite**.","prio":"P1","sec":"s6"},{"id":"fc-342-9ab193","poly":"cardio","fiche":"342","front":"ECG normal et pas de cardiopathie clinique : faut-il arrêter le bilan ?","back":"**Non** : poursuivre les examens pour s'en assurer.","prio":"P2","sec":"s6"},{"id":"fc-342-e07e9d","poly":"cardio","fiche":"342","front":"Bilan d'une syncope : quelle est la question principale ?","back":"Existe-t-il une **cardiopathie sous-jacente** (risque de **mort subite**) ?","prio":"P1","sec":"s7"},{"id":"fc-342-1e3e83","poly":"cardio","fiche":"342","front":"Syncope : quels antécédents imposent de garder le patient ?","back":"**Mort subite familiale** jeune ; **cardiopathie**, IC, infarctus, FEVG altérée.","prio":"P1","sec":"s7"},{"id":"fc-342-f6f68d","poly":"cardio","fiche":"342","front":"Syncope : quelles caractéristiques imposent de garder le patient ?","back":"**À l'effort**, **précédée de palpitations**, ou **en position couchée**.","prio":"P1","sec":"s7"},{"id":"fc-342-572ba8","poly":"cardio","fiche":"342","front":"Syncope : quels symptômes associés imposent de garder le patient ?","back":"**Douleur thoracique** ou abdominale, **céphalées**, **dyspnée brutale**, **traumatisme grave**.","prio":"P1","sec":"s7"},{"id":"fc-342-b60917","poly":"cardio","fiche":"342","front":"Syncope : quel signe d'examen impose de garder le patient ?","back":"Un **souffle systolique éjectionnel**.","prio":"P1","sec":"s7"},{"id":"fc-342-1a49e4","poly":"cardio","fiche":"342","front":"Syncope : quelle anomalie ECG impose de garder le patient ?","back":"Toute anomalie à valeur **diagnostique** ou d'**orientation**.","prio":"P1","sec":"s7"},{"id":"fc-342-b990b0","poly":"cardio","fiche":"342","front":"Critères de gravité d'une syncope : quelle mnémotechnique ?","back":"**3A - 3S** : **A**TCD familiaux, **A**TCD personnels, **A**nomalie ECG ; **S**yncope d'effort/couchée/palpitations, **S**ymptôme grave, **S**ouffle.","prio":"P2","sec":"s7"},{"id":"fc-342-3d8bea","poly":"cardio","fiche":"342","front":"Syncope : quelles conditions pour un retour à domicile ?","back":"**Réflexe évidente** ou **HTO** traitée + **examen et ECG normaux** + **aucune cardiopathie**.","prio":"P1","sec":"s7"},{"id":"fc-342-8e5a92","poly":"cardio","fiche":"342","front":"Syncope à risque vital suspecté : quelle surveillance aux urgences ?","back":"**Monitorage ECG obligatoire**.","prio":"P2","sec":"s7"},{"id":"fc-342-c33802","poly":"cardio","fiche":"342","front":"Syncope chez un cardiaque : quand retenir une syncope vasovagale ?","back":"Seulement **après bilan complet** : c'est un **diagnostic d'élimination**.","prio":"P1","sec":"s7"},{"id":"fc-342-a0cf37","poly":"cardio","fiche":"342","front":"Syncope : quelle place de l'échocardiographie ?","back":"**Quasi systématique**.","prio":"P2","sec":"s8"},{"id":"fc-342-34b7c7","poly":"cardio","fiche":"342","front":"Syncope avec cardiopathie du VG à FEVG altérée : quelle conduite possible ?","back":"**DAI** d'emblée en prévention de la mort subite, **sans autre examen**.","prio":"P2","sec":"s8"},{"id":"fc-342-248de6","poly":"cardio","fiche":"342","front":"Épreuve d'effort pour syncope : comment interpréter le moment de survenue ?","back":"**Pendant ou juste après** l'effort → **cardiaque** ; **après** l'effort → **réflexe**.","prio":"P2","sec":"s8"},{"id":"fc-342-8cc312","poly":"cardio","fiche":"342","front":"Syncope : quels biomarqueurs aident à repérer une cause cardiaque ?","back":"**BNP/NT-proBNP**, **troponine**.","prio":"P3","sec":"s8"},{"id":"fc-342-a7393e","poly":"cardio","fiche":"342","front":"Holter ECG pour syncope : quelle durée et quelle indication ?","back":"**24 h à 3 semaines**, si pas de haut risque et épisodes **fréquents**.","prio":"P2","sec":"s8"},{"id":"fc-342-5f5858","poly":"cardio","fiche":"342","front":"Holter normal : qu'est-ce qu'il n'élimine pas ?","back":"Un **trouble du rythme ventriculaire** ni un **BAV hissien/infrahissien** paroxystique.","prio":"P2","sec":"s8"},{"id":"fc-342-3c3ce7","poly":"cardio","fiche":"342","front":"Holter : pour quels troubles est-il sensible ?","back":"**Dysfonction sinusale** et troubles de conduction AV **nodaux**.","prio":"P3","sec":"s8"},{"id":"fc-342-7d6049","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quand est-il positif ?","back":"Pause **> 3 s** ou baisse de PAS **> 50 mmHg** **reproduisant les symptômes**.","prio":"P2","sec":"s8"},{"id":"fc-342-c92349","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quelles contre-indications ?","back":"**AIT** ou **AVC** antérieur, **sténose carotidienne**.","prio":"P2","sec":"s8"},{"id":"fc-342-106c35","poly":"cardio","fiche":"342","front":"Massage du sinus carotidien : quelles modalités ?","back":"Couché puis debout, **un côté puis l'autre**, **5 à 10 s**, à hauteur du cricoïde.","prio":"P3","sec":"s8"},{"id":"fc-342-12e33d","poly":"cardio","fiche":"342","front":"EEP : quelle indication devant une syncope ?","back":"Syncope **non élucidée** + **cardiopathie** ou **anomalie ECG** (bloc bifasciculaire, BBG).","prio":"P2","sec":"s8"},{"id":"fc-342-acb355","poly":"cardio","fiche":"342","front":"EEP : que mesure-t-on ou recherche-t-on ?","back":"**HV** (conduction infrahissienne), stimulation atriale, **stimulation ventriculaire programmée** (déclencher une TV).","prio":"P3","sec":"s8"},{"id":"fc-342-79d771","poly":"cardio","fiche":"342","front":"EEP : quand ne pas la proposer ?","back":"**Cœur normal** à l'écho **et ECG normal**, sauf palpitations avant la syncope.","prio":"P2","sec":"s8"},{"id":"fc-342-e50cda","poly":"cardio","fiche":"342","front":"EEP : quelle voie d'abord et quelle surveillance ?","back":"Voie **veineuse fémorale** ; surveiller le point de ponction, mobilisation **4 h** après.","prio":"P3","sec":"s8"},{"id":"fc-342-71f132","poly":"cardio","fiche":"342","front":"MAPA : quel intérêt devant une syncope ?","back":"Peut suggérer une **HTO** (souvent **HTA nocturne paradoxale**).","prio":"P3","sec":"s8"},{"id":"fc-342-44609b","poly":"cardio","fiche":"342","front":"Test d'inclinaison : que reproduit-il ?","back":"La syncope **vasovagale** ; parfois une **PDCB psychogène** (ECG et PA normaux).","prio":"P2","sec":"s8"},{"id":"fc-342-7a007b","poly":"cardio","fiche":"342","front":"Test d'inclinaison : quelles modalités ?","back":"Décubitus **≥ 5 min**, table à **60-70°**, **20 à 45 min**, sensibilisation par isoprénaline ou trinitrine.","prio":"P3","sec":"s8"},{"id":"fc-342-20ebd9","poly":"cardio","fiche":"342","front":"Test d'inclinaison positif : élimine-t-il une cause cardiaque ?","back":"**Non** (prudence).","prio":"P2","sec":"s8"},{"id":"fc-342-4f33bd","poly":"cardio","fiche":"342","front":"Moniteur ECG implantable : quelle autonomie et quelles indications ?","back":"**> 2 ans** : syncopes **espacées** ; EEP négative avec faux négatif suspecté ; syncopes sévères, fréquentes et **totalement inexpliquées**.","prio":"P2","sec":"s8"},{"id":"fc-342-573e67","poly":"cardio","fiche":"342","front":"Moniteur ECG implantable : quand n'est-il pas indiqué ?","back":"Patient relevant déjà d'un **DAI** ou d'un **stimulateur**.","prio":"P2","sec":"s8"},{"id":"fc-342-4bd286","poly":"cardio","fiche":"342","front":"Syncope : quelle hiérarchie des examens rythmiques ?","back":"**Holter et écho** avant l'**EEP** ; **MEI** si EEP négative.","prio":"P2","sec":"s8"},{"id":"fc-342-4e913d","poly":"cardio","fiche":"342","front":"Patients cardiaques : quelle est la 1re cause de mort subite ?","back":"Les **TV** (la syncope peut en être le signe annonciateur).","prio":"P1","sec":"s8"},{"id":"fc-342-057e8b","poly":"cardio","fiche":"342","front":"TV déclenchée lors de l'exploration d'une syncope : quel traitement ?","back":"Pose d'un **défibrillateur automatique implantable**.","prio":"P1","sec":"s8"},{"id":"fc-342-74273a","poly":"cardio","fiche":"342","front":"Toute syncope : quel trépied initial ?","back":"**Interrogatoire** + **examen** (avec HTO) + **ECG**.","prio":"P1","sec":"s9"},{"id":"fc-342-5d6ed5","poly":"cardio","fiche":"342","front":"Syncope sans cause évidente : que rechercher avant tout ?","back":"Une **cardiopathie sous-jacente**.","prio":"P1","sec":"s9"},{"id":"fc-342-e5e453","poly":"cardio","fiche":"342","front":"Syncope : si tous les examens sont normaux, quelle cause est probable ?","back":"Une syncope **réflexe**.","prio":"P1","sec":"s9"},{"id":"fc-342-3c0619","poly":"cardio","fiche":"342","front":"Syncope sans cause : quelles explorations si syncope grave possible ?","back":"**DAI d'emblée**, **EEP**, **MEI**.","prio":"P3","sec":"s9"},{"id":"fc-342-cb472f","poly":"cardio","fiche":"342","front":"Syncope sans cause : quelles explorations si syncope réflexe probable ?","back":"**Test d'inclinaison**, **MEI**.","prio":"P3","sec":"s9"},{"id":"fc-342-5e330d","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel geste immédiat ?","back":"**Allonger** le patient et **surélever ses jambes**.","prio":"P1","sec":"s10"},{"id":"fc-342-d816f1","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quels contextes déclenchants ?","back":"**Station debout prolongée**, lieu confiné, foule, **chaleur**, **douleur**, **émotion**, vue du sang.","prio":"P2","sec":"s10"},{"id":"fc-342-55a3e9","poly":"cardio","fiche":"342","front":"Syncopes réflexes : quelles circonstances favorisent toutes les formes ?","back":"La **nuit**, la **chaleur**, la période **postprandiale**.","prio":"P2","sec":"s10"},{"id":"fc-342-d6c18d","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel terrain typique ?","back":"Sujet **jeune**, **souvent** anxieux, émotif ou dépressif ; souvent passé de syncopes répétées **avant 40 ans**.","prio":"P2","sec":"s10"},{"id":"fc-342-4dc5ec","poly":"cardio","fiche":"342","front":"Syndrome du sinus carotidien : quel terrain typique ?","back":"L'**homme âgé**.","prio":"P1","sec":"s10"},{"id":"fc-342-d29788","poly":"cardio","fiche":"342","front":"Syncope vasovagale : quel tableau typique ?","back":"**Prodromes** (nausées, vue trouble, jambes faibles), **sueurs**, **pâleur**, chute, bradycardie parfois sévère.","prio":"P2","sec":"s10"},{"id":"fc-342-a77024","poly":"cardio","fiche":"342","front":"Syncope réflexe : quel est le traitement de fond de base ?","back":"**Non médicamenteux** : **réassurance**, éducation, **eau et sel**, baisse des **hypotenseurs**.","prio":"P2","sec":"s10"},{"id":"fc-342-61470d","poly":"cardio","fiche":"342","front":"Syncope réflexe : quelles mesures éducatives ?","back":"Éviter les déclencheurs, **reconnaître les prodromes** pour s'asseoir ou se coucher, **contractions isométriques**.","prio":"P3","sec":"s10"},{"id":"fc-342-ef3f82","poly":"cardio","fiche":"342","front":"Syncope réflexe : quels médicaments, rarement ?","back":"**Fludrocortisone** ou **agonistes alpha**.","prio":"P3","sec":"s10"},{"id":"fc-342-e13e5e","poly":"cardio","fiche":"342","front":"Syncope réflexe : quand discuter un pacemaker ?","back":"Composante **bradycardique prédominante et documentée**.","prio":"P3","sec":"s10"},{"id":"fc-342-84398a","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle cause la plus fréquente ?","back":"**Iatrogène** (psychotropes, antiparkinsoniens, antihypertenseurs).","prio":"P2","sec":"s11"},{"id":"fc-342-50834a","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelle circonstance médicamenteuse typique ?","back":"**Introduction ou changement de dose** d'un hypotenseur (vasodilatateur, diurétique).","prio":"P1","sec":"s11"},{"id":"fc-342-4e4e34","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quel terrain fréquent ?","back":"Le **sujet âgé**, parfois avec **dysautonomie**.","prio":"P2","sec":"s11"},{"id":"fc-342-cbb3b8","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles mesures de 1re ligne ?","back":"**Hydratation** et **apports sodés**, **baisse ou arrêt des hypotenseurs**, **bas de contention**, **lever prudent**.","prio":"P1","sec":"s11"},{"id":"fc-342-0c8131","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quelles manœuvres physiques ?","back":"**Croiser les jambes**, **s'accroupir**.","prio":"P2","sec":"s11"},{"id":"fc-342-db08f8","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quels médicaments si besoin ?","back":"**Midodrine** (alpha-agoniste) ou **fludrocortisone** (minéralocorticoïde).","prio":"P2","sec":"s11"},{"id":"fc-342-36e7f2","poly":"cardio","fiche":"342","front":"Fludrocortisone : quel mécanisme dans l'hypotension orthostatique ?","back":"**Rétention hydrosodée**.","prio":"P3","sec":"s11"},{"id":"fc-342-70787f","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quels diagnostics finaux les plus fréquents ?","back":"**TV** ou **BAV**.","prio":"P1","sec":"s12"},{"id":"fc-342-701c36","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quel terrain ?","back":"ATCD (parfois très ancien) d'**infarctus** ou de **cardiomyopathie dilatée**, en général à **FEVG abaissée** ; **parfois** morts subites familiales.","prio":"P2","sec":"s12"},{"id":"fc-342-725614","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quand la suspecter ?","back":"Syncope **à l'effort**, **en position couchée** ou **précédée de palpitations**.","prio":"P1","sec":"s12"},{"id":"fc-342-e11ba0","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quelle sanction thérapeutique selon le mécanisme ?","back":"**TV** → **défibrillateur** ; atteinte des **voies de conduction** → **stimulateur**.","prio":"P3","sec":"s12"},{"id":"fc-342-90e539","poly":"cardio","fiche":"342","front":"Tamponnade confirmée : quel traitement ?","back":"**Drainage** en urgence (ponction échoguidée ou chirurgical) en Usic ; remplissage par **macromolécules**.","prio":"P1","sec":"s13"},{"id":"fc-342-cc7ce9","poly":"cardio","fiche":"342","front":"Tamponnade non traitée : quel risque ?","back":"**Arrêt cardiaque** par **adiastolie**.","prio":"P2","sec":"s13"},{"id":"fc-342-2d12d6","poly":"cardio","fiche":"342","front":"EP à haut risque : quel traitement ?","back":"**Fibrinolyse** sauf CI ; **embolectomie chirurgicale** si CI ou échec.","prio":"P1","sec":"s13"},{"id":"fc-342-137d3a","poly":"cardio","fiche":"342","front":"EP à haut risque fibrinolysée : quel anticoagulant et quelle cible ?","back":"**HNF** : TCA **2 à 3 fois** le témoin ou anti-Xa **0,5 à 0,8**.","prio":"P2","sec":"s13"},{"id":"fc-342-a3ad95","poly":"cardio","fiche":"342","front":"RA serré symptomatique : quel traitement ?","back":"Toujours le traiter : **remplacement valvulaire** ou **TAVI**, pratiquement sans limite d'âge.","prio":"P2","sec":"s13"},{"id":"fc-342-5a4c24","poly":"cardio","fiche":"342","front":"Rétrécissement aortique symptomatique : quelle notion est inacceptable ?","back":"Ne **pas l'adresser** au spécialiste.","prio":"P1","sec":"s13"},{"id":"fc-342-753749","poly":"cardio","fiche":"342","front":"Thrombose de prothèse mécanique : quelle prise en charge initiale ?","back":"**INR en urgence**, Usic, **héparine IV** à la seringue + **aspirine** (bolus IV puis per os).","prio":"P1","sec":"s13"},{"id":"fc-342-3942c5","poly":"cardio","fiche":"342","front":"Thrombose de prothèse mécanique : quelle cause fréquente ?","back":"Une **anticoagulation insuffisante**.","prio":"P2","sec":"s13"},{"id":"fc-342-8c3c7e","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quels signes d'auscultation ?","back":"Bruits de prothèse **diminués** ; souffle systolique (aortique) ou roulement diastolique (mitral).","prio":"P2","sec":"s13"},{"id":"fc-342-542a21","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quels examens diagnostiques ?","back":"**Radiocinéma**, **ETT/ETO**, scanner injecté synchronisé.","prio":"P3","sec":"s13"},{"id":"fc-342-b9333b","poly":"cardio","fiche":"342","front":"Thrombose aiguë de prothèse mécanique : quel traitement et quelle mortalité ?","back":"**Réintervention en urgence** (changement de valve) ; mortalité **30 %**.","prio":"P2","sec":"s13"},{"id":"fc-342-83c65e","poly":"cardio","fiche":"342","front":"Thrombose de prothèse : quand recourir à la thrombolyse ?","back":"Si **chirurgie contre-indiquée** ou forme **subaiguë** résistante.","prio":"P3","sec":"s13"},{"id":"fc-342-b8a1bc","poly":"cardio","fiche":"342","front":"Syncope par obstacle : quelles causes prédominent ?","back":"**RA** et **EP**, puis CMH obstructive, tamponnade, thrombose de valve mécanique.","prio":"P2","sec":"s13"},{"id":"fc-342-82dfe6","poly":"cardio","fiche":"342","front":"Après une EP : comment se fait le lever ?","back":"Avec **bas de contention**, **sans alitement**.","prio":"P3","sec":"s13"},{"id":"fc-342-681233","poly":"cardio","fiche":"342","front":"Crise généralisée : sur quoi repose le diagnostic rétrospectif ?","back":"L'**interrogatoire de l'entourage**.","prio":"P1","sec":"s14"},{"id":"fc-342-3e170f","poly":"cardio","fiche":"342","front":"Crise convulsive généralisée : quel antiépileptique de courte durée administrer ?","back":"Une **benzodiazépine**.","prio":"P1","sec":"s14"},{"id":"fc-342-ff1ebd","poly":"cardio","fiche":"342","front":"Antiépileptique de courte durée : à quoi l'associer ?","back":"À un traitement de **longue durée d'action**.","prio":"P2","sec":"s14"},{"id":"fc-342-e34043","poly":"cardio","fiche":"342","front":"Syncope réflexe : quel message clé au patient ?","back":"Sa **bénignité** (récidives souvent moins nombreuses après évaluation).","prio":"P2","sec":"s15"},{"id":"fc-342-225744","poly":"cardio","fiche":"342","front":"Syncope rythmique du cardiaque : quel objectif du suivi ?","back":"**Prévention de la mort subite** (DAI si TV, stimulateur si trouble conductif).","prio":"P2","sec":"s15"},{"id":"fc-342-9d6a68","poly":"cardio","fiche":"342","front":"Hypotension orthostatique : quel suivi ?","back":"**Sécurité des médicaments** (hypotenseurs réduits), **lever prudent**, contention ; penser au sujet âgé.","prio":"P2","sec":"s15"},{"id":"fc-d111-b000ca","poly":"dermato","fiche":"d111","front":"Acné : quelle est sa définition ?","back":"Dermatose **inflammatoire chronique** du **follicule pilo-sébacé**.","prio":"P1","sec":"s1"},{"id":"fc-d111-c252b7","poly":"dermato","fiche":"d111","front":"Acné : à quel âge survient-elle le plus souvent ?","back":"À l'**adolescence**.","prio":"P1","sec":"s1"},{"id":"fc-d111-2c3c3b","poly":"dermato","fiche":"d111","front":"Acné : quelles sont les trois anomalies qui en expliquent la survenue ?","back":"**Séborrhée** (excès de sébum) + **kératinisation infundibulaire** anormale (comédon) + **flore** pro-inflammatoire (*Cutibacterium acnes*).","prio":"P2","sec":"s1"},{"id":"fc-d111-159d53","poly":"dermato","fiche":"d111","front":"Acné : quelle hormone lance et entretient surtout la sécrétion de sébum ?","back":"La **dihydrotestostérone**, formée dans le sébocyte à partir de la testostérone libre par la **5α-réductase de type I**.","prio":"P3","sec":"s1"},{"id":"fc-d111-085552","poly":"dermato","fiche":"d111","front":"Acné : comment sont les androgènes circulants ?","back":"À taux **normaux** : ce sont les récepteurs aux androgènes de la peau qui sont trop sensibles (**hyperandrogénie périphérique**).","prio":"P2","sec":"s1"},{"id":"fc-d111-838e51","poly":"dermato","fiche":"d111","front":"Acné : quel mécanisme aboutit à la formation du comédon ?","back":"Kératinocytes du canal **infundibulaire** qui prolifèrent trop et se différencient mal : ils ne s'éliminent plus normalement.","prio":"P2","sec":"s1"},{"id":"fc-d111-d5dbde","poly":"dermato","fiche":"d111","front":"Acné : quelle bactérie domine la flore du follicule ?","back":"***Cutibacterium acnes*** (Gram positif, flore anaérobie), qui sécrète des facteurs pro-inflammatoires.","prio":"P2","sec":"s1"},{"id":"fc-d111-ff26ae","poly":"dermato","fiche":"d111","front":"Acné : les souches de *C. acnes* de la peau acnéique sont-elles celles de la peau saine ?","back":"**Non** : souches différentes, au pouvoir inflammatoire différent.","prio":"P3","sec":"s1"},{"id":"fc-d111-79737d","poly":"dermato","fiche":"d111","front":"Acné : est-ce une maladie infectieuse ?","back":"**Non** : maladie **inflammatoire** du follicule pilo-sébacé, même si une bactérie de la flore y participe.","prio":"P1","sec":"s1"},{"id":"fc-d111-ae5728","poly":"dermato","fiche":"d111","front":"Acné : quelle est la traduction clinique de la séborrhée ?","back":"Une peau **grasse et luisante**.","prio":"P3","sec":"s1"},{"id":"fc-d111-070cd3","poly":"dermato","fiche":"d111","front":"Acné : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique** : séborrhée, lésions **rétentionnelles**, lésions **inflammatoires**, cicatrices.","prio":"P1","sec":"s2"},{"id":"fc-d111-3708fb","poly":"dermato","fiche":"d111","front":"Acné : sur quelles zones siège la séborrhée ?","back":"**Centre du visage** (nez, front, menton, joues) et **haut du thorax** (dos, face antérieure).","prio":"P2","sec":"s2"},{"id":"fc-d111-15e037","poly":"dermato","fiche":"d111","front":"Acné : la séborrhée est-elle constante ou inconstante ?","back":"**Constante**.","prio":"P2","sec":"s2"},{"id":"fc-d111-f3d93e","poly":"dermato","fiche":"d111","front":"Acné : quelles sont les deux lésions rétentionnelles ?","back":"**Comédon fermé** (microkyste) et **comédon ouvert** (point noir).","prio":"P1","sec":"s2"},{"id":"fc-d111-cceb79","poly":"dermato","fiche":"d111","front":"Comédon fermé (microkyste) : quel aspect et quelle taille ?","back":"Petite **papule couleur de peau**, parfois plus palpable que visible ; **2 à 3 mm**.","prio":"P1","sec":"s2"},{"id":"fc-d111-7a78c5","poly":"dermato","fiche":"d111","front":"Comédon fermé : quel en est le mécanisme ?","back":"Sébum et kératine accumulés dans un canal **dilaté** dont l'**orifice est bouché**.","prio":"P2","sec":"s2"},{"id":"fc-d111-2ab602","poly":"dermato","fiche":"d111","front":"Comédon ouvert (point noir) : à quoi correspond-il ?","back":"Kératinocytes **oxydés** accumulés dans l'orifice dilaté du canal infundibulaire ; **1 à 3 mm**.","prio":"P1","sec":"s2"},{"id":"fc-d111-44a7a5","poly":"dermato","fiche":"d111","front":"Comédon ouvert : quelle évolution possible ?","back":"**Expulsion spontanée** ou **inflammation**.","prio":"P3","sec":"s2"},{"id":"fc-d111-97145c","poly":"dermato","fiche":"d111","front":"Acné : quelles sont les lésions inflammatoires superficielles ?","back":"**Papules** (< 10 mm) et **pustules**.","prio":"P1","sec":"s2"},{"id":"fc-d111-c01097","poly":"dermato","fiche":"d111","front":"Papule d'acné : quel aspect ?","back":"Rouge, **ferme**, parfois douloureuse, **< 10 mm** ; née le plus souvent d'une lésion rétentionnelle.","prio":"P2","sec":"s2"},{"id":"fc-d111-ac8300","poly":"dermato","fiche":"d111","front":"Pustule d'acné : comment se forme-t-elle ?","back":"Le plus souvent à partir d'une **papule**, au sommet de laquelle apparaît un contenu jaune purulent (**polynucléaires**).","prio":"P2","sec":"s2"},{"id":"fc-d111-7b33b0","poly":"dermato","fiche":"d111","front":"Nodule d'acné : quelle taille et quelle évolution ?","back":"Lésion inflammatoire **profonde**, **> 10 mm** ; évolution vers abcès et **cicatrices**.","prio":"P1","sec":"s2"},{"id":"fc-d111-4efef3","poly":"dermato","fiche":"d111","front":"Acné : quel seuil de taille sépare papule et nodule ?","back":"**10 mm** : en dessous papule (superficielle), au-dessus nodule (profond).","prio":"P1","sec":"s2"},{"id":"fc-d111-115acb","poly":"dermato","fiche":"d111","front":"Acné : que sont les sinus ?","back":"Nodules allongés **très douloureux**, dus à la rupture d'un nodule dans la profondeur du derme.","prio":"P2","sec":"s2"},{"id":"fc-d111-9dbcfb","poly":"dermato","fiche":"d111","front":"Cicatrices d'acné : après quelles lésions surtout ?","back":"Après des lésions **inflammatoires qui ont duré** ; parfois déprimées et hyperpigmentées sur peau foncée.","prio":"P2","sec":"s2"},{"id":"fc-d111-0c36d2","poly":"dermato","fiche":"d111","front":"Acné : quelle est la forme clinique la plus commune ?","back":"L'**acné mixte juvénile** (lésions rétentionnelles + inflammatoires superficielles).","prio":"P2","sec":"s3"},{"id":"fc-d111-f47ead","poly":"dermato","fiche":"d111","front":"Acné mixte juvénile : à quel âge apparaît-elle en moyenne ?","back":"À la puberté : **12 ans** chez la fille, **14 ans** chez le garçon.","prio":"P3","sec":"s3"},{"id":"fc-d111-4c6918","poly":"dermato","fiche":"d111","front":"Acné mixte juvénile : quand devient-elle sévère ?","back":"**Dès qu'il y a des nodules**.","prio":"P2","sec":"s3"},{"id":"fc-d111-d8094c","poly":"dermato","fiche":"d111","front":"Acné : quelle est la forme la plus fréquente de l'acné qui débute ?","back":"L'**acné rétentionnelle** (surtout microkystes et comédons ouverts du visage).","prio":"P2","sec":"s3"},{"id":"fc-d111-9e983d","poly":"dermato","fiche":"d111","front":"Acné nodulaire (conglobata) : quelles caractéristiques ?","back":"Forme **grave** ; nodules qui peuvent **abcéder** ou se fistuliser (sinus) ; extension au **tronc** fréquente surtout chez le **garçon** ; cicatrices souvent importantes.","prio":"P2","sec":"s3"},{"id":"fc-d111-300936","poly":"dermato","fiche":"d111","front":"Acné néonatale : quand et où apparaît-elle ?","back":"Sur le **visage**, dès les **premières semaines de vie**.","prio":"P3","sec":"s4"},{"id":"fc-d111-d07599","poly":"dermato","fiche":"d111","front":"Acné néonatale : quelle en est la cause ?","back":"Les **androgènes d'origine maternelle**.","prio":"P2","sec":"s4"},{"id":"fc-d111-e1711c","poly":"dermato","fiche":"d111","front":"Acné néonatale : quelle évolution ?","back":"**Régression spontanée** en quelques semaines.","prio":"P3","sec":"s4"},{"id":"fc-d111-52605d","poly":"dermato","fiche":"d111","front":"Acné : quand suspecter une endocrinopathie ?","back":"Acné **féminine grave et résistante** aux traitements, ou acné avec **signes d'hyperandrogénie** (hirsutisme, alopécie, troubles des règles).","prio":"P2","sec":"s4"},{"id":"fc-d111-cfe72e","poly":"dermato","fiche":"d111","front":"Acné et endocrinopathie suspectée : quel bilan hormonal ?","back":"**Testostérone libre**, **17OH-progestérone**, **sulfate de DHA**, **Δ4-androstènedione**.","prio":"P3","sec":"s4"},{"id":"fc-d111-7a3403","poly":"dermato","fiche":"d111","front":"Acné et endocrinopathie suspectée : quel examen d'imagerie et quelle cause la plus fréquente ?","back":"**Échographie abdomino-pelvienne** ; cause la plus fréquente : **maladie des ovaires polykystiques**.","prio":"P2","sec":"s4"},{"id":"fc-d111-be3e36","poly":"dermato","fiche":"d111","front":"Acné : quel signe absent élimine le diagnostic ?","back":"L'absence de toute **lésion rétentionnelle** (ni comédon, ni microkyste).","prio":"P1","sec":"s5"},{"id":"fc-d111-d3a969","poly":"dermato","fiche":"d111","front":"Papulo-pustules du visage sans comédon : quels diagnostics évoquer ?","back":"**Folliculite infectieuse** (bactérienne, à *Demodex*, à *Candida*) ou **rosacée** (papulo-pustuleuse ou granulomateuse).","prio":"P2","sec":"s5"},{"id":"fc-d111-63be8f","poly":"dermato","fiche":"d111","front":"Acné : sur quels deux critères juge-t-on la gravité ?","back":"L'**étendue au visage** (< moitié, > moitié, tout le visage) et le **nombre de nodules**.","prio":"P2","sec":"s6"},{"id":"fc-d111-a3c243","poly":"dermato","fiche":"d111","front":"Acné : au bout de combien de temps juge-t-on un traitement d'attaque ?","back":"À **3 mois**.","prio":"P2","sec":"s6"},{"id":"fc-d111-af37e4","poly":"dermato","fiche":"d111","front":"Acné : quel est le seul traitement capable de guérir ?","back":"L'**isotrétinoïne** ; les autres traitements généraux sont seulement **suspensifs**.","prio":"P1","sec":"s6"},{"id":"fc-d111-7acf76","poly":"dermato","fiche":"d111","front":"Acné légère : quel traitement ?","back":"**Topiques seuls** : **peroxyde de benzoyle**, ou peroxyde de benzoyle + **rétinoïde** topique.","prio":"P1","sec":"s6"},{"id":"fc-d111-827676","poly":"dermato","fiche":"d111","front":"Acné moyenne et/ou sévère : quel traitement ?","back":"Mêmes topiques **+ cycline orale**.","prio":"P1","sec":"s6"},{"id":"fc-d111-634f0c","poly":"dermato","fiche":"d111","front":"Acné : quand recourir à l'isotrétinoïne orale ?","back":"En **2e intention** après **échec de 3 mois de cyclines** ; d'emblée si forme **très sévère**.","prio":"P1","sec":"s6"},{"id":"fc-d111-17f11b","poly":"dermato","fiche":"d111","front":"Acné : que faire une fois la rémission obtenue ?","back":"Traitement **local d'entretien**, poursuivi aussi longtemps que nécessaire.","prio":"P2","sec":"s6"},{"id":"fc-d111-add403","poly":"dermato","fiche":"d111","front":"Acné : quel traitement général ne s'associe pas obligatoirement à un traitement local ?","back":"L'**isotrétinoïne** ; tous les autres doivent être associés à un traitement local.","prio":"P2","sec":"s6"},{"id":"fc-d111-bd218f","poly":"dermato","fiche":"d111","front":"Acné : quelles sont les trois classes de traitements locaux ?","back":"**Rétinoïdes topiques**, **peroxyde de benzoyle**, **antibiotiques locaux** (+ associations fixes).","prio":"P2","sec":"s6"},{"id":"fc-d111-a35f80","poly":"dermato","fiche":"d111","front":"Acné : quels sont les traitements généraux disponibles ?","back":"**Cyclines** (ou macrolides si impossibles), **gluconate de zinc**, **isotrétinoïne**, + place de l'**hormonothérapie** contraceptive.","prio":"P2","sec":"s6"},{"id":"fc-d111-0c2ec4","poly":"dermato","fiche":"d111","front":"Acné : en combien de temps obtient-on en moyenne un résultat appréciable ?","back":"**2 à 3 mois** : l'effet est lent, à annoncer.","prio":"P2","sec":"s11"},{"id":"fc-d111-89c203","poly":"dermato","fiche":"d111","front":"Rétinoïde topique : quelle est son action principale ?","back":"**Comédolytique** (kératolytique) : il vise comédons et microkystes.","prio":"P2","sec":"s7"},{"id":"fc-d111-18ba52","poly":"dermato","fiche":"d111","front":"Quel rétinoïde topique est en plus anti-inflammatoire ?","back":"L'**adapalène** (2e génération).","prio":"P3","sec":"s7"},{"id":"fc-d111-24278a","poly":"dermato","fiche":"d111","front":"Rétinoïdes topiques : quelles molécules ?","back":"**Trétinoïne** (1re génération), **isotrétinoïne topique**, **adapalène** (2e génération).","prio":"P3","sec":"s7"},{"id":"fc-d111-c9e617","poly":"dermato","fiche":"d111","front":"Peroxyde de benzoyle : quelle action principale ?","back":"**Fortement antibactérien** (lésions inflammatoires superficielles), un peu comédolytique, **sans résistance bactérienne** connue.","prio":"P2","sec":"s7"},{"id":"fc-d111-81d651","poly":"dermato","fiche":"d111","front":"Peroxyde de benzoyle : quelles concentrations selon la zone ?","back":"**2,5 ou 5 %** sur le visage ; **10 %** surtout pour le dos.","prio":"P3","sec":"s7"},{"id":"fc-d111-b4381b","poly":"dermato","fiche":"d111","front":"Peroxyde de benzoyle : quels effets indésirables surveiller ?","back":"**Irritation**, **phototoxicité**, **décoloration des vêtements**.","prio":"P3","sec":"s7"},{"id":"fc-d111-685965","poly":"dermato","fiche":"d111","front":"Topiques de l'acné : à quel moment de la journée les appliquer et pourquoi ?","back":"Le **soir** : les UV les dégradent et certains sont photosensibilisants.","prio":"P2","sec":"s7"},{"id":"fc-d111-c33254","poly":"dermato","fiche":"d111","front":"Rétinoïdes topiques : quel est le principal facteur limitant ?","back":"L'**irritation** : adapter la posologie, espacer les applications (par exemple **1 jour sur 2**).","prio":"P2","sec":"s7"},{"id":"fc-d111-3ccbf5","poly":"dermato","fiche":"d111","front":"Antibiotique local de l'acné : quelles molécules ?","back":"**Érythromycine 4 %** ou **clindamycine**.","prio":"P3","sec":"s7"},{"id":"fc-d111-c2e3ca","poly":"dermato","fiche":"d111","front":"Antibiotique local de l'acné : quelle règle d'utilisation ?","back":"**Jamais seul** : toujours avec peroxyde de benzoyle ou rétinoïde, sur une **durée limitée** (résistances).","prio":"P1","sec":"s7"},{"id":"fc-d111-213753","poly":"dermato","fiche":"d111","front":"Antibiotique local de l'acné : pourquoi est-il remis en cause ?","back":"Par la hausse des **résistances** bactériennes, notamment aux **macrolides** (activité par ailleurs **modeste**).","prio":"P3","sec":"s7"},{"id":"fc-d111-c71761","poly":"dermato","fiche":"d111","front":"Acné : quel intérêt des associations fixes de topiques ?","back":"Faciliter l'**observance** (rétinoïde + antibiotique, ou rétinoïde + peroxyde de benzoyle).","prio":"P3","sec":"s7"},{"id":"fc-d111-c57ee4","poly":"dermato","fiche":"d111","front":"Acné sous topiques : quel soin d'accompagnement le matin ?","back":"Une **crème hydratante**, si nécessaire.","prio":"P3","sec":"s7"},{"id":"fc-d111-23c183","poly":"dermato","fiche":"d111","front":"Acné : quelles cyclines utilise-t-on ?","back":"**Doxycycline** ou **lymécycline**.","prio":"P2","sec":"s8"},{"id":"fc-d111-d7a9bf","poly":"dermato","fiche":"d111","front":"Cyclines dans l'acné : à quelle dose agissent-elles ?","back":"Effets antiséborrhéique et anti-inflammatoire à une dose **moitié moindre** que la dose antibactérienne.","prio":"P3","sec":"s8"},{"id":"fc-d111-9fdc73","poly":"dermato","fiche":"d111","front":"Cyclines dans l'acné : quelle durée de traitement ?","back":"**3 mois** en moyenne ; au-delà, risque accru de **résistance**.","prio":"P2","sec":"s8"},{"id":"fc-d111-91f8c8","poly":"dermato","fiche":"d111","front":"Cyclines : en dessous de quel âge sont-elles contre-indiquées et pourquoi ?","back":"Avant **8 ans** : **dyschromies dentaires**.","prio":"P1","sec":"s8"},{"id":"fc-d111-4d5485","poly":"dermato","fiche":"d111","front":"Cycline orale dans l'acné : avec quoi ne jamais l'associer ?","back":"Avec un **antibiotique local** et avec l'**isotrétinoïne** (hypertension intracrânienne).","prio":"P1","sec":"s8"},{"id":"fc-d111-e28eb7","poly":"dermato","fiche":"d111","front":"Quelle cycline expose surtout à la phototoxicité ?","back":"La **doxycycline**.","prio":"P3","sec":"s8"},{"id":"fc-d111-3a9ce7","poly":"dermato","fiche":"d111","front":"Acné : que prescrire si les cyclines sont impossibles (femme enceinte, jeune enfant) ?","back":"Un **macrolide oral** (érythromycine, roxithromycine, josamycine), sur une **courte période**.","prio":"P2","sec":"s8"},{"id":"fc-d111-0d2ea8","poly":"dermato","fiche":"d111","front":"Acné : dans quelles situations les cyclines sont-elles contre-indiquées au profit du zinc ?","back":"**Acné prépubertaire**, **été**, **grossesse** → **gluconate de zinc**.","prio":"P2","sec":"s8"},{"id":"fc-d111-d3f1af","poly":"dermato","fiche":"d111","front":"Gluconate de zinc dans l'acné : quelles caractéristiques ?","back":"Surtout **anti-inflammatoire**, **moins actif** que les cyclines, **sans photosensibilisation**.","prio":"P3","sec":"s8"},{"id":"fc-d111-91081e","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quel est son mécanisme d'action ?","back":"Inhibiteur **non hormonal** de la sécrétion sébacée (**apoptose des sébocytes**) ; le plus puissant des sébostatiques.","prio":"P3","sec":"s9"},{"id":"fc-d111-257f55","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelles particularités de prescription et de délivrance ?","back":"**Réglementation spéciale** (médecin et pharmacien) avec **carnet** de suivi.","prio":"P2","sec":"s9"},{"id":"fc-d111-9a1485","poly":"dermato","fiche":"d111","front":"Isotrétinoïne chez la femme en âge de procréer : quelle contraception et sur quelle période ?","back":"Contraception **efficace** de **1 mois avant** à **1 mois après** l'arrêt, pendant tout le traitement.","prio":"P1","sec":"s9"},{"id":"fc-d111-9cbd02","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quel risque impose une contraception efficace chez la femme en âge de procréer ?","back":"Le **risque tératogène**.","prio":"P1","sec":"s9"},{"id":"fc-d111-a8b5c4","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle démarche d'information est obligatoire ?","back":"**Information détaillée** + **consentement signé** (patiente ou représentant légal si mineure).","prio":"P2","sec":"s9"},{"id":"fc-d111-097090","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : pourquoi évacuer les lésions rétentionnelles avant de commencer ?","back":"Pour limiter les **poussées inflammatoires**.","prio":"P3","sec":"s9"},{"id":"fc-d111-ee9bac","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quel risque psychiatrique évaluer avant de débuter ?","back":"La **dépression** (évaluer l'humeur par une échelle, prévenir le patient).","prio":"P2","sec":"s9"},{"id":"fc-d111-75de87","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quel bilan biologique initial ?","back":"**Transaminases** (ASAT, ALAT), **cholestérol total**, **triglycérides**.","prio":"P2","sec":"s9"},{"id":"fc-d111-f0e230","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle posologie et quelle dose cumulée ?","back":"**0,5 mg/kg/j** en moyenne jusqu'à **120 à 150 mg/kg** cumulés.","prio":"P2","sec":"s9"},{"id":"fc-d111-477d9a","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle posologie dans les formes rétentionnelles ?","back":"**0,2 ou 0,3 mg/kg/j**.","prio":"P3","sec":"s9"},{"id":"fc-d111-e5825c","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle durée moyenne de traitement ?","back":"**9 à 12 mois** en moyenne.","prio":"P3","sec":"s9"},{"id":"fc-d111-5f236b","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle association est contre-indiquée et pourquoi ?","back":"Les **cyclines** : risque d'**hypertension intracrânienne**.","prio":"P1","sec":"s9"},{"id":"fc-d111-f587e0","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : pourquoi proscrire les lentilles de contact ?","back":"Sécheresse oculaire avec **conjonctivite**.","prio":"P3","sec":"s9"},{"id":"fc-d111-ebe6cd","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelle contraception est insuffisante ?","back":"L'association **acétate de cyprotérone/éthinylestradiol** (efficacité contraceptive insuffisante).","prio":"P2","sec":"s9"},{"id":"fc-d111-e4681e","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : à quel rythme surveiller transaminases et lipides ?","back":"Au départ puis **tous les 3 mois**.","prio":"P2","sec":"s9"},{"id":"fc-d111-ed6ec7","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : comment surveiller l'absence de grossesse ?","back":"**β-hCG plasmatiques chaque mois** ; le dernier **5 semaines après l'arrêt**.","prio":"P1","sec":"s9"},{"id":"fc-d111-02f000","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quelles manifestations de sécheresse cutanéo-muqueuse ?","back":"**Chéilite**, xérose cutanée, **conjonctivite**, rhinite sèche avec **épistaxis** (effet dose-dépendant).","prio":"P2","sec":"s9"},{"id":"fc-d111-13ace1","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quand une poussée d'acné est-elle possible ?","back":"Pendant les **4 premières semaines**.","prio":"P3","sec":"s9"},{"id":"fc-d111-675958","poly":"dermato","fiche":"d111","front":"Isotrétinoïne : quels autres effets indésirables surveiller ?","back":"**Douleurs ligamentaires** ; **troubles de l'humeur** (dépression).","prio":"P3","sec":"s9"},{"id":"fc-d111-0c4b68","poly":"dermato","fiche":"d111","front":"Femme acnéique sans besoin de contraception : prescrire un œstroprogestatif pour l'acné ?","back":"**Non**, ce n'est pas recommandé.","prio":"P2","sec":"s10"},{"id":"fc-d111-05b277","poly":"dermato","fiche":"d111","front":"Femme acnéique voulant un œstroprogestatif : quel progestatif en 1re intention ?","back":"Un progestatif peu androgénique : **lévonorgestrel** (2e génération).","prio":"P2","sec":"s10"},{"id":"fc-d111-99c4d6","poly":"dermato","fiche":"d111","front":"Femme acnéique voulant un œstroprogestatif : quel progestatif en 2e intention ?","back":"Le **norgestimate** (assimilé 2e génération).","prio":"P3","sec":"s10"},{"id":"fc-d111-406251","poly":"dermato","fiche":"d111","front":"Acné persistante sous contraception malgré un traitement bien mené : quelle option discuter ?","back":"Avec un **gynécologue** : **acétate de cyprotérone 2 mg/éthinylestradiol 35 µg**, selon l'ANSM (risque **thromboembolique**).","prio":"P3","sec":"s10"},{"id":"fc-d111-28b092","poly":"dermato","fiche":"d111","front":"Acné : faut-il presser les comédons ?","back":"**Non**.","prio":"P3","sec":"s11"},{"id":"fc-d111-c11365","poly":"dermato","fiche":"d111","front":"Acné : où appliquer le traitement local ?","back":"Sur **tout le visage**, pas seulement sur les boutons, le **soir**.","prio":"P2","sec":"s11"},{"id":"fc-d111-454ec1","poly":"dermato","fiche":"d111","front":"Acné : faut-il désinfecter les boutons avec un antiseptique ?","back":"**Non** : antiseptique et toilette vigoureuse sont **inutiles, voire nuisibles**.","prio":"P2","sec":"s11"},{"id":"fc-d111-222215","poly":"dermato","fiche":"d111","front":"Acné : quel régime alimentaire conseiller ?","back":"**Aucun** régime alimentaire.","prio":"P2","sec":"s11"},{"id":"fc-d111-27fa8e","poly":"dermato","fiche":"d111","front":"Acné : quel effet a le soleil ?","back":"Il calme un temps l'inflammation mais **épaissit la peau** et favorise les **comédons** ; l'amélioration de l'été est **généralement** suivie d'une poussée à l'**automne**.","prio":"P3","sec":"s11"},{"id":"fc-d111-7437a9","poly":"dermato","fiche":"d111","front":"Acné sous produits photosensibilisants : quelle précaution solaire ?","back":"Une **photoprotection**, parfois nécessaire, surtout sur **peau foncée**.","prio":"P3","sec":"s11"},{"id":"fc-d111-4623e1","poly":"dermato","fiche":"d111","front":"Acné : quelle place pour les « nettoyages de peau » ?","back":"Au mieux un **complément**.","prio":"P3","sec":"s11"},{"id":"fc-d111-df51ed","poly":"dermato","fiche":"d111","front":"Acné de l'adolescent : quel problème de suivi est fréquent ?","back":"Une **observance souvent médiocre**.","prio":"P3","sec":"s11"},{"id":"fc-d111-e46ae8","poly":"dermato","fiche":"d111","front":"Rosacée : quel terrain ?","back":"**Adulte**, surtout après **20 ans** ; peau, yeux et cheveux **clairs** ; **femme** (environ 2 femmes pour 1 homme).","prio":"P1","sec":"s12"},{"id":"fc-d111-d32b74","poly":"dermato","fiche":"d111","front":"Rosacée : quel est le pic de fréquence ?","back":"Entre **40 et 50 ans**.","prio":"P2","sec":"s12"},{"id":"fc-d111-da2886","poly":"dermato","fiche":"d111","front":"Rosacée : quel terme faut-il abandonner ?","back":"« **Acné rosacée** » (longtemps confondue avec l'acné).","prio":"P2","sec":"s12"},{"id":"fc-d111-ae81af","poly":"dermato","fiche":"d111","front":"Rosacée : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique**, **aucun** examen complémentaire.","prio":"P1","sec":"s12"},{"id":"fc-d111-7acc18","poly":"dermato","fiche":"d111","front":"Rosacée : quelles sont les trois formes ?","back":"**Vasculaire** (paroxystique et permanente), **papulo-pustuleuse**, **hypertrophique** (rhinophyma).","prio":"P1","sec":"s12"},{"id":"fc-d111-a3a683","poly":"dermato","fiche":"d111","front":"Rosacée : comment se présentent les bouffées vasomotrices ?","back":"Rougeur **brutale** du visage et du cou avec chaleur, **sans signe systémique**, durant **quelques minutes**.","prio":"P1","sec":"s12"},{"id":"fc-d111-fce418","poly":"dermato","fiche":"d111","front":"Rosacée : qu'est-ce qui déclenche les bouffées vasomotrices ?","back":"**Changements de température**, boissons et aliments **chauds**, **alcool**, aliments **épicés**.","prio":"P2","sec":"s12"},{"id":"fc-d111-afe8bb","poly":"dermato","fiche":"d111","front":"Rosacée érythémato-télangiectasique : quels signes ?","back":"**Érythème facial permanent** + **télangiectasies** (couperose) des joues, nez, menton, milieu du front.","prio":"P1","sec":"s12"},{"id":"fc-d111-2e2e74","poly":"dermato","fiche":"d111","front":"Quelle est la forme la plus caractéristique de la rosacée ?","back":"La forme **papulo-pustuleuse** : papules et pustules sur un **fond d'érythème permanent**.","prio":"P1","sec":"s12"},{"id":"fc-d111-79d21f","poly":"dermato","fiche":"d111","front":"Rhinophyma : quel aspect clinique ?","back":"Nez **augmenté de volume**, rouge diffus, orifices folliculaires dilatés, peau épaissie et **fibreuse** (« trogne »).","prio":"P2","sec":"s12"},{"id":"fc-d111-6ce43e","poly":"dermato","fiche":"d111","front":"Rhinophyma : quel terrain ?","back":"**Homme** dans plus de **95 %** des cas, généralement après **50 ans**.","prio":"P1","sec":"s12"},{"id":"fc-d111-7d9f9c","poly":"dermato","fiche":"d111","front":"Rhinophyma : est-il dû à l'alcoolisme ?","back":"**Non**, aucun alcoolisme en cause.","prio":"P1","sec":"s12"},{"id":"fc-d111-2cc408","poly":"dermato","fiche":"d111","front":"Rosacée : passe-t-on obligatoirement par les formes successives ?","back":"**Non**, pas obligatoirement.","prio":"P2","sec":"s12"},{"id":"fc-d111-5eab33","poly":"dermato","fiche":"d111","front":"Rosacée versus acné : quels signes distinguent la rosacée ?","back":"**Bouffées vasomotrices**, érythème + télangiectasies, papulo-pustules **sans comédon**, chez l'**adulte**.","prio":"P1","sec":"s13"},{"id":"fc-d111-376ff7","poly":"dermato","fiche":"d111","front":"Acné versus rosacée : quels signes orientent vers l'acné ?","back":"Sujet **jeune**, signes **rétentionnels** (comédons, microkystes), **séborrhée**, **pas de bouffées vasomotrices**.","prio":"P1","sec":"s13"},{"id":"fc-d111-538a09","poly":"dermato","fiche":"d111","front":"Rosacée : quand débute-t-elle par rapport à l'acné ?","back":"**Après l'âge de l'acné**, le plus souvent à l'âge moyen.","prio":"P3","sec":"s13"},{"id":"fc-d111-16e07d","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique versus rosacée : quel aspect la distingue ?","back":"Fond rouge **parsemé de squames grasses** (ailes du nez, sillons naso-labiaux, sourcils, glabelle, lisière du cuir chevelu).","prio":"P1","sec":"s13"},{"id":"fc-d111-4b65ae","poly":"dermato","fiche":"d111","front":"Qu'est-ce que la « dermatose mixte du visage » ?","back":"La **coexistence** d'une **rosacée** et d'une **dermatite séborrhéique** chez la même personne.","prio":"P2","sec":"s13"},{"id":"fc-d111-eaed10","poly":"dermato","fiche":"d111","front":"Rosacée : quelle fréquence de l'atteinte oculaire ?","back":"Signes subjectifs chez **30 à 50 %** des patients.","prio":"P2","sec":"s14"},{"id":"fc-d111-15ec1e","poly":"dermato","fiche":"d111","front":"Rosacée oculaire : quelles manifestations ?","back":"**Sécheresse**, **conjonctivite**, **blépharite**, parfois **kératite**.","prio":"P2","sec":"s14"},{"id":"fc-d111-c3ce53","poly":"dermato","fiche":"d111","front":"Rosacée : quelle évolution ?","back":"**Chronique, par poussées** de papules et pustules, sans facteur déclenchant particulier.","prio":"P2","sec":"s14"},{"id":"fc-d111-7f517c","poly":"dermato","fiche":"d111","front":"Rosacée : quel effet a le soleil ?","back":"Il majore le plus souvent la **rougeur** et les signes fonctionnels.","prio":"P3","sec":"s14"},{"id":"fc-d111-9e9c72","poly":"dermato","fiche":"d111","front":"Rosacée : quels facteurs sont incriminés dans le déclenchement ?","back":"**Climat continental** (fortes amplitudes thermiques), **travail à la chaleur**, **exposition solaire**.","prio":"P3","sec":"s14"},{"id":"fc-d111-c4437b","poly":"dermato","fiche":"d111","front":"Rosacée : comment évoluent les phases inflammatoires avec l'âge ?","back":"Elles tendent à **s'effacer**.","prio":"P3","sec":"s14"},{"id":"fc-d111-d7af69","poly":"dermato","fiche":"d111","front":"Rhinophyma installé : régresse-t-il sous traitement médical ?","back":"**Non** : il ne régresse plus et n'est sensible à aucun traitement **médical**.","prio":"P3","sec":"s14"},{"id":"fc-d111-f7f7f1","poly":"dermato","fiche":"d111","front":"Rosacée : quelle classe thérapeutique est contre-indiquée ?","back":"Les **dermocorticoïdes**.","prio":"P1","sec":"s14"},{"id":"fc-d111-2059d6","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quelle prévalence en France ?","back":"**1 à 3 %** : dermatose **chronique fréquente**.","prio":"P2","sec":"s15"},{"id":"fc-d111-6052a8","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : le rôle du sébum est-il démontré ?","back":"**Non**, pas clairement, malgré la prédilection pour les **zones séborrhéiques**.","prio":"P3","sec":"s15"},{"id":"fc-d111-de1a36","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quel micro-organisme est suspecté ?","back":"Une levure, ***Malassezia*** (*M. furfur*, *M. globosa*…).","prio":"P1","sec":"s15"},{"id":"fc-d111-fb66af","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quels arguments pour le rôle de *Malassezia* ?","back":"Lésions là où la levure est la **plus dense** + efficacité des **antifongiques**.","prio":"P3","sec":"s15"},{"id":"fc-d111-b26ea6","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : la gravité est-elle liée à la densité levurique ?","back":"**Non**, pas de lien quantitatif.","prio":"P3","sec":"s15"},{"id":"fc-d111-3750ab","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : est-elle contagieuse ?","back":"**Non** : pas une maladie infectieuse à proprement parler.","prio":"P2","sec":"s15"},{"id":"fc-d111-c6f58f","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quels examens pour le diagnostic ?","back":"**Aucun** : diagnostic **clinique** (ni biopsie, ni prélèvement mycologique, ni biologie).","prio":"P1","sec":"s16"},{"id":"fc-d111-8a488f","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique de l'adulte : quelle est la localisation la plus fréquente ?","back":"Le **visage**.","prio":"P2","sec":"s16"},{"id":"fc-d111-9c1bcd","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du visage : quel terrain ?","back":"Le plus souvent **homme jeune** (18 à 40 ans).","prio":"P1","sec":"s16"},{"id":"fc-d111-282454","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du visage : quelles lésions élémentaires ?","back":"**Plaques rouges** couvertes de **petites squames grasses**.","prio":"P1","sec":"s16"},{"id":"fc-d111-06f0dd","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du visage : quels sièges ?","back":"**Sillons nasogéniens**, **sourcils**, **glabelle**, lisière antérieure du **cuir chevelu**, barbe et moustache.","prio":"P1","sec":"s16"},{"id":"fc-d111-3b057c","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique étendue du visage : quels sièges supplémentaires ?","back":"**Menton** et **bords ciliaires** (blépharite séborrhéique).","prio":"P3","sec":"s16"},{"id":"fc-d111-7b7e7c","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : qu'est-ce qui l'aggrave et quand s'améliore-t-elle ?","back":"Aggravée par le **stress émotionnel** ; amélioration spontanée en **été**.","prio":"P2","sec":"s16"},{"id":"fc-d111-6a4b36","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du cuir chevelu : quelle forme minimale ?","back":"L'**état pelliculaire** (**pityriasis capitis**) : petites squames non adhérentes.","prio":"P2","sec":"s16"},{"id":"fc-d111-1342da","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du cuir chevelu : comment s'appelle la forme sévère ?","back":"Le **pityriasis amiantacé** : casque engainant des touffes de cheveux.","prio":"P3","sec":"s16"},{"id":"fc-d111-c4a8de","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du tronc : quel aspect ?","back":"Plaques **annulaires ou circinées** à bordure squameuse de la région **présternale**.","prio":"P3","sec":"s16"},{"id":"fc-d111-63eaf8","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du nourrisson : quand débute-t-elle ?","back":"**Après la deuxième semaine de vie**, chez un enfant en bonne santé.","prio":"P2","sec":"s16"},{"id":"fc-d111-5c95a8","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique du nourrisson : quelles lésions ?","back":"**Croûtes jaunes** du cuir chevelu (« croûtes de lait ») et du visage ; possibles dermatite du siège et squames grasses axillaires.","prio":"P1","sec":"s16"},{"id":"fc-d111-83ffd9","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique étendue du nourrisson : comment s'appelle-t-elle ?","back":"L'**érythrodermie de Leiner-Moussous**, le plus souvent spontanément favorable.","prio":"P2","sec":"s16"},{"id":"fc-d111-d8003e","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique sévère et étendue : sur quels terrains est-elle plus fréquente ?","back":"**Parkinson** ou syndromes extrapyramidaux iatrogènes, **alcoolisme chronique**, **carcinome des VADS** traité, **VIH**.","prio":"P1","sec":"s16"},{"id":"fc-d111-342c27","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique et VIH : quelle fréquence ?","back":"**40 %** des séropositifs, jusqu'à **80 %** au stade sida.","prio":"P2","sec":"s16"},{"id":"fc-d111-fc3f21","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique grave et/ou chronique : quel examen réaliser ?","back":"Un **test de dépistage du VIH**.","prio":"P1","sec":"s16"},{"id":"fc-d111-738b1c","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique au cours du VIH : quelles particularités ?","back":"Formes **profuses** qui **résistent** au traitement.","prio":"P2","sec":"s18"},{"id":"fc-d111-95e327","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique versus sébopsoriasis : comment les distinguer ?","back":"Souvent **impossible cliniquement** ; on s'aide des **localisations extrafaciales** et des **antécédents**.","prio":"P2","sec":"s17"},{"id":"fc-d111-28981d","poly":"dermato","fiche":"d111","front":"Érythrodermie de Leiner-Moussous : de quoi peut-elle être le début ?","back":"D'une **dermatite atopique** ou d'un **psoriasis**.","prio":"P3","sec":"s17"},{"id":"fc-d111-da007b","poly":"dermato","fiche":"d111","front":"Dermatite atopique de l'adulte versus dermatite séborrhéique : quel élément distinctif ?","back":"La dermatite atopique **déborde largement** les zones séborrhéiques.","prio":"P3","sec":"s17"},{"id":"fc-d111-3998e1","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quel est le traitement ?","back":"Essentiellement **local antifongique**.","prio":"P1","sec":"s18"},{"id":"fc-d111-6f1d54","poly":"dermato","fiche":"d111","front":"Dermatite séborrhéique : quelle évolution annoncer ?","back":"Dermatose **chronique** par **poussées**, **parfois** favorisées par le stress, avec amélioration spontanée en **été**.","prio":"P2","sec":"s18"},{"id":"fc-d112-7c47ad","poly":"dermato","fiche":"d112","front":"DBAI : quelle fréquence et quel pronostic globalement ?","back":"Maladies **peu fréquentes**, groupe hétérogène ; pronostic **variable**, souvent **péjoratif**.","prio":"P2","sec":"s1"},{"id":"fc-d112-d03b1c","poly":"dermato","fiche":"d112","front":"DBAI : sur quels trois volets repose le diagnostic ?","back":"**Clinique** + **histologie** d'une biopsie cutanée + **immunopathologie** (IFD, anticorps sériques anti-épiderme).","prio":"P1","sec":"s1"},{"id":"fc-d112-898c13","poly":"dermato","fiche":"d112","front":"DBAI : par quel examen voit-on les anticorps fixés in vivo dans la peau ?","back":"L'**immunofluorescence directe (IFD)**.","prio":"P1","sec":"s1"},{"id":"fc-d112-406239","poly":"dermato","fiche":"d112","front":"DBAI : quelles protéines les autoanticorps prennent-ils pour cible ?","back":"Des **protéines d'adhérence** : de la **jonction dermo-épidermique (JDE)** ou des **jonctions entre kératinocytes**.","prio":"P1","sec":"s1"},{"id":"fc-d112-e43878","poly":"dermato","fiche":"d112","front":"DBAI : quelles muqueuses peuvent être atteintes ?","back":"**Bouche**, **conjonctive**, organes **génitaux**, anus, nez, œsophage, pharynx, larynx.","prio":"P2","sec":"s1"},{"id":"fc-d112-104650","poly":"dermato","fiche":"d112","front":"Peau : quelle structure assure la cohésion des kératinocytes entre eux ?","back":"Les **desmosomes**.","prio":"P2","sec":"s1"},{"id":"fc-d112-9da91e","poly":"dermato","fiche":"d112","front":"JDE : quelles structures, de la surface vers la profondeur ?","back":"**Hémidesmosomes** (pôle basal du kératinocyte) → **filaments d'ancrage** → **lame dense** → **fibrilles d'ancrage**.","prio":"P3","sec":"s1"},{"id":"fc-d112-d12e0a","poly":"dermato","fiche":"d112","front":"Anticorps anti-desmosomes : quelle conséquence histologique ?","back":"Séparation des kératinocytes = **acantholyse** → bulle **intra-épidermique** (groupe des **pemphigus**).","prio":"P1","sec":"s1"},{"id":"fc-d112-961868","poly":"dermato","fiche":"d112","front":"Anticorps contre un composant de la JDE : quel type de bulle ?","back":"Bulle **sous-épidermique** (décollement derme-épiderme) : groupe des **pemphigoïdes** et autres DBAI de la JDE.","prio":"P1","sec":"s1"},{"id":"fc-d112-da14fc","poly":"dermato","fiche":"d112","front":"Pemphigus : comment nomme-t-on les anticorps en cause ?","back":"Anticorps **anti-substance intercellulaire (anti-SIC)**.","prio":"P2","sec":"s1"},{"id":"fc-d112-727741","poly":"dermato","fiche":"d112","front":"DBAI sous-épidermiques : comment nomme-t-on les anticorps en cause ?","back":"Anticorps **anti-membrane basale**.","prio":"P2","sec":"s1"},{"id":"fc-d112-21fba6","poly":"dermato","fiche":"d112","front":"Moyen mnémotechnique : pemphIgus, quel niveau de clivage ?","back":"Pemph**I**gus = **I**ntra-épidermique : toit mince, bulle **flasque** (pemphigoïde : toit = épiderme entier, bulle tendue).","prio":"P2","sec":"s1"},{"id":"fc-d112-0524d4","poly":"dermato","fiche":"d112","front":"Bulle : définition ?","back":"Lésion élémentaire **liquidienne superficielle**, contenu **clair ou séro-hématique**, taille **> 5 mm**, sur peau ou muqueuses.","prio":"P1","sec":"s2"},{"id":"fc-d112-03f872","poly":"dermato","fiche":"d112","front":"Hors bulle visible : quels signes doivent faire évoquer une dermatose bulleuse ?","back":"**Érosions post-bulleuses** arrondies (parfois croûteuses) ; **érosions muqueuses** ; décollement en « **linge mouillé** » ; **signe de Nikolsky**.","prio":"P1","sec":"s2"},{"id":"fc-d112-c9b711","poly":"dermato","fiche":"d112","front":"Signe de Nikolsky : en quoi consiste-t-il ?","back":"Un **frottement appuyé sur la peau saine** la décolle.","prio":"P1","sec":"s2"},{"id":"fc-d112-4aad5c","poly":"dermato","fiche":"d112","front":"Signe de Nikolsky : quel niveau de décollement traduit-il ?","back":"Un décollement **intra-épidermique** (**acantholyse**).","prio":"P1","sec":"s2"},{"id":"fc-d112-597642","poly":"dermato","fiche":"d112","front":"Bulle tendue : quel niveau de clivage et pourquoi ?","back":"Clivage **sous-épidermique** : son toit est l'**épiderme intact** → DBAI de la JDE (pemphigoïdes).","prio":"P1","sec":"s2"},{"id":"fc-d112-ba311c","poly":"dermato","fiche":"d112","front":"Bulle flasque et fragile : quel niveau de clivage et pourquoi ?","back":"Clivage **intra-épidermique** : toit **très fin** → groupe des **pemphigus**.","prio":"P1","sec":"s2"},{"id":"fc-d112-d78fc6","poly":"dermato","fiche":"d112","front":"Muqueuses : pourquoi des érosions suffisent-elles à évoquer une dermatose bulleuse ?","back":"Les bulles muqueuses sont **fugaces**, **rarement vues** : on ne voit souvent que des **érosions**.","prio":"P2","sec":"s2"},{"id":"fc-d112-80d970","poly":"dermato","fiche":"d112","front":"Examen d'une DBAI : peau péribulleuse saine, quelle orientation ?","back":"**Pemphigus**.","prio":"P1","sec":"s3"},{"id":"fc-d112-5cca00","poly":"dermato","fiche":"d112","front":"Examen d'une DBAI : peau péribulleuse urticarienne ou érythémateuse, quelle orientation ?","back":"**Pemphigoïde bulleuse**.","prio":"P1","sec":"s3"},{"id":"fc-d112-c3f55b","poly":"dermato","fiche":"d112","front":"DBAI : topographie tronc, racine et face de flexion des membres, quelle orientation ?","back":"**Pemphigoïde bulleuse**.","prio":"P2","sec":"s3"},{"id":"fc-d112-adaa48","poly":"dermato","fiche":"d112","front":"DBAI : bulles des faces d'extension des membres, quelles orientations ?","back":"**Dermatite herpétiforme**, **épidermolyse bulleuse acquise**.","prio":"P2","sec":"s3"},{"id":"fc-d112-be20b5","poly":"dermato","fiche":"d112","front":"DBAI : atteinte des plis de flexion et du cuir chevelu, quelles orientations ?","back":"**Pemphigus**, **pemphigoïde cicatricielle**.","prio":"P2","sec":"s3"},{"id":"fc-d112-edd020","poly":"dermato","fiche":"d112","front":"DBAI : lésions des muqueuses (bouche, conjonctive, génitales), quelles orientations ?","back":"**Pemphigus** ou **pemphigoïde cicatricielle**.","prio":"P1","sec":"s3"},{"id":"fc-d112-b7cbd9","poly":"dermato","fiche":"d112","front":"DBAI : que rechercher à l'interrogatoire ?","back":"**Médicaments inducteurs** ; antécédents personnels/familiaux de **maladies auto-immunes** ; âge de début ; **prurit** ; circonstances (grossesse).","prio":"P2","sec":"s3"},{"id":"fc-d112-5b0224","poly":"dermato","fiche":"d112","front":"Quelle DBAI évoquer devant une apparition pendant la grossesse ?","back":"La **pemphigoïde gravidique**.","prio":"P2","sec":"s3"},{"id":"fc-d112-9e7c65","poly":"dermato","fiche":"d112","front":"DBAI : quels terrains débilités rechercher et pourquoi ?","back":"**Maladies neurologiques grabatisantes** (AVC, démence, Parkinson), **diabète**, **insuffisance cardiaque** : complications à la mise en route des **corticoïdes**.","prio":"P2","sec":"s3"},{"id":"fc-d112-635e5a","poly":"dermato","fiche":"d112","front":"Quelles maladies neurologiques sont souvent associées à la pemphigoïde bulleuse ?","back":"Maladies **grabatisantes** : **AVC**, **démence**, **maladie de Parkinson**.","prio":"P3","sec":"s3"},{"id":"fc-d112-01626f","poly":"dermato","fiche":"d112","front":"DBAI : quelle forme impose une hospitalisation en dermatologie ?","back":"Toute DBAI **étendue** et/ou **rapidement évolutive** → service **spécialisé de dermatologie**.","prio":"P1","sec":"s3"},{"id":"fc-d112-16fa17","poly":"dermato","fiche":"d112","front":"DBAI : sur quelle lésion porte la biopsie pour l'histologie standard ?","back":"Une bulle cutanée **intacte et récente** (ou le **bord d'une érosion muqueuse**), sous anesthésie locale.","prio":"P1","sec":"s4"},{"id":"fc-d112-d1db76","poly":"dermato","fiche":"d112","front":"DBAI : que montre l'histologie standard de la bulle ?","back":"Le niveau du clivage : **sous-épidermique** ou **intra-épidermique**.","prio":"P1","sec":"s4"},{"id":"fc-d112-4740ce","poly":"dermato","fiche":"d112","front":"DBAI : où se fait la biopsie pour l'IFD ?","back":"En peau ou muqueuse **périlésionnelle**.","prio":"P1","sec":"s4"},{"id":"fc-d112-3f1d4b","poly":"dermato","fiche":"d112","front":"DBAI : quels dépôts recherche l'IFD ?","back":"Dépôts in vivo d'**IgG** et/ou d'**IgA** et/ou de **C3**, anti-membrane basale ou anti-SIC.","prio":"P1","sec":"s4"},{"id":"fc-d112-01fa61","poly":"dermato","fiche":"d112","front":"DBAI : comment rechercher les anticorps sériques circulants ?","back":"**IFI standard** (classe IgG/IgA et **titre**) ; caractérisation de l'antigène par **immunotransfert** ou **ELISA**.","prio":"P2","sec":"s4"},{"id":"fc-d112-6cf398","poly":"dermato","fiche":"d112","front":"IFD : dépôts linéaires le long de la JDE, quel groupe ?","back":"DBAI **sous-épidermiques** (pemphigoïdes).","prio":"P1","sec":"s4"},{"id":"fc-d112-48fdb8","poly":"dermato","fiche":"d112","front":"IFD : dépôts en mailles de filet autour des kératinocytes, quel groupe ?","back":"DBAI **intra-épidermiques** = **pemphigus** (aspect en **résille**).","prio":"P1","sec":"s4"},{"id":"fc-d112-5a3e92","poly":"dermato","fiche":"d112","front":"Muqueuse : contre quelle jonction sont dirigés les anticorps anti-membrane basale ?","back":"La **jonction chorio-épithéliale** (équivalent muqueux de la JDE).","prio":"P3","sec":"s4"},{"id":"fc-d112-8f23f2","poly":"dermato","fiche":"d112","front":"DBAI : combien de biopsies faire, et pour quel examen chacune ?","back":"**Deux biopsies distinctes** : bulle intacte et récente → histologie ; peau/muqueuse **périlésionnelle** → IFD.","prio":"P1","sec":"s4"},{"id":"fc-d112-48e1b8","poly":"dermato","fiche":"d112","front":"Bulles non auto-immunes : sur quoi les écarte-t-on ?","back":"Aspect clinique, évolution et examens immunopathologiques **négatifs**, surtout l'**IFD cutanée**.","prio":"P2","sec":"s5"},{"id":"fc-d112-971531","poly":"dermato","fiche":"d112","front":"Devant des bulles : quelle toxidermie grave éliminer en priorité ?","back":"La **nécrolyse épidermique toxique** : syndrome de **Lyell**, syndrome de **Stevens-Johnson**.","prio":"P1","sec":"s5"},{"id":"fc-d112-732d13","poly":"dermato","fiche":"d112","front":"Nécrolyse épidermique toxique : quels arguments cliniques ?","back":"Début **brutal**, évolution rapide, **signes généraux**, atteinte **muqueuse** fréquente et souvent **inaugurale**, médicament dans le **délai d'imputabilité**.","prio":"P1","sec":"s5"},{"id":"fc-d112-279764","poly":"dermato","fiche":"d112","front":"Nécrolyse épidermique toxique : quelle prise en charge immédiate ?","back":"**Hospitalisation en urgence** (signes généraux) ; ce n'est **pas une DBAI**.","prio":"P1","sec":"s5"},{"id":"fc-d112-413a42","poly":"dermato","fiche":"d112","front":"Dermatose bulleuse par agents externes : comment fait-on le diagnostic ?","back":"Par l'**anamnèse**.","prio":"P2","sec":"s5"},{"id":"fc-d112-ac14ad","poly":"dermato","fiche":"d112","front":"Dermatoses bulleuses par agents externes : citer des causes physiques ?","back":"**Coup de soleil** (érythème actinique), **dermite des prés** (photophytodermatose), **brûlure thermique**.","prio":"P3","sec":"s5"},{"id":"fc-d112-cc1984","poly":"dermato","fiche":"d112","front":"Dermatoses bulleuses par agents externes : citer des causes chimiques ou autres ?","back":"**Dermatite caustique**, **piqûres d'insectes**.","prio":"P3","sec":"s5"},{"id":"fc-d112-388d14","poly":"dermato","fiche":"d112","front":"Érythème polymorphe bulleux : quel aspect des lésions ?","back":"Lésions en **cocardes** (au moins **trois cercles concentriques**), disposition **acrale** (coudes, genoux, mains, visage).","prio":"P2","sec":"s5"},{"id":"fc-d112-cda672","poly":"dermato","fiche":"d112","front":"Érythème polymorphe bulleux : quel contexte de survenue le plus souvent ?","back":"**10-15 jours après une infection**, surtout une **récurrence d'herpès**.","prio":"P2","sec":"s5"},{"id":"fc-d112-f00c23","poly":"dermato","fiche":"d112","front":"Érythème polymorphe bulleux : quelle évolution et quelle atteinte muqueuse ?","back":"Guérit **seul en 2 à 3 semaines** ; lésions muqueuses bulleuses ou érosives **fréquentes** (bouche, génitales, conjonctives).","prio":"P3","sec":"s5"},{"id":"fc-d112-1a7ed7","poly":"dermato","fiche":"d112","front":"Bulles de l'adulte : quel diagnostic non auto-immun éliminer en plus ?","back":"La **porphyrie cutanée tardive**.","prio":"P3","sec":"s5"},{"id":"fc-d112-d8070c","poly":"dermato","fiche":"d112","front":"Bulles de l'enfant : quels diagnostics non auto-immuns éliminer en plus ?","back":"**Épidermolyse bulleuse héréditaire** et **épidermolyse staphylococcique**.","prio":"P3","sec":"s5"},{"id":"fc-d112-9269af","poly":"dermato","fiche":"d112","front":"DBAI sous-épidermiques : contre quoi sont dirigés les autoanticorps ?","back":"Contre **différentes protéines de la JDE**.","prio":"P3","sec":"s6"},{"id":"fc-d112-75d118","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelles cibles antigéniques ?","back":"**BPAG1 (BP230)** et **BPAG2 (BP180)** ; IFD : dépôts linéaires IgG, C3.","prio":"P2","sec":"s6"},{"id":"fc-d112-0446fb","poly":"dermato","fiche":"d112","front":"Pemphigoïde gravidique et pemphigoïde cicatricielle : quelle cible antigénique ?","back":"**BPAG2** (cible commune aux trois pemphigoïdes du tableau).","prio":"P3","sec":"s6"},{"id":"fc-d112-e529ff","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : quelle cible antigénique ?","back":"La **desmogléine 3** (clivage profond, **suprabasal**).","prio":"P2","sec":"s6"},{"id":"fc-d112-89534a","poly":"dermato","fiche":"d112","front":"Pemphigus superficiel : quelle cible antigénique ?","back":"La **desmogléine 1** (clivage **sous-corné**).","prio":"P2","sec":"s6"},{"id":"fc-d112-7fdeaf","poly":"dermato","fiche":"d112","front":"Pemphigus : citer les formes du groupe intra-épidermique au tableau de classification ?","back":"Pemphigus **vulgaire**, **superficiel**, **paranéoplasique**, **médicamenteux** (dépôts IgG, C3 en mailles).","prio":"P3","sec":"s6"},{"id":"fc-d112-2fa854","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : âge de survenue ?","back":"Pemphigoïde : **> 70 ans** ; pemphigus : **40-50 ans**.","prio":"P1","sec":"s7"},{"id":"fc-d112-ef4579","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : prodromes ?","back":"Pemphigoïde : **prurit ++** ; pemphigus : **pas** de prodrome prurigineux.","prio":"P1","sec":"s7"},{"id":"fc-d112-dfe859","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : atteinte muqueuse ?","back":"Pemphigoïde : **rare** ; pemphigus : **+++**, **inaugurale**.","prio":"P1","sec":"s7"},{"id":"fc-d112-e4e4af","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : aspect de l'atteinte cutanée ?","back":"Pemphigoïde : bulles **tendues** sur peau **lésée** (eczématiforme, urticarienne) ; pemphigus : bulles **flasques** sur peau **saine**, **érosions ++**.","prio":"P1","sec":"s7"},{"id":"fc-d112-8054a4","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : topographie ?","back":"Pemphigoïde : **symétrique**, extrémités (forme dishydrosique) ; pemphigus : **plis**, zones de frottement, **cuir chevelu**.","prio":"P2","sec":"s7"},{"id":"fc-d112-93fd1a","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : histologie ?","back":"Pemphigoïde : bulle **sous-épidermique + éosinophiles** ; pemphigus : bulle **intra-épidermique**.","prio":"P1","sec":"s7"},{"id":"fc-d112-c65533","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : signe de Nikolsky ?","back":"**Absent** dans la pemphigoïde ; **présent** dans le pemphigus.","prio":"P1","sec":"s7"},{"id":"fc-d112-957012","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse vs pemphigus : Western blot / ELISA ?","back":"Pemphigoïde : **230-180 kD** (BP230, BP180) ; pemphigus : **130 kD** (desmogléine 3).","prio":"P3","sec":"s7"},{"id":"fc-d112-0e6bc4","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle place parmi les DBAI ?","back":"La DBAI **la plus fréquente**.","prio":"P1","sec":"s8"},{"id":"fc-d112-911358","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quel âge moyen ?","back":"Sujet âgé : **80 ans** en moyenne.","prio":"P1","sec":"s8"},{"id":"fc-d112-af16ea","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : par quoi débute-t-elle ?","back":"**Prurit généralisé et intense**, avec placards **eczématiformes** ou **urticariens**.","prio":"P1","sec":"s8"},{"id":"fc-d112-589aa2","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle éruption typique ?","back":"Bulles **tendues**, souvent grandes, sur base érythémateuse, eczématiforme ou urticarienne.","prio":"P1","sec":"s8"},{"id":"fc-d112-09b279","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle topographie de prédilection ?","back":"**Symétrique** : faces de **flexion** et **racine des membres**, face antéro-interne des **cuisses**, **abdomen**.","prio":"P2","sec":"s8"},{"id":"fc-d112-863c36","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : Nikolsky et muqueuses ?","back":"**Pas de signe de Nikolsky** ; atteinte muqueuse **rare** (habituellement absente).","prio":"P1","sec":"s8"},{"id":"fc-d112-e2dcf0","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle anomalie fréquente à la NFS ?","back":"**Hyperéosinophilie** (fréquente).","prio":"P1","sec":"s8"},{"id":"fc-d112-350a7f","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle histologie standard ?","back":"Bulle **sous-épidermique** à **éosinophiles**, sans acantholyse ni nécrose kératinocytaire ; infiltrat dermique riche en éosinophiles.","prio":"P1","sec":"s8"},{"id":"fc-d112-4bf289","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quel résultat d'IFD ?","back":"Dépôts **linéaires** d'**IgG** et/ou de **C3** à la **JDE**.","prio":"P1","sec":"s8"},{"id":"fc-d112-043547","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : fréquence des anticorps anti-membrane basale en IFI standard ?","back":"IgG retrouvées dans **80 %** des sérums.","prio":"P3","sec":"s8"},{"id":"fc-d112-1788d3","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : le titre des anticorps en IFI reflète-t-il la sévérité ?","back":"**Non** : sans lien avec la **sévérité** ni l'**étendue** (contrairement au pemphigus).","prio":"P2","sec":"s8"},{"id":"fc-d112-760d51","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : que montre l'IFI sur peau clivée ?","back":"Anticorps fixés au **toit** du clivage (versant **épidermique**).","prio":"P3","sec":"s8"},{"id":"fc-d112-5a2694","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quels anticorps recherche l'ELISA ?","back":"**Anti-BPAG1** et **anti-BPAG2**.","prio":"P3","sec":"s8"},{"id":"fc-d112-870acd","poly":"dermato","fiche":"d112","front":"Pemphigus : quel mécanisme physiopathologique ?","back":"Autoanticorps contre des protéines des **desmosomes** → **acantholyse** → clivage **intra-épidermique**.","prio":"P1","sec":"s9"},{"id":"fc-d112-9ad3fd","poly":"dermato","fiche":"d112","front":"Pemphigus : citer les trois grands types ?","back":"Pemphigus **vulgaire** (suprabasal), pemphigus **superficiels** (sous-corné), pemphigus **paranéoplasique**.","prio":"P2","sec":"s9"},{"id":"fc-d112-54f374","poly":"dermato","fiche":"d112","front":"Pemphigus induits : quels médicaments à groupe thiol ?","back":"**D-pénicillamine**, **captopril**, thiopronine, pyrithioxine.","prio":"P2","sec":"s9"},{"id":"fc-d112-337553","poly":"dermato","fiche":"d112","front":"Pemphigus induits : quelles autres molécules (sans groupe thiol) ?","back":"**Piroxicam**, **bêtabloquants**, phénylbutazone, **rifampicine**.","prio":"P3","sec":"s9"},{"id":"fc-d112-5cf856","poly":"dermato","fiche":"d112","front":"Pemphigus induit : l'arrêt du médicament suffit-il ?","back":"**Pas toujours**, à la différence des dermatoses à **IgA linéaire** médicamenteuses.","prio":"P2","sec":"s9"},{"id":"fc-d112-988203","poly":"dermato","fiche":"d112","front":"Pemphigus : à quelles maladies auto-immunes peut-il s'associer ?","back":"**Myasthénie**, **lupus**, Gougerot-Sjögren, polyarthrite rhumatoïde, **Basedow**, glomérulonéphrites.","prio":"P3","sec":"s9"},{"id":"fc-d112-43ecce","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : comment débute-t-il souvent ?","back":"De façon **insidieuse** par des **érosions muqueuses**, surtout **buccales**, douloureuses et traînantes.","prio":"P1","sec":"s9"},{"id":"fc-d112-3c7865","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : retentissement des érosions buccales ?","back":"Gêne à l'alimentation → **dysphagie**, **amaigrissement**.","prio":"P2","sec":"s9"},{"id":"fc-d112-6dd683","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : en dehors de la bouche, quelles autres muqueuses peuvent être érodées ?","back":"**Génitales** (moins souvent) ; **parfois** œsophagiennes, intravaginales, anales, oculaires.","prio":"P3","sec":"s9"},{"id":"fc-d112-d36370","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : quand apparaît l'atteinte cutanée ?","back":"En général **secondairement**, **plusieurs semaines ou mois** après les érosions muqueuses.","prio":"P1","sec":"s9"},{"id":"fc-d112-b20446","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : quel aspect des bulles cutanées ?","back":"Bulles **flasques**, contenu clair, en **peau saine**, vite remplacées par des **érosions** à **collerette épidermique**.","prio":"P1","sec":"s9"},{"id":"fc-d112-736d26","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : où siègent volontiers les érosions post-bulleuses ?","back":"**Plis de flexion** et **cuir chevelu** (autres sites possibles).","prio":"P2","sec":"s9"},{"id":"fc-d112-e1c6eb","poly":"dermato","fiche":"d112","front":"Pemphigus vulgaire : où recherche-t-on le signe de Nikolsky ?","back":"En peau **périlésionnelle**, parfois en **peau saine**.","prio":"P2","sec":"s9"},{"id":"fc-d112-ab6ad7","poly":"dermato","fiche":"d112","front":"Pemphigus superficiels : quelles deux formes ?","back":"**Séborrhéique** (forme localisée) et **foliacé** (forme disséminée).","prio":"P3","sec":"s9"},{"id":"fc-d112-9b38d0","poly":"dermato","fiche":"d112","front":"Pemphigus séborrhéique : quel aspect clinique ?","back":"Bulles très fugaces → lésions **squamo-croûteuses** (érythémato-squameuses à bordure figurée), parfois prurigineuses.","prio":"P3","sec":"s9"},{"id":"fc-d112-33e76e","poly":"dermato","fiche":"d112","front":"Pemphigus séborrhéique : quelle topographie et quelle atteinte muqueuse ?","back":"Zones **séborrhéiques** (thorax antérieur, visage, cuir chevelu, interscapulaire) ; en général **pas d'atteinte muqueuse**.","prio":"P3","sec":"s9"},{"id":"fc-d112-fb3799","poly":"dermato","fiche":"d112","front":"Pemphigus : que montre l'histologie d'une bulle récente ?","back":"Bulle **intra-épidermique** (suprabasale si vulgaire, sous-cornée si superficiel) avec **acantholyse**.","prio":"P1","sec":"s9"},{"id":"fc-d112-d591f2","poly":"dermato","fiche":"d112","front":"Pemphigus superficiels : à quel niveau se fait le clivage histologique ?","back":"**Sous-corné**, par clivage dans la **couche granuleuse**.","prio":"P3","sec":"s9"},{"id":"fc-d112-f3d57c","poly":"dermato","fiche":"d112","front":"Pemphigus : quel résultat d'IFD ?","back":"Dépôts d'**IgG** et de **C3** autour des kératinocytes, aspect **en résille** (mailles de filet).","prio":"P1","sec":"s9"},{"id":"fc-d112-47d7eb","poly":"dermato","fiche":"d112","front":"Pemphigus : que trouve l'IFI standard dans le sérum ?","back":"Anticorps circulants **anti-SIC** de classe **IgG**, titre **corrélé à l'activité** de la maladie.","prio":"P2","sec":"s9"},{"id":"fc-d112-396c2e","poly":"dermato","fiche":"d112","front":"DBAI suspectée : quelles étapes de la conduite à tenir, dans l'ordre ?","back":"Hospitaliser si **étendue**/rapide → éliminer une **nécrolyse épidermique toxique** → biopsie de bulle (**histologie**) → biopsie périlésionnelle (**IFD**) → sérum (**IFI**).","prio":"P1","sec":"s10"},{"id":"fc-d112-b09e6b","poly":"dermato","fiche":"d112","front":"DBAI : sur quoi repose surtout le traitement des principales formes ?","back":"Les **corticoïdes**, **locaux ou généraux**, eux-mêmes sources de complications **iatrogènes**.","prio":"P1","sec":"s10"},{"id":"fc-d112-2ac266","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle mortalité à 1 an ?","back":"**30 à 40 %** de décès à 1 an (maladie grave).","prio":"P1","sec":"s11"},{"id":"fc-d112-080f8d","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelles causes de décès ?","back":"**Infections** (septicémie, pneumopathie) et causes **cardiovasculaires** (insuffisance cardiaque, AVC), favorisées par corticoïdes/immunosuppresseurs et **grand âge**.","prio":"P1","sec":"s11"},{"id":"fc-d112-a53d36","poly":"dermato","fiche":"d112","front":"Maladie bulleuse : quels soins communs (locaux, hydratation, nutrition) ?","back":"**Bains antiseptiques** ; compenser les pertes **hydro-électrolytiques** ; nutrition **hypercalorique** (pertes protéiques).","prio":"P2","sec":"s11"},{"id":"fc-d112-d792cd","poly":"dermato","fiche":"d112","front":"Maladie bulleuse : pertes hydro-électrolytiques, quelle voie éviter si possible et pourquoi ?","back":"La **voie veineuse**, à cause du **risque infectieux**.","prio":"P2","sec":"s11"},{"id":"fc-d112-6691a4","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quel traitement local de référence et à quelle dose ?","back":"**Propionate de clobétasol 20 à 40 g/jour**, puis décroissance **par paliers**.","prio":"P1","sec":"s11"},{"id":"fc-d112-d83228","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : durée totale du clobétasol ?","back":"**6 à 12 mois** au total (décroissance par paliers progressifs).","prio":"P1","sec":"s11"},{"id":"fc-d112-968131","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : clobétasol local comparé à la corticothérapie générale ?","back":"**Aussi efficace**, mieux toléré : **moins d'effets indésirables**, **mortalité plus basse**.","prio":"P1","sec":"s11"},{"id":"fc-d112-ce1c68","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quelle dose de prednisone en alternative ?","back":"**0,5 à 0,75 mg/kg/j**, puis décroissance progressive sur **plusieurs mois**.","prio":"P1","sec":"s11"},{"id":"fc-d112-e2e0ae","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse : quand la prednisone peut-elle être choisie en première intention ?","back":"Si l'atteinte est **limitée** : **< 10 bulles par jour**.","prio":"P2","sec":"s11"},{"id":"fc-d112-690b28","poly":"dermato","fiche":"d112","front":"Pemphigoïde bulleuse sous corticoïdes : que surveiller de près ?","back":"**Poids**, **pression artérielle**, foyers **infectieux**, prévention des **thromboses**, **diabète** (iatrogénie majeure à cet âge).","prio":"P1","sec":"s11"},{"id":"fc-d112-88c1b5","poly":"dermato","fiche":"d112","front":"Corticothérapie d'une DBAI : quoi associer systématiquement ?","back":"Des **mesures adjuvantes** (non détaillées dans ce chapitre).","prio":"P3","sec":"s11"},{"id":"fc-d112-8b1ede","poly":"dermato","fiche":"d112","front":"Pemphigus : quelle mortalité et quelle cause principale ?","back":"Environ **10 %**, surtout liée aux complications **iatrogènes** du traitement.","prio":"P1","sec":"s12"},{"id":"fc-d112-2e15c1","poly":"dermato","fiche":"d112","front":"Pemphigus : quel traitement d'attaque ?","back":"**Corticothérapie générale à forte dose** : prednisone **1 à 1,5 mg/kg/j**.","prio":"P1","sec":"s12"},{"id":"fc-d112-a24cfe","poly":"dermato","fiche":"d112","front":"Prednisone : comparer les doses de la pemphigoïde bulleuse et du pemphigus ?","back":"Pemphigoïde : **0,5 à 0,75 mg/kg/j** ; pemphigus : **1 à 1,5 mg/kg/j** (plus forte).","prio":"P1","sec":"s12"},{"id":"fc-d112-2c7a49","poly":"dermato","fiche":"d112","front":"Pemphigus : place du rituximab ?","back":"Anti-**CD20**, proposable **dès la première intention** pour réduire **dose et durée** des corticoïdes et leurs effets indésirables.","prio":"P2","sec":"s12"},{"id":"fc-d112-5640d1","poly":"dermato","fiche":"d112","front":"Pemphigus résistant aux corticoïdes : que peut-on associer ?","back":"**Parfois** un **immunosuppresseur** : **azathioprine**, **cyclophosphamide** ou **ciclosporine**.","prio":"P3","sec":"s12"},{"id":"fc-d112-c7ff4f","poly":"dermato","fiche":"d112","front":"Pemphigus sous traitement : quel examen biologique suit l'activité de la maladie ?","back":"Le **titre des anticorps anti-SIC (IgG)** en **IFI**.","prio":"P2","sec":"s12"},{"id":"fc-d112-82cf7c","poly":"dermato","fiche":"d112","front":"Pemphigus sous traitement : quelle surveillance clinique prioritaire ?","back":"La **tolérance de la corticothérapie générale** (mortalité surtout **iatrogène**).","prio":"P2","sec":"s12"},{"id":"fc-d112-84e66f","poly":"dermato","fiche":"d112","front":"Sujet âgé sous corticoïdes pour DBAI : quel risque domine ?","back":"Une morbidité et une mortalité **iatrogènes majeures**.","prio":"P2","sec":"s13"},{"id":"fc-d113-41b5ea","poly":"dermato","fiche":"d113","front":"Anomalies vasculaires : quelles sont les deux grandes familles ?","back":"**Tumeurs vasculaires** (endothélium qui **prolifère**) ; **malformations vasculaires** (endothélium **quiescent**).","prio":"P1","sec":"s1"},{"id":"fc-d113-6726ae","poly":"dermato","fiche":"d113","front":"Tumeur vs malformation vasculaire : quelle question réflexe poser devant un enfant ?","back":"« Était-ce **déjà là à la naissance** ? » : tumeur **absente** à la naissance ; malformation **présente** dès la naissance.","prio":"P1","sec":"s1"},{"id":"fc-d113-6fcc54","poly":"dermato","fiche":"d113","front":"Tumeur vasculaire : quelle évolution ?","back":"**Croissance** puis **régression**, jusqu'à la disparition.","prio":"P1","sec":"s1"},{"id":"fc-d113-fa303d","poly":"dermato","fiche":"d113","front":"Malformation vasculaire : quelle évolution ?","back":"**Stabilité ou aggravation** ; elle **persiste**, ne régresse pas.","prio":"P1","sec":"s1"},{"id":"fc-d113-12d6f8","poly":"dermato","fiche":"d113","front":"Tumeurs vasculaires : quel est le principal représentant ?","back":"L'**hémangiome du nourrisson** (hémangiome infantile) ; tumeurs le plus souvent **capillaires**.","prio":"P2","sec":"s1"},{"id":"fc-d113-72b419","poly":"dermato","fiche":"d113","front":"Malformations vasculaires : citer les types ?","back":"**Capillaires** · **veineuses** · **lymphatiques** · **artérioveineuses** · **mixtes**.","prio":"P1","sec":"s1"},{"id":"fc-d113-5d281b","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : quelle place parmi les tumeurs de l'enfant et quelle prévalence ?","back":"Tumeur **la plus fréquente de l'enfant** ; prévalence **10 %**.","prio":"P1","sec":"s1"},{"id":"fc-d113-6b4d8c","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : quels autres noms ?","back":"Hémangiome **infantile** ou **immature**.","prio":"P3","sec":"s1"},{"id":"fc-d113-d864fc","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : définition ?","back":"Prolifération cutanée **bénigne** de cellules **endothéliales** vasculaires, **non congénitale**, d'origine **inconnue**.","prio":"P1","sec":"s1"},{"id":"fc-d113-8d27bc","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : sur quel terrain est-il plus fréquent ?","back":"**Filles** · **prématurés** · nouveau-nés de **faible poids de naissance**.","prio":"P1","sec":"s1"},{"id":"fc-d113-7a1d5b","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : quelles caractéristiques à l'examen physique ?","back":"Consistance **élastique** (non indurée) ; **pas de souffle** à l'auscultation ; **ni battement ni frémissement** à la palpation.","prio":"P1","sec":"s2"},{"id":"fc-d113-aaba3d","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : unique ou multiple ?","back":"En général **unique**, mais les formes **multiples** ne sont pas rares ; taille et siège variables.","prio":"P2","sec":"s2"},{"id":"fc-d113-08bf0a","poly":"dermato","fiche":"d113","front":"Hémangiome : citer les trois formes cliniques ?","back":"**Superficielle** · **profonde** (sous-cutanée) · **mixte**.","prio":"P2","sec":"s2"},{"id":"fc-d113-53d2ff","poly":"dermato","fiche":"d113","front":"Hémangiome superficiel : quel ancien nom ?","back":"« **Angiome tubéreux** ».","prio":"P3","sec":"s2"},{"id":"fc-d113-d8feb1","poly":"dermato","fiche":"d113","front":"Hémangiome superficiel : quel aspect ?","back":"Nodule ou plaque **rouge vif** en relief, surface tendue ou mamelonnée, dépressible.","prio":"P2","sec":"s2"},{"id":"fc-d113-3dfb60","poly":"dermato","fiche":"d113","front":"Hémangiome superficiel : que se passe-t-il à la pression ?","back":"Il **pâlit**, sans se vider ni disparaître complètement.","prio":"P2","sec":"s2"},{"id":"fc-d113-2e4660","poly":"dermato","fiche":"d113","front":"Hémangiome profond : quel aspect ?","back":"Tuméfaction **bleutée** ou couleur de peau normale ; parfois **télangiectasies arborescentes** en surface ; plus **élastique** que la forme superficielle.","prio":"P2","sec":"s2"},{"id":"fc-d113-241003","poly":"dermato","fiche":"d113","front":"Hémangiome profond peu spécifique : quel examen et quel résultat ?","back":"Imagerie : **écho-Doppler** → tumeur très vascularisée à **flux rapide**.","prio":"P2","sec":"s2"},{"id":"fc-d113-02e3a7","poly":"dermato","fiche":"d113","front":"Hémangiome mixte : définition ?","back":"Association d'une composante **superficielle** et d'une composante **profonde**.","prio":"P3","sec":"s2"},{"id":"fc-d113-415417","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : présent à la naissance ?","back":"**Non**, absent à la naissance.","prio":"P1","sec":"s2"},{"id":"fc-d113-502c6f","poly":"dermato","fiche":"d113","front":"Hémangiome : quelles lésions peuvent précéder son apparition ?","back":"Zone de **vasoconstriction** (macule plus pâle) ou de **vasodilatation** simulant un angiome plan.","prio":"P2","sec":"s2"},{"id":"fc-d113-12b8af","poly":"dermato","fiche":"d113","front":"Hémangiome : quand débute la phase de croissance et combien dure-t-elle ?","back":"Début dans les **premiers jours ou semaines** de vie ; croissance assez rapide les **5 à 6 premiers mois**.","prio":"P1","sec":"s2"},{"id":"fc-d113-9cb9e6","poly":"dermato","fiche":"d113","front":"Hémangiome : durée de la phase d'involution spontanée ?","back":"Variable : **2 à 10 ans**.","prio":"P1","sec":"s2"},{"id":"fc-d113-40ba48","poly":"dermato","fiche":"d113","front":"Hémangiome : comment se manifeste l'involution ?","back":"**Blanchiment** en surface puis **diminution progressive** de taille.","prio":"P2","sec":"s2"},{"id":"fc-d113-5dfea0","poly":"dermato","fiche":"d113","front":"Hémangiome : quelle proportion disparaît sans séquelle ?","back":"**La moitié** des cas.","prio":"P1","sec":"s2"},{"id":"fc-d113-294d95","poly":"dermato","fiche":"d113","front":"Hémangiome : quelles séquelles bénignes possibles après involution ?","back":"**Télangiectasies** ; **nodule fibro-adipeux** (peuvent justifier une prise en charge).","prio":"P2","sec":"s2"},{"id":"fc-d113-51f3fa","poly":"dermato","fiche":"d113","front":"Hémangiome : dans quelle localisation la régression est-elle volontiers incomplète ?","back":"Au **visage** : des séquelles persistent même si la composante vasculaire a régressé.","prio":"P2","sec":"s2"},{"id":"fc-d113-60f4f0","poly":"dermato","fiche":"d113","front":"Lésion vasculaire déjà présente à la naissance : quel diagnostic évoquer plutôt qu'un hémangiome ?","back":"Une **malformation vasculaire** (ou autre diagnostic différentiel).","prio":"P1","sec":"s2"},{"id":"fc-d113-66d265","poly":"dermato","fiche":"d113","front":"Hémangiome du nourrisson : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique** ; la **biopsie est généralement inutile**.","prio":"P1","sec":"s3"},{"id":"fc-d113-4485b0","poly":"dermato","fiche":"d113","front":"Malformations vasculaires et hémangiomes : l'histologie est-elle utile ?","back":"En général **non** : diagnostic **essentiellement clinique**.","prio":"P1","sec":"s3"},{"id":"fc-d113-1f0317","poly":"dermato","fiche":"d113","front":"Anomalie vasculaire : quand demander une échographie Doppler ?","back":"**Parfois**, en cas de **doute diagnostique** (renseigne sur le flux vasculaire).","prio":"P2","sec":"s3"},{"id":"fc-d113-db9440","poly":"dermato","fiche":"d113","front":"Hémangiome en extension vs malformation veineuse ou lymphatique : quel examen de 1re intention ?","back":"**Écho-Doppler** : flux **rapide** dans l'hémangiome, **absent** dans la malformation veineuse ou lymphatique.","prio":"P2","sec":"s3"},{"id":"fc-d113-cde65e","poly":"dermato","fiche":"d113","front":"Malformation veineuse : que montre l'écho-Doppler ?","back":"**Lacs veineux**, **pas de flux spontané**.","prio":"P2","sec":"s3"},{"id":"fc-d113-40af4b","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : que montre l'écho-Doppler ?","back":"Un **flux rapide**.","prio":"P2","sec":"s3"},{"id":"fc-d113-855562","poly":"dermato","fiche":"d113","front":"Hémangiome : quelle proportion se complique ?","back":"Une **minorité** : **10 %** (pronostic esthétique, fonctionnel, voire vital).","prio":"P1","sec":"s4"},{"id":"fc-d113-202db2","poly":"dermato","fiche":"d113","front":"Hémangiome : citer les localisations à risque ?","back":"**Œil** (orbito-palpébral) · **pointe du nez** · **lèvres** · **siège** · **plis** · **larynx** (sous-glottique).","prio":"P1","sec":"s4"},{"id":"fc-d113-61c8b3","poly":"dermato","fiche":"d113","front":"Hémangiome en localisation à risque : quelle conduite générale ?","back":"**Traitement précoce** + prise en charge **multidisciplinaire**.","prio":"P1","sec":"s4"},{"id":"fc-d113-cafd31","poly":"dermato","fiche":"d113","front":"Hémangiome : quelles localisations exposent surtout à l'ulcération ?","back":"**Siège** (fesses, vulve), **lèvres**, **plis** (cou) ; mais **tout** hémangiome peut s'ulcérer.","prio":"P1","sec":"s4"},{"id":"fc-d113-bafa4c","poly":"dermato","fiche":"d113","front":"Hémangiome ulcéré : quelles conséquences ?","back":"**Douleurs** (majorées par les mictions au siège) · **surinfection** · **saignements** · cicatrice **atrophique** inesthétique, voire défect séquellaire.","prio":"P2","sec":"s4"},{"id":"fc-d113-c43d22","poly":"dermato","fiche":"d113","front":"Hémangiome ulcéré de la lèvre : quelle gêne immédiate ?","back":"Gêne pour **boire au biberon**.","prio":"P3","sec":"s4"},{"id":"fc-d113-08eddb","poly":"dermato","fiche":"d113","front":"Hémangiome orbito-palpébral : quel risque fonctionnel principal ?","back":"**Amblyopie fonctionnelle**.","prio":"P1","sec":"s4"},{"id":"fc-d113-11e221","poly":"dermato","fiche":"d113","front":"Hémangiome orbito-palpébral : par quels mécanismes survient l'amblyopie ?","back":"**Fermeture précoce** de la fente palpébrale ; **astigmatisme** (globe comprimé, cornée déformée) ; **déplacement** du globe.","prio":"P2","sec":"s4"},{"id":"fc-d113-ecdaaa","poly":"dermato","fiche":"d113","front":"Hémangiome de la pointe du nez : quels risques ?","back":"**Préjudice esthétique** ; **déformations séquellaires des cartilages** du nez.","prio":"P2","sec":"s4"},{"id":"fc-d113-cf9976","poly":"dermato","fiche":"d113","front":"Hémangiome sous-glottique : quel risque ?","back":"Obstruction **laryngée ou trachéale** → **détresse respiratoire**.","prio":"P1","sec":"s4"},{"id":"fc-d113-90def4","poly":"dermato","fiche":"d113","front":"Hémangiome sous-glottique : quels signes d'appel ?","back":"**Stridor** ; **dyspnée laryngée**.","prio":"P1","sec":"s4"},{"id":"fc-d113-00b4fe","poly":"dermato","fiche":"d113","front":"Hémangiome sous-glottique : à quelles lésions peut-il être associé ?","back":"Hémangiome **cutané « en barbe »** ou hémangiome **muqueux** de la **lèvre** ou de la **langue** ; il peut aussi être **isolé**.","prio":"P1","sec":"s4"},{"id":"fc-d113-28db9c","poly":"dermato","fiche":"d113","front":"Hémangiome « en barbe » : quelles régions touche-t-il ?","back":"Atteinte **symétrique** des régions **mandibulaires**, **mentonnière**, **cervicales** et de la **lèvre inférieure**.","prio":"P2","sec":"s4"},{"id":"fc-d113-c6ea33","poly":"dermato","fiche":"d113","front":"Hémangiome « en barbe », de la lèvre ou de la langue : quel examen demander ?","back":"**Endoscopie ORL** (recherche d'un hémangiome **sous-glottique**, pour traiter tôt une atteinte laryngée).","prio":"P1","sec":"s4"},{"id":"fc-d113-eb244d","poly":"dermato","fiche":"d113","front":"Hémangiomatose miliaire : quel aspect ?","back":"Petits hémangiomes de **quelques mm à 1 cm**, peu nombreux ou **profus** sur tout le tégument ; forme **rare**.","prio":"P3","sec":"s4"},{"id":"fc-d113-a14e62","poly":"dermato","fiche":"d113","front":"Hémangiomatose miliaire : quelle association rechercher et quel risque ?","back":"Hémangiomes **viscéraux**, surtout **hépatiques** ; volumineux → **insuffisance cardiaque à haut débit**.","prio":"P2","sec":"s4"},{"id":"fc-d113-93d532","poly":"dermato","fiche":"d113","front":"Tumeur vasculaire congénitale, unique, indurée du visage ou d'un membre : quel diagnostic évoquer ?","back":"Une **tumeur maligne** richement vascularisée (**rhabdomyosarcome**, **fibrosarcome infantile**…).","prio":"P2","sec":"s5"},{"id":"fc-d113-f602fd","poly":"dermato","fiche":"d113","front":"Suspicion de tumeur maligne simulant un hémangiome : quelle conduite ?","back":"**Biopsie au moindre doute**.","prio":"P2","sec":"s5"},{"id":"fc-d113-1a560c","poly":"dermato","fiche":"d113","front":"Tumeur maligne vascularisée de l'enfant : quel élément peut faire croire à une tumeur vasculaire ?","back":"Une **teinte violacée** ; la tumeur déforme les reliefs.","prio":"P3","sec":"s5"},{"id":"fc-d113-7424cf","poly":"dermato","fiche":"d113","front":"Hémangiome profond sous-cutané : avec quelles malformations peut-on le confondre ?","back":"**Malformation veineuse** ou **lymphatique**.","prio":"P2","sec":"s5"},{"id":"fc-d113-9636d9","poly":"dermato","fiche":"d113","front":"Hémangiome superficiel au stade initial : quel diagnostic peut-il simuler ?","back":"Un **angiome plan**.","prio":"P2","sec":"s5"},{"id":"fc-d113-249568","poly":"dermato","fiche":"d113","front":"Hémangiome débutant vs angiome plan : comment trancher avec l'évolution ?","back":"L'hémangiome **grossit puis involue** ; l'angiome plan **persiste**.","prio":"P2","sec":"s5"},{"id":"fc-d113-7e2e42","poly":"dermato","fiche":"d113","front":"Lésion vasculaire « indurée » et « congénitale » : pourquoi est-ce suspect ?","back":"C'est l'**inverse** de l'hémangiome typique (élastique, absent à la naissance) → évoquer une **tumeur maligne**.","prio":"P2","sec":"s5"},{"id":"fc-d113-1039c9","poly":"dermato","fiche":"d113","front":"Hémangiome typique hors localisation à risque : quel traitement ?","back":"**Aucun traitement** dans la majorité des cas ; il peut régresser complètement seul ; **surveillance**.","prio":"P1","sec":"s6"},{"id":"fc-d113-cb77fc","poly":"dermato","fiche":"d113","front":"Hémangiome typique : que vérifier avant de choisir l'abstention ?","back":"L'**absence de localisation à risque** et d'évolution **volumineuse**.","prio":"P1","sec":"s6"},{"id":"fc-d113-f0e428","poly":"dermato","fiche":"d113","front":"Hémangiome : quel intérêt diagnostique de l'histoire naturelle ?","back":"Son profil **stéréotypé** (absent à la naissance, croissance, involution) est en soi un **argument diagnostique**.","prio":"P2","sec":"s6"},{"id":"fc-d113-ed5d41","poly":"dermato","fiche":"d113","front":"Hémangiome typique : citer les deux erreurs de prise en charge ?","back":"**Traiter tous** les hémangiomes (seuls **10 %** se compliquent) ; **biopsier** un hémangiome typique.","prio":"P1","sec":"s6"},{"id":"fc-d113-741674","poly":"dermato","fiche":"d113","front":"Hémangiome : quelles sont les indications de traitement ?","back":"Hémangiome **volumineux évolutif** · menace du **pronostic fonctionnel ou vital** · risque de **séquelles esthétiques**.","prio":"P1","sec":"s7"},{"id":"fc-d113-bdd3ba","poly":"dermato","fiche":"d113","front":"Hémangiome à traiter : quel traitement de 1re intention ?","back":"**Propranolol per os** (bêtabloquant).","prio":"P1","sec":"s7"},{"id":"fc-d113-3c4b7f","poly":"dermato","fiche":"d113","front":"Propranolol dans l'hémangiome : dose et durée données par le Collège ?","back":"**Non précisées** dans le Collège (seules la molécule et la **voie orale** sont données).","prio":"P3","sec":"s7"},{"id":"fc-d113-a5f5b5","poly":"dermato","fiche":"d113","front":"Hémangiome en localisation à risque : quel piège éviter ?","back":"**Attendre l'involution spontanée** : ces formes demandent un **traitement précoce**.","prio":"P1","sec":"s7"},{"id":"fc-d113-3eaadd","poly":"dermato","fiche":"d113","front":"Cicatrice atrophique après ulcération d'hémangiome : quelle prise en charge possible ?","back":"Une **intervention réparatrice** plus tard.","prio":"P3","sec":"s7"},{"id":"fc-d113-32705c","poly":"dermato","fiche":"d113","front":"Hémangiome sous-glottique : quel traitement retenir selon la règle générale ?","back":"**Traitement précoce** ; règle générale : **propranolol per os** en 1re intention (non détaillé pour la forme laryngée).","prio":"P2","sec":"s8"},{"id":"fc-d113-334977","poly":"dermato","fiche":"d113","front":"Hémangiome sous-glottique : après le diagnostic, quelle organisation de la prise en charge ?","back":"Prise en charge **multidisciplinaire** (localisation à risque).","prio":"P2","sec":"s8"},{"id":"fc-d113-3d6cfa","poly":"dermato","fiche":"d113","front":"Hémangiome « en barbe » : quel piège ?","back":"Se contenter de l'aspect cutané **sans explorer le larynx**.","prio":"P1","sec":"s8"},{"id":"fc-d113-d92af9","poly":"dermato","fiche":"d113","front":"Malformations vasculaires : présentes à la naissance ?","back":"**Oui** ; elles **persistent** (stabilité ou aggravation), sans régression.","prio":"P1","sec":"s10"},{"id":"fc-d113-23075a","poly":"dermato","fiche":"d113","front":"Malformations vasculaires : quels sont les deux groupes selon le flux ?","back":"À **flux lent** (capillaire, veineux, lymphatique…) ; **artérioveineuses** à **flux rapide**.","prio":"P2","sec":"s10"},{"id":"fc-d113-fe871e","poly":"dermato","fiche":"d113","front":"Malformations capillaires (angiomes plans) : comment évoluent-elles ?","back":"Restent **visibles** et **évoluent peu**.","prio":"P3","sec":"s10"},{"id":"fc-d113-5d5ced","poly":"dermato","fiche":"d113","front":"Malformations vasculaires non capillaires : comment peuvent-elles se révéler ?","back":"Inaperçues au début, puis révélation **progressive** ou lors d'une **poussée**.","prio":"P3","sec":"s10"},{"id":"fc-d113-91a73d","poly":"dermato","fiche":"d113","front":"Malformations vasculaires : quels facteurs déclenchent les poussées ?","back":"**Traumatisme** (y compris chirurgical) · **infection** · **puberté** · **grossesse**.","prio":"P2","sec":"s10"},{"id":"fc-d113-ef561c","poly":"dermato","fiche":"d113","front":"Malformation vasculaire hors malformation capillaire : quelle prise en charge ?","back":"Prise en charge **multidisciplinaire**.","prio":"P1","sec":"s10"},{"id":"fc-d113-6ee0ca","poly":"dermato","fiche":"d113","front":"Hémangiome vs malformation : quel moyen mnémotechnique ?","back":"Hémangiome = « **arrive après, s'en va** » ; malformation = « **déjà là, reste là** ».","prio":"P2","sec":"s10"},{"id":"fc-d113-52db1f","poly":"dermato","fiche":"d113","front":"Angiome plan : quelle anomalie vasculaire est-ce ?","back":"Une **malformation capillaire**.","prio":"P2","sec":"s11"},{"id":"fc-d113-626d57","poly":"dermato","fiche":"d113","front":"Angiome plan : quel aspect ?","back":"Tache rouge **congénitale**, **plane**, s'effaçant plus ou moins à la pression, siège quelconque.","prio":"P2","sec":"s11"},{"id":"fc-d113-647efc","poly":"dermato","fiche":"d113","front":"Angiome plan : que retrouve l'examen (palpation, auscultation, température) ?","back":"**Ni souffle, ni frémissement, ni battement** ; **même température** que la peau normale.","prio":"P2","sec":"s11"},{"id":"fc-d113-99e6d7","poly":"dermato","fiche":"d113","front":"Angiome plan : est-il associé à un angiome viscéral ?","back":"En règle **isolé**, sans angiome viscéral (notamment **cérébral**), avec des **exceptions**.","prio":"P3","sec":"s11"},{"id":"fc-d113-e7a170","poly":"dermato","fiche":"d113","front":"Angiome plan : quelle évolution ?","back":"**Persiste**, sans disparition spontanée ; surface qui s'accroît **en proportion de la croissance** de l'enfant.","prio":"P2","sec":"s11"},{"id":"fc-d113-d199cc","poly":"dermato","fiche":"d113","front":"Angiome plan : quelle complication évolutive locale possible ?","back":"**Hypertrophie progressive des parties molles** de la zone (visage, segment de membre).","prio":"P3","sec":"s11"},{"id":"fc-d113-738363","poly":"dermato","fiche":"d113","front":"Tache angiomateuse physiologique du nouveau-né : quel autre nom ?","back":"« **Nævus flammeus** » de la glabelle.","prio":"P3","sec":"s11"},{"id":"fc-d113-367526","poly":"dermato","fiche":"d113","front":"Tache angiomateuse physiologique : quels caractères la distinguent d'un angiome plan ?","back":"Très fréquente ; **plus pâle (rose saumon)** ; glabelle, front, paupières supérieures, occiput ; **pâlit avec le temps**.","prio":"P2","sec":"s11"},{"id":"fc-d113-296a6a","poly":"dermato","fiche":"d113","front":"Tache angiomateuse physiologique : où persiste-t-elle ?","back":"Sur la **nuque** et l'**occiput**.","prio":"P3","sec":"s11"},{"id":"fc-d113-4f86ce","poly":"dermato","fiche":"d113","front":"Angiome plan : citer les trois diagnostics différentiels ?","back":"**Tache angiomateuse physiologique** · **hémangiome infantile au stade précoce** · **malformation lymphatique ou artérioveineuse quiescente**.","prio":"P2","sec":"s11"},{"id":"fc-d113-1800d7","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse débutante simulant un angiome plan : comment la distinguer ?","back":"Elle est **plus chaude**, **extensive** et **battante**.","prio":"P2","sec":"s11"},{"id":"fc-d113-efb678","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quel autre nom ?","back":"« **Angiome veineux** ».","prio":"P3","sec":"s12"},{"id":"fc-d113-b4ee17","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quel aspect clinique ?","back":"Tuméfactions **bleutées** sous-cutanées ou lacis de **veines dilatées** superficielles (comme des varices).","prio":"P2","sec":"s12"},{"id":"fc-d113-9760c0","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quelles caractéristiques à la palpation ?","back":"**Molle, dépressible**, se **vide** à la pression ou à la surélévation ; **ni chaleur, ni battement, ni souffle**.","prio":"P2","sec":"s12"},{"id":"fc-d113-496d78","poly":"dermato","fiche":"d113","front":"Malformation veineuse : dans quelles circonstances gonfle-t-elle ?","back":"Position **déclive**, **effort**, **cris** (visage).","prio":"P3","sec":"s12"},{"id":"fc-d113-0538f9","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quelles localisations ?","back":"**Extrémités des membres**, **visage** ; extension **profonde** possible (loges musculaires).","prio":"P3","sec":"s12"},{"id":"fc-d113-82d745","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : quels signes à la palpation et à l'auscultation ?","back":"Palpation : **frémissement (thrill)** ; auscultation : **souffle**.","prio":"P2","sec":"s12"},{"id":"fc-d113-77511a","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : sièges les plus fréquents ?","back":"**Oreilles** · **cuir chevelu** · **extrémités des membres**.","prio":"P3","sec":"s12"},{"id":"fc-d113-c8f5a9","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : comment évolue-t-elle cliniquement ?","back":"D'abord **tache rouge plane** (simule un angiome plan), puis **tuméfaction** ou déformation localisée.","prio":"P3","sec":"s12"},{"id":"fc-d113-3b769c","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quelle évolution au cours de la vie ?","back":"**Aggravation lente**.","prio":"P3","sec":"s12"},{"id":"fc-d113-d3f32d","poly":"dermato","fiche":"d113","front":"Malformation veineuse : quelle complication aiguë fréquente ?","back":"Épisodes de **(micro)thrombose** : nodules **douloureux et inflammatoires** régressant en quelques jours.","prio":"P2","sec":"s12"},{"id":"fc-d113-b772b9","poly":"dermato","fiche":"d113","front":"Malformation veineuse : que deviennent les thromboses ?","back":"Elles se **calcifient** : **phlébolithes** palpables et visibles à la **radiographie**.","prio":"P2","sec":"s12"},{"id":"fc-d113-833a9d","poly":"dermato","fiche":"d113","front":"Malformation veineuse très volumineuse : quelle complication dépister et avec quels examens ?","back":"**Coagulation intravasculaire localisée** : **plaquettes**, **fibrinogène**, **D-dimères** (surtout avant une **chirurgie**).","prio":"P2","sec":"s12"},{"id":"fc-d113-c21b2f","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : quels facteurs déclenchent les poussées ?","back":"**Spontanées** ou **traumatisme**, **tentative de geste thérapeutique**, **puberté**, **grossesse**.","prio":"P2","sec":"s12"},{"id":"fc-d113-0de860","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : quelles complications ?","back":"**Hémorragie** · **nécrose ischémique** · **invasion locorégionale** · **récidive** après traitement · **insuffisance cardiaque à haut débit**.","prio":"P2","sec":"s12"},{"id":"fc-d113-92257f","poly":"dermato","fiche":"d113","front":"Malformation veineuse ou artérioveineuse : comment pose-t-on le diagnostic ?","back":"Diagnostic **essentiellement clinique** ; **écho-Doppler** parfois en cas de doute.","prio":"P1","sec":"s13"},{"id":"fc-d113-e4be2b","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : sur quels éléments repose le diagnostic ?","back":"Palpation : **thrill** ; auscultation : **souffle** ; écho-Doppler : **flux rapide** ; localisation (**oreilles**, **cuir chevelu**, **extrémités**).","prio":"P2","sec":"s13"},{"id":"fc-d113-3e5fb3","poly":"dermato","fiche":"d113","front":"Malformation artérioveineuse : quels pièges thérapeutiques ?","back":"Elle **récidive volontiers** après traitement ; une **tentative de geste** peut déclencher une poussée.","prio":"P2","sec":"s13"},{"id":"fc-d113-8f3a79","poly":"dermato","fiche":"d113","front":"Malformation vasculaire : quel piège sur l'évolution ?","back":"**Attendre une régression** : elle est présente à la naissance et **persiste**.","prio":"P1","sec":"s13"},{"id":"fc-d113-56853c","poly":"dermato","fiche":"d113","front":"Citer les angiomes capillaires cutanés acquis ?","back":"**Angiomes stellaires** ; angiomes liés à l'âge : **taches rubis**, **lacs veineux des lèvres**.","prio":"P2","sec":"s14"},{"id":"fc-d113-8bcddf","poly":"dermato","fiche":"d113","front":"Angiome stellaire : quel aspect ?","back":"Ectasie centrée par un **capillaire** d'où rayonne une **arborescence de télangiectasies** ; les plus gros parfois **pulsatiles**.","prio":"P2","sec":"s14"},{"id":"fc-d113-017873","poly":"dermato","fiche":"d113","front":"Angiome stellaire : que montre la vitropression ?","back":"L'arborescence **disparaît**, le **point central persiste** ; recoloration **à partir du centre**.","prio":"P2","sec":"s14"},{"id":"fc-d113-4cd1cc","poly":"dermato","fiche":"d113","front":"Angiome stellaire : localisations ?","back":"**Surtout** le **visage** (lèvres, nez, joues) et les **extrémités** (doigts).","prio":"P3","sec":"s14"},{"id":"fc-d113-575c0f","poly":"dermato","fiche":"d113","front":"Angiomes stellaires nombreux : quelle pathologie évoquer ?","back":"Une **insuffisance hépatocellulaire** (signe d'appel possible).","prio":"P1","sec":"s14"},{"id":"fc-d113-9f849d","poly":"dermato","fiche":"d113","front":"Angiomes stellaires : chez qui sont-ils fréquents sans signification pathologique ?","back":"**Femme adulte** et **enfant**.","prio":"P2","sec":"s14"},{"id":"fc-d113-7ac2f6","poly":"dermato","fiche":"d113","front":"Angiomes capillaires liés à l'âge : quelle signification ?","back":"Apparition **tardive**, origine inconnue, **sans signification pathologique**, en général asymptomatiques.","prio":"P2","sec":"s14"},{"id":"fc-d113-f49c14","poly":"dermato","fiche":"d113","front":"Taches rubis : quel aspect et quelle localisation ?","back":"Petits angiomes **punctiformes rouge vif**, souvent sur zones **couvertes** (tronc).","prio":"P3","sec":"s14"},{"id":"fc-d113-0d0c4f","poly":"dermato","fiche":"d113","front":"Angiomes des lèvres (« lacs veineux ») : quelle couleur ?","back":"**Bleu violacé**.","prio":"P3","sec":"s14"},{"id":"fc-d113-ea3e58","poly":"dermato","fiche":"d113","front":"Angiome capillaire thrombosé : quel aspect et pourquoi ?","back":"Il devient **noir** (**hémosidérine**).","prio":"P2","sec":"s14"},{"id":"fc-d113-118dc8","poly":"dermato","fiche":"d113","front":"Angiome capillaire devenu noir : quel diagnostic différentiel faire ?","back":"Une lésion **mélanocytaire** : **nævus**, **mélanome**.","prio":"P1","sec":"s14"},{"id":"fc-d114-6c3109","poly":"dermato","fiche":"d114","front":"Exanthème : définition ?","back":"Érythème d'apparition **brutale** et **transitoire** ; intense ou non, diffus ou localisé, isolé ou associé à d'autres symptômes.","prio":"P1","sec":"s1"},{"id":"fc-d114-4be9fa","poly":"dermato","fiche":"d114","front":"Exanthème : comment appelle-t-on l'atteinte muqueuse associée possible ?","back":"**Énanthème**.","prio":"P2","sec":"s1"},{"id":"fc-d114-96371a","poly":"dermato","fiche":"d114","front":"Exanthème : est-ce toujours bénin ?","back":"Non : **bénin** ou **potentiellement grave**.","prio":"P2","sec":"s1"},{"id":"fc-d114-3a571c","poly":"dermato","fiche":"d114","front":"Érythrodermie : définition ?","back":"Érythème **confluant** + **desquamation** sur l'ensemble des téguments (**> 90 %** de la surface corporelle), évoluant depuis **au moins 6 semaines**.","prio":"P1","sec":"s1"},{"id":"fc-d114-7574c5","poly":"dermato","fiche":"d114","front":"Érythrodermie : fréquence et mode de diagnostic ?","back":"Syndrome **rare**, de diagnostic **clinique**, aux causes multiples.","prio":"P2","sec":"s1"},{"id":"fc-d114-9d1dcd","poly":"dermato","fiche":"d114","front":"Érythrodermie : quel degré d'urgence ?","back":"**Urgence dermatologique** : prise en charge thérapeutique et étiologique **immédiate**.","prio":"P1","sec":"s1"},{"id":"fc-d114-7b32b1","poly":"dermato","fiche":"d114","front":"Érythrodermie : piège sur la durée dans le Collège ?","back":"Texte du chapitre : « depuis **au moins 6 semaines** » ; tableau d'objectifs de l'item : « **< 6 semaines** ».","prio":"P3","sec":"s1"},{"id":"fc-d114-b18c18","poly":"dermato","fiche":"d114","front":"Exanthème : quelles sont les deux grandes causes ?","back":"**Infectieuses** (virus ou bactéries) et **médicamenteuses**.","prio":"P1","sec":"s1"},{"id":"fc-d114-6db79c","poly":"dermato","fiche":"d114","front":"Exanthème : principale cause chez l'enfant comme chez l'adulte ?","back":"L'**origine virale**.","prio":"P1","sec":"s1"},{"id":"fc-d114-634ade","poly":"dermato","fiche":"d114","front":"Exanthème infectieux de l'adulte : quelles infections citer notamment ?","back":"Des **IST** : **syphilis**, **VIH**.","prio":"P2","sec":"s1"},{"id":"fc-d114-4905d9","poly":"dermato","fiche":"d114","front":"Exanthème : quelles sont les 3 étapes de la démarche ?","back":"**Anamnèse** (épidémie, contage, médicament) → **analyse de l'éruption** (type) → **signes extracutanés et biologiques**.","prio":"P2","sec":"s2"},{"id":"fc-d114-b684f1","poly":"dermato","fiche":"d114","front":"Exanthème roséoliforme : aspect des lésions ?","back":"Petites **macules rosées**, pâles, bien **séparées** les unes des autres.","prio":"P2","sec":"s2"},{"id":"fc-d114-a8373c","poly":"dermato","fiche":"d114","front":"Exanthème morbilliforme : aspect des lésions ?","back":"**Maculo-papules** rouges pouvant confluer en plaques, avec des **espaces de peau saine** persistants.","prio":"P2","sec":"s2"},{"id":"fc-d114-37c676","poly":"dermato","fiche":"d114","front":"Exanthème scarlatiniforme : aspect des lésions ?","back":"**Nappes diffuses** rouge vif, granitées, chaudes ; **aucun intervalle** de peau saine ; accentuation aux **plis** ; desquamation secondaire possible.","prio":"P1","sec":"s2"},{"id":"fc-d114-21eb5c","poly":"dermato","fiche":"d114","front":"Exanthème roséoliforme : synonyme ?","back":"**Rubéoliforme**.","prio":"P3","sec":"s2"},{"id":"fc-d114-ca850a","poly":"dermato","fiche":"d114","front":"Exanthème : quels signes associés orientent vers une origine virale ?","back":"**Fièvre** · **syndrome grippal** · **énanthème** · **polyadénopathie**.","prio":"P1","sec":"s2"},{"id":"fc-d114-40fb45","poly":"dermato","fiche":"d114","front":"Exanthème : quels signes associés orientent vers une origine médicamenteuse ?","back":"**Prurit** · éruption **polymorphe** · **hyperéosinophilie** sanguine.","prio":"P1","sec":"s2"},{"id":"fc-d114-c85cb1","poly":"dermato","fiche":"d114","front":"Exanthème fébrile de l'enfant : cause la plus fréquente ?","back":"**Virale** le plus souvent ; possiblement bactérienne, inflammatoire ou médicamenteuse.","prio":"P1","sec":"s2"},{"id":"fc-d114-75cdc2","poly":"dermato","fiche":"d114","front":"Exanthème de l'adulte : quelles 3 causes évoquer ?","back":"**VIH** · **syphilis** · **médicaments** (toxidermie).","prio":"P1","sec":"s2"},{"id":"fc-d114-3a88ce","poly":"dermato","fiche":"d114","front":"Exanthème roséoliforme : principales causes ?","back":"**Exanthème subit** · **rubéole** · **primo-infection VIH** · **syphilis secondaire**.","prio":"P2","sec":"s2"},{"id":"fc-d114-399fe5","poly":"dermato","fiche":"d114","front":"Exanthème morbilliforme : principales causes ?","back":"**Rougeole** · **mégalérythème épidémique** · **mononucléose infectieuse**.","prio":"P2","sec":"s2"},{"id":"fc-d114-336b92","poly":"dermato","fiche":"d114","front":"Exanthème scarlatiniforme : principales causes ?","back":"**Scarlatine** · **syndrome de Kawasaki**.","prio":"P2","sec":"s2"},{"id":"fc-d114-144c21","poly":"dermato","fiche":"d114","front":"Exanthème de l'enfant : examens complémentaires ?","back":"**Aucun examen indispensable**, sauf suspicion de scarlatine ou de Kawasaki.","prio":"P2","sec":"s3"},{"id":"fc-d114-d3f50c","poly":"dermato","fiche":"d114","front":"Suspicion de scarlatine chez l'enfant : quels examens ?","back":"**NFS** + **prélèvement de gorge**.","prio":"P2","sec":"s3"},{"id":"fc-d114-874c3c","poly":"dermato","fiche":"d114","front":"Suspicion de syndrome de Kawasaki : quels examens ?","back":"**NFS**, **plaquettes**, **échographie cardiaque**.","prio":"P2","sec":"s3"},{"id":"fc-d114-aa47b8","poly":"dermato","fiche":"d114","front":"Exanthème de l'adulte sans cause évidente : quels examens ?","back":"**NFS**, tests hépatiques, sérodiagnostic de **MNI**, test **tréponémique**, **charge virale VIH**, sérologie VIH combinée (**Ag p24-Ac**).","prio":"P2","sec":"s3"},{"id":"fc-d114-9efb0b","poly":"dermato","fiche":"d114","front":"Exanthème chez la femme enceinte : quelles sérologies ?","back":"**Toxoplasmose, rubéole, CMV, parvovirus B19, syphilis**, selon le statut sérologique de début de grossesse.","prio":"P2","sec":"s3"},{"id":"fc-d114-1ba0d7","poly":"dermato","fiche":"d114","front":"Femme enceinte : 4 principaux exanthèmes à risque ?","back":"**Rubéole** (mort fœtale, malformations) · **parvovirus B19** (anasarque fœtale) · **toxoplasmose** · **syphilis** (congénitale).","prio":"P2","sec":"s3"},{"id":"fc-d114-11dbd3","poly":"dermato","fiche":"d114","front":"Exanthème subit (roséole infantile) : cause ?","back":"Primo-infection à **HHV6** (human herpesvirus 6).","prio":"P1","sec":"s4"},{"id":"fc-d114-1e53d0","poly":"dermato","fiche":"d114","front":"Exanthème subit : terrain ?","back":"**Nourrisson de 6 à 18 mois**.","prio":"P1","sec":"s4"},{"id":"fc-d114-579fe4","poly":"dermato","fiche":"d114","front":"Exanthème subit : tableau clinique typique ?","back":"Souvent asymptomatique ; **fièvre 39-40 °C isolée 48-72 h**, puis exanthème surtout du **tronc** en **une seule poussée**.","prio":"P1","sec":"s4"},{"id":"fc-d114-6c2bc0","poly":"dermato","fiche":"d114","front":"Exanthème subit : complications (rares) ?","back":"**Convulsions fébriles**, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique.","prio":"P2","sec":"s4"},{"id":"fc-d114-c08fce","poly":"dermato","fiche":"d114","front":"Nourrisson : éruption roséoliforme après 3 jours de fièvre isolée, quel diagnostic évoquer ?","back":"**Exanthème subit** (roséole infantile).","prio":"P1","sec":"s4"},{"id":"fc-d114-6823b6","poly":"dermato","fiche":"d114","front":"Rubéole : âge de survenue ?","back":"Entre **15 et 25 ans**.","prio":"P2","sec":"s4"},{"id":"fc-d114-f4fbd3","poly":"dermato","fiche":"d114","front":"Rubéole : durée d'incubation ?","back":"**3 semaines**.","prio":"P2","sec":"s4"},{"id":"fc-d114-14dcd4","poly":"dermato","fiche":"d114","front":"Rubéole : période de contagiosité ?","back":"De **7 jours avant** à **14 jours après** le début de l'éruption.","prio":"P2","sec":"s4"},{"id":"fc-d114-eff5c0","poly":"dermato","fiche":"d114","front":"Rubéole : signes cliniques ?","back":"Exanthème **discret** (2 à 4 jours) ; **arthralgies** et **conjonctivite**.","prio":"P2","sec":"s4"},{"id":"fc-d114-cde63c","poly":"dermato","fiche":"d114","front":"Rubéole : quel risque chez la femme enceinte non immunisée ?","back":"**Mort fœtale** ou **malformations** neurologiques sensorielles.","prio":"P1","sec":"s4"},{"id":"fc-d114-e0d2a9","poly":"dermato","fiche":"d114","front":"Rubéole : conduite à tenir pour la collectivité ?","back":"**Pas d'éviction** ; **informer** le personnel, les parents et la femme enceinte.","prio":"P2","sec":"s4"},{"id":"fc-d114-439611","poly":"dermato","fiche":"d114","front":"Rougeole : quelle association doit la faire évoquer ?","back":"**Catarrhe oculo-nasal** + **conjonctivite** + **exanthème fébrile**, chez l'enfant comme chez l'adulte.","prio":"P1","sec":"s5"},{"id":"fc-d114-d9042a","poly":"dermato","fiche":"d114","front":"Rougeole : agent ?","back":"**Morbillivirus** (paramyxovirus).","prio":"P2","sec":"s5"},{"id":"fc-d114-2e3a89","poly":"dermato","fiche":"d114","front":"Rougeole : durée d'incubation ?","back":"**10-12 jours**.","prio":"P2","sec":"s5"},{"id":"fc-d114-791b07","poly":"dermato","fiche":"d114","front":"Rougeole : signe de Köplick, de quoi s'agit-il ?","back":"Semis de **papules** à la **face interne des joues**, en phase pré-éruptive.","prio":"P1","sec":"s5"},{"id":"fc-d114-25f91d","poly":"dermato","fiche":"d114","front":"Rougeole : signes de la phase pré-éruptive ?","back":"**Catarrhe oculo-nasal**, **fièvre** élevée (39-40 °C), **signe de Köplick**, **conjonctivite**.","prio":"P2","sec":"s5"},{"id":"fc-d114-bb58f7","poly":"dermato","fiche":"d114","front":"Rougeole : où débute l'éruption et comment s'étend-elle ?","back":"**Derrière les oreilles**, puis à tout le corps en **une seule poussée**.","prio":"P1","sec":"s5"},{"id":"fc-d114-1d070d","poly":"dermato","fiche":"d114","front":"Rougeole : complications ?","back":"**Pneumopathie** ; hépatite, pancréatite ; **encéphalite (grave)** ; kératite et **cécité**.","prio":"P1","sec":"s5"},{"id":"fc-d114-2415a3","poly":"dermato","fiche":"d114","front":"Mégalérythème épidémique : agent ?","back":"**Parvovirus B19**.","prio":"P2","sec":"s5"},{"id":"fc-d114-d56dbd","poly":"dermato","fiche":"d114","front":"Mégalérythème épidémique : terrain et incubation ?","back":"Enfant de **5 à 10 ans** ; incubation **14 jours**.","prio":"P2","sec":"s5"},{"id":"fc-d114-b4e24b","poly":"dermato","fiche":"d114","front":"Mégalérythème épidémique : quand est-il contagieux ?","back":"Contagiosité **limitée à la phase pré-éruptive**.","prio":"P2","sec":"s5"},{"id":"fc-d114-950985","poly":"dermato","fiche":"d114","front":"Mégalérythème épidémique : intensité de la fièvre ?","back":"Fièvre **modérée**.","prio":"P3","sec":"s5"},{"id":"fc-d114-f6700b","poly":"dermato","fiche":"d114","front":"Mégalérythème épidémique : aspect de l'éruption ?","back":"Érythème et **œdème des joues**, puis érythème du tronc à bords émiettés ; érythème « **en gants et chaussettes** » ; arthralgies.","prio":"P1","sec":"s5"},{"id":"fc-d114-522334","poly":"dermato","fiche":"d114","front":"Mégalérythème : aspect du visage et du tronc décrit en images ?","back":"Visage « **souffleté** » ; exanthème du tronc **figuré en guirlande**.","prio":"P3","sec":"s5"},{"id":"fc-d114-2dae09","poly":"dermato","fiche":"d114","front":"Mégalérythème : chez qui surviennent surtout les complications ?","back":"**Immunodéprimé**, patient avec **anémie chronique**, **femme enceinte**.","prio":"P2","sec":"s5"},{"id":"fc-d114-dfb665","poly":"dermato","fiche":"d114","front":"Parvovirus B19 et grossesse : est-il tératogène ?","back":"**Non** ; mais infection au **2ᵉ trimestre** : **anasarque fœtale**, myocardite, anémie fœtale.","prio":"P1","sec":"s5"},{"id":"fc-d114-e6a95b","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : agent et terrain ?","back":"**Epstein-Barr virus** (EBV) ; **adolescent**.","prio":"P2","sec":"s5"},{"id":"fc-d114-a10f2d","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : durée d'incubation ?","back":"**4 à 6 semaines**.","prio":"P2","sec":"s5"},{"id":"fc-d114-72c080","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : période de contagiosité ?","back":"Maximale à la **phase aiguë** ; peut aller jusqu'à **6 mois**.","prio":"P3","sec":"s5"},{"id":"fc-d114-7a478b","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : signes généraux ?","back":"Fièvre et **asthénie** importantes ; **polyadénopathie** ; **splénomégalie**.","prio":"P2","sec":"s5"},{"id":"fc-d114-76b0ac","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : fréquence de l'exanthème ?","back":"**Inconstant (5-10 %)**, sauf si une **pénicilline A** est prescrite.","prio":"P1","sec":"s5"},{"id":"fc-d114-0487ce","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : biologie ?","back":"**Lymphocytose** élevée, lymphocytes **hyperbasophiles**.","prio":"P2","sec":"s5"},{"id":"fc-d114-5c4de4","poly":"dermato","fiche":"d114","front":"Mononucléose infectieuse : complications (rares) ?","back":"Hépatite, méningo-encéphalite, **rupture splénique**, agranulocytose.","prio":"P2","sec":"s5"},{"id":"fc-d114-e4754f","poly":"dermato","fiche":"d114","front":"Rougeole : mesures autour du cas ?","back":"**Déclaration obligatoire** ; éviction jusqu'à **5 jours** après le début de l'éruption ; informer personnel et parents.","prio":"P1","sec":"s5"},{"id":"fc-d114-5784de","poly":"dermato","fiche":"d114","front":"Exanthème morbilliforme : autres causes que les 3 viroses classiques ?","back":"**Primo-infection VIH** · **toxidermie** (β-lactamines, sulfamides, anti-comitiaux…) · **syndrome de Kawasaki**.","prio":"P2","sec":"s5"},{"id":"fc-d114-3034e8","poly":"dermato","fiche":"d114","front":"Mononucléose traitée par ampicilline : quel piège devant une éruption ?","back":"« **Rash à l'ampicilline** » : complication classique, à **ne pas confondre** avec une toxidermie aux pénicillines.","prio":"P2","sec":"s5"},{"id":"fc-d114-e78573","poly":"dermato","fiche":"d114","front":"Scarlatine : agent ?","back":"**Streptocoque du groupe A** sécréteur d'exotoxines.","prio":"P1","sec":"s6"},{"id":"fc-d114-86f30f","poly":"dermato","fiche":"d114","front":"Scarlatine : terrain ?","back":"Enfant de **5 à 10 ans**.","prio":"P2","sec":"s6"},{"id":"fc-d114-c4748b","poly":"dermato","fiche":"d114","front":"Scarlatine : incubation, contagiosité, transmission ?","back":"Incubation **2 à 4 j** ; contagiosité **2 à 3 semaines**, persistant **48 h** après le début du traitement ; voie **aérienne**.","prio":"P2","sec":"s6"},{"id":"fc-d114-7c8a51","poly":"dermato","fiche":"d114","front":"Scarlatine : mode de début ?","back":"**Brutal** : fièvre 39-40 °C, douleurs pharyngées, céphalées, **angine rouge**, adénopathies sous-maxillaires.","prio":"P1","sec":"s6"},{"id":"fc-d114-5ea269","poly":"dermato","fiche":"d114","front":"Scarlatine : signes cutanéo-muqueux ?","back":"Éruption surtout aux **grands plis** ; dépapillation linguale en « V », langue **framboisée** ; desquamation fine ou en lambeaux.","prio":"P2","sec":"s6"},{"id":"fc-d114-3a9c7b","poly":"dermato","fiche":"d114","front":"Scarlatine : examen diagnostique ?","back":"**Prélèvement de gorge**.","prio":"P1","sec":"s6"},{"id":"fc-d114-f20be0","poly":"dermato","fiche":"d114","front":"Scarlatine : complications post-streptococciques ?","back":"**Glomérulonéphrite** · **rhumatisme articulaire aigu**.","prio":"P1","sec":"s6"},{"id":"fc-d114-67280d","poly":"dermato","fiche":"d114","front":"Scarlatine streptococcique : traitement et éviction ?","back":"**Amoxicilline** ; éviction jusqu'à **48 h** après le début du traitement.","prio":"P1","sec":"s6"},{"id":"fc-d114-833406","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : agent ?","back":"**Staphylococcus aureus** sécréteur d'entérotoxines ou de **TSST1**.","prio":"P2","sec":"s6"},{"id":"fc-d114-05fa4c","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : terrain ?","back":"**Nouveau-né**, nourrisson, jeune enfant ou **adulte immunodéprimé**.","prio":"P2","sec":"s6"},{"id":"fc-d114-8f22a1","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : durée d'incubation ?","back":"**48 heures**.","prio":"P3","sec":"s6"},{"id":"fc-d114-e4ef3c","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : atteinte cutanée ?","back":"Exanthème des **grands plis** et **péri-orificiel**, puis **décollement bulleux** ; **pas d'angine**.","prio":"P1","sec":"s6"},{"id":"fc-d114-569ea7","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : quel contexte infectieux évoquer chez le nouveau-né et chez le jeune enfant ?","back":"Nouveau-né avec **infection du cordon** ; jeune enfant avec **impétigo**.","prio":"P1","sec":"s6"},{"id":"fc-d114-c65847","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : éléments du diagnostic clinique ?","back":"**Fièvre**, **altération de l'état général**, lésions **péri-orificielles**, **décollements bulleux**.","prio":"P2","sec":"s6"},{"id":"fc-d114-2aeaf8","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : forme sévère ?","back":"**Choc toxique staphylococcique**.","prio":"P2","sec":"s6"},{"id":"fc-d114-34d903","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : diagnostic, traitement et éviction ?","back":"**Prélèvements bactériologiques** ; **oxacilline** ; éviction scolaire jusqu'à **48 h** après le début du traitement.","prio":"P1","sec":"s6"},{"id":"fc-d114-bffa91","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : nature ?","back":"**Vasculite systémique aiguë** (syndrome adéno-cutanéo-muqueux).","prio":"P2","sec":"s6"},{"id":"fc-d114-37b869","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : terrain ?","back":"Enfant de **moins de 5 ans**.","prio":"P1","sec":"s6"},{"id":"fc-d114-e377d7","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : caractéristiques de la fièvre ?","back":"**> 38,5 °C** pendant **plus de 5 jours**, avec altération de l'état général.","prio":"P1","sec":"s6"},{"id":"fc-d114-2c94a5","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : atteintes cutanéo-muqueuses ?","back":"**Conjonctivite bilatérale** + œdème palpébral ; **chéilite**, langue framboisée ; érythème-œdème des **extrémités** ; exanthème polymorphe ; desquamation « en doigt de gant ».","prio":"P2","sec":"s6"},{"id":"fc-d114-0fe583","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : caractère de la lymphadénite ?","back":"Souvent **asymétrique**.","prio":"P2","sec":"s6"},{"id":"fc-d114-fd1413","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : critère diagnostique ?","back":"**Au moins 5 des 6 critères**.","prio":"P1","sec":"s6"},{"id":"fc-d114-e43130","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : biologie attendue ?","back":"**CRP élevée**, **hyperleucocytose à PNN**, **thrombocytose**.","prio":"P2","sec":"s6"},{"id":"fc-d114-d95a0a","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : gravité ?","back":"Atteinte cardiaque : **anévrismes coronariens**, troubles du rythme ; décès par **myocardite** ou **infarctus**.","prio":"P1","sec":"s6"},{"id":"fc-d114-ed6a4e","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : conduite à tenir ?","back":"**Hospitalisation indispensable** ; un retard thérapeutique expose aux **anévrismes coronariens**.","prio":"P1","sec":"s6"},{"id":"fc-d114-e7afd7","poly":"dermato","fiche":"d114","front":"Exanthème scarlatiniforme fébrile brutal : quel syndrome rechercher ?","back":"**Choc toxique staphylococcique** + signes de **retentissement hémodynamique**.","prio":"P2","sec":"s6"},{"id":"fc-d114-2dc1af","poly":"dermato","fiche":"d114","front":"Langue framboisée : dans quels deux tableaux d'exanthème la retrouve-t-on ?","back":"**Scarlatine** et **syndrome de Kawasaki**.","prio":"P1","sec":"s7"},{"id":"fc-d114-8b197c","poly":"dermato","fiche":"d114","front":"Langue framboisée : éléments distinguant scarlatine et Kawasaki ?","back":"Scarlatine : **5-10 ans**, **angine rouge**, début brutal. Kawasaki : **< 5 ans**, fièvre > 38,5 °C **> 5 j**, conjonctivite bilatérale, extrémités.","prio":"P1","sec":"s7"},{"id":"fc-d114-ac6944","poly":"dermato","fiche":"d114","front":"Érythrodermie : quels sont les 3 temps de prise en charge à mener de front ?","back":"**Reconnaître** l'érythrodermie · **chercher sa cause** · **évaluer la gravité** immédiate (traitement symptomatique).","prio":"P1","sec":"s8"},{"id":"fc-d114-b8de19","poly":"dermato","fiche":"d114","front":"Érythrodermie : où hospitaliser le patient ?","back":"Dans un **service spécialisé**.","prio":"P2","sec":"s8"},{"id":"fc-d114-36eb59","poly":"dermato","fiche":"d114","front":"Érythrodermie : caractéristiques de l'érythème ?","back":"**Généralisé**, inflammatoire, plus **violacé aux zones déclives**, d'intensité variable d'un jour à l'autre.","prio":"P1","sec":"s8"},{"id":"fc-d114-638f4a","poly":"dermato","fiche":"d114","front":"Érythrodermie : caractère de la desquamation ?","back":"**Constante**, fine ou en larges lambeaux.","prio":"P2","sec":"s8"},{"id":"fc-d114-3ada78","poly":"dermato","fiche":"d114","front":"Érythrodermie : quel symptôme fonctionnel est constant ?","back":"Le **prurit**.","prio":"P1","sec":"s8"},{"id":"fc-d114-13f617","poly":"dermato","fiche":"d114","front":"Érythrodermie : conséquence du dérèglement thermique cutané ?","back":"Épisodes de **fièvre** et d'**hypothermie**.","prio":"P2","sec":"s8"},{"id":"fc-d114-62e3e4","poly":"dermato","fiche":"d114","front":"Érythrodermie : pachydermie, où la voit-on le mieux ?","back":"Aux **plis** (infiltration cellulaire spécifique).","prio":"P2","sec":"s8"},{"id":"fc-d114-44ebb0","poly":"dermato","fiche":"d114","front":"Érythrodermie : atteinte du visage ?","back":"**Œdème** souvent marqué, parfois avec **ectropion**.","prio":"P2","sec":"s8"},{"id":"fc-d114-240afb","poly":"dermato","fiche":"d114","front":"Érythrodermie : atteintes muqueuses possibles ?","back":"**Chéilite**, **conjonctivite**, **stomatite** (énanthème).","prio":"P3","sec":"s8"},{"id":"fc-d114-12b18c","poly":"dermato","fiche":"d114","front":"Érythrodermie : atteinte des phanères ?","back":"Après quelques semaines : chute des **cheveux, sourcils, cils** ; ongles dystrophiques (**ligne de Beau**, voire chute).","prio":"P2","sec":"s8"},{"id":"fc-d114-aad9d6","poly":"dermato","fiche":"d114","front":"Érythrodermie : caractère des adénopathies ?","back":"**Polyadénopathie** fréquente, généralisée ; ganglions parfois volumineux, **souples et mobiles**.","prio":"P2","sec":"s8"},{"id":"fc-d114-07c627","poly":"dermato","fiche":"d114","front":"Érythrodermie : retentissement général ?","back":"**Troubles hémodynamiques** (pertes hydro-électrolytiques et/ou protéiques) ; **altération de l'état général**.","prio":"P2","sec":"s8"},{"id":"fc-d114-004268","poly":"dermato","fiche":"d114","front":"Érythrodermie : quels tableaux n'en sont PAS ?","back":"Éruption érythémato-squameuse à éléments **séparés par de la peau saine** ; **exanthème** ou **nécrolyse épidermique** d'évolution aiguë.","prio":"P1","sec":"s8"},{"id":"fc-d114-63e58a","poly":"dermato","fiche":"d114","front":"Érythrodermie de l'adulte : dermatoses inflammatoires en cause ?","back":"**Psoriasis** (+++), **eczéma / dermatite atopique** (+++), **toxidermies** (DRESS +++).","prio":"P1","sec":"s9"},{"id":"fc-d114-e54ac0","poly":"dermato","fiche":"d114","front":"Érythrodermie de l'adulte : quel lymphome en cause ?","back":"**Syndrome de Sézary** (+++) : lymphome T cutané épidermotrope.","prio":"P1","sec":"s9"},{"id":"fc-d114-9e570d","poly":"dermato","fiche":"d114","front":"Érythrodermie de l'adulte : causes infectieuses ?","back":"**VIH** (+), **gale croûteuse** (++).","prio":"P1","sec":"s9"},{"id":"fc-d114-502bbc","poly":"dermato","fiche":"d114","front":"Érythrodermie de l'adulte : quelle dermatose inflammatoire citer en plus du psoriasis, de l'eczéma et des toxidermies ?","back":"**Lichen plan**.","prio":"P3","sec":"s9"},{"id":"fc-d114-66cd1d","poly":"dermato","fiche":"d114","front":"Érythrodermie : proportion de formes idiopathiques ?","back":"**10 à 15 %** des cas.","prio":"P3","sec":"s9"},{"id":"fc-d114-9125e3","poly":"dermato","fiche":"d114","front":"Érythrodermie du nouveau-né et du nourrisson de moins de 3 mois : cause ?","back":"**Maladie de Leiner-Moussous**.","prio":"P1","sec":"s9"},{"id":"fc-d114-88b0a0","poly":"dermato","fiche":"d114","front":"Érythrodermie de l'enfant après 3 mois : cause principale ?","back":"**Dermatite atopique** (+++), et les mêmes causes que chez l'adulte.","prio":"P2","sec":"s9"},{"id":"fc-d114-aa199e","poly":"dermato","fiche":"d114","front":"Érythrodermie : éléments de l'interrogatoire étiologique ?","back":"**Ancienneté**, antécédents, **prise médicamenteuse**, **topiques** utilisés, contexte **infectieux** contemporain.","prio":"P2","sec":"s9"},{"id":"fc-d114-c69aff","poly":"dermato","fiche":"d114","front":"Érythrodermie : intérêt de la biopsie cutanée ?","back":"Signes histologiques propres à la **maladie causale** ; **à répéter** si suspicion de **lymphome cutané**.","prio":"P1","sec":"s9"},{"id":"fc-d114-442d1c","poly":"dermato","fiche":"d114","front":"Érythrodermie : quels prélèvements réaliser ?","back":"**Bactériologiques** (hyperthermie, complication infectieuse) ou **parasitologiques** si besoin.","prio":"P2","sec":"s9"},{"id":"fc-d114-154a40","poly":"dermato","fiche":"d114","front":"Érythrodermie : l'aspect clinique oriente-t-il vers la cause ?","back":"**Non**, il ne préjuge pas de la cause : interrogatoire, examen et examens complémentaires indispensables.","prio":"P1","sec":"s9"},{"id":"fc-d114-5840f9","poly":"dermato","fiche":"d114","front":"Érythrodermie : de quoi dépend la gravité ?","back":"Du **terrain** et des **complications**.","prio":"P2","sec":"s10"},{"id":"fc-d114-daf9aa","poly":"dermato","fiche":"d114","front":"Érythrodermie : mécanismes des pertes hydro-électrolytiques ?","back":"**Vasodilatation** cutanée, **desquamation**, **suintement**, **œdème**, **fièvre**.","prio":"P2","sec":"s10"},{"id":"fc-d114-00933c","poly":"dermato","fiche":"d114","front":"Érythrodermie : conséquence des pertes hydro-électrolytiques ?","back":"Décompensation d'une insuffisance **cardiaque, respiratoire ou rénale**.","prio":"P1","sec":"s10"},{"id":"fc-d114-6f00f6","poly":"dermato","fiche":"d114","front":"Érythrodermie : complications du décubitus ?","back":"**Dénutrition**, **cachexie**, **escarres** (à prévenir tôt).","prio":"P2","sec":"s10"},{"id":"fc-d114-88d7d7","poly":"dermato","fiche":"d114","front":"Érythrodermie : complications infectieuses ?","back":"Cutanées bactériennes (**staphylocoque**), virales (**herpès**, varicelle-zona) ; générales (**pneumopathie**, **septicémie**).","prio":"P2","sec":"s10"},{"id":"fc-d114-00b622","poly":"dermato","fiche":"d114","front":"Érythrodermie : mortalité ?","back":"Jusqu'à **20 %**, liée aux complications, notamment **infectieuses**.","prio":"P1","sec":"s10"},{"id":"fc-d114-4429d4","poly":"dermato","fiche":"d114","front":"Érythrodermie : mise en condition en urgence ?","back":"**Hospitalisation** urgente ; **réchauffement**, **rééquilibration hydro-électrolytique**, recherche d'une **infection**.","prio":"P1","sec":"s10"},{"id":"fc-d114-413f23","poly":"dermato","fiche":"d114","front":"Érythrodermie : quel bilan pour mesurer la gravité ?","back":"**Bilan biologique**.","prio":"P2","sec":"s11"},{"id":"fc-d114-cf73ea","poly":"dermato","fiche":"d114","front":"Érythrodermie : intérêt du réchauffement du malade ?","back":"Limite les **pertes caloriques**, l'**hypercatabolisme** et la **dénutrition**.","prio":"P2","sec":"s11"},{"id":"fc-d114-c1578a","poly":"dermato","fiche":"d114","front":"Érythrodermie grave : quel traitement local ?","back":"**Dermocorticoïde de niveau 1 (très fort)** : amélioration symptomatique rapide.","prio":"P1","sec":"s11"},{"id":"fc-d114-6d4def","poly":"dermato","fiche":"d114","front":"Érythrodermie : que prendre en charge en plus des troubles hydro-électrolytiques ?","back":"Les **défaillances viscérales** éventuelles (cardiaque, respiratoire, rénale).","prio":"P2","sec":"s11"},{"id":"fc-d114-45eec9","poly":"dermato","fiche":"d114","front":"Érythrodermie : éléments à surveiller ?","back":"**Hémodynamique** et bilan hydro-électrolytique ; **infections** ; **état nutritionnel** et **points d'appui**.","prio":"P2","sec":"s11"},{"id":"fc-d114-5813bb","poly":"dermato","fiche":"d114","front":"Scarlatine : tableau typique justifiant le prélèvement de gorge ?","back":"Enfant **5-10 ans**, **angine rouge**, fièvre élevée, éruption aux **plis**, **langue framboisée**.","prio":"P2","sec":"s12"},{"id":"fc-d114-b64bcf","poly":"dermato","fiche":"d114","front":"Scarlatine : posologie et durée de l'amoxicilline dans le Collège ?","back":"**Non précisées** dans le Collège.","prio":"P3","sec":"s12"},{"id":"fc-d114-6b54fb","poly":"dermato","fiche":"d114","front":"Épidermolyse staphylococcique : quel signe ORL la distingue de la scarlatine ?","back":"**Pas d'angine**, contrairement à la scarlatine streptococcique.","prio":"P1","sec":"s13"},{"id":"fc-d114-7f6cca","poly":"dermato","fiche":"d114","front":"Syndrome de Kawasaki : traitement spécifique décrit dans le Collège ?","back":"**Non précisé** dans le Collège ; **hospitalisation indispensable**.","prio":"P3","sec":"s14"},{"id":"fc-d114-1ec9e0","poly":"dermato","fiche":"d114","front":"Rougeole : période de contagiosité ?","back":"De **3-5 jours avant** à **4 jours après** l'éruption : contagieux **avant** l'éruption.","prio":"P1","sec":"s15"},{"id":"fc-d114-093233","poly":"dermato","fiche":"d114","front":"Rougeole : traitement spécifique décrit dans le Collège ?","back":"**Aucun** traitement spécifique décrit.","prio":"P3","sec":"s15"},{"id":"fc-d114-882f03","poly":"dermato","fiche":"d114","front":"Rubéole et mégalérythème : traitement spécifique décrit dans le Collège ?","back":"**Aucun** traitement spécifique décrit.","prio":"P3","sec":"s16"},{"id":"fc-d114-a500ef","poly":"dermato","fiche":"d114","front":"Exanthème : orientation médicamenteuse, quels médicaments sont cités ?","back":"**β-lactamines**, **sulfamides**, **anti-comitiaux** ; suivre la conduite des toxidermies.","prio":"P2","sec":"s17"},{"id":"fc-d114-7140f0","poly":"dermato","fiche":"d114","front":"Exanthème : 3 questions clés de l'interrogatoire ?","back":"**Contexte épidémique** · **contage** · **prise de médicament**.","prio":"P2","sec":"s17"},{"id":"fc-d114-baefbb","poly":"dermato","fiche":"d114","front":"Collectivité : quelle éviction pour une maladie bactérienne traitée (scarlatine, épidermolyse staphylococcique) ?","back":"Jusqu'à **48 heures** après le début du traitement.","prio":"P1","sec":"s18"},{"id":"fc-d114-76da61","poly":"dermato","fiche":"d114","front":"Collectivité : comparer les mesures rougeole et rubéole ?","back":"Rougeole : éviction **5 j** après l'éruption + **déclaration obligatoire**. Rubéole : **pas d'éviction**, informer les femmes enceintes.","prio":"P1","sec":"s18"},{"id":"fc-d115-14f897","poly":"dermato","fiche":"d115","front":"Toxidermie : quelle est sa définition ?","back":"Tout effet indésirable **cutané** d'un médicament pris par **voie interne**, à **dose thérapeutique**.","prio":"P1","sec":"s1"},{"id":"fc-d115-ef8a90","poly":"dermato","fiche":"d115","front":"Toxidermie : quels médicaments peuvent en être responsables ?","back":"**Tout médicament** : passer en revue **tous** ceux que prend le patient, sans s'arrêter au « coupable idéal ».","prio":"P1","sec":"s1"},{"id":"fc-d115-f23b73","poly":"dermato","fiche":"d115","front":"Toxidermie : quelle est la nature du diagnostic ?","back":"Un **diagnostic de présomption** : faisceau d'arguments, aucun n'a de valeur absolue à lui seul.","prio":"P1","sec":"s1"},{"id":"fc-d115-a6f273","poly":"dermato","fiche":"d115","front":"Toxidermie non immunologique : quelles caractéristiques ?","back":"Effet **pharmacodynamique** du médicament : **fréquente**, **dose-dépendante**, **prévisible**, mortalité faible.","prio":"P2","sec":"s1"},{"id":"fc-d115-b6801a","poly":"dermato","fiche":"d115","front":"Toxidermie non immunologique : citer un exemple d'effet principal et un d'effet latéral ?","back":"Effet principal : **xérose et chéilite sous rétinoïdes** ; effet latéral : **alopécie des antimitotiques** ou **pigmentation sous hydroxychloroquine**.","prio":"P3","sec":"s1"},{"id":"fc-d115-c4dafe","poly":"dermato","fiche":"d115","front":"Toxidermie immuno-allergique : quelles caractéristiques ?","back":"**Rare**, le plus souvent **imprévisible**, **non dose-dépendante**, mortalité variable.","prio":"P2","sec":"s1"},{"id":"fc-d115-917e49","poly":"dermato","fiche":"d115","front":"Hypersensibilité immédiate médicamenteuse : quel médiateur et quelles manifestations ?","back":"**IgE** ; peu après la prise : **urticaire**, **angiœdème**, **choc anaphylactique**.","prio":"P2","sec":"s1"},{"id":"fc-d115-6b67a9","poly":"dermato","fiche":"d115","front":"Hypersensibilité retardée médicamenteuse : quel médiateur et quel délai ?","back":"**Lymphocytes** ; plusieurs **jours à semaines** après la prise ; c'est la forme **la plus fréquente**.","prio":"P2","sec":"s1"},{"id":"fc-d115-094a71","poly":"dermato","fiche":"d115","front":"Hypersensibilité retardée : quel éventail de sévérité ?","back":"Du simple **exanthème maculo-papuleux** à la **nécrolyse épidermique toxique** (Stevens-Johnson, Lyell).","prio":"P3","sec":"s1"},{"id":"fc-d115-b35164","poly":"dermato","fiche":"d115","front":"Toxidermie : un même aspect clinique relève-t-il toujours du même mécanisme ?","back":"**Non** : urticaire ou photosensibilité peuvent relever de **mécanismes différents**.","prio":"P3","sec":"s1"},{"id":"fc-d115-ffd464","poly":"dermato","fiche":"d115","front":"Toxidermie immunologique : comment est-elle détectée ?","back":"Par les **études post-AMM** seulement (le mécanisme non immunologique est aussi repéré par les essais contrôlés).","prio":"P3","sec":"s1"},{"id":"fc-d115-742bcc","poly":"dermato","fiche":"d115","front":"Toxidermie grave : quelle mesure réglementaire est possible ?","back":"Modification du RCP, voire **retrait** du médicament possible.","prio":"P3","sec":"s1"},{"id":"fc-d115-87ef3a","poly":"dermato","fiche":"d115","front":"Toxidermies : quelle fréquence selon le tableau des objectifs ?","back":"**1 à 3 %** des prises de médicaments ; ce sont les plus fréquents des **accidents iatrogènes médicamenteux**.","prio":"P3","sec":"s1"},{"id":"fc-d115-d3f831","poly":"dermato","fiche":"d115","front":"Accidents iatrogènes médicamenteux : quelle part des consultations ambulatoires ?","back":"**0,5 à 2 %** ; la iatrogénie au sens large, environ **10 %** des hospitalisations.","prio":"P3","sec":"s1"},{"id":"fc-d115-126542","poly":"dermato","fiche":"d115","front":"Toxidermies : quelle proportion est bénigne ?","back":"Plus de **90 %**.","prio":"P2","sec":"s1"},{"id":"fc-d115-18ff18","poly":"dermato","fiche":"d115","front":"Toxidermies menaçant la vie : quelle fréquence ?","back":"Très rares : **1 pour 10 000 à 1 000 000** de patients traités, trop rares pour les essais avant l'AMM.","prio":"P3","sec":"s1"},{"id":"fc-d115-80f460","poly":"dermato","fiche":"d115","front":"Quelle est la toxidermie la plus fréquente parmi les notifications ?","back":"L'**exanthème maculo-papuleux** (**40 à 60 %**), puis l'urticaire (20 à 30 %).","prio":"P2","sec":"s1"},{"id":"fc-d115-9153af","poly":"dermato","fiche":"d115","front":"Toxidermies : quels terrains augmentent le risque ?","back":"Infection par le **VIH** et **immunosuppression** quelle qu'en soit la cause (formes bénignes comme graves).","prio":"P2","sec":"s1"},{"id":"fc-d115-3ef49a","poly":"dermato","fiche":"d115","front":"DRESS : à quelle réactivation virale s'associe-t-il ?","back":"Virus du groupe **herpès** : **HHV6** surtout, mais aussi HHV7, EBV, CMV.","prio":"P2","sec":"s7"},{"id":"fc-d115-138014","poly":"dermato","fiche":"d115","front":"Toxidermie : quelle obligation légale ?","back":"**Déclaration à la pharmacovigilance**, en particulier si grave, inattendue ou non connue.","prio":"P1","sec":"s1"},{"id":"fc-d115-e61ddd","poly":"dermato","fiche":"d115","front":"Éruption sous médicament : quel est le premier réflexe ?","back":"Chercher **systématiquement** les **signes de gravité**.","prio":"P1","sec":"s2"},{"id":"fc-d115-9473f1","poly":"dermato","fiche":"d115","front":"Toxidermie : combien de signes de gravité imposent l'hospitalisation ?","back":"**Un seul** suffit.","prio":"P1","sec":"s2"},{"id":"fc-d115-fab0b8","poly":"dermato","fiche":"d115","front":"Toxidermie : quels signes de gravité concernent l'étendue et l'infiltration ?","back":"Exanthème **généralisé** ou qui s'étend **très vite** ; lésions **infiltrées**, en particulier **œdème du visage**.","prio":"P1","sec":"s2"},{"id":"fc-d115-7acdc6","poly":"dermato","fiche":"d115","front":"Toxidermie : quels signes de gravité concernent les lésions élémentaires et les muqueuses ?","back":"**Vésicules ou bulles**, **pustules**, **érosions muqueuses**, douleurs cutanées ou muqueuses intenses.","prio":"P1","sec":"s2"},{"id":"fc-d115-b0dcab","poly":"dermato","fiche":"d115","front":"Qu'est-ce que le signe de Nikolsky ?","back":"La **peau saine se décolle** sous un frottement appuyé.","prio":"P1","sec":"s2"},{"id":"fc-d115-d635a2","poly":"dermato","fiche":"d115","front":"Toxidermie : quels signes de gravité concernent la couleur de la peau ?","back":"**Purpura infiltré**, **nécrose**, peau d'aspect **grisâtre** (souffrance de l'épiderme).","prio":"P1","sec":"s2"},{"id":"fc-d115-5339d5","poly":"dermato","fiche":"d115","front":"Toxidermie : quels signes généraux de gravité ?","back":"**Fièvre élevée**, **adénopathies multiples**, mauvaise tolérance **hémodynamique**.","prio":"P1","sec":"s2"},{"id":"fc-d115-8d70e3","poly":"dermato","fiche":"d115","front":"Toxidermie : éruption très étendue avec œdème du visage et lésions infiltrées, quelle forme grave évoquer ?","back":"Le **DRESS** (syndrome d'hypersensibilité médicamenteuse).","prio":"P1","sec":"s2"},{"id":"fc-d115-6e0d4e","poly":"dermato","fiche":"d115","front":"Toxidermie : érosions muqueuses, bulles et Nikolsky, quelle forme grave évoquer ?","back":"La **nécrolyse épidermique toxique** (Stevens-Johnson, Lyell).","prio":"P1","sec":"s2"},{"id":"fc-d115-460313","poly":"dermato","fiche":"d115","front":"Toxidermie : fièvre élevée et érythème des grands plis couvert de pustules, quelle forme évoquer ?","back":"La **PEAG** (pustulose exanthématique aiguë généralisée).","prio":"P1","sec":"s2"},{"id":"fc-d115-5c4e7b","poly":"dermato","fiche":"d115","front":"Toxidermie grave : quelle conduite immédiate ?","back":"**Arrêt immédiat** du ou des médicaments suspects + **hospitalisation en urgence**.","prio":"P1","sec":"s2"},{"id":"fc-d115-aa1652","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : purpura pétéchial des jambes, prurit, fièvre modérée sont-ils des signes de gravité ?","back":"**Non**, ils restent compatibles avec un exanthème banal.","prio":"P1","sec":"s2"},{"id":"fc-d115-6faed9","poly":"dermato","fiche":"d115","front":"Quelles sont les toxidermies immuno-allergiques non graves ?","back":"**Exanthème maculo-papuleux** et **érythème pigmenté fixe**.","prio":"P1","sec":"s3"},{"id":"fc-d115-a56ad2","poly":"dermato","fiche":"d115","front":"Quelles sont les toxidermies immuno-allergiques graves ?","back":"**PEAG**, **DRESS**, **Stevens-Johnson / Lyell** (nécrolyse épidermique toxique).","prio":"P1","sec":"s3"},{"id":"fc-d115-142990","poly":"dermato","fiche":"d115","front":"Toxidermies : quelles formes sont classées à part ?","back":"**Urticaire**, **angiœdème** et **choc anaphylactique** (les deux derniers sont des urgences) ; **photosensibilité**.","prio":"P2","sec":"s3"},{"id":"fc-d115-04fe78","poly":"dermato","fiche":"d115","front":"Toxidermies : citer d'autres lésions cutanées qu'un médicament peut induire ?","back":"Réactions **psoriasiformes**, **acnéiformes**, **pemphigus**, **lupus**, **ulcérations buccales**.","prio":"P3","sec":"s3"},{"id":"fc-d115-afd720","poly":"dermato","fiche":"d115","front":"Toxidermies : classer les délais du plus court au plus long ?","back":"**Minutes** (anaphylaxie, urticaire) → **heures** (érythème pigmenté fixe) → **jours** (PEAG, EMP, nécrolyse) → **semaines** (DRESS).","prio":"P1","sec":"s3"},{"id":"fc-d115-bc5bde","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quelle part des causes médicamenteuses selon l'âge ?","back":"Enfant : **10-20 %** ; adulte : **50-70 %**.","prio":"P3","sec":"s3"},{"id":"fc-d115-f8e3db","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quels inducteurs fréquents ?","back":"**Aminopénicillines**, bêtalactamines, **sulfamides** antibactériens, antituberculeux, **anticomitiaux**.","prio":"P3","sec":"s3"},{"id":"fc-d115-254ff5","poly":"dermato","fiche":"d115","front":"Anaphylaxie : quelle part des causes médicamenteuses et quelle mortalité ?","back":"**30 %** de causes médicamenteuses ; mortalité **5 %**.","prio":"P3","sec":"s3"},{"id":"fc-d115-26ce94","poly":"dermato","fiche":"d115","front":"Anaphylaxie médicamenteuse : quels inducteurs principaux ?","back":"**Curarisants**, **AINS**, sérums et vaccins.","prio":"P3","sec":"s3"},{"id":"fc-d115-70395b","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux médicamenteux : quel délai d'apparition ?","back":"**4 à 14 jours** après l'introduction (classiquement 8 à 10 jours).","prio":"P1","sec":"s4"},{"id":"fc-d115-f567dc","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : où débute l'éruption ?","back":"Sur le **tronc** ou la racine des membres ; extension possible quelques jours.","prio":"P2","sec":"s4"},{"id":"fc-d115-7e5a78","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quelle caractéristique des lésions chez un même malade ?","back":"Leur **polymorphisme** : macules morbilliformes, nappes confluentes, papules ou plaques œdémateuses, purpura pétéchial déclive.","prio":"P1","sec":"s4"},{"id":"fc-d115-1b6fb0","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : qu'est-ce que l'aspect scarlatiniforme ?","back":"Érythème maculeux **diffus**, avec peu ou pas d'intervalles de peau saine.","prio":"P3","sec":"s4"},{"id":"fc-d115-d02b9b","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : y a-t-il un énanthème ?","back":"En général **non** (mais chéilite possible du versant semi-muqueux des lèvres).","prio":"P2","sec":"s4"},{"id":"fc-d115-4b9c0e","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quels signes associés ?","back":"**Prurit** fréquent, d'intensité variable ; fièvre **modérée ou absente**.","prio":"P2","sec":"s4"},{"id":"fc-d115-02a9b8","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quelle évolution après l'arrêt du médicament ?","back":"Guérison en **1 semaine à 10 jours**, souvent avec une **fine desquamation** finale.","prio":"P1","sec":"s4"},{"id":"fc-d115-bf546e","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique** ; examens seulement si présentation **atypique**.","prio":"P1","sec":"s4"},{"id":"fc-d115-972bd6","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quelle éosinophilie peut-on trouver ?","back":"Possible, souvent **modérée** (< 1000/mm³).","prio":"P3","sec":"s4"},{"id":"fc-d115-ea81f3","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : quelles atteintes viscérales vérifier absentes ?","back":"Atteinte **rénale** ou **hépatique**, qui signerait une **toxidermie grave**.","prio":"P2","sec":"s4"},{"id":"fc-d115-d1b037","poly":"dermato","fiche":"d115","front":"Exanthème maculo-papuleux : que montre la biopsie ?","back":"Peu spécifique : **nécroses kératinocytaires**, infiltrat souvent discret, parfois avec éosinophiles.","prio":"P3","sec":"s4"},{"id":"fc-d115-766721","poly":"dermato","fiche":"d115","front":"Quelle toxidermie est pathognomonique ?","back":"L'**érythème pigmenté fixe** : dermatose de cause presque exclusivement médicamenteuse (**99 %**).","prio":"P1","sec":"s4"},{"id":"fc-d115-cdb53f","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quel délai après la prise ?","back":"Quelques heures, **avant 48 heures**.","prio":"P1","sec":"s4"},{"id":"fc-d115-36cc71","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quels inducteurs fréquents ?","back":"**Paracétamol** et **AINS**.","prio":"P1","sec":"s4"},{"id":"fc-d115-2e292c","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quel aspect des lésions ?","back":"**1 à 10 macules rouges arrondies** de quelques cm, souvent **douloureuses**, s'infiltrant en plaques.","prio":"P2","sec":"s4"},{"id":"fc-d115-48ca7c","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quels sièges de prédilection ?","back":"**Organes génitaux** ou **lèvres**.","prio":"P2","sec":"s4"},{"id":"fc-d115-a21923","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quelle évolution des lésions ?","back":"Disparition en quelques jours, laissant classiquement (pas toujours) des **taches pigmentées** brunes ou ardoisées.","prio":"P2","sec":"s4"},{"id":"fc-d115-9fe4a7","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : que se passe-t-il en cas de reprise du médicament ?","back":"**Récidive rapide aux mêmes sites**.","prio":"P1","sec":"s4"},{"id":"fc-d115-6d5369","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quelle évolution impose l'hospitalisation ?","back":"Une forme **bulleuse et généralisée**.","prio":"P2","sec":"s12"},{"id":"fc-d115-b9ccea","poly":"dermato","fiche":"d115","front":"Érythème pigmenté fixe : quel piège d'interrogatoire ?","back":"Le **paracétamol** pris occasionnellement est souvent **omis** par le patient : poser la question.","prio":"P2","sec":"s4"},{"id":"fc-d115-a87846","poly":"dermato","fiche":"d115","front":"Urticaire médicamenteuse : quelles lésions et quel délai ?","back":"Papules **prurigineuses**, **mobiles et fugaces**, quelques **minutes à heures** après la prise.","prio":"P1","sec":"s5"},{"id":"fc-d115-8063fa","poly":"dermato","fiche":"d115","front":"Urticaire reconnue médicamenteuse : quelle mesure ?","back":"L'**arrêt du médicament**.","prio":"P1","sec":"s5"},{"id":"fc-d115-2adbdd","poly":"dermato","fiche":"d115","front":"Anaphylaxie : quels signes respiratoires ?","back":"**Dysphonie**, **dyspnée**, **bronchospasme**.","prio":"P2","sec":"s5"},{"id":"fc-d115-1fc58d","poly":"dermato","fiche":"d115","front":"Anaphylaxie : quels signes cardiovasculaires et digestifs ?","back":"**Tachycardie ou bradycardie**, **hypotension** ; nausées, vomissements, diarrhée.","prio":"P2","sec":"s5"},{"id":"fc-d115-5d17e5","poly":"dermato","fiche":"d115","front":"Urticaire : quels arguments en faveur d'une allergie médicamenteuse ?","back":"Délai prise-symptômes **< 45 min**, symptômes durant **< 24 h**, sévérité **> grade II**.","prio":"P2","sec":"s5"},{"id":"fc-d115-e58a9d","poly":"dermato","fiche":"d115","front":"Urticaire (item d187) : quelles classes de médicaments sont le plus souvent en cause ?","back":"**Antibiotiques**, **AINS**, anesthésiques généraux (**curares**).","prio":"P2","sec":"s5"},{"id":"fc-d115-caf229","poly":"dermato","fiche":"d115","front":"Urticaire médicamenteuse : dans quelle proportion le mécanisme est-il IgE-dépendant ?","back":"**Moins de 10 %** (ex. pénicillines) ; bien plus souvent **non immunologique** (intolérance, ex. AINS).","prio":"P2","sec":"s5"},{"id":"fc-d115-11b9de","poly":"dermato","fiche":"d115","front":"Quelle proportion des urticaires aiguës est d'origine médicamenteuse ?","back":"**Moins de 10 %** : les infections, surtout virales (en particulier chez l'enfant), en donnent souvent.","prio":"P1","sec":"s5"},{"id":"fc-d115-99962b","poly":"dermato","fiche":"d115","front":"Hypersensibilité immédiate IgE-médiée : apparaît-elle au premier contact avec le médicament ?","back":"**Non** : elle témoigne d'une **sensibilisation préalable**.","prio":"P2","sec":"s5"},{"id":"fc-d115-be81fe","poly":"dermato","fiche":"d115","front":"Hypersensibilité IgE-médiée à un médicament : quelle conséquence pour la suite ?","back":"**Contre-indication formelle** du même médicament (risque d'anaphylaxie) ; prudence avec les molécules proches (pénicillines/bêtalactamines).","prio":"P2","sec":"s5"},{"id":"fc-d115-099fd6","poly":"dermato","fiche":"d115","front":"Réaction anaphylactoïde (sans IgE) : quelles caractéristiques ?","back":"Activation directe des médiateurs ; réaction **inconstante** et **dose-dépendante** (AINS, aspirine, pénicillines, codéine…).","prio":"P3","sec":"s5"},{"id":"fc-d115-1fb773","poly":"dermato","fiche":"d115","front":"Réaction anaphylactoïde : avec quels produits le risque de récidive existe-t-il ?","back":"Avec **tous les produits de même effet pharmacologique**, même de formule différente (ex. produits de contraste iodés hyperosmolaires).","prio":"P3","sec":"s5"},{"id":"fc-d115-0bdbb5","poly":"dermato","fiche":"d115","front":"Angiœdème aux AINS : quel mécanisme ?","back":"Accumulation de dérivés de l'acide arachidonique (**leucotriènes**).","prio":"P3","sec":"s5"},{"id":"fc-d115-3f6ad3","poly":"dermato","fiche":"d115","front":"Urticaire médicamenteuse : quels inducteurs cite le tableau des types cliniques (5.2) ?","back":"**Pénicillines**, **produits de contraste iodés**.","prio":"P3","sec":"s3"},{"id":"fc-d115-e4138f","poly":"dermato","fiche":"d115","front":"Photosensibilité médicamenteuse : quelle présentation ?","back":"Éruption dans les **heures** suivant une **exposition solaire**, limitée aux **zones découvertes** (visage, décolleté, extrémités).","prio":"P1","sec":"s6"},{"id":"fc-d115-1071fc","poly":"dermato","fiche":"d115","front":"Phototoxicité : de quoi dépend-elle ?","back":"À la fois de la **dose de médicament** et de la **dose d'UVA**.","prio":"P2","sec":"s6"},{"id":"fc-d115-804b43","poly":"dermato","fiche":"d115","front":"Phototoxicité : quel délai et quel aspect ?","back":"**Dès les premières prises**, quelques heures après l'exposition ; érythème à **limite nette** s'arrêtant aux zones découvertes.","prio":"P2","sec":"s6"},{"id":"fc-d115-5d4988","poly":"dermato","fiche":"d115","front":"Phototoxicité : quels médicaments inducteurs ?","back":"**Cyclines**, **quinolones**, phénothiazines, **amiodarone**, méladinine.","prio":"P2","sec":"s6"},{"id":"fc-d115-7753eb","poly":"dermato","fiche":"d115","front":"Phototoxicité : quelle mortalité ?","back":"**< 1 %**.","prio":"P3","sec":"s6"},{"id":"fc-d115-742ae3","poly":"dermato","fiche":"d115","front":"Photo-allergie : quel aspect clinique ?","back":"Lésions d'**eczéma** débutant aux zones exposées mais pouvant gagner les **zones couvertes**.","prio":"P2","sec":"s6"},{"id":"fc-d115-385e60","poly":"dermato","fiche":"d115","front":"Photo-allergie : quel délai après le début du traitement ?","back":"Habituellement **7 à 21 jours** ; parfois après une exposition solaire minime.","prio":"P2","sec":"s6"},{"id":"fc-d115-b6cdae","poly":"dermato","fiche":"d115","front":"Photo-allergie : par quelle voie le médicament peut-il être en cause ?","back":"Voie **systémique ou topique**.","prio":"P3","sec":"s6"},{"id":"fc-d115-69b9d6","poly":"dermato","fiche":"d115","front":"Photo-allergie : quels médicaments inducteurs ?","back":"**Phénothiazines**, **sulfamides**, **AINS**.","prio":"P3","sec":"s6"},{"id":"fc-d115-adb578","poly":"dermato","fiche":"d115","front":"Photo-allergie : quelle évolution exceptionnelle après l'arrêt ?","back":"Une **photosensibilité persistante** malgré l'arrêt du médicament.","prio":"P3","sec":"s6"},{"id":"fc-d115-28ea96","poly":"dermato","fiche":"d115","front":"Photosensibilité médicamenteuse : quelle conduite ?","back":"**Arrêt immédiat** du médicament suspect, contre-indication écrite et déclaration de pharmacovigilance.","prio":"P2","sec":"s12"},{"id":"fc-d115-e55e9a","poly":"dermato","fiche":"d115","front":"PEAG : quel délai après le médicament ?","back":"En général **1 à 11 jours** (souvent un **antibiotique**).","prio":"P1","sec":"s7"},{"id":"fc-d115-01e361","poly":"dermato","fiche":"d115","front":"PEAG : comment débute l'éruption ?","back":"**Fièvre** + érythème en nappe, scarlatiniforme, prédominant dans les **grands plis** (aisselles, aines).","prio":"P1","sec":"s7"},{"id":"fc-d115-c475c3","poly":"dermato","fiche":"d115","front":"PEAG : quelles pustules caractérisent l'éruption ?","back":"Nombreuses **pustules amicrobiennes** superficielles, petites (**< 2 mm**), à contenu lactescent.","prio":"P1","sec":"s7"},{"id":"fc-d115-f05f51","poly":"dermato","fiche":"d115","front":"PEAG : quels signes généraux ?","back":"Début **brutal et très fébrile** ; altération de l'état général fréquente.","prio":"P2","sec":"s7"},{"id":"fc-d115-0f3f80","poly":"dermato","fiche":"d115","front":"PEAG : l'atteinte muqueuse est-elle constante ?","back":"**Non**, inconstante.","prio":"P3","sec":"s7"},{"id":"fc-d115-14456b","poly":"dermato","fiche":"d115","front":"PEAG : quelle évolution après l'arrêt ?","back":"**Régression rapide** : pustules disparues en quelques jours avec **desquamation diffuse**.","prio":"P2","sec":"s7"},{"id":"fc-d115-0de695","poly":"dermato","fiche":"d115","front":"PEAG : quelle anomalie de la NFS ?","back":"**Hyperleucocytose à polynucléaires neutrophiles**, parfois importante.","prio":"P2","sec":"s7"},{"id":"fc-d115-595751","poly":"dermato","fiche":"d115","front":"PEAG : avec quoi est-elle souvent confondue à tort ?","back":"Avec une **infection** (fièvre, pustules), alors que les pustules sont **amicrobiennes**.","prio":"P1","sec":"s7"},{"id":"fc-d115-4ba177","poly":"dermato","fiche":"d115","front":"PEAG : quels médicaments inducteurs fréquents ?","back":"**Aminopénicillines**, **pristinamycine**, quinolones, sulfamides, **diltiazem**, terbinafine, hydroxychloroquine.","prio":"P3","sec":"s14"},{"id":"fc-d115-641337","poly":"dermato","fiche":"d115","front":"PEAG : quelle part de causes médicamenteuses et quelle mortalité ?","back":"**70 à 90 %** de causes médicamenteuses ; mortalité **2 à 5 %**.","prio":"P3","sec":"s14"},{"id":"fc-d115-fa89cd","poly":"dermato","fiche":"d115","front":"DRESS : quel délai après le début du médicament ?","back":"Habituellement **2 à 6 semaines** ; délai court possible (antibiotiques, produits de contraste iodés).","prio":"P1","sec":"s7"},{"id":"fc-d115-cc9cc6","poly":"dermato","fiche":"d115","front":"DRESS : quel aspect de l'éruption ?","back":"Éruption **étendue**, parfois érythrodermique, **infiltrée**, avec prurit sévère.","prio":"P1","sec":"s7"},{"id":"fc-d115-9facfe","poly":"dermato","fiche":"d115","front":"DRESS : quel signe cutané important et caractéristique rechercher ?","back":"L'**œdème du visage et des extrémités**.","prio":"P1","sec":"s7"},{"id":"fc-d115-b7608d","poly":"dermato","fiche":"d115","front":"DRESS : quels signes généraux ?","back":"**Fièvre élevée** et **adénopathies diffuses**.","prio":"P1","sec":"s7"},{"id":"fc-d115-69ac94","poly":"dermato","fiche":"d115","front":"DRESS : quelles atteintes viscérales principales ?","back":"Surtout **hépatite** et **néphropathie interstitielle**.","prio":"P1","sec":"s7"},{"id":"fc-d115-b06c6f","poly":"dermato","fiche":"d115","front":"DRESS : quelles autres atteintes viscérales possibles ?","back":"**Pneumopathie interstitielle**, **myocardite**, **syndrome d'activation macrophagique**.","prio":"P2","sec":"s7"},{"id":"fc-d115-a610ef","poly":"dermato","fiche":"d115","front":"DRESS : quelles anomalies de la NFS ?","back":"**Éosinophilie** (souvent > 1500/mm³, parfois retardée) et/ou **lymphocytose** avec syndrome mononucléosique.","prio":"P1","sec":"s7"},{"id":"fc-d115-d1f387","poly":"dermato","fiche":"d115","front":"DRESS : quelle évolution ?","back":"**Régression lente** ; nouvelles poussées cutanées et/ou viscérales possibles pendant **des semaines à des mois**, souvent avec réactivations virales.","prio":"P2","sec":"s7"},{"id":"fc-d115-6a9693","poly":"dermato","fiche":"d115","front":"DRESS : comment se définit-il ?","back":"Par l'**association de plusieurs critères** : étendue, infiltration, fièvre, adénopathies, atteintes viscérales, anomalies de la NFS.","prio":"P2","sec":"s7"},{"id":"fc-d115-bed0bf","poly":"dermato","fiche":"d115","front":"DRESS : quel bilan biologique est indispensable ?","back":"**NFS**, **fonction rénale**, **fonction hépatique** ; autres atteintes selon la clinique.","prio":"P2","sec":"s7"},{"id":"fc-d115-69087d","poly":"dermato","fiche":"d115","front":"DRESS : quelle population semble plus à risque ?","back":"Les sujets à **peau noire**.","prio":"P3","sec":"s7"},{"id":"fc-d115-1949c6","poly":"dermato","fiche":"d115","front":"DRESS : quels médicaments inducteurs fréquents ?","back":"**Anticomitiaux**, sulfamides, minocycline, **allopurinol**, IPP, produits de contraste iodés.","prio":"P2","sec":"s14"},{"id":"fc-d115-b01053","poly":"dermato","fiche":"d115","front":"DRESS : quelle part de causes médicamenteuses et quelle mortalité ?","back":"**70 à 90 %** de causes médicamenteuses ; mortalité **5 à 10 %**.","prio":"P3","sec":"s14"},{"id":"fc-d115-a91d43","poly":"dermato","fiche":"d115","front":"Quelles sont les formes les plus graves de toxidermie ?","back":"Le **syndrome de Stevens-Johnson** et le **syndrome de Lyell** (nécrolyse épidermique toxique).","prio":"P1","sec":"s8"},{"id":"fc-d115-f7090f","poly":"dermato","fiche":"d115","front":"Stevens-Johnson et Lyell : quel rapport entre les deux ?","back":"Un **continuum** d'une même maladie, séparé par la **surface d'épiderme nécrosé** (décollé ou décollable).","prio":"P1","sec":"s8"},{"id":"fc-d115-eb36b0","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique toxique : quel est le facteur pronostique majeur ?","back":"La **surface d'épiderme décollé ou décollable**.","prio":"P1","sec":"s8"},{"id":"fc-d115-c4fa15","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quel délai d'apparition après l'introduction du médicament ?","back":"**4 à 28 jours** (texte et tableau 5.2) ; le tableau des objectifs indique **7 à 21 jours**.","prio":"P1","sec":"s8"},{"id":"fc-d115-cb1dcb","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : comment débute le tableau ?","back":"Début peu spécifique : **fièvre**, **brûlures oculaires**, **pharyngite**, éruption rouge **douloureuse et non prurigineuse**.","prio":"P1","sec":"s8"},{"id":"fc-d115-f618db","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quels signes à la phase d'état ?","back":"**Érosions muqueuses multifocales**, **bulles cutanées**, **signe de Nikolsky**, état général très altéré.","prio":"P1","sec":"s8"},{"id":"fc-d115-bab984","poly":"dermato","fiche":"d115","front":"Nécrolyse : où rechercher le signe de Nikolsky ?","back":"En zone **non décollée** (« saine ») : des lambeaux d'épiderme se détachent au frottement.","prio":"P2","sec":"s8"},{"id":"fc-d115-cc1d38","poly":"dermato","fiche":"d115","front":"Nécrolyse : quelle atteinte viscérale est de pronostic très défavorable ?","back":"**Polypnée avec hypoxémie** par nécrose de l'épithélium **bronchique**.","prio":"P2","sec":"s8"},{"id":"fc-d115-ef6d67","poly":"dermato","fiche":"d115","front":"Nécrolyse : quelle atteinte digestive possible ?","back":"Une **colite** (nécrose de l'épithélium intestinal).","prio":"P3","sec":"s8"},{"id":"fc-d115-243e92","poly":"dermato","fiche":"d115","front":"Syndrome de Stevens-Johnson : quelle surface décollée ?","back":"**< 10 %** de la surface corporelle.","prio":"P1","sec":"s8"},{"id":"fc-d115-983455","poly":"dermato","fiche":"d115","front":"Syndrome de Lyell : quelle surface décollée ?","back":"**> 30 %** de la surface corporelle.","prio":"P1","sec":"s8"},{"id":"fc-d115-4f2a09","poly":"dermato","fiche":"d115","front":"Syndrome de Stevens-Johnson : quel aspect des lésions ?","back":"Bulles et vésicules disséminées **distinctes et de petite taille**, sur base rouge, avec **intervalles de peau saine**.","prio":"P2","sec":"s8"},{"id":"fc-d115-d6e6c5","poly":"dermato","fiche":"d115","front":"Syndrome de Lyell : quel aspect de la peau ?","back":"**Vastes lambeaux** décollés (derme rouge vif suintant) ou décollables (« **linge mouillé** »), peau grisâtre, sans intervalle sain.","prio":"P2","sec":"s8"},{"id":"fc-d115-050945","poly":"dermato","fiche":"d115","front":"Stevens-Johnson et Lyell : la surface atteinte peut-elle évoluer ?","back":"**Oui** : passage possible du Stevens-Johnson au Lyell en **quelques jours**.","prio":"P2","sec":"s8"},{"id":"fc-d115-ee1599","poly":"dermato","fiche":"d115","front":"Stevens-Johnson et Lyell : les médicaments en cause diffèrent-ils selon le grade ?","back":"**Non** : les **mêmes médicaments** donnent tous les grades de sévérité.","prio":"P3","sec":"s8"},{"id":"fc-d115-8f7805","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quelles anomalies biologiques ?","back":"**Leucopénie**, signes de défaillance multiviscérale, **troubles hydroélectrolytiques** (pertes cutanées).","prio":"P3","sec":"s8"},{"id":"fc-d115-9f76b5","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : que montre la biopsie cutanée ?","back":"Épiderme **nécrosé sur toute son épaisseur**, détaché d'un derme peu modifié ; **IFD négative**.","prio":"P2","sec":"s8"},{"id":"fc-d115-6616b9","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quelle mortalité ?","back":"Élevée : **20 à 25 %**.","prio":"P2","sec":"s8"},{"id":"fc-d115-d7b800","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : en combien de temps se fait la ré-épidermisation ?","back":"En **10 à 30 jours**.","prio":"P3","sec":"s8"},{"id":"fc-d115-b90e32","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quelles séquelles sont assez fréquentes ?","back":"**Troubles pigmentaires** et **cicatrices muqueuses**, surtout **oculaires** (synéchies).","prio":"P2","sec":"s8"},{"id":"fc-d115-943ec4","poly":"dermato","fiche":"d115","front":"Nécrolyse épidermique : quels médicaments inducteurs fréquents ?","back":"**Sulfamides** antibactériens, **anticomitiaux**, AINS (**oxicams**), **allopurinol**, **névirapine**.","prio":"P2","sec":"s8"},{"id":"fc-d115-7de76a","poly":"dermato","fiche":"d115","front":"Stevens-Johnson : quel diagnostic différentiel principal ?","back":"L'**érythème polymorphe majeur**.","prio":"P2","sec":"s9"},{"id":"fc-d115-82b0b5","poly":"dermato","fiche":"d115","front":"Érythème polymorphe : quels éléments le distinguent du Stevens-Johnson ?","back":"**Cocardes** typiques, distribution **acrale** souvent symétrique, lésions souvent monomorphes, **récidives fréquentes**.","prio":"P2","sec":"s9"},{"id":"fc-d115-7f5f19","poly":"dermato","fiche":"d115","front":"Érythème polymorphe : quel terrain ?","back":"Surtout l'**enfant** et l'**adulte jeune**.","prio":"P3","sec":"s9"},{"id":"fc-d115-3f4f2d","poly":"dermato","fiche":"d115","front":"Épidermolyse staphylococcique : quels éléments la distinguent du Lyell ?","back":"**Nourrisson** surtout, **pas d'érosion muqueuse**, décollement superficiel (sous-corné), souvent péri-orificiel et des grands plis ; bon pronostic sous antibiotiques.","prio":"P2","sec":"s9"},{"id":"fc-d115-0d2052","poly":"dermato","fiche":"d115","front":"Dermatose bulleuse auto-immune : comment la distinguer du Lyell ?","back":"**Pas de nécrose** de l'épiderme ; **dépôts d'anticorps** en IFD.","prio":"P3","sec":"s9"},{"id":"fc-d115-c642fb","poly":"dermato","fiche":"d115","front":"Brûlure : comment la distinguer du Lyell ?","back":"**Pas de lésion muqueuse** ; nécrose cutanée de profondeur variable.","prio":"P3","sec":"s9"},{"id":"fc-d115-b3d03c","poly":"dermato","fiche":"d115","front":"PEAG : quel diagnostic différentiel et comment l'écarter ?","back":"**Psoriasis pustuleux généralisé** : début moins brutal, évolution plus prolongée, antécédents de psoriasis.","prio":"P3","sec":"s9"},{"id":"fc-d115-66990c","poly":"dermato","fiche":"d115","front":"DRESS : quels diagnostics différentiels ?","back":"**Autres érythrodermies** (psoriasis, eczéma, lymphomes T épidermotropes) et **syndromes hyperéosinophiliques** (début habituellement moins aigu).","prio":"P3","sec":"s9"},{"id":"fc-d115-62890f","poly":"dermato","fiche":"d115","front":"Imputabilité intrinsèque : sur quels éléments repose-t-elle ?","back":"**Chronologie**, **sémiologie**, **facteurs favorisants**, élimination des autres causes, **tests**.","prio":"P1","sec":"s10"},{"id":"fc-d115-769a19","poly":"dermato","fiche":"d115","front":"Imputabilité extrinsèque : sur quoi repose-t-elle ?","back":"La **notoriété** : accidents identiques décrits dans la littérature ou les banques de pharmacovigilance.","prio":"P1","sec":"s10"},{"id":"fc-d115-a5c12b","poly":"dermato","fiche":"d115","front":"Toxidermie : quels pièges d'interrogatoire sur les médicaments ?","back":"Oubli de ce que le patient ne considère pas comme médicament : **antalgiques/somnifères occasionnels**, **édulcorants**, médecines parallèles.","prio":"P2","sec":"s10"},{"id":"fc-d115-5c4636","poly":"dermato","fiche":"d115","front":"Éruption sous antibiotique pour une infection : quel piège ?","back":"Attribuer à tort l'éruption au médicament alors que l'**infection elle-même** peut en être responsable.","prio":"P2","sec":"s10"},{"id":"fc-d115-bbad62","poly":"dermato","fiche":"d115","front":"Imputabilité chronologique : quels éléments évolutifs plaident pour le médicament ?","back":"**Amélioration à l'arrêt** ou **aggravation** si on poursuit.","prio":"P2","sec":"s10"},{"id":"fc-d115-c9ecde","poly":"dermato","fiche":"d115","front":"Toxidermie : quand l'imputabilité devient-elle très vraisemblable ?","back":"Récidive après **reprise accidentelle**, ou antécédent de **réaction semblable** avec ce médicament.","prio":"P2","sec":"s10"},{"id":"fc-d115-5e5490","poly":"dermato","fiche":"d115","front":"Toxidermie : une réintroduction à visée diagnostique est-elle justifiée ?","back":"**Non**, elle n'est pas justifiée.","prio":"P1","sec":"s10"},{"id":"fc-d115-e934bc","poly":"dermato","fiche":"d115","front":"Imputabilité sémiologique : quel tableau est le plus en faveur d'une origine médicamenteuse ?","back":"L'**érythème pigmenté fixe** (Stevens-Johnson, Lyell et PEAG l'évoquent aussi).","prio":"P2","sec":"s10"},{"id":"fc-d115-2d235c","poly":"dermato","fiche":"d115","front":"Toxidermie : quels tests allergologiques sont validés ?","back":"Les **prick tests**, pour l'hypersensibilité immédiate à la **pénicilline** ou aux **curarisants**.","prio":"P2","sec":"s10"},{"id":"fc-d115-160e5f","poly":"dermato","fiche":"d115","front":"Notoriété d'un médicament : quelle limite comme argument d'imputabilité ?","back":"Argument fort chez le polymédiqué mais seulement **probabiliste**, délicat à appliquer à un individu.","prio":"P3","sec":"s10"},{"id":"fc-d115-14504e","poly":"dermato","fiche":"d115","front":"Mononucléose infectieuse traitée par aminopénicilline : quel risque d'éruption ?","back":"Éruption **presque constante** (exanthème « à l'ampicilline ») : la mononucléose est un **facteur favorisant** de toxidermie.","prio":"P2","sec":"s10"},{"id":"fc-d115-e8425d","poly":"dermato","fiche":"d115","front":"Exanthème sous aminopénicilline au cours d'une mononucléose : quelle conséquence ?","back":"Pas de contre-indication à vie : **réintroduction possible** après guérison de la mononucléose.","prio":"P2","sec":"s10"},{"id":"fc-d115-dc105e","poly":"dermato","fiche":"d115","front":"Toxidermie : le Collège décrit-il un traitement médicamenteux spécifique des formes graves ?","back":"**Non** : arrêt du médicament, évaluation de la gravité, imputabilité, contre-indication écrite, déclaration.","prio":"P2","sec":"s11"},{"id":"fc-d115-a27ff2","poly":"dermato","fiche":"d115","front":"Toxidermie : quelle surveillance après l'arrêt du médicament ?","back":"**Réévaluer la gravité** : l'apparition secondaire d'un signe de gravité impose l'hospitalisation.","prio":"P2","sec":"s11"},{"id":"fc-d115-6f0b3a","poly":"dermato","fiche":"d115","front":"Toxidermie : quelles mesures à la sortie ?","back":"**Contre-indication écrite** (patient, carnet de santé/DMP, correspondants) jusqu'au **bilan allergologique** + **déclaration de pharmacovigilance**.","prio":"P1","sec":"s16"},{"id":"fc-d115-3ff0c9","poly":"dermato","fiche":"d115","front":"Toxidermie : jusqu'à quand maintenir la contre-indication écrite ?","back":"Jusqu'à la réalisation d'un **bilan allergologique**.","prio":"P2","sec":"s16"},{"id":"fc-d115-e7d346","poly":"dermato","fiche":"d115","front":"Toxidermie : quels sont les 5 temps de la conduite à tenir ?","back":"**G**ravité → **A**rrêt → **I**mputabilité → **É**crit (contre-indication) → **D**éclaration.","prio":"P1","sec":"s16"},{"id":"fc-d115-cfff29","poly":"dermato","fiche":"d115","front":"Urticaire médicamenteuse sans atteinte muqueuse : quel traitement symptomatique ?","back":"**Antihistaminique H1 de 2ᵉ génération**, 1 cp/j, pendant **1 à 2 semaines** (injectable si poussée intense).","prio":"P1","sec":"s13"},{"id":"fc-d115-9a4919","poly":"dermato","fiche":"d115","front":"Urticaire médicamenteuse : que surveiller ?","back":"L'apparition de **signes d'anaphylaxie** (respiratoires, cardiovasculaires, digestifs).","prio":"P2","sec":"s13"},{"id":"fc-d115-284f4b","poly":"dermato","fiche":"d115","front":"Œdème laryngé ou anaphylaxie médicamenteuse : quel traitement de référence ?","back":"L'**adrénaline intramusculaire**.","prio":"P1","sec":"s13"},{"id":"fc-d115-471998","poly":"dermato","fiche":"d115","front":"Anaphylaxie : quelle dose d'adrénaline IM ?","back":"**0,01 mg/kg**, sans dépasser **0,5 mg** ; à répéter après **5-15 min** si nécessaire.","prio":"P1","sec":"s13"},{"id":"fc-d115-12abb4","poly":"dermato","fiche":"d115","front":"Anaphylaxie : sous quelle surveillance administrer l'adrénaline ?","back":"Surveillance de l'**ECG** et de la **pression artérielle**.","prio":"P2","sec":"s13"},{"id":"fc-d115-81d640","poly":"dermato","fiche":"d115","front":"Choc anaphylactique ou arrêt cardiaque : quelle voie pour l'adrénaline ?","back":"**Intraveineuse**, titrée sur la pression artérielle et la fréquence cardiaque.","prio":"P1","sec":"s13"},{"id":"fc-d115-28a6e0","poly":"dermato","fiche":"d115","front":"Anaphylaxie : quelles mesures associées à l'adrénaline ?","back":"**Oxygène 6-8 L/min**, **remplissage** au sérum salé isotonique, aérosol de **bêta-2-mimétiques** si crise d'asthme.","prio":"P1","sec":"s13"},{"id":"fc-d115-1f9da0","poly":"dermato","fiche":"d115","front":"Anaphylaxie : à partir de quel grade traite-t-on par adrénaline ?","back":"Anaphylaxie **≥ grade II** (ou angiœdème laryngé).","prio":"P2","sec":"s13"},{"id":"fc-d115-c2d3d0","poly":"dermato","fiche":"d115","front":"Biomédicaments (anti-TNFα) : quels deux types de réactions cutanées ?","back":"**Hypersensibilité aiguë** (anaphylactoïde) et **réaction psoriasiforme paradoxale** retardée.","prio":"P3","sec":"s15"},{"id":"fc-d115-67bc0d","poly":"dermato","fiche":"d115","front":"Réaction aiguë à la perfusion d'un biomédicament : quelles caractéristiques ?","back":"**Transitoire**, souvent modérée (prurit, urticaire), possible **dès la première perfusion**.","prio":"P3","sec":"s15"},{"id":"fc-d115-c3ca08","poly":"dermato","fiche":"d115","front":"Réaction aiguë à la perfusion d'un biomédicament : quelle conduite ?","back":"**Réduire le débit de perfusion**.","prio":"P2","sec":"s15"},{"id":"fc-d115-f2118e","poly":"dermato","fiche":"d115","front":"Réaction psoriasiforme paradoxale : chez quelle proportion de patients sous biomédicaments ?","back":"**5 %** des patients (surtout anti-TNFα).","prio":"P3","sec":"s15"},{"id":"fc-d115-bb15ef","poly":"dermato","fiche":"d115","front":"Réaction psoriasiforme paradoxale : pourquoi « paradoxale » ?","back":"Le biomédicament induit une toxidermie qui **mime la maladie qu'il traite** (ex. pustulose palmo-plantaire sous anti-TNF).","prio":"P3","sec":"s15"},{"id":"fc-d115-f9999a","poly":"dermato","fiche":"d115","front":"Réaction psoriasiforme paradoxale : quel délai d'apparition ?","back":"Très variable : **quelques semaines à plusieurs mois**.","prio":"P3","sec":"s15"},{"id":"fc-d115-de5db5","poly":"dermato","fiche":"d115","front":"Lupus induit : quels auto-anticorps sont surtout induits ?","back":"**Anti-histones** et **anti-ADN dénaturé** (beaucoup plus rarement anti-ADN natif ou anti-ENA).","prio":"P2","sec":"s15"},{"id":"fc-d115-2041c1","poly":"dermato","fiche":"d115","front":"Lupus induit : quelles manifestations cliniques ?","back":"Assez rarement, signes **généraux et articulaires** proches d'un lupus ; **signes cutanés rares**.","prio":"P3","sec":"s15"},{"id":"fc-d115-31c3d8","poly":"dermato","fiche":"d115","front":"Lupus induit : quelle conduite et quelle évolution ?","back":"**Arrêt** du médicament inducteur ; normalisation clinique en général en **quelques semaines**.","prio":"P3","sec":"s15"},{"id":"fc-d116-1f3bf1","poly":"dermato","fiche":"d116","front":"Prurit : définition ?","back":"**Signe fonctionnel** : sensation qui provoque le **besoin de se gratter** ; localisé ou généralisé.","prio":"P1","sec":"s1"},{"id":"fc-d116-09b4ba","poly":"dermato","fiche":"d116","front":"Prurit : quels territoires peut-il toucher ?","back":"Uniquement la **peau** et certaines **muqueuses ou semi-muqueuses**.","prio":"P2","sec":"s1"},{"id":"fc-d116-fad729","poly":"dermato","fiche":"d116","front":"Prurit physiologique : quelles caractéristiques ?","back":"**Discret**, plus marqué **le soir** ou **au déshabillage**, sans vraie gêne.","prio":"P3","sec":"s1"},{"id":"fc-d116-3fdd42","poly":"dermato","fiche":"d116","front":"Prurit : à partir de quand est-il pathologique ?","back":"S'il entraîne des **lésions de grattage** ou retentit sur les **activités quotidiennes** ou le **sommeil**.","prio":"P1","sec":"s1"},{"id":"fc-d116-b7e844","poly":"dermato","fiche":"d116","front":"Prurit sine materia : définition ?","back":"Prurit **diffus sans lésion cutanée spécifique** : seules des lésions de **grattage** (prurigo compris).","prio":"P1","sec":"s1"},{"id":"fc-d116-99cc5e","poly":"dermato","fiche":"d116","front":"Prurit aquagénique : définition ?","back":"Prurit **aussitôt après un contact avec l'eau**, **quelle que soit sa température**, sans aucun autre signe.","prio":"P1","sec":"s1"},{"id":"fc-d116-1e0151","poly":"dermato","fiche":"d116","front":"Prurit : l'histamine est-elle toujours en cause ?","back":"**Non** : mécanismes complexes, l'histamine intervient **parfois mais pas toujours**.","prio":"P2","sec":"s1"},{"id":"fc-d116-41db49","poly":"dermato","fiche":"d116","front":"Prurit : quelles origines possibles sur les voies de transmission ?","back":"**Cutanée**, ou nerveuse : système nerveux **périphérique** ou **central**.","prio":"P3","sec":"s1"},{"id":"fc-d116-5fe483","poly":"dermato","fiche":"d116","front":"Prurit : sur quoi repose le diagnostic positif ?","back":"Diagnostic **clinique**, fondé sur l'**interrogatoire**, conforté par des lésions de grattage **non spécifiques**.","prio":"P1","sec":"s2"},{"id":"fc-d116-782115","poly":"dermato","fiche":"d116","front":"Prurit : quelles lésions de grattage élémentaires ?","back":"**Excoriations**, **stries linéaires**, **ulcérations**.","prio":"P2","sec":"s2"},{"id":"fc-d116-eacd52","poly":"dermato","fiche":"d116","front":"Prurigo : définition ?","back":"Lésions **papulo-vésiculeuses**, papules excoriées ou croûteuses, ou **nodules**, secondaires à un prurit **chronique**.","prio":"P1","sec":"s2"},{"id":"fc-d116-b81990","poly":"dermato","fiche":"d116","front":"Lichénification : quel aspect ?","back":"Peau **épaissie**, **grisâtre**, fines squames en **quadrillage**, due à un prurit **chronique**.","prio":"P1","sec":"s2"},{"id":"fc-d116-3a30c2","poly":"dermato","fiche":"d116","front":"Prurit : quelles surinfections des lésions de grattage ?","back":"**Impétigo**, **pyodermite**.","prio":"P2","sec":"s2"},{"id":"fc-d116-981210","poly":"dermato","fiche":"d116","front":"Prurit : quels diagnostics différentiels sensitifs ?","back":"**Dysesthésies**, **paresthésies**, **douleur**.","prio":"P2","sec":"s2"},{"id":"fc-d116-098852","poly":"dermato","fiche":"d116","front":"Prurit : quelles lésions orientent vers une dermatose causale ?","back":"Les lésions **non expliquées par le grattage** (les lésions de grattage ne donnent pas la cause).","prio":"P1","sec":"s2"},{"id":"fc-d116-f0c95e","poly":"dermato","fiche":"d116","front":"Prurit : quels éléments de sévérité préciser à l'interrogatoire ?","back":"**Insomnie**, troubles du comportement, retentissement sur l'**état général**, gêne au **travail** ou dans la vie quotidienne.","prio":"P2","sec":"s3"},{"id":"fc-d116-8efecc","poly":"dermato","fiche":"d116","front":"Prurit : quelles circonstances rechercher à l'interrogatoire ?","back":"Déclenchants/aggravants (**hypersudation**, **repas**, **douche**), soulageants (**bains froids**), **horaires**.","prio":"P3","sec":"s3"},{"id":"fc-d116-970f2b","poly":"dermato","fiche":"d116","front":"Prurit : quels éléments de contexte ne pas oublier à l'interrogatoire ?","back":"**Métier**, **médicaments**, **traitements locaux**, caractère **collectif**.","prio":"P1","sec":"s3"},{"id":"fc-d116-b8b9c8","poly":"dermato","fiche":"d116","front":"Prurit : quelle évolution et quels signes associés préciser ?","back":"Évolution **aiguë**, **paroxystique** ou **chronique** ; **signes généraux**.","prio":"P3","sec":"s3"},{"id":"fc-d116-744427","poly":"dermato","fiche":"d116","front":"Prurit : quels signes extra-cutanés rechercher à l'examen physique ?","back":"**Adénopathies** périphériques, **hépatomégalie**, **splénomégalie**.","prio":"P1","sec":"s3"},{"id":"fc-d116-7ec1f2","poly":"dermato","fiche":"d116","front":"Prurit : quel signe cutané induit par le frottement rechercher à l'examen ?","back":"Un **dermographisme**.","prio":"P2","sec":"s3"},{"id":"fc-d116-cefbad","poly":"dermato","fiche":"d116","front":"Prurit : quelles deux questions structurent l'arbre décisionnel ?","back":"**Localisé ou diffus ?** puis, si diffus, **lésions cutanées spécifiques ou non** (dermatose vs affection générale).","prio":"P1","sec":"s3"},{"id":"fc-d116-7641fb","poly":"dermato","fiche":"d116","front":"Prurit généralisé avec lésions spécifiques : principales causes ?","back":"**Urticaire**, eczéma de contact, **dermatite atopique**, **ectoparasitoses**, psoriasis, lichen plan, pemphigoïde bulleuse.","prio":"P1","sec":"s3"},{"id":"fc-d116-90010d","poly":"dermato","fiche":"d116","front":"Prurit généralisé sine materia : principales causes ?","back":"**Cholestase**, **insuffisance rénale chronique**, **hémopathies**, **dysthyroïdies**, **carence martiale**, **médicaments**.","prio":"P1","sec":"s3"},{"id":"fc-d116-a231c6","poly":"dermato","fiche":"d116","front":"Prurit localisé : principales causes ?","back":"**Mycoses**, **parasitoses**, **piqûres**, autres selon la topographie.","prio":"P2","sec":"s3"},{"id":"fc-d116-eef7f6","poly":"dermato","fiche":"d116","front":"Prurit avec dermatose : qu'est-ce qui donne le diagnostic ?","back":"Les **lésions élémentaires** (cliniques et/ou histologiques).","prio":"P2","sec":"s4"},{"id":"fc-d116-598591","poly":"dermato","fiche":"d116","front":"Prurit diffus : citer des dermatoses prurigineuses principales ?","back":"**Urticaire**/dermographisme, dermatites de **contact**, dermatite **atopique**, **ectoparasitoses**, piqûres, **psoriasis**, lichen plan, pemphigoïde, dermatophytoses, mycosis fongoïde/Sézary.","prio":"P2","sec":"s4"},{"id":"fc-d116-7f542b","poly":"dermato","fiche":"d116","front":"Gale : quelles caractéristiques du prurit ?","back":"**Recrudescence nocturne**, **épargne le visage** ; **sillons scabieux**.","prio":"P1","sec":"s4"},{"id":"fc-d116-4bbb4b","poly":"dermato","fiche":"d116","front":"Gale : quel contexte est très évocateur ?","back":"Un prurit **collectif** chez des personnes vivant **sous le même toit**.","prio":"P1","sec":"s4"},{"id":"fc-d116-f2ab68","poly":"dermato","fiche":"d116","front":"Pédiculose corporelle : quelle topographie et quel terrain ?","back":"Prurit diffus surtout **tronc** et **racine des membres** ; personnes en **précarité**.","prio":"P2","sec":"s4"},{"id":"fc-d116-57fe27","poly":"dermato","fiche":"d116","front":"Urticaire : quel aspect des lésions ?","back":"Papules **œdémateuses rosées**, **fugaces**, **migratrices**, **récidivantes**.","prio":"P1","sec":"s4"},{"id":"fc-d116-5131fa","poly":"dermato","fiche":"d116","front":"Dermographisme urticarien : définition ?","back":"Papule urticarienne déclenchée par le **frottement** de la peau.","prio":"P2","sec":"s4"},{"id":"fc-d116-5fb93e","poly":"dermato","fiche":"d116","front":"Eczéma / dermatite atopique : quelles lésions ?","back":"Lésions **érythémato-vésiculeuses** qui s'étendent progressivement (contact allergénique ou constitutionnelle).","prio":"P2","sec":"s4"},{"id":"fc-d116-6459f5","poly":"dermato","fiche":"d116","front":"Psoriasis : est-il prurigineux ?","back":"**Oui** : lésions prurigineuses chez **environ 60 %** des patients (contrairement à une idée classique).","prio":"P1","sec":"s4"},{"id":"fc-d116-91817f","poly":"dermato","fiche":"d116","front":"Pemphigoïde, dermatite herpétiforme : quelles caractéristiques du prurit ?","back":"**Fréquent**, souvent **sévère**, peut **précéder** les lésions ; intérêt de l'**IFD** chez le sujet âgé.","prio":"P1","sec":"s4"},{"id":"fc-d116-84dcbb","poly":"dermato","fiche":"d116","front":"Lichen plan : quel aspect des papules ?","back":"Papules **brunâtres ou violines** couvertes de **fines stries blanchâtres en réseau**, souvent symétriques.","prio":"P2","sec":"s4"},{"id":"fc-d116-95c538","poly":"dermato","fiche":"d116","front":"Lichen plan : quelle topographie typique ?","back":"Face antérieure des **poignets**, avant-bras, coudes, genoux, région **lombaire**.","prio":"P3","sec":"s4"},{"id":"fc-d116-f45691","poly":"dermato","fiche":"d116","front":"Lichen plan : quelle histologie ?","back":"Infiltrat dermique superficiel **en bande**.","prio":"P3","sec":"s4"},{"id":"fc-d116-e9f282","poly":"dermato","fiche":"d116","front":"Lichen plan buccal : aspect et prurit ?","back":"Lésions **blanches réticulées**, érythémateuses ou érosives, **non prurigineuses**.","prio":"P3","sec":"s4"},{"id":"fc-d116-9460ed","poly":"dermato","fiche":"d116","front":"Mycosis fongoïde : de quoi s'agit-il et à quel âge ?","back":"**Lymphome cutané T épidermotrope**, le plus souvent **après 50 ans**.","prio":"P2","sec":"s4"},{"id":"fc-d116-684271","poly":"dermato","fiche":"d116","front":"Mycosis fongoïde : quelle évolution clinique ?","back":"Placards **érythémato-squameux** prurigineux, puis **infiltration** de la peau avec prurit important et **insomniant**.","prio":"P3","sec":"s4"},{"id":"fc-d116-76bee9","poly":"dermato","fiche":"d116","front":"Syndrome de Sézary : définition ?","back":"Forme **érythrodermique et leucémique** du lymphome cutané T épidermotrope.","prio":"P2","sec":"s4"},{"id":"fc-d116-3fc188","poly":"dermato","fiche":"d116","front":"Mastocytose cutanée : quelle forme est la plus fréquente chez l'enfant ?","back":"L'**urticaire pigmentaire** (macules ou papules pigmentées).","prio":"P3","sec":"s4"},{"id":"fc-d116-ded63a","poly":"dermato","fiche":"d116","front":"Prurit sine materia : causes générales plus ou moins fréquentes que les dermatologiques ?","back":"**Plus rares** que les causes dermatologiques, mais à chercher quand la peau est « nue ».","prio":"P2","sec":"s5"},{"id":"fc-d116-865f83","poly":"dermato","fiche":"d116","front":"Cholestase responsable de prurit : quel siège et faut-il un ictère ?","back":"Cholestase **intra- ou extra-hépatique**, **avec ou sans ictère**.","prio":"P2","sec":"s5"},{"id":"fc-d116-3afb13","poly":"dermato","fiche":"d116","front":"Prurit : quelle maladie hépatique révèle-t-il souvent ?","back":"La **cirrhose biliaire primitive**.","prio":"P1","sec":"s5"},{"id":"fc-d116-9b2b80","poly":"dermato","fiche":"d116","front":"Prurit intense et insomniant avec ictère obstructif : quelles causes évoquer ?","back":"**Cancer du pancréas** ou **des voies biliaires**.","prio":"P2","sec":"s5"},{"id":"fc-d116-57add0","poly":"dermato","fiche":"d116","front":"Insuffisance rénale chronique : place du prurit ?","back":"**Rarement révélateur**, mais **très fréquent** chez l'**hémodialysé**.","prio":"P1","sec":"s5"},{"id":"fc-d116-ae3f13","poly":"dermato","fiche":"d116","front":"Prurit nu et chronique de l'adulte jeune : quelle cause évoquer ?","back":"Un **lymphome** (hodgkinien ou non hodgkinien).","prio":"P1","sec":"s5"},{"id":"fc-d116-f6611a","poly":"dermato","fiche":"d116","front":"Prurit sine materia : quelle est la cause la plus grave ?","back":"La **maladie de Hodgkin**.","prio":"P1","sec":"s5"},{"id":"fc-d116-467270","poly":"dermato","fiche":"d116","front":"Prurit sine materia : quelle est la cause la moins grave ?","back":"La **xérose** (sécheresse cutanée).","prio":"P1","sec":"s5"},{"id":"fc-d116-b46c79","poly":"dermato","fiche":"d116","front":"Prurit des lymphomes : quelles caractéristiques ?","back":"**Fréquent**, de **pronostic défavorable**, **suit l'évolution** de la maladie.","prio":"P2","sec":"s5"},{"id":"fc-d116-75362d","poly":"dermato","fiche":"d116","front":"Quelle polyglobulie est une hémopathie maligne cause de prurit nu ?","back":"La **maladie de Vaquez**.","prio":"P1","sec":"s5"},{"id":"fc-d116-b47f2b","poly":"dermato","fiche":"d116","front":"Maladie de Vaquez : quel type de prurit typique ?","back":"Prurit **aquagénique**, surtout lors des **bains chauds**.","prio":"P2","sec":"s5"},{"id":"fc-d116-6565fa","poly":"dermato","fiche":"d116","front":"Prurit nu : quelles autres hémopathies et carences citer ?","back":"**Leucémie lymphoïde chronique**, **anémie ferriprive** ; carences **martiale** et **vitaminiques**.","prio":"P2","sec":"s5"},{"id":"fc-d116-805d06","poly":"dermato","fiche":"d116","front":"Dysthyroïdies et prurit : lesquelles ?","back":"**Hyperthyroïdie** (surtout Basedow) et **hypothyroïdie** (prurit probablement lié à la **sécheresse cutanée**).","prio":"P2","sec":"s5"},{"id":"fc-d116-b279de","poly":"dermato","fiche":"d116","front":"Prurit nu : quelles infections chroniques rechercher ?","back":"**VIH**, **VHB**, **VHC**.","prio":"P1","sec":"s5"},{"id":"fc-d116-258d62","poly":"dermato","fiche":"d116","front":"Parasitoses internes et prurit : quel mécanisme et quel signe biologique ?","back":"**Migration tissulaire** avec **hyperéosinophilie** ; prurit et éruptions fugaces.","prio":"P2","sec":"s5"},{"id":"fc-d116-1d1609","poly":"dermato","fiche":"d116","front":"Parasitoses internes prurigineuses rencontrées en France : lesquelles ?","back":"**Ascaridiose**, **toxocarose**, **trichinose**.","prio":"P3","sec":"s5"},{"id":"fc-d116-9d029e","poly":"dermato","fiche":"d116","front":"Médicaments : par quels trois mécanismes donnent-ils un prurit ?","back":"Effet **pharmacologique** (opiacés…), **cholestase** induite, **allergie** (alors avec lésions cutanées).","prio":"P1","sec":"s5"},{"id":"fc-d116-c92f58","poly":"dermato","fiche":"d116","front":"Prurit sine materia sans cause évidente : quel bilan de 1re intention ?","back":"**NFS-plaquettes**, **γGT + PAL**, **créatininémie**, **TSH**, **ferritine**, **EPP**, sérologies **VIH/VHB/VHC**, **radio de thorax**.","prio":"P1","sec":"s5"},{"id":"fc-d116-298ab9","poly":"dermato","fiche":"d116","front":"Prurit sine materia : la biopsie cutanée est-elle indiquée ?","back":"**Non**, la biopsie cutanée **n'est pas indiquée**.","prio":"P1","sec":"s5"},{"id":"fc-d116-785445","poly":"dermato","fiche":"d116","front":"Xérose : quel rôle dans le prurit ?","back":"**Souvent** facteur favorisant de prurits de cause externe, notamment chez la **personne âgée**.","prio":"P2","sec":"s5"},{"id":"fc-d116-532312","poly":"dermato","fiche":"d116","front":"Prurit : quels produits d'environnement favorisent ou aggravent ?","back":"Produits **irritants ou caustiques** et produits d'hygiène **mal rincés**, surtout **parfumés** (antiseptique…).","prio":"P3","sec":"s5"},{"id":"fc-d116-cf7998","poly":"dermato","fiche":"d116","front":"Prurit aquagénique : quelle cause éliminer systématiquement ?","back":"Une **hémopathie**, en particulier une **polyglobulie de Vaquez**.","prio":"P2","sec":"s5"},{"id":"fc-d116-a98e79","poly":"dermato","fiche":"d116","front":"Prurit : quelles affections neurologiques centrales peuvent en donner ?","back":"Des lésions **cérébrales** ou **médullaires** (plusieurs maladies du SNC).","prio":"P3","sec":"s5"},{"id":"fc-d116-4635f2","poly":"dermato","fiche":"d116","front":"Diabète, goutte, hyperuricémie : sont-ils causes de prurit diffus ?","back":"**Non** ; le diabète donne plutôt des **paresthésies**.","prio":"P1","sec":"s5"},{"id":"fc-d116-08e83d","poly":"dermato","fiche":"d116","front":"Prurit nu : faut-il rechercher systématiquement un cancer profond ?","back":"**Non**, sans signe clinique d'orientation : l'origine **paranéoplasique** est **très exceptionnelle**.","prio":"P1","sec":"s5"},{"id":"fc-d116-78d9bd","poly":"dermato","fiche":"d116","front":"Prurit localisé : peut-il révéler une dermatose ?","back":"**Oui** : de nombreuses dermatoses donnent un prurit localisé, au moins **au début** de leur évolution.","prio":"P2","sec":"s6"},{"id":"fc-d116-c65a65","poly":"dermato","fiche":"d116","front":"Prurit de la nuque ou du cuir chevelu : quelle ectoparasitose et quel terrain ?","back":"**Pédiculose**, surtout chez l'**enfant** ou les personnes **sans domicile fixe**.","prio":"P2","sec":"s6"},{"id":"fc-d116-5613e3","poly":"dermato","fiche":"d116","front":"Gale : où siègent les lésions non spécifiques ?","back":"**Espaces interdigitaux**, **poignets**, emmanchures antérieures, **mamelons**, organes génitaux externes.","prio":"P2","sec":"s6"},{"id":"fc-d116-2d52a6","poly":"dermato","fiche":"d116","front":"Helminthiases tropicales : que rechercher après un séjour en zone d'endémie ?","back":"Une **hyperéosinophilie** et une **larva migrans cutanée**.","prio":"P3","sec":"s6"},{"id":"fc-d116-25fcfc","poly":"dermato","fiche":"d116","front":"Larva migrans cutanée : quel aspect et quelle topographie ?","back":"Éruption **serpigineuse**, prurigineuse et **mobile**, sur les zones en contact avec le **sol** (mains, pieds, fesses).","prio":"P3","sec":"s6"},{"id":"fc-d116-071828","poly":"dermato","fiche":"d116","front":"Dermatite des nageurs : quel tableau ?","back":"**Macules érythémateuses prurigineuses** quelques heures après un bain en **étang** (parasites d'oiseaux) ou en mer ; disparaissent en quelques jours.","prio":"P3","sec":"s6"},{"id":"fc-d116-bd4ecb","poly":"dermato","fiche":"d116","front":"Piqûres d'insectes et végétaux : quel type de prurit ?","back":"Prurit **saisonnier** avec lésions **urticariennes**, parfois centrées par un point **purpurique** ou **nécrotique**.","prio":"P3","sec":"s6"},{"id":"fc-d116-f043da","poly":"dermato","fiche":"d116","front":"Prurit du cuir chevelu : quelle cause rechercher systématiquement ?","back":"Une **pédiculose**.","prio":"P1","sec":"s6"},{"id":"fc-d116-8dcb56","poly":"dermato","fiche":"d116","front":"Prurit du cuir chevelu : autres causes que les poux ?","back":"Intolérance/eczéma de contact aux **produits capillaires**, état **pelliculaire**, **psoriasis**, **dermatite séborrhéique**, lichénification de la nuque.","prio":"P3","sec":"s6"},{"id":"fc-d116-0a5fc3","poly":"dermato","fiche":"d116","front":"« Névrodermite » : de quoi s'agit-il ?","back":"Une **lichénification de la nuque**.","prio":"P3","sec":"s6"},{"id":"fc-d116-fbc9c1","poly":"dermato","fiche":"d116","front":"Infection par le VIH : quelles caractéristiques du prurit ?","back":"**Fréquent**, **isolé** ou avec **éruption papuleuse** ; peut être l'occasion du **diagnostic**.","prio":"P1","sec":"s7"},{"id":"fc-d116-ef81d4","poly":"dermato","fiche":"d116","front":"Cholestase intra-hépatique de la grossesse : quel prurit ?","back":"Prurit **généralisé**, **sévère**, **nu**.","prio":"P2","sec":"s7"},{"id":"fc-d116-ad5434","poly":"dermato","fiche":"d116","front":"Cholestase intra-hépatique de la grossesse : quel examen la confirme ?","back":"**Élévation des sels biliaires** sanguins, avec ou sans cytolyse.","prio":"P2","sec":"s7"},{"id":"fc-d116-5c289e","poly":"dermato","fiche":"d116","front":"Grossesse : quelles dermatoses prurigineuses spécifiques citer ?","back":"**Pemphigoïde de la grossesse** (DBAI propre à la grossesse) et **éruption polymorphe de la grossesse**.","prio":"P3","sec":"s7"},{"id":"fc-d116-06d1b2","poly":"dermato","fiche":"d116","front":"Prurit « sénile » : à quoi est-il lié ?","back":"Au **vieillissement physiologique** de la peau et des **terminaisons nerveuses** ; fréquent.","prio":"P2","sec":"s7"},{"id":"fc-d116-5fe087","poly":"dermato","fiche":"d116","front":"Prurit du sujet âgé : quelles caractéristiques ?","back":"**Intense**, parfois **insomniant**, avec des lésions **discrètes** ; retentissement psychique (**dépression**).","prio":"P2","sec":"s7"},{"id":"fc-d116-5f0eb2","poly":"dermato","fiche":"d116","front":"Prurit psychogène : quel type de diagnostic ?","back":"Diagnostic **d'élimination** ; ce n'est **pas** un synonyme de prurit idiopathique.","prio":"P2","sec":"s7"},{"id":"fc-d116-40af06","poly":"dermato","fiche":"d116","front":"Prurit psychogène : que rechercher ?","back":"Pathologie psychiatrique (**dépression**, **cancérophobie**, **anxiété**) ou **événements stressants** déclenchants.","prio":"P3","sec":"s7"},{"id":"fc-d116-18d56a","poly":"dermato","fiche":"d116","front":"Prurit psychogène : quel argument conforte cette origine ?","back":"L'**efficacité du traitement psychiatrique**.","prio":"P3","sec":"s7"},{"id":"fc-d116-b7bc49","poly":"dermato","fiche":"d116","front":"Prurit nu : quelle démarche impose-t-il ?","back":"Rechercher une **affection générale**.","prio":"P1","sec":"s8"},{"id":"fc-d116-898dc8","poly":"dermato","fiche":"d116","front":"Prurit : existe-t-il un traitement général symptomatique ?","back":"**Non** : il n'existe **pas** de traitement général symptomatique ; traiter **la cause**.","prio":"P1","sec":"s9"},{"id":"fc-d116-e81f60","poly":"dermato","fiche":"d116","front":"Prurit d'origine interne : quel traitement ?","back":"Traiter la **maladie causale** (polyglobulie, maladie de Hodgkin…).","prio":"P1","sec":"s9"},{"id":"fc-d116-505024","poly":"dermato","fiche":"d116","front":"Prurit : comment gérer un médicament suspect ?","back":"L'**arrêter**, mais **après accord du prescripteur**.","prio":"P1","sec":"s9"},{"id":"fc-d116-2c20ae","poly":"dermato","fiche":"d116","front":"Prurit : quels irritants faire éviter ?","back":"**Antiseptiques**, **savons parfumés**, vêtements **serrés ou rêches**.","prio":"P2","sec":"s9"},{"id":"fc-d116-d622ee","poly":"dermato","fiche":"d116","front":"Prurit : quelle mesure simple limite les lésions de grattage ?","back":"**Couper les ongles court**.","prio":"P2","sec":"s9"},{"id":"fc-d116-a6bd72","poly":"dermato","fiche":"d116","front":"Prurit : quel piège thérapeutique initial éviter ?","back":"Prescrire un « **antiprurigineux** » **sans chercher la cause**.","prio":"P2","sec":"s9"},{"id":"fc-d116-6b760c","poly":"dermato","fiche":"d116","front":"Antihistaminiques : quand calment-ils le prurit ?","back":"**Seulement** si le prurit est **médié par l'histamine**, comme dans l'**urticaire**.","prio":"P1","sec":"s10"},{"id":"fc-d116-8ea141","poly":"dermato","fiche":"d116","front":"Prurit avec lésions spécifiques : quel traitement ?","back":"Traiter la **dermatose révélée** par le prurit (urticaire, eczéma, gale, psoriasis, mycoses, dermatoses bulleuses…).","prio":"P2","sec":"s10"},{"id":"fc-d116-3d5c55","poly":"dermato","fiche":"d116","front":"Prurit de cholestase : quelles molécules peuvent aider ?","back":"**Cholestyramine** ou **rifampicine**.","prio":"P1","sec":"s11"},{"id":"fc-d116-c261a0","poly":"dermato","fiche":"d116","front":"Prurit nu et chronique : quelles causes graves ne pas méconnaître ?","back":"Un **lymphome** (adulte jeune) et un **VIH** (prurit fréquent, pouvant révéler l'infection).","prio":"P1","sec":"s11"},{"id":"fc-d116-f1f2b9","poly":"dermato","fiche":"d116","front":"Lymphome : pourquoi le prurit est-il utile au suivi ?","back":"Il **suit l'évolution** de la maladie (et il est de mauvais pronostic).","prio":"P2","sec":"s11"},{"id":"fc-d116-8c1ee4","poly":"dermato","fiche":"d116","front":"Xérose : quel traitement symptomatique ?","back":"**Émollient** chaque jour sur **toute la peau**, après la toilette (cérat de Galien, cold-cream).","prio":"P2","sec":"s12"},{"id":"fc-d116-738a0b","poly":"dermato","fiche":"d116","front":"Prurit : quels produits de toilette privilégier ?","back":"**Savons surgras** et **syndets**.","prio":"P3","sec":"s12"},{"id":"fc-d116-d2535c","poly":"dermato","fiche":"d116","front":"Prurit : quand utiliser des dermocorticoïdes ?","back":"Sur les **lésions inflammatoires dues au grattage** ; **non recommandés** en cas de prurit **isolé**.","prio":"P2","sec":"s12"},{"id":"fc-d116-70981a","poly":"dermato","fiche":"d116","front":"Prurit : quelle photothérapie et à quelle condition ?","back":"**UVB**, après **avis dermatologique**.","prio":"P3","sec":"s12"},{"id":"fc-d116-0984e8","poly":"dermato","fiche":"d116","front":"Prurit insomniant : quels anti-H1 peut-on prescrire ?","back":"Anti-H1 de **1re génération** anxiolytiques et hypnotiques : **hydroxyzine**, **doxépine**, **le soir au coucher**.","prio":"P2","sec":"s12"},{"id":"fc-d117-00b469","poly":"dermato","fiche":"d117","front":"Psoriasis : définition ?","back":"Dermatose **inflammatoire** d'évolution **chronique**, à lésions **érythémato-squameuses**.","prio":"P1","sec":"s1"},{"id":"fc-d117-1aaac4","poly":"dermato","fiche":"d117","front":"Psoriasis : comment pose-t-on le diagnostic dans la très grande majorité des cas ?","back":"Diagnostic **clinique**.","prio":"P1","sec":"s1"},{"id":"fc-d117-b01131","poly":"dermato","fiche":"d117","front":"Psoriasis : quelle fréquence dans la population française ?","back":"Environ **2 %** (les points clés du chapitre disent **2 à 3 %**).","prio":"P2","sec":"s1"},{"id":"fc-d117-127a52","poly":"dermato","fiche":"d117","front":"Psoriasis : quelle anomalie du renouvellement épidermique ?","back":"Renouvellement **accéléré** : kératinocytes qui **prolifèrent trop** et se **différencient mal**.","prio":"P2","sec":"s1"},{"id":"fc-d117-53f074","poly":"dermato","fiche":"d117","front":"Psoriasis : que sait-on de son origine ?","back":"Origine **inconnue**, mais **prédisposition génétique certaine** (nombreux gènes de susceptibilité).","prio":"P2","sec":"s1"},{"id":"fc-d117-685f14","poly":"dermato","fiche":"d117","front":"Psoriasis : quels acteurs interagissent sur le terrain génétique ?","back":"**Système immunitaire**, **kératinocytes** et **vaisseaux**.","prio":"P3","sec":"s1"},{"id":"fc-d117-cc23a2","poly":"dermato","fiche":"d117","front":"Psoriasis : citer les déclencheurs de la cascade inflammatoire ?","back":"**Stress** · **traumatisme cutané** (Koebner) · certains **germes** · certains **médicaments**.","prio":"P2","sec":"s1"},{"id":"fc-d117-1d3aad","poly":"dermato","fiche":"d117","front":"Psoriasis : quel peptide antimicrobien pousse à sécréter l'interféron alpha ?","back":"La **cathélicidine** (**LL-37**).","prio":"P3","sec":"s1"},{"id":"fc-d117-3afade","poly":"dermato","fiche":"d117","front":"Psoriasis : quelles cytokines des kératinocytes activent les cellules dendritiques ?","back":"**IL-1β**, **IL-36**, **TNFα**.","prio":"P3","sec":"s1"},{"id":"fc-d117-03273b","poly":"dermato","fiche":"d117","front":"Psoriasis : quelles cytokines produisent les cellules dendritiques activées ?","back":"**IL-12** et **IL-23**.","prio":"P2","sec":"s1"},{"id":"fc-d117-938d03","poly":"dermato","fiche":"d117","front":"Psoriasis : vers quelles sous-populations l'IL-12 et l'IL-23 orientent-elles les lymphocytes T ?","back":"**Th1** (produisent l'**IFNγ**) et **Th17** (produisent l'**IL-17**).","prio":"P2","sec":"s1"},{"id":"fc-d117-bd6e22","poly":"dermato","fiche":"d117","front":"Psoriasis : quels effets locaux de l'IL-12, l'IL-17 et du TNFα ?","back":"**Prolifération** des kératinocytes · **néo-angiogenèse** · chimiokines recrutant les **polynucléaires neutrophiles**.","prio":"P3","sec":"s1"},{"id":"fc-d117-7fc9d0","poly":"dermato","fiche":"d117","front":"Psoriasis : la biopsie cutanée est-elle nécessaire ?","back":"**Habituellement non** ; elle peut aider.","prio":"P1","sec":"s1"},{"id":"fc-d117-e0021d","poly":"dermato","fiche":"d117","front":"Psoriasis : quelles anomalies épidermiques à l'histologie ?","back":"Hyperkératose avec **parakératose** ; **acanthose** ; **micro-abcès** à **polynucléaires neutrophiles**.","prio":"P3","sec":"s1"},{"id":"fc-d117-b6614c","poly":"dermato","fiche":"d117","front":"Psoriasis : quelles anomalies dermiques à l'histologie ?","back":"Infiltrat de **lymphocytes** ; papilles dermiques **allongées** ; vaisseaux néoformés **dilatés**.","prio":"P3","sec":"s1"},{"id":"fc-d117-b9aad4","poly":"dermato","fiche":"d117","front":"Psoriasis en gouttes de l'enfant : quelle infection peut précéder son début ?","back":"Infection **rhinopharyngée** (virus, **streptocoque β hémolytique du groupe A**), chez **certains** psoriasis de l'enfant et de l'adolescent.","prio":"P2","sec":"s2"},{"id":"fc-d117-3f107c","poly":"dermato","fiche":"d117","front":"Psoriasis et VIH : quel lien ?","back":"Apparition ou **aggravation** possible au cours de l'infection par le **VIH**.","prio":"P2","sec":"s2"},{"id":"fc-d117-ac7759","poly":"dermato","fiche":"d117","front":"Psoriasis : quelle classe médicamenteuse est inductrice ou aggravante, sous toutes ses formes ?","back":"**Bêtabloquants**, **collyres compris**.","prio":"P2","sec":"s2"},{"id":"fc-d117-cdb842","poly":"dermato","fiche":"d117","front":"Psoriasis : quels médicaments ont un rôle seulement débattu ?","back":"**Lithium** · **sartans** · **IEC** · **anti-TNFα**.","prio":"P3","sec":"s2"},{"id":"fc-d117-bc2c45","poly":"dermato","fiche":"d117","front":"Psoriasis : quel risque à l'arrêt d'une corticothérapie générale ?","back":"**Rebond** important, voire forme grave : **érythrodermique** ou **pustuleux généralisé**.","prio":"P2","sec":"s2"},{"id":"fc-d117-59192b","poly":"dermato","fiche":"d117","front":"Psoriasis : quel rôle des facteurs psychologiques ?","back":"Rôle **possible** dans le début ou les **poussées** (chocs émotionnels) ; le stress pourrait augmenter les neuromédiateurs pro-inflammatoires.","prio":"P3","sec":"s2"},{"id":"fc-d117-99debf","poly":"dermato","fiche":"d117","front":"Phénomène de Koebner : définition ?","back":"Aggravation du psoriasis sur un **traumatisme cutané** (griffure, vaccination, chirurgie, coup de soleil), par libération de cytokines par les kératinocytes.","prio":"P2","sec":"s2"},{"id":"fc-d117-dbe6d5","poly":"dermato","fiche":"d117","front":"Psoriasis : quels facteurs de gravité et de résistance au traitement ?","back":"**Alcool** · **tabac** · **surcharge pondérale** (participent aussi aux comorbidités).","prio":"P2","sec":"s2"},{"id":"fc-d117-fdfe43","poly":"dermato","fiche":"d117","front":"Psoriasis : lésion élémentaire ?","back":"Papule ou plaque **érythémato-squameuse bien limitée**, ronde, ovale ou polycyclique.","prio":"P1","sec":"s3"},{"id":"fc-d117-a5bf25","poly":"dermato","fiche":"d117","front":"Psoriasis : caractéristiques de la squame ?","back":"Superficielle, **blanchâtre**, parfois très **épaisse**.","prio":"P1","sec":"s3"},{"id":"fc-d117-f9fac2","poly":"dermato","fiche":"d117","front":"Psoriasis : que voit-on sous une plaque décapée par le traitement ?","back":"L'**érythème** sous-jacent.","prio":"P2","sec":"s3"},{"id":"fc-d117-f4c8a6","poly":"dermato","fiche":"d117","front":"Psoriasis : distribution des lésions ?","back":"Le plus souvent **multiples** et **symétriques**, parfois diffuses.","prio":"P1","sec":"s3"},{"id":"fc-d117-34f43d","poly":"dermato","fiche":"d117","front":"Psoriasis : selon la taille des lésions, quelles formes ?","back":"Psoriasis **en plaques** ou psoriasis **en gouttes**.","prio":"P2","sec":"s3"},{"id":"fc-d117-c20f54","poly":"dermato","fiche":"d117","front":"Psoriasis : citer les zones bastions ?","back":"**Coudes** (bord cubital) · **genoux**, jambes · **lombo-sacrée**, fesses · **cuir chevelu** · **ongles** · **paumes et plantes**.","prio":"P1","sec":"s3"},{"id":"fc-d117-f7dbe0","poly":"dermato","fiche":"d117","front":"Psoriasis : pourquoi ces zones bastions ?","back":"Zones exposées aux **frottements** et aux **traumatismes**.","prio":"P3","sec":"s3"},{"id":"fc-d117-2e5d2e","poly":"dermato","fiche":"d117","front":"Psoriasis classique : le visage est-il atteint ?","back":"**Habituellement respecté**.","prio":"P1","sec":"s3"},{"id":"fc-d117-ecc171","poly":"dermato","fiche":"d117","front":"Psoriasis classique : état général ?","back":"**Non altéré**.","prio":"P1","sec":"s3"},{"id":"fc-d117-479974","poly":"dermato","fiche":"d117","front":"Psoriasis : fréquence du prurit ?","back":"Présent lors des **poussées** dans environ **60 %** des cas.","prio":"P1","sec":"s3"},{"id":"fc-d117-2d1dc9","poly":"dermato","fiche":"d117","front":"Psoriasis : les lésions laissent-elles une cicatrice ?","back":"**Non** ; parfois macules **hyperpigmentées** ou **dépigmentées** après régression.","prio":"P2","sec":"s3"},{"id":"fc-d117-514db7","poly":"dermato","fiche":"d117","front":"Psoriasis : où la douleur et la gêne sont-elles surtout possibles ?","back":"**Paumes et plantes** (**fissures**).","prio":"P2","sec":"s3"},{"id":"fc-d117-1ec323","poly":"dermato","fiche":"d117","front":"Psoriasis : quand faire une biopsie cutanée ?","back":"Seulement en cas de **doute diagnostique** devant des lésions **atypiques**.","prio":"P1","sec":"s3"},{"id":"fc-d117-aa8758","poly":"dermato","fiche":"d117","front":"Psoriasis du cuir chevelu : quel aspect des plaques ?","back":"Plaques bien limitées à **larges squames épaisses traversées par les cheveux**, ou **carapace en casque**.","prio":"P1","sec":"s4"},{"id":"fc-d117-c73eaf","poly":"dermato","fiche":"d117","front":"Psoriasis du cuir chevelu : aspect à la lisière antérieure ?","back":"**Couronne** rouge peu squameuse.","prio":"P3","sec":"s4"},{"id":"fc-d117-7b533d","poly":"dermato","fiche":"d117","front":"Psoriasis du cuir chevelu : quel siège fréquent ?","back":"**Occipital**.","prio":"P3","sec":"s4"},{"id":"fc-d117-5cb834","poly":"dermato","fiche":"d117","front":"Psoriasis du cuir chevelu : entraîne-t-il une alopécie ?","back":"**Rarement durable** ; chute de cheveux **temporaire** possible.","prio":"P2","sec":"s4"},{"id":"fc-d117-ed2c93","poly":"dermato","fiche":"d117","front":"Psoriasis unguéal : quelles dépressions ponctuées ?","back":"Dépressions en **« dé à coudre »**.","prio":"P1","sec":"s4"},{"id":"fc-d117-83e80f","poly":"dermato","fiche":"d117","front":"Psoriasis unguéal : aspect de l'onycholyse ?","back":"Onycholyse **distale** avec zone proximale cuivrée « saumonée » ou jaunâtre en **« tache d'huile »**.","prio":"P1","sec":"s4"},{"id":"fc-d117-10b2ad","poly":"dermato","fiche":"d117","front":"Psoriasis unguéal : autres atteintes possibles ?","back":"**Hyperkératose sous-unguéale** · paronychie · perte de transparence · **leuconychie** ; à l'extrême, disparition de la tablette.","prio":"P2","sec":"s4"},{"id":"fc-d117-febc5d","poly":"dermato","fiche":"d117","front":"Psoriasis inversé : définition ?","back":"Psoriasis des **plis**.","prio":"P1","sec":"s4"},{"id":"fc-d117-602f60","poly":"dermato","fiche":"d117","front":"Psoriasis des plis : quel aspect ?","back":"Plaques rouges **vernissées**, **bien limitées**.","prio":"P1","sec":"s4"},{"id":"fc-d117-948b8f","poly":"dermato","fiche":"d117","front":"Psoriasis des plis : citer les localisations ?","back":"Pli **interfessier** · **aisselles** · **sous les seins** · **ombilic** · **aines**.","prio":"P2","sec":"s4"},{"id":"fc-d117-dcf5ea","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : quel aspect ?","back":"**Kératodermie** en îlots ou diffuse, souvent **fissuraire** ; parfois isolée.","prio":"P1","sec":"s4"},{"id":"fc-d117-8567ea","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : quel retentissement ?","back":"Douleurs et fissures gênant la **marche** ou les **activités manuelles**.","prio":"P2","sec":"s4"},{"id":"fc-d117-4ff9a8","poly":"dermato","fiche":"d117","front":"Psoriasis de la langue : quel aspect ?","back":"**Glossite exfoliatrice marginée**.","prio":"P2","sec":"s4"},{"id":"fc-d117-e20a43","poly":"dermato","fiche":"d117","front":"Psoriasis génital : quel aspect ?","back":"Lésions rouges **non squameuses**, aggravées par les **rapports sexuels**.","prio":"P2","sec":"s4"},{"id":"fc-d117-519f36","poly":"dermato","fiche":"d117","front":"Psoriasis du visage : fréquence et aspect ?","back":"**Rare** ; aspect de **dermatite séborrhéique** (sourcils, pli nasogénien finement squameux).","prio":"P1","sec":"s4"},{"id":"fc-d117-b10405","poly":"dermato","fiche":"d117","front":"Psoriasis du visage : quelles autres localisations possibles à la tête ?","back":"**Conque** de l'oreille et **conduit auditif externe**.","prio":"P3","sec":"s4"},{"id":"fc-d117-f8aba1","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : quelle forme pustuleuse possible ?","back":"Type **pustulose palmo-plantaire**, parfois avec atteinte articulaire **sternale** ou **sterno-claviculaire**.","prio":"P3","sec":"s4"},{"id":"fc-d117-deb96e","poly":"dermato","fiche":"d117","front":"Psoriasis : citer les trois formes graves ?","back":"**Érythrodermique** · **pustuleux généralisé** · **rhumatisme psoriasique**.","prio":"P2","sec":"s5"},{"id":"fc-d117-38b17a","poly":"dermato","fiche":"d117","front":"Psoriasis érythrodermique : définition ?","back":"Psoriasis étendu à **plus de 90 %** de la surface cutanée ; desquamation abondante, peau épaissie.","prio":"P2","sec":"s5"},{"id":"fc-d117-f45f3a","poly":"dermato","fiche":"d117","front":"Psoriasis érythrodermique : quelles complications ?","back":"**Surinfection** · carence **vitaminique** · troubles de la **thermorégulation** · **déshydratation** · troubles **hémodynamiques**.","prio":"P2","sec":"s5"},{"id":"fc-d117-129b34","poly":"dermato","fiche":"d117","front":"Psoriasis érythrodermique : quelle conduite ?","back":"**Hospitalisation en milieu spécialisé**.","prio":"P2","sec":"s5"},{"id":"fc-d117-9f6208","poly":"dermato","fiche":"d117","front":"Psoriasis pustuleux généralisé : quels facteurs déclenchants ?","back":"Certains **médicaments**, la **grossesse**… ; d'emblée ou sur un psoriasis en plaques ancien.","prio":"P3","sec":"s5"},{"id":"fc-d117-32b910","poly":"dermato","fiche":"d117","front":"Psoriasis pustuleux généralisé : quel tableau clinique ?","back":"**Début brutal**, altération de l'état général, **fièvre élevée**, placards rouge vif couverts de **pustules** « laiteuses » confluant en nappes (tronc).","prio":"P2","sec":"s5"},{"id":"fc-d117-2b98b8","poly":"dermato","fiche":"d117","front":"Psoriasis pustuleux généralisé : caractéristiques des pustules ?","back":"**Superficielles**, **non folliculaires**, **aseptiques** ; histologie : pustules **spongiformes** (multiloculaires).","prio":"P2","sec":"s5"},{"id":"fc-d117-893391","poly":"dermato","fiche":"d117","front":"Psoriasis pustuleux généralisé : quel pronostic ?","back":"Évolution parfois grave, **pronostic vital** possible.","prio":"P2","sec":"s5"},{"id":"fc-d117-721334","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : quelle fréquence chez les psoriasiques ?","back":"Environ **25 %**.","prio":"P2","sec":"s5"},{"id":"fc-d117-73e617","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : quelles atteintes caractéristiques ?","back":"Interphalangiennes **distales** · **dactylite** (doigt ou orteil entier) · **enthésopathie** ; périphérique ou axial.","prio":"P2","sec":"s5"},{"id":"fc-d117-7330ac","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : la sévérité cutanée est-elle corrélée à l'atteinte articulaire ?","back":"**Non** : un psoriasis cutané minime n'élimine pas un rhumatisme.","prio":"P2","sec":"s5"},{"id":"fc-d117-ed6c57","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : à quelles localisations cutanées est-il plus associé ?","back":"**Cuir chevelu** · **ongles** · **sillon interfessier**.","prio":"P2","sec":"s5"},{"id":"fc-d117-754f38","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : citer les formes articulaires à reconnaître ?","back":"**Oligo- ou monoarthrite** · **polyarthrite** · **rhumatisme axial**.","prio":"P3","sec":"s5"},{"id":"fc-d117-81b9ce","poly":"dermato","fiche":"d117","front":"Psoriasis chez le patient VIH : quelles particularités ?","back":"Souvent **plus grave**, **réfractaire** aux traitements conventionnels ; parfois difficile à distinguer d'une **dermatite séborrhéique profuse**.","prio":"P2","sec":"s5"},{"id":"fc-d117-eee11e","poly":"dermato","fiche":"d117","front":"Psoriasis du nourrisson : quelle forme typique ?","back":"**Napkin psoriasis** (siège ; autrefois « psoriasis des langes »).","prio":"P2","sec":"s6"},{"id":"fc-d117-5a28e4","poly":"dermato","fiche":"d117","front":"Psoriasis de l'enfant plus âgé et de l'adolescent : quelle forme fréquente ?","back":"Psoriasis **aigu en gouttes**, pouvant succéder à une **infection rhinopharyngée streptococcique**.","prio":"P2","sec":"s6"},{"id":"fc-d117-4ad826","poly":"dermato","fiche":"d117","front":"Psoriasis de l'enfant : particularité topographique par rapport à l'adulte ?","back":"Le **visage** est **plus souvent** atteint.","prio":"P3","sec":"s6"},{"id":"fc-d117-c09418","poly":"dermato","fiche":"d117","front":"Pityriasis rosé de Gibert : quelle lésion précède l'éruption et de combien ?","back":"Un **médaillon** isolé, **10-15 jours** avant.","prio":"P2","sec":"s7"},{"id":"fc-d117-75e772","poly":"dermato","fiche":"d117","front":"Pityriasis rosé de Gibert : aspect et topographie de l'éruption ?","back":"Macules rosées finement squameuses et médaillons à centre clair, **tronc** et racine des membres, **« en arbre de Noël »**.","prio":"P2","sec":"s7"},{"id":"fc-d117-24241e","poly":"dermato","fiche":"d117","front":"Pityriasis rosé de Gibert : quelle évolution ?","back":"**Guérison spontanée en 6 à 8 semaines** ; sinon, évoquer un autre diagnostic.","prio":"P2","sec":"s7"},{"id":"fc-d117-72715b","poly":"dermato","fiche":"d117","front":"Pityriasis rosé de Gibert : quels examens de principe ?","back":"**Sérologies VIH et syphilis**.","prio":"P2","sec":"s7"},{"id":"fc-d117-014304","poly":"dermato","fiche":"d117","front":"Pityriasis rosé de Gibert : quelle origine ?","back":"**Inconnue** (peut-être **virale**) ; souvent **saisonnière**.","prio":"P3","sec":"s7"},{"id":"fc-d117-8029eb","poly":"dermato","fiche":"d117","front":"Dermatite séborrhéique : quelle topographie ?","back":"**Visage** (plis nasogéniens), **cuir chevelu**, région **médiothoracique**.","prio":"P2","sec":"s7"},{"id":"fc-d117-042669","poly":"dermato","fiche":"d117","front":"Psoriasis / dermatite séborrhéique : quelles formes frontières ?","back":"**Sébopsoriasis** ; **dermite bipolaire** du nourrisson.","prio":"P3","sec":"s7"},{"id":"fc-d117-bcc43a","poly":"dermato","fiche":"d117","front":"Psoriasis ou dermatite séborrhéique : quel élément aide au diagnostic ?","back":"La présence de **lésions de psoriasis à distance**.","prio":"P3","sec":"s7"},{"id":"fc-d117-434ba0","poly":"dermato","fiche":"d117","front":"Eczéma chronique vs psoriasis : quels éléments distinctifs ?","back":"Eczéma : **peu de squames**, **limites émiettées** ; topographie **visage et plis**.","prio":"P2","sec":"s7"},{"id":"fc-d117-87e60a","poly":"dermato","fiche":"d117","front":"Psoriasis : avec quels eczémas la discussion se pose-t-elle surtout ?","back":"**Eczéma nummulaire** (en médaillons) et **eczémas palmo-plantaires**.","prio":"P3","sec":"s7"},{"id":"fc-d117-d38590","poly":"dermato","fiche":"d117","front":"Doute entre psoriasis et lymphome cutané : quelle conduite ?","back":"**Biopsie cutanée**.","prio":"P2","sec":"s7"},{"id":"fc-d117-2a4941","poly":"dermato","fiche":"d117","front":"Psoriasis des plis : diagnostics différentiels ?","back":"**Intertrigos** bactériens ou mycosiques.","prio":"P2","sec":"s7"},{"id":"fc-d117-505685","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : diagnostics différentiels ?","back":"Autres kératodermies acquises : **eczéma**, **lichen**, **dermatophytie**.","prio":"P3","sec":"s7"},{"id":"fc-d117-812bf2","poly":"dermato","fiche":"d117","front":"Érythrodermie psoriasique : diagnostics différentiels ?","back":"Autres érythrodermies : **toxidermies**, **lymphomes**, **eczémas**.","prio":"P3","sec":"s7"},{"id":"fc-d117-916eba","poly":"dermato","fiche":"d117","front":"Psoriasis pustuleux généralisé : quel diagnostic différentiel ?","back":"**Pustulose exanthématique aiguë généralisée** (toxidermie pustuleuse).","prio":"P2","sec":"s7"},{"id":"fc-d117-7fd194","poly":"dermato","fiche":"d117","front":"Psoriasis : âge de début le plus fréquent ?","back":"**Adolescent** et **adulte jeune**.","prio":"P2","sec":"s8"},{"id":"fc-d117-f3061b","poly":"dermato","fiche":"d117","front":"Psoriasis à début précoce : quelles particularités ?","back":"Plus souvent lié aux **gènes de susceptibilité** ; évolution **plus sévère** qu'un psoriasis apparu après 50 ans.","prio":"P3","sec":"s8"},{"id":"fc-d117-d448bb","poly":"dermato","fiche":"d117","front":"Psoriasis : quels modes évolutifs ?","back":"**Quasi continu** (formes sévères surtout) ou par **poussées** et **rémissions**.","prio":"P2","sec":"s8"},{"id":"fc-d117-cf201c","poly":"dermato","fiche":"d117","front":"Psoriasis : en quelle saison les rémissions sont-elles plus fréquentes et pourquoi ?","back":"En **été** (effet bénéfique des **ultraviolets**).","prio":"P3","sec":"s8"},{"id":"fc-d117-2355e2","poly":"dermato","fiche":"d117","front":"Psoriasis : agents de surinfection les plus fréquents ?","back":"**Candida albicans** (plis) ou **dermatophytes** (paumes et plantes) ; rarement bactérienne.","prio":"P2","sec":"s8"},{"id":"fc-d117-9f5fb1","poly":"dermato","fiche":"d117","front":"Psoriasis eczématisé : quels signes et quelle cause rechercher ?","back":"**Suintement** + **prurit intense** ; chercher une **sensibilisation** ou **irritation** par un topique.","prio":"P2","sec":"s8"},{"id":"fc-d117-0e8368","poly":"dermato","fiche":"d117","front":"Psoriasis : quel retentissement psychique rechercher ?","back":"**Syndrome dépressif** parfois sévère, qualité de vie **profondément altérée**, même hors formes graves.","prio":"P1","sec":"s9"},{"id":"fc-d117-a14445","poly":"dermato","fiche":"d117","front":"Psoriasis : le médecin évalue-t-il bien le retentissement sur la qualité de vie ?","back":"**Non** : il le **sous-estime souvent**.","prio":"P1","sec":"s9"},{"id":"fc-d117-1575ac","poly":"dermato","fiche":"d117","front":"Psoriasis modéré à sévère : quel retentissement social possible ?","back":"**Stigmatisation** et **exclusion sociale**.","prio":"P2","sec":"s9"},{"id":"fc-d117-344635","poly":"dermato","fiche":"d117","front":"Psoriasis : quelles conduites addictives associées ?","back":"**Tabagisme** ; consommation **excessive d'alcool**.","prio":"P1","sec":"s9"},{"id":"fc-d117-884a13","poly":"dermato","fiche":"d117","front":"Psoriasis : quels surrisques de comorbidités ?","back":"**Cardiovasculaires** ; **maladie inflammatoire du tube digestif** ; **syndrome métabolique**.","prio":"P1","sec":"s9"},{"id":"fc-d117-0959f9","poly":"dermato","fiche":"d117","front":"Psoriasis : citer les pathologies psychiques associées listées ?","back":"**Dépression**, **anxiété**.","prio":"P2","sec":"s9"},{"id":"fc-d117-29d076","poly":"dermato","fiche":"d117","front":"Psoriasis sévère : quel risque vital au long cours ?","back":"**Mortalité précoce** accrue.","prio":"P1","sec":"s9"},{"id":"fc-d117-9a390d","poly":"dermato","fiche":"d117","front":"Psoriasis avec comorbidités : quelle organisation de la prise en charge ?","back":"**Multidisciplinaire**, pour traiter en même temps psoriasis et comorbidités.","prio":"P2","sec":"s9"},{"id":"fc-d117-77f0f0","poly":"dermato","fiche":"d117","front":"Syndrome métabolique : seuil de glycémie à jeun ?","back":"**≥ 1,10 g/L**.","prio":"P2","sec":"s9"},{"id":"fc-d117-be138e","poly":"dermato","fiche":"d117","front":"Syndrome métabolique : seuil des triglycérides ?","back":"**> 1,50 g/L**.","prio":"P2","sec":"s9"},{"id":"fc-d117-1b0e11","poly":"dermato","fiche":"d117","front":"Syndrome métabolique : seuils du HDL-cholestérol ?","back":"**< 0,40 g/L** chez l'homme ; **< 0,50 g/L** chez la femme.","prio":"P2","sec":"s9"},{"id":"fc-d117-0424bd","poly":"dermato","fiche":"d117","front":"Syndrome métabolique : seuil de pression artérielle ?","back":"**≥ 130/85 mmHg**.","prio":"P2","sec":"s9"},{"id":"fc-d117-2aa84d","poly":"dermato","fiche":"d117","front":"Syndrome métabolique : seuils du tour de taille ?","back":"**> 102 cm** chez l'homme ; **> 88 cm** chez la femme.","prio":"P2","sec":"s9"},{"id":"fc-d117-23c110","poly":"dermato","fiche":"d117","front":"Syndrome métabolique non traité : à quoi expose-t-il ?","back":"**Complications cardiovasculaires** et **diabète de type 2**.","prio":"P2","sec":"s9"},{"id":"fc-d117-ff128e","poly":"dermato","fiche":"d117","front":"Psoriasis : les traitements actuels permettent-ils la guérison ?","back":"**Non**, pas de guérison définitive : ils réduisent les lésions et améliorent la **qualité de vie**.","prio":"P2","sec":"s10"},{"id":"fc-d117-f379a9","poly":"dermato","fiche":"d117","front":"Psoriasis : quel repère pour estimer la surface atteinte ?","back":"**Une paume = 1 %** de la surface corporelle.","prio":"P2","sec":"s10"},{"id":"fc-d117-759192","poly":"dermato","fiche":"d117","front":"PASI : que signifie le sigle et que mesure-t-il ?","back":"**Psoriasis Area and Severity Index** : la **gravité** des lésions.","prio":"P2","sec":"s10"},{"id":"fc-d117-3a1efa","poly":"dermato","fiche":"d117","front":"Psoriasis : quel score de qualité de vie utiliser et quel seuil de sévérité ?","back":"**DLQI** (coté de 0 à 30) : psoriasis **sévère si > 10**.","prio":"P2","sec":"s10"},{"id":"fc-d117-114a2c","poly":"dermato","fiche":"d117","front":"Psoriasis modéré à sévère : définition ?","back":"Surface atteinte **> 10 %** et/ou **PASI > 10**.","prio":"P2","sec":"s10"},{"id":"fc-d117-6c47e7","poly":"dermato","fiche":"d117","front":"Psoriasis : quand passer aux traitements systémiques ?","back":"Psoriasis **étendu (> 30 %)** ou **résistant** aux topiques.","prio":"P2","sec":"s10"},{"id":"fc-d117-40dfbb","poly":"dermato","fiche":"d117","front":"Psoriasis : sur quoi repose le choix thérapeutique en plus de la surface ?","back":"**Retentissement** (fonctionnel, psychologique…), **désir de rémission**, localisations, atteinte articulaire, comorbidités, CI.","prio":"P2","sec":"s10"},{"id":"fc-d117-e3696b","poly":"dermato","fiche":"d117","front":"Psoriasis : quel but thérapeutique ?","back":"Soigner **au long cours**, soulager, améliorer la qualité de vie, ramener les lésions à un niveau compatible avec une **vie normale**.","prio":"P3","sec":"s10"},{"id":"fc-d117-aa8b57","poly":"dermato","fiche":"d117","front":"Psoriasis : qui organise la stratégie au long cours ?","back":"**Médecin traitant** et **dermatologue** en collaboration ; patient éduqué et **associé aux choix**.","prio":"P2","sec":"s10"},{"id":"fc-d117-6454ad","poly":"dermato","fiche":"d117","front":"Psoriasis : quel accompagnement proposer en plus des traitements ?","back":"Un **soutien** ou une prise en charge **psychologique**.","prio":"P3","sec":"s10"},{"id":"fc-d117-a8a804","poly":"dermato","fiche":"d117","front":"Psoriasis ≤ 10 % de la surface : quel traitement ?","back":"**Traitement local** : **dermocorticoïde**, **dérivé de la vitamine D** ou **association** des deux.","prio":"P2","sec":"s11"},{"id":"fc-d117-4f5dd7","poly":"dermato","fiche":"d117","front":"Psoriasis très squameux : comment préparer le traitement local ?","back":"**Décaper** : préparation d'**acide salicylique** ; **bains** et **émollients** (aussi contre le prurit).","prio":"P2","sec":"s11"},{"id":"fc-d117-ea53fc","poly":"dermato","fiche":"d117","front":"Acide salicylique : quelle contre-indication ?","back":"**Nouveau-né** (risque d'**intoxication salicylée**).","prio":"P2","sec":"s11"},{"id":"fc-d117-497d94","poly":"dermato","fiche":"d117","front":"Dermocorticoïde dans le psoriasis : pommade ou crème ?","back":"**Pommade** pour les lésions sèches, sinon **crème** ; **pas de pommade dans les plis** (macération).","prio":"P2","sec":"s11"},{"id":"fc-d117-422bb9","poly":"dermato","fiche":"d117","front":"Psoriasis hors visage : quelle activité de dermocorticoïde ?","back":"**Activité forte** (propionate de **fluticasone** ou dipropionate de **bétaméthasone**).","prio":"P2","sec":"s11"},{"id":"fc-d117-79bc0a","poly":"dermato","fiche":"d117","front":"Psoriasis du cuir chevelu : quel dermocorticoïde et quelles formes ?","back":"Propionate de **clobétasol** en **lotion**, **mousse** ou **shampooing**.","prio":"P2","sec":"s11"},{"id":"fc-d117-47e929","poly":"dermato","fiche":"d117","front":"Dermocorticoïde dans le psoriasis : combien d'applications par jour et pourquoi ?","back":"**1 par jour** (effet **réservoir** de la couche cornée).","prio":"P2","sec":"s11"},{"id":"fc-d117-5a0341","poly":"dermato","fiche":"d117","front":"Dermocorticoïde dans le psoriasis : schéma d'attaque puis d'entretien ?","back":"Attaque **1 à 3 semaines** en continu, puis entretien intermittent **2 fois par semaine**.","prio":"P2","sec":"s11"},{"id":"fc-d117-fd406c","poly":"dermato","fiche":"d117","front":"Psoriasis : citer les analogues de la vitamine D topiques ?","back":"**Calcipotriol**, **tacalcitol**, **calcitriol**.","prio":"P3","sec":"s11"},{"id":"fc-d117-b289db","poly":"dermato","fiche":"d117","front":"Association dermocorticoïde + calcipotriol : quel intérêt ?","back":"Association **synergique** : plus efficace que chaque produit seul.","prio":"P2","sec":"s11"},{"id":"fc-d117-a58e68","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : comment accroître la pénétration des topiques ?","back":"**Occlusion** (pansement ou **hydrocolloïde**), car la couche cornée épaisse freine la pénétration.","prio":"P3","sec":"s11"},{"id":"fc-d117-a502e1","poly":"dermato","fiche":"d117","front":"Photothérapie du psoriasis : quelles contre-indications ?","back":"Antécédent de **cancer cutané** · dermatose **aggravée par la lumière** · médicament **photosensibilisant**.","prio":"P2","sec":"s12"},{"id":"fc-d117-e19282","poly":"dermato","fiche":"d117","front":"PUVAthérapie : principe ?","back":"Psoralène photosensibilisant (**8-** ou **5-méthoxypsoralène**) puis irradiation **UVA**.","prio":"P2","sec":"s12"},{"id":"fc-d117-83ffbf","poly":"dermato","fiche":"d117","front":"Photothérapie UVB TL-01 : avantages par rapport à la PUVA ?","back":"**Sans psoralène**, aussi efficace, **moins carcinogène**.","prio":"P2","sec":"s12"},{"id":"fc-d117-e95813","poly":"dermato","fiche":"d117","front":"Photothérapie du psoriasis : rythme des séances ?","back":"**2 à 3 séances par semaine**.","prio":"P3","sec":"s12"},{"id":"fc-d117-5d48ed","poly":"dermato","fiche":"d117","front":"Photothérapie du psoriasis : nombre moyen de séances d'une cure ?","back":"PUVA : **20 séances** ; UVB TL-01 : **20 à 30 séances**.","prio":"P3","sec":"s12"},{"id":"fc-d117-62b6f1","poly":"dermato","fiche":"d117","front":"rePUVA : définition ?","back":"**Acitrétine** + **PUVA** (association possible aussi acitrétine + UVB).","prio":"P3","sec":"s12"},{"id":"fc-d117-f5d253","poly":"dermato","fiche":"d117","front":"Photothérapie : nombre maximal de séances cumulées ?","back":"Ne pas dépasser **200 séances**.","prio":"P2","sec":"s12"},{"id":"fc-d117-030bd2","poly":"dermato","fiche":"d117","front":"PUVAthérapie : quelles précautions pendant et après la séance ?","back":"**Photoprotection** dans les heures qui suivent ; **lunettes noires obligatoires** ; protéger les **organes génitaux externes**.","prio":"P2","sec":"s12"},{"id":"fc-d117-158813","poly":"dermato","fiche":"d117","front":"Photothérapie : effets indésirables à court terme ?","back":"**Érythème** (surdosage ou photosensibilisant associé) ; **troubles digestifs** (PUVA).","prio":"P3","sec":"s12"},{"id":"fc-d117-c506cd","poly":"dermato","fiche":"d117","front":"Photothérapie : effets indésirables à long terme ?","back":"**Vieillissement cutané prématuré** ; **cancers cutanés** (surtout **carcinomes**, parfois tardifs) → surveillance prolongée.","prio":"P2","sec":"s12"},{"id":"fc-d117-fd1952","poly":"dermato","fiche":"d117","front":"Photothérapie : pourquoi n'est-elle pas utilisable au long cours ?","back":"**Risque carcinogène**.","prio":"P2","sec":"s12"},{"id":"fc-d117-a85530","poly":"dermato","fiche":"d117","front":"Psoriasis palmo-plantaire : quelle photothérapie possible ?","back":"Photothérapie **localisée** aux **paumes** ou aux **plantes**.","prio":"P3","sec":"s12"},{"id":"fc-d117-424d3f","poly":"dermato","fiche":"d117","front":"Psoriasis modéré à sévère : citer les traitements systémiques classiques oraux ?","back":"**Acitrétine** (rétinoïde) · **méthotrexate** · **ciclosporine**.","prio":"P2","sec":"s13"},{"id":"fc-d117-aaaf37","poly":"dermato","fiche":"d117","front":"Méthotrexate et ciclosporine : quelle classe pharmacologique respective ?","back":"Méthotrexate : **immunomodulateur** non sélectif ; ciclosporine : **immunosuppresseur** non sélectif.","prio":"P3","sec":"s13"},{"id":"fc-d117-80a050","poly":"dermato","fiche":"d117","front":"Acitrétine : quelles contre-indications liées à la procréation ?","back":"Femme en âge de procréer **sans contraception efficace** · **projet de grossesse dans les 3 ans après l'arrêt** · grossesse · allaitement.","prio":"P2","sec":"s13"},{"id":"fc-d117-b94287","poly":"dermato","fiche":"d117","front":"Acitrétine : quelle association est contre-indiquée et pourquoi ?","back":"**Tétracyclines** : risque d'**hypertension intracrânienne**.","prio":"P2","sec":"s13"},{"id":"fc-d117-733302","poly":"dermato","fiche":"d117","front":"Acitrétine : quelles contre-indications biologiques ?","back":"Anomalies du **bilan lipidique** ou **hépatique**.","prio":"P3","sec":"s13"},{"id":"fc-d117-9fd334","poly":"dermato","fiche":"d117","front":"Acitrétine : effets indésirables ?","back":"**Tératogénicité** · sécheresse cutanéo-muqueuse, prurit, chute de cheveux · **hyperlipidémie** · élévation des **transaminases**.","prio":"P2","sec":"s13"},{"id":"fc-d117-fad39d","poly":"dermato","fiche":"d117","front":"Méthotrexate : quelle particularité de la contraception ?","back":"Elle concerne **la femme ET l'homme** en âge de procréer.","prio":"P2","sec":"s13"},{"id":"fc-d117-331a04","poly":"dermato","fiche":"d117","front":"Méthotrexate : quelles contre-indications (hors procréation) ?","back":"Anomalies de l'**hémogramme** ou du **bilan hépatique** · **insuffisance rénale** · **infection évolutive**.","prio":"P2","sec":"s13"},{"id":"fc-d117-44a8d1","poly":"dermato","fiche":"d117","front":"Méthotrexate : effets indésirables hématologiques et hépatiques ?","back":"**Cytopénie**, macrocytose ; **fibrose hépatique** si facteur de risque (alcool, diabète).","prio":"P2","sec":"s13"},{"id":"fc-d117-a8865e","poly":"dermato","fiche":"d117","front":"Méthotrexate : effets indésirables pulmonaires ?","back":"**Pneumopathie d'hypersensibilité** et **fibrose pulmonaire** (rares).","prio":"P3","sec":"s13"},{"id":"fc-d117-bd428e","poly":"dermato","fiche":"d117","front":"Méthotrexate : quelles interactions exposent aux ulcérations cutanéo-muqueuses ?","back":"**Aspirine à forte dose** ; **triméthoprime** (ou surdosage).","prio":"P2","sec":"s13"},{"id":"fc-d117-f94449","poly":"dermato","fiche":"d117","front":"Ciclosporine : contre-indications ?","back":"**HTA** · **insuffisance rénale** · antécédent de **néoplasie** · infection chronique.","prio":"P2","sec":"s13"},{"id":"fc-d117-c70833","poly":"dermato","fiche":"d117","front":"Ciclosporine : effets indésirables ?","back":"**HTA** · **néphrotoxicité** · hypertrichose · hyperplasie gingivale · cancers cutanés ; **nombreuses interactions**.","prio":"P2","sec":"s13"},{"id":"fc-d117-10aa75","poly":"dermato","fiche":"d117","front":"Aprémilast : mécanisme ?","back":"Immunomodulateur qui **inhibe une phosphodiestérase**.","prio":"P2","sec":"s14"},{"id":"fc-d117-cf632b","poly":"dermato","fiche":"d117","front":"Aprémilast : quelle place dans le psoriasis ?","back":"**Échec**, **contre-indication** ou **intolérance** aux autres systémiques (ciclosporine, méthotrexate, PUVA).","prio":"P2","sec":"s14"},{"id":"fc-d117-b782e7","poly":"dermato","fiche":"d117","front":"Biothérapies du psoriasis : modalités de prescription ?","back":"**Réservées au spécialiste**, avec **prescription initiale hospitalière**.","prio":"P2","sec":"s14"},{"id":"fc-d117-814e22","poly":"dermato","fiche":"d117","front":"Biothérapies du psoriasis : indication en France ?","back":"Psoriasis **modéré à sévère** retentissant, après échec, intolérance ou CI d'**au moins deux** systémiques.","prio":"P2","sec":"s14"},{"id":"fc-d117-3bcffe","poly":"dermato","fiche":"d117","front":"Biothérapies du psoriasis : citer les quatre familles ?","back":"**Anti-TNFα** · **anti-IL-12/IL-23** · agents de la **voie de l'IL-17** · **anti-IL-23**.","prio":"P2","sec":"s14"},{"id":"fc-d117-5c395e","poly":"dermato","fiche":"d117","front":"Psoriasis érythrodermique : quels éléments de prise en charge de toute érythrodermie ?","back":"**Hospitalisation en urgence** · biologie · correction **hydro-électrolytique** · traitement des défaillances · **réchauffer** · traiter la cause.","prio":"P2","sec":"s15"},{"id":"fc-d117-c4fbfd","poly":"dermato","fiche":"d117","front":"Érythrodermie : pourquoi réchauffer le patient ?","back":"Limiter les **pertes caloriques**, l'**hypercatabolisme** et la **dénutrition**.","prio":"P3","sec":"s15"},{"id":"fc-d117-be398d","poly":"dermato","fiche":"d117","front":"Érythrodermie psoriasique : quel facteur déclenchant rechercher ?","back":"Un **rebond** après **arrêt d'une corticothérapie générale**.","prio":"P2","sec":"s15"},{"id":"fc-d117-0ba972","poly":"dermato","fiche":"d117","front":"Érythrodermie grave : quel dermocorticoïde est cité ?","back":"Dermocorticoïde de **niveau 1** (**très forte activité**).","prio":"P3","sec":"s15"},{"id":"fc-d117-6d6bbd","poly":"dermato","fiche":"d117","front":"Érythrodermie : quelles complications de toute érythrodermie ?","back":"Pertes **hydro-électrolytiques** (décompensation cardiaque, respiratoire, rénale) · **décubitus** · **infections**.","prio":"P2","sec":"s15"},{"id":"fc-d117-68f55d","poly":"dermato","fiche":"d117","front":"Érythrodermie : jusqu'à quelle mortalité ?","back":"Jusqu'à **20 %**.","prio":"P2","sec":"s15"},{"id":"fc-d117-a7d66e","poly":"dermato","fiche":"d117","front":"Érythrodermie : quelles infections redouter ?","back":"Cutanées à **staphylocoque** · **herpès** · **varicelle-zona** · **pneumopathies** · **septicémies**.","prio":"P3","sec":"s15"},{"id":"fc-d117-af5a50","poly":"dermato","fiche":"d117","front":"Psoriasis suivi au long cours : citer les comorbidités à rechercher ?","back":"**Dépression** · **addictions** (tabac, alcool) · **syndrome métabolique** · risque **cardiovasculaire** · **MICI**.","prio":"P1","sec":"s16"},{"id":"fc-d117-268e18","poly":"dermato","fiche":"d117","front":"Rhumatisme psoriasique : avec qui l'évaluer et le traiter ?","back":"Avec le **rhumatologue**.","prio":"P2","sec":"s16"},{"id":"fc-d117-ceeda6","poly":"dermato","fiche":"d117","front":"Psoriasis : avec qui coordonner la prise en charge des comorbidités ?","back":"Avec le **médecin traitant**.","prio":"P2","sec":"s16"},{"id":"fc-d117-90c6c5","poly":"dermato","fiche":"d117","front":"Psoriasis : pourquoi associer le patient aux choix thérapeutiques ?","back":"Meilleure **adhésion** ; il doit être **informé** et **éduqué** pour gérer sa maladie au quotidien.","prio":"P2","sec":"s16"},{"id":"fc-d155-e652fd","poly":"dermato","fiche":"d155","front":"Infections cutanées bactériennes : quels germes en cause ?","back":"**Cocci à Gram positif** : **streptocoque β-hémolytique du groupe A** et **Staphylococcus aureus**.","prio":"P1","sec":"s1"},{"id":"fc-d155-c63e77","poly":"dermato","fiche":"d155","front":"Infections cutanées bactériennes : 3 caractéristiques générales ?","back":"**Auto-inoculables** · **non immunisantes** · complications **rares**.","prio":"P2","sec":"s1"},{"id":"fc-d155-244f67","poly":"dermato","fiche":"d155","front":"Infections staphylococciques récurrentes : que rechercher ?","back":"Un **portage chronique** de staphylocoque.","prio":"P1","sec":"s1"},{"id":"fc-d155-7af801","poly":"dermato","fiche":"d155","front":"SARM : quelle évolution épidémiologique ?","back":"Émergence de *S. aureus* **résistant à la méticilline**, y compris en **pratique de ville**.","prio":"P2","sec":"s1"},{"id":"fc-d155-111251","poly":"dermato","fiche":"d155","front":"Impétigo : quel étage de la peau est atteint ?","back":"L'**épiderme**.","prio":"P1","sec":"s1"},{"id":"fc-d155-dd2e98","poly":"dermato","fiche":"d155","front":"Impétigo : germes en cause ?","back":"***S. aureus*** (90 % en France), ***S. pyogenes*** (pays émergents), ou les deux.","prio":"P1","sec":"s1"},{"id":"fc-d155-95c5d6","poly":"dermato","fiche":"d155","front":"Folliculite superficielle : définition ?","back":"Infection du follicule pilo-sébacé limitée à l'**ostium folliculaire** ; *S. aureus*.","prio":"P2","sec":"s1"},{"id":"fc-d155-2668c4","poly":"dermato","fiche":"d155","front":"Furoncle : définition ?","back":"Infection **profonde et nécrosante** du follicule pilo-sébacé à ***S. aureus***.","prio":"P1","sec":"s1"},{"id":"fc-d155-8fcd97","poly":"dermato","fiche":"d155","front":"Anthrax (staphylococcique) : définition ?","back":"Conglomérat de **plusieurs furoncles** (complication).","prio":"P2","sec":"s1"},{"id":"fc-d155-da7571","poly":"dermato","fiche":"d155","front":"Panaris : définition ?","back":"Infection du **repli unguéal** (staphylocoque).","prio":"P1","sec":"s1"},{"id":"fc-d155-a9be6e","poly":"dermato","fiche":"d155","front":"Abcès : définition ?","back":"**Collection de pus** : résolution physiologique imparfaite d'une infection locale ; *S. aureus* surtout.","prio":"P1","sec":"s1"},{"id":"fc-d155-61d516","poly":"dermato","fiche":"d155","front":"Candidose : définition ?","back":"Infection **opportuniste** par une **levure** du genre *Candida* (muqueuses > peau glabre) ; surtout *C. albicans*.","prio":"P1","sec":"s1"},{"id":"fc-d155-5ef56b","poly":"dermato","fiche":"d155","front":"Dermatophytie : définition ?","back":"Infection superficielle de la peau et des phanères par un **champignon filamenteux kératinophile**.","prio":"P1","sec":"s1"},{"id":"fc-d155-b26912","poly":"dermato","fiche":"d155","front":"Dermatophytes : citer les 3 genres ?","back":"***Trichophyton***, ***Microsporum***, ***Epidermophyton***.","prio":"P1","sec":"s1"},{"id":"fc-d155-4cd975","poly":"dermato","fiche":"d155","front":"Dermatophytes : sont-ils parfois saprophytes ?","back":"**Non** : **toujours pathogènes** dès qu'on les trouve.","prio":"P1","sec":"s1"},{"id":"fc-d155-b231c7","poly":"dermato","fiche":"d155","front":"Dermatophytes : quel territoire n'atteignent-ils jamais ?","back":"Les **muqueuses** (ils aiment la kératine : couche cornée, poils, cheveux, ongles).","prio":"P1","sec":"s1"},{"id":"fc-d155-4e29de","poly":"dermato","fiche":"d155","front":"Impétigo : contagiosité ?","back":"**Très contagieux** : auto-inoculation, petites épidémies familiales ou en collectivité.","prio":"P1","sec":"s2"},{"id":"fc-d155-42278e","poly":"dermato","fiche":"d155","front":"Impétigo localisé : faut-il un prélèvement bactériologique ?","back":"**Non** : diagnostic **clinique**.","prio":"P1","sec":"s2"},{"id":"fc-d155-ff17f3","poly":"dermato","fiche":"d155","front":"Impétigo : critères de forme grave (justifiant un prélèvement) ?","back":"**Ecthyma** · surface **> 2 %** · **plus de 6 lésions** · **extension rapide**.","prio":"P1","sec":"s2"},{"id":"fc-d155-29865e","poly":"dermato","fiche":"d155","front":"Impétigo : évolution de la lésion élémentaire ?","back":"Vésicule ou bulle **fragile** → pustule → rupture → érosion couverte d'une **croûte mélicérique**.","prio":"P1","sec":"s2"},{"id":"fc-d155-02bbf1","poly":"dermato","fiche":"d155","front":"Croûte mélicérique : aspect ?","back":"Aspect de **miel cristallisé**.","prio":"P2","sec":"s2"},{"id":"fc-d155-79e497","poly":"dermato","fiche":"d155","front":"Impétigo : aspect quand plusieurs lésions se groupent ?","back":"Placards **polycycliques** à contours **circinés**.","prio":"P3","sec":"s2"},{"id":"fc-d155-f695f1","poly":"dermato","fiche":"d155","front":"Impétigo de l'enfant : topographie préférentielle ?","back":"**Autour de la bouche** (toute la peau peut être atteinte).","prio":"P2","sec":"s2"},{"id":"fc-d155-207ef7","poly":"dermato","fiche":"d155","front":"Impétigo : signes généraux ?","back":"**État général conservé**, **pas de fièvre** ; adénopathie satellite possible.","prio":"P1","sec":"s2"},{"id":"fc-d155-f4c423","poly":"dermato","fiche":"d155","front":"Impétigo bulleux : mécanisme ?","back":"**Exfoliatines A et B** de *S. aureus* ciblant la **desmogléine 1** (épiderme superficiel) → décollement.","prio":"P1","sec":"s2"},{"id":"fc-d155-6d9d8c","poly":"dermato","fiche":"d155","front":"Impétigo bulleux : aspect de l'érosion post-bulleuse ?","back":"À **bord ourlé**.","prio":"P3","sec":"s2"},{"id":"fc-d155-5dda24","poly":"dermato","fiche":"d155","front":"Impétigo : chez qui les formes disséminées ?","back":"**Nouveau-né** et **nourrisson**.","prio":"P2","sec":"s2"},{"id":"fc-d155-92cac2","poly":"dermato","fiche":"d155","front":"Impétiginisation : définition ?","back":"Surinfection d'une **dermatose sous-jacente** (eczéma, varicelle) ou de lésions de **grattage** (pédiculose, gale).","prio":"P1","sec":"s2"},{"id":"fc-d155-de545b","poly":"dermato","fiche":"d155","front":"Impétigo de l'adulte : quelle forme est habituelle ?","back":"L'**impétiginisation** (impétigo primitif rare) : chercher la dermatose sous-jacente.","prio":"P1","sec":"s2"},{"id":"fc-d155-a30aa3","poly":"dermato","fiche":"d155","front":"Ecthyma : définition et germe ?","back":"Impétigo **creusant** (ulcération dermique) à **streptocoque β-hémolytique du groupe A**.","prio":"P2","sec":"s2"},{"id":"fc-d155-37816a","poly":"dermato","fiche":"d155","front":"Ecthyma : terrain et évolution ?","back":"Fréquent en situation de **précarité** ; guérit avec une **cicatrice dyschromique**.","prio":"P3","sec":"s2"},{"id":"fc-d155-ca87ae","poly":"dermato","fiche":"d155","front":"Ecthyma gangrenosum : définition ?","back":"Dermohypodermite bactérienne **nécrotique** de l'**immunodéprimé**, à bacilles Gram négatif (***Pseudomonas aeruginosa***).","prio":"P2","sec":"s2"},{"id":"fc-d155-127278","poly":"dermato","fiche":"d155","front":"Impétigo : complications exceptionnelles ?","back":"**Glomérulonéphrite post-streptococcique** · **rhumatisme articulaire aigu**.","prio":"P2","sec":"s2"},{"id":"fc-d155-7c182b","poly":"dermato","fiche":"d155","front":"Folliculite superficielle : lésion élémentaire ?","back":"**Pustule centrée par un poil**, avec érythème périfolliculaire.","prio":"P1","sec":"s3"},{"id":"fc-d155-3f7ee8","poly":"dermato","fiche":"d155","front":"Folliculite : topographie ?","back":"**Zones pileuses** : cuisses, périnée, bras, thorax, dos.","prio":"P3","sec":"s3"},{"id":"fc-d155-c923eb","poly":"dermato","fiche":"d155","front":"Orgelet : définition ?","back":"**Folliculite d'un cil**.","prio":"P2","sec":"s3"},{"id":"fc-d155-44ba82","poly":"dermato","fiche":"d155","front":"Sycosis : définition et facteur aggravant ?","back":"**Folliculite de la barbe** ; le **rasage** favorise extension et chronicité.","prio":"P2","sec":"s3"},{"id":"fc-d155-83ebdd","poly":"dermato","fiche":"d155","front":"Furoncle : aspect clinique ?","back":"Lésion **papulo-nodulaire très inflammatoire**.","prio":"P2","sec":"s3"},{"id":"fc-d155-dced19","poly":"dermato","fiche":"d155","front":"Furoncle : évolution naturelle ?","back":"En **5 à 10 jours**, nécrose du follicule éliminée sous forme d'un **bourbillon** jaunâtre.","prio":"P1","sec":"s3"},{"id":"fc-d155-b5c98b","poly":"dermato","fiche":"d155","front":"Furoncle isolé : faut-il un prélèvement ?","back":"**Non**.","prio":"P1","sec":"s3"},{"id":"fc-d155-212622","poly":"dermato","fiche":"d155","front":"Furoncle compliqué : quand prélever le pus ?","back":"**Avant** l'antibiotique.","prio":"P1","sec":"s3"},{"id":"fc-d155-71705b","poly":"dermato","fiche":"d155","front":"Folliculite : autres folliculites infectieuses à évoquer ?","back":"**Fongiques** (dermatophytes/kérion, pityrosporique, *Candida albicans*) ou à **bacilles à Gram négatif**.","prio":"P2","sec":"s3"},{"id":"fc-d155-e9a901","poly":"dermato","fiche":"d155","front":"Kérion : définition ?","back":"**Dermatophytie inflammatoire** (teigne suppurée).","prio":"P2","sec":"s3"},{"id":"fc-d155-1b9abf","poly":"dermato","fiche":"d155","front":"Folliculite : pseudo-folliculites non infectieuses à évoquer ?","back":"**Maladie de Behçet**, **maladie de Crohn**, folliculite à **éosinophiles**.","prio":"P3","sec":"s3"},{"id":"fc-d155-fa7d38","poly":"dermato","fiche":"d155","front":"Furoncle du visage chez un patient au kyste connu : diagnostic différentiel à évoquer ?","back":"**Kyste épidermique** inflammatoire ou surinfecté.","prio":"P2","sec":"s3"},{"id":"fc-d155-8c4c46","poly":"dermato","fiche":"d155","front":"Hidradénite suppurée (maladie de Verneuil) : définition ?","back":"Inflammation **chronique** des follicules pilo-sébacés des zones riches en **glandes apocrines** (aisselles, sous-mammaire, anopérinéal).","prio":"P3","sec":"s3"},{"id":"fc-d155-c564aa","poly":"dermato","fiche":"d155","front":"Furoncle : complications locales ?","back":"**Anthrax** · multiplication des lésions · **dermohypodermite** péri-lésionnelle · **abcédation**.","prio":"P2","sec":"s3"},{"id":"fc-d155-7fb117","poly":"dermato","fiche":"d155","front":"Furoncle : complications systémiques ?","back":"**Très rares** : fièvre, bactériémie, foyers septiques à distance.","prio":"P3","sec":"s3"},{"id":"fc-d155-34de50","poly":"dermato","fiche":"d155","front":"Furonculose : définition ?","back":"Furoncles qui se **répètent** pendant des mois, voire des années.","prio":"P2","sec":"s3"},{"id":"fc-d155-b1d022","poly":"dermato","fiche":"d155","front":"Furonculose : facteurs à rechercher ?","back":"**Portage** de staphylocoque (nez, gorge, anus, périnée) ; rôle **discuté** du diabète ou de l'immunodépression.","prio":"P2","sec":"s3"},{"id":"fc-d155-39601b","poly":"dermato","fiche":"d155","front":"Staphylococcie maligne de la face : circonstance de survenue ?","back":"**Manipulation** d'un furoncle du visage situé dans le triangle **canthus interne – commissure labiale – aile du nez**.","prio":"P1","sec":"s3"},{"id":"fc-d155-f29c3a","poly":"dermato","fiche":"d155","front":"Staphylococcie maligne de la face : signes cliniques ?","back":"**Fièvre**, altération de l'état général, **œdème du visage**, parfois **cordon veineux** induré.","prio":"P1","sec":"s3"},{"id":"fc-d155-b8aac3","poly":"dermato","fiche":"d155","front":"Staphylococcie maligne de la face : mécanisme et complication majeure ?","back":"**Thrombophlébite superficielle septique** ; risque de **thrombophlébite du sinus caverneux** (risque vital).","prio":"P1","sec":"s3"},{"id":"fc-d155-7964d7","poly":"dermato","fiche":"d155","front":"Staphylococcie maligne de la face : degré d'urgence et fréquence ?","back":"**Urgence** ; complication grave et **exceptionnelle**.","prio":"P2","sec":"s3"},{"id":"fc-d155-a3b5b3","poly":"dermato","fiche":"d155","front":"Panaris : aspect clinique ?","back":"Repli unguéal **rouge, œdématié, douloureux**.","prio":"P2","sec":"s4"},{"id":"fc-d155-2bb7cb","poly":"dermato","fiche":"d155","front":"Abcès des parties molles : évolution clinique ?","back":"Plaque ou nodule rouge **très douloureux** → en quelques jours, **collection** molle **fluctuante**.","prio":"P1","sec":"s4"},{"id":"fc-d155-e56979","poly":"dermato","fiche":"d155","front":"Abcès des parties molles : signes généraux ?","back":"Fièvre **souvent absente** ; état général conservé ; parfois lymphangite et/ou adénopathies.","prio":"P2","sec":"s4"},{"id":"fc-d155-fe10d8","poly":"dermato","fiche":"d155","front":"Lymphangite : aspect clinique ?","back":"**Traînée linéaire** rouge, inflammatoire, de la porte d'entrée au **premier relais ganglionnaire** ; adénopathies satellites.","prio":"P2","sec":"s4"},{"id":"fc-d155-ca01be","poly":"dermato","fiche":"d155","front":"Lymphangite : germes ?","back":"***S. aureus*** ou ***S. pyogenes***.","prio":"P3","sec":"s4"},{"id":"fc-d155-4fd00b","poly":"dermato","fiche":"d155","front":"Thrombophlébite septique superficielle : forme courante ?","back":"Sur **cathéter veineux** : cordon inflammatoire induré au point de perfusion, fébricule.","prio":"P2","sec":"s4"},{"id":"fc-d155-6b1f11","poly":"dermato","fiche":"d155","front":"Thrombophlébite septique superficielle : risques ?","back":"**Extension profonde** et **emboles septiques** (activité thrombogène de *S. aureus*).","prio":"P3","sec":"s4"},{"id":"fc-d155-8f18b4","poly":"dermato","fiche":"d155","front":"Infections staphylococciques : principales manifestations toxiniques ?","back":"**SSSS** (Staphylococcal Scalded Skin Syndrome) et **syndrome du choc toxique**.","prio":"P2","sec":"s4"},{"id":"fc-d155-2978b3","poly":"dermato","fiche":"d155","front":"Abcès : faut-il un prélèvement bactériologique ?","back":"**Oui, systématique** : identification, recherche de toxines, antibiogramme.","prio":"P2","sec":"s4"},{"id":"fc-d155-2b53f6","poly":"dermato","fiche":"d155","front":"Abcès primaire, récidivant ou familial : quelle toxine rechercher ?","back":"La **leucocidine de Panton-Valentine** (*S. aureus*).","prio":"P2","sec":"s4"},{"id":"fc-d155-a2ac83","poly":"dermato","fiche":"d155","front":"Abcès secondaire : circonstances et germe ?","back":"Inoculation accidentelle, toxicomanie, injection septique ; ***S. aureus*** surtout.","prio":"P3","sec":"s4"},{"id":"fc-d155-910b40","poly":"dermato","fiche":"d155","front":"SARM communautaire : type d'infections ?","back":"Infections **suppurées**, beaucoup d'**abcès**, parfois **nécrotiques** ; émergence mondiale.","prio":"P3","sec":"s4"},{"id":"fc-d155-daeaad","poly":"dermato","fiche":"d155","front":"Plaie : étapes du germe à l'infection ?","back":"**Colonisation** → **colonisation critique** (rupture d'équilibre) → **infection** (signes inflammatoires).","prio":"P3","sec":"s4"},{"id":"fc-d155-b5bcb1","poly":"dermato","fiche":"d155","front":"Plaie chronique avec prélèvement bactériologique positif : signe-t-il l'infection ?","back":"**Non** : distinguer infection et colonisation ; c'est la **clinique** qui tranche.","prio":"P2","sec":"s4"},{"id":"fc-d155-4c93c4","poly":"dermato","fiche":"d155","front":"Érysipèle : définition ?","back":"Dermohypodermite bactérienne **non nécrosante** à **streptocoque β-hémolytique du groupe A** (plus rarement B, C, G).","prio":"P1","sec":"s5"},{"id":"fc-d155-c877d9","poly":"dermato","fiche":"d155","front":"Érysipèle : présentation typique ?","back":"Grosse jambe rouge **aiguë, fébrile, unilatérale**, de début **brutal**.","prio":"P1","sec":"s5"},{"id":"fc-d155-4d6f50","poly":"dermato","fiche":"d155","front":"Érysipèle : chronologie fièvre / placard ?","back":"Fièvre **39-40 °C** avec frissons, **précédant** souvent de quelques heures le placard.","prio":"P2","sec":"s5"},{"id":"fc-d155-3e9062","poly":"dermato","fiche":"d155","front":"Érysipèle : caractéristiques du placard ?","back":"**Rouge, œdémateux, circonscrit, douloureux** à la palpation ; parfois bulles superficielles ou purpura.","prio":"P1","sec":"s5"},{"id":"fc-d155-8a63ae","poly":"dermato","fiche":"d155","front":"Érysipèle : siège le plus fréquent ?","back":"La **jambe** (> 80 % des cas).","prio":"P2","sec":"s5"},{"id":"fc-d155-f0d876","poly":"dermato","fiche":"d155","front":"Érysipèle : terrain ?","back":"Adulte **après 40 ans** (âge moyen vers **60 ans**).","prio":"P2","sec":"s5"},{"id":"fc-d155-4221bf","poly":"dermato","fiche":"d155","front":"Érysipèle : facteurs favorisants ?","back":"Insuffisance veineuse/lymphatique, **lymphœdème**, ulcère, **intertrigo inter-orteils**, plaie, antécédent d'érysipèle, **obésité**.","prio":"P1","sec":"s5"},{"id":"fc-d155-3140fc","poly":"dermato","fiche":"d155","front":"Érysipèle : porte d'entrée fréquente à rechercher systématiquement ?","back":"**Intertrigo inter-orteils** (aussi piqûre, érosion traumatique, ulcère de jambe) ; porte d'entrée décelable cliniquement dans **2/3** des cas.","prio":"P1","sec":"s5"},{"id":"fc-d155-2c9a66","poly":"dermato","fiche":"d155","front":"Érysipèle typique sans comorbidité : examens complémentaires ?","back":"**Aucun** ; ne pas retarder l'antibiotique.","prio":"P1","sec":"s5"},{"id":"fc-d155-471ae0","poly":"dermato","fiche":"d155","front":"Érysipèle : biologie possible (formes atypiques) ?","back":"**Hyperleucocytose à PNN**, **CRP souvent > 100 mg/L** ; hémocultures peu rentables.","prio":"P2","sec":"s5"},{"id":"fc-d155-e1757e","poly":"dermato","fiche":"d155","front":"Érysipèle : valeur des D-dimères et place de l'écho-Doppler ?","back":"D-dimères **sans valeur discriminative** ; écho-Doppler veineux si **suspicion de thrombose**.","prio":"P2","sec":"s5"},{"id":"fc-d155-864f1b","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : signes généraux de sévérité ?","back":"Fièvre élevée avec **confusion**, tachypnée, **tachycardie**, **oligurie**, **hypotension**, pâleur.","prio":"P1","sec":"s5"},{"id":"fc-d155-dd2206","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : signes locaux de sévérité ?","back":"**Douleur intense**, œdème majeur, **bulles hémorragiques**, **nécrose**, **hypoesthésie**, **livedo**, **crépitation**.","prio":"P1","sec":"s5"},{"id":"fc-d155-20c26a","poly":"dermato","fiche":"d155","front":"Dermohypodermite / fasciite nécrosante : germes ?","back":"Souvent **associés** : streptocoque, staphylocoque doré, **bacilles à Gram négatif**, **anaérobies**.","prio":"P2","sec":"s5"},{"id":"fc-d155-01a2fb","poly":"dermato","fiche":"d155","front":"Suspicion de dermohypodermite nécrosante : quelle imagerie et quand ?","back":"**Sans délai** : échographie des parties molles, **IRM** (extension de la nécrose en profondeur).","prio":"P1","sec":"s5"},{"id":"fc-d155-9b5548","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante avec signes de gravité : quelle biologie ?","back":"**Enzymes musculaires**, ionogramme, créatininémie, **gaz du sang**, **coagulation** ; + prélèvement de la porte d'entrée.","prio":"P2","sec":"s5"},{"id":"fc-d155-2a484e","poly":"dermato","fiche":"d155","front":"Nécrose d'ischémie artérielle aiguë : élément la distinguant d'une dermohypodermite nécrosante ?","back":"En général **sans érythème ni œdème**.","prio":"P3","sec":"s5"},{"id":"fc-d155-d41492","poly":"dermato","fiche":"d155","front":"Fasciite nécrosante suspectée : quel médicament rechercher et arrêter ?","back":"Les **AINS**.","prio":"P1","sec":"s5"},{"id":"fc-d155-6425b4","poly":"dermato","fiche":"d155","front":"Érysipèle sous traitement : extension du placard dans les 24 premières heures, signification ?","back":"**Fréquente** ; pas d'amélioration à **48 h** ou extension ultérieure → hospitaliser.","prio":"P2","sec":"s5"},{"id":"fc-d155-cc3dfb","poly":"dermato","fiche":"d155","front":"Candida albicans : habitat normal ?","back":"Saprophyte du **tube digestif** et des **muqueuses génitales** de la femme ; **jamais** sur une peau saine.","prio":"P1","sec":"s6"},{"id":"fc-d155-280658","poly":"dermato","fiche":"d155","front":"Candida : conditions favorables à son développement ?","back":"**Chaleur**, **humidité**, **pH acide**, **sucre**.","prio":"P1","sec":"s6"},{"id":"fc-d155-098a77","poly":"dermato","fiche":"d155","front":"Candidose : facteurs favorisants locaux ?","back":"Humidité, **macération** (eau, occlusion, obésité, transpiration), pH acide, **prothèse dentaire**, xérostomie (mucite radique).","prio":"P1","sec":"s6"},{"id":"fc-d155-19a99f","poly":"dermato","fiche":"d155","front":"Candidose : facteur local exogène professionnel typique ?","back":"**Pâtissier** (sucre au contact répété de la peau).","prio":"P2","sec":"s6"},{"id":"fc-d155-1c6238","poly":"dermato","fiche":"d155","front":"Candidose : terrains d'immunosuppression favorisants ?","back":"**Congénitale** ; **physiologique** (âges extrêmes, **grossesse**) ; **acquise** (immunosuppresseurs, corticoïdes, VIH, **diabète**).","prio":"P1","sec":"s6"},{"id":"fc-d155-5aedbd","poly":"dermato","fiche":"d155","front":"Candidose : médicaments favorisants ?","back":"**Antibiotiques** systémiques ; **œstroprogestatifs** (atteinte génitale).","prio":"P1","sec":"s6"},{"id":"fc-d155-72db9b","poly":"dermato","fiche":"d155","front":"Candidose : voie de contamination principale ?","back":"**Endogène** (+++), d'origine **digestive** ou **génitale**.","prio":"P1","sec":"s6"},{"id":"fc-d155-016175","poly":"dermato","fiche":"d155","front":"Candidose : situations de contamination exogène (rare) ?","back":"**Nouveau-né** (chorio-amniotite sur vaginite maternelle) ; adulte (**transmission sexuelle**).","prio":"P3","sec":"s6"},{"id":"fc-d155-4ee2cb","poly":"dermato","fiche":"d155","front":"Candida : septicémies et atteintes viscérales profondes, sur quel terrain ?","back":"**Exceptionnelles** : immunosuppression profonde, **aplasie médullaire**, **prématuré**.","prio":"P2","sec":"s6"},{"id":"fc-d155-9488af","poly":"dermato","fiche":"d155","front":"C. albicans isolé d'une lésion cutanée : signification ?","back":"**Toujours pathogène**.","prio":"P1","sec":"s6"},{"id":"fc-d155-2704bb","poly":"dermato","fiche":"d155","front":"Candidose récidivante : que faire au-delà de l'antifongique ?","back":"Rechercher et corriger les **facteurs favorisants**.","prio":"P1","sec":"s6"},{"id":"fc-d155-f0fb8a","poly":"dermato","fiche":"d155","front":"Candidoses digestives : localisations prédominantes ?","back":"Les **deux extrémités** du tube digestif : **bouche** et **anus**.","prio":"P2","sec":"s7"},{"id":"fc-d155-766b33","poly":"dermato","fiche":"d155","front":"Candidoses digestives : terrains où elles sont fréquentes ?","back":"**Âges extrêmes** (nouveau-né, âgé avec prothèse), **immunodéprimé**, sous **antibiotiques**.","prio":"P2","sec":"s7"},{"id":"fc-d155-f1392e","poly":"dermato","fiche":"d155","front":"Candidose buccale : citer les 4 formes ?","back":"**Perlèche** · **glossite** · **stomatite** · **muguet** (isolées ou associées).","prio":"P1","sec":"s7"},{"id":"fc-d155-36f340","poly":"dermato","fiche":"d155","front":"Perlèche : définition ?","back":"**Intertrigo de la commissure des lèvres** : fond rouge, fissuré ± macéré ; extension possible à la lèvre (**chéilite**).","prio":"P1","sec":"s7"},{"id":"fc-d155-8bed6e","poly":"dermato","fiche":"d155","front":"Perlèche : diagnostics différentiels ?","back":"Perlèche **streptococcique**, **syphilitique**, **herpétique**, **carentielle** (fer, zinc).","prio":"P3","sec":"s7"},{"id":"fc-d155-74c112","poly":"dermato","fiche":"d155","front":"Glossite candidosique : aspect ?","back":"Langue **rouge et dépapillée**, souvent avec stomatite.","prio":"P2","sec":"s7"},{"id":"fc-d155-f9ac13","poly":"dermato","fiche":"d155","front":"Stomatite candidosique : signes ?","back":"Bouche sèche, brûlures, goût métallique ; gencives et palais **rouges, brillants, vernissés**, douloureux.","prio":"P2","sec":"s7"},{"id":"fc-d155-1ae165","poly":"dermato","fiche":"d155","front":"Muguet : aspect ?","back":"Face interne des **joues** : érythème + **dépôt blanchâtre** qui **se détache facilement** au raclage.","prio":"P1","sec":"s7"},{"id":"fc-d155-c2495e","poly":"dermato","fiche":"d155","front":"Muguet : signe d'extension pharyngée ?","back":"**Dysphagie**.","prio":"P2","sec":"s7"},{"id":"fc-d155-a979dd","poly":"dermato","fiche":"d155","front":"Muguet : diagnostics différentiels ?","back":"**Leucoplasies**, **lichen**.","prio":"P3","sec":"s7"},{"id":"fc-d155-b7a273","poly":"dermato","fiche":"d155","front":"Candidose œsophagienne : que doit-elle faire rechercher ?","back":"Une **immunodépression** (VIH, lymphocytes < 400/mm³, hémopathie, traitements).","prio":"P2","sec":"s7"},{"id":"fc-d155-0495ed","poly":"dermato","fiche":"d155","front":"Candidose anorectale : aspect ?","back":"**Anite** prurigineuse, rouge, érosive, suintante ; extension possible en intertrigo interfessier bordé de pustules.","prio":"P3","sec":"s7"},{"id":"fc-d155-cd9e59","poly":"dermato","fiche":"d155","front":"Candidose génitale : caractère sexuellement transmissible ?","back":"**Controversé** (surtout chez la femme).","prio":"P2","sec":"s7"},{"id":"fc-d155-97bebb","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique : terrain ?","back":"Femme jeune ou d'âge moyen, **grossesse** ++ ; **rare après 50 ans**.","prio":"P2","sec":"s7"},{"id":"fc-d155-127e68","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique aiguë : aspect des leucorrhées ?","back":"Abondantes, blanc-jaunâtre, « **lait caillé** », stagnant dans les plis.","prio":"P1","sec":"s7"},{"id":"fc-d155-abc7f1","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique aiguë : autres signes ?","back":"Vulve **rouge et œdémateuse**, **prurit intense** ± dyspareunie ; extension aux plis ; ± cervicite, urétrite.","prio":"P2","sec":"s7"},{"id":"fc-d155-15e221","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique récidivante : mécanisme et retentissement ?","back":"Prolifération **répétée** d'une colonisation saprophyte ; fort **retentissement psychique**.","prio":"P3","sec":"s7"},{"id":"fc-d155-0cb676","poly":"dermato","fiche":"d155","front":"Vulvovaginite : diagnostics différentiels infectieux ?","back":"**Vulvovaginite bactérienne**, **trichomonose**.","prio":"P3","sec":"s7"},{"id":"fc-d155-aaec94","poly":"dermato","fiche":"d155","front":"Vulvovaginite : diagnostics différentiels inflammatoires et tumoraux ?","back":"**Lichen scléreux**, eczéma de contact, lichénification, psoriasis ; **carcinome in situ**, **Paget extramammaire**.","prio":"P3","sec":"s7"},{"id":"fc-d155-46d5a1","poly":"dermato","fiche":"d155","front":"Candidose génitale de l'homme : présentation ?","back":"**Rare**, souvent pauvre (picotements après rapports, sans lésion visible).","prio":"P2","sec":"s7"},{"id":"fc-d155-b60d7f","poly":"dermato","fiche":"d155","front":"Balanite candidosique : diagnostics différentiels imposant une biopsie au moindre doute ?","back":"**Syphilis secondaire**, **herpès**, balanite de macération, **psoriasis**, **carcinome in situ**.","prio":"P2","sec":"s7"},{"id":"fc-d155-4e864f","poly":"dermato","fiche":"d155","front":"Méatite candidosique : comment l'authentifier ?","back":"**Prélèvement mycologique** (+++), car diagnostic souvent porté **par excès**.","prio":"P2","sec":"s7"},{"id":"fc-d155-49091b","poly":"dermato","fiche":"d155","front":"Urétrite candidosique masculine : fréquence et terrain ?","back":"**Exceptionnelle**, sur terrain d'**immunodépression**.","prio":"P3","sec":"s7"},{"id":"fc-d155-3c1fe0","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique : facteurs favorisants ?","back":"**Macération**, **obésité**, **diabète**, **manque d'hygiène**.","prio":"P1","sec":"s8"},{"id":"fc-d155-ddd564","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique : aspect ?","back":"Fond de pli **rouge**, **fissuré**, **enduit crémeux** malodorant ; **pustules** ou **collerette** en bordure.","prio":"P1","sec":"s8"},{"id":"fc-d155-4c7427","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique : évolution ?","back":"**Chronique**, souvent **récidivante**.","prio":"P3","sec":"s8"},{"id":"fc-d155-6f15ff","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique des grands plis : localisations ?","back":"Génito-crural du nourrisson, **interfessier**, **sous-mammaire**, repli abdominal de l'obèse.","prio":"P2","sec":"s8"},{"id":"fc-d155-702275","poly":"dermato","fiche":"d155","front":"Intertrigo des grands plis : quelle distribution oriente vers Candida ?","back":"Atteinte **bilatérale et symétrique**.","prio":"P1","sec":"s8"},{"id":"fc-d155-85e315","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique des petits plis : facteurs ?","back":"**Eau** (plonge, ménage) ou **sucre** (pâtissiers).","prio":"P2","sec":"s8"},{"id":"fc-d155-a68841","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique des petits plis : diagnostics différentiels ?","back":"**Dermatophytose**, **dyshidrose**, **psoriasis**.","prio":"P3","sec":"s8"},{"id":"fc-d155-46fa8b","poly":"dermato","fiche":"d155","front":"Psoriasis inversé : en quoi diffère-t-il d'un intertrigo candidosique ?","back":"Rouge vernissé, **bien limité**, **sans pustule ni collerette** ; plaque typique ailleurs.","prio":"P2","sec":"s8"},{"id":"fc-d155-640294","poly":"dermato","fiche":"d155","front":"Dermatite de contact des plis : deux aspects ?","back":"**Allergique** (très prurigineuse, vésiculeuse, suintante) ou **caustique** (rouge, sèche, crevassée).","prio":"P3","sec":"s8"},{"id":"fc-d155-10b9d8","poly":"dermato","fiche":"d155","front":"Érythrasma : germe et aspect ?","back":"**Corynébactéries** ; brun chamoisé, **souvent symétrique**, teinte homogène, **asymptomatique**.","prio":"P3","sec":"s8"},{"id":"fc-d155-caee51","poly":"dermato","fiche":"d155","front":"Érythrasma : aspect en lumière de Wood ?","back":"Fluorescence **rouge corail**.","prio":"P3","sec":"s8"},{"id":"fc-d155-3b74ba","poly":"dermato","fiche":"d155","front":"Folliculite candidosique du cuir chevelu : terrain associé ?","back":"**Héroïnomanie intraveineuse** (septicémie à *C. albicans*).","prio":"P2","sec":"s8"},{"id":"fc-d155-7c16e7","poly":"dermato","fiche":"d155","front":"Onychomycose candidosique : terrain ?","back":"Adultes aux mains souvent dans l'**eau** (ménage) ou le **sucre** (pâtissiers).","prio":"P2","sec":"s8"},{"id":"fc-d155-098598","poly":"dermato","fiche":"d155","front":"Onychomycose candidosique : comment débute-t-elle ?","back":"Par un **péri-onyxis** : tuméfaction douloureuse du repli, pus possible à la pression.","prio":"P1","sec":"s8"},{"id":"fc-d155-aec909","poly":"dermato","fiche":"d155","front":"Onychomycose candidosique : teinte de la tablette atteinte ?","back":"**Marron-verdâtre**, sur les bords proximaux et latéraux.","prio":"P2","sec":"s8"},{"id":"fc-d155-cd383a","poly":"dermato","fiche":"d155","front":"Onychomycose candidosique : surinfection fréquente et sa teinte ?","back":"**Bacille pyocyanique** : teinte **bleu-vert**.","prio":"P3","sec":"s8"},{"id":"fc-d155-b3613d","poly":"dermato","fiche":"d155","front":"Dermatophytes anthropophiles : citer des espèces ?","back":"*T. rubrum*, *T. interdigitale*, *T. violaceum*, *T. soudanense*, *T. tonsurans*.","prio":"P3","sec":"s9"},{"id":"fc-d155-a6f20a","poly":"dermato","fiche":"d155","front":"Dermatophytes anthropophiles : mode de transmission ?","back":"Surtout **indirecte** : sols (squames), peignes, vêtements ; piscines, douches, vestiaires ; favorisée par la **macération**.","prio":"P1","sec":"s9"},{"id":"fc-d155-9dac5d","poly":"dermato","fiche":"d155","front":"Dermatophytes zoophiles : espèces ?","back":"***Microsporum canis***, ***T. mentagrophytes***.","prio":"P2","sec":"s9"},{"id":"fc-d155-736431","poly":"dermato","fiche":"d155","front":"Dermatophytes zoophiles : pourquoi des lésions inflammatoires ?","back":"Ils sont **mal adaptés à l'homme**.","prio":"P2","sec":"s9"},{"id":"fc-d155-0f3ea9","poly":"dermato","fiche":"d155","front":"Dermatophytes telluriques : exemple et mode de contamination ?","back":"***M. gypseum*** ; sol (terre, sable) lors d'une petite effraction, ou animal vecteur.","prio":"P3","sec":"s9"},{"id":"fc-d155-05f41d","poly":"dermato","fiche":"d155","front":"Dermatophytose : facteur favorisant principal ?","back":"**Altération de l'épiderme**, quelle qu'en soit la cause.","prio":"P1","sec":"s9"},{"id":"fc-d155-064cae","poly":"dermato","fiche":"d155","front":"Dermatophytose : autres facteurs favorisants ?","back":"**Humidité**, occlusion des plis, **immunodépression**, **diabète**.","prio":"P2","sec":"s9"},{"id":"fc-d155-04804b","poly":"dermato","fiche":"d155","front":"Intertrigo dermatophytique des plis : répartition des espèces ?","back":"***T. rubrum*** 70-80 %, *T. interdigitale* 15-20 %, *Epidermophyton floccosum* 5 %.","prio":"P2","sec":"s9"},{"id":"fc-d155-64187a","poly":"dermato","fiche":"d155","front":"Dermatophytie : aspect typique des lésions ?","back":"**Arrondies, bien limitées**, bordure érythémato-squameuse ± vésiculo-pustuleuse, **extension centrifuge**, **guérison centrale**.","prio":"P1","sec":"s9"},{"id":"fc-d155-968296","poly":"dermato","fiche":"d155","front":"Dermatophytie palmo-plantaire : aspect et élément évocateur ?","back":"Aspect **hyperkératosique** ; atteinte **unilatérale** évocatrice.","prio":"P2","sec":"s9"},{"id":"fc-d155-5f271c","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils dermatophytique : espaces les plus touchés ?","back":"**3e et 4e espaces**.","prio":"P1","sec":"s9"},{"id":"fc-d155-f1a2c6","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils dermatophytique : aspect ?","back":"Desquamation **sèche ou suintante** ± fissure, parfois vésiculo-bulles ; prurit variable.","prio":"P2","sec":"s9"},{"id":"fc-d155-79005b","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils dermatophytique : complications ?","back":"**Érysipèle de jambe** (porte d'entrée), extension au pied (*tinea pedis*), lésions à distance, atteinte pieds-main.","prio":"P1","sec":"s9"},{"id":"fc-d155-620290","poly":"dermato","fiche":"d155","front":"Intertrigo inguinal dermatophytique : aspect ?","back":"Placard bistre à **bordure active** érythémato-squameuse ± vésiculeuse, **guérison centrale**, extension vers la cuisse ; prurit.","prio":"P1","sec":"s9"},{"id":"fc-d155-e0ab66","poly":"dermato","fiche":"d155","front":"Intertrigo inguinal dermatophytique : latéralité et fond du pli ?","back":"Classiquement **unilatéral** ; fond du pli **ni rouge ni fissuré**.","prio":"P1","sec":"s9"},{"id":"fc-d155-c12010","poly":"dermato","fiche":"d155","front":"Intertrigo inguinal dermatophytique : origine fréquente ?","back":"**Auto-inoculation** depuis les **pieds**.","prio":"P2","sec":"s9"},{"id":"fc-d155-d24e23","poly":"dermato","fiche":"d155","front":"Dermatophytie de la peau glabre : aspect ?","back":"Plaques arrondies ou polycycliques, bordure rouge **vésiculeuse et/ou squameuse**, guérison centrale ; zones découvertes ; prurit.","prio":"P1","sec":"s9"},{"id":"fc-d155-9e8ded","poly":"dermato","fiche":"d155","front":"Dermatophytie de la peau glabre : origines ?","back":"Les **pieds** (*T. rubrum*) ou un **animal** (chat, chien : *M. canis*).","prio":"P2","sec":"s9"},{"id":"fc-d155-5e05d2","poly":"dermato","fiche":"d155","front":"Kératodermie palmo-plantaire dermatophytique : distribution typique ?","back":"« **One hand, two feet** » : paume **unilatérale** + plantes **bilatérales**.","prio":"P1","sec":"s9"},{"id":"fc-d155-227cd8","poly":"dermato","fiche":"d155","front":"Kératodermie palmo-plantaire dermatophytique : aspect ?","back":"**Blanchâtre, farineuse**, plis marqués ; parfois ongles atteints.","prio":"P3","sec":"s9"},{"id":"fc-d155-5fdfc8","poly":"dermato","fiche":"d155","front":"Dermatophytie de l'immunodéprimé : particularités ?","back":"**Atypique** : ni bordure évolutive ni prurit, lésions **profuses**, extension rapide.","prio":"P2","sec":"s9"},{"id":"fc-d155-7321ab","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils : diagnostics différentiels ?","back":"***Candida*** (rare, plutôt 1er espace) ; **eczéma dyshidrosique** ; intertrigo à **bacille Gram négatif**.","prio":"P2","sec":"s9"},{"id":"fc-d155-398a72","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils à bacille Gram négatif : indices ?","back":"**Érosif, douloureux**, plusieurs espaces, très suintant, verdâtre, odeur âcre, **résistant aux antifongiques**.","prio":"P3","sec":"s9"},{"id":"fc-d155-3eb7e7","poly":"dermato","fiche":"d155","front":"Intertrigo inguinal : diagnostics différentiels ?","back":"**Candidose**, dermatite d'irritation, **eczéma de contact**, **psoriasis inversé**.","prio":"P2","sec":"s9"},{"id":"fc-d155-f7f40f","poly":"dermato","fiche":"d155","front":"Lésion annulaire de la peau glabre : diagnostics différentiels ?","back":"**Eczéma nummulaire**, psoriasis annulaire, **pityriasis rosé de Gibert**, lupus cutané subaigu.","prio":"P3","sec":"s9"},{"id":"fc-d155-b7b24f","poly":"dermato","fiche":"d155","front":"Teigne : définition ?","back":"Dermatophytie avec **parasitisme des cheveux ou des poils**.","prio":"P1","sec":"s10"},{"id":"fc-d155-d60e17","poly":"dermato","fiche":"d155","front":"Teigne : terrain ?","back":"Surtout **enfant prépubère** ; rarement l'adulte (teigne de la **barbe** chez l'homme).","prio":"P1","sec":"s10"},{"id":"fc-d155-0f6943","poly":"dermato","fiche":"d155","front":"Teigne : mode de transmission interhumaine ?","back":"**Indirecte** (bonnets, matériel de coiffure) → petites épidémies familiales.","prio":"P2","sec":"s10"},{"id":"fc-d155-a9ab42","poly":"dermato","fiche":"d155","front":"Teigne : maladie à déclaration obligatoire ?","back":"**Non**.","prio":"P1","sec":"s10"},{"id":"fc-d155-8909ce","poly":"dermato","fiche":"d155","front":"Cuir chevelu : quel aspect doit faire évoquer une teigne ?","back":"**Squameux, croûteux, pustuleux et alopécique**.","prio":"P1","sec":"s10"},{"id":"fc-d155-a2a709","poly":"dermato","fiche":"d155","front":"Teigne tondante microsporique : aspect ?","back":"**Grandes** plaques alopéciques squameuses, **une ou peu nombreuses** ; cheveux cassés à quelques mm.","prio":"P1","sec":"s10"},{"id":"fc-d155-bdfdeb","poly":"dermato","fiche":"d155","front":"Teigne tondante trichophytique : aspect ?","back":"**Multiples petites** plaques éparses squameuses ou croûteuses ; cheveux cassés **au ras**.","prio":"P1","sec":"s10"},{"id":"fc-d155-1d5e2d","poly":"dermato","fiche":"d155","front":"Teignes tondantes trichophytiques : origine ?","back":"Toutes **anthropophiles**.","prio":"P2","sec":"s10"},{"id":"fc-d155-d54a74","poly":"dermato","fiche":"d155","front":"Kérion : aspect clinique ?","back":"Lésions plurinodulaires **très inflammatoires**, orifices laissant sourdre pus et sang **sans vraie collection** ; dépilation.","prio":"P1","sec":"s10"},{"id":"fc-d155-fd0e3a","poly":"dermato","fiche":"d155","front":"Kérion : origine du dermatophyte ?","back":"**Animale** (*T. mentagrophytes*, équidés) ou **tellurique** ; milieu rural ; parfois après **corticothérapie locale**.","prio":"P2","sec":"s10"},{"id":"fc-d155-cd2db6","poly":"dermato","fiche":"d155","front":"Teigne de la barbe : aspect et diagnostic différentiel ?","back":"Folliculite aiguë suppurée ; difficile à distinguer d'un **sycosis staphylococcique** → **prélèvement mycologique**.","prio":"P2","sec":"s10"},{"id":"fc-d155-aa8dd9","poly":"dermato","fiche":"d155","front":"Teigne : formes atypiques imposant un prélèvement mycologique ?","back":"État pelliculaire diffus, teigne **modifiée par des topiques**, teigne de l'**immunodéprimé** (simule DS ou psoriasis).","prio":"P2","sec":"s10"},{"id":"fc-d155-6a6e84","poly":"dermato","fiche":"d155","front":"Teigne : quels diagnostics différentiels ne sont pas alopéciants ?","back":"**Psoriasis** du cuir chevelu et **dermatite séborrhéique**.","prio":"P2","sec":"s10"},{"id":"fc-d155-318b0f","poly":"dermato","fiche":"d155","front":"Pelade : élément la distinguant d'une teigne ?","back":"**Pas de squame**.","prio":"P1","sec":"s10"},{"id":"fc-d155-ab9d54","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : localisation et espèces ?","back":"**Orteils** (80 %) : ***T. rubrum*** 80 %, *T. interdigitale* 20 % ; presque toujours avec atteinte interdigitale ou plantaire.","prio":"P2","sec":"s10"},{"id":"fc-d155-4695f6","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : début et évolution ?","back":"Début **distal et/ou latéral** : leuconychie → hyperkératose sous-unguéale → **onycholyse**.","prio":"P1","sec":"s10"},{"id":"fc-d155-897c2b","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : éléments le distinguant de l'onyxis candidosique ?","back":"**Pas de péri-onyxis** ; leuconychie **blanc ivoire**.","prio":"P1","sec":"s10"},{"id":"fc-d155-7ecc2a","poly":"dermato","fiche":"d155","front":"Onyxis des doigts : dermatophyte ou Candida plus fréquent ?","back":"**Candida** : l'onyxis dermatophytique y est beaucoup moins fréquent.","prio":"P2","sec":"s10"},{"id":"fc-d155-725c24","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : diagnostics différentiels ?","back":"Onychopathie **post-traumatique** (chaussures, sportif) ; **psoriasis**.","prio":"P2","sec":"s10"},{"id":"fc-d155-a3a38f","poly":"dermato","fiche":"d155","front":"Candidose : l'examen mycologique est-il systématique ?","back":"**Non** si clinique évidente ou efficacité d'un traitement d'épreuve ; demandé si atypie ou certaines localisations.","prio":"P1","sec":"s11"},{"id":"fc-d155-950c26","poly":"dermato","fiche":"d155","front":"Prélèvement mycologique pour Candida : indications ?","back":"**Atypie ou doute** (avant traitement), lésions **chroniques ou récidivantes**, **échec** d'un traitement bien suivi.","prio":"P2","sec":"s11"},{"id":"fc-d155-587e20","poly":"dermato","fiche":"d155","front":"Prélèvement mycologique pour Candida : technique ?","back":"**Écouvillon** sur peau et muqueuses ; **fragment de tablette** pour l'ongle.","prio":"P2","sec":"s11"},{"id":"fc-d155-f146df","poly":"dermato","fiche":"d155","front":"Candida : que montre l'examen direct ?","back":"**Levures bourgeonnantes** ; pseudo-filaments ou filaments = **pouvoir pathogène**.","prio":"P2","sec":"s11"},{"id":"fc-d155-5745d1","poly":"dermato","fiche":"d155","front":"Candida : délai de culture sur Sabouraud ?","back":"**48 heures**.","prio":"P2","sec":"s11"},{"id":"fc-d155-f599bf","poly":"dermato","fiche":"d155","front":"Dermatophytie : quand faire le prélèvement mycologique ?","back":"**Avant** tout antifongique (sauf intertrigo inter-orteils), au besoin après une **fenêtre d'au moins 2 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-d155-c554fe","poly":"dermato","fiche":"d155","front":"Dermatophytie : pourquoi le prélèvement est-il indispensable ?","back":"Clinique **peu spécifique** ; l'**espèce** oriente l'enquête d'origine et le traitement.","prio":"P2","sec":"s11"},{"id":"fc-d155-c066a6","poly":"dermato","fiche":"d155","front":"Dermatophytie : technique de prélèvement ?","back":"**Squames**, **cheveux** ou fragments d'**ongle** ; **pas d'écouvillon**.","prio":"P2","sec":"s11"},{"id":"fc-d155-a8ed24","poly":"dermato","fiche":"d155","front":"Dermatophyte : examen direct et délai de culture ?","back":"**Filaments septés** = diagnostic ; culture sur Sabouraud en **3 à 4 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-d155-f4e272","poly":"dermato","fiche":"d155","front":"Culture positive à C. albicans sur une muqueuse : comment l'interpréter ?","back":"Selon le **nombre de colonies** et la présence de **filaments/pseudo-filaments** (saprophyte).","prio":"P3","sec":"s11"},{"id":"fc-d155-e9abcd","poly":"dermato","fiche":"d155","front":"Mycose : place de la biopsie ?","back":"**Pas l'examen de référence** ; diagnostic **fortuit** (filaments au **PAS**), ex. dermatophytie sous dermocorticoïde.","prio":"P3","sec":"s11"},{"id":"fc-d155-c49fc9","poly":"dermato","fiche":"d155","front":"Mycose : quelles atteintes rendent l'examen mycologique indispensable ?","back":"Atteintes des **phanères** (ongles, cuir chevelu).","prio":"P2","sec":"s11"},{"id":"fc-d155-f408cf","poly":"dermato","fiche":"d155","front":"Intertrigo : quelle atteinte muqueuse distingue Candida d'un dermatophyte ?","back":"*Candida* peut toucher les **muqueuses** ; le dermatophyte **jamais**.","prio":"P1","sec":"s12"},{"id":"fc-d155-b597aa","poly":"dermato","fiche":"d155","front":"Intertrigo : comparer le fond du pli Candida vs dermatophyte ?","back":"Candida : rouge, **fissuré**, enduit crémeux. Dermatophyte : **ni rouge ni fissuré**, guérison centrale.","prio":"P1","sec":"s12"},{"id":"fc-d155-b0c4c0","poly":"dermato","fiche":"d155","front":"Intertrigo : comparer la bordure Candida vs dermatophyte ?","back":"Candida : **pustules** satellites, collerette. Dermatophyte : **bordure active** érythémato-squameuse, contours circinés.","prio":"P1","sec":"s12"},{"id":"fc-d155-11a11e","poly":"dermato","fiche":"d155","front":"Kérion : quel traitement local peut le favoriser ?","back":"Une **corticothérapie locale**.","prio":"P2","sec":"s12"},{"id":"fc-d155-47935a","poly":"dermato","fiche":"d155","front":"Impétigo localisé : soins locaux ?","back":"Toilette **eau + savon** 1 à 2 fois/j, rinçage soigneux ; **pas d'antiseptique local**.","prio":"P2","sec":"s13"},{"id":"fc-d155-c2850f","poly":"dermato","fiche":"d155","front":"Impétigo localisé : antibiotique local, molécule et modalités ?","back":"**Mupirocine**, 2 à 3 applications/j pendant **5 jours**.","prio":"P2","sec":"s13"},{"id":"fc-d155-31ae50","poly":"dermato","fiche":"d155","front":"Impétigo : que traiter en plus de l'infection ?","back":"Une **dermatose sous-jacente** (eczéma, varicelle, gale, poux).","prio":"P2","sec":"s13"},{"id":"fc-d155-589d20","poly":"dermato","fiche":"d155","front":"Impétigo grave : faut-il attendre le prélèvement pour l'antibiotique oral ?","back":"**Non** : antibiotique **oral tout de suite** ; **pas d'antibiotique local**.","prio":"P2","sec":"s13"},{"id":"fc-d155-01df1d","poly":"dermato","fiche":"d155","front":"Impétigo grave : soin local après la toilette ?","back":"**Vaseline** 2 fois/jour.","prio":"P3","sec":"s13"},{"id":"fc-d155-fe5794","poly":"dermato","fiche":"d155","front":"Impétigo grave : faut-il couvrir le SARM en probabiliste ?","back":"**Non**, inutile en première intention.","prio":"P2","sec":"s13"},{"id":"fc-d155-8c47d4","poly":"dermato","fiche":"d155","front":"Impétigo grave de l'enfant : antibiotique oral et durée ?","back":"**Amoxicilline/acide clavulanique** ou **céfadroxil**, **7 jours** ; allergie aux pénicillines : **josamycine**.","prio":"P2","sec":"s13"},{"id":"fc-d155-5fac8b","poly":"dermato","fiche":"d155","front":"Impétigo grave de l'adulte : antibiotique oral et durée ?","back":"**Pristinamycine** ou **céfalexine**, **7 jours**.","prio":"P2","sec":"s13"},{"id":"fc-d155-0e96ab","poly":"dermato","fiche":"d155","front":"Impétigo : éviction de la collectivité ?","back":"**3 jours** après le début du traitement si les lésions ne peuvent pas être **couvertes par un pansement**.","prio":"P2","sec":"s13"},{"id":"fc-d155-715c3e","poly":"dermato","fiche":"d155","front":"Furoncle isolé : mesures ?","back":"**Ne pas presser** ; eau + savon, lavage des mains ; inciser la pointe pour évacuer le **bourbillon** ; pansement.","prio":"P2","sec":"s14"},{"id":"fc-d155-d64e99","poly":"dermato","fiche":"d155","front":"Furoncle isolé : antibiotique ?","back":"**Aucun**, ni local ni général.","prio":"P2","sec":"s14"},{"id":"fc-d155-3ef295","poly":"dermato","fiche":"d155","front":"Furoncle compliqué : antibiotique oral et durée ?","back":"**Clindamycine** ou **pristinamycine**, **5 jours** ; pas d'antibiotique local.","prio":"P2","sec":"s14"},{"id":"fc-d155-9beeb7","poly":"dermato","fiche":"d155","front":"Furonculose en poussée : traitement ?","back":"Hygiène quotidienne, douche **chlorhexidine** 1/j 7 j, pansements ; **clindamycine ou pristinamycine** oral **7 jours**.","prio":"P2","sec":"s14"},{"id":"fc-d155-bff016","poly":"dermato","fiche":"d155","front":"Furonculose : quand décoloniser et qui ?","back":"**Après guérison** de la poussée ; le patient **et l'entourage** (même toit, contacts proches).","prio":"P2","sec":"s14"},{"id":"fc-d155-f81524","poly":"dermato","fiche":"d155","front":"Furonculose : moyens de décolonisation ?","back":"**Mupirocine nasale** 2/j 7 j ; **chlorhexidine** moussante (savon, shampooing) ; bains de bouche chlorhexidine ; hygiène.","prio":"P2","sec":"s14"},{"id":"fc-d155-3f6b67","poly":"dermato","fiche":"d155","front":"Bain de bouche à la chlorhexidine : à partir de quel âge chez l'enfant ?","back":"À partir de **6 ans**.","prio":"P3","sec":"s14"},{"id":"fc-d155-f15da2","poly":"dermato","fiche":"d155","front":"Panaris : traitement ?","back":"**Antiseptiques locaux** ; antistaphylococcique oral si **résistance/complication** ; **incision-drainage** si collection.","prio":"P2","sec":"s15"},{"id":"fc-d155-6b6a62","poly":"dermato","fiche":"d155","front":"Abcès : traitement ?","back":"**Chirurgical** (incision-drainage) **et médical** : antibiotique oral **5 jours**.","prio":"P2","sec":"s15"},{"id":"fc-d155-957ed4","poly":"dermato","fiche":"d155","front":"Abcès : antibiotiques oraux possibles ?","back":"**Clindamycine**, **pristinamycine**, **oxacilline** ou **cloxacilline**.","prio":"P3","sec":"s15"},{"id":"fc-d155-3ea74f","poly":"dermato","fiche":"d155","front":"Lymphangite : antibiothérapie ?","back":"Voie **générale**, **adaptée aux prélèvements** bactériologiques.","prio":"P3","sec":"s15"},{"id":"fc-d155-eb6c91","poly":"dermato","fiche":"d155","front":"Thrombophlébite septique sur cathéter : traitement ?","back":"**Retrait du cathéter**, antiseptiques ; antibiotique systémique seulement si **résistance ou complication**.","prio":"P3","sec":"s15"},{"id":"fc-d155-bff5f7","poly":"dermato","fiche":"d155","front":"Érysipèle : quel geste simple au début pour suivre l'évolution ?","back":"**Marquer les bords** du placard.","prio":"P2","sec":"s16"},{"id":"fc-d155-2e5776","poly":"dermato","fiche":"d155","front":"Érysipèle : mesure physique associée ?","back":"**Repos au lit, jambe surélevée**, jusqu'à régression des signes inflammatoires.","prio":"P2","sec":"s16"},{"id":"fc-d155-8e7af8","poly":"dermato","fiche":"d155","front":"Érysipèle : antibiotique de référence, dose et durée ?","back":"**Amoxicilline** per os **3 à 4,5 g/j**, **7 jours**.","prio":"P1","sec":"s16"},{"id":"fc-d155-916f25","poly":"dermato","fiche":"d155","front":"Érysipèle et allergie à la pénicilline : alternatives ?","back":"**Pristinamycine** (3 g/j en 3 prises) ou **clindamycine**.","prio":"P1","sec":"s16"},{"id":"fc-d155-b3afa9","poly":"dermato","fiche":"d155","front":"Érysipèle sans signe de gravité : modalité de traitement ?","back":"Traitement **oral à domicile**.","prio":"P1","sec":"s16"},{"id":"fc-d155-b84ae7","poly":"dermato","fiche":"d155","front":"Érysipèle : critères d'hospitalisation ?","back":"Doute diagnostique, **signes de gravité**, risque de complication, **comorbidité**, contexte social, **pas d'amélioration à 48 h** ou extension.","prio":"P1","sec":"s16"},{"id":"fc-d155-b3e4a8","poly":"dermato","fiche":"d155","front":"Érysipèle : comorbidités imposant l'hospitalisation ?","back":"**Obésité morbide**, insuffisance hépatique, rénale sévère ou cardiaque, **immunodépression**, **diabète déséquilibré**.","prio":"P2","sec":"s16"},{"id":"fc-d155-6e027b","poly":"dermato","fiche":"d155","front":"Érysipèle hospitalisé : schéma de l'amoxicilline ?","back":"IV **50 mg/kg/j** jusqu'à l'**apyrexie**, puis relais oral **3 à 4,5 g/j en 3 prises** ; **7 j** au total.","prio":"P2","sec":"s16"},{"id":"fc-d155-b6ba9c","poly":"dermato","fiche":"d155","front":"Érysipèle : antalgiques ?","back":"Antalgiques **sans AINS**.","prio":"P1","sec":"s16"},{"id":"fc-d155-86c01b","poly":"dermato","fiche":"d155","front":"Érysipèle : place de l'anticoagulation préventive ?","back":"**Seulement** si facteurs de risque thromboembolique (héparine calcique ou HBPM).","prio":"P1","sec":"s16"},{"id":"fc-d155-ecb4c3","poly":"dermato","fiche":"d155","front":"Érysipèle : quelle vaccination vérifier ?","back":"**Antitétanique** (rappel si besoin).","prio":"P2","sec":"s16"},{"id":"fc-d155-061cde","poly":"dermato","fiche":"d155","front":"Érysipèle : délais d'efficacité du traitement ?","back":"**Apyrexie en 48-72 h** ; signes locaux plus lents (**1 semaine**) ; guérison en 8 à 10 jours le plus souvent.","prio":"P1","sec":"s16"},{"id":"fc-d155-2c69b1","poly":"dermato","fiche":"d155","front":"Érysipèle : complications locales et leur fréquence ?","back":"**5 à 10 %** (surtout si retard) : **abcès** à inciser et drainer.","prio":"P2","sec":"s16"},{"id":"fc-d155-f0ab6f","poly":"dermato","fiche":"d155","front":"Érysipèle : complications générales ?","back":"Très rares (< 5 %) : **septicémie** à streptocoque, **glomérulonéphrite** aiguë post-streptococcique.","prio":"P2","sec":"s16"},{"id":"fc-d155-1c2c7c","poly":"dermato","fiche":"d155","front":"Érysipèle : complication la plus fréquente ?","back":"La **récidive** (environ **20 à 30 %**), en général liée à la persistance des facteurs de risque.","prio":"P1","sec":"s16"},{"id":"fc-d155-ee00f4","poly":"dermato","fiche":"d155","front":"Érysipèle : mesures de prévention des récidives ?","back":"Traiter la **porte d'entrée**, troubles circulatoires (**contention**, drainage, perte de poids), **hygiène cutanée**.","prio":"P1","sec":"s16"},{"id":"fc-d155-9b8e91","poly":"dermato","fiche":"d155","front":"Érysipèle : récidives multiples, que proposer ?","back":"**Antibiothérapie préventive**.","prio":"P2","sec":"s16"},{"id":"fc-d155-7932be","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : où la prendre en charge ?","back":"En **unité de soins intensifs**, milieu spécialisé, très rapidement.","prio":"P1","sec":"s17"},{"id":"fc-d155-02441d","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : geste chirurgical ?","back":"**Excision de toutes les zones nécrosées**.","prio":"P1","sec":"s17"},{"id":"fc-d155-3ac3d2","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : antibiothérapie ?","back":"**Parentérale**, adaptée ensuite à l'antibiogramme.","prio":"P1","sec":"s17"},{"id":"fc-d155-1cb6a2","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : molécules citées ?","back":"**Clindamycine** + pénicilline élargie (**tazocilline**) ou céphalosporine ± **aminoside** ; **métronidazole** si anaérobies.","prio":"P2","sec":"s17"},{"id":"fc-d155-db0796","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : désordres à rechercher aux gaz du sang et à la coagulation ?","back":"**Acidose métabolique** ; **CIVD**.","prio":"P2","sec":"s17"},{"id":"fc-d155-945a32","poly":"dermato","fiche":"d155","front":"Dermohypodermite nécrosante : mesures de réanimation associées ?","back":"Corriger l'**hypovolémie** et les désordres **glucidiques** et **électrolytiques**.","prio":"P2","sec":"s17"},{"id":"fc-d155-d94e17","poly":"dermato","fiche":"d155","front":"Candidose : principes du traitement ?","back":"Traiter les **facteurs favorisants** ; traiter **tous les foyers en même temps**.","prio":"P2","sec":"s18"},{"id":"fc-d155-08bd7a","poly":"dermato","fiche":"d155","front":"Candidose : indications du traitement général ?","back":"Atteinte **étendue** (plusieurs plis), **inaccessible** à un topique, **déficit immunitaire**, ou **sévère** (néonatalogie, septicémie).","prio":"P2","sec":"s18"},{"id":"fc-d155-a35081","poly":"dermato","fiche":"d155","front":"Candidose : topiques de première intention ?","back":"**Imidazolés**.","prio":"P2","sec":"s18"},{"id":"fc-d155-ac0b2c","poly":"dermato","fiche":"d155","front":"Candidose : autres antifongiques locaux et leur limite ?","back":"**Ciclopiroxolamine** ; **terbinafine** (moins efficace sur *C. albicans*).","prio":"P3","sec":"s18"},{"id":"fc-d155-029b85","poly":"dermato","fiche":"d155","front":"Antifongique local d'une candidose : modalités ?","back":"**1 à 2 applications/j**, **2 à 4 semaines**.","prio":"P3","sec":"s18"},{"id":"fc-d155-d3e37d","poly":"dermato","fiche":"d155","front":"Candidose : antifongique systémique de première intention ?","back":"**Fluconazole**.","prio":"P2","sec":"s18"},{"id":"fc-d155-0ce7e6","poly":"dermato","fiche":"d155","front":"Fluconazole : principales interactions ?","back":"Via le cytochrome : **anticoagulants oraux**, **sulfamides hypoglycémiants**.","prio":"P2","sec":"s18"},{"id":"fc-d155-94bf47","poly":"dermato","fiche":"d155","front":"Candidose et grossesse : antifongique per os possible ?","back":"**Aucun** antifongique per os.","prio":"P2","sec":"s18"},{"id":"fc-d155-9f8768","poly":"dermato","fiche":"d155","front":"Candidose : poudre dans les plis, que dit le Collège ?","back":"« **Pas de poudre dans les plis** : irritant » (p. 163), mais la poudre est citée parmi les formes pour les plis (p. 165).","prio":"P3","sec":"s18"},{"id":"fc-d155-be9d59","poly":"dermato","fiche":"d155","front":"Candidose buccale de l'immunocompétent : type de traitement ?","back":"**Local**, au contact quelques minutes, **à distance des repas**, **1 à 3 semaines**.","prio":"P2","sec":"s19"},{"id":"fc-d155-0982c0","poly":"dermato","fiche":"d155","front":"Candidose buccale : antifongiques locaux cités ?","back":"**Amphotéricine B** suspension ; **miconazole** gel buccal ou comprimé muco-adhésif.","prio":"P3","sec":"s19"},{"id":"fc-d155-7e4a6e","poly":"dermato","fiche":"d155","front":"Candidose buccale : intérêt des bains de bouche bicarbonatés ?","back":"Adjuvant **sans intérêt démontré** (remonter le pH buccal).","prio":"P3","sec":"s19"},{"id":"fc-d155-a9b304","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique aiguë : traitement ?","back":"**Ovule imidazolé** 1 à 3 jours + **crème imidazolée** 2 à 4 semaines ; toilette au **savon alcalin**.","prio":"P2","sec":"s19"},{"id":"fc-d155-f83a21","poly":"dermato","fiche":"d155","front":"Vulvovaginite candidosique récidivante : traitement ?","back":"**Ovule LP 1 fois/mois vers J20** du cycle, plusieurs mois ; traiter le **partenaire** ; facteurs favorisants.","prio":"P2","sec":"s19"},{"id":"fc-d155-5088a9","poly":"dermato","fiche":"d155","front":"Vulvovaginite récidivante : le fluconazole a-t-il l'AMM ?","back":"**Non**, pas d'AMM dans cette indication.","prio":"P3","sec":"s19"},{"id":"fc-d155-157729","poly":"dermato","fiche":"d155","front":"Balanite candidosique : traitement ?","back":"Crème antifongique 1 à 2/j, **2 à 3 semaines** ; savon alcalin ; partenaire ; **biopsie au moindre doute**.","prio":"P2","sec":"s19"},{"id":"fc-d155-73c5cf","poly":"dermato","fiche":"d155","front":"Candidose des plis : traitement ?","back":"Antifongique local **2 à 4 semaines** ; supprimer la **macération** ; traiter les **foyers réservoirs** (bouche, tube digestif, vagin).","prio":"P2","sec":"s19"},{"id":"fc-d155-df5d5a","poly":"dermato","fiche":"d155","front":"Dermatophytie limitée (plis, peau glabre peu atteinte) : traitement ?","back":"**Traitement local** (2 à 3 semaines p. 175 ; 3 à 4 semaines p. 174).","prio":"P2","sec":"s20"},{"id":"fc-d155-c60bef","poly":"dermato","fiche":"d155","front":"Dermatophytie : indications du traitement systémique ?","back":"Atteinte **palmo-plantaire**, **profuse**, ou atteinte associée des **ongles ou poils**.","prio":"P2","sec":"s20"},{"id":"fc-d155-eb653e","poly":"dermato","fiche":"d155","front":"Dermatophytie : durée du traitement systémique ?","back":"**2 semaines** (peau glabre) à **plusieurs mois** (ongles).","prio":"P3","sec":"s20"},{"id":"fc-d155-eb8532","poly":"dermato","fiche":"d155","front":"Terbinafine : surveillance biologique ?","back":"**Transaminases et bilirubine** avant puis à **6 semaines**.","prio":"P2","sec":"s20"},{"id":"fc-d155-1939e5","poly":"dermato","fiche":"d155","front":"Terbinafine : effets indésirables ?","back":"Troubles **digestifs**, troubles du **goût**, **toxidermies graves** (PEAG…), **hépatites**, cytopénies exceptionnelles.","prio":"P2","sec":"s20"},{"id":"fc-d155-4a3d7b","poly":"dermato","fiche":"d155","front":"Terbinafine et griséofulvine : prise par rapport aux repas ?","back":"Terbinafine **hors des repas** ; griséofulvine **pendant un repas gras**.","prio":"P2","sec":"s20"},{"id":"fc-d155-17a26e","poly":"dermato","fiche":"d155","front":"Itraconazole : précautions ?","back":"En dehors d'un repas ; **nombreuses interactions** ; risque d'**hépatite** ; CI femme enceinte.","prio":"P3","sec":"s20"},{"id":"fc-d155-f5a31d","poly":"dermato","fiche":"d155","front":"Griséofulvine : caractéristiques ?","back":"**Fongistatique** ; associée à un traitement local ; **photosensibilisation** ; retirée du commerce en 2021.","prio":"P3","sec":"s20"},{"id":"fc-d155-705f8c","poly":"dermato","fiche":"d155","front":"Griséofulvine : posologie ?","back":"**1 g/j** chez l'adulte ; **20 mg/kg/j** chez l'enfant.","prio":"P3","sec":"s20"},{"id":"fc-d155-79f463","poly":"dermato","fiche":"d155","front":"Griséofulvine : particularité pédiatrique ?","back":"Seul antifongique oral avec **AMM et forme adaptée à l'enfant** ; approvisionnement difficile depuis 2021.","prio":"P3","sec":"s20"},{"id":"fc-d155-bb9517","poly":"dermato","fiche":"d155","front":"Intertrigo inter-orteils : pourquoi le traiter ?","back":"Fait partie de la **prévention de l'érysipèle**.","prio":"P1","sec":"s20"},{"id":"fc-d155-be0fa7","poly":"dermato","fiche":"d155","front":"Teigne : durée de traitement et objectif ?","back":"**4 à 6 semaines**, jusqu'à guérison **clinique et mycologique**.","prio":"P2","sec":"s21"},{"id":"fc-d155-a23f11","poly":"dermato","fiche":"d155","front":"Teigne : quels traitements associer ?","back":"**Local ET systémique**, impérativement.","prio":"P2","sec":"s21"},{"id":"fc-d155-9fbed8","poly":"dermato","fiche":"d155","front":"Teigne : mesures selon l'origine du dermatophyte ?","back":"Anthropophile : examiner **famille et contacts** ; zoophile : traiter l'**animal** (vétérinaire).","prio":"P2","sec":"s21"},{"id":"fc-d155-0c80df","poly":"dermato","fiche":"d155","front":"Teigne : mesures locales ?","back":"Désinfecter **bonnets** et matériel de coiffure ; **couper les cheveux** autour des plaques ; shampooing **polyvidone iodée** ; imidazolé ou ciclopiroxolamine.","prio":"P3","sec":"s21"},{"id":"fc-d155-453e9e","poly":"dermato","fiche":"d155","front":"Teigne de l'enfant de moins de 10 kg : prise en charge ?","back":"**Hospitalière**.","prio":"P3","sec":"s21"},{"id":"fc-d155-1d2265","poly":"dermato","fiche":"d155","front":"Teigne de l'enfant > 10 kg : traitement systémique selon le type ?","back":"Microsporique : **itraconazole 6 semaines** ; trichophytique ou probabiliste : **terbinafine 4 semaines**.","prio":"P2","sec":"s21"},{"id":"fc-d155-5fbe07","poly":"dermato","fiche":"d155","front":"Teigne : éviction scolaire ?","back":"**Oui**, sauf **certificat médical** attestant consultation et traitement adapté.","prio":"P2","sec":"s21"},{"id":"fc-d155-061273","poly":"dermato","fiche":"d155","front":"Itraconazole et terbinafine dans la teigne : contre-indications ?","back":"**Femme enceinte ou allaitante**, **enfant de moins de 1 an**.","prio":"P3","sec":"s21"},{"id":"fc-d155-d536e3","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : quand débuter le traitement ?","back":"Seulement **après identification mycologique** (fragment d'ongle).","prio":"P2","sec":"s21"},{"id":"fc-d155-917379","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : traitement selon l'atteinte ?","back":"**Modérée et distale** : vernis ou solution filmogène ; **matricielle** : traitement **systémique**.","prio":"P2","sec":"s21"},{"id":"fc-d155-763f1c","poly":"dermato","fiche":"d155","front":"Onyxis dermatophytique : délai de guérison ?","back":"Après repousse : **4 à 6 mois** (main), **9 à 12 mois** (orteils).","prio":"P3","sec":"s21"},{"id":"fc-d155-7a5586","poly":"dermato","fiche":"d155","front":"Dermatophytes anthropophiles : facteurs de macération favorisant la contamination ?","back":"**Séchage insuffisant**, **chaussures fermées**.","prio":"P3","sec":"s22"},{"id":"fc-d155-ffd187","poly":"dermato","fiche":"d155","front":"Candidose génitale récidivante : mesures préventives ?","back":"**Ovule LP mensuel** ; chercher et traiter le ou la **partenaire**.","prio":"P3","sec":"s22"},{"id":"fc-d155-8fcd9a","poly":"dermato","fiche":"d155","front":"Fluconazole : indications de la voie per os et de la voie IV ?","back":"Per os : atteintes **oropharyngées et œsophagiennes de l'immunodéprimé** ; IV : formes **systémiques, disséminées ou profondes**.","prio":"P3","sec":"s18"},{"id":"fc-d155-96752f","poly":"dermato","fiche":"d155","front":"Muguet de l'immunodéprimé : aspect de la forme profuse ?","back":"**Érythème diffus** de la muqueuse buccale + petits dépôts blanchâtres **adhérents**.","prio":"P3","sec":"s7"},{"id":"fc-d155-58b331","poly":"dermato","fiche":"d155","front":"Candidose : critères de choix du traitement ?","back":"**Localisation et étendue**, **terrain** (grossesse, immunodépression), atteinte des **phanères**, risque d'effets indésirables et d'**interactions**.","prio":"P3","sec":"s18"},{"id":"fc-d155-c359ad","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique**.","prio":"P2","sec":"s8"},{"id":"fc-d155-02e3b0","poly":"dermato","fiche":"d155","front":"Intertrigo candidosique : grands plis ou petits plis, lesquels sont le plus touchés ?","back":"Les **grands plis** (grands plis > petits plis).","prio":"P3","sec":"s8"},{"id":"fc-d155-4376ec","poly":"dermato","fiche":"d155","front":"Onychomycose candidosique : évolution et aspects possibles de l'ongle ?","back":"Évolution **chronique par poussées** ; taches **jaunes ou verdâtres**, **sillons transversaux**, **onycholyse**.","prio":"P3","sec":"s8"},{"id":"fc-d155-1539a7","poly":"dermato","fiche":"d155","front":"Candidose génitale de l'enfant : mécanisme ?","back":"**Extension** d'une **dermatite fessière** ou d'une **anite**.","prio":"P3","sec":"s7"},{"id":"fc-d155-55ec40","poly":"dermato","fiche":"d155","front":"Antécédent de vulvovaginite candidosique et début d'un antibiotique : prévention possible ?","back":"**Ovule imidazolé à libération prolongée** préventif.","prio":"P3","sec":"s19"},{"id":"fc-d155-10b94d","poly":"dermato","fiche":"d155","front":"Dermatophytie : antifongiques locaux cités ?","back":"**Imidazolé**, **ciclopiroxolamine** ou **terbinafine** ; 1 à 2 applications/j.","prio":"P3","sec":"s20"},{"id":"fc-d155-2ccd90","poly":"dermato","fiche":"d155","front":"Dermatophytie : antifongiques systémiques cités ?","back":"**Terbinafine** (fongicide) · **itraconazole** · **griséofulvine** (fongistatique, retirée du commerce en 2021).","prio":"P2","sec":"s20"},{"id":"fc-d162-861672","poly":"dermato","fiche":"d162","front":"Item IST (162) : quelles infections regroupe-t-il ?","back":"**Gonococcie**, **chlamydiose**, **syphilis**, infections anogénitales à **HPV**, **trichomonose**.","prio":"P2","sec":"s1"},{"id":"fc-d162-f27d99","poly":"dermato","fiche":"d162","front":"Gonocoque : quel type de bactérie ?","back":"Neisseria gonorrhoeae : **diplocoque à Gram négatif**, encapsulé, intra- ou extracellulaire.","prio":"P2","sec":"s1"},{"id":"fc-d162-98e376","poly":"dermato","fiche":"d162","front":"Chlamydia trachomatis : quel type de bactérie ?","back":"Bacille à Gram négatif, **intracellulaire obligatoire**, immobile.","prio":"P2","sec":"s1"},{"id":"fc-d162-b23c53","poly":"dermato","fiche":"d162","front":"Chlamydia trachomatis : quels sérotypes donnent les infections urogénitales ?","back":"Les sérotypes **D à K**.","prio":"P3","sec":"s1"},{"id":"fc-d162-761cd7","poly":"dermato","fiche":"d162","front":"Lymphogranulomatose vénérienne : quels sérotypes de Chlamydia trachomatis ?","back":"**L1, L2, L3** (maladie de **Nicolas-Favre**).","prio":"P3","sec":"s1"},{"id":"fc-d162-b4471d","poly":"dermato","fiche":"d162","front":"Syphilis : quel est l'agent responsable ?","back":"Treponema pallidum, un **spirochète**.","prio":"P1","sec":"s1"},{"id":"fc-d162-746f79","poly":"dermato","fiche":"d162","front":"Trichomonas vaginalis : quel type d'agent ?","back":"**Protozoaire flagellé**, anaérobie ; réservoir naturel : le tractus uro-génital.","prio":"P3","sec":"s1"},{"id":"fc-d162-378dba","poly":"dermato","fiche":"d162","front":"Trichomonose, candidose, vaginose bactérienne : laquelle est une IST ?","back":"La **trichomonose** (pas la candidose ni la vaginose bactérienne).","prio":"P2","sec":"s1"},{"id":"fc-d162-61fe30","poly":"dermato","fiche":"d162","front":"Toute IST : quels examens proposer systématiquement au patient ?","back":"**Sérologie VIH**, **test tréponémique** (syphilis), **sérologie d'hépatite B**.","prio":"P1","sec":"s1"},{"id":"fc-d162-d4e42d","poly":"dermato","fiche":"d162","front":"Toute IST : que faire pour le ou les partenaires ?","back":"Les retrouver (contaminés ou contaminateurs) et leur proposer **dépistage**, **diagnostic** et/ou **traitement probabiliste**.","prio":"P1","sec":"s1"},{"id":"fc-d162-d9de66","poly":"dermato","fiche":"d162","front":"Toute IST : quels éléments d'éducation donner ?","back":"Risque de **recontamination**, pas de rapport non protégé pendant le traitement, **PrEP** anti-VIH si prises de risque trop régulières.","prio":"P1","sec":"s1"},{"id":"fc-d162-6817ca","poly":"dermato","fiche":"d162","front":"Condylomes : quelle fréquence d'IST associée ?","back":"**25 %** des cas en moyenne.","prio":"P2","sec":"s1"},{"id":"fc-d162-6d2b36","poly":"dermato","fiche":"d162","front":"Syphilis : de quoi sa survenue témoigne-t-elle sur le plan comportemental ?","back":"Une **sexualité à haut risque** : vérifier VIH, hépatite B et autres IST.","prio":"P2","sec":"s1"},{"id":"fc-d162-3bab56","poly":"dermato","fiche":"d162","front":"Gale : pourquoi dépister les autres IST ?","back":"Son mode de transmission l'apparente à une IST : rechercher des **conduites à risque**, et si présentes, dépister les autres IST.","prio":"P3","sec":"s1"},{"id":"fc-d162-d66b62","poly":"dermato","fiche":"d162","front":"Gonococcie : quelle tendance épidémiologique en France ?","back":"Incidence en **hausse** (urétrites gonococciques en augmentation depuis 1998), plus élevée chez l'homme et en Île-de-France.","prio":"P3","sec":"s2"},{"id":"fc-d162-8fe674","poly":"dermato","fiche":"d162","front":"Gonocoque : quels taux de résistance aux antibiotiques ?","back":"Pénicilline (bêtalactamase) **15 %**, cyclines **20 %**, ciprofloxacine **40 %** ; CMI des C3G en hausse.","prio":"P2","sec":"s2"},{"id":"fc-d162-980a36","poly":"dermato","fiche":"d162","front":"Chlamydiose : quelle fréquence par rapport à la gonococcie ?","back":"**50 fois plus fréquente** ; 1re IST bactérienne des pays industrialisés.","prio":"P2","sec":"s2"},{"id":"fc-d162-b28ddd","poly":"dermato","fiche":"d162","front":"Quelle est la 1re cause identifiée d'urétrite aiguë ?","back":"**Chlamydia trachomatis**, devant le gonocoque.","prio":"P2","sec":"s2"},{"id":"fc-d162-a58399","poly":"dermato","fiche":"d162","front":"Chlamydiose : quels pics d'incidence ?","back":"**15-34 ans** chez la femme, **20-39 ans** chez l'homme.","prio":"P3","sec":"s2"},{"id":"fc-d162-73107d","poly":"dermato","fiche":"d162","front":"Lymphogranulomatose vénérienne : chez qui est-elle réapparue depuis 2003 ?","back":"Chez les **hommes homosexuels**, souvent infectés par le VIH.","prio":"P3","sec":"s2"},{"id":"fc-d162-9c877a","poly":"dermato","fiche":"d162","front":"Syphilis : quelle tendance épidémiologique ?","back":"**Recrudescence depuis 2000**, surtout chez les hommes homosexuels en métropole ; patients VIH surreprésentés (**40 %**).","prio":"P3","sec":"s2"},{"id":"fc-d162-767ba4","poly":"dermato","fiche":"d162","front":"Quelle est actuellement l'IST la plus fréquente ?","back":"L'infection à **HPV**.","prio":"P2","sec":"s2"},{"id":"fc-d162-6e0d27","poly":"dermato","fiche":"d162","front":"HPV : quelle évolution chez la plupart des sujets infectés ?","back":"Élimination du virus en **quelques mois** ; < 10 % restent porteurs asymptomatiques, **1 %** font des lésions génitales.","prio":"P3","sec":"s2"},{"id":"fc-d162-69b9e3","poly":"dermato","fiche":"d162","front":"Trichomonose : quelles caractéristiques de transmission ?","back":"Presque uniquement **sexuelle**, possible seulement en **milieu humide** ; incubation **4 à 28 jours**.","prio":"P3","sec":"s2"},{"id":"fc-d162-614658","poly":"dermato","fiche":"d162","front":"Syphilis : quels modes de transmission ?","back":"Surtout **sexuelle** (fellation comprise) ; materno-fœtale ; transfusion ou greffe exceptionnelles.","prio":"P2","sec":"s2"},{"id":"fc-d162-9b1bf8","poly":"dermato","fiche":"d162","front":"Syphilis : quelles lésions sont contagieuses ?","back":"Les **lésions muqueuses** et les **syphilides grattées ou excoriées**.","prio":"P3","sec":"s2"},{"id":"fc-d162-d66062","poly":"dermato","fiche":"d162","front":"Syphilis : à partir de quand la transmission materno-fœtale est-elle surtout possible ?","back":"Surtout après la **16e semaine d'aménorrhée**.","prio":"P2","sec":"s2"},{"id":"fc-d162-870cc1","poly":"dermato","fiche":"d162","front":"HPV : quels types sont à bas risque et que donnent-ils ?","back":"**6 et 11** surtout : près de **90 % des condylomes**.","prio":"P2","sec":"s2"},{"id":"fc-d162-60abb4","poly":"dermato","fiche":"d162","front":"HPV : quels types sont à haut risque oncogène ?","back":"**16 et 18** surtout : lésions précancéreuses puis cancers.","prio":"P2","sec":"s2"},{"id":"fc-d162-026f8e","poly":"dermato","fiche":"d162","front":"HPV : quels modes de transmission non sexuelle ?","back":"**Linges humides** contaminés ; **accouchement** si condylomes maternels (papillomatose laryngée juvénile).","prio":"P3","sec":"s2"},{"id":"fc-d162-a08385","poly":"dermato","fiche":"d162","front":"HPV : quel effet ont le VIH et l'immunodépression ?","back":"Hausse de l'incidence, des **récidives** et de l'évolution vers des **néoplasies intra-épithéliales**.","prio":"P3","sec":"s2"},{"id":"fc-d162-eb3c99","poly":"dermato","fiche":"d162","front":"Urétrites en France : quelle part pour gonocoque et Chlamydia ?","back":"Gonocoque **10 %** ; Chlamydia **20-30 %**.","prio":"P3","sec":"s2"},{"id":"fc-d162-7afbe9","poly":"dermato","fiche":"d162","front":"Chlamydia : pourquoi est-ce un enjeu de santé publique chez les jeunes ?","back":"**Portage asymptomatique**, transmission silencieuse, complications hautes (**GEU**, **stérilité tubaire**).","prio":"P2","sec":"s2"},{"id":"fc-d162-7a4950","poly":"dermato","fiche":"d162","front":"Urétrite gonococcique : quelle durée d'incubation ?","back":"**Courte : 2 à 7 jours**.","prio":"P1","sec":"s3"},{"id":"fc-d162-760be2","poly":"dermato","fiche":"d162","front":"Urétrite gonococcique de l'homme : quel tableau ?","back":"Le plus souvent **bruyant** : écoulement **purulent** (90 %), dysurie, brûlures urétrales, prurit urétral, méatite voire balanite.","prio":"P1","sec":"s3"},{"id":"fc-d162-668be3","poly":"dermato","fiche":"d162","front":"Anorectite gonococcique : quelle fréquence de forme asymptomatique ?","back":"**2 fois sur 3**.","prio":"P3","sec":"s3"},{"id":"fc-d162-c82f91","poly":"dermato","fiche":"d162","front":"Anorectite gonococcique : quels signes possibles ?","back":"Prurit anal, écoulement rectal purulent, diarrhée, saignements, **syndrome rectal** (ténesme, épreintes).","prio":"P3","sec":"s3"},{"id":"fc-d162-0ef274","poly":"dermato","fiche":"d162","front":"Oropharyngite gonococcique : comment se présente-t-elle le plus souvent ?","back":"Le plus souvent **asymptomatique**.","prio":"P2","sec":"s3"},{"id":"fc-d162-9a873a","poly":"dermato","fiche":"d162","front":"Urétrite à Chlamydia : quelle durée d'incubation ?","back":"**Variable** : de quelques jours à quelques mois.","prio":"P1","sec":"s3"},{"id":"fc-d162-697030","poly":"dermato","fiche":"d162","front":"Urétrite à Chlamydia : quelles caractéristiques de l'écoulement ?","back":"Inconstant (**moins de 50 %** des cas), le plus souvent **clair**, modéré, intermittent.","prio":"P1","sec":"s3"},{"id":"fc-d162-d5f560","poly":"dermato","fiche":"d162","front":"Chlamydia chez l'homme : quelle fréquence de portage asymptomatique urétral ?","back":"**50 %** des cas.","prio":"P2","sec":"s3"},{"id":"fc-d162-f3ed96","poly":"dermato","fiche":"d162","front":"Gonocoque chez la femme : quelle proportion de formes asymptomatiques ?","back":"**70 %** des cas.","prio":"P2","sec":"s3"},{"id":"fc-d162-e47c5b","poly":"dermato","fiche":"d162","front":"Gonocoque chez la femme : quelle est la forme clinique la plus fréquente ?","back":"La **cervicite** (leucorrhées purulentes, pus à l'orifice cervical).","prio":"P2","sec":"s3"},{"id":"fc-d162-f199ed","poly":"dermato","fiche":"d162","front":"Cervicite gonococcique : quels signes ?","back":"**Leucorrhées purulentes**, pesanteur pelvienne, signes d'urétrite ; col peu inflammatoire avec **pus à l'orifice**.","prio":"P2","sec":"s3"},{"id":"fc-d162-d31aea","poly":"dermato","fiche":"d162","front":"Chlamydia chez la femme : quelle est la forme la plus fréquente et quelle part asymptomatique ?","back":"La **cervicite**, asymptomatique dans **50 à 90 %** des cas.","prio":"P1","sec":"s3"},{"id":"fc-d162-927e0b","poly":"dermato","fiche":"d162","front":"Cervicite à Chlamydia symptomatique : quels signes ?","back":"Leucorrhées blanchâtres ou jaunâtres, **cystalgies**, syndrome urétral, **dyspareunie**.","prio":"P2","sec":"s3"},{"id":"fc-d162-e46a5c","poly":"dermato","fiche":"d162","front":"Cervicite à Chlamydia : quel aspect du col ?","back":"Col **fragile**, sécrétions mucopurulentes, **ectropion friable et hémorragique**.","prio":"P3","sec":"s3"},{"id":"fc-d162-e5f772","poly":"dermato","fiche":"d162","front":"Gonocoque : où le portage asymptomatique est-il plus fréquent ?","back":"Au **pharynx** et à l'**anus** (exceptionnel à l'urètre).","prio":"P2","sec":"s3"},{"id":"fc-d162-3fe7f5","poly":"dermato","fiche":"d162","front":"Gonocoque : quand rechercher systématiquement un portage pharyngé ?","back":"En cas de **conduite à risque** : partenaires multiples, rapports **orogénitaux réceptifs** non protégés.","prio":"P1","sec":"s3"},{"id":"fc-d162-20b513","poly":"dermato","fiche":"d162","front":"Gonococcie pharyngée : pourquoi le portage persiste-t-il après traitement ?","back":"Les antibiotiques y **diffusent mal** : portage persistant qui entretient la contamination.","prio":"P2","sec":"s3"},{"id":"fc-d162-b96767","poly":"dermato","fiche":"d162","front":"Trichomonose chez l'homme : quelle présentation ?","back":"Le plus souvent **asymptomatique** ; urétrite plutôt subaiguë ou balanoposthite, parfois écoulement du matin et prurit.","prio":"P3","sec":"s3"},{"id":"fc-d162-5daa0b","poly":"dermato","fiche":"d162","front":"Trichomonose chez la femme : quelles leucorrhées ?","back":"**Abondantes, verdâtres, spumeuses et malodorantes**.","prio":"P2","sec":"s3"},{"id":"fc-d162-db1eeb","poly":"dermato","fiche":"d162","front":"Trichomonose chez la femme : quels autres signes ?","back":"Prurit intense, dyspareunie, signes urinaires, vulve œdématiée, **colpite punctiforme « léopard »** au spéculum.","prio":"P3","sec":"s3"},{"id":"fc-d162-86d208","poly":"dermato","fiche":"d162","front":"Gonocoque chez l'homme : quelles complications locorégionales ?","back":"**Prostatite**, **épididymite**.","prio":"P2","sec":"s4"},{"id":"fc-d162-190ff6","poly":"dermato","fiche":"d162","front":"Chlamydia chez l'homme : quelles complications ?","back":"**Épididymite aiguë** ; **prostatite chronique** (prostatites aiguës rares).","prio":"P3","sec":"s4"},{"id":"fc-d162-3add8b","poly":"dermato","fiche":"d162","front":"Chlamydia chez la femme : quelles complications hautes ?","back":"**Endométrite**, **salpingite**, souvent subaiguës ou chroniques ; puis algies pelviennes, **stérilité tubaire**, **GEU**.","prio":"P2","sec":"s4"},{"id":"fc-d162-148632","poly":"dermato","fiche":"d162","front":"Chlamydia : quelle part des salpingites et des stérilités tubaires ?","back":"**50 %** des salpingites de la femme jeune, **70 %** des stérilités tubaires.","prio":"P2","sec":"s4"},{"id":"fc-d162-a09f86","poly":"dermato","fiche":"d162","front":"Périhépatite à Chlamydia : quel tableau ?","back":"Tableau de **cholécystite sans calcul** ; diagnostic sous **cœlioscopie**.","prio":"P3","sec":"s4"},{"id":"fc-d162-53afa1","poly":"dermato","fiche":"d162","front":"Gonocoque : quelles complications systémiques ?","back":"**Septicémie gonococcique** ; plus rarement périhépatite, **endocardite**, **méningite**.","prio":"P2","sec":"s4"},{"id":"fc-d162-116e65","poly":"dermato","fiche":"d162","front":"Septicémie gonococcique : quels signes cutanés ?","back":"**Purpura pétéchial**, papules ou **papulo-pustules** des extrémités ou péri-articulaires.","prio":"P2","sec":"s4"},{"id":"fc-d162-a87b96","poly":"dermato","fiche":"d162","front":"Septicémie gonococcique : quelles atteintes articulaires ?","back":"**Mono- ou oligoarthrites septiques**, **ténosynovites**.","prio":"P3","sec":"s4"},{"id":"fc-d162-d49129","poly":"dermato","fiche":"d162","front":"Syndrome oculo-urétro-synovial : quel germe et quels signes ?","back":"**Chlamydia** : polyarthrite réactionnelle, urétrite, **conjonctivite bilatérale**, balanite circinée, kératodermie palmo-plantaire.","prio":"P2","sec":"s4"},{"id":"fc-d162-10cc57","poly":"dermato","fiche":"d162","front":"Nouveau-né de mère infectée par Chlamydia : quels risques ?","back":"**Kératoconjonctivite** et **pneumopathie**.","prio":"P2","sec":"s4"},{"id":"fc-d162-937be0","poly":"dermato","fiche":"d162","front":"Nouveau-né de mère infectée par le gonocoque : quel risque ?","back":"Une rare **conjonctivite purulente**.","prio":"P3","sec":"s4"},{"id":"fc-d162-3d53e2","poly":"dermato","fiche":"d162","front":"Gonocoque et Chlamydia : quelle technique de dépistage ?","back":"**PCR**, le plus souvent couplée gonocoque + Chlamydia (**PCR biplex**).","prio":"P1","sec":"s5"},{"id":"fc-d162-485b78","poly":"dermato","fiche":"d162","front":"Dépistage PCR chez l'homme : quel prélèvement ?","back":"Le **1er jet d'urine** (**10 à 20 mL**), recueilli **2 heures** au moins après la miction précédente.","prio":"P1","sec":"s5"},{"id":"fc-d162-5fdde1","poly":"dermato","fiche":"d162","front":"Dépistage PCR chez la femme : quel prélèvement ?","back":"**Auto-écouvillonnage vaginal**.","prio":"P1","sec":"s5"},{"id":"fc-d162-5a709c","poly":"dermato","fiche":"d162","front":"Dépistage gonocoque/Chlamydia : quels prélèvements ajouter selon les pratiques sexuelles ?","back":"Prélèvement **pharyngé** et/ou **anal**, dans les deux sexes.","prio":"P2","sec":"s5"},{"id":"fc-d162-1b1169","poly":"dermato","fiche":"d162","front":"Urétrite symptomatique (gonocoque) : que prélever ?","back":"L'**écoulement urétral spontané** ; sans écoulement, 1er jet d'urine, sinon prélèvement endo-urétral.","prio":"P2","sec":"s5"},{"id":"fc-d162-afb447","poly":"dermato","fiche":"d162","front":"Chlamydia : quel est l'examen diagnostique clé ?","back":"La **PCR**, plus sensible que la culture.","prio":"P1","sec":"s5"},{"id":"fc-d162-632669","poly":"dermato","fiche":"d162","front":"Chlamydia : quel intérêt de la sérologie pour le diagnostic ?","back":"**Aucun**.","prio":"P1","sec":"s5"},{"id":"fc-d162-32162e","poly":"dermato","fiche":"d162","front":"Gonocoque : quels examens associer à la PCR ?","back":"**Examen direct**, **culture** et **antibiogramme**.","prio":"P1","sec":"s5"},{"id":"fc-d162-0556f3","poly":"dermato","fiche":"d162","front":"Frottis urétral : quel seuil définit une urétrite biologique ?","back":"> **5 polynucléaires** au grossissement 100, ou > **10** au grossissement 400.","prio":"P3","sec":"s5"},{"id":"fc-d162-ab40b6","poly":"dermato","fiche":"d162","front":"Gonocoque à l'examen direct : quel aspect ?","back":"Diplocoques Gram négatif « **en grains de café** », **intracellulaires**.","prio":"P2","sec":"s5"},{"id":"fc-d162-8e3bd2","poly":"dermato","fiche":"d162","front":"Examen direct du gonocoque : quelles performances ?","back":"Sensibilité et spécificité **> 95 %** dans l'urétrite masculine symptomatique, moins bonnes ailleurs et chez la femme.","prio":"P3","sec":"s5"},{"id":"fc-d162-415fdd","poly":"dermato","fiche":"d162","front":"Gonocoque : pourquoi une forme extracellulaire seule ne suffit-elle pas ?","back":"Il existe des **Neisseria non pathogènes**.","prio":"P3","sec":"s5"},{"id":"fc-d162-92606e","poly":"dermato","fiche":"d162","front":"Gonocoque : sur quel milieu se fait la culture ?","back":"**Gélose au sang cuit** (« gélose chocolat »).","prio":"P3","sec":"s5"},{"id":"fc-d162-88e95d","poly":"dermato","fiche":"d162","front":"Culture du gonocoque : quel intérêt ?","back":"**Systématique** : confirme le diagnostic et donne un **antibiogramme** en 24 à 48 h.","prio":"P2","sec":"s5"},{"id":"fc-d162-c36942","poly":"dermato","fiche":"d162","front":"Trichomonose : quel examen diagnostique ?","back":"**Examen direct à l'état frais** (parasite **mobile**) et, plus récemment, **PCR**.","prio":"P3","sec":"s5"},{"id":"fc-d162-f35296","poly":"dermato","fiche":"d162","front":"Trichomonose chez la femme : où prélever ?","back":"Au **cul-de-sac vaginal postérieur**.","prio":"P3","sec":"s5"},{"id":"fc-d162-0e3c30","poly":"dermato","fiche":"d162","front":"Syphilis : est-ce une maladie immunisante ?","back":"**Non** : une **recontamination** est possible.","prio":"P1","sec":"s6"},{"id":"fc-d162-ebd290","poly":"dermato","fiche":"d162","front":"Syphilis : quelle durée moyenne d'incubation ?","back":"**3 semaines** en moyenne (10 à 90 jours).","prio":"P1","sec":"s6"},{"id":"fc-d162-291784","poly":"dermato","fiche":"d162","front":"Syphilis précoce : quelles formes regroupe-t-elle ?","back":"**Primaire**, **secondaire**, **latente précoce** (moins de 1 an).","prio":"P1","sec":"s6"},{"id":"fc-d162-b7ce20","poly":"dermato","fiche":"d162","front":"Syphilis tardive : quelles formes regroupe-t-elle ?","back":"**Tertiaire** et **latente tardive** (plus de 1 an ou non datable).","prio":"P1","sec":"s6"},{"id":"fc-d162-feaa36","poly":"dermato","fiche":"d162","front":"Syphilis latente précoce : à quelle condition retient-on ce terme ?","back":"Sérologie **négative datant de moins de 1 an** avant la sérologie positive, chez un patient asymptomatique.","prio":"P1","sec":"s6"},{"id":"fc-d162-8e7a59","poly":"dermato","fiche":"d162","front":"Syphilis primaire : quelle est sa définition clinique ?","back":"**Chancre** au point d'inoculation + **adénopathie satellite**.","prio":"P1","sec":"s7"},{"id":"fc-d162-445c0a","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : est-il contagieux ?","back":"**Oui**, il fourmille de tréponèmes.","prio":"P2","sec":"s7"},{"id":"fc-d162-82b3dd","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : dans quels sièges le diagnostic est-il souvent manqué ?","back":"Sièges non visibles : **vagin**, **col utérin**, **anorectum**, **pharynx**.","prio":"P2","sec":"s7"},{"id":"fc-d162-e52b75","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : quel type de lésion ?","back":"**Exulcération** (érosion) superficielle ; plus rarement ulcération profonde.","prio":"P2","sec":"s7"},{"id":"fc-d162-a682ba","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : quelle taille et quel nombre ?","back":"**5 à 15 mm** ; **unique**, parfois multiple (images en miroir).","prio":"P3","sec":"s7"},{"id":"fc-d162-6d3685","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : quel aspect du fond ?","back":"**Propre**, rosé.","prio":"P2","sec":"s7"},{"id":"fc-d162-cd3157","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : quel est le seul caractère vraiment évocateur ?","back":"La **base indurée** : la surface fait bloc avec l'induration, impossible à pincer.","prio":"P1","sec":"s7"},{"id":"fc-d162-1ca5c4","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : est-il douloureux ?","back":"**Non**, il est **indolore** (à la différence de l'herpès).","prio":"P1","sec":"s7"},{"id":"fc-d162-3b86c6","poly":"dermato","fiche":"d162","front":"Chancre syphilitique chez l'homme : quel siège principal ?","back":"Le **sillon balano-préputial** ; plus rarement gland ou fourreau.","prio":"P2","sec":"s7"},{"id":"fc-d162-119436","poly":"dermato","fiche":"d162","front":"Chancre syphilitique chez la femme : quel siège principal ?","back":"La **partie externe de la vulve** (petites et grandes lèvres, fourchette).","prio":"P3","sec":"s7"},{"id":"fc-d162-fb5d74","poly":"dermato","fiche":"d162","front":"Chancre syphilitique : quelles caractéristiques de l'adénopathie satellite ?","back":"**Non inflammatoire**, le plus souvent **unilatérale**.","prio":"P2","sec":"s7"},{"id":"fc-d162-d3f75d","poly":"dermato","fiche":"d162","front":"Chancre syphilitique non traité : quelle évolution ?","back":"Régression **spontanée sans séquelle** en quelques semaines, mais la maladie peut progresser.","prio":"P2","sec":"s7"},{"id":"fc-d162-b1a62b","poly":"dermato","fiche":"d162","front":"Chancre visible non traité : quelle proportion fera une syphilis secondaire ?","back":"Environ **30 %**.","prio":"P3","sec":"s7"},{"id":"fc-d162-882abc","poly":"dermato","fiche":"d162","front":"Ulcération muqueuse aiguë génitale, anale ou buccale : quel diagnostic évoquer systématiquement ?","back":"Un **chancre syphilitique** (aucun caractère n'est pathognomonique).","prio":"P1","sec":"s7"},{"id":"fc-d162-42926e","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quelle lésion chercher au sein d'éruptions polymorphes ?","back":"Des lésions **papuleuses de couleur cuivrée**.","prio":"P1","sec":"s8"},{"id":"fc-d162-9654f4","poly":"dermato","fiche":"d162","front":"Quelles lésions évoquent très fortement une syphilis secondaire ?","back":"Des **papules palmo-plantaires**.","prio":"P1","sec":"s8"},{"id":"fc-d162-7cab65","poly":"dermato","fiche":"d162","front":"Roséole syphilitique : avec quoi ne faut-il pas la confondre ?","back":"Une **éruption virale** (primo-infection VIH) ou une **toxidermie**.","prio":"P1","sec":"s8"},{"id":"fc-d162-42f2c3","poly":"dermato","fiche":"d162","front":"Syphilides papuleuses : quel caractère de l'éruption ?","back":"Éruption **monomorphe**, la lésion élémentaire est presque toujours une **papule**.","prio":"P2","sec":"s8"},{"id":"fc-d162-dc86a5","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quelle durée en général ?","back":"**En général moins de 1 an** ; liée à la diffusion du tréponème dans tout l'organisme.","prio":"P3","sec":"s8"},{"id":"fc-d162-5ee44e","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : comment évoluent les éruptions ?","back":"En plusieurs **« floraisons »** séparées par des phases asymptomatiques de quelques semaines ou mois.","prio":"P3","sec":"s8"},{"id":"fc-d162-eef469","poly":"dermato","fiche":"d162","front":"Roséole syphilitique : quand et comment apparaît-elle ?","back":"Dans les **6 semaines** après le chancre ; macules **rose pâle** de 5 à 15 mm sur le tronc, souvent inaperçue.","prio":"P2","sec":"s8"},{"id":"fc-d162-dce732","poly":"dermato","fiche":"d162","front":"Roséole syphilitique : quelle évolution spontanée ?","back":"Disparition seule en **7 à 10 jours**, sans signe fonctionnel.","prio":"P3","sec":"s8"},{"id":"fc-d162-14ac12","poly":"dermato","fiche":"d162","front":"Syphilides papuleuses : quelles caractéristiques ?","back":"Couleur **cuivrée**, visage, tronc, membres, OGE ; fine desquamation péri-lésionnelle inconstante.","prio":"P2","sec":"s8"},{"id":"fc-d162-7025bc","poly":"dermato","fiche":"d162","front":"Syphilides palmo-plantaires : quelle fréquence au cours de la syphilis secondaire ?","back":"Environ **30 %** ; souvent discrètes mais très évocatrices, à chercher.","prio":"P2","sec":"s8"},{"id":"fc-d162-4d0875","poly":"dermato","fiche":"d162","front":"Syphilides génitales et périnéales : quelles caractéristiques ?","back":"Indolores, non prurigineuses, en général multiples, molles, papuleuses ou érosives, **très contagieuses**.","prio":"P2","sec":"s8"},{"id":"fc-d162-0443ad","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quels signes cutanéo-phanériens trompeurs ?","back":"Fausse perlèche, langue en « **plaques fauchées** », dépilation des sourcils, alopécie en « **fourrure mitée** ».","prio":"P2","sec":"s8"},{"id":"fc-d162-1bf32a","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quels signes généraux possibles ?","back":"Fébricule, céphalées, polyadénopathies, hépatosplénomégalie, polyarthralgies, douleurs osseuses, AEG.","prio":"P3","sec":"s8"},{"id":"fc-d162-96d818","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : les céphalées signent-elles une atteinte neuroméningée ?","back":"**Non** : elles viennent souvent de **micro-abcès du périoste**.","prio":"P2","sec":"s8"},{"id":"fc-d162-a75ad1","poly":"dermato","fiche":"d162","front":"Syphilis secondaire avec atteinte ophtalmique : de quoi s'agit-il ?","back":"D'une **neurosyphilis précoce** (uvéite antérieure surtout, papillite, névrite optique).","prio":"P2","sec":"s8"},{"id":"fc-d162-38027b","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quelle atteinte neurologique est aussi une neurosyphilis précoce ?","back":"L'atteinte d'un **nerf crânien** (hypoacousie, acouphènes, paralysie faciale…).","prio":"P3","sec":"s8"},{"id":"fc-d162-26a58e","poly":"dermato","fiche":"d162","front":"Tréponème : peut-on le cultiver ?","back":"**Non** : diagnostic direct (fond noir abandonné, biologie moléculaire, immunohistochimie) ou indirect par la **sérologie**.","prio":"P2","sec":"s9"},{"id":"fc-d162-ca5963","poly":"dermato","fiche":"d162","front":"Syphilis : quel test de sérologie en 1re intention ?","back":"Un **test tréponémique** : l'**ELISA** ; le TNT n'est fait que si l'ELISA est positif.","prio":"P1","sec":"s9"},{"id":"fc-d162-ec4901","poly":"dermato","fiche":"d162","front":"Ulcération muqueuse pouvant être un chancre : quel examen est obligatoire ?","back":"Un **test tréponémique** (TT).","prio":"P1","sec":"s9"},{"id":"fc-d162-18a36e","poly":"dermato","fiche":"d162","front":"Microscope à fond noir : quel statut actuel ?","back":"Diagnostic immédiat de certitude, mais **rarement disponible** et **plus remboursé** (retiré de la nomenclature).","prio":"P3","sec":"s9"},{"id":"fc-d162-cba51f","poly":"dermato","fiche":"d162","front":"Tests tréponémiques : lesquels ?","back":"**ELISA** et **TPHA**.","prio":"P2","sec":"s9"},{"id":"fc-d162-82ca4d","poly":"dermato","fiche":"d162","front":"Tests non tréponémiques : lesquels ?","back":"**VDRL** et **RPR**.","prio":"P2","sec":"s9"},{"id":"fc-d162-093f71","poly":"dermato","fiche":"d162","front":"Tests tréponémiques : quelle limite de spécificité ?","back":"Spécifiques des tréponématoses, mais ne séparent pas la syphilis des tréponématoses endémiques (**pian, béjel, pinta**).","prio":"P2","sec":"s9"},{"id":"fc-d162-c2f2de","poly":"dermato","fiche":"d162","front":"Test tréponémique : quand se positive-t-il ?","back":"Entre le **7e et le 10e jour** du chancre.","prio":"P2","sec":"s9"},{"id":"fc-d162-6794a9","poly":"dermato","fiche":"d162","front":"Test tréponémique : quel résultat compte ?","back":"Le résultat **qualitatif** seul (le quantitatif varie trop pour suivre l'évolutivité).","prio":"P1","sec":"s9"},{"id":"fc-d162-c4d421","poly":"dermato","fiche":"d162","front":"Test non tréponémique : quand se positive-t-il ?","back":"En moyenne **10 à 15 jours** après l'apparition du chancre.","prio":"P2","sec":"s9"},{"id":"fc-d162-9e9c84","poly":"dermato","fiche":"d162","front":"Tests non tréponémiques : sont-ils spécifiques des tréponématoses ?","back":"**Non**, ils ne sont pas spécifiques.","prio":"P2","sec":"s9"},{"id":"fc-d162-cac841","poly":"dermato","fiche":"d162","front":"Syphilis : quel test sert à suivre l'efficacité du traitement ?","back":"Le **TNT quantitatif** (VDRL).","prio":"P1","sec":"s9"},{"id":"fc-d162-e0d22b","poly":"dermato","fiche":"d162","front":"TNT : quel titre en plateau pendant la phase secondaire ?","back":"En général entre **1/16 et 1/128**.","prio":"P3","sec":"s9"},{"id":"fc-d162-c3e695","poly":"dermato","fiche":"d162","front":"TNT (VDRL) : que traduit un titre élevé, par exemple 1/16 ?","back":"Une **maladie évolutive**, sauf maladie déjà traitée dont le titre baisse progressivement.","prio":"P2","sec":"s9"},{"id":"fc-d162-5330ac","poly":"dermato","fiche":"d162","front":"Sérologie syphilis TT − / TNT − : quelles interprétations ?","back":"Pas de tréponématose ; tréponématose **très récente** (5-15 premiers jours du chancre) ; ou guérie, traitée tôt.","prio":"P2","sec":"s9"},{"id":"fc-d162-f76952","poly":"dermato","fiche":"d162","front":"Sérologie syphilis TT + / TNT + : quelle interprétation ?","back":"Tréponématose traitée ou non, guérie ou non : dépend de la **cinétique du TNT**.","prio":"P2","sec":"s9"},{"id":"fc-d162-e5c06c","poly":"dermato","fiche":"d162","front":"Sérologie syphilis TT − / TNT + : quelles interprétations ?","back":"**Faux positif** ; ou syphilis primaire (TNT positif avant le TT dans **10 %** des cas).","prio":"P2","sec":"s9"},{"id":"fc-d162-60a975","poly":"dermato","fiche":"d162","front":"Sérologie syphilis TT + / TNT − : quelles interprétations ?","back":"**Cicatrice sérologique** (guérie) ; tréponématose très précoce ; syphilis tertiaire très ancienne (rare).","prio":"P2","sec":"s9"},{"id":"fc-d162-8a6687","poly":"dermato","fiche":"d162","front":"Syphilis primaire : dans quel délai TT et TNT peuvent-ils être tous deux négatifs ?","back":"Dans les **7 premiers jours** du chancre.","prio":"P2","sec":"s9"},{"id":"fc-d162-52f5ff","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quel profil sérologique ?","back":"**TT et TNT positifs**, fortement.","prio":"P1","sec":"s9"},{"id":"fc-d162-c22de5","poly":"dermato","fiche":"d162","front":"Syphilis traitée : quel critère sérologique d'efficacité ?","back":"Titre du TNT **divisé par 4** (2 dilutions) à **6 mois**.","prio":"P1","sec":"s9"},{"id":"fc-d162-647729","poly":"dermato","fiche":"d162","front":"Syphilis : quel critère sérologique de recontamination ?","back":"Remontée nette du TNT quantitatif : titre **multiplié par 4** au moins.","prio":"P1","sec":"s9"},{"id":"fc-d162-cde437","poly":"dermato","fiche":"d162","front":"Fausse sérologie syphilitique (TNT +, TT −) : quelles causes principales ?","back":"**Lupus**, **syndrome des antiphospholipides**, **grossesse**, certaines infections (Mycoplasma pneumoniae, borrélioses).","prio":"P2","sec":"s9"},{"id":"fc-d162-cf5ce7","poly":"dermato","fiche":"d162","front":"TPHA positif en dehors d'une tréponématose : est-ce fréquent ?","back":"**Exceptionnel** (lupus systémique, maladie de Lyme…).","prio":"P3","sec":"s9"},{"id":"fc-d162-f1efd4","poly":"dermato","fiche":"d162","front":"Ulcération génitale : quels caractères orientent vers l'herpès ?","back":"Ulcérations superficielles, **douloureuses**, à **contours polycycliques**.","prio":"P1","sec":"s10"},{"id":"fc-d162-57beec","poly":"dermato","fiche":"d162","front":"Chancre mou : quels caractères ?","back":"Terrain africain ; fond **sale**, **très douloureux**, adénopathies **inflammatoires**.","prio":"P2","sec":"s10"},{"id":"fc-d162-1b6525","poly":"dermato","fiche":"d162","front":"Donovanose : quels caractères ?","back":"Terrain africain ; lésions **granulomateuses** peu douloureuses.","prio":"P3","sec":"s10"},{"id":"fc-d162-46a4f6","poly":"dermato","fiche":"d162","front":"Maladie de Nicolas-Favre : quels caractères ?","back":"Terrain (Africains, homosexuels) ; **anorectite**, ulcérations anogénitales, diarrhées trompeuses.","prio":"P3","sec":"s10"},{"id":"fc-d162-88f718","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : devant quelle éruption y penser ?","back":"Devant **toute éruption maculo-papuleuse**, fugace ou persistante.","prio":"P2","sec":"s10"},{"id":"fc-d162-441f54","poly":"dermato","fiche":"d162","front":"Condylomes acuminés : quels diagnostics différentiels physiologiques ?","back":"**Papilles de la couronne du gland** (couronne perlée) et **papillomatose vestibulaire vulvaire**.","prio":"P3","sec":"s10"},{"id":"fc-d162-c9b703","poly":"dermato","fiche":"d162","front":"Condylomes : comment pose-t-on le diagnostic ?","back":"Presque uniquement **clinique** : examen génital et anal complet.","prio":"P1","sec":"s11"},{"id":"fc-d162-8ca8cd","poly":"dermato","fiche":"d162","front":"Condylomes génitaux de la femme : quels examens compléter ?","back":"**Frottis cervico-vaginal** ± **colposcopie** (acide acétique 5 %), ou **test HPV-HR** après 30 ans.","prio":"P2","sec":"s11"},{"id":"fc-d162-c3965e","poly":"dermato","fiche":"d162","front":"Condylomes anaux : quel examen ?","back":"Examen proctologique complet (**anuscopie**).","prio":"P2","sec":"s11"},{"id":"fc-d162-276e83","poly":"dermato","fiche":"d162","front":"Condylomes : quand faire une biopsie ?","back":"Seulement en cas de **doute diagnostique** ou de **suspicion de néoplasie**.","prio":"P2","sec":"s11"},{"id":"fc-d162-f78087","poly":"dermato","fiche":"d162","front":"Condylomes acuminés : quel aspect ?","back":"« **Crêtes-de-coq** » : lésions charnues couvertes de petites saillies kératosiques.","prio":"P2","sec":"s11"},{"id":"fc-d162-a67569","poly":"dermato","fiche":"d162","front":"Condylomes plans : quel aspect ?","back":"**Maculo-papules rosées**, parfois peu visibles, mieux vues après **acide acétique**.","prio":"P3","sec":"s11"},{"id":"fc-d162-811a82","poly":"dermato","fiche":"d162","front":"Néoplasies intra-épithéliales liées aux HPV : quel risque évolutif ?","back":"Évolution possible vers un **carcinome épidermoïde**, en particulier au **col**.","prio":"P2","sec":"s11"},{"id":"fc-d162-95da89","poly":"dermato","fiche":"d162","front":"Néoplasies intra-épithéliales : comment sont-elles classées ?","back":"Selon le **siège** (cervicales, vulvaires, anales, péniennes) et le **grade** (HSIL haut grade, LSIL bas grade).","prio":"P3","sec":"s11"},{"id":"fc-d162-6980ef","poly":"dermato","fiche":"d162","front":"Condylomes chez la femme : pourquoi un examen gynécologique et anal complet ?","back":"Formes **multifocales** et co-infection fréquente par des **HPV oncogènes** (risque de dysplasie).","prio":"P2","sec":"s11"},{"id":"fc-d162-7ef573","poly":"dermato","fiche":"d162","front":"Condylomes de l'enfant : quel mode de contamination le plus souvent ?","back":"**Manuportée** (verrues vulgaires) ou par le **linge** ; parfois mère-enfant.","prio":"P2","sec":"s11"},{"id":"fc-d162-bb823d","poly":"dermato","fiche":"d162","front":"Condylomes de l'enfant : sont-ils un bon marqueur de sévices sexuels ?","back":"**Non**, mauvais marqueur, mais **rester vigilant**.","prio":"P2","sec":"s11"},{"id":"fc-d162-fbd383","poly":"dermato","fiche":"d162","front":"Test HPV-HR : à partir de quel âge est-il recommandé en 1re intention ?","back":"À partir de **30 ans**.","prio":"P1","sec":"s11"},{"id":"fc-d162-e47b05","poly":"dermato","fiche":"d162","front":"Test HPV-HR : pourquoi pas avant 30 ans ?","back":"Les HPV ne sont pas encore tous éliminés : test **presque toujours positif** sans maladie sous-jacente.","prio":"P2","sec":"s11"},{"id":"fc-d162-258f28","poly":"dermato","fiche":"d162","front":"Dépistage du cancer du col : quelle modalité ?","back":"**Frottis cervico-vaginal tous les 3 ans** ou **test HPV-HR**.","prio":"P1","sec":"s11"},{"id":"fc-d162-904413","poly":"dermato","fiche":"d162","front":"Dépistage cervical : que faire devant une dysplasie même mineure ?","back":"**Colposcopie** et, si besoin, **biopsie dirigée** (acide acétique 5 % ou lugol).","prio":"P2","sec":"s11"},{"id":"fc-d162-219b52","poly":"dermato","fiche":"d162","front":"Verrues anogénitales : quelle recherche s'impose ?","back":"La recherche d'une **autre IST**.","prio":"P1","sec":"s11"},{"id":"fc-d162-cefd1c","poly":"dermato","fiche":"d162","front":"Urétrite non compliquée : quelle modalité de traitement est recommandée ?","back":"Traitement **« minute »** (dose unique) donné **sur place**, pendant la consultation.","prio":"P1","sec":"s12"},{"id":"fc-d162-568feb","poly":"dermato","fiche":"d162","front":"Urétrite : pourquoi associer toujours un traitement anti-Chlamydia à celui du gonocoque ?","back":"Urétrite **mixte** dans **15 %** des cas : couverture anti-Chlamydia **systématique**.","prio":"P1","sec":"s12"},{"id":"fc-d162-daa4fb","poly":"dermato","fiche":"d162","front":"Urétrite chez un patient VIH : le schéma change-t-il ?","back":"**Non**, le schéma ne change pas.","prio":"P2","sec":"s12"},{"id":"fc-d162-4abc5b","poly":"dermato","fiche":"d162","front":"Urétrite : combien de temps éviter ou protéger les rapports ?","back":"Au moins **7 jours** ; traitement du ou des partenaires **systématique**.","prio":"P1","sec":"s12"},{"id":"fc-d162-50761e","poly":"dermato","fiche":"d162","front":"Gonocoque : quel antibiotique en 1re intention et à quelle dose ?","back":"**Ceftriaxone 1000 mg IM** en injection unique (IV si trouble de l'hémostase).","prio":"P1","sec":"s12"},{"id":"fc-d162-f1ce00","poly":"dermato","fiche":"d162","front":"Chlamydia (urétrite) : quel traitement à privilégier ?","back":"**Doxycycline 100 mg toutes les 12 h** per os pendant **7 jours**.","prio":"P1","sec":"s12"},{"id":"fc-d162-62e49e","poly":"dermato","fiche":"d162","front":"Couverture anti-Chlamydia : pourquoi préférer la doxycycline à l'azithromycine 1 g ?","back":"L'azithromycine sélectionne des **résistances de Mycoplasma genitalium**.","prio":"P2","sec":"s12"},{"id":"fc-d162-746b70","poly":"dermato","fiche":"d162","front":"Chlamydia : quand utiliser l'azithromycine 1 g en dose unique ?","back":"Si **crainte de mauvaise observance**.","prio":"P2","sec":"s12"},{"id":"fc-d162-836495","poly":"dermato","fiche":"d162","front":"Gonocoque et allergie aux bêtalactamines : quelles alternatives ?","back":"**Azithromycine 2 g** PO, **gentamycine 240 mg IM**, ou **ciprofloxacine 500 mg** (seulement avec antibiogramme), dose unique.","prio":"P2","sec":"s12"},{"id":"fc-d162-6588ae","poly":"dermato","fiche":"d162","front":"Gonocoque : à quelle condition peut-on utiliser la ciprofloxacine ?","back":"Seulement **avec un antibiogramme** (40 % de résistances).","prio":"P2","sec":"s12"},{"id":"fc-d162-4be8b4","poly":"dermato","fiche":"d162","front":"Gonococcie oropharyngée sans antibiogramme possible : quel antibiotique ?","back":"La **ceftriaxone 1000 mg**.","prio":"P3","sec":"s12"},{"id":"fc-d162-268a40","poly":"dermato","fiche":"d162","front":"Urétrite traitée : quand revoir le patient ?","back":"Systématiquement à **J7** : tolérance, efficacité, résultats bactériologiques.","prio":"P2","sec":"s12"},{"id":"fc-d162-56359d","poly":"dermato","fiche":"d162","front":"Gonococcie asymptomatique traitée : quel contrôle ?","back":"**PCR de contrôle** 15 jours après le traitement.","prio":"P3","sec":"s12"},{"id":"fc-d162-92ced4","poly":"dermato","fiche":"d162","front":"Chlamydiose : quand contrôler la PCR après traitement ?","back":"Pas trop tôt : pendant **4 semaines**, des débris peuvent la rendre **faussement positive**.","prio":"P3","sec":"s13"},{"id":"fc-d162-317ce4","poly":"dermato","fiche":"d162","front":"Chlamydiose chez un patient à haut risque de réinfection : quel contrôle ?","back":"Contrôle des sites atteints **3 à 6 mois** après le traitement.","prio":"P3","sec":"s13"},{"id":"fc-d162-06443d","poly":"dermato","fiche":"d162","front":"Chlamydiose : quelles alternatives de 2e intention ?","back":"**Érythromycine 500 mg/6 h** ou **ofloxacine 200 mg/12 h**, 7 jours.","prio":"P3","sec":"s13"},{"id":"fc-d162-dec456","poly":"dermato","fiche":"d162","front":"Grossesse : quels antibiotiques sont contre-indiqués pour une IST ?","back":"**Quinolones**, **cyclines**, **aminosides**.","prio":"P2","sec":"s13"},{"id":"fc-d162-a92274","poly":"dermato","fiche":"d162","front":"Gonococcie chez la femme enceinte : quel traitement ?","back":"**Ceftriaxone 1000 mg IM** dose unique ; alternative **céfixime 400 mg** PO dose unique.","prio":"P3","sec":"s13"},{"id":"fc-d162-2d187c","poly":"dermato","fiche":"d162","front":"Chlamydiose chez la femme enceinte : quel traitement et quel contrôle ?","back":"**Azithromycine 1 g** en prise unique ; **PCR de contrôle à 1 mois**.","prio":"P2","sec":"s13"},{"id":"fc-d162-efb57d","poly":"dermato","fiche":"d162","front":"Infection à Chlamydia du nouveau-né : quel traitement ?","back":"**Érythromycine 12,5 mg/kg toutes les 6 h** PO ou IV, **14 jours**.","prio":"P3","sec":"s13"},{"id":"fc-d162-54056b","poly":"dermato","fiche":"d162","front":"Cervicites de la femme : quelle prise en charge ?","back":"La même que les **urétrites masculines** à Chlamydia et gonocoque.","prio":"P2","sec":"s13"},{"id":"fc-d162-4257e1","poly":"dermato","fiche":"d162","front":"Orchiépididymite à gonocoque : quel traitement ?","back":"**Ceftriaxone 1000 mg IM** ou **céfixime 800 mg** PO, prise unique.","prio":"P3","sec":"s14"},{"id":"fc-d162-86a18a","poly":"dermato","fiche":"d162","front":"Orchiépididymite à Chlamydia : quel traitement ?","back":"**Doxycycline 100 mg/12 h** pendant **10 jours**.","prio":"P3","sec":"s14"},{"id":"fc-d162-85715c","poly":"dermato","fiche":"d162","front":"Gonococcie disséminée : quelle conduite initiale ?","back":"**Hospitaliser**.","prio":"P2","sec":"s14"},{"id":"fc-d162-a5d48b","poly":"dermato","fiche":"d162","front":"Gonococcie disséminée : quelle durée de ceftriaxone IV selon la forme ?","back":"Septicémie **7 à 10 j** ; méningite **10 à 14 j** ; endocardite **4 semaines**.","prio":"P3","sec":"s14"},{"id":"fc-d162-01deb3","poly":"dermato","fiche":"d162","front":"Infection génitale haute non compliquée : quel traitement probabiliste ?","back":"Triple association **ceftriaxone** + **doxycycline** + **métronidazole**.","prio":"P2","sec":"s14"},{"id":"fc-d162-1700e6","poly":"dermato","fiche":"d162","front":"Infection génitale haute probabiliste : quelles doses et durées ?","back":"Ceftriaxone **1 g** IV/IM dose unique + doxycycline **100 mg/12 h** et métronidazole **500 mg/12 h**, **10 jours**.","prio":"P3","sec":"s14"},{"id":"fc-d162-e0db1b","poly":"dermato","fiche":"d162","front":"Infection génitale haute à germe documenté : quel traitement ?","back":"Gonocoque : **ceftriaxone IV 14 j** ; Chlamydia : **doxycycline 14 j**.","prio":"P3","sec":"s14"},{"id":"fc-d162-77d253","poly":"dermato","fiche":"d162","front":"Infection génitale haute traitée : quel contrôle microbiologique ?","back":"**PCR de contrôle** systématique **2 à 3 mois** après le traitement.","prio":"P3","sec":"s14"},{"id":"fc-d162-a4d46b","poly":"dermato","fiche":"d162","front":"Ulcération génitale suspecte de syphilis : faut-il attendre la sérologie pour traiter ?","back":"**Non** : traiter sans attendre le résultat du TT et du TNT.","prio":"P1","sec":"s15"},{"id":"fc-d162-1758b8","poly":"dermato","fiche":"d162","front":"Syphilis précoce : quel traitement de référence ?","back":"**Benzathine-benzylpénicilline 2,4 MU IM** en **une injection**.","prio":"P1","sec":"s15"},{"id":"fc-d162-b9209b","poly":"dermato","fiche":"d162","front":"Syphilis précoce et allergie à la pénicilline : quel traitement ?","back":"**Doxycycline 100 mg** matin et soir pendant **14 jours**.","prio":"P1","sec":"s15"},{"id":"fc-d162-c25f90","poly":"dermato","fiche":"d162","front":"Syphilis : quelles CI de la doxycycline et quelle alternative ?","back":"**Femme enceinte** et **patient VIH+** : **induction de tolérance** à la pénicilline.","prio":"P1","sec":"s15"},{"id":"fc-d162-bd00bf","poly":"dermato","fiche":"d162","front":"Syphilis précoce : dans quelles situations demander un avis spécialisé ?","back":"**Grossesse**, **séropositivité VIH**, **allergie à la pénicilline**.","prio":"P2","sec":"s15"},{"id":"fc-d162-be6acf","poly":"dermato","fiche":"d162","front":"Syphilis précoce : que rechercher à l'examen avant traitement ?","back":"Des signes **neurologiques** et **ophtalmologiques**.","prio":"P2","sec":"s15"},{"id":"fc-d162-471a06","poly":"dermato","fiche":"d162","front":"Réaction d'Herxheimer : quel mécanisme ?","back":"La **lyse des tréponèmes** après l'injection.","prio":"P2","sec":"s15"},{"id":"fc-d162-c9d35d","poly":"dermato","fiche":"d162","front":"Réaction d'Herxheimer : quels signes ?","back":"Quelques heures après l'injection : **fièvre**, céphalées, myalgies, aggravation des lésions cutanées.","prio":"P2","sec":"s15"},{"id":"fc-d162-abae02","poly":"dermato","fiche":"d162","front":"Réaction d'Herxheimer : est-ce une allergie à la pénicilline ?","back":"**Non** : toujours bénigne ; antipyrétique possible, prévenir le patient.","prio":"P2","sec":"s15"},{"id":"fc-d162-e72d4f","poly":"dermato","fiche":"d162","front":"Syphilis précoce traitée : quel calendrier de suivi ?","back":"Clinique et biologie à **3 mois, 6 mois, 1 an**, puis **chaque année** jusqu'à négativation.","prio":"P1","sec":"s15"},{"id":"fc-d162-79bcc3","poly":"dermato","fiche":"d162","front":"Syphilis primaire traitée : quand le TNT doit-il être négatif ?","back":"À **1 an**.","prio":"P2","sec":"s15"},{"id":"fc-d162-27f548","poly":"dermato","fiche":"d162","front":"Syphilis secondaire traitée : quand le TNT doit-il être négatif ?","back":"Dans les **2 ans**.","prio":"P3","sec":"s15"},{"id":"fc-d162-22551d","poly":"dermato","fiche":"d162","front":"Syphilis : peut-on suivre le traitement sur le TT quantitatif ?","back":"**Non** : il ne reflète ni l'évolutivité ni la réponse ; suivi sur le **TNT quantitatif**.","prio":"P1","sec":"s15"},{"id":"fc-d162-a94b2b","poly":"dermato","fiche":"d162","front":"Syphilis : TNT non divisé par 4 à 6 mois, que faire ?","back":"**Retraiter** (avis spécialisé) : benzathine-benzylpénicilline **2,4 MU IM**, **3 injections à 8 jours** d'intervalle.","prio":"P1","sec":"s16"},{"id":"fc-d162-5b3200","poly":"dermato","fiche":"d162","front":"Contact sexuel de moins de 6 semaines avec une syphilis certaine : quelle conduite ?","back":"**Traiter d'emblée** (benzathine-benzylpénicilline 2,4 MU, une injection) et prélever une sérologie.","prio":"P1","sec":"s16"},{"id":"fc-d162-9b052b","poly":"dermato","fiche":"d162","front":"Contact de plus de 6 semaines avec une syphilis certaine : quelle conduite ?","back":"**Sérologie** : positive → traiter ; négative → la **refaire à 3 mois**.","prio":"P2","sec":"s16"},{"id":"fc-d162-673a6c","poly":"dermato","fiche":"d162","front":"Contact d'une syphilis douteuse : quelle conduite ?","back":"Examen + **sérologie** : positive → traiter ; négative → nouvelle sérologie à **3 mois**.","prio":"P2","sec":"s16"},{"id":"fc-d162-f050bc","poly":"dermato","fiche":"d162","front":"Syphilis primaire ou secondaire chez un patient VIH+ : le traitement change-t-il ?","back":"**Non**, même traitement par pénicilline.","prio":"P2","sec":"s16"},{"id":"fc-d162-6c52be","poly":"dermato","fiche":"d162","front":"Patient VIH avec pratiques à risque : quel rythme de sérologie syphilis ?","back":"Au moins **1 fois par an**.","prio":"P2","sec":"s16"},{"id":"fc-d162-7841ff","poly":"dermato","fiche":"d162","front":"Syphilis chez la femme enceinte : pourquoi est-elle grave ?","back":"Le tréponème peut atteindre le **fœtus** après le **4e mois** de grossesse.","prio":"P2","sec":"s16"},{"id":"fc-d162-969226","poly":"dermato","fiche":"d162","front":"Neurosyphilis précoce : quelle conduite diagnostique ?","back":"**Ponction lombaire**.","prio":"P2","sec":"s17"},{"id":"fc-d162-f3d18c","poly":"dermato","fiche":"d162","front":"Neurosyphilis précoce : quel traitement ?","back":"**Pénicilline G** pendant **14 jours**, quel que soit le résultat de la PL.","prio":"P2","sec":"s17"},{"id":"fc-d162-3b929b","poly":"dermato","fiche":"d162","front":"Syphilis secondaire : quels symptômes visuels rechercher à l'interrogatoire ?","back":"**Baisse d'acuité visuelle**, **phosphènes**, **douleurs**.","prio":"P3","sec":"s17"},{"id":"fc-d162-47c22b","poly":"dermato","fiche":"d162","front":"Condylomes : existe-t-il un traitement spécifique de l'HPV ?","back":"**Non** : le but est de faire disparaître les lésions visibles.","prio":"P2","sec":"s18"},{"id":"fc-d162-2fb8c9","poly":"dermato","fiche":"d162","front":"Condylomes : pourquoi les récidives sont-elles fréquentes ?","back":"Le virus peut **persister en peau saine**.","prio":"P3","sec":"s18"},{"id":"fc-d162-9e4433","poly":"dermato","fiche":"d162","front":"Condylomes : faut-il un comportement sexuel à risque pour en avoir ?","back":"**Non** ; l'incubation est très variable : dédramatiser, déculpabiliser.","prio":"P3","sec":"s18"},{"id":"fc-d162-5136c3","poly":"dermato","fiche":"d162","front":"Condylomes : quelles méthodes de destruction physique ?","back":"**Cryothérapie** à l'azote liquide, **laser CO₂**, **électrocoagulation** (toutes exposent à une cicatrice).","prio":"P2","sec":"s18"},{"id":"fc-d162-2c137e","poly":"dermato","fiche":"d162","front":"Cryothérapie des condylomes : quelle limite ?","back":"**Douloureuse** : réservée aux lésions peu étendues.","prio":"P3","sec":"s18"},{"id":"fc-d162-d3b9d1","poly":"dermato","fiche":"d162","front":"Électrocoagulation des condylomes : quel avantage ?","back":"Permet aussi un **prélèvement histologique**.","prio":"P3","sec":"s18"},{"id":"fc-d162-14212d","poly":"dermato","fiche":"d162","front":"Podophyllotoxine 0,5 % : quelles modalités d'application ?","back":"Par le patient, **matin et soir, 3 jours consécutifs par semaine**, uniquement sur les lésions (caustique).","prio":"P3","sec":"s18"},{"id":"fc-d162-91a762","poly":"dermato","fiche":"d162","front":"Podophyllotoxine : quelles contre-indications ?","back":"**Femme enceinte** et **enfant**.","prio":"P2","sec":"s18"},{"id":"fc-d162-bc7d94","poly":"dermato","fiche":"d162","front":"Imiquimod : quel mécanisme et quel schéma ?","back":"**Immunomodulateur** local (cytokines antivirales) ; **3 applications/semaine** pendant **16 semaines**.","prio":"P3","sec":"s18"},{"id":"fc-d162-15e7b0","poly":"dermato","fiche":"d162","front":"Condylomes : quel suivi après traitement ?","back":"À **1 mois**, puis **tous les 3 mois** jusqu'à guérison, puis **6 mois** après la guérison.","prio":"P3","sec":"s18"},{"id":"fc-d162-356008","poly":"dermato","fiche":"d162","front":"Condylomes : quelle conduite vis-à-vis du partenaire ?","back":"**Examiner** le ou les partenaires (portage latent très fréquent).","prio":"P2","sec":"s18"},{"id":"fc-d162-fc3bff","poly":"dermato","fiche":"d162","front":"Trichomonose : quel traitement ?","back":"**Métronidazole 2 g** per os en **dose unique** (ou 500 mg 2 fois/j pendant 7 jours).","prio":"P2","sec":"s19"},{"id":"fc-d162-d6115c","poly":"dermato","fiche":"d162","front":"Trichomonose : quelle alternative au métronidazole ?","back":"**Secnidazole 2 g** en dose unique.","prio":"P3","sec":"s19"},{"id":"fc-d162-3759a4","poly":"dermato","fiche":"d162","front":"Trichomonose : que faire pour le partenaire ?","back":"Dépistage et **traitement simultané** (forte transmissibilité).","prio":"P2","sec":"s19"},{"id":"fc-d162-0f8da4","poly":"dermato","fiche":"d162","front":"Trichomonose : à quoi sont dus les rares échecs ?","back":"À une **sensibilité diminuée au métronidazole**.","prio":"P3","sec":"s19"},{"id":"fc-d162-69a5ce","poly":"dermato","fiche":"d162","front":"Vaccin anti-HPV : quel est son objectif ?","back":"Prévenir les **dysplasies** du col, de l'anus et de l'oropharynx ; surtout **préventif**, avant toute contamination.","prio":"P2","sec":"s20"},{"id":"fc-d162-749eb9","poly":"dermato","fiche":"d162","front":"Vaccination HPV : à quel âge chez tous les adolescents ?","back":"Entre **11 et 14 ans**, filles et garçons ; rattrapage de **15 à 19 ans** révolus.","prio":"P1","sec":"s20"},{"id":"fc-d162-4c2365","poly":"dermato","fiche":"d162","front":"Vaccination HPV : quel vaccin pour toute nouvelle vaccination ?","back":"Le vaccin **nonavalent** (**Gardasil 9®**).","prio":"P1","sec":"s20"},{"id":"fc-d162-6f17a2","poly":"dermato","fiche":"d162","front":"Gardasil 9® entre 11 et 14 ans : quel schéma ?","back":"**2 doses** espacées de **6 à 13 mois**.","prio":"P1","sec":"s20"},{"id":"fc-d162-bb464f","poly":"dermato","fiche":"d162","front":"Gardasil 9® en rattrapage (15-19 ans) : quel schéma ?","back":"**3 doses** à **0, 2 et 6 mois**.","prio":"P2","sec":"s20"},{"id":"fc-d162-f35a24","poly":"dermato","fiche":"d162","front":"Vaccination HPV chez les HSH : jusqu'à quel âge ?","back":"Jusqu'à **26 ans** révolus (3 doses à 0, 2 et 6 mois).","prio":"P2","sec":"s20"},{"id":"fc-d162-32d456","poly":"dermato","fiche":"d162","front":"Vaccination HPV chez l'enfant candidat à une greffe d'organe solide : dès quel âge ?","back":"Dès **9 ans**.","prio":"P3","sec":"s20"},{"id":"fc-d162-f09dfc","poly":"dermato","fiche":"d162","front":"Vaccination HPV chez l'immunodéprimé : quels âges ?","back":"**Mêmes âges** que la population générale, filles et garçons ; rattrapage jusqu'à **19 ans révolus**.","prio":"P3","sec":"s20"},{"id":"fc-d162-75d43e","poly":"dermato","fiche":"d162","front":"Gardasil 9® : quels types d'HPV cible-t-il ?","back":"**6, 11, 16, 18, 31, 33, 45, 52, 58**.","prio":"P2","sec":"s20"},{"id":"fc-d162-3166b0","poly":"dermato","fiche":"d162","front":"Chlamydia : quel dépistage opportuniste systématique ?","back":"Chez les **femmes sexuellement actives de 15 à 25 ans**.","prio":"P1","sec":"s20"},{"id":"fc-d162-6f3e6d","poly":"dermato","fiche":"d162","front":"Chlamydia : quel dépistage ciblé ?","back":"Hommes à risque quel que soit l'âge, femmes à risque de **plus de 25 ans**, femmes consultant pour une **IVG**.","prio":"P2","sec":"s20"},{"id":"fc-d162-408a0c","poly":"dermato","fiche":"d162","front":"Syphilis : quand la sérologie est-elle obligatoire pendant la grossesse ?","back":"Au **1er trimestre**, à renouveler dans certaines situations.","prio":"P2","sec":"s20"},{"id":"fc-d162-14bbca","poly":"dermato","fiche":"d162","front":"Prévention du cancer du col : quelles deux mesures ?","back":"**Dépistage** systématique des infections cervicales à HPV + **vaccination** anti-HPV.","prio":"P2","sec":"s20"},{"id":"fc-d168-b1982c","poly":"dermato","fiche":"d168","front":"HSV : quel type de virus et combien de types ?","back":"Virus à **ADN** de la famille des ***Herpesviridae*** ; **deux types**, **HSV1** et **HSV2**.","prio":"P2","sec":"s1"},{"id":"fc-d168-af9c70","poly":"dermato","fiche":"d168","front":"HSV1 et HSV2 : quelles localisations préférentielles ?","back":"**HSV1** : **moitié haute du corps** ; **HSV2** : **région génitale** (IST, contamination du nouveau-né).","prio":"P1","sec":"s1"},{"id":"fc-d168-127a51","poly":"dermato","fiche":"d168","front":"Herpès génital : quelle part due à HSV1 ?","back":"**20 %** des récurrences et **50 %** des primo-infections génitales.","prio":"P2","sec":"s1"},{"id":"fc-d168-099f3a","poly":"dermato","fiche":"d168","front":"VZV : quelle maladie à la primo-infection et quelle à la récurrence ?","back":"**Varicelle** = primo-infection ; **zona** = récurrence **localisée**.","prio":"P1","sec":"s1"},{"id":"fc-d168-f9b4c6","poly":"dermato","fiche":"d168","front":"VZV : quel mode de contamination ?","back":"Contamination **strictement interhumaine**.","prio":"P2","sec":"s1"},{"id":"fc-d168-d63f0e","poly":"dermato","fiche":"d168","front":"HSV : quelle proportion de primo-infections et de réactivations est asymptomatique ?","back":"**80 %** asymptomatiques (20 % symptomatiques).","prio":"P1","sec":"s1"},{"id":"fc-d168-7041f8","poly":"dermato","fiche":"d168","front":"HSV : définition de la primo-infection ?","back":"**Premier contact infectant**, cutané ou muqueux, avec **HSV1 ou HSV2**.","prio":"P2","sec":"s1"},{"id":"fc-d168-0f88f3","poly":"dermato","fiche":"d168","front":"HSV : définition de la réactivation ?","back":"Nouvelle **réplication virale** chez un sujet déjà infecté par le **même type**.","prio":"P2","sec":"s1"},{"id":"fc-d168-3da76b","poly":"dermato","fiche":"d168","front":"HSV : définition de la récurrence ?","back":"Une **réactivation qui s'exprime cliniquement**.","prio":"P1","sec":"s1"},{"id":"fc-d168-a8dbf3","poly":"dermato","fiche":"d168","front":"HSV : définition de l'excrétion virale asymptomatique ?","back":"Excrétion de virus **sans aucun signe clinique**.","prio":"P2","sec":"s1"},{"id":"fc-d168-5d77b6","poly":"dermato","fiche":"d168","front":"Infection initiale non primaire : définition ?","back":"Premier contact avec un type d'HSV chez un sujet **déjà infecté par l'autre type** (signes en général moins sévères).","prio":"P2","sec":"s1"},{"id":"fc-d168-87c98d","poly":"dermato","fiche":"d168","front":"HSV : incubation d'une primo-infection ?","back":"Environ **une semaine**.","prio":"P3","sec":"s1"},{"id":"fc-d168-87e562","poly":"dermato","fiche":"d168","front":"HSV : où le virus reste-t-il latent ?","back":"Dans le **ganglion sensitif spinal**, « sanctuaire » peu accessible à l'immunité et aux traitements.","prio":"P1","sec":"s1"},{"id":"fc-d168-578be6","poly":"dermato","fiche":"d168","front":"HSV : comment rejoint-il le ganglion puis la peau ?","back":"Migration **antérograde** le long des dendrites sensitives vers le ganglion ; à la réactivation, migration **rétrograde** vers le territoire d'innervation.","prio":"P2","sec":"s1"},{"id":"fc-d168-b171c4","poly":"dermato","fiche":"d168","front":"HSV : que se passe-t-il pendant la latence ?","back":"Le génome viral est **transcrit sans synthèse de protéines** (quiescence).","prio":"P3","sec":"s1"},{"id":"fc-d168-d9c7bf","poly":"dermato","fiche":"d168","front":"Herpès virus : quel effet cytopathogène typique ?","back":"La **ballonisation** des kératinocytes → **vésicule intra-épithéliale**.","prio":"P2","sec":"s1"},{"id":"fc-d168-79ca64","poly":"dermato","fiche":"d168","front":"HSV : durée de l'excrétion virale en primo-infection et en réactivation ?","back":"Primo-infection : **8-20 jours** ; réactivation : **2-4 jours**.","prio":"P2","sec":"s1"},{"id":"fc-d168-696eae","poly":"dermato","fiche":"d168","front":"HSV : pourquoi l'excrétion virale est-elle la clé de la contagion ?","back":"Elle est **intermittente**, avec **ou sans signes cliniques** : source de contamination (génitale, néonatale).","prio":"P1","sec":"s1"},{"id":"fc-d168-e5e91e","poly":"dermato","fiche":"d168","front":"Varicelle : mode de contamination et incubation ?","back":"Contamination **respiratoire** ; incubation de **14 jours** ; dissémination **hématogène**.","prio":"P2","sec":"s1"},{"id":"fc-d168-4c8d3c","poly":"dermato","fiche":"d168","front":"Varicelle chez l'immunocompétent : l'infection est-elle immunisante ?","back":"**Oui** (immunité innée, humorale avec anticorps dès J5, maximum J20, et cellulaire).","prio":"P3","sec":"s1"},{"id":"fc-d168-d4e3db","poly":"dermato","fiche":"d168","front":"VZV : où reste-t-il latent après la varicelle ?","back":"Dans les **ganglions sensitifs**.","prio":"P2","sec":"s1"},{"id":"fc-d168-8b31e1","poly":"dermato","fiche":"d168","front":"Zona : quelles causes de rupture de la latence du VZV ?","back":"Pathogénicité virale modifiée ou **perte du contrôle immunitaire** (immunodépression, **sénescence immunitaire** du sujet âgé).","prio":"P2","sec":"s1"},{"id":"fc-d168-b30ec0","poly":"dermato","fiche":"d168","front":"Zona : combien d'épisodes en général chez un même sujet ?","back":"En général **un seul épisode**.","prio":"P3","sec":"s1"},{"id":"fc-d168-f51451","poly":"dermato","fiche":"d168","front":"Infection herpétique : quelles défenses jouent un rôle important ?","back":"Les défenses immunitaires **cellulaires** ; une primo-infection herpétique chez un **immunodéprimé** est **grave**.","prio":"P2","sec":"s1"},{"id":"fc-d168-a7d020","poly":"dermato","fiche":"d168","front":"HSV : quel est le mode de transmission principal ?","back":"**Contact direct** muqueux ou cutanéo-muqueux avec une personne qui **excrète** du virus.","prio":"P1","sec":"s2"},{"id":"fc-d168-e6be16","poly":"dermato","fiche":"d168","front":"HSV : quels facteurs favorisent la transmission ?","back":"**Épithélium altéré** : érosion, infection, dermatose inflammatoire des muqueuses, **rapport traumatisant**.","prio":"P2","sec":"s2"},{"id":"fc-d168-8620a4","poly":"dermato","fiche":"d168","front":"HSV : quelles sont les trois voies de transmission materno-fœtale ?","back":"***In utero*** (transplacentaire) ; à l'**accouchement** (filière génitale) ; **après la naissance** (contact direct avec un proche).","prio":"P1","sec":"s2"},{"id":"fc-d168-7cb595","poly":"dermato","fiche":"d168","front":"HSV : pourquoi la transmission indirecte est-elle rare ?","back":"Le virus **résiste mal dans le milieu extérieur**.","prio":"P2","sec":"s2"},{"id":"fc-d168-10b3be","poly":"dermato","fiche":"d168","front":"Zona : est-il contagieux ?","back":"**Oui** : il y a **excrétion virale**.","prio":"P2","sec":"s2"},{"id":"fc-d168-b10006","poly":"dermato","fiche":"d168","front":"Herpès génital : quelle place parmi les IST ?","back":"**IST très fréquente**, impact majeur sur la qualité de vie ; **première cause d'érosion/ulcération génitale** dans les pays développés.","prio":"P1","sec":"s2"},{"id":"fc-d168-8142c4","poly":"dermato","fiche":"d168","front":"Herpès néonatal : fréquence et gravité ?","back":"**Rare mais grave** (parfois mortel, lourdes séquelles neurosensorielles) ; ~3/100 000 grossesses en France ; HSV2 dans ~2/3 des cas.","prio":"P2","sec":"s2"},{"id":"fc-d168-476553","poly":"dermato","fiche":"d168","front":"HSV1 : quand a lieu la primo-infection et quelle séroprévalence adulte ?","back":"Dans l'**enfance** ; IgG anti-HSV1 chez **80 %** des adultes.","prio":"P3","sec":"s2"},{"id":"fc-d168-c3082f","poly":"dermato","fiche":"d168","front":"HSV2 : quand a lieu la primo-infection et quelle séroprévalence ?","back":"Dans les **deux premières décennies de vie sexuelle** ; **15 à 30 %** de la population générale, en hausse.","prio":"P3","sec":"s2"},{"id":"fc-d168-606448","poly":"dermato","fiche":"d168","front":"Herpès génital : quels facteurs de risque ?","back":"**Sexe féminin**, premier rapport **précoce**, nombre de **partenaires**, antécédents d'**IST**, **VIH**, bas niveau socio-économique.","prio":"P3","sec":"s2"},{"id":"fc-d168-e71832","poly":"dermato","fiche":"d168","front":"Varicelle : contagiosité et séroprévalence adulte ?","back":"Maladie éruptive **la plus contagieuse** ; séroprévalence **> 90 %** chez l'adulte.","prio":"P2","sec":"s2"},{"id":"fc-d168-906c31","poly":"dermato","fiche":"d168","front":"Varicelle : à quel âge survient-elle le plus ?","back":"**> 90 %** des cas entre **1 et 14 ans**, pic entre **5 et 9 ans** ; en général bénigne.","prio":"P3","sec":"s2"},{"id":"fc-d168-9e47dd","poly":"dermato","fiche":"d168","front":"Zona : fréquence et âge de survenue ?","back":"**20 %** de la population ; après **50 ans**, pic après **75 ans** ; rare chez l'enfant.","prio":"P2","sec":"s2"},{"id":"fc-d168-4ad0a0","poly":"dermato","fiche":"d168","front":"Zona de l'adulte jeune : que rechercher ?","back":"Une **immunodépression** (**VIH**, maladie lymphoproliférative…).","prio":"P1","sec":"s2"},{"id":"fc-d168-4e6a36","poly":"dermato","fiche":"d168","front":"Varicelle de l'adulte : quel risque particulier ?","back":"Risque de **décès** (pneumopathie surtout), en particulier **après 50 ans**.","prio":"P3","sec":"s2"},{"id":"fc-d168-94694c","poly":"dermato","fiche":"d168","front":"HSV : quelle lésion élémentaire cutanée ?","back":"**Vésicules** claires puis troubles, groupées **en bouquet**, puis érosions à contours **polycycliques** et croûtes.","prio":"P1","sec":"s3"},{"id":"fc-d168-87fbe1","poly":"dermato","fiche":"d168","front":"HSV : que voit-on surtout sur les muqueuses ?","back":"Des **érosions** rondes/ovales, multiples, coalescentes, **polycycliques**, à bord inflammatoire (vésicules fugaces).","prio":"P1","sec":"s3"},{"id":"fc-d168-58c0d5","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quel terrain typique ?","back":"**Petit enfant de plus de 6 mois** (disparition des anticorps maternels) ; HSV1 > HSV2.","prio":"P1","sec":"s3"},{"id":"fc-d168-87601e","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quel aspect buccal ?","back":"Gencives **gonflées, érosives, qui saignent** ; érosions **polycycliques** à bord inflammatoire, enduit blanchâtre.","prio":"P2","sec":"s3"},{"id":"fc-d168-0d1240","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quels signes associés ?","back":"Fièvre à **39°**, myalgies, **dysphagie** marquée, haleine fétide, **adénopathies cervicales** sensibles, parfois vésicules péribuccales.","prio":"P2","sec":"s3"},{"id":"fc-d168-e10202","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quelle évolution ?","back":"Favorable en **10 à 15 jours**.","prio":"P2","sec":"s3"},{"id":"fc-d168-d0041b","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quel signe de gravité ?","back":"Une **alimentation impossible** à cause de la dysphagie.","prio":"P1","sec":"s3"},{"id":"fc-d168-62bfb1","poly":"dermato","fiche":"d168","front":"Primo-infection génitale chez la femme : quel tableau ?","back":"**Vulvovaginite aiguë** brutale, douleurs **très intenses**, érosions polycycliques débordant vers l'anus, fièvre, adénopathies inguinales.","prio":"P1","sec":"s3"},{"id":"fc-d168-f93e01","poly":"dermato","fiche":"d168","front":"Primo-infection génitale chez la femme : durée de guérison ?","back":"**2 à 3 semaines**.","prio":"P2","sec":"s3"},{"id":"fc-d168-65fa71","poly":"dermato","fiche":"d168","front":"Primo-infection génitale : faut-il rechercher systématiquement les érosions du col ?","back":"**Non** : examen **très douloureux**, ne pas les chercher systématiquement.","prio":"P3","sec":"s3"},{"id":"fc-d168-22eff9","poly":"dermato","fiche":"d168","front":"Primo-infection génitale chez l'homme : quel tableau ?","back":"**Moins intense** : **balanite œdémateuse** à érosions polycycliques, parfois vésicules (fourreau, scrotum).","prio":"P2","sec":"s3"},{"id":"fc-d168-68753a","poly":"dermato","fiche":"d168","front":"Primo-infection génitale herpétique : quel signe de gravité ?","back":"Une **rétention d'urines** réactionnelle à la douleur.","prio":"P1","sec":"s3"},{"id":"fc-d168-658cc5","poly":"dermato","fiche":"d168","front":"Primo-infection herpétique anale : quel tableau et quel terrain ?","back":"**Anite ou anorectite érosive aiguë**, deux sexes, plus fréquente chez l'**homosexuel masculin**.","prio":"P3","sec":"s3"},{"id":"fc-d168-d947a5","poly":"dermato","fiche":"d168","front":"Panaris herpétique : quel terrain ?","back":"Primo-infection cutanée du **doigt**, notamment chez les **soignants** (contamination professionnelle).","prio":"P2","sec":"s3"},{"id":"fc-d168-323034","poly":"dermato","fiche":"d168","front":"Primo-infection herpétique oculaire : quel tableau ?","back":"Kérato-conjonctivite ou kératite **unilatérale** aiguë ; parfois vésicules palpébrales, adénopathie **prétragienne**.","prio":"P2","sec":"s3"},{"id":"fc-d168-fd40d6","poly":"dermato","fiche":"d168","front":"Herpès oculaire : quelles complications ?","back":"**Uvéite**, **ulcérations cornéennes** avec séquelles visuelles.","prio":"P1","sec":"s3"},{"id":"fc-d168-2dddc4","poly":"dermato","fiche":"d168","front":"Primo-infection herpétique ORL : quelles formes ?","back":"**Angine herpétique** ; **rhinite aiguë érosive** (vésicules péri-narinaires, adénopathies cervicales).","prio":"P3","sec":"s3"},{"id":"fc-d168-036104","poly":"dermato","fiche":"d168","front":"Herpès oculaire : quel traitement local favorise les complications ?","back":"La **corticothérapie locale** ; avis **ophtalmologique** indispensable.","prio":"P2","sec":"s3"},{"id":"fc-d168-0e89d6","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : quels prodromes ?","back":"**Brûlure**, **picotements**, **prurit**, **stéréotypés** (les mêmes à chaque fois chez un patient).","prio":"P1","sec":"s4"},{"id":"fc-d168-400434","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : délai d'apparition des vésicules après les prodromes ?","back":"**Quelques heures** plus tard : vésicules groupées **en bouquet**.","prio":"P2","sec":"s4"},{"id":"fc-d168-d322ed","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : délai de cicatrisation ?","back":"**7 à 14 jours**.","prio":"P1","sec":"s4"},{"id":"fc-d168-348ab4","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : signes généraux associés ?","back":"En général **absents** ; parfois fébricule, asthénie, adénopathie, dysesthésies.","prio":"P2","sec":"s4"},{"id":"fc-d168-bebd5c","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : quelle topographie chez un même malade ?","back":"**Stéréotypée** : le **siège de la primo-infection**.","prio":"P1","sec":"s4"},{"id":"fc-d168-f12458","poly":"dermato","fiche":"d168","front":"Récurrence herpétique : quels sièges par ordre de fréquence ?","back":"**Labial** > génital > cutané, nasal, oculaire.","prio":"P2","sec":"s4"},{"id":"fc-d168-2e613a","poly":"dermato","fiche":"d168","front":"Herpès labial : où siège-t-il et quel diagnostic différentiel ?","back":"**Jonction demi-muqueuse/peau** ; différentiel : **aphtes**.","prio":"P2","sec":"s4"},{"id":"fc-d168-e165cd","poly":"dermato","fiche":"d168","front":"Herpès nasal : quel diagnostic différentiel ?","back":"**Folliculite staphylococcique**.","prio":"P3","sec":"s4"},{"id":"fc-d168-c38841","poly":"dermato","fiche":"d168","front":"Stomatite herpétique récurrente : quel diagnostic différentiel ?","back":"L'**aphtose récidivante**.","prio":"P3","sec":"s4"},{"id":"fc-d168-0e85c7","poly":"dermato","fiche":"d168","front":"Kératite herpétique : quel risque fait sa gravité ?","back":"**Ulcérations cornéennes**, **risque de cécité** ; avis ophtalmologique.","prio":"P1","sec":"s4"},{"id":"fc-d168-eceecb","poly":"dermato","fiche":"d168","front":"Herpès génital récurrent atypique : qu'est-ce qui oriente ?","back":"Le caractère **récidivant**, avec **prodromes** et **siège identiques** d'une poussée à l'autre.","prio":"P1","sec":"s4"},{"id":"fc-d168-51148b","poly":"dermato","fiche":"d168","front":"Herpès génital récurrent : quels aspects atypiques possibles ?","back":"**Ulcérations aphtoïdes**, **fissures**, **œdème**… (aspect typique : vésicules ou érosions multiples groupées).","prio":"P3","sec":"s4"},{"id":"fc-d168-187178","poly":"dermato","fiche":"d168","front":"Herpes gladiatorum : de quoi s'agit-il ?","back":"Herpès cutané **diffus** favorisé par un **sport de contact**.","prio":"P3","sec":"s4"},{"id":"fc-d168-8bbd58","poly":"dermato","fiche":"d168","front":"Récurrences herpétiques : quels facteurs physiques favorisants ?","back":"**Rayons UV**, **froid**, **traumatisme local**.","prio":"P2","sec":"s4"},{"id":"fc-d168-39801d","poly":"dermato","fiche":"d168","front":"Récurrences herpétiques : quels facteurs physiologiques et systémiques ?","back":"**Règles** (herpès cataménial), **rapports sexuels** ; **immunodépression**, **stress**, **asthénie** ; infections intercurrentes.","prio":"P3","sec":"s4"},{"id":"fc-d168-8e1221","poly":"dermato","fiche":"d168","front":"Récurrences herpétiques : quels facteurs iatrogènes ?","back":"**Immunosuppresseurs**, **chirurgie ou laser** dans le territoire.","prio":"P3","sec":"s4"},{"id":"fc-d168-fb76ee","poly":"dermato","fiche":"d168","front":"Syndrome de Kaposi-Juliusberg : définition ?","back":"Surinfection herpétique (primo-contact ou récurrence HSV) d'une **dermatite atopique**.","prio":"P1","sec":"s5"},{"id":"fc-d168-3de742","poly":"dermato","fiche":"d168","front":"Syndrome de Kaposi-Juliusberg : quel terrain ?","back":"Sujet jeune ou **nourrisson**, atopie **sévère** et/ou **en poussée** et/ou **mal traitée**.","prio":"P2","sec":"s5"},{"id":"fc-d168-a64485","poly":"dermato","fiche":"d168","front":"Syndrome de Kaposi-Juliusberg : quel tableau clinique ?","back":"AEG, **fièvre** ; éruption vésiculo-érosive-croûteuse **profuse** extensive, **ombilication centrale**, débutant **volontiers** au **visage**.","prio":"P1","sec":"s5"},{"id":"fc-d168-424a59","poly":"dermato","fiche":"d168","front":"Syndrome de Kaposi-Juliusberg : quelle évolution sous traitement ?","back":"Favorable en **quelques jours** sous **antiviral IV**.","prio":"P2","sec":"s5"},{"id":"fc-d168-3ecaeb","poly":"dermato","fiche":"d168","front":"Primo-infection herpétique chez la femme enceinte : quels risques maternels ?","back":"Risque accru d'**hépatite fulminante** ou d'**encéphalite**.","prio":"P1","sec":"s5"},{"id":"fc-d168-7640c2","poly":"dermato","fiche":"d168","front":"Récurrences herpétiques chez la femme enceinte : quel risque ?","back":"Récurrences **fréquentes**, avec risque de **transmission materno-fœtale**.","prio":"P3","sec":"s5"},{"id":"fc-d168-49acad","poly":"dermato","fiche":"d168","front":"Transmission in utero de l'HSV : quelles conséquences ?","back":"**Très grave** : avortement, RCIU, atteintes oculaires, neurologiques, cardiaques.","prio":"P2","sec":"s5"},{"id":"fc-d168-1e537a","poly":"dermato","fiche":"d168","front":"Herpès néonatal : mortalité selon la forme ?","back":"Cutanéo-muqueuse : **pas de mortalité** ; neurologique : **15 %** (séquelles fréquentes) ; systémique : **40-70 %**.","prio":"P1","sec":"s5"},{"id":"fc-d168-cf8b5c","poly":"dermato","fiche":"d168","front":"Méningo-encéphalite herpétique : fréquence lors d'une récurrence chez l'adulte ?","back":"**Exceptionnelle** ; fort risque de **séquelles**.","prio":"P2","sec":"s5"},{"id":"fc-d168-1c2eff","poly":"dermato","fiche":"d168","front":"Herpès : quelles atteintes viscérales citer ?","back":"**Méningo-encéphalite**, **œsophagite** (HSV1, immunodéprimé), **hépatite** (fulminante possible), **broncho-pneumopathie**.","prio":"P2","sec":"s5"},{"id":"fc-d168-e78a20","poly":"dermato","fiche":"d168","front":"Hépatite herpétique : sur quel terrain peut-elle devenir fulminante ?","back":"**Femme enceinte**, **immunodéprimé**.","prio":"P2","sec":"s5"},{"id":"fc-d168-4e0627","poly":"dermato","fiche":"d168","front":"Herpès de l'immunodéprimé : quel aspect des lésions ?","back":"Lésions **étendues**, **nécrotiques**, **persistantes** ; récurrences fréquentes, atypiques, ulcérations traînantes.","prio":"P2","sec":"s5"},{"id":"fc-d168-6e0005","poly":"dermato","fiche":"d168","front":"Érythème polymorphe : quelle part due à l'herpès ?","back":"Principal facteur : **50 %** des cas (primo-infection, récurrence ou excrétion).","prio":"P2","sec":"s5"},{"id":"fc-d168-8a98ba","poly":"dermato","fiche":"d168","front":"Érythème polymorphe post-herpétique : délai et aspect ?","back":"**5-15 jours** après l'épisode ; papules **en cocarde** à triple contour aux **extrémités**, érosions muqueuses.","prio":"P2","sec":"s5"},{"id":"fc-d168-371b96","poly":"dermato","fiche":"d168","front":"Herpès typique sur terrain non à risque : comment poser le diagnostic ?","back":"Diagnostic **clinique**.","prio":"P1","sec":"s6"},{"id":"fc-d168-fc2d05","poly":"dermato","fiche":"d168","front":"Herpès : dans quelles situations faut-il une confirmation virologique ?","back":"**Atypie**, forme **sévère/compliquée**, atteinte **viscérale**, **immunodéprimé**, **femme en âge de procréer**, grossesse.","prio":"P1","sec":"s6"},{"id":"fc-d168-29bb2e","poly":"dermato","fiche":"d168","front":"Femme en âge de procréer avec herpès : quelle exigence diagnostique ?","back":"Au moins **une confirmation** par diagnostic direct.","prio":"P2","sec":"s6"},{"id":"fc-d168-56c7a7","poly":"dermato","fiche":"d168","front":"Herpès pendant la grossesse : quand le diagnostic direct est-il impératif ?","back":"Poussée **au terme** (infection non prouvée) ou au **dernier mois** ; **pas de sérologie systématique**.","prio":"P2","sec":"s6"},{"id":"fc-d168-f243fa","poly":"dermato","fiche":"d168","front":"Début de l'accouchement : quel prélèvement selon la situation herpétique ?","back":"**Lésions génitales suspectes** : diagnostic direct **rapide** sur les lésions ; **antécédent d'herpès génital** : prélèvement de l'**endocol**.","prio":"P2","sec":"s6"},{"id":"fc-d168-b01a13","poly":"dermato","fiche":"d168","front":"Nouveau-né de mère avec lésions pendant le travail ou antécédent d'herpès : quels prélèvements ?","back":"Diagnostic direct à **48 et 72 heures** de vie (**oculaire** et **pharyngé**).","prio":"P2","sec":"s6"},{"id":"fc-d168-4f088f","poly":"dermato","fiche":"d168","front":"Herpès : comment réaliser le prélèvement pour diagnostic direct ?","back":"Écouvillonner la sérosité d'une **lésion récente**, **milieu de transport spécifique**, acheminement rapide.","prio":"P1","sec":"s6"},{"id":"fc-d168-d0368a","poly":"dermato","fiche":"d168","front":"HSV : quelle est la technique diagnostique de référence ?","back":"La **PCR** : très sensible, très spécifique, résultat **< 24 h** ; a remplacé la culture.","prio":"P1","sec":"s6"},{"id":"fc-d168-c82c6b","poly":"dermato","fiche":"d168","front":"Sérologie HSV : quel intérêt diagnostique ?","back":"**Limité** : prouve un **contage ancien** (IgG chez 80 % des adultes) ; éventuellement **séroconversion** en primo-infection.","prio":"P1","sec":"s6"},{"id":"fc-d168-d316e9","poly":"dermato","fiche":"d168","front":"VZV : quel examen de référence en cas de besoin ?","back":"**PCR VZV** sur le liquide d'une **vésicule récente**.","prio":"P1","sec":"s6"},{"id":"fc-d168-bcef55","poly":"dermato","fiche":"d168","front":"VZV : cytodiagnostic, biopsie et sérologie ont-ils un intérêt ?","back":"**Pas d'intérêt pratique**.","prio":"P2","sec":"s6"},{"id":"fc-d168-2c3afe","poly":"dermato","fiche":"d168","front":"VZV : quand rechercher une immunodépression et par quels examens ?","back":"Sujets **jeunes** et formes sévères/compliquées/atypiques : **NFS** (hémopathie type LLC) et **sérologie VIH**.","prio":"P1","sec":"s6"},{"id":"fc-d168-94d003","poly":"dermato","fiche":"d168","front":"VZV : quelle lésion élémentaire cutanée ?","back":"**Vésicules ombiliquées** (muqueuses : érosions rondes à bord inflammatoire).","prio":"P1","sec":"s7"},{"id":"fc-d168-56d7fc","poly":"dermato","fiche":"d168","front":"Varicelle de l'enfant : faut-il un antiviral ?","back":"**Non** : maladie habituellement **bénigne**, **pas de traitement antiviral**.","prio":"P1","sec":"s7"},{"id":"fc-d168-759ff5","poly":"dermato","fiche":"d168","front":"Varicelle : quels prodromes ?","back":"**Catarrhe oculo-nasal**, fièvre modérée (24-48 h).","prio":"P3","sec":"s7"},{"id":"fc-d168-51eaa2","poly":"dermato","fiche":"d168","front":"Varicelle : quelle phase d'état ?","back":"Fièvre **38-39 °C**, **prurit intense**, éruption vésiculeuse.","prio":"P2","sec":"s7"},{"id":"fc-d168-89fd97","poly":"dermato","fiche":"d168","front":"Varicelle : quelles caractéristiques de l'éruption ?","back":"**Descendante** (début au cuir chevelu), vésicules qui s'**ombiliquent** et croûtent, **éléments d'âges différents**.","prio":"P1","sec":"s7"},{"id":"fc-d168-2c2622","poly":"dermato","fiche":"d168","front":"Varicelle : surinfection bactérienne, quels germes et quel aspect ?","back":"**Staphylocoque doré** ou **streptocoque** ; impétiginisation : placards croûteux **mélicériques**.","prio":"P1","sec":"s7"},{"id":"fc-d168-d49eaf","poly":"dermato","fiche":"d168","front":"Varicelle : quelle surinfection grave est une grande urgence médico-chirurgicale ?","back":"**Dermohypodermite / fasciite nécrosante streptococcique** (placards nécrotiques extensifs, sepsis sévère).","prio":"P1","sec":"s7"},{"id":"fc-d168-a3fc2d","poly":"dermato","fiche":"d168","front":"Épidermolyse staphylococcique (SSSS) : quel tableau ?","back":"Éruption **scarlatiniforme** puis **desquamation**, par toxine exfoliante du staphylocoque.","prio":"P3","sec":"s7"},{"id":"fc-d168-c49d7a","poly":"dermato","fiche":"d168","front":"Pneumopathie varicelleuse : terrain et facteurs favorisants ?","back":"Rare (**5 %**), surtout l'**adulte** ; favorisée par **tabac** et **grossesse** ; aussi nouveau-né et nourrisson.","prio":"P1","sec":"s7"},{"id":"fc-d168-080e6d","poly":"dermato","fiche":"d168","front":"Pneumopathie varicelleuse : quand survient-elle et quels signes ?","back":"**1 à 6 jours** après l'éruption : toux, dyspnée, fièvre, **hémoptysies** ; opacités micro- et macronodulaires.","prio":"P2","sec":"s7"},{"id":"fc-d168-90b3d7","poly":"dermato","fiche":"d168","front":"Pneumopathie varicelleuse : quelle part des décès de la varicelle de l'adulte ?","back":"**30 %** des décès.","prio":"P1","sec":"s7"},{"id":"fc-d168-26b108","poly":"dermato","fiche":"d168","front":"Nourrisson : principale cause de décès de la varicelle avant 6 mois ?","back":"La **pneumopathie varicelleuse**.","prio":"P3","sec":"s7"},{"id":"fc-d168-08c538","poly":"dermato","fiche":"d168","front":"Syndrome de Reye : définition et mortalité ?","back":"**Encéphalopathie + stéatose hépatique** (ou polyviscérale), mortel dans **80 %** des cas.","prio":"P1","sec":"s7"},{"id":"fc-d168-01f52c","poly":"dermato","fiche":"d168","front":"Varicelle : quel médicament est formellement contre-indiqué et pourquoi ?","back":"L'**aspirine** : risque de **syndrome de Reye**.","prio":"P1","sec":"s7"},{"id":"fc-d168-24f4e3","poly":"dermato","fiche":"d168","front":"Varicelle : complication neurologique non spécifique du petit enfant ?","back":"**Convulsions hyperthermiques**.","prio":"P3","sec":"s7"},{"id":"fc-d168-e9bb7a","poly":"dermato","fiche":"d168","front":"Varicelle : complications neurologiques spécifiques ?","back":"**Ataxie cérébelleuse** (régressive), encéphalite, méningite lymphocytaire, myélite, polyradiculonévrite.","prio":"P3","sec":"s7"},{"id":"fc-d168-a86323","poly":"dermato","fiche":"d168","front":"Varicelle de l'immunodéprimé : quelles formes ?","back":"Formes graves plus fréquentes : **ulcéro-hémorragiques**, **profuses**, atteinte **viscérale** (pulmonaire surtout).","prio":"P2","sec":"s7"},{"id":"fc-d168-4826ef","poly":"dermato","fiche":"d168","front":"Varicelle et VIH : quelles particularités ?","back":"Éruption **plus longue**, formes atypiques plus fréquentes ; **sévérité non modifiée**.","prio":"P3","sec":"s7"},{"id":"fc-d168-bed837","poly":"dermato","fiche":"d168","front":"Femme enceinte : proportion non immunisée contre la varicelle ?","back":"**5 %** ; risque de **pneumopathie maternelle**.","prio":"P2","sec":"s7"},{"id":"fc-d168-fea88e","poly":"dermato","fiche":"d168","front":"Varicelle néonatale : gravité ?","back":"Rare mais **grave** : septicémie varicelleuse multiviscérale ; décès dans **30 %** des cas.","prio":"P1","sec":"s7"},{"id":"fc-d168-2ed5a9","poly":"dermato","fiche":"d168","front":"Varicelle avant la 20e semaine de grossesse : quel risque ?","back":"**Fœtopathie varicelleuse** (surtout 13e-20e SA) → surveillance en **centre de diagnostic anténatal**.","prio":"P1","sec":"s7"},{"id":"fc-d168-0b3b41","poly":"dermato","fiche":"d168","front":"Varicelle après la 20e semaine de grossesse : quel risque pour l'enfant ?","back":"Varicelle in utero avec risque de **zona** dans les premières semaines/premiers mois de vie.","prio":"P2","sec":"s7"},{"id":"fc-d168-b249e7","poly":"dermato","fiche":"d168","front":"Varicelle maternelle : quelle fenêtre expose à la varicelle néonatale ?","back":"De **5 jours avant** à **2 jours après** l'accouchement.","prio":"P1","sec":"s7"},{"id":"fc-d168-272448","poly":"dermato","fiche":"d168","front":"Zona pendant la grossesse : risque pour l'enfant ?","back":"**Aucune transmission** à l'enfant.","prio":"P1","sec":"s7"},{"id":"fc-d168-e42d58","poly":"dermato","fiche":"d168","front":"Zona : comment évolue l'éruption ?","back":"**Placard érythémato-œdémateux** → vésicules en **bouquet** → croûtes → cicatrisation vers **10 jours**.","prio":"P2","sec":"s8"},{"id":"fc-d168-5205f0","poly":"dermato","fiche":"d168","front":"Zona : caractéristiques des douleurs ?","back":"Douleurs **radiculaires**, **unilatérales**, intenses, **neuropathiques** (brûlure, coup de poignard) ; peuvent **précéder** l'éruption.","prio":"P1","sec":"s8"},{"id":"fc-d168-786e1d","poly":"dermato","fiche":"d168","front":"Zona : quelle topographie de l'éruption ?","back":"**Unilatérale**, distribution **radiculaire (métamérique)**, n'importe quel dermatome.","prio":"P1","sec":"s8"},{"id":"fc-d168-da2b5a","poly":"dermato","fiche":"d168","front":"Zona : signes d'accompagnement ?","back":"**Fièvre discrète** (38-38,5 °C), **adénopathie satellite**.","prio":"P3","sec":"s8"},{"id":"fc-d168-4610ab","poly":"dermato","fiche":"d168","front":"Zona : quelle forme est la plus fréquente ?","back":"**Intercostal ou dorsolombaire** (**50 %**), éruption en **demi-ceinture**.","prio":"P1","sec":"s8"},{"id":"fc-d168-37412e","poly":"dermato","fiche":"d168","front":"Zona ophtalmique : quel signe fait craindre une atteinte oculaire ?","back":"Une éruption de la **narine** et de la **cloison** (rameau **nasal interne**).","prio":"P1","sec":"s8"},{"id":"fc-d168-edd15c","poly":"dermato","fiche":"d168","front":"Zona auriculaire : quel ganglion et quelle zone ?","back":"Ganglion **géniculé** ; zone de **Ramsay-Hunt** (conduit auditif externe, conque).","prio":"P2","sec":"s8"},{"id":"fc-d168-a9a731","poly":"dermato","fiche":"d168","front":"Zona auriculaire : quels signes associés ?","back":"**Otalgie** très intense, adénopathie prétragienne, anesthésie des 2/3 antérieurs de l'hémilangue, parfois **paralysie faciale**, troubles cochléo-vestibulaires.","prio":"P2","sec":"s8"},{"id":"fc-d168-ef9b69","poly":"dermato","fiche":"d168","front":"Zona ophtalmique : quelles complications oculaires (surtout après 50 ans) ?","back":"Atteinte **cornéenne**, **uvéite antérieure**, kératites (stromales et neurotrophiques **durables**).","prio":"P2","sec":"s8"},{"id":"fc-d168-f82640","poly":"dermato","fiche":"d168","front":"Zona ophtalmique avec manifestation oculaire : quelle prise en charge ?","back":"**Prise en charge ophtalmologique spécialisée** : risque de perte de la fonction de l'œil.","prio":"P1","sec":"s8"},{"id":"fc-d168-b09ce2","poly":"dermato","fiche":"d168","front":"Zona de l'immunodéprimé : quelles formes ?","back":"**Ulcéro-hémorragique**, nécrotique, **bilatéral** ou **multimétamérique**, **zona généralisé**, atteintes viscérales.","prio":"P2","sec":"s8"},{"id":"fc-d168-079c60","poly":"dermato","fiche":"d168","front":"Algies post-zostériennes : nature de la douleur ?","back":"Douleurs **neuropathiques de désafférentation** avec **hypoesthésie**, différentes des douleurs initiales.","prio":"P2","sec":"s8"},{"id":"fc-d168-f21ddf","poly":"dermato","fiche":"d168","front":"Algies post-zostériennes : fréquence selon l'âge ?","back":"**50 %** des cas à 50 ans, **70 %** au-delà de 70 ans.","prio":"P1","sec":"s8"},{"id":"fc-d168-8f1c7a","poly":"dermato","fiche":"d168","front":"Gingivostomatite : comment la distinguer d'une aphtose ?","back":"L'aphtose n'a **ni signes généraux, ni fièvre, ni adénopathies**.","prio":"P2","sec":"s9"},{"id":"fc-d168-2f0f31","poly":"dermato","fiche":"d168","front":"Érosions buccales aiguës + autres muqueuses + signes cutanés : quels diagnostics ?","back":"**Érythème polymorphe**, **syndrome de Stevens-Johnson**.","prio":"P2","sec":"s9"},{"id":"fc-d168-2fa252","poly":"dermato","fiche":"d168","front":"Herpangine : quel virus ?","back":"Le virus **coxsackie** (stomatite virale non herpétique).","prio":"P2","sec":"s9"},{"id":"fc-d168-dfc14d","poly":"dermato","fiche":"d168","front":"Vulvite érosive caustique ou traumatique : que savoir évoquer ?","back":"Une **maltraitance**.","prio":"P1","sec":"s9"},{"id":"fc-d168-39cb7c","poly":"dermato","fiche":"d168","front":"Panaris herpétique : quel diagnostic différentiel ?","back":"Le **panaris staphylococcique**.","prio":"P3","sec":"s9"},{"id":"fc-d168-3d05d1","poly":"dermato","fiche":"d168","front":"Zona : quels diagnostics différentiels ?","back":"Prurigo sur piqûres, **érysipèle** de la face, **impétigo**, **infection à HSV** (zona peu étendu), **eczéma**.","prio":"P2","sec":"s9"},{"id":"fc-d168-a4d1e6","poly":"dermato","fiche":"d168","front":"Aciclovir : quel mécanisme d'action ?","back":"Phosphorylé en **aciclovir triphosphate** dans les cellules infectées → inhibe l'**ADN polymérase virale** (virostatique).","prio":"P2","sec":"s10"},{"id":"fc-d168-6a2fea","poly":"dermato","fiche":"d168","front":"Valaciclovir : quel rapport avec l'aciclovir ?","back":"**Prodrogue** de l'aciclovir, **meilleure biodisponibilité**.","prio":"P2","sec":"s10"},{"id":"fc-d168-d18fa5","poly":"dermato","fiche":"d168","front":"HSV résistant à l'aciclovir : quel traitement ?","back":"**Foscarnet IV** (souches rares, chez l'immunodéprimé).","prio":"P2","sec":"s10"},{"id":"fc-d168-cf8579","poly":"dermato","fiche":"d168","front":"Herpès : les traitements locaux sont-ils efficaces ?","back":"**Non** : aucun traitement local n'a fait la preuve de son efficacité.","prio":"P1","sec":"s10"},{"id":"fc-d168-2ad373","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quel antiviral et quelle durée ?","back":"**Aciclovir** : **PO** si déglutition possible ; **IV** si **troubles de la déglutition** ou **enfant ≥ 3 mois** ; **5 à 10 jours**.","prio":"P1","sec":"s10"},{"id":"fc-d168-ac59d0","poly":"dermato","fiche":"d168","front":"Gingivostomatite herpétique : quelles mesures associées ?","back":"**Support nutritionnel** et **antalgiques** selon la sévérité.","prio":"P2","sec":"s10"},{"id":"fc-d168-154551","poly":"dermato","fiche":"d168","front":"Herpès labial récurrent : faut-il un antiviral pour la poussée ?","back":"**Non** : aucune indication à un antiviral pour une récurrence orofaciale.","prio":"P1","sec":"s10"},{"id":"fc-d168-5562d5","poly":"dermato","fiche":"d168","front":"Herpès labial récidivant : quelle prévention non médicamenteuse ?","back":"Supprimer les facteurs déclenchants, en particulier par la **photoprotection**.","prio":"P2","sec":"s10"},{"id":"fc-d168-f5617a","poly":"dermato","fiche":"d168","front":"Herpès orofacial : quand un traitement préventif ?","back":"Poussées **> 6 par an**, douloureuses, invalidantes et/ou **compliquées** (érythème polymorphe).","prio":"P1","sec":"s10"},{"id":"fc-d168-df261d","poly":"dermato","fiche":"d168","front":"Herpès orofacial récidivant : quel traitement préventif et quelle durée ?","back":"**Aciclovir PO** ou **valaciclovir PO** pendant **6 à 12 mois**, puis réévaluation.","prio":"P1","sec":"s10"},{"id":"fc-d168-e957f2","poly":"dermato","fiche":"d168","front":"Primo-infection génitale herpétique : quel traitement ?","back":"**Aciclovir PO** ou **valaciclovir PO** pendant **5 jours**.","prio":"P1","sec":"s11"},{"id":"fc-d168-735b14","poly":"dermato","fiche":"d168","front":"Primo-infection génitale sévère : quel traitement ?","back":"**Aciclovir IV** pendant **10 jours** (+ sondage si rétention, antalgiques).","prio":"P1","sec":"s11"},{"id":"fc-d168-a67a21","poly":"dermato","fiche":"d168","front":"Récurrence d'herpès génital : quand et comment traiter ?","back":"Non systématique : si **gêne** ou **risque de contagion** ; aciclovir ou valaciclovir **5 jours**, le **plus tôt possible**.","prio":"P1","sec":"s11"},{"id":"fc-d168-4f6223","poly":"dermato","fiche":"d168","front":"Récurrences génitales : comment permettre un traitement précoce ?","back":"Laisser une **ordonnance d'antiviral à disposition** du patient.","prio":"P2","sec":"s11"},{"id":"fc-d168-7e8189","poly":"dermato","fiche":"d168","front":"Herpès génital : quel traitement préventif ?","back":"Si **> 6 récurrences/an** et/ou compliquées : aciclovir ou valaciclovir **PO** **6 à 12 mois**, puis réévaluation.","prio":"P2","sec":"s11"},{"id":"fc-d168-26aa11","poly":"dermato","fiche":"d168","front":"Herpès génital : quel bilan associé ne pas oublier ?","back":"**Dépister les autres IST** ; prévention et dépistage des **partenaires**.","prio":"P1","sec":"s11"},{"id":"fc-d168-fc2ee1","poly":"dermato","fiche":"d168","front":"Herpès génital : quelles mesures d'accompagnement ?","back":"**Information**, éducation, éviction des facteurs déclenchants, **soutien psychologique**.","prio":"P3","sec":"s11"},{"id":"fc-d168-7c4f9c","poly":"dermato","fiche":"d168","front":"Primo-infection génitale à moins d'1 mois du terme : quel traitement ?","back":"**Aciclovir PO** ou **valaciclovir PO** **jusqu'à l'accouchement**.","prio":"P2","sec":"s12"},{"id":"fc-d168-9324a4","poly":"dermato","fiche":"d168","front":"Primo-infection génitale à plus d'1 mois du terme : quel traitement ?","back":"**Aciclovir PO** ou **valaciclovir PO** pendant **10 jours**.","prio":"P2","sec":"s12"},{"id":"fc-d168-3d600c","poly":"dermato","fiche":"d168","front":"Primo-infection génitale pendant la grossesse : quand la césarienne est-elle systématique ?","back":"Si **lésions pendant le travail**.","prio":"P1","sec":"s12"},{"id":"fc-d168-5a6b69","poly":"dermato","fiche":"d168","front":"Primo-infection génitale sans lésion au travail : quelle voie d'accouchement ?","back":"**Voie basse** si primo-infection > 1 mois ; si < 1 mois et **traitée** : **pas d'argument formel** pour imposer la césarienne.","prio":"P2","sec":"s12"},{"id":"fc-d168-17338f","poly":"dermato","fiche":"d168","front":"Récurrence génitale en fin de grossesse : quelle voie d'accouchement ?","back":"**Césarienne** si lésions au travail ; **voie basse** si récurrence > 7 jours ; sinon discuter, examens virologiques (positifs → césarienne).","prio":"P2","sec":"s12"},{"id":"fc-d168-2bbc61","poly":"dermato","fiche":"d168","front":"Herpès et accouchement : quand la césarienne n'apporte-t-elle plus rien ?","back":"**Poche des eaux rompue depuis > 6 heures** ; on dépiste alors le virus chez le nouveau-né.","prio":"P1","sec":"s12"},{"id":"fc-d168-6557b9","poly":"dermato","fiche":"d168","front":"Récurrence herpétique pendant la grossesse : quel traitement ?","back":"Curatif **identique** à hors grossesse ; préventif discuté **au cas par cas**.","prio":"P3","sec":"s12"},{"id":"fc-d168-0003d5","poly":"dermato","fiche":"d168","front":"Herpès néonatal : quel traitement selon la forme ?","back":"**Aciclovir IV** : **14 jours** (forme localisée) ; **21 jours** (neurologique ou disséminée).","prio":"P1","sec":"s12"},{"id":"fc-d168-4ec147","poly":"dermato","fiche":"d168","front":"Herpès : forme grave, quelle voie d'administration de l'antiviral ?","back":"Voie **IV**.","prio":"P1","sec":"s13"},{"id":"fc-d168-c12225","poly":"dermato","fiche":"d168","front":"Méningo-encéphalite herpétique : quel traitement ?","back":"**Aciclovir IV 10 jours** + prise en charge neurologique.","prio":"P1","sec":"s13"},{"id":"fc-d168-1ecd18","poly":"dermato","fiche":"d168","front":"Herpès oculaire : quelle prise en charge ?","back":"**Avis ophtalmologique** indispensable (risque d'ulcération cornéenne, cécité) ; renvoi à l'item 83.","prio":"P1","sec":"s13"},{"id":"fc-d168-3a8bbe","poly":"dermato","fiche":"d168","front":"Varicelle de l'enfant : faut-il évincer de la collectivité ?","back":"**Non**, l'éviction n'est **pas obligatoire**.","prio":"P2","sec":"s14"},{"id":"fc-d168-f9bf72","poly":"dermato","fiche":"d168","front":"Varicelle : quels soins cutanés ?","back":"**Douche tiède** quotidienne, badigeons de **chlorhexidine aqueuse**, **ongles courts** et propres, **pas de talc**.","prio":"P1","sec":"s14"},{"id":"fc-d168-bd04c2","poly":"dermato","fiche":"d168","front":"Varicelle de l'enfant : quel antipyrétique ?","back":"Le **paracétamol** (ni aspirine, ni AINS).","prio":"P1","sec":"s14"},{"id":"fc-d168-947a04","poly":"dermato","fiche":"d168","front":"Varicelle : pourquoi éviter les AINS ?","back":"Risque de **fasciite nécrosante**.","prio":"P1","sec":"s14"},{"id":"fc-d168-33c3af","poly":"dermato","fiche":"d168","front":"Varicelle : traitement du prurit ?","back":"**Anti-H1 sédatif** (aide surtout à dormir, effet **modéré** sur le prurit).","prio":"P2","sec":"s14"},{"id":"fc-d168-040b1d","poly":"dermato","fiche":"d168","front":"Varicelle impétiginisée : quels antibiotiques per os ?","back":"Actifs sur staphylocoque et streptocoque : **macrolide**, **synergistine** ou **pénicilline M**.","prio":"P2","sec":"s14"},{"id":"fc-d168-c278dc","poly":"dermato","fiche":"d168","front":"Varicelle grave ou à risque : quel traitement ?","back":"**Aciclovir IV**.","prio":"P1","sec":"s15"},{"id":"fc-d168-e532b4","poly":"dermato","fiche":"d168","front":"Varicelle : quelles indications de l'aciclovir IV ?","back":"Femme enceinte (varicelle **8-10 j avant l'accouchement**), **nouveau-né**, forme grave **< 1 an**, complication **viscérale**, **immunodépression**.","prio":"P1","sec":"s15"},{"id":"fc-d168-89de58","poly":"dermato","fiche":"d168","front":"Mère avec varicelle de J-5 à J+2 de l'accouchement : que faire chez le nouveau-né ?","back":"**Aciclovir IV** **avant même toute éruption**.","prio":"P1","sec":"s15"},{"id":"fc-d168-92ad22","poly":"dermato","fiche":"d168","front":"Varicelle de l'immunodéprimé : le traitement antiviral est-il systématique ?","back":"**Oui**, systématique.","prio":"P2","sec":"s15"},{"id":"fc-d168-bcb6c9","poly":"dermato","fiche":"d168","front":"Antiviral et fœtopathie varicelleuse : est-il préventif ?","back":"**Efficacité non prouvée** (virémie précoce, traitement trop tardif).","prio":"P2","sec":"s15"},{"id":"fc-d168-6501f1","poly":"dermato","fiche":"d168","front":"Zona de l'immunocompétent : quand prescrire un antiviral ?","back":"**Zona ophtalmique** quel que soit l'âge ; zona non ophtalmique **à partir de 50 ans** (« plus de 50 ans » selon les pages).","prio":"P1","sec":"s16"},{"id":"fc-d168-7726c2","poly":"dermato","fiche":"d168","front":"Zona de l'immunocompétent : quel antiviral, quelle durée, quel délai ?","back":"**Valaciclovir PO 7 jours**, débuté dans les **72 heures** suivant l'éruption.","prio":"P1","sec":"s16"},{"id":"fc-d168-9b58fc","poly":"dermato","fiche":"d168","front":"Zona non ophtalmique après 50 ans : but de l'antiviral ?","back":"Prévenir les **algies post-zostériennes**.","prio":"P2","sec":"s16"},{"id":"fc-d168-0a40bd","poly":"dermato","fiche":"d168","front":"Zona : traitement de la douleur aiguë ?","back":"Antalgiques de **palier II à III** ; **pas de corticothérapie générale**.","prio":"P1","sec":"s16"},{"id":"fc-d168-89a392","poly":"dermato","fiche":"d168","front":"Zona : soins locaux et éviction ?","back":"Soins locaux **comme la varicelle** (chlorhexidine aqueuse, pas de talc) ; **pas d'éviction** de collectivité.","prio":"P3","sec":"s16"},{"id":"fc-d168-9d11b4","poly":"dermato","fiche":"d168","front":"Zona de l'immunodéprimé : quel traitement ?","back":"**Aciclovir IV**, au minimum **7 à 10 jours**.","prio":"P1","sec":"s16"},{"id":"fc-d168-dcdca9","poly":"dermato","fiche":"d168","front":"Zona de l'immunodéprimé : faut-il arrêter l'immunosuppresseur ?","back":"**Pas d'arrêt systématique** (corticothérapie comprise).","prio":"P2","sec":"s16"},{"id":"fc-d168-8e64fe","poly":"dermato","fiche":"d168","front":"Zona ophtalmique : quel traitement local après avis spécialisé ?","back":"**Pommade ophtalmique à l'aciclovir**.","prio":"P2","sec":"s17"},{"id":"fc-d168-be3276","poly":"dermato","fiche":"d168","front":"Zona ophtalmique : place des corticoïdes locaux ?","back":"**Classiquement contre-indiqués** ; réservés aux kératites immunologiques et uvéites antérieures, sur avis ophtalmologique.","prio":"P1","sec":"s17"},{"id":"fc-d168-278dfc","poly":"dermato","fiche":"d168","front":"Algies post-zostériennes : quels antalgiques systémiques ?","back":"À visée **neuropathique** : **amitriptyline** ou **gabapentine** (AMM) ; carbamazépine ou prégabaline (hors AMM).","prio":"P1","sec":"s17"},{"id":"fc-d168-5a4099","poly":"dermato","fiche":"d168","front":"Algies post-zostériennes : quels traitements locaux ?","back":"**Emplâtre de lidocaïne** (**12 h/jour** au maximum) ; **capsaïcine** en préparation magistrale.","prio":"P2","sec":"s17"},{"id":"fc-d168-74907f","poly":"dermato","fiche":"d168","front":"Vaccin varicelle : type et schéma ?","back":"Vaccin **vivant atténué**, **2 doses** espacées d'au moins **1 mois** (idéalement 3 mois).","prio":"P2","sec":"s18"},{"id":"fc-d168-2a4626","poly":"dermato","fiche":"d168","front":"Vaccination varicelle : pourquoi n'est-elle pas généralisée ?","back":"Couverture insuffisante → risque de **décaler la maladie vers l'adulte**, plus grave.","prio":"P3","sec":"s18"},{"id":"fc-d168-48f74f","poly":"dermato","fiche":"d168","front":"Vaccin varicelle post-exposition : chez qui et dans quel délai ?","back":"Adulte **> 18 ans** immunocompétent sans antécédent (ou douteux), dans les **3 jours** après le contact.","prio":"P3","sec":"s18"},{"id":"fc-d168-c972f5","poly":"dermato","fiche":"d168","front":"Vaccin varicelle : quelles cibles parmi adolescents et femmes ?","back":"**12-18 ans** et femmes en âge de procréer sans antécédent ; femme : test de grossesse négatif + **contraception 3 mois** après chaque dose.","prio":"P3","sec":"s18"},{"id":"fc-d168-7a673b","poly":"dermato","fiche":"d168","front":"Vaccin varicelle : quelles autres populations cibles ?","back":"**Professionnels de santé** et de la petite enfance séronégatifs, **entourage d'immunodéprimés**, enfant candidat à une **greffe d'organe**.","prio":"P3","sec":"s18"},{"id":"fc-d168-5a5540","poly":"dermato","fiche":"d168","front":"Vaccin varicelle : contre-indications ?","back":"**Grossesse** et **déficit immunitaire important**.","prio":"P2","sec":"s18"},{"id":"fc-d168-cd9031","poly":"dermato","fiche":"d168","front":"Vaccin zona : schéma, efficacité et âge recommandé ?","back":"Vivant atténué, **1 dose**, efficacité **70 %** ; de **65 à 74 ans** révolus, même après un ou plusieurs zonas.","prio":"P2","sec":"s18"},{"id":"fc-d168-748235","poly":"dermato","fiche":"d168","front":"Vaccin zona : quelle contre-indication ?","back":"L'**immunodépression** (vaccin vivant atténué).","prio":"P2","sec":"s18"},{"id":"fc-d169-73dfca","poly":"dermato","fiche":"d169","front":"VIH : quels sont les modes de transmission ?","back":"**Sexuelle** ou par **exposition au sang** (materno-fœtale, toxicomanie IV, exposition professionnelle…).","prio":"P1","sec":"s1"},{"id":"fc-d169-a9dc25","poly":"dermato","fiche":"d169","front":"VIH : de quels deux facteurs dépend le risque de transmission ?","back":"**Charge virale** du contaminant ; **effractions cutanées et/ou muqueuses** du contaminé (ex. **IST**).","prio":"P1","sec":"s1"},{"id":"fc-d169-a893ef","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : durée moyenne d'incubation ?","back":"**2 à 3 semaines**.","prio":"P1","sec":"s1"},{"id":"fc-d169-4c0e03","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quelle proportion est symptomatique ?","back":"**Plus de 50 %** des cas (environ **50 à 80 %** selon les points clés).","prio":"P1","sec":"s1"},{"id":"fc-d169-20d9c6","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quels sont les caractères habituels des signes cliniques ?","back":"Souvent **discrets** et **peu spécifiques** (risque de les confondre avec une virose banale ou un accident médicamenteux).","prio":"P1","sec":"s1"},{"id":"fc-d169-5d9d43","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : pourquoi l'évoquer systématiquement ?","back":"**Limiter la transmission** et surtout permettre une **prise en charge précoce**, qui favorise la **restauration immunitaire**.","prio":"P1","sec":"s1"},{"id":"fc-d169-a0c0b6","poly":"dermato","fiche":"d169","front":"Contamination VIH par voie muqueuse : quelles cellules sont infectées en premier ?","back":"Les **cellules de Langerhans**, qui transmettent le virus aux **lymphocytes CD4**.","prio":"P3","sec":"s1"},{"id":"fc-d169-909b56","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : délai de dissémination (virémie) après la contamination ?","back":"**4 à 11 jours** ; détectée par **ARN viral en PCR**.","prio":"P2","sec":"s1"},{"id":"fc-d169-e2e1e8","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quel paradoxe de la phase de virémie ?","back":"Virémie **très élevée**, patient **contaminant**, mais **sérologie encore négative**.","prio":"P2","sec":"s1"},{"id":"fc-d169-728bac","poly":"dermato","fiche":"d169","front":"Western blot VIH : contre quoi sont dirigés les premiers anticorps ?","back":"Protéines du **core (p18-p24)**, puis **glycoprotéines d'enveloppe**.","prio":"P3","sec":"s1"},{"id":"fc-d169-b9b79b","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quand la sérologie se positive-t-elle ?","back":"**3 à 6 semaines** après la contamination, le plus souvent **1 à 2 semaines** après le syndrome clinique.","prio":"P2","sec":"s1"},{"id":"fc-d169-6e00db","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quelles anomalies lymphocytaires en phase aiguë ?","back":"**Lymphopénie T CD4**, hausse des **T CD8** cytotoxiques, **baisse du rapport CD4/CD8**.","prio":"P3","sec":"s1"},{"id":"fc-d169-a6d8fc","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quand l'équilibre immunovirologique est-il atteint ?","back":"Environ **6 mois** après la séroconversion.","prio":"P3","sec":"s1"},{"id":"fc-d169-db6b00","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : fréquence du tableau pseudo-grippal ?","back":"**90 %**.","prio":"P1","sec":"s2"},{"id":"fc-d169-89e4a4","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : niveau de fièvre ?","back":"**38 à 39,5 °C**.","prio":"P2","sec":"s2"},{"id":"fc-d169-87a1ca","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : citer les signes du tableau pseudo-grippal ?","back":"Fièvre, sueurs, **asthénie**, malaise, **arthralgies**, **myalgies**, **céphalées**, douleurs pharyngées, douleurs **rétro-orbitaires**.","prio":"P2","sec":"s2"},{"id":"fc-d169-5ce2b5","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : quelle lésion explique les douleurs pharyngées ?","back":"Un **énanthème du palais dur**.","prio":"P3","sec":"s2"},{"id":"fc-d169-e2104b","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : fréquence et caractères de la polyadénopathie ?","back":"**75 %** ; **ferme**, **indolore**, **symétrique**.","prio":"P1","sec":"s2"},{"id":"fc-d169-58a86a","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : fréquence des signes neurologiques ?","back":"**20 %**.","prio":"P2","sec":"s2"},{"id":"fc-d169-2434f0","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : quels signes neurologiques ?","back":"**Syndrome méningé**, **troubles du comportement** ; plus rarement encéphalite, convulsions, polyradiculonévrite, **paralysie faciale périphérique**.","prio":"P2","sec":"s2"},{"id":"fc-d169-fd870c","poly":"dermato","fiche":"d169","front":"Syndrome rétroviral aigu : fréquence des signes digestifs et de la toux ?","back":"**10 %** (diarrhée ; toux).","prio":"P2","sec":"s2"},{"id":"fc-d169-eed743","poly":"dermato","fiche":"d169","front":"Adulte avec éruption généralisée fébrile : quel diagnostic évoquer impérativement ?","back":"Une **primo-infection VIH**.","prio":"P1","sec":"s3"},{"id":"fc-d169-1c27d8","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : fréquence de l'exanthème ?","back":"**60 à 70 %** des cas.","prio":"P1","sec":"s3"},{"id":"fc-d169-b62579","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : aspect habituel ?","back":"**Morbilliforme** : maculo-papules de quelques mm à 1 cm, rondes ou ovales, bien limitées, **non squameuses**.","prio":"P1","sec":"s3"},{"id":"fc-d169-b6dc2c","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : faut-il un rash morbilliforme typique pour l'évoquer ?","back":"**Non** : **tout type de rash** (ex. **roséoliforme**) doit faire penser au VIH.","prio":"P1","sec":"s3"},{"id":"fc-d169-a37dd2","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : quand débute-t-il ?","back":"Entre le **1er et le 5e jour** des signes généraux.","prio":"P2","sec":"s3"},{"id":"fc-d169-9c3bd4","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : topographie ?","back":"Surtout **tronc**, **racine des membres**, **cou**, parfois visage ; atteinte possible des **paumes et plantes**.","prio":"P1","sec":"s3"},{"id":"fc-d169-bd0827","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : prurit ?","back":"**Rare** et **modéré**.","prio":"P2","sec":"s3"},{"id":"fc-d169-909839","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : durée ?","back":"**5 à 10 jours**.","prio":"P2","sec":"s3"},{"id":"fc-d169-59591f","poly":"dermato","fiche":"d169","front":"Exanthème de primo-infection VIH : formes rares ?","back":"**Urticarienne** ; **vésiculo-pustuleuse**.","prio":"P3","sec":"s3"},{"id":"fc-d169-a23dc1","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quelle atteinte de la muqueuse buccale ?","back":"**Énanthème** et/ou **érosions de 5 à 10 mm**, rendant la **déglutition douloureuse**.","prio":"P1","sec":"s3"},{"id":"fc-d169-53692d","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : en dehors de la bouche, où peut-on trouver des érosions ou ulcérations ?","back":"**Œsophage** · **organes génitaux** · région **anale**.","prio":"P2","sec":"s3"},{"id":"fc-d169-f6648c","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : condition préalable à la demande des tests ?","back":"L'**accord du patient**.","prio":"P1","sec":"s4"},{"id":"fc-d169-dc079a","poly":"dermato","fiche":"d169","front":"Suspicion de primo-infection VIH : quels examens demander ?","back":"**Sérologie VIH combinée** (ELISA Ag **p24** + **anticorps**) et **ARN VIH plasmatique**.","prio":"P1","sec":"s4"},{"id":"fc-d169-f53eef","poly":"dermato","fiche":"d169","front":"Primo-infection VIH au stade aigu : sur quoi repose le diagnostic ?","back":"**ARN VIH** plasmatique et **antigénémie p24** (sérologie en général encore **négative**).","prio":"P1","sec":"s4"},{"id":"fc-d169-e26465","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : sérologie négative au stade aigu, que faire ?","back":"La **refaire 3 à 4 semaines** plus tard.","prio":"P1","sec":"s4"},{"id":"fc-d169-9d7b5a","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : fréquence du syndrome mononucléosique ?","back":"**50 %** (lymphocytes **CD8**).","prio":"P2","sec":"s4"},{"id":"fc-d169-e1c983","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : fréquence de la lymphopénie CD4 ?","back":"**40 %**.","prio":"P2","sec":"s4"},{"id":"fc-d169-b1a1fc","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : fréquence de la cytolyse hépatique ?","back":"**30 %**.","prio":"P2","sec":"s4"},{"id":"fc-d169-1496b6","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : fréquence de la thrombopénie ?","back":"**25 %**.","prio":"P2","sec":"s4"},{"id":"fc-d169-f24b2f","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : une sérologie négative élimine-t-elle le diagnostic ?","back":"**Non** : au stade aigu, virémie très élevée et patient contaminant alors que la sérologie peut rester négative.","prio":"P2","sec":"s4"},{"id":"fc-d169-c49e83","poly":"dermato","fiche":"d169","front":"Éruption fébrile évoquant une primo-infection VIH : citer les diagnostics différentiels ?","back":"**Syphilis secondaire** · autre **exanthème viral** · **toxoplasmose** · **pityriasis rosé de Gibert** · **toxidermie**.","prio":"P2","sec":"s5"},{"id":"fc-d169-5f6bec","poly":"dermato","fiche":"d169","front":"Pityriasis rosé de Gibert vs primo-infection VIH : quel élément distinctif ?","back":"**Pas de signes généraux** dans le pityriasis rosé.","prio":"P2","sec":"s5"},{"id":"fc-d169-ec987c","poly":"dermato","fiche":"d169","front":"Éruption fébrile suspecte : quel élément rechercher de principe pour une toxidermie ?","back":"Une **prise de médicament**.","prio":"P2","sec":"s5"},{"id":"fc-d169-e5b831","poly":"dermato","fiche":"d169","front":"Syphilis secondaire en diagnostic différentiel de la primo-infection VIH : quel contexte la fait discuter ?","back":"Une atteinte **cutanée** associée à un **syndrome systémique**.","prio":"P3","sec":"s5"},{"id":"fc-d169-bf65af","poly":"dermato","fiche":"d169","front":"Éruption fébrile suspecte de primo-infection VIH : traitement spécifique avant confirmation ?","back":"**Aucune ordonnance** à ce stade dans le Collège ; examens demandés avec l'accord du patient.","prio":"P2","sec":"s6"},{"id":"fc-d169-fe894e","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : piège diagnostique principal ?","back":"Conclure à une **virose banale** ou une **toxidermie** sans avoir évoqué le VIH.","prio":"P1","sec":"s6"},{"id":"fc-d169-0c633d","poly":"dermato","fiche":"d169","front":"Primo-infection VIH confirmée : quel traitement et quand ?","back":"**Antirétroviraux précoces**, dès la primo-infection.","prio":"P1","sec":"s7"},{"id":"fc-d169-1d60eb","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : l'indication des antirétroviraux dépend-elle des symptômes, des CD4 ou de la charge virale ?","back":"**Non** : traitement indiqué **indépendamment** de ces critères.","prio":"P1","sec":"s7"},{"id":"fc-d169-c87bda","poly":"dermato","fiche":"d169","front":"Antirétroviraux dès la primo-infection : quels objectifs ?","back":"Abaisser la **charge virale résiduelle** · éviter l'évolution vers le **Sida** · meilleure **restauration immunitaire**.","prio":"P1","sec":"s7"},{"id":"fc-d169-49524b","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quel test associer au début des antirétroviraux ?","back":"**Test génotypique de résistance** ; adapter le traitement à son résultat si besoin.","prio":"P1","sec":"s7"},{"id":"fc-d169-39a00e","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quelle information donner au patient ?","back":"Risque de **transmission** à l'entourage et **mesures de prévention** indispensables.","prio":"P1","sec":"s7"},{"id":"fc-d169-16a635","poly":"dermato","fiche":"d169","front":"Primo-infection VIH avec lymphopénie marquée : quel risque ?","back":"**Infections opportunistes** : **candidose œsophagienne**, **cryptosporidiose digestive**…","prio":"P2","sec":"s7"},{"id":"fc-d169-fab2e6","poly":"dermato","fiche":"d169","front":"Exposition sexuelle au VIH : délai maximal pour consulter ?","back":"**48 heures** au plus tard.","prio":"P1","sec":"s8"},{"id":"fc-d169-94f771","poly":"dermato","fiche":"d169","front":"Exposition sexuelle à risque : quelles sérologies en urgence ?","back":"**VIH**, **VHB** et **syphilis**.","prio":"P1","sec":"s8"},{"id":"fc-d169-953498","poly":"dermato","fiche":"d169","front":"Exposition sexuelle : quel rapport expose au risque maximal de transmission du VIH ?","back":"**Rapport anal réceptif** avec un partenaire **séropositif**.","prio":"P1","sec":"s8"},{"id":"fc-d169-ce0481","poly":"dermato","fiche":"d169","front":"Exposition sexuelle : quel type de rapport a un risque bien plus faible ?","back":"**Rapport orogénital réceptif**.","prio":"P2","sec":"s8"},{"id":"fc-d169-310cf1","poly":"dermato","fiche":"d169","front":"Prophylaxie post-exposition VIH : quand la proposer ?","back":"**Selon le risque** de transmission, après **entretien** et **examen clinique** (pas automatique).","prio":"P1","sec":"s8"},{"id":"fc-d169-f4765c","poly":"dermato","fiche":"d169","front":"Prophylaxie post-exposition VIH : durée ?","back":"**4 semaines**.","prio":"P1","sec":"s8"},{"id":"fc-d169-6b07c2","poly":"dermato","fiche":"d169","front":"Prophylaxie post-exposition VIH : quel suivi ?","back":"Consultations de **contrôle sérologique**, incluant le dépistage des **autres IST**.","prio":"P2","sec":"s8"},{"id":"fc-d169-834ad4","poly":"dermato","fiche":"d169","front":"PrEP VIH : quelle association et quelle posologie habituelle ?","back":"**Ténofovir-emtricitabine**, en général **1 comprimé par jour**.","prio":"P1","sec":"s9"},{"id":"fc-d169-8ae4ba","poly":"dermato","fiche":"d169","front":"PrEP VIH : qui peut l'initier depuis juin 2021 ?","back":"**Tous les médecins** (avant : médecins hospitaliers et de CeGIDD).","prio":"P1","sec":"s9"},{"id":"fc-d169-ccb2e2","poly":"dermato","fiche":"d169","front":"Citer les 4 dermatoses de rang A qui doivent faire proposer une sérologie VIH ?","back":"**IST** · **zona de l'adulte jeune** · **candidoses/dermatophytoses** florides et/ou multirécidivantes · **maladie de Kaposi**.","prio":"P1","sec":"s10"},{"id":"fc-d169-39e005","poly":"dermato","fiche":"d169","front":"Dermatite séborrhéique : quand proposer une sérologie VIH ?","back":"Si **floride** et/ou **résistante** au traitement.","prio":"P2","sec":"s10"},{"id":"fc-d169-7d3483","poly":"dermato","fiche":"d169","front":"Psoriasis : quand proposer une sérologie VIH ?","back":"Psoriasis **de novo** sans antécédent familial, **floride** et/ou **résistant** au traitement.","prio":"P2","sec":"s10"},{"id":"fc-d169-7eb5f3","poly":"dermato","fiche":"d169","front":"Maladie de Kaposi : quel aspect sur la figure du Collège ?","back":"**Papules violines** du pied et **lymphœdème**.","prio":"P3","sec":"s10"},{"id":"fc-d169-511f39","poly":"dermato","fiche":"d169","front":"Dermatose évocatrice (IST, zona jeune, Kaposi…) : quel piège ?","back":"Traiter la dermatose **sans proposer de sérologie VIH**.","prio":"P1","sec":"s10"},{"id":"fc-d169-7606a3","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : évolution spontanée du syndrome clinique ?","back":"**Guérison spontanée** en **1 à 3 semaines**.","prio":"P2","sec":"s11"},{"id":"fc-d169-39c202","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : quelle valeur pronostique de sa sévérité ?","back":"**Marqueur pronostique** d'évolution vers le **Sida**.","prio":"P2","sec":"s11"},{"id":"fc-d169-33476f","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : comment évolue la charge virale après la réplication active ?","back":"Baisse jusqu'à un **plateau** ; un traitement précoce diminue la charge virale **résiduelle**.","prio":"P3","sec":"s11"},{"id":"fc-d169-facdd7","poly":"dermato","fiche":"d169","front":"Primo-infection VIH : la guérison spontanée des symptômes dispense-t-elle des antirétroviraux ?","back":"**Non** : le traitement précoce reste indiqué, il ne dépend pas des symptômes.","prio":"P2","sec":"s11"},{"id":"fc-d171-af5c31","poly":"dermato","fiche":"d171","front":"Gale humaine : agent responsable ?","back":"Un acarien : ***Sarcoptes scabiei*** variété ***hominis***.","prio":"P1","sec":"s1"},{"id":"fc-d171-d1368d","poly":"dermato","fiche":"d171","front":"Gale : que traduisent les signes cliniques ?","back":"L'**infestation** par le parasite + la **réaction de l'organisme** contre les sarcoptes et leurs déjections.","prio":"P2","sec":"s1"},{"id":"fc-d171-1cd7fa","poly":"dermato","fiche":"d171","front":"Sillon scabieux : à quoi correspond-il ?","back":"Au trajet de l'acarien **femelle** dans la **couche cornée** de l'épiderme.","prio":"P1","sec":"s1"},{"id":"fc-d171-c81dc3","poly":"dermato","fiche":"d171","front":"Sarcopte femelle : vitesse de déplacement à la surface de la peau ?","back":"**Plusieurs centimètres par heure**.","prio":"P3","sec":"s1"},{"id":"fc-d171-7ad998","poly":"dermato","fiche":"d171","front":"Sarcopte : influence de la température ?","back":"Mobile entre **25 et 30 °C** ; immobile **< 20 °C** ; tué très vite à **55 °C**.","prio":"P3","sec":"s1"},{"id":"fc-d171-9c8f96","poly":"dermato","fiche":"d171","front":"Sarcopte hors de l'hôte : durée de survie ?","back":"Meurt en **12 à 24 heures**.","prio":"P2","sec":"s1"},{"id":"fc-d171-c2cd61","poly":"dermato","fiche":"d171","front":"Gale : durée d'incubation ?","back":"Environ **3 semaines** ; plus courte en cas de **réinfestation**.","prio":"P2","sec":"s1"},{"id":"fc-d171-974b1e","poly":"dermato","fiche":"d171","front":"Sarcopte : durée du cycle parasitaire ?","back":"Environ **20 jours**.","prio":"P3","sec":"s1"},{"id":"fc-d171-4af142","poly":"dermato","fiche":"d171","front":"Gale commune : charge parasitaire habituelle ?","back":"**10 à 20 femelles** par individu.","prio":"P3","sec":"s1"},{"id":"fc-d171-27ac61","poly":"dermato","fiche":"d171","front":"Gale : mode de transmission principal ?","back":"**Interhumaine directe**, par contacts **intimes et prolongés** (famille, couple).","prio":"P1","sec":"s2"},{"id":"fc-d171-600597","poly":"dermato","fiche":"d171","front":"Gale : place de la transmission indirecte (vêtements, literie) ?","back":"**Beaucoup plus rare**, sauf dans les formes **profuses et hyperkératosiques**.","prio":"P2","sec":"s2"},{"id":"fc-d171-1b7407","poly":"dermato","fiche":"d171","front":"Gale : terrains favorisant les épidémies ?","back":"**Collectivités médicalisées**, **foyers de personnes âgées**, milieu **défavorisé**, **immunodépression** (spontanée ou iatrogène).","prio":"P2","sec":"s2"},{"id":"fc-d171-5ba6a8","poly":"dermato","fiche":"d171","front":"Gale : quels comportements faut-il rechercher ?","back":"Des **rapports sexuels à risque** (penser aux **autres IST**).","prio":"P2","sec":"s2"},{"id":"fc-d171-7f0e84","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : mode de transmission ?","back":"**Directe** (contact des têtes, enfants scolarisés) ; **plus rarement indirecte** (bonnets, peignes, brosses).","prio":"P2","sec":"s2"},{"id":"fc-d171-08a25b","poly":"dermato","fiche":"d171","front":"Pou de tête : mode d'alimentation et ponte ?","back":"Adulte **hématophage** ; femelle : **10 à 20 œufs/jour** près de l'émergence des cheveux ; éclosion en **1 semaine**.","prio":"P3","sec":"s2"},{"id":"fc-d171-adb657","poly":"dermato","fiche":"d171","front":"Lente : à partir de quelle distance de l'émergence du cheveu est-elle non viable ?","back":"**Plus de 1 cm** (pousse des cheveux).","prio":"P2","sec":"s2"},{"id":"fc-d171-c52ed1","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : transmission et fréquence ?","back":"**Directe** ou **par les vêtements** ; **beaucoup plus rare** que celle du cuir chevelu.","prio":"P2","sec":"s2"},{"id":"fc-d171-27030c","poly":"dermato","fiche":"d171","front":"Pou de corps : où vit-il et où pond-il ?","back":"Circule sur le corps **le temps de se nourrir**, se réfugie dans les **vêtements** et pond sur les **fibres**.","prio":"P2","sec":"s2"},{"id":"fc-d171-bafb66","poly":"dermato","fiche":"d171","front":"Gale commune : caractéristiques du prurit ?","back":"**Diffus**, à **recrudescence nocturne**, **épargnant le visage**, souvent **conjugal ou familial**.","prio":"P1","sec":"s3"},{"id":"fc-d171-ef9d8d","poly":"dermato","fiche":"d171","front":"Gale : pourquoi y penser devant tout prurit ?","back":"Certaines formes sont **pauci-lésionnelles**.","prio":"P1","sec":"s3"},{"id":"fc-d171-baa160","poly":"dermato","fiche":"d171","front":"Gale : nature et intérêt des lésions non spécifiques ?","back":"Lésions de **grattage**, fréquentes, de **topographie évocatrice**.","prio":"P2","sec":"s3"},{"id":"fc-d171-3c5bcc","poly":"dermato","fiche":"d171","front":"Gale : topographie évocatrice aux membres supérieurs ?","back":"**Espaces interdigitaux**, face antérieure des **poignets**, **coudes**, **emmanchures antérieures**.","prio":"P1","sec":"s3"},{"id":"fc-d171-e14243","poly":"dermato","fiche":"d171","front":"Gale : topographie évocatrice au tronc et au bassin ?","back":"**Ombilic**, **fesses**, face interne des **cuisses**.","prio":"P1","sec":"s3"},{"id":"fc-d171-ac6853","poly":"dermato","fiche":"d171","front":"Gale : topographie évocatrice selon le sexe ?","back":"Homme : **organes génitaux externes** ; femme : **mamelon et aréole**.","prio":"P1","sec":"s3"},{"id":"fc-d171-feee60","poly":"dermato","fiche":"d171","front":"Gale : citer les 3 lésions spécifiques ?","back":"**Sillons scabieux** · **vésicules perlées** · **nodules scabieux** (à rechercher systématiquement).","prio":"P1","sec":"s3"},{"id":"fc-d171-944222","poly":"dermato","fiche":"d171","front":"Sillon scabieux : aspect ?","back":"Lésion **sinueuse** de quelques mm contenant les **œufs** ; parfois à une extrémité l'**éminence acarienne** (femelle).","prio":"P1","sec":"s3"},{"id":"fc-d171-f4301f","poly":"dermato","fiche":"d171","front":"Sillon scabieux : siège ?","back":"**Entre les doigts**, face antérieure des **poignets**.","prio":"P1","sec":"s3"},{"id":"fc-d171-3a3947","poly":"dermato","fiche":"d171","front":"Vésicules perlées : aspect et siège ?","back":"Petites élevures **translucides** sur base **érythémateuse** ; surtout **espaces interdigitaux**.","prio":"P1","sec":"s3"},{"id":"fc-d171-3318fc","poly":"dermato","fiche":"d171","front":"Nodules scabieux : aspect et siège ?","back":"Papulo-nodules **rouges ou violacés**, prurigineux ; surtout régions **génitales de l'homme**.","prio":"P1","sec":"s3"},{"id":"fc-d171-bb336b","poly":"dermato","fiche":"d171","front":"Gale : aspect en dermatoscopie ?","back":"Aspect « **en deltaplane** ».","prio":"P2","sec":"s3"},{"id":"fc-d171-05b0da","poly":"dermato","fiche":"d171","front":"Gale du nourrisson : signes distinctifs ?","back":"**Vésiculo-pustules palmaires et plantaires**, **nodules péri-axillaires**, atteinte possible du **visage**.","prio":"P2","sec":"s4"},{"id":"fc-d171-9fbbd4","poly":"dermato","fiche":"d171","front":"Gale profuse : causes ?","back":"**Diagnostic tardif** ; parfois **déficit immunitaire** (VIH) ou **traitement inadapté** (corticothérapie locale ou générale).","prio":"P2","sec":"s4"},{"id":"fc-d171-721a7f","poly":"dermato","fiche":"d171","front":"Gale profuse : terrain et aspect ?","back":"Souvent **sujets âgés, alités**, troubles cognitifs ; éruption **profuse et étendue**, **dos compris**.","prio":"P2","sec":"s4"},{"id":"fc-d171-83cce9","poly":"dermato","fiche":"d171","front":"Gale hyperkératosique : terrain ?","back":"**Immunodéprimés** ou **sujets âgés en collectivité** sous immunosuppresseurs (typiquement **corticothérapie**).","prio":"P2","sec":"s4"},{"id":"fc-d171-e19683","poly":"dermato","fiche":"d171","front":"Gale hyperkératosique : contagiosité et prurit ?","back":"Contagiosité **majeure** (prolifération parasitaire intense) ; prurit **le plus souvent discret, voire absent**.","prio":"P1","sec":"s4"},{"id":"fc-d171-439241","poly":"dermato","fiche":"d171","front":"Gale hyperkératosique : extension ?","back":"**Tout le corps**, visage, cuir chevelu et ongles compris, voire **érythrodermie** avec zones hyperkératosiques.","prio":"P2","sec":"s4"},{"id":"fc-d171-91c29c","poly":"dermato","fiche":"d171","front":"Impétigo de l'adulte : quelle cause rechercher ?","back":"Une **gale** (ectoparasitose).","prio":"P1","sec":"s4"},{"id":"fc-d171-623d53","poly":"dermato","fiche":"d171","front":"Gale surinfectée dans les pays en développement : quelles complications ?","back":"Cause majeure de **glomérulonéphrite post-streptococcique** et de **rhumatisme articulaire aigu**.","prio":"P3","sec":"s4"},{"id":"fc-d171-3b92ca","poly":"dermato","fiche":"d171","front":"Gale : causes possibles d'eczématisation ?","back":"La gale **ou son traitement**.","prio":"P2","sec":"s4"},{"id":"fc-d171-a82b9c","poly":"dermato","fiche":"d171","front":"Nodules post-scabieux : aspect et durée ?","back":"Papulo-nodules **prurigineux**, rouges ou **cuivrés**, ubiquitaires ; **peuvent persister plusieurs semaines** après un traitement efficace.","prio":"P2","sec":"s4"},{"id":"fc-d171-73623e","poly":"dermato","fiche":"d171","front":"Nodules post-scabieux : contiennent-ils des sarcoptes ?","back":"**Non** : origine **immuno-allergique**.","prio":"P2","sec":"s4"},{"id":"fc-d171-6ba250","poly":"dermato","fiche":"d171","front":"Gale : quelles formes sont de diagnostic difficile ?","back":"**Pauci-lésionnelle**, **profuse et hyperkératosique**, gale du **nourrisson**.","prio":"P3","sec":"s4"},{"id":"fc-d171-c38e86","poly":"dermato","fiche":"d171","front":"Gale : sur quoi repose le diagnostic ?","back":"**Avant tout clinique** : anamnèse (prurit nocturne familial ou du partenaire) + éruption de topographie évocatrice.","prio":"P1","sec":"s5"},{"id":"fc-d171-f0b66d","poly":"dermato","fiche":"d171","front":"Gale : existe-t-il un signe biologique spécifique ?","back":"**Non**, aucun.","prio":"P1","sec":"s5"},{"id":"fc-d171-541f11","poly":"dermato","fiche":"d171","front":"Gale avec rapports sexuels à risque : que prescrire ?","back":"Un **bilan d'IST**.","prio":"P1","sec":"s5"},{"id":"fc-d171-a6b3b9","poly":"dermato","fiche":"d171","front":"Pédiculose : quelles formes justifient un bilan d'IST (objectifs de l'item) ?","back":"Pédiculose **de corps** ou **de pubis**.","prio":"P2","sec":"s5"},{"id":"fc-d171-c90084","poly":"dermato","fiche":"d171","front":"Gale : technique de l'examen parasitologique ?","back":"**Gratter un sillon** au **vaccinostyle**, si possible l'éminence acarienne ; microscope : **œufs** ou **femelle adulte**.","prio":"P2","sec":"s5"},{"id":"fc-d171-41a669","poly":"dermato","fiche":"d171","front":"Gale : dans quelles formes l'acarien n'est-il pas difficile à mettre en évidence ?","back":"Mise en évidence **difficile**, sauf dans les formes **profuses et hyperkératosiques**.","prio":"P2","sec":"s5"},{"id":"fc-d171-11cbbd","poly":"dermato","fiche":"d171","front":"Gale : intérêt de la dermatoscopie ?","back":"Peut **remplacer l'examen parasitologique**, peu accessible en ville.","prio":"P2","sec":"s5"},{"id":"fc-d171-3c87a7","poly":"dermato","fiche":"d171","front":"Gale : l'examen parasitologique est-il obligatoire pour le diagnostic ?","back":"**Dans aucun cas**.","prio":"P2","sec":"s5"},{"id":"fc-d171-6e9be1","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : éléments la distinguant d'une gale ?","back":"Prurit surtout **dorsal**, hygiène très défectueuse ; poux faciles à trouver dans les **coutures des vêtements**.","prio":"P2","sec":"s6"},{"id":"fc-d171-336866","poly":"dermato","fiche":"d171","front":"Gale d'origine animale : éléments du diagnostic ?","back":"Lésions excoriées **sans sillon** ; **animaux** d'élevage ou domestiques au contact.","prio":"P2","sec":"s6"},{"id":"fc-d171-92eb32","poly":"dermato","fiche":"d171","front":"Prurit généralisé sans gale : quel autre diagnostic éliminer ?","back":"**Prurit sine materia** : éliminer toutes leurs causes, notamment **métaboliques**.","prio":"P3","sec":"s6"},{"id":"fc-d171-b53d1b","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : agent ?","back":"***Pediculus humanus*** var. ***capitis***.","prio":"P1","sec":"s7"},{"id":"fc-d171-a41ad5","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : agent ?","back":"***Pediculus humanus*** var. ***corporis***.","prio":"P1","sec":"s7"},{"id":"fc-d171-075575","poly":"dermato","fiche":"d171","front":"Phtiriase : agent ?","back":"***Phtirius inguinalis*** (morpion).","prio":"P1","sec":"s7"},{"id":"fc-d171-b825cb","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : terrain ?","back":"Surtout **enfants d'âge scolaire** et sujets en **précarité**.","prio":"P1","sec":"s7"},{"id":"fc-d171-5909d8","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : terrain ?","back":"Surtout sujets en **précarité**.","prio":"P2","sec":"s7"},{"id":"fc-d171-c47476","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : topographie du prurit ?","back":"**Diffus** ou à prédominance **rétro-auriculaire**, pouvant gagner la **nuque**.","prio":"P1","sec":"s7"},{"id":"fc-d171-9eeb2b","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : signes d'examen ?","back":"Lésions de grattage du cuir chevelu et de la nuque, lésions **croûteuses surinfectées**, parfois **adénopathies cervicales**.","prio":"P2","sec":"s7"},{"id":"fc-d171-88a5e3","poly":"dermato","fiche":"d171","front":"Pédiculose du cuir chevelu : critère de certitude ?","back":"**Poux vivants** (visibles à l'œil nu, très mobiles).","prio":"P1","sec":"s7"},{"id":"fc-d171-89803b","poly":"dermato","fiche":"d171","front":"Lentes vivantes : valeur diagnostique et aspect ?","back":"**Orientent** seulement ; œufs **collés aux cheveux**, qui **ne coulissent pas** ; mieux vus en **rétro-auriculaire**.","prio":"P1","sec":"s7"},{"id":"fc-d171-85ec3b","poly":"dermato","fiche":"d171","front":"Impétigo de la nuque ou du cuir chevelu : que rechercher ?","back":"Une **pédiculose**.","prio":"P1","sec":"s7"},{"id":"fc-d171-10c075","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : topographie des lésions de grattage ?","back":"**Disséminées** sur le **tronc** et la **racine des membres**, parfois hémorragiques ou surinfectées.","prio":"P2","sec":"s7"},{"id":"fc-d171-15c3dc","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : critère de certitude ?","back":"**Poux** sur le corps au **déshabillage** ou sur les vêtements (**coutures** surtout).","prio":"P1","sec":"s7"},{"id":"fc-d171-c670b0","poly":"dermato","fiche":"d171","front":"Pédiculose corporelle : complication à rechercher ?","back":"**Impétiginisation** des lésions de grattage.","prio":"P2","sec":"s7"},{"id":"fc-d171-a68c51","poly":"dermato","fiche":"d171","front":"Phtiriase : localisation du prurit et adénopathies ?","back":"Prurit **pubien** ; possibles **adénopathies inguinales**.","prio":"P2","sec":"s7"},{"id":"fc-d171-451a8a","poly":"dermato","fiche":"d171","front":"Phtiriase : aspect des poux adultes et des lentes ?","back":"Poux : **petite tache grise** près de l'orifice des poils ; lentes : petite masse arrondie **collée au poil**.","prio":"P2","sec":"s7"},{"id":"fc-d171-6ab5f5","poly":"dermato","fiche":"d171","front":"Phtiriase : autres zones pileuses possiblement atteintes ?","back":"Poils **péri-anaux**, **axillaires**, **pectoraux** ; les **cils** peuvent être colonisés.","prio":"P2","sec":"s7"},{"id":"fc-d171-39f653","poly":"dermato","fiche":"d171","front":"Phtiriase : pourquoi est-ce une IST ?","back":"Le pou de pubis, peu mobile, reste **accroché aux poils génitaux** et y pond.","prio":"P1","sec":"s7"},{"id":"fc-d171-f1e283","poly":"dermato","fiche":"d171","front":"Ectoparasitoses : laquelle a la transmission indirecte la plus marquée ?","back":"La **pédiculose corporelle** (++).","prio":"P2","sec":"s8"},{"id":"fc-d171-4bf431","poly":"dermato","fiche":"d171","front":"Phtiriase : transmission indirecte (tableau de synthèse) ?","back":"**Non** (−).","prio":"P3","sec":"s8"},{"id":"fc-d171-2bbdac","poly":"dermato","fiche":"d171","front":"Gale du nourrisson : topographie du prurit (tableau de synthèse) ?","back":"**Palmo-plantaire**.","prio":"P2","sec":"s8"},{"id":"fc-d171-b7ec40","poly":"dermato","fiche":"d171","front":"Pédiculoses : voie de traitement ?","back":"**Locale** ; traitement général **exceptionnel** (hors AMM).","prio":"P1","sec":"s8"},{"id":"fc-d171-de07f6","poly":"dermato","fiche":"d171","front":"Gale : voies de traitement ?","back":"**Per os** et/ou **local**.","prio":"P1","sec":"s8"},{"id":"fc-d171-3b1963","poly":"dermato","fiche":"d171","front":"Gale commune : qui traiter ?","back":"Le malade **et toutes les personnes au contact intime** (famille, partenaires), **en même temps**.","prio":"P1","sec":"s9"},{"id":"fc-d171-734220","poly":"dermato","fiche":"d171","front":"Gale : quand discuter l'ivermectine orale plutôt que le traitement local ?","back":"Pour **faciliter l'observance** (nombreuses personnes à traiter) ou si le local sera **difficile à réaliser**.","prio":"P2","sec":"s9"},{"id":"fc-d171-84a0f4","poly":"dermato","fiche":"d171","front":"Ivermectine dans la gale : posologie ?","back":"**200 µg/kg** per os en **prise unique**.","prio":"P1","sec":"s9"},{"id":"fc-d171-089ebd","poly":"dermato","fiche":"d171","front":"Ivermectine dans la gale : faut-il une 2e prise et quand ?","back":"**Oui, systématique**, **7 à 14 jours** plus tard (cycle du parasite ; délai hors AMM).","prio":"P1","sec":"s9"},{"id":"fc-d171-09e644","poly":"dermato","fiche":"d171","front":"Ivermectine : conditions de l'AMM ?","back":"Adulte et enfant de **plus de 2 ans** et de **plus de 15 kg**.","prio":"P1","sec":"s9"},{"id":"fc-d171-374a49","poly":"dermato","fiche":"d171","front":"Scabicide local : mode d'application ?","back":"Douche tiède au savon, puis produit sur **tout le corps**, organes génitaux compris (± cuir chevelu et visage si doute).","prio":"P2","sec":"s9"},{"id":"fc-d171-85ca09","poly":"dermato","fiche":"d171","front":"Scabicide local : conduite après application ?","back":"Sous-vêtements **propres**, **pas de lavage pendant 24 h**, puis douche eau + savon.","prio":"P2","sec":"s9"},{"id":"fc-d171-dae464","poly":"dermato","fiche":"d171","front":"Benzoate de benzyle : pourquoi une 2e application et quand ?","back":"Il agit mal sur les **œufs** : refaire **8 jours** plus tard (perméthrine : **7 jours**).","prio":"P1","sec":"s9"},{"id":"fc-d171-f555f7","poly":"dermato","fiche":"d171","front":"Benzoate de benzyle : concentration et temps de contact chez l'adulte ?","back":"Émulsion **10 %**, laissée **24 heures**.","prio":"P1","sec":"s9"},{"id":"fc-d171-294114","poly":"dermato","fiche":"d171","front":"Benzoate de benzyle chez l'enfant de 1 mois à 2 ans : temps de contact ?","back":"Réduit : **12 h** (texte) ou **6 à 12 h** (tableau 12.1).","prio":"P2","sec":"s9"},{"id":"fc-d171-954648","poly":"dermato","fiche":"d171","front":"Benzoate de benzyle : âge minimal, grossesse, allaitement ?","back":"Dès **1 mois** ; possible pendant la **grossesse** ; **hors allaitement**.","prio":"P2","sec":"s9"},{"id":"fc-d171-e69dc5","poly":"dermato","fiche":"d171","front":"Perméthrine dans la gale : modalités ?","back":"Crème **5 %**, du cou aux orteils, laissée **8 à 12 h**, renouvelée **7 jours** plus tard.","prio":"P1","sec":"s9"},{"id":"fc-d171-d8ce3e","poly":"dermato","fiche":"d171","front":"Perméthrine 5 % : âge minimal, grossesse, allaitement ?","back":"Dès **2 mois** ; possible pendant la **grossesse** ; **hors allaitement**.","prio":"P2","sec":"s9"},{"id":"fc-d171-acd7b1","poly":"dermato","fiche":"d171","front":"Perméthrine 5 % : quantité chez l'adulte et l'enfant de plus de 12 ans ?","back":"**30 g** (1 tube).","prio":"P3","sec":"s9"},{"id":"fc-d171-14d087","poly":"dermato","fiche":"d171","front":"Perméthrine 5 % : quantités chez l'enfant de 2 mois à 12 ans ?","back":"2 mois-1 an : **1/8 de tube** ; 1-5 ans : **1/4** ; 6-12 ans : **1/2**.","prio":"P3","sec":"s9"},{"id":"fc-d171-0170ff","poly":"dermato","fiche":"d171","front":"Benzoate de benzyle et perméthrine : remboursement ?","back":"Remboursés à **65 %** (benzoate : prescription médicale facultative).","prio":"P3","sec":"s9"},{"id":"fc-d171-1599bd","poly":"dermato","fiche":"d171","front":"Après un scabicide local : que prescrire et pourquoi ?","back":"Un **émollient** : peau **sèche et prurigineuse** après traitement.","prio":"P2","sec":"s9"},{"id":"fc-d171-d0b95f","poly":"dermato","fiche":"d171","front":"Gale : traitement du linge ?","back":"Vêtements, draps, serviettes lavés **au-delà de 60 °C** si possible (+ sèche-linge et repassage si possible).","prio":"P1","sec":"s9"},{"id":"fc-d171-44ab07","poly":"dermato","fiche":"d171","front":"Gale commune : faut-il désinfecter l'environnement ?","back":"**Non**.","prio":"P1","sec":"s9"},{"id":"fc-d171-919364","poly":"dermato","fiche":"d171","front":"Gale : quel support remettre au patient ?","back":"Un **schéma de traitement détaillé et écrit**.","prio":"P2","sec":"s9"},{"id":"fc-d171-aa75e4","poly":"dermato","fiche":"d171","front":"Gale commune de l'enfant : éviction de la collectivité ?","back":"Jusqu'à **3 jours après le traitement**.","prio":"P2","sec":"s9"},{"id":"fc-d171-f01c89","poly":"dermato","fiche":"d171","front":"Gale : faut-il retraiter des nodules post-scabieux persistants ?","back":"**Non** ; éviter les **traitements répétés abusifs**.","prio":"P1","sec":"s9"},{"id":"fc-d171-c11814","poly":"dermato","fiche":"d171","front":"Gale profuse ou hyperkératosique : mesure d'isolement ?","back":"**Isoler** le malade, idéalement en l'**hospitalisant**.","prio":"P1","sec":"s10"},{"id":"fc-d171-c9ad6a","poly":"dermato","fiche":"d171","front":"Gale profuse ou hyperkératosique : traitement scabicide ?","back":"**Ivermectine orale ET traitement local** associés.","prio":"P1","sec":"s10"},{"id":"fc-d171-b0fa5b","poly":"dermato","fiche":"d171","front":"Gale profuse ou hyperkératosique : sujets contacts ?","back":"Les définir **largement**.","prio":"P2","sec":"s10"},{"id":"fc-d171-72e864","poly":"dermato","fiche":"d171","front":"Gale profuse impétiginisée : que faut-il ajouter ?","back":"Une **antibiothérapie**.","prio":"P2","sec":"s10"},{"id":"fc-d171-456e51","poly":"dermato","fiche":"d171","front":"Gale profuse : que faire de l'environnement ?","back":"Envisager une **décontamination des lieux de vie** (+ linge > 60 °C).","prio":"P2","sec":"s10"},{"id":"fc-d171-da9270","poly":"dermato","fiche":"d171","front":"Gale profuse ou hyperkératosique de l'enfant : éviction ?","back":"Jusqu'à **négativation de l'examen parasitologique**.","prio":"P2","sec":"s10"},{"id":"fc-d171-5971b9","poly":"dermato","fiche":"d171","front":"Gale en établissement : avec qui décider de la stratégie ?","back":"En concertation avec les **autorités sanitaires**.","prio":"P3","sec":"s11"},{"id":"fc-d171-3d95e9","poly":"dermato","fiche":"d171","front":"Gale en établissement : qui traiter et comment ?","back":"Au minimum **toutes les personnes contacts**, au maximum tout l'établissement ; **par voie orale**.","prio":"P2","sec":"s11"},{"id":"fc-d171-aad936","poly":"dermato","fiche":"d171","front":"Gale en établissement : information des familles ?","back":"**Informer les familles** en présence du patient ou avec son accord.","prio":"P3","sec":"s11"},{"id":"fc-d171-29643e","poly":"dermato","fiche":"d171","front":"Gale : prurit persistant 8 à 15 jours après traitement, quelles hypothèses ?","back":"**Irritation**, **eczéma de contact**, **parasitophobie**, **autre cause** de prurit, **échec**.","prio":"P2","sec":"s12"},{"id":"fc-d171-8f1be6","poly":"dermato","fiche":"d171","front":"Gale : sur quoi établir un échec du traitement ?","back":"**Lésions cliniques évocatrices** et/ou **examen parasitologique positif**.","prio":"P2","sec":"s12"},{"id":"fc-d171-686ed3","poly":"dermato","fiche":"d171","front":"Poux de tête : quand traiter ?","back":"**Vite**, le sujet **parasité** ; **pas de traitement présomptif**.","prio":"P1","sec":"s13"},{"id":"fc-d171-74ec1c","poly":"dermato","fiche":"d171","front":"Poux de tête : pédiculicides actuels ?","back":"**Diméticone** ou **oxyphthirine** (destruction **mécanique**), en solution ou lotion.","prio":"P1","sec":"s13"},{"id":"fc-d171-e863df","poly":"dermato","fiche":"d171","front":"Poux de tête : quels produits ne sont plus disponibles ?","back":"**Malathion** et **perméthrine**.","prio":"P2","sec":"s13"},{"id":"fc-d171-3f4f1f","poly":"dermato","fiche":"d171","front":"Poux de tête : place des shampooings et poudres ?","back":"Nettement **moins efficaces** : à **ne plus utiliser**.","prio":"P2","sec":"s13"},{"id":"fc-d171-82e220","poly":"dermato","fiche":"d171","front":"Pédiculicide : mode d'application ?","back":"**Raie par raie**, **15 min à 1 h**, puis shampooing **non traitant**, rinçage, **peignage** soigneux.","prio":"P1","sec":"s13"},{"id":"fc-d171-d3fbfa","poly":"dermato","fiche":"d171","front":"Poux de tête : pourquoi un 2e traitement et quand ?","back":"Les produits tuent mal les **lentes** : 2e traitement **7 à 10 jours** plus tard.","prio":"P1","sec":"s13"},{"id":"fc-d171-bc9695","poly":"dermato","fiche":"d171","front":"Poux de tête : traitement du linge et de la literie ?","back":"Lavage **à 50 °C au moins** ou **aérosol insecticide** ; cycle long si infestation massive.","prio":"P2","sec":"s13"},{"id":"fc-d171-1e6874","poly":"dermato","fiche":"d171","front":"Poux de tête : faut-il désinfecter les locaux ?","back":"**Non**, cela ne sert à rien.","prio":"P2","sec":"s13"},{"id":"fc-d171-8f036d","poly":"dermato","fiche":"d171","front":"Poux de tête : qui traiter dans l'entourage ?","back":"Les personnes du foyer **qui ont des poux** ; fratrie et entourage : **pas indispensable**.","prio":"P1","sec":"s13"},{"id":"fc-d171-58525e","poly":"dermato","fiche":"d171","front":"Poux de tête : éviction scolaire ?","back":"**Non systématique**.","prio":"P1","sec":"s13"},{"id":"fc-d171-295952","poly":"dermato","fiche":"d171","front":"Poux de tête en collectivité d'enfants : mesures ?","back":"**Examen du groupe** par une personne formée ; **information écrite** des parents.","prio":"P2","sec":"s13"},{"id":"fc-d171-0eabe4","poly":"dermato","fiche":"d171","front":"Poux de tête : traitement en cas d'échec d'un local bien mené ?","back":"**Ivermectine 400 µg/kg** en 1 prise, **répétée à 7 jours** (> 2 ans et > 15 kg), **hors AMM**.","prio":"P2","sec":"s13"},{"id":"fc-d171-44463b","poly":"dermato","fiche":"d171","front":"Poux de tête : poux vivants au contrôle à J2, conduite ?","back":"Retraiter en **changeant de classe** (résistance probable).","prio":"P1","sec":"s13"},{"id":"fc-d171-2d9fb3","poly":"dermato","fiche":"d171","front":"Poux de tête : poux vivants au contrôle à J12, conduite ?","back":"Retraiter avec le **produit initial** (lentes mal tuées).","prio":"P1","sec":"s13"},{"id":"fc-d171-353d5b","poly":"dermato","fiche":"d171","front":"Poux de tête : traitement préventif ?","back":"**Aucun** ; les shampooings ne sont **jamais curatifs** et pourraient favoriser les résistances.","prio":"P1","sec":"s13"},{"id":"fc-d171-2300e1","poly":"dermato","fiche":"d171","front":"Poux de tête : causes d'échec côté patient ?","back":"**Incompréhension**, négligence ; **coût** (aucune spécialité remboursée) ; **réinfestation**.","prio":"P3","sec":"s13"},{"id":"fc-d171-01fcbd","poly":"dermato","fiche":"d171","front":"Poux de tête : causes d'échec côté traitement ?","back":"Durée/fréquence ou **quantité insuffisantes** ; forme galénique inappropriée ; **résistance acquise**.","prio":"P3","sec":"s13"},{"id":"fc-d171-8c5170","poly":"dermato","fiche":"d171","front":"Poux de corps : traitement ?","back":"**Décontamination du linge et de la literie**, le plus souvent suffisante.","prio":"P1","sec":"s14"},{"id":"fc-d171-fef927","poly":"dermato","fiche":"d171","front":"Phtiriase : traitement local ?","back":"Même traitement que les **poux de tête**, avec **2e traitement 7 à 10 jours** après.","prio":"P1","sec":"s15"},{"id":"fc-d171-6e251a","poly":"dermato","fiche":"d171","front":"Phtiriase : meilleur traitement à cet endroit ?","back":"Le **rasage**.","prio":"P1","sec":"s15"},{"id":"fc-d171-6a9ba3","poly":"dermato","fiche":"d171","front":"Phtiriase : mesures associées ?","back":"**Dépister une autre IST** ; **traiter les partenaires**.","prio":"P1","sec":"s15"},{"id":"fc-d171-7cf4e8","poly":"dermato","fiche":"d171","front":"Gale : 3 messages clés d'éducation ?","back":"Traiter **simultanément** malades et contacts + **linge/literie** ; **schéma écrit** ; **pas de traitements répétés abusifs**.","prio":"P1","sec":"s16"},{"id":"fc-d187-f6fb79","poly":"dermato","fiche":"d187","front":"Urticaire : quel est son mécanisme ?","back":"Activation des **mastocytes**, immunologique ou, le plus souvent, **non immunologique**.","prio":"P1","sec":"s1"},{"id":"fc-d187-da4deb","poly":"dermato","fiche":"d187","front":"Urticaire : quel est le principal médiateur ?","back":"L'**histamine**, que l'urticaire soit immunologique ou non.","prio":"P1","sec":"s1"},{"id":"fc-d187-dd926e","poly":"dermato","fiche":"d187","front":"Urticaire : comment pose-t-on le diagnostic ?","back":"À l'**interrogatoire** et à l'**examen clinique**.","prio":"P1","sec":"s1"},{"id":"fc-d187-4ca8a0","poly":"dermato","fiche":"d187","front":"Urticaire : quelle proportion de la population fait une poussée au cours de la vie ?","back":"**15 %**.","prio":"P2","sec":"s1"},{"id":"fc-d187-b2e40a","poly":"dermato","fiche":"d187","front":"Urticaire superficielle et profonde : où siège l'œdème ?","back":"Superficielle : dans le **derme** ; profonde (angiœdème) : **derme et hypoderme**.","prio":"P2","sec":"s1"},{"id":"fc-d187-a604ba","poly":"dermato","fiche":"d187","front":"Urticaire : quel mécanisme vasculaire produit l'œdème ?","back":"**Vasodilatation** avec hausse de la **perméabilité capillaire**, due aux médiateurs mastocytaires.","prio":"P3","sec":"s1"},{"id":"fc-d187-868594","poly":"dermato","fiche":"d187","front":"Mastocyte : quelles voies immunologiques d'activation ?","back":"**IgE** fixées sur les récepteurs **FcεRI**, ou **auto-anticorps IgG anti-FcεRI** qui fixent le complément.","prio":"P3","sec":"s1"},{"id":"fc-d187-2ad97f","poly":"dermato","fiche":"d187","front":"Mastocyte : quelles voies non immunologiques d'activation ?","back":"Stimulation de récepteurs variés, effet sur le métabolisme de l'**acide arachidonique**, apport ou libération excessive d'**histamine**.","prio":"P3","sec":"s1"},{"id":"fc-d187-c7ebcd","poly":"dermato","fiche":"d187","front":"Urticaire superficielle : quelle lésion élémentaire ?","back":"**Papule œdémateuse** « ortiée », rosée ou érythémateuse, à **bordure nette**.","prio":"P1","sec":"s2"},{"id":"fc-d187-5e6bba","poly":"dermato","fiche":"d187","front":"Urticaire superficielle : quelles sont les trois caractéristiques constantes ?","back":"**Prurit**, lésions **fugaces** (minutes à heures) et **migratrices**.","prio":"P1","sec":"s2"},{"id":"fc-d187-818bed","poly":"dermato","fiche":"d187","front":"Urticaire superficielle : a-t-elle une topographie préférentielle ?","back":"**Non**, aucune topographie préférentielle.","prio":"P3","sec":"s2"},{"id":"fc-d187-18cbb7","poly":"dermato","fiche":"d187","front":"Urticaire superficielle : quels aspects atypiques possibles ?","back":"**Annulaire**, **polycyclique**, **micropapuleux**, **bulleux**.","prio":"P3","sec":"s2"},{"id":"fc-d187-7d0376","poly":"dermato","fiche":"d187","front":"Angiœdème : quel aspect clinique ?","back":"Œdème **blanc rosé**, de consistance **ferme**.","prio":"P1","sec":"s2"},{"id":"fc-d187-730e4c","poly":"dermato","fiche":"d187","front":"Angiœdème : est-il prurigineux ?","back":"**Non** : sensation de **tension** ou **douleur**.","prio":"P1","sec":"s2"},{"id":"fc-d187-4d7b1c","poly":"dermato","fiche":"d187","front":"Angiœdème : quels sièges de prédilection ?","back":"**Visage** (paupières, lèvres), **extrémités** des membres, **organes génitaux**.","prio":"P2","sec":"s2"},{"id":"fc-d187-0a6d86","poly":"dermato","fiche":"d187","front":"Angiœdème : en combien de temps régresse-t-il ?","back":"En **moins de 72 heures**, sans séquelle.","prio":"P1","sec":"s2"},{"id":"fc-d187-6d9554","poly":"dermato","fiche":"d187","front":"Angiœdème : quel siège fait le pronostic ?","back":"Le siège **laryngo-pharyngé** : il peut mettre en jeu le **pronostic vital**.","prio":"P1","sec":"s2"},{"id":"fc-d187-ca504d","poly":"dermato","fiche":"d187","front":"Urticaire superficielle : quelle fréquence d'association aux angiœdèmes ?","back":"**40 %** des cas ; isolée dans la moitié des cas.","prio":"P3","sec":"s2"},{"id":"fc-d187-54d01d","poly":"dermato","fiche":"d187","front":"Angiœdèmes isolés (sans urticaire superficielle) : quelle fréquence ?","back":"**10 %** des cas ; démarche diagnostique et thérapeutique différente.","prio":"P2","sec":"s2"},{"id":"fc-d187-2adbdd","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quels signes respiratoires ?","back":"**Dysphonie**, **dyspnée**, **bronchospasme**.","prio":"P2","sec":"s3"},{"id":"fc-d187-c661a1","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quels signes cardiovasculaires ?","back":"**Tachycardie ou bradycardie**, **hypotension artérielle**.","prio":"P2","sec":"s3"},{"id":"fc-d187-fc2f6c","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quels signes digestifs et neurologiques ?","back":"Nausées, vomissements, diarrhées ; **céphalées**, **convulsions**.","prio":"P2","sec":"s3"},{"id":"fc-d187-2da43d","poly":"dermato","fiche":"d187","front":"Urticaire : les signes d'anaphylaxie l'accompagnent-ils souvent ?","back":"**Non** : seulement dans une **minorité** de cas.","prio":"P3","sec":"s3"},{"id":"fc-d187-cbd7ce","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quelle classification de gravité ?","back":"Classification de **Ring et Messmer** (grades I à IV).","prio":"P2","sec":"s3"},{"id":"fc-d187-a54425","poly":"dermato","fiche":"d187","front":"Anaphylaxie grade I : quels signes ?","back":"**Signes cutanéo-muqueux** seuls : érythème, urticaire et/ou angiœdème.","prio":"P1","sec":"s3"},{"id":"fc-d187-3f7087","poly":"dermato","fiche":"d187","front":"Anaphylaxie grade II : quels signes ?","back":"Atteinte **multiviscérale modérée** : cutanéo-muqueux ± hypotension, tachycardie, toux, dyspnée, signes digestifs.","prio":"P1","sec":"s3"},{"id":"fc-d187-2eec92","poly":"dermato","fiche":"d187","front":"Anaphylaxie grade III : quels signes ?","back":"**Collapsus** cardiovasculaire, tachy- ou bradycardie ± troubles du rythme ± **bronchospasme** ± signes digestifs.","prio":"P1","sec":"s3"},{"id":"fc-d187-eb2dca","poly":"dermato","fiche":"d187","front":"Anaphylaxie grade IV : de quoi s'agit-il ?","back":"L'**arrêt cardiaque**.","prio":"P1","sec":"s3"},{"id":"fc-d187-2f18a7","poly":"dermato","fiche":"d187","front":"Urticaire : quels diagnostics différentiels discuter ?","back":"**Piqûres d'insectes**, **DBAI prébulleuse**, **érythème polymorphe** : leurs lésions persistent plusieurs jours.","prio":"P2","sec":"s4"},{"id":"fc-d187-e209b9","poly":"dermato","fiche":"d187","front":"Urticaire : quel caractère tranche face aux diagnostics différentiels ?","back":"La **fugacité** : des lésions fixes plusieurs jours orientent vers un autre diagnostic.","prio":"P1","sec":"s4"},{"id":"fc-d187-5716b4","poly":"dermato","fiche":"d187","front":"Urticaire atypique, peu prurigineuse et fixe : quels diagnostics évoquer ?","back":"**Vascularite urticarienne** ou **maladie de Still**.","prio":"P3","sec":"s4"},{"id":"fc-d187-b5fcb5","poly":"dermato","fiche":"d187","front":"Angiœdème isolé : quelles causes d'œdème éliminer ?","back":"Origine **infectieuse**, inflammatoire, endocrinienne, médicamenteuse, auto-immune ou **tumorale**.","prio":"P2","sec":"s4"},{"id":"fc-d187-34934c","poly":"dermato","fiche":"d187","front":"Eczéma aigu du visage versus angiœdème : quels caractères de l'eczéma ?","back":"Lésions **fixes**, **vésiculeuses** et **suintantes**.","prio":"P1","sec":"s4"},{"id":"fc-d187-fa0326","poly":"dermato","fiche":"d187","front":"Dermographisme : quel aspect ?","back":"**Stries urticariennes** après frottement des vêtements, friction ou grattage ; fréquent chez l'enfant et l'adulte jeune.","prio":"P2","sec":"s5"},{"id":"fc-d187-622abc","poly":"dermato","fiche":"d187","front":"Urticaire cholinergique : quel aspect et quels déclencheurs ?","back":"Petites papules de **1 à 5 mm**, haut du corps ; **effort**, **sudation**, douche chaude, émotions.","prio":"P2","sec":"s5"},{"id":"fc-d187-9953d5","poly":"dermato","fiche":"d187","front":"Urticaire au froid : quel déclencheur ?","back":"Contact d'**air, d'eau ou d'objets froids** ; le plus souvent acquise et sans cause retrouvée.","prio":"P2","sec":"s5"},{"id":"fc-d187-30a26e","poly":"dermato","fiche":"d187","front":"Urticaire au froid : quelles causes parfois retrouvées ?","back":"**Infection virale**, **cryoglobuline**.","prio":"P3","sec":"s5"},{"id":"fc-d187-75f3e4","poly":"dermato","fiche":"d187","front":"Urticaire au froid : de quoi dépend la gravité ?","back":"Des signes associés (angiœdème, signes systémiques, **choc**) ou des réactions oropharyngées après **boissons ou aliments froids**.","prio":"P3","sec":"s5"},{"id":"fc-d187-1655df","poly":"dermato","fiche":"d187","front":"Urticaire solaire : quelle présentation ?","back":"Après **quelques minutes** de soleil, sur les zones **habituellement couvertes**.","prio":"P3","sec":"s5"},{"id":"fc-d187-1f78bc","poly":"dermato","fiche":"d187","front":"Urticaire retardée à la pression : quel délai et quel aspect ?","back":"Lésions **infiltrées, profondes, douloureuses**, **4 à 8 heures** après un appui fort ou prolongé.","prio":"P2","sec":"s5"},{"id":"fc-d187-7eb46e","poly":"dermato","fiche":"d187","front":"Urticaire retardée à la pression : quels signes associés ?","back":"Signes systémiques (fièvre, arthralgies, céphalées) dans **la moitié** des cas.","prio":"P3","sec":"s5"},{"id":"fc-d187-baface","poly":"dermato","fiche":"d187","front":"Urticaires physiques : comment les confirme-t-on ?","back":"Évoquées à l'interrogatoire, confirmées par un **test de provocation**.","prio":"P2","sec":"s5"},{"id":"fc-d187-bbeaaa","poly":"dermato","fiche":"d187","front":"Urticaire au froid : quel test de confirmation ?","back":"**Test au glaçon** ; si négatif, immersion main et avant-bras dans l'eau froide.","prio":"P3","sec":"s5"},{"id":"fc-d187-5dcca7","poly":"dermato","fiche":"d187","front":"Urticaire retardée à la pression : quel test ?","back":"Sac de **7 kg** porté **20 minutes** (épaule, avant-bras ou cuisse), lecture dans les heures suivantes.","prio":"P3","sec":"s5"},{"id":"fc-d187-07c805","poly":"dermato","fiche":"d187","front":"Urticaire cholinergique : quel test ?","back":"**Test d'effort** en atmosphère chaude.","prio":"P3","sec":"s5"},{"id":"fc-d187-fe832f","poly":"dermato","fiche":"d187","front":"Urticaire de contact : quel exemple type ?","back":"Les protéines du **latex** (gants, objets en latex).","prio":"P2","sec":"s5"},{"id":"fc-d187-eeaa86","poly":"dermato","fiche":"d187","front":"Urticaire de contact allergique : quel risque ?","back":"Signes **systémiques**, jusqu'au **choc anaphylactique**.","prio":"P2","sec":"s5"},{"id":"fc-d187-361dca","poly":"dermato","fiche":"d187","front":"Urticaire de contact : quel mécanisme ?","back":"**IgE-dépendant** ou **non immunologique**.","prio":"P3","sec":"s5"},{"id":"fc-d187-8402f1","poly":"dermato","fiche":"d187","front":"Prick test : quand le dit-on positif ?","back":"Érythème et papule **de même taille que le témoin positif**, lus à **20 minutes**.","prio":"P3","sec":"s5"},{"id":"fc-d187-81f1a2","poly":"dermato","fiche":"d187","front":"Urticaires alimentaires allergiques (IgE-dépendantes) : sont-elles fréquentes ?","back":"**Non**, elles sont **rares** malgré les nombreux aliments accusés.","prio":"P2","sec":"s5"},{"id":"fc-d187-63c9ea","poly":"dermato","fiche":"d187","front":"Urticaire : quels arguments pour une allergie alimentaire ?","back":"Délai **minutes à < 2 h**, gravité **> grade II**, résolution **< 12 h**, récidive à chaque prise quelle que soit la quantité.","prio":"P1","sec":"s5"},{"id":"fc-d187-47515c","poly":"dermato","fiche":"d187","front":"Allergie alimentaire suspectée : comment la confirmer ?","back":"**Prick tests**, **IgE spécifiques** et, si besoin, **test de provocation orale** à l'hôpital.","prio":"P2","sec":"s5"},{"id":"fc-d187-4ce379","poly":"dermato","fiche":"d187","front":"Urticaire : quels arguments pour une allergie médicamenteuse ?","back":"Délai **< 45 min**, symptômes **< 24 h**, sévérité **> grade II**.","prio":"P1","sec":"s5"},{"id":"fc-d187-ae4581","poly":"dermato","fiche":"d187","front":"Urticaire médicamenteuse : quels médicaments surtout ?","back":"**Antibiotiques**, **AINS**, anesthésiques généraux (**curares**) ; tout médicament possible, toute voie.","prio":"P2","sec":"s5"},{"id":"fc-d187-6572c4","poly":"dermato","fiche":"d187","front":"Urticaire médicamenteuse : est-elle le plus souvent allergique ?","back":"**Non** : IgE dans **< 10 %** des cas ; surtout **intolérance** non immunologique (ex. AINS).","prio":"P1","sec":"s5"},{"id":"fc-d187-c793e8","poly":"dermato","fiche":"d187","front":"Urticaire infectieuse : quelles infections virales en cause ?","back":"Infections des **voies aériennes supérieures** (enfant), **EBV**, **CMV**, **hépatites**.","prio":"P2","sec":"s5"},{"id":"fc-d187-10d18e","poly":"dermato","fiche":"d187","front":"Triade de Caroli : quels signes ?","back":"**Céphalées**, **arthralgies**, **urticaire** (hépatite virale).","prio":"P3","sec":"s5"},{"id":"fc-d187-25f39c","poly":"dermato","fiche":"d187","front":"Urticaire : quand évoquer une parasitose ?","back":"Devant une **hyperéosinophilie** sanguine et/ou des **signes digestifs** (giardiase, ascaridiase, toxocarose…).","prio":"P2","sec":"s5"},{"id":"fc-d187-0a4718","poly":"dermato","fiche":"d187","front":"Piqûre d'hyménoptère : comment confirmer l'allergie au venin ?","back":"Prick tests et surtout **intradermoréactions** aux venins standardisés + **IgE spécifiques**.","prio":"P3","sec":"s5"},{"id":"fc-d187-f87e70","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : quelles sont les principales causes ?","back":"**Infections virales**, **médicaments**, certains **aliments**.","prio":"P1","sec":"s5"},{"id":"fc-d187-7b6cc6","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : quelle durée maximale ?","back":"**< 6 semaines** ; le plus souvent épisode unique.","prio":"P1","sec":"s6"},{"id":"fc-d187-246ef5","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : quelle fréquence dans la population ?","back":"La plus fréquente : **15 à 20 %** de la population générale.","prio":"P3","sec":"s6"},{"id":"fc-d187-807444","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : faut-il des examens systématiques ?","back":"**Non** ; cause à l'interrogatoire, bilan allergologique **orienté** seulement si cause allergique suspectée.","prio":"P1","sec":"s6"},{"id":"fc-d187-320d28","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quelle définition ?","back":"Poussées **quotidiennes ou presque** pendant **plus de 6 semaines**.","prio":"P1","sec":"s6"},{"id":"fc-d187-16d6e9","poly":"dermato","fiche":"d187","front":"Urticaire chronique : faut-il un bilan systématique ?","back":"**Non** ; interrogatoire +++.","prio":"P1","sec":"s6"},{"id":"fc-d187-5a36cf","poly":"dermato","fiche":"d187","front":"Urticaire chronique : que préciser à l'interrogatoire ?","back":"Antécédents (atopie, auto-immunité), circonstances, habitudes, **médicaments**, signes associés, facteurs aggravants (infections, stress).","prio":"P2","sec":"s6"},{"id":"fc-d187-9b642c","poly":"dermato","fiche":"d187","front":"Urticaire chronique inductible : quelle fréquence et quelle définition ?","back":"**10-15 %** : provoquée par un stimulus, reproductible, seulement en sa présence.","prio":"P2","sec":"s6"},{"id":"fc-d187-b0c968","poly":"dermato","fiche":"d187","front":"Urticaire chronique spontanée : quelle fréquence ?","back":"**85-90 %** : la plus fréquente.","prio":"P2","sec":"s6"},{"id":"fc-d187-df64cf","poly":"dermato","fiche":"d187","front":"Urticaire chronique spontanée : quels facteurs favorisants ?","back":"**AINS**, **aspirine**, infections, stress, chaleur…","prio":"P2","sec":"s6"},{"id":"fc-d187-c39bca","poly":"dermato","fiche":"d187","front":"Urticaire chronique spontanée sans contexte évocateur : quelles explorations ?","back":"**Aucune** exploration complémentaire.","prio":"P1","sec":"s6"},{"id":"fc-d187-996d27","poly":"dermato","fiche":"d187","front":"Angiœdème isolé : quelle part est histaminique ?","back":"**95 %** (mastocytes : aliments, médicaments, hyménoptères, latex, facteurs physiques).","prio":"P2","sec":"s6"},{"id":"fc-d187-9b9f41","poly":"dermato","fiche":"d187","front":"Angiœdème isolé : quelle part est bradykinique ?","back":"**5 %**.","prio":"P2","sec":"s6"},{"id":"fc-d187-57aad8","poly":"dermato","fiche":"d187","front":"Angiœdème bradykinique médicamenteux : quels médicaments ?","back":"**IEC**, **sartans**, **gliptines**.","prio":"P1","sec":"s6"},{"id":"fc-d187-bad1f0","poly":"dermato","fiche":"d187","front":"Angiœdème bradykinique : quelle cause non médicamenteuse ?","back":"Déficit héréditaire ou acquis en **inhibiteur de la C1 estérase**.","prio":"P1","sec":"s6"},{"id":"fc-d187-7fcf8e","poly":"dermato","fiche":"d187","front":"Suspicion de déficit en C1 inhibiteur : quels dosages ?","back":"**C1 inhibiteur** (quantitatif et fonctionnel) et **C4**.","prio":"P2","sec":"s6"},{"id":"fc-d187-a06fcd","poly":"dermato","fiche":"d187","front":"Angiœdème bradykinique : quelle efficacité des anti-H1 et corticoïdes ?","back":"**Inefficaces** : traitements spécifiques nécessaires.","prio":"P1","sec":"s6"},{"id":"fc-d187-982861","poly":"dermato","fiche":"d187","front":"Urticaire aiguë sans atteinte muqueuse : quel traitement ?","back":"**Anti-H1 de 2ᵉ génération**, 1 cp/j, **1 à 2 semaines** + **éviction** du facteur déclenchant.","prio":"P1","sec":"s7"},{"id":"fc-d187-27e2d0","poly":"dermato","fiche":"d187","front":"Urticaire aiguë intense : quelle voie pour l'anti-H1 ?","back":"Voie **injectable**.","prio":"P3","sec":"s7"},{"id":"fc-d187-a553fb","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : qu'est-ce qui fait basculer vers l'adrénaline ?","back":"Une **atteinte muqueuse laryngo-pharyngée** ou des **signes d'anaphylaxie** au-delà du grade I (**≥ grade II**).","prio":"P1","sec":"s7"},{"id":"fc-d187-d1dbba","poly":"dermato","fiche":"d187","front":"Œdème laryngé ou anaphylaxie ≥ grade II : quel traitement ?","back":"**Adrénaline intramusculaire**.","prio":"P1","sec":"s8"},{"id":"fc-d187-471998","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quelle dose d'adrénaline IM ?","back":"**0,01 mg/kg** sans dépasser **0,5 mg**, à refaire après **5-15 min** si nécessaire.","prio":"P1","sec":"s8"},{"id":"fc-d187-81d640","poly":"dermato","fiche":"d187","front":"Choc anaphylactique ou arrêt cardiaque : quelle voie pour l'adrénaline ?","back":"**IV**, titrée sur la pression artérielle et la fréquence cardiaque.","prio":"P1","sec":"s8"},{"id":"fc-d187-28a6e0","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quelles mesures associées à l'adrénaline ?","back":"**Oxygène 6-8 L/min**, **remplissage** au sérum salé isotonique, **β2-mimétique** en aérosol si asthme.","prio":"P1","sec":"s8"},{"id":"fc-d187-e4f175","poly":"dermato","fiche":"d187","front":"Adrénaline : quelle surveillance pendant son administration ?","back":"**ECG** et **pression artérielle**.","prio":"P2","sec":"s8"},{"id":"fc-d187-5fe0df","poly":"dermato","fiche":"d187","front":"Anaphylaxie : quelle suite après la phase aiguë ?","back":"**Bilan allergologique** orienté si cause allergique suspectée, puis **éviction** de l'allergène.","prio":"P2","sec":"s8"},{"id":"fc-d187-777378","poly":"dermato","fiche":"d187","front":"Anaphylaxie : les anti-H1 sont-ils le traitement de référence ?","back":"**Non** : c'est l'**adrénaline** ; les anti-H1 traitent l'urticaire sans atteinte muqueuse.","prio":"P1","sec":"s8"},{"id":"fc-d187-788f87","poly":"dermato","fiche":"d187","front":"Angiœdème bradykinique médicamenteux : quelle mesure de suite ?","back":"**Supprimer** le médicament responsable (IEC, sartan, gliptine).","prio":"P2","sec":"s9"},{"id":"fc-d187-cd11a2","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quel traitement de 1re ligne ?","back":"**Anti-H1 de 2ᵉ génération** à la dose de l'AMM pendant **4 à 6 semaines**, puis réévaluation.","prio":"P2","sec":"s10"},{"id":"fc-d187-f0aba2","poly":"dermato","fiche":"d187","front":"Urticaire chronique disparue sous anti-H1 : combien de temps poursuivre ?","back":"Au moins **3 mois**.","prio":"P2","sec":"s10"},{"id":"fc-d187-548516","poly":"dermato","fiche":"d187","front":"Urticaire chronique persistante sous anti-H1 : quel bilan ?","back":"**NFS**, **CRP**, **anticorps anti-TPO**.","prio":"P2","sec":"s10"},{"id":"fc-d187-0735e8","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quelle fréquence d'atteinte thyroïdienne associée ?","back":"**10 à 20 %** des cas.","prio":"P3","sec":"s10"},{"id":"fc-d187-05c480","poly":"dermato","fiche":"d187","front":"Urticaire chronique résistante : comment modifier les anti-H1 ?","back":"Autre molécule, ou dose augmentée **jusqu'à 4 fois** celle de l'AMM (hors AMM).","prio":"P2","sec":"s10"},{"id":"fc-d187-949f20","poly":"dermato","fiche":"d187","front":"Urticaire chronique spontanée résistante aux anti-H1 : quel traitement a l'AMM ?","back":"L'**omalizumab** (anti-IgE), en association aux anti-H1.","prio":"P2","sec":"s10"},{"id":"fc-d187-e4d1c2","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quelle proportion résiste aux anti-H1 de 2ᵉ génération ?","back":"**Moins de 10 %**.","prio":"P3","sec":"s10"},{"id":"fc-d187-8f25d8","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quel autre traitement peut être efficace (hors AMM) ?","back":"La **ciclosporine**.","prio":"P3","sec":"s10"},{"id":"fc-d187-e57fe8","poly":"dermato","fiche":"d187","front":"Urticaire chronique et grossesse : peut-on donner des anti-H1 ?","back":"**Oui**, après avis du **CRAT**.","prio":"P3","sec":"s10"},{"id":"fc-d187-6ad6e6","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quelle place pour la corticothérapie générale ?","back":"**Aucune**.","prio":"P2","sec":"s10"},{"id":"fc-d187-c3fe2c","poly":"dermato","fiche":"d187","front":"Urticaire chronique : quel retentissement évaluer ?","back":"La **qualité de vie**, souvent altérée.","prio":"P3","sec":"s10"},{"id":"fc-d187-4838c2","poly":"dermato","fiche":"d187","front":"Atopie : quelle est sa définition ?","back":"Prédisposition **génétique** à produire des **IgE** au contact des allergènes de l'environnement.","prio":"P2","sec":"s11"},{"id":"fc-d187-0f53ef","poly":"dermato","fiche":"d187","front":"Atopie : quelles manifestations selon l'organe ?","back":"**Dermatite atopique**, **allergie alimentaire**, **asthme**/bronchiolite, **rhinite** ou rhinoconjonctivite allergique.","prio":"P2","sec":"s11"},{"id":"fc-d187-a06ff3","poly":"dermato","fiche":"d187","front":"Qu'est-ce que la marche atopique ?","back":"La **succession des manifestations atopiques** au fil de l'âge chez une même personne.","prio":"P2","sec":"s11"},{"id":"fc-d187-cf3dec","poly":"dermato","fiche":"d187","front":"Marche atopique : quelles sont les manifestations les plus précoces ?","back":"**Dermatite atopique**, **allergie alimentaire**, **bronchiolite**.","prio":"P3","sec":"s11"},{"id":"fc-d187-d123ff","poly":"dermato","fiche":"d187","front":"Allergie alimentaire de l'atopique : quel aliment surtout ?","back":"Les **protéines du lait de vache** (aussi œuf, arachide).","prio":"P3","sec":"s11"},{"id":"fc-d187-c6d66a","poly":"dermato","fiche":"d187","front":"Qu'est-ce que la dermatite atopique « intrinsèque » ?","back":"Une dermatite atopique **sans augmentation des IgE** (rare).","prio":"P3","sec":"s11"},{"id":"fc-d187-001ed8","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle fréquence d'atopie familiale ?","back":"Plus de **50 %** des cas.","prio":"P3","sec":"s11"},{"id":"fc-d187-13f8d6","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle protéine de barrière est mutée chez 30 % des patients ?","back":"La **filaggrine** (mutation perte de fonction) : barrière plus perméable aux allergènes.","prio":"P2","sec":"s11"},{"id":"fc-d187-2a7a89","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle anomalie de l'immunité innée ?","back":"Moins de **peptides antimicrobiens** : prédisposition aux infections **bactériennes** et **herpétiques**.","prio":"P3","sec":"s11"},{"id":"fc-d187-0b5864","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle orientation de l'immunité adaptative ?","back":"Différenciation **Th2**, production d'**IgE**, cytokines qui entretiennent l'inflammation.","prio":"P3","sec":"s11"},{"id":"fc-d187-ae2330","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quels facteurs environnementaux ?","back":"**Irritants** (savons, détergents, tabac) et **allergènes** (acariens, aliments, animaux, pollen).","prio":"P3","sec":"s11"},{"id":"fc-d187-c9ce46","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle prévalence chez l'enfant des pays industrialisés ?","back":"**10 à 20 %** des enfants.","prio":"P3","sec":"s11"},{"id":"fc-d187-4c7010","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle théorie explique la hausse de prévalence ?","back":"La **théorie hygiéniste** : moins d'exposition aux agents infectieux, déviation Th2.","prio":"P3","sec":"s11"},{"id":"fc-d187-61db18","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle évolution ?","back":"Maladie **chronique**, évoluant **le plus souvent par poussées**, classiquement aggravée l'**hiver**.","prio":"P1","sec":"s12"},{"id":"fc-d187-b53c27","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quand débute-t-elle habituellement ?","back":"Dans la **première année** de vie.","prio":"P1","sec":"s12"},{"id":"fc-d187-da7eb6","poly":"dermato","fiche":"d187","front":"Dermatite atopique : comment pose-t-on le diagnostic ?","back":"Diagnostic **clinique**, habituellement facile ; aucun examen complémentaire.","prio":"P1","sec":"s12"},{"id":"fc-d187-6378cb","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle proportion d'enfants évolue vers une forme de l'adulte ?","back":"**3 à 5 %**, surtout les formes sévères d'emblée.","prio":"P2","sec":"s12"},{"id":"fc-d187-1df017","poly":"dermato","fiche":"d187","front":"Dermatite atopique débutant à l'âge adulte : que faire ?","back":"Début possible mais rare : écarter d'autres diagnostics (**gale**, **eczéma de contact**, **lymphome cutané T**…).","prio":"P2","sec":"s12"},{"id":"fc-d187-d85973","poly":"dermato","fiche":"d187","front":"Dermatite atopique en phase aiguë : quel aspect ?","back":"Lésions **érythémateuses et vésiculeuses**, puis érosions, **suintement**, croûtes ; lésions mal limitées.","prio":"P2","sec":"s12"},{"id":"fc-d187-fa6563","poly":"dermato","fiche":"d187","front":"Dermatite atopique chronique : qu'est-ce que la lichénification ?","back":"Peau **épaissie, quadrillée, pigmentée** par le grattage chronique.","prio":"P1","sec":"s12"},{"id":"fc-d187-d01cb1","poly":"dermato","fiche":"d187","front":"Dermatite atopique du nourrisson : quelle topographie ?","back":"Zones **convexes** du visage (**respect médio-facial**) et des membres, plis du cou ; siège souvent épargné.","prio":"P1","sec":"s12"},{"id":"fc-d187-c0eb14","poly":"dermato","fiche":"d187","front":"Dermatite atopique après 2 ans : quelle topographie ?","back":"Les **plis**, notamment **coudes et genoux**.","prio":"P1","sec":"s12"},{"id":"fc-d187-417e3e","poly":"dermato","fiche":"d187","front":"Dermatite atopique de l'adolescent et l'adulte : quelle topographie ?","back":"Prédominance au **visage** et au **cou**.","prio":"P1","sec":"s12"},{"id":"fc-d187-25f3d5","poly":"dermato","fiche":"d187","front":"Dermatite atopique : comment se manifeste le prurit chez le tout-petit ?","back":"L'enfant se **frotte** et s'**agite**, surtout déshabillé.","prio":"P2","sec":"s12"},{"id":"fc-d187-d7cd30","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quels signes associés ?","back":"**Prurit** quasi constant, **xérose**, hypopigmentation post-inflammatoire (« dartres »), fissure sous-auriculaire.","prio":"P2","sec":"s12"},{"id":"fc-d187-158bd2","poly":"dermato","fiche":"d187","front":"Qu'est-ce que le signe de Dennie-Morgan ?","back":"Un **double pli sous la paupière inférieure** (dermatite atopique).","prio":"P2","sec":"s12"},{"id":"fc-d187-fac737","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelles formes particulières ?","back":"**Eczéma nummulaire** (lésions arrondies bien limitées), **prurigo**, **érythrodermie**.","prio":"P3","sec":"s12"},{"id":"fc-d187-fbad1b","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle circonstance peut provoquer une érythrodermie ?","back":"L'**arrêt d'une corticothérapie systémique** (non indiquée).","prio":"P2","sec":"s12"},{"id":"fc-d187-a14ab2","poly":"dermato","fiche":"d187","front":"Dermatite atopique : les antécédents d'atopie sont-ils indispensables au diagnostic ?","back":"**Non** : arguments importants mais non indispensables.","prio":"P2","sec":"s13"},{"id":"fc-d187-a8a7f9","poly":"dermato","fiche":"d187","front":"Dermatite atopique : IgE totales élevées ou hyperéosinophilie sont-elles nécessaires au diagnostic ?","back":"**Non** : elles témoignent du terrain atopique sans être nécessaires.","prio":"P2","sec":"s13"},{"id":"fc-d187-6e0c14","poly":"dermato","fiche":"d187","front":"Dermatite atopique : faut-il faire des tests allergologiques en 1re intention ?","back":"**Non**, aucun intérêt en première intention.","prio":"P1","sec":"s13"},{"id":"fc-d187-2e269d","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quels signes d'appel font chercher une allergie alimentaire ?","back":"Signes après ingestion (syndrome oral, urticaire, signes digestifs…), forme **grave ou résistante**, **cassure pondérale**.","prio":"P2","sec":"s13"},{"id":"fc-d187-729838","poly":"dermato","fiche":"d187","front":"Dermatite atopique avec allergie alimentaire suspectée : quelles explorations ?","back":"**Prick tests**, **IgE sériques spécifiques**, **test de provocation orale**, **atopy patch tests**.","prio":"P3","sec":"s13"},{"id":"fc-d187-208b0e","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quand faire des patch tests ?","back":"Atteinte de **zones inhabituelles**, non-réponse ou **aggravation** sous traitement (eczéma de contact suspecté).","prio":"P2","sec":"s13"},{"id":"fc-d187-08f3a0","poly":"dermato","fiche":"d187","front":"Dermatite atopique : que montrerait une biopsie ?","back":"Atteinte épidermique : **exocytose** lymphocytaire et **spongiose** formant des vésicules microscopiques.","prio":"P3","sec":"s13"},{"id":"fc-d187-6d0262","poly":"dermato","fiche":"d187","front":"Dermatite atopique du nourrisson : quels diagnostics différentiels ?","back":"**Dermatite séborrhéique**, **gale** (vésiculo-pustules palmo-plantaires), syndromes génétiques rares (Buckley).","prio":"P3","sec":"s13"},{"id":"fc-d187-87362e","poly":"dermato","fiche":"d187","front":"Dermatite atopique de l'enfant, l'adolescent ou l'adulte : quels diagnostics différentiels ?","back":"**Dermatite de contact**, **psoriasis**, **lymphome cutané**, **gale**.","prio":"P3","sec":"s13"},{"id":"fc-d187-e6023f","poly":"dermato","fiche":"d187","front":"Dermatite atopique surinfectée par S. aureus : quels signes ?","back":"**Croûtes jaunâtres ou purulentes**, souvent **malodorantes**.","prio":"P1","sec":"s14"},{"id":"fc-d187-a5f609","poly":"dermato","fiche":"d187","front":"Dermatite atopique : avec quoi ne pas confondre la surinfection staphylococcique ?","back":"La **colonisation chronique** par le staphylocoque (quasi constante) et le **suintement** des lésions aiguës.","prio":"P2","sec":"s14"},{"id":"fc-d187-e5f453","poly":"dermato","fiche":"d187","front":"Syndrome de Kaposi-Juliusberg : quel agent ?","back":"**HSV**, surtout **HSV1**.","prio":"P1","sec":"s14"},{"id":"fc-d187-122f52","poly":"dermato","fiche":"d187","front":"Syndrome de Kaposi-Juliusberg : quel aspect clinique ?","back":"Lésions qui **changent vite** : vésicules et pustules **ombiliquées** groupées en placards croûteux, ± fièvre et AEG.","prio":"P1","sec":"s14"},{"id":"fc-d187-528281","poly":"dermato","fiche":"d187","front":"Syndrome de Kaposi-Juliusberg : quelle conduite ?","back":"**Antiviral** (IV), **arrêt des dermocorticoïdes**, recherche d'atteinte **oculaire, pulmonaire ou neurologique**.","prio":"P1","sec":"s19"},{"id":"fc-d187-2588d1","poly":"dermato","fiche":"d187","front":"Kaposi-Juliusberg : faut-il hospitaliser ?","back":"**Oui** : infection grave surtout herpétique = hospitalisation en dermatologie.","prio":"P2","sec":"s19"},{"id":"fc-d187-0e6d95","poly":"dermato","fiche":"d187","front":"Kaposi-Juliusberg : quelle évolution sous antiviral IV ?","back":"Favorable en **quelques jours**.","prio":"P3","sec":"s19"},{"id":"fc-d187-3b7361","poly":"dermato","fiche":"d187","front":"Kaposi-Juliusberg : quel terrain typique ?","back":"Sujet jeune ou **nourrisson** atopique, dermatite sévère, en poussée et/ou insuffisamment traitée.","prio":"P2","sec":"s19"},{"id":"fc-d187-371e44","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel poxvirus donne des lésions plus nombreuses chez l'atopique ?","back":"Le **molluscum contagiosum**.","prio":"P3","sec":"s14"},{"id":"fc-d187-3db348","poly":"dermato","fiche":"d187","front":"Dermatite atopique : comment prévenir l'eczéma de contact ?","back":"Éviter les allergènes fréquents : **parfums**, produits « **bio** » à base de plantes.","prio":"P2","sec":"s14"},{"id":"fc-d187-f25b2a","poly":"dermato","fiche":"d187","front":"Dermatite atopique sévère avec retard de croissance : est-il dû aux dermocorticoïdes ?","back":"**Non** : il s'améliore sous traitement et doit faire chercher une **allergie alimentaire**.","prio":"P2","sec":"s14"},{"id":"fc-d187-4ccca6","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle complication ophtalmologique est associée ?","back":"Le **kératocône** (et complications rares d'une corticothérapie systémique mal utilisée).","prio":"P3","sec":"s14"},{"id":"fc-d187-4910a9","poly":"dermato","fiche":"d187","front":"Dermatite atopique en poussée : quelle est la base du traitement ?","back":"Les **dermocorticoïdes**.","prio":"P1","sec":"s15"},{"id":"fc-d187-9369f4","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel niveau de dermocorticoïde sur visage, plis ou avant 2 ans ?","back":"Activité **moyenne**.","prio":"P1","sec":"s15"},{"id":"fc-d187-54447e","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel niveau de dermocorticoïde sur le corps après 2 ans ?","back":"Activité **forte**.","prio":"P1","sec":"s15"},{"id":"fc-d187-acb120","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quand utiliser un dermocorticoïde très fort ?","back":"En **cure courte** sur des lésions **lichénifiées**.","prio":"P2","sec":"s15"},{"id":"fc-d187-583485","poly":"dermato","fiche":"d187","front":"Dermatite atopique : pourquoi pas de dermocorticoïde d'activité faible ?","back":"**Inutile**, car inefficace.","prio":"P2","sec":"s15"},{"id":"fc-d187-a136be","poly":"dermato","fiche":"d187","front":"Dermocorticoïde : crème ou pommade selon les lésions ?","back":"**Crème** : lésions suintantes et plis ; **pommade** : lésions très sèches ou lichénifiées.","prio":"P2","sec":"s15"},{"id":"fc-d187-f535e5","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel rythme d'application du dermocorticoïde ?","back":"**Une application par jour** jusqu'à **disparition complète** de l'inflammation.","prio":"P1","sec":"s15"},{"id":"fc-d187-03772e","poly":"dermato","fiche":"d187","front":"Dermatite atopique : pourquoi préciser la quantité de dermocorticoïde sur l'ordonnance ?","back":"La **corticophobie** fait appliquer moins que nécessaire : **échec par insuffisance de dose**.","prio":"P2","sec":"s15"},{"id":"fc-d187-c40830","poly":"dermato","fiche":"d187","front":"Dermocorticoïdes : quelle quantité pour toute la surface corporelle d'un homme moyen ?","back":"Environ **30 g/jour**.","prio":"P3","sec":"s15"},{"id":"fc-d187-3a7bdb","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel traitement préventif des rechutes par dermocorticoïde ?","back":"**2 applications par semaine** sur la peau guérie.","prio":"P3","sec":"s15"},{"id":"fc-d187-8f67dc","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelle place pour les émollients ?","back":"Prescrits **systématiquement** contre la xérose, sur tout le corps, produit sans parfum.","prio":"P1","sec":"s15"},{"id":"fc-d187-a5439c","poly":"dermato","fiche":"d187","front":"Émollients dans la dermatite atopique : quand sont-ils parfois mal supportés ?","back":"Au début d'une poussée **très inflammatoire** ou sur plaques inflammatoires.","prio":"P3","sec":"s15"},{"id":"fc-d187-92c91a","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelles règles de toilette ?","back":"Bain quotidien ou douche courte, eau **tiède**, nettoyant **sans savon et sans parfum**.","prio":"P2","sec":"s15"},{"id":"fc-d187-5e7415","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel intérêt des anti-H1 oraux ?","back":"Hors AMM, **sans effet sur le prurit** : seulement un intérêt **sédatif**.","prio":"P2","sec":"s15"},{"id":"fc-d187-5adfb1","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quand prescrire antiseptiques ou antibiotiques ?","back":"**Uniquement** en cas d'**infection** avérée.","prio":"P1","sec":"s15"},{"id":"fc-d187-3dd873","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelles mesures associées utiles ?","back":"**Éducation thérapeutique**, soutien psychologique, cures thermales.","prio":"P2","sec":"s15"},{"id":"fc-d187-ce2ae7","poly":"dermato","fiche":"d187","front":"Dermocorticoïdes : quelles contre-indications ?","back":"**Dermatoses infectieuses**, **lésions ulcérées**, **acné et rosacée** du visage.","prio":"P2","sec":"s15"},{"id":"fc-d187-8fcfa8","poly":"dermato","fiche":"d187","front":"Dermatite atopique : comment vérifier l'observance aux consultations ?","back":"**Compter les tubes** utilisés (excès ou, plus souvent, insuffisance).","prio":"P2","sec":"s15"},{"id":"fc-d187-780345","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quels facteurs aggravants éviter ?","back":"**Textiles irritants**, exposition au **tabac** ; se méfier des **contages herpétiques**.","prio":"P2","sec":"s15"},{"id":"fc-d187-cb8648","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quelles règles de vaccination ?","back":"Calendrier **normal**, mais **pas pendant une poussée**.","prio":"P2","sec":"s15"},{"id":"fc-d187-5e9ae8","poly":"dermato","fiche":"d187","front":"Dermatite atopique avec allergie à l'œuf : quelles vaccinations requièrent un avis ?","back":"Vaccins contre la **grippe** et la **fièvre jaune**.","prio":"P3","sec":"s15"},{"id":"fc-d187-de5d2f","poly":"dermato","fiche":"d187","front":"Dermatite atopique : la corticothérapie générale est-elle indiquée ?","back":"**Non** : **rebond** à l'arrêt, même dans les formes sévères.","prio":"P1","sec":"s15"},{"id":"fc-d187-4af84b","poly":"dermato","fiche":"d187","front":"Dermatite atopique : homéopathie, phytothérapie, acupuncture sont-elles recommandées ?","back":"**Non**, aucune preuve scientifique.","prio":"P2","sec":"s15"},{"id":"fc-d187-843087","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel inhibiteur de la calcineurine topique est commercialisé ?","back":"Le **tacrolimus** (seul en France).","prio":"P1","sec":"s16"},{"id":"fc-d187-52c83d","poly":"dermato","fiche":"d187","front":"Tacrolimus topique : quelle indication (AMM) ?","back":"Poussées **modérées à sévères** de l'enfant et de l'adulte si les dermocorticoïdes **échouent** ou sont **contre-indiqués**.","prio":"P1","sec":"s16"},{"id":"fc-d187-5a92ea","poly":"dermato","fiche":"d187","front":"Tacrolimus topique : quelles zones de choix ?","back":"Le **visage** et le **cou**.","prio":"P2","sec":"s16"},{"id":"fc-d187-ab598d","poly":"dermato","fiche":"d187","front":"Tacrolimus topique : quelles conditions de prescription ?","back":"**Médicament d'exception**, réservé aux **dermatologues** et **pédiatres**.","prio":"P2","sec":"s16"},{"id":"fc-d187-3ca5b4","poly":"dermato","fiche":"d187","front":"Tacrolimus pommade : quelles concentrations selon l'âge ?","back":"**0,03 %** de 2 à 15 ans, **0,1 %** chez l'adulte (seule la 0,1 % est remboursée).","prio":"P3","sec":"s16"},{"id":"fc-d187-9e0078","poly":"dermato","fiche":"d187","front":"Tacrolimus topique : quel schéma d'attaque et d'entretien ?","back":"Attaque **2 fois/jour** ; entretien hors AMM **2 fois/semaine** sur les zones habituelles.","prio":"P3","sec":"s16"},{"id":"fc-d187-9053af","poly":"dermato","fiche":"d187","front":"Tacrolimus topique : quel effet indésirable fréquent ?","back":"**Brûlures**, le plus souvent transitoires, surtout chez l'adulte.","prio":"P3","sec":"s16"},{"id":"fc-d187-2ff70e","poly":"dermato","fiche":"d187","front":"Dermatite atopique en échec : quelles erreurs d'application du traitement rechercher ?","back":"Une **quantité insuffisante**, un **arrêt trop tôt** (avant disparition de l'inflammation), un dermocorticoïde **trop faible**.","prio":"P1","sec":"s17"},{"id":"fc-d187-073865","poly":"dermato","fiche":"d187","front":"Dermatite atopique en échec : quelles complications rechercher ?","back":"**Infection** et **eczéma de contact** (possible même aux dermocorticoïdes).","prio":"P2","sec":"s17"},{"id":"fc-d187-2e4236","poly":"dermato","fiche":"d187","front":"Corticophobie : pourquoi la rechercher systématiquement ?","back":"Très répandue (patients et soignants), **non abordée spontanément**, elle mène à une **mauvaise observance**.","prio":"P2","sec":"s17"},{"id":"fc-d187-89d61a","poly":"dermato","fiche":"d187","front":"Dermocorticoïdes : quelles fausses croyances démonter ?","back":"Effets des corticoïdes oraux, peau abîmée, asthme qui « sort ».","prio":"P3","sec":"s17"},{"id":"fc-d187-394dc3","poly":"dermato","fiche":"d187","front":"Dermocorticoïdes bien prescrits : quand surviennent les effets indésirables ?","back":"Traitement **prolongé**, DC **forts ou très forts**, **grandes surfaces**, peau altérée et/ou **occlusion**.","prio":"P2","sec":"s17"},{"id":"fc-d187-a010cd","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quand hospitaliser en dermatologie ?","back":"Forme **grave**, **échec** thérapeutique, **complication** (infection grave surtout herpétique), traitement systémique envisagé.","prio":"P2","sec":"s17"},{"id":"fc-d187-30e9b4","poly":"dermato","fiche":"d187","front":"Dermatite atopique sévère : quels traitements systémiques ?","back":"**Photothérapie**, **ciclosporine**, **dupilumab**, **inhibiteurs de JAK**.","prio":"P2","sec":"s17"},{"id":"fc-d187-dd7f39","poly":"dermato","fiche":"d187","front":"Dermatite atopique : pourquoi une prise en charge psychologique ?","back":"Qualité de vie altérée, et le **stress** peut déclencher des poussées.","prio":"P3","sec":"s17"},{"id":"fc-d187-1ce9f6","poly":"dermato","fiche":"d187","front":"Dermatite atopique : faut-il un antibiotique pour une simple colonisation ou un suintement ?","back":"**Non**.","prio":"P2","sec":"s18"},{"id":"fc-d187-6a092a","poly":"dermato","fiche":"d187","front":"Dermatite atopique surinfectée grave : quelle conduite ?","back":"**Hospitalisation** en dermatologie.","prio":"P3","sec":"s18"},{"id":"fc-d187-05538f","poly":"dermato","fiche":"d187","front":"Eczéma allergique de contact : quel mécanisme ?","back":"Activation de **lymphocytes T** après contact cutané avec des substances chimiques exogènes.","prio":"P1","sec":"s20"},{"id":"fc-d187-88dbbe","poly":"dermato","fiche":"d187","front":"Eczéma de contact : comment s'appellent les petites molécules sensibilisantes ?","back":"Les **haptènes**.","prio":"P1","sec":"s20"},{"id":"fc-d187-06e74d","poly":"dermato","fiche":"d187","front":"Qu'est-ce que la photo-allergie de contact ?","back":"Eczéma dû à un allergène qui ne sensibilise **qu'après irradiation UV**.","prio":"P2","sec":"s20"},{"id":"fc-d187-cfd6a4","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quel type d'hypersensibilité ?","back":"**Retardée à médiation cellulaire** (type Th1), en **deux phases**.","prio":"P2","sec":"s20"},{"id":"fc-d187-b748cb","poly":"dermato","fiche":"d187","front":"Eczéma de contact : que se passe-t-il lors de la phase de sensibilisation ?","back":"Cellules de **Langerhans** captent l'allergène, migrent au ganglion et activent des LT naïfs en **LT mémoires** ; asymptomatique.","prio":"P3","sec":"s20"},{"id":"fc-d187-8b8bbe","poly":"dermato","fiche":"d187","front":"Eczéma de contact : combien de temps dure la phase de sensibilisation ?","back":"De **quelques jours à plusieurs années**.","prio":"P3","sec":"s20"},{"id":"fc-d187-93b5b2","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quel délai de la phase de révélation ?","back":"**24 à 48 heures** après un nouveau contact avec le même allergène.","prio":"P2","sec":"s20"},{"id":"fc-d187-e16403","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quel rôle jouent les irritants ?","back":"Ils altèrent la **barrière cutanée** et facilitent l'entrée des allergènes.","prio":"P3","sec":"s20"},{"id":"fc-d187-45f6a5","poly":"dermato","fiche":"d187","front":"Eczéma aigu : quelles sont les quatre phases ?","back":"**Érythémateuse**, **vésiculeuse**, **suintante**, **croûteuse** ou desquamative.","prio":"P1","sec":"s21"},{"id":"fc-d187-47e3fc","poly":"dermato","fiche":"d187","front":"Eczéma aigu : comment guérit-il ?","back":"**Sans cicatrice**.","prio":"P1","sec":"s21"},{"id":"fc-d187-6c609a","poly":"dermato","fiche":"d187","front":"Eczéma aigu : quel symptôme accompagne les lésions ?","back":"Un **prurit** important (lésions très prurigineuses).","prio":"P2","sec":"s21"},{"id":"fc-d187-439409","poly":"dermato","fiche":"d187","front":"Eczéma aigu en phase érythémateuse : quel aspect ?","back":"Placard rouge, œdémateux, à **contours émiettés**.","prio":"P2","sec":"s21"},{"id":"fc-d187-20593c","poly":"dermato","fiche":"d187","front":"Eczéma : où prend-il un aspect œdémateux ?","back":"Au **visage** (surtout **paupières**), aux extrémités des membres, aux organes génitaux.","prio":"P2","sec":"s21"},{"id":"fc-d187-5fbe61","poly":"dermato","fiche":"d187","front":"Qu'est-ce que la dysidrose ?","back":"Eczéma des **paumes et plantes** à vésicules dures, enchâssées (couche cornée épaisse).","prio":"P2","sec":"s21"},{"id":"fc-d187-e2b67b","poly":"dermato","fiche":"d187","front":"Eczéma des zones photo-exposées : qu'évoque-t-il ?","back":"Une **photosensibilisation**.","prio":"P2","sec":"s21"},{"id":"fc-d187-164331","poly":"dermato","fiche":"d187","front":"Eczéma chronique des paumes et plantes : quel aspect ?","back":"Lésions souvent **hyperkératosiques et fissuraires** (kératodermie palmo-plantaire).","prio":"P3","sec":"s21"},{"id":"fc-d187-2e0127","poly":"dermato","fiche":"d187","front":"Eczéma : quels signes histologiques ?","back":"**Spongiose** (vésicules intra-épidermiques) + **exocytose** + œdème et infiltrat lymphocytaire du derme.","prio":"P3","sec":"s21"},{"id":"fc-d187-b86e67","poly":"dermato","fiche":"d187","front":"Eczéma : quand faire une biopsie ?","back":"Seulement en cas de **doute diagnostique**.","prio":"P3","sec":"s21"},{"id":"fc-d187-9bc1a3","poly":"dermato","fiche":"d187","front":"Dermatite irritative : quel mécanisme ?","back":"Agressions **physiques ou chimiques directes**, **sans mécanisme immunologique**.","prio":"P2","sec":"s22"},{"id":"fc-d187-627588","poly":"dermato","fiche":"d187","front":"Dermatite irritative versus eczéma de contact : quelle proportion de sujets exposés atteints ?","back":"Irritation : la **majorité** ; eczéma de contact : **quelques sujets**.","prio":"P2","sec":"s22"},{"id":"fc-d187-8b16c9","poly":"dermato","fiche":"d187","front":"Dermatite irritative : quel délai d'apparition ?","back":"**Rapide** : minutes ou heures après l'exposition.","prio":"P3","sec":"s22"},{"id":"fc-d187-d90f59","poly":"dermato","fiche":"d187","front":"Dermatite irritative versus eczéma de contact : quels bords et quel symptôme ?","back":"Irritation : bords **nets**, **brûlure** ; eczéma : bords **émiettés**, **prurit**.","prio":"P2","sec":"s22"},{"id":"fc-d187-9356f6","poly":"dermato","fiche":"d187","front":"Eczéma de contact : la topographie se limite-t-elle à la zone de contact ?","back":"**Non** : il déborde, lésions à distance possibles (irritation : limitée au contact).","prio":"P2","sec":"s22"},{"id":"fc-d187-891c5d","poly":"dermato","fiche":"d187","front":"Dermatite irritative : peut-elle se compliquer d'eczéma de contact ?","back":"**Oui** : en abîmant la barrière, elle facilite l'entrée des allergènes.","prio":"P2","sec":"s22"},{"id":"fc-d187-82c11c","poly":"dermato","fiche":"d187","front":"Dermatite atopique et eczéma de contact associés : quand y penser ?","back":"Dermatite atopique **résistante** à un traitement bien conduit ou de **topographie inhabituelle**.","prio":"P3","sec":"s22"},{"id":"fc-d187-1d8fe4","poly":"dermato","fiche":"d187","front":"Eczéma de contact : la recherche de l'allergène est-elle facultative ?","back":"**Non**, elle est **indispensable** : interrogatoire +++, examen, **tests épicutanés**.","prio":"P1","sec":"s23"},{"id":"fc-d187-55c90d","poly":"dermato","fiche":"d187","front":"Eczéma de contact : que préciser à l'interrogatoire ?","back":"**Topographie initiale**, **circonstances** (profession, loisirs, cosmétiques…), **chronologie** (week-ends, vacances), **topiques** utilisés.","prio":"P2","sec":"s23"},{"id":"fc-d187-7a998c","poly":"dermato","fiche":"d187","front":"Eczéma du lobule des oreilles, du poignet ou de l'ombilic : quel allergène évoquer ?","back":"Le **nickel**.","prio":"P1","sec":"s23"},{"id":"fc-d187-5cba05","poly":"dermato","fiche":"d187","front":"Eczéma du visage, des paupières, du cou : quels allergènes évoquer ?","back":"**Cosmétiques**, **vernis à ongles** (manuporté), produits volatils : parfums, peintures, végétaux (aéroporté).","prio":"P2","sec":"s23"},{"id":"fc-d187-c2c0a1","poly":"dermato","fiche":"d187","front":"Eczéma du dos du pied : quel allergène évoquer ?","back":"Le **chrome du cuir** des chaussures.","prio":"P3","sec":"s23"},{"id":"fc-d187-d7e430","poly":"dermato","fiche":"d187","front":"Eczéma de la plante du pied : quel allergène évoquer ?","back":"Les **agents de vulcanisation du caoutchouc**.","prio":"P3","sec":"s23"},{"id":"fc-d187-de3763","poly":"dermato","fiche":"d187","front":"Eczéma du tronc et des plis : quel allergène évoquer ?","back":"Les **colorants textiles**.","prio":"P3","sec":"s23"},{"id":"fc-d187-eddd28","poly":"dermato","fiche":"d187","front":"Eczéma de contact professionnel : quel tableau de maladie professionnelle ?","back":"Le **tableau général 65**.","prio":"P1","sec":"s23"},{"id":"fc-d187-f396df","poly":"dermato","fiche":"d187","front":"Eczéma de contact professionnel : quels arguments cliniques ?","back":"Début et prédominance aux **mains**, **amélioration pendant les congés**.","prio":"P1","sec":"s23"},{"id":"fc-d187-2b11db","poly":"dermato","fiche":"d187","front":"Eczéma professionnel du bâtiment : quels allergènes ?","back":"**Chrome** (ciment), cobalt, résines époxy, formaldéhyde, térébenthine, caoutchouc.","prio":"P2","sec":"s23"},{"id":"fc-d187-6ff8f3","poly":"dermato","fiche":"d187","front":"Eczéma de contact chez les coiffeurs : quel allergène des teintures ?","back":"La **paraphénylènediamine** (aussi thioglycolate, persulfate d'ammonium, caoutchouc, nickel).","prio":"P3","sec":"s23"},{"id":"fc-d187-1a0077","poly":"dermato","fiche":"d187","front":"Eczéma de contact chez les professionnels de santé : quels allergènes ?","back":"Antiseptiques, antibiotiques, AINS, anesthésiques locaux, **caoutchouc** des gants, acrylates.","prio":"P3","sec":"s23"},{"id":"fc-d187-3b05c3","poly":"dermato","fiche":"d187","front":"Eczéma de contact chez les horticulteurs : quels allergènes ?","back":"**Lactones sesquiterpéniques** (chrysanthèmes, primevères), pesticides, gants.","prio":"P3","sec":"s23"},{"id":"fc-d187-418a09","poly":"dermato","fiche":"d187","front":"Eczéma aux médicaments topiques : quels allergènes surtout ?","back":"**Néomycine**, antiseptiques, sparadrap (**colophane**), antiprurigineux, **baume du Pérou**, AINS.","prio":"P2","sec":"s23"},{"id":"fc-d187-0245a3","poly":"dermato","fiche":"d187","front":"Allergie aux dermocorticoïdes : quand l'évoquer ?","back":"Dermatose corticosensible qui **s'eczématise**, ne s'améliore pas ou **s'aggrave** sous traitement.","prio":"P1","sec":"s23"},{"id":"fc-d187-2295f1","poly":"dermato","fiche":"d187","front":"Allergie aux dermocorticoïdes : sur quoi reposent les réactions croisées ?","back":"Sur la **classe chimique**, sans rapport avec le niveau d'activité.","prio":"P2","sec":"s23"},{"id":"fc-d187-3bd504","poly":"dermato","fiche":"d187","front":"Eczéma aux cosmétiques : quels allergènes ?","back":"**Parfums**, conservateurs (**méthylisothiazolinone**), excipients, baume du Pérou, paraphénylènediamine, vernis.","prio":"P2","sec":"s23"},{"id":"fc-d187-0593b8","poly":"dermato","fiche":"d187","front":"Eczéma photo-allergique : quels allergènes ?","back":"**Kétoprofène** et autres AINS, phénothiazines, **filtres solaires chimiques**, certains végétaux.","prio":"P2","sec":"s23"},{"id":"fc-d187-0c601e","poly":"dermato","fiche":"d187","front":"Eczéma photo-allergique : quel test de confirmation ?","back":"Les **photo-patch tests** (patch tests puis irradiation UVA).","prio":"P2","sec":"s23"},{"id":"fc-d187-0ae2ae","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quels sont les allergènes les plus fréquents ?","back":"Les **métaux**, en particulier le **nickel**.","prio":"P1","sec":"s23"},{"id":"fc-d187-324834","poly":"dermato","fiche":"d187","front":"Eczéma de contact : pourquoi certains deviennent-ils chroniques ?","back":"Allergènes **ubiquitaires**, dont l'éviction est difficile.","prio":"P2","sec":"s23"},{"id":"fc-d187-a7086d","poly":"dermato","fiche":"d187","front":"Patch tests : quel est leur intérêt ?","back":"**Indispensables** pour confirmer l'allergène et permettre son éviction.","prio":"P2","sec":"s24"},{"id":"fc-d187-2179fd","poly":"dermato","fiche":"d187","front":"Patch tests : quand les réaliser ?","back":"**À distance de la poussée (1 mois)**, en milieu spécialisé.","prio":"P2","sec":"s24"},{"id":"fc-d187-f4e1f5","poly":"dermato","fiche":"d187","front":"Patch tests : quelle technique d'application ?","back":"Allergènes **sous occlusion** sur le **dos** pendant **48 heures**.","prio":"P3","sec":"s24"},{"id":"fc-d187-b4897b","poly":"dermato","fiche":"d187","front":"Patch tests : quand se font les lectures ?","back":"À **48 h** (30 min après retrait), à **72 ou 96 h**, parfois à **7 jours** (corticoïdes).","prio":"P3","sec":"s24"},{"id":"fc-d187-73f55a","poly":"dermato","fiche":"d187","front":"Patch test ++ : quel aspect ?","back":"**Érythème**, **papule** et **vésicules**.","prio":"P3","sec":"s24"},{"id":"fc-d187-f89e0c","poly":"dermato","fiche":"d187","front":"Batterie standard européenne : combien de substances ?","back":"Une **trentaine**, les plus souvent en cause.","prio":"P3","sec":"s24"},{"id":"fc-d187-dfe31b","poly":"dermato","fiche":"d187","front":"Patch test positif : signe-t-il le coupable ?","back":"**Non** : discuter sa **pertinence** pour l'épisode actuel (sensibilisation ancienne possible).","prio":"P2","sec":"s24"},{"id":"fc-d187-90db90","poly":"dermato","fiche":"d187","front":"Patch test négatif : élimine-t-il une allergie de contact ?","back":"**Non** : d'autres tests sont possibles (applications répétées au pli du coude).","prio":"P3","sec":"s24"},{"id":"fc-d187-4da57b","poly":"dermato","fiche":"d187","front":"Eczéma de contact après éviction de l'allergène : quelle évolution ?","back":"Guérison **sans cicatrice** en **7 à 15 jours**.","prio":"P1","sec":"s25"},{"id":"fc-d187-54f868","poly":"dermato","fiche":"d187","front":"Eczéma de contact avec contact persistant : quelle évolution ?","back":"Les lésions deviennent **chroniques**.","prio":"P2","sec":"s25"},{"id":"fc-d187-904f75","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quelles complications ?","back":"Peu fréquentes : **impétiginisation**, **érythrodermie**.","prio":"P2","sec":"s25"},{"id":"fc-d187-95b6a9","poly":"dermato","fiche":"d187","front":"Impétiginisation d'un eczéma : quels signes ?","back":"**Pus** et **croûtes jaunâtres**, parfois adénopathies et fièvre.","prio":"P2","sec":"s25"},{"id":"fc-d187-194f6c","poly":"dermato","fiche":"d187","front":"Érythrodermie : quelle définition ?","back":"Érythème diffus prurigineux sur **plus de 90 %** de la surface corporelle, chronique (> 6 semaines), avec fièvre, frissons, AEG.","prio":"P2","sec":"s25"},{"id":"fc-d187-456721","poly":"dermato","fiche":"d187","front":"Eczéma professionnel chronique des mains : quelles mesures avec le médecin du travail ?","back":"**Adaptation** ou changement de poste, **protection** vestimentaire, **déclaration** de maladie professionnelle.","prio":"P2","sec":"s27"},{"id":"fc-d187-bab405","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quel dermocorticoïde et quel schéma ?","back":"Activité **forte à très forte**, **1 application/jour**, pendant **1 à 2 semaines**.","prio":"P1","sec":"s26"},{"id":"fc-d187-be600c","poly":"dermato","fiche":"d187","front":"Eczéma de contact avec prurit important : quel antihistaminique ?","back":"Un **anti-H1 de 1re génération** quelques jours (les non sédatifs sont inutiles).","prio":"P2","sec":"s26"},{"id":"fc-d187-e855b7","poly":"dermato","fiche":"d187","front":"Eczéma impétiginisé : quel traitement ?","back":"Antibiotique **général anti-Gram positif** (pristinamycine ou amoxicilline-acide clavulanique), sans retarder le dermocorticoïde.","prio":"P2","sec":"s26"},{"id":"fc-d187-61ee77","poly":"dermato","fiche":"d187","front":"Eczéma de contact : pourquoi l'éviction de l'allergène est-elle indispensable ?","back":"La **désensibilisation est impossible**.","prio":"P1","sec":"s26"},{"id":"fc-d187-0cd7f1","poly":"dermato","fiche":"d187","front":"Eczéma de contact : quelles informations remettre au patient ?","back":"Information **orale et écrite** avec la **liste des produits à éviter** ; protection vestimentaire si éviction impossible.","prio":"P2","sec":"s26"},{"id":"fc-d187-c81f48","poly":"dermato","fiche":"d187","front":"Allergie de contact à un dermocorticoïde : quelle contre-indication ?","back":"Toute sa **classe chimique**, en local **et par voie générale** (risque de toxidermie).","prio":"P1","sec":"s26"},{"id":"fc-d187-8765db","poly":"dermato","fiche":"d187","front":"Eczéma de contact professionnel : quelles mesures en milieu de travail ?","back":"Prévention **primaire et secondaire**, individuelle et collective.","prio":"P2","sec":"s27"},{"id":"fc-d187-8002fb","poly":"dermato","fiche":"d187","front":"Dermatites d'irritation des mains : quelle fréquence par rapport à l'eczéma allergique ?","back":"**Plus fréquentes**, et elles peuvent en favoriser l'apparition.","prio":"P3","sec":"s27"},{"id":"fc-d187-936027","poly":"dermato","fiche":"d187","front":"Dermatite atopique : quel est le traitement de référence au long cours ?","back":"**Dermocorticoïdes** et **émollients**, avec éducation thérapeutique contre la **corticophobie**.","prio":"P1","sec":"s28"},{"id":"fc-d187-d01c7f","poly":"dermato","fiche":"d187","front":"Urticaire aiguë : quelle mesure au long cours ?","back":"**Éviction** du ou des facteurs déclenchants identifiés.","prio":"P2","sec":"s28"},{"id":"fc-d194-4f4648","poly":"dermato","fiche":"d194","front":"Lupus érythémateux : quel type de maladie auto-immune ?","back":"Maladie **auto-immune non spécifique d'organe**, réponse dirigée contre des composants du **noyau** cellulaire (**AAN**).","prio":"P1","sec":"s1"},{"id":"fc-d194-ec30cd","poly":"dermato","fiche":"d194","front":"Lupus cutané (LEC) vs systémique (LES) : quelle différence ?","back":"LEC : **peau seule** ; LES : au moins **un organe atteint en plus de la peau** (dit aussi disséminé).","prio":"P1","sec":"s1"},{"id":"fc-d194-86de5a","poly":"dermato","fiche":"d194","front":"Lupus : définition d'une lésion cutanée spécifique ?","back":"Lésion vue **seulement dans le lupus**, avec une **dermite d'interface** à l'histologie.","prio":"P1","sec":"s1"},{"id":"fc-d194-503abf","poly":"dermato","fiche":"d194","front":"Lupus : définition d'une lésion cutanée non spécifique ?","back":"Lésion vue **aussi dans d'autres maladies**.","prio":"P1","sec":"s1"},{"id":"fc-d194-7b43ff","poly":"dermato","fiche":"d194","front":"Lupus aigu : fréquence d'association au LES et des AAN ?","back":"Associé au LES dans **90 %** des cas ; AAN dans **100 %**.","prio":"P1","sec":"s1"},{"id":"fc-d194-51bed5","poly":"dermato","fiche":"d194","front":"Lupus subaigu : fréquence d'association au LES et des AAN ?","back":"Associé au LES dans **50 %** des cas ; AAN dans **50 %**.","prio":"P1","sec":"s1"},{"id":"fc-d194-a04039","poly":"dermato","fiche":"d194","front":"Lupus chronique : fréquence d'association au LES et des AAN ?","back":"Associé au LES dans **15 %** des cas ; AAN dans **20 %**.","prio":"P1","sec":"s1"},{"id":"fc-d194-211a5f","poly":"dermato","fiche":"d194","front":"LES : combien de critères ACR (1997) faut-il pour le retenir ?","back":"**Au moins quatre** critères ACR.","prio":"P1","sec":"s1"},{"id":"fc-d194-f8502a","poly":"dermato","fiche":"d194","front":"Classification SLICC 2012 : quel critère ACR a été retiré et pourquoi ?","back":"La **photosensibilité**, qui faisait **doublon** avec le « **rash malaire** ».","prio":"P2","sec":"s1"},{"id":"fc-d194-f267dc","poly":"dermato","fiche":"d194","front":"Lupus : quels déficits génétiques causent des lupus de l'enfant ?","back":"Déficits en **C1q**, **C2** et **C4**.","prio":"P3","sec":"s1"},{"id":"fc-d194-2210c4","poly":"dermato","fiche":"d194","front":"Lupus : quels facteurs environnementaux interviennent ?","back":"**Soleil** (UVB > UVA), **EBV** chez l'enfant, **tabac**, stress, **médicaments inducteurs**, **œstrogènes**.","prio":"P2","sec":"s1"},{"id":"fc-d194-a1d06c","poly":"dermato","fiche":"d194","front":"Lupus : quels mécanismes de perte de tolérance au soi ?","back":"Auto-anticorps, **complexes immuns**, mauvaise élimination des **cellules apoptotiques**, LT/LB autoréactifs, **interféron alpha**, complément.","prio":"P3","sec":"s1"},{"id":"fc-d194-b4c29c","poly":"dermato","fiche":"d194","front":"Lupus : quelles cellules produisent l'interféron alpha ?","back":"Les **cellules dendritiques plasmacytoïdes** activées.","prio":"P3","sec":"s1"},{"id":"fc-d194-080696","poly":"dermato","fiche":"d194","front":"Lupus : sex-ratio et prévalence en France ?","back":"**Neuf femmes pour un homme** ; prévalence **47/100 000** ; plus fréquent chez le **sujet noir**.","prio":"P2","sec":"s1"},{"id":"fc-d194-1f4931","poly":"dermato","fiche":"d194","front":"Lupus systémique : quel terrain préférentiel ?","back":"La **femme en période d'activité ovarienne**.","prio":"P2","sec":"s1"},{"id":"fc-d194-bfb0d5","poly":"dermato","fiche":"d194","front":"Lupus systémique : quel mode évolutif ?","back":"Maladie **chronique** par **poussées** entrecoupées de **rémissions**.","prio":"P2","sec":"s1"},{"id":"fc-d194-681e69","poly":"dermato","fiche":"d194","front":"Lupus : quelles caractéristiques des lésions spécifiques vis-à-vis du soleil ?","back":"**Photosensibles** (déclenchées par le soleil) et **photodistribuées**.","prio":"P1","sec":"s2"},{"id":"fc-d194-35cd22","poly":"dermato","fiche":"d194","front":"Lupus : quelles zones photodistribuées ?","back":"**Visage**, **oreilles**, **décolleté**, **mains**.","prio":"P1","sec":"s2"},{"id":"fc-d194-691c08","poly":"dermato","fiche":"d194","front":"Lupus : comment appelle-t-on la topographie des lésions du visage ?","back":"**Vespertilio** (« **masque de loup** », « **ailes de papillon** »).","prio":"P1","sec":"s2"},{"id":"fc-d194-6d7821","poly":"dermato","fiche":"d194","front":"Lupus aigu : quel aspect des lésions cutanées ?","back":"Macules/papules **érythémateuses** en plaques, **souvent en vespertilio** ou au **dos des mains**, parfois **nécrotiques**.","prio":"P1","sec":"s2"},{"id":"fc-d194-19626e","poly":"dermato","fiche":"d194","front":"Lupus aigu : quelle forme éruptive étendue ?","back":"L'**éruption maculo-papuleuse lupique**.","prio":"P3","sec":"s2"},{"id":"fc-d194-3246a8","poly":"dermato","fiche":"d194","front":"Lupus aigu : quelles atteintes de la muqueuse buccale ?","back":"**Chéilite lupique** (lèvres inflammatoires) et **érosions superficielles du palais dur**.","prio":"P2","sec":"s2"},{"id":"fc-d194-77c356","poly":"dermato","fiche":"d194","front":"Lupus subaigu : quel aspect des lésions ?","back":"Lésions **annulaires** ou **psoriasiformes**, photosensibilité souvent marquée.","prio":"P1","sec":"s2"},{"id":"fc-d194-1fa8be","poly":"dermato","fiche":"d194","front":"Lupus subaigu : quel auto-anticorps caractéristique ?","back":"Anticorps **anti-Ro/SSA**.","prio":"P1","sec":"s2"},{"id":"fc-d194-7310da","poly":"dermato","fiche":"d194","front":"Lupus subaigu : quels médicaments peuvent l'induire ?","back":"**Terbinafine**, **griséofulvine**, **IPP**, **IEC**, **anti-TNFα**, **antiépileptiques**…","prio":"P1","sec":"s2"},{"id":"fc-d194-b8f3b3","poly":"dermato","fiche":"d194","front":"Lupus chronique : quelle forme est la plus fréquente ?","back":"Le **lupus discoïde**.","prio":"P1","sec":"s2"},{"id":"fc-d194-5bb16f","poly":"dermato","fiche":"d194","front":"Lupus discoïde : quelles trois composantes lésionnelles ?","back":"**Érythème**, **hyperkératose**, **atrophie** à des degrés divers.","prio":"P1","sec":"s2"},{"id":"fc-d194-b83a2f","poly":"dermato","fiche":"d194","front":"Lupus discoïde : quel aspect et quelle topographie ?","back":"Lésions érythémato-squameuses, atrophiques, télangiectasiques, dyschromiques, **orifices pilaires dilatés** ; **visage** et **oreilles**.","prio":"P2","sec":"s2"},{"id":"fc-d194-ba16b8","poly":"dermato","fiche":"d194","front":"Lupus discoïde du cuir chevelu : quelle conséquence ?","back":"**Alopécie cicatricielle**.","prio":"P1","sec":"s2"},{"id":"fc-d194-e800e5","poly":"dermato","fiche":"d194","front":"Lupus discoïde : quelle atteinte buccale ?","back":"Érosions avec **réseau blanchâtre**, aspect identique au **lichen plan** muqueux.","prio":"P2","sec":"s2"},{"id":"fc-d194-c44208","poly":"dermato","fiche":"d194","front":"Lupus discoïde : pronostic systémique et esthétique ?","back":"**Peu associé au LES**, mais **séquelles esthétiques** importantes (atrophie, dyschromie).","prio":"P1","sec":"s2"},{"id":"fc-d194-ba32b6","poly":"dermato","fiche":"d194","front":"Lupus néonatal : quel mécanisme ?","back":"Passage **transplacentaire** des anticorps maternels (anti-Ro/SSA et/ou anti-Ro/SSB selon le Collège).","prio":"P2","sec":"s2"},{"id":"fc-d194-8f6e76","poly":"dermato","fiche":"d194","front":"Lupus néonatal : quel risque cardiaque ?","back":"**Bloc auriculoventriculaire** au **2ᵉ trimestre** de grossesse, **définitif**.","prio":"P1","sec":"s2"},{"id":"fc-d194-704dd1","poly":"dermato","fiche":"d194","front":"Lupus néonatal : quel risque cutané ?","back":"Lésions **annulaires** de lupus subaigu dans les **3 premiers mois**, qui **disparaissent spontanément**.","prio":"P2","sec":"s2"},{"id":"fc-d194-f762ec","poly":"dermato","fiche":"d194","front":"Lupus tumidus : quel aspect ?","back":"Papules **érythémateuses et œdémateuses** (ex. : dos).","prio":"P3","sec":"s2"},{"id":"fc-d194-a79060","poly":"dermato","fiche":"d194","front":"Panniculite lupique : quel aspect ?","back":"**Nodules sous-cutanés** laissant une cicatrice atrophique **en cupule**.","prio":"P3","sec":"s2"},{"id":"fc-d194-5465e5","poly":"dermato","fiche":"d194","front":"Lupus verruqueux et lupus engelure : quels aspects ?","back":"Verruqueux : lésions squameuses **hypertrophiques** ; engelure : lésions papulo-squameuses du **dos des mains** type engelures.","prio":"P3","sec":"s2"},{"id":"fc-d194-c4edfb","poly":"dermato","fiche":"d194","front":"Lupus aigu : comment évolue l'atteinte cutanée par rapport au LES ?","back":"Souvent associée aux atteintes systémiques, d'**évolution parallèle**.","prio":"P1","sec":"s3"},{"id":"fc-d194-553bab","poly":"dermato","fiche":"d194","front":"Lupus aigu : quels éléments systémiques et biologiques l'accompagnent ?","back":"Atteinte d'organe (**glomérulonéphrite**, **péricardite**, cytopénie auto-immune), **hypocomplémentémie**, **anti-ADN natifs**.","prio":"P1","sec":"s3"},{"id":"fc-d194-8e27a8","poly":"dermato","fiche":"d194","front":"Lupus systémique : comment se présente l'atteinte rénale (objectifs) ?","back":"**Œdèmes** et **bandelette urinaire positive**.","prio":"P2","sec":"s3"},{"id":"fc-d194-f86cea","poly":"dermato","fiche":"d194","front":"Lupus systémique : principales atteintes à repérer ?","back":"**Vespertilio**, **photosensibilité**, **Raynaud**, **polyarthrite**, **sérite**, **glomérulonéphrite**.","prio":"P2","sec":"s3"},{"id":"fc-d194-b204b5","poly":"dermato","fiche":"d194","front":"Critères ACR : quels critères cutanéo-muqueux ?","back":"**Éruption malaire**, **lupus discoïde**, **photosensibilité**, **ulcérations** orales ou nasopharyngées.","prio":"P2","sec":"s3"},{"id":"fc-d194-7f2ab1","poly":"dermato","fiche":"d194","front":"Critères ACR : quel critère articulaire ?","back":"**Arthrite non érosive** d'au moins **deux** articulations périphériques.","prio":"P2","sec":"s3"},{"id":"fc-d194-933334","poly":"dermato","fiche":"d194","front":"Critères ACR : quels critères séreux, rénal et neurologique ?","back":"**Pleurésie** ou **péricardite** ; **protéinurie > 0,5 g/j** ou **cylindrurie** ; **convulsions** ou **psychose**.","prio":"P2","sec":"s3"},{"id":"fc-d194-a97adc","poly":"dermato","fiche":"d194","front":"Critères ACR : quels critères hématologiques ?","back":"**Anémie hémolytique** ; ou leucopénie < 4000/µL (×2) ; ou lymphopénie < 1500/µL (×2) ; ou thrombopénie < 100 000/µL.","prio":"P3","sec":"s3"},{"id":"fc-d194-7a9c74","poly":"dermato","fiche":"d194","front":"Critères ACR : quels critères immunologiques (hors AAN) ?","back":"**Anti-ADN natif**, **anti-Sm**, ou **anti-phospholipides**.","prio":"P2","sec":"s3"},{"id":"fc-d194-8bb09e","poly":"dermato","fiche":"d194","front":"Lupus : quelles lésions vasculaires non spécifiques ?","back":"**Raynaud** ; **vascularite urticarienne** (inflammatoire) ; atteinte **thrombotique** (livedo, nécrose, purpura) souvent liée au **SAPL**.","prio":"P2","sec":"s3"},{"id":"fc-d194-aab554","poly":"dermato","fiche":"d194","front":"Lupus : quelle alopécie non spécifique ?","back":"**Alopécie diffuse, non cicatricielle** (à l'inverse du discoïde).","prio":"P2","sec":"s3"},{"id":"fc-d194-416986","poly":"dermato","fiche":"d194","front":"Lupus avec atteinte cutanée : quels auto-anticorps au bilan initial ?","back":"**AAN**, **anti-ADN natifs**, anticorps anti-antigènes **nucléaires solubles**.","prio":"P2","sec":"s4"},{"id":"fc-d194-ba6aac","poly":"dermato","fiche":"d194","front":"Lupus : quel bilan du complément ?","back":"**C3**, **C4**, **CH50**.","prio":"P2","sec":"s4"},{"id":"fc-d194-3f6608","poly":"dermato","fiche":"d194","front":"Lupus : quels anticorps anti-phospholipides rechercher ?","back":"**Anticoagulant circulant lupique**, **anticardiolipine** IgG/IgM, **anti-β2GPI** IgG/IgM.","prio":"P2","sec":"s4"},{"id":"fc-d194-2c12a8","poly":"dermato","fiche":"d194","front":"Lupus : quel bilan sang, urines et autres au bilan initial ?","back":"**NFS**, ionogramme, **créatininémie**, **protéinurie/créatininurie**, **ECBU**, **ECG**, **radio thoracique**.","prio":"P2","sec":"s4"},{"id":"fc-d194-4be874","poly":"dermato","fiche":"d194","front":"Lupus cutané : quel examen confirme le diagnostic ?","back":"**Biopsie cutanée** avec **immunofluorescence directe**.","prio":"P2","sec":"s4"},{"id":"fc-d194-301db8","poly":"dermato","fiche":"d194","front":"Lupus : que montre l'histologie standard ?","back":"**Dermite de l'interface** (nécrose des kératinocytes basaux + infiltrat lymphocytaire), atrophie épidermique, hyperkératose, **mucine**.","prio":"P2","sec":"s4"},{"id":"fc-d194-88108c","poly":"dermato","fiche":"d194","front":"Lupus : que montre l'immunofluorescence directe ?","back":"Dépôts **granuleux d'IgG et de C3** à la **JDE** (90 % des aigus et chroniques, 60 % des subaigus).","prio":"P2","sec":"s4"},{"id":"fc-d194-022562","poly":"dermato","fiche":"d194","front":"Lupus cutané : est-ce forcément un LES ?","back":"**Non** : le LEC touche **uniquement la peau**.","prio":"P1","sec":"s5"},{"id":"fc-d194-57746f","poly":"dermato","fiche":"d194","front":"Lupus : toute alopécie lupique est-elle cicatricielle ?","back":"**Non** : l'alopécie **diffuse** (non spécifique) **n'est pas** cicatricielle ; seule la discoïde l'est.","prio":"P2","sec":"s5"},{"id":"fc-d194-87a4a4","poly":"dermato","fiche":"d194","front":"Livedo avec nécrose ou purpura chez un lupique : quelle signification ?","back":"Atteinte vasculaire **thrombotique**, souvent associée au **SAPL** (lésion non spécifique).","prio":"P2","sec":"s5"},{"id":"fc-d194-68047c","poly":"dermato","fiche":"d194","front":"SAPL : définition ?","back":"**Thrombose** veineuse ou artérielle ou **accident obstétrical** + **anticorps anti-phospholipides** confirmés à **12 semaines** d'intervalle.","prio":"P1","sec":"s6"},{"id":"fc-d194-ece7e2","poly":"dermato","fiche":"d194","front":"SAPL : quelle règle diagnostique et quels critères ?","back":"**Un critère clinique + un critère biologique** ; critères de **Sydney (2006)**.","prio":"P1","sec":"s6"},{"id":"fc-d194-df0b75","poly":"dermato","fiche":"d194","front":"SAPL : quelles deux formes selon le contexte ?","back":"SAPL **primaire** et SAPL **associé au lupus** (secondaire).","prio":"P1","sec":"s6"},{"id":"fc-d194-4a0f18","poly":"dermato","fiche":"d194","front":"SAPL : critère clinique de thrombose ?","back":"Thrombose artérielle, veineuse ou de la **microcirculation**, confirmée par imagerie ou histologie (**sans inflammation pariétale**).","prio":"P2","sec":"s6"},{"id":"fc-d194-8be0db","poly":"dermato","fiche":"d194","front":"SAPL : critères de morbidité obstétricale ?","back":"Mort fœtale inexpliquée **≥ 10 SA** ; ou **3 fausses couches** consécutives ; ou naissance prématurée à la **34ᵉ semaine** (éclampsie, RCIU, décollement placentaire).","prio":"P2","sec":"s6"},{"id":"fc-d194-0bcde2","poly":"dermato","fiche":"d194","front":"SAPL : critères biologiques ?","back":"**Anti-cardiolipides** IgG/IgM > 40 UGPL, **anti-β2GP1**, **anticoagulant lupique** ; au moins 2 fois à ≥ 12 semaines.","prio":"P2","sec":"s6"},{"id":"fc-d194-de7f16","poly":"dermato","fiche":"d194","front":"CAPS : définition ?","back":"Thromboses **multiples**, d'apparition **rapide**, surtout **microcirculatoires**, avec aPL et **défaillance multiviscérale**.","prio":"P2","sec":"s6"},{"id":"fc-d194-0d71d1","poly":"dermato","fiche":"d194","front":"CAPS : quelle mortalité ?","back":"**30 %**.","prio":"P2","sec":"s6"},{"id":"fc-d194-9ece5e","poly":"dermato","fiche":"d194","front":"SAPL « artériel » : quelle expression et quelles associations ?","back":"Surtout **neurologique** (AVC ischémiques, **chorée**) ; associé au **livedo**, aux **valvulopathies**, atteinte rénale micro-angiopathique.","prio":"P3","sec":"s6"},{"id":"fc-d194-bd1fd8","poly":"dermato","fiche":"d194","front":"SAPL obstétrical : quelles manifestations ?","back":"**≥ 3 fausses couches** avant 10 SA, mort fœtale, prématurité < 34 SA ; aussi **HRP**, syndrome **HELLP**.","prio":"P3","sec":"s6"},{"id":"fc-d194-e67d10","poly":"dermato","fiche":"d194","front":"SAPL : quel aspect du livedo ?","back":"Livedo **non infiltré**, à **grandes mailles ouvertes**, **asymétrique**, prédominant aux **fesses** et au **tronc**.","prio":"P2","sec":"s6"},{"id":"fc-d194-ff3b1d","poly":"dermato","fiche":"d194","front":"SAPL : autres signes cutanés que le livedo ?","back":"**Nécroses**, ulcérations, **hémorragies sous-unguéales en flammèches**, **anétodermie**.","prio":"P3","sec":"s6"},{"id":"fc-d194-f20896","poly":"dermato","fiche":"d194","front":"Anétodermie : définition ?","back":"Peau **fripée** par destruction du **tissu élastique**.","prio":"P3","sec":"s6"},{"id":"fc-d194-d5eafb","poly":"dermato","fiche":"d194","front":"CAPS : quels signes cutanés d'alerte ?","back":"Livedo, nécroses, **gangrène ischémique des extrémités**, **purpura en carte de géographie**, hémorragies en flammèches.","prio":"P2","sec":"s6"},{"id":"fc-d194-ef6da2","poly":"dermato","fiche":"d194","front":"Livedo à grandes mailles non infiltré : que rechercher ?","back":"Une **thrombophilie**, en particulier un **SAPL**.","prio":"P2","sec":"s6"},{"id":"fc-d194-c68fd6","poly":"dermato","fiche":"d194","front":"Lupus : quelles règles de photoprotection ?","back":"Pas de soleil de **12 h à 16 h**, **vêtements couvrants**, crème solaire **indice 50+**.","prio":"P2","sec":"s7"},{"id":"fc-d194-baaeac","poly":"dermato","fiche":"d194","front":"Lupus : quelle mesure concernant le tabac ?","back":"**Arrêt du tabac actif et passif**.","prio":"P2","sec":"s7"},{"id":"fc-d194-0172ac","poly":"dermato","fiche":"d194","front":"Lupus : quelle contraception est contre-indiquée ?","back":"Les **œstroprogestatifs**.","prio":"P1","sec":"s7"},{"id":"fc-d194-983560","poly":"dermato","fiche":"d194","front":"Lupus : quelles contraceptions possibles ?","back":"Microprogestatif **désogestrel** ; acétate de **chlormadinone** ou de **cyprotérone** ; **DIU au lévonorgestrel**.","prio":"P2","sec":"s7"},{"id":"fc-d194-d40dce","poly":"dermato","fiche":"d194","front":"Lupus aigu : quel traitement ?","back":"Celui de la **poussée de LES** (atteintes extradermatologiques), qui comprend l'**hydroxychloroquine**.","prio":"P2","sec":"s8"},{"id":"fc-d194-ca2bc4","poly":"dermato","fiche":"d194","front":"Lupus systémique : quelle molécule est la pierre angulaire du traitement ?","back":"L'**hydroxychloroquine**.","prio":"P1","sec":"s8"},{"id":"fc-d194-d9ad2e","poly":"dermato","fiche":"d194","front":"Lupus aigu : suffit-il de traiter l'atteinte cutanée ?","back":"**Non** : c'est la **poussée systémique** (LES) qu'il faut prendre en charge, pas seulement la peau.","prio":"P2","sec":"s8"},{"id":"fc-d194-705564","poly":"dermato","fiche":"d194","front":"Lupus subaigu ou chronique : but du traitement ?","back":"Faire régresser **au plus vite** l'inflammation pour prévenir les **séquelles pigmentaires ou atrophiques**.","prio":"P2","sec":"s9"},{"id":"fc-d194-9dcea9","poly":"dermato","fiche":"d194","front":"Lupus subaigu ou chronique : traitement local ?","back":"**Dermocorticoïdes**, classe choisie selon le **siège** et l'**intensité**.","prio":"P2","sec":"s9"},{"id":"fc-d194-026269","poly":"dermato","fiche":"d194","front":"Lupus subaigu ou chronique : traitement général de 1re ligne ?","back":"**Hydroxychloroquine** per os (antipaludéen de synthèse), souvent efficace.","prio":"P2","sec":"s9"},{"id":"fc-d194-d88f84","poly":"dermato","fiche":"d194","front":"Hydroxychloroquine dans le lupus cutané : quelle dose maximale ?","back":"Au maximum **6,5 mg/kg/j**, soit en général **400 mg/j** ; adaptable à la **concentration sérique**.","prio":"P2","sec":"s9"},{"id":"fc-d194-e59823","poly":"dermato","fiche":"d194","front":"Hydroxychloroquine : quand juger l'efficacité et quel taux de réponse ?","back":"Après **3 mois** ; efficace dans **60 %** des cas.","prio":"P2","sec":"s9"},{"id":"fc-d194-7039bb","poly":"dermato","fiche":"d194","front":"Lupus cutané en échec d'hydroxychloroquine : quelles options ?","back":"**Corticothérapie générale courte** (peu efficace), **tacrolimus topique**, **thalidomide**, **méthotrexate**.","prio":"P3","sec":"s9"},{"id":"fc-d194-94669d","poly":"dermato","fiche":"d194","front":"Lupus subaigu : quelle mesure étiologique envisager ?","back":"**Arrêter un médicament inducteur** (terbinafine, griséofulvine, IPP, IEC, anti-TNFα, antiépileptiques…).","prio":"P2","sec":"s9"},{"id":"fc-d194-c5967c","poly":"dermato","fiche":"d194","front":"Hydroxychloroquine : quel risque à long terme ?","back":"La **rétinopathie**.","prio":"P2","sec":"s9"},{"id":"fc-d194-628674","poly":"dermato","fiche":"d194","front":"Hydroxychloroquine : quel calendrier de surveillance ophtalmologique ?","back":"Bilan **avant** traitement, puis **annuel à partir de 5 ans** (sans facteur de risque ni rétinopathie préexistante, dose ≤ 6,5 mg/kg).","prio":"P2","sec":"s9"},{"id":"fc-d194-77068e","poly":"dermato","fiche":"d194","front":"Hydroxychloroquine : quels examens ophtalmologiques ?","back":"**Fond d'œil** + **champ visuel automatisé** + un examen parmi : **ERG multifocal**, **OCT** ou clichés du fond d'œil en **autofluorescence**.","prio":"P3","sec":"s9"},{"id":"fc-d194-28370f","poly":"dermato","fiche":"d194","front":"SAPL thrombotique : quelle prévention secondaire ?","back":"Anticoagulation par **AVK à vie** (« la plupart du temps à vie » selon l'objectif).","prio":"P2","sec":"s10"},{"id":"fc-d194-735c5e","poly":"dermato","fiche":"d194","front":"SAPL : quelle biopsie cutanée et que recherche-t-elle ?","back":"Biopsie **large et profonde** : signes de **vasculopathie thrombosante**.","prio":"P3","sec":"s10"},{"id":"fc-d194-5a5935","poly":"dermato","fiche":"d194","front":"Anticorps anti-phospholipides sans thrombose : quel traitement ?","back":"**Aucun consensus** ; **aspirine à faible dose (100 mg)** préconisée.","prio":"P2","sec":"s11"},{"id":"fc-d194-2ee451","poly":"dermato","fiche":"d194","front":"aPL : comparer prévention primaire et secondaire ?","back":"Sans thrombose : **aspirine 100 mg** ; après thrombose (SAPL) : **AVK à vie**.","prio":"P2","sec":"s11"},{"id":"fc-d194-601c27","poly":"dermato","fiche":"d194","front":"CAPS : quel traitement associé ?","back":"**Anticoagulation efficace** + **corticoïdes à fortes doses** + **IgIV** + **plasmaphérèses**.","prio":"P2","sec":"s12"},{"id":"fc-d194-5f1d25","poly":"dermato","fiche":"d194","front":"CAPS réfractaire : quel traitement ?","back":"**Cyclophosphamide IV**.","prio":"P3","sec":"s12"},{"id":"fc-d194-ed2113","poly":"dermato","fiche":"d194","front":"CAPS : quelles défaillances d'organes ?","back":"Détresse **respiratoire**, **rein**, **HTA sévère**, **SNC**, myocarde, tube digestif, peau.","prio":"P3","sec":"s12"},{"id":"fc-d201-508cbf","poly":"dermato","fiche":"d201","front":"Greffé d'organe : quelles sont les deux grandes complications cutanées ?","back":"**Cancers cutanés** et **infections**, liés directement à l'**immunosuppression**.","prio":"P1","sec":"s1"},{"id":"fc-d201-ad99ad","poly":"dermato","fiche":"d201","front":"Greffé : quels trois éléments expliquent l'augmentation des complications cutanées ?","back":"Greffés qui **vivent plus longtemps** · **défenses diminuées** (immunosuppresseurs prolongés) · exposition à des **carcinogènes** (UV, virus…).","prio":"P2","sec":"s1"},{"id":"fc-d201-2c8114","poly":"dermato","fiche":"d201","front":"Complications cutanées du greffé : pourquoi les connaître et les prévenir ?","back":"Pour **réduire la morbidité et la mortalité** des transplantés.","prio":"P3","sec":"s1"},{"id":"fc-d201-4f802a","poly":"dermato","fiche":"d201","front":"Greffé : quelle part des cancers sont cutanés ?","back":"**90 %** de l'ensemble des cancers du transplanté.","prio":"P1","sec":"s1"},{"id":"fc-d201-539d73","poly":"dermato","fiche":"d201","front":"Cancers cutanés du greffé : citer les mécanismes favorisants ?","back":"**Immunosuppression** thérapeutique · mutations induites par les **UV** · effet **procarcinogène** de certains immunosuppresseurs · infections à **HPV**.","prio":"P1","sec":"s1"},{"id":"fc-d201-d9433d","poly":"dermato","fiche":"d201","front":"Greffé : quels immunosuppresseurs ont un effet procarcinogène propre ?","back":"Notamment **azathioprine**, **ciclosporine**, **anticalcineurines**.","prio":"P1","sec":"s1"},{"id":"fc-d201-c89e94","poly":"dermato","fiche":"d201","front":"Greffé : quelle particularité des infections à HPV ?","back":"Taux **élevé** d'infections, notamment par des types **oncogènes** (pas uniquement).","prio":"P2","sec":"s1"},{"id":"fc-d201-8263c9","poly":"dermato","fiche":"d201","front":"Greffé : quels cancers cutanés sont les plus fréquents ?","back":"Les **carcinomes** : **épidermoïdes** (CE, spinocellulaires) et **basocellulaires** (CBC).","prio":"P1","sec":"s1"},{"id":"fc-d201-c05b51","poly":"dermato","fiche":"d201","front":"Greffé : par combien est multiplié le risque de carcinome épidermoïde ?","back":"Par **65 à 250** par rapport à la population générale.","prio":"P1","sec":"s1"},{"id":"fc-d201-2d7c8b","poly":"dermato","fiche":"d201","front":"Greffé : quelle proportion aura un cancer dans les 20 ans suivant la greffe ?","back":"**50 à 70 %**.","prio":"P1","sec":"s1"},{"id":"fc-d201-5adfe9","poly":"dermato","fiche":"d201","front":"Greffé : délai moyen d'apparition du premier carcinome cutané ?","back":"**7 à 8 ans** après la greffe.","prio":"P1","sec":"s1"},{"id":"fc-d201-0e936e","poly":"dermato","fiche":"d201","front":"Greffé : quels greffés sont concernés par le risque de carcinome cutané ?","back":"**L'ensemble** des greffés.","prio":"P2","sec":"s1"},{"id":"fc-d201-4700fa","poly":"dermato","fiche":"d201","front":"Cancers cutanés du greffé : quelles mesures imposent-ils ?","back":"**Éducation** du patient, **prévention** et **dépistage**.","prio":"P2","sec":"s1"},{"id":"fc-d201-946baf","poly":"dermato","fiche":"d201","front":"Greffé : citer les facteurs de risque de carcinome cutané ?","back":"**Âge** à la greffe · **phototype clair** · **expositions solaires** antérieures · **ATCD de carcinome** · **type et durée** de l'immunosuppression · **organe** greffé.","prio":"P1","sec":"s2"},{"id":"fc-d201-d54375","poly":"dermato","fiche":"d201","front":"Greffé : citer les facteurs de risque de mélanome ?","back":"**Expositions solaires importantes** passées · **nombreux nævus** · **phototype clair** · **ATCD familiaux** de mélanome.","prio":"P1","sec":"s2"},{"id":"fc-d201-73e7b4","poly":"dermato","fiche":"d201","front":"Greffé séropositif pour HSV : quand survient l'infection détectable ?","back":"Dans les **mois** qui suivent la greffe.","prio":"P2","sec":"s2"},{"id":"fc-d201-47d741","poly":"dermato","fiche":"d201","front":"Greffé : délai moyen de la maladie de Kaposi ?","back":"**1 à 2 ans** après la greffe (plus **précoce** que les carcinomes).","prio":"P1","sec":"s2"},{"id":"fc-d201-8675f2","poly":"dermato","fiche":"d201","front":"Greffé : quelle fréquence de varicelle ou zona et quand ?","back":"**10 à 15 %** des greffés, dans les **années** suivantes ; souvent **extensifs**.","prio":"P1","sec":"s2"},{"id":"fc-d201-4f0692","poly":"dermato","fiche":"d201","front":"Greffé : délai moyen et fréquence des verrues et kératoses ?","back":"En moyenne **5 ans** après la greffe, chez **la moitié** des transplantés, parfois en grand nombre.","prio":"P2","sec":"s2"},{"id":"fc-d201-5b56a5","poly":"dermato","fiche":"d201","front":"Greffé : délai moyen de survenue du mélanome ?","back":"**5 ans** après la greffe.","prio":"P2","sec":"s2"},{"id":"fc-d201-cd9d02","poly":"dermato","fiche":"d201","front":"Complications cutanées du greffé : dans quel ordre apparaissent-elles (délais moyens) ?","back":"**Herpès** (mois) → **Kaposi** (1-2 ans) → **verrues-kératoses** et **mélanome** (5 ans) → **carcinome** (7-8 ans).","prio":"P2","sec":"s2"},{"id":"fc-d201-565afc","poly":"dermato","fiche":"d201","front":"Carcinomes : quel type prédomine chez l'immunocompétent ?","back":"Le **CBC** (carcinome basocellulaire).","prio":"P1","sec":"s3"},{"id":"fc-d201-1617c9","poly":"dermato","fiche":"d201","front":"Carcinomes : quel type prédomine chez le greffé ?","back":"Le **CE** (carcinome épidermoïde).","prio":"P1","sec":"s3"},{"id":"fc-d201-ef7f64","poly":"dermato","fiche":"d201","front":"CE du greffé : taux de métastases et de récidives locales ?","back":"Métastases de l'ordre de **8 %** ; récidives locales de l'ordre de **12 %** (CE plus **agressifs**).","prio":"P1","sec":"s3"},{"id":"fc-d201-49bd70","poly":"dermato","fiche":"d201","front":"Carcinomes du greffé : quel siège ?","back":"Surtout zones **découvertes** (mains, avant-bras, décolleté, visage), mais **aussi zones couvertes**.","prio":"P1","sec":"s3"},{"id":"fc-d201-cbf975","poly":"dermato","fiche":"d201","front":"Carcinomes du greffé : quel aspect et quelle conduite ?","back":"Aspect souvent **trompeur** → **biopsie au moindre doute**.","prio":"P1","sec":"s3"},{"id":"fc-d201-7d3536","poly":"dermato","fiche":"d201","front":"Greffé : quelle lésion kératosique doit particulièrement être biopsiée ?","back":"Une lésion kératosique qui **résiste** à un traitement destructeur simple comme la **cryothérapie**.","prio":"P1","sec":"s3"},{"id":"fc-d201-8f48c0","poly":"dermato","fiche":"d201","front":"Carcinomes du greffé : nombre et lésions associées ?","back":"Souvent **multiples**, **fréquemment** associés à des **verrues** (vulgaires ou planes) ou à des **kératoses actiniques**.","prio":"P1","sec":"s3"},{"id":"fc-d201-8e9eda","poly":"dermato","fiche":"d201","front":"Greffé : quel piège dans l'examen cutané ?","back":"Limiter l'examen aux zones exposées : il faut examiner **toute la peau** (carcinomes en zone couverte).","prio":"P1","sec":"s3"},{"id":"fc-d201-c80927","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi : définition ?","back":"Lésions **cutanées ou viscérales** par prolifération de **cellules fusiformes** (d'origine **endothéliale**) et de **vaisseaux dermiques**.","prio":"P2","sec":"s4"},{"id":"fc-d201-0c41a6","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi : quel virus est associé ?","back":"**HHV8** (herpèsvirus humain de type 8).","prio":"P1","sec":"s4"},{"id":"fc-d201-e09d8a","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi : dans quelles régions le risque est-il plus important ?","back":"**Bassin méditerranéen** et **Afrique** (infection à HHV8 plus répandue).","prio":"P2","sec":"s4"},{"id":"fc-d201-6928cd","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi du greffé : aspect des lésions ?","back":"**Nodules angiomateux** ou **plaques infiltrées**, **bleutés**, parfois kératosiques.","prio":"P1","sec":"s4"},{"id":"fc-d201-98c682","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi : quel signe associé peut la révéler ?","back":"Un **lymphœdème acquis**.","prio":"P2","sec":"s4"},{"id":"fc-d201-5ed9ac","poly":"dermato","fiche":"d201","front":"Maladie de Kaposi : quelle atteinte peut engager le pronostic vital ?","back":"L'atteinte **extracutanée** (l'atteinte cutanée est très fréquente).","prio":"P1","sec":"s4"},{"id":"fc-d201-ca3683","poly":"dermato","fiche":"d201","front":"Greffé : surrisque de mélanome ?","back":"**1,3 à 4,5** selon le **pays** et le **phototype**.","prio":"P2","sec":"s5"},{"id":"fc-d201-37a1b6","poly":"dermato","fiche":"d201","front":"Greffé : citer les autres tumeurs cutanées plus rares ?","back":"**Carcinome de Merkel** ; certains **lymphomes**.","prio":"P2","sec":"s5"},{"id":"fc-d201-31af76","poly":"dermato","fiche":"d201","front":"Infections cutanées du greffé : quels deux types ?","back":"Infections **banales** ou dues à des germes **opportunistes**.","prio":"P2","sec":"s6"},{"id":"fc-d201-34af7a","poly":"dermato","fiche":"d201","front":"HPV : quelles cibles ?","back":"Virus à **ADN** infectant **peau** et **muqueuses** ; certains sont **oncogènes**.","prio":"P2","sec":"s6"},{"id":"fc-d201-79fea5","poly":"dermato","fiche":"d201","front":"HPV : quelles lésions muqueuses ?","back":"**Végétations vénériennes**.","prio":"P3","sec":"s6"},{"id":"fc-d201-d59513","poly":"dermato","fiche":"d201","front":"HPV : quelles lésions cutanées ?","back":"**Verrues vulgaires** · **verrues en mosaïque** plantaires · **verrues planes** ; composante kératosique **souvent** marquée.","prio":"P2","sec":"s6"},{"id":"fc-d201-6b8ba1","poly":"dermato","fiche":"d201","front":"Greffé : quel rôle des HPV oncogènes sur les lésions précancéreuses ?","back":"Ils peuvent les infecter et favoriser leur **transformation**.","prio":"P2","sec":"s6"},{"id":"fc-d201-cdd81a","poly":"dermato","fiche":"d201","front":"Verrues du greffé : avec quelle lésion peut-on les confondre ?","back":"Avec des **kératoses actiniques** (lésions précancéreuses).","prio":"P1","sec":"s6"},{"id":"fc-d201-4ecf6b","poly":"dermato","fiche":"d201","front":"Verrues du greffé : réponse aux traitements ?","back":"Prise en charge **difficile** : lésions **résistantes** aux traitements habituels.","prio":"P2","sec":"s6"},{"id":"fc-d201-48bbc6","poly":"dermato","fiche":"d201","front":"Greffé séropositif pour HSV : fréquence d'infection détectable après la greffe ?","back":"**50 %** dans les **mois** qui suivent la greffe.","prio":"P1","sec":"s7"},{"id":"fc-d201-db9b51","poly":"dermato","fiche":"d201","front":"Greffé séropositif pour HSV : quelle prévention discuter ?","back":"**Prophylaxie quotidienne par valaciclovir**.","prio":"P1","sec":"s7"},{"id":"fc-d201-cdae61","poly":"dermato","fiche":"d201","front":"Varicelle ou zona du greffé : quel traitement ?","back":"**Aciclovir IV**, adapté à la **fonction rénale** : **indispensable**.","prio":"P1","sec":"s7"},{"id":"fc-d201-192def","poly":"dermato","fiche":"d201","front":"Infections herpétiques du greffé : quelle particularité des lésions ?","back":"Souvent **plus sévères** et **plus étendues**.","prio":"P2","sec":"s7"},{"id":"fc-d201-f95bb8","poly":"dermato","fiche":"d201","front":"Greffé : citer des germes opportunistes cutanés ?","back":"Bactéries (**Nocardia**) · levures (**Cryptococcus**) · filamenteux (**Aspergillus**) · **mycobactéries atypiques**.","prio":"P1","sec":"s8"},{"id":"fc-d201-3f41c2","poly":"dermato","fiche":"d201","front":"Infections opportunistes cutanées du greffé : quel aspect ?","back":"**Peu spécifique** : abcès, pustules, nodules, aspect d'**érysipèle** ou **ulcérations chroniques**.","prio":"P1","sec":"s8"},{"id":"fc-d201-4fa28c","poly":"dermato","fiche":"d201","front":"Lésion cutanée inhabituelle chez un greffé : quel examen ?","back":"**Biopsie** avec **prélèvements multiples** : indispensable.","prio":"P1","sec":"s8"},{"id":"fc-d201-49e09c","poly":"dermato","fiche":"d201","front":"Biopsie d'une lésion infectieuse du greffé : quelles analyses ?","back":"**Histologie** avec colorations spéciales · **examen direct** · **cultures** bactériologique, mycologique et parasitologique.","prio":"P2","sec":"s8"},{"id":"fc-d201-5c73f5","poly":"dermato","fiche":"d201","front":"Greffé : quel piège sur les carcinomes par rapport à l'immunocompétent ?","back":"Croire qu'ils sont identiques : le **CE domine**, plus **agressif**, **multiple**, aussi en **zone couverte**.","prio":"P1","sec":"s9"},{"id":"fc-d201-194345","poly":"dermato","fiche":"d201","front":"Lésions kératosiques multiples avec verrues chez un greffé : quelle conduite ?","back":"**Biopsie au moindre doute** (verrues, kératoses actiniques et carcinomes associés).","prio":"P2","sec":"s9"},{"id":"fc-d201-139a8e","poly":"dermato","fiche":"d201","front":"Tout greffé : quelles mesures de photoprotection ?","back":"Limiter au maximum le soleil, a fortiori entre **11 h et 16 h** ; **vêtements couvrants**, **chapeau**, **crème solaire**.","prio":"P1","sec":"s10"},{"id":"fc-d201-51e25f","poly":"dermato","fiche":"d201","front":"Greffé : but de la photoprotection ?","back":"Éviter les **carcinomes induits par les UV**.","prio":"P2","sec":"s10"},{"id":"fc-d201-e1cd44","poly":"dermato","fiche":"d201","front":"Greffé sans complication : fréquence de l'examen cutané de dépistage ?","back":"**1 fois par an** ; **plus souvent** si lésions cancéreuses préexistantes.","prio":"P1","sec":"s10"},{"id":"fc-d201-1532df","poly":"dermato","fiche":"d201","front":"Greffé : quand prendre en charge les lésions précancéreuses et tumorales ?","back":"Le plus **précocement** possible.","prio":"P2","sec":"s10"},{"id":"fc-d201-a5b43f","poly":"dermato","fiche":"d201","front":"Greffé : où trouver une fiche d'information sur la protection solaire ?","back":"Sur le site de la **Société française de dermatologie**.","prio":"P3","sec":"s10"},{"id":"fc-d201-1fb520","poly":"dermato","fiche":"d201","front":"Greffé : de quoi dépend la fréquence des verrues et cancers cutanés ?","back":"De la **durée** et de l'**intensité** de l'immunodépression.","prio":"P2","sec":"s10"},{"id":"fc-d201-a9498c","poly":"dermato","fiche":"d201","front":"Éviction solaire : quels horaires dans le Collège ?","back":"**11 h-16 h** chez le greffé (d201) ; **12 h-16 h** en prévention primaire générale des carcinomes (d302).","prio":"P3","sec":"s10"},{"id":"fc-d201-1865ed","poly":"dermato","fiche":"d201","front":"Crème solaire : quel mésusage éviter ?","back":"**Allonger le temps d'exposition** : elle sert ponctuellement à éviter un coup de soleil.","prio":"P2","sec":"s10"},{"id":"fc-d201-7fa3e2","poly":"dermato","fiche":"d201","front":"Greffé : quelle surveillance cutanée recommandée ?","back":"Surveillance **régulière et systématique** chez **tous** les greffés d'organe.","prio":"P2","sec":"s10"},{"id":"fc-d201-be6dc4","poly":"dermato","fiche":"d201","front":"CEC : le bilan d'extension est-il systématique, et que faire chez l'immunodéprimé ?","back":"**Non systématique**, sauf forme agressive, extension locorégionale ou terrain à risque comme l'**immunodéprimé** : écho ganglionnaire, scanner thoraco-abdominal, TEP-scan.","prio":"P2","sec":"s11"},{"id":"fc-d201-306986","poly":"dermato","fiche":"d201","front":"CEC : quels éléments de l'examen clinique ?","back":"**Mobilité** sur le plan profond, **diamètre**, autres carcinomes ou **mélanome** sur toute la peau, **adénopathie** de drainage.","prio":"P2","sec":"s11"},{"id":"fc-d201-61137d","poly":"dermato","fiche":"d201","front":"Carcinome cutané : traitement de 1re intention ?","back":"**Exérèse chirurgicale**, marge saine de **3 à 10 mm** (plus large pour le CEC que le CBC).","prio":"P1","sec":"s11"},{"id":"fc-d201-e4dc7a","poly":"dermato","fiche":"d201","front":"Carcinome cutané : quand le dossier passe-t-il en RCP ?","back":"Dossier discuté en **RCP**, **sauf** CBC **sans critère agressif**.","prio":"P2","sec":"s11"},{"id":"fc-d201-42435b","poly":"dermato","fiche":"d201","front":"Carcinome cutané : exérèse incomplète ou limite, que faire ?","back":"**Reprise chirurgicale indispensable**.","prio":"P1","sec":"s11"},{"id":"fc-d201-e0eb03","poly":"dermato","fiche":"d201","front":"Carcinome cutané : quand faire une biopsie avant l'exérèse ?","back":"Diagnostic **incertain** ou avant une chirurgie **complexe** ; si le diagnostic est très probable : exérèse d'emblée avec anatomopathologie.","prio":"P2","sec":"s11"},{"id":"fc-d201-b831ec","poly":"dermato","fiche":"d201","front":"Carcinome cutané inopérable : citer les alternatives à la chirurgie ?","back":"**Radiothérapie**, **cryochirurgie** ; tumeur superficielle : **photothérapie dynamique** ou **imiquimod** (CBC superficiel, CEC in situ).","prio":"P3","sec":"s11"},{"id":"fc-d201-251a6a","poly":"dermato","fiche":"d201","front":"Greffé après un premier CE : quelle adaptation de l'immunosuppression discuter ?","back":"Remplacer l'**anticalcineurine** par un **inhibiteur de mTor**, avec l'**équipe de greffe**.","prio":"P1","sec":"s11"},{"id":"fc-d201-3dc8eb","poly":"dermato","fiche":"d201","front":"Passage à un inhibiteur de mTor après un CE : quel bénéfice ?","back":"Diminue nettement le risque d'un **2e CE**.","prio":"P2","sec":"s11"},{"id":"fc-d201-9ae1f8","poly":"dermato","fiche":"d201","front":"Après traitement d'un carcinome : objectifs du suivi ?","back":"Dépister **récidive** locale ou ganglionnaire, nouveau **CBC/CEC**, **mélanome** ; apprendre l'**autosurveillance**.","prio":"P2","sec":"s11"},{"id":"fc-d201-b7b41e","poly":"dermato","fiche":"d201","front":"Carcinome épidermoïde cutané : quel rôle pronostique de l'immunodépression ?","back":"Facteur de **mauvais pronostic**.","prio":"P3","sec":"s11"},{"id":"fc-d201-32f74c","poly":"dermato","fiche":"d201","front":"Verrues : existe-t-il un traitement spécifique de l'HPV ?","back":"**Non** ; objectif : disparition des lésions visibles.","prio":"P2","sec":"s12"},{"id":"fc-d201-c7ea97","poly":"dermato","fiche":"d201","front":"Verrues : quels traitements ?","back":"**Kératolytique** · **cryothérapie** à l'azote liquide · **laser CO₂** (anesthésie locale, cicatrice possible).","prio":"P2","sec":"s12"},{"id":"fc-d201-bce4e3","poly":"dermato","fiche":"d201","front":"Kératolytique des verrues : quelles modalités ?","back":"**Acide salicylique** ou collodion salicylé, en protégeant la peau saine ; ex. chaque soir après **décapage** mécanique, assez longtemps.","prio":"P3","sec":"s12"},{"id":"fc-d201-aaaf75","poly":"dermato","fiche":"d201","front":"Kératoses actiniques : quelles options de traitement ?","back":"Destruction physique (**cryothérapie**, électrocoagulation, laser CO₂), **photothérapie dynamique**, topiques (**5-FU**, **imiquimod**).","prio":"P3","sec":"s12"},{"id":"fc-d201-8edd16","poly":"dermato","fiche":"d201","front":"Verrues : quel taux de récidive annoncer ?","back":"Environ **30 %** (persistance de l'HPV dans la peau saine).","prio":"P2","sec":"s12"},{"id":"fc-d201-f9b471","poly":"dermato","fiche":"d201","front":"Verrues planes chez l'immunodéprimé : quelle particularité évolutive ?","back":"Elles régressent d'habitude en **moins de 2 ans**, mais peuvent devenir **chroniques** chez l'immunodéprimé.","prio":"P3","sec":"s12"},{"id":"fc-d201-319533","poly":"dermato","fiche":"d201","front":"Herpès : différence entre aciclovir et valaciclovir ?","back":"Le **valaciclovir** est la **prodrogue** de l'aciclovir, de meilleure **biodisponibilité**.","prio":"P2","sec":"s13"},{"id":"fc-d201-de1dfa","poly":"dermato","fiche":"d201","front":"Aciclovir et valaciclovir : sur quel virus sont-ils actifs ?","back":"**Virostatiques** : actifs seulement sur le virus en **réplication active**.","prio":"P2","sec":"s13"},{"id":"fc-d201-cf8579","poly":"dermato","fiche":"d201","front":"Herpès : les traitements locaux sont-ils efficaces ?","back":"**Non**, ils n'ont pas montré d'efficacité.","prio":"P3","sec":"s13"},{"id":"fc-d201-15d1eb","poly":"dermato","fiche":"d201","front":"HSV résistant à l'aciclovir chez l'immunodéprimé : quelle option ?","back":"**Foscarnet IV** (souches résistantes rares).","prio":"P2","sec":"s13"},{"id":"fc-d201-10a1d2","poly":"dermato","fiche":"d201","front":"Herpès de l'immunodéprimé : quelle gravité et quel traitement des formes graves ?","back":"Primo-infection **grave** ; forme grave → traitement **IV**.","prio":"P2","sec":"s13"},{"id":"fc-d201-4bedd0","poly":"dermato","fiche":"d201","front":"Zona de l'immunodéprimé : délai pour débuter l'antiviral ?","back":"Dans les **72 h** après le début de l'éruption.","prio":"P1","sec":"s14"},{"id":"fc-d201-2c2940","poly":"dermato","fiche":"d201","front":"Zona de l'immunodéprimé : durée de l'aciclovir IV ?","back":"Au moins **7 à 10 jours**.","prio":"P1","sec":"s14"},{"id":"fc-d201-f73a17","poly":"dermato","fiche":"d201","front":"Varicelle de l'immunodéprimé : quelle conduite ?","back":"Forme **grave** : antiviral **systématique** par **aciclovir IV**.","prio":"P1","sec":"s14"},{"id":"fc-d201-f1132e","poly":"dermato","fiche":"d201","front":"Varicelle ou zona du greffé : faut-il arrêter l'immunosuppresseur ?","back":"**Pas forcément** (corticothérapie comprise).","prio":"P2","sec":"s14"},{"id":"fc-d201-5477c5","poly":"dermato","fiche":"d201","front":"Zona / varicelle : quels soins locaux ?","back":"Douches **tempérées** quotidiennes · **chlorhexidine en solution aqueuse** · ongles courts · **pas de talc**.","prio":"P2","sec":"s14"},{"id":"fc-d201-16f456","poly":"dermato","fiche":"d201","front":"Zona aigu : quels antalgiques et quel traitement éviter ?","back":"Antalgiques de **palier II à III** ; **pas de corticothérapie générale**.","prio":"P2","sec":"s14"},{"id":"fc-d201-729fc7","poly":"dermato","fiche":"d201","front":"Aciclovir IV chez le greffé : quel paramètre surveiller ?","back":"La **fonction rénale** (dose adaptée).","prio":"P1","sec":"s14"},{"id":"fc-d201-9ed1be","poly":"dermato","fiche":"d201","front":"Valaciclovir oral 7 jours dans le zona : pour quels patients ?","back":"Zona de l'**immunocompétent de plus de 50 ans** ou zona **ophtalmique** (pas le greffé).","prio":"P2","sec":"s14"},{"id":"fc-d201-c442ca","poly":"dermato","fiche":"d201","front":"Enfant candidat à une greffe d'organe solide, séronégatif VZV : quelle prévention ?","back":"**Vaccin varicelle** dans les **6 mois** avant la greffe, **2 doses à 1 mois** d'intervalle ; suivi des anticorps.","prio":"P3","sec":"s14"},{"id":"fc-d201-2171c9","poly":"dermato","fiche":"d201","front":"Vaccins varicelle et zona : pourquoi contre-indiqués chez l'immunodéprimé ?","back":"Ce sont des **virus vivants atténués**.","prio":"P2","sec":"s14"},{"id":"fc-d201-728dba","poly":"dermato","fiche":"d201","front":"Fièvre de la varicelle : quel antipyrétique et quels médicaments éviter ?","back":"**Paracétamol** ; ni **aspirine** (syndrome de **Reye**) ni **AINS** (**fasciite nécrosante**).","prio":"P2","sec":"s14"},{"id":"fc-d201-70b3b2","poly":"dermato","fiche":"d201","front":"Infection opportuniste cutanée du greffé : le Collège détaille-t-il le traitement ?","back":"**Non** ; il insiste sur la **biopsie** avec prélèvements multiples.","prio":"P3","sec":"s15"},{"id":"fc-d211-1f97c8","poly":"dermato","fiche":"d211","front":"Sarcoïdose : définition ?","back":"**Granulomatose systémique chronique** d'**étiologie inconnue**.","prio":"P1","sec":"s1"},{"id":"fc-d211-436002","poly":"dermato","fiche":"d211","front":"Sarcoïdose : fréquence de l'atteinte pulmonaire ?","back":"**90 %**.","prio":"P1","sec":"s1"},{"id":"fc-d211-19c2d5","poly":"dermato","fiche":"d211","front":"Sarcoïdose : fréquence de l'atteinte cutanée ?","back":"**30 %**.","prio":"P1","sec":"s1"},{"id":"fc-d211-2b5107","poly":"dermato","fiche":"d211","front":"Sarcoïdose : autres organes pouvant être touchés (hors poumon et peau) ?","back":"**Œil**, ganglions périphériques, **foie**, **système nerveux**, **cœur**, os et articulations.","prio":"P2","sec":"s1"},{"id":"fc-d211-95105f","poly":"dermato","fiche":"d211","front":"Sarcoïdose : quelles formes fréquentes connaître ?","back":"**Atteintes respiratoires**, **syndrome de Löfgren**, **érythème noueux**.","prio":"P2","sec":"s1"},{"id":"fc-d211-4368de","poly":"dermato","fiche":"d211","front":"Sarcoïdose cutanée : élément clé du diagnostic ?","back":"Mettre en évidence dans la peau le **granulome sarcoïdosique**.","prio":"P1","sec":"s1"},{"id":"fc-d211-44cb4f","poly":"dermato","fiche":"d211","front":"Granulome sarcoïdosique : caractéristiques histologiques ?","back":"**Épithélioïde et gigantocellulaire**, **sans nécrose caséeuse**, entouré d'une **couronne lymphocytaire** (LT).","prio":"P1","sec":"s1"},{"id":"fc-d211-a017b3","poly":"dermato","fiche":"d211","front":"Granulome sarcoïdosique : de quels phénomènes témoigne-t-il ?","back":"Phénomènes **inflammatoires** et, secondairement, **fibrosants**.","prio":"P3","sec":"s1"},{"id":"fc-d211-411a34","poly":"dermato","fiche":"d211","front":"Érythème noueux : est-ce une lésion granulomateuse ?","back":"**Non** : signe cutané **non spécifique**, contrairement aux **sarcoïdes**.","prio":"P1","sec":"s1"},{"id":"fc-d211-aa6794","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : intérêt diagnostique ?","back":"Peuvent être **inaugurales** ; histologie **spécifique** et lésions **accessibles à la biopsie**.","prio":"P2","sec":"s1"},{"id":"fc-d211-b8638c","poly":"dermato","fiche":"d211","front":"Syndrome de Löfgren : définition ?","back":"Forme **aiguë** de sarcoïdose : **érythème noueux** + **fièvre** + **arthralgies** + **adénopathies hilaires bilatérales non compressives**.","prio":"P1","sec":"s1"},{"id":"fc-d211-ebae2d","poly":"dermato","fiche":"d211","front":"Syndrome de Löfgren : évolution ?","back":"Forme **aiguë et résolutive**.","prio":"P1","sec":"s1"},{"id":"fc-d211-48c114","poly":"dermato","fiche":"d211","front":"Syndrome de Löfgren : autre nom des adénopathies hilaires ?","back":"« **Pseudo-lymphome** » hilaire.","prio":"P3","sec":"s1"},{"id":"fc-d211-6c1340","poly":"dermato","fiche":"d211","front":"Sarcoïdose : âge et sexe de prédilection ?","back":"Sujet jeune, **20 à 40 ans** ; prédominance **féminine**.","prio":"P2","sec":"s2"},{"id":"fc-d211-cf6a63","poly":"dermato","fiche":"d211","front":"Sarcoïdose : répartition géographique de l'incidence ?","back":"**Gradient nord–sud** : élevée en Europe du Nord, faible en Europe du Sud et Amérique latine ; fréquente si origine **africaine**.","prio":"P2","sec":"s2"},{"id":"fc-d211-55e1ef","poly":"dermato","fiche":"d211","front":"Sarcoïdose : incidence annuelle en Europe du Nord ?","back":"**8 à 40 cas/10⁵** habitants.","prio":"P3","sec":"s2"},{"id":"fc-d211-08992d","poly":"dermato","fiche":"d211","front":"Sarcoïdose : incidence annuelle en Europe du Sud et Amérique latine ?","back":"**1 à 4 cas/10⁵** habitants.","prio":"P3","sec":"s2"},{"id":"fc-d211-0f743f","poly":"dermato","fiche":"d211","front":"Sarcoïdose : hypothèse physiopathologique actuelle ?","back":"**Réponse granulomateuse inappropriée** à des **antigènes de l'environnement** (aucun agent précis connu).","prio":"P2","sec":"s2"},{"id":"fc-d211-c10c0f","poly":"dermato","fiche":"d211","front":"Sarcoïdose : types de réponse lymphocytaire T impliqués ?","back":"**Th1** (IL-12, interféron γ, TNFα) et **Th17** (IL-23).","prio":"P3","sec":"s2"},{"id":"fc-d211-9cf9ff","poly":"dermato","fiche":"d211","front":"Sarcoïdose : séquence physiopathologique ?","back":"Exposition antigénique → **réponse T** → **activation macrophagique** → **granulomes** → **anergie**.","prio":"P3","sec":"s2"},{"id":"fc-d211-0507d6","poly":"dermato","fiche":"d211","front":"Sarcoïdose : mécanisme de l'anergie tuberculinique ?","back":"**Hyperactivité des lymphocytes T régulateurs**.","prio":"P3","sec":"s2"},{"id":"fc-d211-d6f158","poly":"dermato","fiche":"d211","front":"Érythème noueux : fréquence comme signe inaugural de sarcoïdose ?","back":"**20 %** des sarcoïdoses.","prio":"P1","sec":"s3"},{"id":"fc-d211-4a12f7","poly":"dermato","fiche":"d211","front":"Érythème noueux en France : 1re et 2e causes ?","back":"1re : **infections streptococciques** ; 2e : **sarcoïdose**.","prio":"P1","sec":"s3"},{"id":"fc-d211-875db5","poly":"dermato","fiche":"d211","front":"Érythème noueux : lésion élémentaire ?","back":"**Nouures** : nodules **hypodermiques** en relief.","prio":"P1","sec":"s3"},{"id":"fc-d211-5618de","poly":"dermato","fiche":"d211","front":"Nouure : caractères à la palpation ?","back":"**Ferme**, **non fluctuante**, **chaude**, adhérente ; habituellement **douloureuse** ou sensible.","prio":"P1","sec":"s3"},{"id":"fc-d211-a4d3ae","poly":"dermato","fiche":"d211","front":"Nouure : aspect de la surface ?","back":"**Érythémateuse** ou de **couleur normale**.","prio":"P3","sec":"s3"},{"id":"fc-d211-1a9ac9","poly":"dermato","fiche":"d211","front":"Érythème noueux : mode de début et siège ?","back":"Début **aigu** ; le plus souvent **bilatéral**, régions **prétibiales** et **genoux**.","prio":"P1","sec":"s3"},{"id":"fc-d211-f77614","poly":"dermato","fiche":"d211","front":"Érythème noueux : autres sièges possibles ?","back":"**Parfois** mollets, cuisses, fesses ; **plus rarement** membres supérieurs.","prio":"P3","sec":"s3"},{"id":"fc-d211-2657ec","poly":"dermato","fiche":"d211","front":"Érythème noueux : évolution des nouures ?","back":"Régression spontanée en **2 à 3 semaines**, par les stades de la **biligénie**.","prio":"P1","sec":"s3"},{"id":"fc-d211-9b2b5b","poly":"dermato","fiche":"d211","front":"Biligénie : succession des teintes ?","back":"**Bleu-violet** → **vert-jaune** → **brun** (teintes d'une ecchymose).","prio":"P2","sec":"s3"},{"id":"fc-d211-8ba840","poly":"dermato","fiche":"d211","front":"Érythème noueux : symptômes associés ?","back":"**Fièvre modérée**, **asthénie**, signes **rhinopharyngés**, **arthralgies**.","prio":"P2","sec":"s3"},{"id":"fc-d211-ecda80","poly":"dermato","fiche":"d211","front":"Érythème noueux : faut-il une biopsie cutanée ?","back":"**Non** : diagnostic **clinique** ; biopsie non spécifique d'une étiologie.","prio":"P1","sec":"s3"},{"id":"fc-d211-6aefc6","poly":"dermato","fiche":"d211","front":"Érythème noueux : causes infectieuses ?","back":"**Streptocoque β-hémolytique du groupe A**, **tuberculose**, **yersiniose**.","prio":"P2","sec":"s4"},{"id":"fc-d211-83e36f","poly":"dermato","fiche":"d211","front":"Érythème noueux : causes non infectieuses (hors sarcoïdose) ?","back":"**Colites inflammatoires** (RCH, Crohn), **maladie de Behçet**, **grossesse**, **médicaments**.","prio":"P2","sec":"s4"},{"id":"fc-d211-e3a71d","poly":"dermato","fiche":"d211","front":"Érythème noueux : proportion de formes idiopathiques ?","back":"**50 %**.","prio":"P2","sec":"s4"},{"id":"fc-d211-cdf20e","poly":"dermato","fiche":"d211","front":"Yersiniose et érythème noueux : espèces en cause ?","back":"***Yersinia enterocolitica*** ou ***Y. pseudotuberculosis***.","prio":"P3","sec":"s4"},{"id":"fc-d211-b0f0b2","poly":"dermato","fiche":"d211","front":"Érythème noueux : diagnostics différentiels ?","back":"**Sweet profond**, **périartérite noueuse**, hémopathies cutanées, **piqûres d'arthropodes**, sepsis cutanés, **panniculite pancréatique**.","prio":"P3","sec":"s4"},{"id":"fc-d211-1da11c","poly":"dermato","fiche":"d211","front":"Syndrome de Sweet profond : nature ?","back":"Dermatose **neutrophilique**, généralement **fébrile**.","prio":"P3","sec":"s4"},{"id":"fc-d211-db59dc","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : couleur et consistance ?","back":"Lésions **infiltrées**, **jaune ocre à violet foncé**, brunissant avec le temps.","prio":"P2","sec":"s5"},{"id":"fc-d211-66fc1d","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : signes fonctionnels ?","back":"**Indolores**, **non prurigineuses** ; épiderme en général non modifié.","prio":"P2","sec":"s5"},{"id":"fc-d211-4eda25","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : localisation fréquente ?","back":"Le **visage**.","prio":"P2","sec":"s5"},{"id":"fc-d211-3ff8b1","poly":"dermato","fiche":"d211","front":"Sarcoïdes : aspect à la vitropression ?","back":"**Lupoïde** : granulations jaunâtres « **gelée de pomme** ».","prio":"P2","sec":"s5"},{"id":"fc-d211-915877","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : citer les formes cliniques ?","back":"**Papuleuse**, **nodulaire**, **angiolupoïde**, **en plaques**, **lupus pernio**, **sur cicatrice**.","prio":"P2","sec":"s5"},{"id":"fc-d211-191c3e","poly":"dermato","fiche":"d211","front":"Sarcoïdes papuleuses vs nodulaires : autre nom de chaque forme ?","back":"Papuleuses = sarcoïdes à **petits nodules** ; nodulaires = sarcoïdes à **gros nodules**.","prio":"P3","sec":"s5"},{"id":"fc-d211-929694","poly":"dermato","fiche":"d211","front":"Sarcoïde angiolupoïde : aspect et siège ?","back":"Placard nodulaire **télangiectasique** de l'**angle interne de l'œil**, du sillon nasogénien ou de la joue.","prio":"P3","sec":"s5"},{"id":"fc-d211-6bd965","poly":"dermato","fiche":"d211","front":"Sarcoïdes en plaques : aspect et évolution ?","back":"Lésions infiltrées **> 1 cm**, par confluence de papules, parfois annulaires ; évolution **atrophique et dyschromique**.","prio":"P3","sec":"s5"},{"id":"fc-d211-23eaa8","poly":"dermato","fiche":"d211","front":"Lupus pernio : aspect et siège ?","back":"Papules et nodules **violacés des extrémités** : nez, oreilles, pommettes, doigts, orteils.","prio":"P2","sec":"s5"},{"id":"fc-d211-5088f0","poly":"dermato","fiche":"d211","front":"Lupus pernio : risque évolutif local ?","back":"**Destruction osseuse et cartilagineuse ORL** sous-jacente (forme potentiellement grave).","prio":"P2","sec":"s5"},{"id":"fc-d211-e855be","poly":"dermato","fiche":"d211","front":"Lupus pernio : de quelle maladie s'agit-il ?","back":"D'une **sarcoïdose** (le terme « lupus » est **impropre**).","prio":"P2","sec":"s5"},{"id":"fc-d211-09ab52","poly":"dermato","fiche":"d211","front":"Sarcoïdes sur cicatrice : sur quelles lésions surviennent-elles ?","back":"Anciennes cicatrices **post-traumatiques** ou **chirurgicales**, ou **tatouage permanent**.","prio":"P2","sec":"s5"},{"id":"fc-d211-973b41","poly":"dermato","fiche":"d211","front":"Sarcoïdes : que recherche la biopsie cutanée ?","back":"Un **granulome tuberculoïde sans nécrose caséeuse**.","prio":"P1","sec":"s6"},{"id":"fc-d211-6737ef","poly":"dermato","fiche":"d211","front":"Biopsie d'une sarcoïde : examens associés pour écarter une tuberculose ?","back":"Coloration de **Ziehl** ± culture sur milieu de **Löwenstein**.","prio":"P1","sec":"s6"},{"id":"fc-d211-c0e2a8","poly":"dermato","fiche":"d211","front":"Sarcoïdose : quelles expositions rechercher à l'interrogatoire ?","back":"**Poussières organiques et inorganiques** ; le **béryllium** donne une pseudo-sarcoïdose.","prio":"P2","sec":"s6"},{"id":"fc-d211-75e603","poly":"dermato","fiche":"d211","front":"Sarcoïdose : en quoi consiste le diagnostic ?","back":"**Éliminer les autres causes de maladies granulomateuses**.","prio":"P2","sec":"s6"},{"id":"fc-d211-130c8e","poly":"dermato","fiche":"d211","front":"Granulomatoses secondaires : 4 causes principales ?","back":"**Infections** · **lymphomes/cancers** · **DICV** · **médicaments**.","prio":"P2","sec":"s6"},{"id":"fc-d211-97899b","poly":"dermato","fiche":"d211","front":"Granulomatoses infectieuses à éliminer devant une sarcoïdose ?","back":"**Tuberculose**, mycobactéries atypiques, **lèpre**, **leishmaniose**, infections fongiques.","prio":"P2","sec":"s6"},{"id":"fc-d211-e1562c","poly":"dermato","fiche":"d211","front":"Granulomatoses non infectieuses à éliminer devant une sarcoïdose ?","back":"Corps étrangers (**silicone**), rosacée, granulome annulaire, **Crohn**, GPA, **lymphomes**, **DICV**, béryllium.","prio":"P3","sec":"s6"},{"id":"fc-d211-66203c","poly":"dermato","fiche":"d211","front":"Sarcoïdose cutanée : résultat attendu de l'IDR à la tuberculine ?","back":"**Anergie tuberculinique**.","prio":"P2","sec":"s7"},{"id":"fc-d211-9142a1","poly":"dermato","fiche":"d211","front":"Sarcoïdose : que rechercher à l'imagerie thoracique ?","back":"**Adénopathies médiastinales**, **syndrome interstitiel**.","prio":"P2","sec":"s7"},{"id":"fc-d211-ec80d7","poly":"dermato","fiche":"d211","front":"Sarcoïdose : EFR à réaliser ?","back":"EFR avec **pléthysmographie** (volumes) et **DLCO**.","prio":"P3","sec":"s7"},{"id":"fc-d211-2241fd","poly":"dermato","fiche":"d211","front":"Sarcoïdose : trouble ventilatoire le plus fréquent aux EFR ?","back":"**Restrictif** (65 %) ; obstructif possible (> 30 %).","prio":"P2","sec":"s7"},{"id":"fc-d211-a5ea91","poly":"dermato","fiche":"d211","front":"Sarcoïdose : composantes de l'examen ophtalmologique ?","back":"**Lampe à fente** (uvéite antérieure chronique), **tonométrie** (glaucome), **fond d'œil**, **Schirmer** (syndrome sec).","prio":"P2","sec":"s7"},{"id":"fc-d211-972223","poly":"dermato","fiche":"d211","front":"Sarcoïdose : intérêt de l'ECG ?","back":"Rechercher des **troubles du rythme et de la conduction**.","prio":"P2","sec":"s7"},{"id":"fc-d211-455b87","poly":"dermato","fiche":"d211","front":"Sarcoïdose : anomalies attendues à la NFS et à l'électrophorèse ?","back":"**Lymphopénie** ; **hypergammaglobulinémie polyclonale**.","prio":"P2","sec":"s7"},{"id":"fc-d211-9bf48e","poly":"dermato","fiche":"d211","front":"Sarcoïdose cutanée : autres bilans biologiques du bilan d'extension (hors NFS, EPP, calcium, ECA, sérologies) ?","back":"Biologie **inflammatoire**, **hépatique** et **rénale** (**créatinine**).","prio":"P3","sec":"s7"},{"id":"fc-d211-a400ef","poly":"dermato","fiche":"d211","front":"Sarcoïdose : fréquences d'hypercalciurie et d'hypercalcémie ?","back":"Hypercalciurie **40 %** ; hypercalcémie **10 %**.","prio":"P2","sec":"s7"},{"id":"fc-d211-396670","poly":"dermato","fiche":"d211","front":"Sarcoïdose : bilan phosphocalcique à demander ?","back":"**Sanguin** et **urinaire des 24 heures**.","prio":"P3","sec":"s7"},{"id":"fc-d211-f4248a","poly":"dermato","fiche":"d211","front":"ECA dans la sarcoïdose : valeur diagnostique et pronostique ?","back":"Élévation **inconstante (50 %)**, **non spécifique**, **sans valeur pronostique**.","prio":"P2","sec":"s7"},{"id":"fc-d211-847ee2","poly":"dermato","fiche":"d211","front":"ECA dans la sarcoïdose : intérêt de son suivi ?","back":"Son suivi **peut** être un bon marqueur d'**évolutivité** de la maladie.","prio":"P2","sec":"s7"},{"id":"fc-d211-ea483a","poly":"dermato","fiche":"d211","front":"Sarcoïdose : sérologies à faire au diagnostic ?","back":"**Hépatites B et C** et **VIH**.","prio":"P3","sec":"s7"},{"id":"fc-d211-72406d","poly":"dermato","fiche":"d211","front":"Sarcoïdose avec signes cardiaques : examens ?","back":"**Holter-ECG**, **échocardiographie**, **IRM cardiaque**.","prio":"P2","sec":"s7"},{"id":"fc-d211-a86660","poly":"dermato","fiche":"d211","front":"Sarcoïdose avec signes neurologiques centraux : examens ?","back":"**IRM cérébrale**, **ponction lombaire**.","prio":"P3","sec":"s7"},{"id":"fc-d211-e919c9","poly":"dermato","fiche":"d211","front":"Sarcoïdose pulmonaire : examen pouvant évaluer l'extension du granulome ?","back":"**TEP-TDM au ¹⁸FDG**.","prio":"P3","sec":"s7"},{"id":"fc-d211-2947b8","poly":"dermato","fiche":"d211","front":"Sarcoïdose avec atteinte ostéo-articulaire : examen ?","back":"**Radiographies standard** des articulations douloureuses ou inflammatoires.","prio":"P3","sec":"s7"},{"id":"fc-d211-9137c1","poly":"dermato","fiche":"d211","front":"Érythème noueux sarcoïdosique : type de traitement ?","back":"**Symptomatique**.","prio":"P2","sec":"s8"},{"id":"fc-d211-6df260","poly":"dermato","fiche":"d211","front":"Érythème noueux sarcoïdosique : mesures du traitement symptomatique ?","back":"**Repos**, **antalgiques** ou anti-inflammatoires, **contention élastique**.","prio":"P2","sec":"s8"},{"id":"fc-d211-dfc29f","poly":"dermato","fiche":"d211","front":"Érythème noueux sarcoïdosique : anti-inflammatoires cités ?","back":"**AINS**, **colchicine**, **antipaludéens de synthèse**.","prio":"P2","sec":"s8"},{"id":"fc-d211-1a2dd6","poly":"dermato","fiche":"d211","front":"Érythème noueux sarcoïdosique : évolution spontanée ?","back":"**Favorable dans 90 %** des cas.","prio":"P2","sec":"s8"},{"id":"fc-d211-9c8453","poly":"dermato","fiche":"d211","front":"Syndrome de Löfgren : délai de guérison spontanée ?","back":"**Plusieurs mois à quelques années**.","prio":"P3","sec":"s8"},{"id":"fc-d211-7ea426","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : mode évolutif ?","back":"**Lent**, chronique ; **disparition spontanée** possible.","prio":"P2","sec":"s9"},{"id":"fc-d211-180979","poly":"dermato","fiche":"d211","front":"Sarcoïdes cutanées : formes graves (esthétique ou fonction) ?","back":"Sarcoïdes à **gros nodules** ou **infiltrantes**, **lupus pernio**.","prio":"P2","sec":"s9"},{"id":"fc-d211-8b5eea","poly":"dermato","fiche":"d211","front":"Lupus pernio : atteintes souvent associées ?","back":"Atteinte **pulmonaire** et **ORL**.","prio":"P2","sec":"s10"},{"id":"fc-d211-c757b3","poly":"dermato","fiche":"d211","front":"Sarcoïdose : évolution globale ?","back":"**Souvent bénigne**.","prio":"P2","sec":"s10"},{"id":"fc-d211-61f50e","poly":"dermato","fiche":"d211","front":"Syndrome de Löfgren : taux de rémission ?","back":"**90 %** des cas.","prio":"P2","sec":"s10"},{"id":"fc-d215-95dd40","poly":"dermato","fiche":"d215","front":"Purpura : quelle est sa définition ?","back":"Lésion élémentaire cutanée et/ou muqueuse due à une **extravasation de sang** dans le **derme** ou le **chorion**.","prio":"P1","sec":"s1"},{"id":"fc-d215-5ca399","poly":"dermato","fiche":"d215","front":"Purpura : quel est le signe clinique qui le définit à l'examen ?","back":"Il **ne s'efface pas à la vitropression**.","prio":"P1","sec":"s1"},{"id":"fc-d215-ea90c8","poly":"dermato","fiche":"d215","front":"Devant tout purpura : quelle infection faut-il toujours évoquer ?","back":"Une **infection grave à méningocoque** (signe d'alarme).","prio":"P1","sec":"s1"},{"id":"fc-d215-62d54f","poly":"dermato","fiche":"d215","front":"Devant tout purpura : quelles sont les deux démarches indispensables ?","back":"Toujours **rechercher la gravité** ; le **diagnostic étiologique** est une étape capitale.","prio":"P1","sec":"s1"},{"id":"fc-d215-e15bc6","poly":"dermato","fiche":"d215","front":"Purpura pétéchial : quel aspect et quel siège ?","back":"**Punctiforme**, aux **membres inférieurs** surtout ; tableau **le plus fréquent**.","prio":"P1","sec":"s1"},{"id":"fc-d215-7b3850","poly":"dermato","fiche":"d215","front":"Purpura ecchymotique : quel aspect ?","back":"Larges **nappes bleu violacé**.","prio":"P1","sec":"s1"},{"id":"fc-d215-ec49d6","poly":"dermato","fiche":"d215","front":"Vibices : quel aspect et quel siège ?","back":"**Traînées linéaires**, aux **plis** et zones de **friction ou de traction**.","prio":"P1","sec":"s1"},{"id":"fc-d215-e49c5b","poly":"dermato","fiche":"d215","front":"Purpura : quelles lésions associées rechercher systématiquement ?","back":"Parfois présentes : macules, papules, plus rarement nodules, **bulles** (hémorragiques), **pustules**, lésions **nécrotiques** puis ulcérées.","prio":"P2","sec":"s1"},{"id":"fc-d215-51b3a9","poly":"dermato","fiche":"d215","front":"Purpura muqueux : quelle composante est fréquente ?","back":"Une composante **hémorragique ou érosive** : gingivorragie, épistaxis, hémorragie sous-conjonctivale.","prio":"P2","sec":"s1"},{"id":"fc-d215-75ff83","poly":"dermato","fiche":"d215","front":"Purpura : par quelles teintes passe-t-il en évoluant ?","back":"Teintes de la **biligénie** : rouge, bleu-violet, vert-jaune puis chamois.","prio":"P2","sec":"s1"},{"id":"fc-d215-0f1081","poly":"dermato","fiche":"d215","front":"Purpura : quelle évolution et quelle séquelle possible ?","back":"Disparition **sans séquelle**, sauf récidives multiples : **dyschromie brunâtre** (type dermatite ocre).","prio":"P2","sec":"s1"},{"id":"fc-d215-82f713","poly":"dermato","fiche":"d215","front":"Érythème : quel mécanisme et comment réagit-il à la vitropression ?","back":"**Dilatation vasculaire** dermique ; il **s'efface** à la vitropression.","prio":"P1","sec":"s2"},{"id":"fc-d215-335b82","poly":"dermato","fiche":"d215","front":"Télangiectasies : quel aspect et comment réagissent-elles à la vitropression ?","back":"Vaisseaux ectasiques **en branche d'arbre mort** ou **étoilés** ; elles **s'effacent**.","prio":"P2","sec":"s2"},{"id":"fc-d215-84b8ce","poly":"dermato","fiche":"d215","front":"Anomalies vasculaires (angiomes plans) : comment réagissent-elles à la vitropression ?","back":"Elles s'effacent **partiellement**.","prio":"P2","sec":"s2"},{"id":"fc-d215-1ed430","poly":"dermato","fiche":"d215","front":"Lésion rouge qui s'efface même partiellement à la vitropression : est-ce un purpura ?","back":"**Non** : penser **érythème**, **télangiectasies** ou **anomalie vasculaire**.","prio":"P1","sec":"s2"},{"id":"fc-d215-12f45c","poly":"dermato","fiche":"d215","front":"Purpura récent : quand recueillir les éléments de gravité ?","back":"**D'emblée**, dès l'examen initial, avant toute enquête étiologique.","prio":"P1","sec":"s3"},{"id":"fc-d215-a2ba68","poly":"dermato","fiche":"d215","front":"Purpura : quelles sont les trois situations d'hospitalisation en grande urgence ?","back":"Purpura + **sepsis/choc** ; purpura **extensif/nécrotique** ; purpura + **atteinte muqueuse/syndrome hémorragique**.","prio":"P1","sec":"s3"},{"id":"fc-d215-50a0dc","poly":"dermato","fiche":"d215","front":"Purpura : quels signes de gravité du schéma imposent la grande urgence vitale ?","back":"Hémorragie ou lésions muqueuses, **collapsus/choc**, dyspnée/désaturation, syndrome abdominal, confusion/raideur méningée/coma, purpura nécrotique extensif.","prio":"P1","sec":"s3"},{"id":"fc-d215-9863b3","poly":"dermato","fiche":"d215","front":"Purpura sans signe de gravité : quels caractères préciser ?","back":"**Aigu ou chronique**, **plan ou infiltré**, **déclive ou disséminé**, purpura « pur » ou autres lésions (bulles, pustules, nécrose).","prio":"P2","sec":"s3"},{"id":"fc-d215-6f17f3","poly":"dermato","fiche":"d215","front":"Purpura sans signe de gravité : quels symptômes systémiques rechercher ?","back":"**AEG**, syndrome tumoral/organomégalie, **arthralgies/arthrites**, **Raynaud**, sinusite/signes respiratoires, signes neurologiques.","prio":"P2","sec":"s3"},{"id":"fc-d215-b8d802","poly":"dermato","fiche":"d215","front":"Purpura aigu : quelle conduite ?","back":"**Grande urgence** : éliminer les causes graves et faire une **numération plaquettaire**.","prio":"P1","sec":"s3"},{"id":"fc-d215-7236e6","poly":"dermato","fiche":"d215","front":"Purpura : quels sont les éléments de gravité (points clés) ?","back":"**Thrombopénie/hémorragie** ; **infection** (méningococcémie, gonococcémie, endocardite) ; **vasculite avec atteinte viscérale**.","prio":"P1","sec":"s3"},{"id":"fc-d215-aa0298","poly":"dermato","fiche":"d215","front":"Purpura, urgence éliminée : quelle distinction faut-il faire ?","back":"Entre **purpura thrombopénique** et **purpura vasculaire**.","prio":"P1","sec":"s3"},{"id":"fc-d215-0c74eb","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel est le germe principal ?","back":"Le **méningocoque** +++.","prio":"P1","sec":"s4"},{"id":"fc-d215-f33eff","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quels autres germes possibles ?","back":"**Haemophilus**, **staphylocoque**, **streptocoque**.","prio":"P2","sec":"s4"},{"id":"fc-d215-8e5f99","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel tableau est au premier plan ?","back":"Tableau **systémique** : **sepsis sévère** bactériémique ± choc septique ± troubles de la conscience.","prio":"P1","sec":"s4"},{"id":"fc-d215-f5c5ec","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel aspect du purpura ?","back":"**Ecchymotique**, **nécrotique**, **extensif** (initialement aux membres inférieurs) ± pustules.","prio":"P1","sec":"s4"},{"id":"fc-d215-b8d45a","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel risque menace les extrémités ?","back":"Atteinte fréquente avec risque d'**amputation**.","prio":"P1","sec":"s4"},{"id":"fc-d215-93ce12","poly":"dermato","fiche":"d215","front":"Purpura fulminans chez l'enfant : quelles particularités du tableau ?","back":"Tableau **parfois fruste** : pétéchies d'apparition rapide, **peu de fièvre**, parfois **hypothermie**, syndrome méningé pouvant passer inaperçu.","prio":"P1","sec":"s4"},{"id":"fc-d215-456fe5","poly":"dermato","fiche":"d215","front":"Purpura fulminans chez l'enfant : comment peut se résumer le syndrome méningé ?","back":"À une **obnubilation** ou une **asthénie intense** (ou passer inaperçu).","prio":"P2","sec":"s4"},{"id":"fc-d215-5c6108","poly":"dermato","fiche":"d215","front":"Purpura fulminans : pourquoi rechercher systématiquement le purpura ?","back":"Les lésions peuvent être **très discrètes au début**.","prio":"P1","sec":"s4"},{"id":"fc-d215-71f986","poly":"dermato","fiche":"d215","front":"Purpura avec syndrome hémorragique : quelles anomalies biologiques ?","back":"**Thrombopénie** souvent majeure (**< 10 000/mm³**) et/ou **CIVD**.","prio":"P1","sec":"s5"},{"id":"fc-d215-189f9b","poly":"dermato","fiche":"d215","front":"Purpura avec syndrome hémorragique : de quoi dépend le pronostic ?","back":"Du risque d'**hémorragies viscérales** (**méningées** +++).","prio":"P1","sec":"s5"},{"id":"fc-d215-29e872","poly":"dermato","fiche":"d215","front":"Purpura avec syndrome hémorragique : quels signes de gravité ?","back":"Hémorragies **muqueuses** ou **rétiniennes**, **céphalées**, hémorragie extériorisée ou non.","prio":"P1","sec":"s5"},{"id":"fc-d215-a35f5a","poly":"dermato","fiche":"d215","front":"Purpura avec syndrome hémorragique : quelle conduite ?","back":"**Hospitalisation en grande urgence**, diagnostic de la cause **en urgence**, traitement adapté **sans délai**.","prio":"P1","sec":"s13"},{"id":"fc-d215-f38c56","poly":"dermato","fiche":"d215","front":"Purpura avec syndrome hémorragique : faut-il banaliser des céphalées ?","back":"**Non** : signe de gravité (risque d'hémorragie méningée).","prio":"P2","sec":"s13"},{"id":"fc-d215-ae443b","poly":"dermato","fiche":"d215","front":"Purpura hématologique : quels caractères cliniques ?","back":"**Pétéchial**, **non infiltré**, **non orthostatique**, avec signes hémorragiques **mineurs** (épistaxis, gingivorragies).","prio":"P1","sec":"s6"},{"id":"fc-d215-eb5418","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : quels caractères cliniques ?","back":"**Infiltré**, surtout **orthostatique**, souvent avec de **petites nécroses centrales**.","prio":"P1","sec":"s6"},{"id":"fc-d215-a1426d","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : quels mécanismes évoquer ?","back":"Atteinte **pariétale** ou **microthrombotique**.","prio":"P2","sec":"s6"},{"id":"fc-d215-5b393a","poly":"dermato","fiche":"d215","front":"Purpura en dehors de l'urgence : quel examen dans tous les cas ?","back":"Une **numération plaquettaire rapide**.","prio":"P1","sec":"s6"},{"id":"fc-d215-a9b3ca","poly":"dermato","fiche":"d215","front":"Thrombopénie à la numération : comment la contrôler ?","back":"Sur **tube citraté**, pour éliminer une **agrégation dans le tube** (fausse thrombopénie).","prio":"P1","sec":"s6"},{"id":"fc-d215-877e2a","poly":"dermato","fiche":"d215","front":"Purpura thrombopénique : quel aspect ?","back":"**Non infiltré**, plan uniforme, pas particulièrement déclive.","prio":"P1","sec":"s6"},{"id":"fc-d215-9ba7ab","poly":"dermato","fiche":"d215","front":"Purpura vasculitique : quel aspect ?","back":"**Infiltré**, **polymorphe**, souvent **déclive**.","prio":"P1","sec":"s6"},{"id":"fc-d215-1c1303","poly":"dermato","fiche":"d215","front":"Purpura thrombotique : quel aspect ?","back":"**Infiltré** et **nécrotique**.","prio":"P1","sec":"s6"},{"id":"fc-d215-1ee550","poly":"dermato","fiche":"d215","front":"Quel type de purpura s'accompagne d'hémorragies cutanéo-muqueuses importantes ?","back":"Le purpura **thrombopénique**.","prio":"P2","sec":"s6"},{"id":"fc-d215-65790e","poly":"dermato","fiche":"d215","front":"Quel type de purpura s'accompagne le plus d'autres lésions cutanées ?","back":"Le purpura **vasculitique**.","prio":"P2","sec":"s6"},{"id":"fc-d215-8ae27d","poly":"dermato","fiche":"d215","front":"Purpura hématologique : quels signes muqueux fréquents ?","back":"**Gingivorragies**, **épistaxis**, **bulles hémorragiques** dans la bouche.","prio":"P2","sec":"s7"},{"id":"fc-d215-0cebd0","poly":"dermato","fiche":"d215","front":"Purpura non infiltré avec thrombopénie : à partir de quel seuil faire un myélogramme ?","back":"Plaquettes **< 30 000/mm³**.","prio":"P1","sec":"s7"},{"id":"fc-d215-bf28d0","poly":"dermato","fiche":"d215","front":"Myélogramme : comment distingue-t-il thrombopénie centrale et périphérique ?","back":"**Centrale** : mégacaryocytes **raréfiés** ; **périphérique** : moelle **riche** en mégacaryocytes.","prio":"P1","sec":"s7"},{"id":"fc-d215-615e84","poly":"dermato","fiche":"d215","front":"Myélogramme non contributif : quel examen ?","back":"Une **biopsie ostéomédullaire**.","prio":"P2","sec":"s7"},{"id":"fc-d215-b19655","poly":"dermato","fiche":"d215","front":"Myélogramme : que recherche-t-il en plus du mécanisme de la thrombopénie ?","back":"Une atteinte des **autres lignées**.","prio":"P2","sec":"s7"},{"id":"fc-d215-9e2832","poly":"dermato","fiche":"d215","front":"Purpuras par thrombopénie centrale : sont-ils fréquents ?","back":"**Non**, ils sont **rares** (causes hématologique, toxique, infectieuse virale…).","prio":"P2","sec":"s7"},{"id":"fc-d215-76d19f","poly":"dermato","fiche":"d215","front":"Thrombopénie périphérique : quelles causes ?","back":"**Infectieuse**, **iatrogène**, **immunologique** : **PTI** ; lupus, syndrome des anti-phospholipides.","prio":"P1","sec":"s7"},{"id":"fc-d215-600243","poly":"dermato","fiche":"d215","front":"PTI : quel mécanisme ?","back":"Des **anticorps anti-plaquettes**.","prio":"P2","sec":"s7"},{"id":"fc-d215-ee7ff8","poly":"dermato","fiche":"d215","front":"PTI : quelle forme selon l'âge ?","back":"Enfant : forme **aiguë** ++ ; adulte : forme **chronique** ++.","prio":"P3","sec":"s7"},{"id":"fc-d215-74f41e","poly":"dermato","fiche":"d215","front":"Purpura hématologique sans thrombopénie : quelles causes ?","back":"Rares : **thrombopathie acquise** (iatrogène ++, hémopathie) ou **génétique**.","prio":"P2","sec":"s7"},{"id":"fc-d215-a645f1","poly":"dermato","fiche":"d215","front":"Purpura hématologique sans thrombopénie : quelle anomalie de l'hémostase ?","back":"Un **allongement du temps de saignement**.","prio":"P3","sec":"s7"},{"id":"fc-d215-4ae6a2","poly":"dermato","fiche":"d215","front":"Purpura infiltré d'apparition aiguë : quels mécanismes évoquer ?","back":"Une **vasculite** avec localisations cutanées, ou des localisations **septiques** spécifiques.","prio":"P2","sec":"s8"},{"id":"fc-d215-dd7e6f","poly":"dermato","fiche":"d215","front":"Purpura par vasculite : quel aspect ?","back":"Lésions **polymorphes** : purpura ± érythème ± nodules dermiques.","prio":"P2","sec":"s8"},{"id":"fc-d215-2cfd80","poly":"dermato","fiche":"d215","front":"Purpura vasculaire infectieux : quelles infections en cause ?","back":"**Hépatites virales**, **EBV**, **CMV**, **endocardite** bactérienne, sepsis chronique…","prio":"P2","sec":"s8"},{"id":"fc-d215-7fbeb2","poly":"dermato","fiche":"d215","front":"Purpura vasculaire infectieux : quels types de lésions ?","back":"Lésions **spécifiques** ou **réactionnelles** (mécanisme immunitaire).","prio":"P3","sec":"s8"},{"id":"fc-d215-0c2d69","poly":"dermato","fiche":"d215","front":"Purpura pustuleux distal : qu'évoque-t-il ?","back":"Une **septicémie** ou une **endocardite**.","prio":"P2","sec":"s8"},{"id":"fc-d215-9ee4c4","poly":"dermato","fiche":"d215","front":"Purpura vasculaire médicamenteux : quelles caractéristiques ?","back":"Cause **rare** ; retenue après **imputabilité** et élimination des autres causes ; surtout vasculite **leucocytoclasique** des petits vaisseaux.","prio":"P2","sec":"s8"},{"id":"fc-d215-200e3a","poly":"dermato","fiche":"d215","front":"Quelle est la cause la plus fréquente de purpura infiltré chez l'enfant ?","back":"La **vasculite à IgA** (purpura rhumatoïde).","prio":"P1","sec":"s8"},{"id":"fc-d215-d5b814","poly":"dermato","fiche":"d215","front":"Vasculites à ANCA : quels ANCA dans la polyangéite microscopique ?","back":"**p-ANCA anti-myéloperoxydase**.","prio":"P3","sec":"s8"},{"id":"fc-d215-0cbfab","poly":"dermato","fiche":"d215","front":"Granulomatose avec polyangéite : quels ANCA ?","back":"**c-ANCA anti-protéinase 3**.","prio":"P3","sec":"s8"},{"id":"fc-d215-37559c","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : quelles autres vasculites individualisées ?","back":"**PAN** cutanée ou systémique, polyangéite microscopique, granulomatose avec polyangéite, granulomatose éosinophilique avec polyangéite.","prio":"P3","sec":"s8"},{"id":"fc-d215-e10d68","poly":"dermato","fiche":"d215","front":"Vasculites associées aux connectivites et maladies systémiques : quel type notamment ?","back":"Vasculites **leucocytoclasiques des petits vaisseaux**, notamment.","prio":"P3","sec":"s8"},{"id":"fc-d215-35570d","poly":"dermato","fiche":"d215","front":"Purpura vasculaire associé à une maladie systémique : quelles causes ?","back":"**Lupus**, PR, Gougerot-Sjögren, Behçet…, cancers, hémopathies, **cryoglobulinémies mixtes** +++.","prio":"P3","sec":"s8"},{"id":"fc-d215-62fe09","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : comment débute-t-elle ?","back":"Épisode infectieux **ORL** (inconstant), puis purpura en **poussées successives** (éléments d'âges différents).","prio":"P1","sec":"s8"},{"id":"fc-d215-532023","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : quels signes articulaires ?","back":"**Arthralgies mobiles et fugaces** des grosses articulations.","prio":"P2","sec":"s8"},{"id":"fc-d215-cc7e1d","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : quels signes digestifs ?","back":"**Douleurs abdominales** (parfois pseudo-appendiculaires) ± diarrhée/vomissements.","prio":"P1","sec":"s8"},{"id":"fc-d215-601709","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : quelle fréquence de l'atteinte rénale ?","back":"**Un tiers** des cas : **hématurie** avec **protéinurie**.","prio":"P1","sec":"s8"},{"id":"fc-d215-993eeb","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : quel pronostic et quelle durée ?","back":"Le plus souvent **bénin**, durée environ **4 semaines**.","prio":"P2","sec":"s8"},{"id":"fc-d215-fc9ac7","poly":"dermato","fiche":"d215","front":"Vasculite à IgA : quelles complications immédiates ?","back":"**Digestives** : ulcérations, perforations, hémorragies.","prio":"P1","sec":"s8"},{"id":"fc-d215-8755cf","poly":"dermato","fiche":"d215","front":"Vasculite à IgA : quelles complications à long terme ?","back":"**Rénales** (glomérulonéphrites mésangiales, prolifératives…) : **surveillance rénale au long cours**.","prio":"P1","sec":"s8"},{"id":"fc-d215-c9afde","poly":"dermato","fiche":"d215","front":"Vasculite à IgA : comment la confirmer ?","back":"**Dépôts d'IgA** dans la paroi des vaisseaux à l'**immunofluorescence directe**.","prio":"P1","sec":"s15"},{"id":"fc-d215-2febbe","poly":"dermato","fiche":"d215","front":"Microthromboses cutanées : quel aspect du purpura ?","back":"Purpura **monomorphe** à forte composante **nécrotique** (plaques > 1 cm), aigu, ± **livedo** racémeux.","prio":"P2","sec":"s9"},{"id":"fc-d215-a5e59b","poly":"dermato","fiche":"d215","front":"Livedo racémeux : quel aspect ?","back":"Livedo à **mailles larges ouvertes**.","prio":"P3","sec":"s9"},{"id":"fc-d215-fe44fb","poly":"dermato","fiche":"d215","front":"Microthromboses cutanées : quelles causes ?","back":"**CIVD**, SAPL, cryoglobuline monoclonale, cryofibrinogène, **anticoagulants** (AVK, héparines), déficit en protéine C ou S, syndromes myéloprolifératifs.","prio":"P3","sec":"s9"},{"id":"fc-d215-c6c3b0","poly":"dermato","fiche":"d215","front":"Syndrome des anti-phospholipides catastrophique : quel tableau ?","back":"**Thromboses multiples** et **défaillance multiviscérale**.","prio":"P3","sec":"s9"},{"id":"fc-d215-42b62f","poly":"dermato","fiche":"d215","front":"Purpura embolique : quel contexte clinique ?","back":"Contexte particulier avec **lésions distales**.","prio":"P2","sec":"s9"},{"id":"fc-d215-075d5f","poly":"dermato","fiche":"d215","front":"Purpura embolique : quel type d'embolie selon le terrain ?","back":"Polytraumatisé : **graisseuses** ; athérosclérose : **cristaux de cholestérol** ; cardiopathie emboligène : **cruoriques**.","prio":"P3","sec":"s9"},{"id":"fc-d215-5bc09d","poly":"dermato","fiche":"d215","front":"Purpura de Bateman : quel aspect et quel siège ?","back":"**Ecchymoses** du **dos des mains et des avant-bras**, peau atrophique avec pseudo-cicatrices étoilées.","prio":"P1","sec":"s9"},{"id":"fc-d215-efaef6","poly":"dermato","fiche":"d215","front":"Purpura de Bateman : quel terrain ?","back":"**Sujet âgé** et/ou **photo-exposé** : signe de vieillissement cutané avec atrophie.","prio":"P1","sec":"s9"},{"id":"fc-d215-837f03","poly":"dermato","fiche":"d215","front":"Purpura de Bateman : quand apparaît-il précocement ?","back":"En cas d'**hypercorticisme** (endogène ou iatrogène).","prio":"P2","sec":"s9"},{"id":"fc-d215-11f8b7","poly":"dermato","fiche":"d215","front":"Purpura de Bateman : quel mécanisme ?","back":"Purpura non infiltré par **fragilité capillaire**, sans vasculite.","prio":"P2","sec":"s9"},{"id":"fc-d215-bdce95","poly":"dermato","fiche":"d215","front":"Scorbut : quel purpura ?","back":"Purpura **périfolliculaire** + hémorragies muqueuses ± asthénie ± myalgies (carence en **vitamine C**).","prio":"P2","sec":"s9"},{"id":"fc-d215-93c7ba","poly":"dermato","fiche":"d215","front":"Purpura mécanique : dans quelles circonstances ?","back":"À la **pression**, à l'**effort** (vomissements).","prio":"P3","sec":"s9"},{"id":"fc-d215-915a9e","poly":"dermato","fiche":"d215","front":"Capillarite chronique purpurique : à quoi est-elle liée ?","back":"À l'**insuffisance veineuse chronique** ; évolue par poussées, avec **dermatite ocre** séquellaire.","prio":"P3","sec":"s9"},{"id":"fc-d215-f07041","poly":"dermato","fiche":"d215","front":"Purpura vasculaire suspecté : comment le confirmer ?","back":"**Biopsie cutanée** (histologie) avec **immunofluorescence directe** (dépôts d'IgA), idéalement sur **lésions récentes**.","prio":"P1","sec":"s10"},{"id":"fc-d215-e1eefb","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : quel bilan de gravité ?","back":"Rechercher une atteinte **rénale**, **neurologique**, **cardiopulmonaire** ou **digestive**.","prio":"P1","sec":"s10"},{"id":"fc-d215-2ccbac","poly":"dermato","fiche":"d215","front":"Purpura d'allure vasculaire : que rechercher à l'interrogatoire ?","back":"**Antécédents**, **médicaments** pris, affection **emboligène**.","prio":"P2","sec":"s10"},{"id":"fc-d215-517814","poly":"dermato","fiche":"d215","front":"Purpura d'allure vasculaire : quels éléments rechercher à l'examen ?","back":"AEG, adénomégalie, hépatosplénomégalie, arthralgies, myalgies, **HTA**, signes digestifs, neurologiques, ORL, oculaires, urogénitaux.","prio":"P2","sec":"s10"},{"id":"fc-d215-e58660","poly":"dermato","fiche":"d215","front":"Purpura d'allure vasculaire : quel bilan sanguin initial minimal ?","back":"Hémogramme, plaquettes, **CRP**, ionogramme, **créatininémie**, électrophorèse des protéines, transaminases, LDH.","prio":"P3","sec":"s10"},{"id":"fc-d215-226503","poly":"dermato","fiche":"d215","front":"Purpura d'allure vasculaire : quel bilan urinaire initial ?","back":"**Protéinurie** sur échantillon et des 24 h, **sédiment urinaire**.","prio":"P2","sec":"s10"},{"id":"fc-d215-dd1cdf","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : dans quelle proportion aucune cause n'est retrouvée ?","back":"Environ **50 %** des cas.","prio":"P2","sec":"s10"},{"id":"fc-d215-87a9dd","poly":"dermato","fiche":"d215","front":"Purpura fulminans hors de l'hôpital : quel critère déclenche l'antibiothérapie ?","back":"**Fièvre + purpura nécrotique** avec **au moins un élément > 3 mm** de diamètre.","prio":"P1","sec":"s11"},{"id":"fc-d215-384022","poly":"dermato","fiche":"d215","front":"Purpura fulminans hors de l'hôpital : quand et comment injecter l'antibiotique ?","back":"**Immédiatement, sur place**, par voie **IV ou IM**, avant le transfert.","prio":"P1","sec":"s11"},{"id":"fc-d215-0d915d","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel antibiotique et quelle dose chez l'enfant ?","back":"**Ceftriaxone 100 mg/kg** IV ou IM.","prio":"P1","sec":"s11"},{"id":"fc-d215-fe76ed","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel antibiotique et quelle dose chez l'adulte ?","back":"**Ceftriaxone 2 g** IV ou IM.","prio":"P1","sec":"s11"},{"id":"fc-d215-4a815a","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quelle alternative à la ceftriaxone et à quelle dose ?","back":"**Amoxicilline** : enfant **50 mg/kg**, adulte **2 g**, IV ou IM.","prio":"P1","sec":"s11"},{"id":"fc-d215-bbb094","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quel transfert après l'antibiotique ?","back":"**Transfert médicalisé** en urgence par le **SAMU/SMUR**, en **alertant le centre receveur**.","prio":"P1","sec":"s11"},{"id":"fc-d215-32a01c","poly":"dermato","fiche":"d215","front":"Purpura fulminans : quelle prise en charge hospitalière ?","back":"**Soins intensifs** / réanimation (urgence extrême).","prio":"P2","sec":"s11"},{"id":"fc-d215-371766","poly":"dermato","fiche":"d215","front":"Enfant avec purpura : quelle infection éliminer même si la vasculite à IgA est plus fréquente ?","back":"Une **méningococcémie**.","prio":"P1","sec":"s11"},{"id":"fc-d215-02ed67","poly":"dermato","fiche":"d215","front":"Purpura récent avec fièvre : à quoi se reporter ?","back":"Aux **signes de gravité** du schéma de prise en charge.","prio":"P3","sec":"s12"},{"id":"fc-d215-8149b3","poly":"dermato","fiche":"d215","front":"Purpura sans gravité, non infiltré, avec petits saignements : quel type évoquer ?","back":"Un purpura **hématologique**, surtout **thrombopénique**.","prio":"P2","sec":"s14"},{"id":"fc-d215-845f3b","poly":"dermato","fiche":"d215","front":"Purpura infiltré surtout orthostatique : quel examen ?","back":"Une **biopsie cutanée** (purpura vasculaire suspecté).","prio":"P1","sec":"s14"},{"id":"fc-d215-5e0d50","poly":"dermato","fiche":"d215","front":"Purpura vasculaire : quelles grandes causes ?","back":"**Infection**, **vasculite** « entité » ou « associée », **thrombose**, **emboles**, **iatrogénie**.","prio":"P2","sec":"s14"},{"id":"fc-d215-756185","poly":"dermato","fiche":"d215","front":"Purpura plan subaigu ou chronique par fragilité capillaire : quels examens ?","back":"**Aucun examen** selon le schéma, mais seulement après la **numération plaquettaire**, faite **dans tous les cas**.","prio":"P2","sec":"s14"},{"id":"fc-d215-492326","poly":"dermato","fiche":"d215","front":"Vasculite à IgA de l'enfant : quelle surveillance en phase aiguë ?","back":"Surveillance **digestive** (ulcérations, perforations, hémorragies).","prio":"P2","sec":"s15"},{"id":"fc-d215-3a4c99","poly":"dermato","fiche":"d215","front":"Vasculite à IgA : quel piège abdominal ?","back":"Douleurs simulant une **appendicite** (tableau pseudo-appendiculaire).","prio":"P2","sec":"s15"},{"id":"fc-d228-3be13f","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : définition ?","back":"Plaie de la jambe **sans cicatrisation depuis plus d'un mois**.","prio":"P1","sec":"s1"},{"id":"fc-d228-06efda","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : qu'est-ce qui conditionne pronostic et traitement ?","back":"La **maladie vasculaire sous-jacente** dont il est la complication.","prio":"P1","sec":"s1"},{"id":"fc-d228-6b705b","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : quel retentissement en santé publique ?","back":"Affection **fréquente**, **invalidante**, source de **nombreuses hospitalisations**.","prio":"P2","sec":"s1"},{"id":"fc-d228-1a13c5","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : prévalence selon l'âge ?","back":"**1 %** de 60 à 70 ans ; **2 à 5 %** après 80 ans.","prio":"P2","sec":"s1"},{"id":"fc-d228-1f43f6","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quel sex-ratio ?","back":"**Prédominance féminine** (sex-ratio 1/1,6 ; 1,5 fois plus fréquent chez la femme dans le tableau).","prio":"P2","sec":"s1"},{"id":"fc-d228-02f7fb","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : quelles sont les causes les plus fréquentes ?","back":"Insuffisance **veineuse**, insuffisance **artérielle**, ulcères **mixtes**, **angiodermite nécrotique**.","prio":"P1","sec":"s1"},{"id":"fc-d228-816baf","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : quelles causes sont plus rares ?","back":"Ulcères **infectieux**, **neurotrophiques**, **dysimmunitaires**, **néoplasiques** ; vasculites : rares.","prio":"P2","sec":"s1"},{"id":"fc-d228-bd45ac","poly":"dermato","fiche":"d228","front":"Ulcère veineux pur : quel mécanisme central ?","back":"Une **hypertension veineuse**.","prio":"P2","sec":"s2"},{"id":"fc-d228-c10b65","poly":"dermato","fiche":"d228","front":"Hypertension veineuse : quelles origines possibles ?","back":"**Reflux superficiel/perforantes** (varices) ; **reflux et/ou obstruction profonde** (post-thrombotique) ; **déficience de la pompe musculaire du mollet**.","prio":"P2","sec":"s2"},{"id":"fc-d228-ce8691","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quel événement peut le déclencher ?","back":"Un **petit traumatisme**, sur une peau en souffrance microcirculatoire.","prio":"P3","sec":"s2"},{"id":"fc-d228-a96f8d","poly":"dermato","fiche":"d228","front":"Microangiopathie veineuse : quelles anomalies capillaires ?","back":"Capillaires **dilatés et raréfiés**, détruits par l'activation des **leucocytes** (radicaux libres), **facteurs de croissance piégés**, fuite (œdème).","prio":"P3","sec":"s2"},{"id":"fc-d228-1aac66","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quel mécanisme ?","back":"**Ischémie** : défaut de perfusion artérielle et baisse de l'**oxygénation tissulaire** locale.","prio":"P2","sec":"s2"},{"id":"fc-d228-1c87de","poly":"dermato","fiche":"d228","front":"Ulcère mixte à prédominance veineuse : quel mécanisme ?","back":"Mécanisme surtout **veineux** avec une **AOMI modérée** qui n'explique pas à elle seule l'ulcère.","prio":"P2","sec":"s2"},{"id":"fc-d228-6d3ace","poly":"dermato","fiche":"d228","front":"Examen d'un ulcère : quels éléments décrire ?","back":"**Nombre**, **taille**, **siège** (uni- ou bilatéral), **fond**, **bords**, peau péri-ulcéreuse.","prio":"P2","sec":"s3"},{"id":"fc-d228-6320bf","poly":"dermato","fiche":"d228","front":"Ulcère : quels aspects possibles du fond ?","back":"Propre, surinfecté/purulent, **bourgeonnant**, **fibrineux** (enduit jaunâtre adhérent), **nécrotique noirâtre**.","prio":"P2","sec":"s3"},{"id":"fc-d228-b7a517","poly":"dermato","fiche":"d228","front":"Ulcère : quels bords sont de bon pronostic ?","back":"Bords **souples**, **au même niveau** que l'ulcère.","prio":"P2","sec":"s3"},{"id":"fc-d228-caaafc","poly":"dermato","fiche":"d228","front":"Ulcère : quels bords annoncent une cicatrisation retardée ?","back":"Bords **durs**, **en saillie** au-dessus de l'ulcère.","prio":"P2","sec":"s3"},{"id":"fc-d228-7f82b9","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : la peau péri-ulcéreuse est-elle normale ?","back":"**Rarement normale** : elle traduit les complications cutanées de la maladie vasculaire (surtout dans les ulcères **veineux**).","prio":"P2","sec":"s3"},{"id":"fc-d228-3668a4","poly":"dermato","fiche":"d228","front":"Artériopathie : quel aspect de la peau autour de l'ulcère ?","back":"Peau **luisante, dépilée**, **froide** ; **pâleur** à la surélévation, **cyanose de déclivité**, recoloration pulpaire **allongée**.","prio":"P1","sec":"s3"},{"id":"fc-d228-49b061","poly":"dermato","fiche":"d228","front":"Eczéma variqueux : quel aspect ?","back":"Plaques **érythémato-squameuses** prurigineuses, débutant souvent en région **malléolaire interne**.","prio":"P2","sec":"s3"},{"id":"fc-d228-a95d72","poly":"dermato","fiche":"d228","front":"Dermite ocre : quel aspect et pourquoi cette couleur ?","back":"Larges macules **rouge violacé** puis **brunes** (dépôts d'**hémosidérine**), malléolaires internes ou prétibiales.","prio":"P1","sec":"s3"},{"id":"fc-d228-167734","poly":"dermato","fiche":"d228","front":"Atrophie blanche : quel aspect ?","back":"Petites plaques atrophiques couleur **ivoire**, parfois télangiectasiques, souvent **douloureuses**, à forte tendance à **s'ulcérer**.","prio":"P1","sec":"s3"},{"id":"fc-d228-9ebe45","poly":"dermato","fiche":"d228","front":"Capillarités hypertrophiques : quel aspect ?","back":"**Chevelus capillaires** malléolaires ou du dos du pied.","prio":"P3","sec":"s3"},{"id":"fc-d228-096a3b","poly":"dermato","fiche":"d228","front":"Hypodermite aiguë ou subaiguë veineuse : quel tableau ?","back":"**Grosse jambe rouge et douloureuse**, installée **progressivement**, **sans fièvre**.","prio":"P1","sec":"s3"},{"id":"fc-d228-0d12db","poly":"dermato","fiche":"d228","front":"Lipodermatosclérose : quel aspect ?","back":"Mollet **dur**, peau **scléreuse** pigmentée, véritable **guêtre rétractile** (après hypodermites ou d'emblée).","prio":"P2","sec":"s3"},{"id":"fc-d228-7cacc8","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quel terrain typique ?","back":"**Femme de plus de 50 ans**, **surpoids**.","prio":"P1","sec":"s4"},{"id":"fc-d228-26a1c3","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quel terrain typique ?","back":"**Homme de plus de 50 ans** ; **tabac**, **HTA**, **diabète**, obésité, **dyslipidémie**.","prio":"P1","sec":"s4"},{"id":"fc-d228-157913","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quelles caractéristiques de l'ulcère ?","back":"**Unique**, **grand**, **moyennement douloureux**, **périmalléolaire** (jusqu'au 1/3 inférieur du mollet).","prio":"P1","sec":"s4"},{"id":"fc-d228-94a143","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quelles caractéristiques de l'ulcère ?","back":"Unique ou multiple, **creusant**, **à l'emporte-pièce**, mettant parfois à nu les structures ; siège **suspendu** ou **distal** (orteils).","prio":"P1","sec":"s4"},{"id":"fc-d228-a8281b","poly":"dermato","fiche":"d228","front":"Ulcère veineux : que trouve l'examen vasculaire ?","back":"**Varices** ; examen artériel **normal** ; **œdème** (plus marqué si post-phlébitique).","prio":"P1","sec":"s4"},{"id":"fc-d228-dac81f","poly":"dermato","fiche":"d228","front":"Ulcère artériel : que trouve l'examen vasculaire ?","back":"Un ou plusieurs **pouls périphériques abolis** ; douleur habituellement **intense**.","prio":"P1","sec":"s4"},{"id":"fc-d228-f18c44","poly":"dermato","fiche":"d228","front":"Ulcère : quels signes orientent vers une cause artérielle ou artériolaire ?","back":"**Douleur**, surtout **de décubitus**, et **extension nécrotique**.","prio":"P1","sec":"s4"},{"id":"fc-d228-766836","poly":"dermato","fiche":"d228","front":"Ulcère mixte : définition ?","back":"Causes **artérielle et veineuse** mises en évidence **en même temps**.","prio":"P2","sec":"s4"},{"id":"fc-d228-f2ae7a","poly":"dermato","fiche":"d228","front":"Quels ulcères de jambe sont les plus chroniques ?","back":"Les ulcères **post-thrombotiques**.","prio":"P2","sec":"s4"},{"id":"fc-d228-d06a1b","poly":"dermato","fiche":"d228","front":"Ulcère : quels signes d'insuffisance veineuse rechercher à l'interrogatoire ?","back":"**Jambes lourdes**, phlébalgies, **œdème vespéral**, crampes au repos.","prio":"P2","sec":"s5"},{"id":"fc-d228-88cc87","poly":"dermato","fiche":"d228","front":"Ulcère : quels antécédents veineux rechercher ?","back":"**Varices**, **thromboses veineuses** profondes ou superficielles, **embolie pulmonaire**, traumatisme/chirurgie des membres inférieurs.","prio":"P2","sec":"s5"},{"id":"fc-d228-55819d","poly":"dermato","fiche":"d228","front":"Ulcère : quels signes d'artériopathie rechercher à l'interrogatoire ?","back":"**Claudication intermittente**, **douleurs de décubitus**.","prio":"P1","sec":"s5"},{"id":"fc-d228-15f595","poly":"dermato","fiche":"d228","front":"Ulcère : quels facteurs de risque vasculaire rechercher à l'interrogatoire ?","back":"**Diabète**, **HTA**, **tabagisme**, antécédent d'**AVC** ou d'**ischémie myocardique**.","prio":"P2","sec":"s5"},{"id":"fc-d228-94b70d","poly":"dermato","fiche":"d228","front":"Ulcère : que rechercher à l'examen clinique vasculaire ?","back":"**Pouls périphériques**, auscultation artérielle (membres, cou), **varices debout**, **couronne phlébectasique**, cicatrices d'ulcères, **dénutrition**.","prio":"P2","sec":"s5"},{"id":"fc-d228-54588b","poly":"dermato","fiche":"d228","front":"Tout ulcère de jambe : quel bilan vasculaire minimal ?","back":"**Examen vasculaire complet** + **échographie Doppler veineuse et/ou artérielle** avec mesure de l'**IPS**.","prio":"P1","sec":"s5"},{"id":"fc-d228-72d6c0","poly":"dermato","fiche":"d228","front":"IPS : comment le calcule-t-on et quelle valeur normale ?","back":"**Pression tibiale / pression humérale** ; normale **1 à 1,3**.","prio":"P2","sec":"s5"},{"id":"fc-d228-18f52c","poly":"dermato","fiche":"d228","front":"Doppler veineux devant un ulcère : quel apport ?","back":"Confirme l'origine veineuse, précise le mécanisme (**reflux** ou **obstruction**) et oriente le traitement.","prio":"P1","sec":"s5"},{"id":"fc-d228-62bbe0","poly":"dermato","fiche":"d228","front":"Doppler veineux : un reflux profond est quasi synonyme de quoi ?","back":"D'un **syndrome post-thrombotique**.","prio":"P2","sec":"s5"},{"id":"fc-d228-3e9c98","poly":"dermato","fiche":"d228","front":"Doppler veineux devant un ulcère : par quelle mesure est-il systématiquement complété, et pourquoi ?","back":"Par la mesure de l'**IPS**, pour rechercher une **AOMI** associée.","prio":"P3","sec":"s5"},{"id":"fc-d228-f10459","poly":"dermato","fiche":"d228","front":"Ulcère veineux : dans quels cas ajouter un Doppler artériel ?","back":"**Pouls abolis**, symptômes/signes d'**AOMI**, ou **IPS < 0,9 ou > 1,3**.","prio":"P1","sec":"s5"},{"id":"fc-d228-b14c1c","poly":"dermato","fiche":"d228","front":"IPS > 1,3 : quelle interprétation et quel terrain fréquent ?","back":"Artères **calcifiées incompressibles**, souvent chez le **diabétique**.","prio":"P2","sec":"s5"},{"id":"fc-d228-b6024f","poly":"dermato","fiche":"d228","front":"IPS entre 0,9 et 1,3 : quelle interprétation ?","back":"Ulcère **veineux pur** (pas d'AOMI).","prio":"P2","sec":"s5"},{"id":"fc-d228-f7b135","poly":"dermato","fiche":"d228","front":"IPS entre 0,7 et 0,9 : quelle interprétation ?","back":"Ulcère **mixte à prédominance veineuse** (l'AOMI n'explique pas l'ulcère).","prio":"P1","sec":"s5"},{"id":"fc-d228-29094f","poly":"dermato","fiche":"d228","front":"Doppler artériel : que cherche-t-il en plus des lésions artérielles des membres ?","back":"Un **anévrisme de l'aorte abdominale**, source d'emboles.","prio":"P3","sec":"s5"},{"id":"fc-d228-46d05d","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quel examen est indispensable à la décision opératoire ?","back":"L'**angiographie** (siège, longueur de l'oblitération, plaques emboligènes).","prio":"P1","sec":"s5"},{"id":"fc-d228-8590a8","poly":"dermato","fiche":"d228","front":"PO₂ transcutanée : quel intérêt ?","back":"Reflet de l'**oxygénation cutanée** ; aide à décider d'une intervention et de son niveau (**revascularisation**, **amputation**).","prio":"P2","sec":"s5"},{"id":"fc-d228-56007c","poly":"dermato","fiche":"d228","front":"Ischémie critique : quels seuils de pression ?","back":"PAS **< 50 mmHg à la cheville** ou **< 30 mmHg au gros orteil**.","prio":"P2","sec":"s5"},{"id":"fc-d228-8c3de6","poly":"dermato","fiche":"d228","front":"Ischémie critique : quelle conduite ?","back":"**Hospitalisation** recommandée en **milieu spécialisé**.","prio":"P2","sec":"s5"},{"id":"fc-d228-d7741c","poly":"dermato","fiche":"d228","front":"Ulcère : pourquoi évaluer le handicap locomoteur ?","back":"Une **déambulation réduite** diminue les chances de **succès thérapeutique** et de récupération.","prio":"P2","sec":"s5"},{"id":"fc-d228-3b65ad","poly":"dermato","fiche":"d228","front":"Ulcère : quels handicaps locomoteurs rechercher ?","back":"**Ankylose de cheville** (souvent secondaire à l'ulcère), **coxarthrose**, **gonarthrose**, déformations des pieds.","prio":"P2","sec":"s5"},{"id":"fc-d228-53b22c","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : définition ?","back":"**Infarctus cutané** par **occlusion artériolaire** (artériolosclérose du derme).","prio":"P2","sec":"s6"},{"id":"fc-d228-76c145","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : quel terrain ?","back":"**Femme après 60 ans**, **HTA**, **diabète**.","prio":"P2","sec":"s6"},{"id":"fc-d228-11eeae","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : quel début et quelle évolution ?","back":"Début **brutal** par une plaque **purpurique ou livédoïde** extensive → **nécrose noirâtre** rapide.","prio":"P2","sec":"s6"},{"id":"fc-d228-3bfb12","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : quel aspect des ulcérations ?","back":"Ulcérations **superficielles** à bords en « **carte de géographie** ».","prio":"P2","sec":"s6"},{"id":"fc-d228-1ff256","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : quel siège et quelle douleur ?","back":"Siège **suspendu**, face **antéro-externe** de jambe ; douleurs **très importantes, insomniantes**.","prio":"P2","sec":"s6"},{"id":"fc-d228-f2c34f","poly":"dermato","fiche":"d228","front":"Angiodermite nécrotique : quels résultats des examens ?","back":"**Grands axes** artériels et veineux **normaux** ; cryoglobulinémie, FAN et ANCA **négatifs**.","prio":"P3","sec":"s6"},{"id":"fc-d228-bf2751","poly":"dermato","fiche":"d228","front":"Ulcères des vasculites : citer des causes ?","back":"**PR**, PAN, granulomatose avec polyangéite, **lupus** (surtout avec SAPL), emboles de **cristaux de cholestérol**, **cryoglobulinémies**.","prio":"P3","sec":"s6"},{"id":"fc-d228-8cc81d","poly":"dermato","fiche":"d228","front":"Ulcère : quand chercher une autre cause que vasculaire ?","back":"Examens vasculaires **normaux**, évolution **rapide**, pas de cicatrisation après **2 à 3 mois** de traitement bien conduit, aspect anormal, **siège atypique**.","prio":"P2","sec":"s7"},{"id":"fc-d228-d9453b","poly":"dermato","fiche":"d228","front":"Pyoderma gangrenosum : quelle lésion élémentaire et quel aspect ?","back":"**Pustule** → ulcération **douloureuse** extensive, clapiers purulents, **bourrelet périphérique violacé**.","prio":"P2","sec":"s7"},{"id":"fc-d228-78d706","poly":"dermato","fiche":"d228","front":"Pyoderma gangrenosum : quelles maladies associées ?","back":"**Hémopathie** (myéloprolifératif, myélodysplasie) ou **MICI**, dans 1/3 à 2/3 des cas.","prio":"P2","sec":"s7"},{"id":"fc-d228-ed1d03","poly":"dermato","fiche":"d228","front":"Ulcère de cause infectieuse : citer des causes ?","back":"Mycobactérioses dont **tuberculose**, **mycoses profondes**, **parasitoses**.","prio":"P3","sec":"s7"},{"id":"fc-d228-a32714","poly":"dermato","fiche":"d228","front":"Ulcère du sujet jeune de cause hématologique : quelle maladie ?","back":"La **drépanocytose**.","prio":"P3","sec":"s7"},{"id":"fc-d228-f0b17f","poly":"dermato","fiche":"d228","front":"Ulcères des syndromes myéloprolifératifs ou dysglobulinémies : quel aspect ?","back":"Ulcération souvent **superficielle et nécrotique**.","prio":"P3","sec":"s7"},{"id":"fc-d228-0954b4","poly":"dermato","fiche":"d228","front":"Ulcère iatrogène : quel médicament cité et quelle évolution à l'arrêt ?","back":"**Hydroxyurée** ; cicatrisation **lente** après l'arrêt.","prio":"P2","sec":"s7"},{"id":"fc-d228-29bd41","poly":"dermato","fiche":"d228","front":"Pathomimie : comment la retenir ?","back":"Diagnostic **d'élimination** (ulcères inhabituels, rebelles) ; **avis psychiatrique** nécessaire.","prio":"P3","sec":"s7"},{"id":"fc-d228-9158e0","poly":"dermato","fiche":"d228","front":"Mal perforant plantaire : quelles caractéristiques ?","back":"Ulcération **neurologique** de la **plante**, sur **points d'appui**, **indolore**, débutant par une **hyperkératose**.","prio":"P2","sec":"s7"},{"id":"fc-d228-09d640","poly":"dermato","fiche":"d228","front":"Mal perforant plantaire : quelles causes ?","back":"**Diabète** ; neuropathies sensitives familiales (Thévenard) ou acquises (**alcool**, lèpre) ; anomalies **médullaires** (spina bifida).","prio":"P3","sec":"s7"},{"id":"fc-d228-757451","poly":"dermato","fiche":"d228","front":"Ulcérations tumorales de jambe : quelles tumeurs ?","back":"Surtout carcinomes **épidermoïdes**, **basocellulaires**, **lymphomes** ; plus rarement **mélanomes** ulcérés.","prio":"P3","sec":"s7"},{"id":"fc-d228-499677","poly":"dermato","fiche":"d228","front":"Ulcère variqueux : délai de cicatrisation sous traitement bien conduit ?","back":"**3 à 6 mois** ; mais récidive et chronicité **non rares**.","prio":"P1","sec":"s8"},{"id":"fc-d228-0d4ea2","poly":"dermato","fiche":"d228","front":"Ulcère post-thrombotique : pourquoi est-il plus rebelle ?","back":"Troubles péri-ulcéreux importants, perturbations **hémodynamiques**, traitement de la cause **difficile**.","prio":"P2","sec":"s8"},{"id":"fc-d228-bb3f39","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quand peut-il cicatriser ?","back":"Si un **traitement de la cause** est possible (**pontage**, dilatation artérielle…).","prio":"P2","sec":"s8"},{"id":"fc-d228-f5be78","poly":"dermato","fiche":"d228","front":"Ulcère artériel sans revascularisation possible : pourquoi amputer parfois ?","back":"**Douleur**, risque **septique** (gangrène gazeuse), **décompensation viscérale** (IR sur rhabdomyolyse, hyperkaliémie).","prio":"P2","sec":"s8"},{"id":"fc-d228-ca3b4a","poly":"dermato","fiche":"d228","front":"Ulcère : pourquoi la dermatite de contact est-elle fréquente ?","back":"**Nombreux topiques** appliqués sur une **barrière cutanée altérée**.","prio":"P1","sec":"s8"},{"id":"fc-d228-b7f629","poly":"dermato","fiche":"d228","front":"Dermatite de contact péri-ulcéreuse : quel aspect ?","back":"Érythème **microvésiculeux** prurigineux, d'abord limité à la zone d'application, puis diffusion possible à distance.","prio":"P2","sec":"s8"},{"id":"fc-d228-b8646e","poly":"dermato","fiche":"d228","front":"Ulcère : quels allergènes de contact principaux ?","back":"**Baume du Pérou**, certains **antiseptiques**, **fragrances**, **lanoline**, conservateurs, certains pansements.","prio":"P1","sec":"s8"},{"id":"fc-d228-067d73","poly":"dermato","fiche":"d228","front":"Germes isolés sur un ulcère : quelle signification ?","back":"Une **colonisation**, **non pathologique**.","prio":"P1","sec":"s8"},{"id":"fc-d228-f31249","poly":"dermato","fiche":"d228","front":"Ulcère : quels signes évoquent une infection patente ?","back":"**Douleur locale** croissante, **inflammation des bords** (non spécifique), **lymphangite**, **fièvre**.","prio":"P1","sec":"s8"},{"id":"fc-d228-5b336e","poly":"dermato","fiche":"d228","front":"Ulcère infecté : quelles infections possibles ?","back":"**Dermohypodermite bactérienne** ; très rarement **fasciite nécrosante** ; **gangrène gazeuse** (anaérobies) sur ulcère artériel.","prio":"P2","sec":"s8"},{"id":"fc-d228-407d60","poly":"dermato","fiche":"d228","front":"Ulcère : quelles complications ostéo-articulaires ?","back":"**Très fréquentes** : périostite, ostéopériostite, jusqu'à l'**ankylose de la cheville** ; attitudes vicieuses.","prio":"P2","sec":"s8"},{"id":"fc-d228-beae4a","poly":"dermato","fiche":"d228","front":"Hémorragie sur ulcère : sur quel type et quel mécanisme ?","back":"Souvent ulcère **veineux**, par saignement d'une **varice**.","prio":"P2","sec":"s8"},{"id":"fc-d228-b50058","poly":"dermato","fiche":"d228","front":"Carcinome épidermoïde sur ulcère : quels signes d'alerte ?","back":"Ulcère **chronique**, apparition de **douleurs**, **hémorragie** locale, **bourgeonnement excessif**.","prio":"P1","sec":"s8"},{"id":"fc-d228-227038","poly":"dermato","fiche":"d228","front":"Carcinome épidermoïde sur ulcère : fréquence et diagnostic ?","back":"**Rare et tardif** ; diagnostic par **biopsie**, parfois à **répéter**.","prio":"P1","sec":"s8"},{"id":"fc-d228-ff5557","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quelles sont les principales complications ?","back":"La **sensibilisation allergique** aux topiques et les **surinfections**.","prio":"P1","sec":"s8"},{"id":"fc-d228-0c8561","poly":"dermato","fiche":"d228","front":"Ulcère de jambe : quelle prévention infectieuse systématique ?","back":"**Vaccination antitétanique** chez tout malade **non immunisé**.","prio":"P1","sec":"s8"},{"id":"fc-d228-971a05","poly":"dermato","fiche":"d228","front":"Ulcère : pourquoi le traitement de la cause est-il indispensable ?","back":"Il améliore nettement l'**hémodynamique** et limite le **risque de récidive**.","prio":"P1","sec":"s9"},{"id":"fc-d228-a6e0e7","poly":"dermato","fiche":"d228","front":"Ulcère : de quoi dépend le niveau de compression ?","back":"De l'**IPS**.","prio":"P1","sec":"s9"},{"id":"fc-d228-b24654","poly":"dermato","fiche":"d228","front":"Ulcère veineux : la compression est-elle systématique ?","back":"**Oui** : elle combat l'**œdème** et réduit le **reflux** par effet mécanique.","prio":"P1","sec":"s10"},{"id":"fc-d228-99ae34","poly":"dermato","fiche":"d228","front":"Ulcère veineux sans AOMI : quel niveau de compression ?","back":"**30 à 40 mmHg** à la cheville si **IPS entre 0,8 et 1,3**.","prio":"P1","sec":"s10"},{"id":"fc-d228-5a914b","poly":"dermato","fiche":"d228","front":"Ulcère veineux : quel type de compression et quelle durée de port ?","back":"Systèmes **multicouches**, portés **toute la journée** ; veiller à l'**observance**.","prio":"P2","sec":"s10"},{"id":"fc-d228-39c743","poly":"dermato","fiche":"d228","front":"Ulcère veineux non post-thrombotique : quel traitement chirurgical en priorité ?","back":"**Éveinage** de l'insuffisance veineuse superficielle.","prio":"P1","sec":"s10"},{"id":"fc-d228-325b24","poly":"dermato","fiche":"d228","front":"Éveinage : quelle contre-indication ?","back":"Une **obstruction** ou un **reflux veineux profond axial**.","prio":"P1","sec":"s10"},{"id":"fc-d228-21166b","poly":"dermato","fiche":"d228","front":"Sclérothérapie dans l'ulcère veineux : quelle place ?","back":"Pas d'étude comparative ; surtout **en complément de la chirurgie**.","prio":"P3","sec":"s10"},{"id":"fc-d228-ca8ddb","poly":"dermato","fiche":"d228","front":"Ulcère : quelles indications de la greffe ?","back":"Ulcère **> 10 cm²** ou **rebelle depuis plus de 6 mois** au traitement conventionnel.","prio":"P1","sec":"s10"},{"id":"fc-d228-0601cb","poly":"dermato","fiche":"d228","front":"Ulcère : quels types de greffe et quels bénéfices ?","back":"Greffe **en pastilles** ou **en filet/résille** : **diminue la douleur**, **raccourcit** la cicatrisation.","prio":"P2","sec":"s13"},{"id":"fc-d228-9c7595","poly":"dermato","fiche":"d228","front":"Ulcère : les récidives sont-elles fréquentes ?","back":"**Oui**, fréquentes : elles doivent être **prévenues**.","prio":"P2","sec":"s10"},{"id":"fc-d228-4142d5","poly":"dermato","fiche":"d228","front":"Ulcère mixte à prédominance veineuse : quelle prise en charge de la cause ?","back":"**Prendre en charge l'AOMI** + compression **allégée**.","prio":"P1","sec":"s11"},{"id":"fc-d228-e3e5f9","poly":"dermato","fiche":"d228","front":"Ulcère mixte : quelle compression ?","back":"**< 30 mmHg**, seulement si **IPS > 0,7**, bandes à **étirement court**, sous **surveillance médicale**.","prio":"P1","sec":"s11"},{"id":"fc-d228-79398b","poly":"dermato","fiche":"d228","front":"Ulcère mixte : quelle erreur de compression éviter ?","back":"Appliquer la compression **forte (30-40 mmHg)** de l'ulcère veineux pur.","prio":"P1","sec":"s11"},{"id":"fc-d228-256a1f","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quel traitement envisager en priorité ?","back":"La **chirurgie** : **désobstruction**, **pontage**, **sympathectomie** (selon Doppler et angiographie).","prio":"P1","sec":"s12"},{"id":"fc-d228-798f52","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quel traitement médical ?","back":"**Vasodilatateurs** et **analogues de la prostacycline**.","prio":"P2","sec":"s12"},{"id":"fc-d228-2800db","poly":"dermato","fiche":"d228","front":"Prostacycline : quelle indication dans l'ulcère artériel ?","back":"**Ischémie grave** quand la chirurgie n'est **pas indiquée** ou **contre-indiquée**.","prio":"P2","sec":"s12"},{"id":"fc-d228-576d97","poly":"dermato","fiche":"d228","front":"Ulcère artériel : quels facteurs de risque contrôler ?","back":"**Arrêt du tabac**, équilibre du **diabète**, **hyperlipidémie**, **HTA**, **perte de poids** ; **antiagrégants** si besoin.","prio":"P1","sec":"s12"},{"id":"fc-d228-ca1e84","poly":"dermato","fiche":"d228","front":"Soins locaux de l'ulcère : quelles trois phases ?","back":"**Détersion**, **bourgeonnement**, **épithélialisation**.","prio":"P1","sec":"s13"},{"id":"fc-d228-41ef93","poly":"dermato","fiche":"d228","front":"Soins locaux : condition de réussite ?","back":"Une bonne **coopération médecin-infirmier(e)**.","prio":"P3","sec":"s13"},{"id":"fc-d228-f643df","poly":"dermato","fiche":"d228","front":"Détersion : comment nettoyer l'ulcère ?","back":"À la **douchette** (l'eau stérile ne sert à rien) ; **pas d'antiseptique** sans infection déclarée.","prio":"P1","sec":"s13"},{"id":"fc-d228-4a3e89","poly":"dermato","fiche":"d228","front":"Détersion mécanique : quels instruments et quelle analgésie ?","back":"**Bistouri**, **curette**, **ciseaux** ; topique anesthésique ou **MEOPA** ; anesthésie locorégionale si trop douloureux.","prio":"P2","sec":"s13"},{"id":"fc-d228-c4030a","poly":"dermato","fiche":"d228","front":"Phase de détersion : quels pansements ?","back":"**Alginates** et **hydrogels**, laissés **48 à 72 h** selon l'exsudat, sans infection patente.","prio":"P1","sec":"s13"},{"id":"fc-d228-022f6c","poly":"dermato","fiche":"d228","front":"Phase de bourgeonnement : quels pansements ?","back":"**Tulles vaselinés** (sans baume du Pérou), **hydrocolloïdes**, **hydrocellulaires**, **interfaces**.","prio":"P1","sec":"s13"},{"id":"fc-d228-681247","poly":"dermato","fiche":"d228","front":"Plaie très exsudative : quels pansements ?","back":"**Alginates de calcium** (aussi **hémostatiques**) ou **hydrofibres**.","prio":"P2","sec":"s13"},{"id":"fc-d228-ab3d77","poly":"dermato","fiche":"d228","front":"Phase d'épithélialisation : quels pansements ?","back":"Mêmes produits, surtout **hydrocolloïdes** et **interfaces**.","prio":"P2","sec":"s13"},{"id":"fc-d228-56511d","poly":"dermato","fiche":"d228","front":"Ulcère fortement colonisé sans infection patente : quel pansement ?","back":"**Pansements à l'argent** (érythème autour, mauvaise odeur, exsudat abondant).","prio":"P2","sec":"s13"},{"id":"fc-d228-715ad5","poly":"dermato","fiche":"d228","front":"Dermite ocre : régresse-t-elle sous contention ?","back":"**Non**, elle ne régresse pas ; la contention peut **empêcher son aggravation**.","prio":"P2","sec":"s13"},{"id":"fc-d228-db6637","poly":"dermato","fiche":"d228","front":"Baume du Pérou : pourquoi l'éviter dans les tulles ?","back":"C'est un **allergène majeur** de contact.","prio":"P1","sec":"s13"},{"id":"fc-d228-c38b7b","poly":"dermato","fiche":"d228","front":"Tout ulcère : quelles mesures générales ?","back":"**Vaccin antitétanique** à jour, **antalgiques** (avant les soins), contrôle des **facteurs de risque**, **état nutritionnel**.","prio":"P1","sec":"s14"},{"id":"fc-d228-55b808","poly":"dermato","fiche":"d228","front":"Ulcère : activité physique recommandée ?","back":"**Activité adaptée** en évitant les microtraumatismes ; **kinésithérapie** si besoin (ankylose des chevilles).","prio":"P2","sec":"s14"},{"id":"fc-d228-20283e","poly":"dermato","fiche":"d228","front":"Ulcère : quels compléments indispensables aux traitements spécifiques ?","back":"Bonne **hygiène de vie** et **rééducation de la marche** ; tenir compte du contexte **social et gériatrique**.","prio":"P2","sec":"s14"},{"id":"fc-d228-5d8291","poly":"dermato","fiche":"d228","front":"Ulcère : quand évaluer particulièrement l'état nutritionnel ?","back":"Si la **cicatrisation tarde**.","prio":"P2","sec":"s14"},{"id":"fc-d228-b98973","poly":"dermato","fiche":"d228","front":"Eczéma de contact péri-ulcéreux : comment identifier l'allergène ?","back":"Par **tests épicutanés**.","prio":"P1","sec":"s15"},{"id":"fc-d228-f85871","poly":"dermato","fiche":"d228","front":"Eczéma de contact péri-ulcéreux : quel traitement ?","back":"**Supprimer l'allergène** + **dermocorticoïde**.","prio":"P1","sec":"s15"},{"id":"fc-d228-bab405","poly":"dermato","fiche":"d228","front":"Eczéma de contact : quel dermocorticoïde et quel schéma ?","back":"Activité **forte à très forte**, **1 application/jour**, **1 à 2 semaines**.","prio":"P2","sec":"s15"},{"id":"fc-d228-5d915a","poly":"dermato","fiche":"d228","front":"Eczéma de contact : une désensibilisation est-elle possible ?","back":"**Non** : l'**éviction** de l'allergène est indispensable à la guérison (liste écrite des produits à éviter).","prio":"P2","sec":"s15"},{"id":"fc-d228-be600c","poly":"dermato","fiche":"d228","front":"Eczéma de contact avec prurit important : quel antihistaminique ?","back":"**Anti-H1 de 1re génération**, quelques jours ; les anti-H1 non sédatifs sont **inutiles**.","prio":"P3","sec":"s15"},{"id":"fc-d228-639cbb","poly":"dermato","fiche":"d228","front":"Eczéma de contact péri-ulcéreux : avec quoi est-il parfois difficile à distinguer ?","back":"Une **dermatite de stase** (mécanismes souvent intriqués).","prio":"P2","sec":"s15"},{"id":"fc-d228-ad6ed7","poly":"dermato","fiche":"d228","front":"Ulcère colonisé : faut-il prélever ou traiter systématiquement ?","back":"**Non** : ni prélèvement, ni antiseptique, ni antibiotique **systématiques**.","prio":"P1","sec":"s16"},{"id":"fc-d228-25d894","poly":"dermato","fiche":"d228","front":"Ulcère avec dermohypodermite bactérienne : quel traitement ?","back":"**Désinfection** de la plaie + **antibiothérapie générale**.","prio":"P1","sec":"s16"},{"id":"fc-d228-df1222","poly":"dermato","fiche":"d228","front":"Érysipèle sans gravité à domicile : quel antibiotique, dose et durée ?","back":"**Amoxicilline 3 à 4,5 g/j** per os pendant **7 jours**.","prio":"P1","sec":"s16"},{"id":"fc-d228-f21240","poly":"dermato","fiche":"d228","front":"Érysipèle et allergie à la pénicilline : quelles alternatives ?","back":"**Pristinamycine 3 g/j** en 3 prises ou **clindamycine**.","prio":"P2","sec":"s16"},{"id":"fc-d228-54d922","poly":"dermato","fiche":"d228","front":"Érysipèle hospitalisé : quel schéma antibiotique ?","back":"**Amoxicilline IV 50 mg/kg/j** jusqu'à l'apyrexie, relais PO 3 à 4,5 g/j ; **7 jours** au total.","prio":"P3","sec":"s16"},{"id":"fc-d228-fb8e5d","poly":"dermato","fiche":"d228","front":"Autres dermohypodermites bactériennes : quelle antibiothérapie probabiliste ?","back":"**Antistreptococcique et antistaphylococcique**, adaptée ensuite aux prélèvements.","prio":"P2","sec":"s16"},{"id":"fc-d228-96484a","poly":"dermato","fiche":"d228","front":"Grosse jambe rouge infectieuse : quelles mesures communes ?","back":"**Repos au lit jambe surélevée** jusqu'à régression locale, **antalgiques sans AINS**.","prio":"P1","sec":"s16"},{"id":"fc-d228-de46ed","poly":"dermato","fiche":"d228","front":"Dermohypodermite bactérienne : faut-il attendre les examens pour traiter ?","back":"**Non** : ne pas retarder le traitement ; examens en général **peu utiles** au diagnostic.","prio":"P2","sec":"s16"},{"id":"fc-d228-fef308","poly":"dermato","fiche":"d228","front":"Dermohypodermite bactérienne : quand hospitaliser ?","back":"Si traitement **parentéral** et/ou surveillance rapprochée : doute, **gravité**, comorbidité, contexte social, **pas d'amélioration à 48 h**.","prio":"P2","sec":"s16"},{"id":"fc-d228-3a68fa","poly":"dermato","fiche":"d228","front":"Fasciite nécrosante : quelle prise en charge ?","back":"**Urgence médico-chirurgicale** : imagerie sans délai, **excision** des zones nécrosées, antibiothérapie **parentérale**, correction hypovolémie.","prio":"P1","sec":"s16"},{"id":"fc-d228-e3be07","poly":"dermato","fiche":"d228","front":"Dermohypodermite nécrosante : quelle antibiothérapie ?","back":"**Clindamycine** + pénicilline à spectre élargi (tazocilline) ou céphalosporine, ± aminoside ; **métronidazole** si anaérobies.","prio":"P3","sec":"s16"},{"id":"fc-d228-9084ff","poly":"dermato","fiche":"d228","front":"Dermohypodermite : quand une anticoagulation préventive ?","back":"**Seulement** s'il existe des **facteurs de risque thromboembolique** (héparine calcique ou HBPM).","prio":"P3","sec":"s16"},{"id":"fc-d228-827316","poly":"dermato","fiche":"d228","front":"Érysipèle : un BGN isolé de l'ulcère porte d'entrée est-il responsable ?","back":"**Pas forcément** : il peut n'être que **colonisant**.","prio":"P2","sec":"s16"},{"id":"fc-d228-e2d58c","poly":"dermato","fiche":"d228","front":"Hypodermite inflammatoire veineuse : quel traitement ?","back":"**Contention élastique** (indispensable, parfois mal tolérée) + repos + antalgiques.","prio":"P3","sec":"s16"},{"id":"fc-d228-a42860","poly":"dermato","fiche":"d228","front":"Érysipèle : quelle prévention primaire ?","back":"Traiter la **porte d'entrée**, améliorer les troubles circulatoires (**contention**, drainage lymphatique, perte de poids), hygiène cutanée.","prio":"P2","sec":"s16"},{"id":"fc-d228-6a82c8","poly":"dermato","fiche":"d228","front":"Hémorragie sur ulcère : quel traitement ?","back":"**Compression** et **surélévation** du membre.","prio":"P1","sec":"s17"},{"id":"fc-d239-b3cfb7","poly":"dermato","fiche":"d239","front":"Acrosyndrome vasculaire : définition ?","back":"**Trouble vasomoteur des extrémités**.","prio":"P1","sec":"s1"},{"id":"fc-d239-7ec52e","poly":"dermato","fiche":"d239","front":"Acrosyndromes : citer les cinq tableaux ?","back":"**Raynaud** · **acrocyanose** · **érythermalgie** · **engelures** · **ischémie digitale**.","prio":"P1","sec":"s1"},{"id":"fc-d239-12a716","poly":"dermato","fiche":"d239","front":"Acrosyndromes : quelles sont les deux familles ?","back":"Acrosyndromes **vasomoteurs** et acrosyndromes **trophiques**.","prio":"P2","sec":"s1"},{"id":"fc-d239-075671","poly":"dermato","fiche":"d239","front":"Acrosyndromes vasomoteurs paroxystiques : lesquels ?","back":"**Phénomène de Raynaud** et **érythermalgie**.","prio":"P1","sec":"s1"},{"id":"fc-d239-f2bca2","poly":"dermato","fiche":"d239","front":"Acrosyndrome vasomoteur permanent : lequel ?","back":"L'**acrocyanose**.","prio":"P1","sec":"s1"},{"id":"fc-d239-9f90cd","poly":"dermato","fiche":"d239","front":"Acrosyndromes trophiques : lesquels ?","back":"**Engelures** (récidive en saison froide) et **ischémie digitale** (en général aiguë).","prio":"P1","sec":"s1"},{"id":"fc-d239-ab8b88","poly":"dermato","fiche":"d239","front":"Engelures : quelles deux formes ?","back":"**Idiopathique** (engelures) ou **secondaire** (pseudo-engelures).","prio":"P2","sec":"s1"},{"id":"fc-d239-3340a9","poly":"dermato","fiche":"d239","front":"Raynaud primitif : mécanisme ?","back":"**Spasme excessif au froid** par hypersensibilité des récepteurs **α2-vasoconstricteurs**, avec anomalies de la sécrétion **endothéliale**.","prio":"P2","sec":"s1"},{"id":"fc-d239-cdbdba","poly":"dermato","fiche":"d239","front":"Érythermalgie : mécanisme ?","back":"**Vasodilatation** artériolo-capillaire.","prio":"P1","sec":"s1"},{"id":"fc-d239-2eaef3","poly":"dermato","fiche":"d239","front":"Acrocyanose essentielle : mécanisme ?","back":"**Stase capillaro-veinulaire** : anastomoses artérioveineuses nombreuses, développées, **ouvertes en permanence**.","prio":"P2","sec":"s1"},{"id":"fc-d239-5ee1b9","poly":"dermato","fiche":"d239","front":"Engelures : mécanisme ?","back":"**Hypersensibilité au froid**.","prio":"P2","sec":"s1"},{"id":"fc-d239-7b085e","poly":"dermato","fiche":"d239","front":"Ischémie digitale permanente : mécanisme ?","back":"**Déficit de perfusion** lié à des **lésions artérielles d'amont**.","prio":"P1","sec":"s1"},{"id":"fc-d239-4f1be2","poly":"dermato","fiche":"d239","front":"Phénomène de Raynaud : prévalence ?","back":"**5 %** : acrosyndrome **le plus fréquent**.","prio":"P1","sec":"s2"},{"id":"fc-d239-561608","poly":"dermato","fiche":"d239","front":"Phénomène de Raynaud : quelles localisations ?","back":"**Mains**, **orteils**, **nez**, **oreilles**…","prio":"P2","sec":"s2"},{"id":"fc-d239-dde681","poly":"dermato","fiche":"d239","front":"Phénomène de Raynaud : circonstances déclenchantes ?","back":"**Froid**, **humidité**, parfois **émotions**.","prio":"P1","sec":"s2"},{"id":"fc-d239-d60fb0","poly":"dermato","fiche":"d239","front":"Phénomène de Raynaud : citer les trois phases d'une crise ?","back":"**Syncopale** (blanche) → **cyanique** (bleue) → **hyperhémique** (rouge).","prio":"P1","sec":"s2"},{"id":"fc-d239-ec14e6","poly":"dermato","fiche":"d239","front":"Phénomène de Raynaud : quelle phase est obligatoire ?","back":"La phase **syncopale** (blanche) ; les phases bleue et rouge sont **inconstantes**.","prio":"P1","sec":"s2"},{"id":"fc-d239-7daf49","poly":"dermato","fiche":"d239","front":"Raynaud : aspect et durée de la phase syncopale ?","back":"Extrémités **pâles et froides**, ± baisse de la sensibilité ; de **quelques minutes à quelques heures**.","prio":"P2","sec":"s2"},{"id":"fc-d239-1c9e10","poly":"dermato","fiche":"d239","front":"Raynaud : aspect de la phase hyperhémique ?","back":"**Recoloration** et **réchauffement**, avec dysesthésies douloureuses ou non ; quelques minutes.","prio":"P2","sec":"s2"},{"id":"fc-d239-b9abf5","poly":"dermato","fiche":"d239","front":"Raynaud : quelle durée pour les phases cyanique et hyperhémique ?","back":"**Quelques minutes**.","prio":"P3","sec":"s2"},{"id":"fc-d239-e42fee","poly":"dermato","fiche":"d239","front":"Raynaud : proportions de formes primitives et secondaires ?","back":"**Primitif 90 %** ; **secondaire 10 %**.","prio":"P1","sec":"s3"},{"id":"fc-d239-f58713","poly":"dermato","fiche":"d239","front":"Acrosyndrome : sur quoi repose essentiellement le diagnostic étiologique ?","back":"**Interrogatoire** et **examen clinique**, avec quelques examens complémentaires.","prio":"P2","sec":"s3"},{"id":"fc-d239-fadbc1","poly":"dermato","fiche":"d239","front":"Maladie de Raynaud : quel statut diagnostique ?","back":"Cause **la plus fréquente**, mais **diagnostic d'élimination** (aucun argument pour une cause secondaire).","prio":"P1","sec":"s3"},{"id":"fc-d239-2ad589","poly":"dermato","fiche":"d239","front":"Raynaud primitif : prévalence chez la femme de 25 à 40 ans ?","back":"**6 %**.","prio":"P3","sec":"s3"},{"id":"fc-d239-6c3ec8","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : quand l'évoquer ?","back":"Devant des **atypies** à l'interrogatoire ou à l'examen clinique.","prio":"P1","sec":"s3"},{"id":"fc-d239-7dc335","poly":"dermato","fiche":"d239","front":"Raynaud primitif : quel terrain ?","back":"**Femme jeune** (ratio **4/1**) ; **antécédents familiaux**.","prio":"P1","sec":"s3"},{"id":"fc-d239-5d27fe","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : quel terrain ?","back":"Homme ou femme de **tout âge** ; pas d'antécédent familial.","prio":"P1","sec":"s3"},{"id":"fc-d239-bd18e5","poly":"dermato","fiche":"d239","front":"Raynaud primitif : critère d'évolution ?","back":"Suivi de **plus de 2 ans** sans apparition d'une autre cause.","prio":"P1","sec":"s3"},{"id":"fc-d239-b23472","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : quel rapport chronologique avec la connectivité ?","back":"Il peut **précéder de plusieurs mois** les autres signes : **suivi clinique +++**.","prio":"P1","sec":"s3"},{"id":"fc-d239-5231aa","poly":"dermato","fiche":"d239","front":"Raynaud primitif vs secondaire : facteur déclenchant ?","back":"Primitif : **froid** (recrudescence hivernale) ; secondaire : froid et/ou crises **spontanées**.","prio":"P1","sec":"s3"},{"id":"fc-d239-6109ab","poly":"dermato","fiche":"d239","front":"Raynaud primitif : topographie ?","back":"**Bilatérale** et **symétrique** ; doigts, **pouces respectés**.","prio":"P1","sec":"s3"},{"id":"fc-d239-16a293","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : topographie ?","back":"**Unilatérale**, **asymétrique** ; **pouces parfois touchés**.","prio":"P1","sec":"s3"},{"id":"fc-d239-3c7823","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : quelle phase est absente ?","back":"La phase **hyperhémique** (rouge).","prio":"P1","sec":"s3"},{"id":"fc-d239-e61cfd","poly":"dermato","fiche":"d239","front":"Raynaud : quelles lésions trophiques orientent vers une forme secondaire ?","back":"**Nécrose**, **ulcérations pulpaires** des doigts (actives ou cicatricielles).","prio":"P1","sec":"s3"},{"id":"fc-d239-3a8aef","poly":"dermato","fiche":"d239","front":"Raynaud primitif : examen clinique ?","back":"**Normal** : tous les pouls perçus ; ± engelures, hyperhidrose.","prio":"P1","sec":"s3"},{"id":"fc-d239-b837a9","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : quelles anomalies à l'examen clinique ?","back":"**Signes de connectivité** (doigts boudinés, sclérose cutanée, télangiectasies…), **anomalie des pouls**.","prio":"P1","sec":"s3"},{"id":"fc-d239-98e13b","poly":"dermato","fiche":"d239","front":"Raynaud primitif vs secondaire : résultat de la manœuvre d'Allen ?","back":"Primitif : **négative** ; secondaire : **positive**.","prio":"P1","sec":"s3"},{"id":"fc-d239-f77bd0","poly":"dermato","fiche":"d239","front":"Raynaud primitif vs secondaire : capillaroscopie et AAN ?","back":"Primitif : **normale**, AAN **négatifs** ; secondaire : **anormale**, AAN **positifs** si connectivité.","prio":"P1","sec":"s3"},{"id":"fc-d239-4d73c3","poly":"dermato","fiche":"d239","front":"Raynaud primitif : quel moyen mnémotechnique ?","back":"« Femme jeune, froid, symétrique, **pouces épargnés**, **3 phases**, tout est normal ».","prio":"P2","sec":"s3"},{"id":"fc-d239-7a4e46","poly":"dermato","fiche":"d239","front":"Manœuvre d'Allen : comment la réaliser ?","back":"Compression des artères **radiale** et **cubitale** pendant des flexions-extensions de la main, puis levée de la compression.","prio":"P2","sec":"s4"},{"id":"fc-d239-cbe6e3","poly":"dermato","fiche":"d239","front":"Manœuvre d'Allen : définition d'un résultat négatif et positif ?","back":"Négative : revascularisation **rapide et homogène** ; positive : **retardée et hétérogène**.","prio":"P2","sec":"s4"},{"id":"fc-d239-adbcd6","poly":"dermato","fiche":"d239","front":"Raynaud : quel bilan minimum ?","back":"**Capillaroscopie péri-unguéale** + **anticorps antinucléaires** (titre, spécificité : anti-centromère, anti-Scl70).","prio":"P2","sec":"s4"},{"id":"fc-d239-43f1a4","poly":"dermato","fiche":"d239","front":"Raynaud : pourquoi le bilan minimum comporte-t-il capillaroscopie et AAN ?","back":"La **sclérodermie systémique** peut se révéler par le seul Raynaud **plusieurs années** avant ses signes cutanés et viscéraux.","prio":"P2","sec":"s4"},{"id":"fc-d239-067f46","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : anomalies capillaroscopiques ?","back":"**Mégacapillaires** (ectasies) et **raréfaction des anses** capillaires.","prio":"P2","sec":"s4"},{"id":"fc-d239-481f48","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : quels anticorps ?","back":"Facteurs **antinucléaires** ; anti-**Scl70** ou anti-**centromères**.","prio":"P2","sec":"s4"},{"id":"fc-d239-c59de4","poly":"dermato","fiche":"d239","front":"Raynaud iatrogène : quelle classe en est la cause la plus fréquente ?","back":"Les **bêtabloquants**, quelle que soit la voie, **collyres compris**.","prio":"P2","sec":"s5"},{"id":"fc-d239-baa29c","poly":"dermato","fiche":"d239","front":"Raynaud unilatéral : quel type de cause évoquer ?","back":"Une cause **locorégionale**.","prio":"P2","sec":"s5"},{"id":"fc-d239-2157fa","poly":"dermato","fiche":"d239","front":"Raynaud secondaire : première cause ?","back":"La **sclérodermie systémique**.","prio":"P2","sec":"s5"},{"id":"fc-d239-234584","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : caractéristiques du Raynaud ?","back":"Présent chez **plus de 9 malades sur 10**, **quasi constant**, **précoce**, **bilatéral**, souvent **révélateur**.","prio":"P2","sec":"s5"},{"id":"fc-d239-6cc64a","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : fréquence des anomalies capillaroscopiques ?","back":"**Plus de 90 %** des cas, même si le Raynaud est isolé au début.","prio":"P3","sec":"s5"},{"id":"fc-d239-32891f","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : signes cutanés ?","back":"**Doigts boudinés** (précoces) puis **sclérodactylie** ; sclérose **distale > proximale** ; **télangiectasies** ; **calcinose** ; ulcérations digitales.","prio":"P2","sec":"s5"},{"id":"fc-d239-d12a27","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : atteintes viscérales ?","back":"Troubles **moteurs digestifs** · **HTAP** · **pneumopathie interstitielle**.","prio":"P2","sec":"s5"},{"id":"fc-d239-c5f649","poly":"dermato","fiche":"d239","front":"Raynaud de sclérodermie (image du Collège) : quel aspect des doigts ?","back":"Note ischémique **asymétrique et incomplète**, télangiectasies, doigts boudinés.","prio":"P3","sec":"s5"},{"id":"fc-d239-c77e21","poly":"dermato","fiche":"d239","front":"Sclérodactylie évoluée : quel signe digital peut s'y associer ?","back":"**Hippocratisme digital**.","prio":"P3","sec":"s5"},{"id":"fc-d239-007bcc","poly":"dermato","fiche":"d239","front":"Capillaroscopie anormale isolée avec biologie normale : quelle conduite ?","back":"**Surveillance clinique et biologique** à la recherche d'une **connectivité** auto-immune.","prio":"P2","sec":"s5"},{"id":"fc-d239-29bf87","poly":"dermato","fiche":"d239","front":"Érythermalgie : quel type d'acrosyndrome ?","back":"Acrosyndrome vasculaire **paroxystique** (vasodilatation).","prio":"P2","sec":"s6"},{"id":"fc-d239-a7c8bb","poly":"dermato","fiche":"d239","front":"Érythermalgie : topographie ?","back":"Extrémités, **pieds > mains**.","prio":"P1","sec":"s6"},{"id":"fc-d239-359d1b","poly":"dermato","fiche":"d239","front":"Érythermalgie : facteurs déclenchants ?","back":"**Chaleur** (plus que crise spontanée) ; **effort** ; **orthostatisme**.","prio":"P1","sec":"s6"},{"id":"fc-d239-ed3bde","poly":"dermato","fiche":"d239","front":"Érythermalgie : quels signes pendant la crise ?","back":"**Rougeur**, **chaleur**, **douleurs intenses** (brûlure, striction), de quelques minutes à quelques heures.","prio":"P1","sec":"s6"},{"id":"fc-d239-321230","poly":"dermato","fiche":"d239","front":"Érythermalgie : qu'est-ce qui soulage la crise ?","back":"L'**eau froide**.","prio":"P1","sec":"s6"},{"id":"fc-d239-66cf12","poly":"dermato","fiche":"d239","front":"Érythermalgie : quel bilan ?","back":"Rechercher une **hémopathie** : **examen clinique** + **NFS**.","prio":"P1","sec":"s6"},{"id":"fc-d239-a70fd4","poly":"dermato","fiche":"d239","front":"Érythermalgie idiopathique : quel terrain ?","back":"Forme **rare** : homme de **moins de 40 ans**, atteinte **symétrique**, ATCD familiaux (**autosomique dominante**).","prio":"P2","sec":"s6"},{"id":"fc-d239-51cbd7","poly":"dermato","fiche":"d239","front":"Érythermalgie secondaire : quel terrain et quelle cause principale ?","back":"Homme ou femme de **plus de 40 ans** ; **syndrome myéloprolifératif** (polyglobulie, thrombocytémie).","prio":"P1","sec":"s6"},{"id":"fc-d239-f7ea68","poly":"dermato","fiche":"d239","front":"Érythermalgie secondaire : quelles causes moins fréquentes ?","back":"**Hyperthyroïdie**, **lupus**, cause **paranéoplasique**.","prio":"P2","sec":"s6"},{"id":"fc-d239-3327e1","poly":"dermato","fiche":"d239","front":"Raynaud vs érythermalgie : quel facteur déclenchant oppose les deux ?","back":"Raynaud : **froid** (doigts blancs) ; érythermalgie : **chaleur** (rougeur, brûlure).","prio":"P1","sec":"s6"},{"id":"fc-d239-4b12a8","poly":"dermato","fiche":"d239","front":"Acrocyanose essentielle : quel type d'acrosyndrome ?","back":"Acrosyndrome vasculaire **permanent**.","prio":"P2","sec":"s7"},{"id":"fc-d239-760b4f","poly":"dermato","fiche":"d239","front":"Acrocyanose essentielle : quel terrain ?","back":"**Femmes minces** ; début à l'**adolescence**.","prio":"P1","sec":"s7"},{"id":"fc-d239-edddd4","poly":"dermato","fiche":"d239","front":"Acrocyanose : topographie et aspect ?","back":"Mains et pieds **des deux côtés** ; coloration **bleue, rouge ou violacée**, **froideur**, ± œdème, ± moiteur.","prio":"P1","sec":"s7"},{"id":"fc-d239-e6b81a","poly":"dermato","fiche":"d239","front":"Acrocyanose : douleur et retentissement ?","back":"**Indolore**, mais parfois **gênante socialement**.","prio":"P2","sec":"s7"},{"id":"fc-d239-6db0f5","poly":"dermato","fiche":"d239","front":"Acrocyanose : facteurs d'aggravation ?","back":"**Froid** et **déclivité**.","prio":"P2","sec":"s7"},{"id":"fc-d239-fae565","poly":"dermato","fiche":"d239","front":"Acrocyanose : associations possibles ?","back":"**Raynaud**, **engelures**, **livedo physiologique**…","prio":"P3","sec":"s7"},{"id":"fc-d239-f3c8a4","poly":"dermato","fiche":"d239","front":"Acrocyanose essentielle : quel bilan ?","back":"**Aucun**.","prio":"P1","sec":"s7"},{"id":"fc-d239-8dce63","poly":"dermato","fiche":"d239","front":"Acrocyanose : quel piège ?","back":"Elle est **banale**, mais **parfois trompeuse**.","prio":"P2","sec":"s7"},{"id":"fc-d239-8b531d","poly":"dermato","fiche":"d239","front":"Engelures : à quelle saison récidivent-elles et quelle forme prédomine ?","back":"En **saison froide** ; le plus souvent **idiopathiques**.","prio":"P2","sec":"s8"},{"id":"fc-d239-22398b","poly":"dermato","fiche":"d239","front":"Engelures : quel terrain ?","back":"**Femmes jeunes**, parfois anorexiques, sous-alimentées ; **ATCD familiaux** ; ± acrocyanose, hyperhidrose.","prio":"P1","sec":"s8"},{"id":"fc-d239-78eec9","poly":"dermato","fiche":"d239","front":"Engelures : quelles conditions d'exposition au froid ?","back":"Séjour **prolongé** dans un froid **humide** mais **modéré (8 à 10 °C)**, en automne ou hiver.","prio":"P1","sec":"s8"},{"id":"fc-d239-9153fe","poly":"dermato","fiche":"d239","front":"Engelures : délai d'apparition après l'exposition ?","back":"**12 à 24 heures**.","prio":"P1","sec":"s8"},{"id":"fc-d239-a3e626","poly":"dermato","fiche":"d239","front":"Engelures : topographie ?","back":"Face dorsale des **doigts** > orteils > bords latéraux des pieds, région achilléenne, **hélix**, **nez**.","prio":"P2","sec":"s8"},{"id":"fc-d239-8ef8fe","poly":"dermato","fiche":"d239","front":"Engelures : aspect des lésions ?","back":"**Multiples** : macules érythémateuses puis macules et **papules violacées** ± œdémateuses ; plaques érythrocyaniques ; formes vésiculo-bulleuses possibles.","prio":"P2","sec":"s8"},{"id":"fc-d239-86a7a3","poly":"dermato","fiche":"d239","front":"Engelures : symptômes ?","back":"**Prurit** ± douleurs au **réchauffement**.","prio":"P2","sec":"s8"},{"id":"fc-d239-ad0c82","poly":"dermato","fiche":"d239","front":"Engelures : évolution ?","back":"**Régression spontanée en 2 à 3 semaines**, ± dyschromie séquellaire ; récidive chaque saison.","prio":"P1","sec":"s8"},{"id":"fc-d239-dbe150","poly":"dermato","fiche":"d239","front":"Engelures : principal diagnostic différentiel ?","back":"Le **lupus**.","prio":"P1","sec":"s8"},{"id":"fc-d239-204b6b","poly":"dermato","fiche":"d239","front":"Ischémie digitale : pourquoi est-ce une urgence ?","back":"**Risque de nécrose**.","prio":"P1","sec":"s9"},{"id":"fc-d239-dd3936","poly":"dermato","fiche":"d239","front":"Ischémie digitale : causes thrombotiques ou occlusives ?","back":"**Athérome**, artériolopathie de **Buerger**, **polyglobulie**…","prio":"P2","sec":"s9"},{"id":"fc-d239-5e3acd","poly":"dermato","fiche":"d239","front":"Ischémie digitale : causes emboliques ?","back":"**Arythmie cardiaque**, **athérome de l'aorte**…","prio":"P2","sec":"s9"},{"id":"fc-d239-eeae67","poly":"dermato","fiche":"d239","front":"Ischémie digitale : causes inflammatoires ?","back":"**Vascularites**, **cryoglobulinémie**, **sclérodermie**, **périartérite noueuse**…","prio":"P2","sec":"s9"},{"id":"fc-d239-aaddf7","poly":"dermato","fiche":"d239","front":"Ischémie digitale : quelles causes traumatiques ou mécaniques ?","back":"**Maladies professionnelles**.","prio":"P3","sec":"s9"},{"id":"fc-d239-54dd3c","poly":"dermato","fiche":"d239","front":"Ischémie digitale : histoire typique ?","back":"Épisodes **syncopaux paroxystiques**, puis douleurs (surtout **nocturnes**) entre les crises, **semi-permanentes** puis **permanentes**.","prio":"P2","sec":"s9"},{"id":"fc-d239-774398","poly":"dermato","fiche":"d239","front":"Ischémie digitale : durée habituelle de la cyanose douloureuse ?","back":"Période **prolongée**, habituellement **plusieurs jours**.","prio":"P2","sec":"s9"},{"id":"fc-d239-7d9077","poly":"dermato","fiche":"d239","front":"Ischémie digitale : temps de recoloration pulpaire ?","back":"**Allongé, > 3 minutes**.","prio":"P1","sec":"s9"},{"id":"fc-d239-74c2a3","poly":"dermato","fiche":"d239","front":"Ischémie digitale : quels signes cliniques ?","back":"Doigt **froid et cyanique** · recoloration **> 3 min** · **hémorragies sous-unguéales en flammèches** · puis **nécroses**.","prio":"P1","sec":"s9"},{"id":"fc-d239-d28185","poly":"dermato","fiche":"d239","front":"Nécrose du gros orteil chez un jeune homme consommateur de cannabis : quel diagnostic sur l'image du Collège ?","back":"**Thromboangéite oblitérante de Buerger**.","prio":"P2","sec":"s9"},{"id":"fc-d239-ebab99","poly":"dermato","fiche":"d239","front":"Acrosyndrome : quelle conduite selon le tableau (Raynaud, érythermalgie, acrocyanose, engelures, ischémie) ?","back":"Raynaud : **bilan minimal** · érythermalgie : **NFS** · acrocyanose : **aucun bilan** · engelures : **régression spontanée** · ischémie : **urgence**.","prio":"P1","sec":"s10"},{"id":"fc-d239-097581","poly":"dermato","fiche":"d239","front":"Cyanose douloureuse prolongée avec douleurs entre les crises : quel diagnostic évoquer ?","back":"**Ischémie digitale** (urgence).","prio":"P1","sec":"s10"},{"id":"fc-d239-b64839","poly":"dermato","fiche":"d239","front":"Doigts blancs au froid : peut-on conclure d'emblée à une maladie de Raynaud ?","back":"**Non** : diagnostic d'**élimination**, sans argument pour une forme secondaire.","prio":"P1","sec":"s10"},{"id":"fc-d239-2ab5a9","poly":"dermato","fiche":"d239","front":"Raynaud : le Collège précise-t-il un traitement médicamenteux ?","back":"**Non**, pas pour cet item.","prio":"P3","sec":"s11"},{"id":"fc-d239-2f0cf0","poly":"dermato","fiche":"d239","front":"Raynaud : quel est l'objectif du bilan minimal clinique et biologique ?","back":"Trancher entre forme **primitive** (90 %) et forme **secondaire** (10 %).","prio":"P1","sec":"s11"},{"id":"fc-d239-d7ede2","poly":"dermato","fiche":"d239","front":"Raynaud : citer les atypies cliniques évoquant une forme secondaire ?","back":"Tout âge/sexe, crises **spontanées**, **asymétrie**, **pouces** touchés, **pas de phase rouge**, **ulcérations pulpaires**, **connectivité**, **pouls anormaux**.","prio":"P1","sec":"s11"},{"id":"fc-d239-3abe63","poly":"dermato","fiche":"d239","front":"Raynaud : quelle démarche si cause médicamenteuse vs cause locorégionale professionnelle ?","back":"Médicament/toxique → **pharmacovigilance** ; cause locorégionale professionnelle → **déclaration de maladie professionnelle**.","prio":"P2","sec":"s13"},{"id":"fc-d239-2d330f","poly":"dermato","fiche":"d239","front":"Raynaud : quel traitement oculaire faut-il rechercher à l'interrogatoire ?","back":"Un **collyre bêtabloquant**.","prio":"P2","sec":"s13"},{"id":"fc-d239-e65694","poly":"dermato","fiche":"d239","front":"Ischémie digitale : le Collège précise-t-il un traitement médicamenteux ?","back":"**Non** pour cet item ; urgence, chercher la **lésion artérielle d'amont**.","prio":"P3","sec":"s14"},{"id":"fc-d239-ddbe3d","poly":"dermato","fiche":"d239","front":"Ischémie digitale : quel type d'acrosyndrome et quelle évolution ?","back":"Acrosyndrome **trophique**, en général **aigu**.","prio":"P2","sec":"s14"},{"id":"fc-d239-2c33ee","poly":"dermato","fiche":"d239","front":"Érythermalgie : quelle affection peut-elle révéler avant tout ?","back":"Un **syndrome myéloprolifératif** : ne pas oublier la **NFS**.","prio":"P1","sec":"s15"},{"id":"fc-d239-6ed945","poly":"dermato","fiche":"d239","front":"Ischémie digitale : vers quoi évolue-t-elle ?","back":"Vers les **nécroses digitales** : c'est une **urgence**.","prio":"P1","sec":"s18"},{"id":"fc-d239-0a4d4b","poly":"dermato","fiche":"d239","front":"Sclérodermie systémique : combien de temps le Raynaud peut-il rester isolé ?","back":"**Plusieurs années** avant les signes viscéraux et cutanés.","prio":"P2","sec":"s18"},{"id":"fc-d302-e20dee","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : à partir de quelle cellule se développent-ils ?","back":"Le **kératinocyte** (CBC et CEC).","prio":"P1","sec":"s1"},{"id":"fc-d302-8bb2d2","poly":"dermato","fiche":"d302","front":"Mélanome : définition ?","back":"Tumeur **maligne** née des **mélanocytes**, cellules qui fabriquent la mélanine.","prio":"P1","sec":"s1"},{"id":"fc-d302-a8c898","poly":"dermato","fiche":"d302","front":"Nævus : définition ?","back":"Prolifération et/ou accumulation de **mélanocytes normaux** placés en **situation anormale**.","prio":"P1","sec":"s1"},{"id":"fc-d302-4e8809","poly":"dermato","fiche":"d302","front":"Tumeurs à HPV : nature et localisations ?","back":"Lésions épithéliales **bénignes** de la peau (**verrues**) ou des muqueuses (**condylomes**).","prio":"P2","sec":"s1"},{"id":"fc-d302-1a7a07","poly":"dermato","fiche":"d302","front":"Tumeurs à HPV : cancérisation plus fréquente sur peau ou muqueuses ?","back":"**Muqueuses** plus que peau.","prio":"P2","sec":"s1"},{"id":"fc-d302-13e19d","poly":"dermato","fiche":"d302","front":"CBC, CEC et mélanome : quel lien entre eux ?","back":"Même **terrain** et mêmes **facteurs de risque** ; maladies souvent **associées**.","prio":"P2","sec":"s1"},{"id":"fc-d302-403e0c","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : place parmi les cancers ?","back":"Cancers de l'adulte **les plus fréquents** au monde ; **90 %** des cancers cutanés.","prio":"P1","sec":"s1"},{"id":"fc-d302-3d6326","poly":"dermato","fiche":"d302","front":"Cancer cutané le plus fréquent ?","back":"Le **carcinome basocellulaire** (aussi cancer épithélial le plus fréquent).","prio":"P1","sec":"s1"},{"id":"fc-d302-254cfa","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : incidence en France ?","back":"CBC : **> 150/100 000**/an ; CE : **> 30/100 000**/an.","prio":"P3","sec":"s1"},{"id":"fc-d302-2b4f1f","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : évolution de l'incidence et causes ?","back":"**Hausse constante** : vie plus longue, expositions solaires répétées.","prio":"P2","sec":"s1"},{"id":"fc-d302-798fd9","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : âge d'apparition et exceptions ?","back":"**Après 40 ans**, sauf **immunodépression** ou **génodermatose** (xeroderma pigmentosum, syndrome de Gorlin).","prio":"P2","sec":"s1"},{"id":"fc-d302-a61794","poly":"dermato","fiche":"d302","front":"Carcinogenèse épithéliale : 3 étapes ?","back":"**Initiation** (carcinogène) → **promotion** → **progression** (cocarcinogènes).","prio":"P2","sec":"s1"},{"id":"fc-d302-ba458d","poly":"dermato","fiche":"d302","front":"Carcinogenèse épithéliale : agents initiateurs ?","back":"**UV +++**, agents chimiques, radiations ionisantes, inflammation chronique, **HPV**.","prio":"P2","sec":"s1"},{"id":"fc-d302-3ac428","poly":"dermato","fiche":"d302","front":"Carcinogenèse épithéliale : cocarcinogènes de la progression ?","back":"**Immunosuppression**, **HPV**, **UV**, agents chimiques.","prio":"P3","sec":"s1"},{"id":"fc-d302-69b7a4","poly":"dermato","fiche":"d302","front":"Cancers cutanés : latence entre exposition UV et cancer ?","back":"**30 à 40 ans**.","prio":"P2","sec":"s1"},{"id":"fc-d302-f8a2b2","poly":"dermato","fiche":"d302","front":"UV chroniques et cumulés : quels cancers favorisent-ils ?","back":"**CE** et **CBC**.","prio":"P1","sec":"s1"},{"id":"fc-d302-4d71a1","poly":"dermato","fiche":"d302","front":"UV intenses et intermittents (coups de soleil, sujet jeune) : quels cancers ?","back":"**Mélanome** et **CBC**.","prio":"P1","sec":"s1"},{"id":"fc-d302-d37ef3","poly":"dermato","fiche":"d302","front":"Carcinogenèse cutanée : phototypes à risque ?","back":"Phototypes **I et II** (carnation claire).","prio":"P1","sec":"s1"},{"id":"fc-d302-29dc7a","poly":"dermato","fiche":"d302","front":"Xeroderma pigmentosum : gènes en cause ?","back":"Gènes de **réparation de l'ADN**.","prio":"P2","sec":"s1"},{"id":"fc-d302-4ec137","poly":"dermato","fiche":"d302","front":"Syndrome de Gorlin : autre nom et gène ?","back":"**Nævomatose basocellulaire** ; gène du développement **PATCH**.","prio":"P2","sec":"s1"},{"id":"fc-d302-c787aa","poly":"dermato","fiche":"d302","front":"Épidermodysplasie verruciforme : facteur carcinogène en jeu ?","back":"Certains **HPV**.","prio":"P3","sec":"s1"},{"id":"fc-d302-93c0d9","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : immunosuppressions acquises favorisantes ?","back":"**Transplantation d'organe +++**, hémopathies chroniques (LLC, lymphome), **VIH**, néoplasies.","prio":"P1","sec":"s1"},{"id":"fc-d302-d2ab10","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : dermatoses et plaies favorisantes ?","back":"**Lupus** cutané, **lichen** muqueux érosif ; **ulcère de jambe**, **cicatrice de brûlure**, **escarres** ; radiodermite chronique.","prio":"P2","sec":"s1"},{"id":"fc-d302-432690","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : carcinogènes chimiques ?","back":"**Arsenic**, **goudrons**, **tabac**.","prio":"P2","sec":"s1"},{"id":"fc-d302-6503c5","poly":"dermato","fiche":"d302","front":"Phototype I : réaction au soleil et phénotype ?","back":"Ne bronze **pas**, coups de soleil **systématiques** ; carnation très claire, cheveux **blonds ou roux**, nombreuses éphélides.","prio":"P2","sec":"s1"},{"id":"fc-d302-f699e6","poly":"dermato","fiche":"d302","front":"Phototype II : réaction au soleil ?","back":"Bronze **difficilement**, coups de soleil **souvent**.","prio":"P3","sec":"s1"},{"id":"fc-d302-6e11d0","poly":"dermato","fiche":"d302","front":"Phototype III : réaction au soleil ?","back":"Bronzage **progressif**, coups de soleil **parfois**.","prio":"P3","sec":"s1"},{"id":"fc-d302-8a397d","poly":"dermato","fiche":"d302","front":"Phototype IV : réaction au soleil et phénotype ?","back":"Bronze **facilement**, peu de coups de soleil ; carnation **mate**, yeux foncés.","prio":"P3","sec":"s1"},{"id":"fc-d302-7d15f4","poly":"dermato","fiche":"d302","front":"Phototypes V et VI : réaction au soleil ?","back":"V : bronze très facilement, coups de soleil **exceptionnels** ; VI : bronzage constant, **pas** de coups de soleil.","prio":"P3","sec":"s1"},{"id":"fc-d302-2c5581","poly":"dermato","fiche":"d302","front":"Phototypes : nom de la classification ?","back":"Classification de **Fitzpatrick** (6 phototypes).","prio":"P3","sec":"s1"},{"id":"fc-d302-f41945","poly":"dermato","fiche":"d302","front":"Vieillissement cutané : deux types ?","back":"**Intrinsèque** (âge, génétique > environnement) ; **extrinsèque** (environnement, surtout soleil > génétique).","prio":"P2","sec":"s2"},{"id":"fc-d302-50827e","poly":"dermato","fiche":"d302","front":"Vieillissement extrinsèque : facteur le plus important ?","back":"Le facteur **photo-induit** (UVA, héliodermie).","prio":"P2","sec":"s2"},{"id":"fc-d302-352e2d","poly":"dermato","fiche":"d302","front":"Vieillissement extrinsèque : autres facteurs ?","back":"**Tabac**, alcool, alimentation carencée ; maladies inflammatoires chroniques ; maladies endocriniennes, **corticothérapie prolongée**.","prio":"P3","sec":"s2"},{"id":"fc-d302-7227fd","poly":"dermato","fiche":"d302","front":"Héliodermie : définition de la susceptibilité génétique ?","back":"Le **phototype** = capacité naturelle de **photoprotection**.","prio":"P3","sec":"s2"},{"id":"fc-d302-eb7455","poly":"dermato","fiche":"d302","front":"Phototype : critères qui le définissent ?","back":"Couleur des **yeux** et des **cheveux**, **éphélides**, sensibilité aux **coups de soleil**, aptitude à **bronzer**.","prio":"P3","sec":"s2"},{"id":"fc-d302-f2d72c","poly":"dermato","fiche":"d302","front":"Héliodermie : mécanismes des dommages cellulaires ?","back":"**Phototoxicité directe** des UV sur l'**ADN** + **stress oxydatif** (espèces réactives de l'oxygène).","prio":"P3","sec":"s2"},{"id":"fc-d302-2d7b57","poly":"dermato","fiche":"d302","front":"Vieillissement cutané : signes de perte d'élasticité et épidermiques ?","back":"**Xérose**, **rides**, atrophie, peau rugueuse jaunâtre (front, nuque), **cicatrices stellaires** (avant-bras).","prio":"P3","sec":"s2"},{"id":"fc-d302-95acf9","poly":"dermato","fiche":"d302","front":"Vieillissement cutané : signes vasculaires ?","back":"**Angiomes séniles**, **télangiectasies**, **purpura sénile de Bateman** (avant-bras).","prio":"P3","sec":"s2"},{"id":"fc-d302-5623b6","poly":"dermato","fiche":"d302","front":"Vieillissement cutané : signes pigmentaires ?","back":"**Éphélides** et **lentigos** ; **dépigmentation** (jambes, avant-bras).","prio":"P3","sec":"s2"},{"id":"fc-d302-3677c8","poly":"dermato","fiche":"d302","front":"Vieillissement cutané : proliférations associées ?","back":"**Kératoses actiniques** (zones exposées, visage et mains) ; **kératoses séborrhéiques** (tronc).","prio":"P2","sec":"s2"},{"id":"fc-d302-8d15bd","poly":"dermato","fiche":"d302","front":"Héliodermie : principes de la prévention primaire ?","back":"Réduire l'exposition solaire **dès l'enfance**, surtout phototypes **I/II** ; information, éducation, adaptation du comportement.","prio":"P2","sec":"s2"},{"id":"fc-d302-210ad2","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : survient-il toujours sur une lésion précancéreuse ?","back":"**Très souvent**, mais il peut aussi apparaître **de novo**.","prio":"P1","sec":"s3"},{"id":"fc-d302-36448c","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : précurseurs ?","back":"**Kératoses actiniques**, cicatrices de **brûlure**, **radiodermite**, **plaies chroniques**, **lichen scléreux génital**, lésions muqueuses à **HPV**.","prio":"P1","sec":"s3"},{"id":"fc-d302-c3ec3b","poly":"dermato","fiche":"d302","front":"Lésions précancéreuses cutanées les plus fréquentes ?","back":"Les **kératoses actiniques**.","prio":"P1","sec":"s3"},{"id":"fc-d302-39ac6f","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : potentiel de transformation ?","back":"**Limité** ; mais **marqueur de risque** de cancer cutané.","prio":"P1","sec":"s3"},{"id":"fc-d302-ce6767","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : aspect clinique ?","back":"Lésions **multiples**, kératosiques ou croûteuses, rugueuses (« **papier de verre** »), saignant au grattage.","prio":"P1","sec":"s3"},{"id":"fc-d302-cb361a","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : siège ?","back":"**Zones photo-exposées** : visage, dos des mains.","prio":"P2","sec":"s3"},{"id":"fc-d302-bca7ca","poly":"dermato","fiche":"d302","front":"Champ de cancérisation : définition ?","back":"Zone porteuse d'anomalies **prénéoplasiques** et de **mutations infracliniques multifocales** : kératoses actiniques multiples ± CE ou CBC.","prio":"P2","sec":"s3"},{"id":"fc-d302-11f9cb","poly":"dermato","fiche":"d302","front":"Leucoplasie : définition et siège de prédilection ?","back":"**Kératinisation anormale d'une muqueuse** ; **lèvre inférieure** +++ (tabac, UV).","prio":"P1","sec":"s3"},{"id":"fc-d302-46d627","poly":"dermato","fiche":"d302","front":"Leucoplasie : aspect clinique ?","back":"Lésion **blanchâtre**, bien limitée, **asymptomatique**, **adhérente**, **ne saignant pas** au contact.","prio":"P1","sec":"s3"},{"id":"fc-d302-395dda","poly":"dermato","fiche":"d302","front":"Maladie de Bowen : définition ?","back":"Carcinome **in situ** (intra-épithélial) : forme **non invasive** de CE.","prio":"P1","sec":"s3"},{"id":"fc-d302-f321e7","poly":"dermato","fiche":"d302","front":"Carcinome in situ : pourquoi aucune métastase n'est possible ?","back":"La dysplasie occupe toute l'épaisseur de l'épithélium **sans franchir la membrane basale**.","prio":"P1","sec":"s3"},{"id":"fc-d302-99f087","poly":"dermato","fiche":"d302","front":"Maladie de Bowen cutanée : aspect clinique ?","back":"Lésion souvent **unique**, zone photo-exposée ; plaque **érythémateuse**, bien limitée, **squamo-croûteuse**, bord parfois festonné.","prio":"P1","sec":"s3"},{"id":"fc-d302-b98f99","poly":"dermato","fiche":"d302","front":"Maladie de Bowen : quel aspect de surface est très suspect ?","back":"Aspect **fissuré** ou **érodé**.","prio":"P2","sec":"s3"},{"id":"fc-d302-15788a","poly":"dermato","fiche":"d302","front":"Érythroplasie de Queyrat : définition et aspect ?","back":"Carcinome in situ **génital de l'homme** : lésion **rouge vif du gland**, bien limitée, parfois érosive.","prio":"P1","sec":"s3"},{"id":"fc-d302-ac846d","poly":"dermato","fiche":"d302","front":"Carcinome in situ génital de la femme : aspect ?","back":"Lésion **unique**, chronique, plane ou peu infiltrée, **rosée** avec zones pigmentées.","prio":"P2","sec":"s3"},{"id":"fc-d302-102cc7","poly":"dermato","fiche":"d302","front":"Carcinome in situ : comment confirmer le diagnostic ?","back":"**Biopsie** et examen anatomopathologique.","prio":"P1","sec":"s3"},{"id":"fc-d302-3911f3","poly":"dermato","fiche":"d302","front":"Carcinome in situ qui s'infiltre ou s'ulcère : que craindre ?","back":"Une lésion devenue **invasive**, avec **potentiel métastatique**.","prio":"P1","sec":"s3"},{"id":"fc-d302-f500e7","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : peuvent-elles se transformer en CBC ?","back":"**Non** : le CBC n'a **pas de précurseur** ; elles précèdent le **CE**.","prio":"P1","sec":"s3"},{"id":"fc-d302-4a1a17","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : principal facteur de risque ?","back":"Exposition solaire **cumulative** (dose totale d'UV reçue au cours de la vie).","prio":"P1","sec":"s4"},{"id":"fc-d302-7e9a66","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : localisations des HPV oncogènes ?","back":"**Muqueuses** : col utérin, organes génitaux externes, anus, oropharynx.","prio":"P3","sec":"s4"},{"id":"fc-d302-e21ce0","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : type d'évolution ?","back":"**Agressive** ; métastases possibles (**lymphophile** puis **hématogène**).","prio":"P1","sec":"s4"},{"id":"fc-d302-76a8ea","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde invasif : terrain ?","back":"Surtout **après 60 ans**, **homme** > femme ; peau et/ou muqueuse.","prio":"P2","sec":"s4"},{"id":"fc-d302-3f646c","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : 3 signes cliniques clés ?","back":"**Ulcération** chronique · **bourgeonnement** · **croûte**, sur zone chroniquement photo-exposée.","prio":"P1","sec":"s4"},{"id":"fc-d302-145d6b","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : aspects cliniques ?","back":"Lésion croûteuse **indurée** à ulcération centrale, ou végétante/bourgeonnante, ou **ulcéro-bourgeonnante**.","prio":"P1","sec":"s4"},{"id":"fc-d302-815fab","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde suspecté : comment confirmer ?","back":"**Exérèse à visée diagnostique** ou **biopsie** + examen anatomopathologique (histopronostic).","prio":"P1","sec":"s4"},{"id":"fc-d302-d3a487","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : éléments de l'examen clinique local ?","back":"**Mobilité** sur le plan profond, **diamètre**.","prio":"P2","sec":"s4"},{"id":"fc-d302-618be4","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : que rechercher sur toute la peau et dans le territoire de drainage ?","back":"Autres **carcinomes** et/ou **mélanome** ; **adénopathie** de drainage.","prio":"P1","sec":"s4"},{"id":"fc-d302-56d19c","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : bilan d'extension systématique ?","back":"**Non**, sauf forme agressive, **immunodéprimé** ou signe d'extension locorégionale.","prio":"P1","sec":"s4"},{"id":"fc-d302-8c5eae","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde à risque : examens du bilan d'extension ?","back":"**Échographie ganglionnaire**, **scanner thoraco-abdominal**, **TEP-scan**.","prio":"P2","sec":"s4"},{"id":"fc-d302-df3fe3","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : diagnostics différentiels ?","back":"**Autres cancers cutanés** et **kératoses actiniques**.","prio":"P2","sec":"s4"},{"id":"fc-d302-f8c41a","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : histologie ?","back":"Grands kératinocytes en **lobules/travées** anarchiques, invasion dermo-hypodermique, **globes cornés**, mitoses et atypies.","prio":"P3","sec":"s4"},{"id":"fc-d302-389ba8","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : localisations de haut risque ?","back":"**Cuir chevelu**, zones **péri-orificielles** du visage, **muqueuses**, peau pathologique (radiodermite, brûlure, plaie chronique).","prio":"P2","sec":"s4"},{"id":"fc-d302-99fc6c","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : seuils de taille et d'épaisseur péjoratifs ?","back":"Taille **> 2 cm** ; épaisseur histologique **> 3 mm**.","prio":"P2","sec":"s4"},{"id":"fc-d302-cbc09f","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : critères péjoratifs d'invasion locale ?","back":"**Adhérence** au plan profond, envahissement **péri-nerveux** et/ou **osseux**, **emboles vasculaires**.","prio":"P2","sec":"s4"},{"id":"fc-d302-5e2a32","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : facteurs péjoratifs de différenciation et de terrain ?","back":"Différenciation **moyenne à indifférenciée** ; **récidive locale** ; **immunodépression**.","prio":"P3","sec":"s4"},{"id":"fc-d302-3c6a07","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : comment le considérer d'emblée ?","back":"**Potentiellement agressif** ; identifier les facteurs de mauvais pronostic qui guident la prise en charge.","prio":"P2","sec":"s4"},{"id":"fc-d302-62bae0","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : fréquence des métastases ganglionnaires selon le siège ?","back":"**2 %** des formes cutanées, **20 %** des formes muqueuses.","prio":"P2","sec":"s4"},{"id":"fc-d302-d9c18f","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : sièges des métastases hématogènes ?","back":"**Poumons** ++, foie, os, ganglions à distance.","prio":"P3","sec":"s4"},{"id":"fc-d302-03e4b2","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : risque de récidive global ?","back":"Environ **7 %**.","prio":"P3","sec":"s4"},{"id":"fc-d302-00027b","poly":"dermato","fiche":"d302","front":"Carcinome épidermoïde : causes d'évolution défavorable ?","back":"**Souvent** une prise en charge initiale **tardive, insuffisante ou inadaptée**, ou une forme **agressive**.","prio":"P3","sec":"s4"},{"id":"fc-d302-be565d","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : évolution et potentiel métastatique ?","back":"Évolution **lente**, malignité **locale**, métastases **exceptionnelles**.","prio":"P1","sec":"s5"},{"id":"fc-d302-3ee8a6","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : âge de survenue ?","back":"Surtout **après 50 ans**.","prio":"P2","sec":"s5"},{"id":"fc-d302-d7c8c9","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : type d'exposition solaire en cause ?","back":"Expositions **intermittentes aiguës** (enfance, adolescence) plus que chronique ; **80 %** en zone exposée.","prio":"P1","sec":"s5"},{"id":"fc-d302-3922d1","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : prédispositions génétiques ?","back":"**Syndrome de Gorlin**, **xeroderma pigmentosum**.","prio":"P2","sec":"s5"},{"id":"fc-d302-74f1b1","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : peut-il toucher les muqueuses ?","back":"**Jamais**.","prio":"P1","sec":"s5"},{"id":"fc-d302-f1747d","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : lésion élémentaire quasi constante ?","back":"La **perle** : papule rosée, arrondie, **translucide**, souvent **télangiectasique**.","prio":"P1","sec":"s5"},{"id":"fc-d302-7fed8c","poly":"dermato","fiche":"d302","front":"Carcinome basocellulaire : forme clinique la plus fréquente ?","back":"Le **CBC nodulaire** : tumeur ferme, bien limitée, lisse.","prio":"P1","sec":"s5"},{"id":"fc-d302-fb3c36","poly":"dermato","fiche":"d302","front":"CBC nodulaire : que peut-il simuler ?","back":"Un **kyste** (ou s'étendre de façon centrifuge).","prio":"P3","sec":"s5"},{"id":"fc-d302-e21185","poly":"dermato","fiche":"d302","front":"CBC superficiel : aspect et siège ?","back":"Plaque **érythémato-squameuse** bordée de petites perles, extensive ; surtout sur le **tronc**.","prio":"P1","sec":"s5"},{"id":"fc-d302-5e722e","poly":"dermato","fiche":"d302","front":"CBC superficiel : synonyme ?","back":"CBC **pagétoïde**.","prio":"P3","sec":"s5"},{"id":"fc-d302-2dead0","poly":"dermato","fiche":"d302","front":"CBC sclérodermiforme : aspect ?","back":"Aspect de **cicatrice** blanchâtre, dure, **mal limitée**, parfois atrophique.","prio":"P1","sec":"s5"},{"id":"fc-d302-d484ea","poly":"dermato","fiche":"d302","front":"CBC : la pigmentation a-t-elle une valeur pronostique ?","back":"**Non** ; et toutes les formes peuvent **s'ulcérer**.","prio":"P2","sec":"s5"},{"id":"fc-d302-413e01","poly":"dermato","fiche":"d302","front":"CBC : diagnostics différentiels ?","back":"**CEC**, **Bowen**, **mélanome** (CBC « tatoué ») ; CBC superficiel : **psoriasis**, **dermatophytie**.","prio":"P1","sec":"s5"},{"id":"fc-d302-5b328c","poly":"dermato","fiche":"d302","front":"CBC d'aspect évocateur : comment confirmer ?","back":"**Exérèse à visée diagnostique** + examen anatomopathologique.","prio":"P1","sec":"s5"},{"id":"fc-d302-8fbf14","poly":"dermato","fiche":"d302","front":"CBC : indications d'une biopsie avant traitement ?","back":"Diagnostic **incertain**, traitement **non chirurgical** envisagé, exérèse **complexe**, lésion très **étendue**.","prio":"P1","sec":"s5"},{"id":"fc-d302-b9db0b","poly":"dermato","fiche":"d302","front":"CBC : histologie ?","back":"Lobules de petits kératinocytes **basophiles**, disposition périphérique **en palissade**, **fentes de rétraction**.","prio":"P3","sec":"s5"},{"id":"fc-d302-a69d90","poly":"dermato","fiche":"d302","front":"CBC : risques évolutifs ?","back":"**Récidive locale**, extension locorégionale à bas bruit, survenue d'un **autre cancer** plus agressif.","prio":"P2","sec":"s5"},{"id":"fc-d302-c82179","poly":"dermato","fiche":"d302","front":"CBC : bilan d'extension ?","back":"**Pas de bilan à distance** ; seul l'**examen clinique** (autres carcinomes) ; imagerie locale si forme étendue.","prio":"P2","sec":"s5"},{"id":"fc-d302-99c8ef","poly":"dermato","fiche":"d302","front":"CBC étendu : imagerie locale possible ?","back":"**Scanner cranio-facial**, **IRM du massif facial**.","prio":"P3","sec":"s5"},{"id":"fc-d302-f31ad3","poly":"dermato","fiche":"d302","front":"CBC : facteurs de mauvais pronostic ?","back":"Siège **nez/péri-orificiel**, forme **mal limitée** (sclérodermiforme, infiltrante), **> 2 cm** (> 1 cm nez), **récidive**.","prio":"P2","sec":"s5"},{"id":"fc-d302-026f69","poly":"dermato","fiche":"d302","front":"CBC : risque global de récidive ?","back":"Entre **5 et 10 %**.","prio":"P3","sec":"s5"},{"id":"fc-d302-3590e5","poly":"dermato","fiche":"d302","front":"CBC : intérêt épidémiologique ?","back":"**Marqueur de risque** de cancer de la peau : surveillance et dépistage.","prio":"P2","sec":"s5"},{"id":"fc-d302-e49b43","poly":"dermato","fiche":"d302","front":"CEC vs CBC : précurseurs ?","back":"CEC : **oui** (kératose actinique, leucoplasie) ; CBC : **non**.","prio":"P1","sec":"s6"},{"id":"fc-d302-04d473","poly":"dermato","fiche":"d302","front":"CEC vs CBC : siège ?","back":"CEC : **peau ou muqueuse** ; CBC : **exclusivement la peau**.","prio":"P1","sec":"s6"},{"id":"fc-d302-424bd8","poly":"dermato","fiche":"d302","front":"CEC vs CBC : bilan initial ?","back":"CEC : recherche d'**adénopathies**, extension si CEC à risque ; CBC : **pas de bilan d'extension**.","prio":"P1","sec":"s6"},{"id":"fc-d302-dceae2","poly":"dermato","fiche":"d302","front":"CEC vs CBC : mode évolutif ?","back":"CEC : risque local et **métastatique** (ganglions puis poumon, foie) ; CBC : agressivité **locorégionale**, destruction.","prio":"P2","sec":"s6"},{"id":"fc-d302-2f34ac","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : traitement commun ?","back":"**Exérèse chirurgicale** avec **marge de sécurité** selon les éléments pronostiques.","prio":"P1","sec":"s6"},{"id":"fc-d302-82b276","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : modalités et durée de la surveillance ?","back":"**Clinique**, régulière, selon le groupe pronostique et les facteurs de risque, **au mieux à vie**.","prio":"P1","sec":"s6"},{"id":"fc-d302-694b4c","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : prévention commune ?","back":"**Réduire les expositions solaires**.","prio":"P1","sec":"s6"},{"id":"fc-d302-745670","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : pronostic après exérèse ?","back":"La grande majorité **guérissent** après exérèse chirurgicale.","prio":"P2","sec":"s6"},{"id":"fc-d302-a34ac1","poly":"dermato","fiche":"d302","front":"Verrues : risque oncogène des HPV cutanés ?","back":"Des **co-carcinogènes** sont le plus souvent nécessaires : **UV +++**, tabac, **immunosuppression**.","prio":"P2","sec":"s7"},{"id":"fc-d302-f95415","poly":"dermato","fiche":"d302","front":"HPV muqueux à haut risque : types cités ?","back":"**HPV16, 18, 31, 33** (directement carcinogènes).","prio":"P2","sec":"s7"},{"id":"fc-d302-2e9e76","poly":"dermato","fiche":"d302","front":"Verrues : comment pose-t-on le diagnostic ?","back":"**Cliniquement**.","prio":"P1","sec":"s7"},{"id":"fc-d302-275e25","poly":"dermato","fiche":"d302","front":"Verrues : prévalence et population ?","back":"**7 à 10 %** ; enfants scolarisés, adultes jeunes.","prio":"P2","sec":"s7"},{"id":"fc-d302-2b6f22","poly":"dermato","fiche":"d302","front":"Verrues des mains d'origine professionnelle : métiers et HPV ?","back":"**Bouchers**, vétérinaires, abattoirs, poissonniers ; **HPV7**.","prio":"P3","sec":"s7"},{"id":"fc-d302-763c59","poly":"dermato","fiche":"d302","front":"Infections à HPV chez l'immunodéprimé : particularités ?","back":"**Plus fréquentes** et **plus agressives**.","prio":"P1","sec":"s7"},{"id":"fc-d302-34c655","poly":"dermato","fiche":"d302","front":"Greffé d'organe : facteurs d'incidence des verrues et cancers cutanés ?","back":"**Durée** et **intensité** de l'immunodépression ; photoprotection, autodépistage, suivi systématique +++.","prio":"P1","sec":"s7"},{"id":"fc-d302-ed64af","poly":"dermato","fiche":"d302","front":"Myrmécie : HPV et caractéristiques ?","back":"**HPV1** ; verrue plantaire **profonde**, **douloureuse à la pression**, la plus fréquente.","prio":"P1","sec":"s7"},{"id":"fc-d302-62d852","poly":"dermato","fiche":"d302","front":"Myrmécie : aspect ?","back":"Épais **anneau kératosique** ; centre papillomateux piqueté de **points noirs** (microhémorragies).","prio":"P2","sec":"s7"},{"id":"fc-d302-421618","poly":"dermato","fiche":"d302","front":"Verrues en mosaïque : HPV et caractéristiques ?","back":"**HPV2** ; plantaires, **non douloureuses**, coalescentes en placard kératosique.","prio":"P2","sec":"s7"},{"id":"fc-d302-1eacc2","poly":"dermato","fiche":"d302","front":"Verrues vulgaires communes : HPV et siège ?","back":"**HPV2** ; **dos des mains et des doigts**.","prio":"P2","sec":"s7"},{"id":"fc-d302-f74b98","poly":"dermato","fiche":"d302","front":"Verrues vulgaires : aspect ?","back":"Élevures de 3-4 mm, surface hémisphérique **hérissée de saillies kératosiques** grisâtres.","prio":"P3","sec":"s7"},{"id":"fc-d302-b1c92c","poly":"dermato","fiche":"d302","front":"Verrues péri- et sous-unguéales : quel élément est une indication de traitement ?","back":"Les **altérations de l'ongle**.","prio":"P2","sec":"s7"},{"id":"fc-d302-83f544","poly":"dermato","fiche":"d302","front":"Verrues filiformes : siège et mode d'extension dans la barbe ?","back":"Visage, cuir chevelu, péri-orificiel, cou, **barbe** (auto-inoculation par le **rasage**).","prio":"P3","sec":"s7"},{"id":"fc-d302-5d5341","poly":"dermato","fiche":"d302","front":"Verrues planes communes : HPV, siège et aspect ?","back":"**HPV3** ; visage, dos des mains ; petites papules **très peu saillantes**, jaunes, brunes ou chamois.","prio":"P2","sec":"s7"},{"id":"fc-d302-f3e04b","poly":"dermato","fiche":"d302","front":"Verrues planes : évolution ?","back":"Régression habituelle en **moins de 2 ans** ; parfois chroniques chez l'**immunodéprimé**.","prio":"P2","sec":"s7"},{"id":"fc-d302-92d2b9","poly":"dermato","fiche":"d302","front":"Verrue plantaire : diagnostics différentiels ?","back":"**Durillon** (frottement, points d'appui) ; **mélanome achromique** de la plante +++.","prio":"P1","sec":"s7"},{"id":"fc-d302-dbea60","poly":"dermato","fiche":"d302","front":"Verrue sous- ou péri-unguéale qui persiste : que craindre ?","back":"Un **carcinome in situ**.","prio":"P2","sec":"s7"},{"id":"fc-d302-e8b472","poly":"dermato","fiche":"d302","front":"Mélanome : variation géographique de l'incidence ?","back":"Maximale en **Australie** (peau blanche), minimale en Asie et peaux noires ; liée à la **latitude** (UV).","prio":"P3","sec":"s8"},{"id":"fc-d302-f67e9e","poly":"dermato","fiche":"d302","front":"Mélanome : incidence en France ?","back":"Environ **15 000** nouveaux cas/an (taux standardisé ~10/100 000).","prio":"P3","sec":"s8"},{"id":"fc-d302-93cf2b","poly":"dermato","fiche":"d302","front":"Mélanome : évolution de la mortalité par rapport à l'incidence et explication ?","back":"Progresse **moins** que l'incidence : diagnostic plus précoce de lésions **moins épaisses**.","prio":"P3","sec":"s8"},{"id":"fc-d302-a5cece","poly":"dermato","fiche":"d302","front":"Mélanome : âge médian de survenue ?","back":"**55 ans** ; exceptionnel chez l'enfant prépubère.","prio":"P2","sec":"s8"},{"id":"fc-d302-0f41c4","poly":"dermato","fiche":"d302","front":"Mélanome superficiel extensif : rôle des UV ?","back":"Expositions **intermittentes et intenses**, **brûlures solaires** ; enfance > âge adulte.","prio":"P2","sec":"s8"},{"id":"fc-d302-344836","poly":"dermato","fiche":"d302","front":"Mélanome de Dubreuilh : type d'exposition solaire ?","back":"Exposition **chronique cumulative**.","prio":"P2","sec":"s8"},{"id":"fc-d302-ebe455","poly":"dermato","fiche":"d302","front":"Mélanomes des paumes, plantes et muqueuses : lien avec le soleil ?","back":"**Aucun**.","prio":"P2","sec":"s8"},{"id":"fc-d302-5a86be","poly":"dermato","fiche":"d302","front":"Mélanome familial : définition et fréquence ?","back":"**Deux apparentés au 1er degré** atteints ; **10 %** des mélanomes.","prio":"P2","sec":"s8"},{"id":"fc-d302-455153","poly":"dermato","fiche":"d302","front":"Mélanome familial : principal gène de prédisposition ?","back":"**CDKN2A** (suppresseur de tumeur), muté dans 10 à 30 % des formes familiales.","prio":"P2","sec":"s8"},{"id":"fc-d302-576b03","poly":"dermato","fiche":"d302","front":"Phénotype « roux » : variants de quel gène ?","back":"Gène du récepteur de la mélanocortine (**MC1R**), éventuellement associé au risque de mélanome.","prio":"P3","sec":"s8"},{"id":"fc-d302-092df3","poly":"dermato","fiche":"d302","front":"Syndrome des nævus atypiques : définition ?","back":"Nævus **nombreux (> 50)**, souvent **grands (> 6 mm)**, d'aspect souvent **atypique**, parfois en peau non exposée.","prio":"P2","sec":"s8"},{"id":"fc-d302-ab1c24","poly":"dermato","fiche":"d302","front":"Mélanome : risque de second mélanome après un premier ?","back":"**5 à 8 %**.","prio":"P2","sec":"s8"},{"id":"fc-d302-0d773e","poly":"dermato","fiche":"d302","front":"Mélanome : principaux facteurs de risque ?","back":"**Antécédent personnel/familial**, **phototype clair**, **nombre élevé de nævus** ; soleil (expositions intermittentes, coups de soleil).","prio":"P1","sec":"s8"},{"id":"fc-d302-220175","poly":"dermato","fiche":"d302","front":"Mélanome : naît-il le plus souvent sur un nævus ?","back":"**Non** : la majorité naissent **de novo**, sur peau apparemment saine.","prio":"P1","sec":"s8"},{"id":"fc-d302-9605fa","poly":"dermato","fiche":"d302","front":"Petits nævus communs : faut-il une exérèse préventive ?","back":"**Non** : risque de transformation **très faible**.","prio":"P1","sec":"s8"},{"id":"fc-d302-2cf057","poly":"dermato","fiche":"d302","front":"Nævus congénitaux : quand le risque de mélanome est-il plus élevé ?","back":"S'ils sont **grands** : **> 20 cm** à l'âge adulte.","prio":"P2","sec":"s8"},{"id":"fc-d302-15be86","poly":"dermato","fiche":"d302","front":"Grands nævus congénitaux : position du Collège sur l'exérèse préventive précoce ?","back":"**Souhaitable** si réalisable (p. 373) ; ailleurs « peut se discuter », pas toujours réalisable (p. 390).","prio":"P3","sec":"s8"},{"id":"fc-d302-8e1cc4","poly":"dermato","fiche":"d302","front":"Mélanome : deux phases de croissance histologique ?","back":"Extension **horizontale** intra-épidermique, puis **verticale** (derme superficiel puis profond).","prio":"P2","sec":"s8"},{"id":"fc-d302-344d78","poly":"dermato","fiche":"d302","front":"Mélanome : quelle forme n'a pas de phase horizontale ?","back":"Le **mélanome nodulaire**.","prio":"P1","sec":"s8"},{"id":"fc-d302-00de83","poly":"dermato","fiche":"d302","front":"Mélanome : 4 temps du diagnostic positif ?","back":"**Suspicion clinique** → **dermoscopie** → **exérèse diagnostique** → **confirmation anatomopathologique**.","prio":"P1","sec":"s9"},{"id":"fc-d302-c76f49","poly":"dermato","fiche":"d302","front":"Lésion pigmentée : quelle hypothèse envisager toujours ?","back":"Un **mélanome**.","prio":"P1","sec":"s9"},{"id":"fc-d302-3aec9c","poly":"dermato","fiche":"d302","front":"Règle ABCDE : signification des lettres ?","back":"**A**symétrie · **B**ords irréguliers · **C**ouleur inhomogène · **D**iamètre > 6 mm · **É**volution récente.","prio":"P1","sec":"s9"},{"id":"fc-d302-b7f477","poly":"dermato","fiche":"d302","front":"Règle ABCDE : nombre de critères pour suspecter un mélanome ?","back":"**Au moins 2**.","prio":"P1","sec":"s9"},{"id":"fc-d302-8d0c79","poly":"dermato","fiche":"d302","front":"Règle ABCDE : quel critère est non spécifique ?","back":"Le **diamètre** > 6 mm.","prio":"P2","sec":"s9"},{"id":"fc-d302-487852","poly":"dermato","fiche":"d302","front":"Règle ABCDE : limites ?","back":"Conçue pour l'**autodépistage** ; repère mal les modifications **subtiles et/ou récentes**.","prio":"P2","sec":"s9"},{"id":"fc-d302-6f9e64","poly":"dermato","fiche":"d302","front":"Règle du vilain petit canard : principe ?","back":"Les nævus d'un patient se ressemblent ; un nævus **discordant** fait suspecter un mélanome.","prio":"P1","sec":"s9"},{"id":"fc-d302-e8652a","poly":"dermato","fiche":"d302","front":"Règle du vilain petit canard : quel examen impose-t-elle ?","back":"Un examen du **corps entier**, patient dénudé.","prio":"P2","sec":"s9"},{"id":"fc-d302-22e791","poly":"dermato","fiche":"d302","front":"Mélanome : proportion repérée par le patient avant le médecin ?","back":"Près de **80 %**.","prio":"P2","sec":"s9"},{"id":"fc-d302-dd5ab4","poly":"dermato","fiche":"d302","front":"Mélanome : valeur du prurit ou du saignement au contact ?","back":"**Signes tardifs**.","prio":"P2","sec":"s9"},{"id":"fc-d302-3fb04e","poly":"dermato","fiche":"d302","front":"Dermatoscopie dans le mélanome : intérêt et caractère obligatoire ?","back":"Améliore **sensibilité et spécificité** chez l'opérateur formé ; **utile mais non obligatoire**.","prio":"P2","sec":"s9"},{"id":"fc-d302-c4c0d0","poly":"dermato","fiche":"d302","front":"Dermoscopie devant une lésion pigmentée : quand est-elle surtout utile ?","back":"Surtout si les nævus sont **nombreux** et/ou **atypiques**.","prio":"P2","sec":"s9"},{"id":"fc-d302-60b58d","poly":"dermato","fiche":"d302","front":"Mélanome suspecté : modalités de l'exérèse diagnostique ?","back":"Sous **anesthésie locale**, exérèse **complète** emportant toute la tumeur jusqu'à l'**hypoderme**.","prio":"P1","sec":"s9"},{"id":"fc-d302-2feed3","poly":"dermato","fiche":"d302","front":"Exérèse d'un mélanome potentiel : faut-il respecter un délai de réflexion ?","back":"**Pas rigoureusement indispensable** : « urgence » diagnostique ; on **informe** le patient.","prio":"P2","sec":"s9"},{"id":"fc-d302-ed158c","poly":"dermato","fiche":"d302","front":"Exérèse esthétique d'une lésion bénigne : délai de réflexion ?","back":"**Incompressible** après information (valeur médico-légale).","prio":"P3","sec":"s9"},{"id":"fc-d302-731df2","poly":"dermato","fiche":"d302","front":"Mélanome suspecté : pourquoi pas de biopsie partielle ?","back":"Mesure du **Breslow** et de l'**index mitotique** impossible : **perte de chance**.","prio":"P1","sec":"s9"},{"id":"fc-d302-b59e98","poly":"dermato","fiche":"d302","front":"Mélanome suspecté : exception où une biopsie partielle se discute ?","back":"Lésion **très grande** dont l'exérèse serait **délabrante** (visage) : biopsies des zones les plus suspectes.","prio":"P2","sec":"s9"},{"id":"fc-d302-fb6f40","poly":"dermato","fiche":"d302","front":"Mélanome : marqueurs immunohistochimiques de la nature mélanocytaire ?","back":"**Melan-A**, **protéine S100**, **HMB45**.","prio":"P2","sec":"s9"},{"id":"fc-d302-5bd9ae","poly":"dermato","fiche":"d302","front":"Mélanome : paramètres histopronostiques sur la pièce ?","back":"**Indice de Breslow**, **ulcération**, **index mitotique**.","prio":"P1","sec":"s9"},{"id":"fc-d302-fa8bda","poly":"dermato","fiche":"d302","front":"Mélanome : apports de l'examen histologique ?","back":"Nature **mélanocytaire**, **malignité** et sous-type, **histopronostic**, exérèse **complète** ou non, ± **BRAF**.","prio":"P2","sec":"s9"},{"id":"fc-d302-893f14","poly":"dermato","fiche":"d302","front":"Mélanome : quand rechercher la mutation BRAF sur la pièce ?","back":"Selon la **RCP**, notamment tumeurs **épaisses** de mauvais pronostic.","prio":"P3","sec":"s9"},{"id":"fc-d302-8728a0","poly":"dermato","fiche":"d302","front":"Mélanome : nature du diagnostic ?","back":"**Anatomoclinique**.","prio":"P2","sec":"s9"},{"id":"fc-d302-bd2c4a","poly":"dermato","fiche":"d302","front":"Mélanome : forme anatomoclinique la plus fréquente ?","back":"**Mélanome superficiel extensif** (SSM), **60 à 70 %**.","prio":"P2","sec":"s10"},{"id":"fc-d302-b9b8e9","poly":"dermato","fiche":"d302","front":"Mélanome de Dubreuilh : terrain et siège ?","back":"Zones exposées **chroniquement** (visage), **après 60 ans**, photovieillissement ; ~10 %.","prio":"P2","sec":"s10"},{"id":"fc-d302-0ea79c","poly":"dermato","fiche":"d302","front":"Mélanome acral lentigineux : sièges et terrain ?","back":"**Paumes, plantes**, bords des doigts/orteils, **appareil unguéal** ; 2 à 5 % des cas mais forme **majoritaire** chez les sujets à **peau pigmentée**.","prio":"P2","sec":"s10"},{"id":"fc-d302-9943a3","poly":"dermato","fiche":"d302","front":"Mélanome nodulaire : fréquence et caractéristiques ?","back":"**10 à 20 %** ; évolution **rapidement verticale** et invasive, parfois **achromique**.","prio":"P2","sec":"s10"},{"id":"fc-d302-b5c434","poly":"dermato","fiche":"d302","front":"Mélanome : à Breslow identique, le pronostic dépend-il de la forme anatomoclinique ?","back":"**Non** : pronostic globalement **comparable**.","prio":"P1","sec":"s10"},{"id":"fc-d302-5fd1d3","poly":"dermato","fiche":"d302","front":"Mélanome AJCC : définition du stade III ?","back":"Atteinte **régionale** : métastases **en transit** et/ou **ganglions régionaux**.","prio":"P2","sec":"s10"},{"id":"fc-d302-11b6c3","poly":"dermato","fiche":"d302","front":"Mélanome AJCC : définition du stade IV ?","back":"**Métastases à distance**.","prio":"P2","sec":"s10"},{"id":"fc-d302-aa05f3","poly":"dermato","fiche":"d302","front":"Mélanome AJCC : définition du stade I ?","back":"Breslow **0-1 mm** ± ulcération, ou **> 1-2 mm sans ulcération**.","prio":"P3","sec":"s10"},{"id":"fc-d302-f23b1f","poly":"dermato","fiche":"d302","front":"Mélanome AJCC : définition du stade IIc ?","back":"Breslow **à partir de 4 mm avec ulcération**.","prio":"P3","sec":"s10"},{"id":"fc-d302-2936ca","poly":"dermato","fiche":"d302","front":"Mélanome in situ : pronostic ?","back":"**Guérison constante** après exérèse et marge élargie.","prio":"P1","sec":"s10"},{"id":"fc-d302-962b66","poly":"dermato","fiche":"d302","front":"Mélanome invasif : types de récidive ?","back":"**Locale**, métastases **en transit**, **ganglionnaires** régionales, **à distance**.","prio":"P1","sec":"s10"},{"id":"fc-d302-239197","poly":"dermato","fiche":"d302","front":"Métastases en transit : définition ?","back":"Métastases cutanées ou sous-cutanées **entre la tumeur et le premier relais ganglionnaire**.","prio":"P2","sec":"s10"},{"id":"fc-d302-305892","poly":"dermato","fiche":"d302","front":"Mélanome : organe à risque particulier de métastase à distance ?","back":"Le **cerveau**.","prio":"P2","sec":"s10"},{"id":"fc-d302-e1b2cc","poly":"dermato","fiche":"d302","front":"Mélanome : risques « épidémiologiques » après un premier mélanome ?","back":"**Second mélanome** primitif ; autres cancers cutanés (**CBC, CE**), parfois favorisés par les thérapies ciblées.","prio":"P2","sec":"s10"},{"id":"fc-d302-240e8a","poly":"dermato","fiche":"d302","front":"Mélanome : principal critère pronostique du primitif ?","back":"L'**indice de Breslow** (épaisseur maximale), corrélation presque linéaire avec la mortalité.","prio":"P1","sec":"s10"},{"id":"fc-d302-6df93e","poly":"dermato","fiche":"d302","front":"Mélanome : valeur pronostique de l'ulcération ?","back":"Valeur **péjorative** importante, **quelle que soit l'épaisseur**.","prio":"P2","sec":"s10"},{"id":"fc-d302-ce0652","poly":"dermato","fiche":"d302","front":"Mélanome : statut actuel de l'index mitotique ?","back":"Valeur indépendante si **< 1 mm**, mais **plus retenu** dans l'AJCC 8e édition.","prio":"P3","sec":"s10"},{"id":"fc-d302-b31972","poly":"dermato","fiche":"d302","front":"Mélanome : durée du risque de récidive ?","back":"**Toute la vie**, sauf mélanomes de très faible épaisseur.","prio":"P2","sec":"s10"},{"id":"fc-d302-1a2921","poly":"dermato","fiche":"d302","front":"Mélanome : survie à 5 ans si Breslow ≤ 1 mm ?","back":"**> 93 %**.","prio":"P3","sec":"s10"},{"id":"fc-d302-116995","poly":"dermato","fiche":"d302","front":"Mélanome : survie à 5 ans si Breslow ≤ 2 mm sans ulcération ?","back":"**> 80 %**.","prio":"P3","sec":"s10"},{"id":"fc-d302-e5dcf2","poly":"dermato","fiche":"d302","front":"Mélanome : survie à 5 ans si Breslow 2-4 mm et/ou ulcération ?","back":"**> 50 %**.","prio":"P3","sec":"s10"},{"id":"fc-d302-8be785","poly":"dermato","fiche":"d302","front":"Mélanome : survie à 5 ans selon l'atteinte ganglionnaire ?","back":"Microscopique : **> 70 %** ; macroscopique : **> 50 %**.","prio":"P3","sec":"s10"},{"id":"fc-d302-e033ed","poly":"dermato","fiche":"d302","front":"Ganglion sentinelle : technique de repérage et signification d'une micrométastase ?","back":"Repéré par **scintigraphie** ; micrométastase = marqueur pronostique indépendant (**stade IIIA**).","prio":"P2","sec":"s10"},{"id":"fc-d302-b2dfd7","poly":"dermato","fiche":"d302","front":"Mélanome stade III : facteurs péjoratifs ?","back":"**Nombre** et **taille** des ganglions, **rupture capsulaire**, **ulcération** du primitif.","prio":"P3","sec":"s10"},{"id":"fc-d302-aca223","poly":"dermato","fiche":"d302","front":"Mélanome stade IV : traitements ayant amélioré le pronostic ?","back":"**Thérapies ciblées** (anti-BRAF V600E/K + anti-MEK) et **immunothérapie** (anti-CTLA4, anti-PD1).","prio":"P2","sec":"s10"},{"id":"fc-d302-0eab3e","poly":"dermato","fiche":"d302","front":"Mélanome métastatique : critères de mauvais pronostic ?","back":"**LDH élevés**, > 3 organes, > 3 métastases hépatiques, métastases **cérébrales** symptomatiques et/ou > 3.","prio":"P3","sec":"s10"},{"id":"fc-d302-c0d4ea","poly":"dermato","fiche":"d302","front":"Nævus : nature et dynamique d'apparition ?","back":"Tumeur mélanocytaire **bénigne**, se multipliant dès l'enfance selon l'**exposition solaire** et la **génétique**.","prio":"P1","sec":"s11"},{"id":"fc-d302-a7cafe","poly":"dermato","fiche":"d302","front":"Peau normale : rapport mélanocytes / kératinocytes ?","back":"**1 mélanocyte pour 20 à 30 kératinocytes** (unité de mélanisation).","prio":"P3","sec":"s11"},{"id":"fc-d302-a181ea","poly":"dermato","fiche":"d302","front":"Mélanocytes : origine embryologique et marqueur ?","back":"**Neuro-ectodermique** ; expriment la **protéine S100**.","prio":"P3","sec":"s11"},{"id":"fc-d302-ebaf9b","poly":"dermato","fiche":"d302","front":"Lésions mélanocytaires : 3 catégories ?","back":"**Bénignes acquises** (nævus communs) · **malformatives** (nævus congénitaux, mélanoses dermiques) · **malignes** (mélanomes).","prio":"P3","sec":"s11"},{"id":"fc-d302-0b80a4","poly":"dermato","fiche":"d302","front":"Mélanoses dermiques : exemples ?","back":"**Tache mongolique**, **nævus d'Ota**.","prio":"P3","sec":"s11"},{"id":"fc-d302-ad9810","poly":"dermato","fiche":"d302","front":"Nævus jonctionnel : localisation des thèques ?","back":"Couche **basale de l'épiderme**.","prio":"P2","sec":"s11"},{"id":"fc-d302-255264","poly":"dermato","fiche":"d302","front":"Nævus dermique : localisation des thèques ?","back":"**Strictement dans le derme**.","prio":"P2","sec":"s11"},{"id":"fc-d302-002777","poly":"dermato","fiche":"d302","front":"Nævus mixte (composé) : localisation des thèques ?","back":"**Derme** et **jonction dermo-épidermique**.","prio":"P2","sec":"s11"},{"id":"fc-d302-4babd3","poly":"dermato","fiche":"d302","front":"Nævus : évolution de la composante jonctionnelle avec l'âge et conséquence ?","back":"Marquée chez l'**enfant**, **diminue** avec l'âge : l'**âge** est fondamental pour interpréter l'histologie.","prio":"P2","sec":"s11"},{"id":"fc-d302-be1cec","poly":"dermato","fiche":"d302","front":"Nævus vs mélanome : sur quoi repose surtout la distinction histologique ?","back":"L'**architecture** (peu la cytologie).","prio":"P2","sec":"s11"},{"id":"fc-d302-af5670","poly":"dermato","fiche":"d302","front":"« Dysplasie » mélanocytaire : signification ?","back":"**N'est pas** synonyme de tumeur maligne ni précancéreuse.","prio":"P1","sec":"s11"},{"id":"fc-d302-c63023","poly":"dermato","fiche":"d302","front":"Nævus communs : âge d'apparition et plateau ?","back":"Dès **4-5 ans** ; plateau vers la **4e décennie** (~20 nævus en moyenne).","prio":"P2","sec":"s11"},{"id":"fc-d302-6ce5d9","poly":"dermato","fiche":"d302","front":"Nævus : évolution du relief entre enfance et âge adulte ?","back":"Enfance : **planes** > tubéreux ; adulte : **tubéreux** > plans.","prio":"P3","sec":"s11"},{"id":"fc-d302-6a9c76","poly":"dermato","fiche":"d302","front":"Nævus : évolution après 60 ans ?","back":"**Régression** progressive et raréfaction.","prio":"P3","sec":"s11"},{"id":"fc-d302-fb831b","poly":"dermato","fiche":"d302","front":"Nævus et grossesse : modifications et conduite ?","back":"Augmentation de taille, pigmentation modifiée possibles ; **vigilance** (mélanomes agressifs possibles) ; **exérèse si doute**.","prio":"P2","sec":"s11"},{"id":"fc-d302-ee2836","poly":"dermato","fiche":"d302","front":"Nævus : 3 caractéristiques d'un nævus banal ?","back":"**Non évolutif**, grossièrement **régulier**, **comparable** aux autres nævus.","prio":"P1","sec":"s12"},{"id":"fc-d302-836dd6","poly":"dermato","fiche":"d302","front":"Nævus tubéreux : aspect ?","back":"Peu ou pas pigmenté ; papule **en dôme**, plutôt au **visage** ; thèques surtout dermiques.","prio":"P3","sec":"s12"},{"id":"fc-d302-f44f72","poly":"dermato","fiche":"d302","front":"Nævus bleu : aspect et nature ?","back":"Nævus dermique très chargé en mélanine, **bleu nuit**, visage ou membre supérieur ; **bénin**.","prio":"P2","sec":"s12"},{"id":"fc-d302-7f4866","poly":"dermato","fiche":"d302","front":"Nævus achromique : aspect ?","back":"Couleur de **peau normale**, souvent tubéreux, parfois **centré par un poil** ; visage ou tronc.","prio":"P3","sec":"s12"},{"id":"fc-d302-7722b9","poly":"dermato","fiche":"d302","front":"Nævus cliniquement atypique : aspect ?","back":"Souvent **> 5 mm**, rosé/brun, bords **asymétriques**, forme irrégulière, couleur **inhomogène** ; type jonctionnel.","prio":"P2","sec":"s12"},{"id":"fc-d302-eafa5a","poly":"dermato","fiche":"d302","front":"Nævus cliniquement atypique : terme à préférer ?","back":"« **Atypique** » plutôt que « dysplasique ».","prio":"P3","sec":"s12"},{"id":"fc-d302-617cce","poly":"dermato","fiche":"d302","front":"Nævus atypiques : signification et conduite ?","back":"**Marqueur phénotypique** de risque de mélanome ; **exérèse préventive non justifiée**.","prio":"P1","sec":"s12"},{"id":"fc-d302-5140ed","poly":"dermato","fiche":"d302","front":"Nævus atypiques : antécédents à rechercher ?","back":"**Antécédents familiaux de mélanome** (transmission familiale possible).","prio":"P2","sec":"s12"},{"id":"fc-d302-5ce5f7","poly":"dermato","fiche":"d302","front":"Nævus : seuil de « grande taille » selon le Collège ?","back":"**> 5 mm** (NCA, nævus communs) ; **> 6 mm** dans le syndrome des nævus atypiques.","prio":"P3","sec":"s12"},{"id":"fc-d302-f7d2a8","poly":"dermato","fiche":"d302","front":"Nævus du lit de l'ongle : aspect bénin ?","back":"**Mélanonychie en bande** homogène, régulière, **stable** dans le temps.","prio":"P2","sec":"s12"},{"id":"fc-d302-e162f1","poly":"dermato","fiche":"d302","front":"Mélanonychies multiples chez le sujet à peau foncée : signification ?","back":"Simple **dépôt de pigment**, sans prolifération mélanocytaire.","prio":"P3","sec":"s12"},{"id":"fc-d302-d4adda","poly":"dermato","fiche":"d302","front":"Nævus des oreilles et des seins : particularité ?","back":"Analyse anatomoclinique **parfois délicate**.","prio":"P3","sec":"s12"},{"id":"fc-d302-5ff285","poly":"dermato","fiche":"d302","front":"Nævus congénitaux : fréquence à la naissance ?","back":"**< 1 %** des naissances.","prio":"P3","sec":"s12"},{"id":"fc-d302-f3b5eb","poly":"dermato","fiche":"d302","front":"Nævus congénital de grande taille : définition ?","back":"Diamètre projeté à l'âge adulte **> 20 cm**.","prio":"P2","sec":"s12"},{"id":"fc-d302-cbe547","poly":"dermato","fiche":"d302","front":"Nævus congénitaux géants : distribution et risques ?","back":"Distribution **métamérique**, souvent dorsale ; impact **esthétique** et **risque accru de mélanome**.","prio":"P2","sec":"s12"},{"id":"fc-d302-0e8421","poly":"dermato","fiche":"d302","front":"Tache mongolique : aspect, siège et évolution ?","back":"Tache **ardoisée** ~10 cm, **lombo-sacrée** ; disparaît **en règle** progressivement dans l'enfance.","prio":"P2","sec":"s12"},{"id":"fc-d302-d9d393","poly":"dermato","fiche":"d302","front":"Tache mongolique : fréquence ?","back":"Très fréquente chez les enfants d'origine **africaine ou asiatique** ; **1 %** des enfants à peau claire.","prio":"P3","sec":"s12"},{"id":"fc-d302-d3f071","poly":"dermato","fiche":"d302","front":"Nævus d'Ota : topographie ?","back":"**En règle unilatéral**, territoire des **deux branches supérieures du trijumeau** ; sclérotique et conjonctive possiblement pigmentées.","prio":"P3","sec":"s12"},{"id":"fc-d302-d30f5b","poly":"dermato","fiche":"d302","front":"Halo nævus (phénomène de Sutton) : définition et évolution ?","back":"**Halo blanc** autour d'un nævus (infiltrat cytotoxique), aboutissant à sa **disparition** ; surtout vers la 2e décennie, tronc.","prio":"P2","sec":"s12"},{"id":"fc-d302-d5520b","poly":"dermato","fiche":"d302","front":"Nævus : microtraumatismes répétés et risque de transformation ?","back":"**Pas d'augmentation** du risque ; exérèse d'un nævus excorié discutée pour le **confort**.","prio":"P1","sec":"s12"},{"id":"fc-d302-54a001","poly":"dermato","fiche":"d302","front":"Nævus exposés au soleil (tronc, visage) : risque de dégénérescence ?","back":"**Pas plus élevé**.","prio":"P2","sec":"s12"},{"id":"fc-d302-6036eb","poly":"dermato","fiche":"d302","front":"Folliculite sous- ou intranævique : présentation ?","back":"Nævus **transitoirement inflammatoire** et sensible.","prio":"P3","sec":"s12"},{"id":"fc-d302-5ac9d5","poly":"dermato","fiche":"d302","front":"Nævus commun : probabilité de transformation en mélanome ?","back":"**Rare** : < 1 pour 100 000.","prio":"P1","sec":"s12"},{"id":"fc-d302-cd1b13","poly":"dermato","fiche":"d302","front":"Mélanome : proportion survenant hors de toute lésion préexistante ?","back":"**80 %**.","prio":"P1","sec":"s12"},{"id":"fc-d302-3852ad","poly":"dermato","fiche":"d302","front":"Nævus : quand sont-ils marqueurs de risque de mélanome ?","back":"**> 50** nævus, taille **> 5 mm**, **> 10 nævus atypiques**, **antécédents familiaux** de mélanome.","prio":"P1","sec":"s12"},{"id":"fc-d302-b7831c","poly":"dermato","fiche":"d302","front":"Nævus congénitaux : risque de mélanome selon la taille ?","back":"Petits : comme les nævus communs ; **géants** : précurseurs potentiels (taille, satellites, topographie **médiane**).","prio":"P2","sec":"s12"},{"id":"fc-d302-c60881","poly":"dermato","fiche":"d302","front":"Mélanonychie : quels signes font craindre un mélanome ?","back":"Mélanonychie qui **évolue** ou ne touche qu'**un seul doigt**.","prio":"P1","sec":"s12"},{"id":"fc-d302-a58379","poly":"dermato","fiche":"d302","front":"Halo nævus : quels signes font craindre un mélanome ?","back":"Apparition **tardive** ou halo **irrégulier**.","prio":"P1","sec":"s12"},{"id":"fc-d302-f2cad3","poly":"dermato","fiche":"d302","front":"Lésion pigmentée : lésions pouvant simuler un mélanome ?","back":"**Nævus atypique**, **kératose séborrhéique**, **CBC tatoué**, histiocytofibrome pigmenté, **angiome thrombosé**, hématome plantaire.","prio":"P2","sec":"s13"},{"id":"fc-d302-b3b4c9","poly":"dermato","fiche":"d302","front":"Kératose séborrhéique : aspect ?","back":"Après 40-50 ans ; surface mate, **bords nets** (« posée » sur la peau), grains blanchâtres, friable ; surface **cérébriforme**.","prio":"P2","sec":"s13"},{"id":"fc-d302-5bf9d1","poly":"dermato","fiche":"d302","front":"Lésion pigmentée la plus fréquente après 40 ans ?","back":"La **kératose séborrhéique** (bénigne).","prio":"P2","sec":"s13"},{"id":"fc-d302-ceecaa","poly":"dermato","fiche":"d302","front":"Histiocytofibrome : signe à la palpation ?","back":"**Pastille indurée** (disque dur), invagination centrale.","prio":"P3","sec":"s13"},{"id":"fc-d302-d7c0ae","poly":"dermato","fiche":"d302","front":"Angiome thrombosé : quel mélanome peut-il simuler ?","back":"Un petit **mélanome nodulaire**.","prio":"P3","sec":"s13"},{"id":"fc-d302-95c9c1","poly":"dermato","fiche":"d302","front":"Lentigo : aspect ?","back":"Petites macules pigmentées, contours « **en tache de peinture** », teinte **uniforme et fixe**.","prio":"P3","sec":"s13"},{"id":"fc-d302-f49b13","poly":"dermato","fiche":"d302","front":"Éphélides : aspect ?","back":"Semis de petites macules **brun clair**, plus foncées au soleil, en zones **exposées** (sujets roux).","prio":"P3","sec":"s13"},{"id":"fc-d302-620e8c","poly":"dermato","fiche":"d302","front":"Lésion pigmentée douteuse : conduite ?","back":"**Exérèse chirurgicale** pour examen anatomopathologique.","prio":"P1","sec":"s13"},{"id":"fc-d302-3ad09d","poly":"dermato","fiche":"d302","front":"Lésion pigmentée : seul examen affirmant bénignité ou malignité ?","back":"L'**examen anatomopathologique**.","prio":"P2","sec":"s13"},{"id":"fc-d302-d3f94b","poly":"dermato","fiche":"d302","front":"Critères ABCD : à quelle forme de mélanome ne s'appliquent-ils pas ?","back":"Au **mélanome nodulaire**.","prio":"P1","sec":"s13"},{"id":"fc-d302-b1ea9d","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : moyens physiques de destruction ?","back":"**Cryothérapie** à l'azote liquide, **électrocoagulation**, **laser CO₂**.","prio":"P2","sec":"s14"},{"id":"fc-d302-9c8efc","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : moyen physico-chimique ?","back":"**Photothérapie dynamique**.","prio":"P2","sec":"s14"},{"id":"fc-d302-92c882","poly":"dermato","fiche":"d302","front":"Kératoses actiniques : topiques chimiques ?","back":"**5-fluoro-uracile** crème ou **imiquimod** crème.","prio":"P2","sec":"s14"},{"id":"fc-d302-a33e28","poly":"dermato","fiche":"d302","front":"Champ de cancérisation : que rechercher parmi les kératoses actiniques ?","back":"Un **CE** ou un **CBC** coexistant.","prio":"P2","sec":"s14"},{"id":"fc-d302-37aae7","poly":"dermato","fiche":"d302","front":"Traiter les lésions précancéreuses : quel objectif ?","back":"**Prévention primaire** des carcinomes.","prio":"P2","sec":"s14"},{"id":"fc-d302-fb5e07","poly":"dermato","fiche":"d302","front":"Leucoplasie : options thérapeutiques ?","back":"**Destruction** (mêmes moyens que les kératoses actiniques) ou **chirurgie**.","prio":"P2","sec":"s15"},{"id":"fc-d302-3f61d6","poly":"dermato","fiche":"d302","front":"Leucoplasie : mesures de prévention ?","back":"**Arrêt du tabac**, réduire les autres cocarcinogènes ; traiter une inflammation chronique (**lichen scléreux**, lichen érosif).","prio":"P2","sec":"s15"},{"id":"fc-d302-fa7d66","poly":"dermato","fiche":"d302","front":"Carcinome in situ : types de traitement ?","back":"Traitements **locaux** : **chirurgicaux** ou **destructeurs** (physiques ou chimiques).","prio":"P1","sec":"s16"},{"id":"fc-d302-c682d4","poly":"dermato","fiche":"d302","front":"Carcinome in situ : moyens destructeurs cités ?","back":"**Cryochirurgie**, **5-fluoro-uracile** topique, **imiquimod** topique, **photothérapie dynamique**.","prio":"P2","sec":"s16"},{"id":"fc-d302-44797d","poly":"dermato","fiche":"d302","front":"CEC : quelle instance valide la prise en charge ?","back":"La **RCP** (après consultation d'annonce) ; seuls les CBC sans critère agressif en sont dispensés.","prio":"P1","sec":"s17"},{"id":"fc-d302-217ec5","poly":"dermato","fiche":"d302","front":"CEC : quand biopsier d'abord plutôt qu'exciser d'emblée ?","back":"Diagnostic **incertain**, chirurgie **complexe**, lésion très **volumineuse** ou **inhabituelle**, topographie ou chirurgie **mutilante** (lèvres…) ; sinon exérèse d'emblée.","prio":"P2","sec":"s17"},{"id":"fc-d302-8bcd05","poly":"dermato","fiche":"d302","front":"CEC localisé : traitement de première intention ?","back":"**Exérèse chirurgicale** avec marge de peau saine adaptée au **groupe pronostique**.","prio":"P1","sec":"s17"},{"id":"fc-d302-c763fa","poly":"dermato","fiche":"d302","front":"Carcinomes cutanés : marges d'exérèse ?","back":"**3 à 10 mm** selon le groupe pronostique ; **plus larges pour un CEC** que pour un CBC.","prio":"P1","sec":"s17"},{"id":"fc-d302-501b59","poly":"dermato","fiche":"d302","front":"Carcinome cutané : modalités habituelles de l'exérèse ?","back":"Le plus souvent **exérèse-suture en ambulatoire** ; parfois en **2 temps** sous AG (contrôle histologique puis reconstruction).","prio":"P2","sec":"s17"},{"id":"fc-d302-b328bc","poly":"dermato","fiche":"d302","front":"Carcinome cutané : exérèse incomplète ou limite, conduite ?","back":"**Reprise chirurgicale indispensable**.","prio":"P1","sec":"s17"},{"id":"fc-d302-87e983","poly":"dermato","fiche":"d302","front":"CBC : quand la RCP n'est-elle pas nécessaire ?","back":"CBC **sans critère agressif** (présentation si traitement complexe).","prio":"P2","sec":"s18"},{"id":"fc-d302-fe365b","poly":"dermato","fiche":"d302","front":"CBC : traitement de première intention et marges ?","back":"**Exérèse chirurgicale**, marges **3 à 10 mm** selon le groupe pronostique (**moins larges** que pour un CEC).","prio":"P1","sec":"s18"},{"id":"fc-d302-66c228","poly":"dermato","fiche":"d302","front":"CBC : que proposer au patient après traitement ?","back":"**Information** et éducation à l'**autosurveillance** et à l'**autodépistage**.","prio":"P2","sec":"s18"},{"id":"fc-d302-4bd1f0","poly":"dermato","fiche":"d302","front":"CBC pigmenté (« tatoué ») : quel diagnostic fait-il discuter ?","back":"Un **mélanome**.","prio":"P2","sec":"s18"},{"id":"fc-d302-d400b8","poly":"dermato","fiche":"d302","front":"Carcinome inopérable ou délabrant : alternatives à la chirurgie ?","back":"**Radiothérapie** (électronthérapie, curiethérapie) ou **cryochirurgie** (après biopsie et RCP).","prio":"P2","sec":"s19"},{"id":"fc-d302-5891c3","poly":"dermato","fiche":"d302","front":"Cryochirurgie : technique et piège ?","back":"**Cryode de contact** sous contrôle impédancemétrique ; à ne pas confondre avec la **cryothérapie**.","prio":"P3","sec":"s19"},{"id":"fc-d302-f6b858","poly":"dermato","fiche":"d302","front":"Carcinome superficiel : alternatives non chirurgicales ?","back":"**Photothérapie dynamique** ou **imiquimod** topique.","prio":"P2","sec":"s19"},{"id":"fc-d302-a769d8","poly":"dermato","fiche":"d302","front":"Imiquimod : indications parmi les carcinomes ?","back":"**Uniquement** CBC **superficiel** ou CEC **in situ**.","prio":"P2","sec":"s19"},{"id":"fc-d302-16425a","poly":"dermato","fiche":"d302","front":"Carcinome cutané traité : que dépiste la surveillance ?","back":"**Récidive** locale ou ganglionnaire, **nouveau CBC ou CEC**, **mélanome**.","prio":"P1","sec":"s20"},{"id":"fc-d302-db5834","poly":"dermato","fiche":"d302","front":"Après un carcinome : pourquoi chercher aussi un mélanome ?","back":"CBC, CEC et mélanome partagent **terrain** et facteurs de risque, et sont **souvent associés**.","prio":"P2","sec":"s20"},{"id":"fc-d302-aedb33","poly":"dermato","fiche":"d302","front":"Prévention des carcinomes : plage horaire à éviter ?","back":"**12 h à 16 h** (d201, transplanté : a fortiori 11 h - 16 h).","prio":"P1","sec":"s21"},{"id":"fc-d302-6691ab","poly":"dermato","fiche":"d302","front":"Prévention des carcinomes : mesures de photoprotection ?","back":"**Chapeau**, **vêtements**, **ombre** ; déconseiller les **lampes à bronzer**.","prio":"P1","sec":"s21"},{"id":"fc-d302-57dc0a","poly":"dermato","fiche":"d302","front":"Prévention des carcinomes : populations à cibler en priorité ?","back":"**Phototypes clairs** et **grands exposés** (travail, loisirs) ; surtout **enfance et adolescence**.","prio":"P2","sec":"s21"},{"id":"fc-d302-e7aa18","poly":"dermato","fiche":"d302","front":"Écran solaire dans la prévention des carcinomes : bon usage ?","back":"**Ponctuel** pour éviter un coup de soleil ; **ne doit pas allonger** le temps d'exposition.","prio":"P1","sec":"s21"},{"id":"fc-d302-104c02","poly":"dermato","fiche":"d302","front":"Mélanome : recommandation du Collège sur les photoprotecteurs externes ?","back":"Usage **répété** sur les **zones découvertes**.","prio":"P2","sec":"s21"},{"id":"fc-d302-57a8e8","poly":"dermato","fiche":"d302","front":"Prévention des carcinomes : quelles lésions traiter ?","back":"Les **lésions précancéreuses** : kératoses actiniques, lésions induites par **HPV**.","prio":"P2","sec":"s21"},{"id":"fc-d302-9ea292","poly":"dermato","fiche":"d302","front":"Verrues : existe-t-il un traitement spécifique de l'infection à HPV ?","back":"**Non** : le but est de faire disparaître les **lésions visibles**.","prio":"P1","sec":"s22"},{"id":"fc-d302-73a642","poly":"dermato","fiche":"d302","front":"Verrues : évolution spontanée et principe du traitement ?","back":"Régression le plus souvent **spontanée** ; traitement guidé par symptômes et vécu, **sans acharnement**.","prio":"P1","sec":"s22"},{"id":"fc-d302-9a2679","poly":"dermato","fiche":"d302","front":"Verrues : risque de récidive et explication ?","back":"Environ **30 %** : persistance de l'**HPV** dans la peau saine.","prio":"P2","sec":"s22"},{"id":"fc-d302-2d74ca","poly":"dermato","fiche":"d302","front":"Verrues : kératolytique, molécule et modalités ?","back":"**Acide salicylique** (protéger la peau saine) ou collodion salicylé ; par ex. **chaque soir** au coucher, après **décapage** mécanique.","prio":"P2","sec":"s22"},{"id":"fc-d302-7cb04a","poly":"dermato","fiche":"d302","front":"Kératolytique : condition d'efficacité ?","back":"**Observance régulière** et traitement **assez prolongé** pour limiter l'échec.","prio":"P2","sec":"s22"},{"id":"fc-d302-8c7c6c","poly":"dermato","fiche":"d302","front":"Verrues : modalités et inconvénient de la cryothérapie ?","back":"**Azote liquide** direct ± décapage ; **douloureuse** (paume, péri- et sous-unguéal +++).","prio":"P2","sec":"s22"},{"id":"fc-d302-6da74c","poly":"dermato","fiche":"d302","front":"Verrues : laser CO₂, modalités et inconvénients ?","back":"Sous **anesthésie locale** ; **cicatrice** possible, récidive possible.","prio":"P3","sec":"s22"},{"id":"fc-d302-55dd7f","poly":"dermato","fiche":"d302","front":"Verrues de l'enfant : principe du traitement ?","back":"**Non agressif** ; éradication systématique pas toujours justifiée.","prio":"P2","sec":"s22"},{"id":"fc-d302-e07b4a","poly":"dermato","fiche":"d302","front":"Verrues : mesures pour limiter la diffusion ?","back":"**Vernis incolore** les jours de piscine/sport pieds nus ; **serviettes individuelles**.","prio":"P3","sec":"s22"},{"id":"fc-d302-2ea910","poly":"dermato","fiche":"d302","front":"Verrues : le traitement est-il consensuel ?","back":"**Non**.","prio":"P3","sec":"s22"},{"id":"fc-d302-59336b","poly":"dermato","fiche":"d302","front":"Exérèse diagnostique d'une lésion pigmentée : technique ?","back":"**Bistouri à lame**, incision **en dehors des limites visibles** de la lésion, suture selon l'anatomie.","prio":"P3","sec":"s23"},{"id":"fc-d302-0505f0","poly":"dermato","fiche":"d302","front":"Après exérèse d'une lésion pigmentée : pourquoi une consultation de contrôle ?","back":"Vérifier la **cicatrice** et **rendre le résultat** histologique.","prio":"P3","sec":"s23"},{"id":"fc-d302-1cbc37","poly":"dermato","fiche":"d302","front":"Lésion pigmentée suspecte : l'exérèse peut-elle être différée ?","back":"**Jamais** : seule l'**histologie** donne la certitude.","prio":"P2","sec":"s23"},{"id":"fc-d302-311c62","poly":"dermato","fiche":"d302","front":"Mélanome confirmé : faut-il une reprise chirurgicale ?","back":"**Oui, dans tous les cas** : reprise **élargie**.","prio":"P1","sec":"s23"},{"id":"fc-d302-3d5ce5","poly":"dermato","fiche":"d302","front":"Mélanome : profondeur de la reprise d'exérèse ?","back":"Toute l'épaisseur cutanée **jusqu'au fascia**, en le **respectant**.","prio":"P1","sec":"s24"},{"id":"fc-d302-7fe590","poly":"dermato","fiche":"d302","front":"Mélanome : qu'est-ce qui fixe la marge de reprise ?","back":"L'**indice de Breslow**.","prio":"P1","sec":"s24"},{"id":"fc-d302-6ed904","poly":"dermato","fiche":"d302","front":"Mélanome in situ : marge de reprise ?","back":"**0,5 cm**.","prio":"P1","sec":"s24"},{"id":"fc-d302-e755a0","poly":"dermato","fiche":"d302","front":"Mélanome Breslow 0,1-1 mm : marge de reprise ?","back":"**1 cm**.","prio":"P1","sec":"s24"},{"id":"fc-d302-8e08ce","poly":"dermato","fiche":"d302","front":"Mélanome Breslow 1,1-2 mm : marge de reprise ?","back":"**1 à 2 cm**.","prio":"P1","sec":"s24"},{"id":"fc-d302-6a5855","poly":"dermato","fiche":"d302","front":"Mélanome Breslow > 2 mm : marge de reprise ?","back":"**2 cm**.","prio":"P1","sec":"s24"},{"id":"fc-d302-24660b","poly":"dermato","fiche":"d302","front":"Mélanome de Dubreuilh intra-épidermique : modalités de reprise ?","back":"Marge de **1 cm** ou contrôle exhaustif des berges (**chirurgie de Mohs**).","prio":"P2","sec":"s24"},{"id":"fc-d302-116ec9","poly":"dermato","fiche":"d302","front":"Mélanome primitif isolé : radiothérapie ou chimiothérapie ?","back":"**Ni l'une ni l'autre**.","prio":"P1","sec":"s24"},{"id":"fc-d302-6e8745","poly":"dermato","fiche":"d302","front":"Mélanome stade I : bilan initial ?","back":"**Examen clinique complet** (peau, aires ganglionnaires) + **éducation à l'autodépistage**.","prio":"P2","sec":"s24"},{"id":"fc-d302-54a81a","poly":"dermato","fiche":"d302","front":"Mélanome stade II : bilan initial ?","back":"Examen clinique complet + **échographie locorégionale** de la zone de drainage.","prio":"P2","sec":"s24"},{"id":"fc-d302-4a07d2","poly":"dermato","fiche":"d302","front":"Mélanome : à quels stades scanner ou TEP-scan (tableau 20.7) ?","back":"Seulement aux stades **IIIB-IIIC** ; pas d'imagerie viscérale systématique pour les mélanomes peu épais.","prio":"P2","sec":"s24"},{"id":"fc-d302-f85f90","poly":"dermato","fiche":"d302","front":"Mélanome : à partir de quel stade l'échographie ganglionnaire (tableau 20.7) ?","back":"À partir du stade **IIA**.","prio":"P3","sec":"s24"},{"id":"fc-d302-6666c4","poly":"dermato","fiche":"d302","front":"Mélanome : indications de la technique du ganglion sentinelle ?","back":"Breslow **≥ 1 mm** et/ou **ulcération**, sans ganglion suspect à la clinique et à l'échographie.","prio":"P2","sec":"s24"},{"id":"fc-d302-cdb456","poly":"dermato","fiche":"d302","front":"Ganglion sentinelle micrométastatique : conséquences ?","back":"Stade **IIIA** ; traitement **adjuvant de 1 an** possible selon le profil mutationnel.","prio":"P2","sec":"s24"},{"id":"fc-d302-fdd82e","poly":"dermato","fiche":"d302","front":"Mélanome stade III opéré : sur quoi repose le choix de l'adjuvant ?","back":"Le **profil mutationnel** de la tumeur.","prio":"P2","sec":"s25"},{"id":"fc-d302-1092a7","poly":"dermato","fiche":"d302","front":"Mélanome stade III opéré : traitements adjuvants et bénéfice ?","back":"**Anti-PD1**, ou **anti-BRAF + anti-MEK** si mutation V600E/K ; augmentent la **survie sans récidive**.","prio":"P2","sec":"s25"},{"id":"fc-d302-6c035a","poly":"dermato","fiche":"d302","front":"Mélanome stade IV : sur quoi repose le choix du traitement ?","back":"La recherche de **mutation BRAF V600** dans la tumeur.","prio":"P2","sec":"s26"},{"id":"fc-d302-10f485","poly":"dermato","fiche":"d302","front":"Thérapie ciblée anti-BRAF : condition de prescription ?","back":"**Mutation BRAF V600E/K** démontrée sur la tumeur.","prio":"P2","sec":"s26"},{"id":"fc-d302-a50afe","poly":"dermato","fiche":"d302","front":"Mélanome : mesures de prévention primaire ?","back":"Informer sur les **UV naturels et artificiels** (cabines) ; éviter le fort soleil, vêtements, **écran réappliqué**.","prio":"P1","sec":"s27"},{"id":"fc-d302-a00c27","poly":"dermato","fiche":"d302","front":"Mélanome : à quel âge la prévention primaire est-elle essentielle ?","back":"Chez l'**enfant** (importante à tout âge).","prio":"P1","sec":"s27"},{"id":"fc-d302-1a05db","poly":"dermato","fiche":"d302","front":"Mélanome : principes de la prévention secondaire par le médecin ?","back":"Examiner **toute la peau**, repérer (ABCDE, vilain petit canard), adresser si doute, **préférer une exérèse à un doute**.","prio":"P1","sec":"s27"},{"id":"fc-d302-4cc9da","poly":"dermato","fiche":"d302","front":"Sujets à très haut risque de mélanome : suivi ?","back":"Suivi dermatologique spécifique : **photographies**, **vidéodermoscopie** (antécédent de mélanome, syndrome des nævus atypiques).","prio":"P2","sec":"s27"},{"id":"fc-d302-4bd7ed","poly":"dermato","fiche":"d302","front":"Dépistage du mélanome : cibles prioritaires ?","back":"Sujets **âgés**, **isolés**, **hommes** peu enclins à s'examiner (tumeurs épaisses).","prio":"P2","sec":"s27"},{"id":"fc-d302-fa538f","poly":"dermato","fiche":"d302","front":"Mélanome : clé de l'amélioration du pronostic ?","back":"**Diagnostic précoce** d'une tumeur **peu épaisse**, exérèse avec **marges correctes**.","prio":"P1","sec":"s27"},{"id":"fc-d302-da11b3","poly":"dermato","fiche":"d302","front":"Sujet à risque de mélanome : rythme et durée de la surveillance ?","back":"**Au moins 1 fois/an**, **à vie**, couplée à l'**autosurveillance**.","prio":"P1","sec":"s27"},{"id":"fc-d302-ab849a","poly":"dermato","fiche":"d302","front":"Nævus : faut-il les enlever tous ou surveiller tout le monde ?","back":"**Non**, aucun intérêt pour prévenir le mélanome.","prio":"P1","sec":"s28"},{"id":"fc-d302-57222d","poly":"dermato","fiche":"d302","front":"Nævus : qui doit bénéficier d'une surveillance régulière ?","back":"Nævus **nombreux** (notamment > 5 mm) ; sujets à risque de mélanome ou de cancer épithélial (**phototype clair**, **antécédent** perso/familial de mélanome).","prio":"P2","sec":"s28"},{"id":"fc-d302-6ded11","poly":"dermato","fiche":"d302","front":"Autosurveillance cutanée : principes à enseigner ?","back":"**Rythme et rituel** (même lieu, conditions, ordre), repérer l'**inhabituel**, **consulter sans tarder**, éviter l'anxiété.","prio":"P2","sec":"s28"},{"id":"fc-d302-7f5dd9","poly":"dermato","fiche":"d302","front":"Exérèse esthétique ou fonctionnelle d'un nævus : indications et précautions ?","back":"Nævus **disgracieux**, traumatisé ou irrité ; à discuter (**cicatrice**) ; délai de réflexion **incompressible**.","prio":"P2","sec":"s28"},{"id":"fc-d302-c2773b","poly":"dermato","fiche":"d302","front":"Nævus excisé : l'examen histologique est-il obligatoire ?","back":"**Oui**, toujours (objectif de l'exérèse, **document opposable**).","prio":"P2","sec":"s28"},{"id":"fc-d302-834eae","poly":"dermato","fiche":"d302","front":"Exérèse d'un nævus : peut-elle provoquer sa transformation ?","back":"**Non** : idée reçue à combattre.","prio":"P2","sec":"s28"},{"id":"fc-d302-98be41","poly":"dermato","fiche":"d302","front":"Nævus congénital : qui décide de l'exérèse et comment ?","back":"**Au cas par cas**, quelle que soit la taille ; affaire de **spécialiste**.","prio":"P2","sec":"s29"},{"id":"fc-d302-054e9f","poly":"dermato","fiche":"d302","front":"Grand nævus congénital : à quel âge l'exérèse est-elle plus facile ?","back":"Dans les **premiers mois de vie**.","prio":"P3","sec":"s29"},{"id":"fc-d302-65cf0a","poly":"dermato","fiche":"d302","front":"Nævus congénitaux : pourquoi la surveillance est-elle parfois difficile ?","back":"**Surface irrégulière**.","prio":"P3","sec":"s29"},{"id":"fc-d302-8c2c42","poly":"dermato","fiche":"d302","front":"Nævus congénitaux géants : part en nombre absolu des mélanomes ?","back":"**Très faible** (lésions rares).","prio":"P3","sec":"s29"},{"id":"fc-d319-b2804d","poly":"dermato","fiche":"d319","front":"Lymphome cutané : quelle est sa définition ?","back":"Prolifération **maligne de lymphocytes** née dans la **peau**, sans **atteinte extracutanée** lors du diagnostic.","prio":"P1","sec":"s1"},{"id":"fc-d319-c2884e","poly":"dermato","fiche":"d319","front":"Lymphome cutané primitif : de quoi faut-il le distinguer ?","back":"D'un **lymphome systémique** qui atteint la peau **secondairement**.","prio":"P1","sec":"s1"},{"id":"fc-d319-697857","poly":"dermato","fiche":"d319","front":"Lymphomes cutanés primitifs : quel pronostic par rapport aux lymphomes ganglionnaires de même histologie ?","back":"Pronostic **différent**, **le plus souvent meilleur**.","prio":"P1","sec":"s1"},{"id":"fc-d319-887e74","poly":"dermato","fiche":"d319","front":"Lymphomes cutanés : quel rang de fréquence parmi les lymphomes ?","back":"**Troisième**, après les lymphomes **ganglionnaires** et **digestifs**.","prio":"P2","sec":"s1"},{"id":"fc-d319-848b29","poly":"dermato","fiche":"d319","front":"Lymphomes cutanés : quelle classification utilise-t-on ?","back":"La classification **OMS 2016** (critères cliniques, anatomopathologiques, immunohistochimiques).","prio":"P2","sec":"s1"},{"id":"fc-d319-16b1c9","poly":"dermato","fiche":"d319","front":"Classification OMS des lymphomes cutanés : quels deux grands groupes ?","back":"Lymphomes cutanés **T** et **B**, avec de nombreuses entités.","prio":"P2","sec":"s1"},{"id":"fc-d319-d0f0a1","poly":"dermato","fiche":"d319","front":"Quel est le groupe de lymphomes cutanés le plus fréquent ?","back":"Les lymphomes cutanés **T épidermotropes** : **mycosis fongoïde** et **syndrome de Sézary**.","prio":"P1","sec":"s1"},{"id":"fc-d319-954ffb","poly":"dermato","fiche":"d319","front":"Lymphome : quels signes d'atteinte du système lymphoïde peuvent le faire suspecter ?","back":"**Adénopathie**, **splénomégalie**, **hépatomégalie**.","prio":"P1","sec":"s2"},{"id":"fc-d319-1c0ca9","poly":"dermato","fiche":"d319","front":"Lymphome : quelles atteintes extraganglionnaires possibles ?","back":"**ORL**, **digestive**, **cutanée**…","prio":"P2","sec":"s2"},{"id":"fc-d319-5f2042","poly":"dermato","fiche":"d319","front":"Lymphomes : quels éléments recouvre l'objectif « situations d'urgence » ?","back":"Caractéristiques des **adénopathies**, **signes B**, **prurit**, **douleurs à l'alcool** (Hodgkin), **signes compressifs**.","prio":"P2","sec":"s2"},{"id":"fc-d319-5525fb","poly":"dermato","fiche":"d319","front":"Lymphome de Hodgkin : quels deux symptômes propres cite le tableau d'objectifs (situations d'urgence) ?","back":"Le **prurit** et les **douleurs à l'ingestion d'alcool**.","prio":"P1","sec":"s2"},{"id":"fc-d319-57bba7","poly":"dermato","fiche":"d319","front":"Lymphomes : comment s'appellent les signes généraux ?","back":"Les « **signes B** ».","prio":"P2","sec":"s2"},{"id":"fc-d319-686ffa","poly":"dermato","fiche":"d319","front":"Lymphomes : quels sites l'atteinte du système lymphoïde peut-elle toucher ?","back":"**Ganglion**, **rate** ou **tissu lymphoïde** de divers organes **non lymphoïdes** (notion de **clonalité**).","prio":"P3","sec":"s2"},{"id":"fc-d319-1c68ca","poly":"dermato","fiche":"d319","front":"Lymphomes : quelles grandes distinctions de classification ?","back":"**Hodgkin** versus **non hodgkiniens** ; phénotype **B** ou **T**.","prio":"P3","sec":"s2"},{"id":"fc-d319-52dce6","poly":"dermato","fiche":"d319","front":"Lymphomes non hodgkiniens : quels virus sont des facteurs étiologiques ?","back":"**EBV**, **VIH**, **HTLV1**, **HCV**, **HHV8**.","prio":"P2","sec":"s2"},{"id":"fc-d319-503057","poly":"dermato","fiche":"d319","front":"Lymphomes non hodgkiniens : quels facteurs immunitaires ?","back":"Déficits immunitaires **congénitaux** ou **acquis** (transplantation, immunosuppresseurs, maladies immunologiques).","prio":"P3","sec":"s2"},{"id":"fc-d319-a07eaa","poly":"dermato","fiche":"d319","front":"Lymphomes non hodgkiniens : quelle bactérie est un facteur étiologique ?","back":"**Helicobacter pylori**.","prio":"P2","sec":"s2"},{"id":"fc-d319-2d983b","poly":"dermato","fiche":"d319","front":"Lymphomes non hodgkiniens : quels toxiques sont en cause ?","back":"**Pesticides** ++ (déclaration) et **solvants**.","prio":"P3","sec":"s2"},{"id":"fc-d319-9bf7cf","poly":"dermato","fiche":"d319","front":"Quel est le lymphome cutané le plus fréquent ?","back":"Le **mycosis fongoïde**.","prio":"P1","sec":"s3"},{"id":"fc-d319-aa6ed6","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : de quel type de lymphome s'agit-il ?","back":"Lymphome cutané **T épidermotrope** d'évolution **lente**.","prio":"P1","sec":"s3"},{"id":"fc-d319-6fd84c","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : les manifestations cutanées s'accompagnent-elles le plus souvent d'autres signes ?","back":"**Non** : elles sont le plus souvent **isolées**.","prio":"P3","sec":"s3"},{"id":"fc-d319-2dc298","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quelles lésions initiales ?","back":"**Macules érythémateuses et squameuses**, **non infiltrées**, de plusieurs centimètres (érythème « pré-mycosique »).","prio":"P1","sec":"s3"},{"id":"fc-d319-fea6c8","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : sur quelles zones prédominent les lésions ?","back":"**Zones photoprotégées** : seins, tronc, racine des membres, fesses.","prio":"P1","sec":"s3"},{"id":"fc-d319-b8847c","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : comment évoluent les lésions ?","back":"Elles **s'infiltrent** et deviennent des **plaques**.","prio":"P1","sec":"s3"},{"id":"fc-d319-5d4f4a","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quels caractères des lésions sont évocateurs ?","back":"**Fixité**, **délimitation nette**, **aspect figuré** et **prurit**.","prio":"P1","sec":"s3"},{"id":"fc-d319-955e0e","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : avec quelle dermatose peut-il être confondu ?","back":"Le **psoriasis** (aspect parfois proche).","prio":"P1","sec":"s8"},{"id":"fc-d319-1fe000","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quel examen fonde le diagnostic ?","back":"La **biopsie cutanée**, souvent associée à un **génotypage du TCR**.","prio":"P1","sec":"s4"},{"id":"fc-d319-7863a5","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : que faire si la première biopsie n'est pas spécifique ?","back":"**Répéter** les biopsies : l'histologie peut être non spécifique au début.","prio":"P2","sec":"s4"},{"id":"fc-d319-6f3da3","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quel aspect histologique caractéristique ?","back":"Lymphocytes à **noyau circonvoluté** du derme qui montent dans l'épiderme en **thèques** (**épidermotropisme**).","prio":"P2","sec":"s4"},{"id":"fc-d319-246198","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quel immunomarquage des lymphocytes tumoraux ?","back":"**CD3⁺, CD4⁺, CD8⁻**.","prio":"P2","sec":"s4"},{"id":"fc-d319-4aa03e","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde à un stade tumoral : quelle modification cytologique ?","back":"**Transformation cytologique** : grands lymphocytes à **noyau cérébriforme**.","prio":"P3","sec":"s4"},{"id":"fc-d319-3d7c1b","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quel résultat habituel du génotypage du TCR ?","back":"Un **clone T dans la peau** et **pas de clone T circulant**.","prio":"P2","sec":"s4"},{"id":"fc-d319-619c24","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quelle fréquence par rapport au mycosis fongoïde ?","back":"**Beaucoup plus rare**.","prio":"P2","sec":"s5"},{"id":"fc-d319-36255e","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quelle triade le définit ?","back":"**Érythrodermie** + **prurit sévère** + **cellules de Sézary** sanguines **> 1000/mm³**.","prio":"P1","sec":"s5"},{"id":"fc-d319-b48ee7","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quel rapport CD4/CD8 sanguin ?","back":"**> 10**.","prio":"P1","sec":"s5"},{"id":"fc-d319-a2508d","poly":"dermato","fiche":"d319","front":"Cellules de Sézary : de quelles cellules s'agit-il ?","back":"**Lymphocytes T** à **noyau irrégulier**.","prio":"P2","sec":"s5"},{"id":"fc-d319-f208e3","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quels signes sont souvent associés ?","back":"**Kératodermie palmo-plantaire** avec anomalies unguéales, **alopécie**, **ectropion**, **adénopathies**.","prio":"P2","sec":"s5"},{"id":"fc-d319-8d3d56","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : où trouve-t-on aussi les cellules de Sézary ?","back":"Dans la **peau** et les **ganglions**.","prio":"P3","sec":"s5"},{"id":"fc-d319-022de9","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quel immunomarquage ?","back":"Voisin du MF : **CD3⁺, CD4⁺, CD8⁻**.","prio":"P3","sec":"s5"},{"id":"fc-d319-b813fa","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : que montre le génotypage du TCR ?","back":"Le **même clone T** dans le **sang** et la **peau**, de façon constante.","prio":"P2","sec":"s5"},{"id":"fc-d319-ee8f1b","poly":"dermato","fiche":"d319","front":"Syndrome de Sézary : quel pronostic par rapport au mycosis fongoïde ?","back":"**Plus défavorable**.","prio":"P2","sec":"s5"},{"id":"fc-d319-515dfc","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelle conduite immédiate ?","back":"**Hospitalisation urgente** en service spécialisé.","prio":"P1","sec":"s5"},{"id":"fc-d319-6117b8","poly":"dermato","fiche":"d319","front":"Érythrodermie de l'adulte : quel lymphome fait partie des causes principales ?","back":"Le **syndrome de Sézary**.","prio":"P1","sec":"s5"},{"id":"fc-d319-485e7e","poly":"dermato","fiche":"d319","front":"Érythrodermie : son aspect clinique préjuge-t-il de sa cause ?","back":"**Non**.","prio":"P2","sec":"s5"},{"id":"fc-d319-c9a21c","poly":"dermato","fiche":"d319","front":"Autres lymphomes T cutanés : quelles caractéristiques ?","back":"**Plus rares**, **hétérogènes** sur le plan clinique et pronostique.","prio":"P2","sec":"s6"},{"id":"fc-d319-4fee41","poly":"dermato","fiche":"d319","front":"Autres lymphomes T cutanés : quelles lésions le plus souvent ?","back":"**Papulo-nodules** ou **tumeurs**, uniques ou multiples.","prio":"P2","sec":"s6"},{"id":"fc-d319-420b46","poly":"dermato","fiche":"d319","front":"Lymphomes B cutanés : quelle fréquence par rapport aux lymphomes T cutanés ?","back":"**Plus rares**.","prio":"P2","sec":"s6"},{"id":"fc-d319-7fefb4","poly":"dermato","fiche":"d319","front":"Lymphomes B cutanés : quelles lésions les révèlent ?","back":"**Papulo-nodules**, **tumeurs** ou **plaques infiltrées**.","prio":"P2","sec":"s6"},{"id":"fc-d319-840b0b","poly":"dermato","fiche":"d319","front":"Lymphomes B cutanés : quel examen porte le diagnostic ?","back":"L'**examen anatomopathologique**.","prio":"P2","sec":"s6"},{"id":"fc-d319-5ba8c4","poly":"dermato","fiche":"d319","front":"Devant quelles lésions évoquer un lymphome cutané ?","back":"**Plaques infiltrées prurigineuses chroniques**, **érythrodermie**, **un ou plusieurs nodules**.","prio":"P1","sec":"s7"},{"id":"fc-d319-893563","poly":"dermato","fiche":"d319","front":"Lymphome cutané : quel examen pose le diagnostic et distingue T et B ?","back":"La **biopsie cutanée**.","prio":"P1","sec":"s7"},{"id":"fc-d319-301463","poly":"dermato","fiche":"d319","front":"Lymphome cutané : quel examen ajouter souvent à la biopsie ?","back":"Un **génotypage** (**BCR ou TCR**) dans la **peau** et le **sang**.","prio":"P1","sec":"s7"},{"id":"fc-d319-1cf701","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : par qui le diagnostic doit-il être validé ?","back":"Par une **équipe hospitalière**.","prio":"P1","sec":"s7"},{"id":"fc-d319-e246b7","poly":"dermato","fiche":"d319","front":"Lymphome : la cytologie suffit-elle au diagnostic ?","back":"**Non** : elle **oriente** ; la **biopsie du tissu tumoral** est **indispensable**.","prio":"P2","sec":"s8"},{"id":"fc-d319-12c294","poly":"dermato","fiche":"d319","front":"Lymphome : comment réaliser la biopsie ?","back":"Biopsie **chirurgicale** ou **sous imagerie**, sur le tissu tumoral ganglionnaire ou extraganglionnaire.","prio":"P3","sec":"s7"},{"id":"fc-d319-2ac54b","poly":"dermato","fiche":"d319","front":"Lymphome : quel circuit pour le prélèvement ?","back":"**Paraffine**, **congélation**, **tumorothèque** (INCa) ; **circuit d'expertise validé**.","prio":"P3","sec":"s7"},{"id":"fc-d319-e1663b","poly":"dermato","fiche":"d319","front":"Lymphome de Hodgkin et LBDGC : quelle imagerie pour l'extension ostéomédullaire ?","back":"La **TEP au FDG**.","prio":"P2","sec":"s7"},{"id":"fc-d319-5b0ea4","poly":"dermato","fiche":"d319","front":"TEP au FDG dans le LH et le LBDGC : quel examen permet-elle d'éviter ?","back":"La **biopsie ostéomédullaire** systématique, dans la grande majorité des cas.","prio":"P3","sec":"s7"},{"id":"fc-d319-4d1953","poly":"dermato","fiche":"d319","front":"Lymphomes : quel autre rôle de l'imagerie en dehors du bilan initial ?","back":"L'**évaluation de la réponse thérapeutique**.","prio":"P3","sec":"s7"},{"id":"fc-d319-f79a42","poly":"dermato","fiche":"d319","front":"Lymphome cutané primitif : quelle vérification est indispensable pour retenir ce terme ?","back":"L'**absence d'atteinte extracutanée** au diagnostic.","prio":"P1","sec":"s9"},{"id":"fc-d319-b6bf58","poly":"dermato","fiche":"d319","front":"Lymphome cutané primitif : pourquoi tenir compte de ce caractère dans la prise en charge ?","back":"Évolution **particulière** et pronostic **le plus souvent meilleur** que la forme ganglionnaire.","prio":"P2","sec":"s9"},{"id":"fc-d319-49dc96","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde : quelle organisation du suivi ?","back":"Prise en charge **partagée** en **coopération ville-hôpital**, après validation hospitalière.","prio":"P1","sec":"s10"},{"id":"fc-d319-79d59c","poly":"dermato","fiche":"d319","front":"Mycosis fongoïde tumoral : où le traiter ?","back":"En **milieu hospitalier**.","prio":"P1","sec":"s10"},{"id":"fc-d319-452f96","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelles mesures à l'hôpital ?","back":"**Biologie de gravité**, correction **hydro-électrolytique**, prise en charge des défaillances, **recherche de la cause**.","prio":"P2","sec":"s11"},{"id":"fc-d319-c4fbfd","poly":"dermato","fiche":"d319","front":"Érythrodermie : pourquoi réchauffer le patient ?","back":"Limiter les **pertes caloriques**, l'**hypercatabolisme** et la **dénutrition**.","prio":"P2","sec":"s11"},{"id":"fc-d319-5ea7ab","poly":"dermato","fiche":"d319","front":"Érythrodermie : quels éléments d'interrogatoire orientent la cause ?","back":"Ancienneté, antécédents, **médicaments**, **topiques**, contexte **infectieux** contemporain.","prio":"P2","sec":"s11"},{"id":"fc-d319-d2fb3f","poly":"dermato","fiche":"d319","front":"Érythrodermie avec suspicion de lymphome cutané : que faire de la biopsie ?","back":"La **répéter**.","prio":"P2","sec":"s11"},{"id":"fc-d319-d2e2a3","poly":"dermato","fiche":"d319","front":"Érythrodermie grave : quel traitement symptomatique ?","back":"Un **dermocorticoïde de niveau 1** (très fort), avec amélioration symptomatique rapide.","prio":"P2","sec":"s11"},{"id":"fc-d319-e654aa","poly":"dermato","fiche":"d319","front":"Érythrodermie : le dermocorticoïde suffit-il ?","back":"**Non** : traitement symptomatique ; il faut aussi **rechercher et traiter la cause**.","prio":"P2","sec":"s11"},{"id":"fc-d319-ad286f","poly":"dermato","fiche":"d319","front":"Érythrodermie : quels mécanismes expliquent les pertes hydro-électrolytiques ?","back":"**Vasodilatation**, **desquamation**, **suintement**, **œdème**, **fièvre**.","prio":"P3","sec":"s11"},{"id":"fc-d319-f15b23","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelles décompensations les pertes hydro-électrolytiques peuvent-elles entraîner ?","back":"Insuffisance **cardiaque**, **respiratoire** ou **rénale**.","prio":"P2","sec":"s11"},{"id":"fc-d319-bf1167","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelles infections compliquent l'évolution ?","back":"Le plus souvent **cutanées** (staphylocoque, herpès, varicelle-zona), ou **générales** (pneumopathie, septicémie).","prio":"P2","sec":"s11"},{"id":"fc-d319-5612ef","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelle mortalité ?","back":"Jusqu'à **20 %**, liée aux complications, notamment **infectieuses**.","prio":"P2","sec":"s11"},{"id":"fc-d319-80b47f","poly":"dermato","fiche":"d319","front":"Érythrodermie : quelles complications du décubitus prévenir ?","back":"**Dénutrition**, **cachexie**, **escarres**.","prio":"P3","sec":"s11"},{"id":"fc-d319-2f6965","poly":"dermato","fiche":"d319","front":"Érythrodermie fébrile : quels prélèvements selon le contexte ?","back":"**Bactériologiques**, voire **parasitologiques**.","prio":"P3","sec":"s11"},{"id":"fc-d330-ffb6b4","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : pour quelles actions les utilise-t-on surtout ?","back":"Leurs actions **anti-inflammatoire** et **antiproliférative**.","prio":"P1","sec":"s1"},{"id":"fc-d330-d8ea2e","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelles sont leurs trois propriétés ?","back":"**Anti-inflammatoire** (+++) et **vasoconstrictrice** ; **antiproliférative** ; **immunosuppressive locale**.","prio":"P1","sec":"s1"},{"id":"fc-d330-418ab6","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : sur quelles cellules s'exerce l'action antiproliférative ?","back":"**Kératinocytes**, **mélanocytes**, **cellules de Langerhans** et **fibroblastes**.","prio":"P2","sec":"s1"},{"id":"fc-d330-5024b7","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : d'où vient l'atrophie cutanée ?","back":"De l'action sur les **fibroblastes** (synthèse de **collagène** inhibée).","prio":"P1","sec":"s1"},{"id":"fc-d330-58d047","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : sur quels deux critères choisit-on un DC pour une indication donnée ?","back":"Son **niveau d'activité** et son **excipient** (galénique).","prio":"P1","sec":"s1"},{"id":"fc-d330-ed7764","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : combien de niveaux d'activité et lesquels ?","back":"**4** : classe **IV très forte**, **III forte**, **II modérée**, **I faible**.","prio":"P1","sec":"s1"},{"id":"fc-d330-ba21dd","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelle classe correspond à l'activité très forte ?","back":"La **classe IV**.","prio":"P1","sec":"s1"},{"id":"fc-d330-5a3473","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : qu'est-ce qui détermine le choix de la molécule (DCI) ?","back":"Le **niveau d'activité** (classe).","prio":"P1","sec":"s1"},{"id":"fc-d330-4b0a7c","poly":"dermato","fiche":"d330","front":"Corticophobie : le Collège la juge-t-il justifiée ?","back":"**Non** : respecter les règles de bon usage évite les effets secondaires dans l'**immense majorité** des cas.","prio":"P1","sec":"s1"},{"id":"fc-d330-4f77c0","poly":"dermato","fiche":"d330","front":"Test de McKenzie : sur quoi repose-t-il et à quoi sert-il ?","back":"Sur l'effet **vasoconstricteur** des DC ; évalue leur efficacité et établit une **échelle de puissance**.","prio":"P2","sec":"s1"},{"id":"fc-d330-f7a071","poly":"dermato","fiche":"d330","front":"Test de McKenzie : que mesure-t-on et à quoi est-ce corrélé ?","back":"Le **blanchiment** de la peau, **corrélé** à l'activité **anti-inflammatoire**.","prio":"P3","sec":"s1"},{"id":"fc-d330-ae63c0","poly":"dermato","fiche":"d330","front":"Classification des DC : sur quelles deux bases repose-t-elle ?","back":"Le **test de McKenzie** et les **essais cliniques contrôlés**.","prio":"P3","sec":"s1"},{"id":"fc-d330-a84500","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelles indications générales ?","back":"Nombreuses **dermatoses inflammatoires**, en **poussée** et en **entretien**.","prio":"P1","sec":"s2"},{"id":"fc-d330-fcb7af","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quels eczémas en sont des indications ?","back":"**Dermatite atopique**, **eczéma de contact**, **dysidrose**.","prio":"P2","sec":"s2"},{"id":"fc-d330-bae101","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : hors eczémas, cicatrices, vitiligo et pelade, quelles indications ?","back":"**Psoriasis**, **lichen**, **prurigo et lichénification**, **pemphigoïde bulleuse**, **lupus érythémateux chronique**.","prio":"P1","sec":"s2"},{"id":"fc-d330-bb0e28","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelles autres indications (cicatrices, pigmentation, cheveux) ?","back":"**Cicatrices hypertrophiques et chéloïdes**, **vitiligo**, **pelade**.","prio":"P2","sec":"s2"},{"id":"fc-d330-ce2ae7","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelles contre-indications ?","back":"Dermatoses **infectieuses**, lésions **ulcérées**, et au visage **acné** et **rosacée**.","prio":"P1","sec":"s2"},{"id":"fc-d330-b9467f","poly":"dermato","fiche":"d330","front":"Acné et rosacée : que peuvent provoquer les DC en plus d'être contre-indiqués ?","back":"Ils peuvent **induire** une acné, une rosacée ou une **dermatite péri-orale**.","prio":"P1","sec":"s2"},{"id":"fc-d330-7e5237","poly":"dermato","fiche":"d330","front":"DC sur une infection cutanée : quels risques ?","back":"**Transformer l'éruption** (dermatophytie, gale) ou **aggraver** l'infection (herpès).","prio":"P1","sec":"s2"},{"id":"fc-d330-f91dc6","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : de quoi dépend la pénétration cutanée ?","back":"De la **molécule** (polarité, taille, liposolubilité), du **produit**, de la **peau** et de l'**application**.","prio":"P3","sec":"s3"},{"id":"fc-d330-3ad58d","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : par quelles voies pénètrent-ils ?","back":"À travers l'**épiderme** (entre et à travers les kératinocytes) et par les **follicules**.","prio":"P3","sec":"s3"},{"id":"fc-d330-874b45","poly":"dermato","fiche":"d330","front":"Crème de DC : quelle place par rapport à la pommade ?","back":"**Plus agréable**, prescrite **de préférence** ; effet occlusif **moindre** que la pommade (émulsion « huile dans l'eau » ou « eau dans l'huile »).","prio":"P2","sec":"s3"},{"id":"fc-d330-328cd2","poly":"dermato","fiche":"d330","front":"Pommade : pour quel type de lésions ?","back":"Seulement des lésions **sèches, épaisses, squameuses et kératosiques** (excipient gras, occlusif, pénètre plus).","prio":"P2","sec":"s3"},{"id":"fc-d330-b795a5","poly":"dermato","fiche":"d330","front":"Gel ou lotion : pour quelles localisations ?","back":"**Plis** et **zones pileuses**.","prio":"P2","sec":"s3"},{"id":"fc-d330-4c7614","poly":"dermato","fiche":"d330","front":"Gel : pénètre-t-il plus ou moins qu'une crème ?","back":"**Moins** qu'une crème.","prio":"P3","sec":"s3"},{"id":"fc-d330-d7fe12","poly":"dermato","fiche":"d330","front":"Cuir chevelu : quelles galéniques de DC ?","back":"**Shampooing** ou **mousse**.","prio":"P2","sec":"s3"},{"id":"fc-d330-a20d4f","poly":"dermato","fiche":"d330","front":"Hyperkératose épaisse : que peut-on associer au DC et pourquoi ?","back":"De l'**acide salicylique** : réduit l'hyperkératose et **facilite la pénétration** du DC.","prio":"P2","sec":"s3"},{"id":"fc-d330-c958ee","poly":"dermato","fiche":"d330","front":"Occlusion : quel effet sur la pénétration du DC ?","back":"Elle la **renforce** (hydrate la couche cornée, prolonge le contact) ; à préciser sur l'ordonnance.","prio":"P2","sec":"s3"},{"id":"fc-d330-36a929","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : à quels âges l'absorption est-elle accrue ?","back":"**Nouveau-né prématuré** et, à un moindre degré, **sujet âgé** (couche cornée plus fine).","prio":"P2","sec":"s3"},{"id":"fc-d330-0fd023","poly":"dermato","fiche":"d330","front":"Absorption de l'hydrocortisone : quel coefficient aux paupières et au scrotum ?","back":"**42** (avant-bras = 1).","prio":"P2","sec":"s3"},{"id":"fc-d330-5ae5d6","poly":"dermato","fiche":"d330","front":"Absorption de l'hydrocortisone : quel coefficient au visage et au cuir chevelu ?","back":"Visage **6** ; cuir chevelu **3,5** (avant-bras = 1).","prio":"P3","sec":"s3"},{"id":"fc-d330-e07356","poly":"dermato","fiche":"d330","front":"Absorption de l'hydrocortisone : quel coefficient aux paumes et aux plantes ?","back":"Paumes **0,83** ; plantes **0,14** (avant-bras = 1).","prio":"P3","sec":"s3"},{"id":"fc-d330-6cb1c9","poly":"dermato","fiche":"d330","front":"Barrière cutanée altérée : quel effet sur la pénétration du DC ?","back":"Le DC **pénètre davantage** qu'à travers une peau normale.","prio":"P2","sec":"s3"},{"id":"fc-d330-900bfb","poly":"dermato","fiche":"d330","front":"DC sur les paupières au long cours : quels risques ?","back":"**Glaucome** et **cataracte**.","prio":"P1","sec":"s3"},{"id":"fc-d330-eb05e8","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : pourquoi les effets systémiques sont-ils plus fréquents chez l'enfant ?","back":"**Surface corporelle grande** par rapport au **poids**.","prio":"P1","sec":"s3"},{"id":"fc-d330-619352","poly":"dermato","fiche":"d330","front":"Ordonnance de DC : quels 6 éléments préciser ?","back":"**Niveau d'activité**, **galénique**, **rythme**, **quantité**, **occlusion ou non**, **durée**.","prio":"P1","sec":"s4"},{"id":"fc-d330-514b9d","poly":"dermato","fiche":"d330","front":"Classe de DC : selon quels critères l'adapter ?","back":"Le **diagnostic**, la **topographie** des lésions et l'**âge**.","prio":"P1","sec":"s4"},{"id":"fc-d330-3f8ba3","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quel rythme d'application en général ?","back":"**Une seule application par jour**.","prio":"P1","sec":"s4"},{"id":"fc-d330-370d34","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : pourquoi une application par jour suffit-elle dans la très grande majorité des cas ?","back":"Grâce à l'**effet réservoir**.","prio":"P2","sec":"s4"},{"id":"fc-d330-7a4db2","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : comment exprimer la quantité sur l'ordonnance ?","back":"En **nombre de tubes** ou **unités phalangettes**, selon la **surface** atteinte.","prio":"P1","sec":"s4"},{"id":"fc-d330-3e7df8","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quelle quantité pour toute la surface corporelle d'un adulte ?","back":"Environ **30 g par jour** (homme de corpulence moyenne).","prio":"P1","sec":"s4"},{"id":"fc-d330-05fba4","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : pourquoi préciser la quantité ?","back":"Améliore le rapport **efficacité/tolérance** et l'**observance**.","prio":"P2","sec":"s4"},{"id":"fc-d330-57f3e2","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : de quoi dépend la quantité nécessaire ?","back":"De la **surface à traiter** et de la **durée prévue**.","prio":"P2","sec":"s4"},{"id":"fc-d330-3b9926","poly":"dermato","fiche":"d330","front":"Suivi sous DC : quel indicateur évaluer en consultation ?","back":"Le **nombre de tubes** utilisés, pour corriger un **excès** ou une **insuffisance** de quantité.","prio":"P1","sec":"s4"},{"id":"fc-d330-469a64","poly":"dermato","fiche":"d330","front":"Suivi sous DC : quand est-il particulièrement nécessaire ?","back":"Dermatose **chronique**, surtout chez l'**enfant**.","prio":"P2","sec":"s4"},{"id":"fc-d330-db986f","poly":"dermato","fiche":"d330","front":"Surveillance sous DC : selon quels éléments l'orienter ?","back":"Traitement à **court ou long terme**, **effet thérapeutique attendu**, **non-amélioration**, apparition d'**effets secondaires**.","prio":"P2","sec":"s4"},{"id":"fc-d330-dea6ea","poly":"dermato","fiche":"d330","front":"Ordonnance « appliquer la crème » sans quantité ni durée : est-ce suffisant ?","back":"**Non**, incomplète : la **quantité** est un élément **fondamental**.","prio":"P2","sec":"s4"},{"id":"fc-d330-fb559b","poly":"dermato","fiche":"d330","front":"Psoriasis : à quelles molécules peut-on associer le DC ?","back":"**Acide salicylique** ou **analogue de la vitamine D3**.","prio":"P2","sec":"s5"},{"id":"fc-d330-77f980","poly":"dermato","fiche":"d330","front":"Dermatose aiguë guérie : comment arrêter le DC ?","back":"Arrêt **brutal** possible.","prio":"P1","sec":"s6"},{"id":"fc-d330-d68d3f","poly":"dermato","fiche":"d330","front":"Dermatose chronique : comment arrêter le DC et pourquoi ?","back":"Parfois **progressivement** (espacement des applications) pour éviter un **rebond**.","prio":"P1","sec":"s6"},{"id":"fc-d330-296186","poly":"dermato","fiche":"d330","front":"Dermatite atopique guérie : quel traitement préventif par DC ?","back":"**2 applications par semaine** sur la peau guérie, pour limiter les rechutes.","prio":"P1","sec":"s6"},{"id":"fc-d330-bf22c6","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : risque d'effets indésirables si bien prescrits ?","back":"**Quasi inexistant**.","prio":"P1","sec":"s7"},{"id":"fc-d330-139155","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : dans quelles conditions apparaissent les effets secondaires ?","back":"Traitement **prolongé**, DC **fort/très fort**, **grande surface**, **peau altérée**, **occlusion**.","prio":"P1","sec":"s7"},{"id":"fc-d330-6a8a71","poly":"dermato","fiche":"d330","front":"Allergie de contact à un DC : fréquence ?","back":"**Exceptionnelle**.","prio":"P2","sec":"s7"},{"id":"fc-d330-e1e309","poly":"dermato","fiche":"d330","front":"Atrophie épidermique sous DC : quel aspect ?","back":"Épiderme **fin et fragile**, peau « **en papier à cigarette** ».","prio":"P1","sec":"s7"},{"id":"fc-d330-93f4bd","poly":"dermato","fiche":"d330","front":"Atrophie dermique sous DC : quelles manifestations ?","back":"Retard de **cicatrisation**, pseudo-cicatrices, **télangiectasies**, **purpura**, **vergetures**, réseau veineux visible.","prio":"P1","sec":"s7"},{"id":"fc-d330-77d716","poly":"dermato","fiche":"d330","front":"DC au visage : quelles dermatites rosacéiformes ?","back":"**Acné** induite, **rosacée** induite ou aggravée, **dermatite péri-orale**.","prio":"P1","sec":"s7"},{"id":"fc-d330-584f2f","poly":"dermato","fiche":"d330","front":"Dermatite péri-orale sous DC : à quoi équivaut-elle ?","back":"À une **rosacée induite**.","prio":"P3","sec":"s7"},{"id":"fc-d330-65fe84","poly":"dermato","fiche":"d330","front":"DC et infections : quels effets indésirables infectieux ?","back":"Éruption **transformée** (dermatophytie rosacéiforme ou granulomateuse, gale), infection **aggravée** (herpès), **surinfection** (peu fréquente).","prio":"P2","sec":"s7"},{"id":"fc-d330-697aa2","poly":"dermato","fiche":"d330","front":"Dermocorticoïdes : quels effets hormonaux ?","back":"**Hypertrichose** sur la zone d'application ; effets systémiques (**Cushing** induit) **très rares**.","prio":"P2","sec":"s7"},{"id":"fc-d330-81b089","poly":"dermato","fiche":"d330","front":"Dépigmentation volontaire par DC : quelles conséquences ?","back":"Effets indésirables **bien plus fréquents** : **infections**, **vergetures**, **dyschromies**, retard de cicatrisation.","prio":"P2","sec":"s7"},{"id":"fc-d330-468a53","poly":"dermato","fiche":"d330","front":"Quantité de DC accrue : quel risque ?","back":"Expose aux **effets secondaires**.","prio":"P3","sec":"s7"},{"id":"fc-d330-b6c28f","poly":"dermato","fiche":"d330","front":"Suivi sous DC : excès ou insuffisance le plus souvent ?","back":"Le plus souvent une **insuffisance** de quantité.","prio":"P1","sec":"s7"},{"id":"fc-d330-ed8e14","poly":"dermato","fiche":"d330","front":"DC inefficace : quelle cause fréquente évoquer ?","back":"La **corticophobie** : application **insuffisante** → échec par **insuffisance de dose**.","prio":"P1","sec":"s8"},{"id":"fc-d330-f374f3","poly":"dermato","fiche":"d330","front":"Dermatoses chroniques sous DC : que dire de l'observance ?","back":"Le plus souvent **insuffisante**.","prio":"P2","sec":"s8"},{"id":"fc-d330-5075c1","poly":"dermato","fiche":"d330","front":"DC inefficace : que reprendre sur l'ordonnance ?","back":"**Classe** adaptée (diagnostic, topographie, âge), **galénique**, **rythme**, **quantité** chiffrée, **durée**.","prio":"P2","sec":"s8"},{"id":"fc-d330-00fa7f","poly":"dermato","fiche":"d330","front":"Moyen mnémotechnique : les 6 choix de l'ordonnance de DC dans l'ordre ?","back":"**N**iveau, **G**alénique, **R**ythme, **Q**uantité, **O**cclusion, **D**urée.","prio":"P2","sec":"s9"},{"id":"fc-d350-457491","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge aiguë : quels sont les trois éléments du tableau typique ?","back":"**Placard érythémateux** assez bien limité avec **œdème**, en général **unilatéral** · **fièvre ≥ 38 °C** · installation **rapide** (heures à jours).","prio":"P1","sec":"s1"},{"id":"fc-d350-0136ff","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge aiguë fébrile : cause de loin la plus fréquente ?","back":"L'**érysipèle** (dermohypodermite infectieuse aiguë **streptococcique**).","prio":"P1","sec":"s1"},{"id":"fc-d350-e5186f","poly":"dermato","fiche":"d350","front":"Dermohypodermites nécrosantes : citer les formes ?","back":"**Fasciite nécrosante**, **gangrène gazeuse** : **urgences vitales**.","prio":"P1","sec":"s1"},{"id":"fc-d350-2ba94b","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quelles questions guident l'arbre décisionnel ?","back":"**Aiguë ou subaiguë** ? **Fébrile ou non** ? **Autres lésions élémentaires** ?","prio":"P1","sec":"s1"},{"id":"fc-d350-1f07ad","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quels signes distinguent ce tableau ?","back":"**Signes locaux de gravité** et **signes généraux marqués** ; urgence vitale **médico-chirurgicale**.","prio":"P1","sec":"s1"},{"id":"fc-d350-62be3e","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge après morsure de chat ou de chien : quel diagnostic ?","back":"**Pasteurellose d'inoculation**.","prio":"P2","sec":"s1"},{"id":"fc-d350-690f39","poly":"dermato","fiche":"d350","front":"DH inflammatoire sur insuffisance veineuse : quelles caractéristiques ?","back":"Poussées **douloureuses**, le plus souvent **bilatérales**, **peu ou pas fébriles**.","prio":"P2","sec":"s1"},{"id":"fc-d350-55e274","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : évolution et porte d'entrée habituelle ?","back":"Évolution **subaiguë et torpide** ; porte d'entrée souvent un **mal perforant plantaire**.","prio":"P2","sec":"s1"},{"id":"fc-d350-8a74be","poly":"dermato","fiche":"d350","front":"Eczéma aigu de jambe : quels signes orientent ?","back":"**Prurit** (+++), **vésicules** sur placard à **bords émiettés**.","prio":"P2","sec":"s1"},{"id":"fc-d350-f21a97","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : que préciser sur le début et l'extension ?","back":"**Date**, mode de début (brutal ou insidieux), extension **rapide ou lente**.","prio":"P2","sec":"s2"},{"id":"fc-d350-9076db","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quels signes associés rechercher à l'interrogatoire ?","back":"**Frissons**, **fièvre**, douleur locale majorée **jambe pendante** ou à la palpation.","prio":"P2","sec":"s2"},{"id":"fc-d350-2fd7a0","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : citer les facteurs déclenchants à rechercher ?","back":"**Intertrigo inter-orteils** · traumatisme avec effraction · thrombophlébite · grattage · pathologie articulaire gênant le retour veineux · **morsure**, piqûre.","prio":"P1","sec":"s2"},{"id":"fc-d350-54b339","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quels éléments du terrain rechercher ?","back":"ATCD chirurgicaux du membre · **diabète** · **artériopathie** · **obésité** · **épisodes antérieurs** · œdème chronique veineux ou lymphatique.","prio":"P1","sec":"s2"},{"id":"fc-d350-a97f68","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quels traitements déjà pris rechercher ?","back":"**Antibiotique** général, topiques, **AINS** ou **corticoïdes** locaux ou généraux.","prio":"P1","sec":"s2"},{"id":"fc-d350-b569b6","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : aspect des lésions à l'examen ?","back":"Érythème **rouge vif**, **œdème** souvent tendu, douloureux à la palpation ; parfois vésicules et/ou bulles ; limites nettes ou floues.","prio":"P2","sec":"s2"},{"id":"fc-d350-ed74c6","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge du sujet âgé : quelle lésion liée à l'œdème rapide ?","back":"**Décollements superficiels étendus**.","prio":"P3","sec":"s2"},{"id":"fc-d350-7e7156","poly":"dermato","fiche":"d350","front":"Fasciite nécrosante : citer les signes locaux de gravité ?","back":"**Nécrose** (zones pâles, plaques noirâtres, livédoïdes) · **hypoesthésie** ou **douleurs spontanées intenses** · **crépitation** · **extension malgré antibiotique**.","prio":"P1","sec":"s2"},{"id":"fc-d350-f22521","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : citer les portes d'entrée à rechercher ?","back":"**Intertrigo inter-orteils** · **ulcère** de jambe · plaie traumatique · excoriations · grattage · **piqûre** d'insecte.","prio":"P1","sec":"s2"},{"id":"fc-d350-bfa367","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : que rechercher sur le plan circulatoire ?","back":"Signes d'**insuffisance veineuse chronique** (œdème, varices, lipodermatosclérose) ; **pouls pédieux et tibiaux postérieurs**.","prio":"P2","sec":"s2"},{"id":"fc-d350-844bd6","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : que rechercher sur le drainage lymphatique ?","back":"**Lymphangite**, **adénopathie** inflammatoire **inguinale** homolatérale.","prio":"P2","sec":"s2"},{"id":"fc-d350-160880","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : que rechercher à l'examen général ?","back":"Fièvre, altération de l'état général, signes de **sepsis sévère**, voire **choc septique**.","prio":"P1","sec":"s2"},{"id":"fc-d350-667e95","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge aiguë fébrile avec dermohypodermite : causes à évoquer ?","back":"**Érysipèle** · autres dermohypodermites infectieuses · **fasciite nécrosante**.","prio":"P1","sec":"s3"},{"id":"fc-d350-e44362","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge subaiguë fébrile : causes à évoquer ?","back":"**Dermohypodermites infectieuses**.","prio":"P2","sec":"s3"},{"id":"fc-d350-f3e6e9","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge subaiguë non fébrile : causes à évoquer ?","back":"**Insuffisance veineuse** ; **pied diabétique**.","prio":"P1","sec":"s3"},{"id":"fc-d350-fc036f","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge non fébrile avec d'autres lésions élémentaires : cause à évoquer ?","back":"**Eczéma**.","prio":"P1","sec":"s3"},{"id":"fc-d350-4c93c4","poly":"dermato","fiche":"d350","front":"Érysipèle : définition ?","back":"Dermohypodermite **aiguë bactérienne** à **streptocoque β-hémolytique A** (plus rarement B, C ou G).","prio":"P1","sec":"s4"},{"id":"fc-d350-4fe310","poly":"dermato","fiche":"d350","front":"Érysipèle : quelle localisation prédominante ?","back":"La **jambe**, dans **plus de 80 %** des cas.","prio":"P1","sec":"s4"},{"id":"fc-d350-0259da","poly":"dermato","fiche":"d350","front":"Érysipèle : quel terrain ?","back":"Adulte de **plus de 40 ans**, âge moyen vers **60 ans**.","prio":"P2","sec":"s4"},{"id":"fc-d350-23385f","poly":"dermato","fiche":"d350","front":"Érysipèle : quel facteur favorise l'atteinte des membres inférieurs ?","back":"L'**insuffisance veineuse et/ou lymphatique**.","prio":"P2","sec":"s4"},{"id":"fc-d350-1249de","poly":"dermato","fiche":"d350","front":"Érysipèle : citer les facteurs favorisants ?","back":"**Ulcère** de jambe · **intertrigo inter-orteils** · **plaie** · **lymphœdème** · **ATCD d'érysipèle** · **obésité**.","prio":"P1","sec":"s4"},{"id":"fc-d350-6db9ed","poly":"dermato","fiche":"d350","front":"Érysipèle : la recherche d'une porte d'entrée est-elle facultative ?","back":"**Non** : **systématique et indispensable**.","prio":"P1","sec":"s4"},{"id":"fc-d350-8a5d36","poly":"dermato","fiche":"d350","front":"Érysipèle : mode de début ?","back":"**Brutal** : fièvre élevée (**39 à 40 °C**) avec **frissons**, précédant souvent de quelques heures le placard.","prio":"P1","sec":"s4"},{"id":"fc-d350-72cb8e","poly":"dermato","fiche":"d350","front":"Érysipèle : aspect du placard ?","back":"**Érythémateux**, **œdémateux**, **circonscrit**, **douloureux** à la palpation ; **unilatéral**.","prio":"P1","sec":"s4"},{"id":"fc-d350-082d5a","poly":"dermato","fiche":"d350","front":"Érysipèle : où observe-t-on un bourrelet périphérique marqué ?","back":"**Uniquement au visage** (pas à la jambe).","prio":"P1","sec":"s4"},{"id":"fc-d350-44a355","poly":"dermato","fiche":"d350","front":"Érysipèle : quelles lésions peuvent s'ajouter sur le placard ?","back":"**Décollements bulleux** superficiels (œdème du derme) ou **purpura**.","prio":"P2","sec":"s4"},{"id":"fc-d350-caf0e7","poly":"dermato","fiche":"d350","front":"Érysipèle : signes lymphatiques associés ?","back":"**Adénopathies** inflammatoires homolatérales fréquentes ; parfois **lymphangite**.","prio":"P2","sec":"s4"},{"id":"fc-d350-9676fd","poly":"dermato","fiche":"d350","front":"Érysipèle : dans quelle proportion la porte d'entrée est-elle visible ?","back":"**Deux tiers** des cas.","prio":"P1","sec":"s4"},{"id":"fc-d350-7932be","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : où la prendre en charge ?","back":"Prise en charge **médico-chirurgicale très rapide** en **unité de soins intensifs**.","prio":"P1","sec":"s5"},{"id":"fc-d350-e15331","poly":"dermato","fiche":"d350","front":"Hypodermite infectieuse : citer les signes locaux de sévérité ?","back":"Douleur spontanée **intense** · œdème majeur · **bulles hémorragiques** · **nécrose** · **hypoesthésie** · **livedo** · **crépitation**.","prio":"P1","sec":"s5"},{"id":"fc-d350-5fcff3","poly":"dermato","fiche":"d350","front":"Hypodermite infectieuse : citer les signes généraux de sévérité ?","back":"Fièvre élevée avec **confusion** · désorientation · **tachypnée** · **tachycardie** · **oligurie** · **hypotension** · pâleur.","prio":"P1","sec":"s5"},{"id":"fc-d350-e5a615","poly":"dermato","fiche":"d350","front":"Hypodermite infectieuse : quels autres facteurs de sévérité ?","back":"**Comorbidité** (diabète, obésité) ; **précarité sociale**.","prio":"P2","sec":"s5"},{"id":"fc-d350-dcc2db","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quand apparaissent les signes locaux de gravité ?","back":"**D'emblée** : nécrose, anesthésie locale, **écoulements fétides**, crépitation.","prio":"P2","sec":"s5"},{"id":"fc-d350-3b291f","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quel examen apprécie l'extension en profondeur ?","back":"L'**IRM**.","prio":"P1","sec":"s5"},{"id":"fc-d350-a3b5f4","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quels germes ?","back":"**Streptocoque**, **staphylocoque doré**, **bacilles à Gram négatif**, **anaérobies**, souvent **associés**.","prio":"P1","sec":"s5"},{"id":"fc-d350-75e044","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quel médicament rechercher et interrompre ?","back":"Les **AINS**.","prio":"P1","sec":"s5"},{"id":"fc-d350-da764a","poly":"dermato","fiche":"d350","front":"Fasciite nécrosante : quel phénomène est habituel au niveau des fascias ?","back":"La **compression des fascias**.","prio":"P3","sec":"s5"},{"id":"fc-d350-6d77fc","poly":"dermato","fiche":"d350","front":"Érysipèle typique sans comorbidité : quels examens complémentaires ?","back":"**Aucun**.","prio":"P1","sec":"s6"},{"id":"fc-d350-a167f4","poly":"dermato","fiche":"d350","front":"Dermohypodermite atypique : quel intérêt des examens complémentaires ?","back":"**Limité** (peu sensibles et spécifiques) ; l'examen clinique reste **primordial**.","prio":"P2","sec":"s6"},{"id":"fc-d350-de46ed","poly":"dermato","fiche":"d350","front":"Dermohypodermite bactérienne : faut-il attendre les examens pour traiter ?","back":"**Non**, le traitement ne doit pas être retardé.","prio":"P1","sec":"s6"},{"id":"fc-d350-7f7b7c","poly":"dermato","fiche":"d350","front":"Érysipèle : que montrent NFS et CRP si elles sont faites ?","back":"**Hyperleucocytose à PNN** ; syndrome inflammatoire important (**CRP souvent > 100 mg/L**).","prio":"P2","sec":"s6"},{"id":"fc-d350-49bd89","poly":"dermato","fiche":"d350","front":"Érysipèle : rentabilité des hémocultures ?","back":"**Faible**.","prio":"P2","sec":"s6"},{"id":"fc-d350-3b62e2","poly":"dermato","fiche":"d350","front":"Dermohypodermite : quand faire un prélèvement de la porte d'entrée ?","back":"Dans les **formes graves**, pour adapter l'antibiothérapie si besoin.","prio":"P2","sec":"s6"},{"id":"fc-d350-e05495","poly":"dermato","fiche":"d350","front":"Prélèvement d'ulcère de jambe : quel piège d'interprétation ?","back":"Un **bacille à Gram négatif** colonisant l'ulcère n'est **pas forcément responsable**.","prio":"P2","sec":"s6"},{"id":"fc-d350-c3e313","poly":"dermato","fiche":"d350","front":"Suspicion de thrombose veineuse sur grosse jambe rouge : quel examen ?","back":"**Écho-Doppler veineux** des membres.","prio":"P1","sec":"s6"},{"id":"fc-d350-ab3b29","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : pourquoi ne pas doser les D-dimères pour éliminer une TVP ?","back":"**Sans valeur discriminative** : élevés dans la dermohypodermite infectieuse.","prio":"P1","sec":"s6"},{"id":"fc-d350-a2bce6","poly":"dermato","fiche":"d350","front":"Dermohypodermite avec signes de gravité : quel bilan biologique ?","back":"**Enzymes musculaires**, ionogramme, **créatininémie**, **gaz du sang** (acidose métabolique ?), **coagulation** (CIVD ?).","prio":"P2","sec":"s6"},{"id":"fc-d350-01a2fb","poly":"dermato","fiche":"d350","front":"Suspicion de dermohypodermite nécrosante : quelle imagerie et quand ?","back":"**Sans délai** : **échographie** cutanée et des parties molles, **IRM**.","prio":"P1","sec":"s6"},{"id":"fc-d350-d77593","poly":"dermato","fiche":"d350","front":"DH inflammatoire sur insuffisance veineuse : signes d'insuffisance veineuse chronique associés ?","back":"**Télangiectasies**, **varices**, **dermite ocre**, **atrophie blanche**, **ulcère**, **lipodermatosclérose**.","prio":"P3","sec":"s7"},{"id":"fc-d350-d3083f","poly":"dermato","fiche":"d350","front":"DH inflammatoire sur insuffisance veineuse : vers quoi évolue-t-elle ?","back":"**Lipodermatosclérose** du tiers inférieur de jambe ; facteur de risque de **DH bactérienne vraie**.","prio":"P2","sec":"s7"},{"id":"fc-d350-bb1072","poly":"dermato","fiche":"d350","front":"Eczéma de jambe : quel est le contexte le plus fréquent ?","back":"**Eczéma de contact** autour d'un **ulcère de jambe**.","prio":"P2","sec":"s7"},{"id":"fc-d350-e2d627","poly":"dermato","fiche":"d350","front":"Eczéma de jambe sans allergie de contact : quel nom ?","back":"**Dermite de stase** (sur insuffisance veineuse chronique).","prio":"P2","sec":"s7"},{"id":"fc-d350-d5d3d9","poly":"dermato","fiche":"d350","front":"Eczéma de contact de jambe : quel examen pour l'allergène ?","back":"**Tests allergologiques**.","prio":"P2","sec":"s7"},{"id":"fc-d350-ad764e","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : en quoi diffère-t-elle de l'érysipèle ?","back":"Inflammation **plus profonde**, **moins bien limitée** ; douleur **modérée** ; fièvre **parfois absente**.","prio":"P2","sec":"s7"},{"id":"fc-d350-8e065f","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : quels germes principaux ?","back":"**Staphylococcus aureus**, **Pseudomonas aeruginosa**, **anaérobies**.","prio":"P2","sec":"s7"},{"id":"fc-d350-7741f4","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : que rechercher par principe ?","back":"Une **ostéite** sous-jacente et une **décompensation du diabète**.","prio":"P2","sec":"s7"},{"id":"fc-d350-562506","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : quel pronostic thérapeutique ?","back":"Évolution **moins favorable**, mauvaise réponse aux anti-infectieux ; **geste chirurgical** souvent nécessaire.","prio":"P2","sec":"s7"},{"id":"fc-d350-7a626d","poly":"dermato","fiche":"d350","front":"Pasteurellose d'inoculation : quel germe ?","back":"**Pasteurella multocida**.","prio":"P2","sec":"s7"},{"id":"fc-d350-3cf679","poly":"dermato","fiche":"d350","front":"Rouget du porc (érysipéloïde) : quel contexte et quel germe ?","back":"Blessure par un **os d'origine animale** (bouchers) ; **Erysipelothrix rhusiopathiae**.","prio":"P3","sec":"s7"},{"id":"fc-d350-29c248","poly":"dermato","fiche":"d350","front":"Rouget du porc : quel aspect ?","back":"Plaie **érythémateuse**, de préférence à la **main**, pourtour œdématié, **extrêmement douloureuse**.","prio":"P3","sec":"s7"},{"id":"fc-d350-e67f3d","poly":"dermato","fiche":"d350","front":"Syndrome des loges simulant un érysipèle : quel contexte et quelle fréquence ?","back":"Notamment **exercice physique violent** ; diagnostic **exceptionnel**.","prio":"P3","sec":"s7"},{"id":"fc-d350-a59218","poly":"dermato","fiche":"d350","front":"Lymphœdème chronique : pourquoi peut-il être difficile à distinguer d'un érysipèle ?","back":"**Poussées inflammatoires** possibles ; si l'atteinte est **unilatérale**, distinction difficile.","prio":"P2","sec":"s8"},{"id":"fc-d350-ecfec3","poly":"dermato","fiche":"d350","front":"Borréliose vs érysipèle : éléments distinctifs ?","back":"Plus **circonscrite**, **moins inflammatoire**, **sans fièvre** ; piqûre de tique pas toujours retrouvée.","prio":"P2","sec":"s8"},{"id":"fc-d350-34c33f","poly":"dermato","fiche":"d350","front":"Lymphangite : quel aspect ?","back":"**Trajet rouge inflammatoire** (parfois placard linéaire), souvent avec **adénopathie inguinale** homolatérale ; peut accompagner un érysipèle.","prio":"P2","sec":"s8"},{"id":"fc-d350-92b8c4","poly":"dermato","fiche":"d350","front":"Panniculite : quel aspect et quelles localisations ?","back":"**Nodules et plaques** inflammatoires de l'**hypoderme** : plutôt cuisses, abdomen, bras ; signes systémiques possibles.","prio":"P3","sec":"s8"},{"id":"fc-d350-dca70c","poly":"dermato","fiche":"d350","front":"Nodules des membres inférieurs : quel diagnostic différentiel de l'érysipèle discuter ?","back":"L'**érythème noueux**.","prio":"P3","sec":"s8"},{"id":"fc-d350-9230a1","poly":"dermato","fiche":"d350","front":"TVP isolée : donne-t-elle une grosse jambe rouge ?","back":"**Non**, mais elle peut **rarement** s'associer à un érysipèle : **écho-Doppler** en cas de doute.","prio":"P2","sec":"s8"},{"id":"fc-d350-6eb61c","poly":"dermato","fiche":"d350","front":"Nécrose d'ischémie artérielle aiguë vs DH nécrosante : élément distinctif ?","back":"En général **ni érythème ni œdème** dans l'ischémie artérielle.","prio":"P2","sec":"s8"},{"id":"fc-d350-8c6aeb","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quelles mesures communes à toutes les causes ?","back":"**Repos** jambe **surélevée** · **antalgiques sans AINS** · héparine préventive si FdR thromboembolique · **vaccination antitétanique**.","prio":"P1","sec":"s9"},{"id":"fc-d350-5f9099","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : jusqu'à quand le repos jambe surélevée ?","back":"Jusqu'à **régression de l'inflammation** locale (moins d'œdème, moins de douleur).","prio":"P2","sec":"s9"},{"id":"fc-d350-0b17d9","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quand prescrire une anticoagulation préventive ?","back":"**Uniquement** s'il existe des **facteurs de risque thromboembolique** (héparine calcique ou HBPM).","prio":"P1","sec":"s9"},{"id":"fc-d350-cabe98","poly":"dermato","fiche":"d350","front":"Grosse jambe rouge : quelle classe d'antalgiques proscrire ?","back":"Les **AINS**.","prio":"P1","sec":"s9"},{"id":"fc-d350-b8564a","poly":"dermato","fiche":"d350","front":"Érysipèle : quand hospitaliser ?","back":"Si un **traitement parentéral** ou une **surveillance rapprochée** est nécessaire.","prio":"P1","sec":"s9"},{"id":"fc-d350-90a8b2","poly":"dermato","fiche":"d350","front":"Érysipèle : citer les situations justifiant l'hospitalisation ?","back":"**Doute diagnostique** · **gravité** locale ou générale · risque de complication locale · **comorbidité** · contexte **social** · pas d'amélioration à **48 h** ou extension.","prio":"P1","sec":"s9"},{"id":"fc-d350-e939f1","poly":"dermato","fiche":"d350","front":"Érysipèle : quelles comorbidités justifient l'hospitalisation ?","back":"**Obésité morbide**, insuffisance **hépatique**, **rénale** sévère ou **cardiaque**, **immunodépression**, **diabète déséquilibré**.","prio":"P2","sec":"s9"},{"id":"fc-d350-641821","poly":"dermato","fiche":"d350","front":"Érysipèle : quelle classe d'antibiotiques en 1re intention et quelle molécule de référence ?","back":"**β-lactamines** ; **amoxicilline**.","prio":"P1","sec":"s10"},{"id":"fc-d350-eb441c","poly":"dermato","fiche":"d350","front":"Érysipèle sans gravité : quelle posologie et durée d'amoxicilline ?","back":"**3 à 4,5 g/j per os** pendant **7 jours**.","prio":"P1","sec":"s10"},{"id":"fc-d350-771aa6","poly":"dermato","fiche":"d350","front":"Érysipèle sans signe de gravité : où le traiter ?","back":"**À domicile**, par voie **orale** (évite les contraintes et effets indésirables de l'IV).","prio":"P1","sec":"s10"},{"id":"fc-d350-f21240","poly":"dermato","fiche":"d350","front":"Érysipèle et allergie à la pénicilline : quelles alternatives ?","back":"**Pristinamycine** ou **clindamycine**.","prio":"P1","sec":"s10"},{"id":"fc-d350-c87e25","poly":"dermato","fiche":"d350","front":"Érysipèle : posologie de la pristinamycine ?","back":"**3 g/j** en **3 prises**.","prio":"P2","sec":"s10"},{"id":"fc-d350-37d9ef","poly":"dermato","fiche":"d350","front":"Érysipèle : pourquoi marquer les bords du placard dès le début ?","back":"Pour **suivre l'évolution** : l'extension est fréquente dans les **24 premières heures**.","prio":"P1","sec":"s10"},{"id":"fc-d350-3b6431","poly":"dermato","fiche":"d350","front":"Érysipèle hospitalisé : quel traitement d'attaque ?","back":"**Amoxicilline IV**.","prio":"P1","sec":"s11"},{"id":"fc-d350-9ae010","poly":"dermato","fiche":"d350","front":"Érysipèle hospitalisé : posologie de l'amoxicilline IV ?","back":"**50 mg/kg/j**.","prio":"P2","sec":"s11"},{"id":"fc-d350-f6927a","poly":"dermato","fiche":"d350","front":"Érysipèle hospitalisé : modalités du relais oral ?","back":"Amoxicilline **per os**, jusqu'à **disparition des signes locaux** ; durée totale **7 jours** (IV + oral).","prio":"P1","sec":"s11"},{"id":"fc-d350-3f2b33","poly":"dermato","fiche":"d350","front":"Érysipèle : jusqu'à quand poursuivre la voie IV ?","back":"Jusqu'à l'**apyrexie** (pas jusqu'à la disparition des signes locaux).","prio":"P2","sec":"s11"},{"id":"fc-d350-edf735","poly":"dermato","fiche":"d350","front":"Érysipèle : quelle complication la plus fréquente et à quelle fréquence ?","back":"La **récidive** : **20 à 30 %**, liée à la persistance des facteurs de risque.","prio":"P1","sec":"s12"},{"id":"fc-d350-52fae8","poly":"dermato","fiche":"d350","front":"Érysipèle : prévention primaire par la porte d'entrée ?","back":"**Traiter la porte d'entrée**, en particulier diagnostiquer et traiter un **intertrigo inter-orteils**.","prio":"P1","sec":"s12"},{"id":"fc-d350-f97522","poly":"dermato","fiche":"d350","front":"Érysipèle : mesures pour améliorer la circulation ?","back":"**Bandes de contention** · **drainage lymphatique manuel** · **perte de poids**.","prio":"P1","sec":"s12"},{"id":"fc-d350-0eb3bc","poly":"dermato","fiche":"d350","front":"Érysipèle : mesures d'hygiène cutanée préventives ?","back":"**Bien sécher entre les orteils** · désinfecter les plaies · **surveiller les pieds** du diabétique.","prio":"P2","sec":"s12"},{"id":"fc-d350-ed2b49","poly":"dermato","fiche":"d350","front":"Érysipèle : quand indiquer une antibiothérapie préventive ?","back":"En cas de **récidives multiples** (molécules et doses non précisées).","prio":"P1","sec":"s12"},{"id":"fc-d350-3433e0","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quel geste chirurgical ?","back":"**Excision de toutes les zones nécrosées**.","prio":"P1","sec":"s13"},{"id":"fc-d350-e3be07","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quelle antibiothérapie ?","back":"**Parentérale**, **associée**, adaptée ensuite à l'**antibiogramme**.","prio":"P1","sec":"s13"},{"id":"fc-d350-8a6095","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quelles molécules citées ?","back":"**Clindamycine** + **pénicilline à spectre élargi** (tazocilline) ou **céphalosporine** ± **aminoside** ; **métronidazole** si anaérobies.","prio":"P2","sec":"s13"},{"id":"fc-d350-46e9c2","poly":"dermato","fiche":"d350","front":"Dermohypodermite nécrosante : quelles corrections métaboliques ?","back":"**Hypovolémie**, troubles **glycémiques** et **électrolytiques**.","prio":"P2","sec":"s13"},{"id":"fc-d350-1a3a1a","poly":"dermato","fiche":"d350","front":"Autres DH bactériennes (dont pied diabétique) : quelle antibiothérapie probabiliste ?","back":"**Mal codifiée** ; initialement **antistreptococcique ET antistaphylococcique**, adaptée aux prélèvements.","prio":"P1","sec":"s14"},{"id":"fc-d350-8f6d9c","poly":"dermato","fiche":"d350","front":"DH sur pied diabétique : quelles mesures associées ?","back":"**Équilibrer la glycémie** (+++) · **immobiliser le pied** (+++) · geste chirurgical éventuel sur une **collection**.","prio":"P1","sec":"s14"},{"id":"fc-d350-9c905f","poly":"dermato","fiche":"d350","front":"Morsure animale avec dermohypodermite : antibiotique de référence ?","back":"**Amoxicilline + acide clavulanique**, per os ou IV.","prio":"P2","sec":"s15"},{"id":"fc-d350-cf6d80","poly":"dermato","fiche":"d350","front":"Pasteurellose : dose d'amoxicilline citée ?","back":"**3 g/j** (associée à l'acide clavulanique), per os ou IV.","prio":"P3","sec":"s15"},{"id":"fc-d350-2b4503","poly":"dermato","fiche":"d350","front":"Morsure animale et allergie aux β-lactamines : quelles alternatives ?","back":"**Macrolide** ou **pristinamycine**.","prio":"P2","sec":"s15"},{"id":"fc-d350-dee797","poly":"dermato","fiche":"d350","front":"Poussée inflammatoire sur insuffisance veineuse : quel traitement ?","back":"**Contention élastique** (indispensable, même mal tolérée) + **repos** + **antalgiques**.","prio":"P2","sec":"s16"},{"id":"fc-d350-150a63","poly":"dermato","fiche":"d350","front":"Eczéma de jambe : quel traitement ?","back":"**Éviction de l'allergène** suspecté + **dermocorticoïdes**.","prio":"P2","sec":"s17"},{"id":"fc-d350-a0496c","poly":"dermato","fiche":"d350","front":"Érysipèle sous antibiotique : délai d'apyrexie ?","back":"**48 à 72 h** (signe d'efficacité).","prio":"P1","sec":"s18"},{"id":"fc-d350-787edc","poly":"dermato","fiche":"d350","front":"Érysipèle sous antibiotique : délai d'amélioration des signes locaux ?","back":"Plus lente : **1 semaine**.","prio":"P2","sec":"s18"},{"id":"fc-d350-cccd6e","poly":"dermato","fiche":"d350","front":"Érysipèle sous antibiotique : délai d'évolution favorable ?","back":"**8 à 10 jours** dans la plupart des cas.","prio":"P2","sec":"s18"},{"id":"fc-d350-bb3717","poly":"dermato","fiche":"d350","front":"Érysipèle : fréquence et nature des complications locales ?","back":"**5 à 10 %** (surtout si traitement retardé) : **abcès** à inciser et drainer.","prio":"P1","sec":"s18"},{"id":"fc-d350-734f5a","poly":"dermato","fiche":"d350","front":"Érysipèle : complications systémiques ?","back":"Très rares (**< 5 %**) : **septicémie** à streptocoque, **glomérulonéphrite aiguë post-streptococcique**.","prio":"P2","sec":"s18"},{"id":"fc-d350-9d6b0b","poly":"dermato","fiche":"d350","front":"Érysipèle : comment interpréter une extension selon le moment ?","back":"Dans les **24 premières heures** de traitement : fréquente (bords marqués) ; pas d'amélioration à **48 h** ou extension : **hospitaliser** ; malgré antibiotique bien conduit : **fasciite nécrosante** ?","prio":"P1","sec":"s18"},{"id":"fc-p110-900e64","poly":"pneumo","fiche":"p110","front":"Sommeil normal de l'adulte : quelle durée totale par jour ?","back":"**6 à 10 heures** par jour.","prio":"P1","sec":"s1"},{"id":"fc-p110-032161","poly":"pneumo","fiche":"p110","front":"Sommeil : quels sont les 3 stades ?","back":"Sommeil **léger** · sommeil **profond** · sommeil **paradoxal**.","prio":"P1","sec":"s1"},{"id":"fc-p110-906c90","poly":"pneumo","fiche":"p110","front":"Cycle de sommeil : quelle durée habituelle ?","back":"**90 à 110 minutes** en général.","prio":"P1","sec":"s1"},{"id":"fc-p110-345787","poly":"pneumo","fiche":"p110","front":"Sommeil normal : combien de cycles par nuit ?","back":"**4 à 6 cycles**.","prio":"P1","sec":"s1"},{"id":"fc-p110-b47c52","poly":"pneumo","fiche":"p110","front":"Sommeil paradoxal : quelle part du temps total de sommeil ?","back":"**20 à 25 %**.","prio":"P1","sec":"s1"},{"id":"fc-p110-900c6d","poly":"pneumo","fiche":"p110","front":"Sommeil lent profond : quelle durée normale ?","back":"**90 à 120 min**.","prio":"P2","sec":"s1"},{"id":"fc-p110-d4cc8a","poly":"pneumo","fiche":"p110","front":"Durée de sommeil de la naissance à l'adolescence : quelle évolution ?","back":"De **16 h/j à 9 h/j**.","prio":"P2","sec":"s1"},{"id":"fc-p110-f11eab","poly":"pneumo","fiche":"p110","front":"Cycles de sommeil chez l'enfant : quelle particularité ?","back":"Ils se succèdent **plus rapidement** (et l'enfant dort plus longtemps que l'adulte).","prio":"P3","sec":"s1"},{"id":"fc-p110-ab46b2","poly":"pneumo","fiche":"p110","front":"Pathologie du sommeil : de quelles 3 façons perturbe-t-elle l'architecture du sommeil ?","back":"**↓ sommeil lent profond** · **↓ sommeil paradoxal** · sommeil **fragmenté**.","prio":"P2","sec":"s1"},{"id":"fc-p110-98478a","poly":"pneumo","fiche":"p110","front":"Pourquoi le sommeil est-il une période fragile pour la respiration ?","back":"Le cortex perd le contrôle respiratoire : **ventilation ↓**, perte de tonus des muscles respiratoires (accessoires surtout) et des **dilatateurs du pharynx**.","prio":"P2","sec":"s1"},{"id":"fc-p110-d3df7c","poly":"pneumo","fiche":"p110","front":"Quels sont les 3 grands troubles respiratoires du sommeil ?","back":"**SAHOS** (obstructif) · **SAHCS** (central) · **hypoventilation alvéolaire nocturne**.","prio":"P1","sec":"s2"},{"id":"fc-p110-5ca553","poly":"pneumo","fiche":"p110","front":"SAHOS : quel mécanisme le définit ?","back":"**Occlusions répétées des voies aériennes supérieures** (VAS) pendant le sommeil.","prio":"P1","sec":"s2"},{"id":"fc-p110-15dfad","poly":"pneumo","fiche":"p110","front":"SAHCS : quel mécanisme ?","back":"Baisses ou abolitions répétées de la **commande ventilatoire centrale**.","prio":"P2","sec":"s2"},{"id":"fc-p110-4b8ac4","poly":"pneumo","fiche":"p110","front":"Hypoventilation alvéolaire nocturne : quelles conséquences gazométriques ?","back":"**Hausse du CO₂** et **hypoxémie nocturne** ; peut évoluer vers une hypoventilation alvéolaire diurne.","prio":"P2","sec":"s2"},{"id":"fc-p110-20134c","poly":"pneumo","fiche":"p110","front":"Hypoventilation alvéolaire nocturne : quelles maladies complique-t-elle ?","back":"Maladies respiratoires sévères **obstructives** (BPCO) ou **restrictives** (obésité, maladies neuromusculaires).","prio":"P2","sec":"s2"},{"id":"fc-p110-14ffe1","poly":"pneumo","fiche":"p110","front":"SAHCS : quelle fréquence parmi les SAS ?","back":"Beaucoup moins fréquent : environ **10 %** des SAS.","prio":"P2","sec":"s2"},{"id":"fc-p110-e91088","poly":"pneumo","fiche":"p110","front":"SAHCS : quel bilan étiologique ?","back":"**Cardiologique**, **neurologique** et **médicamenteux**, puis traitement spécifique.","prio":"P2","sec":"s2"},{"id":"fc-p110-32052f","poly":"pneumo","fiche":"p110","front":"Apnée obstructive : quelle définition ?","back":"Arrêt du débit aérien naso-buccal **≥ 10 s** avec **persistance des efforts ventilatoires**.","prio":"P1","sec":"s2"},{"id":"fc-p110-ab7706","poly":"pneumo","fiche":"p110","front":"Hypopnée : quelle définition ?","back":"Ventilation **↓ > 30 %** pendant **≥ 10 s** + désaturation **≥ 3 %** et/ou **micro-éveil**.","prio":"P1","sec":"s2"},{"id":"fc-p110-44014a","poly":"pneumo","fiche":"p110","front":"Apnée obstructive à l'enregistrement : quel aspect ?","back":"Arrêt du flux nasal avec mouvements thoraciques et abdominaux **en opposition de phase** ; désaturation **retardée** sur le début de l'apnée.","prio":"P2","sec":"s2"},{"id":"fc-p110-4ab247","poly":"pneumo","fiche":"p110","front":"Micro-éveil : quel examen permet de l'identifier ?","back":"Uniquement la **polysomnographie**.","prio":"P1","sec":"s2"},{"id":"fc-p110-4108c2","poly":"pneumo","fiche":"p110","front":"IAH : quelle définition ?","back":"Nombre d'**apnées + hypopnées** rapporté au temps d'enregistrement (polygraphie) ou au temps de sommeil (polysomnographie).","prio":"P1","sec":"s2"},{"id":"fc-p110-4ca3d5","poly":"pneumo","fiche":"p110","front":"SAHOS : quelle définition (critères) ?","back":"(**A** somnolence diurne excessive inexpliquée **ou B** ≥ 2 signes évocateurs) **+ C : IAH ≥ 5**.","prio":"P1","sec":"s2"},{"id":"fc-p110-b1d510","poly":"pneumo","fiche":"p110","front":"SAHOS : citer les signes du critère B ?","back":"Ronflement sévère quotidien · étouffement nocturne · éveils répétés · sommeil non réparateur · fatigue diurne · troubles de concentration · nycturie.","prio":"P2","sec":"s2"},{"id":"fc-p110-b7e3e5","poly":"pneumo","fiche":"p110","front":"SAHOS critère B : combien de signes évocateurs faut-il ?","back":"**Au moins 2**, sans autre explication.","prio":"P2","sec":"s2"},{"id":"fc-p110-1a5af4","poly":"pneumo","fiche":"p110","front":"SAHOS : quels seuils d'IAH définissent la sévérité ?","back":"Léger **5-14**/h · modéré **15-29**/h · sévère **≥ 30**/h.","prio":"P1","sec":"s2"},{"id":"fc-p110-029359","poly":"pneumo","fiche":"p110","front":"Sévérité du SAHOS : quelle composante s'ajoute à l'IAH ?","back":"Le **retentissement de la somnolence diurne** (conduite automobile, activité professionnelle).","prio":"P1","sec":"s2"},{"id":"fc-p110-954059","poly":"pneumo","fiche":"p110","front":"SAHOS : quel autre élément entre dans le choix du traitement ?","back":"Les **comorbidités cardiovasculaires et/ou respiratoires sévères**.","prio":"P2","sec":"s2"},{"id":"fc-p110-0d3a6a","poly":"pneumo","fiche":"p110","front":"IAH ≥ 5 isolé : suffit-il à définir un SAHOS ?","back":"**Non** : il faut aussi le **critère clinique A ou B**.","prio":"P1","sec":"s2"},{"id":"fc-p110-c3740d","poly":"pneumo","fiche":"p110","front":"Obstruction des VAS dans le SAHOS : quand parle-t-on d'apnée, quand d'hypopnée ?","back":"**Apnée** si l'obstruction est **complète** ; **hypopnée** si elle est **incomplète**.","prio":"P2","sec":"s3"},{"id":"fc-p110-966494","poly":"pneumo","fiche":"p110","front":"SAHOS : où siège surtout l'obstruction ?","back":"Au niveau du **pharynx** (voile du palais et/ou en arrière de la base de langue).","prio":"P2","sec":"s3"},{"id":"fc-p110-fc819e","poly":"pneumo","fiche":"p110","front":"SAHOS : quel défaut musculaire explique le collapsus ?","back":"Contraction **insuffisante des muscles dilatateurs du pharynx** contre la pression négative inspiratoire.","prio":"P2","sec":"s3"},{"id":"fc-p110-4b390c","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles causes de réduction anatomique du calibre des VAS ?","back":"Dépôts graisseux pariétaux (**obésité**) · **rétrognathie** mandibulaire · hypertrophie **amygdalienne et vélaire** (enfant surtout).","prio":"P2","sec":"s3"},{"id":"fc-p110-d6ddd1","poly":"pneumo","fiche":"p110","front":"SAHOS : d'où viennent les ronflements ?","back":"**Vibration des structures pharyngées** au passage de l'air, due aux résistances accrues des VAS.","prio":"P3","sec":"s3"},{"id":"fc-p110-638a8e","poly":"pneumo","fiche":"p110","front":"SAHOS : comment se lève l'obstruction ?","back":"Par un **micro-éveil** (**3 à 15 s**) qui rigidifie le pharynx.","prio":"P2","sec":"s3"},{"id":"fc-p110-f5c7d5","poly":"pneumo","fiche":"p110","front":"SAHOS : quelle conséquence des micro-éveils répétés sur le sommeil ?","back":"**Fragmentation** : ↓ sommeil lent profond et paradoxal au profit du sommeil lent léger → sommeil non réparateur, troubles de vigilance.","prio":"P2","sec":"s3"},{"id":"fc-p110-443e38","poly":"pneumo","fiche":"p110","front":"SAHOS : quels mécanismes augmentent le risque cardiovasculaire ?","back":"**Hypoxémie intermittente** + **activation sympathique répétée** (en plus de la fragmentation).","prio":"P2","sec":"s3"},{"id":"fc-p110-cd2503","poly":"pneumo","fiche":"p110","front":"SAHOS : quelle chaîne physiopathologique en 5 mots ?","back":"**Obstruction** → **efforts** → **micro-éveil** → **fragmentation** → **troubles de vigilance**.","prio":"P3","sec":"s3"},{"id":"fc-p110-76547c","poly":"pneumo","fiche":"p110","front":"SAHOS : quels sont les principaux facteurs de risque ?","back":"**Sexe masculin** · **âge** · **surpoids**.","prio":"P1","sec":"s4"},{"id":"fc-p110-d83d78","poly":"pneumo","fiche":"p110","front":"SAHOS : quel est le facteur de risque principal ?","back":"L'**obésité** ; l'IAH est **corrélé à l'IMC**.","prio":"P1","sec":"s4"},{"id":"fc-p110-c60167","poly":"pneumo","fiche":"p110","front":"SAHOS chez la femme : quand la prévalence augmente-t-elle ?","back":"**Après la ménopause**.","prio":"P1","sec":"s4"},{"id":"fc-p110-8c6d1f","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles anomalies anatomiques des VAS le favorisent ?","back":"**Rétrognathie**, **micromandibulie** · **hypertrophie amygdalienne** · **macroglossie**.","prio":"P1","sec":"s4"},{"id":"fc-p110-86a4b6","poly":"pneumo","fiche":"p110","front":"SAHOS modéré à sévère symptomatique : quelle prévalence ?","back":"Environ **14 %** des hommes et **6 %** des femmes adultes ; augmente avec l'âge.","prio":"P3","sec":"s4"},{"id":"fc-p110-ddcb2f","poly":"pneumo","fiche":"p110","front":"PPC en France : combien de patients traités ?","back":"Plus de **1,5 million**.","prio":"P3","sec":"s4"},{"id":"fc-p110-b28d12","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles conséquences neuropsychologiques ?","back":"Asthénie, somnolence, ralentissement intellectuel → qualité de vie altérée, **accidents de la route et du travail**, troubles de l'humeur, irritabilité.","prio":"P1","sec":"s4"},{"id":"fc-p110-3f4c47","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles comorbidités cardiovasculaires et métaboliques favorise-t-il ?","back":"**HTA** · **diabète** · coronaropathie · **AVC** · insuffisance cardiaque · troubles du rythme.","prio":"P1","sec":"s4"},{"id":"fc-p110-ca605e","poly":"pneumo","fiche":"p110","front":"Hypersomnolence : quelle règle pour la conduite automobile ?","back":"**Quelle qu'en soit la cause**, elle **contre-indique la conduite** (arrêté du 18 décembre 2015) ; le SAHOS, lui, augmente le risque d'accident.","prio":"P2","sec":"s4"},{"id":"fc-p110-d7a354","poly":"pneumo","fiche":"p110","front":"Conducteur professionnel hypersomnolent : que faut-il envisager ?","back":"Une **interruption temporaire du travail**.","prio":"P2","sec":"s4"},{"id":"fc-p110-440a2d","poly":"pneumo","fiche":"p110","front":"Hypersomnolence traitée : quand la conduite peut-elle reprendre ?","back":"Après **1 mois** de traitement bien conduit, efficacité évaluée.","prio":"P2","sec":"s4"},{"id":"fc-p110-381341","poly":"pneumo","fiche":"p110","front":"Reprise de la conduite : comment évaluer l'efficacité selon le permis ?","back":"Véhicule léger : **examen clinique** ; poids lourd : **test EEG de maintien d'éveil**.","prio":"P2","sec":"s4"},{"id":"fc-p110-6bcf87","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles comorbidités font particulièrement suspecter le diagnostic ?","back":"**Syndrome métabolique** et **HTA résistante**.","prio":"P1","sec":"s5"},{"id":"fc-p110-0b84b3","poly":"pneumo","fiche":"p110","front":"SAHOS : quels symptômes nocturnes rechercher ?","back":"**Ronflements** · **pauses respiratoires** vues par l'entourage · étouffement · agitation/insomnie · **nycturie**.","prio":"P1","sec":"s5"},{"id":"fc-p110-38fc15","poly":"pneumo","fiche":"p110","front":"SAHOS : quels symptômes diurnes rechercher ?","back":"**Somnolence diurne excessive** · asthénie · troubles cognitifs · troubles de la libido · **céphalées matinales**.","prio":"P1","sec":"s5"},{"id":"fc-p110-4e2d4d","poly":"pneumo","fiche":"p110","front":"Nycturie : quelle définition dans le SAHOS ?","back":"**Plus d'une miction par nuit**.","prio":"P2","sec":"s5"},{"id":"fc-p110-9ea922","poly":"pneumo","fiche":"p110","front":"Somnolence diurne excessive : quelle définition ?","back":"Besoin **non désiré**, parfois incontrôlable, de dormir le jour ; pas forcément sous forme de sieste ou d'assoupissements brefs.","prio":"P2","sec":"s5"},{"id":"fc-p110-244093","poly":"pneumo","fiche":"p110","front":"Asthénie dans le SAHOS : quelle valeur diagnostique ?","back":"Souvent présente mais **encore moins spécifique** que la somnolence.","prio":"P3","sec":"s5"},{"id":"fc-p110-cbff17","poly":"pneumo","fiche":"p110","front":"Échelle d'Epworth : quel score traduit une somnolence excessive ?","back":"Score **≥ 11/24** (échelle de 0 à 24).","prio":"P2","sec":"s5"},{"id":"fc-p110-c4a606","poly":"pneumo","fiche":"p110","front":"SAHOS : quelle proportion des patients a une somnolence excessive ?","back":"Seulement **50 %** (ESE > 10) → interroger sur les autres symptômes.","prio":"P2","sec":"s5"},{"id":"fc-p110-32a4f2","poly":"pneumo","fiche":"p110","front":"Échelle d'Epworth : est-ce un outil de dépistage du SAS ?","back":"**Non** : elle **quantifie** la somnolence, sans remplacer l'interrogatoire sur la vigilance.","prio":"P2","sec":"s5"},{"id":"fc-p110-4747e2","poly":"pneumo","fiche":"p110","front":"Suspicion de SAHOS : quelles mesures anthropométriques ?","back":"**IMC** (obésité si > 30 kg/m²) + **périmètre abdominal** (> 94 cm homme, > 80 cm femme).","prio":"P1","sec":"s5"},{"id":"fc-p110-47bcb2","poly":"pneumo","fiche":"p110","front":"Suspicion de SAHOS : que chercher à l'examen ORL ?","back":"**Rétrognathisme**, **macroglossie** · hypertrophie palais mou, piliers, **luette** · **amygdales** · **obstruction nasale**.","prio":"P1","sec":"s5"},{"id":"fc-p110-64064b","poly":"pneumo","fiche":"p110","front":"SAHOS de l'enfant : quelle est la cause principale ?","back":"L'**hypertrophie des amygdales**.","prio":"P1","sec":"s6"},{"id":"fc-p110-6215a1","poly":"pneumo","fiche":"p110","front":"Enfant : quand l'examen des amygdales est-il systématique ?","back":"**Ronflement** rapporté par les parents · **cassure staturo-pondérale** · **troubles des acquisitions** (hyperactivité, attention).","prio":"P1","sec":"s6"},{"id":"fc-p110-846912","poly":"pneumo","fiche":"p110","front":"SAHOS de l'enfant : quel autre facteur peut contribuer ?","back":"**Hypertrophie des végétations adénoïdes**, parfois avec signes d'**occlusion nasale**.","prio":"P2","sec":"s6"},{"id":"fc-p110-e6b339","poly":"pneumo","fiche":"p110","front":"Enregistrement nocturne dans le SAHOS : que fournit-il ?","back":"L'**IAH** et le caractère **obstructif ou central** des événements.","prio":"P2","sec":"s7"},{"id":"fc-p110-e9b127","poly":"pneumo","fiche":"p110","front":"Enregistrement nocturne : où peut-il se faire ?","back":"En **ambulatoire** ou lors d'une **courte hospitalisation**.","prio":"P3","sec":"s7"},{"id":"fc-p110-76341e","poly":"pneumo","fiche":"p110","front":"Suspicion de SAHOS : quel examen de 1re intention ?","back":"La **polygraphie ventilatoire**.","prio":"P2","sec":"s7"},{"id":"fc-p110-d06a4f","poly":"pneumo","fiche":"p110","front":"Enregistrement du sommeil (SAHOS) : quel est l'examen de référence ?","back":"La **polysomnographie** (« gold standard »), plus complète mais plus longue et plus coûteuse.","prio":"P2","sec":"s7"},{"id":"fc-p110-e71e8b","poly":"pneumo","fiche":"p110","front":"Polysomnographie dans le SAHOS : quand la proposer ?","back":"Situations **complexes**, ou en **2e intention** si la polygraphie n'a pas permis de conclure.","prio":"P2","sec":"s7"},{"id":"fc-p110-bd642c","poly":"pneumo","fiche":"p110","front":"Polygraphie ventilatoire : quels capteurs ?","back":"**Canules de pression nasale** (flux) · **sangles thoraco-abdominales** (efforts) · **oxymètre de pouls**.","prio":"P2","sec":"s7"},{"id":"fc-p110-ea6896","poly":"pneumo","fiche":"p110","front":"Polygraphie : à quoi servent les sangles thoraciques et abdominales ?","back":"Analyser les efforts respiratoires → caractère **obstructif ou central** des événements.","prio":"P3","sec":"s7"},{"id":"fc-p110-3544e9","poly":"pneumo","fiche":"p110","front":"Polysomnographie : quels capteurs ajoute-t-elle à la polygraphie ?","back":"**EEG**, **électro-oculogramme**, **EMG du menton** (± EMG des jambes).","prio":"P3","sec":"s7"},{"id":"fc-p110-b5b424","poly":"pneumo","fiche":"p110","front":"Polysomnographie : quelles données propres apporte-t-elle ?","back":"**Hypnogramme** (stades du sommeil) + éveils et **micro-éveils** liés aux apnées-hypopnées.","prio":"P3","sec":"s7"},{"id":"fc-p110-37d69a","poly":"pneumo","fiche":"p110","front":"SAHOS : quand demander une spirométrie ?","back":"Fumeur ou ex-fumeur, et/ou **IMC > 30**, et/ou symptômes respiratoires.","prio":"P2","sec":"s7"},{"id":"fc-p110-ac3cfc","poly":"pneumo","fiche":"p110","front":"SAHOS : quand demander une gazométrie artérielle ?","back":"**BPCO associée** et **obésité sévère (IMC > 35)**, et/ou **SpO₂ d'éveil < 94 %**.","prio":"P2","sec":"s7"},{"id":"fc-p110-c13d9b","poly":"pneumo","fiche":"p110","front":"SAHOS avec obésité (abdominale surtout) : quel bilan métabolique ?","back":"**Glycémie**, **bilan lipidique**, surveillance **tensionnelle**.","prio":"P2","sec":"s7"},{"id":"fc-p110-03404d","poly":"pneumo","fiche":"p110","front":"SAHOS : quand faire un bilan stomatologique ?","back":"Si un traitement par **orthèse d'avancée mandibulaire** est envisagé.","prio":"P2","sec":"s7"},{"id":"fc-p110-714298","poly":"pneumo","fiche":"p110","front":"Somnolence diurne ou troubles du maintien du sommeil : quels diagnostics autres que le SAHOS ?","back":"**Dette de sommeil**/hygiène · somnolence **iatrogène** (psychotropes, antalgiques) · insomnie chronique · **dépression** · hypersomnies centrales.","prio":"P1","sec":"s8"},{"id":"fc-p110-455e00","poly":"pneumo","fiche":"p110","front":"Hypersomnies centrales : citer deux exemples ?","back":"**Narcolepsie** · **hypersomnie idiopathique**.","prio":"P2","sec":"s8"},{"id":"fc-p110-09df78","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : quel critère de durée ?","back":"Symptômes **> 3 nuits par semaine** depuis **> 3 mois**, avec retentissement diurne.","prio":"P1","sec":"s8"},{"id":"fc-p110-6bc3a8","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : quels symptômes nocturnes ?","back":"Latence d'endormissement **> 45 min** · difficulté à maintenir le sommeil · **éveils précoces**.","prio":"P2","sec":"s8"},{"id":"fc-p110-959063","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : quel retentissement diurne ?","back":"Fatigue, manque d'entrain, troubles de concentration ou de l'humeur, **irritabilité**.","prio":"P2","sec":"s8"},{"id":"fc-p110-75c6d0","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : comment se fait le diagnostic ?","back":"Diagnostic **clinique**.","prio":"P1","sec":"s8"},{"id":"fc-p110-7979ba","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : quel outil sur 15 jours ?","back":"L'**agenda du sommeil** : objective la plainte et sa régularité ; c'est aussi un **outil du traitement**.","prio":"P1","sec":"s8"},{"id":"fc-p110-57f546","poly":"pneumo","fiche":"p110","front":"Agenda du sommeil : que note-t-on ?","back":"Heures de **coucher et de lever**, durée d'endormissement, durée et fréquence des **éveils nocturnes**.","prio":"P3","sec":"s8"},{"id":"fc-p110-bfebc2","poly":"pneumo","fiche":"p110","front":"Insomnie : la polygraphie ventilatoire est-elle indiquée ?","back":"**Jamais**.","prio":"P1","sec":"s8"},{"id":"fc-p110-c30ee8","poly":"pneumo","fiche":"p110","front":"Insomnie : quand discuter une polysomnographie ?","back":"Si **somnolence diurne** et/ou suspicion d'un **trouble associé** (SAHOS par exemple).","prio":"P2","sec":"s8"},{"id":"fc-p110-d03d0d","poly":"pneumo","fiche":"p110","front":"Insomnie chronique : quel traitement ?","back":"Essentiellement une **thérapie cognitivo-comportementale** (TCC), pour restaurer l'efficacité du sommeil.","prio":"P1","sec":"s10"},{"id":"fc-p110-11cdef","poly":"pneumo","fiche":"p110","front":"Syndrome des jambes sans repos : quelle prévalence en France ?","back":"**10 à 15 %** de la population.","prio":"P3","sec":"s8"},{"id":"fc-p110-6f4e61","poly":"pneumo","fiche":"p110","front":"Syndrome des jambes sans repos : quels signes cliniques ?","back":"Besoin de **bouger les jambes** (± douleurs, lourdeurs) **au repos**, soulagé par le **mouvement**, surtout **le soir ou la nuit**.","prio":"P2","sec":"s8"},{"id":"fc-p110-191cde","poly":"pneumo","fiche":"p110","front":"Syndrome des jambes sans repos : diagnostic et quand le traiter ?","back":"Diagnostic **clinique** ; prise en charge s'il retentit sur le **sommeil** ou la **qualité de vie**.","prio":"P2","sec":"s18"},{"id":"fc-p110-1e2add","poly":"pneumo","fiche":"p110","front":"Hygiène du sommeil : pour quels patients ?","back":"**Tout trouble du sommeil** (insomnie, SAHOS, adulte ou enfant) : mesures essentielles.","prio":"P1","sec":"s9"},{"id":"fc-p110-114dee","poly":"pneumo","fiche":"p110","front":"Hygiène du sommeil : quelle chambre ?","back":"**Calme**, **dans le noir**, à température **fraîche**.","prio":"P2","sec":"s9"},{"id":"fc-p110-4c0fb5","poly":"pneumo","fiche":"p110","front":"Hygiène du sommeil : à partir de quelle heure éviter les excitants ?","back":"Pas de café ni boissons énergisantes **après 14 h**.","prio":"P2","sec":"s9"},{"id":"fc-p110-c730d7","poly":"pneumo","fiche":"p110","front":"Hygiène du sommeil : quelles règles sur la lumière et les écrans ?","back":"Éviter la **lumière directe** dans l'heure avant le coucher ; **sortir les écrans** de la chambre.","prio":"P2","sec":"s9"},{"id":"fc-p110-b12d33","poly":"pneumo","fiche":"p110","front":"Hygiène du sommeil : quelle règle sur le rythme ?","back":"**Écouter sa fatigue** et respecter son propre rythme de sommeil.","prio":"P3","sec":"s9"},{"id":"fc-p110-b4c060","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles mesures générales pour tous ?","back":"**Hygiène du sommeil** · **perte de poids** · éviction **benzodiazépines, morphiniques, alcool le soir** · prise en charge des **FRCV**.","prio":"P2","sec":"s11"},{"id":"fc-p110-38bc4a","poly":"pneumo","fiche":"p110","front":"SAHOS avec surpoids : quels conseils systématiques ?","back":"**Conseils diététiques** + encouragement à l'**activité physique**.","prio":"P2","sec":"s11"},{"id":"fc-p110-15e341","poly":"pneumo","fiche":"p110","front":"SAHOS et obésité morbide (IMC ≥ 40) : quelle place de la chirurgie de l'obésité ?","back":"Le SAHOS est un **argument de plus** ; elle peut parfois faire **disparaître complètement** le SAHOS.","prio":"P2","sec":"s11"},{"id":"fc-p110-fb1790","poly":"pneumo","fiche":"p110","front":"SAHOS : quels médicaments et substances éviter ?","back":"**Benzodiazépines**, **morphiniques**, **alcool le soir** ; limiter **hypnotiques** et **myorelaxants**.","prio":"P2","sec":"s11"},{"id":"fc-p110-bddf2c","poly":"pneumo","fiche":"p110","front":"SAHOS : le traitement spécifique suffit-il à corriger HTA, diabète, dyslipidémie ?","back":"**Non** : les **dépister et traiter** à part entière.","prio":"P2","sec":"s11"},{"id":"fc-p110-fe2021","poly":"pneumo","fiche":"p110","front":"SAHOS : existe-t-il un médicament validé ?","back":"**Non**, aucun médicament validé à ce jour.","prio":"P2","sec":"s11"},{"id":"fc-p110-23d995","poly":"pneumo","fiche":"p110","front":"SAHOS : quand ajouter un traitement spécifique (instrumental ou chirurgical) ?","back":"Formes **modérées à sévères** : empêcher la fermeture des VAS pendant le sommeil.","prio":"P2","sec":"s11"},{"id":"fc-p110-54b253","poly":"pneumo","fiche":"p110","front":"SAHOS : quelles indications de la PPC en 1re intention ?","back":"Patient symptomatique avec **IAH ≥ 30/h**, ou **15 ≤ IAH < 30/h** + somnolence sévère (ou risque d'accident) ou comorbidités CV/respiratoires graves.","prio":"P2","sec":"s12"},{"id":"fc-p110-b8c5d7","poly":"pneumo","fiche":"p110","front":"PPC : quel mode d'action ?","back":"Air sous pression délivré par un masque = **attelle pneumatique des VAS** ; traitement le plus efficace à ce jour.","prio":"P2","sec":"s12"},{"id":"fc-p110-2ed381","poly":"pneumo","fiche":"p110","front":"PPC : quelles démarches pour la mise en route ?","back":"**Demande d'entente préalable** à la Sécurité sociale + prescription par un **spécialiste** ou un médecin formé au sommeil.","prio":"P2","sec":"s12"},{"id":"fc-p110-b54c96","poly":"pneumo","fiche":"p110","front":"PPC : qui assure l'installation et le suivi à domicile ?","back":"Un **prestataire de santé à domicile** (observance, tolérance, efficacité).","prio":"P3","sec":"s12"},{"id":"fc-p110-0f3e2f","poly":"pneumo","fiche":"p110","front":"PPC : comment favoriser son acceptation ?","back":"Par l'**éducation thérapeutique** et le traitement **précoce des effets indésirables**.","prio":"P3","sec":"s12"},{"id":"fc-p110-674916","poly":"pneumo","fiche":"p110","front":"PPC : quels effets indésirables traiter tôt ?","back":"Gêne **cutanée** liée au masque · **bouche sèche** · inconfort **digestif**.","prio":"P3","sec":"s12"},{"id":"fc-p110-8d1c49","poly":"pneumo","fiche":"p110","front":"PPC : quels masques possibles ?","back":"Masque **nasal**, **narinaire** ou **bucco-nasal**.","prio":"P3","sec":"s12"},{"id":"fc-p110-3eafa0","poly":"pneumo","fiche":"p110","front":"Refus ou intolérance de la PPC : quel traitement de 2e intention ?","back":"**Orthèse d'avancée mandibulaire** (sans contre-indication dentaire ou maxillo-faciale).","prio":"P2","sec":"s12"},{"id":"fc-p110-2ddda5","poly":"pneumo","fiche":"p110","front":"Neurostimulation du nerf hypoglosse : quelles conditions ?","back":"**3e intention** : intolérance à la **PPC et à l'OAM**, sans obésité importante (**IMC < 32**).","prio":"P2","sec":"s12"},{"id":"fc-p110-894c39","poly":"pneumo","fiche":"p110","front":"PPC : que transmet le télésuivi ?","back":"Chaque jour : **observance**, **fuites** et **IAH résiduel** ; rapports réguliers au prescripteur.","prio":"P3","sec":"s12"},{"id":"fc-p110-638af2","poly":"pneumo","fiche":"p110","front":"PPC : quels bénéfices démontrés ?","back":"↓ **asthénie** et **somnolence**, meilleure qualité de vie, ↓ **nycturie** ; ↓ **risque d'accident** si usage régulier.","prio":"P2","sec":"s12"},{"id":"fc-p110-02782f","poly":"pneumo","fiche":"p110","front":"PPC et risque cardiovasculaire : quelle nuance ?","back":"Elle **pourrait** le réduire, sous réserve d'un **usage quotidien régulier** et d'une correction des autres FRCV.","prio":"P2","sec":"s12"},{"id":"fc-p110-e1f708","poly":"pneumo","fiche":"p110","front":"PPC : qui peut renouveler la prescription au-delà d'un an ?","back":"Le **médecin traitant** (renouvellement annuel) si efficace et bien tolérée.","prio":"P3","sec":"s12"},{"id":"fc-p110-67c961","poly":"pneumo","fiche":"p110","front":"SAHOS : quand l'OAM est-elle de 1re intention ?","back":"Symptomatique avec **15 ≤ IAH < 30/h**, sans somnolence sévère ni comorbidité grave, sans contre-indication dentaire ou maxillo-faciale.","prio":"P2","sec":"s13"},{"id":"fc-p110-913f44","poly":"pneumo","fiche":"p110","front":"Orthèse d'avancée mandibulaire : quel principe ?","back":"Deux **gouttières** qui maintiennent la **mandibule en avant** pendant le sommeil et libèrent le carrefour pharyngé.","prio":"P2","sec":"s13"},{"id":"fc-p110-592d8d","poly":"pneumo","fiche":"p110","front":"OAM : quelle condition dentaire ?","back":"Assez de **dents saines sur chaque arcade** ; pas de contre-indication dentaire ou maxillo-faciale.","prio":"P2","sec":"s13"},{"id":"fc-p110-592758","poly":"pneumo","fiche":"p110","front":"OAM : avec qui la mettre en place ?","back":"Un **dentiste** ou **stomatologue** spécialisé, après bilan stomatologique.","prio":"P3","sec":"s13"},{"id":"fc-p110-b126df","poly":"pneumo","fiche":"p110","front":"OAM : que surveiller ?","back":"Efficacité clinique · **douleurs temporo-maxillaires** · **déplacements dentaires** à long terme.","prio":"P3","sec":"s13"},{"id":"fc-p110-aa3b83","poly":"pneumo","fiche":"p110","front":"OAM vs PPC : comment se comparent-elles ?","back":"L'OAM baisse **moins l'IAH**, mais efficacité **clinique jugée équivalente** dans le SAHOS modéré à sévère.","prio":"P2","sec":"s13"},{"id":"fc-p110-f946fc","poly":"pneumo","fiche":"p110","front":"SAHOS : quels sont les deux traitements codifiés ?","back":"**PPC** et **OAM** ; les autres sont d'usage plus restreint.","prio":"P2","sec":"s14"},{"id":"fc-p110-5c8c72","poly":"pneumo","fiche":"p110","front":"SAHOS positionnel : quel traitement possible ?","back":"Dispositif **mécanique** (sphère dans le dos ou système **vibrant** détectant le décubitus dorsal), **parfois** efficace.","prio":"P3","sec":"s14"},{"id":"fc-p110-1302f9","poly":"pneumo","fiche":"p110","front":"Hypertrophie amygdalienne majeure : quel traitement ?","back":"**Chirurgie vélo-amygdalienne**, surtout chez l'**enfant**, rarement chez l'adulte.","prio":"P2","sec":"s14"},{"id":"fc-p110-3cc22a","poly":"pneumo","fiche":"p110","front":"Chirurgie d'avancée maxillo-mandibulaire : pour qui ?","back":"Patients **sélectionnés** : rétro-micrognathie avec retentissement esthétique ou masticatoire, **sans obésité**, après échec PPC et OAM.","prio":"P3","sec":"s14"},{"id":"fc-p110-a851f1","poly":"pneumo","fiche":"p110","front":"Neurostimulation du nerf hypoglosse : quel statut ?","back":"Récemment **approuvée par la HAS**, en **3e intention**.","prio":"P3","sec":"s14"},{"id":"fc-p110-2dab9b","poly":"pneumo","fiche":"p110","front":"SAHOS de l'enfant : quelle prise en charge ?","back":"Examen systématique des **amygdales** ; **chirurgie vélo-amygdalienne** si hypertrophie majeure ; règles d'**hygiène du sommeil**.","prio":"P2","sec":"s16"},{"id":"fc-p154-512f5a","poly":"pneumo","fiche":"p154","front":"Infection respiratoire basse (IRB) : quel territoire est atteint ?","back":"Voies aériennes situées **sous la glotte** + **parenchyme pulmonaire**.","prio":"P2","sec":"s1"},{"id":"fc-p154-9c0eae","poly":"pneumo","fiche":"p154","front":"Infection respiratoire communautaire : définition ?","back":"Acquise **hors d'une structure hospitalière**, ou déclarée dans les **48 premières heures** suivant l'admission.","prio":"P1","sec":"s1"},{"id":"fc-p154-4a87a3","poly":"pneumo","fiche":"p154","front":"IRB communautaires de l'adulte : citer les trois entités ?","back":"**Bronchite aiguë** ; **exacerbation aiguë de BPCO** ; **pneumonie aiguë communautaire (PAC)**.","prio":"P1","sec":"s1"},{"id":"fc-p154-cb3508","poly":"pneumo","fiche":"p154","front":"Pourquoi les IRB nosocomiales et celles de l'immunodéprimé sont-elles traitées à part ?","back":"**Mécanismes** et **germes différents**.","prio":"P3","sec":"s1"},{"id":"fc-p154-0edc9e","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : quelles structures sont enflammées, lesquelles sont épargnées ?","back":"Atteinte des **bronches et bronchioles** (conduction) ; **parenchyme** épargné, notamment les **alvéoles**.","prio":"P1","sec":"s1"},{"id":"fc-p154-89993a","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : part des causes virales ?","back":"**90 %** des cas (rhinovirus, influenza, para-influenza, adénovirus, VRS, métapneumovirus…).","prio":"P1","sec":"s1"},{"id":"fc-p154-384882","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë en France : nombre de cas par an et saison ?","back":"Environ **10 millions** de cas/an, surtout l'**hiver**.","prio":"P3","sec":"s1"},{"id":"fc-p154-3bc9cc","poly":"pneumo","fiche":"p154","front":"PAC : définition ?","back":"Infection du **parenchyme pulmonaire** acquise **en dehors de l'hôpital**.","prio":"P1","sec":"s1"},{"id":"fc-p154-485de7","poly":"pneumo","fiche":"p154","front":"PAC : part parmi les IRB et nombre de cas annuels en France ?","back":"Seulement **10 %** des IRB, mais environ **500 000** cas/an.","prio":"P2","sec":"s1"},{"id":"fc-p154-78fbfb","poly":"pneumo","fiche":"p154","front":"PAC dans les pays occidentaux : quel rang parmi les causes de décès infectieux ?","back":"**1re cause de décès par infection**, gravité possible **même sans comorbidité**.","prio":"P1","sec":"s1"},{"id":"fc-p154-e31e42","poly":"pneumo","fiche":"p154","front":"PAC : mortalité globale et en réanimation ?","back":"**2 à 5 %** globalement ; jusqu'à **40 %** chez les patients admis en réanimation.","prio":"P1","sec":"s1"},{"id":"fc-p154-102dde","poly":"pneumo","fiche":"p154","front":"PAC : proportion hospitalisée et poids de ces hospitalisations dans les dépenses ?","back":"**10 à 20 %** hospitalisés ; ces hospitalisations = **90 %** des dépenses liées aux PAC.","prio":"P3","sec":"s1"},{"id":"fc-p154-daccf1","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : contexte évocateur ?","back":"**Épidémie**, période **hivernale** ; atteinte de plusieurs muqueuses avec « syndrome viral ».","prio":"P2","sec":"s2"},{"id":"fc-p154-9fafa4","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : caractères de la toux ?","back":"D'abord **sèche** puis **productive**, souvent douloureuse.","prio":"P1","sec":"s2"},{"id":"fc-p154-9cc02c","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : siège et trajet des brûlures thoraciques ?","back":"Bilatérales, **rétrosternales**, suivant le trajet de la **trachée et des grosses bronches**.","prio":"P2","sec":"s2"},{"id":"fc-p154-86a875","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : aspect possible de l'expectoration ?","back":"**Muqueuse ou purulente**.","prio":"P2","sec":"s2"},{"id":"fc-p154-701c8d","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : signes généraux ?","back":"**Inconstants** : fièvre, signes viraux (céphalées, myalgies, malaise…).","prio":"P3","sec":"s2"},{"id":"fc-p154-6ee503","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : que trouve l'auscultation ?","back":"**Râles bronchiques** ou auscultation **normale** ; **pas de crépitants en foyer** (signe négatif important).","prio":"P1","sec":"s2"},{"id":"fc-p154-3d4ca3","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : quelle discordance clinique est typique ?","back":"Plaintes nettes mais examen presque normal : **pas de polypnée**, **pas de foyer**, **aucun signe de gravité**.","prio":"P2","sec":"s2"},{"id":"fc-p154-d6b583","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë typique : quels examens complémentaires ?","back":"**Aucun** : diagnostic **clinique**.","prio":"P1","sec":"s2"},{"id":"fc-p154-4e62a7","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : seule situation justifiant un examen, et lequel ?","back":"**Doute sur une pneumonie** → **radiographie thoracique de face**.","prio":"P1","sec":"s2"},{"id":"fc-p154-c88563","poly":"pneumo","fiche":"p154","front":"Crachats purulents : suffisent-ils à évoquer une pneumonie plutôt qu'une bronchite ?","back":"**Non** : l'expectoration de la bronchite peut être purulente ; ce sont les **signes en foyer** qui orientent vers la pneumonie.","prio":"P1","sec":"s2"},{"id":"fc-p154-89d73f","poly":"pneumo","fiche":"p154","front":"PAC : signes fonctionnels respiratoires à rechercher ?","back":"**Toux**, **expectoration purulente**, **dyspnée**, **douleur thoracique** si réaction pleurale.","prio":"P2","sec":"s3"},{"id":"fc-p154-16f3a1","poly":"pneumo","fiche":"p154","front":"PAC : signes généraux ?","back":"**Fièvre**, **asthénie**.","prio":"P3","sec":"s3"},{"id":"fc-p154-810acc","poly":"pneumo","fiche":"p154","front":"PAC : signes d'un syndrome de condensation alvéolaire en foyer ?","back":"**Crépitants localisés**, murmure vésiculaire **diminué**, **souffle tubaire**, **vibrations vocales** mieux transmises.","prio":"P1","sec":"s3"},{"id":"fc-p154-8f98e5","poly":"pneumo","fiche":"p154","front":"PAC : signes d'un syndrome pleural associé ?","back":"Murmure vésiculaire **aboli**, **matité** à la percussion.","prio":"P2","sec":"s3"},{"id":"fc-p154-b65dcf","poly":"pneumo","fiche":"p154","front":"Anomalies auscultatoires en foyer dans la PAC : VPP ou VPN, laquelle domine ?","back":"**VPP >> VPN** : un foyer oriente fortement, son absence n'élimine pas.","prio":"P1","sec":"s3"},{"id":"fc-p154-1975b0","poly":"pneumo","fiche":"p154","front":"PAC : l'auscultation peut-elle être normale ?","back":"**Oui** : une auscultation normale n'élimine pas une PAC.","prio":"P1","sec":"s3"},{"id":"fc-p154-e6e9f5","poly":"pneumo","fiche":"p154","front":"PAC du sujet âgé dépendant ou avec déficit cognitif : forme anatomique habituelle ?","back":"**Bronchopneumonie**.","prio":"P2","sec":"s3"},{"id":"fc-p154-0c3d3e","poly":"pneumo","fiche":"p154","front":"PAC du sujet âgé dépendant : modes de révélation trompeurs ?","back":"**Décompensation d'une comorbidité** ou **troubles du comportement** ; signes respiratoires parfois absents, **fièvre parfois absente**.","prio":"P1","sec":"s3"},{"id":"fc-p154-f5b3f7","poly":"pneumo","fiche":"p154","front":"PAC chez l'immunodéprimé : conduite générale ?","back":"**Urgence** ; explorations poussées (**TDM thoracique, LBA** souvent) ; prise en charge **spécialisée et pluridisciplinaire**.","prio":"P1","sec":"s3"},{"id":"fc-p154-272e9d","poly":"pneumo","fiche":"p154","front":"Pneumonie à pneumocoque : quel dépistage faire ?","back":"**Dépistage du VIH**.","prio":"P1","sec":"s3"},{"id":"fc-p154-56ec01","poly":"pneumo","fiche":"p154","front":"VIH : quel germe domine dans les PAC, plus fréquentes sur ce terrain ?","back":"**Pneumocoque**.","prio":"P2","sec":"s3"},{"id":"fc-p154-0e9698","poly":"pneumo","fiche":"p154","front":"Déficit immunitaire humoral : quels germes donnent des pneumonies fréquentes ?","back":"**Germes encapsulés** : **pneumocoque**, **H. influenzae**.","prio":"P2","sec":"s3"},{"id":"fc-p154-e9cd3e","poly":"pneumo","fiche":"p154","front":"Pneumonies à germes encapsulés : quel examen demander et pour chercher quoi ?","back":"**Électrophorèse des protéines plasmatiques** → **hypogammaglobulinémie**, a fortiori chez le sujet jeune.","prio":"P1","sec":"s3"},{"id":"fc-p154-734f28","poly":"pneumo","fiche":"p154","front":"PAC : seul examen complémentaire systématique ?","back":"**Radiographie thoracique de face** (indispensable, elle affirme la pneumonie).","prio":"P1","sec":"s4"},{"id":"fc-p154-5ddc3a","poly":"pneumo","fiche":"p154","front":"PAC : deux aspects radiographiques possibles ?","back":"**Condensation alvéolaire systématisée** ; ou **opacités infiltratives** uni- ou bilatérales **non systématisées**.","prio":"P1","sec":"s4"},{"id":"fc-p154-5b0566","poly":"pneumo","fiche":"p154","front":"PAC : la clinique + radiographie suffisent-elles au diagnostic ?","back":"Oui, dans **la majorité des cas**.","prio":"P2","sec":"s4"},{"id":"fc-p154-4fc056","poly":"pneumo","fiche":"p154","front":"Radiographie thoracique dans la PAC : deux pièges ?","back":"**Retard radiologique** ; foyer **caché par le cœur** ou d'autres structures.","prio":"P1","sec":"s4"},{"id":"fc-p154-4367a7","poly":"pneumo","fiche":"p154","front":"TDM thoracique dans la PAC : en première intention ?","back":"**Non** ; TDM **non injectée** en 2e ligne.","prio":"P2","sec":"s4"},{"id":"fc-p154-0ef150","poly":"pneumo","fiche":"p154","front":"TDM thoracique dans la PAC : citer les situations où elle est utile ?","back":"Radio difficile (sujet âgé, maladie pulmonaire préexistante) ; étiologie (immunodépression, cause obstructive) ; complication ; différentiel.","prio":"P2","sec":"s4"},{"id":"fc-p154-f78df2","poly":"pneumo","fiche":"p154","front":"Suspicion d'embolie pulmonaire devant une pseudo-PAC : TDM injectée ou non ?","back":"**Injectée**.","prio":"P3","sec":"s4"},{"id":"fc-p154-619824","poly":"pneumo","fiche":"p154","front":"Échographie thoracique dans la PAC : principal intérêt ?","back":"Rechercher un **épanchement pleural** associé (elle peut aussi montrer une condensation).","prio":"P3","sec":"s4"},{"id":"fc-p154-ab9490","poly":"pneumo","fiche":"p154","front":"PAC traitée en ambulatoire : quelle biologie ?","back":"**Aucune**.","prio":"P1","sec":"s4"},{"id":"fc-p154-c2725e","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée : biologie de gravité ?","back":"**NFS**, **bilan rénal**, **bilan hépatique**, **coagulation**.","prio":"P2","sec":"s4"},{"id":"fc-p154-ce0480","poly":"pneumo","fiche":"p154","front":"PAC : quelle atteinte biologique oriente volontiers vers une bactérie intracellulaire ?","back":"Atteinte **hépatique** ou **rénale**.","prio":"P3","sec":"s4"},{"id":"fc-p154-b8888d","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée : quand faire un gaz du sang artériel et que recherche-t-il ?","back":"Si **SpO₂ basse** ou mauvaise tolérance : profondeur de l'**hypoxémie**, **hypercapnie**, **hyperlactatémie**.","prio":"P2","sec":"s4"},{"id":"fc-p154-989c4c","poly":"pneumo","fiche":"p154","front":"PAC : le germe est-il souvent identifié ?","back":"**Rarement**, même avec des prélèvements faits avant tout antibiotique.","prio":"P2","sec":"s5"},{"id":"fc-p154-d5645a","poly":"pneumo","fiche":"p154","front":"PAC : objectifs des prélèvements microbiologiques à l'hôpital ?","back":"Asseoir le **diagnostic** et permettre une **désescalade** ; indication selon la **gravité**.","prio":"P2","sec":"s5"},{"id":"fc-p154-672385","poly":"pneumo","fiche":"p154","front":"Prélèvements microbiologiques de la PAC : relation avec l'antibiotique ?","back":"**De préférence avant**, mais ils **ne doivent pas retarder** l'antibiothérapie.","prio":"P1","sec":"s5"},{"id":"fc-p154-68a882","poly":"pneumo","fiche":"p154","front":"Antigénuries légionelle et pneumocoque : effet d'un antibiotique déjà donné ?","back":"Elles **restent positives**.","prio":"P2","sec":"s5"},{"id":"fc-p154-27e039","poly":"pneumo","fiche":"p154","front":"ECBC : critères de qualité pour qu'il soit interprétable ?","back":"**PNN > 25/champ** et **cellules épithéliales < 10/champ**.","prio":"P2","sec":"s5"},{"id":"fc-p154-242ae6","poly":"pneumo","fiche":"p154","front":"PCR multiplex dans la PAC : sur quel prélèvement et que détecte-t-elle ?","back":"**Écouvillon nasopharyngé** (ou crachat, aspiration, LBA) : principaux **virus respiratoires**, parfois certaines **bactéries atypiques**.","prio":"P3","sec":"s5"},{"id":"fc-p154-495f9b","poly":"pneumo","fiche":"p154","front":"PCR des bactéries atypiques : quels germes vise-t-elle ?","back":"**Mycoplasma pneumoniae**, **Chlamydophila pneumoniae**, **Legionella pneumophila**.","prio":"P3","sec":"s5"},{"id":"fc-p154-64cef7","poly":"pneumo","fiche":"p154","front":"PAC ambulatoire : quels prélèvements microbiologiques ?","back":"**Aucun**.","prio":"P2","sec":"s5"},{"id":"fc-p154-d0dd03","poly":"pneumo","fiche":"p154","front":"PAC en hospitalisation conventionnelle : quels prélèvements systématiques ?","back":"**Hémocultures** et **ECBC** ; le reste selon le cas ; liquide pleural si épanchement.","prio":"P2","sec":"s5"},{"id":"fc-p154-2bc9ca","poly":"pneumo","fiche":"p154","front":"PAC en réanimation : quels prélèvements sont faits d'emblée ?","back":"Hémocultures, ECBC (ou aspiration bronchique), **antigénuries pneumocoque et légionelle**, PCR multiplex en automne-hiver.","prio":"P3","sec":"s5"},{"id":"fc-p154-c477bd","poly":"pneumo","fiche":"p154","front":"Antigénurie légionelle en service conventionnel : dans quelles situations ?","back":"Selon le cas : **suspicion**, **contexte épidémique**, **terrain à risque**.","prio":"P3","sec":"s5"},{"id":"fc-p154-a1974b","poly":"pneumo","fiche":"p154","front":"Score CRB 65 : nature des critères ?","back":"Critères **uniquement cliniques**.","prio":"P2","sec":"s6"},{"id":"fc-p154-94668d","poly":"pneumo","fiche":"p154","front":"CRB 65 : que signifient les lettres C et R (avec seuil) ?","back":"**C** = **confusion** ; **R** = fréquence respiratoire **≥ 30/min**.","prio":"P1","sec":"s6"},{"id":"fc-p154-96853e","poly":"pneumo","fiche":"p154","front":"CRB 65 : critère B (seuils tensionnels) ?","back":"PAS **< 90 mmHg** ou PAD **≤ 60 mmHg**.","prio":"P1","sec":"s6"},{"id":"fc-p154-9fbce2","poly":"pneumo","fiche":"p154","front":"CRB 65 : critère 65 et sa nuance ?","back":"Âge **≥ 65 ans** ; l'**âge physiologique** compte plus que l'âge civil, surtout sans comorbidité.","prio":"P2","sec":"s6"},{"id":"fc-p154-a954aa","poly":"pneumo","fiche":"p154","front":"CRB 65 : conduite selon le nombre de critères ?","back":"**0** : ambulatoire possible ; **≥ 1** : **évaluation à l'hôpital**.","prio":"P1","sec":"s6"},{"id":"fc-p154-5812c3","poly":"pneumo","fiche":"p154","front":"PAC : trois éléments qui fondent l'évaluation de la gravité ?","back":"Signes de gravité **respiratoires** ; signes de gravité du **sepsis** ; **étendue radiologique** et rapidité d'extension.","prio":"P2","sec":"s6"},{"id":"fc-p154-c87ead","poly":"pneumo","fiche":"p154","front":"PAC : critères respiratoires faisant envisager soins intensifs/réanimation ?","back":"Ventilation nécessaire ; **FR > 30/min** ; cyanose ou **SpO₂ < 90 % sous O₂** ; atteinte **bilatérale/multilobaire** ou extension rapide.","prio":"P1","sec":"s6"},{"id":"fc-p154-308394","poly":"pneumo","fiche":"p154","front":"PAC : critères systémiques faisant envisager soins intensifs/réanimation ?","back":"**Choc septique** ; **oligurie** ; autre défaillance d'organe sévère.","prio":"P1","sec":"s6"},{"id":"fc-p154-61a663","poly":"pneumo","fiche":"p154","front":"PAC : critères métaboliques/hématologiques faisant envisager la réanimation ?","back":"IR ou IH aiguë ; acidose sévère ; plaquettes **< 100 000/mm³** ; CIVD ; leucocytes **< 4000/mm³** ; hyperlactatémie.","prio":"P2","sec":"s6"},{"id":"fc-p154-804dd7","poly":"pneumo","fiche":"p154","front":"PAC : citer les motifs pratiques d'hospitalisation ?","back":"**Signes de gravité** ; **incertitude diagnostique** ; **échec** à domicile ; risque de **décompensation** d'une comorbidité ; prise orale **compromise**.","prio":"P1","sec":"s6"},{"id":"fc-p154-b0d3e8","poly":"pneumo","fiche":"p154","front":"PAC : situations compromettant la prise orale des antibiotiques ?","back":"**Inobservance** prévisible, **isolement**, **perte d'autonomie**, **intolérance digestive**…","prio":"P2","sec":"s6"},{"id":"fc-p154-5bc631","poly":"pneumo","fiche":"p154","front":"PAC, cas douteux ou litigieux : quelle attitude ?","back":"Hospitalisation **même courte** pour surveiller les **48-72 premières heures** de traitement.","prio":"P2","sec":"s6"},{"id":"fc-p154-169762","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : seuils de pouls et de température en faveur de l'hospitalisation ?","back":"Pouls **> 120/min** ; température **< 35 °C** ou **≥ 40 °C**.","prio":"P3","sec":"s6"},{"id":"fc-p154-216238","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : hors antibiotique ambulatoire en échec, quel traitement reçu avant l'hôpital est un critère de gravité ?","back":"**AINS**.","prio":"P2","sec":"s6"},{"id":"fc-p154-9cb6f1","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : quels types de pneumonie imposent l'hospitalisation ?","back":"**Pneumonie d'inhalation** (trouble de déglutition) ou **obstructive** (obstacle trachéobronchique connu ou suspect).","prio":"P3","sec":"s6"},{"id":"fc-p154-9d76ea","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : quel signe biologique doit alerter vers une CIVD ?","back":"La **thrombopénie**.","prio":"P3","sec":"s6"},{"id":"fc-p154-ea41cd","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : facteurs de risque liés au terrain imposant l'hospitalisation ?","back":"**2 facteurs**, ou **≥ 1 facteur + âge > 65 ans**.","prio":"P2","sec":"s6"},{"id":"fc-p154-cdb348","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : quand l'ambulatoire est-il possible selon le terrain ?","back":"Âge ≤ 65 ans et **≤ 1 facteur**, ou âge > 65 ans **sans facteur**.","prio":"P3","sec":"s6"},{"id":"fc-p154-7d47bc","poly":"pneumo","fiche":"p154","front":"Critères AFSSAPS 2010 : citer des facteurs d'immunodépression retenus ?","back":"Corticoïdes généraux ou immunosuppresseur ou chimiothérapie **dans les 6 mois**, **splénectomie**, SIDA, cachexie…","prio":"P3","sec":"s6"},{"id":"fc-p154-455c6f","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée : germe le plus souvent isolé et sa fréquence ?","back":"**Streptococcus pneumoniae** : **50 %** des PAC hospitalisées.","prio":"P1","sec":"s7"},{"id":"fc-p154-11a574","poly":"pneumo","fiche":"p154","front":"PAC graves de réanimation : deux germes les plus fréquents ?","back":"**Pneumocoque** et **Legionella pneumophila**.","prio":"P1","sec":"s7"},{"id":"fc-p154-6dfeff","poly":"pneumo","fiche":"p154","front":"PAC non sévère du sujet jeune soignée à domicile : germes les plus fréquents ?","back":"Bactéries **atypiques**, surtout **Mycoplasma pneumoniae** (Chlamydophila beaucoup plus rarement).","prio":"P1","sec":"s7"},{"id":"fc-p154-faa639","poly":"pneumo","fiche":"p154","front":"Virus respiratoires : fréquence de détection dans les PAC hospitalisées ?","back":"**25 à 50 %** (PCR multiplex) ; surtout **influenza** et **paramyxovirus** ; co-infections fréquentes.","prio":"P2","sec":"s7"},{"id":"fc-p154-f045b7","poly":"pneumo","fiche":"p154","front":"Virus détecté dans une PAC : son rôle direct est-il toujours établi ?","back":"**Non**, pas toujours (co-infections virus-bactérie fréquentes).","prio":"P3","sec":"s7"},{"id":"fc-p154-fde755","poly":"pneumo","fiche":"p154","front":"PAC à pneumocoque : type de début et de tableau ?","back":"Début **brutal** ; tableau **bruyant** (forte fièvre, malaise général).","prio":"P1","sec":"s7"},{"id":"fc-p154-bca53e","poly":"pneumo","fiche":"p154","front":"PAC à pneumocoque : signes thoraciques typiques ?","back":"Nets : **douleur thoracique**, **crachats saumonés**.","prio":"P2","sec":"s7"},{"id":"fc-p154-203847","poly":"pneumo","fiche":"p154","front":"Quel signe extrathoracique plaide pour le pneumocoque ?","back":"**Herpès labial** récurrent.","prio":"P2","sec":"s7"},{"id":"fc-p154-17e247","poly":"pneumo","fiche":"p154","front":"Pneumocoque : terrains où il est plus fréquent ?","back":"**Cirrhose**, **âge > 65 ans**, **immunodépression** (VIH surtout).","prio":"P2","sec":"s7"},{"id":"fc-p154-59e5e3","poly":"pneumo","fiche":"p154","front":"PAC à mycoplasme : début, tableau et contexte ?","back":"Début **progressif** (2-3 j) ; tableau **peu bruyant**, non grave ; **épidémie**, **adulte jeune**.","prio":"P1","sec":"s7"},{"id":"fc-p154-7bd657","poly":"pneumo","fiche":"p154","front":"PAC à mycoplasme : signes extrathoraciques ?","back":"**Rhinopharyngite**, **polyarthralgies**, myalgies, diarrhée, éruption cutanéomuqueuse.","prio":"P2","sec":"s7"},{"id":"fc-p154-c6992a","poly":"pneumo","fiche":"p154","front":"PAC à mycoplasme : signes thoraciques ?","back":"**Modérés** : examen souvent **normal**, **toux sèche**.","prio":"P3","sec":"s7"},{"id":"fc-p154-2eda9e","poly":"pneumo","fiche":"p154","front":"PAC à mycoplasme : anomalies biologiques possibles ?","back":"**Cytolyse hépatique**, **anémie hémolytique** (agglutinines froides).","prio":"P2","sec":"s7"},{"id":"fc-p154-00b5e6","poly":"pneumo","fiche":"p154","front":"Légionellose : expositions à risque ?","back":"**Voyage**, **thermes**, **eau ou aérosols contaminés** (+ épidémie).","prio":"P1","sec":"s7"},{"id":"fc-p154-e6ad28","poly":"pneumo","fiche":"p154","front":"Légionellose : quelle discordance entre deux constantes est classique ?","back":"**Dissociation pouls-température** (tableau bruyant et grave).","prio":"P1","sec":"s7"},{"id":"fc-p154-5fd235","poly":"pneumo","fiche":"p154","front":"Légionellose : signes extrathoraciques (fréquence et types) ?","back":"Marqués (**1/3** des cas) : myalgies, **digestifs**, **neurologiques** (confusion, hallucinations), bradycardie ; **pas d'ORL**.","prio":"P2","sec":"s7"},{"id":"fc-p154-28d1f3","poly":"pneumo","fiche":"p154","front":"Légionellose : anomalies biologiques évocatrices ?","back":"**Hyponatrémie**, **rhabdomyolyse** (CPK élevées), cytolyse hépatique, insuffisance rénale.","prio":"P1","sec":"s7"},{"id":"fc-p154-228a8d","poly":"pneumo","fiche":"p154","front":"Légionellose : mode de début ?","back":"**Rapidement progressif**.","prio":"P3","sec":"s7"},{"id":"fc-p154-1500d0","poly":"pneumo","fiche":"p154","front":"PAC virale : aspect radiographique ?","back":"Opacités **alvéolo-interstitielles** ou **verre dépoli** non systématisé.","prio":"P3","sec":"s7"},{"id":"fc-p154-6df6cb","poly":"pneumo","fiche":"p154","front":"PAC à pneumocoque : aspect radiographique typique ?","back":"**Condensation systématisée**.","prio":"P2","sec":"s7"},{"id":"fc-p154-e2b0e0","poly":"pneumo","fiche":"p154","front":"Pneumocoque à l'ECBC : aspect à l'examen direct ?","back":"**Cocci Gram +** en chaînettes (diplocoques).","prio":"P3","sec":"s7"},{"id":"fc-p154-6bda8b","poly":"pneumo","fiche":"p154","front":"Quels germes de PAC ne répondent pas aux bêtalactamines ?","back":"**Mycoplasme**, **légionelle**, **virus** (le pneumocoque y répond).","prio":"P1","sec":"s7"},{"id":"fc-p154-8dd5b8","poly":"pneumo","fiche":"p154","front":"Éléments d'orientation étiologique d'une PAC : sont-ils discriminants ?","back":"**Non** : ils orientent, mais **aucun n'est vraiment discriminant**.","prio":"P1","sec":"s7"},{"id":"fc-p154-454377","poly":"pneumo","fiche":"p154","front":"Pneumocoque : pourquoi toujours le prendre en compte dans une PAC grave ?","back":"Il peut devenir **rapidement sévère**.","prio":"P1","sec":"s8"},{"id":"fc-p154-7ac444","poly":"pneumo","fiche":"p154","front":"Pneumocoque : proportion de souches de sensibilité diminuée à la pénicilline (PSDP) ?","back":"Environ **un quart**.","prio":"P1","sec":"s8"},{"id":"fc-p154-594154","poly":"pneumo","fiche":"p154","front":"PSDP : mécanisme de résistance ?","back":"**Modification des PLP** (protéines liant les pénicillines), pas une enzyme.","prio":"P1","sec":"s8"},{"id":"fc-p154-597dda","poly":"pneumo","fiche":"p154","front":"PSDP : intérêt d'ajouter de l'acide clavulanique ?","back":"**Aucun** : c'est la **dose d'amoxicilline** qui compte.","prio":"P1","sec":"s8"},{"id":"fc-p154-ca3c2b","poly":"pneumo","fiche":"p154","front":"Pneumocoque : origine et transmission interhumaine ?","back":"**Colonisation de l'oropharynx** ; **pas de transmission interhumaine**, donc pas d'épidémie.","prio":"P2","sec":"s8"},{"id":"fc-p154-f359d6","poly":"pneumo","fiche":"p154","front":"Bactéries atypiques : localisation et mode de transmission ?","back":"Bactéries **intracellulaires**, transmises de personne à personne par **inhalation** de particules respiratoires.","prio":"P2","sec":"s8"},{"id":"fc-p154-9e7241","poly":"pneumo","fiche":"p154","front":"Bactéries atypiques : âge et contexte évocateurs ?","back":"**Avant 40 ans** ; contexte **épidémique**, notamment en **collectivité** (famille, classe, bureau).","prio":"P2","sec":"s8"},{"id":"fc-p154-3aa3fc","poly":"pneumo","fiche":"p154","front":"Bactéries atypiques : méthode diagnostique principale ?","back":"**PCR** sur sécrétions respiratoires ; la sérologie aide peu (rétrospective, 2 prélèvements à 2 semaines).","prio":"P2","sec":"s8"},{"id":"fc-p154-4b44bf","poly":"pneumo","fiche":"p154","front":"Bactéries atypiques : antibiotique de référence ?","back":"**Macrolide** (fluoroquinolone = alternative, pas en 1re intention).","prio":"P1","sec":"s8"},{"id":"fc-p154-fc4be2","poly":"pneumo","fiche":"p154","front":"Pneumonies à bactéries atypiques : gravité habituelle ?","back":"**Rarement** graves.","prio":"P2","sec":"s8"},{"id":"fc-p154-e2134e","poly":"pneumo","fiche":"p154","front":"Légionelle : terrain à risque ?","back":"**Âge avancé**, **tabagisme**, **immunodépression** acquise ou congénitale.","prio":"P2","sec":"s8"},{"id":"fc-p154-78cfe5","poly":"pneumo","fiche":"p154","front":"Légionelle : nature du germe et mode de contamination ?","back":"**Bacille Gram négatif** de l'eau ; contamination par **inhalation d'aérosols** d'eau contaminée.","prio":"P2","sec":"s8"},{"id":"fc-p154-a16eae","poly":"pneumo","fiche":"p154","front":"Légionellose : faut-il isoler le patient ?","back":"**Non** : **pas de transmission interhumaine**.","prio":"P2","sec":"s8"},{"id":"fc-p154-f0b85a","poly":"pneumo","fiche":"p154","front":"Légionellose : quelle démarche administrative, et pourquoi ?","back":"**Déclaration obligatoire à l'ARS** (cas sporadiques et nosocomiaux) → enquête sur le **réseau d'eau**.","prio":"P1","sec":"s8"},{"id":"fc-p154-0a2a7e","poly":"pneumo","fiche":"p154","front":"Antigénurie légionelle : quelle souche détecte-t-elle ?","back":"Uniquement **L. pneumophila sérogroupe 1** (90 à 95 % des légionelloses).","prio":"P2","sec":"s8"},{"id":"fc-p154-13641f","poly":"pneumo","fiche":"p154","front":"Antigénurie légionelle : délai de positivité et durée ?","back":"Positive **2 à 3 jours** après les premiers signes ; reste positive environ **2 mois**.","prio":"P3","sec":"s8"},{"id":"fc-p154-eedb90","poly":"pneumo","fiche":"p154","front":"Antigénurie légionelle : quand écarte-t-on le diagnostic ?","back":"**2 tests négatifs à 72 h d'intervalle** → exclusion avec **90 %** de certitude.","prio":"P3","sec":"s8"},{"id":"fc-p154-dc49b9","poly":"pneumo","fiche":"p154","front":"Légionellose : intérêt de la culture des prélèvements respiratoires ?","back":"Seule à **identifier la souche** (diagnostic, enquête) ; fortement recommandée si suspicion forte ; prévenir le laboratoire.","prio":"P3","sec":"s8"},{"id":"fc-p154-b31d87","poly":"pneumo","fiche":"p154","front":"Pneumonie virale : tableau clinique associé aux signes respiratoires ?","back":"**Syndrome grippal** : fièvre, asthénie, myalgies, céphalées, signes ORL, digestifs, éruption.","prio":"P3","sec":"s8"},{"id":"fc-p154-91d790","poly":"pneumo","fiche":"p154","front":"COVID-19 : signes extrarespiratoires évocateurs ?","back":"**Anosmie**, **dysgueusie** ; aussi digestifs, pseudo-engelures, conjonctivite.","prio":"P1","sec":"s8"},{"id":"fc-p154-47252d","poly":"pneumo","fiche":"p154","front":"COVID-19 : forme la plus grave et facteurs de risque cités ?","back":"**Pneumonie hypoxémiante avec SDRA** ; âge avancé, **obésité**, **diabète**, **hypertension**.","prio":"P2","sec":"s8"},{"id":"fc-p154-9944c0","poly":"pneumo","fiche":"p154","front":"COVID-19 : aspect scanographique initial ?","back":"**Verre dépoli** non systématisé à prédominance **sous-pleurale**, puis condensations.","prio":"P1","sec":"s8"},{"id":"fc-p154-7d260e","poly":"pneumo","fiche":"p154","front":"COVID-19 : méthode diagnostique ?","back":"**PCR sur écouvillon nasopharyngé** (intégrée aux PCR multiplex).","prio":"P2","sec":"s8"},{"id":"fc-p154-53dcc5","poly":"pneumo","fiche":"p154","front":"Pseudo-PAC focalisée : quel diagnostic différentiel ne se distingue pas par douleur, fièvre et début brutal ?","back":"**Embolie pulmonaire**.","prio":"P2","sec":"s9"},{"id":"fc-p154-3c897e","poly":"pneumo","fiche":"p154","front":"Infarctus pulmonaire : aspect radiologique évocateur ?","back":"Opacité **périphérique**, **sous-pleurale**, **triangulaire**, avec atélectasies des bases.","prio":"P3","sec":"s9"},{"id":"fc-p154-21d30a","poly":"pneumo","fiche":"p154","front":"Pneumopathie interstitielle diffuse aiguë faisant évoquer un OAP fébrile : quelle cause rechercher ?","back":"**Endocardite**.","prio":"P3","sec":"s9"},{"id":"fc-p154-829357","poly":"pneumo","fiche":"p154","front":"Pneumopathie excavée : citer des diagnostics différentiels ?","back":"**Cancer bronchique**, **tuberculose**, infarctus pulmonaire, vascularite, aspergillose, histoplasmose.","prio":"P2","sec":"s9"},{"id":"fc-p154-f016b8","poly":"pneumo","fiche":"p154","front":"Fièvre persistant ou réapparaissant sous antibiotique : causes extrapulmonaires à éliminer ?","back":"**Veinite**, infection sur **sonde urinaire**, **TVP**, néoplasie, **allergie médicamenteuse**, **colite post-antibiotique**.","prio":"P2","sec":"s9"},{"id":"fc-p154-7a2ad3","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë du sujet sain : lieu et type de traitement ?","back":"**À domicile**, uniquement **symptomatique** (antipyrétique : **paracétamol**).","prio":"P1","sec":"s10"},{"id":"fc-p154-c44762","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë de l'adulte sain : antibiotique ?","back":"**Non** (origine virale dans 90 % des cas) ; le patient BPCO est un cas à part.","prio":"P1","sec":"s10"},{"id":"fc-p154-dab83f","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : traitements à ne pas prescrire ?","back":"**Corticoïdes** (oraux ou inhalés), **AINS**, **mucolytiques**, **expectorants** (potentiellement délétères) ; ni **antitussif**.","prio":"P1","sec":"s10"},{"id":"fc-p154-350cfd","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë : évolution attendue de la fièvre et de la toux ?","back":"Fièvre disparue en **3 jours** ; toux post-infectieuse jusqu'à **3 semaines**.","prio":"P1","sec":"s10"},{"id":"fc-p154-090948","poly":"pneumo","fiche":"p154","front":"Bronchite aiguë d'évolution non favorable : que faire ?","back":"**Remettre en question le diagnostic**.","prio":"P2","sec":"s10"},{"id":"fc-p154-c24f90","poly":"pneumo","fiche":"p154","front":"Antibiothérapie de la PAC : trois éléments qui guident le choix ?","back":"**Épidémiologie** des PAC, **terrain** du patient, **gravité**.","prio":"P2","sec":"s11"},{"id":"fc-p154-71b387","poly":"pneumo","fiche":"p154","front":"PAC : délai de début de l'antibiothérapie ?","back":"**Urgente** : dès le diagnostic posé, si possible après les prélèvements (à l'hôpital).","prio":"P1","sec":"s11"},{"id":"fc-p154-267b6a","poly":"pneumo","fiche":"p154","front":"Règle des 4 h entre arrivée à l'hôpital et antibiotique dans la PAC : toujours en vigueur ?","back":"**Non**, abandonnée depuis **2012**.","prio":"P3","sec":"s11"},{"id":"fc-p154-ea6928","poly":"pneumo","fiche":"p154","front":"PAC : germe que l'antibiothérapie probabiliste couvre toujours ?","back":"Le **pneumocoque** (sauf rares tableaux très évocateurs d'atypique chez un sujet jeune traité à domicile).","prio":"P1","sec":"s11"},{"id":"fc-p154-cb6a7b","poly":"pneumo","fiche":"p154","front":"PAC grave : germe à couvrir en plus du pneumocoque ?","back":"**Légionelle**.","prio":"P1","sec":"s11"},{"id":"fc-p154-dafadd","poly":"pneumo","fiche":"p154","front":"Pneumonie d'inhalation : germes à couvrir en plus ?","back":"**Streptocoques**, **anaérobies**, **S. aureus**, **entérobactéries**.","prio":"P1","sec":"s11"},{"id":"fc-p154-dbc4c2","poly":"pneumo","fiche":"p154","front":"PAC en période grippale : germes à couvrir en plus du pneumocoque ?","back":"**S. aureus**, **H. influenzae**, **streptocoques du groupe A**.","prio":"P1","sec":"s11"},{"id":"fc-p154-d1307f","poly":"pneumo","fiche":"p154","front":"PAC : voie d'administration préférée de l'antibiotique ?","back":"**Voie orale** dès le début si possible (les C3G : voie **parentérale**).","prio":"P2","sec":"s11"},{"id":"fc-p154-a1a3a1","poly":"pneumo","fiche":"p154","front":"PAC « tout venant » : durée de l'antibiothérapie ?","back":"**7 jours**.","prio":"P1","sec":"s11"},{"id":"fc-p154-364528","poly":"pneumo","fiche":"p154","front":"PAC : trois mesures de préservation de l'écologie bactérienne ?","back":"**Raccourcir** la durée ; **réduire le spectre** si évolution favorable ; **éviter les fluoroquinolones** en 1re intention.","prio":"P2","sec":"s11"},{"id":"fc-p154-9154fe","poly":"pneumo","fiche":"p154","front":"PAC : quand la réévaluation clinique est-elle obligatoire ?","back":"À **48-72 h**, quel que soit le lieu de soins.","prio":"P1","sec":"s11"},{"id":"fc-p154-35bf69","poly":"pneumo","fiche":"p154","front":"Amoxicilline forte dose active sur les PSDP : posologie ?","back":"**≥ 50 mg/kg**, soit **3 g/j en 3 prises**.","prio":"P1","sec":"s11"},{"id":"fc-p154-8c184a","poly":"pneumo","fiche":"p154","front":"Amoxicilline et S. aureus : pourquoi ne le couvre-t-elle pas ?","back":"**95 %** des souches produisent une **pénicillinase**.","prio":"P1","sec":"s11"},{"id":"fc-p154-bbc3ac","poly":"pneumo","fiche":"p154","front":"C3G injectables utilisées dans la PAC ?","back":"**Ceftriaxone**, **céfotaxime**.","prio":"P2","sec":"s11"},{"id":"fc-p154-9ab48a","poly":"pneumo","fiche":"p154","front":"Ceftazidime dans la PAC : pourquoi l'éviter ?","back":"Activité **insuffisante sur les cocci Gram +** (pneumocoque, S. aureus).","prio":"P1","sec":"s11"},{"id":"fc-p154-b602b5","poly":"pneumo","fiche":"p154","front":"Macrolides : principale précaution d'emploi ?","back":"**Interactions médicamenteuses**.","prio":"P2","sec":"s11"},{"id":"fc-p154-48594f","poly":"pneumo","fiche":"p154","front":"FQAP dans la PAC : contre-indication formelle ?","back":"**Fluoroquinolone reçue dans les 3 derniers mois**, quelle qu'en soit l'indication.","prio":"P1","sec":"s11"},{"id":"fc-p154-e56fec","poly":"pneumo","fiche":"p154","front":"FQAP : effet indésirable à expliquer au patient et précautions ?","back":"**Tendinopathie** (prudence si âgé sous corticoïdes) ; pas d'**exposition solaire** ; arrêter et consulter si douleur tendineuse.","prio":"P2","sec":"s11"},{"id":"fc-p154-b7ccac","poly":"pneumo","fiche":"p154","front":"FQAP : quand les utiliser dans la PAC ?","back":"Avec prudence, seulement **sans alternative** (résistances, impact écologique).","prio":"P2","sec":"s11"},{"id":"fc-p154-006c55","poly":"pneumo","fiche":"p154","front":"FQAP : quelle molécule préférer ?","back":"**Lévofloxacine** (plutôt que la moxifloxacine).","prio":"P2","sec":"s11"},{"id":"fc-p154-e72c5f","poly":"pneumo","fiche":"p154","front":"Antibiotiques à ne pas utiliser dans la PAC ?","back":"**Céphalosporines orales**, **cyclines**, **triméthoprime-sulfaméthoxazole** (insuffisants sur le pneumocoque).","prio":"P1","sec":"s11"},{"id":"fc-p154-e70beb","poly":"pneumo","fiche":"p154","front":"Antibiotique de référence des anaérobies et de H. influenzae parmi les bêtalactamines orales ?","back":"**Amoxicilline-acide clavulanique**.","prio":"P3","sec":"s11"},{"id":"fc-p154-c35674","poly":"pneumo","fiche":"p154","front":"Métronidazole : quel spectre couvre-t-il dans la PAC ?","back":"Uniquement les **anaérobies**.","prio":"P3","sec":"s11"},{"id":"fc-p154-b882b1","poly":"pneumo","fiche":"p154","front":"Pristinamycine : à quelle famille est-elle apparentée ?","back":"Aux **macrolides**.","prio":"P3","sec":"s11"},{"id":"fc-p154-34d7a0","poly":"pneumo","fiche":"p154","front":"PAC à domicile, adulte sain sans gravité : antibiotique ?","back":"**Amoxicilline** ou **macrolide** ; alternative : **pristinamycine**.","prio":"P1","sec":"s12"},{"id":"fc-p154-9632a8","poly":"pneumo","fiche":"p154","front":"PAC à domicile, adulte sain : biologie et microbiologie ?","back":"**Ni biologie ni prélèvement** microbiologique.","prio":"P2","sec":"s12"},{"id":"fc-p154-ff4990","poly":"pneumo","fiche":"p154","front":"PAC ambulatoire d'évolution favorable : désescalade ?","back":"**Non** (pas de microbiologie).","prio":"P3","sec":"s12"},{"id":"fc-p154-62fe68","poly":"pneumo","fiche":"p154","front":"PAC ambulatoire de l'adulte sain sans amélioration à 48-72 h sous macrolide : que faire ?","back":"**Switch** pour couvrir le **pneumocoque**.","prio":"P2","sec":"s12"},{"id":"fc-p154-598ff4","poly":"pneumo","fiche":"p154","front":"PAC ambulatoire de l'adulte sain en échec sous pristinamycine ou FQAP : que faire ?","back":"**Hospitaliser**.","prio":"P2","sec":"s12"},{"id":"fc-p154-2fca3a","poly":"pneumo","fiche":"p154","front":"PAC à domicile, sujet âgé ou comorbide : antibiotiques possibles ?","back":"**Amoxicilline-acide clavulanique**, ou **ceftriaxone**, ou **FQAP**.","prio":"P1","sec":"s12"},{"id":"fc-p154-498170","poly":"pneumo","fiche":"p154","front":"PAC ambulatoire du sujet âgé ou comorbide en échec à 48-72 h : conduite ?","back":"**Hospitalisation**.","prio":"P2","sec":"s12"},{"id":"fc-p154-c03cf0","poly":"pneumo","fiche":"p154","front":"Prévention des PAC chez les sujets à risque : quelles vaccinations ?","back":"**Antigrippale** et **antipneumococcique** (et anti-SARS-CoV-2).","prio":"P2","sec":"s12"},{"id":"fc-p154-710b71","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée : critères définissant un pneumocoque suspecté ?","back":"**Cocci Gram +** à l'ECBC et/ou **antigénurie pneumocoque +** avec antigénurie légionelle négative.","prio":"P2","sec":"s13"},{"id":"fc-p154-da575c","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée avec pneumocoque suspecté ou documenté : antibiotique ?","back":"**Amoxicilline**, à tout âge.","prio":"P1","sec":"s13"},{"id":"fc-p154-68074a","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée, sujet jeune sans argument pour le pneumocoque : antibiotique ?","back":"**Amoxicilline** ; alternative : **pristinamycine**.","prio":"P1","sec":"s13"},{"id":"fc-p154-2154a6","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée, sujet âgé ou comorbide sans argument pour le pneumocoque : antibiotique ?","back":"**Amoxicilline-acide clavulanique**, ou **ceftriaxone**, ou **FQAP** (même en institution).","prio":"P1","sec":"s13"},{"id":"fc-p154-aaa6ef","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée : place de la kinésithérapie respiratoire ?","back":"Drainage bronchique **systématique**.","prio":"P3","sec":"s13"},{"id":"fc-p154-57d48d","poly":"pneumo","fiche":"p154","front":"PAC : corticoïdes par voie générale ?","back":"**Pas de bénéfice démontré**.","prio":"P2","sec":"s13"},{"id":"fc-p154-abcff6","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée avec suspicion de grippe en période épidémique : quel antiviral et durée ?","back":"**Oseltamivir** oral, **5 jours** ; ne remplace pas l'antibiotique.","prio":"P2","sec":"s13"},{"id":"fc-p154-4986e2","poly":"pneumo","fiche":"p154","front":"PAC : la fièvre peut persister combien de temps avec les bactéries intracellulaires ?","back":"Jusqu'à **5 jours** (amélioration attendue à 72 h, pas forcément apyrexie).","prio":"P2","sec":"s13"},{"id":"fc-p154-e38871","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée d'évolution favorable : quelle adaptation envisager ?","back":"**Désescalade** selon l'**antibiogramme**, seulement si évolution favorable.","prio":"P1","sec":"s13"},{"id":"fc-p154-a35930","poly":"pneumo","fiche":"p154","front":"PAC hospitalisée en échec à 48-72 h, sujet jeune sans argument pour le pneumocoque : conduite ?","back":"**Ajouter un macrolide** ou **passer à la pristinamycine**.","prio":"P2","sec":"s13"},{"id":"fc-p154-a2211e","poly":"pneumo","fiche":"p154","front":"PAC grave de réanimation, cas général : antibiothérapie ?","back":"**C3G IV** + **macrolide IV** ou **FQAP** (lévofloxacine).","prio":"P2","sec":"s14"},{"id":"fc-p154-545d70","poly":"pneumo","fiche":"p154","front":"PAC grave : facteurs de risque de Pseudomonas aeruginosa ?","back":"**Bronchectasies**, exacerbations de BPCO antérieures à **Pseudomonas**.","prio":"P2","sec":"s14"},{"id":"fc-p154-ebc49c","poly":"pneumo","fiche":"p154","front":"PAC grave avec facteur de risque de Pseudomonas : schéma ?","back":"Pipéracilline/tazobactam ou céfépime (ou carbapénème) **+ aminoside** + macrolide IV ou lévofloxacine IV.","prio":"P2","sec":"s14"},{"id":"fc-p154-e0d46b","poly":"pneumo","fiche":"p154","front":"PAC grave à risque de Pseudomonas : quand réserver le carbapénème ?","back":"Souche antérieure **résistante à pipéracilline/tazobactam et à la C4G**.","prio":"P3","sec":"s14"},{"id":"fc-p154-3bea21","poly":"pneumo","fiche":"p154","front":"PAC grave : durée maximale de l'aminoside ?","back":"**3 jours au maximum**.","prio":"P3","sec":"s14"},{"id":"fc-p154-b00fee","poly":"pneumo","fiche":"p154","front":"PAC grave en réanimation : quand doser les antibiotiques ?","back":"**Troisième secteur** ou **obésité** (problème de pharmacocinétique).","prio":"P3","sec":"s14"},{"id":"fc-p154-d8d147","poly":"pneumo","fiche":"p154","front":"PAC en période grippale : antibiotique de choix et alternative ?","back":"**Amoxicilline-acide clavulanique** ; alternative : **pristinamycine** (ou FQAP).","prio":"P1","sec":"s15"},{"id":"fc-p154-980287","poly":"pneumo","fiche":"p154","front":"Antigrippal probabiliste dans la PAC : dispense-t-il de l'antibiotique ?","back":"**Non**.","prio":"P2","sec":"s15"},{"id":"fc-p154-cb02e3","poly":"pneumo","fiche":"p154","front":"Vaccin antigrippal et vaccin antipneumococcique : peuvent-ils être faits le même jour ?","back":"**Oui**.","prio":"P2","sec":"s15"},{"id":"fc-p154-b2d3fa","poly":"pneumo","fiche":"p154","front":"Pneumonie abcédée : germes à couvrir et antibiotique de choix ?","back":"**Anaérobies** ; **amoxicilline-acide clavulanique**.","prio":"P1","sec":"s15"},{"id":"fc-p154-ef58c3","poly":"pneumo","fiche":"p154","front":"Pneumonie abcédée : alternative à l'amoxicilline-acide clavulanique ?","back":"**C3G** (ceftriaxone ou céfotaxime) **+ métronidazole**.","prio":"P1","sec":"s15"},{"id":"fc-p154-82b89d","poly":"pneumo","fiche":"p154","front":"Pneumonie excavée chez le fumeur, contours irréguliers : quel diagnostic redouter ?","back":"**Cancer bronchique**.","prio":"P2","sec":"s15"},{"id":"fc-p154-9a5cce","poly":"pneumo","fiche":"p154","front":"Excavation des lobes supérieurs : quel diagnostic évoquer ?","back":"**Tuberculose**.","prio":"P2","sec":"s15"},{"id":"fc-p154-79daa7","poly":"pneumo","fiche":"p154","front":"Pneumonie à pneumocoque : complication possible ?","back":"**Épanchement pleural**.","prio":"P2","sec":"s16"},{"id":"fc-p154-1155e1","poly":"pneumo","fiche":"p154","front":"Pneumonie à pneumocoque : vaccination à la sortie ?","back":"**Antipneumococcique** si le patient fait partie des personnes à **risque élevé**.","prio":"P3","sec":"s16"},{"id":"fc-p154-4ade86","poly":"pneumo","fiche":"p154","front":"Macrolide seul : couvre-t-il suffisamment le pneumocoque ?","back":"**Non**, couverture **insuffisante**.","prio":"P2","sec":"s16"},{"id":"fc-p154-40dfe7","poly":"pneumo","fiche":"p154","front":"Pneumonie à bactérie atypique : effet de l'amoxicilline ?","back":"**Inefficace** (pas de réponse aux bêtalactamines).","prio":"P1","sec":"s16"},{"id":"fc-p154-750726","poly":"pneumo","fiche":"p154","front":"Légionellose sans signe de gravité : traitement et durée ?","back":"**Macrolide seul**, **8 jours**.","prio":"P1","sec":"s16"},{"id":"fc-p154-a2fadf","poly":"pneumo","fiche":"p154","front":"Légionellose sévère : traitement et durée ?","back":"**Fluoroquinolone** seule ou + **macrolide** ou **rifampicine**, **8 à 21 jours**.","prio":"P1","sec":"s16"},{"id":"fc-p154-0d16a9","poly":"pneumo","fiche":"p154","front":"Légionellose grave de réanimation : quelle molécule a fait ses preuves ?","back":"**Lévofloxacine**.","prio":"P2","sec":"s16"},{"id":"fc-p154-85902c","poly":"pneumo","fiche":"p154","front":"Légionellose sévère : de quoi dépendent les modalités du traitement ?","back":"De la **gravité** et de l'**immunodépression**.","prio":"P3","sec":"s16"},{"id":"fc-p154-358095","poly":"pneumo","fiche":"p154","front":"PAC sur terrain particulier : quels terrains relèvent de la vaccination antipneumococcique ?","back":"**Immunodépression**, **VIH**, **asplénie**…","prio":"P3","sec":"s17"},{"id":"fc-p154-091c05","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : germes bactériens en cause ?","back":"**H. influenzae**, **Moraxella (Branhamella) catarrhalis**, **pneumocoque** (cause virale possible aussi).","prio":"P2","sec":"s18"},{"id":"fc-p154-3cb234","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO sans gravité, en ville : examens ?","back":"**Aucun**.","prio":"P2","sec":"s18"},{"id":"fc-p154-8c868a","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO à l'hôpital : bilan ?","back":"**Radio thoracique**, **ECG**, NFS, CRP, ionogramme-créatinine, **gaz du sang artériels**.","prio":"P3","sec":"s18"},{"id":"fc-p154-b4bb24","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : critères d'indication de l'antibiotique ?","back":"Expectoration **franchement purulente** ; ou BPCO très sévère (**VEMS < 30 %**) ; ou **signes de gravité**.","prio":"P1","sec":"s18"},{"id":"fc-p154-0a5714","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : traitement essentiel ?","back":"**Bronchodilatateurs inhalés** : bêta-2 agonistes de courte durée ± anticholinergique de courte durée.","prio":"P1","sec":"s18"},{"id":"fc-p154-d78152","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : antibiotiques de première intention et durée ?","back":"**Amoxicilline ± acide clavulanique**, **pristinamycine** ou **macrolide** ; **5 à 7 jours**.","prio":"P1","sec":"s18"},{"id":"fc-p154-75fd57","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO sous antibiotique : quand le réévaluer ?","back":"À **J2-J3** ; adaptation selon l'ECBC si des germes résistants (Pseudomonas…) sont ciblés.","prio":"P3","sec":"s18"},{"id":"fc-p154-9f98db","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : place de la lévofloxacine et des C3G injectables ?","back":"Réservées aux **cas particuliers** (échec d'antibiotiques antérieurs…).","prio":"P2","sec":"s18"},{"id":"fc-p154-c3be3d","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : cible de SpO₂ sous oxygène ?","back":"**88 à 92 %**.","prio":"P1","sec":"s18"},{"id":"fc-p154-c2517a","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : que signifie une hypoxémie profonde ou mal tolérée ?","back":"**Signe de gravité majeur**, toujours à corriger par un **débit d'oxygène adéquat**.","prio":"P2","sec":"s18"},{"id":"fc-p154-496a58","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : seuil de pH imposant la ventilation, et quelle modalité ?","back":"**pH < 7,35** → **VNI** au masque facial en 1re intention.","prio":"P1","sec":"s18"},{"id":"fc-p154-402e09","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : quand une corticothérapie systémique ?","back":"**Signes de gravité** ou amélioration insuffisante après **48 h** ; courte (prednisolone 30-40 mg/j, 5 j à l'hôpital).","prio":"P2","sec":"s18"},{"id":"fc-p154-b379fe","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : médicaments contre-indiqués ?","back":"**Antitussifs** et **neurosédatifs**.","prio":"P1","sec":"s18"},{"id":"fc-p154-26d099","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO hypercapnique sous oxygène : surveillance ?","back":"**Gaz du sang** (l'oxygène peut aggraver l'acidose respiratoire).","prio":"P2","sec":"s18"},{"id":"fc-p154-f578cc","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO : délai de la consultation chez le médecin traitant après la sortie ?","back":"**Dans la semaine** (indispensable).","prio":"P3","sec":"s18"},{"id":"fc-p154-719139","poly":"pneumo","fiche":"p154","front":"Après hospitalisation pour exacerbation de BPCO : délai de la réadaptation respiratoire ?","back":"**Dans les 90 jours** (si non faite récemment).","prio":"P3","sec":"s18"},{"id":"fc-p154-87eb84","poly":"pneumo","fiche":"p154","front":"Pneumonie chez un patient BPCO : quel schéma antibiotique ?","back":"Celui des **PAC**, avec si besoin des bronchodilatateurs renforcés.","prio":"P2","sec":"s18"},{"id":"fc-p154-e76707","poly":"pneumo","fiche":"p154","front":"Exacerbation de BPCO hospitalisée : prévention thromboembolique ?","back":"**HBPM** préventive (pas à domicile).","prio":"P3","sec":"s18"},{"id":"fc-p154-1fa5ef","poly":"pneumo","fiche":"p154","front":"PAC à 48-72 h : définition d'une évolution défavorable ?","back":"Symptômes qui **persistent** ou **s'aggravent**.","prio":"P2","sec":"s19"},{"id":"fc-p154-8d4343","poly":"pneumo","fiche":"p154","front":"PAC sans amélioration à 48-72 h : deux étapes de la démarche ?","back":"1) Chercher une **complication locorégionale** ou un **diagnostic différentiel** ; 2) antibiothérapie de **2e ligne**.","prio":"P2","sec":"s19"},{"id":"fc-p154-fccc02","poly":"pneumo","fiche":"p154","front":"Désescalade antibiotique : où la question se pose-t-elle surtout ?","back":"En **réanimation**, où le spectre initial est large.","prio":"P3","sec":"s19"},{"id":"fc-p154-e3950d","poly":"pneumo","fiche":"p154","front":"PAC en échec : complications locorégionales à rechercher ?","back":"**Épanchement pleural**, **abcès**, **obstacle endobronchique**.","prio":"P2","sec":"s20"},{"id":"fc-p154-2b5f05","poly":"pneumo","fiche":"p154","front":"Épanchement pleural compliquant une PAC : geste diagnostique ?","back":"**Ponction pleurale** sous contrôle **échographique** quand le volume le permet.","prio":"P2","sec":"s20"},{"id":"fc-p154-cff4ed","poly":"pneumo","fiche":"p154","front":"Pneumonie obstructive : quand l'évoquer ?","back":"Trouble de **ventilation** radiologique et/ou **pneumonies récidivantes** dans le même territoire.","prio":"P2","sec":"s20"},{"id":"fc-p154-5ec3c9","poly":"pneumo","fiche":"p154","front":"Pneumonie obstructive : causes et examen de confirmation ?","back":"**Corps étranger**, **cancer bronchique** du fumeur ; confirmation par **endoscopie bronchique**.","prio":"P2","sec":"s20"},{"id":"fc-p154-c93de2","poly":"pneumo","fiche":"p154","front":"PAC en échec : germes hors spectre à évoquer ?","back":"Entérobactéries, SARM, **Pseudomonas**, anaérobies, **bacille de Koch**, **pneumocystose** révélant un VIH.","prio":"P2","sec":"s20"},{"id":"fc-p154-019361","poly":"pneumo","fiche":"p154","front":"PAC en échec : outre germe et diagnostic, que vérifier côté traitement ?","back":"**Observance** et **pharmacocinétique** (obésité, 3e secteur, troubles de l'absorption).","prio":"P3","sec":"s20"},{"id":"fc-p154-714968","poly":"pneumo","fiche":"p154","front":"Suspicion de tuberculose : pourquoi éviter une fluoroquinolone en 1re intention ?","back":"Elle peut **négativer l'examen direct**.","prio":"P2","sec":"s20"},{"id":"fc-p154-30707c","poly":"pneumo","fiche":"p154","front":"Vaccinations antigrippale, antipneumococcique, anti-SARS-CoV-2 : pour tous les adultes ?","back":"**Non** : recommandées dans certaines **populations à risque**.","prio":"P1","sec":"s21"},{"id":"fc-p154-a77951","poly":"pneumo","fiche":"p154","front":"Vaccination antipneumococcique : citer des immunodépressions concernées ?","back":"**Asplénie** (drépanocytose homozygote), déficit héréditaire, **VIH**, cancer/hémopathie, **greffe**, immunosuppresseur, syndrome néphrotique.","prio":"P2","sec":"s21"},{"id":"fc-p154-91f844","poly":"pneumo","fiche":"p154","front":"Vaccination antipneumococcique : citer des maladies prédisposant aux infections invasives ?","back":"IC, **BPCO**, asthme sévère, IR, hépatopathie, diabète non équilibré par régime, **brèche ostéoméningée**, **implant cochléaire**.","prio":"P2","sec":"s21"},{"id":"fc-p154-2b8b56","poly":"pneumo","fiche":"p154","front":"Adulte à risque jamais vacciné contre le pneumocoque : schéma ?","back":"1 dose de **VPC13**, puis 1 dose de **VPP23** **2 mois** après (« 13 d'abord, 23 deux mois après »).","prio":"P1","sec":"s21"},{"id":"fc-p154-353f58","poly":"pneumo","fiche":"p154","front":"Rappel de VPP23 : délai minimal après le précédent VPP23 ?","back":"Au moins **5 ans**.","prio":"P2","sec":"s21"},{"id":"fc-p154-90d4cb","poly":"pneumo","fiche":"p154","front":"Adulte ayant reçu le VPP23 seul il y a plus d'un an : schéma ?","back":"1 dose de **VPC13**, puis rappel **VPP23** au moins 5 ans après le dernier VPP23.","prio":"P3","sec":"s21"},{"id":"fc-p159-0cb6de","poly":"pneumo","fiche":"p159","front":"Tuberculose : quel est l'agent responsable ?","back":"Mycobacterium tuberculosis hominis = **bacille de Koch (BK)**.","prio":"P1","sec":"s1"},{"id":"fc-p159-5a443d","poly":"pneumo","fiche":"p159","front":"Tuberculose : est-ce une maladie transmissible ?","back":"**Oui**, maladie infectieuse **transmissible**.","prio":"P2","sec":"s1"},{"id":"fc-p159-8ec502","poly":"pneumo","fiche":"p159","front":"BK : quelle propriété tinctoriale ?","back":"**Bacille acido-alcoolo-résistant (BAAR)**.","prio":"P1","sec":"s1"},{"id":"fc-p159-f2c35e","poly":"pneumo","fiche":"p159","front":"BK : quelles caractéristiques de croissance et de métabolisme ?","back":"Croissance **lente** ; métabolisme **aérobie strict** ; multiplication intra- et extracellulaire.","prio":"P2","sec":"s1"},{"id":"fc-p159-b5432d","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie : quel est son siège principal ?","back":"Le **poumon**, mais **tout organe** peut être atteint (ganglions, plèvre…).","prio":"P2","sec":"s1"},{"id":"fc-p159-17b245","poly":"pneumo","fiche":"p159","front":"Tuberculose dans le monde : combien de nouveaux cas par an ?","back":"**10,6 millions**.","prio":"P3","sec":"s1"},{"id":"fc-p159-667f2e","poly":"pneumo","fiche":"p159","front":"Tuberculose dans le monde : combien de décès en 2021 ?","back":"**1,6 million**, dont 187 000 co-infectés par le VIH.","prio":"P3","sec":"s1"},{"id":"fc-p159-a47a51","poly":"pneumo","fiche":"p159","front":"Tuberculose en France : quelle incidence en 2020 ?","back":"**4606 cas** déclarés, soit **6,8/100 000** : pays à **faible incidence**.","prio":"P2","sec":"s1"},{"id":"fc-p159-2d45cf","poly":"pneumo","fiche":"p159","front":"Tuberculose en France : quelles zones échappent à la faible incidence ?","back":"L'**Île-de-France** et les **grandes villes**.","prio":"P2","sec":"s1"},{"id":"fc-p159-5c6aac","poly":"pneumo","fiche":"p159","front":"Tuberculose en France en 2020 : quelle évolution de l'incidence ?","back":"Baisse de **10 %** (contexte de pandémie de COVID-19).","prio":"P3","sec":"s1"},{"id":"fc-p159-2fa27a","poly":"pneumo","fiche":"p159","front":"Tuberculose : par quelle voie se fait la contamination ?","back":"Voie **aérienne**, à partir d'un malade **bacillifère** (gouttelettes émises par la toux).","prio":"P1","sec":"s2"},{"id":"fc-p159-f38ca2","poly":"pneumo","fiche":"p159","front":"Contamination tuberculeuse : comment s'appelle le site alvéolaire initial ?","back":"Le **foyer primaire**, point de départ de la **primo-infection tuberculeuse (PIT)**.","prio":"P2","sec":"s2"},{"id":"fc-p159-b23ee5","poly":"pneumo","fiche":"p159","front":"Risque de PIT après exposition : de quels 3 facteurs dépend-il ?","back":"**Intensité de la toux** ; **contagiosité** du cas (BAAR à l'examen direct, cavernes) ; **durée d'exposition**.","prio":"P1","sec":"s2"},{"id":"fc-p159-463a1b","poly":"pneumo","fiche":"p159","front":"PIT : quelle est son expression clinique habituelle ?","back":"Le plus souvent **asymptomatique** ; elle aboutit à une **ITL**.","prio":"P1","sec":"s2"},{"id":"fc-p159-5946a2","poly":"pneumo","fiche":"p159","front":"ITL : quelle définition ?","back":"Une **PIT asymptomatique**.","prio":"P1","sec":"s2"},{"id":"fc-p159-cf1cb1","poly":"pneumo","fiche":"p159","front":"PIT : où vont les bacilles après le foyer primaire ?","back":"Phagocytés par les **macrophages alvéolaires** (où ils se multiplient), puis vers le **ganglion hilaire** satellite.","prio":"P3","sec":"s2"},{"id":"fc-p159-f69f8c","poly":"pneumo","fiche":"p159","front":"Tuberculose : quelle lésion histologique produit la réponse immune cellulaire ?","back":"**Granulome giganto-cellulaire avec nécrose caséeuse**, contenant quelques bacilles quiescents.","prio":"P1","sec":"s2"},{"id":"fc-p159-524a62","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie : comment survient-elle à partir de l'infection ?","back":"Multiplication des **bacilles quiescents**, à tout moment (pendant ou après la PIT) : le patient devient **symptomatique**.","prio":"P2","sec":"s2"},{"id":"fc-p159-a28c4f","poly":"pneumo","fiche":"p159","front":"PIT : quelle proportion évolue vers une tuberculose maladie ?","back":"**10 %**, le plus souvent dans les **2 premières années**.","prio":"P1","sec":"s2"},{"id":"fc-p159-a09eed","poly":"pneumo","fiche":"p159","front":"ITL : quand le risque de bascule en maladie augmente-t-il ?","back":"Aux **âges extrêmes** et chez l'**immunodéprimé** (bascule possible à tout moment, surtout dans les 2 ans).","prio":"P2","sec":"s2"},{"id":"fc-p159-09dcbc","poly":"pneumo","fiche":"p159","front":"PIT patente : quels signes cliniques possibles ?","back":"**AEG**, **érythème noueux**, **kérato-conjonctivite phlycténulaire**, adénopathies cervicales.","prio":"P2","sec":"s2"},{"id":"fc-p159-2aec49","poly":"pneumo","fiche":"p159","front":"PIT patente : que peut montrer la radiographie thoracique ?","back":"**Adénopathies médiastinales** ± lésion parenchymateuse du foyer primaire (**chancre d'inoculation**).","prio":"P3","sec":"s2"},{"id":"fc-p159-622e3b","poly":"pneumo","fiche":"p159","front":"Passage à la tuberculose maladie : quels facteurs d'immunodépression favorisent ?","back":"**VIH +++**, tumeurs et hémopathies, **immunosuppresseurs ou anti-TNF**.","prio":"P1","sec":"s2"},{"id":"fc-p159-dbb3e9","poly":"pneumo","fiche":"p159","front":"Passage à la tuberculose maladie : quels terrains et conditions de vie favorisent ?","back":"**Âges extrêmes** ; diabète, insuffisance rénale, malnutrition, alcool/tabac ; **précarité**, toxicomanie.","prio":"P2","sec":"s2"},{"id":"fc-p159-9ae557","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie : quelle part a une atteinte pulmonaire ou intrathoracique ?","back":"**75 %** des cas.","prio":"P2","sec":"s3"},{"id":"fc-p159-2b210d","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : comment se forme la caverne ?","back":"Le **caséum fond** et la caverne se **fistulise dans les bronches** ; dissémination **bronchogène** au reste du poumon.","prio":"P2","sec":"s3"},{"id":"fc-p159-0efb16","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : quel mode d'installation ?","back":"Début **insidieux**, progressif sur **plusieurs semaines à mois** ; **aucun symptôme spécifique**.","prio":"P1","sec":"s3"},{"id":"fc-p159-3c6367","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : quels signes généraux ?","back":"**AEG** (asthénie, anorexie, amaigrissement), **fébricule à prédominance nocturne**, **sueurs nocturnes**.","prio":"P1","sec":"s3"},{"id":"fc-p159-fc6ffa","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : quels signes fonctionnels ?","back":"**Toux chronique** ± expectorations ; **hémoptysie** (du crachat hémoptoïque à la forme grave) ; dyspnée tardive.","prio":"P1","sec":"s3"},{"id":"fc-p159-d4b97d","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : que trouve l'examen physique ?","back":"Généralement **rien** ; syndrome pleural possible si pleurésie associée.","prio":"P1","sec":"s3"},{"id":"fc-p159-9b1e32","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : quels 3 types de lésions radiologiques ?","back":"**Nodules**, **infiltrats**, **caverne** (lésion excavée), parfois associés.","prio":"P1","sec":"s3"},{"id":"fc-p159-222f44","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire commune : quel siège radiologique typique ?","back":"Segments **supérieurs et postérieurs** (lobes supérieurs).","prio":"P1","sec":"s3"},{"id":"fc-p159-17ac22","poly":"pneumo","fiche":"p159","front":"Tuberculose : quel contexte doit la faire évoquer ?","back":"**Contage**, précarité, **immigration**, vie en communauté, **immunosuppression/VIH**.","prio":"P1","sec":"s3"},{"id":"fc-p159-d74fe7","poly":"pneumo","fiche":"p159","front":"Pourquoi surnomme-t-on la tuberculose « la grande trompeuse » ?","back":"Elle peut **simuler de multiples pathologies pulmonaires**.","prio":"P2","sec":"s3"},{"id":"fc-p159-e1bf2b","poly":"pneumo","fiche":"p159","front":"Miliaire tuberculeuse : de quel type de forme s'agit-il ?","back":"Forme **disséminée, généralisée** (pas une forme pulmonaire à proprement parler), d'où sa **sévérité**.","prio":"P1","sec":"s4"},{"id":"fc-p159-b1fef4","poly":"pneumo","fiche":"p159","front":"Miliaire tuberculeuse : quel mécanisme ?","back":"**Dissémination hématogène** (bacillémie initiale ou érosion vasculaire d'un foyer caséeux).","prio":"P1","sec":"s4"},{"id":"fc-p159-7f8a30","poly":"pneumo","fiche":"p159","front":"Miliaire tuberculeuse : quelle présentation clinique ?","back":"**AEG marquée**, souvent **fébrile**, parfois **dyspnée**.","prio":"P2","sec":"s4"},{"id":"fc-p159-158758","poly":"pneumo","fiche":"p159","front":"Miliaire tuberculeuse : quel aspect radiographique ?","back":"Pneumopathie interstitielle diffuse **micronodulaire** (« grains de mil ») des **deux poumons**.","prio":"P2","sec":"s4"},{"id":"fc-p159-6eeb9c","poly":"pneumo","fiche":"p159","front":"Miliaire tuberculeuse : quels prélèvements envoyer en mycobactériologie ?","back":"**Tout prélèvement** (urines, selles, LCR, biopsie d'organe…).","prio":"P2","sec":"s4"},{"id":"fc-p159-2b3452","poly":"pneumo","fiche":"p159","front":"Pleurésie tuberculeuse : quel aspect du liquide ?","back":"**Exsudat lymphocytaire**, liquide **clair**.","prio":"P2","sec":"s4"},{"id":"fc-p159-041ede","poly":"pneumo","fiche":"p159","front":"Pleurésie tuberculeuse : quel mécanisme ?","back":"Effraction d'un **foyer parenchymateux sous-pleural**, souvent infra-radiologique.","prio":"P3","sec":"s4"},{"id":"fc-p159-1e7311","poly":"pneumo","fiche":"p159","front":"Pleurésie tuberculeuse : quel prélèvement a la meilleure rentabilité bactériologique ?","back":"**Surtout la biopsie pleurale** (culture) ; PCR rarement positive.","prio":"P1","sec":"s4"},{"id":"fc-p159-67c962","poly":"pneumo","fiche":"p159","front":"Pleurésie tuberculeuse : que montre l'histologie des biopsies pleurales ?","back":"**Granulomes avec nécrose caséeuse**.","prio":"P1","sec":"s4"},{"id":"fc-p159-a39167","poly":"pneumo","fiche":"p159","front":"Pleurésie tuberculeuse : pourquoi rechercher le BK dans les crachats ?","back":"Atteintes **pulmonaires associées fréquentes** : recherche **rentable**.","prio":"P3","sec":"s4"},{"id":"fc-p159-f66fa9","poly":"pneumo","fiche":"p159","front":"Tuberculose extra-pulmonaire : pourquoi le diagnostic est-il souvent anatomopathologique ?","back":"Formes **pauci-bacillaires**.","prio":"P2","sec":"s4"},{"id":"fc-p159-58e970","poly":"pneumo","fiche":"p159","front":"Formes extra-pulmonaires de tuberculose : dans quelle proportion sont-elles isolées ?","back":"Dans **30 %** des cas (formes moins fréquentes).","prio":"P3","sec":"s4"},{"id":"fc-p159-7dd11e","poly":"pneumo","fiche":"p159","front":"Tuberculose extra-pulmonaire : quels organes peuvent être touchés ?","back":"**Tous** : ganglions, os, péricarde, appareil génito-urinaire, méninges, plèvre.","prio":"P2","sec":"s4"},{"id":"fc-p159-dafe09","poly":"pneumo","fiche":"p159","front":"Formes systémiques de tuberculose : sur quels terrains sont-elles plus fréquentes ?","back":"**Immunodéprimé** et **enfant** (diagnostic plus difficile).","prio":"P3","sec":"s4"},{"id":"fc-p159-bd9817","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire : quelles séquelles possibles ?","back":"Nodules calcifiés, lésions fibreuses rétractiles, **DDB**, **aspergillome**.","prio":"P2","sec":"s4"},{"id":"fc-p159-92dbdb","poly":"pneumo","fiche":"p159","front":"Aspergillome post-tuberculeux : quelle définition ?","back":"Greffe d'**Aspergillus** dans une **caverne résiduelle**.","prio":"P2","sec":"s4"},{"id":"fc-p159-acabad","poly":"pneumo","fiche":"p159","front":"Tuberculose chez l'immunodéprimé : quelles particularités de présentation ?","back":"**Extra-pulmonaire > 50 %**, **disséminée ~25 %**, diagnostic **tardif**, infections associées possibles.","prio":"P2","sec":"s5"},{"id":"fc-p159-58c877","poly":"pneumo","fiche":"p159","front":"Immunodéprimé : devant quel signe isolé penser à la tuberculose ?","back":"Une **fièvre prolongée** (symptômes d'autant moins marqués que l'immunodépression est profonde).","prio":"P2","sec":"s5"},{"id":"fc-p159-3c6486","poly":"pneumo","fiche":"p159","front":"VIH : de combien le risque de tuberculose est-il multiplié ?","back":"Par **7**.","prio":"P2","sec":"s5"},{"id":"fc-p159-992975","poly":"pneumo","fiche":"p159","front":"Tuberculose chez le patient VIH : quel stade de l'infection signe-t-elle ?","back":"Le **stade SIDA**.","prio":"P2","sec":"s5"},{"id":"fc-p159-cc3599","poly":"pneumo","fiche":"p159","front":"VIH avec CD4 < 200/mm³ : quelles particularités de la tuberculose ?","back":"Pas de **granulome** ; **fièvre** souvent seul signe ; atteintes extra-respiratoires à chercher ; radio parfois presque normale.","prio":"P2","sec":"s5"},{"id":"fc-p159-5c6f13","poly":"pneumo","fiche":"p159","front":"VIH avec CD4 > 350/mm³ : comment se présente la tuberculose pulmonaire ?","back":"Avec des **symptômes classiques**.","prio":"P3","sec":"s5"},{"id":"fc-p159-d86033","poly":"pneumo","fiche":"p159","front":"Tuberculose : quel est le diagnostic de certitude ?","back":"La **mise en évidence du BK**, par des prélèvements **multiples**.","prio":"P1","sec":"s6"},{"id":"fc-p159-5982d2","poly":"pneumo","fiche":"p159","front":"Suspicion de tuberculose pulmonaire : quelles caractéristiques des prélèvements respiratoires ?","back":"**Systématiques**, **multiples et répétés**, adressés en **mycobactériologie**.","prio":"P1","sec":"s6"},{"id":"fc-p159-edef5a","poly":"pneumo","fiche":"p159","front":"Recherche de BK sur expectoration : quel piège de prescription ?","back":"Demander **spécifiquement la recherche de BAAR** : un **ECBC standard** ne la comporte pas.","prio":"P1","sec":"s6"},{"id":"fc-p159-2cd94f","poly":"pneumo","fiche":"p159","front":"Suspicion de tuberculose chez un patient qui ne crache pas : quel prélèvement ?","back":"**Tubage gastrique** le **matin à jeun**, avant tout lever.","prio":"P1","sec":"s6"},{"id":"fc-p159-33fcc6","poly":"pneumo","fiche":"p159","front":"Tubage gastrique : pourquoi le faire le matin à jeun ?","back":"Sécrétions **avalées la nuit** ; BAAR **résistants à l'acidité** gastrique : prélever **avant la vidange gastrique**.","prio":"P2","sec":"s6"},{"id":"fc-p159-328684","poly":"pneumo","fiche":"p159","front":"Tuberculose : quand faire une fibroscopie bronchique ?","back":"Après **3 examens directs négatifs** ou si **miliaire** suspectée (aspiration en territoire atteint).","prio":"P1","sec":"s6"},{"id":"fc-p159-9e6d64","poly":"pneumo","fiche":"p159","front":"Miliaire : quels prélèvements en plus des respiratoires ?","back":"**Hémocultures** sur milieu mycobactéries, **ECBU** en mycobactériologie, ± **myéloculture** si leuco-neutropénie.","prio":"P2","sec":"s6"},{"id":"fc-p159-158c8a","poly":"pneumo","fiche":"p159","front":"Tuberculose extra-pulmonaire : quels prélèvements selon la localisation ?","back":"Pleurale : **biopsie** ; ganglionnaire : ponction/exérèse ; méningée : **PL** ; génito-urinaire : **urines 3 jours** de suite.","prio":"P3","sec":"s6"},{"id":"fc-p159-d47905","poly":"pneumo","fiche":"p159","front":"Examen direct mycobactériologique : quelle coloration ?","back":"**Ziehl-Neelsen** (recherche de BAAR).","prio":"P1","sec":"s6"},{"id":"fc-p159-b77766","poly":"pneumo","fiche":"p159","front":"Examen direct négatif : élimine-t-il une tuberculose ?","back":"**Non** : positif seulement au-delà de **10³ bacilles/ml**.","prio":"P1","sec":"s6"},{"id":"fc-p159-a8aaac","poly":"pneumo","fiche":"p159","front":"Examen direct pour BAAR : en combien de temps a-t-on le résultat ?","back":"En **quelques heures**.","prio":"P3","sec":"s6"},{"id":"fc-p159-7c1bd1","poly":"pneumo","fiche":"p159","front":"Culture mycobactériologique : quand la faire ?","back":"**Systématiquement**, même si l'examen direct est négatif.","prio":"P1","sec":"s6"},{"id":"fc-p159-307637","poly":"pneumo","fiche":"p159","front":"Culture du BK sur milieu solide : quel milieu et quel délai ?","back":"**Löwenstein-Jensen** ; positive à partir de **3 à 4 semaines**.","prio":"P1","sec":"s6"},{"id":"fc-p159-e54839","poly":"pneumo","fiche":"p159","front":"Culture du BK en milieu liquide : quel délai de positivité ?","back":"Dès **10 à 15 jours** environ.","prio":"P2","sec":"s6"},{"id":"fc-p159-c02954","poly":"pneumo","fiche":"p159","front":"Test génotypique après examen direct ou culture positifs : quels apports ?","back":"Confirme le **complexe tuberculosis** (vs mycobactérie non tuberculeuse) ; cherche une mutation **rpoB**.","prio":"P1","sec":"s6"},{"id":"fc-p159-c8b642","poly":"pneumo","fiche":"p159","front":"Mutation du gène rpoB : quelle résistance confère-t-elle ?","back":"Résistance à la **rifampicine**.","prio":"P1","sec":"s6"},{"id":"fc-p159-f8fde3","poly":"pneumo","fiche":"p159","front":"Test génotypique du BK : quel délai de résultat ?","back":"**72 h** au maximum (habituellement **24 h**).","prio":"P2","sec":"s6"},{"id":"fc-p159-f7198e","poly":"pneumo","fiche":"p159","front":"Recherche de mutation rpoB : à quelle autre recherche peut-on la coupler ?","back":"Aux mutations de résistance à l'**isoniazide**.","prio":"P3","sec":"s6"},{"id":"fc-p159-4486f4","poly":"pneumo","fiche":"p159","front":"Antibiogramme du BK : quand est-il réalisé ?","back":"**Obligatoire**, systématique dès que la **culture est positive**.","prio":"P1","sec":"s6"},{"id":"fc-p159-ec0de6","poly":"pneumo","fiche":"p159","front":"Suspicion de BK résistant : à qui transmettre la souche ?","back":"Au **Centre national de référence des mycobactéries** (antibiotiques de 2e ligne).","prio":"P3","sec":"s6"},{"id":"fc-p159-5adc0e","poly":"pneumo","fiche":"p159","front":"Test moléculaire positif pour M. tuberculosis (ex. Xpert MTB/RIF) : quelle valeur ?","back":"**Signe une tuberculose** sans attendre la culture (qui confirmera ensuite).","prio":"P2","sec":"s6"},{"id":"fc-p159-f279a8","poly":"pneumo","fiche":"p159","front":"Granulome épithélioïde giganto-cellulaire avec nécrose caséeuse : est-il pathognomonique ?","back":"**Non** : **fortement évocateur** mais non pathognomonique de tuberculose.","prio":"P1","sec":"s6"},{"id":"fc-p159-bfd11b","poly":"pneumo","fiche":"p159","front":"Bacilles extracellulaires (95 %) : quel rôle et quelles molécules actives ?","back":"**Contagiosité et symptômes** ; **isoniazide + rifampicine**.","prio":"P2","sec":"s7"},{"id":"fc-p159-b5f417","poly":"pneumo","fiche":"p159","front":"Bacilles intracellulaires quiescents des macrophages : quelles molécules actives ?","back":"**Pyrazinamide + rifampicine**.","prio":"P2","sec":"s7"},{"id":"fc-p159-ceba23","poly":"pneumo","fiche":"p159","front":"Bacilles extracellulaires du caséum : quel risque et quelle molécule active ?","back":"Risque de **rechute à distance** ; **rifampicine**.","prio":"P2","sec":"s7"},{"id":"fc-p159-fd3df1","poly":"pneumo","fiche":"p159","front":"Antituberculeux : citer les 4 molécules de 1re ligne.","back":"**Isoniazide**, **rifampicine**, **éthambutol**, **pyrazinamide**.","prio":"P1","sec":"s7"},{"id":"fc-p159-dc8952","poly":"pneumo","fiche":"p159","front":"Isoniazide : quels effets indésirables ?","back":"Troubles digestifs ; **hépatite** (de la hausse des transaminases à la forme sévère) ; **polynévrite sensitivo-motrice**.","prio":"P1","sec":"s7"},{"id":"fc-p159-690b87","poly":"pneumo","fiche":"p159","front":"Polynévrite sous isoniazide : quelle carence la favorise ?","back":"Carence en **vitamine B6** (pyridoxine).","prio":"P1","sec":"s7"},{"id":"fc-p159-11cd2b","poly":"pneumo","fiche":"p159","front":"Rifampicine : quel est son principal effet indésirable ?","back":"Les **réactions immuno-allergiques**.","prio":"P1","sec":"s7"},{"id":"fc-p159-105f99","poly":"pneumo","fiche":"p159","front":"Rifampicine : la coloration orange des urines, larmes, sperme est-elle un effet indésirable ?","back":"**Non**, phénomène **normal** ; **prévenir le patient**.","prio":"P1","sec":"s7"},{"id":"fc-p159-518021","poly":"pneumo","fiche":"p159","front":"Rifampicine : quelle propriété pharmacologique source d'interactions ?","back":"**Puissant inducteur enzymatique**.","prio":"P1","sec":"s7"},{"id":"fc-p159-108a55","poly":"pneumo","fiche":"p159","front":"Rifampicine (inducteur enzymatique) : citer des médicaments avec lesquels elle interagit.","back":"**AVK** (INR), **AOD**, **pilule œstroprogestative**, inhibiteurs de protéase, **méthadone**, corticoïdes, digitaliques…","prio":"P1","sec":"s7"},{"id":"fc-p159-8ab6f7","poly":"pneumo","fiche":"p159","front":"Rifampicine et méthadone : quel risque ?","back":"**Syndrome de sevrage**.","prio":"P2","sec":"s7"},{"id":"fc-p159-2ae699","poly":"pneumo","fiche":"p159","front":"Éthambutol : quel effet indésirable majeur ?","back":"**Névrite optique rétrobulbaire**.","prio":"P1","sec":"s7"},{"id":"fc-p159-bd2405","poly":"pneumo","fiche":"p159","front":"Névrite optique sous éthambutol : quels facteurs favorisants ?","back":"**Posologie élevée prolongée**, **éthylisme chronique**, **insuffisance rénale**.","prio":"P2","sec":"s7"},{"id":"fc-p159-624705","poly":"pneumo","fiche":"p159","front":"Éthambutol : quelle surveillance spécifique ?","back":"**Examen ophtalmologique** : vision des couleurs, champ visuel.","prio":"P1","sec":"s7"},{"id":"fc-p159-b91193","poly":"pneumo","fiche":"p159","front":"Pyrazinamide : quelles contre-indications ?","back":"**Insuffisance hépatocellulaire** et **insuffisance rénale**.","prio":"P1","sec":"s7"},{"id":"fc-p159-3b41e9","poly":"pneumo","fiche":"p159","front":"Pyrazinamide : quelle anomalie biologique métabolique entraîne-t-il ?","back":"**Hyperuricémie** par effondrement de l'uraturie, généralement asymptomatique.","prio":"P1","sec":"s7"},{"id":"fc-p159-c08df3","poly":"pneumo","fiche":"p159","front":"Hyperuricémie sous pyrazinamide : quel risque clinique existe, lequel n'existe pas ?","back":"**Crise de goutte** possible ; **pas de colique néphrétique**.","prio":"P2","sec":"s7"},{"id":"fc-p159-430bb8","poly":"pneumo","fiche":"p159","front":"Cytolyse hépatique : laquelle survient plus tardivement, INH ou PZA ?","back":"Celle du **pyrazinamide**.","prio":"P2","sec":"s7"},{"id":"fc-p159-fbd0a1","poly":"pneumo","fiche":"p159","front":"Rifater : quelle composition ?","back":"**INH + RMP + PZA**.","prio":"P2","sec":"s7"},{"id":"fc-p159-1501f6","poly":"pneumo","fiche":"p159","front":"Rifinah : quelle composition ?","back":"**INH + RMP**.","prio":"P2","sec":"s7"},{"id":"fc-p159-b67f78","poly":"pneumo","fiche":"p159","front":"Suspicion de tuberculose : pourquoi éviter les fluoroquinolones pour une infection pulmonaire ?","back":"Risque de **négativer les prélèvements**.","prio":"P2","sec":"s7"},{"id":"fc-p159-baddce","poly":"pneumo","fiche":"p159","front":"Fluoroquinolones dans la tuberculose : quelle indication ?","back":"Seulement une **tuberculose résistante documentée**.","prio":"P2","sec":"s7"},{"id":"fc-p159-7cfaa3","poly":"pneumo","fiche":"p159","front":"Traitement antituberculeux : quel caractère d'urgence ?","back":"**Urgence** : l'examen ophtalmologique peut être **différé**.","prio":"P2","sec":"s8"},{"id":"fc-p159-034c07","poly":"pneumo","fiche":"p159","front":"Avant le traitement antituberculeux : quel bilan biologique ?","back":"**Créatininémie** (DFG), **uricémie**, **transaminases**, **hémogramme**.","prio":"P1","sec":"s8"},{"id":"fc-p159-c317f1","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie : quelles sérologies proposer systématiquement ?","back":"**VIH** et hépatites : **Ag HBs, Ac anti-HBs, Ac anti-HBc, Ac anti-VHC**.","prio":"P1","sec":"s8"},{"id":"fc-p159-a17d2b","poly":"pneumo","fiche":"p159","front":"Tuberculose : pourquoi la poly-antibiothérapie est-elle obligatoire ?","back":"La monothérapie fait émerger des **mutants résistants** ; il faut agir sur les **3 populations** de BK.","prio":"P1","sec":"s8"},{"id":"fc-p159-45a050","poly":"pneumo","fiche":"p159","front":"Antituberculeux : pourquoi une seule prise par jour ?","back":"**Temps de doublement long** du BK (**20 h**).","prio":"P2","sec":"s8"},{"id":"fc-p159-005319","poly":"pneumo","fiche":"p159","front":"Tuberculose : pourquoi un traitement prolongé ?","back":"**Bacilles persistants** dans les foyers tuberculeux.","prio":"P2","sec":"s8"},{"id":"fc-p159-6939dc","poly":"pneumo","fiche":"p159","front":"Rifampicine : à quel moment la prendre ?","back":"**À jeun** : 30 min à 1 h avant le repas, ou au moins 2 h après (absorption diminuée par le repas).","prio":"P1","sec":"s8"},{"id":"fc-p159-491e22","poly":"pneumo","fiche":"p159","front":"Tuberculose multi-sensible : quel schéma classique ?","back":"**2 mois INH + RMP + EMB + PZA**, puis **4 mois INH + RMP** (6 mois).","prio":"P1","sec":"s8"},{"id":"fc-p159-c7e2dc","poly":"pneumo","fiche":"p159","front":"Tuberculose multi-sensible : quelle localisation fait exception aux 6 mois ?","back":"La forme **neuro-méningée** : **9 à 12 mois**.","prio":"P1","sec":"s8"},{"id":"fc-p159-77cc1e","poly":"pneumo","fiche":"p159","front":"Antituberculeux : quand adapter le traitement à l'antibiogramme ?","back":"**Dès qu'il est rendu**.","prio":"P2","sec":"s8"},{"id":"fc-p159-e2ec6a","poly":"pneumo","fiche":"p159","front":"Isoniazide : chez qui penser à la pyridoxine (B6) ?","back":"**Femme enceinte**, **alcoolique chronique**, **dénutri** (prévention de la polyneuropathie).","prio":"P2","sec":"s8"},{"id":"fc-p159-7d7554","poly":"pneumo","fiche":"p159","front":"Tuberculose : quel est l'enjeu de l'observance ?","back":"Elle conditionne le risque de **rechute** et de **souches résistantes**.","prio":"P2","sec":"s8"},{"id":"fc-p159-be07ab","poly":"pneumo","fiche":"p159","front":"Tuberculose : quelle prise en charge financière demander ?","back":"**100 %** au titre de l'**ALD n° 29**.","prio":"P2","sec":"s8"},{"id":"fc-p159-61ec53","poly":"pneumo","fiche":"p159","front":"Tuberculose traitée : quels 3 axes de suivi ?","back":"**Efficacité**, **tolérance**, **observance**.","prio":"P2","sec":"s8"},{"id":"fc-p159-0c4c7b","poly":"pneumo","fiche":"p159","front":"Tuberculose traitée : à quelles échéances le contrôle clinique ?","back":"**J15, M1, M2, M4, M6, M9, M12**.","prio":"P3","sec":"s8"},{"id":"fc-p159-4b8f52","poly":"pneumo","fiche":"p159","front":"Tuberculose traitée : à quelles échéances le contrôle bactériologique ?","back":"**J15, M1**, puis jusqu'à **négativation**.","prio":"P2","sec":"s8"},{"id":"fc-p159-ac71de","poly":"pneumo","fiche":"p159","front":"Tuberculose traitée : quel rythme d'imagerie en pratique ?","back":"OMS : M1, M2, M6, M12, M18, puis 2 ans après ; souvent **M6, M12, M24** si évolution clinique satisfaisante.","prio":"P3","sec":"s8"},{"id":"fc-p159-86ac00","poly":"pneumo","fiche":"p159","front":"Antituberculeux : quel rythme du bilan hépatique ?","back":"**Chaque semaine le 1er mois**, puis selon le terrain ; éduquer aux signes d'insuffisance hépatocellulaire.","prio":"P1","sec":"s8"},{"id":"fc-p159-c8c756","poly":"pneumo","fiche":"p159","front":"Éthambutol prolongé : quelle surveillance ophtalmologique ?","back":"**Vision des couleurs tous les mois** pendant les premiers mois.","prio":"P2","sec":"s8"},{"id":"fc-p159-09674b","poly":"pneumo","fiche":"p159","front":"Rifampicine et contraception œstroprogestative : quelle conduite ?","back":"Pilule **inefficace** : passer à une **contraception mécanique**.","prio":"P1","sec":"s8"},{"id":"fc-p159-2d26a8","poly":"pneumo","fiche":"p159","front":"Troubles digestifs importants sous antituberculeux : que dire au patient ?","back":"Le traitement peut être **adapté**.","prio":"P3","sec":"s8"},{"id":"fc-p159-b46e2b","poly":"pneumo","fiche":"p159","front":"Contre-indication au pyrazinamide : quel schéma antituberculeux ?","back":"**2 mois INH + RMP + EMB**, puis **7 mois INH + RMP** (**9 mois**).","prio":"P1","sec":"s9"},{"id":"fc-p159-ad1e87","poly":"pneumo","fiche":"p159","front":"Schéma de 9 mois sans pyrazinamide : quelles indications ?","back":"**CI au PZA** (insuffisance hépatocellulaire ou rénale) ou **effet indésirable grave** ; transaminases 3-5N.","prio":"P2","sec":"s9"},{"id":"fc-p159-c09b54","poly":"pneumo","fiche":"p159","front":"Transaminases < 3N sous antituberculeux : quelle conduite ?","back":"**Surveillance rapprochée** jusqu'à normalisation.","prio":"P1","sec":"s10"},{"id":"fc-p159-91e093","poly":"pneumo","fiche":"p159","front":"Transaminases entre 3 et 5N sous antituberculeux : quelle conduite ?","back":"**Arrêt du PZA** ; poursuite INH + RMP + EMB (2 mois) puis INH + RMP (7 mois).","prio":"P1","sec":"s10"},{"id":"fc-p159-75cc18","poly":"pneumo","fiche":"p159","front":"Transaminases > 5N sous antituberculeux : quelle conduite ?","back":"**Arrêt INH et PZA** ; après normalisation, essai de réintroduction de l'INH à **demi-dose** avec dosages sériques.","prio":"P1","sec":"s10"},{"id":"fc-p159-b56adf","poly":"pneumo","fiche":"p159","front":"Cytolyse majeure ou signe de gravité sous antituberculeux : quelle conduite ?","back":"**Arrêt de tous** les antituberculeux, **pharmacovigilance**, avis spécialisé (2e ligne).","prio":"P1","sec":"s10"},{"id":"fc-p159-555ebe","poly":"pneumo","fiche":"p159","front":"Tuberculose pulmonaire suspectée chez un hospitalisé : quand isoler ?","back":"**Chambre seule + isolement respiratoire** avant même les prélèvements.","prio":"P1","sec":"s11"},{"id":"fc-p159-701736","poly":"pneumo","fiche":"p159","front":"Tuberculose contagieuse au diagnostic : depuis combien de temps l'est-elle en général ?","back":"Depuis **3 mois** : l'entourage proche a pu être contaminé.","prio":"P1","sec":"s11"},{"id":"fc-p159-89e4f4","poly":"pneumo","fiche":"p159","front":"Tuberculose à examens directs négatifs au départ : quand lever l'isolement ?","back":"En général après **15 jours de traitement plein**.","prio":"P1","sec":"s11"},{"id":"fc-p159-d69fc1","poly":"pneumo","fiche":"p159","front":"Isolement respiratoire tuberculeux : quand le prolonger ?","back":"Forme **très bacillifère**, ou **enfants, personnes âgées, immunodéprimés** au domicile.","prio":"P2","sec":"s11"},{"id":"fc-p159-ba9b14","poly":"pneumo","fiche":"p159","front":"Tuberculose : est-ce une maladie à déclaration obligatoire ?","back":"**Oui**.","prio":"P1","sec":"s12"},{"id":"fc-p159-2352cf","poly":"pneumo","fiche":"p159","front":"Déclaration obligatoire de tuberculose : à qui et sous quelle forme ?","back":"**ARS**, formulaire en ligne **anonyme**, transmis à Santé publique France.","prio":"P1","sec":"s12"},{"id":"fc-p159-e877d0","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie : quand la déclarer ?","back":"Confirmée ou suspectée, **dès qu'un traitement est débuté**, même **sans preuve bactériologique**.","prio":"P1","sec":"s12"},{"id":"fc-p159-8188eb","poly":"pneumo","fiche":"p159","front":"ITL : dans quel cas est-elle à déclaration obligatoire ?","back":"Chez l'enfant ou le jeune de **moins de 18 ans** (depuis 2021 ; avant, 15 ans).","prio":"P1","sec":"s12"},{"id":"fc-p159-5112ad","poly":"pneumo","fiche":"p159","front":"Déclaration de l'ITL de l'enfant : quel objectif ?","back":"Retrouver le **contaminateur**.","prio":"P2","sec":"s12"},{"id":"fc-p159-125883","poly":"pneumo","fiche":"p159","front":"Signalement au CLAT : quelles caractéristiques ?","back":"**Nominatif**, simultané à la DO, par tout moyen, sans formulaire ; il lance l'**enquête autour du cas**.","prio":"P1","sec":"s12"},{"id":"fc-p159-ea9dad","poly":"pneumo","fiche":"p159","front":"Enquête autour d'un cas de tuberculose : qu'est-ce qu'un sujet contact ?","back":"Adulte ou enfant ayant eu des contacts **répétés et rapprochés** avec le cas index (même pièce, distance de conversation).","prio":"P2","sec":"s12"},{"id":"fc-p159-57465e","poly":"pneumo","fiche":"p159","front":"Sujet contact : de quoi dépend le risque d'infection tuberculeuse ?","back":"**Contagiosité** du cas, **période contagieuse** (3 mois avant le diagnostic), **proximité**, confinement, durée.","prio":"P2","sec":"s12"},{"id":"fc-p159-6726af","poly":"pneumo","fiche":"p159","front":"Contact étroit d'un cas de tuberculose : quelle définition ?","back":"**Même lieu fermé plusieurs heures par jour** (famille, classe, bureau, cellule).","prio":"P2","sec":"s12"},{"id":"fc-p159-3f4451","poly":"pneumo","fiche":"p159","front":"Contact régulier vs occasionnel d'un cas de tuberculose : quelle différence ?","back":"Régulier : même lieu fermé **de façon répétée** (cantine, club) ; occasionnel : **ponctuel** (dîner).","prio":"P3","sec":"s12"},{"id":"fc-p159-a22913","poly":"pneumo","fiche":"p159","front":"Enquête autour d'un cas de tuberculose : quels contacts dépister systématiquement ?","back":"Seulement les contacts **étroits et réguliers**.","prio":"P1","sec":"s12"},{"id":"fc-p159-783164","poly":"pneumo","fiche":"p159","front":"Sujet contact : quel premier temps de dépistage ?","back":"Dès que possible, rechercher une **tuberculose maladie** : clinique, évaluation des risques, **radiographie thoracique**.","prio":"P2","sec":"s12"},{"id":"fc-p159-ef151b","poly":"pneumo","fiche":"p159","front":"Sujet contact : quand rechercher une ITL ?","back":"**8 semaines après le dernier contact**, par **IGRA ou IDR**.","prio":"P1","sec":"s12"},{"id":"fc-p159-a5f82f","poly":"pneumo","fiche":"p159","front":"Traitement de l'ITL : quel objectif ?","back":"Limiter le **passage de l'ITL à la tuberculose maladie**.","prio":"P2","sec":"s13"},{"id":"fc-p159-afad63","poly":"pneumo","fiche":"p159","front":"ITL : chez qui la rechercher (pour la traiter) ?","back":"ITL **récente < 2 ans** (contacts) ; **migrant < 18 ans** arrivé < 5 ans de forte incidence ; **avant immunosuppresseur** ; **VIH** découvert.","prio":"P1","sec":"s13"},{"id":"fc-p159-6d7d70","poly":"pneumo","fiche":"p159","front":"Avant de faire une IDR ou un IGRA : que faut-il éliminer ?","back":"Une **tuberculose maladie** (clinique, radiographie thoracique).","prio":"P1","sec":"s13"},{"id":"fc-p159-84e3a7","poly":"pneumo","fiche":"p159","front":"IDR et IGRA : distinguent-ils ITL et tuberculose maladie ?","back":"**Non** : ils servent **uniquement au diagnostic d'ITL**.","prio":"P1","sec":"s13"},{"id":"fc-p159-35217a","poly":"pneumo","fiche":"p159","front":"IDR à la tuberculine : quelles modalités de réalisation et de lecture ?","back":"**0,1 ml** de tuberculine intradermique ; lecture à **72 h** de l'**induration** (pas l'érythème).","prio":"P1","sec":"s13"},{"id":"fc-p159-81b815","poly":"pneumo","fiche":"p159","front":"IDR : quel seuil de positivité ?","back":"Négative **< 5 mm** ; positive **≥ 5 mm**.","prio":"P1","sec":"s13"},{"id":"fc-p159-5a865b","poly":"pneumo","fiche":"p159","front":"IDR : quels seuils font suspecter une ITL ?","back":"**> 10 mm** sans BCG ; **> 15 mm** si vacciné ; ou **virage** (+10 mm entre deux IDR à 3 mois).","prio":"P1","sec":"s13"},{"id":"fc-p159-ee0b05","poly":"pneumo","fiche":"p159","front":"IGRA : quel avantage sur l'IDR ?","back":"Pas de **réaction croisée avec le BCG** : moins de faux positifs.","prio":"P1","sec":"s13"},{"id":"fc-p159-fa441a","poly":"pneumo","fiche":"p159","front":"IGRA : quel principe ?","back":"Production d'**interféron gamma** par les lymphocytes au contact d'antigènes spécifiques de M. tuberculosis.","prio":"P2","sec":"s13"},{"id":"fc-p159-003064","poly":"pneumo","fiche":"p159","front":"IGRA : dans quelles indications est-il pris en charge ?","back":"Migrants **< 15 ans** de zone d'endémie, **VIH**, **avant anti-TNF**, contacts **≥ 15 ans**.","prio":"P2","sec":"s13"},{"id":"fc-p159-4e68ce","poly":"pneumo","fiche":"p159","front":"IDR : pourquoi peut-elle être faussement négative ?","back":"**Anergie tuberculinique**, notamment en cas d'**immunodépression**.","prio":"P1","sec":"s13"},{"id":"fc-p159-8e423f","poly":"pneumo","fiche":"p159","front":"IDR et BCG : quel problème d'interprétation ?","back":"Réaction croisée (M. bovis) : interprétation difficile dans les **10 ans** suivant le BCG.","prio":"P2","sec":"s13"},{"id":"fc-p159-3cbbd3","poly":"pneumo","fiche":"p159","front":"IGRA : quels avantages pratiques ?","back":"Prise de sang, **non opérateur-dépendante**, **une seule visite**.","prio":"P3","sec":"s13"},{"id":"fc-p159-59c286","poly":"pneumo","fiche":"p159","front":"IGRA : quels résultats possibles ?","back":"**Positif**, **négatif** ou **indéterminé**.","prio":"P3","sec":"s13"},{"id":"fc-p159-d0a234","poly":"pneumo","fiche":"p159","front":"IGRA : citer les deux tests disponibles.","back":"**QuantiFERON-TB Gold IT** et **T-SPOT.TB**.","prio":"P3","sec":"s13"},{"id":"fc-p159-95a32f","poly":"pneumo","fiche":"p159","front":"Chimioprophylaxie primaire : chez qui ?","back":"**Enfant < 2 ans** ou **très immunodéprimé** exposé, traité **avant le résultat des tests** (maladie éliminée).","prio":"P1","sec":"s13"},{"id":"fc-p159-25cf56","poly":"pneumo","fiche":"p159","front":"Chimioprophylaxie secondaire : quelles indications ?","back":"Toute **ITL avant 18 ans** ; après 18 ans si **immunodépression** ou **ITL récente** (< 2 ans).","prio":"P1","sec":"s13"},{"id":"fc-p159-826085","poly":"pneumo","fiche":"p159","front":"Traitement de l'ITL en monothérapie : quel schéma ?","back":"**Isoniazide 5 mg/kg/j pendant 6 mois**.","prio":"P1","sec":"s13"},{"id":"fc-p159-f997ad","poly":"pneumo","fiche":"p159","front":"Traitement de l'ITL en bithérapie : quel schéma ?","back":"**INH 4-5 mg/kg/j + RMP 10 mg/kg/j pendant 3 à 4 mois**.","prio":"P1","sec":"s13"},{"id":"fc-p159-81a9e5","poly":"pneumo","fiche":"p159","front":"Chimioprophylaxie de l'ITL : quelle surveillance ?","back":"**Même** que pour la tuberculose maladie (bilan hépatique, interactions de la RMP, information).","prio":"P2","sec":"s13"},{"id":"fc-p159-3638d3","poly":"pneumo","fiche":"p159","front":"IGRA à l'embauche d'un personnel exposé : est-il remboursé ?","back":"**Non** : médicalement justifié mais **non pris en charge**.","prio":"P3","sec":"s13"},{"id":"fc-p159-1f16ad","poly":"pneumo","fiche":"p159","front":"Tuberculose et grossesse : faut-il modifier le schéma ?","back":"**Non** (pas de tératogénicité connue) ; même schéma selon le CRAT.","prio":"P2","sec":"s14"},{"id":"fc-p159-73473f","poly":"pneumo","fiche":"p159","front":"Grossesse sous isoniazide : quelle supplémentation ?","back":"**Vitamine B6** chez la mère.","prio":"P2","sec":"s14"},{"id":"fc-p159-f5f16a","poly":"pneumo","fiche":"p159","front":"Rifampicine au 3e trimestre de grossesse : quel risque et quelle prévention ?","back":"**Hémorragie** maternelle et néonatale précoce : **vitamine K1**.","prio":"P2","sec":"s14"},{"id":"fc-p159-6cd5f0","poly":"pneumo","fiche":"p159","front":"Tuberculose et allaitement : sous quelles molécules est-il déconseillé ?","back":"**Éthambutol** et **pyrazinamide** (cas par cas).","prio":"P3","sec":"s14"},{"id":"fc-p159-aa8b39","poly":"pneumo","fiche":"p159","front":"Tuberculose et insuffisance rénale : à partir de quelle clairance le schéma est-il standard ?","back":"Clairance **> 30 mL/min** ; doses d'INH selon le test d'acétylation.","prio":"P3","sec":"s14"},{"id":"fc-p159-7d286f","poly":"pneumo","fiche":"p159","front":"Pyrazinamide et insuffisance rénale : quelles formulations du Collège ?","back":"**Contre-indication** (p. 59) et « **à adapter** » selon la clairance (p. 64).","prio":"P2","sec":"s14"},{"id":"fc-p159-88bf01","poly":"pneumo","fiche":"p159","front":"Hépatopathie préexistante : peut-on débuter le schéma antituberculeux standard ?","back":"**Oui**, tant que les transaminases restent **< 3N**.","prio":"P2","sec":"s14"},{"id":"fc-p159-ad9ec0","poly":"pneumo","fiche":"p159","front":"Avant un anti-TNF ou une greffe : que rechercher ?","back":"Une **ITL** (interrogatoire, examen, radiographie ; **IGRA préféré** à l'IDR).","prio":"P1","sec":"s15"},{"id":"fc-p159-6a866c","poly":"pneumo","fiche":"p159","front":"Tuberculose active et projet d'anti-TNF : quand débuter l'anti-TNF ?","back":"Pas avant la **fin de la phase d'attaque** (2 mois de quadrithérapie).","prio":"P2","sec":"s15"},{"id":"fc-p159-b799ad","poly":"pneumo","fiche":"p159","front":"ITL avant un anti-TNF : quelle chimioprophylaxie ?","back":"**INH + RMP 3 mois**, débutée **≥ 3 semaines avant** l'anti-TNF, quelle que soit l'ancienneté de l'ITL.","prio":"P2","sec":"s15"},{"id":"fc-p159-980720","poly":"pneumo","fiche":"p159","front":"Tuberculose MDR : quelle définition ?","back":"Souche résistante à la fois à l'**isoniazide** et à la **rifampicine**.","prio":"P1","sec":"s16"},{"id":"fc-p159-548a8c","poly":"pneumo","fiche":"p159","front":"Tuberculose MDR : quelle fréquence en France ?","back":"Environ **2 %** des cas (moins d'une centaine par an).","prio":"P2","sec":"s16"},{"id":"fc-p159-ea293b","poly":"pneumo","fiche":"p159","front":"Tuberculose résistante : quels facteurs de risque ?","back":"Origine (**ex-URSS, Chine, Inde**), **antécédent de tuberculose** (surtout traitement interrompu), **contact** d'un cas résistant.","prio":"P2","sec":"s16"},{"id":"fc-p159-d565f2","poly":"pneumo","fiche":"p159","front":"Résistance aux antituberculeux : quelle origine ?","back":"Des traitements **mal suivis ou inadaptés**.","prio":"P2","sec":"s16"},{"id":"fc-p159-a643b9","poly":"pneumo","fiche":"p159","front":"Tuberculose MDR : quel traitement ?","back":"Antituberculeux de **2e ligne** associés (fluoroquinolones, **bédaquiline**, **linézolide**) en milieu spécialisé.","prio":"P2","sec":"s16"},{"id":"fc-p159-059061","poly":"pneumo","fiche":"p159","front":"Tuberculose pré-XDR : quelle définition ?","back":"Résistance à **INH, RMP et toutes les fluoroquinolones**.","prio":"P3","sec":"s16"},{"id":"fc-p159-bf27da","poly":"pneumo","fiche":"p159","front":"Tuberculose XDR : quelle définition ?","back":"Pré-XDR + résistance à la **bédaquiline et/ou au linézolide** (mortalité élevée).","prio":"P3","sec":"s16"},{"id":"fc-p159-c2b368","poly":"pneumo","fiche":"p159","front":"Tuberculose XDR en France : quelle fréquence ?","back":"**Exceptionnelle** (moins de 10-20 cas par an).","prio":"P3","sec":"s16"},{"id":"fc-p159-09db42","poly":"pneumo","fiche":"p159","front":"BCG : quels risques réduit-il ?","back":"Tuberculose **neuro-méningée**, **miliaire**, tuberculose pulmonaire.","prio":"P1","sec":"s17"},{"id":"fc-p159-240418","poly":"pneumo","fiche":"p159","front":"BCG : combien de temps dure la protection ?","back":"Elle diminue en **10 à 15 ans**.","prio":"P2","sec":"s17"},{"id":"fc-p159-1b238e","poly":"pneumo","fiche":"p159","front":"BCG : est-il obligatoire chez l'enfant ?","back":"**Non**, il n'est plus obligatoire chez l'enfant et l'adolescent.","prio":"P1","sec":"s17"},{"id":"fc-p159-0acbe6","poly":"pneumo","fiche":"p159","front":"BCG : chez quels enfants est-il fortement recommandé ?","back":"**< 15 ans** : Guyane, Mayotte, **Île-de-France** ; lien avec pays de **forte endémie** ; ATCD familial ; grande précarité.","prio":"P1","sec":"s17"},{"id":"fc-p159-047b8f","poly":"pneumo","fiche":"p159","front":"BCG : à quel âge le faire ?","back":"**Le plus tôt possible**, idéalement **dès la naissance**, sans test tuberculinique préalable.","prio":"P2","sec":"s17"},{"id":"fc-p159-060def","poly":"pneumo","fiche":"p159","front":"BCG non fait à la naissance : jusqu'à quel âge et à quelle condition ?","back":"Possible jusqu'à **15 ans**, après **contrôle du test tuberculinique**.","prio":"P2","sec":"s17"},{"id":"fc-p159-297a45","poly":"pneumo","fiche":"p159","front":"BCG : quelle voie et quel site d'injection ?","back":"**Intradermique** dans le **deltoïde**.","prio":"P2","sec":"s17"},{"id":"fc-p159-e8f17f","poly":"pneumo","fiche":"p159","front":"BCG : quelles contre-indications ?","back":"**VIH** (enfant infecté ou né de mère infectée), **déficit immunitaire**, **immunosuppresseur**, **dermatose étendue évolutive**.","prio":"P1","sec":"s17"},{"id":"fc-p159-55d521","poly":"pneumo","fiche":"p159","front":"BCG : quelles complications possibles ?","back":"Réaction inflammatoire locale, **adénomégalies axillaires**, **BCGite disséminée** (exceptionnelle).","prio":"P2","sec":"s17"},{"id":"fc-p159-8c197c","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie, cas confirmé : quels critères de notification ?","back":"**Culture positive** (complexe tuberculosis), ou **BAAR à la microscopie + détection d'acide nucléique**.","prio":"P2","sec":"s18"},{"id":"fc-p159-ab8fc4","poly":"pneumo","fiche":"p159","front":"Tuberculose maladie, cas probable : quels critères de notification ?","back":"Signes cliniques et/ou radiologiques compatibles + **décision de traiter**.","prio":"P2","sec":"s18"},{"id":"fc-p159-2a98de","poly":"pneumo","fiche":"p159","front":"ITL de l'enfant à déclarer : quels critères IDR sur le formulaire ?","back":"Induration **> 15 mm** si BCG, **> 10 mm** sinon, ou **gain de 10 mm** vs IDR de moins de 2 ans (ou IGRA +).","prio":"P2","sec":"s18"},{"id":"fc-p159-d2b115","poly":"pneumo","fiche":"p159","front":"Issues de traitement de la tuberculose : quand et à qui les déclarer ?","back":"À l'**ARS**, de façon anonyme, **12 mois** après le début du traitement.","prio":"P1","sec":"s18"},{"id":"fc-p159-ac3fec","poly":"pneumo","fiche":"p159","front":"Déclaration des issues de traitement : quel objectif ?","back":"Connaître la part de patients ayant **terminé leur traitement** en 12 mois, et sinon **pourquoi**.","prio":"P2","sec":"s18"},{"id":"fc-p159-cd0acd","poly":"pneumo","fiche":"p159","front":"Formulaire d'issue : quelle définition de « traitement achevé » ?","back":"Patient **guéri** selon le médecin et ayant pris **≥ 80 %** de la dose totale prescrite.","prio":"P3","sec":"s18"},{"id":"fc-p159-602364","poly":"pneumo","fiche":"p159","front":"Déclaration initiale de tuberculose : faut-il attendre culture et antibiogramme ?","back":"**Non**, envoyer la fiche sans attendre.","prio":"P2","sec":"s18"},{"id":"fc-p159-049297","poly":"pneumo","fiche":"p159","front":"Formulaire à 12 mois : quelles issues possibles ?","back":"Traitement **achevé** ; **non achevé** (décès, arrêt, toujours traité) ; issue **inconnue** (transfert, perdu de vue).","prio":"P3","sec":"s18"},{"id":"fc-p186-91e27d","poly":"pneumo","fiche":"p186","front":"Hypersensibilité : quelle définition ?","back":"Symptômes **objectifs et reproductibles** déclenchés par un stimulus précis, à une dose **tolérée par les sujets sains**.","prio":"P1","sec":"s1"},{"id":"fc-p186-d22680","poly":"pneumo","fiche":"p186","front":"Hypersensibilité : quelles sont les 2 grandes familles ?","back":"**Allergique** (mécanisme immunologique prouvé) et **non allergique**.","prio":"P1","sec":"s1"},{"id":"fc-p186-70a526","poly":"pneumo","fiche":"p186","front":"Atopie : quelle définition ?","back":"Prédisposition **héréditaire** à produire des **IgE** face à de faibles doses d'allergènes (origine génétique et environnementale).","prio":"P1","sec":"s1"},{"id":"fc-p186-7f8b51","poly":"pneumo","fiche":"p186","front":"Atopie : de quelles maladies est-elle un facteur de risque ?","back":"Hypersensibilité immédiate : **asthme**, **rhino-conjonctivite**, **dermatite**.","prio":"P2","sec":"s1"},{"id":"fc-p186-9c6e6e","poly":"pneumo","fiche":"p186","front":"Sensibilisation : quelle définition ?","back":"**Test cutané positif** et/ou **IgE spécifiques** positives vis-à-vis d'un allergène.","prio":"P1","sec":"s1"},{"id":"fc-p186-739103","poly":"pneumo","fiche":"p186","front":"Sensibilisation : présage-t-elle une réaction clinique ?","back":"**Non** : on peut être **sensibilisé sans être allergique**.","prio":"P1","sec":"s1"},{"id":"fc-p186-f42995","poly":"pneumo","fiche":"p186","front":"Allergie : quelle définition ?","back":"Réaction clinique d'hypersensibilité chez un sujet **déjà sensibilisé** sur le plan immunologique.","prio":"P1","sec":"s1"},{"id":"fc-p186-e35534","poly":"pneumo","fiche":"p186","front":"Allergie : par quels effecteurs est-elle médiée ?","back":"Par des **anticorps** ou par des **cellules**.","prio":"P3","sec":"s1"},{"id":"fc-p186-612710","poly":"pneumo","fiche":"p186","front":"Allergène : quelle définition ?","back":"Antigène capable de provoquer une réaction d'**hypersensibilité allergique**.","prio":"P2","sec":"s1"},{"id":"fc-p186-cbdb44","poly":"pneumo","fiche":"p186","front":"Pneumallergènes : de quoi s'agit-il ?","back":"Allergènes **transportés par l'air**, inhalés (nez, bronches) ou au contact des yeux.","prio":"P2","sec":"s1"},{"id":"fc-p186-de00e1","poly":"pneumo","fiche":"p186","front":"Trophallergènes : de quoi s'agit-il ?","back":"Allergènes des **aliments** (allergie alimentaire).","prio":"P2","sec":"s1"},{"id":"fc-p186-739aa1","poly":"pneumo","fiche":"p186","front":"Hausse des maladies allergiques : quelle hypothèse sur la barrière épithéliale ?","back":"Lésions de la **barrière épithéliale** par des agents nocifs liés à l'**industrialisation**, l'urbanisation et le mode de vie moderne.","prio":"P3","sec":"s1"},{"id":"fc-p186-51000d","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : quels sont ses 4 composants ?","back":"Un **allergène** + une réaction passant par les **IgE** + une **inflammation** rhino-sinusienne et/ou bronchique + des **symptômes**.","prio":"P3","sec":"s1"},{"id":"fc-p186-0d8612","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 1 : quel effecteur et quel mécanisme ?","back":"**IgE** fixées sur **mastocytes et basophiles**, activés à l'entrée de l'allergène (réaction **immédiate**).","prio":"P2","sec":"s2"},{"id":"fc-p186-e79182","poly":"pneumo","fiche":"p186","front":"Quel type d'hypersensibilité est le plus souvent en cause dans l'allergie ?","back":"Le **type 1** (immédiat, IgE-médié).","prio":"P2","sec":"s2"},{"id":"fc-p186-49f3fb","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 1 : exemples ?","back":"**Rhinite allergique**, **anaphylaxie alimentaire**.","prio":"P3","sec":"s2"},{"id":"fc-p186-611ee0","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 2 : effecteurs, mécanisme et exemple ?","back":"**IgG ou IgM** → destruction d'une cellule cible (complément, phagocytose) ; ex. **cytopénie médicamenteuse**.","prio":"P3","sec":"s2"},{"id":"fc-p186-ec7365","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 3 : mécanisme et exemples ?","back":"Dépôt de **complexes immuns** circulants dans les tissus ; ex. **pneumopathies d'hypersensibilité**, maladie sérique.","prio":"P3","sec":"s2"},{"id":"fc-p186-b41656","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 4 : effecteur et délai ?","back":"**Lymphocytes T** ; réaction **retardée** de **48-72 heures**.","prio":"P3","sec":"s2"},{"id":"fc-p186-5c0a9a","poly":"pneumo","fiche":"p186","front":"Hypersensibilité de type 4 : quelle lésion habituelle et quels exemples ?","back":"**Granulome épithélioïde et giganto-cellulaire** ; ex. **eczéma de contact**, certaines allergies médicamenteuses.","prio":"P3","sec":"s2"},{"id":"fc-p186-d01b04","poly":"pneumo","fiche":"p186","front":"Asthme : est-il monogénique ?","back":"**Non**, maladie hétérogène **polygénique** (aucun gène seul responsable).","prio":"P3","sec":"s2"},{"id":"fc-p186-fbfaf0","poly":"pneumo","fiche":"p186","front":"Risque d'asthme chez l'enfant selon les parents ?","back":"**10 %** si aucun parent asthmatique ; **25 %** si un parent ; **> 50 %** si les deux.","prio":"P3","sec":"s2"},{"id":"fc-p186-113535","poly":"pneumo","fiche":"p186","front":"Asthme : quels sont les 2 grands facteurs favorisants ?","back":"**Infections virales** et **sensibilisation aux pneumallergènes**.","prio":"P3","sec":"s2"},{"id":"fc-p186-6e1768","poly":"pneumo","fiche":"p186","front":"Asthme : quels 2 autres facteurs favorisants clairement identifiés ?","back":"**Tabac dès la conception** et **pollution de l'air intérieur**.","prio":"P3","sec":"s2"},{"id":"fc-p186-1d9dfb","poly":"pneumo","fiche":"p186","front":"Maladies allergiques : quel facteur néonatal pourrait majorer le risque ?","back":"Une **altération du microbiote** du nouveau-né.","prio":"P3","sec":"s2"},{"id":"fc-p186-b01a24","poly":"pneumo","fiche":"p186","front":"Réaction à IgE : que se passe-t-il au 1er contact avec l'allergène ?","back":"Phase de **sensibilisation**, **sans symptôme** : production d'IgE spécifiques.","prio":"P3","sec":"s2"},{"id":"fc-p186-9cd69a","poly":"pneumo","fiche":"p186","front":"Réaction à IgE : que se passe-t-il lors du contact suivant ?","back":"Phase **effectrice** : l'allergène se lie aux IgE des **mastocytes/basophiles**, qui libèrent leurs médiateurs.","prio":"P3","sec":"s2"},{"id":"fc-p186-cf10b9","poly":"pneumo","fiche":"p186","front":"Mastocytes activés : quels médiateurs libèrent-ils ?","back":"Préformés (**histamine**, protéases) ; néoformés (**prostaglandines**, **leucotriènes**) ; chimiokines et cytokines.","prio":"P3","sec":"s2"},{"id":"fc-p186-5bfced","poly":"pneumo","fiche":"p186","front":"Médiateurs de la réaction allergique : quels effets ?","back":"**Bronchoconstriction**, **vasodilatation**, extravasation, **œdème**.","prio":"P3","sec":"s2"},{"id":"fc-p186-4ec181","poly":"pneumo","fiche":"p186","front":"Asthme allergique : quel profil d'inflammation bronchique, avec quelles cytokines ?","back":"Souvent **profil T2** : **IL-4, IL-5, IL-13**.","prio":"P3","sec":"s2"},{"id":"fc-p186-1cdde4","poly":"pneumo","fiche":"p186","front":"IL-4 et IL-13 : quel effet sur les lymphocytes B ?","back":"**Commutation isotypique** vers la production d'**IgE**.","prio":"P3","sec":"s2"},{"id":"fc-p186-8f2c46","poly":"pneumo","fiche":"p186","front":"Remodelage bronchique : quelles anomalies de structure ?","back":"Épithélium anormal, **membrane basale épaissie**, œdème, **hyperplasie/hypertrophie musculaire lisse**, hypersécrétion de mucus.","prio":"P3","sec":"s2"},{"id":"fc-p186-ad3ceb","poly":"pneumo","fiche":"p186","front":"Remodelage bronchique : est-il propre à l'asthme allergique ?","back":"**Non** ; il accompagne la **chronicité** de l'asthme.","prio":"P3","sec":"s2"},{"id":"fc-p186-a28241","poly":"pneumo","fiche":"p186","front":"Atopie : quelle part de la population française est sensibilisée à au moins un allergène ?","back":"**30 à 40 %**.","prio":"P1","sec":"s3"},{"id":"fc-p186-b27385","poly":"pneumo","fiche":"p186","front":"Allergies respiratoires en Europe : quelle évolution de prévalence ?","back":"**Doublée en 20 ans**, par évolution des expositions environnementales.","prio":"P2","sec":"s3"},{"id":"fc-p186-617c01","poly":"pneumo","fiche":"p186","front":"Hausse des allergies : quels facteurs d'environnement sont évoqués ?","back":"Habitudes **alimentaires**, **tabagisme passif** (avant et après la naissance), environnement allergénique, **pollution atmosphérique**.","prio":"P2","sec":"s3"},{"id":"fc-p186-9302c0","poly":"pneumo","fiche":"p186","front":"Théorie hygiéniste : que dit-elle ?","back":"Moins de **contacts infectieux** ↔ plus de maladies **allergiques et auto-immunes** ; on accuse plutôt la **baisse de biodiversité**.","prio":"P2","sec":"s3"},{"id":"fc-p186-4b26ef","poly":"pneumo","fiche":"p186","front":"Atopie : chez quels enfants est-elle moins fréquente ?","back":"**Derniers de fratrie**, enfants passés par la **crèche**, enfants élevés à la **campagne** (endotoxines bactériennes).","prio":"P2","sec":"s3"},{"id":"fc-p186-4edb97","poly":"pneumo","fiche":"p186","front":"Asthme : combien de décès par an en France ?","back":"Environ **1000** ; mortalité en baisse mais plus forte dans les milieux **défavorisés**.","prio":"P1","sec":"s3"},{"id":"fc-p186-b20ef8","poly":"pneumo","fiche":"p186","front":"Décès par asthme : sont-ils évitables et pourquoi surviennent-ils ?","back":"Beaucoup sont **évitables** (surtout sujet jeune) ; semblent liés à : absence/mauvaise **observance du traitement de fond**, crise mal gérée, recours **trop tardif** aux soins.","prio":"P1","sec":"s3"},{"id":"fc-p186-36947b","poly":"pneumo","fiche":"p186","front":"Asthme en France : quel coût ?","back":"**1,5 milliard d'euros** (65 % coûts directs, 35 % indirects).","prio":"P3","sec":"s3"},{"id":"fc-p186-b1b5c3","poly":"pneumo","fiche":"p186","front":"Venins d'hyménoptères : part de la population sensibilisée et faisant des réactions systémiques ?","back":"**10 à 40 %** sensibilisés ; réactions systémiques chez **0,3 à 7,5 %**.","prio":"P3","sec":"s3"},{"id":"fc-p186-b3e5a9","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : quelle prévalence chez l'adulte ?","back":"Environ **2 %** (pic 6,8 % entre 6 et 10 ans).","prio":"P3","sec":"s3"},{"id":"fc-p186-e1de14","poly":"pneumo","fiche":"p186","front":"Chocs anaphylactiques : quelle part est d'origine alimentaire ?","back":"**10 à 41 %**.","prio":"P3","sec":"s3"},{"id":"fc-p186-0d2772","poly":"pneumo","fiche":"p186","front":"Allergie médicamenteuse : quelle prévalence et quel poids dans la mortalité ?","back":"Environ **7 %** ; la plupart des **décès par anaphylaxie de l'adulte** en France sont médicamenteux.","prio":"P3","sec":"s3"},{"id":"fc-p186-cc09e5","poly":"pneumo","fiche":"p186","front":"Allergies respiratoires : quelles sont les 2 expressions principales ?","back":"**Asthme** et/ou **rhinite** (ou rhino-conjonctivite).","prio":"P1","sec":"s4"},{"id":"fc-p186-6bb5d9","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : quel délai entre contact et symptômes ?","back":"**Quelques minutes à quelques heures**.","prio":"P1","sec":"s4"},{"id":"fc-p186-31f3dd","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : quel argument d'interrogatoire est le plus évocateur ?","back":"Relation **forte** exposition-symptômes, avec **unité de temps et de lieu**.","prio":"P1","sec":"s4"},{"id":"fc-p186-729b20","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : comment se fait le diagnostic de rhinite ?","back":"Il est **clinique**.","prio":"P1","sec":"s4"},{"id":"fc-p186-fc38f2","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quels symptômes (acronyme) ?","back":"**PAREO** : **P**rurit, **A**nosmie, **R**hinorrhée, **É**ternuements, **O**bstruction nasale.","prio":"P1","sec":"s4"},{"id":"fc-p186-a7f0c6","poly":"pneumo","fiche":"p186","front":"Rhinite : quel examen des fosses nasales et que chercher ?","back":"**Spéculum** (à défaut otoscope) : muqueuse inflammatoire, recherche de **polypes**.","prio":"P3","sec":"s4"},{"id":"fc-p186-7363ac","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quand est-elle dite intermittente ou persistante ?","back":"Intermittente **≤ 4 semaines** consécutives/an ; persistante **> 4 semaines**.","prio":"P1","sec":"s4"},{"id":"fc-p186-4c4533","poly":"pneumo","fiche":"p186","front":"Rhinite allergique sévère : quels critères (au moins 1) ?","back":"**Sommeil perturbé** ; activités sociales/sportives/professionnelles/scolaires **perturbées** ; symptômes **gênants**.","prio":"P1","sec":"s4"},{"id":"fc-p186-91688c","poly":"pneumo","fiche":"p186","front":"Symptômes allergiques toute l'année : quels allergènes évoquer ?","back":"Allergènes d'**intérieur** : **acariens**, blattes, **phanères d'animaux**, **moisissures**.","prio":"P2","sec":"s4"},{"id":"fc-p186-de0d5d","poly":"pneumo","fiche":"p186","front":"Symptômes allergiques saisonniers : quels allergènes évoquer ?","back":"Allergènes d'**extérieur** : **pollens** (arbres, **graminées**, herbacées) ; certaines moisissures (*Alternaria*).","prio":"P2","sec":"s4"},{"id":"fc-p186-0de6b5","poly":"pneumo","fiche":"p186","front":"Pollens : lesquels sont les plus ubiquitaires ?","back":"Les **graminées**.","prio":"P3","sec":"s4"},{"id":"fc-p186-15c0a8","poly":"pneumo","fiche":"p186","front":"Alternaria alternata : quel cycle et quelle implication ?","back":"Moisissure atmosphérique à **cycle estival**, impliquée aussi dans l'**asthme**.","prio":"P3","sec":"s4"},{"id":"fc-p186-c4b3d2","poly":"pneumo","fiche":"p186","front":"Allergie professionnelle du boulanger-pâtissier : quels allergènes ?","back":"**Blé** et **acarien de la farine**.","prio":"P2","sec":"s4"},{"id":"fc-p186-9733d0","poly":"pneumo","fiche":"p186","front":"Allergie professionnelle des soignants : quels allergènes ?","back":"**Latex**, **aldéhydes**, **ammoniums**.","prio":"P2","sec":"s4"},{"id":"fc-p186-6c1eb0","poly":"pneumo","fiche":"p186","front":"Allergie professionnelle : allergènes du coiffeur et du peintre ?","back":"Coiffeur : **persulfates** ; peintre : **isocyanates**.","prio":"P2","sec":"s4"},{"id":"fc-p186-4116dc","poly":"pneumo","fiche":"p186","front":"Allergie professionnelle : allergènes des agents d'entretien et des travailleurs du bois ?","back":"Entretien : **ammoniums** ; bois : **poussières**, **moisissures**.","prio":"P3","sec":"s4"},{"id":"fc-p186-630170","poly":"pneumo","fiche":"p186","front":"Allergie professionnelle : chez quels patients faut-il la rechercher systématiquement ?","back":"Chez **tout asthmatique** (recherche **systématique**).","prio":"P1","sec":"s4"},{"id":"fc-p186-b8ee7b","poly":"pneumo","fiche":"p186","front":"Asthme professionnel : comment le diagnostiquer ?","back":"Montrer un **lien** entre symptômes d'asthme et **exposition au travail**.","prio":"P2","sec":"s4"},{"id":"fc-p186-75a69b","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : quelles sont les 3 conditions du diagnostic ?","back":"**Clinique évocatrice** + **sensibilisation IgE** prouvée + **lien de cause à effet** exposition-symptômes.","prio":"P1","sec":"s5"},{"id":"fc-p186-8dd63d","poly":"pneumo","fiche":"p186","front":"Asthme : l'enquête allergologique est-elle systématique ?","back":"**Oui** (SPLF 2021).","prio":"P1","sec":"s5"},{"id":"fc-p186-d217b8","poly":"pneumo","fiche":"p186","front":"Sensibilisation IgE : quel examen de référence en 1re intention ?","back":"Le **prick-test** à lecture immédiate (SPLF 2021).","prio":"P2","sec":"s5"},{"id":"fc-p186-3ca3b4","poly":"pneumo","fiche":"p186","front":"Prick-test : quel mécanisme produit la réaction ?","back":"L'allergène se fixe sur les IgE des **mastocytes cutanés**, qui dégranulent → petite **plaque d'urticaire**.","prio":"P3","sec":"s5"},{"id":"fc-p186-c21e04","poly":"pneumo","fiche":"p186","front":"Prick-test : où le réaliser ?","back":"Peau saine : **face antérieure de l'avant-bras**, bras, voire tiers supérieur du dos.","prio":"P3","sec":"s5"},{"id":"fc-p186-3d8dc4","poly":"pneumo","fiche":"p186","front":"Prick-test : quand le lire ?","back":"À **15-20 minutes**.","prio":"P2","sec":"s5"},{"id":"fc-p186-a29128","poly":"pneumo","fiche":"p186","front":"Prick-test : critère de positivité ?","back":"Papule + érythème + prurit, papule dépassant de **3 mm** le **témoin négatif**.","prio":"P2","sec":"s5"},{"id":"fc-p186-555bfb","poly":"pneumo","fiche":"p186","front":"Prick-test : quels témoins et à quoi servent-ils ?","back":"Positif = **histamine** (la peau réagit) ; négatif = **sérum physiologique** (positif si dermographisme).","prio":"P3","sec":"s5"},{"id":"fc-p186-c3f412","poly":"pneumo","fiche":"p186","front":"Prick-test : pourquoi le réaliser sous surveillance médicale ?","back":"Effets indésirables très rares (urticaire généralisée, asthme…), **anaphylaxie exceptionnelle** (surtout médicaments).","prio":"P3","sec":"s5"},{"id":"fc-p186-540114","poly":"pneumo","fiche":"p186","front":"IgE spécifiques sanguines : quand les demander ?","back":"En **2e temps** : discordance clinique/prick-tests, ou prick-tests **irréalisables ou ininterprétables**.","prio":"P2","sec":"s5"},{"id":"fc-p186-4268ab","poly":"pneumo","fiche":"p186","front":"IgE spécifiques : vis-à-vis de quoi peut-on les doser ?","back":"D'une **source entière** (extrait complet) ou d'une **protéine précise** (allergène moléculaire).","prio":"P3","sec":"s5"},{"id":"fc-p186-264793","poly":"pneumo","fiche":"p186","front":"IgE spécifiques : par quelles techniques ?","back":"**ELISA**, immunofluorescence ou immuno-chimioluminescence.","prio":"P3","sec":"s5"},{"id":"fc-p186-263ad7","poly":"pneumo","fiche":"p186","front":"Test multi-allergénique sanguin : quel type de réponse ?","back":"**Qualitative** (positif/négatif) : sensibilisation à l'un des allergènes du panel.","prio":"P3","sec":"s5"},{"id":"fc-p186-ffbfc3","poly":"pneumo","fiche":"p186","front":"Test multi-allergénique (Phadiatop®) : quelle place ?","back":"Peu d'indications ; **1re intention pour le non-allergologue** devant une suspicion d'allergie respiratoire.","prio":"P3","sec":"s5"},{"id":"fc-p186-9d614b","poly":"pneumo","fiche":"p186","front":"Test multi-allergénique : quelle performance pour dépister l'atopie ?","back":"Très bonne **sensibilité (> 90 %)**, bonnes VPN et VPP.","prio":"P3","sec":"s5"},{"id":"fc-p186-a66761","poly":"pneumo","fiche":"p186","front":"Allergie : quel examen apporte le diagnostic de certitude ?","back":"Le **test de provocation**.","prio":"P1","sec":"s5"},{"id":"fc-p186-42ac31","poly":"pneumo","fiche":"p186","front":"Test de provocation : quelles conditions d'indication ?","back":"Doute persistant après le bilan de 1re intention **et** résultat modifiant la **conduite thérapeutique**.","prio":"P2","sec":"s5"},{"id":"fc-p186-c364f1","poly":"pneumo","fiche":"p186","front":"Test de provocation : dans quelles allergies surtout ?","back":"**Alimentaires**, **médicamenteuses**, certaines **professionnelles**.","prio":"P2","sec":"s5"},{"id":"fc-p186-da4370","poly":"pneumo","fiche":"p186","front":"Test de provocation : dans quelles conditions de sécurité ?","back":"**Hôpital spécialisé**, surveillance étroite, **chariot d'urgence** à portée, doses croissantes.","prio":"P2","sec":"s5"},{"id":"fc-p186-e9b9c1","poly":"pneumo","fiche":"p186","front":"Provocation nasale ou bronchique : quelles conditions respiratoires ?","back":"Asthme **contrôlé** et **VEMS > 70 %**.","prio":"P1","sec":"s5"},{"id":"fc-p186-b0bea3","poly":"pneumo","fiche":"p186","front":"Allergie : quels examens ne sont pas indiqués pour la diagnostiquer ?","back":"**IgE totales**, **IgG spécifiques**, **éosinophiles** sanguins.","prio":"P1","sec":"s5"},{"id":"fc-p186-1afc1a","poly":"pneumo","fiche":"p186","front":"Tryptase : à quoi sert-elle ?","back":"À confirmer la **dégranulation mastocytaire** d'une anaphylaxie, pas à diagnostiquer une allergie.","prio":"P1","sec":"s5"},{"id":"fc-p186-611b77","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : est-elle fréquente ?","back":"Oui, une des affections oculaires **les plus fréquentes**.","prio":"P2","sec":"s6"},{"id":"fc-p186-504427","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quelle part a des symptômes oculaires, et de quel côté ?","back":"**80 %** ; symptômes **bilatéraux**.","prio":"P1","sec":"s6"},{"id":"fc-p186-2787b1","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : quels signes ?","back":"**Larmoiement**, **rougeur**, **démangeaisons**, caractère **indolore**.","prio":"P1","sec":"s6"},{"id":"fc-p186-260042","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : quels éléments du diagnostic ?","back":"Signes **immédiatement** après le contact + **sensibilisation** prouvée (tests cutanés ou IgE spécifiques).","prio":"P2","sec":"s6"},{"id":"fc-p186-8b5f7e","poly":"pneumo","fiche":"p186","front":"Test de provocation conjonctival : quelle place ?","back":"Réservé à la **recherche**.","prio":"P2","sec":"s6"},{"id":"fc-p186-4820bd","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire avant 6 mois : quel allergène le plus fréquent ?","back":"Le **lait**.","prio":"P1","sec":"s7"},{"id":"fc-p186-1ae0a8","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire de 5 mois à 15 ans : quel allergène le plus fréquent ?","back":"L'**œuf** (puis arachide, lait de vache, moutarde, morue).","prio":"P1","sec":"s7"},{"id":"fc-p186-b30211","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire après 3 ans : quel allergène domine ?","back":"L'**arachide**.","prio":"P1","sec":"s7"},{"id":"fc-p186-0f58b8","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire de l'adulte : quels allergènes ?","back":"**Fruits à coque**, **légumineuses**, certains fruits, **crustacés** (selon les habitudes).","prio":"P2","sec":"s7"},{"id":"fc-p186-2adfbf","poly":"pneumo","fiche":"p186","front":"Quel aliment est le plus souvent en cause dans les anaphylaxies sévères et les décès ?","back":"L'**arachide** (une légumineuse).","prio":"P1","sec":"s7"},{"id":"fc-p186-892008","poly":"pneumo","fiche":"p186","front":"Allergie à l'arachide : fréquence et évolution ?","back":"**1 %** de la population ; persiste en général **toute la vie**.","prio":"P3","sec":"s7"},{"id":"fc-p186-a47bdc","poly":"pneumo","fiche":"p186","front":"Allergie à l'arachide : à quelle autre allergie s'associe-t-elle souvent ?","back":"Aux **fruits à coque** (noix, pistache, cajou, noisette, amande) ; parfois aux légumineuses.","prio":"P3","sec":"s7"},{"id":"fc-p186-b57cb8","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire IgE : quelles étapes du diagnostic ?","back":"**Anamnèse**, **enquête alimentaire**, **prick-tests**, IgE spécifiques en 2e intention, **test de provocation** si besoin.","prio":"P3","sec":"s7"},{"id":"fc-p186-df59a1","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : avec quoi réalise-t-on le plus souvent les prick-tests ?","back":"Avec l'**aliment natif** (plus souvent que des extraits standardisés).","prio":"P3","sec":"s7"},{"id":"fc-p186-14e944","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : que signifient des prick-tests négatifs ?","back":"Ils **excluent en général** l'allergie.","prio":"P3","sec":"s7"},{"id":"fc-p186-72421f","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : quel est le gold standard diagnostique ?","back":"Le **test de provocation**.","prio":"P3","sec":"s7"},{"id":"fc-p186-5130a7","poly":"pneumo","fiche":"p186","front":"Allergies croisées pollen-aliment : quel mécanisme ?","back":"Les IgE reconnaissent des allergènes **homologues** présents dans des sources différentes.","prio":"P3","sec":"s7"},{"id":"fc-p186-a35395","poly":"pneumo","fiche":"p186","front":"Syndrome oral : de quoi s'agit-il ?","back":"Œdème et prurit des **lèvres/langue/bouche/pharynx** après un **fruit cru**, chez un allergique aux **pollens**.","prio":"P3","sec":"s7"},{"id":"fc-p186-189740","poly":"pneumo","fiche":"p186","front":"Allergie croisée : quels aliments chez un allergique au pollen de bouleau ?","back":"**Pomme** et autres fruits et légumes crus.","prio":"P3","sec":"s7"},{"id":"fc-p186-97a2d5","poly":"pneumo","fiche":"p186","front":"Allergie croisée : quels aliments chez un allergique au pollen de cyprès ?","back":"**Pêche**, **agrumes**.","prio":"P3","sec":"s7"},{"id":"fc-p186-39dfaf","poly":"pneumo","fiche":"p186","front":"Allergie croisée : quel aliment chez un sensibilisé aux acariens ?","back":"Les **crustacés** (**crevette**).","prio":"P3","sec":"s7"},{"id":"fc-p186-975f83","poly":"pneumo","fiche":"p186","front":"Syndrome œuf-oiseau : de quoi s'agit-il ?","back":"Allergie à l'**œuf** après sensibilisation respiratoire aux **plumes/déjections d'oiseaux**.","prio":"P3","sec":"s7"},{"id":"fc-p186-f5cc51","poly":"pneumo","fiche":"p186","front":"Venin d'hyménoptères : quels composants et quels effets ?","back":"**Substances vasoactives** (réactions toxiques, non allergiques) ; **enzymes et protéines** (manifestations allergiques).","prio":"P3","sec":"s8"},{"id":"fc-p186-b65408","poly":"pneumo","fiche":"p186","front":"Allergie aux venins : quelle mortalité ?","back":"**Faible** : 0,03 à 0,45 par million d'habitants et par an.","prio":"P3","sec":"s8"},{"id":"fc-p186-46f829","poly":"pneumo","fiche":"p186","front":"Allergie aux venins : quelles étapes du diagnostic ?","back":"**Anamnèse** (insecte), type et chronologie de la réaction, **IDR**, **IgE spécifiques**.","prio":"P3","sec":"s8"},{"id":"fc-p186-de76a4","poly":"pneumo","fiche":"p186","front":"Allergie aux venins : quels tests cutanés ?","back":"Des **intradermoréactions** (IDR).","prio":"P3","sec":"s8"},{"id":"fc-p186-a36714","poly":"pneumo","fiche":"p186","front":"Rhinite : pourquoi argumenter son caractère allergique ?","back":"Les rhinites chroniques **non allergiques** sont **nombreuses**.","prio":"P1","sec":"s9"},{"id":"fc-p186-ac6f9f","poly":"pneumo","fiche":"p186","front":"Rhinite : faut-il une imagerie ?","back":"**Non**, sauf pour chercher un diagnostic **différentiel ou associé**.","prio":"P2","sec":"s9"},{"id":"fc-p186-4775f6","poly":"pneumo","fiche":"p186","front":"L'asthme est-il toujours d'origine allergique ?","back":"**Non**, pas toujours.","prio":"P1","sec":"s9"},{"id":"fc-p186-fa8528","poly":"pneumo","fiche":"p186","front":"Prick-test positif sans symptôme à l'exposition : comment conclure ?","back":"Patient **sensibilisé**, **pas allergique**.","prio":"P1","sec":"s9"},{"id":"fc-p186-43888b","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : quels sont les 2 volets de la prévention secondaire ?","back":"**Éviction** des allergènes identifiés + **traitement des symptômes** (avec éducation thérapeutique).","prio":"P1","sec":"s10"},{"id":"fc-p186-4ecc8a","poly":"pneumo","fiche":"p186","front":"Allergie : où en est la prévention primaire (empêcher la sensibilisation) ?","back":"Elle reste **expérimentale**.","prio":"P2","sec":"s10"},{"id":"fc-p186-45b922","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quel traitement de 1re intention ?","back":"**Lavage nasal** au sérum physiologique + **antihistaminique H1** (oral/local) **ou corticoïde nasal**.","prio":"P1","sec":"s10"},{"id":"fc-p186-e6db1e","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : antihistaminique H1 ou corticoïde nasal en 1re intention ?","back":"**Aucune préférence** ; on les **associe** en cas d'inefficacité.","prio":"P1","sec":"s10"},{"id":"fc-p186-9f934a","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quelles interventions modifient l'histoire naturelle ?","back":"L'**éviction** et l'**immunothérapie allergénique**.","prio":"P1","sec":"s10"},{"id":"fc-p186-782060","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : quelle génération d'antihistaminiques H1 privilégier ?","back":"La **2e génération** (avec les corticoïdes locaux, traitements principaux).","prio":"P2","sec":"s10"},{"id":"fc-p186-4e8700","poly":"pneumo","fiche":"p186","front":"Rhinite : quelles mesures non médicamenteuses ?","back":"**Arrêt du tabac** ; prise en charge du **stress et de l'anxiété** (sommeil souvent perturbé).","prio":"P2","sec":"s10"},{"id":"fc-p186-9743da","poly":"pneumo","fiche":"p186","front":"Asthme allergique : sur quoi repose le traitement ?","back":"**Corticoïdes inhalés** et **bronchodilatateurs** (détails item 188).","prio":"P2","sec":"s10"},{"id":"fc-p186-d5bab1","poly":"pneumo","fiche":"p186","front":"Asthme : quel est le traitement de choix quand un traitement de fond est indiqué ?","back":"Les **corticoïdes inhalés**.","prio":"P3","sec":"s10"},{"id":"fc-p186-5ceceb","poly":"pneumo","fiche":"p186","front":"Rhino-conjonctivite allergique : quel est le seul traitement curatif ?","back":"L'**immunothérapie allergénique** (désensibilisation).","prio":"P1","sec":"s10"},{"id":"fc-p186-18302b","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire : sur quoi porte l'éducation thérapeutique ?","back":"Mise en place de l'**éviction**, usage des traitements (**inhalés**, ITA, **trousse d'urgence**), **lavage nasal**.","prio":"P2","sec":"s10"},{"id":"fc-p186-516e53","poly":"pneumo","fiche":"p186","front":"Antihistaminiques H1 : sur quel symptôme de rhinite sont-ils inefficaces ?","back":"L'**obstruction nasale** (actifs aussi sur conjonctivite et prurit).","prio":"P3","sec":"s10"},{"id":"fc-p186-cdce53","poly":"pneumo","fiche":"p186","front":"Antihistaminiques H1 de 2e génération : quels effets indésirables ?","back":"Bien tolérés : **somnolence rare**, parfois **stimulation de l'appétit**.","prio":"P3","sec":"s10"},{"id":"fc-p186-0f51ce","poly":"pneumo","fiche":"p186","front":"Antihistaminiques H1 : quel mécanisme ?","back":"Blocage du **récepteur H1** de l'histamine.","prio":"P3","sec":"s10"},{"id":"fc-p186-c77df0","poly":"pneumo","fiche":"p186","front":"Corticoïdes locaux (nasaux, inhalés) : quel mode d'action ?","back":"**Anti-inflammatoires** agissant **au long cours** sur l'inflammation nasale ou bronchique.","prio":"P3","sec":"s10"},{"id":"fc-p186-ee53c9","poly":"pneumo","fiche":"p186","front":"Corticoïdes inhalés : ont-ils une place dans l'urgence de l'asthme ?","back":"**Aucune** ; l'urgence relève des **corticoïdes systémiques**.","prio":"P3","sec":"s10"},{"id":"fc-p186-16bd81","poly":"pneumo","fiche":"p186","front":"Corticoïdes systémiques : pourquoi les éviter au long cours ?","back":"Leur **toxicité s'additionne**.","prio":"P3","sec":"s10"},{"id":"fc-p186-dccfcc","poly":"pneumo","fiche":"p186","front":"Vasoconstricteurs nasaux : pourquoi les déconseiller au long cours ?","back":"**Rhinite iatrogène** ; risque de **coronarospasme** chez le coronarien.","prio":"P1","sec":"s10"},{"id":"fc-p186-54d85f","poly":"pneumo","fiche":"p186","front":"Exacerbation d'asthme : quelle corticothérapie orale chez l'adulte ?","back":"**Prednisone/prednisolone 0,5 à 1 mg/kg/j** (max 60 mg/j), **5 à 7 jours**, arrêt **sans décroissance**.","prio":"P2","sec":"s10"},{"id":"fc-p186-fcd04d","poly":"pneumo","fiche":"p186","front":"Rhinite allergique : que surveiller au cours du suivi ?","back":"Symptômes ORL et **oculaires** ; **apparition ou aggravation d'un asthme**.","prio":"P2","sec":"s10"},{"id":"fc-p186-f5fe82","poly":"pneumo","fiche":"p186","front":"Allergie respiratoire professionnelle : quelle démarche administrative ?","back":"Déclaration possible en **maladie professionnelle**, ouvrant droit à **réparation**.","prio":"P2","sec":"s10"},{"id":"fc-p186-e68884","poly":"pneumo","fiche":"p186","front":"Éviction allergénique : quel prérequis ?","back":"Un **bilan allergologique précis** du ou des allergènes.","prio":"P2","sec":"s11"},{"id":"fc-p186-3b048a","poly":"pneumo","fiche":"p186","front":"CMEI : quel rôle ?","back":"Conseiller médical en environnement intérieur : **visite du domicile**, prélèvements, conseils pour réduire la charge allergénique.","prio":"P3","sec":"s11"},{"id":"fc-p186-7bd9fa","poly":"pneumo","fiche":"p186","front":"Éviction des acariens : quel principe d'efficacité ?","back":"Mesures d'autant plus efficaces qu'elles sont **combinées**.","prio":"P2","sec":"s11"},{"id":"fc-p186-cc694f","poly":"pneumo","fiche":"p186","front":"Éviction des acariens : quel taux d'humidité intérieure viser ?","back":"**< 50 %** d'humidité relative.","prio":"P2","sec":"s11"},{"id":"fc-p186-b2916c","poly":"pneumo","fiche":"p186","front":"Éviction des acariens : à quelle température laver les draps ?","back":"**≥ 60 °C** (les acariens meurent au-delà de 56 °C).","prio":"P2","sec":"s11"},{"id":"fc-p186-b2a8c2","poly":"pneumo","fiche":"p186","front":"Éviction des acariens : quelle mesure de literie est prioritaire ?","back":"**Housse anti-acariens** surtout pour le **matelas** (aussi couettes, oreillers).","prio":"P2","sec":"s11"},{"id":"fc-p186-268cda","poly":"pneumo","fiche":"p186","front":"Éviction des acariens : citer d'autres mesures ?","back":"Aspirateur (filtre **HEPA**), retirer peluches et **ramasse-poussière**, sommier à lattes, chambre **< 20 °C** et aérée.","prio":"P3","sec":"s11"},{"id":"fc-p186-0e1e18","poly":"pneumo","fiche":"p186","front":"Allergie aux animaux : quelles mesures d'éviction ?","back":"Animal **dehors**, sans accès à la **chambre** ; privilégier son **départ** du domicile.","prio":"P2","sec":"s11"},{"id":"fc-p186-dea517","poly":"pneumo","fiche":"p186","front":"Allergie au chat : combien de temps persistent les allergènes après le départ de l'animal ?","back":"**Plusieurs mois**.","prio":"P3","sec":"s11"},{"id":"fc-p186-f0e1a2","poly":"pneumo","fiche":"p186","front":"Moisissures : quelles mesures d'éviction ?","back":"Nettoyage à l'**eau de Javel** ; **ventilation** et **ensoleillement** du logement.","prio":"P3","sec":"s11"},{"id":"fc-p186-45d898","poly":"pneumo","fiche":"p186","front":"Allergie aux pollens : quelles mesures d'éviction ?","back":"Pas de linge séché dehors ; **aérer** tôt le matin et le soir ; sortir moins lors des **pics polliniques** et des **orages**.","prio":"P3","sec":"s11"},{"id":"fc-p186-81f4af","poly":"pneumo","fiche":"p186","front":"Orage en période pollinique : quel risque chez l'asthmatique ?","back":"Risque d'**exacerbation d'asthme**.","prio":"P2","sec":"s11"},{"id":"fc-p186-381b8a","poly":"pneumo","fiche":"p186","front":"Asthme : quelle éviction en plus des allergènes ?","back":"Les **irritants respiratoires** domestiques et professionnels (produits ménagers, parfums d'intérieur…).","prio":"P2","sec":"s11"},{"id":"fc-p186-b8525d","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : quel traitement général ?","back":"**Éviction** + **antihistaminique H1 de 2e génération** par voie générale.","prio":"P1","sec":"s12"},{"id":"fc-p186-10d1dc","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : quels traitements locaux ?","back":"**Lavages** au sérum physiologique, **compresses humides froides**, collyre **antihistaminique H1**, collyre **cromoglicate de sodium**.","prio":"P1","sec":"s12"},{"id":"fc-p186-e174c8","poly":"pneumo","fiche":"p186","front":"Cromoglicate de sodium en collyre : quel mécanisme ?","back":"**Inhibiteur de la dégranulation mastocytaire**.","prio":"P2","sec":"s12"},{"id":"fc-p186-d9179f","poly":"pneumo","fiche":"p186","front":"Conjonctivite allergique : à partir de quel âge une ITA est-elle possible ?","back":"Dès **5 ans**.","prio":"P2","sec":"s12"},{"id":"fc-p186-f5247b","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quel principe ?","back":"Induire une **tolérance** par des **doses croissantes** d'allergène.","prio":"P2","sec":"s13"},{"id":"fc-p186-425e8c","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quel effet immunologique ?","back":"Passage **Th2 → Th1** : baisse des **IgE**, hausse des **IgG4** bloquantes, induction de **lymphocytes T régulateurs**.","prio":"P2","sec":"s13"},{"id":"fc-p186-787e92","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : pour quels allergènes est-elle efficace ?","back":"**Acariens** et certains **pollens** (graminées, bouleau, oliviers, cyprès, ambroisie, pariétaire).","prio":"P1","sec":"s13"},{"id":"fc-p186-497884","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quelles indications ?","back":"Dès **5 ans** : **rhinite** et **conjonctivite** allergiques ; **asthme non sévère et contrôlé** allergique aux **acariens**.","prio":"P1","sec":"s13"},{"id":"fc-p186-9c9dfc","poly":"pneumo","fiche":"p186","front":"ITA dans l'asthme allergique aux graminées : quelle position ?","back":"L'indication **se discute**.","prio":"P2","sec":"s13"},{"id":"fc-p186-4fae4d","poly":"pneumo","fiche":"p186","front":"ITA sublinguale (GINA 2022) : quel adulte peut en bénéficier ?","back":"Rhinite + sensibilisation **acariens**, asthme symptomatique sous **CSI faible à moyenne dose**, **VEMS > 70 %**.","prio":"P2","sec":"s13"},{"id":"fc-p186-2afe21","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quelle durée ?","back":"**Au moins 3 ans** (ou 3 saisons polliniques consécutives).","prio":"P1","sec":"s13"},{"id":"fc-p186-5c0659","poly":"pneumo","fiche":"p186","front":"ITA sublinguale en comprimés : pour quels allergènes en France ?","back":"**Acariens**, **graminées**, **bouleau**.","prio":"P3","sec":"s13"},{"id":"fc-p186-09d145","poly":"pneumo","fiche":"p186","front":"ITA sublinguale en comprimés : quelle précaution à la 1re prise ?","back":"**Surveillance médicale de 30 minutes**.","prio":"P3","sec":"s13"},{"id":"fc-p186-81dff4","poly":"pneumo","fiche":"p186","front":"ITA sublinguale en comprimés : quel avantage pratique ?","back":"Conservation à **température ambiante**.","prio":"P3","sec":"s13"},{"id":"fc-p186-78808e","poly":"pneumo","fiche":"p186","front":"ITA sous-cutanée : est-elle remboursée en France ?","back":"**Non**, sauf pour les **venins d'hyménoptères**.","prio":"P3","sec":"s13"},{"id":"fc-p186-b0d3b0","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quand doit-elle prouver son efficacité ?","back":"Dès la **1re année** (moins de symptômes et/ou de médicaments), sinon discuter l'**arrêt**.","prio":"P2","sec":"s13"},{"id":"fc-p186-87fd59","poly":"pneumo","fiche":"p186","front":"Immunothérapie allergénique : quels objectifs ?","back":"Moins de symptômes/traitements, éviter de **nouvelles sensibilisations**, **prévenir un asthme** (enfant), réduire sa sévérité, qualité de vie.","prio":"P2","sec":"s13"},{"id":"fc-p186-fae25a","poly":"pneumo","fiche":"p186","front":"ITA sublinguale : quels effets indésirables ?","back":"**Locaux** : gonflement des lèvres ou de la langue, démangeaisons buccales.","prio":"P3","sec":"s13"},{"id":"fc-p186-dbe03d","poly":"pneumo","fiche":"p186","front":"ITA : citer des contre-indications absolues ?","back":"**Grossesse** (pour la débuter), immunodépression sévère, maladie auto-immune systémique, **néoplasie**, trouble psychiatrique sévère, **asthme non contrôlé** (transitoire).","prio":"P3","sec":"s13"},{"id":"fc-p186-120e14","poly":"pneumo","fiche":"p186","front":"ITA et grossesse : quelle règle ?","back":"On ne la **commence pas** ; on peut la **poursuivre** si débutée avant et bien tolérée.","prio":"P3","sec":"s13"},{"id":"fc-p186-3c72d6","poly":"pneumo","fiche":"p186","front":"ITA chez un asthmatique non contrôlé ou infecté : quelle attitude ?","back":"Contre-indication **transitoire** : attendre le **contrôle** de l'asthme ou la **guérison** de l'infection.","prio":"P3","sec":"s13"},{"id":"fc-p186-89a7c4","poly":"pneumo","fiche":"p186","front":"ITA : quelle contre-indication liée à l'exacerbation d'asthme ?","back":"Asthme sévère non contrôlé ou **exacerbation sévère dans les 3 derniers mois**.","prio":"P3","sec":"s13"},{"id":"fc-p186-5fae9c","poly":"pneumo","fiche":"p186","front":"ITA : citer des contre-indications relatives ?","back":"Asthme sévère contrôlé, **bêtabloquants**, mauvaise observance, eczéma atopique sévère, maladie cardiovasculaire grave.","prio":"P3","sec":"s13"},{"id":"fc-p186-7f0166","poly":"pneumo","fiche":"p186","front":"ITA : la polysensibilisation la contre-indique-t-elle ?","back":"**Non**.","prio":"P3","sec":"s13"},{"id":"fc-p186-f61304","poly":"pneumo","fiche":"p186","front":"ITA sublinguale liquide : donne-t-elle habituellement des effets systémiques ?","back":"**Non**, habituellement pas d'effet systémique (effets surtout **locaux**).","prio":"P3","sec":"s13"},{"id":"fc-p186-f6d464","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : quel régime ?","back":"**Éviction** du ou des aliments identifiés.","prio":"P3","sec":"s14"},{"id":"fc-p186-e0e496","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : que contient la trousse d'urgence ?","back":"**Antihistaminique H1** ; **bronchodilatateur** si antécédent de bronchospasme ; **adrénaline auto-injectable** si antécédent/risque d'anaphylaxie.","prio":"P3","sec":"s14"},{"id":"fc-p186-0ed7fa","poly":"pneumo","fiche":"p186","front":"Après un choc anaphylactique à risque de récidive : quelle prévention ?","back":"Trousse avec **adrénaline auto-injectable** + **éducation à l'auto-injection IM**.","prio":"P1","sec":"s14"},{"id":"fc-p186-b1392e","poly":"pneumo","fiche":"p186","front":"Enfant allergique alimentaire : quel dispositif scolaire proposer ?","back":"Un **PAI** (plan d'action individualisé) avec parents, école, médecin scolaire et médecin traitant.","prio":"P1","sec":"s14"},{"id":"fc-p186-165acb","poly":"pneumo","fiche":"p186","front":"PAI : à la demande de qui et à quoi sert-il ?","back":"Des **parents** ; protocole de soins en cas de réaction accidentelle (dérogation au **secret professionnel**).","prio":"P3","sec":"s14"},{"id":"fc-p186-e6586f","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : quels documents remettre au patient ?","back":"**Carte d'allergique** (sensibilisations, sévérité) + **liste des aliments** pouvant contenir l'allergène.","prio":"P2","sec":"s14"},{"id":"fc-p186-60b475","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire : sur quoi porte l'éducation thérapeutique ?","back":"**Trousse d'urgence**, évaluer les symptômes, **lire les étiquettes**, repérer les aliments à risque, conduites à tenir.","prio":"P3","sec":"s14"},{"id":"fc-p186-62ef69","poly":"pneumo","fiche":"p186","front":"Allergie alimentaire sans guérison spontanée : quelle option ?","back":"**Induction de tolérance orale** ; un seul médicament a l'AMM en France (**arachide**).","prio":"P3","sec":"s14"},{"id":"fc-p186-ea446a","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable : quelle dose entre 15 et 30 kg ?","back":"**150 µg** (pas d'AMM sous 15 kg).","prio":"P1","sec":"s14"},{"id":"fc-p186-5f9708","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable : quelle dose au-delà de 30 kg et chez l'adulte ?","back":"**300 µg** (> 30 kg et adulte < 60 kg) ; **300 à 500 µg** chez l'adulte > 60 kg.","prio":"P2","sec":"s14"},{"id":"fc-p186-55a28f","poly":"pneumo","fiche":"p186","front":"Adrénaline IM dans l'anaphylaxie : quand répéter la dose ?","back":"Toutes les **5-10 minutes** jusqu'à **stabilisation**.","prio":"P1","sec":"s14"},{"id":"fc-p186-c45846","poly":"pneumo","fiche":"p186","front":"Après adrénaline pour anaphylaxie : quelle surveillance ?","back":"Transport médicalisé + surveillance hospitalière **≥ 6 h**, même si asymptomatique (**réaction biphasique**).","prio":"P1","sec":"s14"},{"id":"fc-p186-6727e2","poly":"pneumo","fiche":"p186","front":"Après une anaphylaxie : combien de temps évincer l'allergène ?","back":"**À vie**, jusqu'à preuve du contraire.","prio":"P2","sec":"s14"},{"id":"fc-p186-00e160","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable (allergie alimentaire) : quelles indications absolues ?","back":"**Anaphylaxie antérieure** à un aliment ; allergie alimentaire + **asthme persistant modéré à sévère ou non contrôlé**.","prio":"P1","sec":"s14"},{"id":"fc-p186-38348f","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable chez l'enfant allergique alimentaire : quelles indications ?","back":"**Plus larges** (sévérité d'une récidive difficile à prévoir).","prio":"P2","sec":"s14"},{"id":"fc-p186-95690c","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable après réaction alimentaire légère à modérée : citer des indications relatives ?","back":"Réaction à **petite quantité**, aliment à risque (arachide, fruits à coque, lait, crustacés), **adolescent/adulte jeune**, domicile éloigné.","prio":"P3","sec":"s14"},{"id":"fc-p186-7b2a05","poly":"pneumo","fiche":"p186","front":"Anaphylaxie : antihistaminiques et corticoïdes sont-ils des traitements d'urgence ?","back":"**Non, en aucun cas** ; ils agissent sur **urticaire et prurit** (et la phase tardive).","prio":"P1","sec":"s14"},{"id":"fc-p186-eae5b5","poly":"pneumo","fiche":"p186","front":"Suspicion d'anaphylaxie alimentaire : faut-il vider l'estomac ?","back":"**Non** (risque d'**inhalation**).","prio":"P2","sec":"s14"},{"id":"fc-p186-009e5b","poly":"pneumo","fiche":"p186","front":"Piqûre d'abeille : comment gérer le dard ?","back":"Le retirer **le plus tôt possible** : la précocité compte plus que la technique.","prio":"P2","sec":"s15"},{"id":"fc-p186-c4d1be","poly":"pneumo","fiche":"p186","front":"Réaction systémique après piqûre d'hyménoptère : quel traitement ?","back":"**Adrénaline IM sans délai**, puis **surveillance hospitalière**.","prio":"P1","sec":"s15"},{"id":"fc-p186-fd9a20","poly":"pneumo","fiche":"p186","front":"Allergie grave aux venins : quel traitement de fond proposer ?","back":"L'**immunothérapie allergénique** aux venins, **efficace et bien tolérée**.","prio":"P1","sec":"s15"},{"id":"fc-p186-f5bf43","poly":"pneumo","fiche":"p186","front":"ITA aux venins : pour quelles réactions ?","back":"Réactions systémiques **anaphylactiques sévères** de mécanisme **IgE démontré**.","prio":"P3","sec":"s15"},{"id":"fc-p186-009157","poly":"pneumo","fiche":"p186","front":"Allergie aux venins : quelles mesures pour prévenir la récidive ?","back":"**Carte d'allergique** + **trousse avec adrénaline auto-injectable** + apprentissage de l'auto-injection.","prio":"P2","sec":"s15"},{"id":"fc-p186-d1ba24","poly":"pneumo","fiche":"p186","front":"Adrénaline IM hospitalière : quelle dose chez l'adulte ?","back":"**0,3 ou 0,5 mg**.","prio":"P2","sec":"s15"},{"id":"fc-p186-4ef355","poly":"pneumo","fiche":"p186","front":"Adrénaline IM hospitalière : quelle dose chez l'enfant de moins de 15 kg ?","back":"**0,01 mg/kg**.","prio":"P3","sec":"s15"},{"id":"fc-p186-d65e4c","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable (venin) : quelle indication absolue ?","back":"Réaction systémique **plus sévère qu'une atteinte cutanéo-muqueuse** : sans ITA ou avec **risque élevé de réexposition**, ou pendant/après une ITA si **risque de récidive** élevé.","prio":"P2","sec":"s15"},{"id":"fc-p186-984357","poly":"pneumo","fiche":"p186","front":"Adrénaline auto-injectable (venin) : quelle indication relative ?","back":"Réaction systémique plus que cutanéo-muqueuse chez un patient avec **maladie cardiovasculaire**.","prio":"P3","sec":"s15"},{"id":"fc-p186-c97aca","poly":"pneumo","fiche":"p186","front":"Anaphylaxie sous bêtabloquant : quelle attitude ?","back":"**Remplacer le bêtabloquant** par une autre classe, avec le **cardiologue**.","prio":"P1","sec":"s15"},{"id":"fc-p186-5b412d","poly":"pneumo","fiche":"p186","front":"Adrénaline IM : où injecter ?","back":"**Face antérolatérale externe de la cuisse** ou région **deltoïdienne**.","prio":"P1","sec":"s15"},{"id":"fc-p186-75b08f","poly":"pneumo","fiche":"p186","front":"Adrénaline : la voie sous-cutanée est-elle acceptable ?","back":"**Non, proscrite** (trop lente).","prio":"P1","sec":"s15"},{"id":"fc-p186-e83bab","poly":"pneumo","fiche":"p186","front":"Adrénaline IM hospitalière : quelle dose chez l'enfant de 15 à 30 kg, et au-delà de 30 kg (ou > 12 ans) ?","back":"**0,15 mg** de 15 à 30 kg ; **0,3 mg** si > 30 kg ou > 12 ans.","prio":"P3","sec":"s15"},{"id":"fc-p186-d5ef4b","poly":"pneumo","fiche":"p186","front":"Avant des prick-tests : combien de temps arrêter les antihistaminiques ?","back":"**5 jours** (idéalement 7).","prio":"P3","sec":"s16"},{"id":"fc-p186-c34211","poly":"pneumo","fiche":"p186","front":"Avant des prick-tests : quand arrêter l'omalizumab et les dermocorticoïdes ?","back":"Omalizumab **6 semaines** avant ; dermocorticoïdes **3 semaines** avant.","prio":"P3","sec":"s16"},{"id":"fc-p186-0bab9d","poly":"pneumo","fiche":"p186","front":"Avant des prick-tests : faut-il arrêter une cure courte de corticoïdes oraux ?","back":"**Non** (ex. prednisone 30 mg/j × 7 j ne diminue pas la réactivité cutanée).","prio":"P3","sec":"s16"},{"id":"fc-p186-15e4fc","poly":"pneumo","fiche":"p186","front":"Test de provocation : quelles contre-indications ?","back":"**Antihistaminiques** en cours, **bêtabloquants**, **grossesse**, maladie cardiovasculaire ou **asthme non contrôlés**.","prio":"P1","sec":"s16"},{"id":"fc-p186-1ec460","poly":"pneumo","fiche":"p186","front":"Test de provocation : pourquoi les bêtabloquants le contre-indiquent-ils ?","back":"Ils **bloquent l'effet de l'adrénaline** si elle est nécessaire.","prio":"P2","sec":"s16"},{"id":"fc-p186-d336de","poly":"pneumo","fiche":"p186","front":"Allergie chronique : quel retentissement évaluer ?","back":"Le **retentissement psychologique**.","prio":"P2","sec":"s17"},{"id":"fc-p188-418a9e","poly":"pneumo","fiche":"p188","front":"Asthme : quelle définition ?","back":"Maladie **inflammatoire chronique** des voies aériennes inférieures : symptômes respiratoires **variables** + obstruction **variable et/ou réversible** après bronchodilatateurs.","prio":"P1","sec":"s1"},{"id":"fc-p188-505e70","poly":"pneumo","fiche":"p188","front":"Asthme : quels symptômes respiratoires le caractérisent ?","back":"**Dyspnée**, **sifflements**, **oppression thoracique** et/ou **toux**, variables dans le temps et en intensité.","prio":"P2","sec":"s1"},{"id":"fc-p188-941123","poly":"pneumo","fiche":"p188","front":"Asthme : comment se mesure l'obstruction ?","back":"**Trouble ventilatoire obstructif** (TVO), réversible totalement ou partiellement, à l'état basal ou après test de provocation.","prio":"P2","sec":"s1"},{"id":"fc-p188-a68037","poly":"pneumo","fiche":"p188","front":"Asthme : quels facteurs environnementaux favorisent et entretiennent la maladie ?","back":"Surtout **infections virales**, **exposition aux allergènes**, **irritants bronchiques**.","prio":"P2","sec":"s1"},{"id":"fc-p188-e3b591","poly":"pneumo","fiche":"p188","front":"Hyperréactivité bronchique : quelle définition ?","back":"**Bronchoconstriction excessive** lors de l'exposition à divers stimuli.","prio":"P1","sec":"s1"},{"id":"fc-p188-e25e0a","poly":"pneumo","fiche":"p188","front":"Hyperréactivité bronchique : quels types de stimuli ?","back":"**Physiques** (air froid et sec) · **pharmacologiques** (méthacholine) · **professionnels** · **pneumallergènes**.","prio":"P2","sec":"s1"},{"id":"fc-p188-cceb6f","poly":"pneumo","fiche":"p188","front":"Asthme : pourquoi les exacerbations sont-elles importantes ?","back":"Événements **potentiellement graves**, sources de **décès**.","prio":"P2","sec":"s1"},{"id":"fc-p188-7112d6","poly":"pneumo","fiche":"p188","front":"Quel terme préférer à « crise d'asthme » ?","back":"« **Symptômes d'asthme de brève durée** ».","prio":"P2","sec":"s1"},{"id":"fc-p188-c525f4","poly":"pneumo","fiche":"p188","front":"Symptômes d'asthme de brève durée : quelle durée habituelle ?","back":"Quelques minutes ; cèdent en général en **moins de 20 minutes**, spontanément ou sous BDCA.","prio":"P2","sec":"s1"},{"id":"fc-p188-a21087","poly":"pneumo","fiche":"p188","front":"Exacerbation d'asthme : quelle définition ?","back":"↑ **progressive** des symptômes **≥ 2 jours**, non calmée par des BDCA répétés, sans retour à l'état habituel, imposant de **modifier le traitement**.","prio":"P1","sec":"s1"},{"id":"fc-p188-ba2ab1","poly":"pneumo","fiche":"p188","front":"Asthme : quels sont les deux cadres de prise en charge ?","back":"**Consultation programmée** (symptômes passés racontés) et **urgence** (exacerbation, symptômes présents à l'examen).","prio":"P3","sec":"s1"},{"id":"fc-p188-840dae","poly":"pneumo","fiche":"p188","front":"Asthme : quels sont les 3 mécanismes ?","back":"**Inflammation bronchique chronique** (le plus souvent à éosinophiles) · **remaniement** des voies aériennes · **hyperréactivité bronchique**.","prio":"P2","sec":"s2"},{"id":"fc-p188-f3ff12","poly":"pneumo","fiche":"p188","front":"Asthme T2 : quelles cellules et quels asthmes ?","back":"Lymphocytes **Th2** et **éosinophiles** ; asthmes **allergiques** et à éosinophiles non allergiques.","prio":"P2","sec":"s2"},{"id":"fc-p188-d24a91","poly":"pneumo","fiche":"p188","front":"Asthme non-T2 : quelle caractéristique ?","back":"Ne dépend **pas complètement** des lymphocytes Th2 ni des éosinophiles.","prio":"P3","sec":"s2"},{"id":"fc-p188-d294b2","poly":"pneumo","fiche":"p188","front":"Asthme de l'adulte en France : quelle prévalence ?","back":"**6 %**.","prio":"P2","sec":"s2"},{"id":"fc-p188-cb1214","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelle prévalence chez l'asthmatique et en population générale ?","back":"**80 %** des asthmatiques ; **24-25 %** de la population générale.","prio":"P2","sec":"s2"},{"id":"fc-p188-dc7c99","poly":"pneumo","fiche":"p188","front":"Asthme : sur quels deux volets repose le diagnostic ?","back":"**Symptômes caractéristiques** + preuve d'une **obstruction réversible** des voies aériennes.","prio":"P1","sec":"s3"},{"id":"fc-p188-604755","poly":"pneumo","fiche":"p188","front":"Asthme : quels arguments cliniques ?","back":"**Plusieurs symptômes** associés · **variables** et **réversibles** · **déclenchés** par des facteurs · **aggravés la nuit ou au petit matin**.","prio":"P1","sec":"s3"},{"id":"fc-p188-b0aeb8","poly":"pneumo","fiche":"p188","front":"Asthme : quels facteurs déclenchants des symptômes ?","back":"Infections virales · **exercice** · allergènes · irritants (tabac, cannabis, produits ménagers, pollution) · émotions, rire, pleurs (enfant).","prio":"P1","sec":"s3"},{"id":"fc-p188-504c81","poly":"pneumo","fiche":"p188","front":"Asthme : comment documenter l'obstruction variable et réversible ?","back":"**Sibilants** (actuels ou passés) · **TVO réversible** sous bronchodilatateurs.","prio":"P2","sec":"s3"},{"id":"fc-p188-d2c0d3","poly":"pneumo","fiche":"p188","front":"Asthme : quand rechercher une HRB par test de provocation ?","back":"**Seulement si la spirométrie est normale** : méthacholine ou test d'effort.","prio":"P2","sec":"s3"},{"id":"fc-p188-18b43d","poly":"pneumo","fiche":"p188","front":"Asthme : l'histoire clinique suffit-elle au diagnostic ?","back":"**Non** : elle fait **suspecter** ; diagnostic **confirmé par les EFR** (obstruction réversible).","prio":"P1","sec":"s3"},{"id":"fc-p188-d68ea1","poly":"pneumo","fiche":"p188","front":"Asthme : quel examen confirme le diagnostic ?","back":"**Spirométrie avec test de réversibilité** (TVO réversible).","prio":"P1","sec":"s4"},{"id":"fc-p188-0b8d7e","poly":"pneumo","fiche":"p188","front":"Spirométrie normale en consultation : l'asthme est-il éliminé ?","back":"**Non** : refaire plus tard avec **test de réversibilité** ou **test de provocation**.","prio":"P1","sec":"s4"},{"id":"fc-p188-959bab","poly":"pneumo","fiche":"p188","front":"Asthme : quand la radiographie thoracique est-elle indispensable ?","back":"À la **1re consultation**, pour le **diagnostic différentiel** (obstacle bronchique ou trachéal).","prio":"P1","sec":"s4"},{"id":"fc-p188-4b676f","poly":"pneumo","fiche":"p188","front":"TVO de l'adulte : quel critère spirométrique ?","back":"**VEMS/CVF < 0,7**.","prio":"P2","sec":"s4"},{"id":"fc-p188-7506cf","poly":"pneumo","fiche":"p188","front":"Réversibilité du TVO : quel critère ?","back":"Après BDCA, **gain de VEMS > 200 ml ET > 12 %** par rapport à la valeur de départ.","prio":"P2","sec":"s4"},{"id":"fc-p188-6ff513","poly":"pneumo","fiche":"p188","front":"Réversibilité complète du TVO : quels critères ?","back":"**VEMS/CVF > 0,7** ET **VEMS > 80 %** de la valeur prédite.","prio":"P2","sec":"s4"},{"id":"fc-p188-5fc5ae","poly":"pneumo","fiche":"p188","front":"Réversibilité du VEMS : est-elle pathognomonique de l'asthme ?","back":"**Non** : c'est l'**association** symptômes évocateurs + réversibilité qui fait le diagnostic.","prio":"P2","sec":"s4"},{"id":"fc-p188-daf336","poly":"pneumo","fiche":"p188","front":"DEP : quelle définition ?","back":"**Débit maximal instantané** pendant une expiration forcée.","prio":"P2","sec":"s4"},{"id":"fc-p188-a7bb81","poly":"pneumo","fiche":"p188","front":"DEP vs VEMS : quelle fiabilité ?","back":"DEP **moins fiable** ; il ne remplace pas la courbe débit-volume.","prio":"P2","sec":"s4"},{"id":"fc-p188-639236","poly":"pneumo","fiche":"p188","front":"DEP : quelles utilisations ?","back":"Suivi d'une **exacerbation grave** aux urgences · efficacité d'un traitement de fond · **asthme professionnel** · **autosurveillance**.","prio":"P2","sec":"s4"},{"id":"fc-p188-408028","poly":"pneumo","fiche":"p188","front":"Asthme professionnel : quel usage du DEP ?","back":"**Journal de DEP** : variabilité au travail et hors du travail.","prio":"P3","sec":"s4"},{"id":"fc-p188-6c88df","poly":"pneumo","fiche":"p188","front":"Exacerbation grave d'asthme : pourquoi une radiographie thoracique ?","back":"Vérifier l'absence de **pneumothorax** ou de **pneumonie**.","prio":"P2","sec":"s4"},{"id":"fc-p188-69ea32","poly":"pneumo","fiche":"p188","front":"Radiographie thoracique dans le suivi de l'asthme : est-elle recommandée ?","back":"**Non**.","prio":"P1","sec":"s4"},{"id":"fc-p188-580acf","poly":"pneumo","fiche":"p188","front":"Asthme : quand envisager une TDM thoracique ?","back":"Seulement si l'asthme est **difficile à contrôler**.","prio":"P1","sec":"s4"},{"id":"fc-p188-52f247","poly":"pneumo","fiche":"p188","front":"Asthme difficile à contrôler : quelles pathologies associées chercher en TDM ?","back":"**Aspergillose bronchopulmonaire allergique** · **pneumonie à éosinophiles** · **granulomatose éosinophilique avec polyangéite**.","prio":"P2","sec":"s4"},{"id":"fc-p188-b1648f","poly":"pneumo","fiche":"p188","front":"Asthme : quels diagnostics différentiels sans TVO ni HRB ?","back":"**Dysfonction des cordes vocales** · **syndrome d'hyperventilation**.","prio":"P1","sec":"s5"},{"id":"fc-p188-d3ef6c","poly":"pneumo","fiche":"p188","front":"Syndrome d'hyperventilation : comment l'évoquer ?","back":"Grâce à des **questionnaires spécifiques validés**.","prio":"P3","sec":"s5"},{"id":"fc-p188-725301","poly":"pneumo","fiche":"p188","front":"Asthme : quelles maladies chroniques des voies aériennes en différentiel (TVO pas complètement réversible) ?","back":"**BPCO** · **bronchectasies** · **mucoviscidose** · **bronchiolites constrictives**.","prio":"P2","sec":"s5"},{"id":"fc-p188-61897a","poly":"pneumo","fiche":"p188","front":"Bronchectasies : comment en fait-on le diagnostic ?","back":"Diagnostic **morphologique**, sur la **TDM thoracique**.","prio":"P2","sec":"s5"},{"id":"fc-p188-ae2202","poly":"pneumo","fiche":"p188","front":"Asthme : quels autres diagnostics différentiels citer ?","back":"**Corps étranger** · **tumeurs trachéo-bronchiques** · **insuffisance cardiaque**.","prio":"P2","sec":"s5"},{"id":"fc-p188-80f679","poly":"pneumo","fiche":"p188","front":"Asthme professionnel du boulanger : quels agents ?","back":"**Farines** (blé, seigle) · enzymes ajoutées (alpha-amylase, cellulase) · contaminants (acariens de stockage, blatte).","prio":"P2","sec":"s6"},{"id":"fc-p188-112c9e","poly":"pneumo","fiche":"p188","front":"Asthme professionnel des métiers de la santé : quels agents ?","back":"**Latex** (gants) · **aldéhydes** (glutaraldéhyde…) · **ammoniums quaternaires** · oxyde d'éthylène.","prio":"P2","sec":"s6"},{"id":"fc-p188-f345ac","poly":"pneumo","fiche":"p188","front":"Asthme professionnel du coiffeur : quel agent principal ?","back":"**Persulfates alcalins** ++ (décoloration) ; aussi teintures, produits de permanente.","prio":"P1","sec":"s6"},{"id":"fc-p188-160d10","poly":"pneumo","fiche":"p188","front":"Asthme du peintre au pistolet : quel agent en cause ?","back":"**Isocyanates** (peintures polyuréthanes) ; les **solvants** ne font qu'**aggraver** (irritants).","prio":"P1","sec":"s6"},{"id":"fc-p188-568d1a","poly":"pneumo","fiche":"p188","front":"Asthme des travailleurs du bois : quels agents ?","back":"**Bois exotiques**, colles (**colophane**, formaldéhyde), vernis (isocyanates).","prio":"P2","sec":"s6"},{"id":"fc-p188-311458","poly":"pneumo","fiche":"p188","front":"Asthme des métiers du nettoyage : quels agents ?","back":"Acariens, latex, **ammoniums quaternaires**, **amines aliphatiques** ; les **sprays** facilitent la pénétration.","prio":"P2","sec":"s6"},{"id":"fc-p188-0ea7ba","poly":"pneumo","fiche":"p188","front":"Asthme professionnel : quelle part concentrent les 6 métiers principaux ?","back":"**50 %** des asthmes professionnels.","prio":"P3","sec":"s6"},{"id":"fc-p188-26589f","poly":"pneumo","fiche":"p188","front":"Asthme professionnel : quels arguments cliniques pour l'origine professionnelle ?","back":"Asthme **de novo** au travail · **profession à risque** · **rythme professionnel** (mieux le week-end, disparu en congés).","prio":"P2","sec":"s6"},{"id":"fc-p188-e5ffc2","poly":"pneumo","fiche":"p188","front":"Asthme professionnel : quels arguments objectifs ?","back":"Variations du **DEP ou du VEMS** liées au travail · **sensibilisation** IgE (tests cutanés, IgE spécifiques) · exceptionnellement **tests de provocation** en cabine.","prio":"P2","sec":"s6"},{"id":"fc-p188-4e5a4e","poly":"pneumo","fiche":"p188","front":"Asthme : quel bilan initial en consultation programmée ?","back":"Examen avec **auscultation pulmonaire** · recherche des **facteurs favorisants** · **radiographie thoracique** · **EFR** (spirométrie + test de réversibilité ± méthacholine).","prio":"P2","sec":"s7"},{"id":"fc-p188-c23640","poly":"pneumo","fiche":"p188","front":"Asthme : quel bilan allergologique au diagnostic ?","back":"**Interrogatoire** et **prick-tests**.","prio":"P2","sec":"s7"},{"id":"fc-p188-b2460c","poly":"pneumo","fiche":"p188","front":"Asthme : que vérifier à chaque consultation ?","back":"**Contrôle** · **observance** · **effets indésirables** · **technique d'inhalation**.","prio":"P2","sec":"s7"},{"id":"fc-p188-d575e2","poly":"pneumo","fiche":"p188","front":"Asthme contrôlé : quelles sont les 3 conditions ?","back":"**ACT ≥ 20/25** · **< 2 cures** de corticoïdes systémiques l'année précédente · **VEMS/CVF > 0,7 et VEMS ≥ 80 %**.","prio":"P1","sec":"s7"},{"id":"fc-p188-c2f696","poly":"pneumo","fiche":"p188","front":"ACT : sur quelle période et comment est-il coté ?","back":"**4 dernières semaines** ; **5 questions** cotées de 1 à 5, total **sur 25**.","prio":"P2","sec":"s7"},{"id":"fc-p188-4779bd","poly":"pneumo","fiche":"p188","front":"ACT : quel seuil pour un asthme bien contrôlé ?","back":"**≥ 20/25** ; < 20/25 = insuffisamment contrôlé.","prio":"P1","sec":"s7"},{"id":"fc-p188-f18f1a","poly":"pneumo","fiche":"p188","front":"Asthme : quand réévaluer le contrôle après un changement de traitement de fond ?","back":"**1 à 3 mois** après, selon sévérité et contrôle, puis à chaque consultation.","prio":"P1","sec":"s7"},{"id":"fc-p188-3e4711","poly":"pneumo","fiche":"p188","front":"Cure de corticothérapie systémique : quelle conséquence sur le traitement de fond ?","back":"Elle impose de **réévaluer le traitement de fond**.","prio":"P1","sec":"s7"},{"id":"fc-p188-daa0fd","poly":"pneumo","fiche":"p188","front":"Avant de monter d'un palier : que vérifier ?","back":"Causes de non-contrôle : **observance**, **technique d'inhalation**, **facteurs favorisants**.","prio":"P2","sec":"s7"},{"id":"fc-p188-0ddc5c","poly":"pneumo","fiche":"p188","front":"Asthme : comment juge-t-on la sévérité ?","back":"**A posteriori**, sur la **pression thérapeutique** nécessaire au contrôle.","prio":"P1","sec":"s7"},{"id":"fc-p188-224c73","poly":"pneumo","fiche":"p188","front":"Asthme sévère : quelle définition ?","back":"Asthme nécessitant un **palier 5** (CSI dose forte + BDLA).","prio":"P1","sec":"s7"},{"id":"fc-p188-f1b6d9","poly":"pneumo","fiche":"p188","front":"Exacerbation d'asthme : quelles circonstances de survenue ?","back":"En général : **agent extérieur** (infection virale, allergène, pollution) ou traitement de fond par CSI **absent ou insuffisant**.","prio":"P1","sec":"s8"},{"id":"fc-p188-6216d4","poly":"pneumo","fiche":"p188","front":"Exacerbation : peut-elle toucher un asthme léger bien contrôlé ?","back":"**Oui**.","prio":"P2","sec":"s8"},{"id":"fc-p188-c2f426","poly":"pneumo","fiche":"p188","front":"Exacerbation : sur quoi juger la gravité ?","back":"**Présentation clinique** + **facteurs de risque de décès** par asthme.","prio":"P2","sec":"s8"},{"id":"fc-p188-72d125","poly":"pneumo","fiche":"p188","front":"Exacerbation modérée : quelle définition ?","back":"Modification du traitement nécessaire, **faisable en ambulatoire**.","prio":"P2","sec":"s8"},{"id":"fc-p188-08f8f3","poly":"pneumo","fiche":"p188","front":"Exacerbation sévère (asthme aigu grave) : quelle définition ?","back":"**Pronostic vital en jeu** ; prise en charge **hospitalière**.","prio":"P1","sec":"s8"},{"id":"fc-p188-500e16","poly":"pneumo","fiche":"p188","front":"Exacerbation quasi mortelle : quelle définition ?","back":"**Insuffisance respiratoire d'évolution suraiguë**.","prio":"P2","sec":"s8"},{"id":"fc-p188-ca19fa","poly":"pneumo","fiche":"p188","front":"Exacerbation : quels signes de lutte ?","back":"Parle avec des **phrases** · préfère assis · non agité · FR ↑ · **FC > 100** · **SpO₂ < 95 %** · **DEP > 50 %**.","prio":"P1","sec":"s8"},{"id":"fc-p188-44f300","poly":"pneumo","fiche":"p188","front":"Exacerbation : quels signes de défaillance (fonctionnels et vitaux) ?","back":"Parle avec des **mots** · assis penché en avant · agité · **FR > 30** · muscles accessoires · **FC > 120** · **SpO₂ < 90 %**.","prio":"P1","sec":"s8"},{"id":"fc-p188-3ae6d5","poly":"pneumo","fiche":"p188","front":"Exacerbation : quel seuil de DEP signe la défaillance ?","back":"**DEP ≤ 50 %** de la meilleure valeur (ou théorique), ou **impossible** à réaliser.","prio":"P1","sec":"s8"},{"id":"fc-p188-1b6d4f","poly":"pneumo","fiche":"p188","front":"Exacerbation : quels signes de défaillance extrême à l'examen ?","back":"**Silence auscultatoire** · **respiration paradoxale** · troubles de la conscience · **bradycardie** · **collapsus**.","prio":"P1","sec":"s8"},{"id":"fc-p188-971d96","poly":"pneumo","fiche":"p188","front":"Asthme : quels antécédents et recours sont des facteurs de risque de décès ?","back":"Exacerbation passée en **réanimation**/intubée · **hospitalisation ou urgences** pour asthme dans l'année · **corticothérapie orale** en cours ou récente.","prio":"P2","sec":"s8"},{"id":"fc-p188-982f0d","poly":"pneumo","fiche":"p188","front":"Asthme : quels critères de mauvaise observance sont des facteurs de risque de décès ?","back":"**CSI arrêté ou absent** · **> 3 flacons de BDCA/an** · pas de suivi codifié.","prio":"P2","sec":"s8"},{"id":"fc-p188-5fda76","poly":"pneumo","fiche":"p188","front":"Asthme : quels terrains et toxiques sont des facteurs de risque de décès ?","back":"Maladie **psychiatrique**/problèmes psychosociaux · **allergie alimentaire** · hypersensibilité **aspirine/AINS** · **tabac** · toxicomanie (**cannabis** +++).","prio":"P2","sec":"s8"},{"id":"fc-p188-2c4e8e","poly":"pneumo","fiche":"p188","front":"Syndrome de Widal : quelle triade ?","back":"**Asthme** + **polypose naso-sinusienne** + **intolérance à l'aspirine et aux AINS**.","prio":"P1","sec":"s8"},{"id":"fc-p188-a74bb5","poly":"pneumo","fiche":"p188","front":"Exacerbation : quand faire un gaz du sang artériel ?","back":"S'il existe des **critères de sévérité** : recherche d'une **hypercapnie**.","prio":"P2","sec":"s8"},{"id":"fc-p188-9e290c","poly":"pneumo","fiche":"p188","front":"Exacerbation : que recherche la radiographie de thorax ?","back":"Diagnostic différentiel et complication : **pneumothorax**, **pneumomédiastin**, **emphysème sous-cutané**.","prio":"P2","sec":"s8"},{"id":"fc-p188-9381dc","poly":"pneumo","fiche":"p188","front":"Exacerbation : les examens complémentaires doivent-ils précéder le traitement ?","back":"**Non** : ils se font **en parallèle**, sans retarder la prise en charge.","prio":"P1","sec":"s8"},{"id":"fc-p188-8de353","poly":"pneumo","fiche":"p188","front":"BDCA à fortes doses : quelle anomalie biologique possible et que faire ?","back":"**Acidose lactique** : pas de traitement spécifique, elle régresse quand on **diminue** le BDCA.","prio":"P3","sec":"s8"},{"id":"fc-p188-0badf9","poly":"pneumo","fiche":"p188","front":"Que signifient BDCA et BDLA ?","back":"β2-mimétique inhalé de **courte** (BDCA) ou de **longue** (BDLA) durée d'action.","prio":"P2","sec":"s9"},{"id":"fc-p188-97d6a2","poly":"pneumo","fiche":"p188","front":"Tiotropium : quelle classe ?","back":"**Antimuscarinique** (anticholinergique) inhalé de **longue durée d'action**.","prio":"P2","sec":"s9"},{"id":"fc-p188-dfd5f5","poly":"pneumo","fiche":"p188","front":"Corticoïdes inhalés : citer les molécules ?","back":"**Béclométhasone**, **budésonide**, **fluticasone**, **ciclésonide**.","prio":"P2","sec":"s9"},{"id":"fc-p188-4bb527","poly":"pneumo","fiche":"p188","front":"CSI : quel rôle dans l'asthme ?","back":"**Anti-inflammatoire le plus efficace** de l'asthme (traitement de fond).","prio":"P1","sec":"s9"},{"id":"fc-p188-63bb8f","poly":"pneumo","fiche":"p188","front":"BDLA : citer les molécules ?","back":"**Salmétérol**, **formotérol**.","prio":"P2","sec":"s9"},{"id":"fc-p188-6d9420","poly":"pneumo","fiche":"p188","front":"BDLA : quelle règle d'utilisation dans l'asthme ?","back":"**Toujours associé à un CSI** (idéalement même dispositif) : un BDLA seul **augmente le risque de décès**.","prio":"P1","sec":"s9"},{"id":"fc-p188-6aa197","poly":"pneumo","fiche":"p188","front":"Montélukast : quelle classe et quelle place ?","back":"**Anti-leucotriène** oral : alternative au BDLA en association au CSI, **moins efficace** que le BDLA.","prio":"P2","sec":"s9"},{"id":"fc-p188-be24f5","poly":"pneumo","fiche":"p188","front":"Corticoïdes systémiques de l'exacerbation : quelle voie préférer ?","back":"**Voie orale**, préférée à l'IM et l'IV en l'absence de trouble de la conscience.","prio":"P2","sec":"s9"},{"id":"fc-p188-be057e","poly":"pneumo","fiche":"p188","front":"Corticoïdes systémiques dans l'exacerbation : en combien de temps agissent-ils ?","back":"En **4 à 6 h**.","prio":"P2","sec":"s9"},{"id":"fc-p188-050921","poly":"pneumo","fiche":"p188","front":"BDCA : citer les molécules ?","back":"**Salbutamol**, **terbutaline**.","prio":"P2","sec":"s9"},{"id":"fc-p188-ebbaf2","poly":"pneumo","fiche":"p188","front":"BDCA : quelles indications de choix ?","back":"Traitement des **symptômes** et **prévention de l'asthme d'effort** ; association BDCA + CSI licite.","prio":"P2","sec":"s9"},{"id":"fc-p188-4bce76","poly":"pneumo","fiche":"p188","front":"Ipratropium : quelle classe et quelle indication dans l'asthme ?","back":"**Anticholinergique** nébulisé, associé au BDCA dans l'**asthme aigu grave**.","prio":"P2","sec":"s9"},{"id":"fc-p188-44cb95","poly":"pneumo","fiche":"p188","front":"Asthme : en quelles unités s'expriment les doses de CSI et de corticoïdes systémiques ?","back":"CSI en **µg/j** ; corticoïdes systémiques en **mg/j**.","prio":"P3","sec":"s9"},{"id":"fc-p188-7b14b7","poly":"pneumo","fiche":"p188","front":"Une nébulisation équivaut à combien de bouffées d'aérosol doseur ?","back":"**50 bouffées**.","prio":"P3","sec":"s9"},{"id":"fc-p188-2d398c","poly":"pneumo","fiche":"p188","front":"Traitement de fond de l'asthme : quand le débuter ?","back":"**Dès que l'asthme est évoqué** ; en pratique, symptômes **plus de 2 fois par mois** ; pris **chaque jour**.","prio":"P1","sec":"s10"},{"id":"fc-p188-3cfbd8","poly":"pneumo","fiche":"p188","front":"Traitement de l'asthme : quels sont les buts ?","back":"**Meilleur contrôle** des symptômes ; ↓ risque d'**exacerbation** (viser zéro), du **déclin fonctionnel** et des **effets indésirables**.","prio":"P2","sec":"s10"},{"id":"fc-p188-3df637","poly":"pneumo","fiche":"p188","front":"Traitement de fond : quel est le socle et à quel palier démarrer ?","back":"**CSI** (seul ou + bronchodilatateur) ; démarrage au **palier 2 ou 3** selon le contrôle.","prio":"P1","sec":"s10"},{"id":"fc-p188-22e489","poly":"pneumo","fiche":"p188","front":"Asthme : que comportent les paliers 1 et 2 ?","back":"Palier 1 : **pas de traitement de fond** ; palier 2 : **CSI faible dose**.","prio":"P1","sec":"s10"},{"id":"fc-p188-dc8592","poly":"pneumo","fiche":"p188","front":"Asthme : que comportent les paliers 3 et 4 ?","back":"Palier 3 : **CSI faible dose + BDLA** ; palier 4 : **CSI dose modérée + BDLA**.","prio":"P1","sec":"s10"},{"id":"fc-p188-b90c5f","poly":"pneumo","fiche":"p188","front":"Asthme : que comporte le palier 5 ?","back":"**CSI dose forte + BDLA**, avis **pneumologue**, ajout de **tiotropium**, discussion d'une **biothérapie**.","prio":"P1","sec":"s10"},{"id":"fc-p188-c1d608","poly":"pneumo","fiche":"p188","front":"Asthme : quel traitement de secours à tous les paliers ?","back":"**BDCA à la demande** (salbutamol ou terbutaline).","prio":"P1","sec":"s10"},{"id":"fc-p188-58b628","poly":"pneumo","fiche":"p188","front":"Secours : quelle alternative au BDCA aux paliers 2 à 4 ?","back":"**CSI/formotérol** à la demande dans un même dispositif.","prio":"P1","sec":"s10"},{"id":"fc-p188-67c41f","poly":"pneumo","fiche":"p188","front":"CSI/formotérol : pourquoi peut-il servir de fond et de secours ?","back":"Le **formotérol** est le **seul BDLA d'action rapide**.","prio":"P2","sec":"s10"},{"id":"fc-p188-c1118e","poly":"pneumo","fiche":"p188","front":"Perte de contrôle de l'asthme : quelle dose de BDCA ?","back":"**2 à 8 bouffées** (chambre d'inhalation si possible), puis réévaluation à **1 h**.","prio":"P1","sec":"s13"},{"id":"fc-p188-ccad1c","poly":"pneumo","fiche":"p188","front":"Asthme : « autres options » au palier 2 ?","back":"**Anti-leucotriène** ou **CSI-formotérol à la demande** (validées, moins efficaces que la ligne principale).","prio":"P3","sec":"s10"},{"id":"fc-p188-99f611","poly":"pneumo","fiche":"p188","front":"Asthme : « autre option » au palier 5 ?","back":"**Corticoïde oral faible dose**.","prio":"P3","sec":"s10"},{"id":"fc-p188-d0a9f6","poly":"pneumo","fiche":"p188","front":"Asthme : « autres options » aux paliers 3 et 4 ?","back":"Palier 3 : CSI dose modérée à forte ou CSI faible dose + ALT ; palier 4 : CSI dose forte + ALT.","prio":"P3","sec":"s10"},{"id":"fc-p188-e59aae","poly":"pneumo","fiche":"p188","front":"Asthme révélé par une exacerbation : quel traitement de fond ?","back":"Traiter l'exacerbation **et** débuter d'emblée un traitement de fond de **palier 3**.","prio":"P1","sec":"s10"},{"id":"fc-p188-1d3cb6","poly":"pneumo","fiche":"p188","front":"Prescription d'un traitement inhalé : quelle mesure associée ?","back":"**Éducation au maniement** du dispositif, technique **revérifiée à chaque consultation**.","prio":"P2","sec":"s10"},{"id":"fc-p188-f1043c","poly":"pneumo","fiche":"p188","front":"Asthme non contrôlé malgré la vérification des causes : que faire ?","back":"Passer au **palier supérieur** ; si non-contrôle persistant : **spécialiste** et/ou centre expert de l'asthme sévère.","prio":"P1","sec":"s11"},{"id":"fc-p188-3a6c94","poly":"pneumo","fiche":"p188","front":"Asthme contrôlé : comment adapter le traitement de fond ?","back":"Même traitement ou **diminution** vers la **dose minimale efficace**.","prio":"P1","sec":"s11"},{"id":"fc-p188-6e6ade","poly":"pneumo","fiche":"p188","front":"Adulte ou adolescent contrôlé : jusqu'où peut-on diminuer le traitement ?","back":"Garder **au minimum un CSI faible dose** (pas d'arrêt du CSI).","prio":"P1","sec":"s11"},{"id":"fc-p188-b5f793","poly":"pneumo","fiche":"p188","front":"Asthme sévère : quand envisager une corticothérapie orale au long cours ?","back":"Certains asthmes sévères, **si une biothérapie n'est pas disponible**, suivi avec le pneumologue.","prio":"P2","sec":"s11"},{"id":"fc-p188-32c528","poly":"pneumo","fiche":"p188","front":"Asthme : quelles situations liées au diagnostic et à la fonction imposent un avis pneumologique ?","back":"Diagnostic **différentiel ou associé** · **spirométrie non accessible** · **VEMS < 80 %**.","prio":"P2","sec":"s11"},{"id":"fc-p188-b98894","poly":"pneumo","fiche":"p188","front":"Asthme : quelles situations liées au traitement imposent un avis pneumologique ?","back":"**CSI dose moyenne ou forte** · **> 500 mg de corticoïde oral/an** et/ou **3 flacons de BDCA/an** · contrôle non obtenu **malgré une prise en charge optimale** · **asthme sévère**.","prio":"P2","sec":"s11"},{"id":"fc-p188-20d70d","poly":"pneumo","fiche":"p188","front":"Asthme sévère : pourquoi adresser vite au pneumologue ?","back":"Pour **ne pas retarder une biothérapie**.","prio":"P2","sec":"s11"},{"id":"fc-p188-07972d","poly":"pneumo","fiche":"p188","front":"Asthme : quel rythme de suivi ?","back":"Adapté à la sévérité, **au minimum 1 fois/an** ; **3 mois** après chaque changement ; **mensuel** pendant la grossesse.","prio":"P2","sec":"s11"},{"id":"fc-p188-af9c45","poly":"pneumo","fiche":"p188","front":"Asthme : quelle spirométrie au suivi ?","back":"Spirométrie **± test de réversibilité** si celle-ci n'a pas encore été documentée.","prio":"P2","sec":"s11"},{"id":"fc-p188-e05df0","poly":"pneumo","fiche":"p188","front":"Asthme : pourquoi prendre en charge les facteurs favorisants ?","back":"Sans eux, l'asthme **ne peut pas être contrôlé**.","prio":"P2","sec":"s12"},{"id":"fc-p188-5c8cbd","poly":"pneumo","fiche":"p188","front":"Asthme : quelles mesures sur l'environnement et le tabac ?","back":"**Sevrage tabagique** encouragé fortement et de façon répétée · éviction des **irritants** domestiques et professionnels.","prio":"P2","sec":"s12"},{"id":"fc-p188-cfc689","poly":"pneumo","fiche":"p188","front":"Asthme : quelle comorbidité ORL traiter ?","back":"La **rhinite** associée (et les allergies).","prio":"P2","sec":"s12"},{"id":"fc-p188-769630","poly":"pneumo","fiche":"p188","front":"β-bloquants chez l'asthmatique : quelle précaution ?","back":"Peuvent aggraver l'asthme, **collyres compris** → avis pneumologique avant prescription si asthme non contrôlé.","prio":"P1","sec":"s12"},{"id":"fc-p188-351b67","poly":"pneumo","fiche":"p188","front":"Aspirine et AINS chez l'asthmatique : quand sont-ils contre-indiqués ?","back":"En cas d'**antécédent d'hypersensibilité** à ces molécules.","prio":"P2","sec":"s12"},{"id":"fc-p188-6a9f60","poly":"pneumo","fiche":"p188","front":"Asthme : quelles comorbidités fréquentes prendre en charge ?","back":"**Obésité** · troubles psychiatriques · **RGO** · **SAOS** · maladies cardiovasculaires · complications des corticoïdes (ostéoporose, diabète).","prio":"P2","sec":"s12"},{"id":"fc-p188-212060","poly":"pneumo","fiche":"p188","front":"Asthme : quelles vaccinations ?","back":"**Antigrippal** chez tous · **anti-COVID** à jour · **antipneumococcique** si asthme sévère.","prio":"P2","sec":"s12"},{"id":"fc-p188-30f92b","poly":"pneumo","fiche":"p188","front":"Asthme : quelle recommandation sur l'activité physique ?","back":"Encourager **systématiquement** une activité physique régulière.","prio":"P2","sec":"s12"},{"id":"fc-p188-4399ea","poly":"pneumo","fiche":"p188","front":"Plan d'action écrit : qu'apprend-il au patient ?","back":"Juger la gravité d'une exacerbation (**symptômes + DEP**), le traitement à prendre, comment **accéder aux soins** si gravité ou échec.","prio":"P2","sec":"s12"},{"id":"fc-p188-8bd4a8","poly":"pneumo","fiche":"p188","front":"Éducation thérapeutique dans l'asthme : quels bénéfices ?","back":"Améliore **observance** et **contrôle**, **réduit les exacerbations**, optimise l'usage du système d'inhalation.","prio":"P2","sec":"s12"},{"id":"fc-p188-25a63e","poly":"pneumo","fiche":"p188","front":"Éducation thérapeutique : quelles compétences visées ?","back":"Comprendre la maladie · reconnaître perte de contrôle/exacerbation · **mesurer son DEP** · connaître ses traitements · maîtriser l'**inhalation** · appliquer le **plan d'action**.","prio":"P2","sec":"s12"},{"id":"fc-p188-e7c0da","poly":"pneumo","fiche":"p188","front":"Exacerbation : quelle voie pour les BDCA et pourquoi ?","back":"**Inhalée, toujours** : plus efficace et plus sûre que les autres voies (SC, IV).","prio":"P2","sec":"s13"},{"id":"fc-p188-548d35","poly":"pneumo","fiche":"p188","front":"Exacerbation hors milieu médical : quelle posologie de BDCA ?","back":"**4 à 10 bouffées** toutes les **20 min** pendant 1 h (chambre d'inhalation si disponible).","prio":"P1","sec":"s13"},{"id":"fc-p188-96a712","poly":"pneumo","fiche":"p188","front":"Exacerbation en milieu médicalisé : quelle posologie de BDCA ?","back":"Nébulisation de **5 mg** en 10-15 min, toutes les **20 min** la 1re heure, gaz vecteur **oxygène 6 L/min**.","prio":"P1","sec":"s13"},{"id":"fc-p188-fc9130","poly":"pneumo","fiche":"p188","front":"Exacerbation : quelle corticothérapie systémique ?","back":"**Prednisone/prednisolone** orale **0,5 à 1 mg/kg/j**, **≤ 60 mg/j**, débutée sans attendre.","prio":"P1","sec":"s13"},{"id":"fc-p188-54d459","poly":"pneumo","fiche":"p188","front":"Corticothérapie de l'exacerbation : quelle durée et quel arrêt ?","back":"**5 à 7 jours**, arrêt **sans décroissance**.","prio":"P1","sec":"s13"},{"id":"fc-p188-79866a","poly":"pneumo","fiche":"p188","front":"Exacerbation modérée hypoxémique : quelle cible de SpO₂ ?","back":"**94 à 98 %**.","prio":"P1","sec":"s13"},{"id":"fc-p188-5375fb","poly":"pneumo","fiche":"p188","front":"Exacerbation : quels facteurs favorisants rechercher ?","back":"**Infection**, **médicament**, **exposition allergénique**.","prio":"P2","sec":"s13"},{"id":"fc-p188-5df60a","poly":"pneumo","fiche":"p188","front":"Exacerbation modérée : quand autoriser le retour à domicile ?","back":"À **1 h** : **DEP normalisé** et symptômes disparus → domicile avec traitement et rendez-vous.","prio":"P2","sec":"s13"},{"id":"fc-p188-d6eaac","poly":"pneumo","fiche":"p188","front":"Exacerbation : de quoi dépend souvent l'orientation ?","back":"**Absence d'accompagnant** à domicile, **âge**, **comorbidités**.","prio":"P2","sec":"s13"},{"id":"fc-p188-84133b","poly":"pneumo","fiche":"p188","front":"Exacerbation modérée sans amélioration après 1 h : que faire ?","back":"Transfert en **soins intensifs** (transport médicalisé si besoin d'un transport) et traitement de l'exacerbation sévère.","prio":"P1","sec":"s13"},{"id":"fc-p188-e6510e","poly":"pneumo","fiche":"p188","front":"Après toute exacerbation : que faire du traitement de fond ?","back":"Le **débuter ou l'augmenter**.","prio":"P1","sec":"s13"},{"id":"fc-p188-fb01df","poly":"pneumo","fiche":"p188","front":"Exacerbation : comment surveiller ?","back":"Surveillance **clinique** très rapprochée (dyspnée, FR, auscultation, pouls, PA, SpO₂) et **DEP répété**.","prio":"P2","sec":"s13"},{"id":"fc-p188-75d3f8","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quelle orientation ?","back":"Traitement dès le domicile puis **transfert médicalisé en USI**, sans retarder le traitement.","prio":"P1","sec":"s14"},{"id":"fc-p188-c325a9","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quelle cible de SpO₂ ?","back":"**93 à 95 %**.","prio":"P1","sec":"s14"},{"id":"fc-p188-7e544d","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quel schéma de nébulisation de β2-mimétique ?","back":"**5 mg** en 10-15 min toutes les **20 min** la 1re heure (au moins 3 fois ou en continu), gaz vecteur oxygène.","prio":"P1","sec":"s14"},{"id":"fc-p188-494351","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quelle posologie d'ipratropium ?","back":"**0,5 mg** nébulisé en 10-15 min, **toutes les 8 heures**.","prio":"P1","sec":"s14"},{"id":"fc-p188-029a18","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave en échec des nébulisations : quel traitement ?","back":"**Salbutamol IV** à la seringue électrique, doses croissantes depuis **0,25-0,5 mg/h**.","prio":"P1","sec":"s14"},{"id":"fc-p188-5e5ac0","poly":"pneumo","fiche":"p188","front":"Salbutamol IV : quelle précaution obligatoire et pourquoi ?","back":"**Scope obligatoire** : effet adrénergique, **hypokaliémie** majorée par les corticoïdes.","prio":"P1","sec":"s14"},{"id":"fc-p188-fbb836","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave avec infection suspectée : faut-il différer les corticoïdes ?","back":"**Non** : **aucune contre-indication** dans l'exacerbation sévère, même COVID-19 suspecté.","prio":"P1","sec":"s14"},{"id":"fc-p188-877685","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quand recourir à la ventilation mécanique ?","back":"Devant un **signe de gravité extrême**.","prio":"P2","sec":"s14"},{"id":"fc-p188-18aff9","poly":"pneumo","fiche":"p188","front":"Asthme aigu grave : quels effets indésirables du traitement guetter ?","back":"**Hyperglycémie** (corticoïdes) · **hypokaliémie** (BDCA, corticoïdes) · **acidose lactique** (BDCA) · **tachycardie**, troubles du rythme.","prio":"P2","sec":"s14"},{"id":"fc-p188-ef1a28","poly":"pneumo","fiche":"p188","front":"Rhinite chronique : quelle définition ?","back":"Maladie **inflammatoire chronique des VAS** avec symptômes **PAREO**.","prio":"P2","sec":"s15"},{"id":"fc-p188-585cf4","poly":"pneumo","fiche":"p188","front":"PAREO : que signifie l'acronyme ?","back":"**P**rurit · **A**nosmie · **R**hinorrhée · **É**ternuements · **O**bstruction nasale.","prio":"P1","sec":"s15"},{"id":"fc-p188-c1e5bd","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelle définition ?","back":"Rhinite avec inflammation **IgE-dépendante** rattachable à une exposition aux **pneumallergènes**.","prio":"P1","sec":"s15"},{"id":"fc-p188-fa646e","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : comment se fait le diagnostic ?","back":"**Clinique** : symptômes, examen du nez, recherche de sensibilisations ; caractère allergique à **argumenter**.","prio":"P1","sec":"s15"},{"id":"fc-p188-dfd5a4","poly":"pneumo","fiche":"p188","front":"Rhinite allergique polysensibilisée : quel rôle de l'interrogatoire ?","back":"Établir quels allergènes sont **réellement en cause**.","prio":"P2","sec":"s15"},{"id":"fc-p188-06eb75","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quels signes de conjonctivite associée ?","back":"**Larmoiement**, rougeur, brûlure, photosensibilité, **prurit oculaire**.","prio":"P2","sec":"s15"},{"id":"fc-p188-fda33e","poly":"pneumo","fiche":"p188","front":"Rhinite : comment examiner les fosses nasales et que chercher ?","back":"**Spéculum nasal** (à défaut otoscope) : muqueuse inflammatoire ; chercher des **polypes**.","prio":"P2","sec":"s15"},{"id":"fc-p188-9d3def","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : faut-il une imagerie ?","back":"**Non**, sauf recherche d'un **diagnostic différentiel ou associé**.","prio":"P2","sec":"s15"},{"id":"fc-p188-e21713","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : à quoi s'associe-t-elle souvent et comment évolue-t-elle ?","back":"**Asthme** ou **conjonctivite** ; exacerbations souvent **saisonnières** selon les pneumallergènes.","prio":"P2","sec":"s15"},{"id":"fc-p188-1ae212","poly":"pneumo","fiche":"p188","front":"Rhinite allergique intermittente vs persistante : quel seuil ?","back":"Intermittente **≤ 4 semaines consécutives/an** ; persistante **> 4 semaines consécutives/an**.","prio":"P1","sec":"s15"},{"id":"fc-p188-d62ff0","poly":"pneumo","fiche":"p188","front":"Rhinite allergique sévère : quelle définition ?","back":"**≥ 1 item perturbé** : sommeil, activités sociales/sportives, activités professionnelles/scolaires, symptômes gênants.","prio":"P1","sec":"s15"},{"id":"fc-p188-2575ee","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelles sont les mesures de base ?","back":"**Éviction** de l'allergène · **lavage nasal** au sérum physiologique.","prio":"P2","sec":"s16"},{"id":"fc-p188-bb34d6","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quels médicaments principaux ?","back":"**Antihistaminiques H1 de 2e génération** (oraux et/ou locaux) et **corticoïdes nasaux**.","prio":"P1","sec":"s16"},{"id":"fc-p188-372bb5","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : antihistaminique ou corticoïde nasal en 1re intention ?","back":"**Aucun privilégié** ; association possible en cas d'inefficacité.","prio":"P1","sec":"s16"},{"id":"fc-p188-9f934a","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelles interventions modifient l'histoire naturelle ?","back":"**Mesures d'éviction** et **immunothérapie allergénique**.","prio":"P2","sec":"s16"},{"id":"fc-p188-bf4f6c","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelle éducation est indispensable ?","back":"Technique du **lavage des fosses nasales** et utilisation des **gouttes nasales**.","prio":"P2","sec":"s16"},{"id":"fc-p188-454e9f","poly":"pneumo","fiche":"p188","front":"Rhinite allergique : quelles mesures non médicamenteuses ?","back":"**Sevrage tabagique** · prise en charge du **stress et de l'anxiété**.","prio":"P2","sec":"s16"},{"id":"fc-p188-cd46c2","poly":"pneumo","fiche":"p188","front":"Vasoconstricteurs nasaux : quelle règle ?","back":"**Déconseillés au long cours** (rhinite iatrogène), surtout chez le **coronarien** (spasme coronaire).","prio":"P1","sec":"s16"},{"id":"fc-p203-682fa9","poly":"pneumo","fiche":"p203","front":"Dyspnée : définition ?","back":"Impression de respirer de façon **inconfortable ou pénible**, au repos ou à l'effort, dans des circonstances qui normalement ne gênent pas.","prio":"P1","sec":"s1"},{"id":"fc-p203-d44550","poly":"pneumo","fiche":"p203","front":"Dyspnée : quelles sont ses deux composantes ?","back":"**Sensorielle** (afférences périphériques : oppression, inspiration incomplète) + **affective/émotionnelle** (désagrément, anxiété, frayeur).","prio":"P2","sec":"s1"},{"id":"fc-p203-ff4927","poly":"pneumo","fiche":"p203","front":"Dyspnée et tachypnée : sont-elles synonymes ?","back":"**Non** : on peut respirer vite sans gêne, ou être gêné sans respirer vite.","prio":"P1","sec":"s1"},{"id":"fc-p203-d843b5","poly":"pneumo","fiche":"p203","front":"Expression de la dyspnée par le patient : est-elle uniforme ?","back":"**Non** : très variable, notamment selon l'**origine culturelle** (terme peu connu).","prio":"P3","sec":"s1"},{"id":"fc-p203-dc514f","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë : délai d'installation ?","back":"**Quelques heures à quelques jours** ; début datable.","prio":"P1","sec":"s1"},{"id":"fc-p203-47c33c","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : durée minimale ?","back":"Au moins **8 semaines** (jusqu'à des mois ou années).","prio":"P1","sec":"s1"},{"id":"fc-p203-9f98f5","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique d'installation progressive : que chercher malgré tout à l'interrogatoire ?","back":"Un **facteur déclenchant** ou une **date de début**, et une **aggravation récente**.","prio":"P2","sec":"s1"},{"id":"fc-p203-e05f07","poly":"pneumo","fiche":"p203","front":"Hyperpnée et hypopnée : quel paramètre respiratoire décrivent-elles ?","back":"Le **volume courant** (amplitude) : augmenté = hyperpnée ; diminué = hypopnée.","prio":"P2","sec":"s1"},{"id":"fc-p203-6a7d49","poly":"pneumo","fiche":"p203","front":"Tachypnée (polypnée) et bradypnée : définitions ?","back":"Fréquence respiratoire **excessive** (tachypnée) ou **franchement réduite** (bradypnée).","prio":"P2","sec":"s1"},{"id":"fc-p203-e07d4d","poly":"pneumo","fiche":"p203","front":"Hyperventilation excessive (HVE) : définition ?","back":"Ventilation **au-delà des besoins**, avec fréquence et volume courant augmentés **de façon harmonieuse**.","prio":"P2","sec":"s1"},{"id":"fc-p203-787742","poly":"pneumo","fiche":"p203","front":"« Dysfunctional breathing » : définition ?","back":"HVE où fréquence et volume courant augmentent de façon **non harmonieuse** : trouble du **contrôle** de la ventilation.","prio":"P2","sec":"s1"},{"id":"fc-p203-cf76e4","poly":"pneumo","fiche":"p203","front":"Sémiologie de la dyspnée : sur quoi repose-t-elle d'abord ?","back":"Sur l'**interrogatoire** (circonstances et même les **mots choisis** par le patient orientent).","prio":"P2","sec":"s2"},{"id":"fc-p203-641080","poly":"pneumo","fiche":"p203","front":"Dyspnée : premières questions clés de l'interrogatoire ?","back":"**Aiguë ou chronique** ? **Chez qui** (terrain, traitements) ? **Facteurs favorisants** ? **Quand** ? **Comment** (position, effort) ?","prio":"P2","sec":"s2"},{"id":"fc-p203-169843","poly":"pneumo","fiche":"p203","front":"Dyspnée : facteurs favorisants à rechercher ?","back":"**Allergène**, **arrêt d'un médicament**, **infection**, **voyage en avion**, **chirurgie**, cause **iatrogène**.","prio":"P2","sec":"s2"},{"id":"fc-p203-3bf560","poly":"pneumo","fiche":"p203","front":"Dyspnée inspiratoire avec cornage : quel étage atteint ?","back":"**Voies aériennes supérieures** (larynx, trachée extra-thoracique).","prio":"P1","sec":"s2"},{"id":"fc-p203-de6adb","poly":"pneumo","fiche":"p203","front":"Dyspnée avec sifflements expiratoires : quel étage atteint ?","back":"Les **bronches**.","prio":"P1","sec":"s2"},{"id":"fc-p203-7b7062","poly":"pneumo","fiche":"p203","front":"Orthopnée : définition et première hypothèse ?","back":"Dyspnée en **décubitus dorsal** ; d'abord **insuffisance cardiaque** (aussi dysfonction diaphragmatique, obésité).","prio":"P1","sec":"s2"},{"id":"fc-p203-82bb37","poly":"pneumo","fiche":"p203","front":"Antépnée : définition et causes ?","back":"Dyspnée **penché en avant** ; **dysfonction diaphragmatique**, **obésité**.","prio":"P1","sec":"s2"},{"id":"fc-p203-618c9f","poly":"pneumo","fiche":"p203","front":"Platypnée : définition et mécanisme évoqué ?","back":"Dyspnée en **position debout** ; **shunt** intracardiaque ou intrapulmonaire.","prio":"P1","sec":"s2"},{"id":"fc-p203-56600c","poly":"pneumo","fiche":"p203","front":"Platypnée : causes de shunt à évoquer ?","back":"**Foramen ovale perméable** ; malformation/fistule **artério-veineuse** pulmonaire ; **syndrome hépato-pulmonaire**.","prio":"P2","sec":"s2"},{"id":"fc-p203-cbbec0","poly":"pneumo","fiche":"p203","front":"Dyspnée nocturne : deux causes à évoquer avant tout ?","back":"**Œdème aigu pulmonaire** et **asthme**.","prio":"P1","sec":"s2"},{"id":"fc-p203-bb7e13","poly":"pneumo","fiche":"p203","front":"Bruits respiratoires : stridor/cornage et sibilants, quel temps respiratoire ?","back":"Stridor, cornage = **inspiratoires** ; sibilants, sifflements = **expiratoires**.","prio":"P2","sec":"s2"},{"id":"fc-p203-0ac5bf","poly":"pneumo","fiche":"p203","front":"Examen d'un dyspnéique : deux signes soulignés par le Collège ?","back":"**Mise en jeu inspiratoire des muscles du cou** et **respiration abdominale paradoxale**.","prio":"P1","sec":"s2"},{"id":"fc-p203-549db8","poly":"pneumo","fiche":"p203","front":"Dyspnée : signes généraux à rechercher ?","back":"**Fièvre**, **altération de l'état général**, **sueurs**.","prio":"P3","sec":"s2"},{"id":"fc-p203-e090bd","poly":"pneumo","fiche":"p203","front":"Dyspnée inexpliquée : quel syndrome évoquer ?","back":"**Syndrome d'hyperventilation** (« dysfunctional breathing »).","prio":"P1","sec":"s2"},{"id":"fc-p203-570e88","poly":"pneumo","fiche":"p203","front":"Syndrome d'hyperventilation : éléments évocateurs ?","back":"**Examen clinique normal**, gêne **non liée à l'effort**, **vertiges**, **paresthésies**.","prio":"P2","sec":"s2"},{"id":"fc-p203-43d2f9","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë : statut par défaut et première chose à apprécier ?","back":"**Urgence jusqu'à preuve du contraire** ; apprécier d'abord le **pronostic vital**.","prio":"P1","sec":"s3"},{"id":"fc-p203-1a61ef","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire aiguë : quel risque majeur peut-elle annoncer ?","back":"Un **arrêt cardio-circulatoire d'origine hypoxique**.","prio":"P1","sec":"s3"},{"id":"fc-p203-200084","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire aiguë (DRA) : définition ?","back":"Signes respiratoires traduisant un **déséquilibre** entre la **charge** imposée à l'appareil respiratoire et sa **capacité** à y faire face.","prio":"P2","sec":"s3"},{"id":"fc-p203-d8b128","poly":"pneumo","fiche":"p203","front":"Insuffisance respiratoire aiguë : définition gazométrique ?","back":"**PaO₂ < 60 mmHg** et modification du pH, notamment acidose avec **PaCO₂ > 45 mmHg**.","prio":"P1","sec":"s3"},{"id":"fc-p203-16c316","poly":"pneumo","fiche":"p203","front":"Hypoxies tissulaires sans hypoxémie : citer des exemples ?","back":"Transport d'O₂ altéré : **anémie**, **intoxication au CO**, **choc** ; respiration cellulaire altérée : **cyanure**, sepsis grave.","prio":"P2","sec":"s3"},{"id":"fc-p203-367e24","poly":"pneumo","fiche":"p203","front":"DRA avec gaz du sang faussement rassurants : conduite ?","back":"Si la détresse persiste : **refaire les gaz tôt**, penser aux hypoxies sans hypoxémie, **doser le lactate**.","prio":"P3","sec":"s3"},{"id":"fc-p203-a34183","poly":"pneumo","fiche":"p203","front":"DRA : que peut masquer une hypocapnie marquée avec une PaO₂ normale ?","back":"Une **hypoxémie profonde** compensée par l'**hyperventilation**.","prio":"P3","sec":"s3"},{"id":"fc-p203-265934","poly":"pneumo","fiche":"p203","front":"Tachypnée chez l'adulte : seuil de fréquence respiratoire ?","back":"FR **> 25/min**.","prio":"P1","sec":"s3"},{"id":"fc-p203-342637","poly":"pneumo","fiche":"p203","front":"DRA : citer les signes de lutte ?","back":"**Tachypnée**, **tirage** (sus-claviculaire, sus-sternal, intercostal), **expiration abdominale active**, **stridor**.","prio":"P1","sec":"s3"},{"id":"fc-p203-fd5cf4","poly":"pneumo","fiche":"p203","front":"Pouls inspiratoire : définition ?","back":"Perception au doigt de la contraction des **muscles inspiratoires extra-diaphragmatiques** (tirage).","prio":"P3","sec":"s3"},{"id":"fc-p203-1db890","poly":"pneumo","fiche":"p203","front":"Stridor : quelle obstruction traduit-il ?","back":"Obstruction des **voies aériennes hautes** (larynx, trachée cervicale).","prio":"P2","sec":"s3"},{"id":"fc-p203-648286","poly":"pneumo","fiche":"p203","front":"Expiration abdominale active : vers quel type de pathologie oriente-t-elle ?","back":"Souvent une pathologie **obstructive**, mais pas seulement.","prio":"P3","sec":"s3"},{"id":"fc-p203-db6e07","poly":"pneumo","fiche":"p203","front":"DRA : citer les signes de faillite ?","back":"**Respiration abdominale paradoxale**, **cyanose**, **signes neurologiques**, **signes hémodynamiques**.","prio":"P1","sec":"s3"},{"id":"fc-p203-d564c8","poly":"pneumo","fiche":"p203","front":"DRA : combien de signes de faillite pour parler de détresse grave ?","back":"**Un seul** suffit.","prio":"P1","sec":"s3"},{"id":"fc-p203-cec68b","poly":"pneumo","fiche":"p203","front":"Respiration abdominale paradoxale : description et signification ?","back":"L'abdomen se **creuse à l'inspiration** ; le diaphragme ne participe plus = faillite de la **pompe ventilatoire**.","prio":"P1","sec":"s3"},{"id":"fc-p203-256c11","poly":"pneumo","fiche":"p203","front":"Respiration abdominale paradoxale : quelle position est proscrite ?","back":"Le **décubitus dorsal** (qui l'aggrave).","prio":"P1","sec":"s3"},{"id":"fc-p203-218d8a","poly":"pneumo","fiche":"p203","front":"Respiration abdominale paradoxale : quelle décision discuter ?","back":"Une **assistance ventilatoire**, au minimum admission là où elle peut être posée sans délai.","prio":"P2","sec":"s3"},{"id":"fc-p203-1f6633","poly":"pneumo","fiche":"p203","front":"Cyanose : de quelle faillite témoigne-t-elle ?","back":"Faillite de l'**oxygénation**.","prio":"P2","sec":"s3"},{"id":"fc-p203-f5dc15","poly":"pneumo","fiche":"p203","front":"Bradypnée ou respiration irrégulière en détresse : signification ?","back":"Défaillance plutôt **neurologique** ; **arrêt respiratoire imminent**.","prio":"P1","sec":"s3"},{"id":"fc-p203-23a3c1","poly":"pneumo","fiche":"p203","front":"Cyanose : seuil d'hémoglobine réduite d'apparition ?","back":"Hémoglobine réduite **> 5 g/dl**.","prio":"P2","sec":"s3"},{"id":"fc-p203-d12ccc","poly":"pneumo","fiche":"p203","front":"Cyanose chez le sujet à peau noire : où la chercher ?","back":"Sur la **langue**.","prio":"P3","sec":"s3"},{"id":"fc-p203-a7763f","poly":"pneumo","fiche":"p203","front":"Cyanose : effet d'une anémie profonde et d'une polyglobulie ?","back":"Anémie : **absente ou très tardive** ; polyglobulie : **fréquente et moins spécifique**.","prio":"P2","sec":"s3"},{"id":"fc-p203-ce450f","poly":"pneumo","fiche":"p203","front":"Cyanose : sensibilité et spécificité, et conduite ?","back":"**Peu sensible mais spécifique** → **oxygène immédiat**.","prio":"P1","sec":"s3"},{"id":"fc-p203-75f23c","poly":"pneumo","fiche":"p203","front":"Cyanose avec Hb à 14 g/dl : SpO₂ correspondante approximative ?","back":"Environ **80 %** (PaO₂ ≈ 45-50 mmHg).","prio":"P3","sec":"s3"},{"id":"fc-p203-b93014","poly":"pneumo","fiche":"p203","front":"SpO₂ en détresse : seuil imposant l'oxygène immédiat ?","back":"**< 90 %** (alerte plus tôt que la cyanose).","prio":"P1","sec":"s3"},{"id":"fc-p203-2019f9","poly":"pneumo","fiche":"p203","front":"Signes neurologiques de détresse : quelle anomalie gazométrique font-ils suspecter ?","back":"Une **hypercapnie**.","prio":"P1","sec":"s3"},{"id":"fc-p203-1bab0f","poly":"pneumo","fiche":"p203","front":"Astérixis : que suggère-t-il en détresse respiratoire, et est-il spécifique ?","back":"**Hypercapnie** installée assez vite ; **non spécifique** (aussi encéphalopathie hépatique).","prio":"P2","sec":"s3"},{"id":"fc-p203-4859af","poly":"pneumo","fiche":"p203","front":"Troubles de vigilance par hypercapnie : terme pour les troubles de conscience francs ?","back":"**Carbonarcose**.","prio":"P2","sec":"s3"},{"id":"fc-p203-a29739","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : seuil de Glasgow imposant l'intubation ?","back":"**Glasgow < 9** (protéger les voies aériennes d'une inhalation).","prio":"P2","sec":"s3"},{"id":"fc-p203-f90750","poly":"pneumo","fiche":"p203","front":"Insuffisance cardiaque droite aiguë en détresse : quelles causes évoquer ?","back":"**EP massive**, **pneumothorax compressif**, **asthme aigu grave**, **tamponnade**.","prio":"P1","sec":"s3"},{"id":"fc-p203-efcbac","poly":"pneumo","fiche":"p203","front":"Pouls paradoxal : définition et causes évoquées ?","back":"Baisse de la PAS à l'**inspiration** ; **asthme aigu grave** ou **tamponnade**.","prio":"P3","sec":"s3"},{"id":"fc-p203-a7acd1","poly":"pneumo","fiche":"p203","front":"État de choc en détresse respiratoire : critères tensionnels et de pouls ?","back":"PAS **< 90 mmHg** ou chute **> 30 mmHg** ; tachycardie **> 120/min** ; + marbrures, confusion, oligurie.","prio":"P2","sec":"s3"},{"id":"fc-p203-95d5b9","poly":"pneumo","fiche":"p203","front":"HTA au cours d'une détresse respiratoire : que faire rechercher ?","back":"Une **hypercapnie**.","prio":"P2","sec":"s3"},{"id":"fc-p203-24a8a7","poly":"pneumo","fiche":"p203","front":"Hypercapnie : signes de vasodilatation et de réaction adrénergique ?","back":"**Céphalées**, conjonctives hyperhémiées ; **tremblements**, **sueurs**, **tachycardie**, **HTA**.","prio":"P2","sec":"s3"},{"id":"fc-p203-5edd7a","poly":"pneumo","fiche":"p203","front":"Expiration abdominale active vs respiration abdominale paradoxale : laquelle signe la faillite ?","back":"La **respiration abdominale paradoxale** (l'expiration active est un signe de **lutte**).","prio":"P1","sec":"s3"},{"id":"fc-p203-fe1aae","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : quand faire la radiographie thoracique ?","back":"**De face, au lit**, dès que le traitement symptomatique est débuté.","prio":"P2","sec":"s4"},{"id":"fc-p203-497761","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : examens biologiques lancés d'emblée ?","back":"**Gaz du sang + lactate**, **NFS-plaquettes**, **ionogramme, urée, créatinine** (+ ECG).","prio":"P2","sec":"s4"},{"id":"fc-p203-15e43c","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë : signes ECG de tamponnade ?","back":"**Microvoltage** ou **alternance électrique**.","prio":"P2","sec":"s4"},{"id":"fc-p203-2ba2ac","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë : valeur d'un ECG normal ?","back":"Argument important **contre un OAP cardiogénique**.","prio":"P1","sec":"s4"},{"id":"fc-p203-0098bb","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë : quand doser BNP/NT-proBNP ?","back":"Si **doute avec un OAP cardiogénique**.","prio":"P2","sec":"s4"},{"id":"fc-p203-b4ad9b","poly":"pneumo","fiche":"p203","front":"Dyspnée aiguë avec suspicion d'EP : D-dimères ou angioscanner selon la probabilité ?","back":"**D-dimères** si probabilité faible/intermédiaire ; **angioscanner** si forte ou D-dimères élevés.","prio":"P2","sec":"s4"},{"id":"fc-p203-f45e32","poly":"pneumo","fiche":"p203","front":"BNP : seuil excluant une dyspnée aiguë d'origine cardiaque ?","back":"**< 100 pg/mL** (bonne VPN).","prio":"P1","sec":"s4"},{"id":"fc-p203-5ef1b0","poly":"pneumo","fiche":"p203","front":"BNP élevé : causes hors OAP ?","back":"Toute dilatation ou post-charge élevée d'un ventricule : **HTP de l'embolie pulmonaire**, **exacerbation de BPCO**.","prio":"P2","sec":"s4"},{"id":"fc-p203-80deb2","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : première étape de l'algorithme étiologique ?","back":"**Éliminer une obstruction des voies aériennes supérieures**.","prio":"P1","sec":"s4"},{"id":"fc-p203-71bfa4","poly":"pneumo","fiche":"p203","front":"Obstruction des voies aériennes supérieures : signes évocateurs ?","back":"Patient paniqué, **mains au cou**, sans son ; **bradypnée inspiratoire** ; dysphonie/aphonie ; **cornage**, **stridor**.","prio":"P1","sec":"s4"},{"id":"fc-p203-db9dbe","poly":"pneumo","fiche":"p203","front":"Détresse avec radiographie anormale : trois causes à évoquer d'abord ?","back":"**Pneumonie**, **OAP cardiogénique**, **pneumothorax sous tension**.","prio":"P1","sec":"s4"},{"id":"fc-p203-24a3fc","poly":"pneumo","fiche":"p203","front":"Détresse avec radiographie anormale : causes de deuxième temps ?","back":"**SDRA** ; **exacerbation d'une pneumopathie infiltrative diffuse** (récupérer les imageries antérieures).","prio":"P2","sec":"s4"},{"id":"fc-p203-bd50ea","poly":"pneumo","fiche":"p203","front":"Détresse avec radiographie normale : quels examens tranchent ?","back":"La **clinique** et les **gaz du sang**.","prio":"P2","sec":"s4"},{"id":"fc-p203-8bf2f7","poly":"pneumo","fiche":"p203","front":"Radio normale, hypercapnie et bicarbonates > 30 mmol/L : quel diagnostic ?","back":"**Décompensation d'une maladie respiratoire chronique**.","prio":"P1","sec":"s4"},{"id":"fc-p203-fdaf18","poly":"pneumo","fiche":"p203","front":"Détresse à radio normale, sans hypercapnie chronique : causes aiguës de novo ?","back":"**Embolie pulmonaire**, **pneumothorax**, **exacerbation d'asthme**.","prio":"P1","sec":"s4"},{"id":"fc-p203-5ebd2e","poly":"pneumo","fiche":"p203","front":"Obstruction des voies aériennes supérieures : causes principales ?","back":"**Corps étranger**, **laryngite** (enfant), **épiglottite**, **œdème de Quincke**, **sténose trachéale**, **tumeur laryngée**.","prio":"P1","sec":"s4"},{"id":"fc-p203-ccccf7","poly":"pneumo","fiche":"p203","front":"Inhalation de corps étranger : terrains les plus exposés ?","back":"Âges extrêmes : **petit enfant** (80 % < 3 ans), **sujet âgé** avec troubles de déglutition ou de dentition.","prio":"P2","sec":"s4"},{"id":"fc-p203-330813","poly":"pneumo","fiche":"p203","front":"Épiglottite : pourquoi est-elle devenue rarissime ?","back":"**Vaccination** du nourrisson contre **Haemophilus influenzae**.","prio":"P2","sec":"s4"},{"id":"fc-p203-5d2abf","poly":"pneumo","fiche":"p203","front":"SDRA : critères de définition ?","back":"Évolution **< 7 jours** ; opacités **bilatérales diffuses** ; **sans** défaillance cardiaque ni surcharge (PAPO < 15 mmHg).","prio":"P2","sec":"s4"},{"id":"fc-p203-aa70e7","poly":"pneumo","fiche":"p203","front":"SDRA vs OAP cardiogénique : mécanisme de l'œdème ?","back":"SDRA : œdème **lésionnel** (perméabilité ↑, exsudation) ; OAP : pression **hydrostatique** ↑ (transsudation).","prio":"P2","sec":"s4"},{"id":"fc-p203-885b56","poly":"pneumo","fiche":"p203","front":"SDRA : cause endothéliale la plus fréquente ?","back":"**Sepsis sévère**.","prio":"P2","sec":"s4"},{"id":"fc-p203-db655e","poly":"pneumo","fiche":"p203","front":"SDRA : citer des causes d'agression épithéliale ?","back":"**Pneumonie**, inhalation de **fumées** ou de **liquide gastrique**, **noyade**.","prio":"P3","sec":"s4"},{"id":"fc-p203-b66797","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire et SDRA : sont-ils synonymes ?","back":"**Non** : la détresse est un ensemble de signes ; le SDRA est une de ses **causes** (une pneumonie peut évoluer vers un SDRA).","prio":"P2","sec":"s4"},{"id":"fc-p203-f523c3","poly":"pneumo","fiche":"p203","front":"Pneumonie vs OAP cardiogénique : signes généraux ?","back":"Pneumonie : **fièvre élevée, frissons** ; OAP : **aucun**.","prio":"P1","sec":"s5"},{"id":"fc-p203-5cf4f7","poly":"pneumo","fiche":"p203","front":"OAP cardiogénique : aspect de l'expectoration ?","back":"**Mousseuse**, parfois **rosée**.","prio":"P2","sec":"s5"},{"id":"fc-p203-0bc149","poly":"pneumo","fiche":"p203","front":"OAP cardiogénique : auscultation typique ?","back":"**Crépitants bilatéraux** prédominant aux **bases** (sibilants possibles).","prio":"P1","sec":"s5"},{"id":"fc-p203-1522be","poly":"pneumo","fiche":"p203","front":"OAP cardiogénique : aspect radiographique ?","back":"Opacités alvéolaires **bilatérales**, **diffuses**, **péri-hilaires**.","prio":"P1","sec":"s5"},{"id":"fc-p203-50dfac","poly":"pneumo","fiche":"p203","front":"Pneumonie : aspect radiographique habituel ?","back":"Opacités alvéolaires le plus souvent **systématisées**.","prio":"P2","sec":"s5"},{"id":"fc-p203-8bab8c","poly":"pneumo","fiche":"p203","front":"OAP cardiogénique : l'ECG peut-il être normal ?","back":"**Jamais normal** dans l'OAP.","prio":"P1","sec":"s5"},{"id":"fc-p203-4afff0","poly":"pneumo","fiche":"p203","front":"Pneumonie vs OAP : éléments cliniques et radiologiques pathognomoniques ?","back":"**Aucun** élément n'est constant ni pathognomonique.","prio":"P2","sec":"s5"},{"id":"fc-p203-176241","poly":"pneumo","fiche":"p203","front":"Embolie pulmonaire en détresse : auscultation et radiographie (tableau du Collège) ?","back":"Auscultation **normale** ; radiographie **normale**.","prio":"P1","sec":"s5"},{"id":"fc-p203-8c5c22","poly":"pneumo","fiche":"p203","front":"Embolie pulmonaire : anomalies radiographiques possibles ?","back":"**Ascension de coupole**, **atélectasie en bande**, opacité périphérique (infarctus), petit épanchement.","prio":"P3","sec":"s5"},{"id":"fc-p203-aa6d66","poly":"pneumo","fiche":"p203","front":"Pneumothorax : terrain typique ?","back":"Sujet **longiligne**, **tabac**, **cannabis**, maladie respiratoire chronique (emphysème, kystes).","prio":"P2","sec":"s5"},{"id":"fc-p203-e3833c","poly":"pneumo","fiche":"p203","front":"Pneumothorax : signes d'examen ?","back":"**Vibrations vocales** et **murmure vésiculaire abolis**, **tympanisme**.","prio":"P1","sec":"s5"},{"id":"fc-p203-1fa1a6","poly":"pneumo","fiche":"p203","front":"Pneumothorax : signe radiographique ?","back":"**Hyperclarté** limitée par une **ligne pleurale**.","prio":"P1","sec":"s5"},{"id":"fc-p203-b1bcc8","poly":"pneumo","fiche":"p203","front":"Exacerbation d'asthme grave : signe auscultatoire le plus inquiétant ?","back":"**Silence auscultatoire**.","prio":"P1","sec":"s5"},{"id":"fc-p203-c5f8c4","poly":"pneumo","fiche":"p203","front":"Exacerbation d'asthme : aspect radiographique ?","back":"**Distension thoracique**.","prio":"P3","sec":"s5"},{"id":"fc-p203-46aa12","poly":"pneumo","fiche":"p203","front":"Dyspnée sifflante chez le sujet âgé : diagnostics à évoquer en dehors de l'asthme ?","back":"**BPCO** et **cœur gauche** (« pseudo-asthme cardiaque »).","prio":"P1","sec":"s5"},{"id":"fc-p203-434dce","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : déclencheurs à rechercher ?","back":"**Effort**, **allergène**, **froid**, **infection**, **écart de régime sans sel**, **arrêt d'un traitement de fond**.","prio":"P2","sec":"s6"},{"id":"fc-p203-ae3f6a","poly":"pneumo","fiche":"p203","front":"Insuffisance respiratoire chronique : signes à l'inspection ?","back":"**SCM hypertrophiés**, **expiration lèvres pincées**, **signe de Hoover**.","prio":"P1","sec":"s6"},{"id":"fc-p203-4f2aea","poly":"pneumo","fiche":"p203","front":"Dysfonction diaphragmatique : signes évocateurs ?","back":"**Antépnée**, **asynchronisme thoraco-abdominal** chronique (respiration abdominale paradoxale).","prio":"P2","sec":"s6"},{"id":"fc-p203-0582e3","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : signes neuromusculaires à rechercher ?","back":"**Amyotrophie**, **myalgies**, **fasciculations**, **déficit musculaire**.","prio":"P3","sec":"s6"},{"id":"fc-p203-4d6f45","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : principal élément d'orientation ?","back":"L'**examen clinique**, surtout l'**auscultation pulmonaire**.","prio":"P1","sec":"s6"},{"id":"fc-p203-a35ac6","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique avec sibilants : causes à évoquer ?","back":"**Asthme**, **BPCO**, **insuffisance cardiaque gauche**.","prio":"P1","sec":"s6"},{"id":"fc-p203-b2dcad","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique avec crépitants : causes à évoquer ?","back":"**Pneumopathie interstitielle diffuse**, **insuffisance cardiaque gauche**.","prio":"P1","sec":"s6"},{"id":"fc-p203-956b49","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique à auscultation normale : causes à évoquer ?","back":"**EP/maladie vasculaire pulmonaire**, **maladie neuromusculaire**, **maladie pariétale**, **syndrome d'hyperventilation**.","prio":"P1","sec":"s6"},{"id":"fc-p203-c03dc6","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique sifflante : arguments pour un asthme ?","back":"Sujet **jeune**, **atopie**, **variabilité**, **toux nocturne**.","prio":"P2","sec":"s6"},{"id":"fc-p203-efd4bd","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique sifflante : arguments pour une BPCO ?","back":"**Tabac**, **toux**, **expectoration**, râles bronchiques.","prio":"P2","sec":"s6"},{"id":"fc-p203-e32bb6","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique avec crépitants : arguments pour une PID ?","back":"**Toux sèche**, **maladie systémique**.","prio":"P3","sec":"s6"},{"id":"fc-p203-f08182","poly":"pneumo","fiche":"p203","front":"Maladie neuromusculaire : arguments devant une dyspnée chronique ?","back":"**Orthopnée**, **respiration abdominale paradoxale**, **signes neurologiques**.","prio":"P2","sec":"s6"},{"id":"fc-p203-bb41de","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : bilan de première intention ?","back":"**Radiographie thoracique**, **NFS**, **BNP** (si cardiopathie suspectée), **ECG**.","prio":"P1","sec":"s7"},{"id":"fc-p203-ebf43b","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : intérêt de la NFS ?","back":"**Éliminer une anémie**.","prio":"P2","sec":"s7"},{"id":"fc-p203-e92fc2","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : que chercher sur la radiographie thoracique ?","back":"**Distension**, **syndrome interstitiel**, **cardiomégalie**.","prio":"P2","sec":"s7"},{"id":"fc-p203-08f0b4","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique, piste respiratoire : contenu des EFR de repos ?","back":"**Spirométrie** lente et forcée, **pléthysmographie**, **DLCO**.","prio":"P2","sec":"s7"},{"id":"fc-p203-d3111e","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : position pour les gaz du sang de repos ?","back":"**Assis**.","prio":"P3","sec":"s7"},{"id":"fc-p203-6dafd6","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : exploration d'effort idéale ?","back":"Épreuve **incrémentale sur cycloergomètre** (EFXi).","prio":"P2","sec":"s7"},{"id":"fc-p203-cb6bff","poly":"pneumo","fiche":"p203","front":"Désaturation d'effort : définition et tests simples de dépistage ?","back":"Baisse de SpO₂ de **3 %** ; **test de marche de 6 min**, **test de lever de chaise de 3 min**.","prio":"P2","sec":"s7"},{"id":"fc-p203-15623f","poly":"pneumo","fiche":"p203","front":"Scanner de la dyspnée chronique : quand sans injection ?","back":"**Bronchopathie** ou **pneumopathie interstitielle** chronique.","prio":"P2","sec":"s7"},{"id":"fc-p203-dffe0d","poly":"pneumo","fiche":"p203","front":"Scanner de la dyspnée chronique : quand avec injection ?","back":"Piste **vasculaire** : **EP**, **hypertension pulmonaire**, **shunt droite-gauche**.","prio":"P2","sec":"s7"},{"id":"fc-p203-b2f2f6","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique, piste cardiaque : examen de seconde intention ?","back":"**Avis cardiologique** avec **échographie cardiaque** (± EFXi).","prio":"P2","sec":"s7"},{"id":"fc-p203-361c8a","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : objectif immédiat de l'oxygène ?","back":"Corriger l'hypoxémie pour **prévenir un arrêt cardio-respiratoire hypoxique**.","prio":"P1","sec":"s8"},{"id":"fc-p203-fe8046","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : deux piliers de la prise en charge immédiate ?","back":"**Oxygène, toujours** + **assistance ventilatoire** mécanique ; bilan et traitement de la cause **en même temps**.","prio":"P1","sec":"s8"},{"id":"fc-p203-258a59","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : qui appeler hors de l'hôpital et à l'hôpital ?","back":"Hors hôpital : **Samu** ; à l'hôpital : **réanimateur** ou médecin des soins intensifs.","prio":"P1","sec":"s8"},{"id":"fc-p203-850427","poly":"pneumo","fiche":"p203","front":"Détresse avec bruits inspiratoires : que rechercher systématiquement ?","back":"Une atteinte ou **obstruction des voies aériennes supérieures**.","prio":"P2","sec":"s8"},{"id":"fc-p203-62f29a","poly":"pneumo","fiche":"p203","front":"Détresse avec hypoxémie profonde : débit initial d'oxygène ?","back":"**Haut débit d'emblée**, puis adapté à la SpO₂.","prio":"P1","sec":"s8"},{"id":"fc-p203-c0611d","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : cible de SpO₂ sous oxygène ?","back":"**88 à 92 %**.","prio":"P1","sec":"s8"},{"id":"fc-p203-e38dc4","poly":"pneumo","fiche":"p203","front":"BPCO en détresse avec hypoxémie profonde : faut-il réduire le débit initial d'O₂ ?","back":"**Non** : haut débit initial aussi ; dépister l'hypercapnie par les **gaz du sang sous O₂**.","prio":"P1","sec":"s8"},{"id":"fc-p203-c0f93a","poly":"pneumo","fiche":"p203","front":"Oxygénothérapie : débit du masque simple et seuil du masque à haute concentration ?","back":"Masque simple **5 à 10 L/min** ; masque à haute concentration au-delà de **8 L/min**.","prio":"P2","sec":"s8"},{"id":"fc-p203-1c5c6a","poly":"pneumo","fiche":"p203","front":"Canules nasales à haut débit : à partir de quel besoin les envisager ?","back":"Au-delà de **15 L/min** (10 à 50 L/min, gaz réchauffé et humidifié).","prio":"P2","sec":"s8"},{"id":"fc-p203-92798a","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : rythme de surveillance de la PA et de la FR ?","back":"Toutes les **10 minutes** (SpO₂ et FC en **continu**).","prio":"P2","sec":"s8"},{"id":"fc-p203-06b4c7","poly":"pneumo","fiche":"p203","front":"Insuffisant respiratoire chronique sous O₂ : pourquoi contrôler les gaz du sang ?","back":"Risque d'**hypercapnie** (la correction de l'hypoxémie peut freiner les centres respiratoires).","prio":"P1","sec":"s8"},{"id":"fc-p203-4c4f6d","poly":"pneumo","fiche":"p203","front":"Détresse respiratoire : où installer le patient ?","back":"**Scopé** tout de suite, voire en **salle de déchocage**.","prio":"P3","sec":"s8"},{"id":"fc-p203-f5e81c","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : trois raisons de la quantifier ?","back":"Suivre la **maladie causale** ; juger l'**efficacité des traitements** ; mesurer l'impact sur la **qualité de vie**.","prio":"P2","sec":"s11"},{"id":"fc-p203-383fc8","poly":"pneumo","fiche":"p203","front":"Quantification de la dyspnée chronique : est-elle facultative ?","back":"**Non**, elle est **indispensable**.","prio":"P2","sec":"s11"},{"id":"fc-p203-35ce87","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique : échelle la plus utilisée ?","back":"**mMRC** (Medical Research Council modifiée), proche de la **NYHA**.","prio":"P1","sec":"s11"},{"id":"fc-p203-19db93","poly":"pneumo","fiche":"p203","front":"Échelle mMRC : principale limite ?","back":"**Peu sensible au changement** (amélioration ou aggravation).","prio":"P2","sec":"s11"},{"id":"fc-p203-d3bc90","poly":"pneumo","fiche":"p203","front":"Score DIRECT : contenu ?","back":"**10 questions** sur l'impact de la dyspnée dans la vie quotidienne.","prio":"P3","sec":"s11"},{"id":"fc-p203-0708dd","poly":"pneumo","fiche":"p203","front":"Retentissement de la dyspnée chronique : deux questionnaires les plus répandus ?","back":"**CAT** (qualité de vie respiratoire) et **HAD** (anxiété-dépression).","prio":"P2","sec":"s11"},{"id":"fc-p203-7191c2","poly":"pneumo","fiche":"p203","front":"mMRC stade 0 : définition ?","back":"Essoufflé **seulement pour un gros effort**.","prio":"P2","sec":"s11"},{"id":"fc-p203-0fd430","poly":"pneumo","fiche":"p203","front":"mMRC stade 1 : définition ?","back":"Essoufflé en **se dépêchant à plat** ou en montant une **pente légère**.","prio":"P2","sec":"s11"},{"id":"fc-p203-274390","poly":"pneumo","fiche":"p203","front":"mMRC stade 2 : définition ?","back":"Marche **plus lentement** que les gens de son âge, ou doit **s'arrêter** à son propre rythme.","prio":"P2","sec":"s11"},{"id":"fc-p203-d22d26","poly":"pneumo","fiche":"p203","front":"mMRC stade 3 : définition ?","back":"S'arrête pour souffler après **90 mètres** ou quelques minutes à plat.","prio":"P1","sec":"s11"},{"id":"fc-p203-273146","poly":"pneumo","fiche":"p203","front":"mMRC stade 4 : définition ?","back":"Trop essoufflé pour **sortir de chez lui** ou en **s'habillant**.","prio":"P2","sec":"s11"},{"id":"fc-p203-beb0c2","poly":"pneumo","fiche":"p203","front":"NYHA : stades extrêmes I et IV ?","back":"I : **aucun symptôme** à l'effort ; IV : symptômes **au repos**.","prio":"P2","sec":"s11"},{"id":"fc-p203-8886b1","poly":"pneumo","fiche":"p203","front":"NYHA III : définition ?","back":"Symptômes pour des **efforts modérés** (ménage, toilette) ; limitation **marquée**.","prio":"P3","sec":"s11"},{"id":"fc-p203-9cff75","poly":"pneumo","fiche":"p203","front":"Échelle mMRC : bornes des stades dans le tableau du Collège ?","back":"De **0 à 4** (le texte annonce 0 à 5 : contradiction) ; NYHA de 1 à 4.","prio":"P3","sec":"s11"},{"id":"fc-p203-dc2d03","poly":"pneumo","fiche":"p203","front":"Dyspnée avec sifflements expiratoires : quelle cause évoquer en premier ?","back":"L'**asthme** (chez le sujet âgé, aussi **BPCO** et **cœur gauche**).","prio":"P2","sec":"s9"},{"id":"fc-p203-c6d667","poly":"pneumo","fiche":"p203","front":"Dyspnée : en dehors des signes respiratoires, quelles anomalies extra-respiratoires rechercher ?","back":"**Paroi thoracique**, atteinte **neuromusculaire** ou **rhumatologique**, anomalie **cardiaque**.","prio":"P3","sec":"s9"},{"id":"fc-p203-93a981","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique d'allure cardiaque : signes cliniques évocateurs ?","back":"**Douleur angineuse**, **palpitations**, signes d'**insuffisance cardiaque droite**, **souffle**.","prio":"P2","sec":"s10"},{"id":"fc-p203-7326b0","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique sibilante ou crépitante : arguments pour une insuffisance cardiaque gauche ?","back":"**Antécédents cardiaques**, **orthopnée**, **toux**, **horaire nocturne**.","prio":"P2","sec":"s6"},{"id":"fc-p203-b1ad2a","poly":"pneumo","fiche":"p203","front":"Dyspnée chronique à auscultation normale : arguments pour une maladie pariétale ?","back":"**Obésité**, **scoliose**.","prio":"P3","sec":"s6"},{"id":"fc-p203-e9fa63","poly":"pneumo","fiche":"p203","front":"DRA : citer les signes neurologiques de faillite ?","back":"**Céphalées**, **astérixis**, **troubles du comportement ou de la vigilance** (signe majeur de gravité).","prio":"P2","sec":"s3"},{"id":"fc-p203-66df2d","poly":"pneumo","fiche":"p203","front":"DRA : quels sont les signes hémodynamiques de faillite ?","back":"**Insuffisance cardiaque droite**, **état de choc**, **HTA**.","prio":"P2","sec":"s3"},{"id":"fc-p203-a99df5","poly":"pneumo","fiche":"p203","front":"Pneumonie en détresse : examens complémentaires spécifiques (tableau du Collège) ?","back":"**Antigénuries légionelle et pneumocoque**, **prélèvements respiratoires**, **hémocultures**.","prio":"P3","sec":"s5"},{"id":"fc-p203-11e8fd","poly":"pneumo","fiche":"p203","front":"NYHA II : définition ?","back":"Symptômes pour des **efforts importants** (course, plusieurs étages) ; limitation **modérée**.","prio":"P3","sec":"s11"},{"id":"fc-p204-cdf642","poly":"pneumo","fiche":"p204","front":"Toux : quelle définition ?","back":"**Expulsion soudaine et bruyante** de l'air contenu dans les poumons.","prio":"P2","sec":"s1"},{"id":"fc-p204-022b1f","poly":"pneumo","fiche":"p204","front":"Toux : quelle est sa fonction ?","back":"**Réflexe de défense** non spécifique : évacuer les sécrétions ou répondre à une irritation des voies aériennes.","prio":"P2","sec":"s1"},{"id":"fc-p204-525147","poly":"pneumo","fiche":"p204","front":"Toux : avec quoi peut-on la confondre ?","back":"Le **hemmage** (raclement de gorge).","prio":"P1","sec":"s1"},{"id":"fc-p204-767331","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quelle durée ?","back":"**< 3 semaines**.","prio":"P1","sec":"s1"},{"id":"fc-p204-bd37a7","poly":"pneumo","fiche":"p204","front":"Toux chronique : quelle durée ?","back":"**> 8 semaines**.","prio":"P1","sec":"s1"},{"id":"fc-p204-b72789","poly":"pneumo","fiche":"p204","front":"Toux subaiguë : quelle durée ?","back":"**Entre 3 et 8 semaines**.","prio":"P2","sec":"s1"},{"id":"fc-p204-5c9157","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quelle évolution habituelle ?","back":"Amélioration **spontanée** en 3 semaines (le plus souvent infection respiratoire haute virale).","prio":"P1","sec":"s1"},{"id":"fc-p204-a7b0cf","poly":"pneumo","fiche":"p204","front":"Toux chronique : chez qui impose-t-elle une prise en charge spécifique ?","back":"**Chez tous** : même **isolée**, même chez un **fumeur actif** (ne s'améliorera pas seule).","prio":"P1","sec":"s1"},{"id":"fc-p204-7af697","poly":"pneumo","fiche":"p204","front":"Réflexe de toux : par quel nerf passe le message afférent ?","back":"Le **nerf vague**, jusqu'au **noyau solitaire** du tronc cérébral.","prio":"P2","sec":"s2"},{"id":"fc-p204-6ee754","poly":"pneumo","fiche":"p204","front":"Réflexe de toux : quel est le rôle du cortex cérébral ?","back":"**Commande volontaire** qui freine ou déclenche la toux (le Collège y rattache l'efficacité de la **codéine**).","prio":"P3","sec":"s2"},{"id":"fc-p204-e2f31a","poly":"pneumo","fiche":"p204","front":"Récepteurs de la toux : quelles sont les deux familles ?","back":"**Nocicepteurs** (irritants chimiques) et **mécanorécepteurs** (stimuli mécaniques).","prio":"P2","sec":"s2"},{"id":"fc-p204-2b5f3e","poly":"pneumo","fiche":"p204","front":"Nocicepteurs de la toux : quelles fibres nerveuses ?","back":"**Fibres C non myélinisées**, conduction **lente**.","prio":"P3","sec":"s2"},{"id":"fc-p204-cd8bfa","poly":"pneumo","fiche":"p204","front":"Mécanorécepteurs de la toux : quelles fibres et quelle localisation ?","back":"Fibres myélinisées **Aδ** (conduction rapide) ; larynx, trachée, bronches proximales.","prio":"P3","sec":"s2"},{"id":"fc-p204-0cfbda","poly":"pneumo","fiche":"p204","front":"Toux : qu'est-ce que l'hypertussie ?","back":"Toux déclenchée par des stimuli **peu tussigènes** (sensibilité accrue).","prio":"P2","sec":"s2"},{"id":"fc-p204-600926","poly":"pneumo","fiche":"p204","front":"Toux : qu'est-ce que l'allotussie ?","back":"Toux déclenchée par des stimuli qui **ne font normalement pas tousser** (parole, rire).","prio":"P2","sec":"s2"},{"id":"fc-p204-c17df6","poly":"pneumo","fiche":"p204","front":"Toux par excès de sensibilité : à quel mécanisme ressemble-t-elle ?","back":"À celui de la **douleur neuropathique** (voies nerveuses de la toux plus sensibles).","prio":"P3","sec":"s2"},{"id":"fc-p204-8ed2df","poly":"pneumo","fiche":"p204","front":"Toux aiguë isolée : quelle cause très majoritaire ?","back":"**Infection respiratoire haute virale** (rhinopharyngite aiguë).","prio":"P1","sec":"s3"},{"id":"fc-p204-7b7428","poly":"pneumo","fiche":"p204","front":"Toux aiguë : citer les causes non rares autres que l'infection respiratoire haute.","back":"Infection respiratoire **basse** (bronchite aiguë, plus rarement pneumonie), exacerbation d'**asthme** ou de **BPCO**, rhino-sinusite aiguë, **RGO**.","prio":"P2","sec":"s3"},{"id":"fc-p204-aac0d5","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quelles causes sont qualifiées de rares ?","back":"**Insuffisance cardiaque gauche**, **embolie pulmonaire**, pneumothorax, pleurésies.","prio":"P3","sec":"s3"},{"id":"fc-p204-0b1324","poly":"pneumo","fiche":"p204","front":"Toux aiguë : que comporte obligatoirement l'examen physique ?","back":"Inspection des **fosses nasales**, des **conduits auditifs**, de la **cavité buccale** + **auscultation cardio-pulmonaire**.","prio":"P1","sec":"s3"},{"id":"fc-p204-d0b730","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quels examens complémentaires dans la grande majorité des cas ?","back":"**Aucun**.","prio":"P1","sec":"s3"},{"id":"fc-p204-ee7f96","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quand demander une radiographie de thorax ?","back":"Si l'**examen physique est anormal** (bruits auscultatoires anormaux : crépitants…).","prio":"P2","sec":"s3"},{"id":"fc-p204-1b9ee2","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quels éléments rechercher à l'interrogatoire ?","back":"Signes associés (surtout **expectoration** et son aspect), horaires, circonstances ; terrain, traitements, toxiques.","prio":"P2","sec":"s3"},{"id":"fc-p204-2c678f","poly":"pneumo","fiche":"p204","front":"Toux chronique : quelle est la clé de sa caractérisation ?","back":"L'**interrogatoire** (caractéristiques de la toux + profil du patient).","prio":"P2","sec":"s4"},{"id":"fc-p204-dccb3f","poly":"pneumo","fiche":"p204","front":"Toux chronique productive : quelles causes évoquer ?","back":"**BPCO** ou **dilatation des bronches**.","prio":"P1","sec":"s4"},{"id":"fc-p204-628881","poly":"pneumo","fiche":"p204","front":"Toux chronique sèche : quelles causes évoquer ?","back":"**Asthme** ou **fibrose**.","prio":"P1","sec":"s4"},{"id":"fc-p204-0fa66b","poly":"pneumo","fiche":"p204","front":"Toux chronique nocturne : quelles causes évoquer ?","back":"**Asthme** ou **RGO**.","prio":"P1","sec":"s4"},{"id":"fc-p204-c3f026","poly":"pneumo","fiche":"p204","front":"Toux chronique uniquement diurne : quelle cause évoquer ?","back":"**Toux par excès de sensibilité**.","prio":"P1","sec":"s4"},{"id":"fc-p204-c12a10","poly":"pneumo","fiche":"p204","front":"Toux chronique avec pyrosis : quelle cause évoquer ?","back":"**RGO**.","prio":"P1","sec":"s4"},{"id":"fc-p204-247c58","poly":"pneumo","fiche":"p204","front":"Toux chronique avec jetage ou rhinorrhée postérieurs : quelle cause évoquer ?","back":"**Rhinosinusite chronique** = **STOVAS** (syndrome de toux d'origine des voies aériennes supérieures).","prio":"P1","sec":"s4"},{"id":"fc-p204-3839d0","poly":"pneumo","fiche":"p204","front":"Toux chronique : citer des facteurs déclenchants à rechercher.","back":"Odeurs, parfum, spray, position, changement de température, rire, parole, primodécubitus.","prio":"P3","sec":"s4"},{"id":"fc-p204-62fff2","poly":"pneumo","fiche":"p204","front":"Toux par excès de sensibilité : quels déclencheurs typiques ?","back":"**Mécaniques** (chant, parole, rire), **thermiques** (air froid), **chimiques** (parfum, odeurs), décubitus dorsal, repas, effort.","prio":"P3","sec":"s4"},{"id":"fc-p204-dca3c2","poly":"pneumo","fiche":"p204","front":"Toux par excès de sensibilité : quels signes pharyngolaryngés évocateurs ?","back":"**Irritation** du larynx et du pharynx, **paresthésies** des voies aériennes supérieures ; quintes difficiles à contrôler.","prio":"P3","sec":"s4"},{"id":"fc-p204-c8e60c","poly":"pneumo","fiche":"p204","front":"Toux chronique : quelles complications physiques ?","back":"Troubles du sommeil, fatigue, céphalées, fractures de côtes, douleur thoracique, hernie inguinale, vomissements, **incontinence urinaire**…","prio":"P2","sec":"s4"},{"id":"fc-p204-2aaedf","poly":"pneumo","fiche":"p204","front":"Toux chronique : quelle complication physique touche 2/3 des femmes ?","back":"L'**incontinence urinaire**.","prio":"P1","sec":"s4"},{"id":"fc-p204-a51660","poly":"pneumo","fiche":"p204","front":"Toux chronique : quel retentissement est au premier plan ?","back":"Le retentissement **social** (handicap important), avec un retentissement **psychologique** fréquent (dépression, anxiété).","prio":"P1","sec":"s4"},{"id":"fc-p204-302271","poly":"pneumo","fiche":"p204","front":"Toux chronique : qu'évoquent des crépitants secs à l'auscultation ?","back":"**Pneumopathie interstitielle diffuse**.","prio":"P1","sec":"s4"},{"id":"fc-p204-d7a7c5","poly":"pneumo","fiche":"p204","front":"Toux chronique : qu'évoquent des ronchi ou des sibilants à l'auscultation ?","back":"Une **atteinte bronchique**.","prio":"P2","sec":"s4"},{"id":"fc-p204-707fbb","poly":"pneumo","fiche":"p204","front":"Toux chronique primitive : quelle entité ?","back":"Le **syndrome de toux par excès de sensibilité**.","prio":"P2","sec":"s5"},{"id":"fc-p204-11d4eb","poly":"pneumo","fiche":"p204","front":"Toux chronique : citer les causes secondaires fréquentes (1re intention).","back":"**STOVAS**, **asthme**, **RGO** (acide ou non), **médicaments** (IEC, gliptines), **BPCO**.","prio":"P1","sec":"s5"},{"id":"fc-p204-e5d63b","poly":"pneumo","fiche":"p204","front":"Toux chronique : quels médicaments rechercher ?","back":"**IEC**, **sartans**, **gliptines**.","prio":"P1","sec":"s5"},{"id":"fc-p204-0c8b2f","poly":"pneumo","fiche":"p204","front":"Toux chronique : citer des causes de 2e intention.","back":"PID (FPI, sarcoïdose), **cancer bronchique**, pleurésie, DDB, SAOS, IC gauche, causes neurologiques/déglutition, toux psychogène.","prio":"P2","sec":"s5"},{"id":"fc-p204-4ebf59","poly":"pneumo","fiche":"p204","front":"Toux chronique du non-fumeur à radiographie normale : quelles principales causes ?","back":"**STOVAS**, **RGO**, **asthme**, **médicaments**.","prio":"P1","sec":"s5"},{"id":"fc-p204-4cd958","poly":"pneumo","fiche":"p204","front":"Toux chronique à radiographie normale avec argument pour une cause fréquente : quelle conduite ?","back":"**Traitement d'épreuve** de cette cause.","prio":"P1","sec":"s5"},{"id":"fc-p204-4e0bb8","poly":"pneumo","fiche":"p204","front":"Toux : citer les signes de gravité.","back":"**AEG**, **dyspnée d'effort**, **hémoptysie**, syndrome infectieux, toux nouvelle/modifiée du **fumeur**, dysphonie/dysphagie/fausses routes, ADP cervicale suspecte, examen anormal.","prio":"P1","sec":"s6"},{"id":"fc-p204-396d94","poly":"pneumo","fiche":"p204","front":"Toux avec signe de gravité : quelle conduite ?","back":"**Examens complémentaires d'emblée** (en plus des EFR et de la radio) ; prise en charge **spécifique** de la cause.","prio":"P1","sec":"s6"},{"id":"fc-p204-b64f11","poly":"pneumo","fiche":"p204","front":"Toux qui apparaît ou se modifie chez un fumeur : quel diagnostic évoquer ?","back":"**Cancer bronchique**.","prio":"P1","sec":"s6"},{"id":"fc-p204-83c3f0","poly":"pneumo","fiche":"p204","front":"Toux avec suspicion de cancer bronchique : quel examen ?","back":"**Scanner thoracique**.","prio":"P2","sec":"s6"},{"id":"fc-p204-125c62","poly":"pneumo","fiche":"p204","front":"Toux avec signe de gravité : peut-on attendre l'effet d'un traitement d'épreuve ?","back":"**Non**, les examens se font **d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-p204-473230","poly":"pneumo","fiche":"p204","front":"Toux chronique : quels examens sont systématiques ?","back":"**Radiographie de thorax** et **spirométrie**.","prio":"P1","sec":"s7"},{"id":"fc-p204-1f6df7","poly":"pneumo","fiche":"p204","front":"Toux chronique : quand ne pas faire de scanner thoracique ?","back":"Examen clinique **normal**, radio **normale**, **pas de facteur de risque** de cancer bronchique.","prio":"P2","sec":"s7"},{"id":"fc-p204-90235d","poly":"pneumo","fiche":"p204","front":"Toux chronique persistante : y a-t-il un bilan systématique au-delà de radio et spirométrie ?","back":"**Non** : choix selon le **profil de la toux** et le contexte.","prio":"P1","sec":"s7"},{"id":"fc-p204-f60e2a","poly":"pneumo","fiche":"p204","front":"Toux post-prandiale persistante : quel bilan ?","back":"Avis **gastro-entérologique**, **pH-métrie des 24 h**, **manométrie œsophagienne**.","prio":"P2","sec":"s7"},{"id":"fc-p204-3893a7","poly":"pneumo","fiche":"p204","front":"Toux avec signes de RGO malgré les IPP : quel bilan ?","back":"Avis gastro, **pH-métrie 24 h**, manométrie œsophagienne, **fibroscopie œso-gastro-duodénale**.","prio":"P2","sec":"s7"},{"id":"fc-p204-3ea334","poly":"pneumo","fiche":"p204","front":"Toux productive malgré les traitements inhalés : quel bilan ?","back":"Avis **pneumologique**, **ECBC**, **endoscopie bronchique**, EFR avec test de provocation ; ± TDM thoracique.","prio":"P2","sec":"s7"},{"id":"fc-p204-f09900","poly":"pneumo","fiche":"p204","front":"Toux avec symptômes rhino-sinusiens malgré les traitements locaux : quel bilan ?","back":"Avis **ORL** avec **nasofibroscopie** ; ± TDM des sinus.","prio":"P2","sec":"s7"},{"id":"fc-p204-d58312","poly":"pneumo","fiche":"p204","front":"Toux avec symptômes évocateurs d'asthme ou de BPCO : quel examen ?","back":"**EFR avec épreuves pharmacodynamiques** ; bilan allergique.","prio":"P1","sec":"s7"},{"id":"fc-p204-4385cc","poly":"pneumo","fiche":"p204","front":"Toux avec symptômes d'insuffisance ventriculaire gauche : quelle conduite ?","back":"**Avis cardiologique**.","prio":"P2","sec":"s7"},{"id":"fc-p204-101acd","poly":"pneumo","fiche":"p204","front":"Toux avec suspicion de diverticule de Zenker : quel examen ?","back":"**Transit pharyngo-œsophagien**.","prio":"P3","sec":"s7"},{"id":"fc-p204-82c481","poly":"pneumo","fiche":"p204","front":"Toux chronique avec rhinorrhée postérieure : quelle durée de traitement d'épreuve ?","back":"**3 semaines**.","prio":"P3","sec":"s7"},{"id":"fc-p204-5c8515","poly":"pneumo","fiche":"p204","front":"EFR d'une toux chronique : que signifie un TVO réversible ?","back":"**Asthme certain** (si réversibilité complète).","prio":"P1","sec":"s7"},{"id":"fc-p204-1918b5","poly":"pneumo","fiche":"p204","front":"EFR d'une toux chronique : à quoi l'arbre décisionnel associe-t-il un TVO irréversible ?","back":"À la **BPCO** (une absence de réversibilité n'élimine pas seule un asthme).","prio":"P2","sec":"s7"},{"id":"fc-p204-2cf28a","poly":"pneumo","fiche":"p204","front":"Toux chronique : que conclure d'une hyperréactivité bronchique présente ?","back":"**Asthme probable** : test thérapeutique.","prio":"P1","sec":"s7"},{"id":"fc-p204-185b5d","poly":"pneumo","fiche":"p204","front":"Toux chronique : que conclure d'une hyperréactivité bronchique absente ?","back":"**Asthme exclu**.","prio":"P1","sec":"s7"},{"id":"fc-p204-6b97ec","poly":"pneumo","fiche":"p204","front":"Réversibilité significative mais incomplète : permet-elle de trancher entre asthme et BPCO ?","back":"**Non**, pas à elle seule.","prio":"P2","sec":"s7"},{"id":"fc-p204-d4e94a","poly":"pneumo","fiche":"p204","front":"Toux chronique : comment évaluer objectivement sa sévérité ?","back":"Par une **EVA**, comme pour la douleur.","prio":"P1","sec":"s8"},{"id":"fc-p204-fb0ad4","poly":"pneumo","fiche":"p204","front":"Toux chronique : quels facteurs arrêter et combien de temps ?","back":"**Tabac** (au moins **4 semaines**) et médicaments **tussigènes** (IEC, sartans, gliptines) pendant **4 semaines**.","prio":"P1","sec":"s8"},{"id":"fc-p204-68733a","poly":"pneumo","fiche":"p204","front":"Arrêt du tabac chez un tousseur chronique : de quoi prévenir le patient ?","back":"**Majoration paradoxale et transitoire** de la toux possible (période réfractaire variable).","prio":"P2","sec":"s8"},{"id":"fc-p204-2018aa","poly":"pneumo","fiche":"p204","front":"Toux chronique persistante après arrêt des tussigènes : quelles 3 causes chercher ?","back":"**STOVAS**, **asthme**, **RGO**.","prio":"P1","sec":"s8"},{"id":"fc-p204-e2eb8b","poly":"pneumo","fiche":"p204","front":"Toux chronique sans argument étiologique ou résistante : quelles explorations discuter ?","back":"**pH-métrie** + manométrie, **endoscopie bronchique**, **enregistrement du sommeil**, **ECG** ; ± TDM thorax/sinus, écho cardiaque.","prio":"P2","sec":"s8"},{"id":"fc-p204-43d9dc","poly":"pneumo","fiche":"p204","front":"TOCRI : quelle définition ?","back":"**Toux chronique réfractaire ou inexpliquée** : aucune cause trouvée ou persistance malgré le traitement des causes.","prio":"P1","sec":"s8"},{"id":"fc-p204-98df87","poly":"pneumo","fiche":"p204","front":"Toux chronique : quel ordre de la démarche (figure 3) ?","back":"Examen + radio/spiro → **alarme ?** → complications, **EVA** → stop **tabac et tussigènes** → **3 causes fréquentes** → explorations → **TOCRI**.","prio":"P2","sec":"s8"},{"id":"fc-p204-a0582f","poly":"pneumo","fiche":"p204","front":"Toux chronique : faut-il traiter la toux ou sa cause ?","back":"La **cause** : traitement avant tout **étiologique**, le traitement symptomatique a **peu de place**.","prio":"P1","sec":"s9"},{"id":"fc-p204-1341ac","poly":"pneumo","fiche":"p204","front":"TOCRI : peut-on porter ce diagnostic d'emblée ?","back":"**Non** : seulement **à l'issue de la prise en charge** : **aucune cause retrouvée** ou **aucun traitement efficace**.","prio":"P1","sec":"s9"},{"id":"fc-p204-3f8904","poly":"pneumo","fiche":"p204","front":"Toux chronique : quand prescrire un IPP ?","back":"Seulement s'il existe des **signes de RGO** (pyrosis et/ou régurgitation acide).","prio":"P2","sec":"s9"},{"id":"fc-p204-b8c1da","poly":"pneumo","fiche":"p204","front":"Toux aiguë : faut-il prescrire un antibiotique ?","back":"**Non**, sauf **infection bactérienne avérée**.","prio":"P1","sec":"s10"},{"id":"fc-p204-4abe78","poly":"pneumo","fiche":"p204","front":"Toux aiguë : faut-il prescrire un antitussif ou un expectorant ?","back":"**Non** : bénéfice/risque faible, efficacité non démontrée, effets indésirables parfois sérieux.","prio":"P1","sec":"s10"},{"id":"fc-p204-4c474f","poly":"pneumo","fiche":"p204","front":"Pholcodine : pourquoi a-t-elle été retirée du marché ?","back":"Risque d'**allergie grave aux curares**.","prio":"P2","sec":"s10"},{"id":"fc-p204-9b5bb9","poly":"pneumo","fiche":"p204","front":"Toux aiguë chez un fumeur : quel conseil donner à l'occasion de la consultation ?","back":"Rappeler la nocivité du tabac et conseiller un **arrêt définitif**.","prio":"P2","sec":"s10"},{"id":"fc-p204-5152b8","poly":"pneumo","fiche":"p204","front":"Toux aiguë : quand revoir le patient ?","back":"À **4-6 semaines**, pour vérifier la disparition de la toux.","prio":"P1","sec":"s10"},{"id":"fc-p204-49a093","poly":"pneumo","fiche":"p204","front":"Toux chronique : les antitussifs sont-ils recommandés ?","back":"**Non** (ni par la Société européenne de pneumologie, ni par la SPLF).","prio":"P2","sec":"s11"},{"id":"fc-p204-be4517","poly":"pneumo","fiche":"p204","front":"Toux chronique : à quoi sert la réévaluation après 4 semaines d'arrêt des tussigènes ?","back":"Vérifier si la toux **persiste** pour passer à l'étape suivante (arbre décisionnel).","prio":"P3","sec":"s11"},{"id":"fc-p204-0b6c4a","poly":"pneumo","fiche":"p204","front":"Toux chronique : quelle mesure tabac dans tous les cas ?","back":"**Arrêt du tabac** avec **aide au sevrage définitif**.","prio":"P2","sec":"s11"},{"id":"fc-p204-7a439e","poly":"pneumo","fiche":"p204","front":"Toux avec signe de gravité : quel traitement ?","back":"Celui de la **cause** retrouvée (prise en charge spécifique).","prio":"P2","sec":"s12"},{"id":"fc-p204-1bbd4c","poly":"pneumo","fiche":"p204","front":"STOVAS : quels traitements ?","back":"**Lavages de nez**, **corticothérapie nasale**, éviction des facteurs favorisants, éducation thérapeutique.","prio":"P2","sec":"s13"},{"id":"fc-p204-52e5a9","poly":"pneumo","fiche":"p204","front":"STOVAS avec bilan allergique positif : quel traitement ?","back":"Traitement de la **rhinite allergique**.","prio":"P3","sec":"s13"},{"id":"fc-p204-4f0548","poly":"pneumo","fiche":"p204","front":"Toux chronique d'origine asthmatique : quel traitement médicamenteux ?","back":"**Corticostéroïde inhalé** ± **bronchodilatateur de longue durée d'action**.","prio":"P2","sec":"s14"},{"id":"fc-p204-35f070","poly":"pneumo","fiche":"p204","front":"Toux chronique d'origine asthmatique : quelles mesures non médicamenteuses ?","back":"**Éviction des facteurs favorisants** et **éducation thérapeutique**.","prio":"P3","sec":"s14"},{"id":"fc-p204-00f861","poly":"pneumo","fiche":"p204","front":"Toux chronique et RGO : quel traitement médicamenteux et quelle durée ?","back":"**IPP** pendant **au moins 8 semaines**, seulement si signes de RGO.","prio":"P2","sec":"s15"},{"id":"fc-p204-fe237f","poly":"pneumo","fiche":"p204","front":"Toux chronique et RGO : quelle mesure est essentielle en plus des IPP ?","back":"Les **règles hygiéno-diététiques**.","prio":"P2","sec":"s15"},{"id":"fc-p204-e5befc","poly":"pneumo","fiche":"p204","front":"Toux chronique persistante : quand l'exploration retrouve une cause, quelle conduite ?","back":"**Prise en charge spécifique** de cette cause ; sinon (ni cause ni traitement efficace) : **TOCRI**.","prio":"P2","sec":"s16"},{"id":"fc-p204-9a680c","poly":"pneumo","fiche":"p204","front":"TOCRI : sur quoi repose le diagnostic de toux par excès de sensibilité ?","back":"Sur l'**interrogatoire**.","prio":"P2","sec":"s17"},{"id":"fc-p204-3d5a6a","poly":"pneumo","fiche":"p204","front":"TOCRI : quels traitements médicamenteux ?","back":"**Prégabaline** ou **gabapentine** ; **morphine à faible dose**.","prio":"P2","sec":"s17"},{"id":"fc-p204-0d44e7","poly":"pneumo","fiche":"p204","front":"TOCRI : pourquoi parle-t-on d'impasse ?","back":"Réels problèmes **diagnostiques et thérapeutiques**, pour le patient comme pour le médecin.","prio":"P3","sec":"s17"},{"id":"fc-p204-c5322d","poly":"pneumo","fiche":"p204","front":"Toux aiguë qui dure au-delà de 8 semaines : comment la qualifier ?","back":"**Toux chronique** : démarche spécifique.","prio":"P2","sec":"s18"},{"id":"fc-p204-7108d2","poly":"pneumo","fiche":"p204","front":"Toux chronique avec symptômes pharyngolaryngés : quelle conduite selon l'arbre décisionnel ?","back":"**Avis ORL**.","prio":"P2","sec":"s7"},{"id":"fc-p204-a1c876","poly":"pneumo","fiche":"p204","front":"Toux chronique avec un autre dysfonctionnement nasal chronique : quelle conduite ?","back":"**Avis ORL** ; **bilan allergique**.","prio":"P3","sec":"s7"},{"id":"fc-p204-d53216","poly":"pneumo","fiche":"p204","front":"Toux aiguë avec suspicion d'une autre maladie qu'une infection haute ou une bronchite virale : quels examens ?","back":"Examens choisis **selon la maladie suspectée**.","prio":"P3","sec":"s3"},{"id":"fc-p204-40a048","poly":"pneumo","fiche":"p204","front":"Toux chronique : que faire de ses complications ?","back":"Les **rechercher** et les **traiter** (sommeil, incontinence urinaire, retentissement social et psychologique…).","prio":"P2","sec":"s18"},{"id":"fc-p205-4d78c5","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelle définition ?","back":"Saignement des voies respiratoires **sous-glottiques**, extériorisé ou non.","prio":"P1","sec":"s1"},{"id":"fc-p205-3c96be","poly":"pneumo","fiche":"p205","front":"Hémoptysie : à quel étage de l'appareil respiratoire peut siéger l'anomalie ?","back":"À **n'importe quel étage**.","prio":"P2","sec":"s1"},{"id":"fc-p205-469849","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelle gamme d'abondance ?","back":"Du simple **crachat strié** de sang à l'hémoptysie **massive** mortelle.","prio":"P3","sec":"s1"},{"id":"fc-p205-9be8a0","poly":"pneumo","fiche":"p205","front":"Hémoptysie peu abondante : faut-il la considérer comme une urgence ?","back":"**Oui** : elle peut **récidiver sous forme massive** et révèle le plus souvent une **maladie pulmonaire**.","prio":"P1","sec":"s1"},{"id":"fc-p205-732e56","poly":"pneumo","fiche":"p205","front":"Hémoptysie : faut-il chercher la cause même si elle est minime ?","back":"**Oui, quelle que soit l'abondance**.","prio":"P1","sec":"s1"},{"id":"fc-p205-460e16","poly":"pneumo","fiche":"p205","front":"Hémoptysie menaçante : comment s'articulent diagnostic et traitement ?","back":"**En parallèle**.","prio":"P1","sec":"s1"},{"id":"fc-p205-cfaf3c","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelles sont les 3 questions de la démarche ?","back":"Est-ce bien une **hémoptysie** ? Quelle **gravité** ? Quelle **origine** (mécanisme, cause) ?","prio":"P2","sec":"s1"},{"id":"fc-p205-3ff791","poly":"pneumo","fiche":"p205","front":"Hémoptysie : sur quoi repose largement sa prise en charge selon le Collège ?","back":"Sur l'**empirisme** et l'**organisation locale** (beaucoup d'incertitudes).","prio":"P3","sec":"s1"},{"id":"fc-p205-c4a37f","poly":"pneumo","fiche":"p205","front":"Circulation pulmonaire : quelles caractéristiques ?","back":"**Petite** circulation, **fonctionnelle**, à **basse pression**.","prio":"P3","sec":"s1"},{"id":"fc-p205-b925ac","poly":"pneumo","fiche":"p205","front":"Circulation bronchique : quelles caractéristiques ?","back":"**Grande** circulation (systémique), **nourricière**, à **haute pression**.","prio":"P3","sec":"s1"},{"id":"fc-p205-cc2813","poly":"pneumo","fiche":"p205","front":"Circulation bronchique : quelles structures irrigue-t-elle en dehors de l'arbre trachéobronchique ?","back":"**Œsophage**, plèvre viscérale médiastinale/diaphragmatique, parois des vaisseaux pulmonaires, paroi de l'**aorte**.","prio":"P3","sec":"s1"},{"id":"fc-p205-322389","poly":"pneumo","fiche":"p205","front":"Circulations bronchique et pulmonaire : communiquent-elles ?","back":"**Oui**, par de nombreuses **anastomoses** artérielles et veineuses.","prio":"P3","sec":"s1"},{"id":"fc-p205-a0aa0f","poly":"pneumo","fiche":"p205","front":"Lit capillaire bronchique proximal : où se draine-t-il ?","back":"Vers le système **azygos** et la **veine cave supérieure**.","prio":"P3","sec":"s1"},{"id":"fc-p205-3a8169","poly":"pneumo","fiche":"p205","front":"Lit pleural et bronchique distal : où se draine-t-il ?","back":"Vers le versant **veineux pulmonaire** (70 % du débit) : **shunt** artério-veineux physiologique.","prio":"P3","sec":"s1"},{"id":"fc-p205-0d0d8d","poly":"pneumo","fiche":"p205","front":"Hémoptysie : de quelle circulation vient le plus souvent le sang ?","back":"De la circulation **bronchique** (hypervascularisation artérielle systémique), bien plus que de la pulmonaire.","prio":"P2","sec":"s1"},{"id":"fc-p205-50a570","poly":"pneumo","fiche":"p205","front":"Hypervascularisation systémique (HVS) : quel est son principal mécanisme ?","back":"La **destruction du lit capillaire** (tuberculose, cancer, processus fibrosant).","prio":"P3","sec":"s1"},{"id":"fc-p205-ee9dc2","poly":"pneumo","fiche":"p205","front":"HVS : quels autres mécanismes peuvent y contribuer ?","back":"L'**hyperhémie infectieuse** (bronchectasies, abcès) ; facteurs **néo-angiogéniques** si la circulation pulmonaire est altérée.","prio":"P3","sec":"s1"},{"id":"fc-p205-23e5f7","poly":"pneumo","fiche":"p205","front":"HVS par artères systémiques non bronchiques : quelle condition ?","back":"Des zones de **symphyse pleurale** par lesquelles ces artères atteignent le poumon.","prio":"P3","sec":"s1"},{"id":"fc-p205-a2a6e5","poly":"pneumo","fiche":"p205","front":"HVS non bronchique : quelles artères peuvent être en cause ?","back":"**Mammaires internes**, **intercostales**, **sous-clavières**, tronc thyro-bicervico-scapulaire…","prio":"P3","sec":"s1"},{"id":"fc-p205-1f8b7f","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel aspect et quel mode d'émission du sang ?","back":"Sang le plus souvent **rouge vif**, rejeté par la bouche lors d'**efforts de toux**.","prio":"P1","sec":"s2"},{"id":"fc-p205-9fcefc","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels prodromes ou signes d'accompagnement ?","back":"**Chaleur rétrosternale**, **angoisse**, gêne/chatouillement **laryngé**, **goût métallique**.","prio":"P2","sec":"s2"},{"id":"fc-p205-855c47","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels sont les 2 diagnostics différentiels ?","back":"**Hématémèse** et **saignement ORL** (épistaxis postérieure, saignement pharyngolaryngé).","prio":"P1","sec":"s2"},{"id":"fc-p205-259a2f","poly":"pneumo","fiche":"p205","front":"Hémoptysie vs hématémèse : quel est le point crucial à rechercher ?","back":"Le sang rejeté au cours d'un **effort de toux**.","prio":"P1","sec":"s2"},{"id":"fc-p205-e6d96d","poly":"pneumo","fiche":"p205","front":"Hématémèse : quels éléments l'orientent ?","back":"**Antécédents digestifs**, émission lors d'un **effort de vomissement**, **débris alimentaires**.","prio":"P1","sec":"s2"},{"id":"fc-p205-e2853a","poly":"pneumo","fiche":"p205","front":"Hémoptysie douteuse : quel examen tranche sur l'origine du sang ?","back":"L'**endoscopie** (bronchique, œso-gastrique, ORL).","prio":"P2","sec":"s2"},{"id":"fc-p205-717e73","poly":"pneumo","fiche":"p205","front":"Hémoptysie douteuse : quels signes indirects au scanner peuvent orienter ?","back":"Plages de **verre dépoli**, **condensations alvéolaires** (fenêtre parenchymateuse).","prio":"P2","sec":"s2"},{"id":"fc-p205-196c5a","poly":"pneumo","fiche":"p205","front":"Sang dans l'estomac : écarte-t-il une hémoptysie ?","back":"**Non** : ce peut être du sang bronchique **avalé**.","prio":"P1","sec":"s2"},{"id":"fc-p205-2bf09c","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : quel est le danger vital ?","back":"L'**asphyxie** et l'atteinte de l'**hématose**, pas le choc hémorragique.","prio":"P1","sec":"s3"},{"id":"fc-p205-ab17e6","poly":"pneumo","fiche":"p205","front":"Voies aériennes de conduction : quel volume ?","back":"Environ **200 ml**.","prio":"P1","sec":"s3"},{"id":"fc-p205-39e5c1","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel volume la rend grave chez un sujet sain ?","back":"**≥ 200 ml**.","prio":"P1","sec":"s3"},{"id":"fc-p205-1d2ccb","poly":"pneumo","fiche":"p205","front":"Hémoptysie chez un insuffisant respiratoire : quel volume la rend grave ?","back":"Un saignement même **modéré** suffit.","prio":"P1","sec":"s3"},{"id":"fc-p205-14b433","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels sont les critères de gravité ?","back":"**Abondance** (≥ 200 ml), **terrain** (insuffisance respiratoire), **persistance** (notamment sous vasoconstricteur), **tolérance respiratoire**.","prio":"P1","sec":"s3"},{"id":"fc-p205-cd36ea","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel volume représente une cuillère à soupe pleine aux ¾ ?","back":"Environ **10 ml**.","prio":"P2","sec":"s3"},{"id":"fc-p205-1c6a73","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel volume représente un verre ou un crachoir plein aux ¾ ?","back":"Environ **100 ml**.","prio":"P2","sec":"s3"},{"id":"fc-p205-f69588","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel volume représente un haricot ou un bol plein aux ¾ ?","back":"Environ **500 ml**.","prio":"P2","sec":"s3"},{"id":"fc-p205-4491d6","poly":"pneumo","fiche":"p205","front":"Hémoptysie à l'hôpital : comment mesurer l'abondance ?","back":"Recueil de **toutes** les expectorations en **récipients gradués**, par tranches de **3 heures**.","prio":"P1","sec":"s3"},{"id":"fc-p205-d94c6d","poly":"pneumo","fiche":"p205","front":"Hémoptysie hors hôpital : comment estimer l'abondance ?","back":"Interroger patient ou proches à l'aide de **contenants familiers**.","prio":"P2","sec":"s3"},{"id":"fc-p205-d7665c","poly":"pneumo","fiche":"p205","front":"Hémoptysie : que rechercher à l'examen ?","back":"Constantes (**SpO₂**, PA, pouls), signes de **mauvaise tolérance respiratoire** (plus rarement hémodynamique), **gêne unilatérale**.","prio":"P2","sec":"s3"},{"id":"fc-p205-b7a1bf","poly":"pneumo","fiche":"p205","front":"Hémoptysie : que peut indiquer une gêne d'un seul côté ?","back":"Le **côté qui saigne**.","prio":"P2","sec":"s3"},{"id":"fc-p205-3aa407","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels antécédents rechercher à l'interrogatoire ?","back":"**Respiratoires** (bronchectasies, tuberculose, cancer) et **cardiaques**.","prio":"P2","sec":"s4"},{"id":"fc-p205-999b43","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels éléments d'histoire récente rechercher ?","back":"**Alitement**, **chirurgie**, médicament ou toxique (**pénicillamine**, **crack**).","prio":"P3","sec":"s4"},{"id":"fc-p205-fd1ac5","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels aspects du sang préciser à l'interrogatoire ?","back":"**Rouge foncé** ou **noirâtre** ± **caillots**, ou **rouge vif**.","prio":"P3","sec":"s4"},{"id":"fc-p205-771ce6","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels signes d'examen orientent vers la cause ?","back":"**Hippocratisme digital**, signes de cancer, **rétrécissement mitral**, signes de **vascularite** systémique.","prio":"P3","sec":"s4"},{"id":"fc-p205-9cef1d","poly":"pneumo","fiche":"p205","front":"Hémoptysie et hippocratisme digital : quelles causes évoquer ?","back":"**Dilatations des bronches**, **cancer**, cardiopathie congénitale.","prio":"P3","sec":"s4"},{"id":"fc-p205-50c54b","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelles causes dominent (moyen mnémotechnique) ?","back":"« **ABCDE** » : **A**spergillome, **B**K, **C**ancer, **D**DB, **E**mbolie pulmonaire.","prio":"P1","sec":"s4"},{"id":"fc-p205-af3670","poly":"pneumo","fiche":"p205","front":"Aspergillome : de quoi s'agit-il ?","back":"Prolifération mycélienne d'*A. fumigatus* dans une **cavité pulmonaire séquellaire**.","prio":"P3","sec":"s4"},{"id":"fc-p205-5d9189","poly":"pneumo","fiche":"p205","front":"Embolie pulmonaire : quelle abondance d'hémoptysie ?","back":"**Faible** abondance.","prio":"P2","sec":"s4"},{"id":"fc-p205-cb2a6d","poly":"pneumo","fiche":"p205","front":"Tuberculose évolutive : par quel mécanisme saigne-t-elle ?","back":"Une **caverne érode un vaisseau**.","prio":"P3","sec":"s4"},{"id":"fc-p205-0a018d","poly":"pneumo","fiche":"p205","front":"Séquelles de tuberculose : quelles causes d'hémoptysie ?","back":"**Bronchectasies secondaires** ; **aspergillome** dans une caverne détergée.","prio":"P3","sec":"s4"},{"id":"fc-p205-a55e8f","poly":"pneumo","fiche":"p205","front":"Hémoptysie de cause vasculaire : citer des causes ?","back":"**Embolie pulmonaire** ; **malformations artério-veineuses** (isolées ou maladie de **Rendu-Osler**).","prio":"P3","sec":"s4"},{"id":"fc-p205-6bed4e","poly":"pneumo","fiche":"p205","front":"Hémorragies alvéolaires : citer des causes ?","back":"**IC gauche**/rétrécissement mitral ; toxiques (pénicillamine, isocyanates, crack) ; **Goodpasture** ; **lupus**.","prio":"P3","sec":"s4"},{"id":"fc-p205-b77e3f","poly":"pneumo","fiche":"p205","front":"Hémoptysie idiopathique : quand la retenir ?","back":"Seulement si **scanner thoracique** et **endoscopie bronchique** ne trouvent pas de cause.","prio":"P2","sec":"s4"},{"id":"fc-p205-40cda4","poly":"pneumo","fiche":"p205","front":"Hémoptysie idiopathique : quelle fréquence ?","back":"**Fréquente** : plus d'**un tiers** des cas selon les séries.","prio":"P3","sec":"s4"},{"id":"fc-p205-cb3c93","poly":"pneumo","fiche":"p205","front":"BPCO : est-elle une cause d'hémoptysie ?","back":"**Non** ; chercher une autre maladie, surtout un **cancer bronchopulmonaire**.","prio":"P1","sec":"s4"},{"id":"fc-p205-d69154","poly":"pneumo","fiche":"p205","front":"Hémoptysie chez un BPCO : quel bilan ?","back":"**Endoscopie bronchique** + **scanner thoracique** dans tous les cas, puis **surveillance prolongée**.","prio":"P2","sec":"s4"},{"id":"fc-p205-09aaa7","poly":"pneumo","fiche":"p205","front":"Surdosage en anticoagulant : peut-il expliquer à lui seul une hémoptysie ?","back":"**Non** : une **cause sous-jacente** reste à chercher.","prio":"P2","sec":"s4"},{"id":"fc-p205-a7dcde","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quels sont les 4 objectifs de la stratégie diagnostique ?","back":"**Confirmer** l'hémoptysie si doute ; apprécier la **gravité** ; trouver la **cause** ; préciser le **site** (ou au moins le **côté**) du saignement.","prio":"P3","sec":"s5"},{"id":"fc-p205-463bc9","poly":"pneumo","fiche":"p205","front":"Hémoptysie : pourquoi localiser le site ou le côté du saignement ?","back":"Dans les formes graves, il **guide le traitement** : embolisation, chirurgie, hémostase endobronchique.","prio":"P2","sec":"s5"},{"id":"fc-p205-ed5de5","poly":"pneumo","fiche":"p205","front":"Angioscanner thoracique vs radiographie dans l'hémoptysie : lequel est le plus précis ?","back":"L'**angioscanner**, **bien plus précis** que la radiographie.","prio":"P3","sec":"s5"},{"id":"fc-p205-6072f1","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel est l'examen clé de 1re intention ?","back":"L'**angioscanner thoracique** injecté au **temps aortique**.","prio":"P1","sec":"s5"},{"id":"fc-p205-7177b0","poly":"pneumo","fiche":"p205","front":"Angioscanner dans l'hémoptysie : quel triple intérêt ?","back":"Oriente sur la **nature** de la lésion, sur la **localisation** du saignement ; **cartographie vasculaire** pour l'embolisation.","prio":"P2","sec":"s5"},{"id":"fc-p205-c45a21","poly":"pneumo","fiche":"p205","front":"Endoscopie bronchique dans l'hémoptysie : quelles indications ?","back":"Confirmer (doute avec hématémèse), **localiser** si lésions **bilatérales** au scanner, trouver une **tumeur proximale**.","prio":"P3","sec":"s5"},{"id":"fc-p205-8210be","poly":"pneumo","fiche":"p205","front":"Endoscopie bronchique : peut-elle retarder le scanner ?","back":"**Non**, le scanner reste l'examen clé.","prio":"P2","sec":"s5"},{"id":"fc-p205-d77749","poly":"pneumo","fiche":"p205","front":"Artériographie bronchique : quelle place dans l'hémoptysie ?","back":"Seulement en vue d'une **embolisation** ; aucune place purement **diagnostique**.","prio":"P2","sec":"s5"},{"id":"fc-p205-c4126b","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelle biologie de gravité et pré-geste ?","back":"**SpO₂** ± gaz du sang, **NFS-plaquettes**, **coagulation** (TP, INR, TCA, anti-Xa), **groupe sanguin**.","prio":"P3","sec":"s5"},{"id":"fc-p205-ec8968","poly":"pneumo","fiche":"p205","front":"Hémoptysie : pourquoi demander le groupe sanguin ?","back":"Prise en charge, même si la **transfusion** n'est qu'**exceptionnellement** indiquée.","prio":"P3","sec":"s5"},{"id":"fc-p205-1d45c9","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quand rechercher des BAAR dans l'expectoration ?","back":"Dès qu'une **tuberculose** peut être évoquée (image, antécédents).","prio":"P3","sec":"s5"},{"id":"fc-p205-f8ce5f","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quel bilan si aspergillose suspectée ?","back":"**Sérologie aspergillaire**, parfois **antigénémie**.","prio":"P3","sec":"s5"},{"id":"fc-p205-86c696","poly":"pneumo","fiche":"p205","front":"Hémoptysie : pourquoi un ECG avant tout vasoconstricteur ?","back":"Éliminer une **coronaropathie méconnue**.","prio":"P3","sec":"s5"},{"id":"fc-p205-75f973","poly":"pneumo","fiche":"p205","front":"Hémoptysie et OAP hémorragique suspecté : quels examens ?","back":"**ECG** et **échocardiographie**.","prio":"P3","sec":"s5"},{"id":"fc-p205-f94bbb","poly":"pneumo","fiche":"p205","front":"Hémoptysie : existe-t-il une prescription propre à la conduite initiale ?","back":"**Non** : traitement selon la **gravité** et la **cause**.","prio":"P3","sec":"s6"},{"id":"fc-p205-3f5a31","poly":"pneumo","fiche":"p205","front":"Hémoptysie : la transfusion est-elle souvent nécessaire ?","back":"**Très rarement** : le danger n'est pas la perte de sang.","prio":"P3","sec":"s6"},{"id":"fc-p205-16ea55","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : quels sont les 2 buts du traitement ?","back":"**Éviter l'asphyxie** et **tarir le saignement**.","prio":"P1","sec":"s7"},{"id":"fc-p205-e443a6","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : où hospitaliser ?","back":"En **soins intensifs respiratoires** ou en **réanimation**.","prio":"P1","sec":"s7"},{"id":"fc-p205-1d05a2","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : quels intervenants ?","back":"**Pneumologue**, **réanimateur**, **radiologue interventionnel**, parfois chirurgien thoracique.","prio":"P3","sec":"s7"},{"id":"fc-p205-68c7bd","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : traitement médical, embolisation, chirurgie et traitement local s'excluent-ils ?","back":"**Non** : selon la sévérité et l'organisation locale, ils se **combinent**, en même temps ou **successivement**.","prio":"P3","sec":"s7"},{"id":"fc-p205-e2c76d","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : quel objectif d'oxygénothérapie ?","back":"**SpO₂ > 90 %** (oxymétrie de pouls).","prio":"P1","sec":"s7"},{"id":"fc-p205-ce01a8","poly":"pneumo","fiche":"p205","front":"Hémoptysie massive : comment positionner le patient ?","back":"**Décubitus latéral du côté qui saigne** (s'il est connu).","prio":"P1","sec":"s7"},{"id":"fc-p205-c3a244","poly":"pneumo","fiche":"p205","front":"Hémoptysie massive très sévère : quelle prise en charge des voies aériennes ?","back":"**Intubation** et **ventilation mécanique**, parfois nécessaires.","prio":"P2","sec":"s7"},{"id":"fc-p205-ffbc88","poly":"pneumo","fiche":"p205","front":"Hémoptysie massive : quelle sonde d'intubation idéale ?","back":"Sonde **à double lumière** pour protéger le poumon sain.","prio":"P3","sec":"s7"},{"id":"fc-p205-1a45c4","poly":"pneumo","fiche":"p205","front":"Hémoptysie massive sans sonde double lumière : quelles alternatives ?","back":"Intubation **sélective du côté sain**, ou sonde à **ballonnet occlusif** dans la bronche souche qui saigne.","prio":"P3","sec":"s7"},{"id":"fc-p205-beae26","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave sous anticoagulant ou antiagrégant : quelle attitude ?","back":"**Arrêter** et **antagoniser** si besoin.","prio":"P3","sec":"s7"},{"id":"fc-p205-f24580","poly":"pneumo","fiche":"p205","front":"Hémoptysie grave : quel vasoconstricteur IV ?","back":"La **terlipressine**.","prio":"P3","sec":"s7"},{"id":"fc-p205-2c9a9d","poly":"pneumo","fiche":"p205","front":"Terlipressine dans l'hémoptysie : quelles indications ?","back":"Embolisation **indisponible** ou pas faisable vite, ou **menace vitale immédiate** (après ECG, hors CI).","prio":"P3","sec":"s7"},{"id":"fc-p205-33493c","poly":"pneumo","fiche":"p205","front":"Terlipressine : quelle contre-indication citée en particulier ?","back":"L'**athéromatose** (risque d'**infarctus du myocarde** ou d'**AVC**).","prio":"P3","sec":"s7"},{"id":"fc-p205-e00045","poly":"pneumo","fiche":"p205","front":"Terlipressine : quel impact sur l'embolisation ?","back":"Elle rend l'embolisation **impossible pendant 6 heures**.","prio":"P3","sec":"s7"},{"id":"fc-p205-53c9b8","poly":"pneumo","fiche":"p205","front":"Acide tranexamique dans l'hémoptysie : quelle place ?","back":"**Non systématique**, **pas de consensus** (IV ou inhalé).","prio":"P3","sec":"s7"},{"id":"fc-p205-7fc894","poly":"pneumo","fiche":"p205","front":"Hémoptysie sous vasoconstricteur : que signifie un saignement qui ne se tarit pas ?","back":"Un **critère de gravité**.","prio":"P2","sec":"s7"},{"id":"fc-p205-7dfbb5","poly":"pneumo","fiche":"p205","front":"Hémoptysie menaçante : quel est le traitement de référence ?","back":"L'**embolisation artérielle bronchique**.","prio":"P1","sec":"s8"},{"id":"fc-p205-bad24f","poly":"pneumo","fiche":"p205","front":"Embolisation artérielle bronchique : quel abord ?","back":"Abord artériel **systémique**, en général par ponction **fémorale**.","prio":"P3","sec":"s8"},{"id":"fc-p205-a9347a","poly":"pneumo","fiche":"p205","front":"Artériographie bronchique : quels signes d'artère pathologique ?","back":"Artère **élargie**, **hypervascularisation**, **shunt systémo-pulmonaire**, **fuite de contraste** (saignement actif).","prio":"P3","sec":"s8"},{"id":"fc-p205-d6da23","poly":"pneumo","fiche":"p205","front":"Embolisation artérielle bronchique : avec quel matériel ?","back":"**Particules** ou **spirales**.","prio":"P3","sec":"s8"},{"id":"fc-p205-9af173","poly":"pneumo","fiche":"p205","front":"Embolisation artérielle bronchique : quelle contrainte organisationnelle ?","back":"Équipe de **radiologie vasculaire experte**, absente de certains centres.","prio":"P3","sec":"s8"},{"id":"fc-p205-a37c17","poly":"pneumo","fiche":"p205","front":"Hémoptysie d'origine vasculaire pulmonaire : quel traitement envisager ?","back":"**Vaso-occlusion artérielle pulmonaire** par abord **veineux**.","prio":"P3","sec":"s8"},{"id":"fc-p205-2be5af","poly":"pneumo","fiche":"p205","front":"Embolisation bronchique : quelle est la complication la plus grave ?","back":"Embolisation de l'**artère spinale antérieure** (artère d'**Adamkiewicz**).","prio":"P2","sec":"s8"},{"id":"fc-p205-c3694a","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelles conditions pour une chirurgie ?","back":"Lésion **limitée et unilatérale**, **fonction respiratoire** suffisante.","prio":"P2","sec":"s8"},{"id":"fc-p205-aeff68","poly":"pneumo","fiche":"p205","front":"Chirurgie de l'hémoptysie : quel geste habituel ?","back":"**Lobectomie** (plus rarement pneumonectomie) : arrête le saignement et évite la récidive.","prio":"P3","sec":"s8"},{"id":"fc-p205-97b6b4","poly":"pneumo","fiche":"p205","front":"Chirurgie de l'hémoptysie : à chaud ou à froid ?","back":"**À froid**, à distance de l'épisode ; ou **à chaud** en cas d'**échec de l'embolisation** (mortalité importante à chaud).","prio":"P2","sec":"s8"},{"id":"fc-p205-2288d1","poly":"pneumo","fiche":"p205","front":"Hémoptysie non grave : quel traitement topique ?","back":"Instillation de **sérum physiologique à 4 °C** ou de **solution adrénalinée** (indication anecdotique).","prio":"P3","sec":"s8"},{"id":"fc-p205-90f0f9","poly":"pneumo","fiche":"p205","front":"Toilette bronchique dans l'hémoptysie : quel piège éviter ?","back":"**Mobiliser le caillot** : à proscrire.","prio":"P3","sec":"s8"},{"id":"fc-p205-cb426f","poly":"pneumo","fiche":"p205","front":"Hémoptysie hospitalisée : quels paramètres surveiller ?","back":"**Volume des crachats** (par tranches de 3 h), **SpO₂** (> 90 %), signes de **détresse respiratoire**, tarissement du saignement.","prio":"P2","sec":"s9"},{"id":"fc-p205-94f107","poly":"pneumo","fiche":"p205","front":"Hémoptysie : quelle biologie surveiller et pourquoi ?","back":"**Gaz du sang**, **hémoglobine**, **plaquettes**, **coagulation** : gravité et préparation d'un geste d'hémostase.","prio":"P3","sec":"s9"},{"id":"fc-p206-988d77","poly":"pneumo","fiche":"p206","front":"Plèvre normale : quel volume de liquide produit-elle par jour ?","back":"**5 à 20 mL/j** : film permettant le glissement des deux feuillets.","prio":"P2","sec":"s1"},{"id":"fc-p206-d1fff5","poly":"pneumo","fiche":"p206","front":"Liquide pleural : par où est-il réabsorbé ?","back":"Par les **pores lymphatiques** (« stomas ») des plèvres **pariétale et médiastinale**.","prio":"P3","sec":"s1"},{"id":"fc-p206-27d009","poly":"pneumo","fiche":"p206","front":"Pleurésie : quel mécanisme général ?","back":"Rupture de l'équilibre **sécrétion / résorption** du liquide pleural ; une pleurésie est **toujours pathologique**.","prio":"P1","sec":"s1"},{"id":"fc-p206-38ec21","poly":"pneumo","fiche":"p206","front":"Pleurésie mécanique : quelles causes par hausse de pression hydrostatique ?","back":"**Insuffisance cardiaque**, **hypertension portale**.","prio":"P2","sec":"s1"},{"id":"fc-p206-e3fd94","poly":"pneumo","fiche":"p206","front":"Pleurésie mécanique : quelles causes par baisse de pression oncotique ?","back":"Hypoalbuminémie : **syndrome néphrotique**, **insuffisance hépatocellulaire**, **dénutrition sévère**.","prio":"P2","sec":"s1"},{"id":"fc-p206-8e43a6","poly":"pneumo","fiche":"p206","front":"Pleurésie mécanique : quels autres mécanismes que les pressions hydrostatique et oncotique ?","back":"**Dépression pleurale** accrue (atélectasie) · passage d'**ascite** dans la plèvre (puits de Ranvier).","prio":"P3","sec":"s1"},{"id":"fc-p206-442681","poly":"pneumo","fiche":"p206","front":"Pleurésie par agression de la plèvre : quelles causes ?","back":"**Inflammation**, **infection**, **cancer**.","prio":"P2","sec":"s1"},{"id":"fc-p206-a7e8cb","poly":"pneumo","fiche":"p206","front":"Transsudat : quelles caractéristiques ?","back":"Pleurésie « **symptôme** » : plèvre **saine**, liquide **clair**, pauvre en protéines, LDH basses.","prio":"P2","sec":"s1"},{"id":"fc-p206-233bb0","poly":"pneumo","fiche":"p206","front":"Exsudat : quelles caractéristiques ?","back":"Pleurésie « **maladie** » : plèvre **pathologique**, liquide d'aspect variable, **riche en protéines**.","prio":"P2","sec":"s1"},{"id":"fc-p206-bc2a43","poly":"pneumo","fiche":"p206","front":"Transsudat : quels seuils de protides et LDH pleuraux ?","back":"Protides **< 25 g/L** ; LDH **< 200 UI/L**.","prio":"P1","sec":"s1"},{"id":"fc-p206-1c32d4","poly":"pneumo","fiche":"p206","front":"Exsudat : quels seuils de protides et LDH pleuraux ?","back":"Protides **> 35 g/L** ; LDH **> 200 UI/L**.","prio":"P1","sec":"s1"},{"id":"fc-p206-9b5e00","poly":"pneumo","fiche":"p206","front":"Pleurésie : quelles sont les deux questions à poser, dans l'ordre ?","back":"**Exsudat ou transsudat ?** puis **quelle cause ?**","prio":"P1","sec":"s1"},{"id":"fc-p206-d977e0","poly":"pneumo","fiche":"p206","front":"Transsudat : quels organes évaluer ?","back":"**Cœur**, **foie**, **reins**.","prio":"P2","sec":"s1"},{"id":"fc-p206-79c682","poly":"pneumo","fiche":"p206","front":"Transsudats classés à tort en exsudats : quelle proportion et quel exemple ?","back":"Près de **20 %**, ex. insuffisant cardiaque sous **diurétiques**.","prio":"P2","sec":"s1"},{"id":"fc-p206-204266","poly":"pneumo","fiche":"p206","front":"Doute transsudat/exsudat : quel critère complémentaire ?","back":"Le **gradient d'albumine** sang − plèvre.","prio":"P2","sec":"s1"},{"id":"fc-p206-49b47b","poly":"pneumo","fiche":"p206","front":"Douleur pleurale : quelles caractéristiques ?","back":"Latérothoracique, irradiant à l'épaule ou au dos, **↑ à l'inspiration profonde et à la toux**, **non reproduite à la palpation** ; surtout dans les exsudats.","prio":"P1","sec":"s2"},{"id":"fc-p206-53c401","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : de quoi dépend l'intensité de la dyspnée ?","back":"De l'**abondance**, de la **vitesse d'accumulation** et du **terrain**.","prio":"P2","sec":"s2"},{"id":"fc-p206-3f6f09","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quel type de toux ?","back":"**Sèche**, déclenchée par les **changements de position**.","prio":"P2","sec":"s2"},{"id":"fc-p206-2c3b48","poly":"pneumo","fiche":"p206","front":"Épanchement pleural fébrile aigu : quelle cause la plus fréquente ?","back":"Une **pneumonie sous-jacente** (épanchement parapneumonique).","prio":"P1","sec":"s2"},{"id":"fc-p206-de3642","poly":"pneumo","fiche":"p206","front":"Syndrome pleural liquidien : quels signes d'examen ?","back":"**Matité** · **silence auscultatoire** · **abolition des vibrations vocales** ; parfois souffle pleurétique.","prio":"P1","sec":"s2"},{"id":"fc-p206-53c986","poly":"pneumo","fiche":"p206","front":"Souffle pleurétique : quelles caractéristiques ?","back":"**Expiratoire**, au **sommet** d'un épanchement abondant.","prio":"P3","sec":"s2"},{"id":"fc-p206-050355","poly":"pneumo","fiche":"p206","front":"Syndrome pleural : quelle valeur diagnostique ?","back":"Il **oriente** mais n'est **pas spécifique**.","prio":"P2","sec":"s2"},{"id":"fc-p206-3e6e43","poly":"pneumo","fiche":"p206","front":"Pleurésie de moins de 500 mL : que montre l'examen ?","back":"Souvent **normal**, ou seulement un **frottement pleural**.","prio":"P1","sec":"s2"},{"id":"fc-p206-5f6477","poly":"pneumo","fiche":"p206","front":"Infection respiratoire basse : quand penser à une pleurésie ?","back":"**Fièvre** en forme aiguë · pneumonie avec **douleur intense de type pleural** · pneumonie qui **évolue mal** sous antibiotiques.","prio":"P1","sec":"s2"},{"id":"fc-p206-a9e42c","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quels examens confirment le diagnostic ?","back":"**Radiographie** et/ou **échographie**.","prio":"P1","sec":"s3"},{"id":"fc-p206-a36f7f","poly":"pneumo","fiche":"p206","front":"Pleurésie à la radiographie de face : quel aspect typique ?","back":"Opacité **dense, homogène, non systématisée**, **non rétractile**, effaçant les contours, **ligne bordante concave en haut et en dedans**.","prio":"P1","sec":"s3"},{"id":"fc-p206-f160aa","poly":"pneumo","fiche":"p206","front":"Pleurésie minime à la radiographie : quel aspect ?","back":"Simple **comblement du cul-de-sac pleural**.","prio":"P2","sec":"s3"},{"id":"fc-p206-031521","poly":"pneumo","fiche":"p206","front":"Pleurésie de moyenne abondance : comment s'appelle la ligne bordante ?","back":"**Ligne de Damoiseau**.","prio":"P2","sec":"s3"},{"id":"fc-p206-dc37ba","poly":"pneumo","fiche":"p206","front":"Pleurésie de grande abondance à la radiographie : quel aspect ?","back":"**Opacité de tout l'hémithorax**, **médiastin repoussé du côté opposé**.","prio":"P1","sec":"s3"},{"id":"fc-p206-505399","poly":"pneumo","fiche":"p206","front":"Opacité d'un hémithorax avec médiastin attiré vers elle : quel diagnostic ?","back":"**Atélectasie** (pleurésie = médiastin repoussé côté sain).","prio":"P1","sec":"s3"},{"id":"fc-p206-21b7d9","poly":"pneumo","fiche":"p206","front":"« Poumon blanc » avec bronchogramme aérique : quelle orientation ?","back":"**Syndrome alvéolaire** (pas une pleurésie).","prio":"P1","sec":"s3"},{"id":"fc-p206-6e6bfb","poly":"pneumo","fiche":"p206","front":"Poumon blanc : quelles lésions sont systématisées ?","back":"**Atélectasie** et **syndrome alvéolaire** ; la pleurésie est **non systématisée**.","prio":"P2","sec":"s3"},{"id":"fc-p206-fe7ad6","poly":"pneumo","fiche":"p206","front":"Échographie pleurale : quel aspect de l'épanchement liquidien ?","back":"**Image anéchogène**.","prio":"P2","sec":"s3"},{"id":"fc-p206-f7dd29","poly":"pneumo","fiche":"p206","front":"Échographie pleurale : quel rôle pour la ponction ?","back":"Elle doit **systématiquement guider la ponction** (repérage précis).","prio":"P1","sec":"s3"},{"id":"fc-p206-2e9a40","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : le scanner est-il indispensable en urgence ?","back":"**Non**, pas pour le diagnostic.","prio":"P1","sec":"s3"},{"id":"fc-p206-d50413","poly":"pneumo","fiche":"p206","front":"Scanner thoracique dans la pleurésie : quel intérêt majeur ?","back":"La **cause** : analyse du poumon sous-jacent, au besoin après évacuation (« **plèvre vide** »).","prio":"P1","sec":"s3"},{"id":"fc-p206-7fa80a","poly":"pneumo","fiche":"p206","front":"Scanner « plèvre vide » : quelles lésions orientent un exsudat ?","back":"**Plaques pleurales** · **nodule(s) ou masse(s)** du parenchyme · autres anomalies pulmonaires.","prio":"P2","sec":"s3"},{"id":"fc-p206-a5bfe4","poly":"pneumo","fiche":"p206","front":"Scanner et poches cloisonnées : fait-il mieux que l'échographie ?","back":"**Non** : utile pour les repérer, sans faire mieux que l'échographie.","prio":"P3","sec":"s3"},{"id":"fc-p206-4f1b0f","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quels sont les 3 volets de gravité ?","back":"**Clinique** (mauvaise tolérance) · **radiologique** (grande abondance) · **infectieux** (fièvre).","prio":"P2","sec":"s4"},{"id":"fc-p206-d8b270","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quelles indications de ponction en urgence ?","back":"Épanchement **fébrile** (but étiologique) ou **mal toléré** (but évacuateur) ; sinon ponction **rapide**.","prio":"P1","sec":"s4"},{"id":"fc-p206-552f3d","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : le volume seul fait-il la gravité ?","back":"**Non** : un adulte sain peut tolérer sans dyspnée plus d'un hémithorax ; c'est la **tolérance clinique** qui décide.","prio":"P1","sec":"s4"},{"id":"fc-p206-7584e0","poly":"pneumo","fiche":"p206","front":"Épanchement mal toléré : quel volume retirer ?","back":"**1 à 2 L** suffisent le plus souvent.","prio":"P1","sec":"s4"},{"id":"fc-p206-bd43a2","poly":"pneumo","fiche":"p206","front":"Vidange trop rapide d'un gros épanchement : quel risque ?","back":"**Œdème aigu de réexpansion** (œdème a vacuo).","prio":"P1","sec":"s4"},{"id":"fc-p206-37cedb","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique compliqué : quel délai d'évacuation ?","back":"L'évacuer **le plus tôt possible**.","prio":"P2","sec":"s4"},{"id":"fc-p206-09d5eb","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quels patients ponctionner ?","back":"La **majorité**, d'abord pour le **diagnostic** ; tout épanchement **fébrile** en urgence.","prio":"P2","sec":"s5"},{"id":"fc-p206-ff847a","poly":"pneumo","fiche":"p206","front":"Épanchement pleural : quand ne pas ponctionner d'emblée ?","back":"**Cause connue** et bonne tolérance · **insuffisance cardiaque** suspectée · épanchement **minime**.","prio":"P1","sec":"s5"},{"id":"fc-p206-717271","poly":"pneumo","fiche":"p206","front":"Insuffisant cardiaque gauche connu : quand ponctionner l'épanchement ?","back":"**Unilatéral ou asymétrique** · **douleur ou fièvre** · **aucun changement sous diurétiques** · **mauvaise tolérance**.","prio":"P1","sec":"s5"},{"id":"fc-p206-331378","poly":"pneumo","fiche":"p206","front":"Liquide pleural : quelle est la 1re étape de l'enquête étiologique ?","back":"L'**aspect à l'œil**.","prio":"P2","sec":"s5"},{"id":"fc-p206-ac9430","poly":"pneumo","fiche":"p206","front":"Liquide pleural : quel aspect est le plus fréquent ?","back":"**Citrin**.","prio":"P2","sec":"s5"},{"id":"fc-p206-3603be","poly":"pneumo","fiche":"p206","front":"Liquide pleural lactescent : quelle orientation ?","back":"**Chylothorax** (chyle dans la plèvre).","prio":"P2","sec":"s5"},{"id":"fc-p206-27f53e","poly":"pneumo","fiche":"p206","front":"Liquide pleural hémorragique hors traumatisme : quelle orientation d'abord ?","back":"Un épanchement **néoplasique** ; il ne signe pas toujours un hémothorax (peu de sang suffit à teinter).","prio":"P2","sec":"s5"},{"id":"fc-p206-a51cee","poly":"pneumo","fiche":"p206","front":"Liquide pleural hémorragique après traumatisme : quel examen ?","back":"**Hématocrite pleural**.","prio":"P1","sec":"s5"},{"id":"fc-p206-7fd68c","poly":"pneumo","fiche":"p206","front":"Liquide pleural non franchement citrin et clair : quelle orientation ?","back":"**Exsudat a priori** ; mais un liquide citrin peut aussi être un exsudat.","prio":"P2","sec":"s5"},{"id":"fc-p206-7a36ec","poly":"pneumo","fiche":"p206","front":"Liquide pleural : quelles analyses de 1re intention ?","back":"**Biochimie** (protides, LDH, albumine) · **cytologie** · **bactériologie** (pyogènes + mycobactéries).","prio":"P1","sec":"s5"},{"id":"fc-p206-a85f9c","poly":"pneumo","fiche":"p206","front":"Bactériologie pleurale des pyogènes : quelles techniques ?","back":"**Examen direct** + **cultures en aérobie et en anaérobie**.","prio":"P2","sec":"s5"},{"id":"fc-p206-790e08","poly":"pneumo","fiche":"p206","front":"Mycobactéries dans le liquide pleural : quelles techniques ?","back":"**Examen direct** + culture sur **milieux spéciaux**.","prio":"P2","sec":"s5"},{"id":"fc-p206-b3b563","poly":"pneumo","fiche":"p206","front":"Exsudat : que rechercher systématiquement à la cytologie ?","back":"Des **cellules tumorales**.","prio":"P2","sec":"s5"},{"id":"fc-p206-afbceb","poly":"pneumo","fiche":"p206","front":"Liquide pleural : quand doser l'amylase ?","back":"Suspicion de pathologie **pancréatique** ou **sous-phrénique**.","prio":"P2","sec":"s5"},{"id":"fc-p206-34c645","poly":"pneumo","fiche":"p206","front":"Liquide pleural lactescent : quel dosage et quel seuil affirme le chylothorax ?","back":"**Triglycérides** ; **> 1,1 g/L** (1,2 mmol/L).","prio":"P2","sec":"s5"},{"id":"fc-p206-2d09ad","poly":"pneumo","fiche":"p206","front":"Liquide pleural : quelles analyses de 2e intention pour la tuberculose ?","back":"**PCR BK** et **adénosine désaminase**, selon le contexte.","prio":"P2","sec":"s5"},{"id":"fc-p206-147801","poly":"pneumo","fiche":"p206","front":"Épanchement avec pneumonie associée : quelle conduite ?","back":"**Ponction immédiate** pour distinguer forme parapneumonique **compliquée ou non**.","prio":"P1","sec":"s6"},{"id":"fc-p206-debd8d","poly":"pneumo","fiche":"p206","front":"Épanchement en contexte de traumatisme : quelle conduite ?","back":"**Ponction immédiate** pour le diagnostic d'**hémothorax**.","prio":"P1","sec":"s6"},{"id":"fc-p206-c5cde3","poly":"pneumo","fiche":"p206","front":"Épanchement chez un patient ayant un cancer connu : que chercher ?","back":"Des **cellules tumorales** dans le liquide (localisation secondaire).","prio":"P2","sec":"s6"},{"id":"fc-p206-a00776","poly":"pneumo","fiche":"p206","front":"Transsudat : quel bilan cardiaque ?","back":"**Échographie** cardiaque et **NT-proBNP** (+ fonctions hépatique et rénale).","prio":"P2","sec":"s6"},{"id":"fc-p206-214d17","poly":"pneumo","fiche":"p206","front":"Exsudat : quelle est LA question à se poser ?","back":"**S'agit-il d'un cancer ?**","prio":"P1","sec":"s6"},{"id":"fc-p206-e2bcba","poly":"pneumo","fiche":"p206","front":"Épanchement néoplasique : quelle est la 1re cause ?","back":"Le **cancer du poumon**.","prio":"P1","sec":"s6"},{"id":"fc-p206-107aab","poly":"pneumo","fiche":"p206","front":"Exsudat qui ne fait pas sa preuve : que faire ?","back":"**Biopsie pleurale**.","prio":"P1","sec":"s6"},{"id":"fc-p206-923231","poly":"pneumo","fiche":"p206","front":"Exsudat sans cause malgré les biopsies : quelle conduite ?","back":"**Surveillance prolongée** : on pense toujours à un **cancer**.","prio":"P1","sec":"s6"},{"id":"fc-p206-db55d1","poly":"pneumo","fiche":"p206","front":"Transsudats plutôt bilatéraux : quelles causes ?","back":"**Insuffisance cardiaque**, **syndrome néphrotique**.","prio":"P2","sec":"s6"},{"id":"fc-p206-26eb8d","poly":"pneumo","fiche":"p206","front":"Transsudats plutôt unilatéraux : quelles causes ?","back":"**Cirrhose**, **embolie pulmonaire**.","prio":"P2","sec":"s6"},{"id":"fc-p206-c21b56","poly":"pneumo","fiche":"p206","front":"Exsudats à cellules tumorales : quelles causes ?","back":"**Pleurésie métastatique**, **mésothéliome**.","prio":"P2","sec":"s6"},{"id":"fc-p206-2483d6","poly":"pneumo","fiche":"p206","front":"Exsudat à neutrophiles : quelle cause ?","back":"**Épanchement parapneumonique**.","prio":"P2","sec":"s6"},{"id":"fc-p206-e19e6f","poly":"pneumo","fiche":"p206","front":"Exsudats à lymphocytes : quelles causes ?","back":"**Tuberculose** · **cancer** · pleurésie des **collagénoses** (PR, lupus).","prio":"P1","sec":"s6"},{"id":"fc-p206-70b435","poly":"pneumo","fiche":"p206","front":"Exsudats à éosinophiles : quelles causes ?","back":"**Embolie pulmonaire** · antécédent d'**hémothorax** · **parasitose** · **cancer**.","prio":"P2","sec":"s6"},{"id":"fc-p206-bf4086","poly":"pneumo","fiche":"p206","front":"Embolie pulmonaire : comment le Collège classe-t-il son épanchement ?","back":"Tableau : transsudat plutôt unilatéral **et** exsudat à éosinophiles ; texte : exsudat non tumoral non infectieux. Retenir les deux.","prio":"P2","sec":"s6"},{"id":"fc-p206-9ce6b7","poly":"pneumo","fiche":"p206","front":"Formule cytologique pleurale : quelle valeur ?","back":"Valeur d'orientation **très faible** : oriente parfois, ne fait **pas le diagnostic**.","prio":"P2","sec":"s6"},{"id":"fc-p206-d3d53d","poly":"pneumo","fiche":"p206","front":"Épanchement de l'insuffisance cardiaque gauche : quelles caractéristiques ?","back":"**Bilatéral et symétrique**, **rarement abondant**.","prio":"P1","sec":"s7"},{"id":"fc-p206-288e2d","poly":"pneumo","fiche":"p206","front":"Insuffisance cardiaque gauche : quels signes radiographiques associés à l'épanchement ?","back":"**Cardiomégalie**, surcharge vasculaire pulmonaire, comblement alvéolaire.","prio":"P2","sec":"s7"},{"id":"fc-p206-641cc6","poly":"pneumo","fiche":"p206","front":"Épanchement de la cirrhose : quelles caractéristiques ?","back":"**Indolore**, bien toléré sauf abondant, **à droite** ou à prédominance droite.","prio":"P2","sec":"s7"},{"id":"fc-p206-b3bdf7","poly":"pneumo","fiche":"p206","front":"Cirrhose : quand l'épanchement impose-t-il un bilan plus poussé ?","back":"**Douloureux**, **fébrile** ou **bilatéral** sans syndrome œdémato-ascitique.","prio":"P2","sec":"s7"},{"id":"fc-p206-ff9a0f","poly":"pneumo","fiche":"p206","front":"Épanchement du syndrome néphrotique : quel mécanisme et quel aspect ?","back":"**↓ pression oncotique** capillaire ; **bilatéral et symétrique**.","prio":"P2","sec":"s7"},{"id":"fc-p206-e906d4","poly":"pneumo","fiche":"p206","front":"Pleurésies néoplasiques : lesquelles sont les plus fréquentes ?","back":"Les **pleurésies métastatiques**.","prio":"P2","sec":"s8"},{"id":"fc-p206-9c1751","poly":"pneumo","fiche":"p206","front":"Pleurésie métastatique : quels cancers primitifs les plus fréquents ?","back":"**Poumon** et **sein**.","prio":"P1","sec":"s8"},{"id":"fc-p206-82c96f","poly":"pneumo","fiche":"p206","front":"Pleurésie métastatique : quelles caractéristiques de l'épanchement ?","back":"Souvent **abondant et récidivant** ; liquide séro-hématique, rosé ou citrin.","prio":"P2","sec":"s8"},{"id":"fc-p206-85a714","poly":"pneumo","fiche":"p206","front":"Pleurésie néoplasique : que recherche le scanner après évacuation ?","back":"**Masse** sous-jacente · **épaississement irrégulier**/bourgeons pleuraux · **lâcher de ballons** · **lymphangite** · **adénomégalies** médiastinales.","prio":"P2","sec":"s8"},{"id":"fc-p206-dfa0ca","poly":"pneumo","fiche":"p206","front":"Épanchements malins : dans quelle proportion le cytodiagnostic trouve-t-il des cellules tumorales ?","back":"**2/3**.","prio":"P1","sec":"s8"},{"id":"fc-p206-1d3fe6","poly":"pneumo","fiche":"p206","front":"Cytodiagnostic pleural : quand peut-il suffire au diagnostic de cancer ?","back":"Cellules **nombreuses** et matériel permettant une analyse complète (morphologie, immunohistochimie, biologie moléculaire).","prio":"P2","sec":"s8"},{"id":"fc-p206-515b38","poly":"pneumo","fiche":"p206","front":"Cytodiagnostic pleural négatif : élimine-t-il un cancer ?","back":"**Non** : une **preuve histologique** est nécessaire.","prio":"P1","sec":"s8"},{"id":"fc-p206-4143e9","poly":"pneumo","fiche":"p206","front":"Cellules mésothéliales atypiques dans le liquide pleural : quelle interprétation ?","back":"**Normales** : pas une preuve de cancer, encore moins de mésothéliome.","prio":"P1","sec":"s8"},{"id":"fc-p206-d489f1","poly":"pneumo","fiche":"p206","front":"Biopsies pleurales : quand les faire dans une pleurésie néoplasique ?","back":"Si la plèvre est le **seul site atteint** ou s'il est **facile d'accès**.","prio":"P2","sec":"s8"},{"id":"fc-p206-20dced","poly":"pneumo","fiche":"p206","front":"Biopsies pleurales : quelle rentabilité selon la technique ?","back":"Percutanées à l'aveugle : **faible** ; guidées écho/scanner : meilleure si épaississement ou nodules ; **thoracoscopie : excellente**.","prio":"P2","sec":"s8"},{"id":"fc-p206-851257","poly":"pneumo","fiche":"p206","front":"Mésothéliome : quelle définition ?","back":"**Tumeur primitive de la plèvre**.","prio":"P2","sec":"s8"},{"id":"fc-p206-391e55","poly":"pneumo","fiche":"p206","front":"Mésothéliome : quel facteur de risque ?","back":"Exposition professionnelle à l'**amiante**, **même faible**.","prio":"P1","sec":"s8"},{"id":"fc-p206-32b430","poly":"pneumo","fiche":"p206","front":"Mésothéliome : dans quelle proportion l'exposition à l'amiante manque-t-elle ?","back":"**20 à 40 %** des cas (femmes ++).","prio":"P2","sec":"s8"},{"id":"fc-p206-03bbb8","poly":"pneumo","fiche":"p206","front":"Mésothéliome : quelle évolution clinique ?","back":"**Asymptomatique au début**, souvent **douloureux** à un stade avancé.","prio":"P2","sec":"s8"},{"id":"fc-p206-d3441d","poly":"pneumo","fiche":"p206","front":"Mésothéliome : quels signes d'imagerie ?","back":"**Festonnement** pleural · épaississement diffus (évocateur si **circonférentiel**) · **rétraction de l'hémithorax** · parfois plaques calcifiées.","prio":"P1","sec":"s8"},{"id":"fc-p206-6f1806","poly":"pneumo","fiche":"p206","front":"Mésothéliome : quel aspect du liquide pleural ?","back":"**Citrin** ou **séro-hématique**.","prio":"P3","sec":"s8"},{"id":"fc-p206-80b911","poly":"pneumo","fiche":"p206","front":"Mésothéliome : comment fait-on le diagnostic ?","back":"**Biopsies indispensables**, plus rentables **sous thoracoscopie**.","prio":"P1","sec":"s8"},{"id":"fc-p206-1d3d42","poly":"pneumo","fiche":"p206","front":"Exsudats infectieux : à quoi sont-ils le plus souvent associés ?","back":"Aux **pneumonies bactériennes** (épanchements parapneumoniques).","prio":"P2","sec":"s9"},{"id":"fc-p206-d66b30","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique : quel type cellulaire ?","back":"Exsudat riche en **polynucléaires neutrophiles**.","prio":"P2","sec":"s9"},{"id":"fc-p206-5751d6","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique : à quoi sert la ponction ?","back":"Éliminer un **empyème** et choisir le traitement local (abstention ou drainage ± lavage) ; éventuellement identifier le **germe**.","prio":"P2","sec":"s9"},{"id":"fc-p206-e07ce5","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique non compliqué : quels critères ?","back":"**Faible abondance** · liquide **clair** à PNN non altérés · **aucun germe** à l'examen direct ni en culture.","prio":"P2","sec":"s9"},{"id":"fc-p206-d499b4","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique compliqué : quels critères (un seul suffit) ?","back":"**Abondant** (au-dessus du hile) · **cloisonné** · **purulent** · **germes** à l'examen direct ou culture positive.","prio":"P2","sec":"s9"},{"id":"fc-p206-deb71a","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique compliqué : quel traitement ?","back":"Anti-infectieux + **évacuation urgente par drain** ± lavage ou **fibrinolyse** pleurale.","prio":"P2","sec":"s9"},{"id":"fc-p206-11940a","poly":"pneumo","fiche":"p206","front":"Pleurésie virale : quelles caractéristiques ?","back":"Contemporaine d'une pneumonie d'allure virale, parfois **péricardite** associée ; épanchement **peu abondant**.","prio":"P2","sec":"s9"},{"id":"fc-p206-a713cd","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : dans quels contextes survient-elle ?","back":"Pleurésie **sérofibrineuse** juste après une **primo-infection** ou par **réactivation** d'un foyer ancien.","prio":"P2","sec":"s9"},{"id":"fc-p206-f7e314","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quelle clinique ?","back":"Peu spécifique : **fièvre modérée**, **amaigrissement**.","prio":"P2","sec":"s9"},{"id":"fc-p206-e13320","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : BK dans l'expectoration, quelle positivité ?","back":"Exceptionnellement positif (**10 %**).","prio":"P2","sec":"s9"},{"id":"fc-p206-df43b5","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quel aspect radiographique du parenchyme ?","back":"Lésions **peu étendues**, voire **invisibles**.","prio":"P3","sec":"s9"},{"id":"fc-p206-2b3452","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quel aspect du liquide ?","back":"**Citrin**, **lymphocytaire**.","prio":"P2","sec":"s9"},{"id":"fc-p206-c12d7b","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quelle rentabilité de la bactériologie du liquide ?","back":"Examen direct **exceptionnellement positif** ; culture et PCR positives dans **moins de la moitié** des cas.","prio":"P2","sec":"s9"},{"id":"fc-p206-3ea0b9","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quel dosage pleural a une excellente sensibilité ?","back":"**Adénosine désaminase > 50 U/L**.","prio":"P1","sec":"s9"},{"id":"fc-p206-e1c739","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quel examen apporte surtout la preuve ?","back":"Les **biopsies pleurales** (à l'aveugle ou sous thoracoscopie), excellent rendement.","prio":"P1","sec":"s9"},{"id":"fc-p206-dc14d4","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quelle histologie de la biopsie ?","back":"**Granulomes avec nécrose caséeuse**.","prio":"P2","sec":"s19"},{"id":"fc-p206-dc61d6","poly":"pneumo","fiche":"p206","front":"Embolie pulmonaire : quelle proportion a un épanchement pleural ?","back":"**20 %** : peu abondant, **citrin ou séro-hématique**.","prio":"P2","sec":"s10"},{"id":"fc-p206-21cba3","poly":"pneumo","fiche":"p206","front":"Pleurésie bénigne liée à l'amiante : quelles caractéristiques ?","back":"**Diagnostic d'exclusion** ; suspectée sur des **plaques pleurales** ± calcifiées chez un exposé.","prio":"P2","sec":"s10"},{"id":"fc-p206-2af393","poly":"pneumo","fiche":"p206","front":"Pleurésie bénigne liée à l'amiante : quel diagnostic redouter et comment l'éliminer ?","back":"Le **mésothéliome** → **biopsie pleurale sous thoracoscopie**.","prio":"P2","sec":"s10"},{"id":"fc-p206-a3129c","poly":"pneumo","fiche":"p206","front":"Exsudats de maladies de système : citer les principales ?","back":"**Lupus érythémateux disséminé**, **polyarthrite rhumatoïde**.","prio":"P2","sec":"s10"},{"id":"fc-p206-a27cdb","poly":"pneumo","fiche":"p206","front":"Petit épanchement citrin ou séro-hématique : quel diagnostic ne pas oublier ?","back":"L'**embolie pulmonaire** : y penser et l'éliminer.","prio":"P1","sec":"s11"},{"id":"fc-p206-f82960","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : quelle préparation si l'urgence le permet ?","back":"**Arrêt des antiagrégants** (sauf aspirine faible dose) ; relais de l'anticoagulant pour **INR < 1,5**.","prio":"P1","sec":"s12"},{"id":"fc-p206-b922e7","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : comment choisir le site ?","back":"**Examen clinique** ET **repérage échographique**, en **pleine matité**.","prio":"P2","sec":"s12"},{"id":"fc-p206-0a3f05","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : le patient doit-il être à jeun ?","back":"**Non** ; assis confortablement.","prio":"P2","sec":"s12"},{"id":"fc-p206-5532bf","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : où introduire l'aiguille dans l'espace intercostal ?","back":"Au ras du **bord supérieur de la côte inférieure**, perpendiculaire à la paroi.","prio":"P1","sec":"s12"},{"id":"fc-p206-89f9a9","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : comment pousser l'aiguille ?","back":"« **Vide à la main** » : sentir l'entrée dans la plèvre et s'arrêter aussitôt.","prio":"P2","sec":"s12"},{"id":"fc-p206-251f1e","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : faut-il vider l'épanchement ?","back":"**Non** s'il est bien toléré ; **oui** s'il est mal toléré (permet aussi un scanner « plèvre vide »).","prio":"P2","sec":"s12"},{"id":"fc-p206-865da9","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : quelle est la complication la plus fréquente ?","back":"Le **pneumothorax**, rare sous échoguidage (**< 1 %**).","prio":"P1","sec":"s12"},{"id":"fc-p206-15e7dd","poly":"pneumo","fiche":"p206","front":"Pneumothorax post-ponction suspecté : quel examen ?","back":"**Radiographie** ou **échographie** de contrôle.","prio":"P2","sec":"s12"},{"id":"fc-p206-af8c37","poly":"pneumo","fiche":"p206","front":"Ponction pleurale : quelles complications autres que le pneumothorax ?","back":"**Hémothorax** (blessure vasculaire) · **œdème aigu de réexpansion** si vidange trop rapide.","prio":"P2","sec":"s12"},{"id":"fc-p206-4c61f1","poly":"pneumo","fiche":"p206","front":"Épanchement mal toléré : comment profiter de la vidange pour l'étiologie ?","back":"**Scanner thoracique** du parenchyme sous-jacent après évacuation.","prio":"P2","sec":"s13"},{"id":"fc-p206-8e6481","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique non compliqué : quel traitement ?","back":"Celui de la pneumonie : **antibiothérapie**.","prio":"P2","sec":"s14"},{"id":"fc-p206-36a768","poly":"pneumo","fiche":"p206","front":"Pneumonie avec épanchement : quand réévaluer ?","back":"Réévaluation clinique systématique à **48-72 h** d'antibiothérapie.","prio":"P2","sec":"s14"},{"id":"fc-p206-89baaa","poly":"pneumo","fiche":"p206","front":"Pneumonie qui s'aggrave sous antibiotiques : que chercher avant une 2e ligne ?","back":"Une **complication locorégionale** (dont la pleurésie) ou un **autre diagnostic**.","prio":"P2","sec":"s14"},{"id":"fc-p206-f0fe30","poly":"pneumo","fiche":"p206","front":"Empyème : les antibiotiques seuls suffisent-ils ?","back":"**Non** : évacuation **en urgence** par drain.","prio":"P2","sec":"s15"},{"id":"fc-p206-1ef153","poly":"pneumo","fiche":"p206","front":"Épanchement parapneumonique à liquide clair : exclut-il une forme compliquée ?","back":"**Non** : des **germes** à l'examen direct ou une culture positive suffisent.","prio":"P3","sec":"s15"},{"id":"fc-p206-fa7eff","poly":"pneumo","fiche":"p206","front":"Épanchement de l'insuffisant cardiaque : quel diurétique et quelle dose de furosémide ?","back":"**Diurétique de l'anse** (furosémide, bumétamide) ; furosémide de **20 mg/j** à 500 mg/j voire 1 g/j, dose minimale efficace.","prio":"P2","sec":"s16"},{"id":"fc-p206-b1410d","poly":"pneumo","fiche":"p206","front":"Pleurésie néoplasique abondante récidivante : quel traitement ?","back":"**Symphyse pleurale par talcage** ou **cathéter pleural tunnelisé** à demeure.","prio":"P2","sec":"s17"},{"id":"fc-p206-9e0dec","poly":"pneumo","fiche":"p206","front":"Pleurésie tuberculeuse : quel schéma antituberculeux ?","back":"**INH + RMP + EMB + PZA 2 mois**, puis **INH + RMP 4 mois** (6 mois au total).","prio":"P1","sec":"s19"},{"id":"fc-p206-cbb617","poly":"pneumo","fiche":"p206","front":"Tuberculose : quelle localisation est traitée plus longtemps que 6 mois ?","back":"La **neuroméningée**.","prio":"P2","sec":"s19"},{"id":"fc-p206-4b6c7d","poly":"pneumo","fiche":"p206","front":"Antituberculeux : quel bilan avant traitement ?","back":"**Créatinine/DFG**, **uricémie**, **transaminases**, hémogramme ; sérologies **VIH, VHB, VHC** ; examen **ophtalmologique**.","prio":"P2","sec":"s19"},{"id":"fc-p206-f6fb66","poly":"pneumo","fiche":"p206","front":"Éthambutol : quel examen au début et peut-il être différé ?","back":"**Examen ophtalmologique** (couleurs, champ visuel) ; peut être **différé** car le traitement est urgent.","prio":"P2","sec":"s19"},{"id":"fc-p206-746dcf","poly":"pneumo","fiche":"p206","front":"Antituberculeux : quelles modalités de prise ?","back":"**Prise unique quotidienne** ; rifampicine **à jeun** ; polyantibiothérapie obligatoire.","prio":"P2","sec":"s19"},{"id":"fc-p206-6939dc","poly":"pneumo","fiche":"p206","front":"Rifampicine : à quel moment la prendre ?","back":"**30 min à 1 h avant** le repas ou **au moins 2 h après**.","prio":"P2","sec":"s19"},{"id":"fc-p206-6f82f6","poly":"pneumo","fiche":"p206","front":"Pyrazinamide contre-indiqué ou effet indésirable grave : quel schéma alternatif ?","back":"**INH + RMP + EMB 2 mois** puis **INH + RMP 7 mois**.","prio":"P2","sec":"s19"},{"id":"fc-p206-b91193","poly":"pneumo","fiche":"p206","front":"Pyrazinamide : quelles contre-indications ?","back":"**Insuffisance hépatocellulaire** ou **rénale**.","prio":"P2","sec":"s19"},{"id":"fc-p206-c62c86","poly":"pneumo","fiche":"p206","front":"Rifampicine : quelle interaction majeure ?","back":"Puissant **inducteur enzymatique** (AVK, AOD, **pilule œstroprogestative**…).","prio":"P1","sec":"s19"},{"id":"fc-p206-cf4717","poly":"pneumo","fiche":"p206","front":"Isoniazide : quand prescrire de la pyridoxine (B6) ?","back":"Notamment **grossesse**, **alcoolisme chronique**, **dénutrition** : prévention de la **polyneuropathie**.","prio":"P2","sec":"s19"},{"id":"fc-p206-473c16","poly":"pneumo","fiche":"p206","front":"Tuberculose traitée : quelles démarches administratives ?","back":"**Déclaration obligatoire** (ARS) + signalement au **CLAT**, même sans preuve bactériologique ; **ALD n° 29**.","prio":"P2","sec":"s19"},{"id":"fc-p206-ebba37","poly":"pneumo","fiche":"p206","front":"Antituberculeux : quelle surveillance hépatique ?","back":"Transaminases **chaque semaine le 1er mois** (isoniazide, pyrazinamide), puis selon le terrain.","prio":"P1","sec":"s19"},{"id":"fc-p206-bec9e4","poly":"pneumo","fiche":"p206","front":"Antituberculeux : quels effets indésirables spécifiques ?","back":"**Névrite optique** (éthambutol) · **hyperuricémie** (pyrazinamide) · urines et larmes **orange** (rifampicine, normal).","prio":"P2","sec":"s19"},{"id":"fc-p206-6b3fc3","poly":"pneumo","fiche":"p206","front":"Antituberculeux : quand adapter le traitement ?","back":"Dès réception de l'**antibiogramme**.","prio":"P3","sec":"s19"},{"id":"fc-p206-04098b","poly":"pneumo","fiche":"p206","front":"Embolie pulmonaire suspectée : quand débuter l'anticoagulation ?","back":"**Dès la suspicion**, à dose curative, sans attendre les examens (urgence thérapeutique).","prio":"P1","sec":"s21"},{"id":"fc-p206-13bed4","poly":"pneumo","fiche":"p206","front":"Embolie pulmonaire : quel anticoagulant en 1re intention ?","back":"**AOD** (rivaroxaban ou apixaban) ; sinon HBPM, fondaparinux ou HNF avec relais AVK.","prio":"P2","sec":"s21"},{"id":"fc-p206-c80a5e","poly":"pneumo","fiche":"p206","front":"Avant anticoagulation d'une EP : quel bilan ?","back":"**Plaquettes**, **TP**, **TCA**, NFS, **créatinine**, transaminases (± bilan prétransfusionnel).","prio":"P2","sec":"s21"},{"id":"fc-p206-326b23","poly":"pneumo","fiche":"p206","front":"AOD : quelle contre-indication rénale ?","back":"Clairance **< 30 mL/min** (Cockcroft) ; le texte précise < 30 rivaroxaban, **< 25 apixaban**.","prio":"P2","sec":"s21"},{"id":"fc-p206-075a53","poly":"pneumo","fiche":"p206","front":"Insuffisant cardiaque avec épanchement : comment le suivre ?","back":"Évolution sous **diurétiques** ; l'absence de modification fait **ponctionner**.","prio":"P2","sec":"s22"},{"id":"fc-p207-84523b","poly":"pneumo","fiche":"p207","front":"Opacité intraparenchymateuse : taille d'un micronodule ?","back":"**< 3 mm**.","prio":"P1","sec":"s1"},{"id":"fc-p207-226404","poly":"pneumo","fiche":"p207","front":"Opacité intraparenchymateuse : taille d'un nodule ?","back":"**3 à 30 mm** (moins de 3 cm).","prio":"P1","sec":"s1"},{"id":"fc-p207-15fabc","poly":"pneumo","fiche":"p207","front":"Opacité intraparenchymateuse : taille d'une masse ?","back":"**> 3 cm** (« 3 et 3 » : sous 3 mm micronodule, au-dessus de 3 cm masse).","prio":"P1","sec":"s1"},{"id":"fc-p207-93bf13","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : trois densités possibles ?","back":"**Solide**, **verre dépoli pur**, **mixte**.","prio":"P1","sec":"s1"},{"id":"fc-p207-2d2ba8","poly":"pneumo","fiche":"p207","front":"Opacité ronde du thorax : avec quoi ne pas confondre un nodule parenchymateux ?","back":"Les opacités rondes **extra-parenchymateuses** (paroi thoracique, plèvre).","prio":"P2","sec":"s1"},{"id":"fc-p207-98497e","poly":"pneumo","fiche":"p207","front":"Nodules solides : mode de mesure de plus en plus utilisé ?","back":"Le **volume** (mm³), calculé par ordinateur par le radiologue.","prio":"P2","sec":"s1"},{"id":"fc-p207-bf6905","poly":"pneumo","fiche":"p207","front":"Mesure d'un nodule ≤ 10 mm : méthode ?","back":"**Moyenne** du grand axe et du petit axe perpendiculaire (au-delà de 10 mm ou si rond : plus grand diamètre).","prio":"P3","sec":"s1"},{"id":"fc-p207-ed6ae5","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : quatre circonstances de découverte ?","back":"Bilan d'une **maladie respiratoire** ; bilan d'une **autre maladie** ; découverte **fortuite** ; **dépistage**.","prio":"P2","sec":"s2"},{"id":"fc-p207-af9d5e","poly":"pneumo","fiche":"p207","front":"Nodule découvert au bilan d'une autre maladie : comment l'interpréter ?","back":"À la lumière du **terrain** (ex. bilan d'extension d'un cancer, maladie de système).","prio":"P2","sec":"s2"},{"id":"fc-p207-f9c859","poly":"pneumo","fiche":"p207","front":"Radiographie thoracique et nodules : est-elle adaptée ?","back":"**Non** : inadaptée pour découvrir et décrire nodules et micronodules ; une radio normale ne rassure pas.","prio":"P1","sec":"s2"},{"id":"fc-p207-a9ed06","poly":"pneumo","fiche":"p207","front":"Radiographie thoracique : place dans le dépistage du cancer du poumon ?","back":"**Aucune**.","prio":"P1","sec":"s2"},{"id":"fc-p207-803c46","poly":"pneumo","fiche":"p207","front":"Dépistage du cancer du poumon en France : existe-t-il un dépistage organisé recommandé ?","back":"**Pas encore** (HAS 2016) ; des **programmes pilotes** sont en cours.","prio":"P2","sec":"s2"},{"id":"fc-p207-026f3f","poly":"pneumo","fiche":"p207","front":"Dépistage du cancer du poumon : modalités du scanner démontré efficace ?","back":"Scanner **faiblement dosé**, **sans injection**, tous les **1 à 2 ans**.","prio":"P2","sec":"s2"},{"id":"fc-p207-9123b0","poly":"pneumo","fiche":"p207","front":"Dépistage par scanner faiblement dosé : bénéfice sur la mortalité ?","back":"Mortalité par cancer **−20 à 25 %** ; mortalité globale **−7 %**.","prio":"P2","sec":"s2"},{"id":"fc-p207-e5163a","poly":"pneumo","fiche":"p207","front":"Dépistage du cancer du poumon : population éligible (âge et sevrage) ?","back":"**50 à 75 ans**, fumeur actuel ou **sevré depuis 10 ans au plus**.","prio":"P2","sec":"s2"},{"id":"fc-p207-e07e46","poly":"pneumo","fiche":"p207","front":"Dépistage du cancer du poumon : seuils de consommation tabagique ?","back":"**> 15 cig/j depuis > 25 ans**, ou **> 10 cig/j depuis > 30 ans**.","prio":"P3","sec":"s2"},{"id":"fc-p207-93c9f0","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : six éléments de la démarche bénin/malin ?","back":"**Terrain**, **facteurs de risque** (tabac), **taille**, **morphologie** scanner, **évolution**, **activité métabolique** en TEP-FDG.","prio":"P1","sec":"s3"},{"id":"fc-p207-ffadef","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : critères cliniques de haut risque de malignité ?","back":"Sujet **plus âgé**, **fumeur**, **antécédent de cancer**.","prio":"P1","sec":"s3"},{"id":"fc-p207-942443","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : critères scanographiques de haut risque ?","back":"Taille plus grande, contours **irréguliers/spiculés** attirant les structures voisines, **lobe supérieur**.","prio":"P1","sec":"s3"},{"id":"fc-p207-d0729d","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : critères TEP et évolutifs de haut risque ?","back":"**Fixation élevée** ; **augmentation** de taille ou de volume.","prio":"P1","sec":"s3"},{"id":"fc-p207-e34d53","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : critères cliniques et scanographiques de faible risque ?","back":"Sujet **jeune**, non ou peu fumeur ; petite taille, contours **réguliers**, **hors lobes supérieurs**.","prio":"P1","sec":"s3"},{"id":"fc-p207-ccc590","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : fixation en TEP-FDG en faveur d'un faible risque ?","back":"Fixation **faible ou nulle**.","prio":"P2","sec":"s3"},{"id":"fc-p207-af24c6","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : évolutions en faveur d'un faible risque ?","back":"**Disparition** ou quasi, **diminution** de taille, **stabilité**.","prio":"P2","sec":"s3"},{"id":"fc-p207-2b6a93","poly":"pneumo","fiche":"p207","front":"Nodule solide : durée de stabilité rassurante ?","back":"**2 ans**.","prio":"P1","sec":"s3"},{"id":"fc-p207-8a51d1","poly":"pneumo","fiche":"p207","front":"Nodule en verre dépoli : durée de stabilité rassurante ?","back":"**3 à 5 ans**.","prio":"P1","sec":"s3"},{"id":"fc-p207-fc334b","poly":"pneumo","fiche":"p207","front":"Critères de malignité d'un nodule : existe-t-il des valeurs seuils ?","back":"**Non** : c'est un **jugement clinique**.","prio":"P2","sec":"s3"},{"id":"fc-p207-8e68d4","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : quel examen donne le diagnostic de certitude ?","back":"L'**histologie** (aucun argument clinique ou radiologique n'est formel).","prio":"P1","sec":"s3"},{"id":"fc-p207-9128fc","poly":"pneumo","fiche":"p207","front":"Nodule calcifié : quels types de calcification sont en faveur de la bénignité ?","back":"**Totale**, **centrale** (sur 2 reconstructions orthogonales), **périphérique** ou **lamellaire**.","prio":"P2","sec":"s3"},{"id":"fc-p207-bbd3c9","poly":"pneumo","fiche":"p207","front":"Nodule à calcification bénigne : origine la plus fréquente ?","back":"**Cicatrice** d'une lésion **post-infectieuse**.","prio":"P3","sec":"s3"},{"id":"fc-p207-9137ee","poly":"pneumo","fiche":"p207","front":"Ganglion intrapulmonaire : aspect scanographique ?","back":"Nodule tissulaire homogène **< 10 mm**, triangulaire ou ovalaire, **< 15 mm de la plèvre**, sous la carène.","prio":"P3","sec":"s3"},{"id":"fc-p207-51479c","poly":"pneumo","fiche":"p207","front":"Tumeur bénigne pulmonaire la plus fréquente ?","back":"**Hamartochondrome**.","prio":"P2","sec":"s3"},{"id":"fc-p207-ec005f","poly":"pneumo","fiche":"p207","front":"Hamartochondrome : aspect scanographique pathognomonique ?","back":"Aspect **« en pop-corn »** : **calcifications** + **densités graisseuses**.","prio":"P2","sec":"s3"},{"id":"fc-p207-d4dbf5","poly":"pneumo","fiche":"p207","front":"Cancer bronchopulmonaire primitif : type histologique le plus fréquent ?","back":"**Adénocarcinome**.","prio":"P1","sec":"s4"},{"id":"fc-p207-1be905","poly":"pneumo","fiche":"p207","front":"Adénocarcinome bronchique : terrain et présentation habituels ?","back":"**Fumeur de plus de 50 ans** ; le plus souvent **nodule pulmonaire solitaire**.","prio":"P1","sec":"s4"},{"id":"fc-p207-c8bcc0","poly":"pneumo","fiche":"p207","front":"Tumeurs carcinoïdes bronchiques : nature ?","back":"Tumeurs **neuroendocrines de bas grade**.","prio":"P1","sec":"s4"},{"id":"fc-p207-027935","poly":"pneumo","fiche":"p207","front":"Métastases pulmonaires : aspect scanographique ?","back":"Opacités rondes uniques ou multiples, **souvent périphériques et bilatérales**, à **contours réguliers**.","prio":"P1","sec":"s4"},{"id":"fc-p207-e7cfd5","poly":"pneumo","fiche":"p207","front":"Contours réguliers d'un nodule : quel piège ?","back":"Critère de faible risque, mais les **métastases** ont justement des contours **réguliers**.","prio":"P1","sec":"s4"},{"id":"fc-p207-242641","poly":"pneumo","fiche":"p207","front":"Opacité mixte (verre dépoli + solide) attirant la scissure : diagnostic illustré par le Collège ?","back":"**Adénocarcinome d'architecture lépidique**.","prio":"P2","sec":"s4"},{"id":"fc-p207-ed19b4","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : citer des cancers primitifs donnant des métastases pulmonaires ?","back":"Poumon, **côlon**, **rein**, **thyroïde**, ORL, **mélanome**, **testicule**, sein, prostate, tumeur osseuse.","prio":"P3","sec":"s4"},{"id":"fc-p207-8d4f83","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : citer des opacités non tumorales ?","back":"Ganglion intrapulmonaire, **GPA**, nodules rhumatoïdes, kyste hydatique, aspergillome, abcès, **tuberculome**, atélectasie ronde, silicose.","prio":"P3","sec":"s4"},{"id":"fc-p207-6c6ee6","poly":"pneumo","fiche":"p207","front":"Tumeurs bénignes du poumon : part parmi les nodules thoraciques et aspect ?","back":"**1/10** ; opacité **unique**, sphérique, à contour **régulier**.","prio":"P3","sec":"s4"},{"id":"fc-p207-6e611e","poly":"pneumo","fiche":"p207","front":"Abcès pulmonaire à pyogène : ce qui le distingue d'une tumeur ?","back":"Contexte **aigu fébrile**, **excavation rapide** avec **vomique**.","prio":"P3","sec":"s4"},{"id":"fc-p207-39b513","poly":"pneumo","fiche":"p207","front":"Actinomyces et Nocardia : pourquoi sont-ils des pièges diagnostiques ?","back":"Bactéries filamenteuses lentes : l'opacité peut **imiter un cancer** au scanner comme en **TEP-FDG**.","prio":"P2","sec":"s4"},{"id":"fc-p207-fb559f","poly":"pneumo","fiche":"p207","front":"Actinomycose pulmonaire : porte d'entrée habituelle ?","back":"**Dentaire**.","prio":"P3","sec":"s4"},{"id":"fc-p207-61ce1b","poly":"pneumo","fiche":"p207","front":"Tuberculome : aspect scanographique et conduite si tuberculose non connue ?","back":"**Calcifications concentriques** ; **prélèvements mycobactériologiques** dirigés (foyer peut être actif).","prio":"P3","sec":"s4"},{"id":"fc-p207-1feb7d","poly":"pneumo","fiche":"p207","front":"Kyste hydatique pulmonaire : signe scanographique en cas de décollement ?","back":"**« Membrane flottante »** sous un croissant gazeux.","prio":"P3","sec":"s4"},{"id":"fc-p207-6470f0","poly":"pneumo","fiche":"p207","front":"Aspergillome : mécanisme, image scanner et confirmation ?","back":"Prolifération mycélienne dans une **cavité préexistante** ; image **« en grelot »** ; **sérologie aspergillaire** (arcs de précipitation).","prio":"P2","sec":"s4"},{"id":"fc-p207-7ab17d","poly":"pneumo","fiche":"p207","front":"Malformations artérioveineuses pulmonaires : contexte habituel ?","back":"**Maladie de Rendu-Osler** familiale ; souvent **multiples**.","prio":"P3","sec":"s4"},{"id":"fc-p207-53c4e2","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : examen essentiel d'orientation étiologique ?","back":"**Scanner thoracique avec injection** de produit de contraste.","prio":"P1","sec":"s5"},{"id":"fc-p207-903038","poly":"pneumo","fiche":"p207","front":"Scanner d'un nodule : éléments associés importants à rechercher ?","back":"**Plaques pleurales** asbestosiques, **adénopathies médiastinales**.","prio":"P2","sec":"s5"},{"id":"fc-p207-c5bbf7","poly":"pneumo","fiche":"p207","front":"Scanner d'un nodule : quelle décision pratique guide-t-il ?","back":"Le **mode de prélèvement** : ponction/biopsie **transpariétale** ou abord **chirurgical**.","prio":"P2","sec":"s5"},{"id":"fc-p207-e021cc","poly":"pneumo","fiche":"p207","front":"TEP-FDG positive sur un nodule : rapport de vraisemblance en faveur du cancer ?","back":"De l'ordre de **4**.","prio":"P1","sec":"s5"},{"id":"fc-p207-4278cd","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : intérêt des scanners répétés ?","back":"Juger l'**évolutivité** de la lésion.","prio":"P2","sec":"s5"},{"id":"fc-p207-00e3d6","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : qu'est-ce qui affirme la nature cancéreuse ?","back":"La **preuve anatomopathologique** (jamais l'imagerie seule).","prio":"P1","sec":"s5"},{"id":"fc-p207-df2e74","poly":"pneumo","fiche":"p207","front":"TEP-FDG : causes de faux négatifs sur un nodule ?","back":"Nodule **< 1 cm** ; nodule en **verre dépoli pur**.","prio":"P2","sec":"s5"},{"id":"fc-p207-7a385d","poly":"pneumo","fiche":"p207","front":"TEP-FDG : causes de faux positifs en France ?","back":"Inflammation granulomateuse/infection : **actinomycose**, **nocardiose**, **mycobactérioses**, **aspergilloses**, **sarcoïdose**.","prio":"P2","sec":"s5"},{"id":"fc-p207-509d43","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : de quoi dépend le choix des examens diagnostiques ?","back":"Risque du terrain, taille, aspect scanner et TEP, évolutivité et **fonction respiratoire**.","prio":"P3","sec":"s5"},{"id":"fc-p207-680921","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : premier temps avant tout prélèvement invasif ?","back":"**Examen clinique** attentif à la recherche d'une lésion facile à prélever (adénopathie **sus-claviculaire**…).","prio":"P2","sec":"s5"},{"id":"fc-p207-b11710","poly":"pneumo","fiche":"p207","front":"Endoscopie bronchique devant un nodule : limite et intérêt ?","back":"Ne voit que les **bronches centrales** ; reste indiquée pour chercher une **lésion plus proximale**.","prio":"P3","sec":"s5"},{"id":"fc-p207-6b6600","poly":"pneumo","fiche":"p207","front":"Ponction transpariétale d'un nodule : fréquence du pneumothorax ?","back":"**10 à 20 %** des cas.","prio":"P2","sec":"s5"},{"id":"fc-p207-4c2763","poly":"pneumo","fiche":"p207","front":"Ponction transpariétale : facteurs favorisant le pneumothorax ?","back":"Nodule **loin de la plèvre** ou dans un lobe **emphysémateux**.","prio":"P3","sec":"s5"},{"id":"fc-p207-6f98eb","poly":"pneumo","fiche":"p207","front":"Ponction transpariétale : quel examen faire avant le geste, et pourquoi ?","back":"**Spirométrie** : un pneumothorax est mal toléré en cas d'insuffisance respiratoire.","prio":"P2","sec":"s5"},{"id":"fc-p207-f553a5","poly":"pneumo","fiche":"p207","front":"Biopsie échoguidée d'une lésion pulmonaire : à quelles lésions est-elle réservée ?","back":"Lésions **au contact de la plèvre**, en centre spécialisé.","prio":"P3","sec":"s5"},{"id":"fc-p207-947cea","poly":"pneumo","fiche":"p207","front":"Adénopathies médiastinales fixant en TEP : moyen de prélèvement ?","back":"**Écho-endoscopie transbronchique**, voire **médiastinoscopie**.","prio":"P3","sec":"s5"},{"id":"fc-p207-bef395","poly":"pneumo","fiche":"p207","front":"Exérèse d'un nodule avec extemporané montrant un cancer primitif : conduite ?","back":"Compléter par une **résection anatomique** (lobectomie le plus souvent) + **curage ganglionnaire**.","prio":"P2","sec":"s5"},{"id":"fc-p207-23af63","poly":"pneumo","fiche":"p207","front":"Masse du médiastin : base de l'orientation étiologique ?","back":"Sa **localisation précise** dans le médiastin.","prio":"P1","sec":"s6"},{"id":"fc-p207-807836","poly":"pneumo","fiche":"p207","front":"Médiastin : en combien de loges est-il découpé ?","back":"**9 loges** : 3 **étages** × 3 **compartiments**.","prio":"P1","sec":"s6"},{"id":"fc-p207-3bb2dc","poly":"pneumo","fiche":"p207","front":"Médiastin : limites de l'étage supérieur ?","back":"Au-dessus de la portion horizontale de la **crosse aortique**.","prio":"P1","sec":"s6"},{"id":"fc-p207-1dbf53","poly":"pneumo","fiche":"p207","front":"Médiastin : limites de l'étage moyen ?","back":"Entre l'**aorte** et la **carène**.","prio":"P1","sec":"s6"},{"id":"fc-p207-4b97a0","poly":"pneumo","fiche":"p207","front":"Médiastin : limite de l'étage inférieur ?","back":"**Sous la carène**.","prio":"P1","sec":"s6"},{"id":"fc-p207-128f8e","poly":"pneumo","fiche":"p207","front":"Médiastin : situation des compartiments antérieur, moyen et postérieur ?","back":"Antérieur : en avant de l'axe trachéal ; moyen : à hauteur de l'**axe trachéobronchique** ; postérieur : en arrière.","prio":"P1","sec":"s6"},{"id":"fc-p207-4aaf35","poly":"pneumo","fiche":"p207","front":"Syndrome médiastinal : définition ?","back":"Signes dus à l'atteinte d'un **organe du médiastin** (tumorale, inflammatoire ou infectieuse).","prio":"P3","sec":"s6"},{"id":"fc-p207-356d13","poly":"pneumo","fiche":"p207","front":"Masse médiastinale à la radiographie : caractéristiques de l'opacité ?","back":"Limite externe **nette et convexe**, raccord en **pente douce**, **pas de limite interne**, tonalité **hydrique**.","prio":"P3","sec":"s6"},{"id":"fc-p207-cce7aa","poly":"pneumo","fiche":"p207","front":"Signe de la silhouette : principe ?","back":"Une masse située **en avant du médiastin** en **efface les bords**, et inversement : signe **localisateur** majeur.","prio":"P3","sec":"s6"},{"id":"fc-p207-76e293","poly":"pneumo","fiche":"p207","front":"Masse médiastinale : pourquoi injecter le scanner ?","back":"Reconnaître les **vaisseaux**, vérifier la **perméabilité** d'un gros tronc, écarter un **anévrysme**.","prio":"P3","sec":"s6"},{"id":"fc-p207-3ef40d","poly":"pneumo","fiche":"p207","front":"Masse du médiastin postérieur : examen complémentaire du scanner ?","back":"**IRM** (repère les lésions infiltrantes).","prio":"P2","sec":"s6"},{"id":"fc-p207-e9d525","poly":"pneumo","fiche":"p207","front":"Médiastin antérieur et supérieur : causes principales ?","back":"**Goitre thyroïdien** (plongeant), lésions **parathyroïdiennes**.","prio":"P2","sec":"s7"},{"id":"fc-p207-dfba82","poly":"pneumo","fiche":"p207","front":"Médiastin antérieur et moyen : causes principales ?","back":"Lésions **thymiques**, **tératomes**, **tumeurs germinales**.","prio":"P2","sec":"s7"},{"id":"fc-p207-7b7786","poly":"pneumo","fiche":"p207","front":"Médiastin antérieur et inférieur : cause principale ?","back":"**Kystes pleuro-péricardiques** (angle cardiophrénique, souvent asymptomatiques).","prio":"P2","sec":"s7"},{"id":"fc-p207-fc35ac","poly":"pneumo","fiche":"p207","front":"Médiastin moyen : cause la plus fréquente de masse ?","back":"Les **adénopathies**.","prio":"P2","sec":"s7"},{"id":"fc-p207-5e0f9a","poly":"pneumo","fiche":"p207","front":"Kyste bronchogénique : siège et aspect ?","back":"Médiastin **moyen** ; masse régulière, arrondie, **liquidienne**, au contact de l'arbre bronchique.","prio":"P3","sec":"s7"},{"id":"fc-p207-2e6506","poly":"pneumo","fiche":"p207","front":"Médiastin postérieur : cause principale, à tous les étages ?","back":"**Tumeurs neurogènes** (« en arrière, les nerfs »).","prio":"P2","sec":"s7"},{"id":"fc-p207-270252","poly":"pneumo","fiche":"p207","front":"Tumeurs neurogènes du médiastin : bénignes ou malignes selon l'âge ?","back":"Plutôt **bénignes chez l'adulte** (surtout **schwannome**), **malignes chez l'enfant**.","prio":"P2","sec":"s7"},{"id":"fc-p207-50e2d6","poly":"pneumo","fiche":"p207","front":"Tumeurs neurogènes : part parmi les tumeurs du médiastin ?","back":"Environ **1/3**.","prio":"P3","sec":"s7"},{"id":"fc-p207-a136f1","poly":"pneumo","fiche":"p207","front":"Goitre plongeant : quel examen affirme le diagnostic et comment ?","back":"Le **scanner** : **continuité avec la thyroïde**, calcifications fréquentes.","prio":"P2","sec":"s7"},{"id":"fc-p207-1c2794","poly":"pneumo","fiche":"p207","front":"Thymus chez l'adulte : à partir de quand un thymus qui grossit est-il pathologique ?","back":"Après **40 ans** (normalement il involue en graisse).","prio":"P2","sec":"s7"},{"id":"fc-p207-67ac21","poly":"pneumo","fiche":"p207","front":"Tumeurs épithéliales du thymus : maladie auto-immune pouvant les révéler ?","back":"**Myasthénie** (anticorps anti-récepteurs de l'acétylcholine).","prio":"P2","sec":"s7"},{"id":"fc-p207-dcfce4","poly":"pneumo","fiche":"p207","front":"Tumeurs du thymus : trois catégories ?","back":"Tumeurs **épithéliales**, **lymphomes** thymiques, **kystes et tumeurs bénignes**.","prio":"P3","sec":"s7"},{"id":"fc-p207-8536a7","poly":"pneumo","fiche":"p207","front":"Tératomes du médiastin : nature et fréquence parmi les tumeurs germinales ?","back":"Tumeurs germinales **bénignes** : **60 à 70 %** des tumeurs germinales du médiastin.","prio":"P3","sec":"s7"},{"id":"fc-p207-ffc44a","poly":"pneumo","fiche":"p207","front":"Séminome médiastinal : terrain ?","back":"Tumeur maligne de l'**homme jeune**.","prio":"P3","sec":"s7"},{"id":"fc-p207-9e977d","poly":"pneumo","fiche":"p207","front":"Adénopathies médiastinales : causes tumorales fréquentes ?","back":"**Cancers bronchopulmonaires**, **lymphome**, **LLC**, métastases de cancers extrathoraciques.","prio":"P2","sec":"s7"},{"id":"fc-p207-6fc819","poly":"pneumo","fiche":"p207","front":"Adénopathies médiastinales : causes non tumorales fréquentes ?","back":"**Sarcoïdose**, **tuberculose**, **silicose**, infections chroniques, histoplasmose.","prio":"P2","sec":"s7"},{"id":"fc-p207-e2d69d","poly":"pneumo","fiche":"p207","front":"Adénopathies médiastinales diffuses, non spécifiques, modérées : cause non pulmonaire ?","back":"**Insuffisance cardiaque gauche**.","prio":"P3","sec":"s7"},{"id":"fc-p207-211c19","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire : sur quel examen raisonner, scanner ou radiographie ?","back":"Le **scanner thoracique**.","prio":"P1","sec":"s8"},{"id":"fc-p207-05e81e","poly":"pneumo","fiche":"p207","front":"Nodule pulmonaire découvert : y a-t-il un traitement médicamenteux dans cet item ?","back":"**Non** : item diagnostique (si cancer prouvé, prise en charge du cancer bronchique).","prio":"P3","sec":"s8"},{"id":"fc-p207-a301f5","poly":"pneumo","fiche":"p207","front":"Dépistage du cancer du poumon : faut-il injecter le scanner ?","back":"**Non**, scanner **sans** produit de contraste.","prio":"P2","sec":"s9"},{"id":"fc-p207-fc650c","poly":"pneumo","fiche":"p207","front":"Masse médiastinale bénigne typique : faut-il une preuve histologique avant traitement ?","back":"**Non** (goitre plongeant, kyste typique, thymome bien limité résécable, tumeur neurogène de l'adulte).","prio":"P2","sec":"s10"},{"id":"fc-p207-079aab","poly":"pneumo","fiche":"p207","front":"Masse médiastinale : situations imposant une preuve histologique ?","back":"Thymus **mal limité**, **tératome**, **tumeur germinale**, **adénopathies**, tumeur neurogène de l'**enfant**, toute tumeur mal limitée.","prio":"P2","sec":"s10"},{"id":"fc-p207-932bde","poly":"pneumo","fiche":"p207","front":"Masse du médiastin antérieur : marqueurs à doser ?","back":"**Alpha-fœtoprotéine** et **HCG**.","prio":"P2","sec":"s10"},{"id":"fc-p207-a2854b","poly":"pneumo","fiche":"p207","front":"Masse du médiastin antérieur : abords diagnostiques possibles ?","back":"**Ponction transpariétale**, **médiastinotomie antérieure** (2e espace intercostal), ou chirurgie diagnostique et d'exérèse.","prio":"P3","sec":"s10"},{"id":"fc-p207-d69bea","poly":"pneumo","fiche":"p207","front":"Adénopathies du médiastin moyen : examen de référence et sa limite ?","back":"**Médiastinoscopie** (Se/Sp ≈ 100 %) ; n'explore pas **sous la région précarinaire**.","prio":"P2","sec":"s10"},{"id":"fc-p207-893782","poly":"pneumo","fiche":"p207","front":"Adénopathies médiastinales : quelle technique tend à remplacer la médiastinoscopie ?","back":"La **ponction transbronchique échoguidée** (EBUS).","prio":"P2","sec":"s10"},{"id":"fc-p207-1ba3d8","poly":"pneumo","fiche":"p207","front":"Masse du médiastin postérieur : abords diagnostiques ?","back":"**Ponction transpariétale**, ponction **trans-œsophagienne échoguidée**, ou chirurgie.","prio":"P3","sec":"s10"},{"id":"fc-p207-4917cb","poly":"pneumo","fiche":"p207","front":"Masse médiastinale : condition d'une chirurgie diagnostique et d'exérèse en un temps ?","back":"Exérèse **complète** et **peu mutilante** (tumeur parfaitement limitée).","prio":"P2","sec":"s10"},{"id":"fc-p207-047b29","poly":"pneumo","fiche":"p207","front":"Compression médiastinale aiguë chez l'homme jeune : tumeur à suspecter ?","back":"**Tumeur germinale non séminomateuse** (TGNS) ; urgence vitale.","prio":"P2","sec":"s11"},{"id":"fc-p207-597f12","poly":"pneumo","fiche":"p207","front":"TGNS suspectée en urgence : quand peut-on se passer de preuve histologique ?","back":"Élévation **franche** de l'**AFP** ou de l'**HCG** (une seule suffit).","prio":"P2","sec":"s11"},{"id":"fc-p207-25acbd","poly":"pneumo","fiche":"p207","front":"TGNS suspectée avec marqueurs non élevés : conduite ?","back":"Rechercher la **preuve histologique**.","prio":"P3","sec":"s11"},{"id":"fc-p208-241de4","poly":"pneumo","fiche":"p208","front":"Insuffisance respiratoire : quelle définition physiologique ?","back":"**Insuffisance d'organe** : l'appareil respiratoire n'assure plus les **échanges gazeux** (apport d'O₂, élimination du CO₂).","prio":"P2","sec":"s1"},{"id":"fc-p208-3ec53a","poly":"pneumo","fiche":"p208","front":"IRC : quelle définition gazométrique ?","back":"**PaO₂ < 70 mmHg (9,3 kPa)** en **air ambiant**, au **repos**, à l'**état stable**.","prio":"P1","sec":"s1"},{"id":"fc-p208-f5b249","poly":"pneumo","fiche":"p208","front":"IRC : combien de gaz du sang faut-il et à quel intervalle ?","back":"**2 mesures** à **au moins 2 semaines** d'intervalle (pour confirmer l'état stable).","prio":"P1","sec":"s1"},{"id":"fc-p208-402e17","poly":"pneumo","fiche":"p208","front":"IRC : sur quel examen repose exclusivement le diagnostic ?","back":"La **gazométrie artérielle**.","prio":"P1","sec":"s1"},{"id":"fc-p208-9234d6","poly":"pneumo","fiche":"p208","front":"IRC : quels sont les principaux signes cliniques ?","back":"**Dyspnée** et signes d'**hypoventilation alvéolaire**.","prio":"P2","sec":"s1"},{"id":"fc-p208-d7066b","poly":"pneumo","fiche":"p208","front":"IRC hypoxémique : quelle PaCO₂ ?","back":"**Normale ou diminuée** (PaO₂ abaissée).","prio":"P1","sec":"s1"},{"id":"fc-p208-1d5c9c","poly":"pneumo","fiche":"p208","front":"IRC hypercapnique : quelle gazométrie ?","back":"PaO₂ **abaissée** + PaCO₂ **élevée**.","prio":"P1","sec":"s1"},{"id":"fc-p208-9a5c3a","poly":"pneumo","fiche":"p208","front":"IRC : citer les 3 causes les plus fréquentes.","back":"**BPCO**, **syndrome obésité-hypoventilation**, **maladies neuromusculaires**.","prio":"P1","sec":"s1"},{"id":"fc-p208-51912b","poly":"pneumo","fiche":"p208","front":"IRC : quel pronostic ?","back":"**Sévère**.","prio":"P2","sec":"s1"},{"id":"fc-p208-dac84d","poly":"pneumo","fiche":"p208","front":"IRC grave : quelle définition ?","back":"**PaO₂ < 60 mmHg (8,0 kPa)** en air ambiant, au repos, à l'état stable.","prio":"P2","sec":"s1"},{"id":"fc-p208-79e1ff","poly":"pneumo","fiche":"p208","front":"IRC grave : quel droit administratif ouvre-t-elle ?","back":"Exonération du ticket modérateur : **ALD 14** (et critère HAS d'OLD).","prio":"P2","sec":"s1"},{"id":"fc-p208-b87f8b","poly":"pneumo","fiche":"p208","front":"IRC grave en France : combien de patients ?","back":"Près de **300 000**.","prio":"P3","sec":"s1"},{"id":"fc-p208-6c5c0b","poly":"pneumo","fiche":"p208","front":"Hypoxémie chronique : quels sont les 3 grands mécanismes ?","back":"**Inégalité VA/Q** (effet shunt, shunt vrai), **hypoventilation alvéolaire** (pure ou espace mort), **trouble de diffusion**.","prio":"P2","sec":"s2"},{"id":"fc-p208-08373d","poly":"pneumo","fiche":"p208","front":"Effet shunt : quel mécanisme ?","back":"Alvéoles **mal ventilées mais normalement perfusées** → hypoxie alvéolaire puis hypoxémie.","prio":"P2","sec":"s2"},{"id":"fc-p208-a50f0c","poly":"pneumo","fiche":"p208","front":"Effet shunt : citer des exemples.","back":"Atteinte des **voies aériennes distales** : **BPCO** (en aigu comme en chronique), **asthme en aigu**.","prio":"P3","sec":"s2"},{"id":"fc-p208-df08a2","poly":"pneumo","fiche":"p208","front":"Effet shunt : quelle PaCO₂ et pourquoi ?","back":"**Basse** par **hyperventilation compensatrice** ; hypercapnie seulement à un stade avancé.","prio":"P2","sec":"s2"},{"id":"fc-p208-a1bdbf","poly":"pneumo","fiche":"p208","front":"Effet shunt : comment répond l'hypoxémie à l'oxygène ?","back":"**De faibles débits** la corrigent en général.","prio":"P2","sec":"s2"},{"id":"fc-p208-36f125","poly":"pneumo","fiche":"p208","front":"Shunt vrai : comment répond l'hypoxémie à l'oxygène ?","back":"Corrigée **mal ou pas**, même à **haut débit**.","prio":"P2","sec":"s2"},{"id":"fc-p208-7eff29","poly":"pneumo","fiche":"p208","front":"Shunt vrai anatomique : citer des exemples.","back":"**Foramen ovale perméable**, **malformation artério-veineuse pulmonaire**, cardiopathie cyanogène.","prio":"P3","sec":"s2"},{"id":"fc-p208-ee4dde","poly":"pneumo","fiche":"p208","front":"Shunt vrai fonctionnel : citer des exemples.","back":"**Atélectasie** (obstacle bronchique) ; comblement alvéolaire : **OAP, pneumonie, SDRA**.","prio":"P3","sec":"s2"},{"id":"fc-p208-5ca19a","poly":"pneumo","fiche":"p208","front":"Hypoventilation alvéolaire pure : quelle PaCO₂ ?","back":"**≥ 45 mmHg (6,0 kPa)** ; la baisse de PaO₂ suit la hausse de PaCO₂.","prio":"P2","sec":"s2"},{"id":"fc-p208-b1bb15","poly":"pneumo","fiche":"p208","front":"Hypoventilation alvéolaire pure : quelle relation entre PaO₂ et PaCO₂ ?","back":"**PaO₂ + PaCO₂ > 120 mmHg** (16 kPa), valable **sans oxygène** et avec un **parenchyme sain**.","prio":"P3","sec":"s2"},{"id":"fc-p208-5c834a","poly":"pneumo","fiche":"p208","front":"Hypoventilation alvéolaire pure : citer des causes.","back":"Commande centrale (**surdosage en opiacés**) ; pompe : diaphragme/muscles inspiratoires, déformation thoracique, baisse de compliance.","prio":"P3","sec":"s2"},{"id":"fc-p208-406b10","poly":"pneumo","fiche":"p208","front":"Effet espace mort : quel mécanisme ?","back":"Unités **ventilées mais mal perfusées** : le rapport **VD/Vt augmente**.","prio":"P3","sec":"s2"},{"id":"fc-p208-7d8779","poly":"pneumo","fiche":"p208","front":"BPCO : quel est le principal mécanisme de l'hypercapnie ?","back":"L'**effet espace mort**.","prio":"P2","sec":"s2"},{"id":"fc-p208-73abfc","poly":"pneumo","fiche":"p208","front":"Effet espace mort : citer des exemples.","back":"**Embolie pulmonaire** ; **emphysème** avec destruction capillaire > alvéolaire.","prio":"P3","sec":"s2"},{"id":"fc-p208-f30bc8","poly":"pneumo","fiche":"p208","front":"Trouble de la diffusion : quelle PaCO₂ et pourquoi ?","back":"**Normale ou basse** : le CO₂ diffuse **20 fois mieux** que l'O₂.","prio":"P2","sec":"s2"},{"id":"fc-p208-e31962","poly":"pneumo","fiche":"p208","front":"Trouble de la diffusion : quand apparaît l'hypoxémie ?","back":"D'abord à l'**effort** (temps de contact sang-air raccourci).","prio":"P3","sec":"s2"},{"id":"fc-p208-60e636","poly":"pneumo","fiche":"p208","front":"Trouble de la diffusion : citer des exemples.","back":"**PID** (membrane), **emphysème** (versant alvéolaire), **HTAP** (versant vasculaire).","prio":"P3","sec":"s2"},{"id":"fc-p208-50ee1d","poly":"pneumo","fiche":"p208","front":"Vasoconstriction hypoxique de l'effet shunt : quelles conséquences à long terme ?","back":"**Hypertension pulmonaire**, **insuffisance ventriculaire droite**.","prio":"P2","sec":"s2"},{"id":"fc-p208-aa3e38","poly":"pneumo","fiche":"p208","front":"Espace mort anatomique : quel volume chez l'adulte ?","back":"Environ **150 mL** (voies de conduction).","prio":"P3","sec":"s2"},{"id":"fc-p208-87be0c","poly":"pneumo","fiche":"p208","front":"IRC par atteinte de l'échangeur pulmonaire : citer des exemples.","back":"**BPCO**, bronchiolites, **fibrose pulmonaire**.","prio":"P3","sec":"s2"},{"id":"fc-p208-80bb38","poly":"pneumo","fiche":"p208","front":"IRC par atteinte de la pompe ventilatoire : citer des exemples.","back":"Myopathies, **maladies neuromusculaires**, **syndrome obésité-hypoventilation**, **cyphoscoliose**.","prio":"P3","sec":"s2"},{"id":"fc-p208-0cc72b","poly":"pneumo","fiche":"p208","front":"IRC par atteinte de la vascularisation pulmonaire : quel exemple ?","back":"L'**hypertension pulmonaire**.","prio":"P3","sec":"s2"},{"id":"fc-p208-4fbc10","poly":"pneumo","fiche":"p208","front":"IRC sur BPCO : quels signes fonctionnels et quel profil EFR ?","back":"**Dyspnée d'effort**, parfois toux et expectoration ; profil **obstructif**.","prio":"P2","sec":"s3"},{"id":"fc-p208-bfd569","poly":"pneumo","fiche":"p208","front":"IRC sur fibrose pulmonaire : quel signe fonctionnel et quel profil EFR ?","back":"**Toux sèche** ; profil **restrictif**.","prio":"P2","sec":"s3"},{"id":"fc-p208-52ecff","poly":"pneumo","fiche":"p208","front":"IRC sur syndrome obésité-hypoventilation : quel signe fonctionnel évocateur ?","back":"**Sommeil de moins bonne qualité**, parfois dyspnée d'effort ; profil restrictif.","prio":"P2","sec":"s3"},{"id":"fc-p208-942e3a","poly":"pneumo","fiche":"p208","front":"IRC sur maladie neuromusculaire : quels signes évocateurs ?","back":"**Déficit moteur**, **toux inefficace**, **encombrement bronchique** à répétition ; profil restrictif.","prio":"P2","sec":"s3"},{"id":"fc-p208-c6abfb","poly":"pneumo","fiche":"p208","front":"IRC : comment évolue la dyspnée ?","back":"D'abord à l'**effort**, puis pour des efforts de plus en plus modestes, voire au **repos** ; très variable.","prio":"P2","sec":"s3"},{"id":"fc-p208-e278db","poly":"pneumo","fiche":"p208","front":"Dyspnée de l'IRC : quelle échelle utiliser en consultation ?","back":"L'échelle **mMRC**.","prio":"P2","sec":"s3"},{"id":"fc-p208-13b15a","poly":"pneumo","fiche":"p208","front":"Hypoventilation alvéolaire : quels signes cliniques ?","back":"Sommeil non réparateur, **céphalées frontales du matin**, **somnolence diurne**, troubles mnésiques, syndrome anxio-dépressif.","prio":"P1","sec":"s3"},{"id":"fc-p208-275aa7","poly":"pneumo","fiche":"p208","front":"IRC : l'examen clinique permet-il en règle de la révéler ?","back":"**Rarement** : il montre surtout la maladie causale ; diagnostic en règle pendant le **suivi pneumologique**.","prio":"P2","sec":"s3"},{"id":"fc-p208-9814a4","poly":"pneumo","fiche":"p208","front":"Cyanose : à partir de quel taux apparaît-elle ?","back":"**> 5 g/dl d'hémoglobine désoxygénée**.","prio":"P1","sec":"s3"},{"id":"fc-p208-fe0ff8","poly":"pneumo","fiche":"p208","front":"Cyanose dans l'IRC : quelle valeur ?","back":"**Signe de gravité**, mais **inconstant**.","prio":"P1","sec":"s3"},{"id":"fc-p208-b35c9b","poly":"pneumo","fiche":"p208","front":"IRC évoluée : quels signes d'insuffisance cardiaque droite ?","back":"**Turgescence jugulaire**, **reflux hépato-jugulaire**, hépatomégalie, **œdèmes des MI** avec prise de poids.","prio":"P1","sec":"s3"},{"id":"fc-p208-435fbd","poly":"pneumo","fiche":"p208","front":"IRC : dans quelles conditions prélever les gaz du sang diagnostiques ?","back":"À l'**état stable** (loin d'un épisode aigu), en **air ambiant**.","prio":"P1","sec":"s4"},{"id":"fc-p208-b19d7e","poly":"pneumo","fiche":"p208","front":"Gaz du sang : que signifie une acidose respiratoire compensée par des bicarbonates élevés ?","back":"Une **hypercapnie chronique**.","prio":"P1","sec":"s4"},{"id":"fc-p208-dfa2d1","poly":"pneumo","fiche":"p208","front":"IRC : quel est l'examen pivot pour orienter la cause ?","back":"Les **EFR** (obstructif, restrictif, mixte, sans anomalie des volumes).","prio":"P1","sec":"s4"},{"id":"fc-p208-073ad2","poly":"pneumo","fiche":"p208","front":"IRC : quelle imagerie réaliser ?","back":"**Radiographie thoracique** puis le plus souvent **scanner thoracique**.","prio":"P2","sec":"s4"},{"id":"fc-p208-94ba3f","poly":"pneumo","fiche":"p208","front":"IRC : que suggère une polyglobulie à la NFS ?","back":"Une hypoxémie **ancienne**.","prio":"P1","sec":"s4"},{"id":"fc-p208-5f8fec","poly":"pneumo","fiche":"p208","front":"IRC : que peut montrer l'ECG ?","back":"Des signes d'**hypertrophie des cavités droites**.","prio":"P2","sec":"s4"},{"id":"fc-p208-af560f","poly":"pneumo","fiche":"p208","front":"IRC : quel est l'intérêt de l'échocardiographie transthoracique systématique ?","back":"**PAPS** pour dépister une **HTP** ; dépister une **insuffisance cardiaque gauche** (âge, tabac, surtout BPCO).","prio":"P1","sec":"s4"},{"id":"fc-p208-0cf410","poly":"pneumo","fiche":"p208","front":"IRC : quel examen confirme une HTP si besoin ?","back":"Le **cathétérisme cardiaque droit**.","prio":"P2","sec":"s4"},{"id":"fc-p208-247430","poly":"pneumo","fiche":"p208","front":"IRC : à quoi servent les tests d'exercice ?","back":"**Pronostic** et orientation du **traitement** (marche de 6 min, lever de chaise, épreuve d'effort).","prio":"P3","sec":"s4"},{"id":"fc-p208-f89641","poly":"pneumo","fiche":"p208","front":"IRC obstructive : quel critère aux EFR ?","back":"**VEMS/CVF < 70 %**.","prio":"P1","sec":"s4"},{"id":"fc-p208-f02178","poly":"pneumo","fiche":"p208","front":"IRC obstructive : citer des causes.","back":"**BPCO**, **asthme vieilli**, **bronchiolite**.","prio":"P1","sec":"s4"},{"id":"fc-p208-bbb9d1","poly":"pneumo","fiche":"p208","front":"IRC restrictive : quel critère aux EFR ?","back":"**CPT < 80 %** des valeurs théoriques (capacité vitale aussi diminuée).","prio":"P1","sec":"s4"},{"id":"fc-p208-ef8d83","poly":"pneumo","fiche":"p208","front":"IRC restrictive : citer des causes.","back":"**Cyphoscoliose**, **SOH**, **maladies neuromusculaires**, pachypleurite, **pneumopathies interstitielles**.","prio":"P1","sec":"s4"},{"id":"fc-p208-477830","poly":"pneumo","fiche":"p208","front":"IRC mixte : quel critère aux EFR ?","back":"Critères de **TVO** et de **TVR** **à la fois**.","prio":"P1","sec":"s4"},{"id":"fc-p208-027267","poly":"pneumo","fiche":"p208","front":"IRC mixte : citer des causes.","back":"**DDB étendues**, **mucoviscidose**, séquelles de tuberculose, silicose et pneumoconioses.","prio":"P1","sec":"s4"},{"id":"fc-p208-fe7b3a","poly":"pneumo","fiche":"p208","front":"IRC sans anomalie des volumes : quelle anomalie EFR et quelle cause ?","back":"**Anomalie de la diffusion** ; maladie vasculaire pulmonaire chronique (ex. **HTAP**).","prio":"P1","sec":"s4"},{"id":"fc-p208-44a1bd","poly":"pneumo","fiche":"p208","front":"IRC restrictive avec TLCO abaissé : quelle cause évoquer ?","back":"**Pneumopathies interstitielles**.","prio":"P2","sec":"s4"},{"id":"fc-p208-a0f23b","poly":"pneumo","fiche":"p208","front":"IRC restrictive avec TLCO normal : quelles causes évoquer ?","back":"**Syndrome obésité-hypoventilation**, atteinte de la **paroi thoracique** (mécanisme : hypoventilation).","prio":"P2","sec":"s4"},{"id":"fc-p208-4bde42","poly":"pneumo","fiche":"p208","front":"Hypoxémie sans trouble ventilatoire avec TLCO/VA abaissé : quelle cause ?","back":"**Hypertension pulmonaire**.","prio":"P3","sec":"s4"},{"id":"fc-p208-ae882c","poly":"pneumo","fiche":"p208","front":"IRC : sur quels 3 piliers repose l'orientation étiologique ?","back":"**Histoire clinique**, **EFR**, **imagerie thoracique**.","prio":"P2","sec":"s4"},{"id":"fc-p208-e0e355","poly":"pneumo","fiche":"p208","front":"PID : quel paramètre EFR est abaissé par l'atteinte membranaire ?","back":"Le **TLCO**.","prio":"P1","sec":"s4"},{"id":"fc-p208-0b77b1","poly":"pneumo","fiche":"p208","front":"IRC : une SpO₂ ponctuelle a-t-elle une valeur diagnostique ?","back":"**Non** : il faut des **gaz du sang artériels** à l'état stable en air ambiant.","prio":"P1","sec":"s4"},{"id":"fc-p208-70d2e3","poly":"pneumo","fiche":"p208","front":"IRC : dans quels cas la radiographie peut-elle suffire au diagnostic de cause ?","back":"**Grandes déformations du thorax**, **séquelles de tuberculose**.","prio":"P3","sec":"s4"},{"id":"fc-p208-42e279","poly":"pneumo","fiche":"p208","front":"IRC obstructive : quelle en est la cause principale ?","back":"La **BPCO** (TVO aux EFR).","prio":"P2","sec":"s5"},{"id":"fc-p208-0a2946","poly":"pneumo","fiche":"p208","front":"BPCO : d'où vient surtout l'hypoxémie et comment se corrige-t-elle ?","back":"**Déséquilibre VA/Q** ; corrigée par une OLD à **faibles débits**.","prio":"P2","sec":"s5"},{"id":"fc-p208-edcef9","poly":"pneumo","fiche":"p208","front":"BPCO : quelle évolution de la PaCO₂ ?","back":"Longtemps **normale voire basse** (hyperventilation réflexe) ; hypercapnie **tardive**.","prio":"P2","sec":"s5"},{"id":"fc-p208-79d41e","poly":"pneumo","fiche":"p208","front":"Syndrome obésité-hypoventilation : quelle définition ?","back":"**Hypercapnie diurne** (PaCO₂ **≥ 45 mmHg**) avec **IMC ≥ 30 kg/m²**, sans autre cause d'hypercapnie.","prio":"P1","sec":"s5"},{"id":"fc-p208-6a3497","poly":"pneumo","fiche":"p208","front":"Syndrome obésité-hypoventilation : quel type d'IRC ?","back":"**Restrictive** (une des causes les plus fréquentes).","prio":"P1","sec":"s5"},{"id":"fc-p208-9d2ef8","poly":"pneumo","fiche":"p208","front":"SOH : pourquoi seuls certains obèses deviennent hypercapniques ?","back":"**Coût mécanique** respiratoire, **apnées obstructives** longues, **réponse ventilatoire au CO₂ effondrée** (leptine ?).","prio":"P3","sec":"s5"},{"id":"fc-p208-6c8bc9","poly":"pneumo","fiche":"p208","front":"Maladies neuromusculaires : quelle anomalie gazométrique ?","back":"**Hypoxémie + hypercapnie** (baisse de la ventilation alvéolaire).","prio":"P1","sec":"s5"},{"id":"fc-p208-b90a40","poly":"pneumo","fiche":"p208","front":"Maladies neuromusculaires causes d'IRC : citer un exemple par niveau.","back":"Commande : **AVC** ; moelle : **tétraplégie** ; corne antérieure : **SLA** ; muscle : **Duchenne**, **Steinert**.","prio":"P2","sec":"s5"},{"id":"fc-p208-f10cd5","poly":"pneumo","fiche":"p208","front":"Cyphoscoliose idiopathique : pourquoi peut-elle donner une IRC ?","back":"La paroi thoracique impose une **charge** qui altère la **pompe ventilatoire**.","prio":"P2","sec":"s5"},{"id":"fc-p208-b31933","poly":"pneumo","fiche":"p208","front":"Cyphoscoliose : quels facteurs de risque d'IRC ?","back":"Déformation apparue **avant 5 ans**, longue, haut située, très angulée.","prio":"P3","sec":"s5"},{"id":"fc-p208-44194e","poly":"pneumo","fiche":"p208","front":"Cyphoscoliose : à quel âge survient en général l'IRC ?","back":"Vers **40-50 ans**.","prio":"P3","sec":"s5"},{"id":"fc-p208-ae18bd","poly":"pneumo","fiche":"p208","front":"Atteintes pleurales causes d'IRC : quel mécanisme ?","back":"**Pachypleurite** (séquelles d'hémothorax ou de pleurésie infectieuse) qui gêne l'expansion pulmonaire.","prio":"P3","sec":"s5"},{"id":"fc-p208-60bad7","poly":"pneumo","fiche":"p208","front":"PID fibrosantes causes d'IRC : quelles origines ?","back":"Sans cause connue (**FPI**) ou avec cause (exposition professionnelle, médicament, maladie de système).","prio":"P2","sec":"s5"},{"id":"fc-p208-7514ef","poly":"pneumo","fiche":"p208","front":"PID : que signifie une hypoventilation ?","back":"Rare : atteinte **terminale** ou autre atteinte associée (obésité, atrophie musculaire).","prio":"P3","sec":"s5"},{"id":"fc-p208-49eff5","poly":"pneumo","fiche":"p208","front":"Atteinte de la pompe ventilatoire : comment chercher la cause ?","back":"Systématiquement à **chaque étage** : tronc cérébral, moelle, nerf phrénique, muscle, VAS, parenchyme, paroi.","prio":"P3","sec":"s5"},{"id":"fc-p208-ebf86d","poly":"pneumo","fiche":"p208","front":"Polyglobulie de l'IRC : quel mécanisme ?","back":"**Érythropoïétine rénale** en réponse à l'hypoxémie chronique.","prio":"P1","sec":"s6"},{"id":"fc-p208-c7ea4c","poly":"pneumo","fiche":"p208","front":"Polyglobulie de l'IRC : quel risque ?","back":"**Hyperviscosité** et **thromboses** artérielles ou veineuses.","prio":"P1","sec":"s6"},{"id":"fc-p208-518038","poly":"pneumo","fiche":"p208","front":"Polyglobulie de l'IRC : est-elle fréquente aujourd'hui ?","back":"**Rare** (diagnostic plus précoce) ; adaptative et inconstante.","prio":"P2","sec":"s6"},{"id":"fc-p208-1ec232","poly":"pneumo","fiche":"p208","front":"IRC : quelle est la cause des œdèmes déclives ?","back":"**Rétention hydro-sodée** (régulation du facteur natriurétique ou HTP secondaire).","prio":"P2","sec":"s6"},{"id":"fc-p208-73b61d","poly":"pneumo","fiche":"p208","front":"HTP de l'IRC : quel mécanisme ?","back":"**Vasoconstriction pulmonaire hypoxique** → **remodelage vasculaire**.","prio":"P1","sec":"s6"},{"id":"fc-p208-cc2cae","poly":"pneumo","fiche":"p208","front":"Hypertension pulmonaire : quelle définition hémodynamique ?","back":"**PAPm > 20 mmHg** et résistances **> 3 UW** au **cathétérisme droit**.","prio":"P1","sec":"s6"},{"id":"fc-p208-ac4ac8","poly":"pneumo","fiche":"p208","front":"HTP secondaire à une IRC : à quel groupe appartient-elle ?","back":"**Groupe 3**.","prio":"P1","sec":"s6"},{"id":"fc-p208-4ed35a","poly":"pneumo","fiche":"p208","front":"HTP : quel seuil de PAPS à l'échographie la fait suspecter ?","back":"**PAPS > 35 mmHg**.","prio":"P1","sec":"s6"},{"id":"fc-p208-49df30","poly":"pneumo","fiche":"p208","front":"IRC documentée avec HTP suspectée à l'écho : faut-il un cathétérisme droit ?","back":"**Rarement indiqué**.","prio":"P2","sec":"s6"},{"id":"fc-p208-b9b579","poly":"pneumo","fiche":"p208","front":"HTP confirmée à l'état stable dans l'IRC : quelle valeur ?","back":"**Pronostique péjorative**.","prio":"P1","sec":"s6"},{"id":"fc-p208-b54621","poly":"pneumo","fiche":"p208","front":"IRC : quand se manifeste surtout la dysfonction ventriculaire droite ?","back":"Pendant les épisodes d'**insuffisance respiratoire aiguë**.","prio":"P2","sec":"s6"},{"id":"fc-p208-04a85b","poly":"pneumo","fiche":"p208","front":"Cœur pulmonaire chronique : quels 3 facteurs l'expliquent ?","back":"**Résistances vasculaires pulmonaires** augmentées, **hyperviscosité** sanguine, **rétention hydro-sodée**.","prio":"P3","sec":"s6"},{"id":"fc-p208-926633","poly":"pneumo","fiche":"p208","front":"IRC : quel est le principal risque évolutif ?","back":"La **décompensation** = **insuffisance respiratoire aiguë**, qui engage le pronostic vital.","prio":"P1","sec":"s7"},{"id":"fc-p208-590a06","poly":"pneumo","fiche":"p208","front":"IRC : qu'est-ce qui diminue la survenue des décompensations ?","back":"Traitement de la **maladie causale** + **assistance respiratoire au long cours**.","prio":"P2","sec":"s7"},{"id":"fc-p208-cdc404","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quel est le traitement clé ?","back":"L'**oxygène** (hypoxémie aggravée quelle que soit la cause).","prio":"P1","sec":"s7"},{"id":"fc-p208-0e16de","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quels facteurs déclenchants rechercher en premier ?","back":"**Infection respiratoire basse**, **dysfonction cardiaque gauche**/troubles du rythme, **embolie pulmonaire**.","prio":"P1","sec":"s7"},{"id":"fc-p208-a7e0ff","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quels facteurs déclenchants rechercher ensuite ?","back":"**Benzodiazépines**/myorelaxants, **opiacés**, chirurgie sus-mésocolique, traumatisme ou chirurgie thoracique, tassement vertébral, **pneumothorax**.","prio":"P1","sec":"s7"},{"id":"fc-p208-cc3f2b","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quels types de signes cliniques de gravité ?","back":"**Signes de lutte** (travail respiratoire accru) et **signes de faillite** (défaillance neuromusculaire).","prio":"P1","sec":"s7"},{"id":"fc-p208-245463","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quels critères de gravité aux gaz du sang ?","back":"**pH < 7,35**, **PaO₂ < 60 mmHg**, **PaCO₂ > 45 mmHg**, toute hausse des **lactates**.","prio":"P1","sec":"s7"},{"id":"fc-p208-624470","poly":"pneumo","fiche":"p208","front":"Hypercapnie aggravée en heures ou jours avec acidose décompensée : quelle prise en charge ?","back":"**Ventilation mécanique** : non invasive au masque ou invasive par intubation.","prio":"P1","sec":"s7"},{"id":"fc-p208-160d36","poly":"pneumo","fiche":"p208","front":"Gaz du sang prélevés pendant une décompensation : permettent-ils de poser une IRC ?","back":"**Non** : il faut l'**état stable**, en air ambiant, et une 2e mesure ≥ 2 semaines après.","prio":"P1","sec":"s8"},{"id":"fc-p208-231132","poly":"pneumo","fiche":"p208","front":"PaO₂ < 60 mmHg : quel sens à l'état stable et en décompensation ?","back":"État stable : **IRC grave** ; décompensation : **critère de gravité aiguë**.","prio":"P3","sec":"s8"},{"id":"fc-p208-142ff6","poly":"pneumo","fiche":"p208","front":"Œdèmes des MI chez un insuffisant respiratoire chronique : quelles causes évoquer ?","back":"**Rétention hydro-sodée** de l'IRC et **insuffisance cardiaque droite** (HTP).","prio":"P2","sec":"s8"},{"id":"fc-p208-419e3e","poly":"pneumo","fiche":"p208","front":"IRC restrictive : dans quelles causes trouve-t-on une hypercapnie ?","back":"**SOH** (par définition) et **maladies neuromusculaires** (hypoventilation).","prio":"P2","sec":"s8"},{"id":"fc-p208-9f83c6","poly":"pneumo","fiche":"p208","front":"Décompensation d'IRC : quelle escalade thérapeutique ?","back":"Hausse des débits d'**O₂** (jusqu'à l'**oxygénothérapie à haut débit**), puis **ventilation mécanique** en soins intensifs.","prio":"P1","sec":"s9"},{"id":"fc-p208-0d6fef","poly":"pneumo","fiche":"p208","front":"IRC : quel est le principe général du traitement ?","back":"Surtout **symptomatique** : **assistance respiratoire à domicile** (O₂ et/ou ventilation) + traitement de la maladie causale.","prio":"P2","sec":"s10"},{"id":"fc-p208-ada4a0","poly":"pneumo","fiche":"p208","front":"IRC : à quels patients vise prioritairement l'oxygène, et la ventilation ?","back":"O₂ : IRC **normo/hypocapniques** par atteinte de l'**échangeur** ; ventilation : IRC **hypercapniques** par **hypoventilation**.","prio":"P2","sec":"s10"},{"id":"fc-p208-458ca2","poly":"pneumo","fiche":"p208","front":"OLD : quels bénéfices ?","back":"Corrige l'**hypoxémie**, prévient les complications (surtout **HTP**), diminue la **mortalité dans la BPCO**.","prio":"P2","sec":"s10"},{"id":"fc-p208-1dbcbd","poly":"pneumo","fiche":"p208","front":"IRC obstructive : quel seuil de PaO₂ pour l'OLD ?","back":"**PaO₂ < 55 mmHg** (7,3 kPa).","prio":"P2","sec":"s10"},{"id":"fc-p208-881ad8","poly":"pneumo","fiche":"p208","front":"IRC obstructive avec PaO₂ 55-59 mmHg : quand prescrire une OLD ?","back":"Si **hypoxie tissulaire** : polyglobulie (**Ht > 55 %**), **insuffisance ventriculaire droite**, désaturations nocturnes non apnéiques (**SpO₂ moy ≤ 88 %**).","prio":"P2","sec":"s10"},{"id":"fc-p208-18a482","poly":"pneumo","fiche":"p208","front":"IRC restrictive : quel seuil de PaO₂ pour l'OLD ?","back":"**PaO₂ < 60 mmHg**.","prio":"P2","sec":"s10"},{"id":"fc-p208-512f03","poly":"pneumo","fiche":"p208","front":"OLD : quelle durée quotidienne minimale ?","back":"**Au moins 15 h/j**, idéalement **24 h/24**, nuit et effort compris.","prio":"P2","sec":"s10"},{"id":"fc-p208-a6bd5a","poly":"pneumo","fiche":"p208","front":"OLD : quelle cible de débit ?","back":"**PaO₂ > 60 mmHg** ou **SpO₂ > 90 %**, au repos et à l'effort.","prio":"P2","sec":"s10"},{"id":"fc-p208-d48c31","poly":"pneumo","fiche":"p208","front":"OLD : quelle interface habituelle ?","back":"**Lunettes nasales** (le masque permet des apports plus élevés).","prio":"P3","sec":"s10"},{"id":"fc-p208-8c32ef","poly":"pneumo","fiche":"p208","front":"OLD et tabagisme actif : quel risque ?","back":"**Brûlures graves du visage**, **incendie** : peut remettre en cause l'OLD.","prio":"P2","sec":"s10"},{"id":"fc-p208-160dbb","poly":"pneumo","fiche":"p208","front":"OLD : citer les 3 sources d'oxygène.","back":"**Concentrateur** (électrique), **oxygène liquide**, **bouteille** d'oxygène gazeux (appoint).","prio":"P3","sec":"s10"},{"id":"fc-p208-0cc9e2","poly":"pneumo","fiche":"p208","front":"OLD : sur quels critères choisir la source d'oxygène ?","back":"**Mobilité** du patient, **débit** nécessaire, praticité (efficacité équivalente).","prio":"P3","sec":"s10"},{"id":"fc-p208-b3f7eb","poly":"pneumo","fiche":"p208","front":"Concentrateur d'oxygène : quel principe ?","back":"**Sépare l'oxygène de l'azote** de l'air ambiant (fixe, transportable ou portable).","prio":"P3","sec":"s10"},{"id":"fc-p208-68c322","poly":"pneumo","fiche":"p208","front":"Oxygène liquide : à quelle température est-il stocké ?","back":"**-183 °C** (1 litre de liquide = 860 litres de gaz).","prio":"P3","sec":"s10"},{"id":"fc-p208-caef4d","poly":"pneumo","fiche":"p208","front":"Bouteille d'oxygène gazeux : quelle autonomie ?","back":"Environ **2 heures à 3 L/min** (appoint seulement).","prio":"P3","sec":"s10"},{"id":"fc-p208-469940","poly":"pneumo","fiche":"p208","front":"IRC hypercapnique : l'hypercapnie contre-indique-t-elle l'OLD ?","back":"**Non**, même sévère.","prio":"P2","sec":"s11"},{"id":"fc-p208-6da863","poly":"pneumo","fiche":"p208","front":"OLD chez un hypercapnique : quelle vérification faire ?","back":"**Gaz du sang sous O₂** : la PaCO₂ ne doit pas augmenter de façon importante.","prio":"P2","sec":"s11"},{"id":"fc-p208-53f63a","poly":"pneumo","fiche":"p208","front":"PaCO₂ qui monte nettement sous OLD : quelle conduite ?","back":"Ajouter une **ventilation mécanique à domicile**.","prio":"P2","sec":"s11"},{"id":"fc-p208-7c310f","poly":"pneumo","fiche":"p208","front":"Ventilation mécanique à domicile : quel principe ?","back":"Pression positive : augmente le **volume courant** et la **ventilation alvéolaire**, soulage les **muscles inspiratoires**.","prio":"P3","sec":"s12"},{"id":"fc-p208-264fc0","poly":"pneumo","fiche":"p208","front":"Ventilation mécanique à domicile : quels objectifs ?","back":"Corriger **gaz du sang** et symptômes d'hypoventilation, améliorer **survie** et **qualité de vie**.","prio":"P2","sec":"s12"},{"id":"fc-p208-b6995b","poly":"pneumo","fiche":"p208","front":"IRC restrictive : quand débuter la ventilation à domicile ?","back":"**Dès les premiers signes d'hypoventilation** alvéolaire, diurne et/ou nocturne.","prio":"P2","sec":"s12"},{"id":"fc-p208-b027fd","poly":"pneumo","fiche":"p208","front":"BPCO : quand proposer une ventilation à domicile ?","back":"Formes **les plus sévères**, en particulier en **échec de l'OLD**.","prio":"P2","sec":"s12"},{"id":"fc-p208-6b0147","poly":"pneumo","fiche":"p208","front":"Ventilation mécanique à domicile : quelle interface et quel horaire ?","back":"**Masque nasal ou naso-buccal**, la **nuit** (parfois plus le jour chez les neuromusculaires) ; trachéotomie exceptionnelle.","prio":"P3","sec":"s12"},{"id":"fc-p208-1eb77f","poly":"pneumo","fiche":"p208","front":"Ventilation à domicile vs PPC : quelle différence d'indication ?","back":"Ventilation : IRC par **hypoventilation** ; PPC : **syndrome d'apnées du sommeil**.","prio":"P2","sec":"s12"},{"id":"fc-p208-af9954","poly":"pneumo","fiche":"p208","front":"Maladie neuromusculaire avec toux inefficace : quelle kinésithérapie ?","back":"**Recrutement pulmonaire**, **aide instrumentale à la toux**, désencombrement dès l'encombrement aigu.","prio":"P3","sec":"s12"},{"id":"fc-p208-4a53eb","poly":"pneumo","fiche":"p208","front":"IRC : l'arrêt du tabac concerne-t-il seulement la BPCO ?","back":"**Non** : **impératif quelle que soit la cause** de l'IRC.","prio":"P2","sec":"s13"},{"id":"fc-p208-23e10b","poly":"pneumo","fiche":"p208","front":"IRC : quels vaccins recommander ?","back":"**Grippe**, **SARS-CoV-2**, **pneumocoque** (sauf contre-indication).","prio":"P2","sec":"s13"},{"id":"fc-p208-494e3d","poly":"pneumo","fiche":"p208","front":"BPCO : quelle activité physique améliore la survie ?","back":"Marche **≥ 30 min/jour** ou **≥ 2 h/semaine**.","prio":"P2","sec":"s13"},{"id":"fc-p208-1a7ed7","poly":"pneumo","fiche":"p208","front":"Réadaptation respiratoire : quels sont ses 2 piliers ?","back":"**Réentraînement à l'exercice** et **éducation thérapeutique**.","prio":"P2","sec":"s13"},{"id":"fc-p208-cb4c3e","poly":"pneumo","fiche":"p208","front":"Réadaptation respiratoire : à quel stade la proposer ?","back":"À **tous les stades**, sauf CI cardiologique, vasculaire ou motrice.","prio":"P2","sec":"s13"},{"id":"fc-p208-8e3f7c","poly":"pneumo","fiche":"p208","front":"Réadaptation respiratoire : quels buts ?","back":"Meilleure **capacité d'effort**, **changements de comportement** de santé maintenus au long cours.","prio":"P3","sec":"s13"},{"id":"fc-p208-0c8590","poly":"pneumo","fiche":"p208","front":"IRC : le drainage bronchique au long cours est-il souvent nécessaire ?","back":"**Rarement**, sauf par exemple **DDB**.","prio":"P3","sec":"s13"},{"id":"fc-p208-4864aa","poly":"pneumo","fiche":"p208","front":"Transplantation pulmonaire dans l'IRC : pour qui ?","back":"Très peu de patients **très sélectionnés** (un peu plus de **400/an** en France).","prio":"P3","sec":"s13"},{"id":"fc-p208-7b16b8","poly":"pneumo","fiche":"p208","front":"IRC : après chaque épisode aigu, quelle conduite ?","back":"**Réévaluer** le patient une fois revenu à l'**état stable** (gaz du sang à distance de l'épisode aigu).","prio":"P1","sec":"s14"},{"id":"fc-p209-046ee4","poly":"pneumo","fiche":"p209","front":"BPCO : comment la caractériser en une phrase ?","back":"Maladie respiratoire chronique **fréquente**, **évitable** et **traitable**.","prio":"P2","sec":"s1"},{"id":"fc-p209-73d329","poly":"pneumo","fiche":"p209","front":"BPCO : quelles sont les 2 conditions du diagnostic ?","back":"**Symptômes respiratoires chroniques** + **TVO non complètement réversible** (obstruction permanente).","prio":"P1","sec":"s1"},{"id":"fc-p209-76c041","poly":"pneumo","fiche":"p209","front":"BPCO : quels symptômes chroniques peuvent compter ?","back":"Au moins un parmi : **toux**, **expectoration**, **dyspnée d'effort**, infections respiratoires basses **répétées ou traînantes**.","prio":"P2","sec":"s1"},{"id":"fc-p209-d47fae","poly":"pneumo","fiche":"p209","front":"BPCO : quel examen est indispensable au diagnostic, et dans quelles conditions ?","back":"**Spirométrie** à l'**état stable**, VEMS et CVF **avant puis après bronchodilatateur**.","prio":"P1","sec":"s1"},{"id":"fc-p209-8952f5","poly":"pneumo","fiche":"p209","front":"TVO : quel est le critère spirométrique ?","back":"Rapport **VEMS/CVF < 0,7**.","prio":"P1","sec":"s1"},{"id":"fc-p209-eaee3b","poly":"pneumo","fiche":"p209","front":"VEMS/CVF < 70 % : s'agit-il d'un pourcentage de la valeur théorique ?","back":"**Non** : c'est le rapport **VEMS mesuré / CVF mesurée** du patient.","prio":"P1","sec":"s1"},{"id":"fc-p209-fdf46b","poly":"pneumo","fiche":"p209","front":"BPCO : que devient le rapport VEMS/CVF après bronchodilatateur ?","back":"Il reste **< 0,7** (TVO **persistant**), quelle que soit la variation du VEMS.","prio":"P1","sec":"s1"},{"id":"fc-p209-22d196","poly":"pneumo","fiche":"p209","front":"Réversibilité significative du TVO : quel critère ?","back":"Gain de VEMS **> 200 mL ET > 12 %** de la valeur de départ.","prio":"P1","sec":"s1"},{"id":"fc-p209-5bb401","poly":"pneumo","fiche":"p209","front":"Réversibilité significative : élimine-t-elle une BPCO ?","back":"**Non** : elle évoque un asthme mais peut se voir dans une BPCO.","prio":"P1","sec":"s1"},{"id":"fc-p209-484b87","poly":"pneumo","fiche":"p209","front":"Réversibilité complète du TVO : quelle définition et quelle conséquence ?","back":"Rapport VEMS/CVF **normalisé (> 0,7)** : **écarte la BPCO**, oriente vers un asthme.","prio":"P1","sec":"s1"},{"id":"fc-p209-6af8f5","poly":"pneumo","fiche":"p209","front":"Quel gain de VEMS après bronchodilatateur doit faire évoquer un asthme ?","back":"Plus de **400 mL** (réversibilité très importante).","prio":"P2","sec":"s1"},{"id":"fc-p209-9111e8","poly":"pneumo","fiche":"p209","front":"Réversibilité : après quel autre traitement que le bronchodilatateur peut-on la tester ?","back":"Après **2 semaines de corticoïde systémique**.","prio":"P3","sec":"s1"},{"id":"fc-p209-2eb6d4","poly":"pneumo","fiche":"p209","front":"Bronchite chronique : quelle définition ?","back":"Toux **productive** quasi quotidienne **≥ 3 mois par an**, **≥ 2 années** consécutives (définition **clinique**).","prio":"P1","sec":"s1"},{"id":"fc-p209-2d86fe","poly":"pneumo","fiche":"p209","front":"Bronchite chronique sans TVO : est-ce une BPCO ?","back":"**Non**.","prio":"P1","sec":"s1"},{"id":"fc-p209-015f06","poly":"pneumo","fiche":"p209","front":"Bronchite chronique : quelle part des fumeurs touche-t-elle ?","back":"Environ **la moitié**.","prio":"P3","sec":"s1"},{"id":"fc-p209-23082c","poly":"pneumo","fiche":"p209","front":"Emphysème : quelle définition ?","back":"Agrandissement **anormal et définitif** des espaces aériens au-delà des **bronchioles terminales**, destruction alvéolaire, **sans fibrose**.","prio":"P1","sec":"s1"},{"id":"fc-p209-b65e4a","poly":"pneumo","fiche":"p209","front":"Emphysème : quel type de définition ?","back":"**Anatomopathologique**.","prio":"P2","sec":"s1"},{"id":"fc-p209-7756f4","poly":"pneumo","fiche":"p209","front":"Emphysème centro-lobulaire : quelle atteinte et quelle conséquence ?","back":"Destruction centrée sur la **bronchiole**, capillaires épargnés → hypoxémie par **inégalité ventilation/perfusion**.","prio":"P2","sec":"s1"},{"id":"fc-p209-914afa","poly":"pneumo","fiche":"p209","front":"Emphysème pan-lobulaire : quelle atteinte et quelle conséquence ?","back":"Bronchioles **et capillaires** détruits sur tout le lobule → **hypoxémie de repos tardive**.","prio":"P2","sec":"s1"},{"id":"fc-p209-41c876","poly":"pneumo","fiche":"p209","front":"Emphysème paraseptal : où siège-t-il ?","back":"**Sous la plèvre** (acinaire distal).","prio":"P3","sec":"s1"},{"id":"fc-p209-376f94","poly":"pneumo","fiche":"p209","front":"Emphysème : quelles anomalies aux EFR peuvent le faire suspecter ?","back":"**Distension** et **baisse de la diffusion** alvéolo-capillaire.","prio":"P2","sec":"s1"},{"id":"fc-p209-2a4d7b","poly":"pneumo","fiche":"p209","front":"Emphysème : comment l'imagerie le confirme-t-elle ?","back":"**Suspecté** à la radiographie, **affirmé au scanner** (zones hypodenses).","prio":"P3","sec":"s1"},{"id":"fc-p209-9e21d3","poly":"pneumo","fiche":"p209","front":"Emphysème sans TVO : est-ce une BPCO ?","back":"**Non**.","prio":"P3","sec":"s1"},{"id":"fc-p209-00b2fe","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quelle définition ?","back":"Aggravation de la **dyspnée** et/ou de la **toux et des expectorations** installée en **< 14 jours** (± tachypnée, tachycardie).","prio":"P1","sec":"s1"},{"id":"fc-p209-5a7344","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : à quoi est-elle souvent associée ?","back":"Inflammation locale et générale accrue (**infection**, **pollution**, autre agression des voies aériennes).","prio":"P3","sec":"s1"},{"id":"fc-p209-d635f1","poly":"pneumo","fiche":"p209","front":"BPCO : quel est le principal facteur de risque ?","back":"Le **tabac** (> 80 % des patients BPCO en France sont fumeurs).","prio":"P1","sec":"s2"},{"id":"fc-p209-1181d4","poly":"pneumo","fiche":"p209","front":"Expositions professionnelles : peuvent-elles être en cause dans une BPCO ?","back":"**Oui** : facteur de risque de BPCO en dehors du tabac.","prio":"P2","sec":"s2"},{"id":"fc-p209-7fd255","poly":"pneumo","fiche":"p209","front":"Aérocontaminants professionnels : dans quelle part des BPCO sont-ils en cause ?","back":"**Au moins 15 %**.","prio":"P3","sec":"s2"},{"id":"fc-p209-116ded","poly":"pneumo","fiche":"p209","front":"BPCO : quelle pollution domestique est en cause dans les pays émergents ?","back":"Fumées de **combustion de biomasse** (chauffage, cuisine) en pièces mal ventilées.","prio":"P3","sec":"s2"},{"id":"fc-p209-7f8806","poly":"pneumo","fiche":"p209","front":"Cannabis : quel lien avec la BPCO ?","back":"Associé au tabac : facteur de risque de **BPCO** et d'**emphysème**.","prio":"P3","sec":"s2"},{"id":"fc-p209-d59072","poly":"pneumo","fiche":"p209","front":"Pollution particulaire de l'air : quel rôle dans la BPCO ?","back":"Participe au **déclenchement des exacerbations**.","prio":"P3","sec":"s2"},{"id":"fc-p209-153d60","poly":"pneumo","fiche":"p209","front":"BPCO : quel facteur génétique ?","back":"Le **déficit en alpha-1 antitrypsine** (emphysème **pan-lobulaire**, aggravé par le tabac).","prio":"P3","sec":"s2"},{"id":"fc-p209-ca58ba","poly":"pneumo","fiche":"p209","front":"BPCO : quels événements du début de la vie y prédisposent ?","back":"**Prématurité**, petit poids de naissance, infections respiratoires précoces, **tabagisme passif**, tabagisme actif très précoce, asthme non contrôlé.","prio":"P3","sec":"s2"},{"id":"fc-p209-9bb373","poly":"pneumo","fiche":"p209","front":"BPCO : quelles infections sont des facteurs de risque ?","back":"Infections respiratoires basses de la **petite enfance**, **tuberculose**, **VIH**.","prio":"P3","sec":"s2"},{"id":"fc-p209-c36c41","poly":"pneumo","fiche":"p209","front":"BPCO : quelles comorbidités rechercher chez tout patient ?","back":"**Cardio-vasculaires**, **cancer bronchique**, **dénutrition/obésité**, **déconditionnement musculaire**, **anémie**, **anxiété/dépression**, **ostéoporose**.","prio":"P1","sec":"s2"},{"id":"fc-p209-bae833","poly":"pneumo","fiche":"p209","front":"Comorbidités de la BPCO : impliquent-elles un lien de cause ?","back":"**Non**, elles coexistent sans préjuger d'un lien causal ; elles **participent au pronostic**.","prio":"P2","sec":"s2"},{"id":"fc-p209-7e89dd","poly":"pneumo","fiche":"p209","front":"Fumeur avec atteinte cardio-vasculaire, dénutrition ou fonte musculaire : que rechercher ?","back":"Une **BPCO**.","prio":"P2","sec":"s2"},{"id":"fc-p209-e30ab0","poly":"pneumo","fiche":"p209","front":"BPCO en France : quelle prévalence ?","back":"**5 à 10 %** des plus de **45 ans** (2,5 à 3,5 millions de personnes).","prio":"P3","sec":"s2"},{"id":"fc-p209-6d8cfd","poly":"pneumo","fiche":"p209","front":"BPCO en France : combien de décès en 2022 ?","back":"Plus de **18 000**.","prio":"P3","sec":"s2"},{"id":"fc-p209-3f993b","poly":"pneumo","fiche":"p209","front":"BPCO dans le monde : quel rang de mortalité ?","back":"**4e cause** de mortalité ; attendue **3e** d'ici **2030**.","prio":"P3","sec":"s2"},{"id":"fc-p209-6805a0","poly":"pneumo","fiche":"p209","front":"Cigarette électronique : quel rôle dans la BPCO ?","back":"Rôle de facteur de risque **suspecté**, encore à l'étude.","prio":"P3","sec":"s2"},{"id":"fc-p209-734534","poly":"pneumo","fiche":"p209","front":"BPCO : sur quoi s'évoque et se confirme le diagnostic ?","back":"S'**évoque** sur la clinique ; se **confirme** par la **spirométrie** avec test de réversibilité.","prio":"P2","sec":"s3"},{"id":"fc-p209-d89a95","poly":"pneumo","fiche":"p209","front":"BPCO : quel est le symptôme principal et ses caractéristiques ?","back":"La **dyspnée d'effort**, **tardive** et **souvent sous-estimée**.","prio":"P1","sec":"s3"},{"id":"fc-p209-3d605c","poly":"pneumo","fiche":"p209","front":"Dyspnée d'effort : chez qui la rechercher systématiquement ?","back":"Chez **tout fumeur**.","prio":"P1","sec":"s3"},{"id":"fc-p209-1cfc93","poly":"pneumo","fiche":"p209","front":"Dyspnée de la BPCO : avec quelle échelle la mesurer ?","back":"L'échelle **mMRC**.","prio":"P1","sec":"s3"},{"id":"fc-p209-2574bd","poly":"pneumo","fiche":"p209","front":"BPCO débutante : que montre l'examen physique ?","back":"Souvent **rien** pendant des années, ou des **ronchi**.","prio":"P2","sec":"s3"},{"id":"fc-p209-922337","poly":"pneumo","fiche":"p209","front":"BPCO avec TVO installé : quels signes à l'auscultation ?","back":"**Murmure vésiculaire diminué**, **ronchi** et/ou **sibilants** ; signes de **distension**.","prio":"P2","sec":"s3"},{"id":"fc-p209-95136b","poly":"pneumo","fiche":"p209","front":"BPCO au stade d'insuffisance respiratoire chronique : quels signes ?","back":"Signes d'**hypercapnie**, d'**hypertension pulmonaire**, de **dysfonction cardiaque droite**.","prio":"P2","sec":"s3"},{"id":"fc-p209-e11c9c","poly":"pneumo","fiche":"p209","front":"Spirométrie dans la BPCO : quels apports ?","back":"**Certitude diagnostique**, distinction avec l'asthme, **sévérité**, guide du traitement et du **pronostic**.","prio":"P2","sec":"s4"},{"id":"fc-p209-49178f","poly":"pneumo","fiche":"p209","front":"Test de réversibilité : quand refaire la spirométrie après le bronchodilatateur ?","back":"**10 à 15 minutes** après un BD d'action rapide.","prio":"P2","sec":"s4"},{"id":"fc-p209-a12ec7","poly":"pneumo","fiche":"p209","front":"BPCO : sur quelle valeur se lit la sévérité du TVO ?","back":"Le **VEMS post-BD** (en % de la valeur prédite).","prio":"P1","sec":"s4"},{"id":"fc-p209-454801","poly":"pneumo","fiche":"p209","front":"Doute persistant BPCO/asthme : quel test de réversibilité proposer ?","back":"Après **corticothérapie systémique** : prednisone **0,5 mg/kg/j pendant 15 jours**.","prio":"P2","sec":"s4"},{"id":"fc-p209-0710db","poly":"pneumo","fiche":"p209","front":"Pléthysmographie : quel critère de distension ?","back":"**CPT > 120 %** avec **VR/CPT > 30 %**.","prio":"P3","sec":"s4"},{"id":"fc-p209-df05a4","poly":"pneumo","fiche":"p209","front":"Transfert du CO (DLCO) : que reflète-t-il et quel seuil pathologique ?","back":"La **surface d'échange** (destruction alvéolo-capillaire) ; pathologique si **< 70 %** de la valeur prédite.","prio":"P2","sec":"s4"},{"id":"fc-p209-1e946b","poly":"pneumo","fiche":"p209","front":"BPCO : quel examen pour rechercher une insuffisance respiratoire chronique ?","back":"Les **gaz du sang artériel**.","prio":"P2","sec":"s4"},{"id":"fc-p209-8f49e2","poly":"pneumo","fiche":"p209","front":"Épreuve d'exercice maximale : quelles indications dans la BPCO ?","back":"Dyspnée sévère avec **EFR peu perturbées** ; **avant réadaptation** (contre-indication, réglage du réentraînement).","prio":"P3","sec":"s4"},{"id":"fc-p209-92cc33","poly":"pneumo","fiche":"p209","front":"Test de marche de 6 minutes : à quoi sert-il dans la BPCO ?","back":"Au **suivi** (épreuve sous-maximale).","prio":"P2","sec":"s4"},{"id":"fc-p209-0520f6","poly":"pneumo","fiche":"p209","front":"Test de marche de 6 minutes : quel repère de normalité ?","back":"Environ **500 m** (marche rapide à 5 km/h), selon âge, sexe et taille.","prio":"P3","sec":"s4"},{"id":"fc-p209-e86e9a","poly":"pneumo","fiche":"p209","front":"Sévérité de la BPCO : quelles 2 classifications complémentaires ?","back":"**GOLD 1-2-3-4** (fonctionnelle, VEMS post-BD) et **GOLD A-B-E** (clinique : dyspnée mMRC + exacerbations).","prio":"P2","sec":"s5"},{"id":"fc-p209-51b9c8","poly":"pneumo","fiche":"p209","front":"Sévérité et pronostic de la BPCO : sur quels éléments ?","back":"**EFR**, **symptômes** (dyspnée, exacerbations), **comorbidités**, scores composites.","prio":"P3","sec":"s5"},{"id":"fc-p209-f6169a","poly":"pneumo","fiche":"p209","front":"GOLD 1 : quel VEMS post-BD ?","back":"**≥ 80 %** (obstruction légère).","prio":"P1","sec":"s5"},{"id":"fc-p209-4d7d41","poly":"pneumo","fiche":"p209","front":"GOLD 2 : quel VEMS post-BD ?","back":"**50 à 79 %** (obstruction modérée).","prio":"P1","sec":"s5"},{"id":"fc-p209-64b59d","poly":"pneumo","fiche":"p209","front":"GOLD 3 : quel VEMS post-BD ?","back":"**30 à 49 %** (obstruction sévère).","prio":"P1","sec":"s5"},{"id":"fc-p209-0fded9","poly":"pneumo","fiche":"p209","front":"GOLD 4 : quel VEMS post-BD ?","back":"**< 30 %** (obstruction très sévère).","prio":"P1","sec":"s5"},{"id":"fc-p209-f0545d","poly":"pneumo","fiche":"p209","front":"Échelle mMRC : à quoi correspond le stade 0 ?","back":"Essoufflé seulement lors d'un **effort important**.","prio":"P2","sec":"s5"},{"id":"fc-p209-25ba96","poly":"pneumo","fiche":"p209","front":"Échelle mMRC : à quoi correspond le stade 1 ?","back":"Essoufflé en **pressant le pas** à plat ou en montant une **pente douce**.","prio":"P2","sec":"s5"},{"id":"fc-p209-fad959","poly":"pneumo","fiche":"p209","front":"Échelle mMRC : à quoi correspond le stade 2 ?","back":"Marche à plat **moins vite que les gens de son âge**, ou doit s'arrêter en marchant à son propre rythme.","prio":"P2","sec":"s5"},{"id":"fc-p209-041dcc","poly":"pneumo","fiche":"p209","front":"Échelle mMRC : à quoi correspond le stade 3 ?","back":"S'arrête pour souffler après **90 mètres** ou quelques minutes à plat.","prio":"P2","sec":"s5"},{"id":"fc-p209-c4df44","poly":"pneumo","fiche":"p209","front":"Échelle mMRC : à quoi correspond le stade 4 ?","back":"Trop essoufflé pour **sortir de chez lui** ou dès qu'il **s'habille**.","prio":"P2","sec":"s5"},{"id":"fc-p209-43af26","poly":"pneumo","fiche":"p209","front":"GOLD groupe A : quels critères ?","back":"**0 ou 1** exacerbation/an sans hospitalisation + **mMRC 0-1**.","prio":"P1","sec":"s5"},{"id":"fc-p209-e0f928","poly":"pneumo","fiche":"p209","front":"GOLD groupe B : quels critères ?","back":"**0 ou 1** exacerbation/an sans hospitalisation + **mMRC ≥ 2**.","prio":"P1","sec":"s5"},{"id":"fc-p209-7c0c67","poly":"pneumo","fiche":"p209","front":"GOLD groupe E : quels critères ?","back":"**≥ 2** exacerbations/an ou **≥ 1 avec hospitalisation**, quelle que soit la dyspnée.","prio":"P1","sec":"s5"},{"id":"fc-p209-1d661a","poly":"pneumo","fiche":"p209","front":"Classification GOLD : que sont devenus les groupes C et D ?","back":"**Abandonnés**, regroupés dans le **groupe E**.","prio":"P3","sec":"s5"},{"id":"fc-p209-0afd38","poly":"pneumo","fiche":"p209","front":"Exacerbateur fréquent : quelle définition ?","back":"**> 2** (texte) ou **≥ 2** (tableau) exacerbations/an et/ou **≥ 1 exacerbation hospitalisée**.","prio":"P1","sec":"s5"},{"id":"fc-p209-64a425","poly":"pneumo","fiche":"p209","front":"Exacerbateur fréquent : quelle valeur pronostique ?","back":"Facteur de **mauvais pronostic** (exacerbations répétées pèsent sur la **survie**).","prio":"P2","sec":"s5"},{"id":"fc-p209-ae03bf","poly":"pneumo","fiche":"p209","front":"BPCO : quelle mesure fonctionnelle simple est un facteur pronostique important ?","back":"Le **VEMS post-BD**.","prio":"P2","sec":"s5"},{"id":"fc-p209-b7dc4f","poly":"pneumo","fiche":"p209","front":"BPCO : faut-il une évaluation cardiaque ?","back":"Oui, à proposer **largement** (comorbidités cardio-vasculaires fréquentes).","prio":"P2","sec":"s6"},{"id":"fc-p209-45b72e","poly":"pneumo","fiche":"p209","front":"BPCO : chez qui faire une échographie cardiaque ?","back":"Patients **hypoxémiques** ou **très dyspnéiques**.","prio":"P1","sec":"s6"},{"id":"fc-p209-cefa9f","poly":"pneumo","fiche":"p209","front":"Échographie cardiaque dans la BPCO : que recherche-t-on ?","back":"Signes d'**hypertension pulmonaire** ou **cardiopathie gauche** associée.","prio":"P2","sec":"s6"},{"id":"fc-p209-e68dfa","poly":"pneumo","fiche":"p209","front":"NFS dans la BPCO : que recherche-t-on ?","back":"**Polyglobulie** réactionnelle à l'hypoxémie, ou **anémie** (aggrave la dyspnée).","prio":"P1","sec":"s6"},{"id":"fc-p209-55b63a","poly":"pneumo","fiche":"p209","front":"Alpha-1 antitrypsine : chez qui la doser ?","back":"Chez **tout patient BPCO**.","prio":"P1","sec":"s6"},{"id":"fc-p209-17d14f","poly":"pneumo","fiche":"p209","front":"ECG dans la BPCO : quels signes rechercher notamment ?","back":"Des **signes droits**.","prio":"P3","sec":"s6"},{"id":"fc-p209-d6dcaa","poly":"pneumo","fiche":"p209","front":"Radiographie de thorax : quel intérêt pour le diagnostic positif de BPCO ?","back":"**Aucun**.","prio":"P2","sec":"s7"},{"id":"fc-p209-5c014a","poly":"pneumo","fiche":"p209","front":"Radiographie de BPCO : quels signes de distension de profil ?","back":"**Coupoles aplaties**, espaces clairs **rétrosternal et rétrocardiaque** agrandis, **thorax en tonneau**.","prio":"P3","sec":"s7"},{"id":"fc-p209-c4ec5e","poly":"pneumo","fiche":"p209","front":"Radiographie de BPCO : quels signes de face ?","back":"**Côtes horizontalisées** ; **hyperclarté** pulmonaire (vascularisation diminuée).","prio":"P3","sec":"s7"},{"id":"fc-p209-8f7959","poly":"pneumo","fiche":"p209","front":"Radiographie de thorax : est-elle utile pour dépister le cancer bronchique chez le BPCO ?","back":"**Non**, ce n'est pas un outil pertinent de dépistage.","prio":"P3","sec":"s7"},{"id":"fc-p209-e6331a","poly":"pneumo","fiche":"p209","front":"Scanner thoracique dans la BPCO : est-il systématique ?","back":"**Non**, mais plus informatif que la radiographie.","prio":"P2","sec":"s7"},{"id":"fc-p209-9b2946","poly":"pneumo","fiche":"p209","front":"Scanner thoracique dans la BPCO : quels apports ?","back":"Caractériser l'**emphysème**, chercher des **bronchectasies**, **dépister le cancer**, repérer des **calcifications coronaires**.","prio":"P3","sec":"s7"},{"id":"fc-p209-d996b4","poly":"pneumo","fiche":"p209","front":"Calcifications coronaires au scanner d'un BPCO : quelle conduite ?","back":"Rechercher une **coronaropathie** non connue.","prio":"P3","sec":"s7"},{"id":"fc-p209-ea0847","poly":"pneumo","fiche":"p209","front":"BPCO : quels sont les 2 grands diagnostics différentiels ?","back":"L'**asthme** et la **dilatation des bronches** (DDB).","prio":"P1","sec":"s8"},{"id":"fc-p209-3886d6","poly":"pneumo","fiche":"p209","front":"Asthme vs BPCO : quelle différence de mécanisme ?","back":"Asthme : **épisodes** d'inflammation et bronchoconstriction ; BPCO : **obstruction chronique** avec destruction de l'échangeur.","prio":"P2","sec":"s8"},{"id":"fc-p209-76ea88","poly":"pneumo","fiche":"p209","front":"Asthme et BPCO : peuvent-ils coexister ?","back":"**Oui** ; et un asthme sévère, même sans tabac, peut donner un TVO peu réversible.","prio":"P2","sec":"s8"},{"id":"fc-p209-541989","poly":"pneumo","fiche":"p209","front":"BPCO vs asthme : quel terrain typique ?","back":"BPCO : **fumeur > 40 ans** ; asthme : **adulte jeune**, déclenché par une exposition allergénique.","prio":"P2","sec":"s8"},{"id":"fc-p209-1dd489","poly":"pneumo","fiche":"p209","front":"BPCO vs asthme : quelle différence pour la rhinosinusite chronique ?","back":"BPCO : **inconstante**, peu symptomatique ; asthme : **presque constante** (parfois polypose).","prio":"P3","sec":"s8"},{"id":"fc-p209-b83338","poly":"pneumo","fiche":"p209","front":"BPCO vs asthme : quelle histoire naturelle ?","back":"BPCO : début vers **40 ans**, aggravation **souvent progressive** ; asthme : début **souvent** dans l'**enfance**, symptômes variables et réversibles.","prio":"P3","sec":"s8"},{"id":"fc-p209-146d34","poly":"pneumo","fiche":"p209","front":"BPCO : la spirométrie peut-elle être normale ?","back":"**Jamais** (TVO permanent) ; dans l'asthme, elle peut être normale.","prio":"P1","sec":"s8"},{"id":"fc-p209-f46363","poly":"pneumo","fiche":"p209","front":"BPCO vs asthme : que montre l'imagerie ?","back":"BPCO : **emphysème** (inconstant) ; asthme : le plus souvent **normale**.","prio":"P3","sec":"s8"},{"id":"fc-p209-559f24","poly":"pneumo","fiche":"p209","front":"Asthme : quelle cause fréquente d'exacerbation ?","back":"L'**absence ou l'arrêt** du traitement **anti-inflammatoire inhalé**.","prio":"P3","sec":"s8"},{"id":"fc-p209-e91ee4","poly":"pneumo","fiche":"p209","front":"DDB et BPCO : peuvent-elles s'associer ?","back":"Oui, des **DDB modérées** peuvent se voir au cours d'une BPCO.","prio":"P3","sec":"s8"},{"id":"fc-p209-23cd72","poly":"pneumo","fiche":"p209","front":"BPCO vs asthme : quelle clinique typique ?","back":"BPCO : **dyspnée d'effort puis de repos** ± bronchite chronique ; asthme : symptômes **variables et réversibles**, périodes sans symptôme fréquentes.","prio":"P3","sec":"s8"},{"id":"fc-p209-24a289","poly":"pneumo","fiche":"p209","front":"BPCO stable : quelle logique d'escalade médicamenteuse ?","back":"**Un bronchodilatateur**, puis **bithérapie**, puis éventuellement **trithérapie**.","prio":"P2","sec":"s9"},{"id":"fc-p209-1bbc88","poly":"pneumo","fiche":"p209","front":"BPCO stable : quels objectifs du traitement ?","back":"Réduire le **handicap** (dyspnée, exercice, qualité de vie) et les **risques futurs** (exacerbations, mortalité, déclin, IRC).","prio":"P2","sec":"s9"},{"id":"fc-p209-4047c6","poly":"pneumo","fiche":"p209","front":"BPCO : quelle est la seule mesure qui modifie avec certitude l'histoire naturelle ?","back":"L'**arrêt complet et définitif du tabac**, quel que soit le stade.","prio":"P1","sec":"s9"},{"id":"fc-p209-37da59","poly":"pneumo","fiche":"p209","front":"BPCO : quelles autres expositions faire cesser ?","back":"**Cannabis** et **aérocontaminants professionnels**.","prio":"P2","sec":"s9"},{"id":"fc-p209-ec094d","poly":"pneumo","fiche":"p209","front":"BPCO : quelles vaccinations ?","back":"**Grippe** annuelle, **pneumocoque** (VPC 13 puis VPP 23), **COVID-19**.","prio":"P1","sec":"s9"},{"id":"fc-p209-771155","poly":"pneumo","fiche":"p209","front":"BPCO : quel schéma de vaccination antipneumococcique ?","back":"**VPC 13** puis **VPP 23** au moins **8 semaines** après ; rappel VPP 23 au moins **5 ans** plus tard.","prio":"P1","sec":"s9"},{"id":"fc-p209-e3206d","poly":"pneumo","fiche":"p209","front":"VPP 23 : pourquoi tracer chaque injection ?","back":"Risque théorique en cas de **réadministrations précoces répétées** (baisse de la réponse lymphocytaire B).","prio":"P3","sec":"s9"},{"id":"fc-p209-724875","poly":"pneumo","fiche":"p209","front":"BPCO : quelle activité physique recommander ?","back":"Endurance + entretien musculaire : **30 min de marche/jour** ou **> 2 h/semaine** (réduit la mortalité).","prio":"P2","sec":"s9"},{"id":"fc-p209-6c74a9","poly":"pneumo","fiche":"p209","front":"BPCO : quel suivi nutritionnel ?","back":"Conseils et suivi pour le **surpoids** comme pour la **dénutrition**.","prio":"P2","sec":"s9"},{"id":"fc-p209-c9a17b","poly":"pneumo","fiche":"p209","front":"BPCO : quel bronchodilatateur pour tous ?","back":"Un **BD de courte durée d'action à la demande** dès qu'une dyspnée survient.","prio":"P1","sec":"s9"},{"id":"fc-p209-358d01","poly":"pneumo","fiche":"p209","front":"BPCO : quelle voie d'administration et quelle exigence pour les inhalés ?","back":"Voie **inhalée** ; dispositif adapté aux **capacités du patient**, apprentissage et **contrôle régulier** de la technique.","prio":"P2","sec":"s9"},{"id":"fc-p209-063958","poly":"pneumo","fiche":"p209","front":"BPCO : quand proposer une réadaptation respiratoire ?","back":"Dès qu'un **handicap persiste** malgré les médicaments, même **dyspnée isolée**.","prio":"P1","sec":"s9"},{"id":"fc-p209-50f136","poly":"pneumo","fiche":"p209","front":"Réadaptation respiratoire : quels sont ses composants principaux ?","back":"**Réentraînement à l'exercice** et **éducation thérapeutique** (approche globale, multidisciplinaire).","prio":"P2","sec":"s9"},{"id":"fc-p209-d4d1c9","poly":"pneumo","fiche":"p209","front":"Réadaptation respiratoire : quels bénéfices ?","back":"Améliore dyspnée, effort, qualité de vie ; réduit **exacerbations**, **hospitalisations**, consommation de soins.","prio":"P3","sec":"s9"},{"id":"fc-p209-16a737","poly":"pneumo","fiche":"p209","front":"Réadaptation : de quoi dépend l'efficacité à long terme ?","back":"De la **poursuite des activités physiques** mises en place.","prio":"P2","sec":"s9"},{"id":"fc-p209-e031ff","poly":"pneumo","fiche":"p209","front":"BPCO stable : quel rythme de réévaluation ?","back":"**1 à 3 mois** après chaque modification, puis tous les **3 à 12 mois** ; **EFR au moins annuelle**.","prio":"P2","sec":"s9"},{"id":"fc-p209-d71c30","poly":"pneumo","fiche":"p209","front":"BPCO : quels traitements n'ont aucun intérêt ?","back":"**Mucomodificateurs**, **antileucotriènes**, **antitussifs**.","prio":"P3","sec":"s9"},{"id":"fc-p209-cd5d63","poly":"pneumo","fiche":"p209","front":"BPCO et bêtabloquant nécessaire pour indication cardiaque forte : quelle attitude ?","back":"La BPCO n'est **plus une CI formelle** : choisir un **cardiosélectif**.","prio":"P1","sec":"s9"},{"id":"fc-p209-11e1a3","poly":"pneumo","fiche":"p209","front":"BPCO stable : sur quoi repose le choix des traitements inhalés ?","back":"Sur la **dyspnée** et les **exacerbations**, **pas** sur le VEMS.","prio":"P1","sec":"s10"},{"id":"fc-p209-b1214b","poly":"pneumo","fiche":"p209","front":"Algorithme BPCO : comment définir un patient « exacerbateur » ?","back":"**≥ 2 exacerbations modérées** ou **≥ 1 sévère** (hospitalisée) dans l'année écoulée.","prio":"P2","sec":"s10"},{"id":"fc-p209-211618","poly":"pneumo","fiche":"p209","front":"BPCO : dyspnée et/ou exacerbations sous BD de courte durée : quel cran suivant ?","back":"**Un bronchodilatateur de longue durée** (plutôt **anticholinergique** si exacerbations).","prio":"P1","sec":"s10"},{"id":"fc-p209-c03314","poly":"pneumo","fiche":"p209","front":"Anticholinergique vs bêta-2 de longue durée : lequel prévient le mieux les exacerbations ?","back":"L'**anticholinergique de longue durée** (efficacité équivalente sur fonction et dyspnée).","prio":"P2","sec":"s10"},{"id":"fc-p209-d92aa0","poly":"pneumo","fiche":"p209","front":"Bronchodilatateurs de longue durée : quels bénéfices ?","back":"Améliorent dyspnée, capacité d'exercice, qualité de vie ; **réduisent les exacerbations**.","prio":"P2","sec":"s10"},{"id":"fc-p209-d24be7","poly":"pneumo","fiche":"p209","front":"BPCO sous 1 BDLA, dyspnée (mMRC ≥ 2) sans exacerbation : quel traitement ?","back":"**Deux bronchodilatateurs de longue durée** (bêta-2 + anticholinergique).","prio":"P1","sec":"s10"},{"id":"fc-p209-9fa403","poly":"pneumo","fiche":"p209","front":"BPCO sous 1 BDLA, exacerbations sans dyspnée marquée : quel traitement ?","back":"**Corticostéroïde inhalé + bêta-2 de longue durée**.","prio":"P1","sec":"s10"},{"id":"fc-p209-692844","poly":"pneumo","fiche":"p209","front":"BPCO sous 1 BDLA, dyspnée et exacerbations : quel traitement ?","back":"**Deux bronchodilatateurs de longue durée**.","prio":"P2","sec":"s10"},{"id":"fc-p209-6724a1","poly":"pneumo","fiche":"p209","front":"BPCO : sous quel seuil d'éosinophiles sanguins ne pas proposer de corticostéroïde inhalé ?","back":"**< 300/mm³** (le choix entre 2 BDLA et CSI + bêta-2 de longue durée peut tenir compte des éosinophiles).","prio":"P3","sec":"s10"},{"id":"fc-p209-570ea0","poly":"pneumo","fiche":"p209","front":"BPCO : dyspnée et/ou exacerbations persistantes sous double traitement : quelle option ?","back":"**Trithérapie inhalée** (CSI + 2 BDLA).","prio":"P1","sec":"s10"},{"id":"fc-p209-da485f","poly":"pneumo","fiche":"p209","front":"BPCO sous trithérapie avec exacerbations persistantes : quelle option ?","back":"Discuter un **macrolide**, sur **avis spécialisé**.","prio":"P2","sec":"s10"},{"id":"fc-p209-2736c2","poly":"pneumo","fiche":"p209","front":"BPCO : quels motifs de désescalade d'un corticostéroïde inhalé ?","back":"**Pneumonie** (effet indésirable), indication initiale erronée (aucune exacerbation), ou **aucune exacerbation sur 1 an + éosinophiles < 300/mm³**.","prio":"P2","sec":"s10"},{"id":"fc-p209-aa4280","poly":"pneumo","fiche":"p209","front":"BPCO non contrôlée : que vérifier avant de monter d'un cran ?","back":"**Diagnostic** (asthme ?), **arrêt du tabac**, fonction respiratoire, **observance et technique d'inhalation**, éducation/réhabilitation, **comorbidités**.","prio":"P1","sec":"s10"},{"id":"fc-p209-347109","poly":"pneumo","fiche":"p209","front":"CSI + bêta-2 de longue durée chez l'exacerbateur fréquent : quels bénéfices et quel risque ?","back":"Moins de symptômes et d'exacerbations, meilleure qualité de vie ; plus d'**infections parenchymateuses**.","prio":"P2","sec":"s10"},{"id":"fc-p209-cd5480","poly":"pneumo","fiche":"p209","front":"BPCO : un corticostéroïde inhalé seul est-il indiqué ?","back":"**Non**, jamais en monothérapie (contrairement à l'asthme).","prio":"P1","sec":"s10"},{"id":"fc-p209-06821a","poly":"pneumo","fiche":"p209","front":"BPCO au stade d'IRC : quel traitement diminue la mortalité ?","back":"L'**oxygénothérapie de longue durée** (OLD).","prio":"P1","sec":"s11"},{"id":"fc-p209-c148da","poly":"pneumo","fiche":"p209","front":"OLD dans l'IRC obstructive : quel critère principal de PaO₂ ?","back":"**PaO₂ < 55 mmHg** (7,3 kPa).","prio":"P3","sec":"s11"},{"id":"fc-p209-1c70b8","poly":"pneumo","fiche":"p209","front":"OLD avec PaO₂ entre 55 et 59 mmHg : quelles conditions ?","back":"Hypoxie tissulaire : **polyglobulie** (Ht > 55 %), **insuffisance ventriculaire droite**, ou **désaturations nocturnes non apnéiques** (SpO₂ moy ≤ 88 %).","prio":"P3","sec":"s11"},{"id":"fc-p209-3e440c","poly":"pneumo","fiche":"p209","front":"OLD : comment mesurer la PaO₂ retenue ?","back":"**Deux gaz du sang** au repos, en air ambiant, à l'état stable, espacés d'**au moins 2 semaines**.","prio":"P3","sec":"s11"},{"id":"fc-p209-8c32ef","poly":"pneumo","fiche":"p209","front":"OLD et tabagisme actif : quel risque ?","back":"**Brûlures graves** du visage, **incendie** : peut remettre en cause l'OLD.","prio":"P3","sec":"s11"},{"id":"fc-p209-7e4376","poly":"pneumo","fiche":"p209","front":"OLD chez l'hypercapnique : est-ce une contre-indication ?","back":"**Non** si la PaCO₂ ne monte pas nettement ; sinon ajouter une **ventilation à domicile**.","prio":"P3","sec":"s11"},{"id":"fc-p209-9c4808","poly":"pneumo","fiche":"p209","front":"OLD : quel débit et quelle durée quotidienne ?","back":"PaO₂ **> 60 mmHg** ou SpO₂ **> 90 %** ; idéalement **24 h/24**, au minimum **15 h/j** (nuit et activité).","prio":"P3","sec":"s11"},{"id":"fc-p209-c83c18","poly":"pneumo","fiche":"p209","front":"BPCO : quand indiquer une VNI à domicile ?","back":"**Hypercapnie diurne importante** malgré un traitement optimal.","prio":"P1","sec":"s11"},{"id":"fc-p209-d2b66e","poly":"pneumo","fiche":"p209","front":"VNI à domicile chez le BPCO sévère : quels bénéfices ?","back":"Améliore **survie** et symptômes, réduit les **hospitalisations**.","prio":"P2","sec":"s11"},{"id":"fc-p209-32a88a","poly":"pneumo","fiche":"p209","front":"VNI à domicile dans la BPCO : quelles modalités ?","back":"Surtout **nocturne**, ventilateur de domicile, masque **nasal ou naso-buccal**.","prio":"P3","sec":"s11"},{"id":"fc-p209-05c91a","poly":"pneumo","fiche":"p209","front":"BPCO avec distension : quel traitement interventionnel peut soulager la dyspnée ?","back":"**Réduction de volume pulmonaire** (chirurgicale ou endoscopique) en centre spécialisé.","prio":"P3","sec":"s11"},{"id":"fc-p209-3e2ecc","poly":"pneumo","fiche":"p209","front":"Bullectomie : quelles indications ?","back":"Bulles **volumineuses**, **compressives** ou **compliquées** (infection, hémorragie, pneumothorax).","prio":"P3","sec":"s11"},{"id":"fc-p209-91b9c2","poly":"pneumo","fiche":"p209","front":"Insuffisance respiratoire chronique : quels médicaments sont contre-indiqués ?","back":"**Benzodiazépines**, **neuroleptiques sédatifs**, **opiacés** (si indispensables : prudence + gaz du sang).","prio":"P1","sec":"s11"},{"id":"fc-p209-573450","poly":"pneumo","fiche":"p209","front":"Exacerbation chez un BPCO connu : sur quoi repose le diagnostic ?","back":"Aggravation de la **dyspnée**, de la **toux** et/ou de l'**expectoration**.","prio":"P2","sec":"s12"},{"id":"fc-p209-b0760b","poly":"pneumo","fiche":"p209","front":"Exacerbation inaugurale grave : quelle démarche suivre ?","back":"Celle de l'**insuffisance respiratoire aiguë** (item 359).","prio":"P3","sec":"s12"},{"id":"fc-p209-2c51dd","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quelles sont les 2 premières questions ?","back":"Y a-t-il un **critère d'hospitalisation** ? Quelle est la **cause** ?","prio":"P1","sec":"s12"},{"id":"fc-p209-5eed67","poly":"pneumo","fiche":"p209","front":"Exacerbation sévère de BPCO : quelle définition ?","back":"Exacerbation qui **nécessite une hospitalisation**.","prio":"P1","sec":"s12"},{"id":"fc-p209-59a42f","poly":"pneumo","fiche":"p209","front":"Exacerbation : quand le pronostic vital est-il engagé ?","back":"**Hypoxémie profonde** et/ou **acidose respiratoire décompensée** (pH ≤ 7,35).","prio":"P1","sec":"s12"},{"id":"fc-p209-774f7f","poly":"pneumo","fiche":"p209","front":"Exacerbation : quels critères d'hospitalisation liés à la gravité et à l'évolution ?","back":"Signes de **détresse respiratoire**, **aggravation rapide**, **pas de réponse** au traitement initial.","prio":"P1","sec":"s12"},{"id":"fc-p209-c205a4","poly":"pneumo","fiche":"p209","front":"Exacerbation : quels critères d'hospitalisation liés à la BPCO de fond ?","back":"Dyspnée aux **gestes du quotidien** (habillage), **OLD ou ventilation à domicile**, antécédent de **réanimation**.","prio":"P2","sec":"s12"},{"id":"fc-p209-4c50ed","poly":"pneumo","fiche":"p209","front":"Exacerbation : quels critères d'hospitalisation liés au terrain et au contexte ?","back":"**Âge avancé**/fragilité, comorbidités (cardio, alcool, neuro, psy), **isolement**, **incertitude diagnostique**.","prio":"P2","sec":"s12"},{"id":"fc-p209-3d122e","poly":"pneumo","fiche":"p209","front":"Exacerbation : quel critère d'hospitalisation lié à l'oxygène ?","back":"**Besoin d'oxygène**, ou d'**augmenter le débit** chez un patient sous OLD.","prio":"P1","sec":"s12"},{"id":"fc-p209-a38a22","poly":"pneumo","fiche":"p209","front":"Exacerbation : que faire d'une hypoxémie profonde ou mal tolérée ?","back":"Toujours la **corriger** par un débit d'oxygène adéquat.","prio":"P2","sec":"s12"},{"id":"fc-p209-c09b03","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quelle est la cause la plus fréquente ?","back":"**Infectieuse** (virale, bactérienne ou mixte).","prio":"P3","sec":"s12"},{"id":"fc-p209-99158f","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quels virus fréquents ?","back":"**Grippe**, **VRS**, **SARS-CoV-2**, rhinovirus, adénovirus.","prio":"P3","sec":"s12"},{"id":"fc-p209-e4e44e","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quelles bactéries fréquentes ?","back":"***Haemophilus influenzae***, ***Streptococcus pneumoniae***, ***Moraxella catarrhalis***.","prio":"P3","sec":"s12"},{"id":"fc-p209-2e5497","poly":"pneumo","fiche":"p209","front":"Exacerbation : quand craindre Pseudomonas aeruginosa ?","back":"**VEMS < 30 %**, **bronchectasies**, hospitalisation antérieure avec antibiotiques large spectre, **corticothérapie systémique** au long cours.","prio":"P3","sec":"s12"},{"id":"fc-p209-598a08","poly":"pneumo","fiche":"p209","front":"Exacerbation : quel est le principal argument pour une infection bactérienne ?","back":"La **purulence** des expectorations.","prio":"P2","sec":"s12"},{"id":"fc-p209-612537","poly":"pneumo","fiche":"p209","front":"Exacerbation : quelles causes non infectieuses ?","back":"**Pic de pollution**, **tabagisme massif** ; souvent cause inconnue.","prio":"P3","sec":"s12"},{"id":"fc-p209-59339d","poly":"pneumo","fiche":"p209","front":"Exacerbation : quels diagnostics différentiels évoquer ?","back":"**Pneumonie**, **œdème pulmonaire**, **embolie pulmonaire**, **pneumothorax**, sédatifs/opiacés/O₂ haut débit, traumatisme thoracique, chirurgie.","prio":"P2","sec":"s12"},{"id":"fc-p209-8d61e2","poly":"pneumo","fiche":"p209","front":"Exacerbation vs pneumonie : quels arguments pour la pneumonie ?","back":"**Foyer de crépitants**, fièvre typiquement ≥ **38,5 °C**, syndrome **alvéolaire** à l'imagerie.","prio":"P2","sec":"s12"},{"id":"fc-p209-65c120","poly":"pneumo","fiche":"p209","front":"Exacerbation avec suspicion d'embolie pulmonaire : quel examen ?","back":"**Angio-TDM thoracique**.","prio":"P2","sec":"s12"},{"id":"fc-p209-520bb2","poly":"pneumo","fiche":"p209","front":"Exacerbation légère ou modérée traitée en ville : quels examens ?","back":"**Aucun** examen complémentaire.","prio":"P1","sec":"s12"},{"id":"fc-p209-63ffe1","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quel bilan systématique ?","back":"**Radio thorax**, **ECG**, **NFS**, **CRP**, ionogramme, créatinine, **gaz du sang artériel**.","prio":"P1","sec":"s12"},{"id":"fc-p209-2726d5","poly":"pneumo","fiche":"p209","front":"Exacerbation : quand faire un ECBC ?","back":"Échec d'antibiotique, antécédent de **Pseudomonas**, obstruction sévère motivant l'hospitalisation, **réanimation/soins intensifs**, **immunodépression**.","prio":"P3","sec":"s12"},{"id":"fc-p209-0b7e73","poly":"pneumo","fiche":"p209","front":"Exacerbation : quels examens selon l'orientation ?","back":"(Angio-)**TDM**, **BNP**, **troponine**, **échocardiographie**.","prio":"P3","sec":"s12"},{"id":"fc-p209-d389a3","poly":"pneumo","fiche":"p209","front":"Exacerbation : quel est le traitement principal ?","back":"Les **bronchodilatateurs inhalés**, à **fortes doses**, pris **tôt** par le patient.","prio":"P1","sec":"s13"},{"id":"fc-p209-a9c78f","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville : quel bronchodilatateur en 1re intention ?","back":"**Bêta-2-agoniste de courte durée**, seul ou avec un **anticholinergique de courte durée**.","prio":"P2","sec":"s13"},{"id":"fc-p209-470071","poly":"pneumo","fiche":"p209","front":"Exacerbation à domicile : quels dispositifs d'inhalation ?","back":"**Aérosol-doseur** (± chambre d'inhalation), dispositif à **poudre** ou **nébuliseur**.","prio":"P3","sec":"s13"},{"id":"fc-p209-7628ca","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville sans expectoration plus purulente : antibiotique ?","back":"**Non** : surveillance et **réévaluation à 48 h** ; antibiotique si aggravation.","prio":"P1","sec":"s13"},{"id":"fc-p209-8a7e40","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville, expectoration plus purulente sans facteur de risque : quel antibiotique ?","back":"**Amoxicilline-acide clavulanique**, **amoxicilline**, **pristinamycine** ou **macrolide**, **5 jours**.","prio":"P1","sec":"s13"},{"id":"fc-p209-38112d","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville : quelle dose d'amoxicilline (± clavulanate) ou de pristinamycine ?","back":"**3 g/j**.","prio":"P2","sec":"s13"},{"id":"fc-p209-4026fd","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville : quels facteurs de risque modifient l'antibiothérapie ?","back":"**VEMS < 50 %**, **> 2 exacerbations/an**, **cardiopathie ischémique**, **oxygène à domicile**, **corticothérapie orale chronique**.","prio":"P1","sec":"s13"},{"id":"fc-p209-34ea17","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville, purulence avec facteur de risque : quel antibiotique ?","back":"**Amoxicilline-acide clavulanique**, **C3G** ou **fluoroquinolone antipneumococcique** (lévofloxacine), **5 jours**.","prio":"P1","sec":"s13"},{"id":"fc-p209-24eac7","poly":"pneumo","fiche":"p209","front":"Exacerbation : quelle durée d'antibiotique selon le texte du Collège ?","back":"**5 à 7 jours** (5 j dans la figure ville), réévaluation à **J2-J3**.","prio":"P3","sec":"s13"},{"id":"fc-p209-4c41ef","poly":"pneumo","fiche":"p209","front":"Exacerbation en ville : quand donner un corticoïde oral ?","back":"En **2e intention**, si **pas d'amélioration après 48 h** (bénéfice non démontré à domicile).","prio":"P1","sec":"s13"},{"id":"fc-p209-81b77a","poly":"pneumo","fiche":"p209","front":"Exacerbation : quand prescrire une kinésithérapie ?","back":"**Désencombrement** si sécrétions bronchiques **abondantes**.","prio":"P2","sec":"s13"},{"id":"fc-p209-065574","poly":"pneumo","fiche":"p209","front":"Exacerbation en ambulatoire : héparine préventive ?","back":"**Non**.","prio":"P2","sec":"s13"},{"id":"fc-p209-3a20e2","poly":"pneumo","fiche":"p209","front":"Exacerbation de BPCO : quels médicaments sont contre-indiqués ?","back":"**Antitussifs** et **neurosédatifs** (ville comme hôpital).","prio":"P1","sec":"s13"},{"id":"fc-p209-b58c11","poly":"pneumo","fiche":"p209","front":"Après une exacerbation : quel suivi ?","back":"**Médecin traitant dans la semaine** ; suivi **renforcé** (clinique + spirométrie à distance).","prio":"P2","sec":"s13"},{"id":"fc-p209-49caba","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quel objectif de SpO₂ ?","back":"**88 à 92 %** (oxygène titré, lunettes ou masque à mélangeur).","prio":"P1","sec":"s14"},{"id":"fc-p209-b60da0","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quel mode d'administration des bronchodilatateurs ?","back":"**Nébulisation** : bêta-2 systématiques ± anticholinergique.","prio":"P2","sec":"s14"},{"id":"fc-p209-3279ca","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quelles doses de terbutaline et d'ipratropium nébulisés ?","back":"Terbutaline **5 mg** 4 à 6 fois/j ; ipratropium **0,5 mg** 3 à 4 fois/j.","prio":"P3","sec":"s14"},{"id":"fc-p209-15169e","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quelles indications de l'antibiotique ?","back":"Expectoration **franchement purulente**, OU **VEMS < 30 %**, OU **signes de gravité**.","prio":"P1","sec":"s14"},{"id":"fc-p209-053287","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quels antibiotiques de 1re intention ?","back":"**Amoxicilline ± acide clavulanique**, **pristinamycine** ou **macrolide**.","prio":"P2","sec":"s14"},{"id":"fc-p209-360b99","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : place de la lévofloxacine et des C3G injectables ?","back":"**Cas particuliers** (ex. échec d'un antibiotique antérieur).","prio":"P2","sec":"s14"},{"id":"fc-p209-96c637","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : comment adapter l'antibiothérapie ?","back":"Cibler un **germe résistant** selon l'historique, puis adapter à l'**ECBC**.","prio":"P3","sec":"s14"},{"id":"fc-p209-f8006d","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : quelle corticothérapie systémique ?","back":"En option : **prednisolone 30 à 40 mg/j**, **5 jours**, arrêt sans décroissance.","prio":"P1","sec":"s14"},{"id":"fc-p209-0ca02d","poly":"pneumo","fiche":"p209","front":"Corticoïde systémique dans l'exacerbation hospitalisée : quels bénéfices ?","back":"Accélère l'amélioration du **VEMS**, **raccourcit l'hospitalisation**.","prio":"P3","sec":"s14"},{"id":"fc-p209-923da9","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : prévention thromboembolique ?","back":"**HBPM préventive** (en l'absence d'insuffisance rénale).","prio":"P1","sec":"s14"},{"id":"fc-p209-3b3c1c","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée : que traiter en plus ?","back":"La **cause** déclenchante, le **tabagisme**, les **comorbidités** ; revoir la **technique d'inhalation**.","prio":"P3","sec":"s14"},{"id":"fc-p209-8e13bf","poly":"pneumo","fiche":"p209","front":"Exacerbation hospitalisée chez l'hypercapnique : quelle surveillance ?","back":"**Gaz du sang répétés** : repérer l'aggravation de l'acidose sous oxygène.","prio":"P2","sec":"s14"},{"id":"fc-p209-a4d05d","poly":"pneumo","fiche":"p209","front":"Après une hospitalisation pour exacerbation : quand proposer une réadaptation ?","back":"Dans les **90 jours**, si pas de réadaptation récente.","prio":"P1","sec":"s14"},{"id":"fc-p209-a60c42","poly":"pneumo","fiche":"p209","front":"Exacerbation avec acidose respiratoire : quel seuil de pH indique la ventilation ?","back":"**pH < 7,35**.","prio":"P1","sec":"s15"},{"id":"fc-p209-f2a263","poly":"pneumo","fiche":"p209","front":"Exacerbation avec acidose respiratoire : quelle ventilation en 1re intention ?","back":"**Ventilation non invasive** au **masque facial**.","prio":"P1","sec":"s15"},{"id":"fc-p209-4a5ab2","poly":"pneumo","fiche":"p209","front":"Exacerbation avec signes de gravité : quels traitements sont indiqués ?","back":"**Antibiotique** (même sans purulence franche) et **corticoïdes oraux**.","prio":"P2","sec":"s15"},{"id":"fc-p209-9b9489","poly":"pneumo","fiche":"p209","front":"BPCO sous corticostéroïde inhalé : quel risque surveiller et quelle conséquence ?","back":"Risque accru de **pneumonies** ; une pneumonie fait discuter la **décroissance** du CSI.","prio":"P2","sec":"s16"},{"id":"fc-p210-331732","poly":"pneumo","fiche":"p210","front":"PID : quelle définition ?","back":"Grand ensemble de maladies ayant en commun des **opacités infiltrantes diffuses** à l'imagerie, touchant surtout l'**interstitium**.","prio":"P1","sec":"s1"},{"id":"fc-p210-fc550c","poly":"pneumo","fiche":"p210","front":"PID : est-ce une maladie unique ?","back":"**Non** : un aspect commun à de nombreuses entités, pas un diagnostic.","prio":"P1","sec":"s1"},{"id":"fc-p210-ad0efa","poly":"pneumo","fiche":"p210","front":"Interstitium pulmonaire : quelle définition ?","back":"Tissu conjonctif soutenant les **axes broncho-vasculaires** et formant les **septa** interlobulaires et intralobulaires.","prio":"P1","sec":"s1"},{"id":"fc-p210-25d5a5","poly":"pneumo","fiche":"p210","front":"PID : quel infiltrat anatomopathologique de l'interstitium ?","back":"Infiltrat **cellulaire**, **œdémateux** ou **fibreux**.","prio":"P1","sec":"s1"},{"id":"fc-p210-ad690d","poly":"pneumo","fiche":"p210","front":"PID : quelles structures peuvent être touchées en plus de l'interstitium ?","back":"Les **bronchioles** et l'**espace alvéolaire** (certaines PID).","prio":"P3","sec":"s1"},{"id":"fc-p210-b47716","poly":"pneumo","fiche":"p210","front":"PID : quelles caractéristiques des opacités à l'imagerie ?","back":"**Diffuses**, **non systématisées**, **bilatérales**, habituellement **symétriques**.","prio":"P1","sec":"s1"},{"id":"fc-p210-a4442b","poly":"pneumo","fiche":"p210","front":"PID : quel examen d'imagerie est indispensable ?","back":"Le **scanner thoracique**.","prio":"P1","sec":"s1"},{"id":"fc-p210-7dfb13","poly":"pneumo","fiche":"p210","front":"PID : quels signes cliniques communs ?","back":"**Dyspnée**, **toux** (non spécifiques) ; **crépitants** fréquents ; **hypoxémie à l'effort**.","prio":"P1","sec":"s1"},{"id":"fc-p210-a45432","poly":"pneumo","fiche":"p210","front":"Lobule pulmonaire : quelle taille et quelle orientation ?","back":"Polyèdre de **1 à 2,5 cm**, pointe vers le **hile**, base contre la **plèvre**.","prio":"P3","sec":"s1"},{"id":"fc-p210-ceb781","poly":"pneumo","fiche":"p210","front":"Lobule pulmonaire : que trouve-t-on au centre et en périphérie ?","back":"Centre : **bronchiole terminale** + **artère centrolobulaire** ; septa périphériques : **veines** et **lymphatiques**.","prio":"P3","sec":"s1"},{"id":"fc-p210-ea3b3f","poly":"pneumo","fiche":"p210","front":"PID : sur quels deux axes les classe-t-on ?","back":"**Durée** (aiguë ou subaiguë/chronique) et **cause** (connue ou inconnue).","prio":"P1","sec":"s2"},{"id":"fc-p210-4b047f","poly":"pneumo","fiche":"p210","front":"PID aiguë : quelle définition ?","back":"Évolution depuis **moins de 3 semaines** ; sinon PID subaiguë ou chronique (PID-SC).","prio":"P1","sec":"s2"},{"id":"fc-p210-a1d231","poly":"pneumo","fiche":"p210","front":"PID aiguë vs PID-SC : la démarche est-elle la même ?","back":"**Non** : démarche diagnostique et prise en charge **fondamentalement différentes**.","prio":"P1","sec":"s2"},{"id":"fc-p210-c8b5c0","poly":"pneumo","fiche":"p210","front":"PID-SC : quelle répartition cause connue / inconnue ?","back":"Cause **connue 35 %**, **inconnue 65 %**.","prio":"P1","sec":"s2"},{"id":"fc-p210-0387b9","poly":"pneumo","fiche":"p210","front":"PID aiguë : quelles sont les 4 grandes causes ?","back":"**Infection** · **œdème cardiogénique** · **SDRA** · **exacerbation** d'une PID-SC.","prio":"P2","sec":"s2"},{"id":"fc-p210-5e56b2","poly":"pneumo","fiche":"p210","front":"PID aiguë : quelles causes plus rares ?","back":"Pneumopathie **médicamenteuse** · **hémorragie intra-alvéolaire** · pneumopathie aiguë à **éosinophiles** · certaines **connectivites**.","prio":"P3","sec":"s2"},{"id":"fc-p210-e92a01","poly":"pneumo","fiche":"p210","front":"PID-SC de cause connue : citer les 7 groupes ?","back":"**Connectivites** · **PHS** · **médicaments** · **proliférations malignes** · pneumoconioses · infection (tuberculose) · **insuffisance cardiaque gauche**.","prio":"P1","sec":"s2"},{"id":"fc-p210-30db12","poly":"pneumo","fiche":"p210","front":"PID des connectivites : citer des exemples ?","back":"**Polyarthrite rhumatoïde**, **sclérodermie**, **myosites**.","prio":"P1","sec":"s2"},{"id":"fc-p210-3f37a7","poly":"pneumo","fiche":"p210","front":"Pneumopathies d'hypersensibilité : citer des exemples ?","back":"**Poumon d'éleveur d'oiseaux**, **poumon de fermier**, PHS domestiques.","prio":"P1","sec":"s2"},{"id":"fc-p210-226547","poly":"pneumo","fiche":"p210","front":"PID par prolifération maligne : citer des exemples ?","back":"**Lymphangite carcinomateuse**, **adénocarcinomes lépidiques**.","prio":"P1","sec":"s2"},{"id":"fc-p210-c72ae0","poly":"pneumo","fiche":"p210","front":"Pneumoconioses : citer deux exemples ?","back":"**Silicose**, **asbestose**.","prio":"P1","sec":"s2"},{"id":"fc-p210-18504a","poly":"pneumo","fiche":"p210","front":"PID-SC de cause inconnue : quels groupes ?","back":"**Sarcoïdose** · **PID idiopathiques** · autres entités (histiocytose langerhansienne, lymphangioléiomyomatose).","prio":"P1","sec":"s2"},{"id":"fc-p210-ffc295","poly":"pneumo","fiche":"p210","front":"PID idiopathiques : quelle part représente la FPI ?","back":"**55 %** des PID idiopathiques.","prio":"P1","sec":"s2"},{"id":"fc-p210-b2a0fd","poly":"pneumo","fiche":"p210","front":"PINS : quelle part des PID idiopathiques ?","back":"**10 %**.","prio":"P2","sec":"s2"},{"id":"fc-p210-260e36","poly":"pneumo","fiche":"p210","front":"PID idiopathiques : citer les principales ?","back":"**FPI** · **PINS** · **POC** (pneumopathie organisée cryptogénique).","prio":"P2","sec":"s2"},{"id":"fc-p210-7dc614","poly":"pneumo","fiche":"p210","front":"PID-SC : quels sont les 3 groupes dominants ?","back":"**Sarcoïdose** · **FPI** · **PID des connectivites**.","prio":"P1","sec":"s2"},{"id":"fc-p210-adddb2","poly":"pneumo","fiche":"p210","front":"PID aiguë : quelles causes dominent ?","back":"Causes **infectieuses** et **cardiogéniques**.","prio":"P2","sec":"s3"},{"id":"fc-p210-29c956","poly":"pneumo","fiche":"p210","front":"PID aiguë sans fièvre : quel bilan est indispensable ?","back":"Le **bilan cardiologique** (œdème cardiogénique fréquent, toujours à suspecter).","prio":"P2","sec":"s3"},{"id":"fc-p210-300777","poly":"pneumo","fiche":"p210","front":"PID aiguë : quels éléments du contexte analyser ?","back":"**Antécédents** (cancer, hémopathie, FRCV, connectivite) · **immunodépression** · exposition **médicaments pneumotoxiques**, gaz toxique, **drogues**.","prio":"P2","sec":"s3"},{"id":"fc-p210-26708a","poly":"pneumo","fiche":"p210","front":"Œdème pulmonaire hémodynamique : quels examens ?","back":"**ECG**, **BNP**, **échographie cardiaque** transthoracique, **test thérapeutique aux diurétiques**.","prio":"P2","sec":"s3"},{"id":"fc-p210-be5293","poly":"pneumo","fiche":"p210","front":"Œdème pulmonaire hémodynamique : quels signes cliniques et radiologiques ?","back":"**Expectoration mousseuse**, **orthopnée** ; cardiomégalie, opacités floues **périhilaires**, épanchements pleuraux.","prio":"P2","sec":"s3"},{"id":"fc-p210-92f76c","poly":"pneumo","fiche":"p210","front":"PID aiguë infectieuse : quels agents des PAC en cause ?","back":"*S. pneumoniae*, **légionelles**, mycoplasme, chlamydiae, **grippe**, **COVID-19**.","prio":"P2","sec":"s3"},{"id":"fc-p210-ec33e7","poly":"pneumo","fiche":"p210","front":"PID aiguë infectieuse : quelles autres causes que les PAC ?","back":"**Miliaire tuberculeuse** · **pneumocystose**.","prio":"P2","sec":"s3"},{"id":"fc-p210-144acb","poly":"pneumo","fiche":"p210","front":"Miliaire tuberculeuse au scanner : quel aspect ?","back":"**Micronodules** diffus (< 3 mm) à **contours nets**.","prio":"P2","sec":"s3"},{"id":"fc-p210-219954","poly":"pneumo","fiche":"p210","front":"PID aiguë infectieuse : quels examens microbiologiques ?","back":"Hémocultures · **antigénuries** · antigénémies · **écouvillon nasopharyngé** (grippe, COVID-19, mycoplasme) · expectoration (BK) · LBA si immunodéprimé.","prio":"P2","sec":"s3"},{"id":"fc-p210-564d13","poly":"pneumo","fiche":"p210","front":"Exacerbation de PID-SC : quelles causes surtout ?","back":"**Médicaments**, **exacerbation de FPI**, **connectivites**.","prio":"P3","sec":"s3"},{"id":"fc-p210-b4bb6c","poly":"pneumo","fiche":"p210","front":"PID aiguë : quel est l'examen clé si fébrile ou immunodéprimé ?","back":"Le **LBA**, une fois la **cause cardiaque écartée**.","prio":"P2","sec":"s3"},{"id":"fc-p210-08d473","poly":"pneumo","fiche":"p210","front":"PID de l'immunodéprimé : quelle est l'indication du LBA, et pourquoi ?","back":"Indiqué devant **toute PID de l'immunodéprimé** (si réalisable, cause cardiaque écartée), car l'infection peut y être **sans fièvre**.","prio":"P2","sec":"s3"},{"id":"fc-p210-6d6858","poly":"pneumo","fiche":"p210","front":"LBA dans la PID aiguë : quelle performance ?","back":"**Très performant** pour diagnostiquer une **infection** ; oriente dans les autres cas.","prio":"P3","sec":"s3"},{"id":"fc-p210-a0f40a","poly":"pneumo","fiche":"p210","front":"PID-SC : quelles sont les circonstances de découverte habituelles ?","back":"**Dyspnée d'effort** ± **toux sèche**, d'installation **progressive**.","prio":"P2","sec":"s4"},{"id":"fc-p210-4b81a3","poly":"pneumo","fiche":"p210","front":"PID-SC : quels autres modes de découverte ?","back":"**Crépitants « Velcro »** aux bases · **hippocratisme digital** · découverte **fortuite** · bilan d'une **connectivite**.","prio":"P2","sec":"s4"},{"id":"fc-p210-087789","poly":"pneumo","fiche":"p210","front":"Hippocratisme digital dans une PID : quelle valeur ?","back":"Peu spécifique mais **évocateur de FPI**.","prio":"P2","sec":"s4"},{"id":"fc-p210-067fd6","poly":"pneumo","fiche":"p210","front":"PID-SC : pourquoi interroger sur le tabac ?","back":"Certaines PID se voient **presque uniquement chez les fumeurs**.","prio":"P3","sec":"s4"},{"id":"fc-p210-67d14b","poly":"pneumo","fiche":"p210","front":"PID et drogues : quel risque ?","back":"Quel que soit le mode de consommation, la drogue ou ses **produits de coupe** peuvent donner une PID aiguë ou chronique.","prio":"P3","sec":"s4"},{"id":"fc-p210-4856db","poly":"pneumo","fiche":"p210","front":"PID médicamenteuse : quelle ressource consulter ?","back":"Le site **Pneumotox** (toxicités pulmonaires actualisées).","prio":"P2","sec":"s4"},{"id":"fc-p210-c343f8","poly":"pneumo","fiche":"p210","front":"PID médicamenteuse : un médicament pris depuis longtemps peut-il être en cause ?","back":"**Oui**, une prise ancienne peut aussi être responsable.","prio":"P2","sec":"s4"},{"id":"fc-p210-362b98","poly":"pneumo","fiche":"p210","front":"PID-SC : quelles expositions professionnelles et domestiques rechercher ?","back":"Pneumoconioses : **amiante**, **silice** ; PHS : **oiseaux**, **actinomycètes du foin humide**, **moisissures** domestiques.","prio":"P2","sec":"s4"},{"id":"fc-p210-2cb8d1","poly":"pneumo","fiche":"p210","front":"PID-SC : quels signes fonctionnels de connectivite rechercher ?","back":"**Arthralgies**, **myalgies**, **syndrome sec**, **syndrome de Raynaud**.","prio":"P2","sec":"s4"},{"id":"fc-p210-eaab63","poly":"pneumo","fiche":"p210","front":"PID-SC : quels signes physiques de connectivite rechercher ?","back":"Déformations articulaires, éruptions, **sclérodactylie**, télangiectasies, faiblesse musculaire, **mains de mécanicien** ; bandelette urinaire.","prio":"P2","sec":"s4"},{"id":"fc-p210-6b3097","poly":"pneumo","fiche":"p210","front":"PID : d'où vient surtout l'orientation étiologique ?","back":"**Interrogatoire** (+++), **scanner** (pierre angulaire), synthèse en **DMD** ; examen pulmonaire et EFR tranchent rarement.","prio":"P2","sec":"s4"},{"id":"fc-p210-dcc765","poly":"pneumo","fiche":"p210","front":"Scanner des PID : quelle technique ?","back":"**Haute résolution**, **coupes fines** ; c'est la **pierre angulaire** de l'orientation.","prio":"P2","sec":"s5"},{"id":"fc-p210-81f2cb","poly":"pneumo","fiche":"p210","front":"PID au scanner : quelles sont les 5 lésions élémentaires ?","back":"**Nodules** · **lignes/réticulations** · **épaississements péribronchovasculaires** · **hyperdensités** · **kystes**.","prio":"P2","sec":"s5"},{"id":"fc-p210-a746e9","poly":"pneumo","fiche":"p210","front":"Micronodule et nodule : quelles tailles ?","back":"Micronodule **< 3 mm** ; nodule **3 à 30 mm**.","prio":"P2","sec":"s5"},{"id":"fc-p210-f51b3e","poly":"pneumo","fiche":"p210","front":"Nodules des PID : quelles distributions ?","back":"**Périlymphatique**, **hématogène** (miliaire) ou **centrolobulaire**.","prio":"P2","sec":"s5"},{"id":"fc-p210-a16fea","poly":"pneumo","fiche":"p210","front":"Réticulations : quels deux types au scanner ?","back":"**Interlobulaires à larges mailles** polyédriques ; **intralobulaires à petites mailles**.","prio":"P2","sec":"s5"},{"id":"fc-p210-7fa524","poly":"pneumo","fiche":"p210","front":"Verre dépoli vs condensation : quelle différence ?","back":"Verre dépoli : vaisseaux et parois bronchiques **visibles** ; condensation : les **efface** (± bronchogramme aérique).","prio":"P2","sec":"s5"},{"id":"fc-p210-0eead6","poly":"pneumo","fiche":"p210","front":"Rayon de miel : quelle définition ?","back":"Espaces **kystiques** aériens **jointifs**, à parois épaissies, **empilés sous la plèvre**.","prio":"P2","sec":"s5"},{"id":"fc-p210-56aac3","poly":"pneumo","fiche":"p210","front":"PID : quels signes scanographiques de fibrose ?","back":"**Bronchectasies de traction** · **distorsion architecturale** · **perte de volume**.","prio":"P2","sec":"s5"},{"id":"fc-p210-fb4ac6","poly":"pneumo","fiche":"p210","front":"Bronchectasie de traction : quel mécanisme ?","back":"Paroi bronchique **normale**, tirée par la **rétraction élastique accrue** du parenchyme fibreux.","prio":"P3","sec":"s5"},{"id":"fc-p210-3d7fc4","poly":"pneumo","fiche":"p210","front":"Micronodules périlymphatiques avec scissure « perlée » : quelle orientation ?","back":"**Sarcoïdose**.","prio":"P2","sec":"s5"},{"id":"fc-p210-e748b5","poly":"pneumo","fiche":"p210","front":"Épaississement des cloisons interlobulaires (larges mailles) : quelle orientation ?","back":"**Lymphangite carcinomateuse**.","prio":"P2","sec":"s5"},{"id":"fc-p210-bae5d4","poly":"pneumo","fiche":"p210","front":"Rayon de miel avec bronchectasies de traction : quelle orientation ?","back":"**Fibrose pulmonaire idiopathique**.","prio":"P2","sec":"s5"},{"id":"fc-p210-a24cb3","poly":"pneumo","fiche":"p210","front":"Réticulations intralobulaires à fines mailles avec quelques bronchectasies de traction : quelle orientation ?","back":"**PINS**.","prio":"P3","sec":"s5"},{"id":"fc-p210-6e5f16","poly":"pneumo","fiche":"p210","front":"PID : quelles anomalies hors du parenchyme orientent le diagnostic ?","back":"**Adénopathies hilaires bilatérales**, **pleurésie**.","prio":"P3","sec":"s5"},{"id":"fc-p210-1d215f","poly":"pneumo","fiche":"p210","front":"PID aux EFR : quel trouble ventilatoire ?","back":"**Trouble restrictif pur** : **CPT < 80 %**, baisse homogène volumes et débits, **VEMS/CVF > 70 %**.","prio":"P2","sec":"s6"},{"id":"fc-p210-29ee05","poly":"pneumo","fiche":"p210","front":"PID : quand un trouble obstructif peut-il s'associer ?","back":"Chez le **fumeur** ou dans certaines connectivites (**polyarthrite rhumatoïde**).","prio":"P3","sec":"s6"},{"id":"fc-p210-95ef87","poly":"pneumo","fiche":"p210","front":"PID : quel seuil de DLCO traduit l'atteinte de l'échangeur ?","back":"**DLCO < 70 %** de la théorique.","prio":"P2","sec":"s6"},{"id":"fc-p210-a9a500","poly":"pneumo","fiche":"p210","front":"PID : comment démasquer une hypoxémie absente au repos ?","back":"**Désaturation au test de marche de 6 minutes**.","prio":"P2","sec":"s6"},{"id":"fc-p210-e5d8fd","poly":"pneumo","fiche":"p210","front":"PID : le trouble restrictif et l'hypoxémie orientent-ils vers la cause ?","back":"**Non**.","prio":"P2","sec":"s6"},{"id":"fc-p210-444359","poly":"pneumo","fiche":"p210","front":"PID : quels examens biologiques pour une connectivite ?","back":"**Facteur rhumatoïde**, **anti-CCP**, **anticorps antinucléaires**, anti-ADN ; selon l'orientation dot myosites ou sclérodermie.","prio":"P2","sec":"s7"},{"id":"fc-p210-0a7543","poly":"pneumo","fiche":"p210","front":"PID : quel examen biologique pour une vascularite ?","back":"Les **ANCA**.","prio":"P2","sec":"s7"},{"id":"fc-p210-5c29fa","poly":"pneumo","fiche":"p210","front":"PID : quel bilan biologique oriente vers une sarcoïdose ?","back":"**Calcémie**, **calciurie**.","prio":"P2","sec":"s7"},{"id":"fc-p210-105424","poly":"pneumo","fiche":"p210","front":"PID : quelles anomalies de la formule sanguine rechercher ?","back":"**Hyperéosinophilie**, **lymphopénie**.","prio":"P3","sec":"s7"},{"id":"fc-p210-ed470e","poly":"pneumo","fiche":"p210","front":"LBA : comment est-il réalisé ?","back":"Au cours d'une **bronchoscopie souple** ; sa **formule cytologique** oriente la cause.","prio":"P2","sec":"s7"},{"id":"fc-p210-baf9fb","poly":"pneumo","fiche":"p210","front":"LBA normal : quelle formule ?","back":"**Macrophages 85-95 %**, **lymphocytes 5-15 %**.","prio":"P2","sec":"s7"},{"id":"fc-p210-11d6ca","poly":"pneumo","fiche":"p210","front":"LBA : qu'est-ce qu'une alvéolite ?","back":"**Augmentation du nombre de cellules** par ml ; chez le fumeur : alvéolite **macrophagique**.","prio":"P3","sec":"s7"},{"id":"fc-p210-40c589","poly":"pneumo","fiche":"p210","front":"LBA : quelles découvertes apportent une certitude diagnostique ?","back":"**Cellules malignes** · **agent infectieux** pathogène · **sidérophages** (hémorragie alvéolaire).","prio":"P2","sec":"s7"},{"id":"fc-p210-9f823f","poly":"pneumo","fiche":"p210","front":"PHS en phase aiguë : quelle formule du LBA ?","back":"**Alvéolite lymphocytaire**.","prio":"P2","sec":"s7"},{"id":"fc-p210-e4d4e9","poly":"pneumo","fiche":"p210","front":"PID : dans quelle proportion l'histologie est-elle nécessaire ?","back":"**Moins de 15 %** des PID.","prio":"P2","sec":"s8"},{"id":"fc-p210-371c19","poly":"pneumo","fiche":"p210","front":"Biopsies d'éperons bronchiques : pour quelles PID ?","back":"Processus lymphophiles : **sarcoïdose**, **lymphangite carcinomateuse**.","prio":"P2","sec":"s8"},{"id":"fc-p210-1ba4e8","poly":"pneumo","fiche":"p210","front":"Biopsies transbronchiques : pour quelles PID apportent-elles une certitude ?","back":"**Sarcoïdose** (stades 2-4) · **pneumopathie organisée** · **lymphangite carcinomateuse** · **miliaire tuberculeuse**.","prio":"P2","sec":"s8"},{"id":"fc-p210-aa7261","poly":"pneumo","fiche":"p210","front":"Biopsies transbronchiques hors indications : quels risques ?","back":"Non contributives et dangereuses : **pneumothorax**, **hémoptysie**.","prio":"P2","sec":"s8"},{"id":"fc-p210-570dc2","poly":"pneumo","fiche":"p210","front":"EBUS : pour quelles pathologies ?","back":"**Sarcoïdose**, **lymphangite carcinomateuse**, **tuberculose ganglionnaire**, **lymphome**.","prio":"P2","sec":"s8"},{"id":"fc-p210-caaa78","poly":"pneumo","fiche":"p210","front":"Biopsie pulmonaire chirurgicale ou cryobiopsie : quelles conditions ?","back":"Après **discussion multidisciplinaire**, PID **non typique**, **impact attendu** sur la prise en charge, sans contre-indication.","prio":"P2","sec":"s8"},{"id":"fc-p210-dc7261","poly":"pneumo","fiche":"p210","front":"Biopsie des glandes salivaires accessoires : pour quelles maladies ?","back":"**Sarcoïdose**, **Gougerot-Sjögren**.","prio":"P3","sec":"s8"},{"id":"fc-p210-17b99d","poly":"pneumo","fiche":"p210","front":"PID-SC : quelles PID évoquer en premier ?","back":"Les plus fréquentes ou urgentes : **œdème pulmonaire**, **infections**, **tumeur**, **médicament**, certaines **connectivites**, **sarcoïdose**.","prio":"P2","sec":"s8"},{"id":"fc-p210-13ed6d","poly":"pneumo","fiche":"p210","front":"PID-SC sans diagnostic après bilan initial : quelle étape suivante ?","back":"**Fibroscopie bronchique avec LBA** (± biopsies bronchiques si sarcoïdose ou lymphangite suspectée).","prio":"P2","sec":"s8"},{"id":"fc-p210-22eceb","poly":"pneumo","fiche":"p210","front":"PID-SC : quel est le rôle de la discussion multidisciplinaire ?","back":"**Pierre angulaire** : réunir clinique, biologie et imagerie ; très grande majorité des dossiers.","prio":"P2","sec":"s8"},{"id":"fc-p210-ba43d7","poly":"pneumo","fiche":"p210","front":"FPI : quelle place parmi les PID de cause inconnue ?","back":"La **plus fréquente après la sarcoïdose** ; incidence ~**10/100 000**.","prio":"P2","sec":"s9"},{"id":"fc-p210-9a9d7d","poly":"pneumo","fiche":"p210","front":"FPI : quel terrain ?","back":"Âge moyen **68 ans**, légère prédominance **masculine**, **tabagisme** dans 60 à 80 % des cas.","prio":"P2","sec":"s9"},{"id":"fc-p210-e925af","poly":"pneumo","fiche":"p210","front":"FPI : quel pronostic sans traitement ?","back":"**Très sombre** : survie médiane de **3 ans**.","prio":"P2","sec":"s9"},{"id":"fc-p210-07d35c","poly":"pneumo","fiche":"p210","front":"FPI : quelle clinique ?","back":"Dyspnée d'effort progressive, toux sèche, **crépitants velcro** aux bases ; **hippocratisme digital** (40 %), pas d'atteinte extrarespiratoire.","prio":"P2","sec":"s9"},{"id":"fc-p210-881958","poly":"pneumo","fiche":"p210","front":"FPI : quel aspect scanographique ?","back":"**PIC** : **rayon de miel**, réticulations intralobulaires, bronchectasies de traction, prédominance **sous-pleurale et basale**.","prio":"P2","sec":"s9"},{"id":"fc-p210-9962e8","poly":"pneumo","fiche":"p210","front":"FPI : quel aspect radiographique ?","back":"Parfois normale au début ; opacités **réticulées** basales sous-pleurales ; **perte de volume**.","prio":"P3","sec":"s9"},{"id":"fc-p210-bc9bca","poly":"pneumo","fiche":"p210","front":"FPI : que montrent la biologie et le bilan immunitaire ?","back":"**Normaux** (bilan immunitaire négatif).","prio":"P3","sec":"s9"},{"id":"fc-p210-fca2b0","poly":"pneumo","fiche":"p210","front":"FPI : quel rôle du LBA ?","back":"N'apporte **pas le diagnostic positif** ; peut écarter un **différentiel** si le scanner est atypique.","prio":"P2","sec":"s9"},{"id":"fc-p210-8bcfbe","poly":"pneumo","fiche":"p210","front":"FPI : quand faire une biopsie pulmonaire ?","back":"Seulement si **scanner atypique** et impact réel, après **DMD** (elle montre une PIC).","prio":"P2","sec":"s9"},{"id":"fc-p210-7903e6","poly":"pneumo","fiche":"p210","front":"FPI : quel traitement médicamenteux ?","back":"**Antifibrosants**.","prio":"P2","sec":"s9"},{"id":"fc-p210-ef4580","poly":"pneumo","fiche":"p210","front":"PINS : quel profil scanographique ?","back":"**Verre dépoli + réticulations**, distribution **péribronchovasculaire**, relatif **respect sous-pleural**.","prio":"P2","sec":"s10"},{"id":"fc-p210-d40716","poly":"pneumo","fiche":"p210","front":"PINS idiopathique : quel terrain et quel pronostic ?","back":"Sujet plus jeune (**< 50 ans**) ; pronostic **meilleur** que la FPI.","prio":"P2","sec":"s10"},{"id":"fc-p210-6976f7","poly":"pneumo","fiche":"p210","front":"PINS idiopathique : comment affirmer le diagnostic ?","back":"**Biopsie pulmonaire**.","prio":"P3","sec":"s10"},{"id":"fc-p210-ce0137","poly":"pneumo","fiche":"p210","front":"PINS secondaire : quelles causes ?","back":"Surtout les **connectivites** (leur atteinte pulmonaire la plus fréquente) ; aussi un **médicament**.","prio":"P2","sec":"s10"},{"id":"fc-p210-8dcbb3","poly":"pneumo","fiche":"p210","front":"PINS au cours d'une connectivite : la biopsie est-elle nécessaire ?","back":"**Non** : un scanner évocateur suffit.","prio":"P3","sec":"s10"},{"id":"fc-p210-eb729e","poly":"pneumo","fiche":"p210","front":"PHS : quel mécanisme ?","back":"**Hypersensibilité retardée** à des **antigènes organiques** inhalés de façon répétée.","prio":"P2","sec":"s11"},{"id":"fc-p210-d16be8","poly":"pneumo","fiche":"p210","front":"PHS : quels contextes d'exposition ?","back":"**Domestique** (oiseaux, moisissures) ou **professionnel** (agriculture : foin moisi, déjections d'oiseaux).","prio":"P2","sec":"s11"},{"id":"fc-p210-44ce87","poly":"pneumo","fiche":"p210","front":"PHS et tabac : quelle particularité ?","back":"PHS **rares chez le fumeur**.","prio":"P2","sec":"s11"},{"id":"fc-p210-5ab831","poly":"pneumo","fiche":"p210","front":"PHS non fibrosante aiguë : quelle présentation ?","back":"**Syndrome pseudo-grippal fébrile** quelques heures après l'exposition.","prio":"P2","sec":"s11"},{"id":"fc-p210-fb2ccf","poly":"pneumo","fiche":"p210","front":"PHS : quel signe auscultatoire évoque l'atteinte bronchiolaire ?","back":"Râles piaulants de fin d'inspiration (**squeaks**).","prio":"P3","sec":"s11"},{"id":"fc-p210-8b58b4","poly":"pneumo","fiche":"p210","front":"PHS non fibrosante : quel aspect au scanner ?","back":"**Verre dépoli** et/ou **nodules flous centrolobulaires** peu denses.","prio":"P2","sec":"s11"},{"id":"fc-p210-62fb43","poly":"pneumo","fiche":"p210","front":"PHS fibrosante : quelle évolution possible ?","back":"Le plus souvent évitée par l'arrêt de l'exposition, **mais pas toujours** : la fibrose peut progresser seule jusqu'à l'**insuffisance respiratoire** ; aspect parfois proche de la FPI.","prio":"P2","sec":"s11"},{"id":"fc-p210-b3b627","poly":"pneumo","fiche":"p210","front":"PHS : quel élément du scanner aggrave nettement le pronostic ?","back":"Des **signes de fibrose**.","prio":"P2","sec":"s11"},{"id":"fc-p210-1130ec","poly":"pneumo","fiche":"p210","front":"Précipitines sériques : quelle valeur dans la PHS ?","back":"Positives = **exposition** prouvée, pas la maladie ; négatives = PHS **non exclue**.","prio":"P2","sec":"s11"},{"id":"fc-p210-b41eee","poly":"pneumo","fiche":"p210","front":"PHS : sur quoi repose le diagnostic ?","back":"Contexte **clinique, scanographique, fonctionnel et environnemental**, renforcé par une sérologie positive.","prio":"P2","sec":"s11"},{"id":"fc-p210-2d15d6","poly":"pneumo","fiche":"p210","front":"PHS : qui peut confirmer l'exposition à domicile ?","back":"Un **conseiller médical en environnement intérieur** (moisissures notamment).","prio":"P3","sec":"s11"},{"id":"fc-p210-5417d5","poly":"pneumo","fiche":"p210","front":"PHS : que montre la biopsie (exceptionnelle) ?","back":"**Granulomes mal formés**, lésions **bronchocentriques**.","prio":"P3","sec":"s11"},{"id":"fc-p210-c0d6f2","poly":"pneumo","fiche":"p210","front":"PHS d'un éleveur d'oiseaux (cas du Collège) : quel aspect au scanner en inspiration puis expiration ?","back":"Verre dépoli **en mosaïque** avec **piégeage expiratoire**.","prio":"P3","sec":"s11"},{"id":"fc-p210-9c99ff","poly":"pneumo","fiche":"p210","front":"Pneumoconiose : quelle définition ?","back":"**Fibrose pulmonaire** due à l'inhalation de **particules minérales**.","prio":"P2","sec":"s12"},{"id":"fc-p210-379610","poly":"pneumo","fiche":"p210","front":"Pneumoconiose : quel élément est crucial au diagnostic ?","back":"Le **curriculum laboris**.","prio":"P2","sec":"s12"},{"id":"fc-p210-f8c905","poly":"pneumo","fiche":"p210","front":"Pneumoconiose : quelle démarche médico-sociale ?","back":"Le plus souvent **maladie professionnelle** à faire reconnaître par la Sécurité sociale.","prio":"P2","sec":"s12"},{"id":"fc-p210-c3ba51","poly":"pneumo","fiche":"p210","front":"Pneumoconioses en France : laquelle est la plus fréquente ?","back":"L'**asbestose**.","prio":"P2","sec":"s12"},{"id":"fc-p210-dfd408","poly":"pneumo","fiche":"p210","front":"Asbestose : quel aspect au scanner ?","back":"Profil **proche de la FPI** ; plaques pleurales ± calcifiées, inconstantes (confirment l'exposition).","prio":"P2","sec":"s12"},{"id":"fc-p210-a646ad","poly":"pneumo","fiche":"p210","front":"Asbestose : quelle évolution ?","back":"Aggravation progressive vers l'**insuffisance respiratoire chronique**.","prio":"P3","sec":"s12"},{"id":"fc-p210-4282c0","poly":"pneumo","fiche":"p210","front":"Corps asbestosiques dans le LBA : quelle valeur ?","back":"Prouvent l'**exposition**, pas la maladie ; **non indispensables** au diagnostic.","prio":"P2","sec":"s12"},{"id":"fc-p210-d76da0","poly":"pneumo","fiche":"p210","front":"Plaques pleurales : font-elles partie de l'asbestose ?","back":"**Non** : elles **confirment l'exposition** à l'amiante.","prio":"P2","sec":"s12"},{"id":"fc-p210-3f944c","poly":"pneumo","fiche":"p210","front":"Silicose : quelles professions exposées ?","back":"**Mineurs** de charbon, **tailleurs de pierre**, sablage, **fonderies**, bâtiment.","prio":"P2","sec":"s12"},{"id":"fc-p210-102007","poly":"pneumo","fiche":"p210","front":"Silicose en France aujourd'hui : quels cas actuels ?","back":"**Prothésistes dentaires** sans protection ; récemment textile (jeans délavés), plans de travail en matériau composite.","prio":"P3","sec":"s12"},{"id":"fc-p210-1cf4df","poly":"pneumo","fiche":"p210","front":"Silicose : quel aspect à l'imagerie ?","back":"**Micronodules** à prédominance **lobaire supérieure**, pouvant confluer en **masses pseudo-tumorales** ; adénopathies calcifiées « **en coquille d'œuf** » souvent associées.","prio":"P2","sec":"s12"},{"id":"fc-p210-16c9bf","poly":"pneumo","fiche":"p210","front":"Silicose : quelle latence ?","back":"Parfois **très longue**.","prio":"P3","sec":"s12"},{"id":"fc-p210-5773c1","poly":"pneumo","fiche":"p210","front":"Lymphangite carcinomateuse : quelle clinique ?","back":"**Toux sèche rebelle** et **polypnée** rapidement progressives, AEG, antécédent de tumeur.","prio":"P2","sec":"s13"},{"id":"fc-p210-fb1a72","poly":"pneumo","fiche":"p210","front":"Lymphangite carcinomateuse : quels cancers primitifs surtout ?","back":"**Bronchique**, **mammaire**, **digestif** ; plus rarement pancréas, prostate.","prio":"P2","sec":"s13"},{"id":"fc-p210-5cf545","poly":"pneumo","fiche":"p210","front":"Lymphangite carcinomateuse : quel aspect au scanner ?","back":"Épaississement **irrégulier et nodulaire des septa interlobulaires** (grandes mailles polyédriques).","prio":"P2","sec":"s13"},{"id":"fc-p210-da3c37","poly":"pneumo","fiche":"p210","front":"Lymphangite carcinomateuse : comment la confirmer ?","back":"Le plus souvent **biopsies d'éperons bronchiques**, voire transbronchiques.","prio":"P3","sec":"s13"},{"id":"fc-p210-2a26a3","poly":"pneumo","fiche":"p210","front":"Adénocarcinome lépidique : quelle présentation ?","back":"Dyspnée **non fébrile** progressive, **expectoration abondante et claire** ; plages de **verre dépoli** ± condensation.","prio":"P2","sec":"s13"},{"id":"fc-p210-571075","poly":"pneumo","fiche":"p210","front":"Fibrose pulmonaire progressive : quelle définition ?","back":"Aggravation **clinique, fonctionnelle et radiologique** en **1 an ou moins** malgré le traitement optimal de la cause.","prio":"P2","sec":"s13"},{"id":"fc-p210-ac22e2","poly":"pneumo","fiche":"p210","front":"Fibrose pulmonaire progressive : quel traitement possible ?","back":"Les **antifibrosants**, comme dans la FPI (pas réservés à la FPI).","prio":"P2","sec":"s21"},{"id":"fc-p210-8ca5a7","poly":"pneumo","fiche":"p210","front":"Fibrose pulmonaire progressive : quel est l'archétype ?","back":"La **FPI** ; mais toute PID fibrosante peut évoluer ainsi.","prio":"P3","sec":"s21"},{"id":"fc-p210-afc99a","poly":"pneumo","fiche":"p210","front":"PID aiguë : la démarche diagnostique doit-elle retarder le traitement ?","back":"**Non**.","prio":"P2","sec":"s14"},{"id":"fc-p210-91a6d0","poly":"pneumo","fiche":"p210","front":"PID aiguë : quels traitements immédiats ?","back":"**Réanimation** si détresse · **O₂ haut débit** · **anti-infectieux probabiliste** si fièvre · **diurétiques** si doute cardiaque · **arrêt des pneumotoxiques**.","prio":"P2","sec":"s14"},{"id":"fc-p210-69d83e","poly":"pneumo","fiche":"p210","front":"PID aiguë fébrile : quelle antibiothérapie probabiliste (cas général) ?","back":"Comme une PAC grave : **C3G IV** (céfotaxime ou ceftriaxone) + **macrolide IV** ou **lévofloxacine**.","prio":"P2","sec":"s14"},{"id":"fc-p210-d78f1e","poly":"pneumo","fiche":"p210","front":"PID aiguë avec suspicion de miliaire : quel antibiotique éviter ?","back":"Les **fluoroquinolones** (risque de **négativer** les prélèvements à BK).","prio":"P2","sec":"s14"},{"id":"fc-p210-c706cd","poly":"pneumo","fiche":"p210","front":"PID aiguë, suspicion clinique de grippe chez un hospitalisé en période épidémique : quel traitement ajouter ?","back":"**Oseltamivir** per os **5 jours**, en plus de l'antibiothérapie.","prio":"P2","sec":"s14"},{"id":"fc-p210-6044c0","poly":"pneumo","fiche":"p210","front":"PID aiguë de l'immunodéprimé évoquant une pneumocystose : quel traitement ajouter ?","back":"Un traitement **anti-Pneumocystis jirovecii**.","prio":"P3","sec":"s14"},{"id":"fc-p210-ecdc5e","poly":"pneumo","fiche":"p210","front":"PID aiguë évoquant une miliaire grave : quand débuter les antituberculeux ?","back":"Sans attendre la preuve si la **gravité** l'impose : quadrithérapie 2 mois puis bithérapie 4 mois.","prio":"P3","sec":"s14"},{"id":"fc-p210-a08321","poly":"pneumo","fiche":"p210","front":"PAC avec PID aiguë qui ne s'améliore pas : quelles hypothèses en premier ?","back":"PAC à germes conventionnels (légionelle, pneumocoque) · **œdème fébrile** (endocardite) · **tuberculose** (miliaire) · **pneumocystose**.","prio":"P3","sec":"s14"},{"id":"fc-p210-369460","poly":"pneumo","fiche":"p210","front":"PID aiguë suspecte d'origine médicamenteuse : quelle conduite ?","back":"**Arrêt immédiat** de tout médicament potentiellement pneumotoxique (s'aider de Pneumotox).","prio":"P2","sec":"s15"},{"id":"fc-p210-0847be","poly":"pneumo","fiche":"p210","front":"Pneumopathie médicamenteuse : pourquoi la rechercher en premier ?","back":"Elle impose des **mesures rapides**.","prio":"P3","sec":"s15"},{"id":"fc-p210-441331","poly":"pneumo","fiche":"p210","front":"PID-SC : quel rôle des EFR ?","back":"**Diagnostic** et **suivi** (trouble restrictif, DLCO, test de marche de 6 minutes).","prio":"P2","sec":"s16"},{"id":"fc-p210-8b85f0","poly":"pneumo","fiche":"p210","front":"Antifibrosants dans la FPI : quels effets ?","back":"**Freinent la perte de fonction**, ↓ **exacerbations aiguës**, semblent allonger la survie (seulement « probablement »).","prio":"P2","sec":"s17"},{"id":"fc-p210-733ead","poly":"pneumo","fiche":"p210","front":"PINS idiopathique : quel traitement ?","back":"**Immunosuppresseurs**, avec **éventuellement** des antifibrosants.","prio":"P2","sec":"s18"},{"id":"fc-p210-dbe4b9","poly":"pneumo","fiche":"p210","front":"PHS : quel est le traitement principal ?","back":"**Éviction de l'antigène** ; la forme non fibrosante peut alors évoluer **spontanément favorablement** (parfois).","prio":"P2","sec":"s19"},{"id":"fc-p210-3fcccb","poly":"pneumo","fiche":"p210","front":"Asbestose : comment est-elle souvent découverte ?","back":"Sur une imagerie faite pour autre chose ou lors de la **surveillance systématique** d'un sujet exposé.","prio":"P3","sec":"s20"},{"id":"fc-p210-3f93ab","poly":"pneumo","fiche":"p210","front":"PID : quel suivi pour une PID fibrosante ?","back":"**Clinique**, **EFR**, **scanners successifs** (dépister une fibrose progressive).","prio":"P3","sec":"s22"},{"id":"fc-p210-170489","poly":"pneumo","fiche":"p210","front":"PHS : quels deux types distingue-t-on aujourd'hui ?","back":"PHS **non fibrosante** et PHS **fibrosante** (autrefois : aiguë, subaiguë, chronique).","prio":"P2","sec":"s11"},{"id":"fc-p210-b07174","poly":"pneumo","fiche":"p210","front":"Asbestose au stade précoce : quel aspect au scanner ?","back":"Opacités **linéaires non septales** des **bases**, parallèles ou perpendiculaires à la plèvre.","prio":"P3","sec":"s12"},{"id":"fc-p210-67fac8","poly":"pneumo","fiche":"p210","front":"PID : quand biopsier une lésion extrathoracique ?","back":"En cas de **maladie systémique** : **sarcoïdose**, **myopathies inflammatoires**, **vascularite**.","prio":"P3","sec":"s8"},{"id":"fc-p210-b03791","poly":"pneumo","fiche":"p210","front":"FPI : quel est l'apport de la discussion multidisciplinaire ?","back":"Elle **optimise largement** le diagnostic de FPI.","prio":"P3","sec":"s9"},{"id":"fc-p210-61b6a0","poly":"pneumo","fiche":"p210","front":"Précipitines sériques : de quoi s'agit-il ?","back":"**IgG** dirigées contre l'antigène suspecté d'une **PHS** (déjections d'oiseaux, moisissures du foin…).","prio":"P3","sec":"s7"},{"id":"fc-p211-1f97c8","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : définition ?","back":"Maladie **systémique** de cause **inconnue**, avec granulomes **épithélioïdes et giganto-cellulaires** **sans nécrose caséeuse**.","prio":"P1","sec":"s1"},{"id":"fc-p211-bce483","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : condition indispensable pour retenir le diagnostic devant des granulomes ?","back":"Avoir **éliminé les causes connues de granulomes**.","prio":"P1","sec":"s1"},{"id":"fc-p211-225edc","poly":"pneumo","fiche":"p211","front":"Granulomes de la sarcoïdose : autre nom usuel ?","back":"Granulomes **tuberculoïdes** (immuns), sans nécrose caséeuse.","prio":"P2","sec":"s1"},{"id":"fc-p211-024695","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : fréquence de l'atteinte médiastino-pulmonaire ?","back":"Environ **90 %** des patients ; **isolée** dans la moitié des cas.","prio":"P1","sec":"s1"},{"id":"fc-p211-88a0e3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : hypothèse physiopathologique de formation des granulomes ?","back":"**Antigènes de l'environnement** (mycobactéries, bactéries, particules inertes) chez un sujet au **terrain génétique** prédisposé.","prio":"P3","sec":"s1"},{"id":"fc-p211-243b65","poly":"pneumo","fiche":"p211","front":"Granulome sarcoïdien : cellules qui le composent ?","back":"**Cellules épithélioïdes** et **géantes** (lignée macrophagique) + lymphocytes T surtout **CD4+** ; fibrose inconstante.","prio":"P3","sec":"s1"},{"id":"fc-p211-ba8ef4","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : prévalence en France ?","back":"**30/100 000** habitants.","prio":"P3","sec":"s1"},{"id":"fc-p211-f09847","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : populations les plus touchées ?","back":"**Afro-Américains et Caribéens** (3 fois plus fréquente et plus sévère), **pays nordiques** de l'Europe.","prio":"P3","sec":"s1"},{"id":"fc-p211-c8f129","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : âge habituel de début ?","back":"**25 à 45 ans** dans 2/3 des cas ; rare avant 15 ans et après 75 ans.","prio":"P3","sec":"s1"},{"id":"fc-p211-7378a6","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : répartition selon le sexe et formes familiales ?","back":"Discrète **prépondérance féminine** (F/M 1 à 1,5) ; formes familiales **< 10 %**.","prio":"P3","sec":"s1"},{"id":"fc-p211-5679d9","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : circonstances de diagnostic principales ?","back":"**Signes respiratoires** ; **Löfgren**/**érythème noueux** ; **radiographie** thoracique anormale fortuite.","prio":"P1","sec":"s2"},{"id":"fc-p211-693a45","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : autres circonstances de découverte ?","back":"Localisation extra-pulmonaire (**œil**, **peau**, adénopathies), **asthénie** importante, **hypercalcémie**.","prio":"P2","sec":"s2"},{"id":"fc-p211-eb8851","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : caractère de la toux ?","back":"Fréquente, le plus souvent **non productive**.","prio":"P1","sec":"s2"},{"id":"fc-p211-2e737c","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : place de la dyspnée ?","back":"**Rare au début**, souvent dans les **formes avancées**.","prio":"P1","sec":"s2"},{"id":"fc-p211-da0268","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : auscultation pulmonaire habituelle ?","back":"Généralement **normale**.","prio":"P1","sec":"s2"},{"id":"fc-p211-d0d7ff","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : hippocratisme digital, fréquence et conduite ?","back":"**Exceptionnel** : doit faire **éliminer un autre diagnostic**.","prio":"P1","sec":"s2"},{"id":"fc-p211-f402de","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : cause possible de douleur thoracique ?","back":"Volumineuses **adénopathies intrathoraciques**.","prio":"P3","sec":"s2"},{"id":"fc-p211-a2eca3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : place de l'asthénie ?","back":"**Très fréquente**, parfois au premier plan même dans une forme limitée.","prio":"P2","sec":"s2"},{"id":"fc-p211-566bf6","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : contextes où la fièvre est attendue ?","back":"**Löfgren**, **uvéo-parotidite fébrile**, atteinte **hépatique** ou **rénale**.","prio":"P2","sec":"s2"},{"id":"fc-p211-bde8ea","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : fièvre hors contexte typique, que rechercher ?","back":"Une **infection** (notamment **tuberculose**) ou un autre diagnostic (notamment **lymphome**).","prio":"P2","sec":"s2"},{"id":"fc-p211-07e948","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : altération marquée de l'état général, conduite ?","back":"Chercher un **diagnostic alternatif**.","prio":"P2","sec":"s2"},{"id":"fc-p211-778856","poly":"pneumo","fiche":"p211","front":"Érythème noueux : définition et topographie ?","back":"**Dermo-hypodermite** inflammatoire aiguë des **faces d'extension** des membres (surtout jambes).","prio":"P1","sec":"s3"},{"id":"fc-p211-00c85d","poly":"pneumo","fiche":"p211","front":"Érythème noueux : faut-il le biopsier ?","back":"**Non** : lésion **non spécifique**, **pas de granulome**.","prio":"P1","sec":"s3"},{"id":"fc-p211-ca7bb6","poly":"pneumo","fiche":"p211","front":"Érythème noueux en France : cause la plus fréquente ?","back":"La **sarcoïdose**.","prio":"P1","sec":"s3"},{"id":"fc-p211-b8638c","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : définition ?","back":"**Érythème noueux** + **adénopathies hilaires et médiastinales** bilatérales.","prio":"P1","sec":"s3"},{"id":"fc-p211-14bb18","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : terrain préférentiel ?","back":"**Femme** originaire d'**Europe du Nord**.","prio":"P1","sec":"s3"},{"id":"fc-p211-bbc37e","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : forme aiguë ou chronique, fébrile ou non ?","back":"Forme **aiguë**, souvent **fébrile**.","prio":"P1","sec":"s3"},{"id":"fc-p211-07287f","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : quelle atteinte articulaire peut accompagner ou remplacer l'érythème noueux ?","back":"**Arthralgies/arthrites des chevilles**, notamment chez l'**homme**.","prio":"P1","sec":"s3"},{"id":"fc-p211-049fc9","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : faut-il une biopsie ?","back":"**Non** : tableau **quasi pathognomonique**.","prio":"P1","sec":"s3"},{"id":"fc-p211-eeb405","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : évolution spontanée ?","back":"Résolutive dans **plus de 90 %** des cas, en **12 à 24 mois**.","prio":"P2","sec":"s3"},{"id":"fc-p211-c0ce70","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cutanée : citer les lésions spécifiques ?","back":"**Sarcoïdes** (nodules, plaques), **nodules sur cicatrice**, nodules sous-cutanés, **lupus pernio**.","prio":"P2","sec":"s3"},{"id":"fc-p211-5e1b0d","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : atteintes extra-respiratoires les plus fréquentes ?","back":"**Cutanées**, **oculaires**, **ganglionnaires périphériques**, **hépatiques**.","prio":"P2","sec":"s4"},{"id":"fc-p211-b64c37","poly":"pneumo","fiche":"p211","front":"Atteinte extra-respiratoire associée à l'atteinte médiastino-pulmonaire : apport diagnostique ?","back":"Elle affirme le caractère **systémique** de la maladie.","prio":"P2","sec":"s4"},{"id":"fc-p211-a339c2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose oculaire : fréquence et manifestations ?","back":"**15-30 %** ; **uvéite**, atteinte lacrymale, névrite optique, nodule conjonctival.","prio":"P2","sec":"s4"},{"id":"fc-p211-a3e60c","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cutanée : fréquence et conduite diagnostique ?","back":"**15-25 %** ; **avis dermatologique** et **biopsie cutanée**.","prio":"P3","sec":"s4"},{"id":"fc-p211-048678","poly":"pneumo","fiche":"p211","front":"Sarcoïdose hépatique : fréquence et manifestations ?","back":"**15 %** ; **cholestase sans ictère**, **hépatomégalie**.","prio":"P2","sec":"s4"},{"id":"fc-p211-6ba59c","poly":"pneumo","fiche":"p211","front":"Neurosarcoïdose : fréquence et nerf crânien le plus cité ?","back":"**5-10 %** ; **VII** (facial).","prio":"P2","sec":"s4"},{"id":"fc-p211-a8c694","poly":"pneumo","fiche":"p211","front":"Neurosarcoïdose : atteintes neuro-endocrines possibles ?","back":"**Diabète insipide**, **insuffisance antéhypophysaire**.","prio":"P3","sec":"s4"},{"id":"fc-p211-1ae372","poly":"pneumo","fiche":"p211","front":"Sarcoïdose ORL : manifestations ?","back":"**Obstruction nasale**, croûtes, épistaxis, anosmie ; **parotidite**.","prio":"P3","sec":"s4"},{"id":"fc-p211-c72e7f","poly":"pneumo","fiche":"p211","front":"Sarcoïdose ostéo-articulaire : manifestations ?","back":"**Arthralgies** (poignets, chevilles), **ostéites chroniques**.","prio":"P3","sec":"s4"},{"id":"fc-p211-960b84","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cardiaque : manifestations ?","back":"**BAV**, **bloc de branche droit**, **TV**, **insuffisance cardiaque**, **mort subite**.","prio":"P2","sec":"s4"},{"id":"fc-p211-841e64","poly":"pneumo","fiche":"p211","front":"Sarcoïdose rénale : fréquence et manifestations ?","back":"**2 %** ; créatininémie élevée, **hypercalciurie**, **hypercalcémie**.","prio":"P3","sec":"s4"},{"id":"fc-p211-940c5d","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : œil rouge et/ou baisse d'acuité, diagnostic et examen ?","back":"**Uvéite antérieure aiguë** ; examen à la **lampe à fente**.","prio":"P2","sec":"s4"},{"id":"fc-p211-7ca9b2","poly":"pneumo","fiche":"p211","front":"Iridocyclite chronique sarcoïdienne : complications menaçant la vision ?","back":"**Synéchies** irido-cristalliniennes, **cataracte**, **glaucome**.","prio":"P3","sec":"s4"},{"id":"fc-p211-b664cd","poly":"pneumo","fiche":"p211","front":"Uvéite postérieure sarcoïdienne : pourquoi une consultation ophtalmologique systématique ?","back":"Parfois **latente**, menace le pronostic visuel, souvent associée à une atteinte **neurologique centrale**.","prio":"P2","sec":"s4"},{"id":"fc-p211-4f1c02","poly":"pneumo","fiche":"p211","front":"Lupus pernio : aspect et topographie ?","back":"Plaque **violacée infiltrée** du **nez et des joues** (aile de papillon), parfois oreilles, mains.","prio":"P2","sec":"s4"},{"id":"fc-p211-02552f","poly":"pneumo","fiche":"p211","front":"Lupus pernio : quelle atteinte rechercher ?","back":"Une atteinte **ORL** (lupus pernio surtout observé dans les **formes chroniques**).","prio":"P2","sec":"s4"},{"id":"fc-p211-000c97","poly":"pneumo","fiche":"p211","front":"Syndrome de Heerfordt : définition ?","back":"**Uvéo-parotidite bilatérale fébrile** + **paralysie faciale** (ou d'un autre nerf crânien) + **méningite lymphocytaire** aseptique.","prio":"P2","sec":"s4"},{"id":"fc-p211-4fe9f4","poly":"pneumo","fiche":"p211","front":"Syndrome de Mikulicz : définition ?","back":"Hypertrophie des **glandes lacrymales et salivaires**.","prio":"P2","sec":"s4"},{"id":"fc-p211-58eda2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cardiaque : rang parmi les causes de mortalité de la maladie ?","back":"**2e cause** de mortalité (insuffisance cardiaque, mort subite).","prio":"P2","sec":"s4"},{"id":"fc-p211-9a0bfa","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : place de l'ECG ?","back":"**Indispensable** dans toute forme, à **renouveler périodiquement**.","prio":"P2","sec":"s4"},{"id":"fc-p211-058bf0","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cardiaque : signes ECG à rechercher ?","back":"**BAV** de divers degrés, **bloc de branche** surtout droit, **TV/FV**.","prio":"P3","sec":"s4"},{"id":"fc-p211-525781","poly":"pneumo","fiche":"p211","front":"Sarcoïdose suspectée : trois objectifs du bilan initial systématique ?","back":"**Affirmer** le diagnostic (éliminer les différentiels) ; rechercher les **atteintes d'organes** ; évaluer le **retentissement pulmonaire** et l'**activité**.","prio":"P2","sec":"s5"},{"id":"fc-p211-b4602b","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : trois éléments du diagnostic ?","back":"Tableau clinico-radiologique **compatible** ; **granulomes** sans nécrose caséeuse ; **élimination** des autres granulomatoses.","prio":"P1","sec":"s5"},{"id":"fc-p211-a4101b","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : points clés de l'interrogatoire initial ?","back":"Origine géographique et **contage tuberculeux**, **exposition professionnelle**, forme **familiale**, **tabagisme**.","prio":"P2","sec":"s5"},{"id":"fc-p211-e1a3ca","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : biologie du bilan initial ?","back":"NFS, CRP, iono, créatinine, **calcémie**, EPP, bilan hépatique, **calciurie des 24 h**, **ECA**, **sérologie VIH**.","prio":"P1","sec":"s5"},{"id":"fc-p211-c50a65","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : examens non biologiques du bilan initial systématique ?","back":"**Radiographie thoracique**, **ECG**, **examen ophtalmologique**, **EFR** avec DLCO.","prio":"P1","sec":"s5"},{"id":"fc-p211-914f0d","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : existe-t-il un examen biologique spécifique ?","back":"**Non**, aucun.","prio":"P2","sec":"s5"},{"id":"fc-p211-e6703f","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : la preuve histologique est-elle le plus souvent nécessaire ?","back":"**Oui**, le plus souvent.","prio":"P2","sec":"s5"},{"id":"fc-p211-f1feba","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : tableaux dispensant de biopsie ?","back":"**Löfgren**, **Heerfordt** ou **lupus pernio** avec adénopathies médiastino-hilaires bilatérales ; **stade I asymptomatique** surveillé.","prio":"P1","sec":"s5"},{"id":"fc-p211-cd618f","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : place de la radiographie thoracique ?","back":"**Systématique** : diagnostic, **pronostic** et **suivi** ; elle définit **5 stades**.","prio":"P1","sec":"s6"},{"id":"fc-p211-8dbabf","poly":"pneumo","fiche":"p211","front":"Stades radiographiques de la sarcoïdose : à quoi sont-ils corrélés ?","back":"À la **probabilité de guérison spontanée**.","prio":"P2","sec":"s6"},{"id":"fc-p211-769e13","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : stades radiographiques 0 et I ?","back":"0 : radio **normale** ; I : **adénopathies hilaires bilatérales** et médiastinales **sans** atteinte parenchymateuse.","prio":"P2","sec":"s6"},{"id":"fc-p211-e15ac2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : stades radiographiques II, III et IV ?","back":"II : adénopathies **+ parenchyme** ; III : **parenchyme seul** ; IV : **fibrose** (souvent apicale).","prio":"P2","sec":"s6"},{"id":"fc-p211-d3ee87","poly":"pneumo","fiche":"p211","front":"Adénopathies intrathoraciques sarcoïdiennes : caractères habituels ?","back":"Hilaires **bilatérales**, **symétriques**, homogènes, **non compressives** (95 %).","prio":"P2","sec":"s6"},{"id":"fc-p211-d9ef4f","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : adénopathies asymétriques ou compressives, conduite ?","back":"**Éliminer formellement** un autre diagnostic.","prio":"P2","sec":"s6"},{"id":"fc-p211-33c5e6","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : aspect radiographique du parenchyme ?","back":"**Micronodulaire diffus**, prédominant dans les parties **moyennes et supérieures**.","prio":"P3","sec":"s6"},{"id":"fc-p211-5ed8c2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : contraste clinico-radiologique évocateur ?","back":"Atteinte radiographique **importante** vs symptômes **discrets** et auscultation **normale**.","prio":"P2","sec":"s6"},{"id":"fc-p211-61616e","poly":"pneumo","fiche":"p211","front":"Fibrose sarcoïdienne : topographie prédominante ?","back":"Parties **supérieures et postérieures** ; ascension des hiles, distorsion broncho-vasculaire.","prio":"P3","sec":"s6"},{"id":"fc-p211-6402d5","poly":"pneumo","fiche":"p211","front":"Fibrose sarcoïdienne avec cavités : complication infectieuse exposée ?","back":"**Greffe aspergillaire** (aspergillome, aspergillose chronique).","prio":"P3","sec":"s6"},{"id":"fc-p211-2c4ddb","poly":"pneumo","fiche":"p211","front":"Scanner thoracique de la sarcoïdose : modifie-t-il la classification en stades ?","back":"**Non** : les stades reposent sur la **radiographie standard**.","prio":"P3","sec":"s6"},{"id":"fc-p211-67cf1d","poly":"pneumo","fiche":"p211","front":"Scanner thoracique dans la sarcoïdose : quand est-il indispensable ?","back":"Présentation **non typique** ou suspicion de **complication** (fibrose, HTP, aspergillome, néoplasie) ; **pas indispensable** si stade I typique.","prio":"P3","sec":"s6"},{"id":"fc-p211-f3f156","poly":"pneumo","fiche":"p211","front":"Sarcoïdose au scanner : distribution caractéristique des micronodules ?","back":"Distribution **lymphatique** (péribroncho-vasculaire, sous-pleurale, scissures) ; aspect **« perlé »** des scissures.","prio":"P2","sec":"s6"},{"id":"fc-p211-f5eb4c","poly":"pneumo","fiche":"p211","front":"TEP-FDG dans la sarcoïdose : indications ?","back":"Site **occulte à biopsier**, atteinte **cardiaque active**, **fatigue** inexpliquée, activité d'un **stade IV** ; pas en routine.","prio":"P3","sec":"s6"},{"id":"fc-p211-9b6f9b","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : place des EFR ?","back":"**Systématiques**.","prio":"P1","sec":"s6"},{"id":"fc-p211-3646f3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : anomalie fonctionnelle précoce aux EFR ?","back":"**Baisse de la DLCO**.","prio":"P2","sec":"s6"},{"id":"fc-p211-6da74b","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : spirométrie en stade I ?","back":"**Normale ou peu altérée** (syndrome restrictif/mixte possible ensuite).","prio":"P3","sec":"s6"},{"id":"fc-p211-4aa998","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : test de marche de 6 min anormal, que peut-il refléter ?","back":"**Insuffisance respiratoire** ou **hypertension pulmonaire**.","prio":"P3","sec":"s6"},{"id":"fc-p211-4565bc","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : mécanisme de l'hypercalciurie ?","back":"**Calcitriol** élevé par **1α-hydroxylase** macrophagique → absorption intestinale du Ca et turn-over osseux accrus.","prio":"P2","sec":"s7"},{"id":"fc-p211-5697b7","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : fréquence de l'hypercalcémie et circonstances favorisantes ?","back":"**5 à 10 %** ; été/**exposition solaire**, apports calciques majorés, **vitamine D**.","prio":"P2","sec":"s7"},{"id":"fc-p211-8b5b66","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : anomalie de l'hémogramme typique ?","back":"**Lymphopénie** à prédominance **CD4+**.","prio":"P2","sec":"s7"},{"id":"fc-p211-f52293","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : anomalie de l'électrophorèse des protéines ?","back":"**Hypergammaglobulinémie polyclonale** (activation B).","prio":"P3","sec":"s7"},{"id":"fc-p211-322ec7","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : test tuberculinique ?","back":"**Négatif** dans environ **80 %** (anergie) ; c'est sa **négativation** qui oriente.","prio":"P2","sec":"s7"},{"id":"fc-p211-f2960b","poly":"pneumo","fiche":"p211","front":"Anergie tuberculinique de la sarcoïdose : traduit-elle un déficit immunitaire ?","back":"**Non**.","prio":"P3","sec":"s7"},{"id":"fc-p211-a311ca","poly":"pneumo","fiche":"p211","front":"ECA sérique : origine et signification ?","back":"Produite par les **macrophages** des granulomes ; reflète la **masse granulomateuse** et l'**activité**.","prio":"P2","sec":"s7"},{"id":"fc-p211-6005cb","poly":"pneumo","fiche":"p211","front":"ECA sérique : sensibilité et spécificité ?","back":"**Peu sensible** (élevée dans ≈ **60 %**) et **non spécifique**.","prio":"P2","sec":"s7"},{"id":"fc-p211-cbbe0d","poly":"pneumo","fiche":"p211","front":"ECA : situation la rendant ininterprétable ?","back":"Traitement par **inhibiteur de l'enzyme de conversion**.","prio":"P2","sec":"s7"},{"id":"fc-p211-830c36","poly":"pneumo","fiche":"p211","front":"Endoscopie bronchique dans la sarcoïdose : aspect habituel ?","back":"Souvent **normale** ou muqueuse **« en fond d'œil »** ; parfois granulations blanchâtres.","prio":"P3","sec":"s8"},{"id":"fc-p211-a77305","poly":"pneumo","fiche":"p211","front":"Endoscopie bronchique dans la sarcoïdose : est-elle systématique ?","back":"**Non**, si un site plus accessible a déjà apporté la preuve histologique.","prio":"P3","sec":"s8"},{"id":"fc-p211-f2c463","poly":"pneumo","fiche":"p211","front":"Biopsies bronchiques étagées : sensibilité pour les granulomes ?","back":"**50-60 %** (plus si muqueuse anormale).","prio":"P3","sec":"s8"},{"id":"fc-p211-ecee63","poly":"pneumo","fiche":"p211","front":"LBA dans la sarcoïdose : résultat évocateur ?","back":"Alvéolite **lymphocytaire** (20-50 %) à **CD4+** ; **CD4/CD8 > 3,5** évocateur mais insuffisant.","prio":"P2","sec":"s8"},{"id":"fc-p211-37637b","poly":"pneumo","fiche":"p211","front":"Biopsies transbronchiques vs bronchiques : sensibilité ?","back":"Transbronchiques **plus sensibles** (faible risque d'hémorragie ou de pneumothorax).","prio":"P3","sec":"s8"},{"id":"fc-p211-fea656","poly":"pneumo","fiche":"p211","front":"Sarcoïdose stade I : place de la ponction ganglionnaire sous écho-endoscopie ?","back":"Peut se discuter **en 1re intention**.","prio":"P3","sec":"s8"},{"id":"fc-p211-378c19","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : sites de biopsie à privilégier en premier ?","back":"Sites d'accès **aisé** : **peau**, **adénopathie périphérique**, **glandes salivaires accessoires**, **nodule conjonctival**.","prio":"P2","sec":"s8"},{"id":"fc-p211-99e73c","poly":"pneumo","fiche":"p211","front":"Biopsie des glandes salivaires accessoires : rentabilité ?","back":"**40 %**.","prio":"P3","sec":"s8"},{"id":"fc-p211-aa1427","poly":"pneumo","fiche":"p211","front":"Médiastinoscopie dans la sarcoïdose : place et rendement ?","back":"Très rare (supplantée par l'**écho-endoscopie**) ; diagnostic dans près de **100 %**.","prio":"P3","sec":"s8"},{"id":"fc-p211-3f578b","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : biopsie pulmonaire chirurgicale ou transthoracique, quand ?","back":"**Exceptionnelle** : PID ou nodules d'origine incertaine.","prio":"P3","sec":"s8"},{"id":"fc-p211-fe21e9","poly":"pneumo","fiche":"p211","front":"Granulomes : causes infectieuses à éliminer avant de conclure à une sarcoïdose ?","back":"**Tuberculose**, **MNT**, mycoses (histoplasmose…), brucellose, fièvre Q, syphilis, Whipple, tularémie.","prio":"P2","sec":"s9"},{"id":"fc-p211-927f14","poly":"pneumo","fiche":"p211","front":"Granulomatose sarcoid-like médicamenteuse : médicaments en cause ?","back":"**Inhibiteurs de checkpoint** (PD-1, PD-L1), **interféron**, **anti-TNF**, **BCG intravésical**.","prio":"P2","sec":"s9"},{"id":"fc-p211-8264d3","poly":"pneumo","fiche":"p211","front":"Granulomes : expositions particulaires à éliminer ?","back":"**Bérylliose**, talcose, silicose.","prio":"P2","sec":"s9"},{"id":"fc-p211-cc1875","poly":"pneumo","fiche":"p211","front":"Granulomes + hypogammaglobulinémie + infections répétées : quel diagnostic ?","back":"**Déficit immunitaire commun variable**.","prio":"P3","sec":"s9"},{"id":"fc-p211-829a10","poly":"pneumo","fiche":"p211","front":"Granulomes : maladies inflammatoires/auto-immunes à éliminer ?","back":"**Maladie de Crohn**, **granulomatose avec polyangéite** (Wegener), **cirrhose biliaire primitive**.","prio":"P3","sec":"s9"},{"id":"fc-p211-327141","poly":"pneumo","fiche":"p211","front":"Granulomes : réactions péri-tumorales à éliminer ?","back":"**Lymphomes**, chorion de certains **carcinomes**.","prio":"P3","sec":"s9"},{"id":"fc-p211-7c9d06","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : éléments atypiques cliniques faisant chercher un autre diagnostic ?","back":"Âge atypique, **fièvre** hors Löfgren, **crépitants**, **hippocratisme digital**.","prio":"P2","sec":"s9"},{"id":"fc-p211-af002e","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : éléments atypiques paracliniques faisant chercher un autre diagnostic ?","back":"Micronodules **non lymphatiques**, adénopathies **unilatérales/compressives**, **IDR positive**, **hypogammaglobulinémie**, **VIH +**.","prio":"P2","sec":"s9"},{"id":"fc-p211-1e3f7e","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : proportion de guérisons spontanées à 2 ans ?","back":"Près de la **moitié** des patients.","prio":"P2","sec":"s10"},{"id":"fc-p211-2e23f6","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : rémission après 5 ans d'évolution ?","back":"**Très peu probable**.","prio":"P3","sec":"s10"},{"id":"fc-p211-ee9b4e","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : définition des formes aiguë et chronique ?","back":"Aiguë **< 2 ans** ; chronique **≥ 3-5 ans**.","prio":"P2","sec":"s10"},{"id":"fc-p211-be7dbb","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : organes dont l'atteinte menace le pronostic vital ?","back":"**Poumon**, **cœur**, **système nerveux central**.","prio":"P2","sec":"s10"},{"id":"fc-p211-5aea39","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : organes dont l'atteinte menace le pronostic fonctionnel ?","back":"**Poumon**, **œil**, **foie**, **rein**.","prio":"P3","sec":"s10"},{"id":"fc-p211-41f795","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : pronostic global ?","back":"Favorable dans **80 %** ; séquelles **10-20 %** ; décès **1-5 %**.","prio":"P2","sec":"s10"},{"id":"fc-p211-03410a","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : formes aiguës favorables sans traitement ?","back":"**Syndrome de Löfgren** et **stade I**.","prio":"P2","sec":"s10"},{"id":"fc-p211-694eb0","poly":"pneumo","fiche":"p211","front":"Sarcoïdose pulmonaire : principal risque évolutif ?","back":"La **fibrose pulmonaire**.","prio":"P2","sec":"s10"},{"id":"fc-p211-39400e","poly":"pneumo","fiche":"p211","front":"Fibrose sarcoïdienne : conséquences ?","back":"**Insuffisance respiratoire chronique**, **HTP** et IC droite, **aspergillose** chronique avec hémoptysies.","prio":"P3","sec":"s10"},{"id":"fc-p211-9b6ed3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose en Occident : principale cause de mortalité ?","back":"La **fibrose pulmonaire**.","prio":"P2","sec":"s10"},{"id":"fc-p211-3698d8","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : critères pronostiques favorables ?","back":"**Érythème noueux**, forme **aiguë**, **stade I asymptomatique**.","prio":"P2","sec":"s10"},{"id":"fc-p211-b0183a","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : critères défavorables majeurs ?","back":"Début **après 40 ans**, **chronicité**, **stades III/IV**, syndrome **obstructif**, atteintes extra-respiratoires graves.","prio":"P2","sec":"s10"},{"id":"fc-p211-bbeaa2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : critères défavorables mineurs ?","back":"Origine **afro-caribéenne**, atteinte **multiviscérale**, **progression rapide**.","prio":"P3","sec":"s10"},{"id":"fc-p211-0058c7","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : deux situations d'urgence ?","back":"**Hypercalcémie** et **trouble de conduction** cardiaque.","prio":"P2","sec":"s10"},{"id":"fc-p211-9b6b0e","poly":"pneumo","fiche":"p211","front":"Sarcoïdose sans plainte oculaire : faut-il un examen ophtalmologique au bilan initial ?","back":"**Oui**, chez **tous** (bilan systématique) : l'atteinte oculaire, notamment l'**uvéite postérieure**, peut être **latente**.","prio":"P1","sec":"s11"},{"id":"fc-p211-6641b3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : un traitement médicamenteux est-il détaillé dans le chapitre ?","back":"**Non**, aucune molécule n'est précisée.","prio":"P3","sec":"s11"},{"id":"fc-p211-143a41","poly":"pneumo","fiche":"p211","front":"Syndrome de Löfgren : quelle prise en charge thérapeutique ?","back":"**Abstention surveillée** : forme aiguë **favorable sans traitement** (résolution spontanée dans **plus de 90 %** des cas).","prio":"P1","sec":"s12"},{"id":"fc-p211-dae9b4","poly":"pneumo","fiche":"p211","front":"Sarcoïdose de stade I asymptomatique : la biopsie est-elle obligatoire ?","back":"**Non** : elle peut être évitée sous couvert d'une **surveillance spécialisée**.","prio":"P1","sec":"s12"},{"id":"fc-p211-4101b2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose chronique : rythme de suivi ?","back":"Tous les **3 à 6 mois**.","prio":"P2","sec":"s13"},{"id":"fc-p211-1312b5","poly":"pneumo","fiche":"p211","front":"Sarcoïdose chronique : but du suivi ?","back":"Repérer tôt les atteintes menaçant la **vie** (cœur, SNC) ou la **fonction** (fibrose, segment postérieur de l'œil).","prio":"P2","sec":"s13"},{"id":"fc-p211-d0953a","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : biologie de surveillance ?","back":"**ECA**, **hémogramme**, **fonction rénale**, **calcémie**, **enzymes hépatiques**.","prio":"P3","sec":"s13"},{"id":"fc-p211-f68c06","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : examens clés de la surveillance ?","back":"**Radiographie thoracique** + **EFR** (et **ECG**).","prio":"P2","sec":"s16"},{"id":"fc-p211-2d06fc","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : définition de la guérison ?","back":"**Rémission stable** sans traitement pendant **3 ans**.","prio":"P2","sec":"s16"},{"id":"fc-p211-1baad1","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : délai habituel des rechutes ?","back":"**2 à 6 mois** après l'arrêt du traitement ; exceptionnelles après **3 ans** sans traitement.","prio":"P3","sec":"s16"},{"id":"fc-p211-78c30a","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : siège habituel des rechutes ?","back":"Souvent les **mêmes sites** qu'au départ.","prio":"P3","sec":"s16"},{"id":"fc-p211-e5f8e3","poly":"pneumo","fiche":"p211","front":"Sarcoïdose avec trouble du métabolisme calcique : conseil préventif ?","back":"**Déconseiller l'exposition solaire**.","prio":"P2","sec":"s14"},{"id":"fc-p211-c0bccc","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cardiaque suspectée : examens d'exploration ?","back":"**Échographie cardiaque**, **Holter ECG**, **IRM cardiaque**, **TEP-scanner** (protocole cardiaque).","prio":"P2","sec":"s14"},{"id":"fc-p211-e8aa61","poly":"pneumo","fiche":"p211","front":"Sarcoïdose cardiaque : signes d'appel cliniques ?","back":"**Palpitations** soutenues, **malaise**, **syncope**, insuffisance cardiaque (peu spécifiques).","prio":"P3","sec":"s14"},{"id":"fc-p211-5e09bc","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : quels critères rénaux/calciques sont de mauvais pronostic ?","back":"**Hypercalcémie chronique** et **néphrocalcinose**.","prio":"P3","sec":"s14"},{"id":"fc-p211-214e12","poly":"pneumo","fiche":"p211","front":"Neurosarcoïdose : examens d'exploration ?","back":"**IRM**, dosages hormonaux, **ponction lombaire**, EMG.","prio":"P3","sec":"s15"},{"id":"fc-p211-a50bf2","poly":"pneumo","fiche":"p211","front":"Sarcoïdose hépatique : examens d'exploration ?","back":"Enzymes hépatiques, **TP**, **échographie**, **biopsie hépatique**.","prio":"P3","sec":"s15"},{"id":"fc-p211-c39550","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : atteinte oculaire méconnue, risque ?","back":"Baisse **irréversible** de l'acuité visuelle, voire **cécité**.","prio":"P2","sec":"s15"},{"id":"fc-p211-264447","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : atteintes sources de morbidité importante sans menace vitale ?","back":"Atteinte **hépatique**, atteinte **cutanée disgracieuse**.","prio":"P3","sec":"s15"},{"id":"fc-p211-016e5c","poly":"pneumo","fiche":"p211","front":"Adénopathies périphériques sarcoïdiennes : sites superficiels possibles ?","back":"**Cervicales**, **sus-claviculaires**, axillaires, **épitrochléennes**, inguinales.","prio":"P3","sec":"s15"},{"id":"fc-p211-ddf2fc","poly":"pneumo","fiche":"p211","front":"Granulomes : quelle pneumopathie figure à part dans la liste des autres causes de granulomes ?","back":"Les **pneumopathies d'hypersensibilité**.","prio":"P3","sec":"s9"},{"id":"fc-p211-b6c0f1","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : dans quels contextes un amaigrissement est-il possible ?","back":"**Syndrome de Löfgren** ou **formes multiviscérales**.","prio":"P3","sec":"s2"},{"id":"fc-p211-10c244","poly":"pneumo","fiche":"p211","front":"Sarcoïdose : gaz du sang au repos ?","back":"**Longtemps normaux**.","prio":"P3","sec":"s6"},{"id":"fc-p211-35cdf6","poly":"pneumo","fiche":"p211","front":"Adénopathies périphériques de la sarcoïdose : fréquence et explorations ?","back":"**15 %** ; examen clinique, **échographie**, **biopsie ganglionnaire** (site de preuve facile d'accès).","prio":"P3","sec":"s4"},{"id":"fc-p226-dde372","poly":"pneumo","fiche":"p226","front":"MTEV : quelle relation entre TVP et EP ?","back":"**Une même maladie**, deux expressions cliniques : **TVP** et/ou **EP**.","prio":"P1","sec":"s1"},{"id":"fc-p226-d99e23","poly":"pneumo","fiche":"p226","front":"TVP symptomatique : quelle définition ?","back":"Thrombus des **veines profondes des MI** avec symptômes aux jambes et **aucun symptôme thoracique**.","prio":"P2","sec":"s1"},{"id":"fc-p226-42c750","poly":"pneumo","fiche":"p226","front":"TVP proximale : quelles veines sont concernées ?","back":"Veines **poplitées, fémorales et/ou iliaques**.","prio":"P1","sec":"s1"},{"id":"fc-p226-bca925","poly":"pneumo","fiche":"p226","front":"TVP distale : quelle définition ?","back":"Thrombose **sous-poplitée** (veines tibiales et péronières).","prio":"P1","sec":"s1"},{"id":"fc-p226-57d8bf","poly":"pneumo","fiche":"p226","front":"EP symptomatique : quelle définition ?","back":"Thrombus des **artères pulmonaires** avec **symptômes thoraciques**, avec ou sans TVP prouvée.","prio":"P2","sec":"s1"},{"id":"fc-p226-5f2461","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quelle définition ?","back":"EP avec **état de choc**.","prio":"P1","sec":"s1"},{"id":"fc-p226-a73584","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quelle fréquence parmi les EP ?","back":"**5 %** (forme rare).","prio":"P1","sec":"s1"},{"id":"fc-p226-8a3f8c","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quelle mortalité ?","back":"**25 à 50 %** (points clés) ; **> 25 %** dans la stratification en 4 stades.","prio":"P1","sec":"s1"},{"id":"fc-p226-45285c","poly":"pneumo","fiche":"p226","front":"EP sans choc (95 %) : quelle est la principale difficulté ?","back":"**Y penser** (présentation très variable) et **suivre l'algorithme**.","prio":"P2","sec":"s1"},{"id":"fc-p226-636c1d","poly":"pneumo","fiche":"p226","front":"MTEV : dans quelle proportion ne retrouve-t-on aucun facteur de risque ?","back":"**50 %** des cas.","prio":"P1","sec":"s1"},{"id":"fc-p226-785a84","poly":"pneumo","fiche":"p226","front":"MTEV : comment évolue l'incidence avec l'âge ?","back":"Elle **augmente** : **1/100 après 75 ans** vs 1/10 000 avant 40 ans.","prio":"P2","sec":"s1"},{"id":"fc-p226-3dc7cb","poly":"pneumo","fiche":"p226","front":"Tabac et dyslipidémies : sont-ils des facteurs de risque de MTEV ?","back":"**Non**.","prio":"P1","sec":"s1"},{"id":"fc-p226-b5e044","poly":"pneumo","fiche":"p226","front":"MTEV : citer d'autres facteurs de risque reconnus hors tableau majeur/mineur.","back":"**Âge > 65 ans**, **obésité**, **syndrome néphrotique**.","prio":"P2","sec":"s1"},{"id":"fc-p226-96bc97","poly":"pneumo","fiche":"p226","front":"MTEV : citer les facteurs de risque majeurs transitoires (3 derniers mois).","back":"**Chirurgie sous AG > 30 min**, **fracture de MI**, **immobilisation > 3 j** (médical aigu), **facteurs hormonaux**.","prio":"P1","sec":"s1"},{"id":"fc-p226-384ff0","poly":"pneumo","fiche":"p226","front":"MTEV : quels facteurs hormonaux sont des facteurs majeurs transitoires ?","back":"**Contraception œstroprogestative**, **grossesse**, **post-partum**, **THM** (3 derniers mois).","prio":"P1","sec":"s1"},{"id":"fc-p226-01260d","poly":"pneumo","fiche":"p226","front":"MTEV : citer les facteurs de risque majeurs persistants.","back":"**Cancer actif** ; **thrombophilie majeure** (déficit en antithrombine, SAPL).","prio":"P1","sec":"s1"},{"id":"fc-p226-b83246","poly":"pneumo","fiche":"p226","front":"MTEV : citer les facteurs de risque mineurs transitoires.","back":"Traumatisme MI non plâtré (mobilité réduite ≥ 3 j), chirurgie AG < 30 min, immobilisation < 3 j (2 derniers mois), **voyage > 6 h**.","prio":"P2","sec":"s1"},{"id":"fc-p226-c91454","poly":"pneumo","fiche":"p226","front":"MTEV : citer les facteurs de risque mineurs persistants.","back":"**MICI** ou rhumatisme inflammatoire ; **thrombophilie non majeure** (protéine C/S, Leiden, prothrombine).","prio":"P2","sec":"s1"},{"id":"fc-p226-595e7e","poly":"pneumo","fiche":"p226","front":"Thrombophilies majeures : lesquelles ?","back":"**Déficit en antithrombine** et **SAPL**.","prio":"P1","sec":"s1"},{"id":"fc-p226-2ad64a","poly":"pneumo","fiche":"p226","front":"Déficit en protéine C ou S, mutation Leiden ou prothrombine : quel poids comme facteur de risque ?","back":"Thrombophilie **non majeure** = facteur **mineur**.","prio":"P1","sec":"s1"},{"id":"fc-p226-357bdc","poly":"pneumo","fiche":"p226","front":"Facteur de risque majeur vs mineur : quel impact sur la durée d'anticoagulation ?","back":"Majeur : **décisif** (arrêt ou prolongation) ; mineur : pèse **peu** ou effet non démontré.","prio":"P2","sec":"s1"},{"id":"fc-p226-2bcbbf","poly":"pneumo","fiche":"p226","front":"MTEV avec facteur majeur transitoire : quel risque de récidive à l'arrêt ?","back":"**Faible**.","prio":"P1","sec":"s1"},{"id":"fc-p226-844291","poly":"pneumo","fiche":"p226","front":"MTEV non provoquée ou avec facteur majeur persistant : quel risque de récidive à l'arrêt ?","back":"**Élevé**.","prio":"P1","sec":"s1"},{"id":"fc-p226-dda0d6","poly":"pneumo","fiche":"p226","front":"Thrombose veineuse : quels mécanismes y prédisposent ?","back":"**Stase veineuse** et **lésions endothéliales**.","prio":"P2","sec":"s2"},{"id":"fc-p226-19d6e1","poly":"pneumo","fiche":"p226","front":"EP : d'où viennent la plupart des thrombi ?","back":"Des **veines profondes des membres inférieurs et du pelvis**.","prio":"P2","sec":"s2"},{"id":"fc-p226-3b3d3e","poly":"pneumo","fiche":"p226","front":"EP : quelle est la conséquence initiale sur le ventricule droit ?","back":"Hausse de la **PAP** et de la **post-charge du VD** : dilatation, travail et consommation d'O₂ accrus.","prio":"P2","sec":"s2"},{"id":"fc-p226-2c1d66","poly":"pneumo","fiche":"p226","front":"EP grave : comment aboutit-on à l'état de choc ?","back":"**Ischémie du VD**, VD qui **comprime le VG** (précharge VG ↓) → **bas débit**, hypotension, choc.","prio":"P2","sec":"s2"},{"id":"fc-p226-6ff748","poly":"pneumo","fiche":"p226","front":"EP : de quoi dépend la tolérance hémodynamique ?","back":"Importance de l'**obstruction** (seuil 50-60 % chez le sain) et **état cardiovasculaire antérieur**.","prio":"P3","sec":"s2"},{"id":"fc-p226-da3b9a","poly":"pneumo","fiche":"p226","front":"EP : quel est le principal mécanisme de l'hypoxémie ?","back":"L'**effet shunt** (redistribution de la perfusion, VA/Q abaissé).","prio":"P2","sec":"s2"},{"id":"fc-p226-adad83","poly":"pneumo","fiche":"p226","front":"EP : quelles autres causes d'hypoxémie que l'effet shunt ?","back":"Shunt droit-gauche par **foramen ovale** réouvert, trouble de **diffusion**, baisse de la **SvO₂** (EP grave).","prio":"P3","sec":"s2"},{"id":"fc-p226-eb255c","poly":"pneumo","fiche":"p226","front":"EP : quel effet ventilatoire survient en premier ?","back":"Un **effet espace mort** (territoires ventilés non perfusés).","prio":"P3","sec":"s2"},{"id":"fc-p226-faa31c","poly":"pneumo","fiche":"p226","front":"MTEV : quelle part des patients a une thrombophilie héréditaire ?","back":"**Un quart**.","prio":"P3","sec":"s2"},{"id":"fc-p226-6cee29","poly":"pneumo","fiche":"p226","front":"Thrombophilies héréditaires : quels deux mécanismes ?","back":"**Défaut d'anticoagulation** (protéine C, S, antithrombine) ; **excès de procoagulants** (Leiden, G20210A prothrombine).","prio":"P2","sec":"s2"},{"id":"fc-p226-eea4f9","poly":"pneumo","fiche":"p226","front":"Thrombophilies héréditaires : laquelle a un impact clinique important ?","back":"Le **déficit en antithrombine** (les autres : impact faible).","prio":"P2","sec":"s2"},{"id":"fc-p226-299308","poly":"pneumo","fiche":"p226","front":"ATCD familial de MTEV sans thrombophilie retrouvée : comment le considérer ?","back":"Comme un **marqueur** de thrombophilie héréditaire.","prio":"P3","sec":"s2"},{"id":"fc-p226-627e82","poly":"pneumo","fiche":"p226","front":"Diagnostic d'EP : quelles sont les 3 étapes incontournables ?","back":"**Suspecter**, **estimer la probabilité clinique**, **examen adapté à la PC**.","prio":"P1","sec":"s3"},{"id":"fc-p226-865103","poly":"pneumo","fiche":"p226","front":"Diagnostic d'EP : dans quel délai et comment le poser ?","back":"**Dans les 24 h**, avec certitude, en **combinant PC et examens** (aucun examen ne suffit seul).","prio":"P1","sec":"s3"},{"id":"fc-p226-127924","poly":"pneumo","fiche":"p226","front":"EP : quelle douleur thoracique typique ?","back":"Douleur de type **pleural**, parfois avec petites **hémoptysies** rouge foncé.","prio":"P1","sec":"s3"},{"id":"fc-p226-0ca8bc","poly":"pneumo","fiche":"p226","front":"EP : quelles caractéristiques de la dyspnée ?","back":"Souvent **brutale** et **inexpliquée**, parfois progressive ; auscultation souvent **normale**.","prio":"P1","sec":"s3"},{"id":"fc-p226-7f41af","poly":"pneumo","fiche":"p226","front":"EP : quel signe d'examen est constant ?","back":"La **tachypnée** (tachycardie moins constante).","prio":"P1","sec":"s3"},{"id":"fc-p226-2319e6","poly":"pneumo","fiche":"p226","front":"EP : quels signes d'insuffisance cardiaque droite aiguë ?","back":"**Turgescence jugulaire**, **reflux hépato-jugulaire**, **sans œdème des MI**.","prio":"P2","sec":"s3"},{"id":"fc-p226-ac2f5b","poly":"pneumo","fiche":"p226","front":"EP : un examen clinique normal permet-il de l'écarter ?","back":"**Non** (signes inconstants et non spécifiques).","prio":"P1","sec":"s3"},{"id":"fc-p226-c16167","poly":"pneumo","fiche":"p226","front":"EP : que peut montrer la radiographie de thorax ?","back":"Normale ou : **atélectasie en bande**, épanchement pleural, coupole surélevée, **infarctus pulmonaire**, hyperclarté.","prio":"P2","sec":"s3"},{"id":"fc-p226-14e3ad","poly":"pneumo","fiche":"p226","front":"EP : quels diagnostics différentiels la radiographie de thorax écarte-t-elle ?","back":"**Pneumonie**, **pneumothorax**, **fracture de côte**.","prio":"P1","sec":"s3"},{"id":"fc-p226-d108ac","poly":"pneumo","fiche":"p226","front":"EP : quels signes ECG droits ?","back":"**S1Q3**, **bloc de branche droit**, **T négatives de V1 à V3** ; souvent tachycardie.","prio":"P1","sec":"s3"},{"id":"fc-p226-78ce37","poly":"pneumo","fiche":"p226","front":"EP : quels diagnostics différentiels l'ECG écarte-t-il ?","back":"**Infarctus du myocarde**, **péricardite aiguë**.","prio":"P1","sec":"s3"},{"id":"fc-p226-17ae03","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP : faut-il faire des gaz du sang ?","back":"**Non** : ni sensibles ni spécifiques, potentiellement **dangereux** si thrombolyse.","prio":"P1","sec":"s3"},{"id":"fc-p226-795f91","poly":"pneumo","fiche":"p226","front":"Radiographie et ECG dans l'EP : quel est leur intérêt ?","back":"Ni sensibles ni spécifiques, mais indispensables pour **écarter les diagnostics différentiels**.","prio":"P2","sec":"s3"},{"id":"fc-p226-5a9c84","poly":"pneumo","fiche":"p226","front":"TVP : quels signes cliniques du score de probabilité ?","back":"**Douleur trajet veineux**, **œdème de tout le MI**, **mollet > 3 cm**, **godet**, **circulation collatérale**.","prio":"P2","sec":"s3"},{"id":"fc-p226-20af80","poly":"pneumo","fiche":"p226","front":"Forme sévère de TVP : comment s'appelle-t-elle ?","back":"**Phlegmatia cerulea** (phlébite bleue).","prio":"P2","sec":"s3"},{"id":"fc-p226-8f04ca","poly":"pneumo","fiche":"p226","front":"EP sans instabilité hémodynamique : quelle est l'étape la plus importante ?","back":"L'estimation de la **probabilité clinique**.","prio":"P1","sec":"s4"},{"id":"fc-p226-bae7b4","poly":"pneumo","fiche":"p226","front":"Probabilité clinique d'EP : quelles 3 classes et quelles prévalences ?","back":"**Faible < 10 %** ; **intermédiaire 30-40 %** ; **forte > 70 %**.","prio":"P1","sec":"s4"},{"id":"fc-p226-c81e24","poly":"pneumo","fiche":"p226","front":"Probabilité clinique d'EP : quels types de scores ?","back":"Score **implicite** (empirique) et scores **explicites** (**Wells**, **Genève**), aussi performants.","prio":"P2","sec":"s4"},{"id":"fc-p226-71960e","poly":"pneumo","fiche":"p226","front":"Score implicite d'EP : quels 3 éléments ?","back":"**Signes évocateurs**, **facteur(s) de risque**, **absence de diagnostic alternatif** (1 point chacun).","prio":"P2","sec":"s4"},{"id":"fc-p226-11249f","poly":"pneumo","fiche":"p226","front":"Score de Wells : quels items valent 3 points ?","back":"**Signes de TVP** et **diagnostic alternatif moins probable** que l'EP.","prio":"P3","sec":"s4"},{"id":"fc-p226-bd9c37","poly":"pneumo","fiche":"p226","front":"Score de Genève simplifié : quels items sont absents du score de Wells ?","back":"**Âge > 65 ans** et **douleur spontanée du mollet**.","prio":"P3","sec":"s4"},{"id":"fc-p226-7cbc48","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP sans choc, PC faible ou intermédiaire : quel premier examen ?","back":"**D-dimères**.","prio":"P1","sec":"s4"},{"id":"fc-p226-1bdff3","poly":"pneumo","fiche":"p226","front":"PC non forte et D-dimères négatifs : quelle conduite ?","back":"**EP exclue**, pas de traitement.","prio":"P1","sec":"s4"},{"id":"fc-p226-0c2389","poly":"pneumo","fiche":"p226","front":"PC non forte et D-dimères positifs : quel examen ?","back":"**Angioscanner thoracique**.","prio":"P1","sec":"s4"},{"id":"fc-p226-8595cb","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP avec PC forte : quel examen ?","back":"**Angioscanner d'emblée**, **sans D-dimères**.","prio":"P1","sec":"s4"},{"id":"fc-p226-e6a199","poly":"pneumo","fiche":"p226","front":"PC forte : pourquoi ne pas doser les D-dimères ?","back":"Risque de **faux négatif**.","prio":"P1","sec":"s4"},{"id":"fc-p226-b67e66","poly":"pneumo","fiche":"p226","front":"Angioscanner négatif avec PC forte : quelle conduite ?","back":"**Ne pas conclure** : 2e lecture ± **écho-Doppler** et/ou **scintigraphie**.","prio":"P1","sec":"s4"},{"id":"fc-p226-a561fb","poly":"pneumo","fiche":"p226","front":"Angioscanner non conclusif : quelle définition ?","back":"Qualité insuffisante pour analyser jusqu'au niveau **sous-segmentaire**.","prio":"P3","sec":"s4"},{"id":"fc-p226-1b2cc2","poly":"pneumo","fiche":"p226","front":"Angioscanner contre-indiqué : quels examens alternatifs ?","back":"**Écho-Doppler veineux** et/ou **scintigraphie V/Q**.","prio":"P2","sec":"s4"},{"id":"fc-p226-a607ce","poly":"pneumo","fiche":"p226","front":"D-dimères : de quoi s'agit-il ?","back":"Des **produits de dégradation de la fibrine**.","prio":"P2","sec":"s4"},{"id":"fc-p226-d959c4","poly":"pneumo","fiche":"p226","front":"D-dimères : quelle sensibilité et quelle valeur d'un test négatif ?","back":"**≥ 96 %** : négatifs, ils **excluent** l'EP (et la TVP) si la PC **n'est pas forte**.","prio":"P1","sec":"s4"},{"id":"fc-p226-ebcec7","poly":"pneumo","fiche":"p226","front":"D-dimères positifs : quelle valeur diagnostique ?","back":"**Aucune** (non spécifiques).","prio":"P1","sec":"s4"},{"id":"fc-p226-feb49b","poly":"pneumo","fiche":"p226","front":"D-dimères : quel seuil de négativité avant 50 ans ?","back":"**< 500 µg/L**.","prio":"P1","sec":"s4"},{"id":"fc-p226-1bbe2d","poly":"pneumo","fiche":"p226","front":"D-dimères : quel seuil de négativité à partir de 50 ans ?","back":"**< âge × 10 µg/L** (ex. 78 ans → 780).","prio":"P1","sec":"s4"},{"id":"fc-p226-64db34","poly":"pneumo","fiche":"p226","front":"D-dimères : citer des situations où ils s'élèvent hors MTEV.","back":"**Cancer**, **infections**, **dissection aortique**, **grossesse**… (sensibilité conservée).","prio":"P2","sec":"s4"},{"id":"fc-p226-f14661","poly":"pneumo","fiche":"p226","front":"D-dimères : dans quelle situation thérapeutique sont-ils moins interprétables ?","back":"Sous **anticoagulant curatif**.","prio":"P2","sec":"s4"},{"id":"fc-p226-94aea7","poly":"pneumo","fiche":"p226","front":"D-dimères chez le sujet âgé ou la femme enceinte : sont-ils utiles ?","back":"**Oui**, sensibilité **inchangée** : à doser si PC non forte.","prio":"P2","sec":"s4"},{"id":"fc-p226-fba53b","poly":"pneumo","fiche":"p226","front":"Angioscanner thoracique : quel critère diagnostique d'EP ?","back":"**Lacune endovasculaire** ou absence d'opacification d'une artère **segmentaire ou plus proximale**.","prio":"P2","sec":"s5"},{"id":"fc-p226-09d26e","poly":"pneumo","fiche":"p226","front":"Angioscanner positif : quelle conclusion ?","back":"**EP confirmée quelle que soit la PC** (très spécifique).","prio":"P1","sec":"s5"},{"id":"fc-p226-b2bef1","poly":"pneumo","fiche":"p226","front":"Angioscanner négatif : quelle conclusion ?","back":"**EP exclue sauf si PC forte** (modérément sensible).","prio":"P1","sec":"s5"},{"id":"fc-p226-33136e","poly":"pneumo","fiche":"p226","front":"Angioscanner : quelles contre-indications ?","back":"**Allergie aux produits iodés**, **insuffisance rénale sévère**.","prio":"P1","sec":"s5"},{"id":"fc-p226-fb4a14","poly":"pneumo","fiche":"p226","front":"Scintigraphie V/Q planaire normale : quelle conclusion ?","back":"**EP exclue quelle que soit la PC** (sensibilité 100 %).","prio":"P1","sec":"s5"},{"id":"fc-p226-6416ba","poly":"pneumo","fiche":"p226","front":"Scintigraphie V/Q de haute probabilité : quelle définition ?","back":"**≥ 2 défects segmentaires de perfusion** sans défect ventilatoire en regard (**mismatch**).","prio":"P2","sec":"s5"},{"id":"fc-p226-db41b8","poly":"pneumo","fiche":"p226","front":"Scintigraphie de haute probabilité : quand confirme-t-elle l'EP ?","back":"Si **PC forte ou intermédiaire** (non conclusive si PC faible).","prio":"P1","sec":"s5"},{"id":"fc-p226-df013e","poly":"pneumo","fiche":"p226","front":"Scintigraphie V/Q de probabilité non haute : quelle valeur ?","back":"**Non conclusive**.","prio":"P2","sec":"s5"},{"id":"fc-p226-bc023c","poly":"pneumo","fiche":"p226","front":"Tomoscintigraphie (SPECT) : quelle valeur d'un résultat négatif ou positif ?","back":"Négative : **EP exclue** ; positive (1 défect segmentaire ou 2 sous-segmentaires) : **EP confirmée**.","prio":"P2","sec":"s5"},{"id":"fc-p226-6e6f37","poly":"pneumo","fiche":"p226","front":"Scintigraphie pulmonaire dans l'EP : quelles indications ?","back":"Angioscanner **contre-indiqué** ou difficile à obtenir ; **forte suspicion avec angioscanner négatif**.","prio":"P2","sec":"s5"},{"id":"fc-p226-ac099b","poly":"pneumo","fiche":"p226","front":"Écho-Doppler veineux : quel critère de TVP ?","back":"**Veine profonde incompressible**.","prio":"P1","sec":"s5"},{"id":"fc-p226-54df31","poly":"pneumo","fiche":"p226","front":"Suspect d'EP avec TVP proximale à l'écho-Doppler : quelle conclusion ?","back":"**EP confirmée quelle que soit la PC**, sans autre imagerie.","prio":"P1","sec":"s5"},{"id":"fc-p226-f3f8ea","poly":"pneumo","fiche":"p226","front":"Suspect d'EP avec TVP distale à l'écho-Doppler : quelle conclusion ?","back":"**Insuffisant** pour confirmer l'EP : autres tests.","prio":"P1","sec":"s5"},{"id":"fc-p226-b04cb8","poly":"pneumo","fiche":"p226","front":"Écho-Doppler veineux normal chez un suspect d'EP : quelle conclusion ?","back":"**N'exclut pas** l'EP (non sensible).","prio":"P1","sec":"s5"},{"id":"fc-p226-d9a4f2","poly":"pneumo","fiche":"p226","front":"Diagnostic de TVP : quelle démarche ?","back":"Mêmes principes que l'EP : **PC**, puis **D-dimères** et **échographie veineuse**.","prio":"P2","sec":"s6"},{"id":"fc-p226-fadf6c","poly":"pneumo","fiche":"p226","front":"Score de probabilité de TVP : quel seuil de TVP probable ?","back":"Score **≥ 2** (< 2 = probabilité faible).","prio":"P2","sec":"s6"},{"id":"fc-p226-a00211","poly":"pneumo","fiche":"p226","front":"Score de TVP : quel item retire 2 points ?","back":"**Diagnostic alternatif au moins aussi probable** que la TVP.","prio":"P3","sec":"s6"},{"id":"fc-p226-3a2735","poly":"pneumo","fiche":"p226","front":"Score de TVP : quels items de terrain rapportent 1 point ?","back":"**Cancer actif**, paralysie/parésie/**plâtre** du MI, **alitement > 3 j** ou chirurgie majeure < 4 semaines.","prio":"P3","sec":"s6"},{"id":"fc-p226-dcbd32","poly":"pneumo","fiche":"p226","front":"Suspicion de TVP à PC faible : quel premier examen ?","back":"**D-dimères** (négatifs : pas de traitement ; positifs : échographie).","prio":"P1","sec":"s6"},{"id":"fc-p226-588abe","poly":"pneumo","fiche":"p226","front":"Suspicion de TVP à PC forte : quel examen ?","back":"**Échographie veineuse d'emblée**.","prio":"P1","sec":"s6"},{"id":"fc-p226-69fd4a","poly":"pneumo","fiche":"p226","front":"TVP à PC forte avec échographie négative : quelle conduite ?","back":"**Répéter l'échographie 7 jours plus tard**.","prio":"P2","sec":"s6"},{"id":"fc-p226-0fe5b7","poly":"pneumo","fiche":"p226","front":"Grossesse et suspicion d'EP : quel score de probabilité ?","back":"Le score de **Genève** (validé pendant la grossesse).","prio":"P2","sec":"s6"},{"id":"fc-p226-1208c2","poly":"pneumo","fiche":"p226","front":"Grossesse, D-dimères positifs ou PC forte : quel premier examen d'imagerie ?","back":"**Écho-Doppler veineux**.","prio":"P2","sec":"s6"},{"id":"fc-p226-4f6c80","poly":"pneumo","fiche":"p226","front":"Grossesse, écho-Doppler négatif : quel examen d'imagerie pulmonaire ?","back":"**Scintigraphie de perfusion** en 1re intention si disponible, sinon **angioscanner**.","prio":"P2","sec":"s6"},{"id":"fc-p226-334ae2","poly":"pneumo","fiche":"p226","front":"Grossesse : l'irradiation fœtale par l'imagerie de l'EP est-elle dangereuse ?","back":"Elle reste **très en dessous du seuil toxique**.","prio":"P3","sec":"s6"},{"id":"fc-p226-75dc59","poly":"pneumo","fiche":"p226","front":"Scanner injecté pendant la grossesse : quelle surveillance du nouveau-né ?","back":"Doser les **hormones thyroïdiennes** à la naissance.","prio":"P2","sec":"s6"},{"id":"fc-p226-8ed490","poly":"pneumo","fiche":"p226","front":"MTEV pendant la grossesse : quel traitement ?","back":"**HBPM pendant toute la grossesse**.","prio":"P1","sec":"s6"},{"id":"fc-p226-51dfde","poly":"pneumo","fiche":"p226","front":"État de choc dans l'EP : quelle définition ?","back":"**PAS < 90 mmHg** ou chute de PAS **> 40 mmHg** pendant **≥ 15 min**.","prio":"P1","sec":"s7"},{"id":"fc-p226-19e221","poly":"pneumo","fiche":"p226","front":"EP avec choc : l'algorithme PC/D-dimères/angioscanner s'applique-t-il ?","back":"**Non** : il vaut en l'absence d'instabilité ; démarche différente devant un choc.","prio":"P1","sec":"s7"},{"id":"fc-p226-76be22","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP grave avec angioscanner immédiatement réalisable : quelle conduite ?","back":"**Angioscanner** (si patient stabilisé) : positif → traitement (± thrombolyse) ; négatif → autre cause.","prio":"P1","sec":"s7"},{"id":"fc-p226-c0d2f9","poly":"pneumo","fiche":"p226","front":"Échographie cardiaque transthoracique dans l'EP : quand en 1re intention ?","back":"**Seulement** si suspicion d'**EP grave** avec scanner non accessible ou patient **intransportable**.","prio":"P1","sec":"s7"},{"id":"fc-p226-40ad58","poly":"pneumo","fiche":"p226","front":"ETT dans la suspicion d'EP grave : quels diagnostics alternatifs écarte-t-elle ?","back":"**Tamponnade**, **dissection aortique**, **infarctus du VD**.","prio":"P1","sec":"s7"},{"id":"fc-p226-1ef963","poly":"pneumo","fiche":"p226","front":"ETT dans l'EP grave : quels signes indirects confirment l'EP ?","back":"**Dilatation du VD**, **septum paradoxal** (patient grave, non transportable, PC forte).","prio":"P1","sec":"s7"},{"id":"fc-p226-e3629e","poly":"pneumo","fiche":"p226","front":"ETT dans l'EP grave : quels signes directs ?","back":"**Thrombus** dans les cavités droites ou le tronc de l'AP (exceptionnellement vus en ETT).","prio":"P2","sec":"s7"},{"id":"fc-p226-46d379","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP grave, ETT sans dilatation des cavités droites : quelle conduite ?","back":"**Rechercher une autre cause** (thrombolyse non nécessaire).","prio":"P1","sec":"s7"},{"id":"fc-p226-3580b1","poly":"pneumo","fiche":"p226","front":"Suspicion d'EP grave, VD dilaté, patient instable sans autre test : quelle conduite ?","back":"**Traiter l'EP** (considérer thrombolyse / embolectomie).","prio":"P1","sec":"s7"},{"id":"fc-p226-79e360","poly":"pneumo","fiche":"p226","front":"Pronostic de l'EP : quels paramètres cliniques ?","back":"**Pression artérielle** (choc) et score **sPESI**.","prio":"P1","sec":"s8"},{"id":"fc-p226-f26ea9","poly":"pneumo","fiche":"p226","front":"Pronostic de l'EP : quels paramètres paracliniques ?","back":"**Dysfonction du VD** et **biomarqueurs** (troponine I/T, NT-proBNP/BNP).","prio":"P1","sec":"s8"},{"id":"fc-p226-05ac7a","poly":"pneumo","fiche":"p226","front":"Dysfonction du VD dans l'EP : quels critères ?","back":"Rapport **VD/VG > 0,9**, **hypokinésie du VD**.","prio":"P1","sec":"s8"},{"id":"fc-p226-d799cf","poly":"pneumo","fiche":"p226","front":"Complications de la MTEV : citer les séquelles.","back":"**Syndrome post-thrombotique** (TVP) ; **HTP thrombo-embolique chronique** (EP).","prio":"P2","sec":"s8"},{"id":"fc-p226-f43f46","poly":"pneumo","fiche":"p226","front":"EP à risque faible : quel critère et quelle mortalité ?","back":"**sPESI = 0** ; mortalité **1 %**.","prio":"P2","sec":"s8"},{"id":"fc-p226-757eb0","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-faible : quelle définition ?","back":"sPESI ≥ 1 avec dysfonction VD **ou** biomarqueurs élevés, **ou aucun** des deux.","prio":"P2","sec":"s8"},{"id":"fc-p226-b525ea","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé : quelle définition ?","back":"sPESI ≥ 1 avec dysfonction VD **ET** biomarqueurs élevés.","prio":"P2","sec":"s8"},{"id":"fc-p226-2ed1f7","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire : quelle mortalité ?","back":"**3 à 25 %**.","prio":"P3","sec":"s8"},{"id":"fc-p226-64bc9b","poly":"pneumo","fiche":"p226","front":"Score sPESI : quels items ?","back":"**Âge > 80**, **SaO₂ < 90 %**, **PAS < 100**, **FC > 110**, **cancer**, **IC ou IR chronique**.","prio":"P2","sec":"s8"},{"id":"fc-p226-078886","poly":"pneumo","fiche":"p226","front":"Score sPESI : quelle mortalité à 30 jours selon le score ?","back":"0 point : **1 %** ; ≥ 1 point : **11 %**.","prio":"P3","sec":"s8"},{"id":"fc-p226-962d4a","poly":"pneumo","fiche":"p226","front":"EP à faible risque : quelle orientation ?","back":"**Hospitalisation courte (< 24 h)**, sortie précoce envisageable.","prio":"P1","sec":"s8"},{"id":"fc-p226-d014dd","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-faible : où hospitaliser ?","back":"En **service de médecine**.","prio":"P1","sec":"s8"},{"id":"fc-p226-9ab76c","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé ou à haut risque : où hospitaliser ?","back":"Intermédiaire-élevé : **soins intensifs** ; haut risque : **réanimation**.","prio":"P2","sec":"s8"},{"id":"fc-p226-32e242","poly":"pneumo","fiche":"p226","front":"EP à faible risque : que vérifier avant une sortie précoce ?","back":"Diagnostic et traitement, risque de complications, obstacles **psycho-sociaux**, **éducation**, surveillance, **consultation précoce**.","prio":"P2","sec":"s8"},{"id":"fc-p226-88952d","poly":"pneumo","fiche":"p226","front":"TVP : où la majorité des patients est-elle traitée ?","back":"En **ambulatoire**.","prio":"P1","sec":"s8"},{"id":"fc-p226-9c625d","poly":"pneumo","fiche":"p226","front":"EP : qu'est-ce qui ne permet pas de conclure ?","back":"**D-dimères positifs**, **écho-Doppler normal**, **TVP distale**, **scintigraphie non conclusive**.","prio":"P1","sec":"s9"},{"id":"fc-p226-c6bd8c","poly":"pneumo","fiche":"p226","front":"EP et TVP proximale : quand débuter l'anticoagulation ?","back":"**Dès la suspicion**, à dose **curative**, sans attendre les examens (urgence thérapeutique).","prio":"P1","sec":"s10"},{"id":"fc-p226-2e2db7","poly":"pneumo","fiche":"p226","front":"Anticoagulation de la MTEV : quel est son but ?","back":"**Empêcher la récidive**.","prio":"P2","sec":"s10"},{"id":"fc-p226-e92c4a","poly":"pneumo","fiche":"p226","front":"Anticoagulation de la MTEV : de quelle nature sont ses contre-indications ?","back":"Surtout **relatives** : balance **bénéfice-risque** au cas par cas.","prio":"P2","sec":"s10"},{"id":"fc-p226-adaf70","poly":"pneumo","fiche":"p226","front":"Anticoagulation curative : citer des contre-indications.","back":"**Coagulopathie sévère** (plaquettes < 30 000, hémophilie, TP < 30 %), **hémorragie intracrânienne** spontanée, **saignement actif**, chirurgie récente.","prio":"P1","sec":"s10"},{"id":"fc-p226-1408a5","poly":"pneumo","fiche":"p226","front":"Avant anticoagulation curative : quel bilan biologique ?","back":"**Plaquettes, TP, TCA, NFS, créatinine, transaminases** (+ bilan prétransfusionnel si risque hémorragique).","prio":"P1","sec":"s10"},{"id":"fc-p226-4e6199","poly":"pneumo","fiche":"p226","front":"MTEV non grave : quel anticoagulant en 1re intention ?","back":"**AOD anti-Xa** : **rivaroxaban** ou **apixaban**, d'emblée sans héparine.","prio":"P1","sec":"s10"},{"id":"fc-p226-a184f4","poly":"pneumo","fiche":"p226","front":"AOD dans la MTEV : quels avantages par rapport aux AVK ?","back":"Au moins **aussi efficaces** et **plus sûrs** (moins d'hémorragies graves) ; dose fixe, per os.","prio":"P1","sec":"s10"},{"id":"fc-p226-5fe96e","poly":"pneumo","fiche":"p226","front":"MTEV non grave, option 2 : quel schéma anticoagulant ?","back":"**Héparine** (HBPM ou fondaparinux de préférence, ou HNF) avec **relais AVK précoce** débuté simultanément.","prio":"P1","sec":"s10"},{"id":"fc-p226-25607e","poly":"pneumo","fiche":"p226","front":"HBPM et fondaparinux : pourquoi préférés à l'HNF ?","back":"Dose selon le **poids**, voie **SC**, **pas de surveillance** biologique, **moins de TIH**.","prio":"P1","sec":"s10"},{"id":"fc-p226-6b7a8a","poly":"pneumo","fiche":"p226","front":"HBPM et fondaparinux : quelle contre-indication rénale ?","back":"**ClCr < 30 ml/min** (Cockcroft-Gault).","prio":"P1","sec":"s10"},{"id":"fc-p226-d5f60e","poly":"pneumo","fiche":"p226","front":"HBPM et fondaparinux : disposent-ils d'un antidote efficace ?","back":"**Non** (protamine **moins efficace** avec les HBPM).","prio":"P2","sec":"s10"},{"id":"fc-p226-6ae520","poly":"pneumo","fiche":"p226","front":"HNF dans la MTEV : quelles indications ?","back":"**Insuffisance rénale sévère** et **EP avec état de choc**.","prio":"P1","sec":"s10"},{"id":"fc-p226-d79df0","poly":"pneumo","fiche":"p226","front":"HNF : comment adapter la dose ?","back":"**Anti-Xa 0,3 à 0,7 UI/ml** ou **TCA** ratio **1,5 à 2,5**.","prio":"P2","sec":"s10"},{"id":"fc-p226-722c67","poly":"pneumo","fiche":"p226","front":"HNF : quelle surveillance spécifique et pourquoi ?","back":"**Plaquettes 2 fois par semaine** (risque de **TIH**).","prio":"P1","sec":"s10"},{"id":"fc-p226-454cd4","poly":"pneumo","fiche":"p226","front":"HNF : quel antidote ?","back":"**Sulfate de protamine IV**, actif immédiatement.","prio":"P2","sec":"s10"},{"id":"fc-p226-31ccde","poly":"pneumo","fiche":"p226","front":"AOD : quelles contre-indications dans la MTEV ?","back":"**IR sévère**, **instabilité hémodynamique**, **grossesse**, **allaitement**, interactions **CYP3A4/P-gp**.","prio":"P1","sec":"s10"},{"id":"fc-p226-60d58f","poly":"pneumo","fiche":"p226","front":"AOD : citer des médicaments interagissant via CYP3A4/P-gp.","back":"**Rifampicine**, phénobarbital, **azolés**, antiprotéases VIH, anti-tyrosine kinases, **macrolides** (sauf azithromycine).","prio":"P2","sec":"s10"},{"id":"fc-p226-bf8fc4","poly":"pneumo","fiche":"p226","front":"Rivaroxaban et apixaban : quels seuils de contre-indication rénale ?","back":"Rivaroxaban : **ClCr < 30 ml/min** ; apixaban : **< 25 ml/min** (Cockcroft-Gault).","prio":"P1","sec":"s10"},{"id":"fc-p226-d40be4","poly":"pneumo","fiche":"p226","front":"MTEV : quel traitement d'entretien les 3 à 6 premiers mois ?","back":"**AOD ou AVK**.","prio":"P2","sec":"s10"},{"id":"fc-p226-379e66","poly":"pneumo","fiche":"p226","front":"Patient anticoagulé : sur quoi porte l'éducation obligatoire ?","back":"Signes de **récidive** et de **saignement**, **observance**, interactions, **pas d'aspirine ni AINS**, **carte** d'anticoagulant.","prio":"P1","sec":"s10"},{"id":"fc-p226-50bedd","poly":"pneumo","fiche":"p226","front":"TIH : quels anticoagulants restent utilisables ?","back":"**Hirudine**, **AVK**, **danaparoïde sodique**.","prio":"P3","sec":"s10"},{"id":"fc-p226-960de7","poly":"pneumo","fiche":"p226","front":"HBPM, fondaparinux, AOD : faut-il une surveillance biologique de l'effet ?","back":"**Non**.","prio":"P2","sec":"s10"},{"id":"fc-p226-04a4aa","poly":"pneumo","fiche":"p226","front":"HNF, HBPM et fondaparinux : leur efficacité diffère-t-elle ?","back":"**Non**, même efficacité ; pic d'action **1 h** après l'injection.","prio":"P3","sec":"s10"},{"id":"fc-p226-250d23","poly":"pneumo","fiche":"p226","front":"AVK de référence dans la MTEV : lequel ?","back":"La **warfarine**.","prio":"P1","sec":"s11"},{"id":"fc-p226-9d7c98","poly":"pneumo","fiche":"p226","front":"Fluindione : peut-on l'initier ?","back":"**Non**, interdit (réactions **immuno-allergiques** plus fréquentes).","prio":"P1","sec":"s11"},{"id":"fc-p226-5913bd","poly":"pneumo","fiche":"p226","front":"Relais héparine-AVK : quand débuter l'AVK ?","back":"**En même temps que l'héparine** (MTEV non grave).","prio":"P1","sec":"s11"},{"id":"fc-p226-3b9af7","poly":"pneumo","fiche":"p226","front":"Relais héparine-AVK : quand arrêter l'héparine ?","back":"**≥ 5 jours de chevauchement** ET **2 INR entre 2 et 3** à 24 h d'intervalle.","prio":"P1","sec":"s11"},{"id":"fc-p226-6f6e89","poly":"pneumo","fiche":"p226","front":"AVK dans la MTEV : quel INR cible ?","back":"**2 à 3**.","prio":"P1","sec":"s11"},{"id":"fc-p226-d2de5f","poly":"pneumo","fiche":"p226","front":"AVK : citer des facteurs majeurs de saignement.","back":"**Âge > 75 ans**, ATCD d'**hémorragie digestive**, AVC, alcoolisme, diabète, **antiagrégant**, IR, AVK mal équilibré.","prio":"P2","sec":"s11"},{"id":"fc-p226-11dffd","poly":"pneumo","fiche":"p226","front":"AVK : quels inconvénients par rapport aux AOD ?","back":"**INR répétés**, **interactions**, **marge étroite**, **hémorragies plus fréquentes**.","prio":"P2","sec":"s11"},{"id":"fc-p226-5fef8e","poly":"pneumo","fiche":"p226","front":"AVK : faut-il un régime alimentaire particulier ?","back":"**Non**.","prio":"P2","sec":"s11"},{"id":"fc-p226-d47401","poly":"pneumo","fiche":"p226","front":"TVP : quels critères d'hospitalisation ?","back":"TVP **sous anticoagulant**, **IR sévère**, comorbidité (cancer, > 75 ans…), **phlegmatia cerulea** ou **bilatérale**, saignement, suivi impossible.","prio":"P1","sec":"s12"},{"id":"fc-p226-c7db05","poly":"pneumo","fiche":"p226","front":"Compression veineuse élastique : quelle indication et quelle durée ?","back":"**TVP** (isolée ou avec EP), pendant **au moins 6 mois**.","prio":"P1","sec":"s12"},{"id":"fc-p226-a05c07","poly":"pneumo","fiche":"p226","front":"Compression veineuse élastique : quelle contre-indication ?","back":"**Artériopathie oblitérante des membres inférieurs**.","prio":"P1","sec":"s12"},{"id":"fc-p226-65982f","poly":"pneumo","fiche":"p226","front":"TVP proximale vs EP : la durée d'anticoagulation diffère-t-elle ?","back":"**Non**, elle est **identique**.","prio":"P2","sec":"s12"},{"id":"fc-p226-9f1795","poly":"pneumo","fiche":"p226","front":"EP à faible risque : quand lever le patient ?","back":"**Lever précoce 1 heure** après le début de l'anticoagulant.","prio":"P2","sec":"s13"},{"id":"fc-p226-d23fbd","poly":"pneumo","fiche":"p226","front":"EP à risque faible ou intermédiaire-faible : quel anticoagulant ?","back":"**AOD** en 1re intention (ou HBPM/fondaparinux + AVK).","prio":"P1","sec":"s13"},{"id":"fc-p226-152576","poly":"pneumo","fiche":"p226","front":"EP à faible risque : que vérifie la consultation précoce programmée avant la sortie ?","back":"L'**observance**, l'**efficacité** et la **tolérance** de l'anticoagulant.","prio":"P2","sec":"s13"},{"id":"fc-p226-f242a1","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé : quel anticoagulant les 48-72 premières heures ?","back":"**HBPM SC** (HNF IVSE si CI) ; **pas d'AOD d'emblée** ni relais AVK précoce.","prio":"P2","sec":"s14"},{"id":"fc-p226-a9ef60","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé : quand faire le relais oral ?","back":"À **48-72 h**, après amélioration, par **AVK ou AOD**.","prio":"P3","sec":"s14"},{"id":"fc-p226-8eb2a1","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé : quelle place pour la thrombolyse ?","back":"**2e intention**, si évolution vers l'**état de choc**.","prio":"P2","sec":"s14"},{"id":"fc-p226-99ab30","poly":"pneumo","fiche":"p226","front":"EP à risque intermédiaire-élevé : quelles mesures associées ?","back":"**Oxygénothérapie** et **repos au lit**, monitoring en soins intensifs.","prio":"P3","sec":"s14"},{"id":"fc-p226-c718dc","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quel anticoagulant ?","back":"**HNF IVSE** à dose curative.","prio":"P2","sec":"s15"},{"id":"fc-p226-593f36","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quelle place pour la thrombolyse ?","back":"**D'emblée (1re intention)**, toujours associée à une **anticoagulation efficace**.","prio":"P1","sec":"s15"},{"id":"fc-p226-6e986b","poly":"pneumo","fiche":"p226","front":"Thrombolyse : quel est son avantage ?","back":"**Désobstruction plus rapide** des artères pulmonaires.","prio":"P3","sec":"s15"},{"id":"fc-p226-927009","poly":"pneumo","fiche":"p226","front":"Thrombolyse : quel risque majeur et quelles contre-indications ?","back":"**Hémorragie grave**, notamment intracrânienne (**2 %**) ; CI **relatives** sauf **hémorragie intracérébrale**.","prio":"P2","sec":"s15"},{"id":"fc-p226-134b46","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quand discuter l'embolectomie ?","back":"**Échec de la thrombolyse** ou **CI absolue** ; technique d'exception, centre expert.","prio":"P2","sec":"s15"},{"id":"fc-p226-3c4aeb","poly":"pneumo","fiche":"p226","front":"EP à haut risque : quelles mesures symptomatiques ?","back":"**Oxygène** voire ventilation, **correction du choc**, **repos strict au lit**.","prio":"P2","sec":"s15"},{"id":"fc-p226-2eb2ea","poly":"pneumo","fiche":"p226","front":"EP avec choc : pourquoi éviter HBPM et fondaparinux ?","back":"**Résorption sous-cutanée aléatoire** en cas de choc.","prio":"P2","sec":"s15"},{"id":"fc-p226-380a8d","poly":"pneumo","fiche":"p226","front":"MTEV et IR sévère (ClCr < 30) : quel anticoagulant ?","back":"**HNF** avec relais par **AVK** (AOD, HBPM, fondaparinux contre-indiqués).","prio":"P1","sec":"s16"},{"id":"fc-p226-6a7a6c","poly":"pneumo","fiche":"p226","front":"TVP et insuffisance rénale sévère : traitement ambulatoire possible ?","back":"**Non** : **hospitalisation**.","prio":"P2","sec":"s16"},{"id":"fc-p226-83acd9","poly":"pneumo","fiche":"p226","front":"Grossesse et allaitement : les AOD sont-ils autorisés ?","back":"**Non**, contre-indiqués.","prio":"P1","sec":"s17"},{"id":"fc-p226-83ba92","poly":"pneumo","fiche":"p226","front":"MTEV sous pilule œstroprogestative : comment l'arrêter ?","back":"**Sans urgence** : finir la plaquette.","prio":"P1","sec":"s17"},{"id":"fc-p226-ddbc3f","poly":"pneumo","fiche":"p226","front":"Après MTEV sous œstroprogestatif : quelles contraceptions proposer ?","back":"**Non thrombogènes** : microprogestatif oral, implant ou stérilet à la progestérone, **stérilet au cuivre**.","prio":"P1","sec":"s17"},{"id":"fc-p226-b78944","poly":"pneumo","fiche":"p226","front":"Contraception œstroprogestative : quelles CI liées à la MTEV ?","back":"**ATCD personnel de MTEV**, **thrombophilie** (génétique ou SAPL), **parent 1er degré** avec MTEV non provoquée < 50 ans.","prio":"P1","sec":"s17"},{"id":"fc-p226-d3d738","poly":"pneumo","fiche":"p226","front":"MTEV et cancer : quel anticoagulant les 3 à 6 premiers mois ?","back":"**HBPM** ou **apixaban** en 1re intention.","prio":"P2","sec":"s18"},{"id":"fc-p226-7039c0","poly":"pneumo","fiche":"p226","front":"MTEV et cancer, 3 à 6 premiers mois : HBPM ou AVK, lesquels sont plus efficaces ?","back":"Les **HBPM** (l'apixaban est **non inférieur** aux HBPM en efficacité et sécurité).","prio":"P3","sec":"s18"},{"id":"fc-p226-8a6e75","poly":"pneumo","fiche":"p226","front":"MTEV et cancer : quelle place pour le rivaroxaban ?","back":"**2e intention**, si **pas de cancer digestif ou uro-génital**.","prio":"P3","sec":"s18"},{"id":"fc-p226-922d64","poly":"pneumo","fiche":"p226","front":"MTEV et cancer : quand utiliser les AVK ?","back":"Si **HBPM et AOD sont contre-indiqués** (IR sévère).","prio":"P3","sec":"s18"},{"id":"fc-p226-5dbab0","poly":"pneumo","fiche":"p226","front":"MTEV et cancer : combien de temps anticoaguler ?","back":"Au-delà de 6 mois, **tant que le cancer est actif ou traité** (durée non limitée).","prio":"P2","sec":"s18"},{"id":"fc-p226-e11101","poly":"pneumo","fiche":"p226","front":"MTEV et cancer sous HBPM : conduite si plaquettes < 30 G/L après chimiothérapie ?","back":"**Arrêt de l'HBPM**, reprise au-dessus de **30 G/L**.","prio":"P3","sec":"s18"},{"id":"fc-p226-488bae","poly":"pneumo","fiche":"p226","front":"Thrombose veineuse superficielle : quel examen indispensable et pourquoi ?","back":"**Écho-Doppler veineux** : TVP associée dans **5 %** des cas.","prio":"P2","sec":"s19"},{"id":"fc-p226-be7532","poly":"pneumo","fiche":"p226","front":"TVS isolée : quand traiter par anticoagulant et comment ?","back":"Si **> 5 cm** et à **> 3 cm de la jonction saphéno-fémorale** : **fondaparinux préventif 45 jours**.","prio":"P2","sec":"s19"},{"id":"fc-p226-ab9dd2","poly":"pneumo","fiche":"p226","front":"TVS : quelle dose d'anticoagulant ?","back":"**Dose préventive** (pas curative).","prio":"P3","sec":"s19"},{"id":"fc-p226-315e61","poly":"pneumo","fiche":"p226","front":"Thrombose veineuse superficielle : quelle mesure non médicamenteuse est proposée ?","back":"La **compression veineuse élastique**.","prio":"P2","sec":"s19"},{"id":"fc-p226-d9c37a","poly":"pneumo","fiche":"p226","front":"Filtre cave : quelles indications ?","back":"**TVP proximale < 1 mois** + CI formelle aux anticoagulants ; EP < 1 mois sans TVP (cas par cas) ; **récidive d'EP** sous traitement bien conduit.","prio":"P2","sec":"s20"},{"id":"fc-p226-b0642a","poly":"pneumo","fiche":"p226","front":"Filtres caves actuels : de quel type sont-ils ?","back":"**Temporaires**, retirables sans limite de délai.","prio":"P3","sec":"s20"},{"id":"fc-p226-157dd9","poly":"pneumo","fiche":"p226","front":"EP ou TVP proximale : quelle durée minimale d'anticoagulation ?","back":"**3 mois**.","prio":"P2","sec":"s21"},{"id":"fc-p226-787383","poly":"pneumo","fiche":"p226","front":"MTEV : quand proposer un traitement court (3 à 6 mois) ?","back":"1re MTEV avec **facteur majeur transitoire** ; non provoquée chez une **femme < 50 ans** ; **risque hémorragique élevé**.","prio":"P2","sec":"s21"},{"id":"fc-p226-ac1195","poly":"pneumo","fiche":"p226","front":"MTEV : quand proposer un traitement non limité ?","back":"Non provoquée **récidivante**, **facteur majeur persistant**, 1re **EP à haut risque non provoquée** (si risque hémorragique faible/modéré).","prio":"P2","sec":"s21"},{"id":"fc-p226-db583a","poly":"pneumo","fiche":"p226","front":"MTEV : quand la durée est-elle incertaine (≥ 6 mois ou non limitée) ?","back":"1re EP à risque faible/intermédiaire ou TVP proximale isolée **non provoquée**, ± facteur mineur.","prio":"P3","sec":"s21"},{"id":"fc-p226-121b28","poly":"pneumo","fiche":"p226","front":"Anticoagulation au-delà de 6 mois : quelle dose de référence ?","back":"La **dose curative**.","prio":"P3","sec":"s21"},{"id":"fc-p226-aa4025","poly":"pneumo","fiche":"p226","front":"SAPL : quel anticoagulant et quelle durée ?","back":"**AVK** pour une durée **non limitée**.","prio":"P2","sec":"s21"},{"id":"fc-p226-95947a","poly":"pneumo","fiche":"p226","front":"MTEV non provoquée : quel cancer rechercher et comment ?","back":"**Cancer occulte** : clinique avec **touchers pelviens**, NFS, radio thorax (si pas d'angioscanner), **dépistages** de la population générale à jour.","prio":"P2","sec":"s22"},{"id":"fc-p226-5930e7","poly":"pneumo","fiche":"p226","front":"Recherche de cancer occulte : faut-il d'autres examens systématiques ?","back":"**Non** : seulement sur **point d'appel** clinique (coûteux, sans impact pronostique).","prio":"P2","sec":"s22"},{"id":"fc-p226-fa822f","poly":"pneumo","fiche":"p226","front":"Thrombophilie : quelles indications de recherche ?","back":"MTEV non provoquée **< 50 ans** avec ATCD familial 1er degré ; **récidivante** (un épisode < 50 ans) ; **site atypique**.","prio":"P2","sec":"s22"},{"id":"fc-p226-ecac16","poly":"pneumo","fiche":"p226","front":"Thrombophilie : quand faire les dosages ?","back":"À **distance** de l'épisode aigu (**≥ 1 mois**) ; protéines C/S hors AVK, antithrombine hors héparine/AOD.","prio":"P3","sec":"s22"},{"id":"fc-p226-b1d5bd","poly":"pneumo","fiche":"p226","front":"SAPL : comment confirmer le diagnostic biologique ?","back":"**Répéter** les tests (anticoagulant lupique, anticardiolipine, anti-β2GPI) **à 3 mois**.","prio":"P3","sec":"s22"},{"id":"fc-p226-c91ed0","poly":"pneumo","fiche":"p226","front":"Recherche de thrombophilie héréditaire : quelle formalité ?","back":"**Consentement écrit** du patient (ou représentant légal).","prio":"P3","sec":"s22"},{"id":"fc-p226-8cc881","poly":"pneumo","fiche":"p226","front":"Déficit en antithrombine : quelles conséquences ?","back":"**Anticoagulation non limitée** et **dépistage familial**.","prio":"P3","sec":"s22"},{"id":"fc-p226-d6c6dc","poly":"pneumo","fiche":"p226","front":"HTP thrombo-embolique chronique : quand l'évoquer ?","back":"**Dyspnée persistante** après **≥ 3 mois** de traitement d'une EP, avant l'arrêt.","prio":"P2","sec":"s23"},{"id":"fc-p226-43a263","poly":"pneumo","fiche":"p226","front":"HTP thrombo-embolique chronique : quelle fréquence ?","back":"**Rare : 2 à 3 %**.","prio":"P3","sec":"s23"},{"id":"fc-p226-94fd58","poly":"pneumo","fiche":"p226","front":"HTP-TEC suspectée : quelle démarche diagnostique ?","back":"**ETT** → **scintigraphie V/Q** → si défects : **cathétérisme droit** + angio-TDM ou angiographie.","prio":"P3","sec":"s23"},{"id":"fc-p226-08d384","poly":"pneumo","fiche":"p226","front":"Syndrome post-thrombotique : quels signes ?","back":"Douleurs, **varices**, œdème, **dermite ocre**, **ulcères variqueux**.","prio":"P2","sec":"s23"},{"id":"fc-p226-f59335","poly":"pneumo","fiche":"p226","front":"Syndrome post-thrombotique : quelle fréquence après TVP ?","back":"**1/3** des patients.","prio":"P3","sec":"s23"},{"id":"fc-p226-bd9415","poly":"pneumo","fiche":"p226","front":"MTEV : quel risque de récidive à un an après arrêt du traitement ?","back":"**3 à 15 %**.","prio":"P3","sec":"s23"},{"id":"fc-p226-e1e91c","poly":"pneumo","fiche":"p226","front":"Chirurgie à risque thrombo-embolique faible : quelle prévention ?","back":"**Aucune** (chirurgie générale ou mineure, < 40 ans, sans facteur de risque).","prio":"P1","sec":"s24"},{"id":"fc-p226-60e27e","poly":"pneumo","fiche":"p226","front":"Chirurgie à risque modéré : quelle prévention de la MTEV ?","back":"**HNF, HBPM ou fondaparinux** à dose préventive.","prio":"P2","sec":"s24"},{"id":"fc-p226-ada672","poly":"pneumo","fiche":"p226","front":"Chirurgie à risque thrombo-embolique élevé : quels exemples ?","back":"**Hanche ou genou**, chirurgie **carcinologique**, anomalie de coagulation, > 40 ans avec ATCD de MTEV.","prio":"P1","sec":"s24"},{"id":"fc-p226-8a7f8b","poly":"pneumo","fiche":"p226","front":"Chirurgie à risque élevé : quelle prévention ?","back":"**HNF, HBPM, fondaparinux ou AOD** à dose préventive.","prio":"P1","sec":"s24"},{"id":"fc-p226-ede605","poly":"pneumo","fiche":"p226","front":"Prévention de la MTEV en milieu médical : quelles indications d'emblée ?","back":"**IDM**, **AVC ischémique**, **insuffisance cardiaque ou respiratoire aiguë**.","prio":"P1","sec":"s24"},{"id":"fc-p226-639fb6","poly":"pneumo","fiche":"p226","front":"Prévention médicale : quand traiter une infection, une MICI ou une affection rhumatologique ?","back":"Si facteur associé : **> 75 ans**, **cancer**, ATCD MTEV, obésité, varices, œstroprogestatif, IC/IR chronique.","prio":"P2","sec":"s24"},{"id":"fc-p226-93869f","poly":"pneumo","fiche":"p226","front":"Prévention de la MTEV en milieu médical : quel traitement et quelle durée ?","back":"**HBPM, HNF ou fondaparinux** préventifs, **7 à 14 jours**.","prio":"P1","sec":"s24"},{"id":"fc-p226-7c1148","poly":"pneumo","fiche":"p226","front":"Prévention de la MTEV : que proposer si les anticoagulants sont contre-indiqués ?","back":"**Compression veineuse élastique**.","prio":"P2","sec":"s24"},{"id":"fc-p230-eb0253","poly":"pneumo","fiche":"p230","front":"Douleur thoracique aiguë : quel est le premier objectif ?","back":"Identifier une **urgence à risque vital** et lancer les mesures adaptées.","prio":"P1","sec":"s1"},{"id":"fc-p230-cd282d","poly":"pneumo","fiche":"p230","front":"Douleur thoracique chronique : comment la caractériser ?","back":"Douleur qui **persiste plusieurs semaines** ou **récidive** à plusieurs reprises (pas de définition précise).","prio":"P3","sec":"s1"},{"id":"fc-p230-a67032","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels sont les 3 éléments d'orientation diagnostique ?","back":"**Sémiologie** de la douleur, **influence de la respiration**, **signes de gravité**.","prio":"P2","sec":"s1"},{"id":"fc-p230-6bdbe9","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quelles structures peuvent faire mal ?","back":"**Paroi** (côtes, muscles), **enveloppes** (plèvre, péricarde), **organes** (cœur, œsophage, aorte).","prio":"P2","sec":"s1"},{"id":"fc-p230-0db41b","poly":"pneumo","fiche":"p230","front":"Le parenchyme pulmonaire peut-il donner une douleur thoracique ?","back":"**Non** : seulement une atteinte pulmonaire **au contact de la plèvre**.","prio":"P1","sec":"s1"},{"id":"fc-p230-12c4a8","poly":"pneumo","fiche":"p230","front":"Douleur thoracique constrictive, en étau ou en pesanteur : quelle origine évoquer ?","back":"**Coronaire**.","prio":"P1","sec":"s2"},{"id":"fc-p230-c392d4","poly":"pneumo","fiche":"p230","front":"Douleur thoracique à type de brûlure : quelles origines évoquer ?","back":"**Coronaire** ou **digestive**.","prio":"P2","sec":"s2"},{"id":"fc-p230-134558","poly":"pneumo","fiche":"p230","front":"Douleur rétrosternale, médiothoracique : quelles origines évoquer ?","back":"**Coronaire**, **trachéale** ou **œsophagienne**.","prio":"P2","sec":"s2"},{"id":"fc-p230-b6be2a","poly":"pneumo","fiche":"p230","front":"Douleur thoracique basse, latérale et/ou dorsale : quelle origine évoquer ?","back":"**Pleurale** ou pleuro-parenchymateuse.","prio":"P2","sec":"s2"},{"id":"fc-p230-393a2f","poly":"pneumo","fiche":"p230","front":"Douleur thoracique irradiant au cou, à la mâchoire et aux bras : quelle origine ?","back":"**Coronarienne**.","prio":"P1","sec":"s2"},{"id":"fc-p230-5e483b","poly":"pneumo","fiche":"p230","front":"Douleur thoracique irradiant dans le dos : quelles origines ?","back":"**Aortique** ou **pancréatique**.","prio":"P1","sec":"s2"},{"id":"fc-p230-c56e8c","poly":"pneumo","fiche":"p230","front":"Douleur irradiant le long du bras jusqu'aux doigts : quelle origine ?","back":"Atteinte du **plexus brachial**.","prio":"P2","sec":"s2"},{"id":"fc-p230-539420","poly":"pneumo","fiche":"p230","front":"Douleur thoracique à irradiation intercostale : quelles causes ?","back":"**Névralgie**, **zona**.","prio":"P2","sec":"s2"},{"id":"fc-p230-cbf2fe","poly":"pneumo","fiche":"p230","front":"Douleur thoracique déclenchée par l'effort et soulagée au repos : quel diagnostic ?","back":"**Angor stable**.","prio":"P2","sec":"s2"},{"id":"fc-p230-3ed4f1","poly":"pneumo","fiche":"p230","front":"Douleur thoracique déclenchée par l'ingestion d'aliments : quelle origine ?","back":"**Œsophagienne**.","prio":"P2","sec":"s2"},{"id":"fc-p230-f06cf0","poly":"pneumo","fiche":"p230","front":"Douleur thoracique déclenchée par la position allongée : quel diagnostic ?","back":"**Péricardite aiguë**.","prio":"P2","sec":"s2"},{"id":"fc-p230-5cb310","poly":"pneumo","fiche":"p230","front":"Douleur thoracique de début brutal, au repos, sans facteur déclenchant : quels diagnostics ?","back":"**Infarctus du myocarde**, **dissection aortique**.","prio":"P1","sec":"s2"},{"id":"fc-p230-032ae3","poly":"pneumo","fiche":"p230","front":"Douleur soulagée par la trinitrine en moins de 3 minutes : quelle origine ?","back":"**Coronaire**.","prio":"P1","sec":"s2"},{"id":"fc-p230-c4d675","poly":"pneumo","fiche":"p230","front":"Douleur thoracique soulagée par la position penchée en avant : quelles causes ?","back":"**Péricardite**, **pancréatite**.","prio":"P1","sec":"s2"},{"id":"fc-p230-3b4213","poly":"pneumo","fiche":"p230","front":"Position penchée en avant : quelle douleur déclenche-t-elle ?","back":"Le **pyrosis**.","prio":"P2","sec":"s2"},{"id":"fc-p230-351860","poly":"pneumo","fiche":"p230","front":"Douleur thoracique soulagée par l'alimentation : quelle cause ?","back":"**Ulcère gastro-duodénal**.","prio":"P3","sec":"s2"},{"id":"fc-p230-923a22","poly":"pneumo","fiche":"p230","front":"Douleur rythmée par la respiration ou majorée à la palpation : quelle origine ?","back":"Surtout **pariétale** (paroi, plèvre), ou pulmonaire avec **contact pariétal**.","prio":"P1","sec":"s2"},{"id":"fc-p230-93b227","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes associés respiratoires rechercher ?","back":"Cyanose, dyspnée, polypnée, toux, **hémoptysie**, **silence auscultatoire unilatéral**, crépitants.","prio":"P3","sec":"s2"},{"id":"fc-p230-c233c7","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes associés cardiovasculaires rechercher ?","back":"Tachycardie, **bruits du cœur assourdis**, hypotension, choc, insuffisance cardiaque, douleurs des membres inférieurs, **thrombophlébite**.","prio":"P3","sec":"s2"},{"id":"fc-p230-06542e","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels antécédents rechercher ?","back":"**Coronariens**, **MTEV**, maladies respiratoires, **cancer** ; facteurs de risque CV (**tabac**).","prio":"P2","sec":"s2"},{"id":"fc-p230-dd40a9","poly":"pneumo","fiche":"p230","front":"Douleur thoracique chez un jeune sans antécédent : quelle prise rechercher ?","back":"La **cocaïne**.","prio":"P1","sec":"s2"},{"id":"fc-p230-08303b","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quel traitement en cours rechercher notamment ?","back":"La **pilule œstroprogestative**.","prio":"P2","sec":"s2"},{"id":"fc-p230-4e61ad","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes de gravité cardiovasculaire ?","back":"**Pâleur**, **tachycardie**, **hypotension**, choc (**marbrures**, TRC allongé, extrémités froides).","prio":"P2","sec":"s3"},{"id":"fc-p230-09fc2b","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes de gravité respiratoire ?","back":"**Cyanose**, **tachypnée** (ou bradypnée), **signes de lutte** (tirage, balancement thoraco-abdominal).","prio":"P2","sec":"s3"},{"id":"fc-p230-b70094","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes de gravité neurologique et générale ?","back":"**Lipothymie/syncope**, **agitation**, **troubles de la vigilance**, **sudation**.","prio":"P2","sec":"s3"},{"id":"fc-p230-961498","poly":"pneumo","fiche":"p230","front":"Quels signes font craindre un arrêt cardio-respiratoire ?","back":"**Bradypnée** ou respiration irrégulière, **bradycardie avec choc**, **troubles de la vigilance**.","prio":"P1","sec":"s3"},{"id":"fc-p230-54ea50","poly":"pneumo","fiche":"p230","front":"Douleur thoracique avec gravité immédiate : quels diagnostics évoquer ?","back":"**SCA**, **EP massive**, **PNO grave**, **tamponnade**, **dissection aortique**.","prio":"P1","sec":"s3"},{"id":"fc-p230-49cf78","poly":"pneumo","fiche":"p230","front":"Diagnostics qui engagent le pronostic vital : qu'imposent-ils ?","back":"Des **examens complémentaires**, des **soins immédiats** et un transfert en **soins intensifs** ou **réanimation**.","prio":"P2","sec":"s9"},{"id":"fc-p230-428361","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : peut-on attendre les résultats des examens pour chercher une urgence ?","back":"**Non**, cela ne doit pas retarder la recherche d'une urgence.","prio":"P2","sec":"s9"},{"id":"fc-p230-8ff783","poly":"pneumo","fiche":"p230","front":"Pneumothorax : la douleur est-elle un signe de gravité ?","back":"**Non** : la gravité = **détresse respiratoire** et **chute tensionnelle**.","prio":"P1","sec":"s3"},{"id":"fc-p230-d3d13b","poly":"pneumo","fiche":"p230","front":"Douleur thoracique aiguë : quels examens sont systématiques ?","back":"**Fréquence respiratoire**, **SpO₂**, **ECG**, **radiographie de thorax**.","prio":"P1","sec":"s4"},{"id":"fc-p230-627cea","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : comment choisir les autres examens ?","back":"Selon la **probabilité pré-test** du diagnostic.","prio":"P2","sec":"s4"},{"id":"fc-p230-e32eb1","poly":"pneumo","fiche":"p230","front":"Probabilité pré-test (EP, SCA) : quelles catégories selon l'item 230 ?","back":"**Faible < 10 %**, **intermédiaire 30-40 %**, **forte > 60 %** (> 70 % pour l'EP selon l'item 226).","prio":"P2","sec":"s4"},{"id":"fc-p230-fb9251","poly":"pneumo","fiche":"p230","front":"Douleur thoracique avec bradypnée ou tachypnée : quel examen d'emblée ?","back":"Les **gaz du sang**.","prio":"P1","sec":"s4"},{"id":"fc-p230-b3367a","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quel seuil de SpO₂ évoque une hypoxémie ?","back":"**SpO₂ < 95 %**, à confirmer par les gaz du sang.","prio":"P1","sec":"s4"},{"id":"fc-p230-75f40f","poly":"pneumo","fiche":"p230","front":"Gazométrie artérielle : quelle information toujours préciser ?","back":"Le **débit d'oxygène**.","prio":"P2","sec":"s9"},{"id":"fc-p230-2785c6","poly":"pneumo","fiche":"p230","front":"ECG : quel aspect évoque un SCA ST+ ?","back":"Sus-décalage du ST avec **onde de Pardee** et **image en miroir**.","prio":"P1","sec":"s4"},{"id":"fc-p230-89a3a6","poly":"pneumo","fiche":"p230","front":"ECG : quel aspect évoque une péricardite ?","back":"Sus-décalage du ST **concave**, **sans miroir** (microvoltage si épanchement abondant).","prio":"P1","sec":"s4"},{"id":"fc-p230-a66336","poly":"pneumo","fiche":"p230","front":"ECG : quels signes de cœur pulmonaire aigu (ex. EP) ?","back":"Onde **P ample**, **S1Q3**, **déviation axiale droite**.","prio":"P2","sec":"s4"},{"id":"fc-p230-158e2f","poly":"pneumo","fiche":"p230","front":"ECG : quels signes évoquent une tamponnade ?","back":"**Alternance électrique** des QRS, **tachycardie**, **microvoltage**.","prio":"P1","sec":"s4"},{"id":"fc-p230-ac493b","poly":"pneumo","fiche":"p230","front":"Tamponnade gazeuse ou péricardique : quelles causes ?","back":"Gazeuse : **pneumothorax compressif** ; péricardique : **épanchement péricardique**.","prio":"P2","sec":"s4"},{"id":"fc-p230-feebd4","poly":"pneumo","fiche":"p230","front":"Dissection aortique : que montre l'ECG ?","back":"Le plus souvent **normal** ; anomalies du ST/T si une **coronaire** est lésée.","prio":"P2","sec":"s4"},{"id":"fc-p230-4549e4","poly":"pneumo","fiche":"p230","front":"Un ECG normal entre deux crises élimine-t-il un SCA ?","back":"**Non**.","prio":"P1","sec":"s4"},{"id":"fc-p230-8ab68a","poly":"pneumo","fiche":"p230","front":"Radiographie de thorax : quel aspect évoque une dissection aortique ?","back":"**Élargissement du médiastin**.","prio":"P2","sec":"s4"},{"id":"fc-p230-59cf08","poly":"pneumo","fiche":"p230","front":"Radiographie de thorax : que montre-t-elle dans la péricardite ?","back":"Le plus souvent **normale**.","prio":"P3","sec":"s4"},{"id":"fc-p230-18e743","poly":"pneumo","fiche":"p230","front":"Radiographie thoracique non contributive : quel examen en 2e intention ?","back":"Le **scanner**.","prio":"P3","sec":"s4"},{"id":"fc-p230-5c5203","poly":"pneumo","fiche":"p230","front":"Troponine : quand la doser ?","back":"À l'**arrivée** ; à refaire à **H6** si normale, ou à **H3** si troponine **ultrasensible** normale.","prio":"P1","sec":"s11"},{"id":"fc-p230-42068e","poly":"pneumo","fiche":"p230","front":"Troponine initiale normale : exclut-elle un SCA ?","back":"**Non**.","prio":"P1","sec":"s4"},{"id":"fc-p230-73e46a","poly":"pneumo","fiche":"p230","front":"Troponine : quelle cinétique affirme ou oriente vers un SCA ?","back":"Variation **> 30 %** : très en faveur ; **doublement H0-H3** : diagnostic affirmé.","prio":"P1","sec":"s11"},{"id":"fc-p230-fe230b","poly":"pneumo","fiche":"p230","front":"Troponine élevée : dans quelles pathologies autres que le SCA ?","back":"**Péricardite**, **dissection aortique**, **EP** avec retentissement cardiaque droit.","prio":"P1","sec":"s4"},{"id":"fc-p230-b11e2b","poly":"pneumo","fiche":"p230","front":"D-dimères : quand les demander devant une suspicion d'EP ?","back":"Si la probabilité clinique est **faible ou modérée**.","prio":"P2","sec":"s4"},{"id":"fc-p230-ff045f","poly":"pneumo","fiche":"p230","front":"SCA ST+ : quel délai pour une efficacité maximale de la coronarographie ?","back":"**< 2 heures** après le début de la douleur.","prio":"P3","sec":"s10"},{"id":"fc-p230-84022e","poly":"pneumo","fiche":"p230","front":"SCA ST+ avec délai prévisible de coronarographie > 2 h : quelle reperfusion ?","back":"**Fibrinolyse intraveineuse**, puis angioplastie.","prio":"P3","sec":"s10"},{"id":"fc-p230-5266dc","poly":"pneumo","fiche":"p230","front":"SCA ST+ évoluant depuis > 12 h : quand reste indiquée l'angioplastie primaire ?","back":"**Douleur persistante**, **instabilité hémodynamique** ou **troubles du rythme ventriculaires**.","prio":"P3","sec":"s10"},{"id":"fc-p230-69bf5f","poly":"pneumo","fiche":"p230","front":"SCA ST+ : jusqu'à quand discuter l'angioplastie et ensuite ?","back":"Jusqu'à **48 h** ; au-delà, sans douleur, rechercher d'abord une **viabilité**.","prio":"P3","sec":"s10"},{"id":"fc-p230-e920f6","poly":"pneumo","fiche":"p230","front":"SCA non ST+ : quel délai pour la coronarographie ?","back":"Dans les **24 h**.","prio":"P3","sec":"s11"},{"id":"fc-p230-b5315d","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quelles sont les 5 urgences à risque vital ?","back":"**SCA**, **EP**, **tamponnade**, **dissection aortique**, **pneumothorax compressif**.","prio":"P1","sec":"s5"},{"id":"fc-p230-e548ca","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quelles 4 urgences cardiovasculaires (acronyme) ?","back":"**PIED** : **P**éricardite, **I**nfarctus, **E**mbolie pulmonaire, **D**issection aortique.","prio":"P1","sec":"s5"},{"id":"fc-p230-e94b67","poly":"pneumo","fiche":"p230","front":"SCA : quelle part des douleurs thoraciques admises aux urgences ?","back":"Près d'**un tiers**.","prio":"P2","sec":"s5"},{"id":"fc-p230-f00826","poly":"pneumo","fiche":"p230","front":"Suspicion de SCA : quel mode de transport ?","back":"**Transport médicalisé** via le **15** (mortalité pré-hospitalière élevée).","prio":"P1","sec":"s10"},{"id":"fc-p230-30f3b5","poly":"pneumo","fiche":"p230","front":"SCA ST+ à l'ECG : faut-il attendre la troponine pour reperfuser ?","back":"**Non** : l'aspect ECG suffit à lancer la **reperfusion**.","prio":"P1","sec":"s10"},{"id":"fc-p230-adca49","poly":"pneumo","fiche":"p230","front":"Infarctus : pourquoi désobstruer l'artère au plus vite ?","back":"Pour **limiter l'étendue de la nécrose**.","prio":"P2","sec":"s10"},{"id":"fc-p230-eb1155","poly":"pneumo","fiche":"p230","front":"Angor stable typique sans lésion coronaire explicative : que rechercher ?","back":"Un **angor fonctionnel** : RA serré, CMH, tachycardie (FA), **anémie**, **hyperthyroïdie**.","prio":"P3","sec":"s5"},{"id":"fc-p230-c1687f","poly":"pneumo","fiche":"p230","front":"Dyspnée aiguë ± douleur, sans anomalie auscultatoire franche, radio « normale » : quel diagnostic évoquer ?","back":"**Embolie pulmonaire** jusqu'à preuve du contraire.","prio":"P1","sec":"s5"},{"id":"fc-p230-41bdc5","poly":"pneumo","fiche":"p230","front":"EP : quelle valeur prédictive des signes cliniques ?","back":"**Faible** (thrombose veineuse, tachycardie, insuffisance ventriculaire droite).","prio":"P2","sec":"s5"},{"id":"fc-p230-ed52cf","poly":"pneumo","fiche":"p230","front":"EP : les signes de thrombose veineuse sont-ils constants ?","back":"**Non**, absents dans **un tiers** des cas.","prio":"P1","sec":"s5"},{"id":"fc-p230-60d42d","poly":"pneumo","fiche":"p230","front":"Suspicion d'EP : que faire dès la suspicion ?","back":"Évaluer la **probabilité clinique**, examens adaptés, **bilan d'hémostase**, **anticoagulation curative** sans attendre.","prio":"P1","sec":"s5"},{"id":"fc-p230-a7262f","poly":"pneumo","fiche":"p230","front":"Angioscanner thoracique dans l'EP : quels signes directs et indirects ?","back":"Directs : **lacunes** dans les artères pulmonaires ; indirects : **condensations** (infarctus pulmonaires).","prio":"P2","sec":"s5"},{"id":"fc-p230-3bb15c","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quel terrain ?","back":"Pathologie **exceptionnelle**, plus fréquente **à partir de 60 ans** ; aorte pathologique, le plus souvent par athérosclérose liée à une **HTA non contrôlée**.","prio":"P2","sec":"s5"},{"id":"fc-p230-e74a1c","poly":"pneumo","fiche":"p230","front":"Dissection aortique chez le sujet jeune : quelles maladies évoquer ?","back":"Maladies du tissu conjonctif : **Marfan**, **Ehlers-Danlos**.","prio":"P1","sec":"s5"},{"id":"fc-p230-b5d5df","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quelle douleur typique ?","back":"Intense, prolongée, en **déchirement**, irradiant dans le **dos**, migrant vers les **lombes**.","prio":"P1","sec":"s5"},{"id":"fc-p230-2c719f","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quel signe tensionnel rechercher ?","back":"**Asymétrie tensionnelle > 20 mmHg** entre les deux bras.","prio":"P1","sec":"s15"},{"id":"fc-p230-e964c1","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quels autres signes d'examen ?","back":"**Souffle d'insuffisance aortique**, **déficit neurologique**.","prio":"P2","sec":"s15"},{"id":"fc-p230-0b9cd4","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quels signes à la radiographie ?","back":"**Médiastin élargi**, parfois **double contour aortique**, **épanchement pleural** (hémothorax).","prio":"P3","sec":"s5"},{"id":"fc-p230-770679","poly":"pneumo","fiche":"p230","front":"Dissection aortique : quels examens de confirmation ?","back":"**Échocardiographie** (surtout **transœsophagienne**) ; si stable, **angioscanner** ou angio-IRM aortique.","prio":"P3","sec":"s15"},{"id":"fc-p230-94dbd6","poly":"pneumo","fiche":"p230","front":"Péricardite aiguë : quelle cause la plus fréquente et quel terrain ?","back":"**Idiopathique ou virale** ; plus fréquente chez l'**homme**.","prio":"P2","sec":"s5"},{"id":"fc-p230-0bbc35","poly":"pneumo","fiche":"p230","front":"Tamponnade : quel mécanisme ?","back":"Compression aiguë des cavités **droites** par un **épanchement péricardique**, habituellement d'installation rapide et abondant.","prio":"P1","sec":"s5"},{"id":"fc-p230-c96c8c","poly":"pneumo","fiche":"p230","front":"Tamponnade : quelle fréquence au cours des péricardites ?","back":"**Rare** (**2 %**) mais redoutable.","prio":"P2","sec":"s5"},{"id":"fc-p230-6fd23e","poly":"pneumo","fiche":"p230","front":"Tamponnade : quelle cause d'épanchement est particulièrement citée ?","back":"**Néoplasique**.","prio":"P2","sec":"s5"},{"id":"fc-p230-8e6134","poly":"pneumo","fiche":"p230","front":"Tamponnade : quels signes cliniques ?","back":"**Hypotension**, **insuffisance cardiaque droite sans signe gauche**, **pouls paradoxal**.","prio":"P1","sec":"s5"},{"id":"fc-p230-e1d2ef","poly":"pneumo","fiche":"p230","front":"Pouls paradoxal de Küssmaul : quelle définition ?","back":"Baisse de la PAS **> 10 mmHg** à l'**inspiration** par rapport à l'expiration.","prio":"P1","sec":"s5"},{"id":"fc-p230-a36fc7","poly":"pneumo","fiche":"p230","front":"Alternance électrique : quelle définition ?","back":"Amplitude des QRS **variable** dans une même dérivation.","prio":"P2","sec":"s5"},{"id":"fc-p230-0d9dfb","poly":"pneumo","fiche":"p230","front":"Tamponnade : quel examen confirme le diagnostic ?","back":"L'**échographie cardiaque**.","prio":"P1","sec":"s16"},{"id":"fc-p230-530d6a","poly":"pneumo","fiche":"p230","front":"Tamponnade : que montre la radiographie ?","back":"Cœur élargi **« en carafe »**, mais elle peut être **normale**.","prio":"P3","sec":"s5"},{"id":"fc-p230-6d89d8","poly":"pneumo","fiche":"p230","front":"Pneumothorax : quelle définition ?","back":"**Air dans l'espace pleural**, avec collapsus partiel ou complet du poumon.","prio":"P1","sec":"s5"},{"id":"fc-p230-443ff4","poly":"pneumo","fiche":"p230","front":"Pneumothorax : quel antécédent est un argument fort ?","back":"Un **antécédent de PNO** (récidive dans près d'**un tiers** des cas).","prio":"P2","sec":"s5"},{"id":"fc-p230-50e895","poly":"pneumo","fiche":"p230","front":"Pneumothorax : quels signes cliniques ?","back":"**Asymétrie auscultatoire**, **tympanisme**.","prio":"P2","sec":"s5"},{"id":"fc-p230-9e22a3","poly":"pneumo","fiche":"p230","front":"Pneumothorax complet : quel aspect radiographique ?","back":"**Hyperclarté** sans structure vasculaire + **opacité hilaire** (poumon rétracté).","prio":"P2","sec":"s5"},{"id":"fc-p230-346d19","poly":"pneumo","fiche":"p230","front":"PNO spontané : quels taux de récidive selon l'item 360 ?","back":"Un peu moins de **30 %** (primaire) ; plus de **50 %** (secondaire), surtout **homolatérale**.","prio":"P3","sec":"s5"},{"id":"fc-p230-150338","poly":"pneumo","fiche":"p230","front":"Sans urgence vitale : sur quoi repose l'algorithme diagnostique ?","back":"Sur l'**influence de la respiration** sur la douleur.","prio":"P2","sec":"s6"},{"id":"fc-p230-f7cd2c","poly":"pneumo","fiche":"p230","front":"Douleur rythmée par la respiration : quelles causes (arbre d'orientation) ?","back":"**PNO**, **pneumomédiastin**, **EP**, **pneumonie**, **pleurésie**, **péricardite**, atteintes **pariétales**.","prio":"P1","sec":"s6"},{"id":"fc-p230-9713e7","poly":"pneumo","fiche":"p230","front":"Fracture de côte post-traumatique sans lésion pleuro-parenchymateuse : quel traitement ?","back":"Traitement **symptomatique** de la douleur.","prio":"P2","sec":"s17"},{"id":"fc-p230-586e21","poly":"pneumo","fiche":"p230","front":"Pneumonie : à quelle condition donne-t-elle une douleur thoracique ?","back":"S'il existe un **contact pleural**.","prio":"P1","sec":"s6"},{"id":"fc-p230-46a720","poly":"pneumo","fiche":"p230","front":"Pneumonie douloureuse : comment confirmer le diagnostic ?","back":"**Radiographie** (scanner non nécessaire) ; **ponction pleurale** si pleurésie.","prio":"P2","sec":"s17"},{"id":"fc-p230-eec6d9","poly":"pneumo","fiche":"p230","front":"Épanchement pleural : quelle douleur et quelle toux ?","back":"Douleur **latéro- ou basithoracique** majorée par inspiration et toux ; **toux aux changements de position**.","prio":"P2","sec":"s6"},{"id":"fc-p230-c1713b","poly":"pneumo","fiche":"p230","front":"Épanchement pleural : quel aspect radiographique ?","back":"Opacité **hydrique homogène**, effaçant les vaisseaux, à **concavité supérieure et interne**.","prio":"P3","sec":"s6"},{"id":"fc-p230-dcc508","poly":"pneumo","fiche":"p230","front":"Trachéobronchite aiguë : quelle douleur ?","back":"**Brûlure** à chaque mouvement respiratoire, aggravée par une **toux d'abord sèche**.","prio":"P2","sec":"s6"},{"id":"fc-p230-91f633","poly":"pneumo","fiche":"p230","front":"Trachéobronchite aiguë : comment se fait le diagnostic ?","back":"Diagnostic **clinique** ; traitement symptomatique.","prio":"P1","sec":"s6"},{"id":"fc-p230-fc2390","poly":"pneumo","fiche":"p230","front":"Douleurs musculo-squelettiques thoraciques : quelles caractéristiques ?","back":"Rythmées par les mouvements, **reproductibles à la palpation**, majorées par la toux.","prio":"P2","sec":"s6"},{"id":"fc-p230-4f4599","poly":"pneumo","fiche":"p230","front":"Une toux violente peut-elle provoquer des fractures de côtes ?","back":"**Oui**, des fractures **spontanées**.","prio":"P2","sec":"s6"},{"id":"fc-p230-99a7ab","poly":"pneumo","fiche":"p230","front":"Douleurs pariétales : quelles causes citer ?","back":"**Lésions vertébrales**, **névralgies cervico-brachiales**, **tumeurs costales** (souvent métastatiques).","prio":"P3","sec":"s6"},{"id":"fc-p230-95fb3a","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quelle douleur ?","back":"**Rétrosternale**, d'installation **brusque**.","prio":"P2","sec":"s6"},{"id":"fc-p230-1a11e7","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quel signe d'examen ?","back":"**Emphysème sous-cutané cervical** qui **crépite** à la palpation.","prio":"P2","sec":"s6"},{"id":"fc-p230-f7054e","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quel examen fait le diagnostic ?","back":"Le **scanner**.","prio":"P1","sec":"s6"},{"id":"fc-p230-2219af","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quel aspect radiographique ?","back":"Médiastin bordé d'une **hyperclarté** (double contour).","prio":"P3","sec":"s6"},{"id":"fc-p230-4ccf7c","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quel mécanisme ?","back":"L'air des espaces distaux diffuse vers le **médiastin** par le **hile**, le long des axes **bronchovasculaires**.","prio":"P3","sec":"s6"},{"id":"fc-p230-dc3bc1","poly":"pneumo","fiche":"p230","front":"Douleur non rythmée par la respiration : quelles causes (arbre d'orientation) ?","back":"**SCA**, **dissection aortique**, **EP**, douleur **digestive**, douleur **psychogène**.","prio":"P1","sec":"s7"},{"id":"fc-p230-b59ae5","poly":"pneumo","fiche":"p230","front":"Hors urgence vitale : quelles sont les 3 causes de douleur thoracique les plus fréquentes ?","back":"**SCA**, douleurs **œsophagiennes**, douleurs **psychogènes**.","prio":"P1","sec":"s7"},{"id":"fc-p230-a17d85","poly":"pneumo","fiche":"p230","front":"Douleurs œsophagiennes et psychogènes : quel type de diagnostic ?","back":"Des **diagnostics d'élimination**.","prio":"P1","sec":"s7"},{"id":"fc-p230-8cd99c","poly":"pneumo","fiche":"p230","front":"Angor d'effort stable : en combien de temps la douleur cède-t-elle ?","back":"**2 à 5 min** après l'arrêt de l'effort ou la trinitrine.","prio":"P2","sec":"s7"},{"id":"fc-p230-1f127d","poly":"pneumo","fiche":"p230","front":"Angor d'effort stable : que montre l'ECG en dehors des crises ?","back":"Il est **normal**.","prio":"P2","sec":"s7"},{"id":"fc-p230-dc6d7a","poly":"pneumo","fiche":"p230","front":"Péricardite : quelle localisation de la douleur ?","back":"**Précordiale gauche** ou **rétrosternale** (inconstante).","prio":"P2","sec":"s7"},{"id":"fc-p230-305147","poly":"pneumo","fiche":"p230","front":"Position penchée en avant : soulage-t-elle les douleurs pariétales ou pulmonaires ?","back":"**Non** (elle soulage la péricardite).","prio":"P2","sec":"s7"},{"id":"fc-p230-95a6cc","poly":"pneumo","fiche":"p230","front":"Péricardite chronique : quelles causes suspecter ?","back":"**Tuberculose** ou **néoplasie**.","prio":"P1","sec":"s7"},{"id":"fc-p230-4a00f3","poly":"pneumo","fiche":"p230","front":"Cocaïne : quelles complications thoraciques peut-elle donner ?","back":"**SCA** (voire spasme de **Prinzmetal**), **myopéricardite**, **pneumothorax** (sniff).","prio":"P2","sec":"s7"},{"id":"fc-p230-a4bbeb","poly":"pneumo","fiche":"p230","front":"Zona thoracique : comment débute-t-il ?","back":"**Hyperesthésie** et **brûlures** pendant **24 à 48 h**, classiquement métamériques.","prio":"P2","sec":"s7"},{"id":"fc-p230-9f9b78","poly":"pneumo","fiche":"p230","front":"Zona thoracique : quelle éruption ensuite ?","back":"Éruption **vésiculaire** sur un **dermatome**.","prio":"P2","sec":"s7"},{"id":"fc-p230-290c60","poly":"pneumo","fiche":"p230","front":"Dermatome : quelle définition ?","back":"Zone de peau innervée par **une seule racine** nerveuse rachidienne.","prio":"P3","sec":"s7"},{"id":"fc-p230-385419","poly":"pneumo","fiche":"p230","front":"RGO et spasmes œsophagiens : quel piège diagnostique ?","back":"Ils peuvent **simuler un SCA** (innervation commune œsophage-cœur).","prio":"P1","sec":"s7"},{"id":"fc-p230-8ce500","poly":"pneumo","fiche":"p230","front":"Spasme œsophagien : quels traitements peuvent le faire céder ?","back":"**Dérivés nitrés** et **phloroglucinol**.","prio":"P1","sec":"s18"},{"id":"fc-p230-0bcd30","poly":"pneumo","fiche":"p230","front":"Douleur thoracique d'allure œsophagienne : quand retenir cette origine ?","back":"**Après avoir exclu un SCA**.","prio":"P1","sec":"s18"},{"id":"fc-p230-fdf614","poly":"pneumo","fiche":"p230","front":"Syndrome de Mallory-Weiss : quel tableau ?","back":"**Efforts de vomissements** puis douleur et **hématémèse** (dilacération du bas œsophage/cardia).","prio":"P2","sec":"s7"},{"id":"fc-p230-37e2b2","poly":"pneumo","fiche":"p230","front":"Syndrome de Boerhaave : de quoi s'agit-il ?","back":"**Rupture œsophagienne** rarissime après vomissements très intenses, avec **choc septique** rapide.","prio":"P2","sec":"s7"},{"id":"fc-p230-c68a53","poly":"pneumo","fiche":"p230","front":"Rupture œsophagienne : quel signe radiologique doit la faire suspecter ?","back":"Épanchement pleural **gauche** avec **niveau hydroaérique**.","prio":"P2","sec":"s7"},{"id":"fc-p230-aa5019","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quelles causes digestives non œsophagiennes ?","back":"**Pancréatite**, **ulcère perforé**, **cholécystite**, hépatalgie d'**insuffisance cardiaque droite**.","prio":"P3","sec":"s7"},{"id":"fc-p230-340e01","poly":"pneumo","fiche":"p230","front":"Douleurs psychogènes : quelle part des douleurs thoraciques aux urgences ?","back":"Jusqu'à **un quart**.","prio":"P2","sec":"s7"},{"id":"fc-p230-a167b1","poly":"pneumo","fiche":"p230","front":"Douleur psychogène : quels signes associés ?","back":"Riches et variés : **palpitations**, tremblements, **sueurs**, frissons, nausées ; sans lien avec l'effort.","prio":"P2","sec":"s7"},{"id":"fc-p230-e030b4","poly":"pneumo","fiche":"p230","front":"Soulagement par la trinitrine : quels délais donne le Collège ?","back":"**< 3 min** (douleur coronaire, p. 268) ; **2 à 5 min** (angor d'effort, p. 277).","prio":"P3","sec":"s7"},{"id":"fc-p230-2d5514","poly":"pneumo","fiche":"p230","front":"Péricardite : comment est-elle classée vis-à-vis de la respiration ?","back":"**Non rythmée** (points clés) mais dans la branche **« rythmée/modifiée par la position »** de l'arbre ; soulagée penché en avant.","prio":"P3","sec":"s8"},{"id":"fc-p230-34bea3","poly":"pneumo","fiche":"p230","front":"Douleurs rythmées par la respiration (points clés) : lesquelles ?","back":"Douleurs **pleurales** et **pariétales**, **trachéobronchites**, **EP**.","prio":"P2","sec":"s8"},{"id":"fc-p230-58e6ac","poly":"pneumo","fiche":"p230","front":"Douleurs non rythmées par la respiration (points clés) : lesquelles ?","back":"**SCA**, **péricardites**, douleurs **œsophagiennes**, autres.","prio":"P2","sec":"s8"},{"id":"fc-p230-8b96ca","poly":"pneumo","fiche":"p230","front":"Arbre d'orientation : dans quelles branches figure l'EP ?","back":"Dans les **trois** branches (gravité, rythmée, non rythmée).","prio":"P1","sec":"s8"},{"id":"fc-p230-46f381","poly":"pneumo","fiche":"p230","front":"EP : quel bilan biologique avant traitement anticoagulant ?","back":"**Plaquettes**, **TP**, **TCA**, NFS, **créatinine**, transaminases (± pré-transfusionnel).","prio":"P2","sec":"s12"},{"id":"fc-p230-edec97","poly":"pneumo","fiche":"p230","front":"Anticoagulation de l'EP : quelles situations de risque hémorragique rechercher ?","back":"**Coagulopathie sévère** (plaquettes < 30 000, TP < 30 %), **hémorragie intracrânienne**, hémorragie active, **chirurgie récente**.","prio":"P3","sec":"s12"},{"id":"fc-p230-c28e55","poly":"pneumo","fiche":"p230","front":"EP à faible risque : quelle hospitalisation ?","back":"**Courte (< 24 h)** ; risque intermédiaire-faible : service de médecine.","prio":"P3","sec":"s12"},{"id":"fc-p230-c00bc9","poly":"pneumo","fiche":"p230","front":"EP : quand le patient peut-il se lever ?","back":"**1 h** après le début de l'anticoagulation, selon l'état clinique.","prio":"P3","sec":"s12"},{"id":"fc-p230-d00da3","poly":"pneumo","fiche":"p230","front":"EP stable : quel anticoagulant en 1re intention ?","back":"**AOD anti-Xa** : **rivaroxaban** ou **apixaban** (d'emblée, sans héparine préalable).","prio":"P1","sec":"s12"},{"id":"fc-p230-75fdf8","poly":"pneumo","fiche":"p230","front":"AOD dans l'EP : quelles contre-indications ?","back":"**IR sévère**, **instabilité hémodynamique**, **grossesse**, **allaitement**, interactions **CYP3A4/P-gp**.","prio":"P2","sec":"s12"},{"id":"fc-p230-b97697","poly":"pneumo","fiche":"p230","front":"AOD : quels seuils de clairance contre-indiquent rivaroxaban et apixaban ?","back":"Rivaroxaban **< 30 mL/min** ; apixaban **< 25 mL/min** (points clés : < 30).","prio":"P3","sec":"s12"},{"id":"fc-p230-99eccc","poly":"pneumo","fiche":"p230","front":"AOD : citer des médicaments à interaction majeure ?","back":"**Rifampicine**, phénobarbital, **azolés**, **antiprotéases du VIH**, anti-tyrosine kinases, **macrolides** (sauf azithromycine).","prio":"P3","sec":"s12"},{"id":"fc-p230-3ccc0d","poly":"pneumo","fiche":"p230","front":"HBPM ou fondaparinux dans l'EP : quels avantages ?","back":"Dose **adaptée au poids**, **pas de surveillance biologique**, risque de **TIH diminué**.","prio":"P2","sec":"s12"},{"id":"fc-p230-f106bb","poly":"pneumo","fiche":"p230","front":"HBPM et fondaparinux : quelle contre-indication ?","back":"**Insuffisance rénale sévère** (clairance < 30 mL/min).","prio":"P2","sec":"s12"},{"id":"fc-p230-d51184","poly":"pneumo","fiche":"p230","front":"HNF dans l'EP : quelles indications ?","back":"**Insuffisance rénale sévère** ou **EP avec choc**.","prio":"P1","sec":"s12"},{"id":"fc-p230-10b53b","poly":"pneumo","fiche":"p230","front":"HNF : quelles cibles de surveillance ?","back":"**Anti-Xa 0,3 à 0,7 UI/mL** ou **TCA 1,5 à 2,5** (ratio malade/témoin).","prio":"P3","sec":"s12"},{"id":"fc-p230-2537c1","poly":"pneumo","fiche":"p230","front":"HNF : quelle surveillance plaquettaire et quel antidote ?","back":"Plaquettes **2 fois/semaine** (TIH) ; antidote : **sulfate de protamine**.","prio":"P2","sec":"s12"},{"id":"fc-p230-8202ff","poly":"pneumo","fiche":"p230","front":"HBPM : existe-t-il un antidote efficace ?","back":"**Non** (protamine moins efficace).","prio":"P3","sec":"s12"},{"id":"fc-p230-450e45","poly":"pneumo","fiche":"p230","front":"Relais AVK dans l'EP : quel AVK et lequel est interdit à l'initiation ?","back":"**Warfarine** (référence) ; initiation de la **fluindione interdite**.","prio":"P2","sec":"s12"},{"id":"fc-p230-bc23e2","poly":"pneumo","fiche":"p230","front":"Relais AVK : quand arrêter l'anticoagulant injectable ?","back":"Après **≥ 5 jours** de chevauchement **et** **2 INR entre 2 et 3** à 24 h d'intervalle.","prio":"P2","sec":"s12"},{"id":"fc-p230-c28ddc","poly":"pneumo","fiche":"p230","front":"AVK : quel INR cible dans l'EP ?","back":"**2 à 3**.","prio":"P2","sec":"s12"},{"id":"fc-p230-73c4cb","poly":"pneumo","fiche":"p230","front":"AOD vs AVK dans l'EP : quelle comparaison ?","back":"AOD **au moins aussi efficaces** et **plus sûrs** (moins d'hémorragies graves).","prio":"P3","sec":"s12"},{"id":"fc-p230-0e135f","poly":"pneumo","fiche":"p230","front":"Anticoagulation de l'EP : quelle durée minimale ?","back":"**3 mois**, identique pour EP et TVP proximale.","prio":"P2","sec":"s12"},{"id":"fc-p230-ac5df7","poly":"pneumo","fiche":"p230","front":"EP : quand une durée courte (3 à 6 mois) d'anticoagulation ?","back":"1re EP **provoquée par un facteur majeur transitoire**, non provoquée chez une **femme < 50 ans**, ou **risque hémorragique élevé**.","prio":"P3","sec":"s12"},{"id":"fc-p230-7e1ab9","poly":"pneumo","fiche":"p230","front":"EP : quand une anticoagulation non limitée ?","back":"**Récidive non provoquée**, **facteur majeur persistant**, 1re EP à haut risque non provoquée (si risque hémorragique faible/modéré).","prio":"P3","sec":"s12"},{"id":"fc-p230-c072b7","poly":"pneumo","fiche":"p230","front":"1re EP non provoquée à risque faible ou intermédiaire : quelle durée d'anticoagulation ?","back":"**Incertaine** : 6 mois minimum ou non limitée.","prio":"P3","sec":"s12"},{"id":"fc-p230-33ab01","poly":"pneumo","fiche":"p230","front":"EP sous contraception œstroprogestative : quelle attitude ?","back":"Arrêt **sans urgence** (finir la plaquette), relais par contraception **non thrombogène**.","prio":"P2","sec":"s12"},{"id":"fc-p230-39c6e1","poly":"pneumo","fiche":"p230","front":"Anticoagulation : sur quoi porte l'éducation ?","back":"Signes de **récidive** et de **saignement**, observance, interactions, **pas d'automédication** (aspirine, AINS), **carte d'anticoagulant**.","prio":"P2","sec":"s12"},{"id":"fc-p230-5fef8e","poly":"pneumo","fiche":"p230","front":"AVK : faut-il un régime alimentaire particulier ?","back":"**Non** (carnet et contrôles d'INR).","prio":"P3","sec":"s12"},{"id":"fc-p230-2e8da8","poly":"pneumo","fiche":"p230","front":"EP avec état de choc : quel traitement de 1re intention ?","back":"**Thrombolyse** d'emblée, toujours associée à une **anticoagulation efficace**, en **réanimation**.","prio":"P2","sec":"s13"},{"id":"fc-p230-6b362d","poly":"pneumo","fiche":"p230","front":"EP à haut risque : quelle héparine et pourquoi ?","back":"**HNF IVSE** : la voie sous-cutanée a une **biodisponibilité aléatoire** en cas de choc.","prio":"P2","sec":"s13"},{"id":"fc-p230-269d50","poly":"pneumo","fiche":"p230","front":"EP grave : quand recourir à l'embolectomie ?","back":"**Échec** ou **contre-indication absolue** de la thrombolyse (centres experts).","prio":"P3","sec":"s13"},{"id":"fc-p230-a68689","poly":"pneumo","fiche":"p230","front":"Thrombolyse : quel risque principal ?","back":"**Hémorragie grave**, dont **intracrânienne** (**2 %**).","prio":"P3","sec":"s13"},{"id":"fc-p230-64e6de","poly":"pneumo","fiche":"p230","front":"Thrombolyse : quelle est la seule contre-indication non relative ?","back":"L'**hémorragie intracérébrale**.","prio":"P3","sec":"s13"},{"id":"fc-p230-a2b9a8","poly":"pneumo","fiche":"p230","front":"EP avec instabilité hémodynamique : AOD possible ?","back":"**Non**, contre-indiqués.","prio":"P2","sec":"s13"},{"id":"fc-p230-c53b1a","poly":"pneumo","fiche":"p230","front":"Gaz du sang dans l'EP : quel intérêt et quel risque ?","back":"**Inutiles** au diagnostic (ni sensibles ni spécifiques), **dangereux** si une thrombolyse est envisagée.","prio":"P2","sec":"s13"},{"id":"fc-p230-a7190c","poly":"pneumo","fiche":"p230","front":"EP avec choc : quelles mesures symptomatiques ?","back":"**Oxygène** nasal (voire ventilation), **correction du choc**, **repos strict** au lit.","prio":"P3","sec":"s13"},{"id":"fc-p230-77a7b1","poly":"pneumo","fiche":"p230","front":"Pneumothorax : quelle incidence radiographique ?","back":"Thorax de **face en inspiration** (pas d'expiration) ; **scanner sans injection** si doute.","prio":"P2","sec":"s14"},{"id":"fc-p230-55e4ed","poly":"pneumo","fiche":"p230","front":"Pneumothorax grave : quels signes ?","back":"Dyspnée sévère et/ou collapsus : **PAS ≤ 90 mmHg**, **bradycardie**, **désaturation**, **déviation médiastinale** controlatérale.","prio":"P1","sec":"s14"},{"id":"fc-p230-2fb037","poly":"pneumo","fiche":"p230","front":"Pneumothorax grave : la taille du décollement compte-t-elle ?","back":"**Non**, grave quelle que soit la taille.","prio":"P2","sec":"s14"},{"id":"fc-p230-0ef3ce","poly":"pneumo","fiche":"p230","front":"Pneumothorax compressif : quel mécanisme et quels signes ?","back":"Pression pleurale **positive** gênant le retour veineux : **chute tensionnelle**, **turgescence jugulaire**.","prio":"P1","sec":"s14"},{"id":"fc-p230-df3af6","poly":"pneumo","fiche":"p230","front":"Pneumothorax : quand évacuer l'air ?","back":"PNO **mal toléré** (dyspnée) ou de **grande abondance**.","prio":"P1","sec":"s14"},{"id":"fc-p230-6d2a0b","poly":"pneumo","fiche":"p230","front":"Pneumothorax de grande abondance : quelle définition ?","back":"Décollement **sur toute la hauteur** de la ligne axillaire, largeur **≥ 2 cm** au hile.","prio":"P2","sec":"s14"},{"id":"fc-p230-055d05","poly":"pneumo","fiche":"p230","front":"PNO non grave à évacuer : quelles alternatives au drain chirurgical ?","back":"**Exsufflation simple** ou **cathéter de petit calibre**.","prio":"P2","sec":"s14"},{"id":"fc-p230-196ed7","poly":"pneumo","fiche":"p230","front":"Exsufflation : où ponctionner ?","back":"Voie **antérieure**, **2e ou 3e espace intercostal**, en dehors de la ligne médio-claviculaire.","prio":"P2","sec":"s14"},{"id":"fc-p230-ff7d47","poly":"pneumo","fiche":"p230","front":"Exsufflation : quelle technique ?","back":"Aspiration à la **seringue de 50 mL**, retrait du cathéter, **contrôle radiologique**.","prio":"P2","sec":"s14"},{"id":"fc-p230-2a848b","poly":"pneumo","fiche":"p230","front":"Exsufflation : quel taux de succès et que faire en cas d'échec ?","back":"Environ **50 %** ; si échec, **drain de petit calibre**.","prio":"P2","sec":"s14"},{"id":"fc-p230-ad1e19","poly":"pneumo","fiche":"p230","front":"PNO mal toléré ou abondant : quel geste selon le type ?","back":"Spontané primaire : **exsufflation ou petit drain** ; secondaire : **petit drain** ; traumatique : **drain**.","prio":"P3","sec":"s14"},{"id":"fc-p230-46beaf","poly":"pneumo","fiche":"p230","front":"PNO bien toléré de faible abondance : quelle attitude selon le type ?","back":"Primaire : **surveillance** ; secondaire : **drain** (sauf tout petit décollement) ; traumatique : surveillance (drain si ventilé).","prio":"P3","sec":"s14"},{"id":"fc-p230-a6c306","poly":"pneumo","fiche":"p230","front":"Drainage pleural du PNO : quelles modalités ?","back":"Drain **≤ 14 Fr**, valve anti-retour ou écoulement libre ; aspiration douce (**-5 à -20 cm H₂O**) si non recollement.","prio":"P3","sec":"s14"},{"id":"fc-p230-5fc367","poly":"pneumo","fiche":"p230","front":"Pneumothorax : comment prévenir les récidives ?","back":"**Arrêt du tabac** et **pleurodèse**.","prio":"P3","sec":"s14"},{"id":"fc-p230-edb401","poly":"pneumo","fiche":"p230","front":"Pleurodèse : quand la proposer ?","back":"**Récidive** ou PNO **persistant après 3-5 jours** de drainage malgré l'aspiration.","prio":"P3","sec":"s14"},{"id":"fc-p230-3f080e","poly":"pneumo","fiche":"p230","front":"Après un PNO spontané : quelles règles pour l'avion et la plongée ?","back":"Avion : délai théorique de **2 semaines** ; **plongée en bouteille définitivement contre-indiquée**, même opéré.","prio":"P3","sec":"s14"},{"id":"fc-p230-762323","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes associés généraux, neurologiques et digestifs rechercher ?","back":"Généraux : **fièvre**, sueurs, AEG · neurologiques : déficit, **syncope**, lipothymie, troubles de la vigilance · digestifs : vomissements, **dysphagie**.","prio":"P3","sec":"s2"},{"id":"fc-p230-4b3621","poly":"pneumo","fiche":"p230","front":"Douleur thoracique déclenchée par un traumatisme : quelle origine évoquer ?","back":"Une **lésion pariétale**.","prio":"P2","sec":"s2"},{"id":"fc-p230-07b3d0","poly":"pneumo","fiche":"p230","front":"Douleur thoracique : quels signes de gravité immédiate cite le tableau d'orientation ?","back":"**Dyspnée**, **cyanose** · **hypotension**, **sueurs** · **syncope**, **lipothymie**.","prio":"P1","sec":"s3"},{"id":"fc-p230-994bcf","poly":"pneumo","fiche":"p230","front":"ECG devant une douleur thoracique : quand le faire et que rechercher ?","back":"**Dès que possible** aux urgences : souffrance **coronarienne**, **péricardite**, troubles de **conduction** ou du **rythme**.","prio":"P2","sec":"s4"},{"id":"fc-p230-a4371b","poly":"pneumo","fiche":"p230","front":"Radiographie de thorax : quelles causes évoque une cardiomégalie ?","back":"**Insuffisance cardiaque gauche**, **tamponnade**.","prio":"P3","sec":"s4"},{"id":"fc-p230-743e4c","poly":"pneumo","fiche":"p230","front":"Pneumomédiastin : quelle fréquence et quelles circonstances ?","back":"**Rare** ; **traumatique ou spontané** ; parfois associé à un **PNO**.","prio":"P3","sec":"s6"},{"id":"fc-p230-3edb14","poly":"pneumo","fiche":"p230","front":"Douleur thoracique post-traumatique : quelles caractéristiques ?","back":"Souvent **fractures de côtes** ; douleur **localisée**, **intense**, majorée à l'inspiration profonde et à la toux, parfois **permanente**.","prio":"P3","sec":"s6"},{"id":"fc-p230-17e37c","poly":"pneumo","fiche":"p230","front":"Douleur thoracique d'origine digestive : quel siège est le plus souvent en cause ?","back":"L'**œsophage** (RGO surtout, spasmes) ; plus rarement gastro-duodénal, pancréatique ou hépatique.","prio":"P2","sec":"s7"},{"id":"fc-p230-dbd2e5","poly":"pneumo","fiche":"p230","front":"EP : quelle place pour l'HBPM ou le fondaparinux par rapport à l'HNF ?","back":"**Préférés à l'HNF** (sous-cutanés) ; efficacité **équivalente** entre HNF, HBPM et fondaparinux.","prio":"P3","sec":"s12"},{"id":"fc-p309-446f75","poly":"pneumo","fiche":"p309","front":"Cancer du poumon en France : quelle incidence annuelle ?","back":"Plus de **46 000** nouveaux cas par an (2,1 millions dans le monde).","prio":"P3","sec":"s1"},{"id":"fc-p309-b9e65b","poly":"pneumo","fiche":"p309","front":"Cancer du poumon en France : quel rang parmi les tumeurs solides ?","back":"**2e** chez l'homme, **3e** chez la femme.","prio":"P3","sec":"s1"},{"id":"fc-p309-0bbc35","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle place dans la mortalité par cancer en France ?","back":"**1re cause** (**20 %** des décès par cancer), plus de **33 000** décès par an.","prio":"P2","sec":"s1"},{"id":"fc-p309-95fecb","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle survie à 5 ans tous stades confondus ?","back":"**17 %** (points clés) ; **< 20 %** (texte).","prio":"P2","sec":"s1"},{"id":"fc-p309-00a01a","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : pourquoi l'évolution diffère-t-elle selon le sexe ?","back":"Suit celle du **tabagisme** : faible baisse chez l'homme, **hausse chez la femme**.","prio":"P3","sec":"s1"},{"id":"fc-p309-36a327","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : pourquoi est-il accessible à la prévention primaire ?","back":"Son principal facteur de risque, le **tabac**, est identifié et **évitable**.","prio":"P2","sec":"s1"},{"id":"fc-p309-8f0960","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle part est attribuable au tabac ?","back":"**85 %** : principal facteur de risque.","prio":"P2","sec":"s2"},{"id":"fc-p309-75a642","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle part a une exposition professionnelle ?","back":"Près de **20 %**.","prio":"P1","sec":"s2"},{"id":"fc-p309-4056d2","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelles expositions professionnelles les plus fréquentes ?","back":"**Amiante** · **silice** · **hydrocarbures aromatiques polycycliques** · **diesel**.","prio":"P1","sec":"s2"},{"id":"fc-p309-f8cfc3","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quand faire une enquête professionnelle ?","back":"**Systématiquement**, à tout diagnostic.","prio":"P1","sec":"s2"},{"id":"fc-p309-240011","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : pourquoi le rôle professionnel est-il sous-estimé ?","back":"Le **tabac** est un **facteur confondant**.","prio":"P2","sec":"s2"},{"id":"fc-p309-090e27","poly":"pneumo","fiche":"p309","front":"Radon : quelles caractéristiques ?","back":"**Gaz radioactif naturel**, incolore et inodore, présent dans le **sol** et la **pierre**.","prio":"P2","sec":"s2"},{"id":"fc-p309-dd91fc","poly":"pneumo","fiche":"p309","front":"Radon : quel rôle dans le cancer du poumon ?","back":"**Fortement suspecté** d'en causer en France, notamment chez le **non-fumeur**.","prio":"P1","sec":"s2"},{"id":"fc-p309-cdc0a4","poly":"pneumo","fiche":"p309","front":"Pollution atmosphérique : quel rôle dans le cancer du poumon ?","back":"**Facteur de risque**, notamment la pollution **particulaire** (particules fines, diesel).","prio":"P2","sec":"s2"},{"id":"fc-p309-a970c5","poly":"pneumo","fiche":"p309","front":"Tabac : quels paramètres pèsent le plus sur la carcinogenèse ?","back":"L'**âge de début** (précocité) et la **durée** du tabagisme.","prio":"P2","sec":"s2"},{"id":"fc-p309-a0cc11","poly":"pneumo","fiche":"p309","front":"Paquets-années : pourquoi évaluent-ils mal le risque ?","back":"La quantité agit à la **puissance deux**, la durée à la **puissance quatre**.","prio":"P2","sec":"s2"},{"id":"fc-p309-95d974","poly":"pneumo","fiche":"p309","front":"Tabac : existe-t-il un seuil de consommation sans risque ?","back":"**Non**, pas de seuil.","prio":"P2","sec":"s2"},{"id":"fc-p309-342c04","poly":"pneumo","fiche":"p309","front":"Arrêt du tabac : quelle évolution du risque de cancer ?","back":"Il **diminue** sans revenir à celui du non-fumeur ; arrêter reste utile **à tout âge**.","prio":"P2","sec":"s2"},{"id":"fc-p309-e242fe","poly":"pneumo","fiche":"p309","front":"Tabagisme passif : quelle part des cancers du non-fumeur ?","back":"Environ **un quart** ; risque notamment chez l'enfant.","prio":"P2","sec":"s2"},{"id":"fc-p309-2ccf92","poly":"pneumo","fiche":"p309","front":"Quelles maladies respiratoires augmentent le risque de cancer du poumon indépendamment du tabac ?","back":"**BPCO** et pathologies **fibrosantes**.","prio":"P2","sec":"s2"},{"id":"fc-p309-118fa8","poly":"pneumo","fiche":"p309","front":"Antécédent de cancer du poumon : quel risque ?","back":"Risque accru d'un **second cancer**, surtout si le tabac continue (carcinogenèse en champ).","prio":"P2","sec":"s2"},{"id":"fc-p309-584650","poly":"pneumo","fiche":"p309","front":"Mutations EGFR, KRAS : sont-elles constitutionnelles ?","back":"**Non** : **somatiques**, présentes dans les cellules cancéreuses seulement.","prio":"P2","sec":"s2"},{"id":"fc-p309-ff6ab4","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quels sont les deux grands types histologiques ?","back":"**CBNPC** (adénocarcinome, épidermoïde, autres) et **cancer à petites cellules** (CPC).","prio":"P2","sec":"s3"},{"id":"fc-p309-0b83e1","poly":"pneumo","fiche":"p309","front":"CBNPC et CPC : quelles proportions ?","back":"CBNPC **85 %**, CPC **15 %** (texte) ; points clés : CBNPC > 80 %, CPC < 15 %.","prio":"P2","sec":"s3"},{"id":"fc-p309-3e6a4f","poly":"pneumo","fiche":"p309","front":"Adénocarcinome bronchique : quelle fréquence et quel siège ?","back":"**Le plus fréquent** (majorité des CBNPC), le plus souvent **périphérique**.","prio":"P2","sec":"s3"},{"id":"fc-p309-662298","poly":"pneumo","fiche":"p309","front":"Adénocarcinome : quel marqueur immunohistochimique ?","back":"**TTF1** le plus souvent positif ; architecture **glandulaire**.","prio":"P2","sec":"s3"},{"id":"fc-p309-25bcba","poly":"pneumo","fiche":"p309","front":"Carcinome épidermoïde : quel siège et quel marqueur ?","back":"**Proximal** ; marquage **p40** positif.","prio":"P2","sec":"s3"},{"id":"fc-p309-36698e","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules : quelle présentation ?","back":"Le plus souvent tumeur **volumineuse**, **proximale**, étendue au **médiastin** (compressions) ; syndromes **paranéoplasiques** fréquents.","prio":"P2","sec":"s3"},{"id":"fc-p309-5db8ba","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules : quel marquage immunohistochimique ?","back":"**Neuroendocrine**.","prio":"P2","sec":"s3"},{"id":"fc-p309-b7589b","poly":"pneumo","fiche":"p309","front":"Addiction oncogénique : citer les principales altérations ?","back":"Mutation **EGFR**, réarrangement **ALK** ou **ROS1**.","prio":"P2","sec":"s3"},{"id":"fc-p309-8cdf0d","poly":"pneumo","fiche":"p309","front":"Addiction oncogénique : chez qui la trouve-t-on surtout ?","back":"**Adénocarcinomes** et **non-fumeurs** (jamais fumeurs ou sevrés depuis > 10 ans).","prio":"P2","sec":"s3"},{"id":"fc-p309-7cc67c","poly":"pneumo","fiche":"p309","front":"Addiction oncogénique : que prédit-elle ?","back":"La réponse aux **inhibiteurs de tyrosine kinase** (ITK).","prio":"P2","sec":"s3"},{"id":"fc-p309-2a396c","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle proportion diagnostiquée à un stade avancé ou métastatique ?","back":"**Trois quarts**.","prio":"P1","sec":"s4"},{"id":"fc-p309-e69a78","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : pourquoi un diagnostic souvent tardif ?","back":"Pas d'**innervation nociceptive** · symptômes **non spécifiques** · symptômes tardifs (organes centraux, paroi, plèvre, métastases).","prio":"P2","sec":"s4"},{"id":"fc-p309-deb11e","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quels symptômes respiratoires révélateurs ?","back":"**Toux**, **dyspnée**, **hémoptysie**, infection respiratoire basse **récidivante**.","prio":"P1","sec":"s4"},{"id":"fc-p309-07ee13","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quels signes d'extension locorégionale ?","back":"**Syndrome cave supérieur** · **dysphonie** · douleur thoracique · **syndrome de Pancoast**.","prio":"P1","sec":"s4"},{"id":"fc-p309-c93fd1","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelles autres circonstances de découverte ?","back":"**Métastase** · **AEG** inexpliquée · **maladie thromboembolique** sans cause · syndrome **paranéoplasique** · découverte **fortuite**.","prio":"P2","sec":"s4"},{"id":"fc-p309-66adf4","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : citer des syndromes paranéoplasiques ?","back":"**Hippocratisme**, ostéoarthropathie hypertrophiante · **SIADH** · fièvre au long cours · pseudomyasthénie, neuropathies · **hypercalcémie** · **Cushing**.","prio":"P1","sec":"s4"},{"id":"fc-p309-ac7437","poly":"pneumo","fiche":"p309","front":"Hypercalcémie et Cushing paranéoplasiques : quels mécanismes ?","back":"Sécrétion de **pseudo-PTH** et de **pseudo-ACTH**.","prio":"P2","sec":"s4"},{"id":"fc-p309-11d332","poly":"pneumo","fiche":"p309","front":"Syndrome cave supérieur : quel mécanisme ?","back":"Compression de la **veine cave supérieure** par la tumeur ou des **adénopathies latéro-trachéales droites**.","prio":"P1","sec":"s4"},{"id":"fc-p309-cfb4c9","poly":"pneumo","fiche":"p309","front":"Syndrome de Pancoast : quel mécanisme ?","back":"Tumeur de l'**apex** envahissant paroi, **plexus brachial** et **ganglion stellaire**.","prio":"P1","sec":"s4"},{"id":"fc-p309-d2c97e","poly":"pneumo","fiche":"p309","front":"Syndrome de Pancoast : quels signes ?","back":"Névralgie cervico-brachiale **C8-D1** + **Claude Bernard-Horner** homolatéral → scanner thoracique.","prio":"P1","sec":"s4"},{"id":"fc-p309-002c5d","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quels sites métastatiques extrathoraciques les plus fréquents ?","back":"**Cerveau** · **os** · **foie** · **surrénales**.","prio":"P1","sec":"s4"},{"id":"fc-p309-8f4eb2","poly":"pneumo","fiche":"p309","front":"Syndrome paranéoplasique : quelle définition ?","back":"Manifestation **à distance** due à une substance sécrétée ou à une réaction immunitaire, **sans envahissement** de l'organe.","prio":"P2","sec":"s4"},{"id":"fc-p309-4dd4df","poly":"pneumo","fiche":"p309","front":"Syndrome paranéoplasique qui réapparaît après résection complète : que craindre ?","back":"Une **rechute** tumorale.","prio":"P1","sec":"s4"},{"id":"fc-p309-2d977d","poly":"pneumo","fiche":"p309","front":"Fumeur de 40 ans ou plus avec signe d'appel : quel examen initial ?","back":"**Scanner thoracique**.","prio":"P1","sec":"s5"},{"id":"fc-p309-d3a46b","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle place de la radiographie thoracique ?","back":"**Marginale** : élimine surtout une autre cause (infection, plèvre), peut montrer une masse.","prio":"P2","sec":"s5"},{"id":"fc-p309-d28299","poly":"pneumo","fiche":"p309","front":"Radiographie thoracique normale : élimine-t-elle un cancer du poumon ?","back":"**Non**.","prio":"P1","sec":"s5"},{"id":"fc-p309-4cf7f1","poly":"pneumo","fiche":"p309","front":"Scanner thoracique et bronchoscopie : dans quel ordre ?","back":"**Scanner d'abord**, pour orienter les prélèvements.","prio":"P1","sec":"s5"},{"id":"fc-p309-21e328","poly":"pneumo","fiche":"p309","front":"Scanner pour le bilan d'extension : quelles modalités ?","back":"**Injecté**, étages **thoracique**, **abdominal** (surrénales incluses) et **encéphalique**.","prio":"P2","sec":"s5"},{"id":"fc-p309-d9f6ae","poly":"pneumo","fiche":"p309","front":"Scanner : que précise-t-il sur la tumeur primitive ?","back":"Siège **central ou périphérique**, caractère systématisé ou rétractile, rapports avec **paroi, plèvre, médiastin**.","prio":"P3","sec":"s5"},{"id":"fc-p309-5ed3e5","poly":"pneumo","fiche":"p309","front":"TEP-TDM au 18FDG : quel principe ?","back":"Glucose marqué fixé par les tissus à **haut métabolisme** : tumeurs, mais aussi **inflammation** et **infection**.","prio":"P2","sec":"s5"},{"id":"fc-p309-eb7b5e","poly":"pneumo","fiche":"p309","front":"TEP-TDM : chez quels patients est-elle indiquée ?","back":"Si une **chirurgie** ou une **radiothérapie curative** est envisagée (formes localisées ou localement avancées).","prio":"P1","sec":"s5"},{"id":"fc-p309-795fc9","poly":"pneumo","fiche":"p309","front":"TEP-TDM : quelle valeur pour le bilan d'extension ?","back":"**Valeur prédictive négative élevée**.","prio":"P2","sec":"s5"},{"id":"fc-p309-f012a2","poly":"pneumo","fiche":"p309","front":"TEP-TDM : quelles indications les plus pertinentes ?","back":"Caractériser un **nodule incertain** · **staging médiastinal** d'un cancer opérable · bilan à distance avant traitement local.","prio":"P2","sec":"s5"},{"id":"fc-p309-67fd10","poly":"pneumo","fiche":"p309","front":"Adénopathie de taille normale au scanner mais hypermétabolique en TEP : que faire ?","back":"Peut justifier un **examen histologique** avant la décision chirurgicale.","prio":"P2","sec":"s5"},{"id":"fc-p309-478dc2","poly":"pneumo","fiche":"p309","front":"IRM thoracique dans le cancer du poumon : quelle place ?","back":"Aucune sauf exception : rapports d'une **tumeur de l'apex** (Pancoast) quand le scanner ne suffit pas.","prio":"P3","sec":"s5"},{"id":"fc-p309-766689","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : sur quoi repose le diagnostic positif ?","back":"Une **preuve histologique** (biopsie ou ponction).","prio":"P1","sec":"s6"},{"id":"fc-p309-629611","poly":"pneumo","fiche":"p309","front":"Lésion centrale (autour de la carène) : quel prélèvement ?","back":"Habituellement **bronchoscopie souple** avec biopsies (anesthésie locale ou sédation).","prio":"P1","sec":"s6"},{"id":"fc-p309-bc1ffc","poly":"pneumo","fiche":"p309","front":"Lésion périphérique (tiers externe) : quel prélèvement ?","back":"Habituellement **ponction transpariétale** à l'aiguille sous **scanner** ; à défaut, vidéo-thoracoscopie.","prio":"P1","sec":"s6"},{"id":"fc-p309-ca4f4d","poly":"pneumo","fiche":"p309","front":"Lésion ni centrale ni périphérique : quels prélèvements possibles ?","back":"**Fibroscopie**, **ponction transpariétale** ou **vidéo-thoracoscopie**.","prio":"P2","sec":"s9"},{"id":"fc-p309-955f95","poly":"pneumo","fiche":"p309","front":"Adénopathies au contact de la trachée : quel prélèvement ?","back":"Ponction sous **écho-endoscopie bronchique**, ou **médiastinoscopie**.","prio":"P1","sec":"s6"},{"id":"fc-p309-24be3e","poly":"pneumo","fiche":"p309","front":"Ponction transpariétale : quelle complication et quelle fréquence ?","back":"**Pneumothorax** dans **10 à 20 %**, souvent minime et bien toléré.","prio":"P1","sec":"s6"},{"id":"fc-p309-1639e4","poly":"pneumo","fiche":"p309","front":"Ponction transpariétale : quand l'échoguider plutôt que la scanoguider ?","back":"Si la lésion **touche directement la paroi**.","prio":"P3","sec":"s6"},{"id":"fc-p309-2d657f","poly":"pneumo","fiche":"p309","front":"Bronchoscopie souple : jusqu'où voit-elle ?","back":"Jusqu'au niveau **sous-segmentaire**.","prio":"P3","sec":"s6"},{"id":"fc-p309-606aec","poly":"pneumo","fiche":"p309","front":"Médiastinoscopie : quels sites atteint-elle ?","back":"Les sites ganglionnaires **latéro-trachéaux**.","prio":"P3","sec":"s6"},{"id":"fc-p309-316521","poly":"pneumo","fiche":"p309","front":"Vidéo-thoracoscopie : quelles indications diagnostiques ?","back":"**Épanchement pleural exsudatif** · ganglions inaccessibles en médiastinoscopie (gauche, sous-carinaires) · lésion périphérique non ponctionnable.","prio":"P3","sec":"s6"},{"id":"fc-p309-87a160","poly":"pneumo","fiche":"p309","front":"Techniques chirurgicales de prélèvement : quand y recourir ?","back":"Échec des méthodes moins invasives, **pas de lésion à distance** accessible simplement, **suspicion élevée**.","prio":"P3","sec":"s6"},{"id":"fc-p309-47d31b","poly":"pneumo","fiche":"p309","front":"Adénopathie sus-claviculaire ou métastase cutanée palpable : quelle conduite ?","back":"La **biopsier en priorité** : geste peu risqué, positivité = **N3** ou **M1**.","prio":"P2","sec":"s6"},{"id":"fc-p309-1ea780","poly":"pneumo","fiche":"p309","front":"Biopsie à distance : quelles cibles possibles ?","back":"**Adénopathie sus-claviculaire**, métastase **cutanée**, **hépatique**, lésion **ostéolytique**, métastase **cérébrale**.","prio":"P3","sec":"s6"},{"id":"fc-p309-6b2d28","poly":"pneumo","fiche":"p309","front":"Prélèvement initial : pourquoi en prélever une quantité importante ?","back":"Pour les **recherches moléculaires** (thérapies ciblées, immunothérapie) ; à défaut, cytologie riche en cellules tumorales.","prio":"P2","sec":"s6"},{"id":"fc-p309-e01e29","poly":"pneumo","fiche":"p309","front":"CBNPC localement avancé ou métastatique : quel marqueur rechercher systématiquement ?","back":"**PD-L1** sur les cellules tumorales (guide l'immunothérapie).","prio":"P1","sec":"s6"},{"id":"fc-p309-17996a","poly":"pneumo","fiche":"p309","front":"Analyse moléculaire avant 1re ligne : quelles altérations au minimum ?","back":"**ALK**, **ROS1**, **EGFR**, **KRAS**.","prio":"P1","sec":"s6"},{"id":"fc-p309-8910a0","poly":"pneumo","fiche":"p309","front":"Analyse moléculaire : pour quels cancers avancés est-elle recommandée ?","back":"**Non épidermoïdes** de stade avancé et **épidermoïdes du non-fumeur**.","prio":"P1","sec":"s6"},{"id":"fc-p309-da0e37","poly":"pneumo","fiche":"p309","front":"Marqueurs tumoraux sériques dans le cancer du poumon : quelle indication ?","back":"**Aucune** : dosage non recommandé.","prio":"P1","sec":"s6"},{"id":"fc-p309-e0f5ca","poly":"pneumo","fiche":"p309","front":"Bilan pré-thérapeutique : quelles 3 questions dans l'ordre ?","back":"**Petites cellules ou non ?** · si CBNPC, **résécable ?** · si oui, **opérable ?**","prio":"P2","sec":"s7"},{"id":"fc-p309-5b7a51","poly":"pneumo","fiche":"p309","front":"Bilan d'extension : quels examens d'imagerie systématiques ?","back":"Scanner **thoraco-abdomino-pelvien injecté** (sauf contre-indication) + **imagerie cérébrale injectée** (scanner ou IRM).","prio":"P1","sec":"s7"},{"id":"fc-p309-ffe7ee","poly":"pneumo","fiche":"p309","front":"TEP-TDM : en première intention dans le bilan d'extension ?","back":"**Non** : seulement si maladie **a priori localisée** au scanner.","prio":"P1","sec":"s7"},{"id":"fc-p309-812791","poly":"pneumo","fiche":"p309","front":"Extension ganglionnaire au scanner : que signifient N1 et N2 ?","back":"N1 : **hilaire** ; N2 : **médiastinal homolatéral** ou **sous-carinaire**.","prio":"P2","sec":"s7"},{"id":"fc-p309-60e16d","poly":"pneumo","fiche":"p309","front":"Extension ganglionnaire : que signifie N3 ?","back":"**Médiastinal controlatéral** ou **sus-claviculaire**.","prio":"P2","sec":"s7"},{"id":"fc-p309-b83b31","poly":"pneumo","fiche":"p309","front":"Preuve histologique d'une atteinte ganglionnaire : quel examen en 1re intention ?","back":"L'**écho-endoscopie**.","prio":"P2","sec":"s7"},{"id":"fc-p309-126b96","poly":"pneumo","fiche":"p309","front":"cTNM vs pTNM : quelle différence ?","back":"**cTNM** : extension clinique (examens) ; **pTNM** : anatomopathologique post-opératoire (T et surtout N sur la pièce).","prio":"P2","sec":"s7"},{"id":"fc-p309-2429e0","poly":"pneumo","fiche":"p309","front":"CBNPC : quels sont les 3 stades pratiques ?","back":"**Localisé** (I-II) · **localement avancé** (III) · **disséminé** (IV).","prio":"P1","sec":"s7"},{"id":"fc-p309-d148bc","poly":"pneumo","fiche":"p309","front":"CBNPC : quelle part de chaque stade pratique ?","back":"Localisé **15-30 %** · localement avancé **~20 %** · disséminé **50 %**.","prio":"P2","sec":"s7"},{"id":"fc-p309-9edf57","poly":"pneumo","fiche":"p309","front":"Performance Status : que signifie PS 2 ?","back":"**Autonome**, se fatigue, repos **moins de la moitié** des heures de veille.","prio":"P2","sec":"s7"},{"id":"fc-p309-c90303","poly":"pneumo","fiche":"p309","front":"Performance Status : que signifie PS 3 ?","back":"**Dépendant**, lever possible, repos **plus de la moitié** des heures de veille.","prio":"P2","sec":"s7"},{"id":"fc-p309-3f16ee","poly":"pneumo","fiche":"p309","front":"Performance Status : que signifient PS 0, 1 et 4 ?","back":"0 : **normal** ; 1 : **efforts réduits**, autonomie complète ; 4 : **dépendance totale**, grabataire.","prio":"P2","sec":"s7"},{"id":"fc-p309-46a13c","poly":"pneumo","fiche":"p309","front":"État général dans le cancer du poumon : quelle importance ?","back":"Conditionne la **décision thérapeutique** ; **facteur pronostique majeur**.","prio":"P1","sec":"s7"},{"id":"fc-p309-9c6413","poly":"pneumo","fiche":"p309","front":"L'âge civil contre-indique-t-il la chirurgie du cancer du poumon ?","back":"**Non** : ce sont les **comorbidités**, surtout cardio-respiratoires.","prio":"P1","sec":"s7"},{"id":"fc-p309-811969","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quel autre facteur pronostique évaluer systématiquement ?","back":"L'**état nutritionnel**.","prio":"P1","sec":"s7"},{"id":"fc-p309-f039e4","poly":"pneumo","fiche":"p309","front":"Bilan d'opérabilité : que rechercher à l'examen clinique ?","back":"**BPCO**, **insuffisance respiratoire**, classe fonctionnelle de la **dyspnée** ; comorbidités **cardiovasculaires** systématiquement.","prio":"P2","sec":"s7"},{"id":"fc-p309-7b755d","poly":"pneumo","fiche":"p309","front":"Traitement local envisagé : quelles EFR au minimum ?","back":"**Spirométrie** et **DLCO**.","prio":"P1","sec":"s7"},{"id":"fc-p309-d1a2c5","poly":"pneumo","fiche":"p309","front":"EFR anormales avant chirurgie : quels examens complémentaires ?","back":"**Épreuve d'effort** cardio-respiratoire (VO₂max) + **scintigraphie** de ventilation/perfusion.","prio":"P2","sec":"s7"},{"id":"fc-p309-07de38","poly":"pneumo","fiche":"p309","front":"Chirurgie d'exérèse : sous quel VEMS post-opératoire prédit n'est-elle pas envisageable ?","back":"**< 1 litre** ou **< 30 %** de la théorique.","prio":"P1","sec":"s11"},{"id":"fc-p309-4c99ec","poly":"pneumo","fiche":"p309","front":"Lobectomie : quelle part des capacités respiratoires enlève-t-elle ?","back":"Environ **un quart** (lobe moyen non compté) ; ex. VEMS 80 % → ~60 % prédit.","prio":"P2","sec":"s11"},{"id":"fc-p309-113800","poly":"pneumo","fiche":"p309","front":"Cancer du poumon après 70 ans : quelle évaluation ?","back":"**Oncogériatrique**, au minimum par le score **G8**.","prio":"P1","sec":"s7"},{"id":"fc-p309-ee2083","poly":"pneumo","fiche":"p309","front":"Métastases pulmonaires : quels cancers primitifs possibles ?","back":"Cancers **épithéliaux**, **sarcomes**, **mélanomes**, cancer du poumon lui-même…","prio":"P2","sec":"s8"},{"id":"fc-p309-be7191","poly":"pneumo","fiche":"p309","front":"Métastases pulmonaires : quels sont les 3 tableaux radio-cliniques ?","back":"**Nodule(s)** · **épanchement pleural exsudatif** · **lymphangite carcinomateuse**.","prio":"P1","sec":"s8"},{"id":"fc-p309-78c7b7","poly":"pneumo","fiche":"p309","front":"Lâcher de ballons : quel aspect et quel exemple de primitif ?","back":"Nodules **lisses bilatéraux**, distribution hématogène ; ex. cancer du **rein**.","prio":"P2","sec":"s8"},{"id":"fc-p309-bd040c","poly":"pneumo","fiche":"p309","front":"Lymphangite carcinomateuse au scanner : quel aspect ?","back":"**Épaississement des septa interlobulaires**.","prio":"P2","sec":"s8"},{"id":"fc-p309-1a6603","poly":"pneumo","fiche":"p309","front":"Métastases pulmonaires : que rechercher systématiquement à l'examen ?","back":"**Adénopathies** axillaires, sus-claviculaires et cervicales (examen souvent pauvre).","prio":"P1","sec":"s8"},{"id":"fc-p309-bc0c51","poly":"pneumo","fiche":"p309","front":"Métastases pulmonaires d'un primitif inconnu : quelle 1re hypothèse ?","back":"Un **cancer du poumon**, surtout chez un **fumeur** actif ou sevré.","prio":"P1","sec":"s8"},{"id":"fc-p309-e64594","poly":"pneumo","fiche":"p309","front":"Métastases d'un primitif inconnu : quelle enquête ?","back":"Rechercher un cancer **accessible à un traitement actif** ; **TEP-TDM** recommandée ; dossier en **RCP**.","prio":"P1","sec":"s8"},{"id":"fc-p309-3fedd9","poly":"pneumo","fiche":"p309","front":"Primitif inconnu : quels cancers chercher en priorité ?","back":"Accessibles à un traitement actif : **poumon**, **gonades**, **thyroïde**, **sein**, endomètre, **prostate**.","prio":"P2","sec":"s18"},{"id":"fc-p309-0aebf5","poly":"pneumo","fiche":"p309","front":"Métastases d'un primitif connu : la biopsie est-elle systématique ?","back":"**Non** : une image typique peut suffire ; biopsie si la **RCP** l'exige (plan modifié, phénotype ou génotype changé).","prio":"P2","sec":"s8"},{"id":"fc-p309-9382fe","poly":"pneumo","fiche":"p309","front":"Primitif ancien guéri : combien de temps après des métastases peuvent-elles survenir ?","back":"**Plus de 10 ans** après (ex. cancer du **sein**).","prio":"P2","sec":"s8"},{"id":"fc-p309-8f31b8","poly":"pneumo","fiche":"p309","front":"Primitif ancien guéri avec atteinte pulmonaire isolée : quelle conduite ?","back":"Enquête complète avec **prélèvement histologique** ; discuter un **traitement local radical**.","prio":"P1","sec":"s8"},{"id":"fc-p309-cd4a0a","poly":"pneumo","fiche":"p309","front":"Métastases pulmonaires isolées d'un primitif ancien : quels traitements locaux possibles ?","back":"**Chirurgie**, **radiothérapie stéréotaxique**, **radiofréquence**.","prio":"P2","sec":"s18"},{"id":"fc-p309-c38a9e","poly":"pneumo","fiche":"p309","front":"Cancer du poumon prouvé : qui valide les décisions ?","back":"La **RCP** d'oncologie thoracique → **Plan Personnalisé de Soins** écrit.","prio":"P1","sec":"s10"},{"id":"fc-p309-704549","poly":"pneumo","fiche":"p309","front":"Dispositif d'annonce : qu'explique-t-on au patient ?","back":"Principes des traitements, **effets indésirables**, **signes d'alerte**, bénéfice attendu, rythme des évaluations.","prio":"P2","sec":"s10"},{"id":"fc-p309-50e5c4","poly":"pneumo","fiche":"p309","front":"Cancer du poumon prouvé : quelle mesure impérative concernant le tabac ?","back":"**Arrêt du tabac** dans tous les cas.","prio":"P1","sec":"s10"},{"id":"fc-p309-694d29","poly":"pneumo","fiche":"p309","front":"Tabac poursuivi pendant le traitement : quelles conséquences ?","back":"↑ **complications péri-opératoires** ; ↓ efficacité des **ITK** et de la **chimiothérapie** (induction enzymatique).","prio":"P1","sec":"s10"},{"id":"fc-p309-0982f2","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quand débuter les soins de support ?","back":"**Dès le diagnostic**, quel que soit le stade.","prio":"P1","sec":"s10"},{"id":"fc-p309-b8591f","poly":"pneumo","fiche":"p309","front":"Cancer du poumon et exposition professionnelle : quelles démarches ?","back":"Déclarer en **maladie professionnelle** si tableau rempli ; **FIVA** si cancer lié à l'**amiante**.","prio":"P2","sec":"s10"},{"id":"fc-p309-f7a9fc","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quelle attitude vis-à-vis des essais cliniques ?","back":"Encourager **systématiquement** la participation.","prio":"P2","sec":"s10"},{"id":"fc-p309-c12c44","poly":"pneumo","fiche":"p309","front":"CBNPC localisé (I-II) opérable : quel traitement ?","back":"**Chirurgie d'exérèse** (résection anatomique) ± **chimiothérapie adjuvante** selon le pTNM.","prio":"P1","sec":"s12"},{"id":"fc-p309-9d0a76","poly":"pneumo","fiche":"p309","front":"CBNPC localisé non opérable : quel traitement ?","back":"**Radiothérapie curative**, si possible **stéréotaxique**.","prio":"P1","sec":"s12"},{"id":"fc-p309-352439","poly":"pneumo","fiche":"p309","front":"Chimiothérapie adjuvante d'un CBNPC : de quoi dépend l'indication ?","back":"Du **stade post-opératoire (pTNM)**.","prio":"P2","sec":"s12"},{"id":"fc-p309-b86cac","poly":"pneumo","fiche":"p309","front":"Chimiothérapie du cancer du poumon : quelle base ?","back":"**Sels de platine**, en règle en **doublet**.","prio":"P1","sec":"s12"},{"id":"fc-p309-dadd59","poly":"pneumo","fiche":"p309","front":"CBNPC localement avancé (III) : quel principe de traitement ?","back":"**Traitement local** (chirurgie ou radiothérapie) + **chimiothérapie** (doublet platine).","prio":"P1","sec":"s13"},{"id":"fc-p309-b25b5a","poly":"pneumo","fiche":"p309","front":"CBNPC stade III traité par radiothérapie : quelle modalité ?","back":"**Radio-chimiothérapie concomitante** si possible, puis **immunothérapie de consolidation**.","prio":"P1","sec":"s13"},{"id":"fc-p309-d23444","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique (IV) : quel traitement ?","back":"**Traitement systémique exclusif** (chimiothérapie, thérapie ciblée, immunothérapie).","prio":"P1","sec":"s14"},{"id":"fc-p309-98b2a2","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique : sur quels critères choisir la 1re ligne ?","back":"**Âge**, **état général**, taux de **PD-L1**, **altération moléculaire** ciblable.","prio":"P1","sec":"s14"},{"id":"fc-p309-d09525","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique avec altération addictive (EGFR, ALK, ROS1) : quel traitement ?","back":"**Thérapie ciblée par ITK**.","prio":"P2","sec":"s14"},{"id":"fc-p309-9e59e6","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique : quand une immunothérapie seule ?","back":"Si **PD-L1 > 50 %**.","prio":"P2","sec":"s14"},{"id":"fc-p309-20713f","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique : chimio-immunothérapie selon quel PD-L1 ?","back":"**Quel que soit** le PD-L1.","prio":"P2","sec":"s14"},{"id":"fc-p309-23b1c0","poly":"pneumo","fiche":"p309","front":"CBNPC métastatique non éligible à l'immunothérapie : quel traitement ?","back":"**Chimiothérapie conventionnelle** avec un **sel de platine**.","prio":"P2","sec":"s14"},{"id":"fc-p309-b42bb0","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules : quel délai de traitement ?","back":"**Urgence** oncologique : chimiothérapie **le plus tôt possible**.","prio":"P1","sec":"s15"},{"id":"fc-p309-ba5a1d","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules non traité : quelle évolution ?","back":"Décès en **moins de 3 mois** (doublement cellulaire très court).","prio":"P1","sec":"s15"},{"id":"fc-p309-90b4de","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules métastatique : quel traitement ?","back":"**Doublet à base de platine** + **immunothérapie**.","prio":"P1","sec":"s15"},{"id":"fc-p309-367f39","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules limité au thorax : que faut-il ajouter à la chimiothérapie ?","back":"**Radiothérapie précoce** (avant le 2e cycle) sur tumeur et médiastin.","prio":"P2","sec":"s15"},{"id":"fc-p309-129dca","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules : quelle place de la chirurgie ?","back":"**Pas de chirurgie** en règle, quel que soit le stade, même localisé.","prio":"P1","sec":"s15"},{"id":"fc-p309-3b0cc9","poly":"pneumo","fiche":"p309","front":"Cancer à petites cellules : quelle réponse à la chimiothérapie ?","back":"Souvent **très chimiosensible**, mais **rechutes rapides** avec **chimiorésistance**.","prio":"P1","sec":"s15"},{"id":"fc-p309-d8e5df","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : comment traiter la douleur ?","back":"Antalgiques par **paliers** I → II → III sans hésiter aux **morphiniques**, en **prévenant la constipation**.","prio":"P1","sec":"s16"},{"id":"fc-p309-fc1f5e","poly":"pneumo","fiche":"p309","front":"Radiothérapie palliative antalgique : pour quelles lésions ?","back":"Lésions **osseuses**, surrénaliennes, cutanées, et lésions **menaçant la moelle**.","prio":"P1","sec":"s16"},{"id":"fc-p309-f3f5f0","poly":"pneumo","fiche":"p309","front":"Métastase menaçant la moelle : quelle chirurgie possible avant la radiothérapie ?","back":"Parfois, si l'état général le permet : **laminectomie décompressive**.","prio":"P2","sec":"s16"},{"id":"fc-p309-69ded3","poly":"pneumo","fiche":"p309","front":"Métastases vertébrales douloureuses : quelle radiologie interventionnelle ?","back":"**Cimentoplastie** percutanée, **cryothérapie**.","prio":"P2","sec":"s16"},{"id":"fc-p309-d9ffbb","poly":"pneumo","fiche":"p309","front":"Douleur de métastase osseuse : quels traitements en complément des antalgiques ?","back":"**AINS** ; **bisphosphonate** ou **inhibiteur du RANK-ligand**.","prio":"P2","sec":"s16"},{"id":"fc-p309-821982","poly":"pneumo","fiche":"p309","front":"Cancer du poumon : quel support nutritionnel ?","back":"Compléments **hypercaloriques hyperprotéiques** pour éviter une perte de poids importante.","prio":"P2","sec":"s16"},{"id":"fc-p309-b6dd82","poly":"pneumo","fiche":"p309","front":"Lymphangite carcinomateuse : quel traitement ?","back":"Étiologique = traitement du **cancer** ; symptomatique **décevant**.","prio":"P2","sec":"s17"},{"id":"fc-p309-81cdf2","poly":"pneumo","fiche":"p309","front":"Obstruction trachéale ou bronchique tumorale : que discuter ?","back":"**Désobstruction** ± **prothèse endobronchique**.","prio":"P2","sec":"s17"},{"id":"fc-p309-fc62fc","poly":"pneumo","fiche":"p309","front":"Pleurésie néoplasique récidivante : quel traitement ?","back":"**Talcage** (symphyse pleurale) ou **cathéter pleural tunnelisé** à demeure.","prio":"P2","sec":"s17"},{"id":"fc-p309-b8e820","poly":"pneumo","fiche":"p309","front":"Syndrome cave supérieur tumoral : quel traitement ?","back":"**Anticoagulation** + **corticothérapie** ; discuter un **stent cave**.","prio":"P2","sec":"s17"},{"id":"fc-p309-120fdd","poly":"pneumo","fiche":"p309","front":"Radon domestique : quelle mesure de prévention ?","back":"Vigilance accrue sur la **mesure des taux** dans certains départements.","prio":"P2","sec":"s19"},{"id":"fc-p338-6a047c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : de quel type d'hypersensibilité est-elle la forme la plus sévère ?","back":"**Hypersensibilité immédiate**.","prio":"P1","sec":"s1"},{"id":"fc-p338-8ce6d9","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : définition clinique ?","back":"Signes **brutaux**, d'aggravation rapide, touchant **au moins deux organes**, ou **chute de PA > 30 %** de la valeur de base.","prio":"P1","sec":"s1"},{"id":"fc-p338-1e4ee2","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : trois tableaux menaçant la vie ?","back":"**Choc anaphylactique**, **œdème de Quincke asphyxique**, **asthme aigu grave**.","prio":"P1","sec":"s1"},{"id":"fc-p338-b203f8","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : deux éléments qui la définissent ?","back":"Sa **sévérité** et sa **chronologie** (survenue juste après le contact).","prio":"P2","sec":"s1"},{"id":"fc-p338-1759f0","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : deux axes de classification ?","back":"Selon la **cause** (allergique ou non) et la **sévérité** (grades).","prio":"P2","sec":"s1"},{"id":"fc-p338-5e0d6f","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : mécanisme le plus fréquent ?","back":"**Allergique IgE-dépendant** (d'autres mécanismes existent).","prio":"P2","sec":"s1"},{"id":"fc-p338-3bcd07","poly":"pneumo","fiche":"p338","front":"Anaphylaxie allergique ou non allergique : qu'est-ce qui diffère ?","back":"**Prévention** et **évolution** ; signes cliniques et traitement curatif sont **identiques**.","prio":"P2","sec":"s1"},{"id":"fc-p338-1e2ad2","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : cellules dont la dégranulation libère les médiateurs ?","back":"**Basophiles** (circulants) et **mastocytes** (tissulaires).","prio":"P2","sec":"s1"},{"id":"fc-p338-7279b5","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : effets principaux des médiateurs libérés ?","back":"**Vasodilatation** et **bronchoconstriction**.","prio":"P2","sec":"s1"},{"id":"fc-p338-3431c6","poly":"pneumo","fiche":"p338","front":"Angioœdème : définition ?","back":"Vasodilatation et œdème des tissus **profonds** (derme, hypoderme, muqueuses), même mécanisme que l'urticaire.","prio":"P1","sec":"s1"},{"id":"fc-p338-007478","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke : définition ?","back":"Angioœdème **grave** de la région du **larynx** et du cou, pouvant tuer par **asphyxie**.","prio":"P1","sec":"s1"},{"id":"fc-p338-1d7376","poly":"pneumo","fiche":"p338","front":"Anaphylaxie allergique : étape de sensibilisation ?","back":"Exposition antérieure (inaperçue) : les **lymphocytes B** produisent des **IgE spécifiques**.","prio":"P2","sec":"s2"},{"id":"fc-p338-becdbf","poly":"pneumo","fiche":"p338","front":"IgE : récepteur de forte affinité et cellules porteuses ?","back":"**FcεRI** sur **basophiles** et **mastocytes**.","prio":"P3","sec":"s2"},{"id":"fc-p338-d0735c","poly":"pneumo","fiche":"p338","front":"IgE : récepteur de faible affinité et cellules porteuses ?","back":"**FcεRII** sur éosinophiles, monocytes, plaquettes.","prio":"P3","sec":"s2"},{"id":"fc-p338-289daa","poly":"pneumo","fiche":"p338","front":"Anaphylaxie allergique : quantité d'allergène nécessaire à la réintroduction ?","back":"Même **minime** → dégranulation brutale.","prio":"P2","sec":"s2"},{"id":"fc-p338-00d0d4","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : médiateurs préformés ?","back":"**Histamine**, **tryptase**, certaines cytokines.","prio":"P2","sec":"s2"},{"id":"fc-p338-a25543","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : médiateurs néoformés ?","back":"Dérivés de l'acide arachidonique (**leucotriènes**, **prostaglandines**), cytokines.","prio":"P3","sec":"s2"},{"id":"fc-p338-c6ea26","poly":"pneumo","fiche":"p338","front":"Anaphylaxie non allergique : mécanisme de l'histamino-libération directe ?","back":"Libération d'histamine **sans sensibilisation préalable** (aliments, médicaments, facteurs physiques).","prio":"P3","sec":"s2"},{"id":"fc-p338-b5204a","poly":"pneumo","fiche":"p338","front":"Agents pouvant donner une anaphylaxie allergique ou non allergique ?","back":"**Produits de contraste iodés** ; **curares**, **opioïdes**, **vancomycine**, **quinolones**.","prio":"P3","sec":"s2"},{"id":"fc-p338-9832ba","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : médiateur responsable des signes immédiats ?","back":"L'**histamine**.","prio":"P2","sec":"s2"},{"id":"fc-p338-81854b","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : dégranulation des basophiles ou des mastocytes, quel type de réaction ?","back":"Basophiles → réaction **systémique** ; mastocytes tissulaires → réactions **d'organe**.","prio":"P3","sec":"s2"},{"id":"fc-p338-1481af","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : trois premières catégories de causes ?","back":"**Aliments**, **médicaments**, **venins d'hyménoptères**.","prio":"P2","sec":"s2"},{"id":"fc-p338-b818d2","poly":"pneumo","fiche":"p338","front":"Anaphylaxie alimentaire de l'enfant : aliments en cause ?","back":"**Arachide**, **fruits à coque**, **œuf**, **laits** de mammifères.","prio":"P2","sec":"s2"},{"id":"fc-p338-8c5305","poly":"pneumo","fiche":"p338","front":"Anaphylaxie alimentaire de l'adulte : aliments en cause ?","back":"**Blé**, **céleri**, **crustacés**.","prio":"P3","sec":"s2"},{"id":"fc-p338-fc165e","poly":"pneumo","fiche":"p338","front":"Anaphylaxie médicamenteuse : principaux médicaments en cause ?","back":"**Antibiotiques** +++, **AINS**, **curares**, **produits de contraste iodés**.","prio":"P2","sec":"s2"},{"id":"fc-p338-cba57c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie aux venins : insectes en cause ?","back":"**Guêpe** et **abeille** (surtout chez l'adulte).","prio":"P3","sec":"s2"},{"id":"fc-p338-1459a4","poly":"pneumo","fiche":"p338","front":"Latex : contexte d'anaphylaxie notable ?","back":"Anaphylaxie **péri-opératoire**.","prio":"P3","sec":"s2"},{"id":"fc-p338-20051c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie idiopathique : fréquence ?","back":"**20 à 30 %** des cas.","prio":"P3","sec":"s2"},{"id":"fc-p338-035adc","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : délai maximal après le contact allergénique ?","back":"**Au plus tard dans l'heure**.","prio":"P1","sec":"s3"},{"id":"fc-p338-4baf88","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : délais selon la voie d'exposition ?","back":"Muqueuses **≈ 30 min** ; piqûre **≈ 15 min** ; voie IV **≈ 5 min**.","prio":"P2","sec":"s3"},{"id":"fc-p338-e6af86","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : sur quoi repose le diagnostic en urgence ?","back":"**Clinique** et **contexte** (aucun examen biologique ne répond en urgence).","prio":"P1","sec":"s3"},{"id":"fc-p338-33b848","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : dans quel contexte le diagnostic est-il plus difficile ?","back":"Au **bloc opératoire** (peropératoire).","prio":"P3","sec":"s3"},{"id":"fc-p338-1f7406","poly":"pneumo","fiche":"p338","front":"Anaphylaxie, situation 1 : association de signes évocatrice ?","back":"Atteinte cutanéo-muqueuse **urticarienne** rapide **+** atteinte **respiratoire** et/ou **hypotension**/mauvaise perfusion.","prio":"P1","sec":"s3"},{"id":"fc-p338-e394e7","poly":"pneumo","fiche":"p338","front":"Anaphylaxie, situation 2 : critère après exposition à un allergène probable ?","back":"**Au moins deux** atteintes : cutanéo-muqueuse, respiratoire, hypotension/hypoperfusion, **gastro-intestinale**.","prio":"P1","sec":"s3"},{"id":"fc-p338-8c5cf5","poly":"pneumo","fiche":"p338","front":"Anaphylaxie, situation 3 : quand une hypotension isolée suffit-elle ?","back":"Après exposition à un allergène **connu** du patient.","prio":"P1","sec":"s3"},{"id":"fc-p338-b2edeb","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : seuil d'hypotension chez l'adulte ?","back":"PAS **< 90 mmHg** ou baisse **> 30 %** de la valeur habituelle.","prio":"P1","sec":"s3"},{"id":"fc-p338-bc0b68","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : seuil d'hypotension de 1 à 10 ans ?","back":"PAS **< 70 + (2 × âge)** mmHg.","prio":"P2","sec":"s3"},{"id":"fc-p338-284dab","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : seuil d'hypotension de 1 mois à 1 an et de 11 à 17 ans ?","back":"1 mois-1 an : PAS **< 70** ; 11-17 ans : PAS **< 90** mmHg.","prio":"P3","sec":"s3"},{"id":"fc-p338-e65b25","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : fréquence de l'atteinte cutanéo-muqueuse ?","back":"**80 à 90 %**.","prio":"P2","sec":"s3"},{"id":"fc-p338-9553e2","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : fréquence de l'atteinte respiratoire et signes ?","back":"**60-72 %** : toux, **sibilants**, **stridor**, dyspnée haute (œdème laryngé) ou basse (bronchospasme).","prio":"P2","sec":"s3"},{"id":"fc-p338-d235f8","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : manifestations cardiovasculaires ?","back":"**Hypotension**, douleur thoracique, **SCA**, troubles du rythme, **arrêt cardiaque** (≈ 30 %).","prio":"P2","sec":"s3"},{"id":"fc-p338-8adf6d","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : signification des signes digestifs persistants ?","back":"Ce sont des **signes de gravité** (douleurs abdominales, vomissements, diarrhée, dysphagie).","prio":"P1","sec":"s3"},{"id":"fc-p338-2e2508","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : autres signes possibles hors organes classiques ?","back":"**Goût métallique**, contractions utérines, **sensation de mort imminente**.","prio":"P3","sec":"s3"},{"id":"fc-p338-09a3d4","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : quelle forme respiratoire peut en être la seule manifestation ?","back":"Un **asthme aigu grave**.","prio":"P1","sec":"s3"},{"id":"fc-p338-c09bfd","poly":"pneumo","fiche":"p338","front":"Anaphylaxie chez l'asthmatique : particularités ?","back":"Choc **plus sévère** ; mortalité accrue si asthme **mal ou non contrôlé**.","prio":"P1","sec":"s3"},{"id":"fc-p338-5c532b","poly":"pneumo","fiche":"p338","front":"Asthmatique avec allergie alimentaire : aliments au premier plan ?","back":"**Arachide**, **fruits à coque**, **sésame**, **lait de chèvre**.","prio":"P3","sec":"s3"},{"id":"fc-p338-b9c301","poly":"pneumo","fiche":"p338","front":"Anaphylaxie fulminante : les signes cutanés sont-ils toujours présents ?","back":"**Non** : discrets voire **absents**.","prio":"P1","sec":"s3"},{"id":"fc-p338-71806b","poly":"pneumo","fiche":"p338","front":"Signes cutanés isolés sans menace vitale : est-ce une anaphylaxie ?","back":"**Non**.","prio":"P2","sec":"s3"},{"id":"fc-p338-338690","poly":"pneumo","fiche":"p338","front":"Prurit de l'anaphylaxie : localisation typique et chronologie ?","back":"**Paumes**, **plantes** (et oropharynx) ; il **précède** le rash, l'urticaire, l'angioœdème.","prio":"P2","sec":"s4"},{"id":"fc-p338-97ee44","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : aspect du rash cutané ?","back":"**Morbilliforme**.","prio":"P3","sec":"s4"},{"id":"fc-p338-3d9b86","poly":"pneumo","fiche":"p338","front":"Urticaire : caractères des lésions ?","back":"Papules/plaques **érythémateuses** saillantes, **le plus souvent prurigineuses** et **migratrices**, disparaissant vite et complètement.","prio":"P2","sec":"s4"},{"id":"fc-p338-b6bcd6","poly":"pneumo","fiche":"p338","front":"Angioœdème histaminique : caractères du gonflement ?","back":"**Ferme**, mal limité, **non érythémateux**, **peu ou pas prurigineux**.","prio":"P1","sec":"s4"},{"id":"fc-p338-eda520","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke : signes de gêne respiratoire haute ?","back":"**Dysphonie**, voix rauque, **dysphagie**, dyspnée, **tirage**, **cornage** (stridor).","prio":"P1","sec":"s4"},{"id":"fc-p338-446936","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke : signes d'examen ?","back":"Gonflement de la **langue**, de la **luette**, des paupières, des **lèvres** et/ou du visage.","prio":"P2","sec":"s4"},{"id":"fc-p338-f87c8c","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique : éléments évocateurs ?","back":"**Antécédents familiaux** ; **en règle ni prurit ni urticaire** ; **résistance au traitement**.","prio":"P2","sec":"s4"},{"id":"fc-p338-2a9d22","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique : caractères de l'œdème ?","back":"**Mou**, non prurigineux, évoluant sur **2 à 3 jours**.","prio":"P2","sec":"s4"},{"id":"fc-p338-606aa5","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique laryngé : réponse à l'adrénaline ?","back":"**Résistant** à l'adrénaline.","prio":"P2","sec":"s4"},{"id":"fc-p338-669bc7","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique : médicaments en cause ?","back":"**IEC**, **sartans**, **œstrogènes**.","prio":"P2","sec":"s4"},{"id":"fc-p338-e368b9","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique : examen diagnostique ?","back":"Dosage **pondéral et/ou fonctionnel du C1 inhibiteur**.","prio":"P2","sec":"s4"},{"id":"fc-p338-f52bc0","poly":"pneumo","fiche":"p338","front":"Angioœdème bradykinique héréditaire : mode de transmission ?","back":"**Autosomique dominant** (déficit en inhibiteur de la C1 estérase).","prio":"P3","sec":"s4"},{"id":"fc-p338-c87753","poly":"pneumo","fiche":"p338","front":"Grades de sévérité : à partir de quel grade parle-t-on d'anaphylaxie ?","back":"À partir du **grade II**.","prio":"P1","sec":"s5"},{"id":"fc-p338-e67eda","poly":"pneumo","fiche":"p338","front":"Grade I de sévérité : signes ?","back":"Signes **cutanés généraux** : érythème, urticaire, angioœdème.","prio":"P2","sec":"s5"},{"id":"fc-p338-9f20f8","poly":"pneumo","fiche":"p338","front":"Grade II de sévérité : définition ?","back":"**Au moins deux organes** atteints (peau, voies aériennes, digestif) : anaphylaxie légère.","prio":"P2","sec":"s5"},{"id":"fc-p338-51b05e","poly":"pneumo","fiche":"p338","front":"Grade III de sévérité : définition ?","back":"**Hypotension artérielle** : anaphylaxie modérée.","prio":"P1","sec":"s5"},{"id":"fc-p338-7c001f","poly":"pneumo","fiche":"p338","front":"Grade IV de sévérité : définition ?","back":"**Arrêt cardiaque et/ou respiratoire**, décès.","prio":"P1","sec":"s5"},{"id":"fc-p338-0c9898","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : lien entre rapidité de survenue et sévérité ?","back":"Plus la réaction est **rapide**, plus le risque de **sévérité** est élevé.","prio":"P1","sec":"s5"},{"id":"fc-p338-a66040","poly":"pneumo","fiche":"p338","front":"Réaction biphasique : définition et fréquence ?","back":"Retour des symptômes **> 4 h** après la phase initiale ; **< 20 %** des cas.","prio":"P1","sec":"s5"},{"id":"fc-p338-a12d6b","poly":"pneumo","fiche":"p338","front":"Réaction biphasique : facteurs de risque ?","back":"Plusieurs organes, atteinte respiratoire sévère, **> 1 dose d'adrénaline**, allergène absorbé **en continu** (aliments), antécédent de réaction biphasique, cause inconnue.","prio":"P3","sec":"s5"},{"id":"fc-p338-be346c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : facteurs de risque de réaction sévère liés au terrain ?","back":"**Asthme non contrôlé**, **maladie cardiovasculaire**, **mastocytose**, réaction sévère antérieure.","prio":"P1","sec":"s5"},{"id":"fc-p338-5574c4","poly":"pneumo","fiche":"p338","front":"Bêtabloquant : pourquoi aggrave-t-il l'anaphylaxie ?","back":"Il bloque le **rétrocontrôle adrénergique** endogène et l'**effet de l'adrénaline** injectée.","prio":"P1","sec":"s5"},{"id":"fc-p338-94eb04","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : cofacteurs potentialisateurs ?","back":"**Effort**, **alcool**, **AINS**, stress, infections, cycle menstruel.","prio":"P2","sec":"s5"},{"id":"fc-p338-89a3c9","poly":"pneumo","fiche":"p338","front":"Bêtabloquant + IEC : pourquoi un risque majoré d'anaphylaxie ?","back":"Abaissement du **seuil d'activation des mastocytes**.","prio":"P3","sec":"s5"},{"id":"fc-p338-ebd21c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : signes imposant l'adrénaline IM ?","back":"Signes **cardiovasculaires**, **respiratoires** ou **digestifs persistants**.","prio":"P1","sec":"s5"},{"id":"fc-p338-408630","poly":"pneumo","fiche":"p338","front":"Tryptase sérique : spécificité cellulaire ?","back":"Quasi spécifique du **mastocyte**.","prio":"P2","sec":"s6"},{"id":"fc-p338-7c9fa2","poly":"pneumo","fiche":"p338","front":"Tryptase : cinétique après un choc anaphylactique ?","back":"Détectable dès **15 min** ; retour au taux de base en **12 à 24 h**.","prio":"P2","sec":"s6"},{"id":"fc-p338-7e5e26","poly":"pneumo","fiche":"p338","front":"Tryptase : temps de prélèvement ?","back":"**Dès que possible**, puis à **1-2 h**, puis à **24 h** ou à distance.","prio":"P2","sec":"s6"},{"id":"fc-p338-31d8ab","poly":"pneumo","fiche":"p338","front":"Tryptase : critère d'élévation significative ?","back":"Pic **≥ 1,2 × taux de base + 2 µg/L** ; toute hausse confirme, même dans les valeurs « normales ».","prio":"P3","sec":"s6"},{"id":"fc-p338-dee254","poly":"pneumo","fiche":"p338","front":"Tryptase : utilités en dehors du diagnostic ?","back":"Argument **médico-légal** (chocs peropératoires), marqueur de **sévérité**, dépistage d'une **mastocytose** latente.","prio":"P3","sec":"s6"},{"id":"fc-p338-d26d82","poly":"pneumo","fiche":"p338","front":"Bilan allergologique après anaphylaxie : délai ?","back":"**Plus d'un mois** après l'accident.","prio":"P1","sec":"s6"},{"id":"fc-p338-f29b32","poly":"pneumo","fiche":"p338","front":"Bilan allergologique trop précoce : quel risque ?","back":"**Faux négatifs** des tests cutanés (mastocytes et basophiles non régénérés).","prio":"P1","sec":"s6"},{"id":"fc-p338-8746b3","poly":"pneumo","fiche":"p338","front":"Bilan allergologique : élément essentiel ?","back":"L'**interrogatoire** (piqûre, repas, anesthésie…).","prio":"P2","sec":"s6"},{"id":"fc-p338-72d774","poly":"pneumo","fiche":"p338","front":"Bilan allergologique : tests cutanés utilisés ?","back":"**Prick-tests** et **IDR**.","prio":"P2","sec":"s6"},{"id":"fc-p338-35bdeb","poly":"pneumo","fiche":"p338","front":"Bilan allergologique : allergènes pour lesquels les IgE spécifiques sont utiles ?","back":"**Curares**, **latex**, **fruits à coque**…","prio":"P3","sec":"s6"},{"id":"fc-p338-d4da49","poly":"pneumo","fiche":"p338","front":"Tests de provocation : conditions de réalisation ?","back":"Milieu **hospitalier spécialisé**, surveillance stricte, **perfusion de sécurité**.","prio":"P2","sec":"s6"},{"id":"fc-p338-5b2a63","poly":"pneumo","fiche":"p338","front":"Choc vagal : tableau ?","back":"**Pâleur**, sueurs, nausées, **bradycardie**, hypotension, sans signes **cutanés** ni **respiratoires**.","prio":"P1","sec":"s7"},{"id":"fc-p338-2821a3","poly":"pneumo","fiche":"p338","front":"Choc cardiogénique vs anaphylactique : éléments d'orientation ?","back":"Contexte d'**IDM** ou d'**EP**, signes d'**insuffisance cardiaque**, réponse paradoxale au remplissage.","prio":"P2","sec":"s7"},{"id":"fc-p338-16ec19","poly":"pneumo","fiche":"p338","front":"Mastocytose : signe cutané évocateur ?","back":"**Signe de Darier**.","prio":"P2","sec":"s7"},{"id":"fc-p338-6b1a0f","poly":"pneumo","fiche":"p338","front":"Œdème du visage majoré en décubitus, surtout au réveil : diagnostic ?","back":"**Syndrome cave supérieur**.","prio":"P2","sec":"s7"},{"id":"fc-p338-a58ed1","poly":"pneumo","fiche":"p338","front":"Œdème du visage avec contexte infectieux : diagnostic différentiel ?","back":"**Érysipèle** du visage.","prio":"P2","sec":"s7"},{"id":"fc-p338-783198","poly":"pneumo","fiche":"p338","front":"Œdème du visage avec vésicules : diagnostic différentiel ?","back":"**Eczéma aigu** du visage.","prio":"P2","sec":"s7"},{"id":"fc-p338-d6d593","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke isolé chez l'enfant : diagnostic à toujours évoquer ?","back":"**Corps étranger**.","prio":"P1","sec":"s7"},{"id":"fc-p338-40715a","poly":"pneumo","fiche":"p338","front":"Allergie alimentaire suspectée : diagnostics différentiels ?","back":"**Toxi-infection**, aliments riches en **histamine**/tyramine, intolérance lactose/gluten, excès de glutamate, mastocytose.","prio":"P3","sec":"s7"},{"id":"fc-p338-1cca41","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : diagnostics différentiels endocriniens ?","back":"**Hypoglycémie**, thyrotoxicose, **syndrome carcinoïde**, **phéochromocytome**.","prio":"P3","sec":"s7"},{"id":"fc-p338-246b69","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : diagnostics différentiels neuropsychiques ?","back":"**Hyperventilation**, **attaque de panique**, épilepsie, conversion, AVC.","prio":"P3","sec":"s7"},{"id":"fc-p338-b8528b","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : premières mesures avant les médicaments ?","back":"Rester près du patient, **appeler à l'aide**, **supprimer l'exposition** (arrêt perfusion, retrait du dard).","prio":"P1","sec":"s8"},{"id":"fc-p338-2e7c4e","poly":"pneumo","fiche":"p338","front":"Piqûre d'hyménoptère : priorité pour le dard ?","back":"Le retirer **sans attendre** (la précocité compte plus que la technique).","prio":"P2","sec":"s8"},{"id":"fc-p338-b5a458","poly":"pneumo","fiche":"p338","front":"Anaphylaxie alimentaire : faut-il vider l'estomac ?","back":"**Non** (risque d'**inhalation**).","prio":"P2","sec":"s8"},{"id":"fc-p338-176d70","poly":"pneumo","fiche":"p338","front":"Anaphylaxie sans dyspnée : position ?","back":"**Allongé jambes surélevées**.","prio":"P1","sec":"s8"},{"id":"fc-p338-000d83","poly":"pneumo","fiche":"p338","front":"Anaphylaxie avec dyspnée : position ?","back":"**Semi-assis jambes surélevées**.","prio":"P1","sec":"s8"},{"id":"fc-p338-1d0e41","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : position du patient inconscient et de la femme enceinte ?","back":"Inconscient : **PLS** ; femme enceinte : **décubitus latéral gauche**.","prio":"P2","sec":"s8"},{"id":"fc-p338-0ce0fa","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : pourquoi ne jamais verticaliser le patient ?","back":"Vasoplégie + **adiastolie** : **désamorçage** de la pompe cardiaque → **arrêt cardiaque**.","prio":"P1","sec":"s8"},{"id":"fc-p338-cb5ed7","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : traitement de première intention ?","back":"**Adrénaline intramusculaire**, le plus vite possible (la survie en dépend).","prio":"P1","sec":"s8"},{"id":"fc-p338-5b4d7e","poly":"pneumo","fiche":"p338","front":"Adrénaline dans l'anaphylaxie : effets α ?","back":"Corrige la **vasodilatation** et diminue l'**œdème**.","prio":"P2","sec":"s8"},{"id":"fc-p338-69a7f5","poly":"pneumo","fiche":"p338","front":"Adrénaline dans l'anaphylaxie : effets β ?","back":"**Bronchodilatation**, inotropisme positif, frein à la libération d'**histamine** et de leucotriènes.","prio":"P2","sec":"s8"},{"id":"fc-p338-fe7383","poly":"pneumo","fiche":"p338","front":"Adrénaline IM : sites d'injection ?","back":"Face **antérolatérale externe de la cuisse** ou région **deltoïdienne**.","prio":"P1","sec":"s8"},{"id":"fc-p338-368c1b","poly":"pneumo","fiche":"p338","front":"Adrénaline IM : délai de renouvellement ?","back":"Toutes les **5 à 10 min** jusqu'à stabilisation.","prio":"P1","sec":"s8"},{"id":"fc-p338-147ec1","poly":"pneumo","fiche":"p338","front":"Adrénaline IM chez l'adulte : dose ?","back":"**0,3 ou 0,5 mg** IM.","prio":"P1","sec":"s8"},{"id":"fc-p338-36bf29","poly":"pneumo","fiche":"p338","front":"Adrénaline IM chez l'enfant : doses selon le poids ?","back":"**> 30 kg** (ou > 12 ans) : **0,3 mg** ; **15-30 kg** : **0,15 mg** ; **< 15 kg** : **0,01 mg/kg**.","prio":"P1","sec":"s8"},{"id":"fc-p338-434059","poly":"pneumo","fiche":"p338","front":"Adrénaline dans l'anaphylaxie : pourquoi proscrire la voie sous-cutanée ?","back":"**Trop lente**, moins efficace, risque de **nécrose cutanée**.","prio":"P1","sec":"s8"},{"id":"fc-p338-7e78c2","poly":"pneumo","fiche":"p338","front":"Adrénaline IV : dans quelles situations est-elle exclue ?","back":"Hors **arrêt cardio-respiratoire** ou hors **milieu spécialisé** (HTA, troubles du rythme, ischémie).","prio":"P1","sec":"s8"},{"id":"fc-p338-be4b1d","poly":"pneumo","fiche":"p338","front":"Adrénaline chez la femme enceinte en anaphylaxie ?","back":"**Mêmes recommandations** que hors grossesse.","prio":"P2","sec":"s8"},{"id":"fc-p338-fd5aed","poly":"pneumo","fiche":"p338","front":"Stylo auto-injecteur d'adrénaline : dose de 15 à 30 kg ?","back":"**150 µg** (pas d'AMM sous 15 kg).","prio":"P2","sec":"s8"},{"id":"fc-p338-154b94","poly":"pneumo","fiche":"p338","front":"Stylo auto-injecteur d'adrénaline : dose chez l'adulte selon le poids ?","back":"**300 µg** si < 60 kg ; **300 à 500 µg** si > 60 kg.","prio":"P2","sec":"s8"},{"id":"fc-p338-e088ac","poly":"pneumo","fiche":"p338","front":"Choc anaphylactique : remplissage vasculaire chez l'adulte et l'enfant ?","back":"Adulte **500 à 1000 mL** ; enfant **20 mL/kg** ; sérum salé isotonique d'abord.","prio":"P1","sec":"s8"},{"id":"fc-p338-5ccabb","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : modalités de l'oxygénothérapie (fiche pneumo) ?","back":"Haut débit **≥ 10 L/min**, **masque à haute concentration** (réservoir).","prio":"P2","sec":"s8"},{"id":"fc-p338-3db86e","poly":"pneumo","fiche":"p338","front":"Antihistaminiques et corticoïdes dans l'anaphylaxie : place ?","back":"**Jamais** des traitements de l'urgence ; au **décours** (urticaire, prurit, phase tardive).","prio":"P1","sec":"s8"},{"id":"fc-p338-7d04ed","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : mode de transport ?","back":"Transport **médicalisé** par le **SAMU**.","prio":"P2","sec":"s8"},{"id":"fc-p338-b2a24d","poly":"pneumo","fiche":"p338","front":"Anaphylaxie sous adrénaline : paramètres à monitorer ?","back":"**Pouls**, **PA**, **SpO₂**, **ECG** (risque de troubles du rythme et d'ischémie).","prio":"P1","sec":"s13"},{"id":"fc-p338-1790e2","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : durée minimale de surveillance hospitalière ?","back":"**6 heures**, même si tout a régressé (réaction biphasique).","prio":"P1","sec":"s13"},{"id":"fc-p338-e8dc69","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : dose d'adrénaline IM et O₂ selon la dermatologie (item 187) ?","back":"**0,01 mg/kg** IM sans dépasser **0,5 mg**, à refaire après 5-15 min ; O₂ **6-8 L/min**.","prio":"P3","sec":"s8"},{"id":"fc-p338-9a8968","poly":"pneumo","fiche":"p338","front":"Hypotension persistante malgré adrénaline IM et remplissage : étape suivante ?","back":"Adrénaline **IV** titrée, par un **spécialiste**, sous monitoring strict.","prio":"P2","sec":"s9"},{"id":"fc-p338-98696c","poly":"pneumo","fiche":"p338","front":"Adrénaline IV chez l'adulte en anaphylaxie : bolus et objectif ?","back":"Bolus de **50 µg** toutes les 1-2 min jusqu'à **PAS > 90 mmHg**, puis seringue électrique.","prio":"P3","sec":"s9"},{"id":"fc-p338-b760a7","poly":"pneumo","fiche":"p338","front":"Anaphylaxie résistante à l'adrénaline sous bêtabloquant : quel traitement ?","back":"**Glucagon** (action indépendante des récepteurs β).","prio":"P1","sec":"s9"},{"id":"fc-p338-8e7f1e","poly":"pneumo","fiche":"p338","front":"Patient sous bêtabloquant ayant fait une anaphylaxie : conduite au long cours ?","back":"**Remplacer** le bêtabloquant par une autre classe, avec le **cardiologue**.","prio":"P1","sec":"s9"},{"id":"fc-p338-33b29a","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke : médicament à injecter en premier et voie ?","back":"**Adrénaline IM**, le plus tôt possible (atteinte respiratoire = indication).","prio":"P1","sec":"s10"},{"id":"fc-p338-b75c75","poly":"pneumo","fiche":"p338","front":"Stridor persistant malgré adrénaline IM : traitement ?","back":"**Adrénaline nébulisée** (1 mg dans 4 mL de NaCl 0,9 %).","prio":"P2","sec":"s10"},{"id":"fc-p338-4a1a4c","poly":"pneumo","fiche":"p338","front":"Œdème de Quincke : gestes de libération des voies aériennes si nécessaire ?","back":"**Intubation orotrachéale** ou **trachéotomie**.","prio":"P1","sec":"s10"},{"id":"fc-p338-b21130","poly":"pneumo","fiche":"p338","front":"Œdème laryngé anaphylactique : les antihistaminiques suffisent-ils ?","back":"**Non** : ce ne sont pas des médicaments de l'urgence.","prio":"P1","sec":"s10"},{"id":"fc-p338-e58c5c","poly":"pneumo","fiche":"p338","front":"Bronchospasme anaphylactique : traitement après l'adrénaline IM ?","back":"**β₂-agoniste de courte durée** en **nébulisation**.","prio":"P2","sec":"s11"},{"id":"fc-p338-77aa1a","poly":"pneumo","fiche":"p338","front":"Bronchospasme anaphylactique : faut-il un β₂-mimétique seul ?","back":"**Non** : l'atteinte respiratoire impose l'**adrénaline IM**.","prio":"P2","sec":"s11"},{"id":"fc-p338-b53b9f","poly":"pneumo","fiche":"p338","front":"Bronchospasme anaphylactique : corticoïdes au décours ?","back":"**Systématiques**, aux mêmes doses que dans l'asthme.","prio":"P2","sec":"s11"},{"id":"fc-p338-0051af","poly":"pneumo","fiche":"p338","front":"Allergie alimentaire + asthme persistant modéré à sévère ou non contrôlé : adrénaline auto-injectable ?","back":"**Indication absolue**.","prio":"P2","sec":"s11"},{"id":"fc-p338-c335ff","poly":"pneumo","fiche":"p338","front":"Après anaphylaxie : durée de l'éviction de l'allergène ?","back":"**À vie**, jusqu'à preuve du contraire.","prio":"P1","sec":"s12"},{"id":"fc-p338-063dd7","poly":"pneumo","fiche":"p338","front":"Enfant ayant fait une anaphylaxie : document de prise en charge scolaire ?","back":"**Plan d'Action Individualisé (PAI)**.","prio":"P1","sec":"s12"},{"id":"fc-p338-ae84f6","poly":"pneumo","fiche":"p338","front":"Après choc anaphylactique ou Quincke à risque de récidive : que remettre au patient ?","back":"**Trousse d'urgence** avec **adrénaline auto-injectable** + apprentissage de l'**auto-injection IM**.","prio":"P1","sec":"s12"},{"id":"fc-p338-6dc776","poly":"pneumo","fiche":"p338","front":"Adrénaline auto-injectable : citer des indications absolues ?","back":"Anaphylaxie antérieure (aliment, piqûre, latex, pneumallergène), **d'effort**, **idiopathique**, **mastocytose systémique**…","prio":"P2","sec":"s12"},{"id":"fc-p338-43dc2d","poly":"pneumo","fiche":"p338","front":"Allergie aux venins : quand l'auto-injecteur est-il indiqué en absolu ?","back":"Réaction **systémique** (plus que cutanéo-muqueuse) sans désensibilisation ou avec risque élevé de réexposition.","prio":"P3","sec":"s12"},{"id":"fc-p338-be1293","poly":"pneumo","fiche":"p338","front":"Enfant avec allergie alimentaire : pourquoi des indications d'adrénaline plus larges ?","back":"Bénéfice/risque **favorable** et gravité d'une récidive **difficile à prévoir**.","prio":"P2","sec":"s12"},{"id":"fc-p338-22de99","poly":"pneumo","fiche":"p338","front":"Après anaphylaxie : document à porter en permanence ?","back":"**Carte d'allergique** (sensibilisations, sévérité) + liste des produits à éviter.","prio":"P1","sec":"s12"},{"id":"fc-p338-540863","poly":"pneumo","fiche":"p338","front":"Allergie médicamenteuse : démarche administrative ?","back":"Déclaration au **centre de pharmacovigilance**.","prio":"P2","sec":"s12"},{"id":"fc-p338-e6edd9","poly":"pneumo","fiche":"p338","front":"Immunothérapie allergénique : deux indications formelles ?","back":"Allergie grave aux **venins d'hyménoptères** ; allergie grave à un **médicament indispensable** sans alternative.","prio":"P1","sec":"s12"},{"id":"fc-p338-a98794","poly":"pneumo","fiche":"p338","front":"Stylo d'adrénaline : condition de conservation ?","back":"Température ambiante, **sans dépasser + 25 °C**.","prio":"P3","sec":"s12"},{"id":"fc-p338-06db50","poly":"pneumo","fiche":"p338","front":"Stylo d'adrénaline 500 µg : quand l'envisager ?","back":"**Surpoids**, anaphylaxie **sévère** antérieure, **échec** du 300 µg.","prio":"P3","sec":"s12"},{"id":"fc-p338-1e41c8","poly":"pneumo","fiche":"p338","front":"Mastocytose systémique de l'enfant : critères d'indication de l'auto-injecteur ?","back":"Atteinte cutanée **> 50 %**, tryptase basale **> 20 ng/mL**, **bulles** dans les 3 premières années.","prio":"P3","sec":"s12"},{"id":"fc-p338-8a89d8","poly":"pneumo","fiche":"p338","front":"Indications relatives de l'auto-injecteur : citer des exemples ?","back":"Réaction à faible quantité d'aliment, aliment à risque (arachide, fruits à coque), **domicile éloigné** des soins, **immunothérapie orale**.","prio":"P3","sec":"s12"},{"id":"fc-p338-fd7712","poly":"pneumo","fiche":"p338","front":"Trousse d'urgence de l'allergie alimentaire (item 186) : contenu ?","back":"**Antihistaminiques H1**, ± **bronchodilatateur**, **adrénaline auto-injectable** si risque d'anaphylaxie.","prio":"P3","sec":"s12"},{"id":"fc-p338-48da0f","poly":"pneumo","fiche":"p338","front":"Adrénaline dans l'anaphylaxie : deux avantages de la voie IM ?","back":"**Meilleur rapport bénéfice/risque** ; **pas besoin de voie veineuse**.","prio":"P2","sec":"s8"},{"id":"fc-p338-6cb74c","poly":"pneumo","fiche":"p338","front":"Anaphylaxie : de quoi dépend sa sévérité ?","back":"Du **nombre de systèmes** atteints et de la **sévérité** de chaque atteinte.","prio":"P2","sec":"s5"},{"id":"fc-p338-ec622f","poly":"pneumo","fiche":"p338","front":"Asthme aigu grave anaphylactique : populations les plus exposées ?","back":"**Enfants**, **adolescents** et **adultes jeunes**.","prio":"P3","sec":"s3"},{"id":"fc-p359-eaebb0","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire aiguë : quelle définition ?","back":"Signes traduisant la **gravité** d'une affection respiratoire : déséquilibre entre la **charge** imposée et la **capacité** à y faire face.","prio":"P1","sec":"s1"},{"id":"fc-p359-c6d974","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire aiguë : quels deux types de signes associe-t-elle ?","back":"**Conséquences directes** de l'atteinte (ex. cyanose) et **moyens de compensation** (muscles respiratoires).","prio":"P2","sec":"s1"},{"id":"fc-p359-cf021d","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : que signifient des signes hémodynamiques ou neurologiques associés ?","back":"Un élément de **gravité supplémentaire**.","prio":"P2","sec":"s1"},{"id":"fc-p359-98272c","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire au cours d'une dyspnée aiguë : quelle signification ?","back":"**Signe majeur de gravité** : peut annoncer un **arrêt cardio-circulatoire hypoxique**.","prio":"P1","sec":"s1"},{"id":"fc-p359-62f29d","poly":"pneumo","fiche":"p359","front":"Insuffisance respiratoire aiguë : quelle définition gazométrique ?","back":"**PaO₂ < 60 mmHg** + **modification du pH** (ex. acidose respiratoire avec **PaCO₂ > 45 mmHg**).","prio":"P1","sec":"s1"},{"id":"fc-p359-4f087e","poly":"pneumo","fiche":"p359","front":"IRA : que traduit l'hypercapnie avec acidose ?","back":"Une **hypoventilation alvéolaire** (le pH signe le caractère aigu).","prio":"P2","sec":"s1"},{"id":"fc-p359-76b76d","poly":"pneumo","fiche":"p359","front":"Définition gazométrique de l'IRA : quelles hypoxies exclut-elle ?","back":"Les **hypoxies tissulaires sans hypoxémie** : anémie, **CO**, choc ; cyanure, sepsis grave.","prio":"P1","sec":"s1"},{"id":"fc-p359-7aca9a","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire avec hypocapnie marquée et PaO₂ normale : quelle interprétation ?","back":"Souvent une **hypoxémie profonde masquée** par l'hyperventilation : refaire tôt les gaz du sang, doser le **lactate**.","prio":"P2","sec":"s1"},{"id":"fc-p359-49485b","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire vs SDRA : quelle différence ?","back":"Détresse : **ensemble de signes** de gravité ; SDRA : **une des causes** de détresse (œdème lésionnel).","prio":"P1","sec":"s1"},{"id":"fc-p359-7a208b","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : en quels deux groupes classe-t-on les signes ?","back":"**Signes de lutte** et **signes de faillite**.","prio":"P1","sec":"s2"},{"id":"fc-p359-e5febf","poly":"pneumo","fiche":"p359","front":"Signes de faillite respiratoire : quelle valeur ?","back":"**Tout signe de faillite** signe la **gravité** de la détresse.","prio":"P1","sec":"s2"},{"id":"fc-p359-b53457","poly":"pneumo","fiche":"p359","front":"Signes de lutte : que traduisent-ils ?","back":"L'**augmentation du travail ventilatoire**.","prio":"P2","sec":"s2"},{"id":"fc-p359-884890","poly":"pneumo","fiche":"p359","front":"Tachypnée chez l'adulte : quel seuil ?","back":"**FR > 25/min**.","prio":"P1","sec":"s2"},{"id":"fc-p359-83e829","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quels signes témoignent d'un volume courant réduit ?","back":"**Difficulté à parler** (hypophonie) et **toux inefficace**.","prio":"P2","sec":"s2"},{"id":"fc-p359-9ae240","poly":"pneumo","fiche":"p359","front":"Signes de lutte : citer les signes de tirage.","back":"Tirage **sus-claviculaire**, **sus-sternal**, **intercostal** ; pouls inspiratoire.","prio":"P1","sec":"s2"},{"id":"fc-p359-4db519","poly":"pneumo","fiche":"p359","front":"Expiration abdominale active : de quoi s'agit-il ?","back":"**Signe de lutte** : recrutement des **abdominaux à l'expiration**.","prio":"P1","sec":"s2"},{"id":"fc-p359-6add27","poly":"pneumo","fiche":"p359","front":"Expiration abdominale active : vers quoi oriente-t-elle souvent ?","back":"Une **pathologie obstructive** (mais pas seulement).","prio":"P3","sec":"s2"},{"id":"fc-p359-4e55ff","poly":"pneumo","fiche":"p359","front":"Stridor : que traduit-il ?","back":"Une **obstruction des voies aériennes hautes** (larynx ou trachée cervicale).","prio":"P1","sec":"s2"},{"id":"fc-p359-05ffa6","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire avec bradypnée ou respiration irrégulière : quelle signification ?","back":"Défaillance plutôt **neurologique**, extrême gravité : **arrêt respiratoire imminent**.","prio":"P1","sec":"s2"},{"id":"fc-p359-bf3215","poly":"pneumo","fiche":"p359","front":"Scalènes et intercostaux : pourquoi ne pas les dire « accessoires » ?","back":"Normalement **actifs à l'inspiration** ; mais incapables de contraction soutenue prolongée.","prio":"P3","sec":"s2"},{"id":"fc-p359-6e7b39","poly":"pneumo","fiche":"p359","front":"Respiration abdominale paradoxale : quelle définition ?","back":"**Recul de la paroi abdominale à l'inspiration** : faillite de la **pompe ventilatoire** (diaphragme inactif).","prio":"P1","sec":"s3"},{"id":"fc-p359-256c11","poly":"pneumo","fiche":"p359","front":"Respiration abdominale paradoxale : quelle position est proscrite ?","back":"Le **décubitus dorsal** (orthopnée associée).","prio":"P1","sec":"s3"},{"id":"fc-p359-0c2189","poly":"pneumo","fiche":"p359","front":"Respiration abdominale paradoxale : quelle conduite ?","back":"Discuter une **assistance ventilatoire**, au minimum admission là où elle est possible **sans délai**.","prio":"P1","sec":"s3"},{"id":"fc-p359-a07cf3","poly":"pneumo","fiche":"p359","front":"Cyanose : à partir de quel taux d'hémoglobine réduite apparaît-elle ?","back":"**> 5 g/dl** de sang capillaire.","prio":"P1","sec":"s3"},{"id":"fc-p359-c4d325","poly":"pneumo","fiche":"p359","front":"Cyanose chez le sujet à peau noire : où la rechercher ?","back":"Sur la **langue**.","prio":"P2","sec":"s3"},{"id":"fc-p359-e315c2","poly":"pneumo","fiche":"p359","front":"Cyanose et anémie profonde : quelle particularité ?","back":"Cyanose **absente ou très tardive**.","prio":"P1","sec":"s3"},{"id":"fc-p359-70bbc2","poly":"pneumo","fiche":"p359","front":"Cyanose et polyglobulie : quelle particularité ?","back":"**Fréquente** et **moins spécifique**.","prio":"P2","sec":"s3"},{"id":"fc-p359-6743bf","poly":"pneumo","fiche":"p359","front":"Cyanose : quelle sensibilité, quelle spécificité et quelle conduite ?","back":"**Peu sensible mais spécifique** → **oxygène immédiat**.","prio":"P1","sec":"s3"},{"id":"fc-p359-295c60","poly":"pneumo","fiche":"p359","front":"Cyanose pour une Hb à 14 g/dl : à quelle SpO₂ correspond-elle ?","back":"SpO₂ **≈ 80 %** (PaO₂ ≈ 45-50 mmHg).","prio":"P3","sec":"s3"},{"id":"fc-p359-56d30a","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quel seuil de SpO₂ impose l'oxygène immédiat ?","back":"**SpO₂ < 90 %** (alerte plus tôt que la cyanose).","prio":"P1","sec":"s3"},{"id":"fc-p359-941d83","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quels signes neurologiques font suspecter une hypercapnie ?","back":"**Céphalées**, **astérixis**, ralentissement idéo-moteur, somnolence, troubles de conscience (**carbonarcose**).","prio":"P1","sec":"s3"},{"id":"fc-p359-713e2c","poly":"pneumo","fiche":"p359","front":"Astérixis : quelle valeur diagnostique ?","back":"Très évocateur d'**hypercapnie** installée assez vite ; **non spécifique** (encéphalopathie hépatique).","prio":"P2","sec":"s3"},{"id":"fc-p359-c4f8d7","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire avec agitation ou confusion : quelles causes possibles ?","back":"**Hypercapnie**, mais aussi **hypoxie cérébrale** ou **bas débit cérébral**.","prio":"P2","sec":"s3"},{"id":"fc-p359-a35677","poly":"pneumo","fiche":"p359","front":"Altération de la vigilance en détresse respiratoire : quelle valeur ?","back":"**Signe majeur de gravité**.","prio":"P1","sec":"s3"},{"id":"fc-p359-771272","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire avec Glasgow < 9 : quelle conduite ?","back":"**Intubation trachéale** pour protéger les voies aériennes d'une **inhalation**.","prio":"P2","sec":"s3"},{"id":"fc-p359-c9fd3d","poly":"pneumo","fiche":"p359","front":"Détresse avec insuffisance cardiaque droite aiguë : quelles causes évoquer ?","back":"**EP massive**, **pneumothorax compressif**, **asthme aigu grave**, **tamponnade**.","prio":"P1","sec":"s3"},{"id":"fc-p359-8a7691","poly":"pneumo","fiche":"p359","front":"Insuffisance cardiaque droite aiguë : quels signes ?","back":"**Turgescence jugulaire**, **reflux hépato-jugulaire**, **hépatomégalie douloureuse**.","prio":"P2","sec":"s3"},{"id":"fc-p359-e92098","poly":"pneumo","fiche":"p359","front":"Pouls paradoxal : quelle définition et quelles causes ?","back":"**Baisse de la PAS à l'inspiration** ; asthme aigu grave ou tamponnade.","prio":"P3","sec":"s3"},{"id":"fc-p359-90473a","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quels critères d'état de choc ?","back":"**PAS < 90 mmHg** ou chute **> 30 mmHg**, marbrures, TRC allongé, **FC > 120/min**, confusion, oligurie.","prio":"P1","sec":"s3"},{"id":"fc-p359-2d4495","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire avec HTA : que rechercher ?","back":"Une **hypercapnie**.","prio":"P1","sec":"s3"},{"id":"fc-p359-13fb82","poly":"pneumo","fiche":"p359","front":"Hypercapnie : quels signes liés à la vasodilatation du CO₂ ?","back":"**Céphalées**, **hyperhémie des conjonctives**.","prio":"P2","sec":"s3"},{"id":"fc-p359-f92b17","poly":"pneumo","fiche":"p359","front":"Hypercapnie : quels signes adrénergiques ?","back":"**Tremblements**, **sueurs**, **tachycardie**, **HTA**.","prio":"P2","sec":"s3"},{"id":"fc-p359-753038","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : sur quoi repose le diagnostic de la cause ?","back":"Clinique + **radiographie thoracique** + **gazométrie artérielle**.","prio":"P1","sec":"s4"},{"id":"fc-p359-affa4d","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quand mener bilan et traitement de la cause ?","back":"**En même temps**, une fois la sécurité assurée par le traitement symptomatique.","prio":"P2","sec":"s4"},{"id":"fc-p359-728159","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quels examens lancer tout de suite ?","back":"**Radio thorax au lit**, **gaz du sang + lactate**, **ECG**, NFS-plaquettes, ionogramme, urée, créatinine.","prio":"P1","sec":"s4"},{"id":"fc-p359-c88ba1","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : que rechercher à l'ECG ?","back":"**Trouble du rythme**, **repolarisation** (OAP ischémique, EP), **microvoltage/alternance électrique** (tamponnade).","prio":"P2","sec":"s4"},{"id":"fc-p359-783605","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quelle valeur d'un ECG normal ?","back":"Argument important **contre un OAP cardiogénique** (bonne VPN).","prio":"P1","sec":"s4"},{"id":"fc-p359-a3c44b","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quand doser le BNP ou NT-proBNP ?","back":"En cas de **doute avec un OAP cardiogénique**.","prio":"P2","sec":"s4"},{"id":"fc-p359-983912","poly":"pneumo","fiche":"p359","front":"BNP < 100 pg/mL : quelle conclusion ?","back":"**Exclut** une dyspnée aiguë d'origine **cardiaque**.","prio":"P1","sec":"s4"},{"id":"fc-p359-91659b","poly":"pneumo","fiche":"p359","front":"BNP élevé : est-il spécifique de l'OAP cardiogénique ?","back":"**Non** : aussi **EP aiguë**, **exacerbation de BPCO** (ventricule dilaté ou post-charge accrue).","prio":"P1","sec":"s4"},{"id":"fc-p359-1597ce","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quand demander un angioscanner thoracique ?","back":"EP de **forte probabilité** ou **D-dimères élevés**, ou atteinte parenchymateuse mal définie.","prio":"P2","sec":"s4"},{"id":"fc-p359-a129ca","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quand doser la troponine ?","back":"Si **ischémie myocardique** suspectée.","prio":"P3","sec":"s4"},{"id":"fc-p359-ddf9f6","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quand doser les D-dimères ?","back":"Si **EP suspectée** avec probabilité **faible ou intermédiaire**.","prio":"P2","sec":"s4"},{"id":"fc-p359-2cc909","poly":"pneumo","fiche":"p359","front":"Cause d'une détresse respiratoire : quelle est la 1re étape ?","back":"**Éliminer une obstruction des voies aériennes supérieures**.","prio":"P1","sec":"s5"},{"id":"fc-p359-746bdb","poly":"pneumo","fiche":"p359","front":"Détresse avec radio anormale : quels 3 diagnostics évoquer d'abord ?","back":"**Pneumonie**, **OAP cardiogénique**, **pneumothorax sous tension**.","prio":"P1","sec":"s5"},{"id":"fc-p359-e61fcd","poly":"pneumo","fiche":"p359","front":"Détresse avec radio anormale : quels diagnostics dans un 2e temps ?","back":"**SDRA** et **exacerbation d'une PID**.","prio":"P2","sec":"s5"},{"id":"fc-p359-a497c2","poly":"pneumo","fiche":"p359","front":"Détresse avec radio normale : quelles orientations ?","back":"**Décompensation d'une maladie respiratoire chronique** ou maladie aiguë « de novo ».","prio":"P1","sec":"s5"},{"id":"fc-p359-331494","poly":"pneumo","fiche":"p359","front":"Détresse à radio normale, maladie « de novo » : quelles 3 causes ?","back":"**Embolie pulmonaire**, **pneumothorax**, **exacerbation d'asthme**.","prio":"P1","sec":"s5"},{"id":"fc-p359-945afe","poly":"pneumo","fiche":"p359","front":"Obstruction des voies aériennes supérieures : quels signes cliniques ?","back":"Patient **paniqué**, mains **souvent** au cou, sans son ; **bradypnée inspiratoire** ; dysphonie/aphonie ; **cornage**, stridor.","prio":"P1","sec":"s5"},{"id":"fc-p359-54b50a","poly":"pneumo","fiche":"p359","front":"Obstruction des voies aériennes supérieures : quelles causes ?","back":"**Corps étranger**, laryngite (enfant), **épiglottite**, **œdème de Quincke**, sténose trachéale, tumeur laryngée.","prio":"P1","sec":"s5"},{"id":"fc-p359-a8deb1","poly":"pneumo","fiche":"p359","front":"Inhalation de corps étranger : à quels âges surtout ?","back":"Âges extrêmes : **petit enfant** (80 % < 3 ans), **sujet âgé** (déglutition, dentition).","prio":"P2","sec":"s5"},{"id":"fc-p359-ba209e","poly":"pneumo","fiche":"p359","front":"Détresse avec opacité radiologique et fièvre : quel diagnostic suspecter d'abord ?","back":"**Pneumonie**.","prio":"P1","sec":"s5"},{"id":"fc-p359-2beb9c","poly":"pneumo","fiche":"p359","front":"OAP cardiogénique : quel terrain et quels signes ?","back":"Sans fièvre, **sujet âgé et/ou cardiopathe**, **crépitants** et/ou sibilants, signes de cardiopathie gauche.","prio":"P1","sec":"s5"},{"id":"fc-p359-19eeb4","poly":"pneumo","fiche":"p359","front":"Pneumothorax sous tension : quels signes évocateurs ?","back":"**Asymétrie auscultatoire** ± douleur latérothoracique, surtout sur maladie respiratoire chronique.","prio":"P2","sec":"s5"},{"id":"fc-p359-300d4c","poly":"pneumo","fiche":"p359","front":"Détresse à radio anormale : quelle cause prioritaire peut évoluer vers un SDRA ?","back":"La **pneumonie**.","prio":"P1","sec":"s5"},{"id":"fc-p359-cb7afa","poly":"pneumo","fiche":"p359","front":"Exacerbation de PID suspectée : quel réflexe ?","back":"**Récupérer les imageries thoraciques antérieures** (patient, famille).","prio":"P2","sec":"s5"},{"id":"fc-p359-58a23b","poly":"pneumo","fiche":"p359","front":"Détresse à radio normale : quels arguments pour une décompensation de maladie chronique ?","back":"**Hypercapnie** (PaCO₂ ≥ 45 mmHg) avec pH anormal, **bicarbonates > 30 mmol/L**.","prio":"P1","sec":"s5"},{"id":"fc-p359-7f9924","poly":"pneumo","fiche":"p359","front":"Bicarbonates > 30 mmol/L : de quoi témoignent-ils ?","back":"D'une **hypercapnie chronique**.","prio":"P1","sec":"s5"},{"id":"fc-p359-7326a3","poly":"pneumo","fiche":"p359","front":"Embolie pulmonaire : quel examen affirme le diagnostic devant une détresse ?","back":"L'**angioscanner**.","prio":"P2","sec":"s5"},{"id":"fc-p359-2b021f","poly":"pneumo","fiche":"p359","front":"Pneumonie vs OAP : quel aspect radiographique dans la pneumonie ?","back":"Opacités alvéolaires **le plus souvent systématisées**.","prio":"P1","sec":"s6"},{"id":"fc-p359-a31d64","poly":"pneumo","fiche":"p359","front":"Pneumonie vs OAP : quel aspect radiographique dans l'OAP cardiogénique ?","back":"Opacités alvéolaires **bilatérales, diffuses, péri-hilaires**.","prio":"P1","sec":"s6"},{"id":"fc-p359-a4c938","poly":"pneumo","fiche":"p359","front":"Détresse avec opacités : quels antécédents orientent vers un OAP cardiogénique plutôt qu'une pneumonie ?","back":"**Insuffisance cardiaque**, **facteurs de risque cardiovasculaire** (HTA, diabète…).","prio":"P3","sec":"s6"},{"id":"fc-p359-c4136c","poly":"pneumo","fiche":"p359","front":"Pneumonie : quels signes cliniques évocateurs ?","back":"**Fièvre élevée**, **frissons**, expectoration purulente (inconstante), douleur rythmée par la respiration, **foyer de crépitants**.","prio":"P2","sec":"s6"},{"id":"fc-p359-cae5c4","poly":"pneumo","fiche":"p359","front":"OAP cardiogénique : quels signes fonctionnels et d'examen ?","back":"**Expectoration mousseuse** parfois rosée, **orthopnée** ; HTA, tachycardie, **crépitants bilatéraux** prédominant aux bases.","prio":"P2","sec":"s6"},{"id":"fc-p359-986a28","poly":"pneumo","fiche":"p359","front":"Pneumonie : quels examens microbiologiques ?","back":"**Antigénuries légionelle et pneumocoque**, prélèvements respiratoires, **hémocultures**.","prio":"P2","sec":"s6"},{"id":"fc-p359-16d71f","poly":"pneumo","fiche":"p359","front":"OAP cardiogénique : quels examens d'orientation ?","back":"**ECG** (jamais normal), **échographie cardiaque**, BNP/NT-proBNP.","prio":"P2","sec":"s6"},{"id":"fc-p359-074990","poly":"pneumo","fiche":"p359","front":"Pneumonie vs OAP : quelle biologie oriente ?","back":"Pneumonie : **syndrome inflammatoire**, hyperleucocytose ; OAP : **BNP/NT-proBNP élevé**.","prio":"P2","sec":"s6"},{"id":"fc-p359-4715a7","poly":"pneumo","fiche":"p359","front":"EP comme cause de détresse : quel aspect radiographique mis en avant ?","back":"Radiographie **normale**.","prio":"P1","sec":"s6"},{"id":"fc-p359-5763bc","poly":"pneumo","fiche":"p359","front":"EP comme cause de détresse : quels signes ?","back":"Douleur latérothoracique inspiratoire, **auscultation normale**, signes d'**IVD**, parfois TVP ; fébricule.","prio":"P2","sec":"s6"},{"id":"fc-p359-52eb4f","poly":"pneumo","fiche":"p359","front":"Pneumothorax : quels signes d'examen ?","back":"**Abolition des vibrations vocales et du murmure vésiculaire**, **tympanisme**.","prio":"P1","sec":"s6"},{"id":"fc-p359-5b56e3","poly":"pneumo","fiche":"p359","front":"Pneumothorax : quel aspect radiographique ?","back":"**Hyperclarté limitée par une ligne pleurale**.","prio":"P1","sec":"s6"},{"id":"fc-p359-a06330","poly":"pneumo","fiche":"p359","front":"Pneumothorax : quel terrain ?","back":"Sujet **longiligne**, **tabac**, **cannabis**, maladie respiratoire chronique (emphysème, kystes).","prio":"P2","sec":"s6"},{"id":"fc-p359-dfd6ae","poly":"pneumo","fiche":"p359","front":"Exacerbation d'asthme : quels signes d'examen ?","back":"**Freinage**, **sibilants**, voire **silence auscultatoire** (formes les plus graves) ; dyspnée expiratoire.","prio":"P2","sec":"s6"},{"id":"fc-p359-dd2e6b","poly":"pneumo","fiche":"p359","front":"Exacerbation d'asthme : quel aspect radiographique ?","back":"**Distension thoracique**.","prio":"P3","sec":"s6"},{"id":"fc-p359-7fafa6","poly":"pneumo","fiche":"p359","front":"SDRA : quels critères de définition ?","back":"Détresse **aiguë (< 7 j)**, opacités **alvéolaires bilatérales diffuses**, **sans** défaillance cardiaque ni surcharge (PAPO < 15 mmHg).","prio":"P2","sec":"s7"},{"id":"fc-p359-101960","poly":"pneumo","fiche":"p359","front":"SDRA : comment classer la sévérité ?","back":"**PaO₂/FiO₂** avec PEP ≥ 5 : léger **200-300**, modéré **100-200**, sévère **≤ 100** mmHg.","prio":"P2","sec":"s7"},{"id":"fc-p359-e88373","poly":"pneumo","fiche":"p359","front":"PEP et CPAP : quelle différence ?","back":"PEP : sous **ventilation assistée** ; CPAP : en **ventilation spontanée** au masque (recrutement alvéolaire).","prio":"P3","sec":"s7"},{"id":"fc-p359-2ec210","poly":"pneumo","fiche":"p359","front":"OAP cardiogénique vs SDRA : quel mécanisme pour chacun ?","back":"OAP : **pression hydrostatique ↑**, **transsudat** ; SDRA : **perméabilité ↑**, **exsudat** (œdème lésionnel).","prio":"P2","sec":"s7"},{"id":"fc-p359-309397","poly":"pneumo","fiche":"p359","front":"SDRA : quelle lésion histologique ?","back":"**Dommage alvéolaire diffus** (connu post-mortem, jamais de biopsie).","prio":"P3","sec":"s7"},{"id":"fc-p359-b70354","poly":"pneumo","fiche":"p359","front":"SDRA : quelles conséquences mécaniques sur le poumon ?","back":"Altération **hétérogène** des rapports VA/Q, **baisse de la compliance**.","prio":"P3","sec":"s7"},{"id":"fc-p359-16661a","poly":"pneumo","fiche":"p359","front":"SDRA : citer des causes exogènes (épithéliales).","back":"**Pneumonies** (bactérienne, virale, fongique), **fumées toxiques**, **inhalation gastrique** (Mendelson), noyade.","prio":"P2","sec":"s7"},{"id":"fc-p359-8fbce7","poly":"pneumo","fiche":"p359","front":"SDRA : citer des causes endogènes (endothéliales).","back":"**Sepsis sévère** (+++), pancréatite aiguë, embolie amniotique, CEC, transfusions massives, polytraumatisme, brûlures.","prio":"P2","sec":"s7"},{"id":"fc-p359-7b1a29","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quelle nature d'urgence ?","back":"**Urgence thérapeutique** : **oxygène toujours** ± assistance ventilatoire.","prio":"P1","sec":"s8"},{"id":"fc-p359-93a7c6","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : qui appeler ?","back":"Hors hôpital : **Samu** ; à l'hôpital : **réanimateur** ou médecin de soins intensifs.","prio":"P1","sec":"s8"},{"id":"fc-p359-c1c2c0","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quelles premières mesures de surveillance ?","back":"**Scoper** sans délai, voire installer en **salle de déchocage**.","prio":"P2","sec":"s8"},{"id":"fc-p359-a7d92a","poly":"pneumo","fiche":"p359","front":"Oxygénothérapie en détresse respiratoire : quel but ?","back":"Corriger l'hypoxémie pour **prévenir l'arrêt cardio-respiratoire hypoxique**.","prio":"P2","sec":"s8"},{"id":"fc-p359-50816c","poly":"pneumo","fiche":"p359","front":"Oxygène en détresse respiratoire : quel débit initial si hypoxémie profonde ?","back":"**Débit élevé d'emblée**, puis adapté à la clinique et à la SpO₂.","prio":"P1","sec":"s8"},{"id":"fc-p359-8ae4f5","poly":"pneumo","fiche":"p359","front":"Oxygène en détresse respiratoire : quelle cible de SpO₂ ?","back":"**88 à 92 %**, obtenue très vite.","prio":"P1","sec":"s8"},{"id":"fc-p359-e38dc4","poly":"pneumo","fiche":"p359","front":"BPCO en détresse avec hypoxémie profonde : faut-il réduire le débit initial d'O₂ ?","back":"**Non** : haut débit initial ; dépister l'hypercapnie par les **gaz du sang sous O₂**.","prio":"P1","sec":"s8"},{"id":"fc-p359-2c2df0","poly":"pneumo","fiche":"p359","front":"Masque simple vs masque à haute concentration : quels débits ?","back":"Simple : **5 à 10 L/min** ; haute concentration avec réserve : **> 8 L/min**.","prio":"P2","sec":"s8"},{"id":"fc-p359-905140","poly":"pneumo","fiche":"p359","front":"Canules nasales à haut débit : quand les envisager et quels débits ?","back":"Au-delà de **15 L/min** ; **10 à 50 L/min**, gaz réchauffé et humidifié.","prio":"P2","sec":"s8"},{"id":"fc-p359-d0acdd","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quel abord veineux poser ?","back":"**Voie veineuse de gros calibre**.","prio":"P3","sec":"s8"},{"id":"fc-p359-e6db50","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire : quel rythme de surveillance des constantes ?","back":"**SpO₂ et FC en continu** ; **PA et FR toutes les 10 min**.","prio":"P1","sec":"s8"},{"id":"fc-p359-3ef076","poly":"pneumo","fiche":"p359","front":"Gaz du sang sous O₂ : pourquoi les contrôler, surtout chez l'insuffisant respiratoire chronique ?","back":"Efficacité de l'oxygénation et absence d'**hypercapnie** (l'O₂ peut freiner les centres respiratoires).","prio":"P1","sec":"s8"},{"id":"fc-p359-4a2b7b","poly":"pneumo","fiche":"p359","front":"SaO₂ de 90 % : à quelle PaO₂ correspond-elle environ ?","back":"**PaO₂ ≈ 60 mmHg** (8 kPa).","prio":"P2","sec":"s8"},{"id":"fc-p359-68fe2e","poly":"pneumo","fiche":"p359","front":"Assistance ventilatoire mécanique : est-elle systématique en détresse respiratoire ?","back":"**Non**, seulement **parfois**, sur indications spécifiques (l'O₂, lui, est toujours donné).","prio":"P2","sec":"s9"},{"id":"fc-p359-5af38c","poly":"pneumo","fiche":"p359","front":"Ventilation mécanique en détresse respiratoire : quelles indications ?","back":"**Hypoventilation menaçante** (respiration paradoxale, troubles de conscience, **pH < 7,35** + hypercapnie) ou **hypoxémie réfractaire**.","prio":"P2","sec":"s9"},{"id":"fc-p359-8bb87f","poly":"pneumo","fiche":"p359","front":"VNI : à quels patients est-elle réservée ?","back":"**Défaillance respiratoire isolée** chez un patient **coopérant**.","prio":"P2","sec":"s9"},{"id":"fc-p359-324219","poly":"pneumo","fiche":"p359","front":"VNI : quelles sont les deux indications principales ?","back":"**Exacerbation de BPCO avec pH < 7,35** et **OAP cardiogénique**.","prio":"P2","sec":"s9"},{"id":"fc-p359-215b0b","poly":"pneumo","fiche":"p359","front":"VNI : quels bénéfices ?","back":"**Baisse de la morbi-mortalité** et des **infections nosocomiales** (verrou glottique préservé), séjour plus court.","prio":"P3","sec":"s9"},{"id":"fc-p359-e1dbdd","poly":"pneumo","fiche":"p359","front":"Ventilation invasive d'emblée : quelles indications ?","back":"Défaillance non seulement respiratoire : **troubles de conscience**, **choc**, **polytraumatisme**, autres organes ; ou **échec de VNI**.","prio":"P2","sec":"s9"},{"id":"fc-p359-118a91","poly":"pneumo","fiche":"p359","front":"Ventilation invasive : quelles indications classiques ?","back":"**SDRA** et **coma (Glasgow < 9)**.","prio":"P2","sec":"s9"},{"id":"fc-p359-dd350c","poly":"pneumo","fiche":"p359","front":"Orientation étiologique : qu'apportent respectivement la radio de thorax et les gaz du sang ?","back":"Radio : **opacités ou non** ; gaz du sang : **acidose ou alcalose**, **hypercapnie ou non**.","prio":"P1","sec":"s10"},{"id":"fc-p359-e064ee","poly":"pneumo","fiche":"p359","front":"Corps étranger chez un patient conscient qui tousse : quelle conduite ?","back":"**Laisser tousser** (la toux expulse mieux que le Heimlich).","prio":"P1","sec":"s11"},{"id":"fc-p359-4d1044","poly":"pneumo","fiche":"p359","front":"Corps étranger, patient conscient et tonique qui ne tousse plus : quelle conduite ?","back":"**Manœuvre de Heimlich**.","prio":"P1","sec":"s11"},{"id":"fc-p359-a287c9","poly":"pneumo","fiche":"p359","front":"Manœuvre de Heimlich : comment la réaliser ?","back":"Derrière le patient, **poing dans le creux épigastrique**, traction brusque **vers le haut et vers soi**.","prio":"P2","sec":"s11"},{"id":"fc-p359-04e4ce","poly":"pneumo","fiche":"p359","front":"Corps étranger avec perte de connaissance : quelle conduite ?","back":"Allonger, chercher un CE pharyngé au doigt, puis **réanimation** (massage cardiaque sur plan dur).","prio":"P1","sec":"s11"},{"id":"fc-p359-b7acd9","poly":"pneumo","fiche":"p359","front":"Obstruction totale des voies aériennes supérieures : quels signes ?","back":"Mouvements respiratoires **sans aucun flux**, **aphonie** : urgence vitale extrême.","prio":"P1","sec":"s11"},{"id":"fc-p359-cec7b5","poly":"pneumo","fiche":"p359","front":"Corps étranger dont l'expulsion n'est pas authentifiée : quelle conduite ?","back":"Le considérer **toujours présent** : **bronchoscopie**, même sans symptôme.","prio":"P1","sec":"s11"},{"id":"fc-p359-1781e1","poly":"pneumo","fiche":"p359","front":"Bronchoscopie d'extraction d'un corps étranger : où la réaliser ?","back":"En **centre spécialisé** (pas par une équipe non rompue à la technique).","prio":"P3","sec":"s11"},{"id":"fc-p359-330813","poly":"pneumo","fiche":"p359","front":"Épiglottite : pourquoi est-elle devenue rarissime ?","back":"**Vaccination anti-Haemophilus influenzae** des nourrissons.","prio":"P2","sec":"s11"},{"id":"fc-p359-9452da","poly":"pneumo","fiche":"p359","front":"Détresse respiratoire sous traitement : que signifie l'apparition d'un signe de faillite ?","back":"**Gravité** ; respiration paradoxale → discuter l'**assistance ventilatoire**.","prio":"P2","sec":"s12"},{"id":"fc-p359bis-dd7aab","poly":"pneumo","fiche":"p359bis","front":"Corps étranger des voies aériennes : quelle définition ?","back":"Ensemble des manifestations dues à l'**inhalation accidentelle** d'un corps étranger dans les voies aériennes.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-2aa35c","poly":"pneumo","fiche":"p359bis","front":"Obstruction brutale des voies aériennes par un corps étranger : quel tableau le plus souvent ?","back":"Un **syndrome de pénétration**.","prio":"P1","sec":"s1"},{"id":"fc-p359bis-e29691","poly":"pneumo","fiche":"p359bis","front":"Corps étranger inhalé : quelle issue possible sans expulsion ni prise en charge adaptée ?","back":"**Mortelle**.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-eaff0f","poly":"pneumo","fiche":"p359bis","front":"Corps étranger inhalé chez l'enfant : quel type le plus souvent ?","back":"Des **aliments** : **graines d'oléagineux** (cacahuètes, petites noix d'apéritif).","prio":"P2","sec":"s1"},{"id":"fc-p359bis-f39459","poly":"pneumo","fiche":"p359bis","front":"Corps étranger inhalé chez l'adulte édenté : quel type ?","back":"Des **morceaux de viande**.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-a1eda7","poly":"pneumo","fiche":"p359bis","front":"Corps étranger métallique ou plastique : quelles circonstances ?","back":"**Jouets** chez l'enfant ; **clous**, punaises tenus entre les lèvres en **bricolant** (adulte, adolescent).","prio":"P3","sec":"s1"},{"id":"fc-p359bis-fee7bb","poly":"pneumo","fiche":"p359bis","front":"Inhalation de fragments dentaires : quelles circonstances ?","back":"**Soins dentaires** ou **traumatisme facial** avec dent fracturée.","prio":"P3","sec":"s1"},{"id":"fc-p359bis-7598f4","poly":"pneumo","fiche":"p359bis","front":"Corps étranger inhalé : quels sont les 3 devenirs possibles ?","back":"**Obstruction aiguë**, **expulsion**, **enclavement**.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-d47e61","poly":"pneumo","fiche":"p359bis","front":"Obstruction aiguë par corps étranger : quelles 2 formes ?","back":"**Transitoire** (toux qui mobilise le CE) ou **définitive** (asphyxie si blocage laryngé/trachéal).","prio":"P2","sec":"s1"},{"id":"fc-p359bis-2d5dc5","poly":"pneumo","fiche":"p359bis","front":"Enfants de moins de 4 ans : quelle part des décès accidentels est due à l'inhalation de CE ?","back":"**7 %**.","prio":"P3","sec":"s1"},{"id":"fc-p359bis-2a5244","poly":"pneumo","fiche":"p359bis","front":"Corps étranger inhalé : dans quelle proportion est-il expulsé ?","back":"Dans **plus de la moitié** des cas, après une **toux violente**.","prio":"P1","sec":"s1"},{"id":"fc-p359bis-4782ee","poly":"pneumo","fiche":"p359bis","front":"Expulsion d'un corps étranger : pourquoi l'entourage peut-il ne pas la voir ?","back":"Revenu au-dessus de la **glotte**, le CE peut être **avalé** aussitôt.","prio":"P1","sec":"s1"},{"id":"fc-p359bis-c96f04","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : où se loge-t-il chez l'enfant et chez l'adulte ?","back":"Enfant : surtout **bronche principale** ; adulte : surtout bronche **lobaire ou segmentaire**.","prio":"P1","sec":"s1"},{"id":"fc-p359bis-202d85","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : que devient la toux ?","back":"Elle **cesse** le plus souvent.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-1867b8","poly":"pneumo","fiche":"p359bis","front":"Corps étranger coincé dans un tronc souche : quels signes ?","back":"**Murmure vésiculaire diminué** d'un côté, parfois **wheezing**.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-60b6af","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : par quel mécanisme le poumon peut-il se distendre ?","back":"Effet **valve unidirectionnelle** : **piégeage de l'air** (hyperinflation).","prio":"P3","sec":"s1"},{"id":"fc-p359bis-726fd6","poly":"pneumo","fiche":"p359bis","front":"Piégeage de l'air par un corps étranger : pourquoi l'air passe-t-il à l'inspiration mais pas à l'expiration ?","back":"Inspiration **active** franchit l'obstacle ; expiration **passive** ne l'évacue pas.","prio":"P3","sec":"s1"},{"id":"fc-p359bis-983db8","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : de quoi dépendent symptômes et complications ?","back":"Du **niveau** où il est bloqué.","prio":"P2","sec":"s1"},{"id":"fc-p359bis-42a319","poly":"pneumo","fiche":"p359bis","front":"Inhalation de corps étranger : quel est le premier pic de fréquence ?","back":"L'**enfant de moins de 3 ans** (porte les objets à la bouche, commence à marcher).","prio":"P1","sec":"s2"},{"id":"fc-p359bis-1ba06d","poly":"pneumo","fiche":"p359bis","front":"Enfant de moins de 3 ans : quel est le corps étranger le plus fréquent ?","back":"La **cacahuète** (graine d'oléagineux à l'apéritif).","prio":"P1","sec":"s2"},{"id":"fc-p359bis-a6708d","poly":"pneumo","fiche":"p359bis","front":"Corps étranger chez le petit enfant : est-il plus souvent à droite ?","back":"**Non** : bronches principales **symétriques**, pas de prédominance droite.","prio":"P1","sec":"s2"},{"id":"fc-p359bis-a268b2","poly":"pneumo","fiche":"p359bis","front":"Sujet âgé : quels facteurs favorisent l'inhalation de corps étranger ?","back":"**Trouble de déglutition** (maladie neurologique, séquelles d'AVC) et **mauvaise denture**.","prio":"P1","sec":"s2"},{"id":"fc-p359bis-aa9777","poly":"pneumo","fiche":"p359bis","front":"Sujet âgé à mauvaise denture : quel tableau typique ?","back":"**Asphyxie aiguë**, notamment par un **morceau de viande** (CE en général coincé à travers le larynx).","prio":"P2","sec":"s2"},{"id":"fc-p359bis-5a994e","poly":"pneumo","fiche":"p359bis","front":"Inhalation chez l'adulte et l'adolescent : dans quels contextes ?","back":"Rare : **traumatisme facial**, **bricolage**, **trouble de conscience** (convulsion, coma, ivresse aiguë).","prio":"P3","sec":"s2"},{"id":"fc-p359bis-71f67e","poly":"pneumo","fiche":"p359bis","front":"Adulte : de quel côté les corps étrangers s'enclavent-ils plus souvent et pourquoi ?","back":"À **droite** : bronche principale droite plus **verticale** et de plus **gros calibre**.","prio":"P3","sec":"s2"},{"id":"fc-p359bis-327363","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration : à quelle phase correspond-il ?","back":"Phase où le CE est **mobile** dans les voies aériennes ; début **brutal**.","prio":"P2","sec":"s3"},{"id":"fc-p359bis-6800c5","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration : quels signes ?","back":"**Toux quinteuse** + accès de **suffocation** avec **tirage**, **cornage** et **cyanose**.","prio":"P1","sec":"s3"},{"id":"fc-p359bis-2cab97","poly":"pneumo","fiche":"p359bis","front":"Cornage : quelle définition ?","back":"Reprise de l'inspiration **difficile et bruyante**.","prio":"P2","sec":"s3"},{"id":"fc-p359bis-324a0b","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration : dans quel contexte typique ?","back":"Sujet **antérieurement sain**, pendant un **repas** ou un **jeu**.","prio":"P1","sec":"s3"},{"id":"fc-p359bis-7cf676","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration : quelle évolution habituelle ?","back":"Le plus souvent **résolutif en quelques secondes**.","prio":"P2","sec":"s3"},{"id":"fc-p359bis-e64bb8","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration non régressif : quel mécanisme et quel risque ?","back":"CE **volumineux** bloqué dans le **larynx ou la trachée** : mort par **asphyxie** en quelques minutes.","prio":"P1","sec":"s3"},{"id":"fc-p359bis-37a463","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration non régressif : quels corps étrangers typiques ?","back":"**Morceau de viande**, **grosses perles**.","prio":"P3","sec":"s3"},{"id":"fc-p359bis-f8b85e","poly":"pneumo","fiche":"p359bis","front":"Symptômes calmés mais expulsion non authentifiée : comment considérer le corps étranger ?","back":"**Toujours présent** : envisager une **bronchoscopie**, même sans symptôme.","prio":"P1","sec":"s3"},{"id":"fc-p359bis-429465","poly":"pneumo","fiche":"p359bis","front":"Au décours d'un syndrome de pénétration avec CE expulsé : que montre l'examen ?","back":"Examen respiratoire **normal**.","prio":"P2","sec":"s4"},{"id":"fc-p359bis-61ee5f","poly":"pneumo","fiche":"p359bis","front":"Syndrome de pénétration non vu : quel signe cutanéo-muqueux est très évocateur ?","back":"Des **pétéchies** (visage, tronc, bouche, conjonctives).","prio":"P1","sec":"s4"},{"id":"fc-p359bis-092db5","poly":"pneumo","fiche":"p359bis","front":"Pétéchies au décours d'un syndrome de pénétration : que traduisent-elles ?","back":"La **violence des quintes de toux**.","prio":"P2","sec":"s4"},{"id":"fc-p359bis-f410e2","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé proximal : quels signes et chez qui surtout ?","back":"Surtout chez l'**enfant** : **murmure vésiculaire diminué** + **wheezing** du côté du CE.","prio":"P1","sec":"s4"},{"id":"fc-p359bis-94ac1d","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé distal (surtout chez l'adulte) : quels symptômes ?","back":"**Aucun** : un examen normal ne l'élimine pas.","prio":"P1","sec":"s4"},{"id":"fc-p359bis-f36b65","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : que montre le plus souvent la radiographie ?","back":"Elle est **normale** (seuls **10 %** des CE sont radio-opaques).","prio":"P2","sec":"s4"},{"id":"fc-p359bis-41e98d","poly":"pneumo","fiche":"p359bis","front":"Corps étranger enclavé : quelles anomalies radiographiques possibles ?","back":"**Atélectasie** ; **hyperclarté unilatérale** augmentant en expiration (piégeage).","prio":"P3","sec":"s4"},{"id":"fc-p359bis-ba156d","poly":"pneumo","fiche":"p359bis","front":"Détresse brutale avec tirage et cornage : quel diagnostic différentiel principal du CE ?","back":"L'**épiglottite aiguë**.","prio":"P1","sec":"s5"},{"id":"fc-p359bis-7f2d5b","poly":"pneumo","fiche":"p359bis","front":"Épiglottite aiguë : chez quel enfant ?","back":"Enfant **non ou mal vacciné**.","prio":"P1","sec":"s5"},{"id":"fc-p359bis-5acb5f","poly":"pneumo","fiche":"p359bis","front":"Épiglottite aiguë : quels arguments cliniques ?","back":"**Fièvre élevée**, **voix étouffée**, **hypersalivation**, **absence de toux**, bouche entrouverte, dyspnée **aggravée couché**.","prio":"P1","sec":"s5"},{"id":"fc-p359bis-ddb72c","poly":"pneumo","fiche":"p359bis","front":"Tableau d'infection respiratoire basse chez un enfant < 3 ans : quels diagnostics différentiels ?","back":"**Pneumonie aiguë communautaire** ou **bronchite aiguë sifflante**.","prio":"P3","sec":"s5"},{"id":"fc-p359bis-f77f29","poly":"pneumo","fiche":"p359bis","front":"Au décours d'un syndrome de pénétration : quelle est la seule exception à l'orientation vers l'hôpital ?","back":"L'**expulsion constatée** du corps étranger.","prio":"P3","sec":"s6"},{"id":"fc-p359bis-68b1d4","poly":"pneumo","fiche":"p359bis","front":"Expulsion non constatée au décours d'un syndrome de pénétration : quel bilan ?","back":"**Cliché de thorax** ± **endoscopie souple**.","prio":"P3","sec":"s6"},{"id":"fc-p359bis-d6d964","poly":"pneumo","fiche":"p359bis","front":"Signes persistants (toux, dyspnée, cornage, tirage) au décours : que craindre ?","back":"Un CE resté dans la **trachée**, à risque de s'**enclaver**.","prio":"P3","sec":"s6"},{"id":"fc-p359bis-9be3c1","poly":"pneumo","fiche":"p359bis","front":"Radiographie en inspiration après suspicion de CE : que rechercher ?","back":"CE **radio-opaque**, **distension/piégeage** unilatéral, complication (**atélectasie**, **pneumonie**).","prio":"P3","sec":"s6"},{"id":"fc-p359bis-bf361c","poly":"pneumo","fiche":"p359bis","front":"Radiographie en expiration : quand la demander ?","back":"**Seulement si** le cliché en inspiration est **normal** (repère mieux un piégeage).","prio":"P3","sec":"s6"},{"id":"fc-p359bis-77b045","poly":"pneumo","fiche":"p359bis","front":"Quand extraire un corps étranger par bronchoscopie rigide ?","back":"**Murmure vésiculaire diminué** d'un côté **+ piégeage** du même côté (CE probable > 90 %).","prio":"P3","sec":"s6"},{"id":"fc-p359bis-997ad5","poly":"pneumo","fiche":"p359bis","front":"Suspicion de CE sans critère de bronchoscopie rigide : quel examen ?","back":"**Endoscopie souple** ; alternative : **scanner thoracique basse dose**.","prio":"P3","sec":"s6"},{"id":"fc-p359bis-e193e1","poly":"pneumo","fiche":"p359bis","front":"Quel terme ne doit plus être employé pour le piégeage unilatéral ?","back":"« **Emphysème post-obstructif** » (parler de distension ou piégeage).","prio":"P3","sec":"s6"},{"id":"fc-p359bis-b43770","poly":"pneumo","fiche":"p359bis","front":"Bronchoscopie rigide : comment se déroule l'extraction ?","back":"Sous **anesthésie générale**, CE saisi à la **pince rigide**, patient **ventilé par le bronchoscope**.","prio":"P3","sec":"s6"},{"id":"fc-p359bis-1a8617","poly":"pneumo","fiche":"p359bis","front":"Victime consciente qui tousse après inhalation d'un CE : quelle attitude ?","back":"**Respecter la toux** : elle expulse mieux le CE que le Heimlich.","prio":"P1","sec":"s7"},{"id":"fc-p359bis-872584","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Heimlich : quand la faire ?","back":"Victime qui **ne tousse plus** mais reste **consciente et tonique**.","prio":"P1","sec":"s7"},{"id":"fc-p359bis-a287c9","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Heimlich : comment la réaliser ?","back":"Derrière la victime, **jambe d'appui entre ses jambes** ; **poing au creux épigastrique** tenu par l'autre main ; traction **sèche vers le haut et vers soi**.","prio":"P1","sec":"s7"},{"id":"fc-p359bis-35d9d9","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Heimlich : quel est son principe ?","back":"Remontée du **diaphragme** → **hyperpression intrathoracique** soudaine qui chasse le CE.","prio":"P2","sec":"s7"},{"id":"fc-p359bis-b4e2f7","poly":"pneumo","fiche":"p359bis","front":"Victime qui perd connaissance par CE : quelle conduite ?","back":"**Allonger au sol**, chercher **au doigt** un gros CE pharyngé, puis **réanimation**.","prio":"P1","sec":"s7"},{"id":"fc-p359bis-2edaaa","poly":"pneumo","fiche":"p359bis","front":"Victime inconsciente : pourquoi ne plus faire de Heimlich ?","back":"Elle est **hypotonique** : impossible de la soutenir pour la manœuvre.","prio":"P2","sec":"s7"},{"id":"fc-p359bis-f8b73f","poly":"pneumo","fiche":"p359bis","front":"Obstruction par CE chez l'inconscient : quel geste expulse le mieux le corps étranger ?","back":"Le **massage cardiaque externe** sur plan dur.","prio":"P1","sec":"s7"},{"id":"fc-p359bis-7cca79","poly":"pneumo","fiche":"p359bis","front":"Enfant de moins de 2 ans en asphyxie par CE : quelle manœuvre ?","back":"La **manœuvre de Mofenson**.","prio":"P1","sec":"s8"},{"id":"fc-p359bis-9ed263","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Mofenson : comment positionner l'enfant ?","back":"À **plat ventre** sur l'avant-bras posé sur la jambe, **tête maintenue** par la main.","prio":"P1","sec":"s8"},{"id":"fc-p359bis-e02276","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Mofenson : combien de claques dans le dos ?","back":"Jusqu'à **5 claques** dans le dos, main bien à plat.","prio":"P1","sec":"s8"},{"id":"fc-p359bis-202ccc","poly":"pneumo","fiche":"p359bis","front":"Manœuvre de Mofenson inefficace : que faire ensuite ?","back":"Retourner l'enfant **sur le dos** et faire des **pressions verticales sur le sternum**.","prio":"P1","sec":"s8"},{"id":"fc-p359bis-0f92ab","poly":"pneumo","fiche":"p359bis","front":"Suspicion d'inhalation de CE chez un enfant asymptomatique : faut-il l'adresser à l'hôpital ?","back":"**Oui** (sauf expulsion constatée par l'entourage).","prio":"P1","sec":"s9"},{"id":"fc-p359bis-8324b0","poly":"pneumo","fiche":"p359bis","front":"Enfant : où réaliser la bronchoscopie d'extraction ?","back":"En **centre spécialisé** (pédiatres, pneumologues ou ORL).","prio":"P1","sec":"s9"},{"id":"fc-p359bis-3d4a05","poly":"pneumo","fiche":"p359bis","front":"Extraction d'un CE par une équipe non entraînée : est-ce recommandé ?","back":"**Non**.","prio":"P2","sec":"s9"},{"id":"fc-p359bis-717d9a","poly":"pneumo","fiche":"p359bis","front":"Enfant suspect d'avoir inhalé un CE : quelle orientation ?","back":"Adressé **sans attendre** à un **centre spécialisé**.","prio":"P1","sec":"s10"},{"id":"fc-p359bis-9ea6ab","poly":"pneumo","fiche":"p359bis","front":"Enfant suspect d'inhalation de CE : dans quelle position le transporter ?","back":"En position **assise**.","prio":"P1","sec":"s10"},{"id":"fc-p359bis-497a32","poly":"pneumo","fiche":"p359bis","front":"Enfant dyspnéique ou suspect d'épiglottite : quel transport ?","back":"**Médicalisé** par une équipe **capable d'intuber** (SMUR **pédiatrique**).","prio":"P1","sec":"s10"},{"id":"fc-p359bis-8f6594","poly":"pneumo","fiche":"p359bis","front":"Transport d'un enfant suspect de CE : quelle mesure organisationnelle ?","back":"**Prévenir l'équipe** d'accueil de son arrivée.","prio":"P2","sec":"s10"},{"id":"fc-p359bis-94b689","poly":"pneumo","fiche":"p359bis","front":"Bronchoscopie rigide chez l'enfant : quelle exigence particulière ?","back":"Une **anesthésie** demandant une **expertise particulière**.","prio":"P3","sec":"s10"},{"id":"fc-p360-6d89d8","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quelle définition ?","back":"Présence d'**air dans l'espace pleural** = **épanchement pleural gazeux**.","prio":"P1","sec":"s1"},{"id":"fc-p360-c6b19a","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quelle conséquence sur le poumon ?","back":"**Collapsus** partiel ou complet : le poumon se désolidarise de la paroi et se **rétracte sur le hile**.","prio":"P1","sec":"s1"},{"id":"fc-p360-e45f08","poly":"pneumo","fiche":"p360","front":"Plèvre : quels sont ses deux feuillets ?","back":"**Pariétal** (costal, diaphragmatique, médiastinal ; tapisse cage thoracique, diaphragme, médiastin) + **viscéral** (recouvre le poumon, scissures comprises).","prio":"P3","sec":"s1"},{"id":"fc-p360-2fb83f","poly":"pneumo","fiche":"p360","front":"Espace pleural : qu'est-ce qui le maintient virtuel et le poumon en expansion ?","back":"La **pression négative** pleurale (« **vide pleural** »).","prio":"P2","sec":"s1"},{"id":"fc-p360-aa69c0","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quels sont les 3 cadres ?","back":"**Spontané primaire** (PSP) · **spontané secondaire** (PSS) · **traumatique** (dont iatrogène).","prio":"P1","sec":"s2"},{"id":"fc-p360-b99b90","poly":"pneumo","fiche":"p360","front":"PNO spontané primaire : quel terrain typique ?","back":"Sujet **jeune**, **longiligne**, **fumeur**, sans maladie pulmonaire ; poumon **en apparence sain**.","prio":"P1","sec":"s2"},{"id":"fc-p360-d17ab0","poly":"pneumo","fiche":"p360","front":"PNO spontané primaire : quel mécanisme ?","back":"Anomalie **microscopique** de la plèvre viscérale qui la rend « **poreuse** ».","prio":"P2","sec":"s2"},{"id":"fc-p360-de0865","poly":"pneumo","fiche":"p360","front":"PNO spontané primaire : quel âge et quel sexe surtout ?","back":"Adulte de **moins de 35 ans**, le plus souvent un **homme**, grand et longiligne.","prio":"P2","sec":"s2"},{"id":"fc-p360-294a13","poly":"pneumo","fiche":"p360","front":"PNO spontané primaire : quelle proportion de fumeurs ?","back":"**3 fois sur 4** ; lien causal démontré avec le tabac → justifie une **prévention primaire**.","prio":"P2","sec":"s2"},{"id":"fc-p360-e55090","poly":"pneumo","fiche":"p360","front":"PNO spontané secondaire : quel terrain et quel mécanisme principal ?","back":"Sujet **en général plus âgé** avec maladie pulmonaire (connue ou non) ; rupture d'une **bulle d'emphysème** dans la plèvre.","prio":"P1","sec":"s2"},{"id":"fc-p360-29e12b","poly":"pneumo","fiche":"p360","front":"PNO spontané secondaire : quelle maladie sous-jacente surtout ?","back":"La **BPCO** ; plus rarement asthme, pneumopathies interstitielles, mucoviscidose.","prio":"P2","sec":"s2"},{"id":"fc-p360-c645f0","poly":"pneumo","fiche":"p360","front":"PNO spontané secondaire : quel autre mécanisme que la bulle ?","back":"Rupture de lésions **kystiques ou nécrosantes** du parenchyme (mucoviscidose, fibroses, tuberculose…).","prio":"P3","sec":"s2"},{"id":"fc-p360-300ec0","poly":"pneumo","fiche":"p360","front":"PNO traumatique : quel est le mécanisme commun ?","back":"**Effraction de la plèvre viscérale** par traumatisme direct ou indirect.","prio":"P2","sec":"s2"},{"id":"fc-p360-642a13","poly":"pneumo","fiche":"p360","front":"PNO iatrogène : citer des gestes en cause ?","back":"**Ponction transthoracique** · **ponction pleurale** · **voie veineuse centrale**…","prio":"P1","sec":"s2"},{"id":"fc-p360-51d356","poly":"pneumo","fiche":"p360","front":"PNO traumatique à thorax fermé : quelles causes ?","back":"**Côte fracturée** blessant la plèvre viscérale ; **blast** pulmonaire.","prio":"P2","sec":"s2"},{"id":"fc-p360-2dfbf0","poly":"pneumo","fiche":"p360","front":"PNO traumatique à thorax ouvert : quelle cause ?","back":"**Plaie pénétrante** (arme blanche, balle).","prio":"P2","sec":"s2"},{"id":"fc-p360-c697f0","poly":"pneumo","fiche":"p360","front":"Côte fracturée : quel signe montre l'effraction pleurale ?","back":"De l'**air dans les parties molles de l'aisselle** (côte rentrée vers l'intérieur : plèvre pariétale, viscérale puis parenchyme).","prio":"P3","sec":"s2"},{"id":"fc-p360-77f617","poly":"pneumo","fiche":"p360","front":"Blast : quel mécanisme et que peut montrer l'imagerie ?","back":"**Ruptures alvéolaires multiples** par hyperpression ; emphysème sous-cutané, pneumomédiastin, pneumopéricarde, PNO.","prio":"P3","sec":"s2"},{"id":"fc-p360-850cba","poly":"pneumo","fiche":"p360","front":"Cocaïne : quel lien avec le pneumothorax ?","back":"PNO possible lié aux **efforts inspiratoires** (sniff) ; prise de cocaïne à **rechercher à l'interrogatoire**.","prio":"P2","sec":"s2"},{"id":"fc-p360-c909f5","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quel facteur favorisant le Collège retient-il ?","back":"Le **tabagisme actif**.","prio":"P1","sec":"s2"},{"id":"fc-p360-8fbfeb","poly":"pneumo","fiche":"p360","front":"Efforts physiques ou à glotte fermée : favorisent-ils le pneumothorax ?","back":"**Non**, contrairement à une croyance répandue (piège).","prio":"P1","sec":"s2"},{"id":"fc-p360-4d4387","poly":"pneumo","fiche":"p360","front":"Vols aériens et plongée : quel rôle sur le pneumothorax ?","back":"Ne **créent pas** de PNO de novo, mais **majorent** un PNO déjà présent.","prio":"P2","sec":"s2"},{"id":"fc-p360-322619","poly":"pneumo","fiche":"p360","front":"Pneumothorax : sur quels deux éléments repose le diagnostic ?","back":"**Signes cliniques** + **radiographie de thorax de face en inspiration**.","prio":"P1","sec":"s3"},{"id":"fc-p360-d34d55","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quelles caractéristiques de la douleur ?","back":"Type **pleural** : **brutale**, **homolatérale**, latérothoracique ou postérieure, ↑ à la toux et à l'inspiration profonde, **classiquement** non reproduite à la palpation.","prio":"P1","sec":"s3"},{"id":"fc-p360-87d9ea","poly":"pneumo","fiche":"p360","front":"Douleur du pneumothorax : comment évolue-t-elle souvent ?","back":"Elle **s'estompe souvent vite**.","prio":"P3","sec":"s3"},{"id":"fc-p360-509114","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quels signes fonctionnels autres que la douleur ?","back":"**Dyspnée inconstante** d'intensité variable · **toux sèche** irritative · parfois **aucun symptôme**.","prio":"P2","sec":"s3"},{"id":"fc-p360-03331e","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quels sont les 3 signes physiques à chercher ?","back":"**Murmure vésiculaire** diminué ou aboli · **vibrations vocales abolies** · **tympanisme** à la percussion.","prio":"P1","sec":"s3"},{"id":"fc-p360-aacf16","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quel aspect de l'hémithorax à l'inspection ?","back":"Normal, ou **distendu et moins mobile** (rare).","prio":"P3","sec":"s3"},{"id":"fc-p360-f7552f","poly":"pneumo","fiche":"p360","front":"Pneumothorax : l'absence de dyspnée élimine-t-elle le diagnostic ?","back":"**Non** : dyspnée **inconstante**, le PNO peut être **asymptomatique**.","prio":"P1","sec":"s3"},{"id":"fc-p360-864236","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quel examen fait le diagnostic de certitude ?","back":"**Radiographie de thorax de face, en inspiration** (apprécie aussi la taille).","prio":"P1","sec":"s4"},{"id":"fc-p360-9b8f9f","poly":"pneumo","fiche":"p360","front":"Pneumothorax : faut-il un cliché en expiration ?","back":"**Non**, il ne doit plus être fait.","prio":"P1","sec":"s4"},{"id":"fc-p360-29ddb8","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quel examen en cas de doute radiologique ?","back":"**Scanner thoracique sans injection**.","prio":"P1","sec":"s4"},{"id":"fc-p360-c91e35","poly":"pneumo","fiche":"p360","front":"Pneumothorax : dans quels cas le scanner est-il indiqué ?","back":"Non systématique : formes **traumatiques**, formes **secondaires**, **doute** diagnostique, recherche d'une **maladie sous-jacente**.","prio":"P2","sec":"s4"},{"id":"fc-p360-bde837","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quel examen permet un diagnostic immédiat au lit ?","back":"L'**échographie pleurale**.","prio":"P2","sec":"s4"},{"id":"fc-p360-94b335","poly":"pneumo","fiche":"p360","front":"PNO complet à la radiographie : quel aspect ?","back":"**Hyperclarté** d'un hémithorax **sans structure vasculaire** + opacité hilaire (poumon rétracté sur le hile).","prio":"P2","sec":"s4"},{"id":"fc-p360-05690a","poly":"pneumo","fiche":"p360","front":"PNO compressif à la radiographie : quel signe ?","back":"**Déviation du médiastin**.","prio":"P2","sec":"s4"},{"id":"fc-p360-e47995","poly":"pneumo","fiche":"p360","front":"PNO avec niveau hydro-aérique : quelles explications ?","back":"Habituel après quelques heures : défaut de réabsorption du liquide pleural physiologique, ou **hémopneumothorax** par rupture de **bride**.","prio":"P3","sec":"s4"},{"id":"fc-p360-6d2a0b","poly":"pneumo","fiche":"p360","front":"Pneumothorax de grande abondance : quelle définition ?","back":"Décollement sur **toute la hauteur de la ligne axillaire**, large d'**au moins 2 cm** mesurés **au hile**.","prio":"P1","sec":"s4"},{"id":"fc-p360-1a53e2","poly":"pneumo","fiche":"p360","front":"PNO grave : quelle définition ?","back":"**Dyspnée sévère** et/ou **collapsus tensionnel**, **quelle que soit la taille** du décollement.","prio":"P1","sec":"s5"},{"id":"fc-p360-197dbb","poly":"pneumo","fiche":"p360","front":"PNO : quels sont les signes de gravité ?","back":"**PAS ≤ 90 mmHg** · **bradycardie** · **désaturation** · déplacement médiastinal (pointe du cœur) **controlatéral**.","prio":"P1","sec":"s5"},{"id":"fc-p360-78bd51","poly":"pneumo","fiche":"p360","front":"PNO : quelles sont les deux situations graves ?","back":"**PNO compressif** et PNO sur **réserve ventilatoire réduite** (insuffisance respiratoire préexistante).","prio":"P1","sec":"s5"},{"id":"fc-p360-d1ceb1","poly":"pneumo","fiche":"p360","front":"PNO compressif : quel mécanisme ?","back":"**Fistule bronchopleurale** en **valve unidirectionnelle** : l'air entre à l'inspiration, ne ressort pas à l'expiration.","prio":"P1","sec":"s5"},{"id":"fc-p360-ff2090","poly":"pneumo","fiche":"p360","front":"PNO compressif : quelles conséquences hémodynamiques ?","back":"Pression pleurale **très positive** → gêne au **retour veineux** (« **tamponnade gazeuse** ») : chute tensionnelle, signes droits dont **turgescence jugulaire**.","prio":"P1","sec":"s5"},{"id":"fc-p360-f02f41","poly":"pneumo","fiche":"p360","front":"PNO compressif : quels signes ECG évoquent la tamponnade gazeuse ?","back":"**Alternance électrique** des QRS · tachycardie · **microvoltage**.","prio":"P2","sec":"s5"},{"id":"fc-p360-b5315d","poly":"pneumo","fiche":"p360","front":"Douleur thoracique : quelles sont les 5 urgences à risque vital ?","back":"**SCA** · **embolie pulmonaire** · **tamponnade** · **dissection aortique** · **PNO compressif**.","prio":"P1","sec":"s5"},{"id":"fc-p360-8fcebe","poly":"pneumo","fiche":"p360","front":"PNO : la douleur thoracique est-elle un signe de gravité ?","back":"**Non** : comptent la **détresse respiratoire** et la **chute tensionnelle**.","prio":"P2","sec":"s5"},{"id":"fc-p360-d273ac","poly":"pneumo","fiche":"p360","front":"PNO grave : quel geste d'évacuation ?","back":"**Drainage thoracique « classique »** (drain chirurgical) ; exsufflation/petit cathéter seulement hors forme grave.","prio":"P1","sec":"s9"},{"id":"fc-p360-6973ca","poly":"pneumo","fiche":"p360","front":"PNO : un petit décollement exclut-il la gravité ?","back":"**Non** : la gravité est **clinique** (dyspnée sévère, collapsus), ex. sur insuffisance respiratoire préexistante.","prio":"P1","sec":"s9"},{"id":"fc-p360-96ae43","poly":"pneumo","fiche":"p360","front":"PNO récidivant : de quel côté le plus souvent ?","back":"Le plus souvent du **même côté**, parfois de l'autre.","prio":"P2","sec":"s6"},{"id":"fc-p360-be4284","poly":"pneumo","fiche":"p360","front":"PNO avec pneumomédiastin : quel signe le caractérise ?","back":"Un **emphysème sous-cutané cervical**.","prio":"P2","sec":"s6"},{"id":"fc-p360-0d6ae7","poly":"pneumo","fiche":"p360","front":"PNO avec pneumomédiastin : quel mécanisme ?","back":"Plèvre en partie **cloisonnée** canalisant l'air vers le hile puis le médiastin, ou brèche pleurale **au hile**.","prio":"P3","sec":"s6"},{"id":"fc-p360-197aeb","poly":"pneumo","fiche":"p360","front":"Patient sous ventilation mécanique : quand penser au PNO ?","back":"**Hausse brutale des pressions d'insufflation** · **collapsus tensionnel brutal** · plaie pleurale possible (tentative de voie sous-clavière).","prio":"P2","sec":"s6"},{"id":"fc-p360-0f19fb","poly":"pneumo","fiche":"p360","front":"PNO : quand le diagnostic différentiel est-il aisé ?","back":"Douleur thoracique « **pleurale** » chez un **sujet sain**.","prio":"P3","sec":"s7"},{"id":"fc-p360-c64490","poly":"pneumo","fiche":"p360","front":"PNO : quelles situations rendent le diagnostic plus difficile ?","back":"**Dyspnée aiguë** sans syndrome pleural typique · **décompensation** d'une maladie respiratoire chronique (BPCO) · **bulles géantes** d'emphysème.","prio":"P2","sec":"s7"},{"id":"fc-p360-8cd042","poly":"pneumo","fiche":"p360","front":"BPCO sévère : quelle image peut être prise à tort pour un PNO ?","back":"Une **bulle géante d'emphysème**.","prio":"P1","sec":"s7"},{"id":"fc-p360-7a537f","poly":"pneumo","fiche":"p360","front":"Bulle géante vs PNO : sur quoi s'aider ?","back":"**Signe du raccordement** sur la radiographie + **tomodensitométrie thoracique**.","prio":"P2","sec":"s7"},{"id":"fc-p360-df3af6","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quand évacuer l'air ?","back":"PNO de **grande abondance** ou **mal toléré**.","prio":"P1","sec":"s8"},{"id":"fc-p360-a850bd","poly":"pneumo","fiche":"p360","front":"Grande abondance : pourquoi le seuil de 2 cm au hile ?","back":"Poumon assez décollé pour introduire un cathéter ou un drain **sans risque de l'embrocher**.","prio":"P2","sec":"s8"},{"id":"fc-p360-446e36","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quelle évolution récente de la prise en charge ?","back":"Approche **moins invasive** : petits drains en drainage libre ou sur valve unidirectionnelle, **ambulatoire** de plus en plus fréquent.","prio":"P3","sec":"s8"},{"id":"fc-p360-ce993c","poly":"pneumo","fiche":"p360","front":"PNO hors forme grave : par quoi remplacer le drainage classique ?","back":"Simple **exsufflation** ou **cathéter de petit calibre**.","prio":"P1","sec":"s8"},{"id":"fc-p360-7c3bf3","poly":"pneumo","fiche":"p360","front":"Exsufflation/drainage par voie antérieure : quels repères ?","back":"Juste **en dehors de la ligne médioclaviculaire**, **2e ou 3e espace intercostal** ; demi-assis ou décubitus dorsal.","prio":"P1","sec":"s8"},{"id":"fc-p360-91bba5","poly":"pneumo","fiche":"p360","front":"Voie axillaire (« triangle de sécurité ») : quels repères ?","back":"**4e ou 5e EIC** sur la **ligne axillaire moyenne** ; chez l'homme, l'horizontale du mamelon repère le 5e ou 6e espace.","prio":"P2","sec":"s8"},{"id":"fc-p360-c267e7","poly":"pneumo","fiche":"p360","front":"PNO : dans quel ordre se poser les 3 questions du choix thérapeutique ?","back":"**Tolérance** (dyspnée, SpO₂) → **taille** (grande abondance ?) → **terrain** (PSP, PSS, traumatique).","prio":"P2","sec":"s8"},{"id":"fc-p360-b92599","poly":"pneumo","fiche":"p360","front":"PSP mal toléré ou de grande abondance (non grave) : quel traitement ?","back":"**Exsufflation manuelle** ou **drain de petit calibre**.","prio":"P2","sec":"s8"},{"id":"fc-p360-c8d287","poly":"pneumo","fiche":"p360","front":"PSS mal toléré ou de grande abondance : quel traitement selon l'arbre du Collège ?","back":"**Drain de petit calibre** (l'exsufflation n'y figure que pour le PSP).","prio":"P2","sec":"s8"},{"id":"fc-p360-dd6886","poly":"pneumo","fiche":"p360","front":"PNO traumatique mal toléré ou de grande abondance : quel traitement ?","back":"**Drain**.","prio":"P2","sec":"s8"},{"id":"fc-p360-8245d8","poly":"pneumo","fiche":"p360","front":"Exsufflation : quels avantages ?","back":"Proposée comme **unique traitement** des PNO spontanés : bien tolérée, hospitalisation courte, faisable en **ambulatoire**.","prio":"P2","sec":"s10"},{"id":"fc-p360-ff7d47","poly":"pneumo","fiche":"p360","front":"Exsufflation : quelle technique ?","back":"**Petit cathéter** par voie antérieure (2e-3e EIC) ; aspiration manuelle à la **seringue de 50 ml**.","prio":"P1","sec":"s10"},{"id":"fc-p360-30281f","poly":"pneumo","fiche":"p360","front":"Exsufflation : quand retirer le cathéter et comment juger le résultat ?","back":"Retiré **dès la fin** du geste ; résultat jugé sur la **radiographie de contrôle**.","prio":"P2","sec":"s10"},{"id":"fc-p360-899b28","poly":"pneumo","fiche":"p360","front":"Exsufflation : quel taux de succès ?","back":"Environ **50 %**, **quelle que soit la taille** du PNO.","prio":"P1","sec":"s10"},{"id":"fc-p360-c1807a","poly":"pneumo","fiche":"p360","front":"Échec de l'exsufflation : que faire ?","back":"Pose d'un **drain de petit calibre** en 2e intention.","prio":"P1","sec":"s10"},{"id":"fc-p360-22dda3","poly":"pneumo","fiche":"p360","front":"Drain pleural : quel calibre privilégier et pourquoi ?","back":"**Petit calibre (≤ 14 Fr)** : aussi efficace que les gros, **moins douloureux**.","prio":"P2","sec":"s11"},{"id":"fc-p360-0437ff","poly":"pneumo","fiche":"p360","front":"Drain pleural : comment l'air s'évacue-t-il initialement ?","back":"**Passivement** : valve **anti-retour** ou écoulement libre vers un bocal muni d'un dispositif anti-retour.","prio":"P2","sec":"s11"},{"id":"fc-p360-1ca5f5","poly":"pneumo","fiche":"p360","front":"Drain : que faire si le poumon ne se réexpand pas ?","back":"**Aspiration douce** dans un 2e temps, de **-5 à -20 cm H₂O** (pas d'emblée).","prio":"P2","sec":"s11"},{"id":"fc-p360-9ff097","poly":"pneumo","fiche":"p360","front":"Drain pleural : quand le retirer ?","back":"Après **réexpansion complète** du poumon, **sans fuite persistante**.","prio":"P2","sec":"s11"},{"id":"fc-p360-6bee25","poly":"pneumo","fiche":"p360","front":"PNO persistant malgré le drainage : quand discuter une pleurodèse ?","back":"PNO qui persiste après **3 à 5 jours** de drainage malgré l'**aspiration douce**.","prio":"P2","sec":"s11"},{"id":"fc-p360-3d2f3f","poly":"pneumo","fiche":"p360","front":"PSP de faible abondance bien toléré : quelle prise en charge ?","back":"**Surveillance**.","prio":"P2","sec":"s12"},{"id":"fc-p360-8db94f","poly":"pneumo","fiche":"p360","front":"PSS de faible abondance bien toléré : quelle prise en charge ?","back":"**Drain** (petit calibre), **sauf** décollement tout petit.","prio":"P2","sec":"s12"},{"id":"fc-p360-fbbbce","poly":"pneumo","fiche":"p360","front":"PNO traumatique de faible abondance bien toléré : quelle prise en charge ?","back":"**Surveillance**, ou **drain** si patient sous **ventilation assistée**.","prio":"P2","sec":"s12"},{"id":"fc-p360-07e522","poly":"pneumo","fiche":"p360","front":"Récidive après un 1er PSP : quel risque ?","back":"Un peu **moins de 30 %**.","prio":"P2","sec":"s13"},{"id":"fc-p360-2d5043","poly":"pneumo","fiche":"p360","front":"Récidive après un 1er PSS : quel risque ?","back":"**Plus de 50 %**.","prio":"P2","sec":"s13"},{"id":"fc-p360-f170ac","poly":"pneumo","fiche":"p360","front":"Item 230 : quel taux de récidive du PNO et quelle conséquence diagnostique ?","back":"Récidive dans **près d'1/3** des cas → un **antécédent de PNO** est un argument fort pour le diagnostic.","prio":"P1","sec":"s13"},{"id":"fc-p360-934900","poly":"pneumo","fiche":"p360","front":"Pneumothorax : quels sont les deux moyens de prévention des récidives ?","back":"**Arrêt du tabac** + **pleurodèse**.","prio":"P2","sec":"s13"},{"id":"fc-p360-f96833","poly":"pneumo","fiche":"p360","front":"Pleurodèse : quelles indications ?","back":"**Récidive** de PNO, ou PNO **persistant après 3-5 jours** de drainage malgré aspiration douce.","prio":"P2","sec":"s13"},{"id":"fc-p360-5059c7","poly":"pneumo","fiche":"p360","front":"Pleurodèse : en quoi consiste-t-elle ?","back":"**Symphyse** des feuillets viscéral et pariétal, sous **thoracoscopie** : abrasion mécanique ou instillation d'un irritant (ex. **talc**).","prio":"P2","sec":"s13"},{"id":"fc-p360-1b7032","poly":"pneumo","fiche":"p360","front":"Après un PNO : faut-il limiter l'activité physique ?","back":"**Non**, aucune preuve ne le justifie.","prio":"P2","sec":"s13"},{"id":"fc-p360-3aa37b","poly":"pneumo","fiche":"p360","front":"Avion : quel effet de l'altitude sur un PNO existant ?","back":"L'**hypobarie** augmente sa taille (~**20 %** entre 3 000 et 5 000 pieds, **30 %** à 8 000 pieds en cabine).","prio":"P3","sec":"s13"},{"id":"fc-p360-7eae69","poly":"pneumo","fiche":"p360","front":"Après un PNO : quel délai avant un vol pressurisé ?","back":"Délai théorique de **2 semaines**, sans preuve formelle.","prio":"P2","sec":"s13"},{"id":"fc-p360-f896d3","poly":"pneumo","fiche":"p360","front":"Après un PNO spontané : quelle règle pour la plongée ?","back":"Plongée **en bouteille définitivement contre-indiquée**, **même opéré** ; masque et tuba autorisés.","prio":"P2","sec":"s13"},{"id":"fc-p360-5cdec8","poly":"pneumo","fiche":"p360","front":"Tabac après un PNO spontané : quelle conduite ?","back":"**Sevrage recommandé à chaque fois** : facteur de risque de PNO spontané et de **récidive**.","prio":"P2","sec":"s13"},{"id":"fc-p360-6dc9e2","poly":"pneumo","fiche":"p360","front":"Tout PNO : que surveiller ?","back":"Les **signes de gravité** : dyspnée sévère, PAS ≤ 90 mmHg, bradycardie, désaturation, déplacement médiastinal controlatéral.","prio":"P1","sec":"s14"},{"id":"fc-p75-e6375c","poly":"pneumo","fiche":"p75","front":"Tabac : comment qualifier tout usage du tabac ?","back":"Un **mésusage** (conduite de consommation avec risque et/ou dommage et/ou dépendance).","prio":"P2","sec":"s1"},{"id":"fc-p75-057a9e","poly":"pneumo","fiche":"p75","front":"Tabac : quel est le principal agent responsable de la dépendance ?","back":"La **nicotine**.","prio":"P1","sec":"s1"},{"id":"fc-p75-1c5610","poly":"pneumo","fiche":"p75","front":"Dépendance à une substance (CIM-10) : combien de manifestations faut-il, et sur quelle période ?","back":"**Au moins 3** manifestations, présentes ensemble au cours de la **dernière année**.","prio":"P1","sec":"s1"},{"id":"fc-p75-fdeb80","poly":"pneumo","fiche":"p75","front":"CIM-10 : citer les 6 manifestations de la dépendance à une substance ?","back":"**Envie** compulsive ; **perte de contrôle** ; **sevrage** ; **tolérance** ; abandon des autres intérêts ; poursuite **malgré les dommages**.","prio":"P2","sec":"s1"},{"id":"fc-p75-28dc77","poly":"pneumo","fiche":"p75","front":"Dépendance : comment définir la tolérance ?","back":"Il faut **plus de produit** pour obtenir le **même effet**.","prio":"P2","sec":"s1"},{"id":"fc-p75-0f5f6e","poly":"pneumo","fiche":"p75","front":"Tabac : quels sont les 3 types de dépendance ?","back":"**Physique** (pharmacologique) ; **psychologique** ; **comportementale** (sociale).","prio":"P1","sec":"s1"},{"id":"fc-p75-e51176","poly":"pneumo","fiche":"p75","front":"Dépendance physique au tabac : par quel mécanisme la nicotine agit-elle sur le cerveau ?","back":"Arrivée très rapide (« effet shoot »), fixation sur les **récepteurs cholinergiques nicotiniques**, stimulation des systèmes de récompense (surtout **dopamine**).","prio":"P2","sec":"s1"},{"id":"fc-p75-f7da62","poly":"pneumo","fiche":"p75","front":"Dépendance physique au tabac : quel outil permet de l'évaluer ?","back":"Le **test de Fagerström**.","prio":"P2","sec":"s1"},{"id":"fc-p75-328d58","poly":"pneumo","fiche":"p75","front":"Dépendance psychologique au tabac : d'où vient-elle et exemples ?","back":"Des « **effets positifs** » prêtés à la cigarette : se **relaxer**, **réfléchir**, effet **coupe-faim**.","prio":"P2","sec":"s1"},{"id":"fc-p75-f75d9b","poly":"pneumo","fiche":"p75","front":"Dépendance comportementale au tabac : d'où vient-elle et exemples ?","back":"De **situations répétées** associées à la cigarette déclenchant une envie réflexe : convivialité, **café**, **alcool**, **cannabis**.","prio":"P2","sec":"s1"},{"id":"fc-p75-6d9f03","poly":"pneumo","fiche":"p75","front":"Arrêt du tabac : pourquoi repérer les 3 types de dépendance ?","back":"Cela **facilite l'arrêt**.","prio":"P2","sec":"s1"},{"id":"fc-p75-04a1ce","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : de quoi est-elle physiquement constituée ?","back":"Un **aérosol** : gaz + particules.","prio":"P3","sec":"s2"},{"id":"fc-p75-512d62","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : quel est le diamètre médian des particules et jusqu'où vont-elles ?","back":"**0,3 micron** ; jusqu'aux **alvéoles**, puis passage dans la circulation avec **inflammation**.","prio":"P3","sec":"s2"},{"id":"fc-p75-8ebb9a","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : à quelle température se forme-t-elle ?","back":"Jusqu'à **1 000 à 1 500 °C**.","prio":"P3","sec":"s2"},{"id":"fc-p75-5ed5b7","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : combien de substances contient-elle, dont combien de cancérigènes ?","back":"Plus de **4 000 à 7 000** substances (contre 2 500 dans le tabac non brûlé), dont **au moins 70 cancérigènes**.","prio":"P3","sec":"s2"},{"id":"fc-p75-460a73","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : de quoi dépend sa composition ?","back":"Type de tabac, **séchage**, traitements et **additifs**.","prio":"P3","sec":"s2"},{"id":"fc-p75-0627e4","poly":"pneumo","fiche":"p75","front":"Nicotine : est-elle cancérigène ?","back":"**Non**, pas en tant que telle ; c'est le principal agent de la **dépendance**.","prio":"P2","sec":"s2"},{"id":"fc-p75-906f6f","poly":"pneumo","fiche":"p75","front":"Nicotine : qu'est-ce qui explique vraisemblablement le fort pouvoir addictif de la cigarette ?","back":"Le **pic plasmatique rapide** de nicotine quand on fume.","prio":"P2","sec":"s2"},{"id":"fc-p75-4de1ab","poly":"pneumo","fiche":"p75","front":"Nicotine : à partir de quand une dépendance peut-elle s'installer ?","back":"Dès les **premières semaines**, et même pour une **faible consommation**.","prio":"P3","sec":"s2"},{"id":"fc-p75-e57575","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : quelle est la principale substance responsable des cancers ?","back":"Les **goudrons** (ils modifient les cellules épithéliales bronchiques).","prio":"P2","sec":"s2"},{"id":"fc-p75-123aae","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : quel est le rôle des radicaux libres ?","back":"Dégradation de la **paroi alvéolaire** et inhibition des enzymes qui la protègent.","prio":"P3","sec":"s2"},{"id":"fc-p75-bbe001","poly":"pneumo","fiche":"p75","front":"Monoxyde de carbone du tabac : par quel mécanisme est-il toxique ?","back":"Fixation sur l'**hémoglobine** → **hypoxie** → **lésions endothéliales** → complications cardiovasculaires.","prio":"P2","sec":"s2"},{"id":"fc-p75-c89cd7","poly":"pneumo","fiche":"p75","front":"CO dans l'air expiré : que reflète sa mesure ?","back":"Le tabagisme des **dernières heures** (utilisable en tabacologie).","prio":"P2","sec":"s2"},{"id":"fc-p75-030cf2","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : quels métaux lourds contient-elle ?","back":"**Cadmium**, **plomb**, **chrome**, **mercure**.","prio":"P3","sec":"s2"},{"id":"fc-p75-569a9d","poly":"pneumo","fiche":"p75","front":"Fumée de tabac : comment favorise-t-elle les thromboses artérielles ?","back":"**Dysfonction endothéliale** + **agrégation plaquettaire** favorisée.","prio":"P2","sec":"s2"},{"id":"fc-p75-940051","poly":"pneumo","fiche":"p75","front":"Statut tabagique : comment définir un non-fumeur ?","back":"Moins de **100 cigarettes** fumées dans toute sa vie.","prio":"P1","sec":"s3"},{"id":"fc-p75-156ca7","poly":"pneumo","fiche":"p75","front":"Statut tabagique : comment définir un ex-fumeur ?","back":"Arrêt **total et définitif** depuis plusieurs mois ; délai le plus admis : **12 mois**.","prio":"P1","sec":"s3"},{"id":"fc-p75-638727","poly":"pneumo","fiche":"p75","front":"Statut tabagique : comment définir un fumeur actif ?","back":"Un fumeur qui n'est **pas sevré depuis 12 mois**.","prio":"P2","sec":"s3"},{"id":"fc-p75-05709e","poly":"pneumo","fiche":"p75","front":"Nicotine inhalée après combustion à haute température : citer des produits ?","back":"Cigarettes **manufacturées ou roulées**, cigarillos, cigare, **pipe**, **chicha**.","prio":"P2","sec":"s3"},{"id":"fc-p75-b3b361","poly":"pneumo","fiche":"p75","front":"Tabac chauffé : quel type de combustion et quelle attitude ?","back":"Combustion **incomplète** ; à considérer **comme des cigarettes**, ne peut **pas être conseillé**.","prio":"P1","sec":"s3"},{"id":"fc-p75-681d37","poly":"pneumo","fiche":"p75","front":"Nicotine inhalée sans combustion : citer des produits ?","back":"**Cigarette électronique** (dont les **puffs** jetables) ; substituts nicotiniques inhalés ; **snuff** (sniffé).","prio":"P2","sec":"s3"},{"id":"fc-p75-f1bfbc","poly":"pneumo","fiche":"p75","front":"Snus : de quoi s'agit-il ?","back":"Tabac **humide en sachet** placé entre la **gencive et la lèvre supérieure** (voie ingérée).","prio":"P2","sec":"s3"},{"id":"fc-p75-b9a836","poly":"pneumo","fiche":"p75","front":"Snus : quel est son statut de vente en Europe ?","back":"**Interdit** à la vente en Europe, **sauf en Suède**.","prio":"P2","sec":"s3"},{"id":"fc-p75-962237","poly":"pneumo","fiche":"p75","front":"Nicotine ingérée : quels produits ?","back":"Le **snus** et le **tabac à chiquer**.","prio":"P3","sec":"s3"},{"id":"fc-p75-2b8729","poly":"pneumo","fiche":"p75","front":"Puffs : de quoi s'agit-il ?","back":"Des **cigarettes électroniques jetables**.","prio":"P3","sec":"s3"},{"id":"fc-p75-ba4ed3","poly":"pneumo","fiche":"p75","front":"Cigarette électronique : de quoi est-elle constituée ?","back":"**Batterie** + **cartouche de liquide** + **résistance** ; le liquide chauffé est inhalé sous forme de **vapeur**.","prio":"P2","sec":"s3"},{"id":"fc-p75-6acd4c","poly":"pneumo","fiche":"p75","front":"Cigarette électronique : produit-elle du CO ou des goudrons ?","back":"**Non** : pas de combustion, donc **ni CO ni goudrons**.","prio":"P2","sec":"s3"},{"id":"fc-p75-27d04b","poly":"pneumo","fiche":"p75","front":"Liquide de cigarette électronique : que contient-il ?","back":"**Arômes**, **propylène glycol**, **glycérine végétale**, additifs ; nicotine haute, moyenne, basse ou absente.","prio":"P3","sec":"s3"},{"id":"fc-p75-614ee1","poly":"pneumo","fiche":"p75","front":"Tabac : quel est son rang parmi les causes de mortalité évitable ?","back":"**1re cause de mortalité évitable**, en France et dans le monde.","prio":"P1","sec":"s4"},{"id":"fc-p75-fbccaa","poly":"pneumo","fiche":"p75","front":"Tabac : quelle proportion de fumeurs mourra prématurément d'une maladie due au tabac ?","back":"**Un fumeur sur deux**.","prio":"P1","sec":"s4"},{"id":"fc-p75-4ab2da","poly":"pneumo","fiche":"p75","front":"Tabac dans le monde : combien de fumeurs et où vivent-ils surtout ?","back":"**1,3 milliard** ; plus de **80 %** dans des pays à revenu faible ou intermédiaire.","prio":"P2","sec":"s4"},{"id":"fc-p75-3f07c2","poly":"pneumo","fiche":"p75","front":"Monde 2020 : quelle part de la population consommait du tabac ?","back":"**22,3 %** (36,7 % des hommes, 7,8 % des femmes).","prio":"P3","sec":"s4"},{"id":"fc-p75-573391","poly":"pneumo","fiche":"p75","front":"Tabac (OMS) : combien de morts par an dans le monde ?","back":"Plus de **8 millions**, dont **1,2 million** liés au tabagisme passif.","prio":"P1","sec":"s4"},{"id":"fc-p75-ecd8bd","poly":"pneumo","fiche":"p75","front":"France 2021 : combien de fumeurs de 18 à 75 ans ?","back":"**15 millions** (34,7 % des hommes, 29,2 % des femmes).","prio":"P1","sec":"s4"},{"id":"fc-p75-0d4ba0","poly":"pneumo","fiche":"p75","front":"France 2021 : combien de fumeurs quotidiens ?","back":"**12 millions** (27,8 % des hommes, 23 % des femmes) ; environ 1 adulte sur 4.","prio":"P2","sec":"s4"},{"id":"fc-p75-0fe31b","poly":"pneumo","fiche":"p75","front":"France 2021 : quelle proportion d'adultes fume ?","back":"Près d'**un sur trois** (un sur quatre chaque jour).","prio":"P2","sec":"s4"},{"id":"fc-p75-01fd79","poly":"pneumo","fiche":"p75","front":"France (2015) : combien de décès par an sont imputables au tabac ?","back":"Environ **75 000** (sur 580 000 décès en métropole).","prio":"P1","sec":"s4"},{"id":"fc-p75-493ee6","poly":"pneumo","fiche":"p75","front":"France (2015) : décès dus au tabac chez l'homme et chez la femme ?","back":"Hommes ≈ **55 000** (19 % des décès) ; femmes ≈ **20 000** (7 %).","prio":"P2","sec":"s4"},{"id":"fc-p75-b1bc5b","poly":"pneumo","fiche":"p75","front":"France (2015) : combien de décès par cancer sont dus au tabac ?","back":"**46 000** (poumon 32 000, autres cancers 14 000).","prio":"P2","sec":"s4"},{"id":"fc-p75-084896","poly":"pneumo","fiche":"p75","front":"France (2015) : décès dus au tabac par maladie cardiovasculaire et respiratoire ?","back":"Cardiovasculaire **17 000** ; respiratoire **12 000**.","prio":"P2","sec":"s4"},{"id":"fc-p75-f8444a","poly":"pneumo","fiche":"p75","front":"Tabagisme en France : quelle tendance depuis 2017 ?","back":"Forte **baisse** à partir de 2017, puis nouvelle **hausse depuis 2020** (peut-être liée au SARS-CoV-2).","prio":"P3","sec":"s4"},{"id":"fc-p75-101889","poly":"pneumo","fiche":"p75","front":"Tabagisme en France : quels facteurs ont accompagné la baisse de 2017 ?","back":"Hausse des **prix**, **paquet neutre**, opération **Moi(s) sans tabac**.","prio":"P3","sec":"s4"},{"id":"fc-p75-035be3","poly":"pneumo","fiche":"p75","front":"Hausse du tabagisme depuis 2020 : quelles populations sont surtout touchées ?","back":"Les **femmes** (20,7 % → 23 %) et les personnes **sans diplôme ou < bac** (29 % → 32 %).","prio":"P3","sec":"s4"},{"id":"fc-p75-e8e015","poly":"pneumo","fiche":"p75","front":"Tabagisme en France : à quels facteurs sociaux la prévalence est-elle liée ?","back":"**Diplôme** (35,8 % sans diplôme vs 17,3 % au-delà du bac), **revenu**, situation professionnelle.","prio":"P3","sec":"s4"},{"id":"fc-p75-a045b1","poly":"pneumo","fiche":"p75","front":"Élèves de 3e : évolution de l'expérimentation du tabac 2010-2021 ?","back":"**51,8 %** → **29,1 %**.","prio":"P3","sec":"s4"},{"id":"fc-p75-ac71b4","poly":"pneumo","fiche":"p75","front":"Élèves de 3e : évolution de l'usage quotidien du tabac 2010-2021 ?","back":"**15,6 %** → **3,7 %**.","prio":"P3","sec":"s4"},{"id":"fc-p75-5a2f24","poly":"pneumo","fiche":"p75","front":"Jeunes de 17 ans : usage quotidien du tabac 2014-2017 ?","back":"**32,4 %** → **25,1 %**, légère prédominance masculine.","prio":"P3","sec":"s4"},{"id":"fc-p75-096aed","poly":"pneumo","fiche":"p75","front":"Jeunes de 17 ans : évolution de l'expérimentation du tabac 2014-2017 ?","back":"**43,8 %** → **34,1 %**.","prio":"P3","sec":"s4"},{"id":"fc-p75-f4c4a9","poly":"pneumo","fiche":"p75","front":"Tabac (2017) : âge moyen d'expérimentation et d'usage quotidien ?","back":"Expérimentation **14,4 ans** ; usage quotidien **15,1 ans**.","prio":"P3","sec":"s4"},{"id":"fc-p75-eaf81f","poly":"pneumo","fiche":"p75","front":"Élèves de 3e (2021) : expérimentation et usage quotidien de la cigarette électronique ?","back":"**34,2 %** l'ont expérimentée ; usage quotidien **2,8 %**.","prio":"P3","sec":"s4"},{"id":"fc-p75-48bceb","poly":"pneumo","fiche":"p75","front":"Adultes 18-75 ans (2021) : expérimentation et usage quotidien de la cigarette électronique ?","back":"**38,7 %** l'ont essayée ; usage quotidien **5 %**.","prio":"P3","sec":"s4"},{"id":"fc-p75-390f90","poly":"pneumo","fiche":"p75","front":"Chicha chez les élèves de 3e : quelle tendance ?","back":"En **net recul** (expérimentation 26,2 % → 20 % de 2018 à 2021), plus fréquente chez les **garçons**.","prio":"P3","sec":"s4"},{"id":"fc-p75-7e7936","poly":"pneumo","fiche":"p75","front":"Femmes enceintes (2017) : quelle proportion fumait à l'annonce de la grossesse ?","back":"**27,9 %**.","prio":"P2","sec":"s4"},{"id":"fc-p75-7748f8","poly":"pneumo","fiche":"p75","front":"Fumeuses enceintes : que deviennent-elles pendant la grossesse ?","back":"**30 %** arrêtent dès l'annonce, **20 %** en cours de grossesse, **44 %** réduisent, **6 %** ne réduisent pas.","prio":"P2","sec":"s4"},{"id":"fc-p75-d090a5","poly":"pneumo","fiche":"p75","front":"Grossesse : quelles femmes sont les plus exposées au tabagisme ?","back":"Les **plus âgées** (35 ans ou plus) ; et celles dont le diplôme est ≥ bac.","prio":"P2","sec":"s4"},{"id":"fc-p75-f0aa9d","poly":"pneumo","fiche":"p75","front":"Tabac et cancers : quelle part des cancers est due au tabac ?","back":"**Un cancer sur quatre**.","prio":"P1","sec":"s5"},{"id":"fc-p75-cb9a34","poly":"pneumo","fiche":"p75","front":"Cancer du poumon : quelle part est liée au tabac ?","back":"**80 %**.","prio":"P1","sec":"s5"},{"id":"fc-p75-4efc46","poly":"pneumo","fiche":"p75","front":"Cancer du poumon : de combien le tabac multiplie-t-il le risque ?","back":"Risque **10 à 15 fois** plus élevé chez le fumeur.","prio":"P1","sec":"s5"},{"id":"fc-p75-eb91c0","poly":"pneumo","fiche":"p75","front":"Cancer du poumon et tabac : existe-t-il un seuil sans risque ?","back":"**Non**, aucun seuil ; le risque dépend du nombre de cigarettes/j et **surtout de la durée**.","prio":"P1","sec":"s5"},{"id":"fc-p75-50b4a9","poly":"pneumo","fiche":"p75","front":"Tabac : citer des cancers autres que le poumon ?","back":"**VADS** (ORL, œsophage), **vessie**, reins, uretères, estomac, côlon-rectum, foie, **pancréas**, col utérin, ovaire, leucémie myéloïde.","prio":"P2","sec":"s5"},{"id":"fc-p75-f51445","poly":"pneumo","fiche":"p75","front":"Tabac : de combien multiplie-t-il le risque de maladie cardiovasculaire ?","back":"Par **20**.","prio":"P1","sec":"s5"},{"id":"fc-p75-49cd9b","poly":"pneumo","fiche":"p75","front":"Tabac : quelles maladies cardiovasculaires favorise-t-il ?","back":"**Cardiopathies ischémiques**/coronaropathies, **artériopathie**, HTA, **AVC**, **anévrysmes de l'aorte**.","prio":"P2","sec":"s5"},{"id":"fc-p75-68eda3","poly":"pneumo","fiche":"p75","front":"BPCO en France : combien de malades et quelle part l'ignore ?","back":"**3,5 millions**, dont **2/3** l'ignorent.","prio":"P2","sec":"s5"},{"id":"fc-p75-cf1879","poly":"pneumo","fiche":"p75","front":"BPCO : quelle évolution sans sevrage tabagique ?","back":"Possible évolution vers l'**insuffisance respiratoire**.","prio":"P2","sec":"s5"},{"id":"fc-p75-ecf783","poly":"pneumo","fiche":"p75","front":"BPCO : de combien le risque de cancer du poumon est-il multiplié ?","back":"Par **3**.","prio":"P2","sec":"s5"},{"id":"fc-p75-763a2b","poly":"pneumo","fiche":"p75","front":"Asthme : quel effet a le tabac (actif et passif) ?","back":"Favorise les **exacerbations** et le **mauvais contrôle**.","prio":"P2","sec":"s5"},{"id":"fc-p75-02131a","poly":"pneumo","fiche":"p75","front":"Tabagisme passif : de combien augmente le risque relatif de cancer du poumon ?","back":"**+26 %**.","prio":"P1","sec":"s5"},{"id":"fc-p75-de0faf","poly":"pneumo","fiche":"p75","front":"Tabagisme passif : de combien augmente le risque relatif de décès cardiovasculaire ?","back":"**+20 à 30 %**.","prio":"P1","sec":"s5"},{"id":"fc-p75-5af659","poly":"pneumo","fiche":"p75","front":"Tabagisme passif chez l'enfant et le nourrisson : quelles conséquences ?","back":"Plus d'**infections ORL et pulmonaires** ; risque accru de **mort subite du nourrisson**.","prio":"P1","sec":"s5"},{"id":"fc-p75-facb03","poly":"pneumo","fiche":"p75","front":"Tabagisme in utero : quelles complications de la grossesse ?","back":"Plus de **fausses couches**, de **RCIU**, de **GEU** et d'**accouchements prématurés**.","prio":"P1","sec":"s5"},{"id":"fc-p75-5fd15f","poly":"pneumo","fiche":"p75","front":"Tabac : quelles atteintes bucco-dentaires ?","back":"**Coloration des dents**, **parodontopathies**, déchaussement dentaire.","prio":"P3","sec":"s5"},{"id":"fc-p75-0ad65b","poly":"pneumo","fiche":"p75","front":"Tabac : quelles atteintes cutanées ?","back":"**Acné** plus sévère, **vieillissement cutané** accéléré, sécheresse cutanée, coloration des ongles.","prio":"P3","sec":"s5"},{"id":"fc-p75-d58009","poly":"pneumo","fiche":"p75","front":"Tabac : quelles atteintes de la sexualité et de la fécondité ?","back":"**Fécondité diminuée** ; risque cardiovasculaire accru avec certaines **contraceptions orales** ; **troubles érectiles**.","prio":"P2","sec":"s5"},{"id":"fc-p75-381835","poly":"pneumo","fiche":"p75","front":"Tabac : quelles anomalies sanguines ?","back":"**Polyglobulie** ; **polynucléose neutrophile**.","prio":"P2","sec":"s5"},{"id":"fc-p75-3dac36","poly":"pneumo","fiche":"p75","front":"Tabac et psychiatrie : quelle part des schizophrènes et des troubles de l'humeur fument ?","back":"**82 %** des schizophrènes ; **56 %** des patients avec trouble de l'humeur.","prio":"P3","sec":"s5"},{"id":"fc-p75-a16919","poly":"pneumo","fiche":"p75","front":"Tabac : quel trouble anxieux pourrait-il favoriser ?","back":"Le **trouble panique** (effet stimulant).","prio":"P3","sec":"s5"},{"id":"fc-p75-6f6ce4","poly":"pneumo","fiche":"p75","front":"Manifestations anxio-dépressives du sevrage : durée et prise en charge habituelle ?","back":"**Quelques semaines** ; un **soutien** au cours du suivi suffit habituellement, sauf si elles persistent.","prio":"P3","sec":"s5"},{"id":"fc-p75-9c76d5","poly":"pneumo","fiche":"p75","front":"Repérage du tabagisme : quand le faire et par qui ?","back":"À **chaque contact avec un soignant**, **systématiquement**, par **tous** les professionnels de santé.","prio":"P1","sec":"s6"},{"id":"fc-p75-c4d51b","poly":"pneumo","fiche":"p75","front":"Repérage précoce du tabagisme : quelle 1re question poser ?","back":"« **Fumez-vous du tabac ?** »","prio":"P1","sec":"s6"},{"id":"fc-p75-e83802","poly":"pneumo","fiche":"p75","front":"Repérage : que faire si le patient fume ?","back":"Évaluer le risque et **conseiller l'arrêt** (brochure/site, a-t-il pensé à arrêter, proposer d'en reparler).","prio":"P1","sec":"s6"},{"id":"fc-p75-43ecb0","poly":"pneumo","fiche":"p75","front":"Repérage : que demander à un patient qui ne fume pas ?","back":"S'il a **déjà fumé** ; si oui, **combien de temps** et **depuis quand** il a arrêté.","prio":"P2","sec":"s6"},{"id":"fc-p75-835204","poly":"pneumo","fiche":"p75","front":"Conseil minimal d'arrêt du tabac : est-il utile ?","back":"**Oui** : il augmente le **taux de sevrage**.","prio":"P1","sec":"s6"},{"id":"fc-p75-a3c43b","poly":"pneumo","fiche":"p75","front":"Intervention brève (HAS 2021) : citer des éléments de son contenu ?","back":"Restituer les questionnaires, informer des risques, discuter l'**intérêt de l'arrêt** ou de la réduction, expliquer les méthodes, évaluer **motivation et confiance**.","prio":"P2","sec":"s6"},{"id":"fc-p75-ce3a30","poly":"pneumo","fiche":"p75","front":"Intervention brève (HAS 2021) : comment fixer les objectifs ?","back":"Les **proposer en laissant le choix** au patient.","prio":"P2","sec":"s6"},{"id":"fc-p75-a0461d","poly":"pneumo","fiche":"p75","front":"Que signifie RPIB ?","back":"**Repérage précoce + intervention brève** (même démarche que pour l'alcool ou le cannabis).","prio":"P1","sec":"s6"},{"id":"fc-p75-2518d9","poly":"pneumo","fiche":"p75","front":"Méthode des 5A : citer les 5 étapes ?","back":"**Ask** (interroger), **Assess** (évaluer la motivation), **Advise** (conseiller), **Assist** (aider), **Arrange** (organiser le suivi).","prio":"P3","sec":"s6"},{"id":"fc-p75-b5c53e","poly":"pneumo","fiche":"p75","front":"Arrêt du tabac : faut-il attendre que le fumeur soit motivé ?","back":"**Non** : l'arrêt s'organise **quelle que soit la motivation** (conseil + aides disponibles).","prio":"P1","sec":"s6"},{"id":"fc-p75-dd0100","poly":"pneumo","fiche":"p75","front":"Tabac Info Service : quels moyens d'accès ?","back":"Site **tabac-info-service.fr** et ligne gratuite **3989** (accompagnement personnalisé, coaching possible).","prio":"P1","sec":"s6"},{"id":"fc-p75-d5d678","poly":"pneumo","fiche":"p75","front":"Repérage et conseil minimal : quelle ordonnance et quelle suite ?","back":"**Aucune ordonnance** ; proposer de **réévaluer la motivation** à une autre consultation.","prio":"P3","sec":"s6"},{"id":"fc-p75-3d7316","poly":"pneumo","fiche":"p75","front":"Évaluation du tabagisme : que préciser sur la consommation ?","back":"Le **mode** (cigarette, roulé, chicha…), la **quantité** moyenne, l'**âge de début**, la **durée** en années.","prio":"P2","sec":"s7"},{"id":"fc-p75-1bc6d3","poly":"pneumo","fiche":"p75","front":"Cigarette manufacturée : quelle quantité de tabac ?","back":"Environ **1 gramme**.","prio":"P3","sec":"s7"},{"id":"fc-p75-d72c57","poly":"pneumo","fiche":"p75","front":"Équivalence en cigarettes manufacturées : roulée et cigarillo ?","back":"1 roulée = **2** ; 1 cigarillo = **4**.","prio":"P2","sec":"s7"},{"id":"fc-p75-eb5a81","poly":"pneumo","fiche":"p75","front":"Équivalence en cigarettes manufacturées : joint de cannabis et chicha ?","back":"1 joint = **4** ; 1 chicha = **40**.","prio":"P2","sec":"s7"},{"id":"fc-p75-cb146e","poly":"pneumo","fiche":"p75","front":"Paquets-années : comment les calculer ?","back":"Nombre de **paquets de 20** fumés par jour × **nombre d'années** à cette consommation.","prio":"P1","sec":"s7"},{"id":"fc-p75-295bca","poly":"pneumo","fiche":"p75","front":"Paquet-année : pourquoi est-ce un mauvais évaluateur du risque de cancer ?","back":"Quantité en **puissance 2** mais **durée en puissance 4** : 10 cig/j × 20 ans ≠ 20 cig/j × 10 ans (10 PA chacun).","prio":"P2","sec":"s7"},{"id":"fc-p75-20911a","poly":"pneumo","fiche":"p75","front":"Consommation récente de tabac (< 24 h) : quel examen non déclaratif ?","back":"La **mesure du CO dans l'air expiré**.","prio":"P2","sec":"s7"},{"id":"fc-p75-ff7f21","poly":"pneumo","fiche":"p75","front":"Test de Fagerström complet : combien de questions et quelle qualité ?","back":"**6 questions** ; qualités psychométriques **mauvaises**.","prio":"P2","sec":"s7"},{"id":"fc-p75-32b4a8","poly":"pneumo","fiche":"p75","front":"Fagerström simplifié : quelles sont les 2 questions ?","back":"**Cigarettes par jour** ; **délai réveil → 1re cigarette**.","prio":"P1","sec":"s7"},{"id":"fc-p75-55db75","poly":"pneumo","fiche":"p75","front":"Fagerström : combien de points pour une 1re cigarette dans les 5 minutes après le réveil ?","back":"**3 points**.","prio":"P2","sec":"s7"},{"id":"fc-p75-af3b44","poly":"pneumo","fiche":"p75","front":"Fagerström : points selon le délai réveil → 1re cigarette de 6 à 30 min, 31 à 60 min, > 60 min ?","back":"6-30 min = **2** ; 31-60 min = **1** ; > 60 min = **0**.","prio":"P3","sec":"s7"},{"id":"fc-p75-146d4c","poly":"pneumo","fiche":"p75","front":"Fagerström : points selon le nombre de cigarettes par jour ?","back":"≤ 10 = **0** ; 11-20 = **1** ; 21-30 = **2** ; ≥ 31 = **3**.","prio":"P3","sec":"s7"},{"id":"fc-p75-e40552","poly":"pneumo","fiche":"p75","front":"Fagerström simplifié : interprétation du score ?","back":"0-1 : **non dépendant** ; 2-3 : **modérée** ; 4-6 : **forte**.","prio":"P3","sec":"s7"},{"id":"fc-p75-2e965f","poly":"pneumo","fiche":"p75","front":"Fagerström complet : interprétation du score ?","back":"0-2 : pas de dépendance ; 3-4 : faible ; 5-6 : moyenne ; **7-10 : forte** ou très forte.","prio":"P3","sec":"s7"},{"id":"fc-p75-0279b5","poly":"pneumo","fiche":"p75","front":"Fagerström complet : quelle cigarette est cotée 1 point si c'est la plus dure à abandonner ?","back":"La **première du matin**.","prio":"P3","sec":"s7"},{"id":"fc-p75-25c250","poly":"pneumo","fiche":"p75","front":"Fagerström complet : quelles 3 questions sont cotées oui = 1, non = 0 ?","back":"Difficile de ne pas fumer **où c'est interdit** ; fume **même malade/alité** ; rythme plus soutenu **le matin**.","prio":"P3","sec":"s7"},{"id":"fc-p75-8671fc","poly":"pneumo","fiche":"p75","front":"Bilan avant sevrage : quel rôle de l'alcool et du cannabis ?","back":"L'**alcool** favorise la **rechute** et déclenche l'envie ; le **cannabis** peut gêner l'arrêt.","prio":"P3","sec":"s7"},{"id":"fc-p75-9a6b27","poly":"pneumo","fiche":"p75","front":"Bilan avant sevrage : que faire en cas d'autres substances que tabac, alcool, cannabis ?","back":"Une **prise en charge spécialisée**.","prio":"P3","sec":"s7"},{"id":"fc-p75-79164d","poly":"pneumo","fiche":"p75","front":"Bilan avant sevrage : quelles comorbidités rechercher ?","back":"Les comorbidités **liées au tabac** et **psychiatriques**, notamment **anxio-dépressives**.","prio":"P3","sec":"s7"},{"id":"fc-p75-996398","poly":"pneumo","fiche":"p75","front":"Signes de sevrage tabagique : quand apparaissent-ils et quel est leur rôle ?","back":"Dès l'**arrêt** ; ce sont le **principal facteur de rechute**.","prio":"P1","sec":"s7"},{"id":"fc-p75-519f98","poly":"pneumo","fiche":"p75","front":"Signes de sevrage tabagique : quelle est leur cause et comment les corriger ?","back":"La **chute de la nicotinémie** ; ils sont corrigibles par la **substitution nicotinique**.","prio":"P1","sec":"s7"},{"id":"fc-p75-9b6eb9","poly":"pneumo","fiche":"p75","front":"Signes de sevrage tabagique : en citer ?","back":"Trouble de l'**humeur**, céphalées, **insomnie**, **irritabilité**, cauchemars, anxiété, nervosité, troubles de **concentration**, **appétit accru**/prise de poids.","prio":"P2","sec":"s7"},{"id":"fc-p75-698b2f","poly":"pneumo","fiche":"p75","front":"Craving : définition et dépendances qu'il reflète ?","back":"La **pulsion à consommer** du tabac ; reflète la dépendance **psychologique et comportementale**.","prio":"P1","sec":"s7"},{"id":"fc-p75-644dea","poly":"pneumo","fiche":"p75","front":"Sevrage tabagique : citer des facteurs prédictifs de réussite ?","back":"Bon niveau **socio-économique**, faible conso tabac/alcool, pas de fumeur autour, **début tardif**, usage bref, long délai réveil-cigarette, **forte motivation**.","prio":"P2","sec":"s7"},{"id":"fc-p75-99e782","poly":"pneumo","fiche":"p75","front":"Aide à l'arrêt du tabac : quels sont les 3 moyens ?","back":"**Substituts nicotiniques**, **psychothérapies**, **aides médicamenteuses** (seuls ou associés).","prio":"P1","sec":"s8"},{"id":"fc-p75-12b066","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : quelle indication ?","back":"**Quasi systématique** dès qu'il existe une **dépendance à la nicotine**.","prio":"P1","sec":"s8"},{"id":"fc-p75-48f875","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : quel gain d'efficacité par rapport au placebo ?","back":"Ils **doublent** les chances de réussite.","prio":"P1","sec":"s8"},{"id":"fc-p75-7b96e5","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : qui peut les prescrire ?","back":"Tout professionnel de santé avec un **numéro RPPS**, y compris **infirmiers** et **kinésithérapeutes**.","prio":"P2","sec":"s8"},{"id":"fc-p75-f0b7c1","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : à quelles conditions sont-ils efficaces ?","back":"Prescrits **à la bonne dose** et **suffisamment longtemps**.","prio":"P1","sec":"s8"},{"id":"fc-p75-a6e775","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : quelle quantité de nicotine apporte une cigarette manufacturée ?","back":"Environ **1 mg**.","prio":"P1","sec":"s8"},{"id":"fc-p75-df0df0","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : existe-t-il une dose maximale ?","back":"**Non** : la dose suit la **consommation réelle**.","prio":"P1","sec":"s8"},{"id":"fc-p75-cd4b90","poly":"pneumo","fiche":"p75","front":"Fumeur de 3 paquets/j : exemple de substitution par patch ?","back":"**3 patchs de 21 mg/24 h** par jour.","prio":"P2","sec":"s8"},{"id":"fc-p75-13f2fb","poly":"pneumo","fiche":"p75","front":"Substitution nicotinique : quelle association de formes prescrire ?","back":"Une forme à **libération prolongée** (patch) + une forme à **libération immédiate** à chaque envie impérieuse.","prio":"P1","sec":"s8"},{"id":"fc-p75-211e2a","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : quel remboursement depuis 2018 ?","back":"**65 %** (sauf inhaleur et spray) ; **100 %** en **ALD**.","prio":"P2","sec":"s8"},{"id":"fc-p75-8ce4bb","poly":"pneumo","fiche":"p75","front":"Patch nicotinique 24 h : quels dosages ?","back":"**21 mg**, **14 mg** ou **7 mg**.","prio":"P2","sec":"s8"},{"id":"fc-p75-8bb2db","poly":"pneumo","fiche":"p75","front":"Patch nicotinique 16 h : quels dosages ?","back":"**15 mg**, **10 mg** ou **5 mg**.","prio":"P2","sec":"s8"},{"id":"fc-p75-fc6cdc","poly":"pneumo","fiche":"p75","front":"Patch nicotinique : quelle forme se retire la nuit en cas de signes de surdosage ?","back":"La forme **16 h/24**.","prio":"P2","sec":"s8"},{"id":"fc-p75-828d7a","poly":"pneumo","fiche":"p75","front":"Patch nicotinique : sur quelle durée et comment ?","back":"**Doses décroissantes** sur **plusieurs mois**.","prio":"P2","sec":"s8"},{"id":"fc-p75-78547d","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques : quelles contre-indications ?","back":"**Aucune**, y compris **grossesse** et après un **événement cardiovasculaire aigu**.","prio":"P1","sec":"s8"},{"id":"fc-p75-d193a8","poly":"pneumo","fiche":"p75","front":"Substituts nicotiniques à libération immédiate : quelles formes ?","back":"**Gommes**, **pastilles**, comprimés à croquer, **inhaleur**, **spray buccal**.","prio":"P2","sec":"s8"},{"id":"fc-p75-d153a8","poly":"pneumo","fiche":"p75","front":"Substituts à libération immédiate : combien de prises par jour au maximum ?","back":"Une à chaque envie impérieuse, jusqu'à **15 à 30 fois par jour** selon le dosage.","prio":"P2","sec":"s8"},{"id":"fc-p75-b4a4ce","poly":"pneumo","fiche":"p75","front":"Substitution nicotinique : que traduisent des signes de manque ?","back":"Un **sous-dosage** : adapter (augmenter) la dose.","prio":"P1","sec":"s8"},{"id":"fc-p75-8d793d","poly":"pneumo","fiche":"p75","front":"Surdosage en nicotine : citer des signes ?","back":"**Céphalées**, **palpitations**, dysgueusie, hoquet, **nausées**, dyspepsie, stomatite, hypersalivation, bouche sèche, cauchemars.","prio":"P1","sec":"s8"},{"id":"fc-p75-2e3f6a","poly":"pneumo","fiche":"p75","front":"Surdosage en nicotine : comment évolue-t-il au retrait du dispositif ?","back":"Il **disparaît rapidement**.","prio":"P2","sec":"s8"},{"id":"fc-p75-95be07","poly":"pneumo","fiche":"p75","front":"Patch nicotinique : que faire en cas d'intolérance à la colle ?","back":"**Changer de dispositif** ou le coller sur une zone moins sensible (**plante du pied**, abdomen…).","prio":"P2","sec":"s8"},{"id":"fc-p75-605a0a","poly":"pneumo","fiche":"p75","front":"Intolérance à la colle du patch : quels signes ?","back":"**Érythème** et **prurit** à l'endroit du collage.","prio":"P3","sec":"s8"},{"id":"fc-p75-c152c3","poly":"pneumo","fiche":"p75","front":"Patient sous patch qui fume encore : faut-il retirer le patch ?","back":"**Non**, on **garde le patch**.","prio":"P1","sec":"s9"},{"id":"fc-p75-aa954a","poly":"pneumo","fiche":"p75","front":"Patient sous patch qui fume : comment l'interpréter ?","back":"Un **sous-dosage** en substituts, **pas un échec** du sevrage.","prio":"P1","sec":"s9"},{"id":"fc-p75-c87af5","poly":"pneumo","fiche":"p75","front":"Fumer sous patch : est-ce dangereux ?","back":"**Non** : rassurer ; il ressentira éventuellement des signes de **surdosage nicotinique**.","prio":"P2","sec":"s9"},{"id":"fc-p75-bd3b7c","poly":"pneumo","fiche":"p75","front":"Patient sous patch qui fume encore : quelle consigne donner ?","back":"Prendre un **substitut à libération immédiate** à chaque nouvelle envie de fumer.","prio":"P1","sec":"s9"},{"id":"fc-p75-d9fb74","poly":"pneumo","fiche":"p75","front":"Sevrage tabagique : l'accompagnement psychologique est-il recommandé ?","back":"**Oui, systématiquement** (la plupart de ses formes ne sont pas propres au tabac).","prio":"P1","sec":"s10"},{"id":"fc-p75-500a4e","poly":"pneumo","fiche":"p75","front":"Entretien motivationnel : de quoi s'agit-il ?","back":"Approche relationnelle **centrée sur le patient** pour faire naître ou renforcer sa **motivation** à changer.","prio":"P2","sec":"s10"},{"id":"fc-p75-f117a1","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : que se passe-t-il à 20 minutes ?","back":"**Fréquence cardiaque** et **pression artérielle** s'améliorent.","prio":"P2","sec":"s10"},{"id":"fc-p75-19e226","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : que devient le CO sanguin à 8 heures ?","back":"Il est **divisé par 2**.","prio":"P1","sec":"s10"},{"id":"fc-p75-8a0050","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : que se passe-t-il à 2 jours ?","back":"**Plus de nicotine** dans le corps ; **goût et odorat** meilleurs.","prio":"P2","sec":"s10"},{"id":"fc-p75-2ea1a9","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : quelques semaines puis quelques mois ?","back":"Semaines : **moins de toux**, peau plus belle ; mois : **souffle** et performances sportives meilleurs.","prio":"P3","sec":"s10"},{"id":"fc-p75-164764","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : que se passe-t-il à 1 an ?","back":"Risque d'**AVC** nettement baissé ; risque d'**infarctus divisé par 2**.","prio":"P1","sec":"s10"},{"id":"fc-p75-4d6792","poly":"pneumo","fiche":"p75","front":"Bénéfices de l'arrêt du tabac : que se passe-t-il à 10 ans ?","back":"Risque de **cancer diminué** ; **espérance de vie** allongée.","prio":"P2","sec":"s10"},{"id":"fc-p75-2845c0","poly":"pneumo","fiche":"p75","front":"Psychothérapie de soutien et TCC dans le sevrage tabagique : quel intérêt ?","back":"Elles modifient le comportement face au tabac et font **mieux qu'un médicament seul**.","prio":"P2","sec":"s10"},{"id":"fc-p75-b02284","poly":"pneumo","fiche":"p75","front":"Arrêt du tabac : quelle évolution de la toux est quasi systématique ?","back":"Une **recrudescence temporaire** de la toux.","prio":"P2","sec":"s10"},{"id":"fc-p75-4d0e5c","poly":"pneumo","fiche":"p75","front":"Recrudescence de la toux à l'arrêt du tabac : quel mécanisme ?","back":"**Ré-épithélialisation bronchique** et reconstitution des **cellules ciliées**.","prio":"P3","sec":"s10"},{"id":"fc-p75-2b7996","poly":"pneumo","fiche":"p75","front":"Arrêt du tabac : dans quelles situations viser un arrêt rapide ?","back":"**Grossesse**, **chirurgie programmée**, découverte d'une **maladie liée au tabac**.","prio":"P1","sec":"s11"},{"id":"fc-p75-068277","poly":"pneumo","fiche":"p75","front":"Chirurgie programmée : quand arrêter le tabac ?","back":"**6 à 8 semaines** avant : diminue la **morbi-mortalité opératoire**.","prio":"P1","sec":"s11"},{"id":"fc-p75-ee0002","poly":"pneumo","fiche":"p75","front":"Femme enceinte fumeuse : les substituts nicotiniques sont-ils utilisables ?","back":"**Oui**, aucune contre-indication pendant la grossesse.","prio":"P1","sec":"s11"},{"id":"fc-p75-f566a8","poly":"pneumo","fiche":"p75","front":"Grossesse, chirurgie, maladie liée au tabac : la prise en charge du sevrage est-elle spécifique ?","back":"**Non**, elle n'est pas spécifique à ces situations.","prio":"P3","sec":"s11"},{"id":"fc-p75-4c11ef","poly":"pneumo","fiche":"p75","front":"Après un infarctus ou une décompensation respiratoire : attitude vis-à-vis du tabac ?","back":"**Proposer le sevrage** ; substituts **non contre-indiqués** après un événement cardiovasculaire aigu.","prio":"P2","sec":"s11"},{"id":"fc-p75-2aeb29","poly":"pneumo","fiche":"p75","front":"Cigarette électronique : peut-elle aider au sevrage tabagique ?","back":"**Oui, avec nicotine**, éventuellement associée à d'autres moyens (patchs, psychothérapie).","prio":"P2","sec":"s12"},{"id":"fc-p75-93502b","poly":"pneumo","fiche":"p75","front":"Cigarette électronique pour arrêter : quels dispositifs conseiller ?","back":"Dispositifs et liquides **aux normes, vendus en France** (pas d'achat à l'étranger sur internet).","prio":"P2","sec":"s12"},{"id":"fc-p75-066a1d","poly":"pneumo","fiche":"p75","front":"Cigarette électronique pour arrêter : comment se déroule la suite ?","back":"Sevrage progressif de la **nicotine** puis du **dispositif**, sur plusieurs **mois voire années**.","prio":"P2","sec":"s12"},{"id":"fc-p75-b7c91b","poly":"pneumo","fiche":"p75","front":"Cigarette électronique : un non-fumeur peut-il commencer ?","back":"**Non**, encore moins avec nicotine.","prio":"P2","sec":"s12"},{"id":"fc-p75-69426d","poly":"pneumo","fiche":"p75","front":"Suivi au long cours de l'arrêt du tabac : quels objectifs ?","back":"**Maintenir l'arrêt**, **ajuster la substitution**, surveiller régulièrement.","prio":"P2","sec":"s13"},{"id":"fc-p75-9cdd34","poly":"pneumo","fiche":"p75","front":"Arrêt du tabac : les rechutes sont-elles fréquentes et quelle attitude ?","back":"Elles sont **la règle** ; proposer **de nouveau l'arrêt**.","prio":"P2","sec":"s13"},{"id":"fc-p75-bcf0bf","poly":"pneumo","fiche":"p75","front":"Suivi du sevrage : quel produit repérer, facteur de rechute ?","back":"L'**alcool** (déclenche aussi l'envie de fumer).","prio":"P2","sec":"s13"},{"id":"fc-p75-36372e","poly":"pneumo","fiche":"p75","front":"Suivi du sevrage : quel trouble peut toucher les fumeurs qui ont du mal à arrêter ?","back":"Une **humeur dépressive**.","prio":"P3","sec":"s13"},{"id":"fc-p75-1ed1ba","poly":"pneumo","fiche":"p75","front":"Suivi de la substitution : quels signes surveiller pour ajuster la dose ?","back":"Signes de **manque** (sous-dosage, 1re cause de rechute) et signes de **surdosage**.","prio":"P2","sec":"s13"},{"id":"fc-p75-1026b3","poly":"pneumo","fiche":"p75","front":"Lutte antitabac en France : quels textes de loi ?","back":"**Loi Veil (1976)**, **loi Evin (1991)**, **décret Bertrand (2006)**.","prio":"P2","sec":"s14"},{"id":"fc-p75-74934b","poly":"pneumo","fiche":"p75","front":"Publicité pour le tabac : quelle règle ?","back":"**Toute publicité** directe ou indirecte est **interdite**.","prio":"P2","sec":"s14"},{"id":"fc-p75-ebe0ae","poly":"pneumo","fiche":"p75","front":"Prévention du tabagisme : quel est l'un des leviers les plus efficaces ?","back":"L'**augmentation des prix**, dissuasive et répétée, pour tous les produits (tabac à rouler compris).","prio":"P1","sec":"s14"},{"id":"fc-p75-3ea703","poly":"pneumo","fiche":"p75","front":"Tabagisme passif : quelle mesure collective ?","back":"Protection dans les **lieux publics** et de **travail**.","prio":"P2","sec":"s14"},{"id":"fc-p75-5c0a92","poly":"pneumo","fiche":"p75","front":"Dénormalisation du tabac : quelles mesures ?","back":"**Paquet neutre**, campagnes d'information, action dans les médias.","prio":"P2","sec":"s14"},{"id":"fc-p75-4d7b4b","poly":"pneumo","fiche":"p75","front":"Éducation et information antitabac : quelles mesures ?","back":"**Avertissements sanitaires illustrés** sur les paquets ; **Moi(s) sans tabac** depuis 2017.","prio":"P2","sec":"s14"},{"id":"fc-p75-2cfa20","poly":"pneumo","fiche":"p75","front":"Programme national de lutte contre le tabac 2018-2022 : quel objectif d'ici 2032 ?","back":"Enfants nés depuis **2014** = 1re **génération d'adultes non-fumeurs** (< 5 % de fumeurs).","prio":"P3","sec":"s14"},{"id":"fc-p75-1fdfda","poly":"pneumo","fiche":"p75","front":"Programme national 2018-2022 : quels axes ?","back":"Protéger les **enfants** de l'entrée dans le tabac, **accompagner** vers le sevrage, agir sur l'**économie** du tabac, surveiller/diffuser.","prio":"P3","sec":"s14"},{"id":"fc-p75-26b36b","poly":"pneumo","fiche":"p75","front":"Lutte antitabac à l'échelle mondiale : quel texte ?","back":"La **convention-cadre de l'OMS** pour la lutte antitabac.","prio":"P3","sec":"s14"}],"fiches":{"152":{"title":"Endocardite infectieuse","poly":"cardio"},"153":{"title":"Surveillance des porteurs de valve et prothèses","poly":"cardio"},"203":{"title":"Dyspnée aiguë et chronique","poly":"cardio"},"221":{"title":"Athérome et malade polyathéromateux","poly":"cardio"},"222":{"title":"Facteurs de risque cardiovasculaire et prévention","poly":"cardio"},"223":{"title":"Dyslipidémies","poly":"cardio"},"224":{"title":"HTA de l'adulte et de l'enfant","poly":"cardio"},"225":{"title":"Artériopathie de l'aorte, des artères viscérales et des membres inférieurs ; anévrismes","poly":"cardio"},"226":{"title":"Thrombose veineuse profonde et embolie pulmonaire","poly":"cardio"},"230":{"title":"Douleur thoracique aiguë","poly":"cardio"},"231":{"title":"Électrocardiogramme","poly":"cardio"},"232":{"title":"Fibrillation atriale","poly":"cardio"},"233":{"title":"Valvulopathies","poly":"cardio"},"234":{"title":"Insuffisance cardiaque de l'adulte","poly":"cardio"},"235":{"title":"Péricardite aiguë","poly":"cardio"},"236":{"title":"Troubles de la conduction intracardiaque","poly":"cardio"},"237":{"title":"Palpitations","poly":"cardio"},"238":{"title":"Souffle cardiaque chez l'enfant","poly":"cardio"},"330":{"title":"Prescription et surveillance des antithrombotiques","poly":"cardio"},"331":{"title":"Arrêt cardiocirculatoire","poly":"cardio"},"339":{"title":"Syndromes coronariens aigus","poly":"cardio"},"342":{"title":"Malaises, perte de connaissance, syncope","poly":"cardio"},"d111":{"title":"Dermatoses faciales : acné, rosacée, dermatite séborrhéique","poly":"dermato"},"d112":{"title":"Dermatoses bulleuses auto-immunes","poly":"dermato"},"d113":{"title":"Hémangiomes et malformations vasculaires cutanées","poly":"dermato"},"d114":{"title":"Exanthème et érythrodermie de l'enfant et de l'adulte (items 114 et 164)","poly":"dermato"},"d115":{"title":"Toxidermies","poly":"dermato"},"d116":{"title":"Prurit","poly":"dermato"},"d117":{"title":"Psoriasis","poly":"dermato"},"d155":{"title":"Infections cutanéo-muqueuses bactériennes et mycosiques","poly":"dermato"},"d162":{"title":"Infections sexuellement transmissibles (IST)","poly":"dermato"},"d168":{"title":"Infections à herpès virus du sujet immunocompétent (herpès, varicelle, zona)","poly":"dermato"},"d169":{"title":"Primo-infection VIH : manifestations cutanéo-muqueuses","poly":"dermato"},"d171":{"title":"Ectoparasitoses cutanées : gale et pédiculose","poly":"dermato"},"d187":{"title":"Urticaire, dermatite atopique, eczéma de contact","poly":"dermato"},"d194":{"title":"Lupus érythémateux et syndrome des anti-phospholipides","poly":"dermato"},"d201":{"title":"Transplantation d'organes : complications cutanées","poly":"dermato"},"d211":{"title":"Sarcoïdose : aspects dermatologiques","poly":"dermato"},"d215":{"title":"Purpura chez l'adulte et l'enfant","poly":"dermato"},"d228":{"title":"Ulcère de jambe","poly":"dermato"},"d239":{"title":"Acrosyndromes (phénomène de Raynaud, érythermalgie, acrocyanose, engelures, ischémie digitale)","poly":"dermato"},"d302":{"title":"Tumeurs cutanées épithéliales et mélaniques","poly":"dermato"},"d319":{"title":"Lymphomes cutanés","poly":"dermato"},"d330":{"title":"Dermocorticoïdes : prescrire et surveiller","poly":"dermato"},"d350":{"title":"Grosse jambe rouge aiguë","poly":"dermato"},"p110":{"title":"Troubles du sommeil de l'enfant et de l'adulte","poly":"pneumo"},"p154":{"title":"Infections broncho-pulmonaires communautaires de l'adulte","poly":"pneumo"},"p159":{"title":"Tuberculose de l'adulte","poly":"pneumo"},"p186":{"title":"Hypersensibilités et allergies respiratoires","poly":"pneumo"},"p188":{"title":"Asthme, rhinite allergique","poly":"pneumo"},"p203":{"title":"Dyspnée aiguë et chronique","poly":"pneumo"},"p204":{"title":"Toux chez l'adulte","poly":"pneumo"},"p205":{"title":"Hémoptysie","poly":"pneumo"},"p206":{"title":"Épanchement pleural liquidien","poly":"pneumo"},"p207":{"title":"Opacités et masses intrathoraciques","poly":"pneumo"},"p208":{"title":"Insuffisance respiratoire chronique","poly":"pneumo"},"p209":{"title":"Bronchopneumopathie chronique obstructive (BPCO)","poly":"pneumo"},"p210":{"title":"Pneumopathies interstitielles diffuses","poly":"pneumo"},"p211":{"title":"Sarcoïdose","poly":"pneumo"},"p226":{"title":"Embolie pulmonaire et thrombose veineuse profonde","poly":"pneumo"},"p230":{"title":"Douleur thoracique aiguë","poly":"pneumo"},"p309":{"title":"Tumeurs du poumon, primitives et secondaires","poly":"pneumo"},"p338":{"title":"Œdème de Quincke et anaphylaxie","poly":"pneumo"},"p359":{"title":"Détresse respiratoire aiguë de l'adulte","poly":"pneumo"},"p359bis":{"title":"Corps étranger des voies aériennes et détresse respiratoire d'origine ORL","poly":"pneumo"},"p360":{"title":"Pneumothorax","poly":"pneumo"},"p75":{"title":"Addiction au tabac","poly":"pneumo"}}};
